#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to reverse a text file
int reverse_text_file(const char* input_filename, const char* output_filename) {
    FILE* input_file = NULL;
    FILE* output_file = NULL;
    long file_size = 0;
    char* buffer = NULL;
    long read_pos, write_pos;

    // Open input file for reading
    input_file = fopen(input_filename, "rb");
    if (input_file == NULL) {
        fprintf(stderr, "Error: Could not open input file %s\n", input_filename);
        return -1;
    }

    // Determine file size
    fseek(input_file, 0, SEEK_END);
    file_size = ftell(input_file);
    rewind(input_file);

    // Allocate memory for file contents
    buffer = (char*)malloc(file_size + 1);
    if (buffer == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        fclose(input_file);
        return -1;
    }

    // Read entire file content
    size_t bytes_read = fread(buffer, 1, file_size, input_file);
    if (bytes_read != file_size) {
        fprintf(stderr, "Error: Could not read entire file\n");
        free(buffer);
        fclose(input_file);
        return -1;
    }
    buffer[file_size] = '\0';  // Null-terminate the buffer

    // Close input file
    fclose(input_file);

    // Open output file for writing
    output_file = fopen(output_filename, "wb");
    if (output_file == NULL) {
        fprintf(stderr, "Error: Could not open output file %s\n", output_filename);
        free(buffer);
        return -1;
    }

    // Write file contents in reverse order
    for (read_pos = file_size - 1; read_pos >= 0; read_pos--) {
        fputc(buffer[read_pos], output_file);
    }

    // Close output file and free memory
    fclose(output_file);
    free(buffer);

    return 0;
}

// Function to reverse a text file by lines
int reverse_text_file_by_lines(const char* input_filename, const char* output_filename) {
    FILE* input_file = NULL;
    FILE* output_file = NULL;
    char* lines[1000];  // Assume max 1000 lines
    int line_count = 0;
    char buffer[1024];

    // Open input file for reading
    input_file = fopen(input_filename, "r");
    if (input_file == NULL) {
        fprintf(stderr, "Error: Could not open input file %s\n", input_filename);
        return -1;
    }

    // Read lines and store in array
    while (fgets(buffer, sizeof(buffer), input_file) != NULL && line_count < 1000) {
        lines[line_count] = strdup(buffer);
        line_count++;
    }
    fclose(input_file);

    // Open output file for writing
    output_file = fopen(output_filename, "w");
    if (output_file == NULL) {
        fprintf(stderr, "Error: Could not open output file %s\n", output_filename);

        // Free allocated memory for lines
        for (int i = 0; i < line_count; i++) {
            free(lines[i]);
        }
        return -1;
    }

    // Write lines in reverse order
    for (int i = line_count - 1; i >= 0; i--) {
        fputs(lines[i], output_file);
        free(lines[i]);  // Free memory after writing
    }

    fclose(output_file);
    return 0;
}

