void reverseFileContent(const char *filename) {
    FILE *file;
    long fileSize;
    char *buffer;
    size_t result;

    // Open the file for reading
    file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    // Determine the file size
    fseek(file, 0, SEEK_END);
    fileSize = ftell(file);
    rewind(file);

    // Allocate memory to hold the file content
    buffer = (char *)malloc(fileSize);
    if (buffer == NULL) {
        perror("Memory allocation failed");
        fclose(file);
        return;
    }

    // Read the file content into the buffer
    result = fread(buffer, 1, fileSize, file);
    if (result != fileSize) {
        perror("Error reading file");
        free(buffer);
        fclose(file);
        return;
    }

    // Close the file
    fclose(file);

    // Reverse the content of the buffer
    for (long i = 0; i < fileSize / 2; i++) {
        char temp = buffer[i];
        buffer[i] = buffer[fileSize - 1 - i];
        buffer[fileSize - 1 - i] = temp;
    }

    // Open the file for writing (this will truncate the file)
    file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Error opening file for writing");
        free(buffer);
        return;
    }

    // Write the reversed content back to the file
    result = fwrite(buffer, 1, fileSize, file);
    if (result != fileSize) {
        perror("Error writing to file");
    }

    // Free the buffer and close the file
    free(buffer);
    fclose(file);
}

