// Function to reverse a string in-place
void reverse_string(char *str) {
    if (str == NULL) {
        return;
    }
    int length = strlen(str);
    int i, j;
    char temp;
    for (i = 0, j = length - 1; i < j; i++, j--) {
        temp = str[i];
        str[i] = str[j];
        str[j] = temp;
    }
}

/**
 * @brief Reverses the entire content of a text file in-place.
 *        This function reads the entire file into memory, reverses it,
 *        and then writes the reversed content back to the same file.
 *        WARNING: Not suitable for very large files that exceed available RAM.
 *
 * @param filename The path to the text file to be reversed.
 * @return 0 on success, -1 on failure.
 */
int reverse_text_file(const char *filename) {
    FILE *file = NULL;
    char *buffer = NULL;
    long file_size;
    int ret_code = -1; // Assume failure

    // 1. Open the file in binary read mode to determine its size accurately
    file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Error opening file for reading");
        return -1;
    }

    // 2. Determine file size
    if (fseek(file, 0, SEEK_END) != 0) {
        perror("Error seeking to end of file");
        fclose(file);
        return -1;
    }
    file_size = ftell(file);
    if (file_size == -1) { // ftell returns -1 on error
        perror("Error getting file size");
        fclose(file);
        return -1;
    }
    if (fseek(file, 0, SEEK_SET) != 0) { // Rewind to beginning
        perror("Error seeking to beginning of file");
        fclose(file);
        return -1;
    }

    if (file_size == 0) {
        printf("File '%s' is empty. Nothing to reverse.\n", filename);
        fclose(file);
        return 0; // Success for an empty file
    }

    // 3. Allocate buffer to hold file content + null terminator for safety (though not strictly needed for binary read)
    buffer = (char *)malloc(file_size + 1);
    if (buffer == NULL) {
        perror("Error allocating memory for file content");
        fclose(file);
        return -1;
    }

    // 4. Read file content into buffer
    size_t bytes_read = fread(buffer, 1, file_size, file);
    if (bytes_read != (size_t)file_size) {
        perror("Error reading file content");
        // For partial reads, you might want to handle it differently, but for full reversal, it's an error.
        if (ferror(file)) { // Check if the error was due to a read error
             // perror already handled.
        } else if (feof(file)) { // Check if it was due to unexpected EOF
            fprintf(stderr, "Warning: Reached end of file unexpectedly (read %zu of %ld bytes).\n", bytes_read, file_size);
        }
        fclose(file);
        free(buffer);
        return -1;
    }
    fclose(file); // Close the file after reading

    // Null-terminate the buffer just in case it's treated as a string by other functions
    // (though not strictly necessary for the byte-by-byte reversal below)
    buffer[file_size] = '\0';

    // 5. Reverse the content in the buffer
    // We reverse the entire byte array, not just null-terminated string part
    int i, j;
    char temp;
    for (i = 0, j = file_size - 1; i < j; i++, j--) {
        temp = buffer[i];
        buffer[i] = buffer[j];
        buffer[j] = temp;
    }

    // 6. Open the file in binary write mode (truncates existing content)
    file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Error opening file for writing");
        free(buffer);
        return -1;
    }

    // 7. Write the reversed content back to the file
    size_t bytes_written = fwrite(buffer, 1, file_size, file);
    if (bytes_written != (size_t)file_size) {
        perror("Error writing reversed content back to file");
        // fwrite doesn't typically set feof, only ferror.
        if (ferror(file)) {
             // perror already handled.
        }
        fclose(file);
        free(buffer);
        return -1;
    }

    printf("Successfully reversed content of '%s'.\n", filename);
    ret_code = 0; // Success

    // Cleanup
    fclose(file);
    free(buffer);
    return ret_code;
}

