int reverse_file_contents(const char* filename) {
    FILE *fp = fopen(filename, "rb+"); // read and write, binary mode
    if (!fp) {
        perror("Could not open file");
        return -1;
    }

    // Find file size
    fseek(fp, 0, SEEK_END);
    long filesize = ftell(fp);
    if(filesize < 0) {
        perror("ftell failed");
        fclose(fp);
        return -1;
    }
    rewind(fp);

    // Allocate buffer
    char* buffer = (char*)malloc(filesize);
    if(!buffer && filesize != 0) {
        perror("Memory allocation failed");
        fclose(fp);
        return -1;
    }

    // Read file into buffer
    size_t read_bytes = fread(buffer, 1, filesize, fp);
    if (read_bytes != filesize) {
        perror("File read failed");
        free(buffer);
        fclose(fp);
        return -1;
    }

    // Reverse buffer
    for (long i = 0; i < filesize / 2; ++i) {
        char tmp = buffer[i];
        buffer[i] = buffer[filesize - i - 1];
        buffer[filesize - i - 1] = tmp;
    }

    // Write reversed buffer back to file
    rewind(fp);
    size_t written = fwrite(buffer, 1, filesize, fp);
    free(buffer);
    fclose(fp);

    if (written != filesize) {
        perror("File write failed");
        return -1;
    }

    return 0; // Success
}

