#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/**
 * Reverses the contents of a text file.
 *
 * @param filename The name of the text file to reverse.
 *
 * @return 0 on success, 1 on failure.
 */
int reverse_file(const char* filename) {
    // Open the file in read mode
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    // Get the file size
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    // Allocate memory to store the file contents
    char* contents = malloc((file_size + 1) * sizeof(char));
    if (!contents) {
        perror("Error allocating memory");
        fclose(file);
        return 1;
    }

    // Read the file contents
    size_t bytes_read = fread(contents, sizeof(char), file_size, file);
    if (bytes_read != file_size) {
        perror("Error reading file");
        free(contents);
        fclose(file);
        return 1;
    }

    // Null-terminate the contents
    contents[file_size] = '\0';

    // Close the file
    fclose(file);

    // Reverse the contents
    int length = strlen(contents);
    char* reversed = malloc((length + 1) * sizeof(char));
    if (!reversed) {
        perror("Error allocating memory");
        free(contents);
        return 1;
    }
    for (int i = 0; i < length; i++) {
        reversed[i] = contents[length - 1 - i];
    }
    reversed[length] = '\0';

    // Open the file again in write mode
    file = fopen(filename, "w");
    if (!file) {
        perror("Error opening file");
        free(contents);
        free(reversed);
        return 1;
    }

    // Write the reversed contents
    if (fprintf(file, "%s", reversed) < 0) {
        perror("Error writing to file");
        free(contents);
        free(reversed);
        fclose(file);
        return 1;
    }

    // Close the file and free memory
    fclose(file);
    free(contents);
    free(reversed);

    return 0;
}

int main() {
    // Example usage
    const char* filename = "example.txt";
    if (reverse_file(filename)) {
        printf("Failed to reverse file.\n");
        return 1;
    }
    printf("File reversed successfully.\n");
    return 0;
}

