    char *fileContent = malloc(fileSize + 1);
    if (fileContent == NULL) {
        perror("Memory allocation failed");
        fclose(inputFile);
        return;
    }

    // Read the entire file content into memory
    fread(fileContent, 1, fileSize, inputFile);
    fclose(inputFile);

    // Null-terminate the string
    fileContent[fileSize] = '\0';

    // Reverse the content
    for (int i = 0, j = fileSize - 1; i < j; i++, j--) {
        char temp = fileContent[i];
        fileContent[i] = fileContent[j];
        fileContent[j] = temp;
    }

    // Open the output file
    FILE *outputFile = fopen(outputFilePath, "w");
    if (outputFile == NULL) {
        perror("Failed to open output file");
        free(fileContent);
        return;
    }

    // Write the reversed content to the output file
    fwrite(fileContent, 1, fileSize, outputFile);
    fclose(outputFile);

    // Free allocated memory
    free(fileContent);
}

