#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <dirent.h>
#include <errno.h>

#define MAX_INPUT_LENGTH 1024
#define MAX_ARGS 64

// Function prototypes
void execute_cd(char *path);
void execute_ls(char *path);
void execute_external_command(char **args);

// Main shell loop
int main() {
    char input[MAX_INPUT_LENGTH];
    char *args[MAX_ARGS];

    while (1) {
        // Print prompt
        printf("myshell> ");

        // Read input
        if (fgets(input, sizeof(input), stdin) == NULL) {
            break;  // Exit on EOF
        }

        // Remove trailing newline
        input[strcspn(input, "\n")] = 0;

        // Skip empty input
        if (strlen(input) == 0) {
            continue;
        }

        // Tokenize input
        int arg_count = 0;
        char *token = strtok(input, " ");
        while (token != NULL && arg_count < MAX_ARGS - 1) {
            args[arg_count++] = token;
            token = strtok(NULL, " ");
        }
        args[arg_count] = NULL;

        // Handle built-in commands
        if (strcmp(args[0], "exit") == 0) {
            break;
        }
        else if (strcmp(args[0], "cd") == 0) {
            // Change directory
            if (arg_count > 1) {
                execute_cd(args[1]);
            } else {
                // Default to home directory if no path specified
                execute_cd(getenv("HOME"));
            }
        }
        else if (strcmp(args[0], "ls") == 0) {
            // List directory contents
            if (arg_count > 1) {
                execute_ls(args[1]);
            } else {
                execute_ls(".");  // Current directory by default
            }
        }
        else {
            // External command
            execute_external_command(args);
        }
    }

    return 0;
}

// Change directory implementation
void execute_cd(char *path) {
    if (chdir(path) != 0) {
        // Error handling
        perror("cd error");
    }
}

// List directory contents implementation
void execute_ls(char *path) {
    DIR *dir;
    struct dirent *entry;

    // Open directory
    dir = opendir(path);

    if (dir == NULL) {
        perror("ls error");
        return;
    }

    // Read and print directory entries
    while ((entry = readdir(dir)) != NULL) {
        // Skip hidden files (starting with .)
        if (entry->d_name[0] != '.') {
            printf("%s\n", entry->d_name);
        }
    }

    // Close directory
    closedir(dir);
}

// Execute external commands
void execute_external_command(char **args) {
    pid_t pid = fork();

    if (pid < 0) {
        // Fork failed
        perror("Fork failed");
        exit(1);
    }
    else if (pid == 0) {
        // Child process
        if (execvp(args[0], args) == -1) {
            // Error executing command
            perror("Command execution failed");
            exit(1);
        }
    }
    else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
    }
}

