#define MAX_COMMAND_LENGTH 1024
#define MAX_ARGS 64

// Function to execute external commands
void execute_external_command(char *args[]) {
    pid_t pid = fork();

    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    } else if (pid == 0) {
        // Child process
        execvp(args[0], args);
        perror("execvp"); // execvp only returns on error
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0); // Wait for the child to finish
    }
}

// Function for the 'cd' command
void handle_cd(char *path) {
    if (path == NULL || strcmp(path, "~") == 0) {
        // If no path is given or path is ~, change to home directory
        path = getenv("HOME");
        if (path == NULL) {
            fprintf(stderr, "cd: HOME environment variable not set.\n");
            return;
        }
    }

    if (chdir(path) != 0) {
        perror("cd");
    }
}

// Function for the 'ls' command
void handle_ls(char *path) {
    DIR *d;
    struct dirent *dir;

    if (path == NULL) {
        path = "."; // Default to current directory
    }

    d = opendir(path);
    if (d) {
        while ((dir = readdir(d)) != NULL) {
            printf("%s\n", dir->d_name);
        }
        closedir(d);
    } else {
        perror("ls");
    }
}

int main() {
    char command[MAX_COMMAND_LENGTH];
    char *args[MAX_ARGS];
    int status;

    printf("Welcome to MyShell!\n");
    printf("Type 'exit' to quit.\n");

    while (1) {
        char *current_dir = getcwd(NULL, 0);
        if (current_dir) {
            printf("\033[1;34m%s\033[0m$ ", current_dir); // Blue prompt for current directory
            free(current_dir);
        } else {
            perror("getcwd");
            printf("$ ");
        }

        if (fgets(command, MAX_COMMAND_LENGTH, stdin) == NULL) {
            // Handle EOF (Ctrl+D)
            printf("\nExiting MyShell.\n");
            break;
        }

        // Remove trailing newline character
        command[strcspn(command, "\n")] = 0;

        if (strlen(command) == 0) {
            continue; // Empty command
        }

        // Tokenize the command
        int i = 0;
        args[i] = strtok(command, " ");
        while (args[i] != NULL && i < MAX_ARGS - 1) {
            i++;
            args[i] = strtok(NULL, " ");
        }
        args[i] = NULL; // Null-terminate the argument list

        if (args[0] == NULL) {
            continue; // Only spaces entered
        }

        // Handle built-in commands
        if (strcmp(args[0], "exit") == 0) {
            printf("Exiting MyShell.\n");
            break;
        } else if (strcmp(args[0], "cd") == 0) {
            handle_cd(args[1]);
        } else if (strcmp(args[0], "ls") == 0) {
            handle_ls(args[1]); // Pass argument (e.g., "ls /tmp") or NULL
        } else {
            // Execute external command
            execute_external_command(args);
        }
    }

    return 0;
}

