#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// SIR Model Structure
typedef struct {
    double susceptible;     // Number of susceptible individuals
    double infected;        // Number of infected individuals
    double recovered;       // Number of recovered individuals
    double total_population; // Total population size
    double beta;            // Transmission rate
    double gamma;           // Recovery rate
} SIRModel;

// Function to initialize SIR model parameters
void initializeSIRModel(SIRModel *model, 
                        double total_pop, 
                        double initial_infected, 
                        double transmission_rate, 
                        double recovery_rate) {
    model->total_population = total_pop;
    model->susceptible = total_pop - initial_infected;
    model->infected = initial_infected;
    model->recovered = 0.0;
    model->beta = transmission_rate;
    model->gamma = recovery_rate;
}

// SIR Model Differential Equations
void updateSIRModel(SIRModel *model, double time_step) {
    // Calculate new rates
    double new_infections = model->beta * 
                             model->susceptible * 
                             model->infected / 
                             model->total_population;

    double new_recoveries = model->gamma * model->infected;

    // Update population compartments
    model->susceptible -= new_infections * time_step;
    model->infected += (new_infections - new_recoveries) * time_step;
    model->recovered += new_recoveries * time_step;

    // Prevent negative values
    model->susceptible = fmax(model->susceptible, 0);
    model->infected = fmax(model->infected, 0);
    model->recovered = fmax(model->recovered, 0);
}

// Simulate virus spread over time
void simulateVirus(SIRModel *model, 
                   int total_days, 
                   double time_step, 
                   const char* output_file) {
    FILE *file = fopen(output_file, "w");
    if (file == NULL) {
        printf("Error opening output file!\n");
        return;
    }

    // Write header
    fprintf(file, "Day,Susceptible,Infected,Recovered\n");

    // Simulation loop
    for (int day = 0; day < total_days; day++) {
        // Write current state
        fprintf(file, "%d,%.2f,%.2f,%.2f\n", 
                day, 
                model->susceptible, 
                model->infected, 
                model->recovered);

        // Update model
        updateSIRModel(model, time_step);
    }

    fclose(file);
}

// Peak infection calculator
double calculatePeakInfection(const char* filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error reading simulation file!\n");
        return -1;
    }

    double max_infected = 0;
    char line[100];
    int first_line = 1;

    // Skip header
    fgets(line, sizeof(line), file);

    // Read and find peak infection
    while (fgets(line, sizeof(line), file)) {
        if (first_line) {
            first_line = 0;
            continue;
        }

        double day, susceptible, infected, recovered;
        sscanf(line, "%lf,%lf,%lf,%lf", 
               &day, &susceptible, &infected, &recovered);

        max_infected = fmax(max_infected, infected);
    }

    fclose(file);
    return max_infected;
}

int main() {
    SIRModel virusModel;

    // Model Parameters
    double total_population = 100000;   // Total population
    double initial_infected = 100;      // Initial infected count
    double transmission_rate = 0.3;     // How quickly virus spreads
    double recovery_rate = 0.1;         // Recovery rate
    int simulation_days = 100;          // Simulation duration
    double time_step = 1.0;             // Time increment

    // Initialize model
    initializeSIRModel(&virusModel, 
                       total_population, 
                       initial_infected, 
                       transmission_rate, 
                       recovery_rate);

    // Output file for results
    const char* output_file = "virus_simulation.csv";

    // Run simulation
    simulateVirus(&virusModel, 
                  simulation_days, 
                  time_step, 
                  output_file);

    // Calculate peak infection
    double peak_infection = calculatePeakInfection(output_file);
    printf("Peak Infection: %.2f\n", peak_infection);

    return 0;
}

#include <stdio.h>

// Function to simulate the SIR model
void sir_model(double beta, double gamma, double S0, double I0, double R0, int days) {
    double S = S0;
    double I = I0;
    double R = R0;
    double N = S + I + R;  // Total population

    printf("Day\tSusceptible\tInfected\tRecovered\n");
    for (int t = 0; t < days; t++) {
        // Calculate the changes in S, I, R
        double dS = -beta * S * I / N;
        double dI = beta * S * I / N - gamma * I;
        double dR = gamma * I;

        // Update S, I, R
        S += dS;
        I += dI;
        R += dR;

        // Print the results for the current day
        printf("%d\t%.2f\t\t%.2f\t\t%.2f\n", t, S, I, R);
    }
}

