}

#include <stdio.h>
#include <stdlib.h> // For round() and other operations, though not strictly needed here for simple integer display

// Function to simulate the SIR model
// Inputs:
//   N_total: Total population
//   S0: Initial susceptible population
//   I0: Initial infected population
//   R0: Initial recovered population
//   beta: Transmission rate (contact rate * probability of infection per contact)
//   gamma: Recovery rate (1 / average infectious period)
//   num_days: Number of days to simulate
void simulate_sir(double N_total, double S0, double I0, double R0,
                  double beta, double gamma, int num_days) {

    // Input validation
    if (S0 < 0 || I0 < 0 || R0 < 0 || N_total <= 0) {
        printf("Error: Initial populations must be non-negative and total population must be positive.\n");
        return;
    }
    if (S0 + I0 + R0 != N_total) {
        printf("Warning: Initial S + I + R does not equal total population N_total. Adjusting S0.\n");
        S0 = N_total - I0 - R0; // Adjust S0 to ensure sum matches N_total
    }
    if (beta < 0 || gamma < 0) {
        printf("Error: Beta and Gamma must be non-negative.\n");
        return;
    }
    if (num_days <= 0) {
        printf("Error: Number of days to simulate must be positive.\n");
        return;
    }

    // Current values for S, I, R
    double S = S0;
    double I = I0;
    double R = R0;

    // Time step (tau) for the Euler method. We'll use 1 day.
    double dt = 1.0;

    printf("Day\tSusceptible\tInfected\tRecovered\n");
    printf("--------------------------------------------------\n");

    for (int day = 0; day <= num_days; ++day) {
        // Print current state (rounded for better readability)
        // Using "%.0f" to display without decimal places, effectively rounding
        printf("%d\t%.0f\t\t%.0f\t\t%.0f\n", day, S, I, R);

        // Calculate derivatives for the current day
        double dS_dt = -beta * S * I / N_total;
        double dI_dt = beta * S * I / N_total - gamma * I;
        double dR_dt = gamma * I;

        // Update S, I, R for the next day using Euler's method
        // Ensure values don't go negative due to numerical issues
        S = S + dS_dt * dt;
        if (S < 0) S = 0; // Cap at 0

        I = I + dI_dt * dt;
        if (I < 0) I = 0; // Cap at 0

        R = R + dR_dt * dt;
        if (R < 0) R = 0; // Cap at 0

        // Important: Re-normalize to N_total occasionally to correct for small numerical drift
        // This can help prevent the total population from drifting over long simulations.
        // For simple Euler with dt=1, it might not be strictly necessary each step
        // but it's good practice for numerical stability, especially if dt were smaller.
        double current_N = S + I + R;
        if (current_N != N_total && current_N > 0) { // Avoid division by zero
             double factor = N_total / current_N;
             S *= factor;
             I *= factor;
             R *= factor;
        }
        // If current_N is 0, it means all populations are 0, which is an unlikely scenario unless N_total was 0,
        // which is handled by initial validation.
    }
}

// Example usage
int main() {
    // --- Scenario 1: A typical epidemic outbreak ---
    printf("--- Scenario 1: Typical Outbreak ---\n");
    double N1 = 1000.0;     // Total population
    double S0_1 = 999.0;    // Initial susceptible
    double I0_1 = 1.0;      // Initial infected
    double R0_1 = 0.0;      // Initial recovered
    double beta1 = 0.3;     // Transmission rate (e.g., 0.3 contacts lead to infection per day)
    double gamma1 = 0.1;    // Recovery rate (e.g., 1/0.1 = 10 days to recover)
    int num_days1 = 100;    // Simulate for 100 days

