void sir_simulate(
    double S0,           // Initial number of susceptibles
    double I0,           // Initial number of infected
    double R0,           // Initial number of recovered
    double beta,         // Infection rate
    double gamma,        // Recovery rate
    int steps,           // Number of time steps
    double dt            // Timestep size (e.g. 1.0 = one day)
) {
    double S = S0, I = I0, R = R0;
    double N = S0 + I0 + R0;

    printf("Step\tSusceptible\tInfected\tRecovered\n");
    for(int t = 0; t <= steps; t++) {
        printf("%d\t%.2f\t\t%.2f\t\t%.2f\n", t, S, I, R);

        // Calculate changes using SIR equations
        double dS = -beta * S * I / N;
        double dI = beta * S * I / N - gamma * I;
        double dR = gamma * I;

        // Update using Euler's method
        S += dS * dt;
        I += dI * dt;
        R += dR * dt;
    }
}

