// Function to simulate one time step of the SIR model
void simulate_sir(double *S, double *I, double *R, double beta, double gamma, double dt) {
    double dS = -beta * (*S) * (*I) * dt;
    double dI = (beta * (*S) * (*I) - gamma * (*I)) * dt;
    double dR = gamma * (*I) * dt;

    *S += dS;
    *I += dI;
    *R += dR;
}

// Function to run the simulation over a given time period
void run_simulation(double S, double I, double R, double beta, double gamma, double dt, int steps) {
    printf("Time\t\tS\t\tI\t\tR\n");
    for (int t = 0; t <= steps; ++t) {
        printf("%d\t\t%.4f\t%.4f\t%.4f\n", t, S, I, R);
        simulate_sir(&S, &I, &R, beta, gamma, dt);
    }
}

