void simulateSIR(int total_population, double beta, double gamma, int initial_infected, int days) {
    // S, I, R populations
    double S = total_population - initial_infected;
    double I = initial_infected;
    double R = 0.0;

    // Time step for the simulation
    double dt = 1.0; // 1 day time step

    printf("Day\tSusceptible\tInfected\tRecovered\n");
    for (int day = 0; day <= days; day++) {
        printf("%d\t%.2f\t\t%.2f\t\t%.2f\n", day, S, I, R);

        // Calculate new infections and recoveries
        double new_infected = (beta * S * I / total_population) * dt;
        double new_recovered = gamma * I * dt;

        // Update the compartments
        S -= new_infected;
        I += new_infected - new_recovered;
        R += new_recovered;

        // Ensure populations do not become negative
        if (S < 0) S = 0;
        if (I < 0) I = 0;
        if (R < 0) R = 0;
    }
}

