#include <stdio.h>
#include <math.h>

// SIR model parameters
typedef struct {
    double beta;  // Infection rate
    double gamma; // Recovery rate
    double N;     // Total population
} SIRParams;

// SIR model state
typedef struct {
    double S; // Susceptible population
    double I; // Infected population
    double R; // Recovered population
} SIRState;

// Runge-Kutta method for SIR model integration
void rungeKutta(SIRState* currentState, SIRParams* params, double dt, SIRState* nextState) {
    double k1S, k1I, k1R;
    double k2S, k2I, k2R;
    double k3S, k3I, k3R;
    double k4S, k4I, k4R;

    // Calculate k1
    k1S = -params->beta * currentState->S * currentState->I / params->N;
    k1I = params->beta * currentState->S * currentState->I / params->N - params->gamma * currentState->I;
    k1R = params->gamma * currentState->I;

    // Calculate k2
    SIRState state2;
    state2.S = currentState->S + dt * k1S / 2;
    state2.I = currentState->I + dt * k1I / 2;
    state2.R = currentState->R + dt * k1R / 2;

    k2S = -params->beta * state2.S * state2.I / params->N;
    k2I = params->beta * state2.S * state2.I / params->N - params->gamma * state2.I;
    k2R = params->gamma * state2.I;

    // Calculate k3
    SIRState state3;
    state3.S = currentState->S + dt * k2S / 2;
    state3.I = currentState->I + dt * k2I / 2;
    state3.R = currentState->R + dt * k2R / 2;

    k3S = -params->beta * state3.S * state3.I / params->N;
    k3I = params->beta * state3.S * state3.I / params->N - params->gamma * state3.I;
    k3R = params->gamma * state3.I;

    // Calculate k4
    SIRState state4;
    state4.S = currentState->S + dt * k3S;
    state4.I = currentState->I + dt * k3I;
    state4.R = currentState->R + dt * k3R;

    k4S = -params->beta * state4.S * state4.I / params->N;
    k4I = params->beta * state4.S * state4.I / params->N - params->gamma * state4.I;
    k4R = params->gamma * state4.I;

    // Update state using Runge-Kutta method
    nextState->S = currentState->S + (dt / 6) * (k1S + 2 * k2S + 2 * k3S + k4S);
    nextState->I = currentState->I + (dt / 6) * (k1I + 2 * k2I + 2 * k3I + k4I);
    nextState->R = currentState->R + (dt / 6) * (k1R + 2 * k2R + 2 * k3R + k4R);
}

// Simulate SIR model
void simulateSIR(SIRParams* params, double initialS, double initialI, double initialR, double endTime, double dt) {
    SIRState currentState;
    currentState.S = initialS;
    currentState.I = initialI;
    currentState.R = initialR;

    printf("Time\tSusceptible\tInfected\tRecovered\n");
    printf("0.0\t%.2f\t%.2f\t%.2f\n", currentState.S, currentState.I, currentState.R);

    double time = 0;
    while (time < endTime) {
        SIRState nextState;
        rungeKutta(&currentState, params, dt, &nextState);
        currentState = nextState;
        time += dt;
        printf("%.2f\t%.2f\t%.2f\t%.2f\n", time, currentState.S, currentState.I, currentState.R);
    }
}

int main() {
    // Define SIR model parameters
    SIRParams params;
    params.beta = 0.2;  // Infection rate
    params.gamma = 0.1; // Recovery rate
    params.N = 1000;    // Total population

    // Define initial state
    double initialS = 999; // Initially, 999 people are susceptible
    double initialI = 1;    // Initially, 1 person is infected
    double initialR = 0;    // Initially, no one has recovered

    // Simulate SIR model
    simulateSIR(&params, initialS, initialI, initialR, 100, 1);

