// Function to simulate the SIR model
void simulate_SIR(double *S, double *I, double *R, double N, double beta, double gamma, double t_max, double dt) {
    double t = 0.0; // Initial time

    // Loop until the maximum simulation time is reached
    while (t < t_max) {
        // Calculate the derivatives
        double dS_dt = -beta * (*S) * (*I) / N;
        double dI_dt = beta * (*S) * (*I) / N - gamma * (*I);
        double dR_dt = gamma * (*I);

        // Update the values using the Euler method
        *S += dS_dt * dt;
        *I += dI_dt * dt;
        *R += dR_dt * dt;

        // Print the current state
        printf("Time: %.2f, Susceptible: %.2f, Infected: %.2f, Recovered: %.2f\n", t, *S, *I, *R);

        // Increment time
        t += dt;
    }
}

