#include <string.h>
#include <openssl/sha.h>

#define BUFFER_SIZE 4096  // Efficient buffer size for file reading

// Function to calculate SHA-256 hash of a file
int calculate_sha256(const char *filepath, char *hash_string) {
    FILE *file;
    SHA256_CTX sha256_context;
    unsigned char buffer[BUFFER_SIZE];
    unsigned char hash[SHA256_DIGEST_LENGTH];
    size_t bytes_read;

    // Open file in binary read mode
    file = fopen(filepath, "rb");
    if (file == NULL) {
        fprintf(stderr, "Error: Unable to open file %s\n", filepath);
        return 0;
    }

    // Initialize SHA-256 context
    if (SHA256_Init(&sha256_context) != 1) {
        fprintf(stderr, "Error: SHA256 initialization failed\n");
        fclose(file);
        return 0;
    }

    // Read file in chunks and update SHA-256 context
    while ((bytes_read = fread(buffer, 1, BUFFER_SIZE, file)) > 0) {
        if (SHA256_Update(&sha256_context, buffer, bytes_read) != 1) {
            fprintf(stderr, "Error: SHA256 update failed\n");
            fclose(file);
            return 0;
        }
    }

    // Finalize hash calculation
    if (SHA256_Final(hash, &sha256_context) != 1) {
        fprintf(stderr, "Error: SHA256 finalization failed\n");
        fclose(file);
        return 0;
    }

    // Close file
    fclose(file);

    // Convert binary hash to hexadecimal string
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        sprintf(hash_string + (i * 2), "%02x", hash[i]);
    }
    hash_string[SHA256_DIGEST_LENGTH * 2] = '\0';

    return 1;
}

// Main function to demonstrate file hash calculation
int main(int argc, char *argv[]) {
    // Check command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filepath>\n", argv[0]);
        return 1;
    }

    // Allocate memory for hash string
    char *hash_string = malloc(SHA256_DIGEST_LENGTH * 2 + 1);
    if (hash_string == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Calculate SHA-256 hash
    if (calculate_sha256(argv[1], hash_string)) {
        printf("SHA-256 hash of %s: %s\n", argv[1], hash_string);
    } else {
        fprintf(stderr, "Failed to calculate hash\n");
        free(hash_string);
        return 1;
    }

    // Free allocated memory
    free(hash_string);
    return 0;
}

