#include <openssl/sha.h> // Required for SHA-256 functions

#define READ_BUFFER_SIZE 4096 // Read file in chunks of 4KB

/**
 * @brief Calculates the SHA-256 hash of a given file.
 *
 * @param filepath The path to the file.
 * @param output_hash A pre-allocated unsigned char array of size SHA256_DIGEST_LENGTH
 *                    to store the resulting hash.
 * @return 0 on success, -1 on failure (e.g., file not found, read error).
 */
int calculate_file_sha256(const char *filepath, unsigned char *output_hash) {
    FILE *file = NULL;
    SHA256_CTX sha256_ctx;
    unsigned char buffer[READ_BUFFER_SIZE];
    size_t bytes_read;
    int ret = -1; // Default to error

    // Initialize SHA-256 context
    if (SHA256_Init(&sha256_ctx) != 1) {
        fprintf(stderr, "Error: SHA256_Init failed.\n");
        return ret;
    }

    // Open the file in binary read mode
    file = fopen(filepath, "rb");
    if (file == NULL) {
        perror("Error opening file");
        return ret;
    }

    // Read file in chunks and update the SHA-256 context
    while ((bytes_read = fread(buffer, 1, READ_BUFFER_SIZE, file)) > 0) {
        if (SHA256_Update(&sha256_ctx, buffer, bytes_read) != 1) {
            fprintf(stderr, "Error: SHA256_Update failed.\n");
            goto cleanup;
        }
    }

    // Check for read errors (other than EOF)
    if (ferror(file)) {
        perror("Error reading file");
        goto cleanup;
    }

    // Finalize the hash calculation
    if (SHA256_Final(output_hash, &sha256_ctx) != 1) {
        fprintf(stderr, "Error: SHA256_Final failed.\n");
        goto cleanup;
    }

    ret = 0; // Success

cleanup:
    if (file != NULL) {
        fclose(file);
    }
    return ret;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filepath>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *filepath = argv[1];
    unsigned char hash[SHA256_DIGEST_LENGTH]; // SHA256_DIGEST_LENGTH is 32 bytes

    printf("Calculating SHA-256 for: %s\n", filepath);

    if (calculate_file_sha256(filepath, hash) == 0) {
        printf("SHA-256 Hash: ");
        for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
            printf("%02x", hash[i]); // Print each byte as a two-digit hexadecimal number
        }
        printf("\n");
        return EXIT_SUCCESS;
    } else {
        fprintf(stderr, "Failed to calculate SHA-256 hash for %s\n", filepath);
        return EXIT_FAILURE;
    }
}

