    for (int i = 0; message[i] != '\0'; i++) {
        char ch = toupper(message[i]);
        if (ch >= 'A' && ch <= 'Z') {
            strcat(encoded_message, morse_code[ch - 'A']);
        } else if (ch >= '0' && ch <= '9') {
            strcat(encoded_message, morse_code[ch - '0' + 26]);
        }
        strcat(encoded_message, " "); // Add space between Morse codes
    }
}

