    const char *token;
    char morse_word[MAX_MESSAGE_LENGTH];
    decoded_message[0] = '\0'; // Initialize decoded_message

    // Split the encoded message by spaces
    char *msg_copy = strdup(encoded_message);
    token = strtok(msg_copy, " ");

    while (token != NULL) {
        for (int i = 0; i < 36; i++) { // 26 letters + 10 digits
            if (strcmp(token, morse_code[i]) == 0) {
                if (i < 26) {
