// Function to encode a string into Morse code
void encode_to_morse(char* str) {
    for (int i = 0; i < strlen(str); i++) {
        char c = toupper(str[i]);
        if (c >= 'A' && c <= 'Z') {
            printf("%s ", morse_code_map[c - 'A']);
        } else if (c == ' ') {
            printf("/ ");
        } else if (c >= '0' && c <= '9') {
            printf("%s ", morse_code_numbers[c - '0']);
        } else {
            printf("Character '%c' is not supported.\n", c);
        }
    }
    printf("\n");
}

// Function to decode a Morse code string
void decode_from_morse(char* str) {
    char* token = strtok(str, " ");
    while (token!= NULL) {
        if (strcmp(token, "/") == 0) {
            printf(" ");
        } else {
            for (int i = 0; i < 26; i++) {
                if (strcmp(token, morse_code_map[i]) == 0) {
                    printf("%c", i + 'a');
                    break;
                }
            }
            for (int i = 0; i < 10; i++) {
                if (strcmp(token, morse_code_numbers[i]) == 0) {
                    printf("%d", i);
                    break;
                }
            }
        }
        token = strtok(NULL, " ");
    }
    printf("\n");
}

