// Function to print OpenSSL errors
void handleOpenSSLErrors(void) {
    fprintf(stderr, "OpenSSL Error(s):\n");
    ERR_print_errors_fp(stderr);
    exit(EXIT_FAILURE);
}

// Function to calculate SHA-256 hash of a file
int calculateFileSHA256(const char *filepath, unsigned char *hash) {
    FILE *file;
    SHA256_CTX sha256;
    int bytesRead;
    unsigned char buffer[8192]; // Increased buffer size for better performance

    // Initialize SHA256 context
    if (SHA256_Init(&sha256) != 1) {
        handleOpenSSLErrors();
    }

    // Open the file in binary read mode
    file = fopen(filepath, "rb");
    if (file == NULL) {
        perror("Error opening file");
        return 0; // Failure
    }

    // Read file in chunks and update SHA256 context
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        if (SHA256_Update(&sha256, buffer, bytesRead) != 1) {
            handleOpenSSLErrors();
        }
    }

    // Finalize SHA256 hash calculation
    if (SHA256_Final(hash, &sha256) != 1) {
        handleOpenSSLErrors();
    }

    // Close the file
    fclose(file);

    return 1; // Success
}

