// Function to generate SHA-256 hash of a file
void generate_sha256_hash(const char* filename) {
    // Open the file in binary mode
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error opening file: %s\n", filename);
        return;
    }

    // Get the file size
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    // Allocate memory for the file contents
    unsigned char* file_contents = (unsigned char*)malloc(file_size);
    if (file_contents == NULL) {
        printf("Error allocating memory\n");
        fclose(file);
        return;
    }

    // Read the file contents
    fread(file_contents, 1, file_size, file);
    fclose(file);

    // Generate SHA-256 hash
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256(file_contents, file_size, hash);

    // Print the hash
    printf("SHA-256 hash of %s: ", filename);
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        printf("%02x", hash[i]);
    }
    printf("\n");

    // Free allocated memory
    free(file_contents);
}

int main(int argc, char* argv[]) {
    if (argc!= 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    generate_sha256_hash(argv[1]);
    return 0;
}

