#include <string.h>

#define MAX_TOKENS 100
#define MAX_TOKEN_LENGTH 50

// Token types
typedef enum {
    TOKEN_IDENTIFIER,
    TOKEN_NUMBER,
    TOKEN_OPERATOR,
    TOKEN_UNKNOWN
} TokenType;

// Token structure
typedef struct {
    TokenType type;
    char value[MAX_TOKEN_LENGTH];
} Token;

// Function prototypes
Token* lexicalAnalyze(const char* input, int* tokenCount);
int isOperator(char c);
void printToken(Token token);

// Main lexical analyzer function
Token* lexicalAnalyze(const char* input, int* tokenCount) {
    Token* tokens = malloc(MAX_TOKENS * sizeof(Token));
    *tokenCount = 0;
    int inputLength = strlen(input);
    int i = 0;

    while (i < inputLength) {
        // Skip whitespace
        while (isspace(input[i])) {
            i++;
        }

        // Check for end of input
        if (i >= inputLength) {
            break;
        }

        // Identifier recognition
        if (isalpha(input[i]) || input[i] == '_') {
            Token token;
            token.type = TOKEN_IDENTIFIER;
            int j = 0;

            while (isalnum(input[i]) || input[i] == '_') {
                token.value[j++] = input[i++];
            }
            token.value[j] = '\0';

            tokens[(*tokenCount)++] = token;
        }
        // Number recognition
        else if (isdigit(input[i])) {
            Token token;
            token.type = TOKEN_NUMBER;
            int j = 0;

            while (isdigit(input[i])) {
                token.value[j++] = input[i++];
            }
            token.value[j] = '\0';

            tokens[(*tokenCount)++] = token;
        }
        // Operator recognition
        else if (isOperator(input[i])) {
            Token token;
            token.type = TOKEN_OPERATOR;
            token.value[0] = input[i];
            token.value[1] = '\0';

            tokens[(*tokenCount)++] = token;
            i++;
        }
        // Unknown token
        else {
            Token token;
            token.type = TOKEN_UNKNOWN;
            token.value[0] = input[i];
            token.value[1] = '\0';

            tokens[(*tokenCount)++] = token;
            i++;
        }
    }

    return tokens;
}

// Check if a character is an operator
int isOperator(char c) {
    char operators[] = {'+', '-', '*', '/', '=', '<', '>', '&', '|', '!'};
    for (int i = 0; i < sizeof(operators); i++) {
        if (c == operators[i]) {
            return 1;
        }
    }
    return 0;
}

// Print token details
void printToken(Token token) {
    const char* tokenTypes[] = {"IDENTIFIER", "NUMBER", "OPERATOR", "UNKNOWN"};
    printf("Token: %s, Value: %s\n", tokenTypes[token.type], token.value);
}

int main() {
    // Test input strings
    const char* testInputs[] = {
        "hello_world 123 + 456",
        "x = 10 * 20",
        "calculate_total = value1 + value2"
    };

    // Number of test inputs
    int numInputs = sizeof(testInputs) / sizeof(testInputs[0]);

    // Process each input
    for (int k = 0; k < numInputs; k++) {
        printf("Input: %s\n", testInputs[k]);

        int tokenCount;
        Token* tokens = lexicalAnalyze(testInputs[k], &tokenCount);

        // Print tokens
        for (int i = 0; i < tokenCount; i++) {
            printToken(tokens[i]);
        }

        printf("\n");

        // Free memory
        free(tokens);
    }

    return 0;
}

