// Function to perform lexical analysis
void lexicalAnalyzer(char *input) {
    int i = 0;
    while (i < strlen(input)) {
        // Skip whitespace
        if (isspace(input[i])) {
            i++;
            continue;
        }

        // Check for identifiers or keywords
        if (isalpha(input[i]) || input[i] == '_') {
            char identifier[100];
            int j = 0;
            while (isalnum(input[i]) || input[i] == '_') {
                identifier[j++] = input[i++];
            }
            identifier[j] = '\0';
            if (isKeyword(identifier)) {
                printf("Keyword: %s\n", identifier);
            } else {
                printf("Identifier: %s\n", identifier);
            }
            continue;
        }

        // Check for numbers
        if (isdigit(input[i])) {
            char number[100];
            int j = 0;
            while (isdigit(input[i]) || input[i] == '.') {
                number[j++] = input[i++];
            }
            number[j] = '\0';
            printf("Number: %s\n", number);
            continue;
        }

        // Check for operators
        if (isOperator(input[i])) {
            char operator[3];
            operator[0] = input[i];
            operator[1] = '\0';
            // Check for multi-character operators (e.g., ==, !=, <=, >=, &&, ||)
            if (i + 1 < strlen(input) && isOperator(input[i + 1])) {
                operator[1] = input[i + 1];
                operator[2] = '\0';
                i++;
            }
            printf("Operator: %s\n", operator);
            i++;
            continue;
        }

        // If none of the above, it's an unknown character
        printf("Unknown character: %c\n", input[i]);
        i++;
    }
}

