#include <stdio.h>
#include <ctype.h> // For isalnum, isalpha, isdigit
#include <string.h> // For strlen

// Define token types
typedef enum {
    TOKEN_IDENTIFIER,
    TOKEN_NUMBER,
    TOKEN_OPERATOR,
    TOKEN_UNKNOWN,
    TOKEN_EOF // End of file
} TokenType;

// Structure to hold the token information
typedef struct {
    TokenType type;
    char lexeme[100]; // Stores the actual text of the token
} Token;

// Global variables for the lexer
char *source_code; // Pointer to the input source code
int current_pos = 0; // Current position in the source code

// Function prototypes
void get_next_token(Token *token);
void skip_whitespace();
void print_token(const Token *token);

int main() {
    // Example source code to analyze
    // You can modify this string or read from a file
    char code[] = "int x = 10 + y / 2;\n"
                  "float pi = 3.14;\n"
                  "// This is a comment\n"
                  "/* This is a multi-line\n"
                  "   comment */\n"
                  "if (x > pi) {\n"
                  "   printf(\"Hello\");\n"
                  "}\n"
                  "123abc // unknown token\n";
    source_code = code;

    printf("Lexical Analysis:\n");
    printf("-------------------\n");

    Token token;
    do {
        get_next_token(&token);
        print_token(&token);
    } while (token.type != TOKEN_EOF);

    return 0;
}

// Skips whitespace characters (spaces, tabs, newlines) and comments
void skip_whitespace() {
    while (source_code[current_pos] != '\0') {
        char c = source_code[current_pos];
        if (isspace(c)) {
            current_pos++;
        } else if (c == '/' && source_code[current_pos + 1] == '/') { // Single-line comment
            current_pos += 2; // Skip '//'
            while (source_code[current_pos] != '\n' && source_code[current_pos] != '\0') {
                current_pos++;
            }
        } else if (c == '/' && source_code[current_pos + 1] == '*') { // Multi-line comment
            current_pos += 2; // Skip '/*'
            while (!(source_code[current_pos] == '*' && source_code[current_pos + 1] == '/') &&
                   source_code[current_pos] != '\0') {
                current_pos++;
            }
            if (source_code[current_pos] != '\0') { // Skip '*/' if found
                current_pos += 2;
            }
        } else {
            break; // Not whitespace or comment
        }
    }
}

// Gets the next token from the source code
void get_next_token(Token *token) {
    skip_whitespace();

    int lexeme_idx = 0;
    char current_char = source_code[current_pos];

    if (current_char == '\0') {
        token->type = TOKEN_EOF;
        strcpy(token->lexeme, "EOF");
        return;
    }

    // Identifiers: Start with a letter or underscore, followed by letters, digits, or underscores
    if (isalpha(current_char) || current_char == '_') {
        token->type = TOKEN_IDENTIFIER;
        while (isalnum(current_char) || current_char == '_') {
            token->lexeme[lexeme_idx++] = current_char;
            current_pos++;
            current_char = source_code[current_pos];
        }
        token->lexeme[lexeme_idx] = '\0';
        return;
    }

    // Numbers: Can be integers or floating-point numbers
    if (isdigit(current_char)) {
        token->type = TOKEN_NUMBER;
        while (isdigit(current_char)) {
            token->lexeme[lexeme_idx++] = current_char;
            current_pos++;
            current_char = source_code[current_pos];
        }
        // Handle floating-point numbers (e.g., 3.14)
        if (current_char == '.') {
            token->lexeme[lexeme_idx++] = current_char;
            current_pos++;
            current_char = source_code[current_pos];
            if (isdigit(current_char)) { // Must have at least one digit after the decimal point
                while (isdigit(current_char)) {
                    token->lexeme[lexeme_idx++] = current_char;
                    current_pos++;
                    current_char = source_code[current_pos];
                }
            } else {
                // If a dot is followed by a non-digit, treat the dot as an operator
                // and backtrack the character, e.g., "10.+"
                current_pos--; // Backtrack the dot
                current_char = source_code[current_pos]; // Get back the dot
                token->lexeme[--lexeme_idx] = '\0'; // Remove the dot from lexeme
                if (lexeme_idx == 0) { // If only a dot was encountered, it's an operator
                    token->type = TOKEN_OPERATOR;
                    token->lexeme[0] = '.';
                    token->lexeme[1] = '\0';
                    current_pos++; // Advance past the dot
                    return;
                }
            }
        }
        token->lexeme[lexeme_idx] = '\0';
        return;
    }

    // Operators: Simple single-character operators for now
    // You can extend this to handle multi-character operators like "==", ">=", "&&", "||"
    if (strchr("+-*/%=(){}[]<>;,", current_char) != NULL) {
        token->type = TOKEN_OPERATOR;
        token->lexeme[lexeme_idx++] = current_char;
        current_pos++;

        // Handle multi-character operators (simple examples)
        char next_char = source_code[current_pos];
        if ((current_char == '=' && next_char == '=') ||
            (current_char == '<' && next_char == '=') ||
            (current_char == '>' && next_char == '=') ||
            (current_char == '&' && next_char == '&') ||
            (current_char == '|' && next_char == '|')) {
            token->lexeme[lexeme_idx++] = next_char;
            current_pos++;
        }
        token->lexeme[lexeme_idx] = '\0';
        return;
    }

    // Unknown token
    token->type = TOKEN_UNKNOWN;
    token->lexeme[lexeme_idx++] = current_char;
    current_pos++;
    // If the next character is also unknown (e.g., "123abc"), consume consecutive unknown characters
    while (!isspace(source_code[current_pos]) && source_code[current_pos] != '\0' &&
           !isalnum(source_code[current_pos]) && strchr("+-*/%=(){}[]<>;,", source_code[current_pos]) == NULL) {
        token->lexeme[lexeme_idx++] = source_code[current_pos];
        current_pos++;
    }
    token->lexeme[lexeme_idx] = '\0';
}

// Prints the token information
void print_token(const Token *token) {
    printf("Token: %-15s Lexeme: \"%s\"\n",
           token->type == TOKEN_IDENTIFIER ? "IDENTIFIER" :
           token->type == TOKEN_NUMBER     ? "NUMBER" :
           token->type == TOKEN_OPERATOR   ? "OPERATOR" :
           token->type == TOKEN_UNKNOWN    ? "UNKNOWN" :
           token->type == TOKEN_EOF        ? "EOF" : "Error",
           token->lexeme);
}

#include <stdio.h>
