#define MAX 100

// Function to check if a character is an operator
int isOperator(char ch) {
    return ch == '+' || ch == '-' || ch == '*' || ch == '/' ||
           ch == '=' || ch == '<' || ch == '>' || ch == '%';
}

// Main analyzer function
void lexicalAnalyzer(FILE *fp) {
    char ch;
    char buffer[MAX];

    int i;

    while ((ch = fgetc(fp)) != EOF) {
        // Skip whitespace
        if (isspace(ch)) continue;

        // Identifier: [a-zA-Z_][a-zA-Z0-9_]*
        if (isalpha(ch) || ch == '_') {
            i = 0;
            buffer[i++] = ch;
            while ((ch = fgetc(fp)) != EOF && (isalnum(ch) || ch == '_')) {
                buffer[i++] = ch;
            }
            buffer[i] = '\0';
            printf("IDENTIFIER\t: %s\n", buffer);

            if (ch != EOF)
                ungetc(ch, fp); // push back for next lexeme
        }
        // Number: [0-9]+
        else if (isdigit(ch)) {
            i = 0;
            buffer[i++] = ch;
            while ((ch = fgetc(fp)) != EOF && isdigit(ch)) {
                buffer[i++] = ch;
            }
            buffer[i] = '\0';
            printf("NUMBER    \t: %s\n", buffer);

            if (ch != EOF)
                ungetc(ch, fp); // push back
        }
        // Operator: + - * / = < > %
        else if (isOperator(ch)) {
            printf("OPERATOR  \t: %c\n", ch);
        }
        // Unknown/Other
        else {
            printf("UNKNOWN   \t: %c\n", ch);
        }
    }
}

