#include <stdio.h>
#include <ctype.h>
#include <string.h>

// Define token types
typedef enum {
    TOKEN_IDENTIFIER,
    TOKEN_NUMBER,
    TOKEN_OPERATOR,
    TOKEN_UNKNOWN
} TokenType;

// Struct to hold a token
typedef struct {
    TokenType type;
    char value[100];
} Token;

// Function declarations
void analyze(const char *input);
void processIdentifier(const char **input, Token *token);
void processNumber(const char **input, Token *token);
void processOperator(const char **input, Token *token);

int main() {
    // Example input: change this string to test different inputs
    const char *input = "int sum = a + 20 * b;";
    analyze(input);
    return 0;
}

// Analyze the input string
void analyze(const char *input) {
    Token token;
    fprintf(stdout, "Analyzing: \"%s\"\n", input);

    while (*input != '\0') {
        if (isspace(*input)) {
            ++input;
        } else if (isalpha(*input) || *input == '_') {
            processIdentifier(&input, &token);
            fprintf(stdout, "[IDENTIFIER]: %s\n", token.value);
        } else if (isdigit(*input)) {
            processNumber(&input, &token);
            fprintf(stdout, "[NUMBER]: %s\n", token.value);
        } else if (strchr("+-*/=;", *input)) {
            processOperator(&input, &token);
            fprintf(stdout, "[OPERATOR]: %s\n", token.value);
        } else {
            fprintf(stderr, "Unknown character: %c\n", *input);
            ++input;
        }
    }
}

// Process an identifier
void processIdentifier(const char **input, Token *token) {
    char *write_ptr = token->value;

    // Start with a letter or underscore, followed by letters, digits, or underscores
    while (isalnum(**input) || **input == '_') {
        *write_ptr++ = **input;
        ++(*input);
    }

    *write_ptr = '\0';
    token->type = TOKEN_IDENTIFIER;
}

// Process a number
void processNumber(const char **input, Token *token) {
    char *write_ptr = token->value;

    while (isdigit(**input)) {
        *write_ptr++ = **input;
        ++(*input);
    }

    *write_ptr = '\0';
    token->type = TOKEN_NUMBER;
}

// Process an operator
void processOperator(const char **input, Token *token) {
    token->value[0] = **input;
    token->value[1] = '\0';
    token->type = TOKEN_OPERATOR;
    ++(*input);
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

#define MAX_LENGTH 100

enum TokenType {IDENTIFIER, NUMBER, OPERATOR, UNKNOWN};

struct Token {
    enum TokenType type;
    char value[MAX_LENGTH];
};

// Function declarations
void getToken(char *input, struct Token *token);
void printToken(struct Token *token);

int main() {
    char input[MAX_LENGTH];
    struct Token token;

    printf("Enter a string to analyze (CTRL+D to end):\n");

    // Read lines until EOF
    while (fgets(input, MAX_LENGTH, stdin) != NULL) {
        char *ptr = input;
        while (*ptr) {
            getToken(ptr, &token);
            if (token.type != UNKNOWN) {
                printToken(&token);
                ptr += strlen(token.value);
            } else {
                ptr++;
            }
        }
    }

    return 0;
}

void getToken(char *input, struct Token *token) {
    // Clear previous token value
    token->value[0] = '\0';

    // Skip whitespace
    while (isspace(*input)) {
        input++;
    }

    // Identify tokens
    if (isalpha(*input)) { // If it's an identifier
        int i = 0;
        while (isalpha(*input) || isdigit(*input) || *input == '_') {
            token->value[i++] = *input++;
        }
        token->value[i] = '\0';
        token->type = IDENTIFIER;

    } else if (isdigit(*input)) { // If it's a number
        int i = 0;
        while (isdigit(*input)) {
            token->value[i++] = *input++;
        }
        token->value[i] = '\0';
        token->type = NUMBER;

    } else if (strchr("+-*/", *input)) { // If it's an operator
        token->value[0] = *input++;
        token->value[1] = '\0';
        token->type = OPERATOR;

    } else if (*input != '\0') { // Unknown character
        token->value[0] = *input++;
        token->value[1] = '\0';
        token->type = UNKNOWN;
    } else { // End of string
        token->type = UNKNOWN;
    }
}

void printToken(struct Token *token) {
    switch (token->type) {
        case IDENTIFIER:
            printf("Identifier: %s\n", token->value);
            break;
        case NUMBER:
            printf("Number: %s\n", token->value);
            break;
        case OPERATOR:
            printf("Operator: %s\n", token->value);
            break;
        case UNKNOWN:
        default:
            printf("Unknown token: %s\n", token->value);
            break;
    }
}

#include <stdio.h>
#include <ctype.h>
#include <string.h>

// Token types
typedef enum {
    ID_TOKEN,
    NUM_TOKEN,
    OPERATOR_TOKEN,
    ERROR_TOKEN,
    END_OF_FILE_TOKEN
} token_type;

// Token structure
typedef struct {
    token_type type;
    char* value;
} token;

// Lexical analyzer function
token* lexical_analyzer(char* input) {
    token* tokens = NULL;
    int token_count = 0;
    char* current_token = NULL;

    // Loop through each character in the input
    for (int i = 0; i < strlen(input); i++) {
        // Check for whitespace
        if (isspace(input[i])) {
            continue;
        }

        // Check for identifiers (variable names)
        if (isalpha(input[i])) {
            current_token = (char*) malloc(sizeof(char) * (strlen(input) - i + 1));
            int j = 0;
            while (isalnum(input[i + j])) {
                current_token[j] = input[i + j];
                j++;
            }
            current_token[j] = '\0';
            i += j - 1;

            // Create a new token for the identifier
            token* new_token = (token*) malloc(sizeof(token));
            new_token->type = ID_TOKEN;
            new_token->value = current_token;
            tokens = (token*) realloc(tokens, sizeof(token) * (token_count + 1));
            tokens[token_count] = *new_token;
            token_count++;
            free(new_token);
            continue;
        }

        // Check for numbers
        if (isdigit(input[i])) {
            current_token = (char*) malloc(sizeof(char) * (strlen(input) - i + 1));
            int j = 0;
            while (isdigit(input[i + j])) {
                current_token[j] = input[i + j];
                j++;
            }
            current_token[j] = '\0';
            i += j - 1;

            // Create a new token for the number
            token* new_token = (token*) malloc(sizeof(token));
            new_token->type = NUM_TOKEN;
            new_token->value = current_token;
            tokens = (token*) realloc(tokens, sizeof(token) * (token_count + 1));
            tokens[token_count] = *new_token;
            token_count++;
            free(new_token);
            continue;
        }

        // Check for operators
        if (input[i] == '+' || input[i] == '-' || input[i] == '*' || input[i] == '/') {
            // Create a new token for the operator
            token* new_token = (token*) malloc(sizeof(token));
            new_token->type = OPERATOR_TOKEN;
            new_token->value = (char*) malloc(sizeof(char) * 2);
            new_token->value[0] = input[i];
            new_token->value[1] = '\0';
            tokens = (token*) realloc(tokens, sizeof(token) * (token_count + 1));
            tokens[token_count] = *new_token;
            token_count++;
            free(new_token);
        }

        // If none of the above, it's an error
        else {
            token* new_token = (token*) malloc(sizeof(token));
            new_token->type = ERROR_TOKEN;
            new_token->value = (char*) malloc(sizeof(char) * (strlen("Error: invalid character") + 1));
            strcpy(new_token->value, "Error: invalid character");
            tokens = (token*) realloc(tokens, sizeof(token) * (token_count + 1));
            tokens[token_count] = *new_token;
            token_count++;
            free(new_token);
        }
    }

    // Create an end-of-file token
    token* eof_token = (token*) malloc(sizeof(token));
    eof_token->type = END_OF_FILE_TOKEN;
    eof_token->value = (char*) malloc(sizeof(char) * (strlen("End of file") + 1));
    strcpy(eof_token->value, "End of file");
    tokens = (token*) realloc(tokens, sizeof(token) * (token_count + 1));
    tokens[token_count] = *eof_token;
    token_count++;

    return tokens;
}

// Print tokens
void print_tokens(token* tokens, int token_count) {
    for (int i = 0; i < token_count; i++) {
        switch (tokens[i].type) {
            case ID_TOKEN:
                printf("ID: %s\n", tokens[i].value);
                break;
            case NUM_TOKEN:
                printf("NUM: %s\n", tokens[i].value);
                break;
            case OPERATOR_TOKEN:
                printf("OPERATOR: %s\n", tokens[i].value);
                break;
            case ERROR_TOKEN:
                printf("%s\n", tokens[i].value);
                break;
            case END_OF_FILE_TOKEN:
                printf("%s\n", tokens[i].value);
                break;
        }
    }
}

// Main function
int main() {
    char input[] = "x = 5 + 3 * y";
    token* tokens = lexical_analyzer(input);
    int token_count = sizeof(input) / sizeof(token) + 1;
    print_tokens(tokens, token_count);

    return 0;
}

#include <stdio.h>
#include <ctype.h>
#include <string.h>

#define MAX_IDENTIFIER_LENGTH 32
#define MAX_NUMBER_LENGTH 10

// Token types
typedef enum {
    TOKEN_IDENTIFIER,
    TOKEN_NUMBER,
    TOKEN_OPERATOR,
    TOKEN_EOF,
    TOKEN_ERROR
} TokenType;

// Token structure
typedef struct {
    TokenType type;
    char value[MAX_IDENTIFIER_LENGTH + 1];
} Token;

// Function prototypes
void skip_whitespace(char **input);
Token get_next_token(char **input);
int is_identifier_start(char c);
int is_identifier_char(char c);
int is_number_char(char c);
int is_operator(char c);

int main() {
    char input[] = "x = 42 + y * z";
    char *input_ptr = input;
    Token token;

    printf("Input: %s\n", input);
    printf("Tokens:\n");

    while ((token = get_next_token(&input_ptr)).type != TOKEN_EOF) {
        switch (token.type) {
            case TOKEN_IDENTIFIER:
                printf("IDENTIFIER: %s\n", token.value);
                break;
            case TOKEN_NUMBER:
                printf("NUMBER: %s\n", token.value);
                break;
            case TOKEN_OPERATOR:
                printf("OPERATOR: %s\n", token.value);
                break;
            case TOKEN_ERROR:
                printf("ERROR: Invalid token '%s'\n", token.value);
                break;
            default:
                printf("UNKNOWN TOKEN\n");
                break;
        }
    }

    printf("EOF\n");
    return 0;
}

void skip_whitespace(char **input) {
    while (isspace(**input)) {
        (*input)++;
    }
}

Token get_next_token(char **input) {
    Token token = {TOKEN_ERROR, ""};
    char *start = *input;

    // Skip whitespace
    skip_whitespace(input);

    if (**input == '\0') {
        token.type = TOKEN_EOF;
        return token;
    }

    // Check for identifier
    if (is_identifier_start(**input)) {
        while (is_identifier_char(**input)) {
            (*input)++;
        }
        token.type = TOKEN_IDENTIFIER;
        strncpy(token.value, start, *input - start);
        token.value[*input - start] = '\0';
        return token;
    }

    // Check for number
    if (isdigit(**input)) {
        while (is_number_char(**input)) {
            (*input)++;
        }
        token.type = TOKEN_NUMBER;
        strncpy(token.value, start, *input - start);
        token.value[*input - start] = '\0';
        return token;
    }

    // Check for operator
    if (is_operator(**input)) {
        (*input)++;
        token.type = TOKEN_OPERATOR;
        token.value[0] = *start;
        token.value[1] = '\0';
        return token;
    }

    // If none of the above, it's an error
    (*input)++;
    token.value[0] = *start;
    token.value[1] = '\0';
    return token;
}

int is_identifier_start(char c) {
    return isalpha(c) || c == '_';
}

int is_identifier_char(char c) {
    return isalpha(c) || isdigit(c) || c == '_';
}

int is_number_char(char c) {
    return isdigit(c) || c == '.';
}

int is_operator(char c) {
    static const char *operators = "=+-*/%!<>^&|(){}[],;:";
    return strchr(operators, c) != NULL;
}

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

// Priority Queue structure using binary heap
typedef struct {
    int* heap;        // Dynamic array to store heap elements
    int capacity;     // Maximum capacity of the heap
    int size;         // Current number of elements in the heap
} PriorityQueue;

// Function prototypes
PriorityQueue* createPriorityQueue(int capacity);
void swap(int* a, int* b);
void heapifyUp(PriorityQueue* pq, int index);
void heapifyDown(PriorityQueue* pq, int index);
void insertElement(PriorityQueue* pq, int value);
int extractMax(PriorityQueue* pq);
int peekMax(PriorityQueue* pq);
int isEmpty(PriorityQueue* pq);
void printPriorityQueue(PriorityQueue* pq);
void freePriorityQueue(PriorityQueue* pq);

// Create a new priority queue
PriorityQueue* createPriorityQueue(int capacity) {
    PriorityQueue* pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    if (pq == NULL) {
        printf("Memory allocation failed!\n");
        exit(1);
    }

    pq->heap = (int*)malloc(capacity * sizeof(int));
    if (pq->heap == NULL) {
        printf("Memory allocation failed!\n");
        free(pq);
        exit(1);
    }

    pq->capacity = capacity;
    pq->size = 0;

    return pq;
}

// Swap two elements
void swap(int* a, int* b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

// Heapify up after insertion
void heapifyUp(PriorityQueue* pq, int index) {
    int parent = (index - 1) / 2;

    if (index > 0 && pq->heap[index] > pq->heap[parent]) {
        swap(&pq->heap[index], &pq->heap[parent]);
        heapifyUp(pq, parent);
    }
}

// Heapify down after extraction
void heapifyDown(PriorityQueue* pq, int index) {
    int left = 2 * index + 1;
    int right = 2 * index + 2;
    int largest = index;

    if (left < pq->size && pq->heap[left] > pq->heap[largest]) {
        largest = left;
    }

    if (right < pq->size && pq->heap[right] > pq->heap[largest]) {
        largest = right;
    }

    if (largest != index) {
        swap(&pq->heap[index], &pq->heap[largest]);
        heapifyDown(pq, largest);
    }
}

// Insert an element into the priority queue
void insertElement(PriorityQueue* pq, int value) {
    if (pq->size == pq->capacity) {
        printf("Priority queue is full. Cannot insert.\n");
        return;
    }

    pq->heap[pq->size] = value;
    heapifyUp(pq, pq->size);
    pq->size++;
}

// Extract the maximum element from the priority queue
int extractMax(PriorityQueue* pq) {
    if (isEmpty(pq)) {
        printf("Priority queue is empty.\n");
        return INT_MIN;
    }

    int max = pq->heap[0];
    pq->heap[0] = pq->heap[pq->size - 1];
    pq->size--;
    heapifyDown(pq, 0);

    return max;
}

// Peek at the maximum element without extracting
int peekMax(PriorityQueue* pq) {
    if (isEmpty(pq)) {
        printf("Priority queue is empty.\n");
        return INT_MIN;
    }

    return pq->heap[0];
}

// Check if the priority queue is empty
int isEmpty(PriorityQueue* pq) {
    return pq->size == 0;
}

// Print the priority queue
void printPriorityQueue(PriorityQueue* pq) {
    printf("Priority Queue: ");
    for (int i = 0; i < pq->size; i++) {
        printf("%d ", pq->heap[i]);
    }
    printf("\n");
}

// Free memory allocated for the priority queue
void freePriorityQueue(PriorityQueue* pq) {
    free(pq->heap);
    free(pq);
}

// Main function to demonstrate priority queue usage
int main() {
    int capacity = 10;
    PriorityQueue* pq = createPriorityQueue(capacity);

    // Insert elements
    insertElement(pq, 10);
    insertElement(pq, 5);
    insertElement(pq, 15);
    insertElement(pq, 8);
    insertElement(pq, 20);

    // Print the priority queue
    printPriorityQueue(pq);

    // Extract max element
    printf("Max element: %d\n", extractMax(pq));

    // Print updated priority queue
    printPriorityQueue(pq);

    // Peek max element
    printf("Current max element: %d\n", peekMax(pq));

    // Free memory
    freePriorityQueue(pq);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAX_HEAP_SIZE 100

typedef struct {
    int priority;
    int data;
} HeapItem;

typedef struct {
    HeapItem items[MAX_HEAP_SIZE];
    int size;
} PriorityQueue;

void swap(HeapItem *a, HeapItem *b) {
    HeapItem temp = *a;
    *a = *b;
    *b = temp;
}

void heapify_up(PriorityQueue *pq, int index) {
    while (index > 0) {
        int parent_index = (index - 1) / 2;
        if (pq->items[index].priority > pq->items[parent_index].priority) {
            swap(&pq->items[index], &pq->items[parent_index]);
            index = parent_index;
        } else {
            break;
        }
    }
}

void heapify_down(PriorityQueue *pq, int index) {
    int left_child, right_child, largest;
    while (1) {
        left_child = 2 * index + 1;
        right_child = 2 * index + 2;
        largest = index;

        if (left_child < pq->size && pq->items[left_child].priority > pq->items[largest].priority) {
            largest = left_child;
        }

        if (right_child < pq->size && pq->items[right_child].priority > pq->items[largest].priority) {
            largest = right_child;
        }

        if (largest != index) {
            swap(&pq->items[index], &pq->items[largest]);
            index = largest;
        } else {
            break;
        }
    }
}

void insert(PriorityQueue *pq, int data, int priority) {
    if (pq->size >= MAX_HEAP_SIZE) {
        printf("Priority queue is full!\n");
        return;
    }

    pq->items[pq->size].data = data;
    pq->items[pq->size].priority = priority;
    heapify_up(pq, pq->size);
    pq->size++;
}

int extract_max(PriorityQueue *pq) {
    if (pq->size <= 0) {
        printf("Priority queue is empty!\n");
        return -1;
    }

    int max_data = pq->items[0].data;
    pq->items[0] = pq->items[pq->size - 1];
    pq->size--;
    heapify_down(pq, 0);
    return max_data;
}

int peek(PriorityQueue *pq) {
    if (pq->size <= 0) {
        printf("Priority queue is empty!\n");
        return -1;
    }

    return pq->items[0].data;
}

int is_empty(PriorityQueue *pq) {
    return pq->size == 0;
}

int main() {
    PriorityQueue pq = { .size = 0 };

    insert(&pq, 10, 2);
    insert(&pq, 20, 5);
    insert(&pq, 30, 1);
    insert(&pq, 40, 3);

    printf("Peek: %d\n", peek(&pq)); // Should print 20

    printf("Extract Max: %d\n", extract_max(&pq)); // Should print 20
    printf("Extract Max: %d\n", extract_max(&pq)); // Should print 40
    printf("Extract Max: %d\n", extract_max(&pq)); // Should print 10
    printf("Extract Max: %d\n", extract_max(&pq)); // Should print 30

    if (is_empty(&pq)) {
        printf("Priority queue is empty.\n");
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h> // For bool type

// Structure to represent an element in the priority queue
// You can customize this to hold more complex data
typedef struct {
    int priority; // Lower value = higher priority
    int data;     // Example data
} HeapNode;

// Structure to represent the Priority Queue (Min-Heap)
typedef struct {
    HeapNode* heapArray; // Array to store heap elements
    int capacity;        // Maximum capacity of the heap
    int size;            // Current number of elements in the heap
} PriorityQueue;

// --- Helper Functions for Heap Operations ---

// Function to swap two HeapNode elements
void swap(HeapNode* a, HeapNode* b) {
    HeapNode temp = *a;
    *a = *b;
    *b = temp;
}

// Function to get the parent index
int parent(int i) {
    return (i - 1) / 2;
}

// Function to get the left child index
int leftChild(int i) {
    return (2 * i + 1);
}

// Function to get the right child index
int rightChild(int i) {
    return (2 * i + 2);
}

// --- Priority Queue API Functions ---

// Initializes a new priority queue with a given capacity
PriorityQueue* initPriorityQueue(int capacity) {
    PriorityQueue* pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    if (pq == NULL) {
        perror("Failed to allocate PriorityQueue");
        return NULL;
    }

    pq->heapArray = (HeapNode*)malloc(sizeof(HeapNode) * capacity);
    if (pq->heapArray == NULL) {
        perror("Failed to allocate heapArray");
        free(pq);
        return NULL;
    }

    pq->capacity = capacity;
    pq->size = 0;
    return pq;
}

// Frees the memory allocated for the priority queue
void freePriorityQueue(PriorityQueue* pq) {
    if (pq == NULL) return;
    free(pq->heapArray);
    free(pq);
}

// Checks if the priority queue is empty
bool isEmpty(PriorityQueue* pq) {
    return pq->size == 0;
}

// Checks if the priority queue is full
bool isFull(PriorityQueue* pq) {
    return pq->size == pq->capacity;
}

// Min-heapify (heapify down) function:
// Ensures the subtree rooted at 'idx' satisfies the min-heap property.
void minHeapify(PriorityQueue* pq, int idx) {
    int smallest = idx;
    int left = leftChild(idx);
    int right = rightChild(idx);

    // If left child is smaller than current smallest
    if (left < pq->size && pq->heapArray[left].priority < pq->heapArray[smallest].priority) {
        smallest = left;
    }

    // If right child is smaller than current smallest
    if (right < pq->size && pq->heapArray[right].priority < pq->heapArray[smallest].priority) {
        smallest = right;
    }

    // If smallest is not the root, swap and recursively heapify the affected subtree
    if (smallest != idx) {
        swap(&pq->heapArray[idx], &pq->heapArray[smallest]);
        minHeapify(pq, smallest);
    }
}

// Inserts an element into the priority queue
void insert(PriorityQueue* pq, int priority, int data) {
    if (isFull(pq)) {
        printf("Priority Queue is full. Cannot insert.\n");
        return;
    }

    // Insert the new element at the end of the array
    pq->size++;
    int i = pq->size - 1;
    pq->heapArray[i].priority = priority;
    pq->heapArray[i].data = data;

    // Fix the min-heap property by bubbling up
    // While the element at 'i' is smaller than its parent
    while (i != 0 && pq->heapArray[parent(i)].priority > pq->heapArray[i].priority) {
        swap(&pq->heapArray[i], &pq->heapArray[parent(i)]);
        i = parent(i);
    }
    printf("Inserted: Priority %d, Data %d\n", priority, data);
}

// Extracts the minimum element (highest priority) from the priority queue
// Returns the HeapNode, or an empty node if the queue is empty
HeapNode extractMin(PriorityQueue* pq) {
    HeapNode emptyNode = {-1, -1}; // Represent an invalid/empty node

    if (isEmpty(pq)) {
        printf("Priority Queue is empty. Cannot extract minimum.\n");
        return emptyNode;
    }

    // If there's only one element, just remove it
    if (pq->size == 1) {
        pq->size--;
        return pq->heapArray[0];
    }

    // Store the minimum value to return
    HeapNode root = pq->heapArray[0];

    // Move the last element to the root position
    pq->heapArray[0] = pq->heapArray[pq->size - 1];
    pq->size--;

    // Heapify down the new root to maintain heap property
    minHeapify(pq, 0);

    return root;
}

// Peeks at the minimum element (highest priority) without removing it
// Returns the HeapNode, or an empty node if the queue is empty
HeapNode peekMin(PriorityQueue* pq) {
    HeapNode emptyNode = {-1, -1}; // Represent an invalid/empty node

    if (isEmpty(pq)) {
        printf("Priority Queue is empty. Nothing to peek.\n");
        return emptyNode;
    }
    return pq->heapArray[0];
}

// Utility function to print the heap array (for debugging)
void printPriorityQueue(PriorityQueue* pq) {
    if (isEmpty(pq)) {
        printf("Priority Queue is empty.\n");
        return;
    }
    printf("Priority Queue elements (priority, data): [");
    for (int i = 0; i < pq->size; i++) {
        printf("(%d, %d)", pq->heapArray[i].priority, pq->heapArray[i].data);
        if (i < pq->size - 1) {
            printf(", ");
        }
    }
    printf("]\n");
}

// --- Main function for demonstration ---
int main() {
    int capacity = 10;
    PriorityQueue* pq = initPriorityQueue(capacity);

    if (pq == NULL) {
        return 1; // Exit if initialization failed
    }

    printf("Priority Queue initialized with capacity %d\n", capacity);

    insert(pq, 5, 101);
    insert(pq, 3, 202);
    insert(pq, 8, 303);
    insert(pq, 1, 404);
    insert(pq, 7, 505);
    insert(pq, 2, 606);
    insert(pq, 6, 707);

    printPriorityQueue(pq);

    HeapNode minNode = peekMin(pq);
    if (minNode.priority != -1) {
        printf("Peeked min: Priority %d, Data %d\n", minNode.priority, minNode.data);
    }

    printf("\nExtracting elements:\n");
    while (!isEmpty(pq)) {
        HeapNode extracted = extractMin(pq);
        printf("Extracted: Priority %d, Data %d\n", extracted.priority, extracted.data);
        printPriorityQueue(pq); // Show state after each extraction
    }

    // Try extracting from an empty queue
    extractMin(pq);

    freePriorityQueue(pq);
    printf("\nPriority Queue freed.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAX_HEAP_SIZE 100

typedef struct {
    int data[MAX_HEAP_SIZE];
    int size;
} PriorityQueue;

// Function prototypes
void init(PriorityQueue *pq);
void push(PriorityQueue *pq, int value);
int pop(PriorityQueue *pq);
int top(PriorityQueue *pq);
int isEmpty(PriorityQueue *pq);

// Helper functions
void swap(int *a, int *b);
void heapifyUp(PriorityQueue *pq, int index);
void heapifyDown(PriorityQueue *pq, int index);

int main() {
    PriorityQueue pq;
    init(&pq);

    push(&pq, 10);
    push(&pq, 4);
    push(&pq, 15);
    push(&pq, 20);
    push(&pq, 0);

    printf("Priority Queue (max first):\n");
    while (!isEmpty(&pq)) {
        printf("%d ", pop(&pq));
    }
    printf("\n");
    return 0;
}

// Initialize the priority queue
void init(PriorityQueue *pq) {
    pq->size = 0;
}

// Swap helper
void swap(int *a, int *b) {
    int tmp = *a;
    *a = *b;
    *b = tmp;
}

// Insert an element into the priority queue
void push(PriorityQueue *pq, int value) {
    if (pq->size >= MAX_HEAP_SIZE) {
        printf("Heap overflow!\n");
        return;
    }
    pq->data[pq->size] = value;
    heapifyUp(pq, pq->size);
    pq->size++;
}

// Restore heap upwards
void heapifyUp(PriorityQueue *pq, int idx) {
    if (idx == 0)
        return;
    int parent = (idx - 1) / 2;
    if (pq->data[parent] < pq->data[idx]) {
        swap(&pq->data[parent], &pq->data[idx]);
        heapifyUp(pq, parent);
    }
}

// Remove and return the maximum element
int pop(PriorityQueue *pq) {
    if (pq->size == 0) {
        printf("Heap underflow!\n");
        return -1;
    }
    int result = pq->data[0];
    pq->data[0] = pq->data[pq->size - 1];
    pq->size--;
    heapifyDown(pq, 0);
    return result;
}

// Restore heap downwards
void heapifyDown(PriorityQueue *pq, int idx) {
    int left = idx * 2 + 1;
    int right = idx * 2 + 2;
    int largest = idx;

    if (left < pq->size && pq->data[left] > pq->data[largest])
        largest = left;
    if (right < pq->size && pq->data[right] > pq->data[largest])
        largest = right;

    if (largest != idx) {
        swap(&pq->data[idx], &pq->data[largest]);
        heapifyDown(pq, largest);
    }
}

// Return the maximum element without removing it
int top(PriorityQueue *pq) {
    if (pq->size == 0) {
        printf("Heap is empty!\n");
        return -1;
    }
    return pq->data[0];
}

int isEmpty(PriorityQueue *pq) {
    return pq->size == 0;
}

