typedef struct {
    int *array; // array that holds the heap
    int capacity; // maximum number of elements
    int size; // current number of elements
} PriorityQueue;

// Function prototypes
PriorityQueue* createPriorityQueue(int capacity);
void destroyPriorityQueue(PriorityQueue* pq);
void insert(PriorityQueue* pq, int value);
int extractMax(PriorityQueue* pq);
int peekMax(PriorityQueue* pq);
int isEmpty(PriorityQueue* pq);
void heapifyUp(PriorityQueue* pq, int index);
void heapifyDown(PriorityQueue* pq, int index);

// Creates a priority queue with a given capacity
PriorityQueue* createPriorityQueue(int capacity) {
    PriorityQueue* pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    pq->capacity = capacity;
    pq->size = 0;
    pq->array = (int*)malloc(capacity * sizeof(int));
    return pq;
}

// Destroys the priority queue and frees memory
void destroyPriorityQueue(PriorityQueue* pq) {
    free(pq->array);
    free(pq);
}

// Inserts a value into the priority queue
void insert(PriorityQueue* pq, int value) {
    if (pq->size == pq->capacity) {
        printf("Priority Queue is full\n");
        return;
    }
    pq->array[pq->size] = value;
    pq->size++;
    heapifyUp(pq, pq->size - 1);
}

// Helper function to maintain heap property after insertion
void heapifyUp(PriorityQueue* pq, int index) {
    int parent = (index - 1) / 2;
    // Ensure the node is not the root and the parent is smaller
    while (index > 0 && pq->array[parent] < pq->array[index]) {
        // Swap values
        int temp = pq->array[parent];
        pq->array[parent] = pq->array[index];
        pq->array[index] = temp;
        index = parent;
        parent = (index - 1) / 2;
    }
}

// Extracts the maximum value (highest priority) from the priority queue
int extractMax(PriorityQueue* pq) {
    if (pq->size == 0) {
        printf("Priority Queue is empty\n");
        return INT_MIN; // or handle underflow
    }
    int max = pq->array[0];
    pq->array[0] = pq->array[pq->size - 1];
    pq->size--;
    heapifyDown(pq, 0);
    return max;
}

// Helper function to maintain heap property after extraction
void heapifyDown(PriorityQueue* pq, int index) {
    int largest = index;
    int left = 2 * index + 1;
    int right = 2 * index + 2;

    if (left < pq->size && pq->array[left] > pq->array[largest]) {
        largest = left;
    }
    if (right < pq->size && pq->array[right] > pq->array[largest]) {
        largest = right;
    }
    if (largest != index) {
        // Swap values and continue heapifying down
        int temp = pq->array[index];
        pq->array[index] = pq->array[largest];
        pq->array[largest] = temp;
        heapifyDown(pq, largest);
    }
}

// Returns the maximum value (highest priority) without removing it
int peekMax(PriorityQueue* pq) {
    if (pq->size == 0) {
        printf("Priority Queue is empty\n");
        return INT_MIN; // or handle underflow
    }
    return pq->array[0];
}

// Check if the priority queue is empty
int isEmpty(PriorityQueue* pq) {
    return pq->size == 0;
}

