// Define the structure for a heap node
typedef struct Node {
    int value;
    int priority;
} Node;

// Define the structure for the heap
typedef struct Heap {
    Node* nodes;
    int capacity;
    int size;
} Heap;

// Function to swap two nodes
void swap(Node* a, Node* b) {
    Node temp = *a;
    *a = *b;
    *b = temp;
}

// Function to heapify the heap
void heapify(Heap* heap, int index) {
    int smallest = index;
    int left = 2 * index + 1;
    int right = 2 * index + 2;

    if (left < heap->size && heap->nodes[left].priority < heap->nodes[smallest].priority) {
        smallest = left;
    }

    if (right < heap->size && heap->nodes[right].priority < heap->nodes[smallest].priority) {
        smallest = right;
    }

    if (smallest != index) {
        swap(&heap->nodes[index], &heap->nodes[smallest]);
        heapify(heap, smallest);
    }
}

// Function to insert a node into the heap
void insert(Heap* heap, int value, int priority) {
    if (heap->size == heap->capacity) {
        printf("Heap is full. Cannot insert more elements.\n");
        return;
    }

    heap->nodes[heap->size].value = value;
    heap->nodes[heap->size].priority = priority;
    heap->size++;

    int index = heap->size - 1;
    while (index > 0 && heap->nodes[index].priority < heap->nodes[(index - 1) / 2].priority) {
        swap(&heap->nodes[index], &heap->nodes[(index - 1) / 2]);
        index = (index - 1) / 2;
    }
}

// Function to extract the minimum element from the heap
Node extractMin(Heap* heap) {
    if (heap->size == 0) {
        printf("Heap is empty. Cannot extract more elements.\n");
        Node dummy;
        dummy.value = -1;
        dummy.priority = -1;
        return dummy;
    }

    Node min = heap->nodes[0];
    heap->nodes[0] = heap->nodes[heap->size - 1];
    heap->size--;

    heapify(heap, 0);

    return min;
}

// Function to print the heap
void printHeap(Heap* heap) {
    for (int i = 0; i < heap->size; i++) {
        printf("Value: %d, Priority: %d\n", heap->nodes[i].value, heap->nodes[i].priority);
    }
}

int main() {
    int capacity = 10;
    Heap* heap = (Heap*)malloc(sizeof(Heap));
    heap->nodes = (Node*)malloc(capacity * sizeof(Node));
    heap->capacity = capacity;
    heap->size = 0;

    // Insert elements into the heap
    insert(heap, 5, 3);
    insert(heap, 10, 1);
    insert(heap, 15, 2);
    insert(heap, 20, 4);

    printf("Heap elements:\n");
    printHeap(heap);

    // Extract the minimum element
    Node min = extractMin(heap);
    printf("Extracted minimum element: Value = %d, Priority = %d\n", min.value, min.priority);

    printf("Heap elements after extraction:\n");
    printHeap(heap);

    free(heap->nodes);
    free(heap);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAX_HEAP_SIZE 100

typedef struct {
    int* elements;
    int size;
} PriorityQueue;

// Function prototypes
void init(PriorityQueue* pq);
int parent(int index);
int leftChild(int index);
int rightChild(int index);
void swap(int* arr, int i, int j);
void minHeapify(PriorityQueue* pq, int index);
void insert(PriorityQueue* pq, int value);
int extractMin(PriorityQueue* pq);
int getMin(PriorityQueue* pq);
void printHeap(PriorityQueue* pq);

// Initialize the priority queue
void init(PriorityQueue* pq) {
    pq->elements = (int*)malloc(MAX_HEAP_SIZE * sizeof(int));
    pq->size = 0;
}

// Return the parent index of the given index
int parent(int index) {
    return (index - 1) / 2;
}

// Return the left child index of the given index
int leftChild(int index) {
    return 2 * index + 1;
}

// Return the right child index of the given index
int rightChild(int index) {
    return 2 * index + 2;
}

// Swap two elements in the array
void swap(int* arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

// Ensure the min-heap property is maintained
void minHeapify(PriorityQueue* pq, int index) {
    int smallest = index;
    int left = leftChild(index);
    int right = rightChild(index);

    if (left < pq->size && pq->elements[left] < pq->elements[smallest]) {
        smallest = left;
    }

    if (right < pq->size && pq->elements[right] < pq->elements[smallest]) {
        smallest = right;
    }

    if (smallest != index) {
        swap(pq->elements, index, smallest);
        minHeapify(pq, smallest);
    }
}

// Insert a new element into the priority queue
void insert(PriorityQueue* pq, int value) {
    if (pq->size >= MAX_HEAP_SIZE) {
        printf("Heap overflow\n");
        return;
    }

    pq->size++;
    int i = pq->size - 1;
    pq->elements[i] = value;

    while (i != 0 && pq->elements[parent(i)] > pq->elements[i]) {
        swap(pq->elements, i, parent(i));
        i = parent(i);
    }
}

// Extract the minimum element from the priority queue
int extractMin(PriorityQueue* pq) {
    if (pq->size <= 0) {
        printf("Heap underflow\n");
        return -1;
    }

    int root = pq->elements[0];
    pq->elements[0] = pq->elements[pq->size - 1];
    pq->size--;
    minHeapify(pq, 0);

    return root;
}

// Get the minimum element from the priority queue without removing it
int getMin(PriorityQueue* pq) {
    if (pq->size == 0) {
        printf("Heap is empty\n");
        return -1;
    }
    return pq->elements[0];
}

// Print the heap
void printHeap(PriorityQueue* pq) {
    for (int i = 0; i < pq->size; i++) {
        printf("%d ", pq->elements[i]);
    }
    printf("\n");
}

// Main function to demonstrate the priority queue
int main() {
    PriorityQueue pq;
    init(&pq);

    insert(&pq, 3);
    insert(&pq, 2);
    insert(&pq, 15);
    insert(&pq, 5);
    insert(&pq, 4);
    insert(&pq, 45);

    printf("Heap after insertion:\n");
    printHeap(&pq);

    printf("Minimum element: %d\n", getMin(&pq));

    int extractedMin = extractMin(&pq);
    printf("Extracted minimum element: %d\n", extractedMin);

    printf("Heap after extraction:\n");
    printHeap(&pq);

    free(pq.elements); // Free allocated memory
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Vector structure for 3D points and directions
typedef struct {
    float x, y, z;
} Vec3;

// Sphere object definition
typedef struct {
    Vec3 center;
    float radius;
    char color;
} Sphere;

// Ray structure
typedef struct {
    Vec3 origin;
    Vec3 direction;
} Ray;

// Function prototypes
Vec3 vec3_subtract(Vec3 a, Vec3 b);
float vec3_dot(Vec3 a, Vec3 b);
float vec3_length(Vec3 v);
Vec3 vec3_normalize(Vec3 v);
float ray_sphere_intersect(Ray ray, Sphere sphere);

// Scene setup
#define WIDTH 80
#define HEIGHT 40
#define MAX_SPHERES 5

// Scene objects
Sphere spheres[MAX_SPHERES] = {
    {{0, 0, -10}, 3, 'O'},   // Large sphere
    {{-4, 2, -8}, 1.5, '*'}, // Smaller sphere
    {{4, -2, -12}, 2, '+'},  // Another sphere
    {{0, 5, -15}, 2.5, '%'}, // High sphere
    {{-3, -3, -7}, 1, '#'}   // Small bottom sphere
};

// Light source
Vec3 light_source = {5, 5, -5};

// Vector subtraction
Vec3 vec3_subtract(Vec3 a, Vec3 b) {
    return (Vec3){a.x - b.x, a.y - b.y, a.z - b.z};
}

// Dot product
float vec3_dot(Vec3 a, Vec3 b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

// Vector length
float vec3_length(Vec3 v) {
    return sqrtf(v.x * v.x + v.y * v.y + v.z * v.z);
}

// Normalize vector
Vec3 vec3_normalize(Vec3 v) {
    float len = vec3_length(v);
    return (Vec3){v.x / len, v.y / len, v.z / len};
}

// Ray-sphere intersection
float ray_sphere_intersect(Ray ray, Sphere sphere) {
    Vec3 oc = vec3_subtract(ray.origin, sphere.center);
    float a = vec3_dot(ray.direction, ray.direction);
    float b = 2.0f * vec3_dot(oc, ray.direction);
    float c = vec3_dot(oc, oc) - sphere.radius * sphere.radius;
    float discriminant = b * b - 4 * a * c;

    if (discriminant < 0) return -1;

    float t1 = (-b - sqrtf(discriminant)) / (2.0f * a);
    float t2 = (-b + sqrtf(discriminant)) / (2.0f * a);

    return (t1 > 0) ? t1 : t2;
}

// Compute shading based on light source
char compute_shading(Vec3 intersection_point, Sphere sphere) {
    Vec3 normal = vec3_normalize(vec3_subtract(intersection_point, sphere.center));
    Vec3 light_dir = vec3_normalize(vec3_subtract(light_source, intersection_point));

    float intensity = fmaxf(0, vec3_dot(normal, light_dir));
    char shading_chars[] = {'.', ',', '-', '~', '+', '*', '#', '%', '@'};

    int index = (int)(intensity * (sizeof(shading_chars) - 1));
    return shading_chars[index];
}

// Render the scene
void render_scene() {
    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            // Create ray from camera through pixel
            Ray ray = {
                {0, 0, 0},
                vec3_normalize((Vec3){
                    (x - WIDTH/2.0f) / (float)WIDTH,
                    (y - HEIGHT/2.0f) / (float)HEIGHT,
                    -1
                })
            };

            char pixel = ' ';
            float closest_hit = INFINITY;

            // Check intersection with all spheres
            for (int i = 0; i < MAX_SPHERES; i++) {
                float t = ray_sphere_intersect(ray, spheres[i]);
                if (t > 0 && t < closest_hit) {
                    closest_hit = t;

                    // Compute intersection point
                    Vec3 intersection_point = (Vec3){
                        ray.origin.x + t * ray.direction.x,
                        ray.origin.y + t * ray.direction.y,
                        ray.origin.z + t * ray.direction.z
                    };

                    // Get shaded character
                    pixel = compute_shading(intersection_point, spheres[i]);
                }
            }

            printf("%c", pixel);
        }
        printf("\n");
    }
}

int main() {
    printf("ASCII Ray Traced Scene:\n");
    render_scene();
    return 0;
}

#include <stdio.h>
#include <math.h>

#define WIDTH 80
#define HEIGHT 40
#define ASPECT_RATIO (float)WIDTH / HEIGHT
#define FOV 1.0f
#define MAX_STEPS 100
#define HIT_DISTANCE 0.01f
#define MAX_DISTANCE 100.0f

typedef struct {
    float x, y, z;
} Vec3;

Vec3 make_vec3(float x, float y, float z) {
    Vec3 v = {x, y, z};
    return v;
}

Vec3 add(Vec3 a, Vec3 b) {
    return make_vec3(a.x + b.x, a.y + b.y, a.z + b.z);
}

Vec3 sub(Vec3 a, Vec3 b) {
    return make_vec3(a.x - b.x, a.y - b.y, a.z - b.z);
}

Vec3 mul(Vec3 v, float s) {
    return make_vec3(v.x * s, v.y * s, v.z * s);
}

float dot(Vec3 a, Vec3 b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

float length(Vec3 v) {
    return sqrtf(dot(v, v));
}

Vec3 normalize(Vec3 v) {
    return mul(v, 1.0f / length(v));
}

float sphere_distance(Vec3 p, Vec3 center, float radius) {
    return length(sub(p, center)) - radius;
}

float scene_distance(Vec3 p) {
    Vec3 sphere_center = make_vec3(0.0f, 0.0f, -5.0f);
    float sphere_radius = 1.0f;
    return sphere_distance(p, sphere_center, sphere_radius);
}

Vec3 ray_march(Vec3 ro, Vec3 rd) {
    float total_distance = 0.0f;
    for (int i = 0; i < MAX_STEPS; i++) {
        Vec3 p = add(ro, mul(rd, total_distance));
        float distance = scene_distance(p);
        if (distance < HIT_DISTANCE) {
            return p;
        }
        if (total_distance > MAX_DISTANCE) {
            break;
        }
        total_distance += distance;
    }
    return make_vec3(0.0f, 0.0f, 0.0f);
}

char get_ascii_char(float intensity) {
    const char *ascii_chars = " .:-=+*#%@";
    int index = (int)(intensity * (strlen(ascii_chars) - 1));
    return ascii_chars[index];
}

int main() {
    Vec3 camera_pos = make_vec3(0.0f, 0.0f, 0.0f);

    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            float u = (float)x / WIDTH * 2.0f - 1.0f;
            float v = (float)y / HEIGHT * 2.0f - 1.0f;
            u *= ASPECT_RATIO * FOV;
            v *= FOV;

            Vec3 ray_dir = normalize(make_vec3(u, v, -1.0f));
            Vec3 hit_point = ray_march(camera_pos, ray_dir);

            float intensity = 0.0f;
            if (hit_point.z != 0.0f) {
                Vec3 light_dir = normalize(make_vec3(1.0f, 1.0f, -1.0f));
                Vec3 normal = normalize(sub(hit_point, make_vec3(0.0f, 0.0f, -5.0f)));
                intensity = fmaxf(0.0f, dot(normal, light_dir));
            }

            char c = get_ascii_char(intensity);
            putchar(c);
        }
        putchar('\n');
    }

    return 0;
}

