#define WIDTH 40
#define HEIGHT 20
#define SPHERE_COUNT 3

typedef struct {
    float x, y, z; // Position
} Vec3;

typedef struct {
    Vec3 center;
    float radius;
} Sphere;

// Function to check ray-sphere intersection
int intersect(Sphere sphere, Vec3 ray_origin, Vec3 ray_direction) {
    Vec3 oc = {ray_origin.x - sphere.center.x, ray_origin.y - sphere.center.y, ray_origin.z - sphere.center.z};
    float a = ray_direction.x * ray_direction.x + ray_direction.y * ray_direction.y + ray_direction.z * ray_direction.z;
    float b = 2.0 * (oc.x * ray_direction.x + oc.y * ray_direction.y + oc.z * ray_direction.z);
    float c = oc.x * oc.x + oc.y * oc.y + oc.z * oc.z - sphere.radius * sphere.radius;
    float discriminant = b * b - 4 * a * c;

    return (discriminant > 0);
}

// Function to render the scene
void render() {
    Sphere spheres[SPHERE_COUNT] = {
        {{0.0, 0.0, 5.0}, 1.0},
        {{-1.5, 0.0, 7.0}, 0.5},
        {{1.5, 0.0, 7.0}, 0.5}
    };

    for (int y = -HEIGHT / 2; y < HEIGHT / 2; ++y) {
        for (int x = -WIDTH / 2; x < WIDTH / 2; ++x) {
            Vec3 ray_origin = {0.0, 0.0, 0.0};
            Vec3 ray_direction = {x / (float)WIDTH, y / (float)HEIGHT, 1.0};
            int hit = 0;

            // Normalize ray direction
            float length = sqrt(ray_direction.x * ray_direction.x + ray_direction.y * ray_direction.y + ray_direction.z * ray_direction.z);
            ray_direction.x /= length;
            ray_direction.y /= length;
            ray_direction.z /= length;

            // Check for intersections with spheres
            for (int i = 0; i < SPHERE_COUNT; ++i) {
                if (intersect(spheres[i], ray_origin, ray_direction)) {
                    hit = 1;
                    break;
                }
            }

            if (hit)
                putchar('*');
            else
                putchar(' ');
        }
        putchar('\n');
    }
}

