    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Structure to represent a 3D vector
typedef struct {
    double x, y, z;
} Vector3D;

// Structure to represent a sphere
typedef struct {
    Vector3D center;
    double radius;
} Sphere;

// Function to calculate the dot product of two vectors
double dotProduct(Vector3D v1, Vector3D v2) {
    return v1.x * v2.x + v1.y * v2.y + v1.z * v2.z;
}

// Function to calculate the magnitude of a vector
double magnitude(Vector3D v) {
    return sqrt(v.x * v.x + v.y * v.y + v.z * v.z);
}

// Function to normalize a vector
Vector3D normalize(Vector3D v) {
    double mag = magnitude(v);
    Vector3D result = {v.x / mag, v.y / mag, v.z / mag};
    return result;
}

// Function to calculate the intersection point of a ray and a sphere
double intersectRaySphere(Vector3D origin, Vector3D direction, Sphere sphere) {
    Vector3D L = {sphere.center.x - origin.x, sphere.center.y - origin.y, sphere.center.z - origin.z};
    double tca = dotProduct(L, direction);
    if (tca < 0) return -1; // No intersection
    double d2 = dotProduct(L, L) - tca * tca;
    if (d2 > sphere.radius * sphere.radius) return -1; // No intersection
    double thc = sqrt(sphere.radius * sphere.radius - d2);
    double t0 = tca - thc;
    double t1 = tca + thc;
    return (t0 < t1) ? t0 : t1;
}

// Function to render the scene
void renderScene(int width, int height, Sphere spheres[], int numSpheres) {
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            Vector3D dir = {(x - width / 2) / (double)width, (y - height / 2) / (double)height, 1};
            dir = normalize(dir);
            double minT = INFINITY;
            for (int i = 0; i < numSpheres; i++) {
                double t = intersectRaySphere((Vector3D){0, 0, 0}, dir, spheres[i]);
                if (t > 0 && t < minT) minT = t;
            }
            if (minT != INFINITY) printf("* ");
            else printf("  ");
        }
        printf("\n");
    }
}

int main() {
    int width = 80, height = 20;
    Sphere spheres[] = {
        {{0, 0, -5}, 1},
        {{-2, 0, -5}, 1},
        {{2, 0, -5}, 1}
    };
    int numSpheres = sizeof(spheres) / sizeof(spheres[0]);
    renderScene(width, height, spheres, numSpheres);
    return 0;
}

#include <stdio.h>
#include <math.h>

#define WIDTH 80
#define HEIGHT 24
#define FOV 1.0
#define MAX_DIST 1000.0
#define AMBIENT_LIGHT 0.2

typedef struct {
    double x, y, z;
} Vector;

typedef struct {
    Vector center;
    double radius;
    char color;
} Sphere;

Vector normalize(Vector v) {
    double len = sqrt(v.x * v.x + v.y * v.y + v.z * v.z);
    return (Vector){v.x / len, v.y / len, v.z / len};
}

double dot(Vector a, Vector b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

Vector add(Vector a, Vector b) {
    return (Vector){a.x + b.x, a.y + b.y, a.z + b.z};
}

Vector sub(Vector a, Vector b) {
    return (Vector){a.x - b.x, a.y - b.y, a.z - b.z};
}

double magnitude(Vector v) {
    return sqrt(v.x * v.x + v.y * v.y + v.z * v.z);
}

Vector scale(Vector v, double s) {
    return (Vector){v.x * s, v.y * s, v.z * s};
}

// Ray-Sphere intersection
int intersect_sphere(Vector ray_origin, Vector ray_dir, Sphere sphere, double *t) {
    Vector oc = sub(ray_origin, sphere.center);
    double a = dot(ray_dir, ray_dir);
    double b = 2.0 * dot(oc, ray_dir);
    double c = dot(oc, oc) - sphere.radius * sphere.radius;
    double discriminant = b * b - 4 * a * c;

    if (discriminant < 0) {
        return 0; // No intersection
    } else {
        *t = (-b - sqrt(discriminant)) / (2.0 * a);
        if (*t > 0.0 && *t < MAX_DIST) {
            return 1; // Intersection found
        } else {
            *t = (-b + sqrt(discriminant)) / (2.0 * a);
            return (*t > 0.0 && *t < MAX_DIST) ? 1 : 0;
        }
    }
}

char* brightness_to_ascii(double brightness) {
    static char* ascii_chars = " .:-=+*#%@";
    int index = (int)(brightness * (strlen(ascii_chars) - 1));
    return &ascii_chars[index];
}

void render_scene(Sphere spheres[], int num_spheres, Vector light, Vector camera, int width, int height) {
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            double screen_x = (x - width / 2.0) * FOV;
            double screen_y = (y - height / 2.0) * FOV;
            Vector ray_dir = normalize((Vector){screen_x, screen_y, 1});

            double t = MAX_DIST;
            Sphere* closest_sphere = NULL;

            for (int i = 0; i < num_spheres; i++) {
                double temp_t;
                if (intersect_sphere(camera, ray_dir, spheres[i], &temp_t) && temp_t < t) {
                    t = temp_t;
                    closest_sphere = &spheres[i];
                }
            }

            if (closest_sphere) {
                Vector hit_pos = add(camera, scale(ray_dir, t));
                Vector normal = normalize(sub(hit_pos, closest_sphere->center));
                double light_dir = dot(normal, normalize(light));
                double brightness = fmax(light_dir + AMBIENT_LIGHT, AMBIENT_LIGHT);
                printf("%c", brightness_to_ascii(brightness)[0]);
            } else {
                printf(" ");
            }
        }
        printf("\n");
    }
}

int main() {
    Sphere spheres[] = {
        {(Vector){0.0, 0.0, 5.0}, 2.0, '@'}
    };
    int num_spheres = sizeof(spheres) / sizeof(Sphere);

    Vector light = (Vector){5.0, 5.0, -10.0};
    Vector camera = (Vector){0.0, 0.0, -10.0};

    render_scene(spheres, num_spheres, light, camera, WIDTH, HEIGHT);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>

// Perceptron structure
typedef struct {
    double weights[3];  // Weights for input, previous input, and bias
    double learning_rate;
} Perceptron;

// Activation function (sigmoid)
double sigmoid(double x) {
    return 1.0 / (1.0 + exp(-x));
}

// Derivative of sigmoid for backpropagation
double sigmoid_derivative(double x) {
    return x * (1.0 - x);
}

// Initialize perceptron with random weights
void initialize_perceptron(Perceptron* p) {
    // Seed random number generator
    srand(time(NULL));

    // Initialize weights randomly between -1 and 1
    for (int i = 0; i < 3; i++) {
        p->weights[i] = ((double)rand() / RAND_MAX) * 2 - 1;
    }

    // Set learning rate
    p->learning_rate = 0.1;
}

// Predict next number in sequence
double predict(Perceptron* p, double input, double prev_input) {
    // Compute weighted sum with bias
    double weighted_sum = 
        p->weights[0] * input + 
        p->weights[1] * prev_input + 
        p->weights[2];

    // Apply activation function
    return sigmoid(weighted_sum);
}

// Train perceptron
void train(Perceptron* p, double input, double prev_input, double target) {
    // Forward pass
    double prediction = predict(p, input, prev_input);

    // Compute error
    double error = target - prediction;

    // Compute gradient
    double gradient = error * sigmoid_derivative(prediction);

    // Update weights
    p->weights[0] += p->learning_rate * gradient * input;
    p->weights[1] += p->learning_rate * gradient * prev_input;
    p->weights[2] += p->learning_rate * gradient;
}

