#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Simple perceptron structure
typedef struct {
    float weight;
    float bias;
    float learning_rate;
} Perceptron;

// Initialize perceptron with random weights
void init_perceptron(Perceptron *p, float learning_rate) {
    srand(time(NULL));
    p->weight = (float)rand() / RAND_MAX * 2.0 - 1.0; // Random between -1 and 1
    p->bias = (float)rand() / RAND_MAX * 2.0 - 1.0;
    p->learning_rate = learning_rate;
}

// Predict output for given input
float predict(Perceptron *p, float input) {
    return input * p->weight + p->bias;
}

// Train the perceptron on one sample
void train(Perceptron *p, float input, float target) {
    float prediction = predict(p, input);
    float error = target - prediction;

    // Update weights and bias
    p->weight += error * input * p->learning_rate;
    p->bias += error * p->learning_rate;
}

int main() {
    // Example sequence: linear pattern (next number is current + 2)
    float sequence[] = {1, 3, 5, 7, 9, 11, 13, 15};
    int sequence_length = sizeof(sequence) / sizeof(sequence[0]);

    Perceptron p;
    init_perceptron(&p, 0.01); // Learning rate

    printf("Initial weights: weight=%.4f, bias=%.4f\n", p.weight, p.bias);

    // Training loop
    int epochs = 100;
    for (int e = 0; e < epochs; e++) {
        for (int i = 0; i < sequence_length - 1; i++) {
            train(&p, sequence[i], sequence[i+1]);
        }
    }

    printf("Trained weights: weight=%.4f, bias=%.4f\n", p.weight, p.bias);

    // Test the perceptron
    printf("\nTesting the perceptron:\n");
    for (int i = 0; i < sequence_length; i++) {
        float prediction = predict(&p, sequence[i]);
        printf("Input: %.1f, Predicted next: %.2f, Actual next: ", 
               sequence[i], prediction);
        if (i < sequence_length - 1) {
            printf("%.1f\n", sequence[i+1]);
        } else {
            printf("?\n");
        }
    }

    // Predict next number after the sequence
    float next_input = sequence[sequence_length - 1];
    float next_prediction = predict(&p, next_input);
    printf("\nPredicted next number after %.1f: %.2f\n", next_input, next_prediction);

    return 0;
}

