// Structure to represent a sample
typedef struct {
    double input;
    double output;
} Sample;

// Structure to represent the perceptron
typedef struct {
    double weight;
    double bias;
} Perceptron;

// Function to initialize the perceptron with random weights
void init_perceptron(Perceptron* p) {
    p->weight = (double)rand() / RAND_MAX * 2 - 1;
    p->bias = (double)rand() / RAND_MAX * 2 - 1;
}

// Function to predict the next number in the sequence
double predict(Perceptron* p, double input) {
    return p->weight * input + p->bias;
}

// Function to train the perceptron using the perceptron learning rule
void train(Perceptron* p, Sample* samples, int num_samples) {
    double learning_rate = 0.1;
    for (int i = 0; i < 1000; i++) {
        for (int j = 0; j < num_samples; j++) {
            double prediction = predict(p, samples[j].input);
            double error = samples[j].output - prediction;
            p->weight += learning_rate * error * samples[j].input;
            p->bias += learning_rate * error;
        }
    }
}

