#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TASKS 10
#define MAX_TASK_LENGTH 100
#define FILENAME "todo.txt"

// Structure to represent a single task
typedef struct {
    char description[MAX_TASK_LENGTH];
    int completed; // 0 for not completed, 1 for completed
} Task;

// Array to store our tasks
Task tasks[MAX_TASKS];
int numTasks = 0; // Current number of tasks loaded

// Function Prototypes
void loadTasksFromFile();
void saveTasksToFile();
void displayTasks();
void addTask();
void markTaskCompleted();
void deleteTask();
void clearScreen();

int main() {
    loadTasksFromFile(); // Load tasks at the beginning

    int choice;
    do {
        clearScreen();
        printf("\n===== To-Do List Manager =====\n");
        printf("1. Display Tasks\n");
        printf("2. Add Task\n");
        printf("3. Mark Task as Completed\n");
        printf("4. Delete Task\n");
        printf("5. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        // Consume the newline character left by scanf
        while (getchar() != '\n'); 

        switch (choice) {
            case 1:
                displayTasks();
                break;
            case 2:
                addTask();
                break;
            case 3:
                markTaskCompleted();
                break;
            case 4:
                deleteTask();
                break;
            case 5:
                printf("Exiting To-Do List Manager. Goodbye!\n");
                break;
            default:
                printf("Invalid choice. Please try again.\n");
                break;
        }
        printf("\nPress Enter to continue...");
        while (getchar() != '\n'); // Wait for user to press Enter
    } while (choice != 5);

    saveTasksToFile(); // Save tasks before exiting
    return 0;
}

// Clears the console screen
void clearScreen() {
#ifdef _WIN32
    system("cls");
#else
    system("clear");
#endif
}

// Loads tasks from the file
void loadTasksFromFile() {
    FILE *file = fopen(FILENAME, "r");
    if (file == NULL) {
        // File doesn't exist yet, or an error occurred.
        // We'll create it when we save.
        printf("No existing to-do list found. Starting with an empty list.\n");
        numTasks = 0;
        return;
    }

    numTasks = 0;
    while (numTasks < MAX_TASKS && 
           fscanf(file, "%d %[^\n]", &tasks[numTasks].completed, 
                  tasks[numTasks].description) == 2) {
        numTasks++;
    }
    fclose(file);
    printf("Tasks loaded successfully from %s.\n", FILENAME);
}

// Saves tasks to the file
void saveTasksToFile() {
    FILE *file = fopen(FILENAME, "w");
    if (file == NULL) {
        perror("Error opening file for writing");
        return;
    }

    for (int i = 0; i < numTasks; i++) {
        fprintf(file, "%d %s\n", tasks[i].completed, tasks[i].description);
    }
    fclose(file);
    printf("Tasks saved successfully to %s.\n", FILENAME);
}

// Displays all tasks
void displayTasks() {
    if (numTasks == 0) {
        printf("\nNo tasks in the list.\n");
        return;
    }

    printf("\n===== Your To-Do List (%d/%d tasks) =====\n", numTasks, MAX_TASKS);
    for (int i = 0; i < numTasks; i++) {
        printf("%2d. [%c] %s\n", i + 1, tasks[i].completed ? 'X' : ' ', tasks[i].description);
    }
    printf("===================================\n");
}

// Adds a new task
void addTask() {
    if (numTasks >= MAX_TASKS) {
        printf("\nError: To-Do list is full! (Max %d tasks)\n", MAX_TASKS);
        return;
    }

    printf("\nEnter new task description: ");
    if (fgets(tasks[numTasks].description, MAX_TASK_LENGTH, stdin) != NULL) {
        // Remove trailing newline character if present
        tasks[numTasks].description[strcspn(tasks[numTasks].description, "\n")] = 0;
        tasks[numTasks].completed = 0; // New tasks are not completed
        numTasks++;
        printf("Task added successfully!\n");
    } else {
        printf("Error reading input.\n");
    }
}

// Marks a task as completed
void markTaskCompleted() {
    if (numTasks == 0) {
        printf("\nNo tasks to mark as completed.\n");
        return;
    }

    displayTasks();
    int taskNum;
    printf("Enter the number of the task to mark as completed: ");
    scanf("%d", &taskNum);
    while (getchar() != '\n'); // Consume newline

    if (taskNum >= 1 && taskNum <= numTasks) {
        if (tasks[taskNum - 1].completed) {
            printf("Task %d is already marked as completed.\n", taskNum);
        } else {
            tasks[taskNum - 1].completed = 1;
            printf("Task %d marked as completed!\n", taskNum);
        }
    } else {
        printf("Invalid task number.\n");
    }
}

// Deletes a task
void deleteTask() {
    if (numTasks == 0) {
        printf("\nNo tasks to delete.\n");
        return;
    }

    displayTasks();
    int taskNum;
    printf("Enter the number of the task to delete: ");
    scanf("%d", &taskNum);
    while (getchar() != '\n'); // Consume newline

    if (taskNum >= 1 && taskNum <= numTasks) {
        // Shift tasks to fill the gap
        for (int i = taskNum - 1; i < numTasks - 1; i++) {
            tasks[i] = tasks[i + 1];
        }
        numTasks--;
        printf("Task %d deleted successfully!\n", taskNum);
    } else {
        printf("Invalid task number.\n");
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TASKS 10
#define TASK_LEN  100
#define FILE_NAME "tasks.txt"

void load_tasks(char tasks[][TASK_LEN], int *count) {
    FILE *file = fopen(FILE_NAME, "r");
    *count = 0;
    if (file == NULL) return; // No file yet
    while (fgets(tasks[*count], TASK_LEN, file) != NULL && *count < MAX_TASKS) {
        tasks[*count][strcspn(tasks[*count], "\n")] = 0; // remove newline
        (*count)++;
    }
    fclose(file);
}

void save_tasks(char tasks[][TASK_LEN], int count) {
    FILE *file = fopen(FILE_NAME, "w");
    for (int i = 0; i < count; ++i)
        fprintf(file, "%s\n", tasks[i]);
    fclose(file);
}

void list_tasks(char tasks[][TASK_LEN], int count) {
    printf("\n----- To-Do List -----\n");
    if (count == 0) {
        printf("No tasks.\n");
        return;
    }
    for (int i = 0; i < count; ++i)
        printf("%2d. %s\n", i+1, tasks[i]);
}

void add_task(char tasks[][TASK_LEN], int *count) {
    if (*count >= MAX_TASKS) {
        printf("Task list full! (max %d)\n", MAX_TASKS);
        return;
    }
    printf("Enter new task: ");
    getchar(); // consume leftover newline
    fgets(tasks[*count], TASK_LEN, stdin);
    tasks[*count][strcspn(tasks[*count], "\n")] = 0;
    (*count)++;
    printf("Task added.\n");
}

void delete_task(char tasks[][TASK_LEN], int *count) {
    int num;
    if (*count == 0) {
        printf("No tasks to delete.\n");
        return;
    }
    printf("Enter task number to delete: ");
    scanf("%d", &num);
    if (num < 1 || num > *count) {
        printf("Invalid task number.\n");
        return;
    }
    for (int i = num-1; i < *count-1; ++i)
        strcpy(tasks[i], tasks[i+1]);
    (*count)--;
    printf("Task deleted.\n");
}

int main() {
    char tasks[MAX_TASKS][TASK_LEN];
    int count = 0, option;
    load_tasks(tasks, &count);

    while (1) {
        printf("\nTo-Do List Menu:\n");
        printf("1. List tasks\n2. Add task\n3. Delete task\n4. Exit\n");
        printf("Choose an option: ");
        if (scanf("%d", &option) != 1) { // bad input
            printf("Invalid input.\n");
            while (getchar() != '\n');
            continue;
        }
        switch(option) {
            case 1: list_tasks(tasks, count); break;
            case 2: add_task(tasks, &count); save_tasks(tasks, count); break;
            case 3: delete_task(tasks, &count); save_tasks(tasks, count); break;
            case 4: save_tasks(tasks, count); printf("Bye!\n"); return 0;
            default: printf("Invalid option.\n");
        }
    }
    return 0;
}

