#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TASKS 10
#define MAX_TASK_LENGTH 100
#define FILE_NAME "todo_list.txt"

// Structure to represent a task
typedef struct {
    int id;
    char description[MAX_TASK_LENGTH];
    int completed;
} Task;

// Function to load tasks from file
void loadTasks(Task *tasks) {
    FILE *file = fopen(FILE_NAME, "r");
    if (file == NULL) {
        printf("File not found. Creating new file.\n");
        return;
    }

    int i = 0;
    while (i < MAX_TASKS && fscanf(file, "%d %s %d", &tasks[i].id, tasks[i].description, &tasks[i].completed) == 3) {
        i++;
    }

    fclose(file);
}

// Function to save tasks to file
void saveTasks(Task *tasks) {
    FILE *file = fopen(FILE_NAME, "w");
    if (file == NULL) {
        printf("Error opening file.\n");
        return;
    }

    for (int i = 0; i < MAX_TASKS; i++) {
        if (tasks[i].id != 0) {
            fprintf(file, "%d %s %d\n", tasks[i].id, tasks[i].description, tasks[i].completed);
        }
    }

    fclose(file);
}

// Function to add a new task
void addTask(Task *tasks) {
    for (int i = 0; i < MAX_TASKS; i++) {
        if (tasks[i].id == 0) {
            tasks[i].id = i + 1;
            printf("Enter task description: ");
            fgets(tasks[i].description, MAX_TASK_LENGTH, stdin);
            tasks[i].description[strcspn(tasks[i].description, "\n")] = 0; // Remove newline character
            tasks[i].completed = 0;
            printf("Task added successfully.\n");
            return;
        }
    }

    printf("No more space available for new tasks.\n");
}

// Function to delete a task
void deleteTask(Task *tasks) {
    int id;
    printf("Enter task ID to delete: ");
    scanf("%d", &id);
    getchar(); // Consume newline character

    for (int i = 0; i < MAX_TASKS; i++) {
        if (tasks[i].id == id) {
            tasks[i].id = 0;
            tasks[i].description[0] = '\0';
            tasks[i].completed = 0;
            printf("Task deleted successfully.\n");
            return;
        }
    }

    printf("Task not found.\n");
}

// Function to update a task
void updateTask(Task *tasks) {
    int id;
    printf("Enter task ID to update: ");
    scanf("%d", &id);
    getchar(); // Consume newline character

    for (int i = 0; i < MAX_TASKS; i++) {
        if (tasks[i].id == id) {
            printf("Enter new task description: ");
            fgets(tasks[i].description, MAX_TASK_LENGTH, stdin);
            tasks[i].description[strcspn(tasks[i].description, "\n")] = 0; // Remove newline character
            printf("Task updated successfully.\n");
            return;
        }
    }

    printf("Task not found.\n");
}

// Function to view all tasks
void viewTasks(Task *tasks) {
    printf("Task List:\n");
    for (int i = 0; i < MAX_TASKS; i++) {
        if (tasks[i].id != 0) {
            printf("%d. %s (%s)\n", tasks[i].id, tasks[i].description, tasks[i].completed ? "Completed" : "Not Completed");
        }
    }
}

int main() {
    Task tasks[MAX_TASKS];
    for (int i = 0; i < MAX_TASKS; i++) {
        tasks[i].id = 0;
        tasks[i].description[0] = '\0';
        tasks[i].completed = 0;
    }

    loadTasks(tasks);

    while (1) {
        printf("To-Do List Manager\n");
        printf("1. Add Task\n");
        printf("2. Delete Task\n");
        printf("3. Update Task\n");
        printf("4. View Tasks\n");
        printf("5. Quit\n");
        printf("Choose an option: ");
        int option;
        scanf("%d", &option);
        getchar(); // Consume newline character

        switch (option) {
            case 1:
                addTask(tasks);
                saveTasks(tasks);
                break;
            case 2:
                deleteTask(tasks);
                saveTasks(tasks);
                break;
            case 3:
                updateTask(tasks);
                saveTasks(tasks);
                break;
            case 4:
                viewTasks(tasks);
                break;
            case 5:
                saveTasks(tasks);
                break;
            default:
                printf("Invalid option.\n");
        }

        if (option == 5) {
            break;
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TASKS 10
#define TASK_LENGTH 100

typedef struct {
    int id;
    char description[TASK_LENGTH];
    int completed;
} Task;

Task tasks[MAX_TASKS];
int task_count = 0;

void load_tasks(const char *filename);
void save_tasks(const char *filename);
void add_task();
void view_tasks();
void mark_task_as_completed();
void delete_task();

int main() {
    char filename[] = "tasks.txt";
    char choice;

    // Load existing tasks from file
    load_tasks(filename);

    while (1) {
        printf("\nTo-Do List Manager\n");
        printf("1. Add Task\n");
        printf("2. View Tasks\n");
        printf("3. Mark Task as Completed\n");
        printf("4. Delete Task\n");
        printf("5. Exit\n");
        printf("Enter your choice: ");
        scanf(" %c", &choice);

        switch (choice) {
            case '1':
                add_task();
                break;
            case '2':
                view_tasks();
                break;
            case '3':
                mark_task_as_completed();
                break;
            case '4':
                delete_task();
                break;
            case '5':
                // Save tasks to file before exiting
                save_tasks(filename);
                exit(0);
            default:
                printf("Invalid choice. Please try again.\n");
        }
    }

    return 0;
}

void load_tasks(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("No existing tasks found. Creating a new file.\n");
        return;
    }

    while (fscanf(file, "%d %[^\n] %d", &tasks[task_count].id, tasks[task_count].description, &tasks[task_count].completed) != EOF) {
        task_count++;
    }

    fclose(file);
    printf("%d tasks loaded from %s.\n", task_count, filename);
}

void save_tasks(const char *filename) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        printf("Failed to open file for writing.\n");
        return;
    }

    for (int i = 0; i < task_count; i++) {
        fprintf(file, "%d %s %d\n", tasks[i].id, tasks[i].description, tasks[i].completed);
    }

    fclose(file);
    printf("%d tasks saved to %s.\n", task_count, filename);
}

void add_task() {
    if (task_count >= MAX_TASKS) {
        printf("Task limit reached. Cannot add more tasks.\n");
        return;
    }

    tasks[task_count].id = task_count + 1;
    printf("Enter task description: ");
    scanf(" %[^\n]", tasks[task_count].description);
    tasks[task_count].completed = 0; // Task is not completed initially

    task_count++;
    printf("Task added successfully.\n");
}

void view_tasks() {
    if (task_count == 0) {
        printf("No tasks to display.\n");
        return;
    }

    printf("To-Do List:\n");
    for (int i = 0; i < task_count; i++) {
        printf("%d. [ %s ] %s\n", tasks[i].id, tasks[i].completed ? "x" : " ", tasks[i].description);
    }
}

void mark_task_as_completed() {
    if (task_count == 0) {
        printf("No tasks to mark as completed.\n");
        return;
    }

    int id;
    printf("Enter the ID of the task to mark as completed: ");
    scanf("%d", &id);

    for (int i = 0; i < task_count; i++) {
        if (tasks[i].id == id) {
            tasks[i].completed = 1;
            printf("Task %d marked as completed.\n", id);
            return;
        }
    }

    printf("Task with ID %d not found.\n", id);
}

void delete_task() {
    if (task_count == 0) {
        printf("No tasks to delete.\n");
        return;
    }

    int id;
    printf("Enter the ID of the task to delete: ");
    scanf("%d", &id);

    for (int i = 0; i < task_count; i++) {
        if (tasks[i].id == id) {
            for (int j = i; j < task_count - 1; j++) {
                tasks[j] = tasks[j + 1];
            }
            task_count--;
            printf("Task %d deleted successfully.\n", id);
            return;
        }
    }

    printf("Task with ID %d not found.\n", id);
}

