// Initialize tasks with empty descriptions
void initializeTasks(Task tasks[]) {
    for (int i = 0; i < MAX_TASKS; i++) {
        tasks[i].description[0] = '\0';
        tasks[i].completed = 0;
    }
}

// Display tasks with their status
void displayTasks(Task tasks[]) {
    printf("\nCurrent Tasks:\n");
    int emptyList = 1;
    for (int i = 0; i < MAX_TASKS; i++) {
        if (tasks[i].description[0] != '\0') {
            printf("%d. %s [%s]\n", 
                   i + 1, 
                   tasks[i].description, 
                   tasks[i].completed ? "Completed" : "Pending");
            emptyList = 0;
        }
    }
    if (emptyList) {
        printf("No tasks in the list.\n");
    }
}

// Add a new task to the list
void addTask(Task tasks[], const char* description) {
    for (int i = 0; i < MAX_TASKS; i++) {
        if (tasks[i].description[0] == '\0') {
            strncpy(tasks[i].description, description, MAX_TASK_LENGTH - 1);
            tasks[i].completed = 0;
            printf("Task added successfully.\n");
            return;
        }
    }
}

// Mark a task as complete
void markTaskComplete(Task tasks[], int taskIndex) {
    if (taskIndex >= 0 && taskIndex < MAX_TASKS && tasks[taskIndex].description[0] != '\0') {
        tasks[taskIndex].completed = 1;
        printf("Task marked as complete.\n");
    } else {
        printf("Invalid task number.\n");
    }
}

// Save tasks to file
void saveTasksToFile(Task tasks[]) {
    FILE *file = fopen(FILENAME, "w");
    if (file == NULL) {
        printf("Error opening file for writing.\n");
        return;
    }

    for (int i = 0; i < MAX_TASKS; i++) {
        if (tasks[i].description[0] != '\0') {
            fprintf(file, "%s|%d\n", tasks[i].description, tasks[i].completed);
        }
    }

    fclose(file);
    printf("Tasks saved to file.\n");
}

// Load tasks from file
void loadTasksFromFile(Task tasks[]) {
    initializeTasks(tasks);

    FILE *file = fopen(FILENAME, "r");
    if (file == NULL) {
        printf("No existing tasks file found. Starting with empty list.\n");
        return;
    }

    char line[MAX_TASK_LENGTH + 10];
    int index = 0;

    while (fgets(line, sizeof(line), file) && index < MAX_TASKS) {
        char *description = strtok(line, "|");
        char *completed_str = strtok(NULL, "\n");

        if (description && completed_str) {
            strncpy(tasks[index].description, description, MAX_TASK_LENGTH - 1);
            tasks[index].completed = atoi(completed_str);
            index++;
        }
    }

    fclose(file);
}

