#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TASKS 3         // We are managing 3 tasks
#define MAX_DESC_LEN 100    // Maximum length for a task description
#define FILENAME "todo.txt" // The file where tasks are stored

// Structure to represent a single task
typedef struct {
    char description[MAX_DESC_LEN];
    int completed; // 0 for incomplete, 1 for complete
} Task;

// Array to hold our tasks in memory
Task todoList[MAX_TASKS];

// --- Function Prototypes ---
void loadTasksFromFile();
void saveTasksToFile();
void displayTasks();
void addTask();
void markTaskComplete();
void deleteTask();
void clearInputBuffer(); // Helper to clear stdin buffer

// --- Main Program ---
int main() {
    int choice;

    // Load tasks from file when the program starts
    loadTasksFromFile();

    do {
        printf("\n--- To-Do List Manager (Max %d Tasks) ---\n", MAX_TASKS);
        printf("1. View Tasks\n");
        printf("2. Add Task\n");
        printf("3. Mark Task Complete\n");
        printf("4. Delete Task\n");
        printf("5. Exit\n");
        printf("Enter your choice: ");

        if (scanf("%d", &choice) != 1) {
            printf("Invalid input. Please enter a number.\n");
            clearInputBuffer();
            continue;
        }
        clearInputBuffer(); // Clear any remaining newline character

        switch (choice) {
            case 1:
                displayTasks();
                break;
            case 2:
                addTask();
                break;
            case 3:
                markTaskComplete();
                break;
            case 4:
                deleteTask();
                break;
            case 5:
                printf("Exiting program. Saving tasks...\n");
                saveTasksToFile(); // Save tasks before exiting
                break;
            default:
                printf("Invalid choice. Please try again.\n");
        }
    } while (choice != 5);

    return 0;
}

// --- Function Implementations ---

// Clears the input buffer to prevent issues with subsequent scanf/fgets
void clearInputBuffer() {
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
}

// Loads tasks from the specified file
void loadTasksFromFile() {
    FILE *file = fopen(FILENAME, "r");
    if (file == NULL) {
        printf("'%s' not found. Creating a new to-do list.\n", FILENAME);
        // Initialize tasks as empty if file doesn't exist
        for (int i = 0; i < MAX_TASKS; i++) {
            strcpy(todoList[i].description, "");
            todoList[i].completed = 0;
        }
        return;
    }

    char line[MAX_DESC_LEN + 3]; // +3 for status char, space, and null terminator
    int taskIndex = 0;

    while (taskIndex < MAX_TASKS && fgets(line, sizeof(line), file) != NULL) {
        // Remove trailing newline character if present
        line[strcspn(line, "\n")] = '\0';

        if (strlen(line) > 0) {
            if (line[0] == 'x' || line[0] == 'X') {
                todoList[taskIndex].completed = 1;
                // Copy description starting from the 2nd character (skip 'x' and space)
                strncpy(todoList[taskIndex].description, line + 2, MAX_DESC_LEN - 1);
                todoList[taskIndex].description[MAX_DESC_LEN - 1] = '\0'; // Ensure null termination
            } else {
                todoList[taskIndex].completed = 0;
                // Copy description starting from the 2nd character (skip space)
                strncpy(todoList[taskIndex].description, line + 1, MAX_DESC_LEN - 1);
                todoList[taskIndex].description[MAX_DESC_LEN - 1] = '\0'; // Ensure null termination
            }
        } else {
            // Handle empty lines gracefully if they somehow appear
            strcpy(todoList[taskIndex].description, "");
            todoList[taskIndex].completed = 0;
        }
        taskIndex++;
    }
    fclose(file);

    // If fewer than MAX_TASKS were loaded, initialize the remaining ones
    for (int i = taskIndex; i < MAX_TASKS; i++) {
        strcpy(todoList[i].description, "");
        todoList[i].completed = 0;
    }
    printf("Tasks loaded successfully from '%s'.\n", FILENAME);
}

// Saves current tasks to the specified file
void saveTasksToFile() {
    FILE *file = fopen(FILENAME, "w"); // "w" truncates (clears) the file
    if (file == NULL) {
        perror("Error opening file for writing");
        return;
    }

    for (int i = 0; i < MAX_TASKS; i++) {
        // Only write tasks that actually have a description
        if (strlen(todoList[i].description) > 0) {
            fprintf(file, "%c %s\n", (todoList[i].completed ? 'x' : ' '), todoList[i].description);
        } else {
             // For consistency in line count, write an empty line if a slot is blank.
             // Alternatively, you could just skip empty slots to save file space.
             // For a fixed 3-task structure, writing a placeholder might be clearer.
             fprintf(file, " \n"); // Write a space and newline for empty slots.
        }
    }
    fclose(file);
    printf("Tasks saved successfully to '%s'.\n", FILENAME);
}

// Displays all tasks with their status
void displayTasks() {
    printf("\n--- Current To-Do List ---\n");
    int activeTasks = 0;
    for (int i = 0; i < MAX_TASKS; i++) {
        if (strlen(todoList[i].description) > 0) {
            printf("%d. [%c] %s\n", i + 1, (todoList[i].completed ? 'x' : ' '), todoList[i].description);
            activeTasks++;
        } else {
            printf("%d. [ ] (Empty Slot)\n", i + 1);
        }
    }
    if (activeTasks == 0) {
        printf("No tasks in the list. Add some!\n");
    }
    printf("--------------------------\n");
}

// Adds a new task
void addTask() {
    char newDesc[MAX_DESC_LEN];
    int slotFound = -1;

    // Find the first empty slot
    for (int i = 0; i < MAX_TASKS; i++) {
        if (strlen(todoList[i].description) == 0) {
            slotFound = i;
            break;
        }
    }

    if (slotFound == -1) {
        printf("All %d task slots are currently full.\n", MAX_TASKS);
        printf("Enter the task number (1-%d) to overwrite, or 0 to cancel: ", MAX_TASKS);
        int choice;
        if (scanf("%d", &choice) != 1) {
            printf("Invalid input.\n");
            clearInputBuffer();
            return;
        }
        clearInputBuffer();
        if (choice >= 1 && choice <= MAX_TASKS) {
            slotFound = choice - 1; // Convert to 0-indexed
            printf("Overwriting task %d: '%s'\n", choice, todoList[slotFound].description);
        } else {
            printf("Add task cancelled.\n");
            return;
        }
    }

    printf("Enter new task description (max %d chars): ", MAX_DESC_LEN - 1);
    if (fgets(newDesc, sizeof(newDesc), stdin) != NULL) {
        // Remove trailing newline character
        newDesc[strcspn(newDesc, "\n")] = '\0';

        if (strlen(newDesc) == 0) {
            printf("Task description cannot be empty. Task not added.\n");
            return;
        }

        strcpy(todoList[slotFound].description, newDesc);
        todoList[slotFound].completed = 0; // New tasks are incomplete by default
        printf("Task added successfully to slot %d.\n", slotFound + 1);
        saveTasksToFile(); // Save immediately after adding
    } else {
        printf("Error reading input.\n");
    }
}

// Marks a task as complete
void markTaskComplete() {
    int taskNum;
    displayTasks();
    printf("Enter the number of the task to mark complete (1-%d): ", MAX_TASKS);
    if (scanf("%d", &taskNum) != 1) {
        printf("Invalid input. Please enter a number.\n");
        clearInputBuffer();
        return;
    }
    clearInputBuffer();

    if (taskNum >= 1 && taskNum <= MAX_TASKS) {
        int index = taskNum - 1; // Convert to 0-indexed

        if (strlen(todoList[index].description) > 0) {
            if (todoList[index].completed) {
                printf("Task %d is already complete.\n", taskNum);
            } else {
                todoList[index].completed = 1;
                printf("Task '%s' marked as complete.\n", todoList[index].description);
                saveTasksToFile(); // Save immediately after marking complete
            }
        } else {
            printf("Task %d is empty. Nothing to mark complete.\n", taskNum);
        }
    } else {
        printf("Invalid task number.\n");
    }
}

// Deletes a task by clearing its description
void deleteTask() {
    int taskNum;
    displayTasks();
    printf("Enter the number of the task to delete (1-%d): ", MAX_TASKS);
    if (scanf("%d", &taskNum) != 1) {
        printf("Invalid input. Please enter a number.\n");
        clearInputBuffer();
        return;
    }
    clearInputBuffer();

    if (taskNum >= 1 && taskNum <= MAX_TASKS) {
        int index = taskNum - 1; // Convert to 0-indexed

        if (strlen(todoList[index].description) > 0) {
            printf("Deleting task '%s'...\n", todoList[index].description);
            strcpy(todoList[index].description, ""); // Clear the description
            todoList[index].completed = 0;           // Reset status
            printf("Task %d deleted.\n", taskNum);
            saveTasksToFile(); // Save immediately after deleting
        } else {
            printf("Task %d is already empty. Nothing to delete.\n", taskNum);
        }
    } else {
        printf("Invalid task number.\n");
    }
}

