void addTask() {
    FILE *file;
    char task[TASK_LENGTH];
    char buffer[TASK_LENGTH];
    int taskCount = 0;

    file = fopen(FILENAME, "a+");
    if (file == NULL) {
        perror("Unable to open file");
        return;
    }

    // Count the current number of tasks
    while (fgets(buffer, sizeof(buffer), file) != NULL) {
        taskCount++;
    }

    if (taskCount >= MAX_TASKS) {
        printf("Task limit reached. Please delete a task before adding a new one.\n");
        fclose(file);
        return;
    }

    printf("Enter the task description: ");
    fgets(task, sizeof(task), stdin);
    task[strcspn(task, "\n")] = '\0'; // Remove newline character

    fprintf(file, "%s\n", task);
    fclose(file);

    printf("Task added successfully.\n");
}

void viewTasks() {
    FILE *file;
    char buffer[TASK_LENGTH];
    int taskNum = 1;

    file = fopen(FILENAME, "r");
    if (file == NULL) {
        perror("Unable to open file");
        return;
    }

    printf("\nYour Tasks:\n");
    while (fgets(buffer, sizeof(buffer), file) != NULL) {
        printf("%d. %s", taskNum, buffer);
        taskNum++;
    }
    if (taskNum == 1) {
        printf("No tasks available.\n");
    }

    fclose(file);
}

void deleteTask() {
    FILE *file, *tempFile;
    char buffer[TASK_LENGTH];
    int deleteTaskNum;
    int currentTask = 1;

    viewTasks();

    printf("\nEnter the task number to delete: ");
    scanf("%d", &deleteTaskNum);
    getchar(); // Consume newline character

    file = fopen(FILENAME, "r");
    if (file == NULL) {
        perror("Unable to open file");
        return;
    }

    tempFile = fopen("temp.txt", "w");
    if (tempFile == NULL) {
        perror("Unable to open temporary file");
        fclose(file);
        return;
    }

    while (fgets(buffer, sizeof(buffer), file) != NULL) {
        if (currentTask != deleteTaskNum) {
            fputs(buffer, tempFile);
        }
        currentTask++;
    }

    fclose(file);
    fclose(tempFile);

    // Replace the original file with the temporary file
    remove(FILENAME);
    rename("temp.txt", FILENAME);

    printf("Task deleted successfully.\n");
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TASKS 3
#define TASK_SIZE 100
#define FILENAME "todo_list.txt"

void load_tasks(char tasks[][TASK_SIZE], int *count) {
    FILE *file = fopen(FILENAME, "r");
    if (file == NULL) {
        *count = 0;  // No tasks stored yet
        return;
    }

    *count = 0;
    while (*count < MAX_TASKS && fgets(tasks[*count], TASK_SIZE, file)) {
        // Remove newline character from the end
        tasks[*count][strcspn(tasks[*count], "\n")] = 0;
        (*count)++;
    }
    fclose(file);
}

void save_tasks(char tasks[][TASK_SIZE], int count) {
    FILE *file = fopen(FILENAME, "w");
    if (file == NULL) {
        printf("Error opening file for writing!\n");
        return;
    }

    for (int i = 0; i < count; i++) {
        fprintf(file, "%s\n", tasks[i]);
    }
    fclose(file);
}

void add_task(char tasks[][TASK_SIZE], int *count) {
    if (*count >= MAX_TASKS) {
        printf("Task list is full!\n");
        return;
    }

    printf("Enter the task: ");
    fgets(tasks[*count], TASK_SIZE, stdin);
    tasks[*count][strcspn(tasks[*count], "\n")] = 0;  // Remove newline
    (*count)++;
