// Initialize tasks with empty strings and not completed
void initializeTasks(Task tasks[]) {
    for (int i = 0; i < MAX_TASKS; i++) {
        strcpy(tasks[i].description, "");
        tasks[i].completed = 0;
    }
}

// Display all tasks
void displayTasks(Task tasks[]) {
    printf("\n--- Current Tasks ---\n");
    int isEmpty = 1;

    for (int i = 0; i < MAX_TASKS; i++) {
        if (strlen(tasks[i].description) > 0) {
            printf("%d. %s [%s]\n", 
                   i + 1, 
                   tasks[i].description, 
                   tasks[i].completed ? "Completed" : "Pending");
            isEmpty = 0;
        }
    }

    if (isEmpty) {
        printf("No tasks in the list.\n");
    }
}

// Add a new task
void addTask(Task tasks[]) {
    for (int i = 0; i < MAX_TASKS; i++) {
        if (strlen(tasks[i].description) == 0) {
            printf("Enter task description: ");
            fgets(tasks[i].description, MAX_TASK_LENGTH, stdin);
            tasks[i].description[strcspn(tasks[i].description, "\n")] = 0;
            tasks[i].completed = 0;
            printf("Task added successfully!\n");
            return;
        }
    }
    printf("Task list is full. Cannot add more tasks.\n");
}

// Mark a task as complete
void markTaskComplete(Task tasks[]) {
    int taskNum;
    displayTasks(tasks);

    printf("Enter task number to mark as complete: ");
    scanf("%d", &taskNum);

    if (taskNum > 0 && taskNum <= MAX_TASKS && 
        strlen(tasks[taskNum - 1].description) > 0) {
        tasks[taskNum - 1].completed = 1;
        printf("Task marked as complete!\n");
    } else {
        printf("Invalid task number.\n");
    }
}

// Remove a task
void removeTask(Task tasks[]) {
    int taskNum;
    displayTasks(tasks);

    printf("Enter task number to remove: ");
    scanf("%d", &taskNum);

    if (taskNum > 0 && taskNum <= MAX_TASKS && 
        strlen(tasks[taskNum - 1].description) > 0) {
        strcpy(tasks[taskNum - 1].description, "");
        tasks[taskNum - 1].completed = 0;
        printf("Task removed successfully!\n");
    } else {
        printf("Invalid task number.\n");
    }
}

// Save tasks to file
void saveTasks(Task tasks[]) {
    FILE *file = fopen(FILENAME, "w");
    if (file == NULL) {
        printf("Error opening file for writing.\n");
        return;
    }

    for (int i = 0; i < MAX_TASKS; i++) {
        if (strlen(tasks[i].description) > 0) {
            fprintf(file, "%s|%d\n", tasks[i].description, tasks[i].completed);
        }
    }

    fclose(file);
}

// Load tasks from file
void loadTasks(Task tasks[]) {
    FILE *file = fopen(FILENAME, "r");
    if (file == NULL) {
        return; // No existing file, start with empty list
    }

    int i = 0;
    char line[MAX_TASK_LENGTH + 10];
    while (fgets(line, sizeof(line), file) && i < MAX_TASKS) {
        char *description = strtok(line, "|");
        char *completed_str = strtok(NULL, "\n");

        if (description && completed_str) {
            strcpy(tasks[i].description, description);
            tasks[i].completed = atoi(completed_str);
            i++;
        }
    }

    fclose(file);
}

