#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define FILENAME "todo.txt"
#define MAX_TASK_LENGTH 256
#define MAX_TASKS 100 // A reasonable limit for tasks in memory

// Structure to represent a single task
typedef struct {
    char description[MAX_TASK_LENGTH];
    int completed; // 0 for incomplete, 1 for complete
} Task;

// Function prototypes
void display_menu();
void add_task();
void view_tasks();
void mark_task_complete();
void delete_task();
void load_tasks(Task tasks[], int *num_tasks);
void save_tasks(const Task tasks[], int num_tasks);
void clear_input_buffer();

int main() {
    int choice;

    do {
        display_menu();
        printf("Enter your choice: ");
        if (scanf("%d", &choice) != 1) {
            printf("Invalid input. Please enter a number.\n");
            clear_input_buffer(); // Clear the invalid input
            choice = 0; // Set to an invalid choice to re-display menu
            continue;
        }
        clear_input_buffer(); // Consume the newline character after scanf

        switch (choice) {
            case 1:
                add_task();
                break;
            case 2:
                view_tasks();
                break;
            case 3:
                mark_task_complete();
                break;
