                break;
            default:
                printf("Invalid choice. Please try again.\n");
        }
        printf("\n"); // Add a newline for better readability between operations
    } while (choice != 5);

    return 0;
}

// Displays the main menu options
void display_menu() {
    printf("--- To-Do List Manager ---\n");
    printf("1. Add a new task\n");
    printf("2. View all tasks\n");
    printf("3. Mark a task as complete\n");
    printf("4. Delete a task\n");
    printf("5. Exit\n");
    printf("--------------------------\n");
}

// Clears the input buffer to prevent issues with `fgets` after `scanf`
void clear_input_buffer() {
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
}

// Loads tasks from the file into an array of Task structures
void load_tasks(Task tasks[], int *num_tasks) {
    FILE *file = fopen(FILENAME, "r");
    if (file == NULL) {
        // File doesn't exist yet, or an error occurred.
        // It's fine for the first run, `add_task` will create it.
        *num_tasks = 0;
        return;
    }

    char line[MAX_TASK_LENGTH + 5]; // +5 for "[ ] " or "[X] " and null terminator
    int count = 0;

    while (fgets(line, sizeof(line), file) != NULL && count < MAX_TASKS) {
        // Remove trailing newline character if present
        line[strcspn(line, "\n")] = 0;

        if (strlen(line) >= 4 && line[0] == '[' && line[2] == ']') {
            tasks[count].completed = (line[1] == 'X') ? 1 : 0;
            // Copy description starting after "[X] " or "[ ] " (4 characters)
            strncpy(tasks[count].description, line + 4, sizeof(tasks[count].description) - 1);
            tasks[count].description[sizeof(tasks[count].description) - 1] = '\0'; // Ensure null-termination
            count++;
        }
    }
    *num_tasks = count;
    fclose(file);
}

// Saves tasks from the array of Task structures back to the file
void save_tasks(const Task tasks[], int num_tasks) {
    FILE *file = fopen(FILENAME, "w"); // Open in write mode, which truncates the file
    if (file == NULL) {
        printf("Error: Could not open file to save tasks.\n");
        return;
    }

    for (int i = 0; i < num_tasks; i++) {
        fprintf(file, "[%c] %s\n", (tasks[i].completed ? 'X' : ' '), tasks[i].description);
    }
    fclose(file);
}

// Adds a new task to the list
void add_task() {
    Task tasks[MAX_TASKS];
    int num_tasks;
    load_tasks(tasks, &num_tasks); // Load existing tasks

    if (num_tasks >= MAX_TASKS) {
        printf("Error: Maximum number of tasks (%d) reached.\n", MAX_TASKS);
        return;
    }

    printf("Enter new task description: ");
    if (fgets(tasks[num_tasks].description, sizeof(tasks[num_tasks].description), stdin) == NULL) {
        printf("Error reading task description.\n");
        return;
    }
    // Remove trailing newline character if present
    tasks[num_tasks].description[strcspn(tasks[num_tasks].description, "\n")] = 0;

    if (strlen(tasks[num_tasks].description) == 0) {
        printf("Task description cannot be empty. Task not added.\n");
        return;
    }

    tasks[num_tasks].completed = 0; // New tasks are incomplete by default
    num_tasks++;

    save_tasks(tasks, num_tasks); // Save the updated list
    printf("Task added successfully!\n");
}

// Views all tasks from the list
void view_tasks() {
    Task tasks[MAX_TASKS];
    int num_tasks;
    load_tasks(tasks, &num_tasks);

    if (num_tasks == 0) {
        printf("No tasks in the list.\n");
        return;
    }

    printf("--- Your To-Do List ---\n");
    for (int i = 0; i < num_tasks; i++) {
        printf("%d. [%c] %s\n", i + 1, (tasks[i].completed ? 'X' : ' '), tasks[i].description);
    }
    printf("------------------------\n");
}

// Marks a task as complete
void mark_task_complete() {
    Task tasks[MAX_TASKS];
    int num_tasks;
    load_tasks(tasks, &num_tasks);

    if (num_tasks == 0) {
        printf("No tasks to mark complete.\n");
        return;
    }

    view_tasks(); // Show tasks with their numbers
    printf("Enter the number of the task to mark as complete: ");
    int task_number;
    if (scanf("%d", &task_number) != 1) {
        printf("Invalid input. Please enter a number.\n");
        clear_input_buffer();
        return;
    }
    clear_input_buffer(); // Consume newline

    if (task_number < 1 || task_number > num_tasks) {
        printf("Invalid task number.\n");
        return;
    }

    // Adjust for 0-based array index
    tasks[task_number - 1].completed = 1;
    save_tasks(tasks, num_tasks);
    printf("Task '%s' marked as complete!\n", tasks[task_number - 1].description);
}

// Deletes a task from the list
void delete_task() {
    Task tasks[MAX_TASKS];
    int num_tasks;
    load_tasks(tasks, &num_tasks);

    if (num_tasks == 0) {
        printf("No tasks to delete.\n");
        return;
    }

    view_tasks(); // Show tasks with their numbers
    printf("Enter the number of the task to delete: ");
    int task_number;
    if (scanf("%d", &task_number) != 1) {
        printf("Invalid input. Please enter a number.\n");
        clear_input_buffer();
        return;
    }
    clear_input_buffer(); // Consume newline

    if (task_number < 1 || task_number > num_tasks) {
        printf("Invalid task number.\n");
        return;
    }

    // Shift tasks to the left to "remove" the deleted one
    for (int i = task_number - 1; i < num_tasks - 1; i++) {
        tasks[i] = tasks[i + 1];
    }
    num_tasks--; // Decrement the total count

    save_tasks(tasks, num_tasks);
    printf("Task deleted successfully!\n");
}

