                complete_task(tasks, count);
                save_tasks(tasks, count);
                break;
            case 4:
                printf("Bye!\n");
                return 0;
            default:
                printf("Invalid option.\n");
        }
    }
    return 0;
}

// Load tasks from file
void load_tasks(Task tasks[], int *count) {
    FILE *fp = fopen(TASK_FILE, "r");
    char line[MAX_LEN + 5];
    *count = 0;

    if (!fp) return;

    while (fgets(line, sizeof(line), fp) && *count < MAX_TASKS) {
        if (strncmp(line, "[X] ", 4) == 0) {
            tasks[*count].completed = 1;
            strncpy(tasks[*count].desc, line + 4, MAX_LEN);
        } else if (strncmp(line, "[ ] ", 4) == 0) {
            tasks[*count].completed = 0;
            strncpy(tasks[*count].desc, line + 4, MAX_LEN);
        } else {
            tasks[*count].completed = 0;
            strncpy(tasks[*count].desc, line, MAX_LEN);
        }
        // Remove newline
        tasks[*count].desc[strcspn(tasks[*count].desc, "\n")] = 0;
        (*count)++;
    }
    fclose(fp);
}

// Save tasks to file
void save_tasks(Task tasks[], int count) {
    FILE *fp = fopen(TASK_FILE, "w");
    int i;
    for (i = 0; i < count; i++) {
        fprintf(fp, "[%c] %s\n", tasks[i].completed ? 'X' : ' ', tasks[i].desc);
    }
    fclose(fp);
}

// List all tasks
void list_tasks(Task tasks[], int count) {
    int i;
    if (count == 0) {
        printf("No tasks found.\n");
        return;
    }
    printf("\nTasks:\n");
    for (i = 0; i < count; i++) {
        printf("%d. [%c] %s\n", i + 1, tasks[i].completed ? 'X' : ' ', tasks[i].desc);
    }
}

// Add a new task
void add_task(Task tasks[], int *count) {
    char temp[MAX_LEN];
    if (*count >= MAX_TASKS) {
        printf("Cannot add more than %d tasks.\n", MAX_TASKS);
        return;
    }
    printf("Enter task description: ");
    getchar(); // Consume newline
    if (fgets(temp, MAX_LEN, stdin)) {
        temp[strcspn(temp, "\n")] = 0; // Remove newline
        strncpy(tasks[*count].desc, temp, MAX_LEN);
        tasks[*count].completed = 0;
        (*count)++;
        printf("Task added.\n");
    }
}

// Mark a task as completed
void complete_task(Task tasks[], int count) {
    int idx, i;
    if (count == 0) {
        printf("No tasks to complete.\n");
        return;
    }
    list_tasks(tasks, count);
    printf("Enter task number to mark as completed: ");
    if (scanf("%d", &idx) != 1 || idx < 1 || idx > count) {
        printf("Invalid input.\n");
        while (getchar() != '\n'); // Clear input
        return;
    }
    i = idx - 1;
    if (tasks[i].completed) {
        printf("Task is already completed.\n");
        return;
    }
    tasks[i].completed = 1;
    printf("Task marked as completed.\n");
}

