// Structure to represent a task
typedef struct {
    char description[MAX_TASK_LENGTH];
    int done;
} Task;

// Function to add a new task
void add_task(Task tasks[], int *task_count) {
    if (*task_count < MAX_TASKS) {
        printf("Enter task description: ");
        fgets(tasks[*task_count].description, MAX_TASK_LENGTH, stdin);
        tasks[*task_count].description[strcspn(tasks[*task_count].description, "\n")] = 0; // Remove newline character
        tasks[*task_count].done = 0;
        (*task_count)++;
        printf("Task added successfully!\n");
    } else {
        printf("Maximum tasks reached!\n");
    }
}

// Function to view all tasks
void view_tasks(Task tasks[], int task_count) {
    printf("Tasks:\n");
    for (int i = 0; i < task_count; i++) {
        printf("%d. %s - %s\n", i + 1, tasks[i].description, tasks[i].done ? "Done" : "Not Done");
    }
}

// Function to delete a task
void delete_task(Task tasks[], int *task_count, int task_number) {
    if (task_number > 0 && task_number <= *task_count) {
        for (int i = task_number - 1; i < *task_count - 1; i++) {
            tasks[i] = tasks[i + 1];
        }
        (*task_count)--;
        printf("Task deleted successfully!\n");
    } else {
        printf("Invalid task number!\n");
    }
}

// Function to save tasks to file
void save_tasks_to_file(Task tasks[], int task_count) {
    FILE *file = fopen("tasks.txt", "w");
    if (file != NULL) {
        for (int i = 0; i < task_count; i++) {
            fprintf(file, "%s:%d\n", tasks[i].description, tasks[i].done);
        }
        fclose(file);
        printf("Tasks saved to file successfully!\n");
    } else {
        printf("Failed to save tasks to file!\n");
    }
}

// Function to load tasks from file
void load_tasks_from_file(Task tasks[], int *task_count) {
    FILE *file = fopen("tasks.txt", "r");
    if (file != NULL) {
        char line[MAX_TASK_LENGTH + 2];
        while (fgets(line, sizeof(line), file) != NULL) {
            if (*task_count < MAX_TASKS) {
                char *description = strtok(line, ":");
                char *done = strtok(NULL, "\n");
                strcpy(tasks[*task_count].description, description);
                tasks[*task_count].done = atoi(done);
                (*task_count)++;
            } else {
                break;
            }
        }
        fclose(file);
        printf("Tasks loaded from file successfully!\n");
    } else {
        printf("Failed to load tasks from file!\n");
    }
}

