#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TASK_LENGTH 100
#define MAX_TASKS 7
#define FILENAME "todo.txt"

// Structure to represent a single to-do task
typedef struct {
    char description[MAX_TASK_LENGTH];
    int completed; // 0 for not completed, 1 for completed
} Task;

// Array to store the to-do list tasks
Task todoList[MAX_TASKS];
int numTasks = 0; // Current number of tasks loaded

// Function prototypes
void loadTasksFromFile();
void saveTasksToFile();
void displayTasks();
void addTask();
void markTaskCompleted();
void deleteTask();
void clearScreen();
void pressEnterToContinue();

int main() {
    loadTasksFromFile(); // Load tasks when the program starts

    int choice;
    do {
        clearScreen();
        printf("--- To-Do List Manager ---\n");
        printf("1. Display Tasks\n");
        printf("2. Add Task\n");
        printf("3. Mark Task as Completed\n");
        printf("4. Delete Task\n");
        printf("5. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);
        while (getchar() != '\n'); // Consume the newline character

        switch (choice) {
            case 1:
                displayTasks();
                pressEnterToContinue();
                break;
            case 2:
                addTask();
                pressEnterToContinue();
                break;
            case 3:
                markTaskCompleted();
                pressEnterToContinue();
                break;
            case 4:
                deleteTask();
                pressEnterToContinue();
                break;
            case 5:
                printf("Exiting To-Do List Manager. Goodbye!\n");
                break;
            default:
                printf("Invalid choice. Please try again.\n");
                pressEnterToContinue();
                break;
        }
    } while (choice != 5);

    saveTasksToFile(); // Save tasks before exiting

    return 0;
}

// Clears the console screen (platform-dependent)
void clearScreen() {
#ifdef _WIN32
    system("cls");
#else
    system("clear");
#endif
}

// Pauses execution until the user presses Enter
void pressEnterToContinue() {
    printf("\nPress Enter to continue...");
    while (getchar() != '\n'); // Wait for Enter key
}

// Loads tasks from the file
void loadTasksFromFile() {
    FILE *file = fopen(FILENAME, "r");
    if (file == NULL) {
        printf("No existing to-do list file found. Starting with an empty list.\n");
        numTasks = 0;
        return;
    }

    numTasks = 0;
    while (numTasks < MAX_TASKS &&
           fscanf(file, "%d %[^\n]\n", &todoList[numTasks].completed, todoList[numTasks].description) == 2) {
        numTasks++;
    }
    fclose(file);
    printf("Tasks loaded from '%s'.\n", FILENAME);
}

// Saves tasks to the file
void saveTasksToFile() {
    FILE *file = fopen(FILENAME, "w");
    if (file == NULL) {
        printf("Error: Could not open file '%s' for writing.\n", FILENAME);
        return;
    }

    for (int i = 0; i < numTasks; i++) {
        fprintf(file, "%d %s\n", todoList[i].completed, todoList[i].description);
    }
    fclose(file);
    printf("Tasks saved to '%s'.\n", FILENAME);
}

// Displays all tasks in the list
void displayTasks() {
    clearScreen();
    printf("--- Your To-Do List ---\n");
    if (numTasks == 0) {
        printf("No tasks in the list.\n");
        return;
    }

    for (int i = 0; i < numTasks; i++) {
        printf("%d. [%c] %s\n", i + 1, (todoList[i].completed ? 'X' : ' '), todoList[i].description);
    }
}

// Adds a new task to the list
void addTask() {
    if (numTasks >= MAX_TASKS) {
        printf("You have reached the maximum number of tasks (%d). Please delete a task first.\n", MAX_TASKS);
        return;
    }

    printf("Enter task description: ");
    fgets(todoList[numTasks].description, MAX_TASK_LENGTH, stdin);
    todoList[numTasks].description[strcspn(todoList[numTasks].description, "\n")] = 0; // Remove trailing newline

    if (strlen(todoList[numTasks].description) == 0) {
        printf("Task description cannot be empty. Task not added.\n");
        return;
    }

    todoList[numTasks].completed = 0; // New tasks are not completed by default
    numTasks++;
    printf("Task added successfully!\n");
    saveTasksToFile(); // Save after adding
}

// Marks a task as completed
void markTaskCompleted() {
    displayTasks();
    if (numTasks == 0) {
        return; // No tasks to mark
    }

    int taskNumber;
    printf("Enter the number of the task to mark as completed: ");
    scanf("%d", &taskNumber);
    while (getchar() != '\n'); // Consume the newline character

    if (taskNumber >= 1 && taskNumber <= numTasks) {
        todoList[taskNumber - 1].completed = 1;
        printf("Task #%d marked as completed!\n", taskNumber);
        saveTasksToFile(); // Save after marking
    } else {
        printf("Invalid task number.\n");
    }
}

// Deletes a task from the list
void deleteTask() {
    displayTasks();
    if (numTasks == 0) {
        return; // No tasks to delete
    }

    int taskNumber;
    printf("Enter the number of the task to delete: ");
    scanf("%d", &taskNumber);
    while (getchar() != '\n'); // Consume the newline character

    if (taskNumber >= 1 && taskNumber <= numTasks) {
        // Shift tasks to fill the gap
        for (int i = taskNumber - 1; i < numTasks - 1; i++) {
            todoList[i] = todoList[i + 1];
        }
        numTasks--;
        printf("Task #%d deleted successfully!\n", taskNumber);
        saveTasksToFile(); // Save after deleting
    } else {
        printf("Invalid task number.\n");
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TASKS 7
#define MAX_LEN 100
#define FILE_NAME "tasks.txt"

void loadTasks(char tasks[][MAX_LEN]) {
    FILE *fp = fopen(FILE_NAME, "r");
    if (!fp) {
        // File does not exist, initialize empty
        for (int i = 0; i < MAX_TASKS; i++)
            strcpy(tasks[i], "");
        return;
    }
    for (int i = 0; i < MAX_TASKS; i++) {
        if (fgets(tasks[i], MAX_LEN, fp)) {
            // Remove trailing newline
            size_t ln = strlen(tasks[i]);
            if (ln > 0 && tasks[i][ln-1] == '\n') tasks[i][ln-1] = '\0';
        } else {
            strcpy(tasks[i], "");
        }
    }
    fclose(fp);
}

void saveTasks(char tasks[][MAX_LEN]) {
    FILE *fp = fopen(FILE_NAME, "w");
    if (!fp) {
        puts("Error saving file!");
        return;
    }
    for (int i = 0; i < MAX_TASKS; i++) {
        fprintf(fp, "%s\n", tasks[i]);
    }
    fclose(fp);
}

void printTasks(char tasks[][MAX_LEN]) {
    printf("Current To-Do List:\n");
    for (int i = 0; i < MAX_TASKS; i++) {
        printf("%d. %s\n", i+1, strlen(tasks[i]) > 0 ? tasks[i] : "[Empty]");
    }
}

void addOrEditTask(char tasks[][MAX_LEN]) {
    int idx;
    char buffer[MAX_LEN];
    printTasks(tasks);
    printf("Enter task number to add/edit (1-%d): ", MAX_TASKS);
    scanf("%d", &idx);
    getchar(); // consume newline
    if (idx < 1 || idx > MAX_TASKS) {
        puts("Invalid task number!");
        return;
    }
    printf("Enter the task description: ");
    fgets(buffer, MAX_LEN, stdin);
    // Remove trailing newline
    size_t ln = strlen(buffer);
    if (ln > 0 && buffer[ln-1] == '\n') buffer[ln-1] = '\0';
    strncpy(tasks[idx-1], buffer, MAX_LEN);
    tasks[idx-1][MAX_LEN-1] = '\0'; // ensure null termination
}

void removeTask(char tasks[][MAX_LEN]) {
    int idx;
    printTasks(tasks);
    printf("Enter task number to remove (1-%d): ", MAX_TASKS);
    scanf("%d", &idx);
    getchar(); // consume newline
    if (idx < 1 || idx > MAX_TASKS) {
        puts("Invalid task number!");
        return;
    }
    strcpy(tasks[idx-1], "");
    puts("Task removed.");
}

int main() {
    char tasks[MAX_TASKS][MAX_LEN];
    int choice;
    loadTasks(tasks);

    do {
        printf("\n-- TO-DO LIST MANAGER --\n");
        printf("1. View Tasks\n");
        printf("2. Add/Edit Task\n");
        printf("3. Remove Task\n");
        printf("4. Save and Exit\n");
        printf("Enter choice: ");
        scanf("%d", &choice);
        getchar(); // consume newline

        switch (choice) {
            case 1: printTasks(tasks); break;
            case 2: addOrEditTask(tasks); break;
            case 3: removeTask(tasks); break;
            case 4: saveTasks(tasks); puts("Saved. Bye!"); break;
            default: puts("Invalid choice!");
        }
    } while (choice != 4);

    return 0;
}

