// Define the maximum number of tasks and the maximum length of a task description
#define MAX_TASKS 7
#define MAX_TASK_LENGTH 100

// Structure to represent a task
typedef struct {
    char description[MAX_TASK_LENGTH];
    int completed;
} Task;

// Function to add a new task to the list
void add_task(Task tasks[], int *num_tasks) {
    if (*num_tasks < MAX_TASKS) {
        printf("Enter task description: ");
        fgets(tasks[*num_tasks].description, MAX_TASK_LENGTH, stdin);
        tasks[*num_tasks].description[strcspn(tasks[*num_tasks].description, "\n")] = 0; // Remove newline character
        tasks[*num_tasks].completed = 0;
        (*num_tasks)++;
        printf("Task added successfully!\n");
    } else {
        printf("Task list is full. Cannot add more tasks.\n");
    }
}

// Function to delete a task from the list
void delete_task(Task tasks[], int *num_tasks) {
    if (*num_tasks > 0) {
        int task_number;
        printf("Enter task number to delete (1-%d): ", *num_tasks);
        scanf("%d", &task_number);
        getchar(); // Consume newline character

        if (task_number >= 1 && task_number <= *num_tasks) {
            // Shift tasks to the left to fill the gap
            for (int i = task_number - 1; i < *num_tasks - 1; i++) {
                tasks[i] = tasks[i + 1];
            }
            (*num_tasks)--;
            printf("Task deleted successfully!\n");
        } else {
            printf("Invalid task number.\n");
        }
    } else {
        printf("Task list is empty. Cannot delete task.\n");
    }
}

// Function to view all tasks in the list
void view_tasks(Task tasks[], int num_tasks) {
    if (num_tasks > 0) {
        printf("Task List:\n");
        for (int i = 0; i < num_tasks; i++) {
            printf("%d. %s - %s\n", i + 1, tasks[i].description, tasks[i].completed? "Completed" : "Pending");
        }
    } else {
        printf("Task list is empty.\n");
    }
}

// Function to mark a task as completed
void mark_completed(Task tasks[], int num_tasks) {
    if (num_tasks > 0) {
        int task_number;
        printf("Enter task number to mark as completed (1-%d): ", num_tasks);
        scanf("%d", &task_number);
        getchar(); // Consume newline character

        if (task_number >= 1 && task_number <= num_tasks) {
            tasks[task_number - 1].completed = 1;
            printf("Task marked as completed.\n");
        } else {
            printf("Invalid task number.\n");
        }
