        fclose(file);
        printf("Tasks saved to file successfully.\n");
    } else {
        printf("Failed to save tasks to file.\n");
    }
}

// Function to load tasks from a file
void load_tasks(Task tasks[], int *num_tasks) {
    FILE *file = fopen("tasks.txt", "r");
    if (file!= NULL) {
        char description[MAX_TASK_LENGTH];
        int completed;
        (*num_tasks) = 0;

        while (fscanf(file, "%[^-] - %d\n", description, &completed) == 2 && (*num_tasks) < MAX_TASKS) {
            strcpy(tasks[*num_tasks].description, description);
            tasks[*num_tasks].completed = completed;
            (*num_tasks)++;
        }

        fclose(file);
        printf("Tasks loaded from file successfully.\n");
    } else {
        printf("Failed to load tasks from file.\n");
    }
