#define EVENT_SIZE (sizeof(struct inotify_event))
#define BUF_LEN (1024 * (EVENT_SIZE + NAME_MAX + 1))

// Function to print event type
void print_event_type(uint32_t mask) {
    if (mask & IN_CREATE)      printf("Created: ");
    if (mask & IN_DELETE)      printf("Deleted: ");
    if (mask & IN_MODIFY)      printf("Modified: ");
    if (mask & IN_MOVED_FROM)  printf("Moved from: ");
    if (mask & IN_MOVED_TO)    printf("Moved to: ");
    if (mask & IN_ACCESS)      printf("Accessed: ");
    if (mask & IN_ATTRIB)      printf("Attributes changed: ");
    if (mask & IN_CLOSE_WRITE) printf("Closed after writing: ");
    if (mask & IN_CLOSE_NOWRITE) printf("Closed without writing: ");
    if (mask & IN_OPEN)        printf("Opened: ");
}

int main(int argc, char *argv[]) {
    // Check if directory path is provided
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory_path>\n", argv[0]);
        exit(1);
    }

    // Initialize inotify
    int inotify_fd = inotify_init();
    if (inotify_fd == -1) {
        perror("inotify_init");
        exit(1);
    }

    // Add watch to the directory
    int watch_fd = inotify_add_watch(inotify_fd, argv[1], 
        IN_CREATE | IN_DELETE | IN_MODIFY | 
        IN_MOVED_FROM | IN_MOVED_TO | IN_ACCESS | 
        IN_ATTRIB | IN_CLOSE_WRITE | IN_CLOSE_NOWRITE | IN_OPEN);

    if (watch_fd == -1) {
        perror("inotify_add_watch");
        close(inotify_fd);
        exit(1);
    }

    printf("Monitoring directory: %s\n", argv[1]);

    // Buffer to read events
    char buffer[BUF_LEN];

    // Event reading loop
    while (1) {
        // Read events
        ssize_t length = read(inotify_fd, buffer, BUF_LEN);

        if (length == -1 && errno != EAGAIN) {
            perror("read");
            break;
        }

        if (length == 0) {
            printf("No events\n");
            continue;
        }

        // Process events
        for (char *ptr = buffer; ptr < buffer + length;) {
            struct inotify_event *event = (struct inotify_event *)ptr;

            // Print event details
            if (event->mask & IN_ISDIR) {
                printf("Directory ");
            } else {
                printf("File ");
            }

            print_event_type(event->mask);

            if (event->len > 0) {
                printf("%s", event->name);
            }
            printf("\n");

            // Move to next event
            ptr += EVENT_SIZE + event->len;
        }
    }

    // Clean up
    inotify_rm_watch(inotify_fd, watch_fd);
    close(inotify_fd);

    return 0;
}

