#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <string.h>
#include <sys/inotify.h>
#include <limits.h>     // For PATH_MAX
#include <unistd.h>     // For read, close
#include <dirent.h>     // For opendir, readdir, closedir
#include <sys/stat.h>   // For stat, S_ISDIR

#define EVENT_SIZE (sizeof(struct inotify_event))
#define BUF_LEN    (1024 * (EVENT_SIZE + 16)) // Buffer for events, 16 extra bytes for name

// Structure to store watch descriptor and its corresponding path
typedef struct {
    int wd;
    char *path;
} WatchEntry;

// Simple dynamic array for watch entries
typedef struct {
    WatchEntry *entries;
    int count;
    int capacity;
} WatchList;

// Function prototypes
void init_watch_list(WatchList *list, int initial_capacity);
void add_watch_entry(WatchList *list, int wd, const char *path);
void remove_watch_entry(WatchList *list, int wd);
char *get_path_from_wd(WatchList *list, int wd);
void free_watch_list(WatchList *list);

int add_recursive_watch(int inotify_fd, const char *path, WatchList *watch_list);
void process_inotify_events(int inotify_fd, WatchList *watch_list);

// --- WatchList Implementation ---

void init_watch_list(WatchList *list, int initial_capacity) {
    list->entries = (WatchEntry *)malloc(initial_capacity * sizeof(WatchEntry));
    if (!list->entries) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = initial_capacity;
}

void add_watch_entry(WatchList *list, int wd, const char *path) {
    if (list->count >= list->capacity) {
        list->capacity *= 2;
        list->entries = (WatchEntry *)realloc(list->entries, list->capacity * sizeof(WatchEntry));
        if (!list->entries) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
    }
    list->entries[list->count].wd = wd;
    list->entries[list->count].path = strdup(path); // Duplicate path string
    if (!list->entries[list->count].path) {
        perror("strdup");
        exit(EXIT_FAILURE);
    }
    list->count++;
}

void remove_watch_entry(WatchList *list, int wd) {
    for (int i = 0; i < list->count; i++) {
        if (list->entries[i].wd == wd) {
            free(list->entries[i].path); // Free duplicated path string
            // Shift remaining elements
            for (int j = i; j < list->count - 1; j++) {
                list->entries[j] = list->entries[j + 1];
            }
            list->count--;
            return;
        }
    }
}

char *get_path_from_wd(WatchList *list, int wd) {
    for (int i = 0; i < list->count; i++) {
        if (list->entries[i].wd == wd) {
            return list->entries[i].path;
        }
    }
    return NULL; // Not found
}

void free_watch_list(WatchList *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->entries[i].path);
    }
    free(list->entries);
    list->entries = NULL;
    list->count = 0;
    list->capacity = 0;
}

// --- Inotify Helper Functions ---

// Adds a watch for a directory and recursively its subdirectories
// Returns 0 on success, -1 on failure
int add_recursive_watch(int inotify_fd, const char *path, WatchList *watch_list) {
    // Add watch for the current path
    int wd = inotify_add_watch(inotify_fd, path,
                               IN_CREATE | IN_DELETE | IN_MODIFY | IN_ATTRIB |
                               IN_MOVED_FROM | IN_MOVED_TO | IN_CLOSE_WRITE);

    if (wd == -1) {
        fprintf(stderr, "Error adding watch for %s: %s\n", path, strerror(errno));
        return -1;
    }
    printf("Added watch for '%s' (WD: %d)\n", path, wd);
    add_watch_entry(watch_list, wd, path);

    // Recursively add watches for subdirectories
    DIR *dir;
    struct dirent *entry;
    struct stat file_stat;
    char full_path[PATH_MAX];

    dir = opendir(path);
    if (!dir) {
        fprintf(stderr, "Could not open directory %s: %s\n", path, strerror(errno));
        return -1;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        snprintf(full_path, PATH_MAX, "%s/%s", path, entry->d_name);

        if (stat(full_path, &file_stat) == -1) {
            perror("stat");
            continue;
        }

        if (S_ISDIR(file_stat.st_mode)) {
            // Recursively call for subdirectories
            if (add_recursive_watch(inotify_fd, full_path, watch_list) == -1) {
                closedir(dir);
                return -1; // Propagate error
            }
        }
    }
    closedir(dir);
    return 0;
}

// Processes events from the inotify file descriptor
void process_inotify_events(int inotify_fd, WatchList *watch_list) {
    char buffer[BUF_LEN] __attribute__((aligned(8))); // Ensure alignment
    ssize_t length;
    char *ptr;

    printf("\nWaiting for events...\n");

    length = read(inotify_fd, buffer, BUF_LEN);
    if (length < 0) {
        perror("read");
        return;
    }

    for (ptr = buffer; ptr < buffer + length; ) {
        struct inotify_event *event = (struct inotify_event *)ptr;

        char *event_path = get_path_from_wd(watch_list, event->wd);
        if (!event_path) {
            fprintf(stderr, "Error: Unknown watch descriptor %d\n", event->wd);
            ptr += EVENT_SIZE + event->len;
            continue;
        }

        char full_event_name[PATH_MAX];
        if (event->len) { // Check if name is present
             // Concatenate base path and event name
            snprintf(full_event_name, PATH_MAX, "%s/%s", event_path, event->name);
        } else {
             // Event involves the directory itself (e.g., directory deleted)
            strncpy(full_event_name, event_path, PATH_MAX - 1);
            full_event_name[PATH_MAX-1] = '\0';
        }


        printf("Event on %s", full_event_name);
        if (event->mask & IN_ISDIR) {
            printf(" (directory)");
        }
        printf(": ");

        if (event->mask & IN_CREATE) {
            printf("CREATE ");
            if (event->mask & IN_ISDIR) {
                // Automatically add watch for new directory
                printf(" - adding watch for new directory\n");
                add_recursive_watch(inotify_fd, full_event_name, watch_list);
            } else {
                printf("\n");
            }
        }
        if (event->mask & IN_DELETE) {
            printf("DELETE ");
            if (event->mask & IN_ISDIR) {
                // Potentially remove watches for deleted directory and its contents
                // This is tricky for nested watches. inotify_rm_watch automatically
                // cleans up if the directory is deleted.
                printf(" - directory deleted\n");
                // The watch might be automatically removed by the kernel if the directory itself is removed.
            } else {
                printf("\n");
            }
        }
        if (event->mask & IN_MODIFY) {
            printf("MODIFY\n");
        }
        if (event->mask & IN_ATTRIB) {
            printf("ATTRIB\n");
        }
        if (event->mask & IN_CLOSE_WRITE) {
            printf("CLOSE_WRITE (file was written to and closed)\n");
        }
        if (event->mask & IN_MOVED_FROM) {
            printf("MOVED_FROM (cookie: %d)\n", event->cookie);
            if (event->mask & IN_ISDIR) {
                // If a directory was moved, its watch becomes invalid in its old location.
                // It's more complex to handle re-watching if it's moved to a new location.
                // For simplicity, we just note it. The watch might be implicitly removed
                // by the kernel if the directory is moved out of the watched hierarchy.
            }
        }
        if (event->mask & IN_MOVED_TO) {
            printf("MOVED_TO (cookie: %d)\n", event->cookie);
            if (event->mask & IN_ISDIR) {
                // If a directory was moved into our watched hierarchy, add a watch.
                printf(" - adding watch for new directory moved in\n");
                add_recursive_watch(inotify_fd, full_event_name, watch_list);
            }
        }
        if (event->mask & IN_IGNORED) {
            printf("IGNORED (watch %d was removed/invalidated)\n", event->wd);
            remove_watch_entry(watch_list, event->wd); // Clean up internally
        }

        ptr += EVENT_SIZE + event->len;
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <directory_to_monitor> [another_directory ...]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int inotify_fd = inotify_init();
    if (inotify_fd == -1) {
        perror("inotify_init");
        exit(EXIT_FAILURE);
    }

    WatchList watch_list;
    init_watch_list(&watch_list, 10); // Start with capacity for 10 watches

    // Add initial watches for all specified directories
    for (int i = 1; i < argc; i++) {
        if (add_recursive_watch(inotify_fd, argv[i], &watch_list) == -1) {
            // Continue with other directories even if one fails
            printf("Failed to add watch for '%s', skipping.\n", argv[i]);
        }
    }

    printf("\nMonitoring started. Press Ctrl+C to exit.\n");

    // Main event loop
    while (1) {
        process_inotify_events(inotify_fd, &watch_list);
    }

    // This part is typically not reached for a daemon-like monitor.
    // In a real application, you'd have signal handling (e.g., SIGINT)
    // to gracefully exit and clean up.
    // For demonstration, we'll put cleanup here assuming termination.
    for (int i = 0; i < watch_list.count; i++) {
        inotify_rm_watch(inotify_fd, watch_list.entries[i].wd);
    }
    close(inotify_fd);
    free_watch_list(&watch_list);

    return 0;
}

