        default:        printf("Unknown machine (%d)\n", machine); break;
    }
}

// Main parsing function
int parse_elf_header(const char* filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        return -1;
    }

    Elf64_Ehdr elf_header;
    ssize_t bytes_read = read(fd, &elf_header, sizeof(Elf64_Ehdr));

    if (bytes_read != sizeof(Elf64_Ehdr)) {
        perror("Error reading ELF header");
        close(fd);
        return -1;
    }

    // Magic number check
    if (elf_header.e_ident[EI_MAG0] != ELFMAG0 ||
        elf_header.e_ident[EI_MAG1] != ELFMAG1 ||
        elf_header.e_ident[EI_MAG2] != ELFMAG2 ||
        elf_header.e_ident[EI_MAG3] != ELFMAG3) {
        fprintf(stderr, "Not an ELF file\n");
        close(fd);
        return -1;
    }

    // Print ELF header information
    printf("ELF Header Analysis:\n");
    printf("Magic Number:\t\t");
    for (int i = 0; i < EI_NIDENT; i++) {
        printf("%02x ", elf_header.e_ident[i]);
    }
    printf("\n");

    print_elf_class(elf_header.e_ident[EI_CLASS]);
    print_elf_data(elf_header.e_ident[EI_DATA]);
    print_elf_version(elf_header.e_ident[EI_VERSION]);
    print_elf_osabi(elf_header.e_ident[EI_OSABI]);

    print_elf_type(elf_header.e_type);
    print_elf_machine(elf_header.e_machine);

    printf("Entry point:\t\t0x%lx\n", elf_header.e_entry);
    printf("Program header offset:\t%ld\n", elf_header.e_phoff);
    printf("Section header offset:\t%ld\n", elf_header.e_shoff);
    printf("Flags:\t\t\t0x%x\n", elf_header.e_flags);
    printf("Header size:\t\t%d bytes\n", elf_header.e_ehsize);
    printf("Program header size:\t%d bytes\n", elf_header.e_phentsize);
    printf("Program header count:\t%d\n", elf_header.e_phnum);
    printf("Section header size:\t%d bytes\n", elf_header.e_shentsize);
    printf("Section header count:\t%d\n", elf_header.e_shnum);
    printf("Section header string index: %d\n", elf_header.e_shstrndx);

    close(fd);
    return 0;
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <executable>\n", argv[0]);
        return 1;
    }

    return parse_elf_header(argv[1]);
}

