// --- Main Parsing Logic ---

void parse_elf_header(int fd, char *filename) {
    unsigned char e_ident[EI_NIDENT];
    ssize_t bytes_read;

    // Read the first EI_NIDENT bytes to determine ELF class (32/64-bit)
    if (lseek(fd, 0, SEEK_SET) == -1) {
        perror("lseek");
        return;
    }
    bytes_read = read(fd, e_ident, EI_NIDENT);
    if (bytes_read != EI_NIDENT) {
        fprintf(stderr, "Error: Could not read ELF identification bytes (expected %d, got %zd).\n", EI_NIDENT, bytes_read);
        return;
    }

    // Check ELF magic number
    if (e_ident[EI_MAG0] != ELFMAG0 ||
        e_ident[EI_MAG1] != ELFMAG1 ||
        e_ident[EI_MAG2] != ELFMAG2 ||
        e_ident[EI_MAG3] != ELFMAG3) {
        fprintf(stderr, "Error: %s is not an ELF file (bad magic number).\n", filename);
        return;
    }

    printf("ELF Header for file: %s\n", filename);
    print_elf_magic(e_ident);
    print_elf_class(e_ident[EI_CLASS]);
    print_elf_data(e_ident[EI_DATA]);
    print_elf_version_ident(e_ident[EI_VERSION]);
    print_elf_osabi(e_ident[EI_OSABI]);
    print_elf_abi_version(e_ident[EI_ABIVERSION]);

    // Determine 32-bit or 64-bit ELF
    if (e_ident[EI_CLASS] == ELFCLASS32) {
        Elf32_Ehdr header;
        // Seek back to the beginning to read the full 32-bit header
        if (lseek(fd, 0, SEEK_SET) == -1) {
            perror("lseek");
            return;
        }
        bytes_read = read(fd, &header, sizeof(Elf32_Ehdr));
        if (bytes_read != sizeof(Elf32_Ehdr)) {
            fprintf(stderr, "Error: Could not read full 32-bit ELF header (expected %zu, got %zd).\n", sizeof(Elf32_Ehdr), bytes_read);
            return;
        }

        printf("  Machine:                           %x\n", header.e_machine);
        print_elf_type(header.e_type);
        print_elf_machine(header.e_machine);
        print_elf_version_hdr(header.e_version);
        printf("  Entry point address:               0x%lx\n", (unsigned long)header.e_entry);
        printf("  Start of program headers:          %lu (bytes into file)\n", (unsigned long)header.e_phoff);
        printf("  Start of section headers:          %lu (bytes into file)\n", (unsigned long)header.e_shoff);
        printf("  Flags:                             0x%x\n", header.e_flags);
        printf("  Size of this header:               %u (bytes)\n", header.e_ehsize);
        printf("  Size of program headers:           %u (bytes)\n", header.e_phentsize);
        printf("  Number of program headers:         %u\n", header.e_phnum);
        printf("  Size of section headers:           %u (bytes)\n", header.e_shentsize);
        printf("  Number of section headers:         %u\n", header.e_shnum);
        printf("  Section header string table index: %u\n", header.e_shstrndx);

    } else if (e_ident[EI_CLASS] == ELFCLASS64) {
        Elf64_Ehdr header;
        // Seek back to the beginning to read the full 64-bit header
        if (lseek(fd, 0, SEEK_SET) == -1) {
            perror("lseek");
            return;
        }
        bytes_read = read(fd, &header, sizeof(Elf64_Ehdr));
        if (bytes_read != sizeof(Elf64_Ehdr)) {
            fprintf(stderr, "Error: Could not read full 64-bit ELF header (expected %zu, got %zd).\n", sizeof(Elf64_Ehdr), bytes_read);
            return;
        }

        print_elf_type(header.e_type);
        print_elf_machine(header.e_machine);
        print_elf_version_hdr(header.e_version);
        printf("  Entry point address:               0x%lx\n", (unsigned long)header.e_entry);
        printf("  Start of program headers:          %lu (bytes into file)\n", (unsigned long)header.e_phoff);
        printf("  Start of section headers:          %lu (bytes into file)\n", (unsigned long)header.e_shoff);
        printf("  Flags:                             0x%x\n", header.e_flags);
        printf("  Size of this header:               %u (bytes)\n", header.e_ehsize);
        printf("  Size of program headers:           %u (bytes)\n", header.e_phentsize);
        printf("  Number of program headers:         %u\n", header.e_phnum);
        printf("  Size of section headers:           %u (bytes)\n", header.e_shentsize);
        printf("  Number of section headers:         %u\n", header.e_shnum);
        printf("  Section header string table index: %u\n", header.e_shstrndx);

    } else {
        fprintf(stderr, "Error: Unknown ELF class %x. Cannot parse header.\n", e_ident[EI_CLASS]);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <executable_file>\n", argv[0]);
        return 1;
    }

    int fd = open(argv[1], O_RDONLY);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    parse_elf_header(fd, argv[1]);

    if (close(fd) == -1) {
        perror("close");
        return 1;
    }

    return 0;
}

