int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <ELF executable>\n", argv[0]);
        return 1;
    }

    FILE *fp = fopen(argv[1], "rb");
    if (!fp) {
        perror("fopen");
        return 1;
    }

    unsigned char e_ident[EI_NIDENT];
    if (fread(e_ident, 1, EI_NIDENT, fp) != EI_NIDENT) {
        fprintf(stderr, "Failed to read ELF identification bytes\n");
        fclose(fp);
        return 1;
    }

    // Check ELF magic
    if (e_ident[EI_MAG0] != ELFMAG0 ||
        e_ident[EI_MAG1] != ELFMAG1 ||
        e_ident[EI_MAG2] != ELFMAG2 ||
        e_ident[EI_MAG3] != ELFMAG3) {
        fprintf(stderr, "Not an ELF file!\n");
        fclose(fp);
        return 1;
    }

    printf("ELF Header:\n");
    print_magic(e_ident);
    print_class(e_ident[EI_CLASS]);
    print_data(e_ident[EI_DATA]);
    printf("  Version:                           %d\n", e_ident[EI_VERSION]);
    print_osabi(e_ident[EI_OSABI]);
    printf("  ABI Version:                       %d\n", e_ident[EI_ABIVERSION]);

    // Set file position back to 0
    fseek(fp, 0, SEEK_SET);

    if (e_ident[EI_CLASS] == ELFCLASS32) {
        Elf32_Ehdr hdr32;
        if (fread(&hdr32, 1, sizeof(hdr32), fp) != sizeof(hdr32)) {
            fprintf(stderr, "Failed to read ELF32 header\n");
            fclose(fp);
            return 1;
        }

        print_type(hdr32.e_type);
        print_machine(hdr32.e_machine);
        print_version(hdr32.e_version);
        printf("  Entry point address:               0x%x\n", hdr32.e_entry);
        printf("  Start of program headers:          %u (bytes into file)\n", hdr32.e_phoff);
        printf("  Start of section headers:          %u (bytes into file)\n", hdr32.e_shoff);
