        printf("  Size of program headers:           %u (bytes)\n", hdr32.e_phentsize);
        printf("  Number of program headers:         %u\n", hdr32.e_phnum);
        printf("  Size of section headers:           %u (bytes)\n", hdr32.e_shentsize);
        printf("  Number of section headers:         %u\n", hdr32.e_shnum);
        printf("  Section header string table index: %u\n", hdr32.e_shstrndx);
    } else if (e_ident[EI_CLASS] == ELFCLASS64) {
        Elf64_Ehdr hdr64;
        if (fread(&hdr64, 1, sizeof(hdr64), fp) != sizeof(hdr64)) {
            fprintf(stderr, "Failed to read ELF64 header\n");
            fclose(fp);
            return 1;
        }

        print_type(hdr64.e_type);
        print_machine(hdr64.e_machine);
        print_version(hdr64.e_version);
        printf("  Entry point address:               0x%lx\n", hdr64.e_entry);
        printf("  Start of program headers:          %lu (bytes into file)\n", hdr64.e_phoff);
        printf("  Start of section headers:          %lu (bytes into file)\n", hdr64.e_shoff);
        printf("  Flags:                             0x%x\n", hdr64.e_flags);
        printf("  Size of this header:               %u (bytes)\n", hdr64.e_ehsize);
        printf("  Size of program headers:           %u (bytes)\n", hdr64.e_phentsize);
        printf("  Number of program headers:         %u\n", hdr64.e_phnum);
        printf("  Size of section headers:           %u (bytes)\n", hdr64.e_shentsize);
        printf("  Number of section headers:         %u\n", hdr64.e_shnum);
        printf("  Section header string table index: %u\n", hdr64.e_shstrndx);
    } else {
        fprintf(stderr, "Unknown ELF class\n");
        fclose(fp);
        return 1;
    }

    fclose(fp);
    return 0;
}

