// ELF header structure
typedef struct {
    unsigned char e_ident[16];  // Magic number and other info
    uint16_t e_type;            // Object file type
    uint16_t e_machine;         // Architecture
    uint32_t e_version;         // Current version
    uint64_t e_entry;           // Entry point virtual address
    uint64_t e_phoff;           // Program header table file offset
    uint64_t e_shoff;           // Section header table file offset
    uint32_t e_flags;           // Processor-specific flags
    uint16_t e_ehsize;          // ELF header size in bytes
    uint16_t e_phentsize;       // Program header table entry size
    uint16_t e_phnum;           // Program header table entry count
    uint16_t e_shentsize;       // Section header table entry size
    uint16_t e_shnum;           // Section header table entry count
    uint16_t e_shstrndx;        // Section header string table index
} Elf64_Ehdr;

// Function to read and validate ELF header
void parse_elf(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Could not open file");
        exit(EXIT_FAILURE);
    }

    Elf64_Ehdr ehdr;

    // Read the ELF header
    if (fread(&ehdr, sizeof(ehdr), 1, file) != 1) {
        perror("Could not read ELF header");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    // Validate ELF magic number
    if (memcmp(ehdr.e_ident, "\x7f" "ELF", 4) != 0) {
        fprintf(stderr, "Not a valid ELF file\n");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    // Display ELF header information
    printf("ELF Header:\n");
    printf("  Magic:   ");
    for (int i = 0; i < 16; i++) {
        printf("%02x ", ehdr.e_ident[i]);
    }
    printf("\n");

    printf("  Type:                             %u\n", ehdr.e_type);
    printf("  Machine:                          %u\n", ehdr.e_machine);
    printf("  Version:                          %u\n", ehdr.e_version);
    printf("  Entry point address:              0x%lx\n", ehdr.e_entry);
    printf("  Start of program headers:         %lu (bytes into file)\n", ehdr.e_phoff);
    printf("  Start of section headers:         %lu (bytes into file)\n", ehdr.e_shoff);
    printf("  Flags:                            %u\n", ehdr.e_flags);
    printf("  Size of this header:              %u (bytes)\n", ehdr.e_ehsize);
    printf("  Size of program headers:           %u (bytes)\n", ehdr.e_phentsize);
    printf("  Number of program headers:         %u\n", ehdr.e_phnum);
    printf("  Size of section headers:           %u (bytes)\n", ehdr.e_shentsize);
    printf("  Number of section headers:         %u\n", ehdr.e_shnum);
    printf("  Section header string table index: %u\n", ehdr.e_shstrndx);

    // Close the file
    fclose(file);
}

// Main function
int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <ELF file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    parse_elf(argv[1]);
    return EXIT_SUCCESS;
}

