}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <executable_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *filename = argv[1];
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("fstat");
        close(fd);
        return EXIT_FAILURE;
    }

    void *map = mmap(NULL, st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (map == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return EXIT_FAILURE;
    }

    Elf64_Ehdr *ehdr = (Elf64_Ehdr *)map;

    if (ehdr->e_ident[EI_MAG0] != ELFMAG0 ||
        ehdr->e_ident[EI_MAG1] != ELFMAG1 ||
        ehdr->e_ident[EI_MAG2] != ELFMAG2 ||
        ehdr->e_ident[EI_MAG3] != ELFMAG3) {
        fprintf(stderr, "Error: Not an ELF file\n");
        munmap(map, st.st_size);
        close(fd);
        return EXIT_FAILURE;
    }

    print_elf_header(ehdr);

    munmap(map, st.st_size);
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_FILE_SIZE 10000

// Function to reverse the contents of a file
int reverseFile(const char* inputFileName, const char* outputFileName) {
    FILE* inputFile;
    FILE* outputFile;
    char buffer[MAX_FILE_SIZE];
    long fileSize;

    // Open input file
    inputFile = fopen(inputFileName, "rb");
    if (inputFile == NULL) {
        fprintf(stderr, "Error: Unable to open input file %s\n", inputFileName);
        return -1;
    }

    // Determine file size
    fseek(inputFile, 0, SEEK_END);
    fileSize = ftell(inputFile);
    rewind(inputFile);

    // Check if file size exceeds buffer
    if (fileSize > MAX_FILE_SIZE) {
        fprintf(stderr, "Error: File size exceeds maximum buffer size\n");
        fclose(inputFile);
        return -1;
    }

    // Read entire file contents
    size_t bytesRead = fread(buffer, 1, fileSize, inputFile);
    if (bytesRead != fileSize) {
        fprintf(stderr, "Error: Unable to read entire file\n");
        fclose(inputFile);
        return -1;
    }

    // Close input file
    fclose(inputFile);

    // Reverse the buffer
    for (long i = 0; i < fileSize / 2; i++) {
        char temp = buffer[i];
        buffer[i] = buffer[fileSize - 1 - i];
        buffer[fileSize - 1 - i] = temp;
    }

    // Open output file
    outputFile = fopen(outputFileName, "wb");
    if (outputFile == NULL) {
        fprintf(stderr, "Error: Unable to open output file %s\n", outputFileName);
        return -1;
    }

    // Write reversed contents to output file
    size_t bytesWritten = fwrite(buffer, 1, fileSize, outputFile);
    if (bytesWritten != fileSize) {
        fprintf(stderr, "Error: Unable to write entire file\n");
        fclose(outputFile);
        return -1;
    }

    // Close output file
    fclose(outputFile);

    return 0;
}

// Alternative method to reverse file contents line by line
int reverseFileLineByLine(const char* inputFileName, const char* outputFileName) {
    FILE* inputFile;
    FILE* outputFile;
    char* lines[MAX_FILE_SIZE];
    int lineCount = 0;
    char buffer[1024];

    // Open input file
    inputFile = fopen(inputFileName, "r");
    if (inputFile == NULL) {
        fprintf(stderr, "Error: Unable to open input file %s\n", inputFileName);
        return -1;
    }

    // Read lines from file
    while (fgets(buffer, sizeof(buffer), inputFile) != NULL && lineCount < MAX_FILE_SIZE) {
        lines[lineCount] = strdup(buffer);
        lineCount++;
    }
    fclose(inputFile);

    // Open output file
    outputFile = fopen(outputFileName, "w");
    if (outputFile == NULL) {
        fprintf(stderr, "Error: Unable to open output file %s\n", outputFileName);

        // Free allocated memory
        for (int i = 0; i < lineCount; i++) {
            free(lines[i]);
        }
        return -1;
    }

    // Write lines in reverse order
    for (int i = lineCount - 1; i >= 0; i--) {
        fputs(lines[i], outputFile);
        free(lines[i]);  // Free memory after writing
    }

    fclose(outputFile);
    return 0;
}

int main(int argc, char* argv[]) {
    // Check command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_file> <output_file>\n", argv[0]);
        return 1;
    }

    const char* inputFileName = argv[1];
    const char* outputFileName = argv[2];

    // Choose reversal method
    int choice;
    printf("Choose reversal method:\n");
    printf("1. Byte-wise reversal\n");
    printf("2. Line-by-line reversal\n");
    printf("Enter your choice (1 or 2): ");
    scanf("%d", &choice);

    int result;
    switch (choice) {
        case 1:
            result = reverseFile(inputFileName, outputFileName);
            break;
        case 2:
            result = reverseFileLineByLine(inputFileName, outputFileName);
            break;
        default:
            fprintf(stderr, "Invalid choice. Defaulting to byte-wise reversal.\n");
            result = reverseFile(inputFileName, outputFileName);
    }

    if (result == 0) {
        printf("File reversed successfully!\n");
    } else {
        printf("Failed to reverse file.\n");
        return 1;
    }

    return 0;
}

