#include <stdio.h>
#include <stdlib.h> // For malloc, free
#include <string.h> // For strlen

// Function to get the size of a file
long int get_file_size(FILE *file) {
    long int current_pos = ftell(file); // Save current position
    fseek(file, 0, SEEK_END);          // Go to end of file
    long int size = ftell(file);       // Get size
    fseek(file, current_pos, SEEK_SET); // Restore original position
    return size;
}

// Function to reverse a string in-place
void reverse_string(char *str) {
    if (!str) return;
    int length = strlen(str);
    int i, j;
    for (i = 0, j = length - 1; i < j; i++, j--) {
        char temp = str[i];
        str[i] = str[j];
        str[j] = temp;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s <input_filename> <output_filename>\n", argv[0]);
        return 1; // Indicate an error
    }

    const char *input_filename = argv[1];
    const char *output_filename = argv[2];

    FILE *input_file = NULL;
    FILE *output_file = NULL;
    char *buffer = NULL;
    long int file_size = 0;

    // 1. Open the input file for reading
    input_file = fopen(input_filename, "rb"); // "rb" for binary read mode (good for all files)
    if (input_file == NULL) {
        perror("Error opening input file"); // Print system error message
        return 1;
    }

    // 2. Get the size of the input file
    file_size = get_file_size(input_file);
    if (file_size == -1) {
        perror("Error getting file size");
        fclose(input_file);
        return 1;
    }

    // 3. Allocate memory to hold the entire file content
    // We need to account for a null terminator if we plan to treat it as a C string
    // For binary reversal, it's not strictly necessary, but good practice if dealing with text.
    // Here, we allocate exactly file_size bytes as we're reversing byte by byte.
    buffer = (char *)malloc(file_size);
    if (buffer == NULL) {
        perror("Error allocating memory");
        fclose(input_file);
        return 1;
    }

    // 4. Read the entire content of the input file into the buffer
    size_t bytes_read = fread(buffer, 1, file_size, input_file);
    if (bytes_read != file_size) {
        perror("Error reading input file");
        // Ensure to close files and free memory on error
        fclose(input_file);
        free(buffer);
        return 1;
    }

    // At this point, the file is fully loaded into 'buffer'.
    // We can close the input file as we no longer need it.
    fclose(input_file);
    input_file = NULL; // Good practice to set to NULL after closing

    // 5. Reverse the content in the buffer (byte by byte)
    // This function can be simplified, but conceptually:
    // We want to reverse 'file_size' bytes.
    // The previous reverse_string function works well for a contiguous block of memory.
    reverse_string(buffer); // Our existing function works on char*, so it's fine.

    // 6. Open the output file for writing
    output_file = fopen(output_filename, "wb"); // "wb" for binary write mode
    if (output_file == NULL) {
        perror("Error opening output file");
        free(buffer); // Remember to free allocated memory
        return 1;
    }

    // 7. Write the reversed content from the buffer to the output file
    size_t bytes_written = fwrite(buffer, 1, file_size, output_file);
    if (bytes_written != file_size) {
        perror("Error writing to output file");
        // Ensure to close files and free memory on error
        fclose(output_file);
        free(buffer);
        return 1;
    }

    printf("File '%s' successfully reversed and saved to '%s'.\n",
           input_filename, output_filename);

    // 8. Clean up: Close the output file and free allocated memory
    fclose(output_file);
    free(buffer);

    return 0; // Indicate success
}

