    fsize = ftell(fin);

    // Open output file
    fout = fopen(argv[2], "wb");
    if (!fout) {
        perror("Error opening output file");
        fclose(fin);
        return 1;
    }

    // Read input file backwards and write to output
    for (i = fsize - 1; i >= 0; --i) {
        fseek(fin, i, SEEK_SET);
        ch = fgetc(fin);
        fputc(ch, fout);
    }

    fclose(fin);
    fclose(fout);

    printf("File reversed successfully.\n");
    return 0;
}

