// Function to reverse the contents of a file
void reverse_file(const char *input_filename, const char *output_filename) {
    // Open the input file in read mode
    FILE *input_file = fopen(input_filename, "r");
    if (input_file == NULL) {
        printf("Error: Unable to open %s for reading.\n", input_filename);
        return;
    }

    // Find the length of the input file
    fseek(input_file, 0, SEEK_END);
    long file_length = ftell(input_file);
    rewind(input_file);

    // Read the input file into a buffer
    char *buffer = malloc((file_length + 1) * sizeof(char));
    if (buffer == NULL) {
        printf("Error: Unable to allocate memory.\n");
        fclose(input_file);
        return;
    }

    if (fread(buffer, sizeof(char), file_length, input_file) != file_length) {
        printf("Error: Unable to read %s.\n", input_filename);
        free(buffer);
        fclose(input_file);
        return;
    }

    // Null-terminate the buffer
    buffer[file_length] = '\0';

    // Close the input file
    fclose(input_file);

    // Open the output file in write mode
    FILE *output_file = fopen(output_filename, "w");
    if (output_file == NULL) {
        printf("Error: Unable to open %s for writing.\n", output_filename);
        free(buffer);
        return;
    }

    // Write the buffer to the output file in reverse order
    for (long i = file_length - 1; i >= 0; i--) {
        if (fputc(buffer[i], output_file) == EOF) {
            printf("Error: Unable to write to %s.\n", output_filename);
            free(buffer);
            fclose(output_file);
            return;
        }
    }

    // Close the output file
    fclose(output_file);

    // Free the buffer
    free(buffer);
}

int main() {
    const char *input_filename = "input.txt";
    const char *output_filename = "output.txt";

    reverse_file(input_filename, output_filename);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

// Function to reverse a string in place
void reverseString(char *str) {
    int n = 0;
    while (str[n] != '\0') {
        n++;
    }
    for (int i = 0; i < n / 2; i++) {
        char temp = str[i];
        str[i] = str[n - i - 1];
        str[n - i - 1] = temp;
    }
}

// Function to reverse the contents of a file
int reverseFileContent(const char *inputFilePath, const char *outputFilePath) {
    FILE *inputFile, *outputFile;
    char *buffer;
    long fileSize;

    // Open the input file in read mode
    inputFile = fopen(inputFilePath, "rb");
    if (inputFile == NULL) {
        perror("Error opening input file");
        return 1;
    }

    // Seek to the end of the file to get its size
    fseek(inputFile, 0, SEEK_END);
    fileSize = ftell(inputFile);
    rewind(inputFile);

    // Allocate memory to read the entire file into a buffer
    buffer = (char *)malloc(fileSize + 1);
    if (buffer == NULL) {
        perror("Memory allocation failed");
        fclose(inputFile);
        return 1;
    }

    // Read the entire file into the buffer
    fread(buffer, fileSize, 1, inputFile);
    fclose(inputFile);

    // Null-terminate the buffer to make it a valid string
    buffer[fileSize] = '\0';

    // Reverse the content of the buffer
    reverseString(buffer);

    // Open the output file in write mode
    outputFile = fopen(outputFilePath, "wb");
    if (outputFile == NULL) {
        perror("Error opening output file");
        free(buffer);
        return 1;
    }

    // Write the reversed content back to the file
    fwrite(buffer, fileSize, 1, outputFile);
    fclose(outputFile);

    // Free the allocated memory
    free(buffer);

    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input_file> [output_file]\n", argv[0]);
        return 1;
    }

    const char *inputFilePath = argv[1];
    const char *outputFilePath = (argc > 2) ? argv[2] : argv[1];

    if (reverseFileContent(inputFilePath, outputFilePath) == 0) {
        printf("File content reversed successfully.\n");
    } else {
        fprintf(stderr, "Failed to reverse file content.\n");
    }

    return 0;
}

