// DNS record types
typedef enum {
    A_RECORD,     // IPv4 address
    AAAA_RECORD,  // IPv6 address
    CNAME_RECORD, // Canonical name
    MX_RECORD     // Mail exchange
} RecordType;

// DNS record structure
typedef struct {
    char domain[100];
    RecordType type;
    char value[100];
} DNSRecord;

// Simulated DNS records database
DNSRecord dnsDatabase[] = {
    {"example.com", A_RECORD, "192.168.1.100"},
    {"example.com", AAAA_RECORD, "2001:0db8:85a3:0000:0000:8a2e:0370:7334"},
    {"example.com", CNAME_RECORD, "www.example.com"},
    {"example.com", MX_RECORD, "mail.example.com"}
};

// Number of records in the database
const int DNS_RECORDS_COUNT = sizeof(dnsDatabase) / sizeof(dnsDatabase[0]);

// Function to convert record type to string
const char* getRecordTypeString(RecordType type) {
    switch (type) {
        case A_RECORD:     return "A";
        case AAAA_RECORD:  return "AAAA";
        case CNAME_RECORD: return "CNAME";
        case MX_RECORD:    return "MX";
        default:           return "UNKNOWN";
    }
}

// DNS lookup function
void dnsLookup(const char* domain, RecordType recordType) {
    printf("DNS Lookup for domain: %s (Type: %s)\n", 
           domain, getRecordTypeString(recordType));

    int found = 0;

    // Iterate through database to find matching records
    for (int i = 0; i < DNS_RECORDS_COUNT; i++) {
        if (strcmp(dnsDatabase[i].domain, domain) == 0 && 
            dnsDatabase[i].type == recordType) {

            printf("Record Found:\n");
            printf("Domain: %s\n", dnsDatabase[i].domain);
            printf("Type: %s\n", getRecordTypeString(dnsDatabase[i].type));
            printf("Value: %s\n\n", dnsDatabase[i].value);

            found = 1;
        }
    }

    if (!found) {
        printf("No records found for %s (Type: %s)\n\n", 
               domain, getRecordTypeString(recordType));
    }
}

// Advanced DNS lookup using system resolver
void advancedDNSLookup(const char* domain) {
    struct hostent* host;
    struct in_addr** addr_list;
    struct in6_addr** addr6_list;

    printf("Advanced DNS Lookup for %s\n", domain);

    // IPv4 Lookup
    host = gethostbyname(domain);
    if (host != NULL) {
        printf("\nIPv4 Addresses:\n");
        addr_list = (struct in_addr**)host->h_addr_list;
        for (int i = 0; addr_list[i] != NULL; i++) {
            char ip[INET_ADDRSTRLEN];
            inet_ntop(AF_INET, addr_list[i], ip, sizeof(ip));
            printf("  %s\n", ip);
        }
    }

    // IPv6 Lookup
    host = gethostbyname2(domain, AF_INET6);
    if (host != NULL) {
        printf("\nIPv6 Addresses:\n");
        addr6_list = (struct in6_addr**)host->h_addr_list;
        for (int i = 0; addr6_list[i] != NULL; i++) {
            char ip[INET6_ADDRSTRLEN];
            inet_ntop(AF_INET6, addr6_list[i], ip, sizeof(ip));
            printf("  %s\n", ip);
        }
    }
}

int main() {
