#include <netinet/in.h>
#include <sys/socket.h>
#include <unistd.h>

#define DNS_SERVER "8.8.8.8" // Google's public DNS server
#define DNS_PORT 53
#define BUFFER_SIZE 1024

// DNS header structure
struct dns_header {
    unsigned short id;
    unsigned char rd :1;
    unsigned char tc :1;
    unsigned char aa :1;
    unsigned char opcode :4;
    unsigned char qr :1;
    unsigned char rcode :4;
    unsigned char z :3;
    unsigned char ra :1;
    unsigned short qdcount;
    unsigned short ancount;
    unsigned short nscount;
    unsigned short arcount;
};

// DNS question structure
struct dns_question {
    unsigned short qtype;
    unsigned short qclass;
};

// Function to encode domain name to DNS format
void encode_dns_name(unsigned char* buffer, int* offset, const char* domain) {
    const char* dot;
    int length;

    while ((dot = strchr(domain, '.'))) {
        length = dot - domain;
        buffer[(*offset)++] = length;
        memcpy(buffer + *offset, domain, length);
        *offset += length;
        domain = dot + 1;
    }

    length = strlen(domain);
    buffer[(*offset)++] = length;
    memcpy(buffer + *offset, domain, length);
    *offset += length;
    buffer[(*offset)++] = 0; // Null terminator
}

// Function to create DNS query
void create_dns_query(unsigned char* buffer, const char* domain, int* length) {
    struct dns_header* header = (struct dns_header*)buffer;
    struct dns_question* question;
    int offset = 0;

    // Set header fields
    header->id = htons(1234); // Random ID
    header->qr = 0; // Query
    header->opcode = 0; // Standard query
    header->aa = 0;
    header->tc = 0;
    header->rd = 1; // Recursion desired
    header->ra = 0;
    header->z = 0;
    header->rcode = 0;
    header->qdcount = htons(1); // One question
    header->ancount = 0;
    header->nscount = 0;
    header->arcount = 0;

    offset = sizeof(struct dns_header);

    // Encode domain name
    encode_dns_name(buffer, &offset, domain);

    // Set question fields
    question = (struct dns_question*)(buffer + offset);
    question->qtype = htons(1); // Type A (host address)
    question->qclass = htons(1); // Class IN (Internet)

    offset += sizeof(struct dns_question);
    *length = offset;
}

int main() {
    int sockfd;
    struct sockaddr_in server_addr;
    unsigned char send_buffer[BUFFER_SIZE], recv_buffer[BUFFER_SIZE];
    int query_len, recv_len;

    // Create UDP socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(DNS_PORT);
    if (inet_pton(AF_INET, DNS_SERVER, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/Address not supported");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    // Create DNS query
    create_dns_query(send_buffer, "example.com", &query_len);

    // Send query
    if (sendto(sockfd, send_buffer, query_len, 0, 
               (const struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Send failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    printf("DNS query sent for example.com\n");

    // Receive response
    recv_len = recvfrom(sockfd, recv_buffer, BUFFER_SIZE, 0, NULL, NULL);
    if (recv_len < 0) {
        perror("Receive failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    printf("DNS response received (%d bytes)\n", recv_len);

    // In a real implementation, you would parse the response here
    // For this simulation, we'll just print that we got a response

    printf("Simulation complete. In a real implementation, we would parse the IP address from the response.\n");

    close(sockfd);
    return 0;
}

