// DNS Record Types
typedef enum {
    A_RECORD,     // IPv4 Address
    AAAA_RECORD,  // IPv6 Address
    CNAME_RECORD, // Canonical Name
    MX_RECORD     // Mail Exchange
} RecordType;

// DNS Record Structure
typedef struct {
    char domain[100];
    RecordType type;
    char value[100];
} DNSRecord;

// Simulated DNS Database
DNSRecord dnsDatabase[] = {
    {"myserver.local", A_RECORD, "192.168.1.100"},
    {"myserver.local", AAAA_RECORD, "2001:0db8:85a3:0000:0000:8a2e:0370:7334"},
    {"myserver.local", CNAME_RECORD, "server.company.local"},
    {"myserver.local", MX_RECORD, "mail.myserver.local"}
};

// Number of records in the database
const int DATABASE_SIZE = sizeof(dnsDatabase) / sizeof(DNSRecord);

// Function to perform DNS lookup
void performDNSLookup(const char* domain, RecordType recordType) {
    printf("DNS Lookup for domain: %s\n", domain);
    printf("---------------------------\n");

    int recordsFound = 0;

    for (int i = 0; i < DATABASE_SIZE; i++) {
        // Check if domain and record type match
        if (strcmp(dnsDatabase[i].domain, domain) == 0 && 
            dnsDatabase[i].type == recordType) {

            recordsFound++;

            // Display record based on type
            switch (dnsDatabase[i].type) {
                case A_RECORD:
                    printf("IPv4 Address: %s\n", dnsDatabase[i].value);
                    break;
                case AAAA_RECORD:
                    printf("IPv6 Address: %s\n", dnsDatabase[i].value);
                    break;
                case CNAME_RECORD:
                    printf("Canonical Name: %s\n", dnsDatabase[i].value);
                    break;
                case MX_RECORD:
                    printf("Mail Exchange: %s\n", dnsDatabase[i].value);
                    break;
            }
        }
    }

    // If no records found
    if (recordsFound == 0) {
        printf("No records found for the specified domain and type.\n");
    }
}

// Function to perform reverse DNS lookup
void performReverseDNSLookup(const char* ipAddress) {
    printf("Reverse DNS Lookup for IP: %s\n", ipAddress);
    printf("---------------------------\n");

    int recordsFound = 0;

    for (int i = 0; i < DATABASE_SIZE; i++) {
        // Check if IP matches
        if (strcmp(dnsDatabase[i].value, ipAddress) == 0 && 
            (dnsDatabase[i].type == A_RECORD || dnsDatabase[i].type == AAAA_RECORD)) {

            recordsFound++;
            printf("Domain: %s\n", dnsDatabase[i].domain);
        }
    }

    // If no records found
    if (recordsFound == 0) {
        printf("No domain found for the specified IP address.\n");
    }
}

