    printf("Example DNS Lookups:\n");
    printf("==================\n\n");

    // IPv4 Lookup
    performDNSLookup("myserver.local", A_RECORD);
    printf("\n");

    // IPv6 Lookup
    performDNSLookup("myserver.local", AAAA_RECORD);
    printf("\n");

    // CNAME Lookup
    performDNSLookup("myserver.local", CNAME_RECORD);
    printf("\n");

    // Mail Exchange Lookup
    performDNSLookup("myserver.local", MX_RECORD);
    printf("\n");

    // Reverse DNS Lookup
    performReverseDNSLookup("192.168.1.100");

