 *
 * This function searches a predefined, in-memory DNS database.
 *
 * @param domain The domain name to look up (e.g., "myserver.local").
 * @param resolved_ip A buffer where the resolved IP address will be copied
 *                    if found. Must be large enough (e.g., 16 bytes for IPv4).
 * @return 0 if the domain was found and its IP copied, -1 if not found.
 */
int simulate_dns_lookup(const char *domain, char *resolved_ip) {
    if (domain == NULL || resolved_ip == NULL) {
        fprintf(stderr, "Error: simulate_dns_lookup received NULL argument(s).\n");
        return -1;
    }

    printf("Simulating DNS lookup for: %s\n", domain);

    for (int i = 0; i < DNS_DB_SIZE; i++) {
        // Use strcmp to compare the domain names (case-sensitive)
        if (strcmp(domain, dns_database[i].domain_name) == 0) {
            // Found a match! Copy the IP address to the output buffer.
            // Ensure resolved_ip buffer is large enough to prevent buffer overflow.
            strncpy(resolved_ip, dns_database[i].ip_address, 16);
            resolved_ip[15] = '\0'; // Ensure null termination in case of truncation
            printf("  -> Match found in simulated database.\n");
            return 0; // Success
        }
    }

    printf("  -> Domain NOT found in simulated database.\n");
    return -1; // Not found
}

