void print_address(struct addrinfo *ai) {
    char ipstr[INET6_ADDRSTRLEN];
    void *addr;

    // Get the pointer to the address itself, different fields in IPv4 and IPv6
    if (ai->ai_family == AF_INET) { // IPv4
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)ai->ai_addr;
        addr = &(ipv4->sin_addr);
    } else { // IPv6
        struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)ai->ai_addr;
        addr = &(ipv6->sin6_addr);
    }

    // Convert the IP to a string and print it
    inet_ntop(ai->ai_family, addr, ipstr, sizeof ipstr);
    printf("  IP Address: %s\n", ipstr);
}

int main(int argc, char *argv[]) {
    struct addrinfo hints, *res, *p;
    int status;
    char domain[] = "myserver.local";

    // Initialize the hints structure
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC;     // Don't care (IPv4 or IPv6)
    hints.ai_socktype = SOCK_STREAM; // TCP stream sockets
    hints.ai_flags = AI_CANONNAME;   // Request for canonical name

    // Perform the DNS lookup
    if ((status = getaddrinfo(domain, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        exit(EXIT_FAILURE);
    }

    printf("DNS Lookup for %s:\n", domain);

    // Loop through all the results and print them
    for (p = res; p != NULL; p = p->ai_next) {
        printf("  Family: %s\n", (p->ai_family == AF_INET) ? "AF_INET" : "AF_INET6");
        if (p->ai_canonname) {
            printf("  Canonical name: %s\n", p->ai_canonname);
        }
        print_address(p); // Print the IP address
    }

    // Free the memory allocated by getaddrinfo
    freeaddrinfo(res);

    return 0;
}

