#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h> // For sleep()

// --- Data Structures ---

// Represents a DNS record (simplified for this simulation)
typedef struct {
    char domain[256];
    char ip_address[16]; // IPv4 format: "XXX.XXX.XXX.XXX"
    int ttl;             // Time To Live in seconds
    int is_authoritative; // 1 if authoritative, 0 if not
} DNSRecord;

// Represents a DNS cache entry
typedef struct CacheEntry {
    DNSRecord record;
    long long timestamp; // When the record was added/refreshed (for TTL checking)
    struct CacheEntry *next;
} CacheEntry;

// Represents a DNS server (simplified)
typedef struct DNSServer {
    char name[64];
    char ip_address[16];
    DNSRecord homepage_records[10]; // Simulating a small set of records the server "hosts"
    int num_homepage_records;
} DNSServer;

// --- Global Variables ---
DNSServer root_server;
DNSServer com_tld_server;
DNSServer openai_authoritative_server;
CacheEntry *local_dns_cache = NULL;

// --- Cache Management Functions ---

// Adds or updates a record in the local DNS cache
void add_to_cache(DNSRecord record) {
    if (record.ttl <= 0) {
        printf("DEBUG: Record for '%s' has TTL <= 0, not adding to cache.\n", record.domain);
        return; // Don't cache records with no or negative TTL
    }

    CacheEntry *current = local_dns_cache;
    CacheEntry *prev = NULL;

    // Check if the record already exists and is valid
    while (current != NULL) {
        if (strcmp(current->record.domain, record.domain) == 0) {
            // Update existing entry
            printf("DEBUG: Updating existing cache entry for '%s'.\n", record.domain);
            current->record = record;
            current->timestamp = time(NULL); // Refresh timestamp
            return;
        }
        prev = current;
        current = current->next;
    }

    // Record not found or expired, add new entry
    CacheEntry *new_entry = (CacheEntry *)malloc(sizeof(CacheEntry));
    if (new_entry == NULL) {
        perror("Failed to allocate cache entry");
        return;
    }
    new_entry->record = record;
    new_entry->timestamp = time(NULL);
    new_entry->next = NULL;

    if (local_dns_cache == NULL) {
        local_dns_cache = new_entry;
    } else {
        prev->next = new_entry;
    }
    printf("DEBUG: Added '%s' to cache. TTL: %d seconds.\n", record.domain, record.ttl);
}

// Looks up a domain in the local DNS cache
// Returns a pointer to the record if found and valid, NULL otherwise
DNSRecord *lookup_in_cache(const char *domain) {
    CacheEntry *current = local_dns_cache;
    while (current != NULL) {
        if (strcmp(current->record.domain, domain) == 0) {
            long long current_time = time(NULL);
            if (current->timestamp + current->record.ttl > current_time) {
                printf("DEBUG: Found '%s' in cache. Still valid for %lld seconds.\n",
                       domain, (long long)(current->timestamp + current->record.ttl - current_time));
                return &(current->record);
            } else {
                printf("DEBUG: Cache entry for '%s' expired. Purging.\n", domain);
                // Simple purge: mark as invalid, will be overwritten by new lookup
                // In a real system, you'd remove it from the linked list to free memory.
                // For simplicity here, we'll let it be overwritten by add_to_cache.
                return NULL;
            }
        }
        current = current->next;
    }
    printf("DEBUG: '%s' not found in cache.\n", domain);
    return NULL;
}

// Frees all memory allocated for the cache
void free_cache() {
    CacheEntry *current = local_dns_cache;
    while (current != NULL) {
        CacheEntry *next = current->next;
        free(current);
        current = next;
    }
    local_dns_cache = NULL;
    printf("DEBUG: DNS cache freed.\n");
}

// --- DNS Server Simulation Functions ---

// Simulates a DNS server's lookup
DNSRecord *server_lookup(DNSServer *server, const char *domain) {
    printf("  %s (%s) is querying for '%s'...\n", server->name, server->ip_address, domain);
    usleep(500000); // Simulate network latency

    for (int i = 0; i < server->num_homepage_records; i++) {
        if (strcmp(server->homepage_records[i].domain, domain) == 0) {
            printf("  %s found a direct match for '%s'! IP: %s\n",
                   server->name, domain, server->homepage_records[i].ip_address);
            return &(server->homepage_records[i]);
        }
    }
    printf("  %s does not have a direct match for '%s'.\n", server->name, domain);
    return NULL; // Not found directly
}

