// --- DNS Lookup Simulation ---

DNSRecord *simulate_dns_lookup(const char *domain) {
    printf("\n--- Starting DNS lookup for '%s' ---\n", domain);

    // 1. Check Local DNS Cache
    printf("1. Checking local DNS cache...\n");
    DNSRecord *record = lookup_in_cache(domain);
    if (record != NULL) {
        printf("  Found '%s' in local cache! IP: %s\n", domain, record->ip_address);
        return record;
    }

    printf("  '%s' not found in local cache. Initiating recursive query.\n", domain);

    DNSRecord *client_received_record = NULL; // The final record the client receives

    // Simplified recursive query logic:
    // Starts with a "local resolver" (represented implicitly by this function)
    // which queries the root, then TLD, then authoritative.

    printf("\n2. Querying Root DNS Server (%s)...\n", root_server.ip_address);
    // Client (or local resolver) asks Root for openai.com
    DNSRecord *root_response = server_lookup(&root_server, "com."); // Root points to .com TLD
    if (root_response != NULL) {
        printf("  Root server responded with pointer to .com TLD server: %s (%s)\n",
               root_server.homepage_records[0].domain, root_server.homepage_records[0].ip_address);
        add_to_cache(*root_response); // Cache the TLD server's IP (if it were a real IP record)
    } else {
        printf("  Root server did not have information for '.com.' No further lookup possible.\n");
        return NULL;
    }

    printf("\n3. Querying .com TLD Server (%s)...\n", com_tld_server.ip_address);
    // Local resolver asks .com TLD for openai.com
    DNSRecord *tld_response = server_lookup(&com_tld_server, "openai.com."); // TLD points to openai.com auth server
    if (tld_response != NULL) {
        printf("  .com TLD server responded with pointer to OpenAI Authoritative server: %s (%s)\n",
               com_tld_server.homepage_records[0].domain, com_tld_server.homepage_records[0].ip_address);
        add_to_cache(*tld_response); // Cache the authoritative server's IP (if it were a real IP record)
    } else {
        printf("  .com TLD server did not have information for 'openai.com.' No further lookup possible.\n");
        return NULL;
    }

    printf("\n4. Querying OpenAI Authoritative DNS Server (%s)...\n", openai_authoritative_server.ip_address);
    // Local resolver asks Authoritative server for openai.com
    DNSRecord *auth_response = server_lookup(&openai_authoritative_server, domain); // Authoritative server has the final A record
    if (auth_response != NULL && auth_response->is_authoritative) {
        printf("  OpenAI Authoritative server successfully returned IP for '%s': %s (Authoritative)\n",
               domain, auth_response->ip_address);
        add_to_cache(*auth_response); // Cache the actual A record
        client_received_record = auth_response;
    } else {
        printf("  OpenAI Authoritative server could not provide an authoritative answer for '%s'.\n", domain);
    }

    return client_received_record;
}

