#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define NUM_GOODS 5
#define SIMULATION_ROUNDS 10
#define MAX_PRODUCTION 1000
#define MAX_DEMAND 1500

// Structure to represent a good in the economy
typedef struct {
    char* name;
    int production_cost;
    int market_price;
    int production_quantity;
    int demand_quantity;
} Good;

// Function prototypes
void initialize_economy(Good* goods);
void simulate_production(Good* goods);
void simulate_demand(Good* goods);
void adjust_prices(Good* goods);
void print_economic_status(Good* goods, int round);
int calculate_total_economic_value(Good* goods);

int main() {
    Good goods[NUM_GOODS];

    // Initialize random seed
    srand(time(NULL));

    // Initialize economy
    initialize_economy(goods);

    // Economic simulation
    printf("Economic Simulation Started\n");
    printf("------------------------------\n");

    for (int round = 1; round <= SIMULATION_ROUNDS; round++) {
        printf("\nRound %d:\n", round);

        // Simulate production and demand
        simulate_production(goods);
        simulate_demand(goods);

        // Adjust market prices based on supply and demand
        adjust_prices(goods);

        // Print economic status for the round
        print_economic_status(goods, round);
    }

    // Final economic assessment
    int total_economic_value = calculate_total_economic_value(goods);
    printf("\nSimulation Complete. Total Economic Value: $%d\n", total_economic_value);

    return 0;
}

void initialize_economy(Good* goods) {
    goods[0] = (Good){"Food", 50, 100, 500, 600};
    goods[1] = (Good){"Clothing", 75, 150, 400, 450};
    goods[2] = (Good){"Electronics", 200, 300, 200, 250};
    goods[3] = (Good){"Energy", 100, 175, 600, 550};
    goods[4] = (Good){"Raw Materials", 25, 75, 700, 800};
}

void simulate_production(Good* goods) {
    for (int i = 0; i < NUM_GOODS; i++) {
        // Random variation in production
        int production_change = rand() % 200 - 100;
        goods[i].production_quantity += production_change;

        // Ensure production stays within reasonable limits
        if (goods[i].production_quantity < 0)
            goods[i].production_quantity = 0;
        if (goods[i].production_quantity > MAX_PRODUCTION)
            goods[i].production_quantity = MAX_PRODUCTION;
    }
}

void simulate_demand(Good* goods) {
    for (int i = 0; i < NUM_GOODS; i++) {
        // Random variation in demand
        int demand_change = rand() % 250 - 125;
        goods[i].demand_quantity += demand_change;

        // Ensure demand stays within reasonable limits
        if (goods[i].demand_quantity < 0)
            goods[i].demand_quantity = 0;
        if (goods[i].demand_quantity > MAX_DEMAND)
            goods[i].demand_quantity = MAX_DEMAND;
    }
}

void adjust_prices(Good* goods) {
    for (int i = 0; i < NUM_GOODS; i++) {
        // Price adjustment based on supply and demand
        if (goods[i].production_quantity > goods[i].demand_quantity) {
            // Oversupply, reduce price
            goods[i].market_price -= rand() % 20 + 5;
        } else if (goods[i].production_quantity < goods[i].demand_quantity) {
            // Undersupply, increase price
            goods[i].market_price += rand() % 20 + 5;
        }

        // Prevent prices from going too low or high
        if (goods[i].market_price < goods[i].production_cost)
            goods[i].market_price = goods[i].production_cost;

        if (goods[i].market_price > goods[i].production_cost * 3)
            goods[i].market_price = goods[i].production_cost * 3;
    }
}

void print_economic_status(Good* goods, int round) {
    printf("Economic Status:\n");
    for (int i = 0; i < NUM_GOODS; i++) {
        printf("%s: Price = $%d, Production = %d, Demand = %d\n", 
               goods[i].name, 
               goods[i].market_price, 
               goods[i].production_quantity, 
               goods[i].demand_quantity);
    }
}

int calculate_total_economic_value(Good* goods) {
    int total_value = 0;
    for (int i = 0; i < NUM_GOODS; i++) {
        total_value += goods[i].market_price * goods[i].production_quantity;
    }
    return total_value;
}

#include <stdio.h>

// Function to calculate demand
double demand(double price) {
    // Example demand function: Qd = a - b*P
    double a = 100;  // Maximum demand when price is 0
    double b = 2;    // Slope of the demand curve
    return a - b * price;
}

// Function to calculate supply
double supply(double price) {
    // Example supply function: Qs = c + d*P
    double c = 20;   // Minimum supply when price is 0
    double d = 3;    // Slope of the supply curve
    return c + d * price;
}

// Function to find the equilibrium price and quantity
void find_equilibrium(double *equilibrium_price, double *equilibrium_quantity) {
    double price = 0.0;
    double step = 0.01;  // Step size for price adjustment
    double diff;

    // Iterate to find the equilibrium price
    while (1) {
        double qd = demand(price);
        double qs = supply(price);
        diff = qd - qs;

        // If the difference is small enough, we've found the equilibrium
        if (diff < 0.01 && diff > -0.01) {
            *equilibrium_price = price;
            *equilibrium_quantity = qd;  // or qs, since they are equal at equilibrium
            break;
        }

        // Adjust the price based on the difference between demand and supply
        if (diff > 0) {
            price += step;  // Increase price if demand is higher than supply
        } else {
            price -= step;  // Decrease price if supply is higher than demand
        }
    }
}

int main() {
    double equilibrium_price, equilibrium_quantity;

    // Find the equilibrium price and quantity
    find_equilibrium(&equilibrium_price, &equilibrium_quantity);

    // Output the results
    printf("Equilibrium Price: %.2f\n", equilibrium_price);
    printf("Equilibrium Quantity: %.2f\n", equilibrium_quantity);

    return 0;
}

