void calculateSupplyAndDemand() {
    // Reset market totals for the current turn
    for (int i = 0; i < NUM_GOODS; i++) {
        goods[i].total_supply = 0;
        goods[i].total_demand = 0;
    }

    for (int i = 0; i < NUM_AGENTS; i++) {
        // --- Production (Supply) ---
        GoodType produced_good = agents[i].primary_production_good;
        int produced_amount = goods[produced_good].base_production; // Using base_production from Good struct
        agents[i].inventory[produced_good] += produced_amount; // Agent adds to their inventory
        goods[produced_good].total_supply += produced_amount; // Market sees this as potential supply

        printf("Agent %d produced %d %s.\n", agents[i].id, produced_amount, goods[produced_good].name);

        // --- Consumption (Demand) ---
        // Agents try to buy a small amount of all goods
        for (int j = 0; j < NUM_GOODS; j++) {
            int desired_amount = CONSUMPTION_PER_AGENT;
            goods[j].total_demand += desired_amount; // Market sees this as demand
        }
    }
}

void adjustPrices() {
    printf("\n--- Price Adjustment ---\n");
    for (int i = 0; i < NUM_GOODS; i++) {
        double old_price = goods[i].price;
        if (goods[i].total_supply > goods[i].total_demand) {
            // Supply > Demand, price decreases
            goods[i].price *= (1.0 - PRICE_ADJUSTMENT_FACTOR);
            printf("%s: Supply exceeds Demand (%d vs %d). Price decreases from $%.2f to $%.2f\n",
                   goods[i].name, goods[i].total_supply, goods[i].total_demand, old_price, goods[i].price);
        } else if (goods[i].total_demand > goods[i].total_supply) {
            // Demand > Supply, price increases
            goods[i].price *= (1.0 + PRICE_ADJUSTMENT_FACTOR);
            printf("%s: Demand exceeds Supply (%d vs %d). Price increases from $%.2f to $%.2f\n",
                   goods[i].name, goods[i].total_supply, goods[i].total_demand, old_price, goods[i].price);
        } else {
            // Supply == Demand, price stable
            printf("%s: Supply equals Demand (%d vs %d). Price remains $%.2f\n",
                   goods[i].name, goods[i].total_supply, goods[i].total_demand, old_price);
        }
        // Ensure price doesn't go below zero (or a very small threshold)
        if (goods[i].price < 0.1) {
            goods[i].price = 0.1;
        }
    }
}

void conductTrades() {
    printf("\n--- Conducting Trades ---\n");
    // Simple trading: Agents sell what they have, then try to buy what they need.
    // This is a very simplified model; a real auction or order book would be more complex.

    // Phase 1: Agents try to sell their production (if they have excess)
    for (int i = 0; i < NUM_AGENTS; i++) {
        GoodType produced_good = agents[i].primary_production_good;
        int amount_to_sell = agents[i].inventory[produced_good]; // Agents sell all they have produced

        if (amount_to_sell > 0) {
            double revenue = amount_to_sell * goods[produced_good].price;
            agents[i].money += revenue;
            agents[i].inventory[produced_good] -= amount_to_sell;
            printf("Agent %d sold %d %s for $%.2f. Money: $%.2f\n",
                   agents[i].id, amount_to_sell, goods[produced_good].name, revenue, agents[i].money);
        }
    }

    // Phase 2: Agents try to buy goods they need
    // We'll iterate through agents and then through goods
    for (int i = 0; i < NUM_AGENTS; i++) { // Buyer agent
        for (int j = 0; j < NUM_GOODS; j++) { // Good to buy
            if (j == agents[i].primary_production_good) {
                // Agent doesn't explicitly *need* to buy what they produce, but can to sustain production.
                // For simplicity, they attempt to buy all goods.
            }

            int desired_buy_amount = CONSUMPTION_PER_AGENT;
            double cost_per_unit = goods[j].price;
            double total_cost = desired_buy_amount * cost_per_unit;

            if (agents[i].money >= total_cost) {
                // Agent has enough money, attempt to buy
                agents[i].money -= total_cost;
                agents[i].inventory[j] += desired_buy_amount;
                printf("Agent %d bought %d %s for $%.2f. Money: $%.2f\n",
                       agents[i].id, desired_buy_amount, goods[j].name, total_cost, agents[i].money);
            } else {
                // Not enough money, try to buy what they can afford
                int affordable_amount = (int)(agents[i].money / cost_per_unit);
                if (affordable_amount > 0) {
                    total_cost = affordable_amount * cost_per_unit;
                    agents[i].money -= total_cost;
                    agents[i].inventory[j] += affordable_amount;
                    printf("Agent %d could only afford %d %s for $%.2f. Money: $%.2f\n",
                           agents[i].id, affordable_amount, goods[j].name, total_cost, agents[i].money);
                } else {
                    printf("Agent %d cannot afford any %s.\n", agents[i].id, goods[j].name);
                }
            }
        }
    }
}

void displayAgentStatus(int agent_id) {
    printf("\n--- Agent %d Status ---\n", agent_id);
    printf("  Money: $%.2f\n", agents[agent_id].money);
    printf("  Producing: %s\n", goods[agents[agent_id].primary_production_good].name);
    printf("  Inventory:\n");
    for (int i = 0; i < NUM_GOODS; i++) {
        printf("    %s: %d\n", goods[i].name, agents[agent_id].inventory[i]);
    }
}

void runSimulation() {
    for (int turn = 1; turn <= MAX_SIMULATION_TURNS; turn++) {
        printf("\n====================================\n");
        printf("          Turn %d\n", turn);
        printf("====================================\n");

        displayMarket();

        // 1. Agents declare production & demand
        printf("\n--- Agents Producing and Demanding ---\n");
        calculateSupplyAndDemand();

        // 2. Adjust prices based on declared S&D
        adjustPrices();

        // 3. Conduct actual trades
        conductTrades();

        // Display a sample agent's status
        if (turn % 5 == 0 || turn == 1 || turn == MAX_SIMULATION_TURNS) {
            displayAgentStatus(0); // Display status of Agent 0 periodically
        }

        // Optional: Introduce a small delay to observe the simulation
        // #ifdef _WIN32
        // Sleep(1000); // 1 second delay (Windows)
        // #else
        // sleep(1);    // 1 second delay (Linux/macOS) - requires unistd.h
        // #endif
    }
}

#include <stdio.h>
#include <math.h>

// Demand: Qd = a - bP
// Supply: Qs = c + dP
// At equilibrium: Qd = Qs

double demand(double price, double a, double b) {
    return a - b * price;
}

double supply(double price, double c, double d) {
    return c + d * price;
}

double find_equilibrium_price(double a, double b, double c, double d) {
    // Equate demand and supply, solve for price:
    // a - bP = c + dP -> (a - c) = bP + dP -> (a - c) = (b + d)P -> P = (a - c)/(b + d)

    if ((b + d) == 0) {
        printf("Invalid parameters: b + d cannot be zero.\n");
        return -1;
    }
    return (a - c) / (b + d);
}

int main() {
    // Parameters (modifiable)
    double a = 100.0; // max demand at price=0
    double b = 2.0;   // sensitivity of demand to price
    double c = 10.0;  // supply offset (minimum supply for price=0)
    double d = 3.0;   // sensitivity of supply to price

    // Find equilibrium price
    double eq_price = find_equilibrium_price(a, b, c, d);

    if (eq_price < 0) {
        printf("No equilibrium price found.\n");
        return 1;
    }

    double eq_quantity = demand(eq_price, a, b);
    printf("Basic Supply and Demand Simulation\n");
    printf("----------------------------------\n");
    printf("Demand function: Qd = %.1f - %.1f * P\n", a, b);
    printf("Supply function: Qs = %.1f + %.1f * P\n\n", c, d);

    printf("Equilibrium price: %.2f\n", eq_price);
    printf("Equilibrium quantity: %.2f\n", eq_quantity);

    // Show table for a range of prices
    printf("\nPrice\tDemand\tSupply\n");
    for (double price = 0.0; price <= eq_price * 2; price += eq_price / 5) {
        double qd = demand(price, a, b);
        double qs = supply(price, c, d);
        printf("%.2f\t%.2f\t%.2f\n", price, qd > 0 ? qd : 0, qs > 0 ? qs : 0);
    }

    return 0;
}

