}

void simulateEconomy(float initialPrice) {
    float price = initialPrice;
    int supply = INITIAL_SUPPLY;
    int demand = INITIAL_DEMAND;
    int iteration = 0;

    printf("\nStarting simulation...\n");
    printf("Iteration | Price | Supply | Demand\n");

    while (iteration < MAX_ITERATIONS) {
        printf("%9d | %5.2f | %6d | %6d\n", iteration, price, supply, demand);

        if (supply > demand) {
            // Surplus: Decrease the price
            price -= 0.5;
        } else if (demand > supply) {
            // Shortage: Increase the price
            price += 0.5;
        }

        // Update supply and demand
        supply = INITIAL_SUPPLY + (int)(price * SUPPLY_INCREMENT);
        demand = INITIAL_DEMAND - (int)(price * DEMAND_DECREMENT);

        // Ensure demand and supply don't go negative
        if (demand < 0) demand = 0;
        if (supply < 0) supply = 0;

        iteration++;
    }

    printf("\nSimulation completed.\n");
}

