// Define a structure to represent a good
typedef struct Good {
    char name[20];
    double price;
    int quantitySupplied;
    int quantityDemanded;
} Good;

// Define a structure to represent a market
typedef struct Market {
    Good goods[10]; // Assuming a maximum of 10 goods
    int numGoods;
} Market;

// Define a structure to represent an economy
typedef struct Economy {
    Market market;
} Economy;

// Function to initialize a good
Good* initGood(char* name, double price, int quantitySupplied, int quantityDemanded) {
    Good* good = (Good*) malloc(sizeof(Good));
    strcpy(good->name, name);
    good->price = price;
    good->quantitySupplied = quantitySupplied;
    good->quantityDemanded = quantityDemanded;
    return good;
}

// Function to add a good to the market
void addGoodToMarket(Market* market, Good* good) {
    if (market->numGoods < 10) {
        market->goods[market->numGoods] = *good;
        market->numGoods++;
    } else {
        printf("Market is full. Cannot add more goods.\n");
    }
}

// Function to simulate supply and demand
void simulateSupplyAndDemand(Economy* economy) {
    Market* market = &economy->market;
    for (int i = 0; i < market->numGoods; i++) {
        Good* good = &market->goods[i];
        if (good->quantitySupplied > good->quantityDemanded) {
            // Excess supply, reduce price
            good->price *= 0.9;
            printf("Price of %s reduced to $%.2f due to excess supply.\n", good->name, good->price);
        } else if (good->quantitySupplied < good->quantityDemanded) {
            // Excess demand, increase price
            good->price *= 1.1;
            printf("Price of %s increased to $%.2f due to excess demand.\n", good->name, good->price);
        } else {
            // Equilibrium, no price change
            printf("Price of %s remains at $%.2f due to equilibrium.\n", good->name, good->price);
        }
    }
}

int main() {
    // Initialize economy and market
    Economy economy;
    economy.market.numGoods = 0;

    // Create goods
    Good* good1 = initGood("Apple", 1.00, 100, 80);
    Good* good2 = initGood("Banana", 0.50, 50, 40);
    Good* good3 = initGood("Orange", 1.50, 80, 100);

    // Add goods to market
    addGoodToMarket(&economy.market, good1);
    addGoodToMarket(&economy.market, good2);
    addGoodToMarket(&economy.market, good3);

    // Simulate supply and demand
    simulateSupplyAndDemand(&economy);

    // Free allocated memory
    free(good1);
    free(good2);
    free(good3);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

// Define constants for supply and demand functions
#define DEMAND_SLOPE -2
#define DEMAND_INTERCEPT 100
#define SUPPLY_SLOPE 3
#define SUPPLY_INTERCEPT 20

// Function to calculate demand based on price
int calculate_demand(int price) {
    return DEMAND_INTERCEPT + (DEMAND_SLOPE * price);
}

// Function to calculate supply based on price
int calculate_supply(int price) {
    return SUPPLY_INTERCEPT + (SUPPLY_SLOPE * price);
}

// Function to find the equilibrium price and quantity
void find_equilibrium() {
    int price = 0;
    while (calculate_demand(price) != calculate_supply(price)) {
        price++;
    }
    printf("Equilibrium Price: %d\n", price);
    printf("Equilibrium Quantity: %d\n", calculate_demand(price));
}

// Function to simulate the economy over multiple rounds
void simulate_economy(int initial_price, int num_rounds) {
    int price = initial_price;
    for (int round = 1; round <= num_rounds; round++) {
        int demand = calculate_demand(price);
        int supply = calculate_supply(price);

        printf("Round %d:\n", round);
        printf("Price: %d\n", price);
        printf("Demand: %d\n", demand);
        printf("Supply: %d\n", supply);

        if (supply > demand) {
            // Surplus: decrease price
            price -= 1;
            printf("Surplus detected. Decreasing price by 1.\n");
        } else if (supply < demand) {
            // Shortage: increase price
            price += 1;
            printf("Shortage detected. Increasing price by 1.\n");
        } else {
            // Equilibrium
            printf("Equilibrium reached.\n");
            break;
        }

        printf("\n");
    }
}

int main() {
    // Set initial conditions
    int initial_price = 10;
    int num_rounds = 20;

    // Find the equilibrium point
    find_equilibrium();

    // Simulate the economy
    printf("\nSimulating the economy for %d rounds starting from price %d:\n", num_rounds, initial_price);
    simulate_economy(initial_price, num_rounds);

    return 0;
}

