// Initialize the ecosystem with random organisms
void initializeEcosystem() {
    // Clear the ecosystem
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            ecosystem[i][j].type = EMPTY;
            ecosystem[i][j].energy = 0;
            ecosystem[i][j].age = 0;
        }
    }

    // Randomly place plants
    for (int i = 0; i < INITIAL_PLANTS; i++) {
        int x = rand() % GRID_SIZE;
        int y = rand() % GRID_SIZE;
        if (ecosystem[x][y].type == EMPTY) {
            ecosystem[x][y].type = PLANT;
            ecosystem[x][y].energy = 10;
        }
    }

    // Randomly place prey
    for (int i = 0; i < INITIAL_PREY; i++) {
        int x = rand() % GRID_SIZE;
        int y = rand() % GRID_SIZE;
        if (ecosystem[x][y].type == EMPTY) {
            ecosystem[x][y].type = PREY;
            ecosystem[x][y].energy = 20;
        }
    }

    // Randomly place predators
    for (int i = 0; i < INITIAL_PREDATORS; i++) {
        int x = rand() % GRID_SIZE;
        int y = rand() % GRID_SIZE;
        if (ecosystem[x][y].type == EMPTY) {
            ecosystem[x][y].type = PREDATOR;
            ecosystem[x][y].energy = 50;
        }
    }
}

// Display the current state of the ecosystem
void displayEcosystem() {
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            switch (ecosystem[i][j].type) {
                case EMPTY:   printf(". "); break;
                case PLANT:   printf("P "); break;
                case PREY:    printf("O "); break;
                case PREDATOR: printf("X "); break;
            }
        }
        printf("\n");
    }
    printf("\n");
}

// Simulate predator movement and hunting
void movePredators() {
    for (int x = 0; x < GRID_SIZE; x++) {
        for (int y = 0; y < GRID_SIZE; y++) {
            if (ecosystem[x][y].type == PREDATOR) {
                // Decrease energy
                ecosystem[x][y].energy--;

                // Find prey in adjacent cells
                for (int dx = -1; dx <= 1; dx++) {
                    for (int dy = -1; dy <= 1; dy++) {
                        int nx = x + dx;
                        int ny = y + dy;

                        // Check boundaries and prey presence
                        if (nx >= 0 && nx < GRID_SIZE && ny >= 0 && ny < GRID_SIZE) {
                            if (ecosystem[nx][ny].type == PREY) {
                                // Hunt prey and gain energy
                                ecosystem[x][y].energy += 20;
                                ecosystem[nx][ny].type = EMPTY;
                                break;
                            }
                        }
                    }
                }

                // Move to an empty cell
                int empty_cell = findEmptyAdjacentCell(x, y);
                if (empty_cell != -1) {
                    int new_x = x + (empty_cell % 3 - 1);
                    int new_y = y + (empty_cell / 3 - 1);

                    ecosystem[new_x][new_y] = ecosystem[x][y];
                    ecosystem[x][y].type = EMPTY;
                    ecosystem[x][y].energy = 0;
                }

                // Death by starvation
                if (ecosystem[x][y].energy <= 0) {
                    ecosystem[x][y].type = EMPTY;
                }

                // Reproduction
                reproduction(x, y);
            }
        }
    }
}

