                    prey_food[new_x][new_y]++;
                    if (prey_food[new_x][new_y] >= PREY_REPRODUCE_FOOD) {
                        prey_food[new_x][new_y] = 0;
                        grid[i][j] = PREY;
                    }
                }

                prey_starve[new_x][new_y]++;
                if (prey_starve[new_x][new_y] >= PREY_STARVE_TIME) {
                    grid[new_x][new_y] = EMPTY;
                }
            } else if (grid[i][j] == PREDATOR) {
                int dx = rand() % 3 - 1;
                int dy = rand() % 3 - 1;
                move_entity(i, j, dx, dy);

                int new_x = (i + dx + GRID_SIZE) % GRID_SIZE;
                int new_y = (j + dy + GRID_SIZE) % GRID_SIZE;

                if (grid[new_x][new_y] == PREY) {
                    grid[new_x][new_y] = EMPTY;
                    predator_food[new_x][new_y]++;
                    if (predator_food[new_x][new_y] >= PREDATOR_REPRODUCE_FOOD) {
                        predator_food[new_x][new_y] = 0;
                        grid[i][j] = PREDATOR;
                    }
                }

                predator_starve[new_x][new_y]++;
                if (predator_starve[new_x][new_y] >= PREDATOR_STARVE_TIME) {
                    grid[new_x][new_y] = EMPTY;
                }
            }
        }
    }
}

int main() {
    srand(time(NULL));
    initialize_grid();
    place_entities();

    for (int step = 0; step < STEPS; step++) {
        printf("Step %d:\n", step + 1);
        print_grid();
        simulate_step();
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <math.h> // For abs() and sqrt()

// --- Configuration Constants ---
#define WORLD_WIDTH 60
#define WORLD_HEIGHT 20
#define MAX_PLANTS 120
#define MAX_PREY 40
#define MAX_PREDATORS 15

// Plant properties
#define PLANT_FOOD_VALUE 10
#define PLANT_REGROWTH_TIME 5 // Ticks for a plant to regrow after being eaten

// Prey properties
#define PREY_START_ENERGY 50
#define PREY_ENERGY_PER_MOVE 1
#define PREY_REPRODUCE_COST 30
#define PREY_REPRODUCE_THRESHOLD 70 // Must have at least this energy to reproduce
#define PREY_FOOD_VALUE 40 // Energy gained by predator from eating prey
#define PREY_REPRODUCTION_COOLDOWN 5 // Ticks before a prey can reproduce again

// Predator properties
#define PREDATOR_START_ENERGY 100
#define PREDATOR_ENERGY_PER_MOVE 2
#define PREDATOR_REPRODUCE_COST 60
#define PREDATOR_REPRODUCE_THRESHOLD 120 // Must have at least this energy to reproduce
#define PREDATOR_REPRODUCTION_COOLDOWN 8 // Ticks before a predator can reproduce again

#define SIMULATION_TICKS 500 // Total simulation steps
#define TICK_DELAY_MS 100   // Milliseconds delay between ticks

// --- Platform-specific clear screen ---
#ifdef _WIN32
#include <windows.h> // For Sleep
#define CLEAR_SCREEN "cls"
#else
#include <unistd.h> // For usleep
#define CLEAR_SCREEN "clear"
#endif

// --- Structures ---
typedef struct {
    int x, y;
    bool is_alive;
    int regrowth_timer; // Counts down until plant is ready to regrow
} Plant;

typedef struct {
    int id; // Unique identifier for debugging
    int x, y;
    int energy;
    bool is_alive;
    int reproduction_cooldown; // Timer for reproduction
} Prey;

typedef struct {
    int id; // Unique identifier for debugging
    int x, y;
    int energy;
    bool is_alive;
    int reproduction_cooldown; // Timer for reproduction
} Predator;

// --- Global Arrays and Counters ---
Plant plants[MAX_PLANTS];
Prey prey[MAX_PREY];
Predator predators[MAX_PREDATORS];

int num_plants_alive = 0;
int num_prey_alive = 0;
int num_predators_alive = 0;

int next_prey_id = 1;
int next_predator_id = 1;

// --- Function Prototypes ---
void initialize_world();
void clear_screen();
void draw_world();
void update_plants();
void update_prey();
void update_predators();

// Helper functions
int get_random_empty_spot(int *x, int *y);
int get_random_direction(int *dx, int *dy);
double distance(int x1, int y1, int x2, int y2);
int find_closest_plant(int px, int py);
int find_closest_prey(int px, int py);
int get_available_prey_slot();
int get_available_predator_slot();
bool is_spot_occupied_by_animal(int x, int y);

// --- Main Function ---
int main() {
    srand(time(NULL)); // Seed the random number generator

    initialize_world();

    printf("Starting ecosystem simulation...\n");
    printf("Legend: #=Plant, S=Prey, P=Predator\n");
    printf("Press Enter to start simulation...");
    getchar(); // Wait for user

    for (int tick = 0; tick < SIMULATION_TICKS; tick++) {
        clear_screen();
        draw_world();

        printf("--- Tick %d ---\n", tick + 1);
        printf("Plants: %d | Prey: %d | Predators: %d\n", num_plants_alive, num_prey_alive, num_predators_alive);

        update_plants();
        update_prey();
        update_predators();

        // Check for extinction
        if (num_prey_alive == 0 && num_predators_alive > 0) {
            printf("\nPredators ran out of food! Predators are dying out...\n");
        }
        if (num_prey_alive == 0 && num_plants_alive > 0) {
             printf("\nAll prey died! The ecosystem might collapse.\n");
        }
        if (num_predators_alive == 0 && num_prey_alive > 0) {
            printf("\nPredators extinct! Prey population might explode.\n");
        }
        if (num_prey_alive == 0 && num_plants_alive == 0 && num_predators_alive == 0) {
            printf("\nEcosystem collapsed! All life extinct.\n");
            break;
        }

#ifdef _WIN32
        Sleep(TICK_DELAY_MS); // Milliseconds
#else
        usleep(TICK_DELAY_MS * 1000); // Microseconds
#endif
    }

    clear_screen();
    draw_world();
    printf("\nSimulation finished after %d ticks.\n", SIMULATION_TICKS);
    printf("Final Counts: Plants: %d | Prey: %d | Predators: %d\n", num_plants_alive, num_prey_alive, num_predators_alive);
    printf("Press Enter to exit.\n");
    getchar(); // Wait for user to see final state

    return 0;
}

// --- Function Implementations ---

void initialize_world() {
    // Initialize all entities as not alive
    for (int i = 0; i < MAX_PLANTS; i++) {
        plants[i].is_alive = false;
        plants[i].regrowth_timer = 0;
    }
    for (int i = 0; i < MAX_PREY; i++) {
        prey[i].is_alive = false;
    }
    for (int i = 0; i < MAX_PREDATORS; i++) {
        predators[i].is_alive = false;
    }

    int x, y;

    // Spawn initial plants
    for (int i = 0; i < MAX_PLANTS; i++) {
        if (get_random_empty_spot(&x, &y)) {
            plants[i].x = x;
            plants[i].y = y;
            plants[i].is_alive = true;
            plants[i].regrowth_timer = 0;
            num_plants_alive++;
        }
    }

    // Spawn initial prey
    for (int i = 0; i < MAX_PREY / 2; i++) { // Start with half max prey
        if (get_random_empty_spot(&x, &y)) {
            prey[i].id = next_prey_id++;
            prey[i].x = x;
            prey[i].y = y;
            prey[i].energy = PREY_START_ENERGY;
            prey[i].is_alive = true;
            prey[i].reproduction_cooldown = 0;
            num_prey_alive++;
        }
    }

    // Spawn initial predators
    for (int i = 0; i < MAX_PREDATORS / 2; i++) { // Start with half max predators
        if (get_random_empty_spot(&x, &y)) {
            predators[i].id = next_predator_id++;
            predators[i].x = x;
            predators[i].y = y;
            predators[i].energy = PREDATOR_START_ENERGY;
            predators[i].is_alive = true;
            predators[i].reproduction_cooldown = 0;
            num_predators_alive++;
        }
    }
}

void clear_screen() {
    system(CLEAR_SCREEN);
}

void draw_world() {
    char world_grid[WORLD_HEIGHT][WORLD_WIDTH];

    // Initialize grid with empty spaces
    for (int i = 0; i < WORLD_HEIGHT; i++) {
        for (int j = 0; j < WORLD_WIDTH; j++) {
            world_grid[i][j] = ' ';
        }
    }

    // Place plants
    for (int i = 0; i < MAX_PLANTS; i++) {
        if (plants[i].is_alive) {
            world_grid[plants[i].y][plants[i].x] = '#';
        }
    }

    // Place prey (overwrites plants if on same spot)
    for (int i = 0; i < MAX_PREY; i++) {
        if (prey[i].is_alive) {
            world_grid[prey[i].y][prey[i].x] = 'S';
        }
    }

    // Place predators (overwrites prey/plants if on same spot)
    for (int i = 0; i < MAX_PREDATORS; i++) {
        if (predators[i].is_alive) {
            world_grid[predators[i].y][predators[i].x] = 'P';
        }
    }

    // Draw the top border
    printf("+");
    for (int j = 0; j < WORLD_WIDTH; j++) printf("-");
    printf("+\n");

    // Draw the grid content with side borders
    for (int i = 0; i < WORLD_HEIGHT; i++) {
        printf("|");
        for (int j = 0; j < WORLD_WIDTH; j++) {
            printf("%c", world_grid[i][j]);
        }
        printf("|\n");
    }

    // Draw the bottom border
    printf("+");
    for (int j = 0; j < WORLD_WIDTH; j++) printf("-");
    printf("+\n");
}

void update_plants() {
    num_plants_alive = 0; // Recalculate
    for (int i = 0; i < MAX_PLANTS; i++) {
        if (!plants[i].is_alive) {
            plants[i].regrowth_timer++;
            if (plants[i].regrowth_timer >= PLANT_REGROWTH_TIME) {
                plants[i].is_alive = true;
                plants[i].regrowth_timer = 0;
            }
        }
        if (plants[i].is_alive) {
            num_plants_alive++;
        }
    }
}

void update_prey() {
    num_prey_alive = 0; // Recalculate
    for (int i = 0; i < MAX_PREY; i++) {
        if (!prey[i].is_alive) continue;

        // Decrease reproduction cooldown
        if (prey[i].reproduction_cooldown > 0) {
            prey[i].reproduction_cooldown--;
        }

        // Energy drain
        prey[i].energy -= PREY_ENERGY_PER_MOVE;

        // Check for death
        if (prey[i].energy <= 0) {
            prey[i].is_alive = false;
            printf("Prey %d died of starvation.\n", prey[i].id);
            continue; // Go to next prey
        }

        // Action: Eat or Move
        int target_plant_idx = find_closest_plant(prey[i].x, prey[i].y);
        bool moved = false;

        if (target_plant_idx != -1) {
            Plant *target_plant = &plants[target_plant_idx];

            // If adjacent, eat
            if (abs(prey[i].x - target_plant->x) <= 1 && abs(prey[i].y - target_plant->y) <= 1) {
                if (target_plant->is_alive) {
                    prey[i].energy += PLANT_FOOD_VALUE;
                    target_plant->is_alive = false;
                    target_plant->regrowth_timer = 0;
                    // printf("Prey %d ate plant at (%d,%d). Energy: %d\n", prey[i].id, target_plant->x, target_plant->y, prey[i].energy);
                }
            } else {
                // Move towards plant
                int dx = 0, dy = 0;
                if (prey[i].x < target_plant->x) dx = 1;
                else if (prey[i].x > target_plant->x) dx = -1;

                if (prey[i].y < target_plant->y) dy = 1;
                else if (prey[i].y > target_plant->y) dy = -1;

                int new_x = prey[i].x + dx;
                int new_y = prey[i].y + dy;

                // Ensure new position is within bounds and not occupied by another animal (for simplicity, only animal collision)
                if (new_x >= 0 && new_x < WORLD_WIDTH && new_y >= 0 && new_y < WORLD_HEIGHT) {
                    if (!is_spot_occupied_by_animal(new_x, new_y)) { // Only check for other animals
                        prey[i].x = new_x;
                        prey[i].y = new_y;
                        moved = true;
                    } else { // If blocked, try to move randomly
                        get_random_direction(&dx, &dy);
                        new_x = prey[i].x + dx;
                        new_y = prey[i].y + dy;
                        if (new_x >= 0 && new_x < WORLD_WIDTH && new_y >= 0 && new_y < WORLD_HEIGHT && !is_spot_occupied_by_animal(new_x, new_y)) {
                             prey[i].x = new_x;
                             prey[i].y = new_y;
                             moved = true;
                        }
                    }
                }
            }
        } else {
            // No food found, move randomly
            int dx, dy;
            get_random_direction(&dx, &dy);
            int new_x = prey[i].x + dx;
            int new_y = prey[i].y + dy;

            if (new_x >= 0 && new_x < WORLD_WIDTH && new_y >= 0 && new_y < WORLD_HEIGHT) {
                if (!is_spot_occupied_by_animal(new_x, new_y)) {
                    prey[i].x = new_x;
                    prey[i].y = new_y;
                    moved = true;
                }
            }
        }

        // Reproduction
        if (prey[i].energy >= PREY_REPRODUCE_THRESHOLD && prey[i].reproduction_cooldown == 0) {
            int new_prey_idx = get_available_prey_slot();
            if (new_prey_idx != -1) {
                int spawn_x, spawn_y;
                int attempts = 0;
                bool spawned = false;
                while (attempts < 8 && !spawned) { // Try to find adjacent spot
                    int d_dx = (rand() % 3) - 1;
                    int d_dy = (rand() % 3) - 1;
                    if (d_dx == 0 && d_dy == 0) continue; // Don't spawn on self

                    spawn_x = prey[i].x + d_dx;
                    spawn_y = prey[i].y + d_dy;

                    if (spawn_x >= 0 && spawn_x < WORLD_WIDTH && spawn_y >= 0 && spawn_y < WORLD_HEIGHT &&
                        !is_spot_occupied_by_animal(spawn_x, spawn_y)) { // Check only for animals
                        prey[new_prey_idx].id = next_prey_id++;
                        prey[new_prey_idx].x = spawn_x;
                        prey[new_prey_idx].y = spawn_y;
                        prey[new_prey_idx].energy = PREY_START_ENERGY; // Child starts with full energy
                        prey[new_prey_idx].is_alive = true;
                        prey[new_prey_idx].reproduction_cooldown = 0; // Child can reproduce immediately
                        prey[i].energy -= PREY_REPRODUCE_COST; // Parent pays cost
                        prey[i].reproduction_cooldown = PREY_REPRODUCTION_COOLDOWN; // Parent cooldown
                        // printf("Prey %d reproduced at (%d,%d)! Parent Energy: %d, New Prey ID: %d\n", prey[i].id, spawn_x, spawn_y, prey[i].energy, prey[new_prey_idx].id);
                        spawned = true;
                    }
                    attempts++;
                }
            }
        }
        num_prey_alive++;
    }
}

void update_predators() {
    num_predators_alive = 0; // Recalculate
    for (int i = 0; i < MAX_PREDATORS; i++) {
        if (!predators[i].is_alive) continue;

        // Decrease reproduction cooldown
        if (predators[i].reproduction_cooldown > 0) {
            predators[i].reproduction_cooldown--;
        }

        // Energy drain
        predators[i].energy -= PREDATOR_ENERGY_PER_MOVE;

        // Check for death
        if (predators[i].energy <= 0) {
            predators[i].is_alive = false;
            printf("Predator %d died of starvation.\n", predators[i].id);
            continue; // Go to next predator
        }

        // Action: Eat or Move
        int target_prey_idx = find_closest_prey(predators[i].x, predators[i].y);
        bool moved = false;

        if (target_prey_idx != -1) {
            Prey *target_prey = &prey[target_prey_idx];

            // If adjacent, eat
            if (abs(predators[i].x - target_prey->x) <= 1 && abs(predators[i].y - target_prey->y) <= 1) {
                if (target_prey->is_alive) {
                    predators[i].energy += PREY_FOOD_VALUE;
                    target_prey->is_alive = false; // Prey is eaten
                    // printf("Predator %d ate Prey %d at (%d,%d). Energy: %d\n", predators[i].id, target_prey->id, target_prey->x, target_prey->y, predators[i].energy);
                }
            } else {
                // Move towards prey
                int dx = 0, dy = 0;
                if (predators[i].x < target_prey->x) dx = 1;
                else if (predators[i].x > target_prey->x) dx = -1;

                if (predators[i].y < target_prey->y) dy = 1;
                else if (predators[i].y > target_prey->y) dy = -1;

                int new_x = predators[i].x + dx;
                int new_y = predators[i].y + dy;

                if (new_x >= 0 && new_x < WORLD_WIDTH && new_y >= 0 && new_y < WORLD_HEIGHT) {
                    if (!is_spot_occupied_by_animal(new_x, new_y)) {
                        predators[i].x = new_x;
                        predators[i].y = new_y;
                        moved = true;
                    } else { // If blocked, try to move randomly
                        get_random_direction(&dx, &dy);
                        new_x = predators[i].x + dx;
                        new_y = predators[i].y + dy;
                        if (new_x >= 0 && new_x < WORLD_WIDTH && new_y >= 0 && new_y < WORLD_HEIGHT && !is_spot_occupied_by_animal(new_x, new_y)) {
                             predators[i].x = new_x;
                             predators[i].y = new_y;
                             moved = true;
                        }
                    }
                }
            }
        } else {
            // No food found, move randomly
            int dx, dy;
            get_random_direction(&dx, &dy);
            int new_x = predators[i].x + dx;
            int new_y = predators[i].y + dy;

            if (new_x >= 0 && new_x < WORLD_WIDTH && new_y >= 0 && new_y < WORLD_HEIGHT) {
                if (!is_spot_occupied_by_animal(new_x, new_y)) {
                    predators[i].x = new_x;
                    predators[i].y = new_y;
                    moved = true;
                }
            }
        }

        // Reproduction
        if (predators[i].energy >= PREDATOR_REPRODUCE_THRESHOLD && predators[i].reproduction_cooldown == 0) {
            int new_predator_idx = get_available_predator_slot();
            if (new_predator_idx != -1) {
                int spawn_x, spawn_y;
                int attempts = 0;
                bool spawned = false;
                while (attempts < 8 && !spawned) {
                    int d_dx = (rand() % 3) - 1;
                    int d_dy = (rand() % 3) - 1;
                    if (d_dx == 0 && d_dy == 0) continue;

                    spawn_x = predators[i].x + d_dx;
                    spawn_y = predators[i].y + d_dy;

                    if (spawn_x >= 0 && spawn_x < WORLD_WIDTH && spawn_y >= 0 && spawn_y < WORLD_HEIGHT &&
                        !is_spot_occupied_by_animal(spawn_x, spawn_y)) {
                        predators[new_predator_idx].id = next_predator_id++;
                        predators[new_predator_idx].x = spawn_x;
                        predators[new_predator_idx].y = spawn_y;
                        predators[new_predator_idx].energy = PREDATOR_START_ENERGY;
                        predators[new_predator_idx].is_alive = true;
                        predators[new_predator_idx].reproduction_cooldown = 0;
                        predators[i].energy -= PREDATOR_REPRODUCE_COST;
                        predators[i].reproduction_cooldown = PREDATOR_REPRODUCTION_COOLDOWN;
                        // printf("Predator %d reproduced at (%d,%d)! Parent Energy: %d, New Predator ID: %d\n", predators[i].id, spawn_x, spawn_y, predators[i].energy, predators[new_predator_idx].id);
                        spawned = true;
                    }
                    attempts++;
                }
            }
        }
        num_predators_alive++;
    }
}

// --- Helper Function Implementations ---

// Get a random empty spot for initial spawning
int get_random_empty_spot(int *x, int *y) {
    for (int attempts = 0; attempts < 100; attempts++) {
        *x = rand() % WORLD_WIDTH;
        *y = rand() % WORLD_HEIGHT;

        // Check if spot is occupied by any existing living entity
        bool occupied = false;
        for (int i = 0; i < MAX_PLANTS; i++) {
            if (plants[i].is_alive && plants[i].x == *x && plants[i].y == *y) {
                occupied = true; break;
            }
        }
        if (occupied) continue;
        for (int i = 0; i < MAX_PREY; i++) {
            if (prey[i].is_alive && prey[i].x == *x && prey[i].y == *y) {
                occupied = true; break;
            }
        }
        if (occupied) continue;
        for (int i = 0; i < MAX_PREDATORS; i++) {
            if (predators[i].is_alive && predators[i].x == *x && predators[i].y == *y) {
                occupied = true; break;
            }
        }
        if (occupied) continue;

        return 1; // Found empty spot
    }
    return 0; // Failed to find empty spot
}

// Get a random direction (dx, dy) where dx, dy are -1, 0, or 1
int get_random_direction(int *dx, int *dy) {
    *dx = (rand() % 3) - 1; // -1, 0, or 1
    *dy = (rand() % 3) - 1; // -1, 0, or 1
    return 1;
}

// Calculate Euclidean distance between two points
double distance(int x1, int y1, int x2, int y2) {
    int dx = x1 - x2;
    int dy = y1 - y2;
    return sqrt(dx * dx + dy * dy);
}

// Find the index of the closest living plant to a given (px, py)
int find_closest_plant(int px, int py) {
    double min_dist = -1.0;
    int closest_idx = -1;

    for (int i = 0; i < MAX_PLANTS; i++) {
        if (plants[i].is_alive) {
            double dist = distance(px, py, plants[i].x, plants[i].y);
            if (closest_idx == -1 || dist < min_dist) {
                min_dist = dist;
                closest_idx = i;
            }
        }
    }
    return closest_idx;
}

// Find the index of the closest living prey to a given (px, py)
int find_closest_prey(int px, int py) {
    double min_dist = -1.0;
    int closest_idx = -1;

    for (int i = 0; i < MAX_PREY; i++) {
        if (prey[i].is_alive) {
            double dist = distance(px, py, prey[i].x, prey[i].y);
            if (closest_idx == -1 || dist < min_dist) {
                min_dist = dist;
                closest_idx = i;
            }
        }
    }
    return closest_idx;
}

// Get an available (not alive) slot in the prey array
int get_available_prey_slot() {
    if (num_prey_alive >= MAX_PREY) return -1; // No space

    for (int i = 0; i < MAX_PREY; i++) {
        if (!prey[i].is_alive) {
            return i;
        }
    }
    return -1; // Should not happen if num_prey_alive is less than MAX_PREY
}

// Get an available (not alive) slot in the predator array
int get_available_predator_slot() {
    if (num_predators_alive >= MAX_PREDATORS) return -1; // No space

    for (int i = 0; i < MAX_PREDATORS; i++) {
        if (!predators[i].is_alive) {
            return i;
        }
    }
    return -1; // Should not happen if num_predators_alive is less than MAX_PREDATORS
}

// Check if a spot is occupied by a living animal (prey or predator)
bool is_spot_occupied_by_animal(int x, int y) {
    for (int i = 0; i < MAX_PREY; i++) {
        if (prey[i].is_alive && prey[i].x == x && prey[i].y == y) {
            return true;
        }
    }
    for (int i = 0; i < MAX_PREDATORS; i++) {
        if (predators[i].is_alive && predators[i].x == x && predators[i].y == y) {
            return true;
        }
    }
    return false;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define SIZE        10    // grid size: 10x10
#define INIT_PLANTS 20
#define INIT_PREY   10
#define INIT_PRED   5

#define PLANT_GROW_PROB  10 // % chance per empty cell for new plant
#define PREY_REPRODUCE   4  // steps without eating to die
#define PREY_BREED_PROB  20 // % after eating
#define PRED_REPRODUCE   6  // steps without eating to die
#define PRED_BREED_PROB  10 // % after eating

typedef enum { EMPTY, PLANT, PREY, PREDATOR } CellType;

typedef struct {
    CellType type;
    int hunger;    // Steps since last meal for prey/predator
    int moved;     // Flag for movement in current step
} Cell;

Cell grid[SIZE][SIZE];

// Directions: N,S,E,W
const int dx[4] = { 0, 0, 1, -1 };
const int dy[4] = { -1, 1, 0, 0 };

void init_grid() {
    int i, x, y;
    for (y=0; y<SIZE; y++)
    for (x=0; x<SIZE; x++)
        grid[y][x] = (Cell){ EMPTY, 0, 0 };

    // Place plants
    for (i=0; i<INIT_PLANTS;) {
        x = rand()%SIZE; y = rand()%SIZE;
        if (grid[y][x].type==EMPTY) {
            grid[y][x].type = PLANT;
            i++;
        }
    }
    // Place prey
    for (i=0; i<INIT_PREY;) {
        x = rand()%SIZE; y = rand()%SIZE;
        if (grid[y][x].type==EMPTY) {
            grid[y][x] = (Cell){ PREY, 0, 0 };
            i++;
        }
    }
    // Place predators
    for (i=0; i<INIT_PRED;) {
        x = rand()%SIZE; y = rand()%SIZE;
        if (grid[y][x].type==EMPTY) {
            grid[y][x] = (Cell){ PREDATOR, 0, 0 };
            i++;
        }
    }
}

void display_grid() {
    int x, y;
    for (y=0; y<SIZE; y++) {
        for (x=0; x<SIZE; x++) {
            switch(grid[y][x].type) {
                case EMPTY:    printf(". "); break;
                case PLANT:    printf("P "); break;
                case PREY:     printf("r "); break; // rabbit
                case PREDATOR: printf("F "); break; // fox
            }
        }
        printf("\n");
    }
    printf("\n");
}

// Helper: Get random direction
int random_dir() { return rand()%4; }

// Try to move entity at (x, y); called only once per turn per cell due to .moved
void move_entity(int x, int y) {
    Cell *c = &grid[y][x];
    if (c->type != PREY && c->type != PREDATOR) return;
    if (c->moved) return;

    int i, nx, ny;
    int found = 0;

    // SEARCH: prey eats plant, predator eats prey
    for (i=0; i<4; i++) {
        nx = x + dx[i];
        ny = y + dy[i];
        if (nx<0||nx>=SIZE||ny<0||ny>=SIZE) continue;
        if (c->type == PREY && grid[ny][nx].type == PLANT) {
            // Eat plant
            grid[ny][nx] = *c;
            grid[ny][nx].hunger = 0; // Reset hunger on feed
            grid[ny][nx].moved = 1;
            grid[y][x] = (Cell){EMPTY,0,0};
            found = 1;
            // Breeding
            if (rand()%100 < PREY_BREED_PROB) grid[y][x] = (Cell){PREY,0,1};
            break;
        }
        if (c->type == PREDATOR && grid[ny][nx].type == PREY) {
            // Eat prey
            grid[ny][nx] = *c;
            grid[ny][nx].hunger = 0;
            grid[ny][nx].moved = 1;
            grid[y][x] = (Cell){EMPTY,0,0};
            found = 1;
            // Breeding
            if (rand()%100 < PRED_BREED_PROB) grid[y][x] = (Cell){PREDATOR,0,1};
            break;
        }
    }
    if (found) return;

    // Otherwise, move randomly into empty cell
    int dirs[4] = {0,1,2,3};
    // Shuffle directions
    for(i=3;i>0;i--) {
        int j = rand() % (i+1);
        int tmp = dirs[i];
        dirs[i] = dirs[j];
        dirs[j] = tmp;
    }
    for(i=0;i<4;i++) {
        nx = x + dx[dirs[i]];
        ny = y + dy[dirs[i]];
        if (nx<0||nx>=SIZE||ny<0||ny>=SIZE) continue;
        if (grid[ny][nx].type == EMPTY) {
            grid[ny][nx] = *c;
            grid[ny][nx].hunger++; // didn't eat
            grid[ny][nx].moved = 1;
            grid[y][x] = (Cell){EMPTY,0,0};
            found = 1;
            break;
        }
    }
    if (!found) c->hunger++; // stuck: hunger tick
}

void plant_growth() {
    int x, y;
    for (y=0; y<SIZE; y++)
    for (x=0; x<SIZE; x++) {
        if (grid[y][x].type == EMPTY && rand()%100 < PLANT_GROW_PROB)
            grid[y][x] = (Cell){PLANT, 0, 0};
    }
}

void cleanup_and_death() {
    int x, y;
    for (y=0; y<SIZE; y++)
    for (x=0; x<SIZE; x++) {
        grid[y][x].moved = 0;
        if (grid[y][x].type == PREY && grid[y][x].hunger >= PREY_REPRODUCE)
            grid[y][x] = (Cell){EMPTY,0,0}; // Prey starves
        if (grid[y][x].type == PREDATOR && grid[y][x].hunger >= PRED_REPRODUCE)
            grid[y][x] = (Cell){EMPTY,0,0}; // Predator starves
    }
}

int main() {
    int t, steps;
    srand(time(NULL));

    init_grid();
    printf("Ecosystem Simulation (Predators, Prey, Plants)\n");
    printf("Enter number of steps: ");
    scanf("%d", &steps);

    for (t=0; t<steps; t++) {
        printf("\n--- Step %d ---\n", t+1);
        display_grid();

        // Move phase
        int x, y;
        for (y=0; y<SIZE; y++)
        for (x=0; x<SIZE; x++)
            move_entity(x, y);

        // Plants grow
        plant_growth();

        // Clean up (hunger, reset moved)
        cleanup_and_death();

        // Optional: pause
        // getchar();
    }
    printf("\nSimulation complete.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define constants
#define GRID_SIZE 10
#define NUM_PLANTS 20
#define NUM_PREY 10
#define NUM_PREDATORS 5
#define SIMULATION_STEPS 20

// Define entities
typedef struct {
    int x, y;
} Plant;

typedef struct {
    int x, y;
    int energy;
} Prey;

typedef struct {
    int x, y;
    int energy;
} Predator;

// Function prototypes
void initialize(Plant plants[], Prey preys[], Predator predators[]);
void simulateStep(Plant plants[], Prey preys[], Predator predators[]);
void moveEntity(int *x, int *y);
void printGrid(Plant plants[], Prey preys[], Predator predators[]);

int main() {
    srand(time(NULL));

    Plant plants[NUM_PLANTS];
    Prey preys[NUM_PREY];
    Predator predators[NUM_PREDATORS];

    initialize(plants, preys, predators);
    for (int step = 0; step < SIMULATION_STEPS; step++) {
        printf("Simulation Step %d:\n", step + 1);
        simulateStep(plants, preys, predators);
        printGrid(plants, preys, predators);
    }

    return 0;
}

void initialize(Plant plants[], Prey preys[], Predator predators[]) {
    for (int i = 0; i < NUM_PLANTS; i++) {
        plants[i].x = rand() % GRID_SIZE;
        plants[i].y = rand() % GRID_SIZE;
    }

    for (int i = 0; i < NUM_PREY; i++) {
        preys[i].x = rand() % GRID_SIZE;
        preys[i].y = rand() % GRID_SIZE;
        preys[i].energy = 5;  // Initial energy
    }

    for (int i = 0; i < NUM_PREDATORS; i++) {
        predators[i].x = rand() % GRID_SIZE;
        predators[i].y = rand() % GRID_SIZE;
        predators[i].energy = 10;  // Initial energy
    }
}

void simulateStep(Plant plants[], Prey preys[], Predator predators[]) {
    // Move preys and allow them to eat plants
    for (int i = 0; i < NUM_PREY; i++) {
        moveEntity(&preys[i].x, &preys[i].y);
        preys[i].energy--;

        for (int j = 0; j < NUM_PLANTS; j++) {
            if (preys[i].x == plants[j].x && preys[i].y == plants[j].y) {
                preys[i].energy += 3;  // Gain energy from eating
                plants[j].x = rand() % GRID_SIZE;  // Regenerate plant
                plants[j].y = rand() % GRID_SIZE;
            }
        }
    }

    // Move predators and allow them to eat prey
    for (int i = 0; i < NUM_PREDATORS; i++) {
        moveEntity(&predators[i].x, &predators[i].y);
        predators[i].energy--;

        for (int j = 0; j < NUM_PREY; j++) {
            if (predators[i].x == preys[j].x && predators[i].y == preys[j].y) {
                predators[i].energy += 5;  // Gain energy from eating prey
                preys[j].x = rand() % GRID_SIZE;  // Respawn prey
                preys[j].y = rand() % GRID_SIZE;
                preys[j].energy = 5;
            }
        }
    }
}

void moveEntity(int *x, int *y) {
    int direction = rand() % 4;
    switch (direction) {
        case 0: if (*x > 0) (*x)--; break;  // Move up
        case 1: if (*x < GRID_SIZE - 1) (*x)++; break;  // Move down
        case 2: if (*y > 0) (*y)--; break;  // Move left
        case 3: if (*y < GRID_SIZE - 1) (*y)++; break;  // Move right
    }
}

void printGrid(Plant plants[], Prey preys[], Predator predators[]) {
    char grid[GRID_SIZE][GRID_SIZE];

    // Initialize grid
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            grid[i][j] = '.';
        }
    }

    // Place plants
    for (int i = 0; i < NUM_PLANTS; i++) {
        grid[plants[i].x][plants[i].y] = 'P';
    }

    // Place preys
    for (int i = 0; i < NUM_PREY; i++) {
        grid[preys[i].x][preys[i].y] = 'r';
    }

    // Place predators
    for (int i = 0; i < NUM_PREDATORS; i++) {
        grid[predators[i].x][predators[i].y] = 'D';
    }

    // Print grid
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            printf("%c ", grid[i][j]);
        }
        printf("\n");
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define INITIAL_PREY 20
#define INITIAL_PREDATORS 5
#define INITIAL_PLANTS 100
#define DAYS 20
#define MAX_PREY_BREED 2
#define MAX_PREDATOR_BREED 1
#define PREY_DEATH_RATE 0.1
#define PREDATOR_DEATH_RATE 0.1
#define PLANT_CONSUMPTION_RATE 2

typedef struct {
    int prey;
    int predators;
    int plants;
} Ecosystem;

void simulate_day(Ecosystem *eco) {
    int new_prey, new_predators;

    // Calculate new plants
    eco->plants += eco->plants * 0.1; // plants grow by 10%

    // Prey breeding
    new_prey = (int)(eco->prey * ((float)rand() / RAND_MAX) < 0.5 ? MAX_PREY_BREED : 0);
    eco->prey += new_prey;

    // Prey dying from predator consumption
    int eaten_prey = eco->predators * PLANT_CONSUMPTION_RATE;
    if (eaten_prey > eco->prey) {
        eaten_prey = eco->prey;
    }
    eco->prey -= eaten_prey;

    // Predators breed
    new_predators = (int)(eco->predators * ((float)rand() / RAND_MAX) < 0.5 ? MAX_PREDATOR_BREED : 0);
    eco->predators += new_predators;

    // Predator death
    int predator_deaths = (int)(eco->predators * PREDATOR_DEATH_RATE);
    eco->predators -= predator_deaths;
    if (eco->predators < 0) {
        eco->predators = 0;  // Prevent negative predators
    }

    // Prey death due to environment
    int prey_deaths = (int)(eco->prey * PREY_DEATH_RATE);
    eco->prey -= prey_deaths;
    if (eco->prey < 0) {
        eco->prey = 0;  // Prevent negative prey
    }
}

void print_ecosystem(Ecosystem eco, int day) {
    printf("Day %d: Prey: %d, Predators: %d, Plants: %d\n", day, eco.prey, eco.predators, eco.plants);
}

int main() {
    srand(time(NULL));

    Ecosystem eco;
    eco.prey = INITIAL_PREY;
    eco.predators = INITIAL_PREDATORS;
    eco.plants = INITIAL_PLANTS;

    printf("Starting Ecosystem Status:\n");
    print_ecosystem(eco, 0);

    for (int day = 1; day <= DAYS; day++) {
        simulate_day(&eco);
        print_ecosystem(eco, day);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define constants
#define MAX_PREDATORS 100
#define MAX_PREY 1000
#define MAX_PLANTS 10000
#define PREDATOR_REPRODUCTION_RATE 0.1
#define PREY_REPRODUCTION_RATE 0.5
#define PLANT_GROWTH_RATE 10
#define PREDATOR_DEATH_RATE 0.05
#define PREY_DEATH_RATE 0.1
#define HUNTING_SUCCESS_RATE 0.2

// Structure to represent a predator
typedef struct {
    int population;
} Predator;

// Structure to represent a prey
typedef struct {
    int population;
} Prey;

// Structure to represent a plant
typedef struct {
    int population;
} Plant;

// Function to simulate predator population growth
void simulatePredators(Predator* predators, Prey* prey) {
    // Calculate the number of prey hunted by predators
    int preyHunted = (int)((double)predators->population * (double)prey->population * HUNTING_SUCCESS_RATE);

    // Update prey population
    prey->population -= preyHunted;

    // Update predator population
    predators->population += (int)((double)predators->population * PREDATOR_REPRODUCTION_RATE);
    predators->population -= (int)((double)predators->population * PREDATOR_DEATH_RATE);

    // Ensure predator population does not exceed maximum
    if (predators->population > MAX_PREDATORS) {
        predators->population = MAX_PREDATORS;
    }
}

// Function to simulate prey population growth
void simulatePrey(Prey* prey, Plant* plants) {
    // Calculate the number of plants eaten by prey
    int plantsEaten = (int)((double)prey->population * 0.1);

    // Update plant population
    plants->population -= plantsEaten;

    // Update prey population
    prey->population += (int)((double)prey->population * PREY_REPRODUCTION_RATE);
    prey->population -= (int)((double)prey->population * PREY_DEATH_RATE);

    // Ensure prey population does not exceed maximum
    if (prey->population > MAX_PREY) {
        prey->population = MAX_PREY;
    }
}

// Function to simulate plant population growth
void simulatePlants(Plant* plants) {
    // Update plant population
    plants->population += PLANT_GROWTH_RATE;

    // Ensure plant population does not exceed maximum
    if (plants->population > MAX_PLANTS) {
        plants->population = MAX_PLANTS;
    }
}

int main() {
    // Initialize random number generator
    srand((unsigned int)time(NULL));

    // Initialize predators, prey, and plants
    Predator predators;
    predators.population = 10;

    Prey prey;
    prey.population = 100;

    Plant plants;
    plants.population = 1000;

    // Simulate ecosystem for 100 time steps
    for (int i = 0; i < 100; i++) {
        // Simulate predators
        simulatePredators(&predators, &prey);

        // Simulate prey
        simulatePrey(&prey, &plants);

        // Simulate plants
        simulatePlants(&plants);

        // Print population sizes
        printf("Time step %d:\n", i + 1);
        printf("Predators: %d\n", predators.population);
        printf("Prey: %d\n", prey.population);
        printf("Plants: %d\n\n", plants.population);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define constants
#define MAX_ENTITIES 100
#define MAX_PLANTS 50
#define TIME_STEPS 100

// Define entity structures
typedef struct {
    int x, y;
    int health;
} Entity;

typedef struct {
    int x, y;
    int health;
} Plant;

// Function prototypes
void initializeEntities(Entity* predators, Entity* prey, Plant* plants);
void simulateEcosystem(Entity* predators, Entity* prey, Plant* plants, int numPredators, int numPrey, int numPlants);
void movePredator(Entity* predator, Entity* prey, int numPrey, Plant* plants, int numPlants);
void movePrey(Entity* prey, Plant* plants, int numPlants);
void growPlants(Plant* plants, int numPlants);
void printEcosystem(Entity* predators, Entity* prey, Plant* plants, int numPredators, int numPrey, int numPlants);

int main() {
    srand(time(NULL));

    // Initialize entities
    Entity predators[MAX_ENTITIES];
    Entity prey[MAX_ENTITIES];
    Plant plants[MAX_PLANTS];
    int numPredators = 10;
    int numPrey = 30;
    int numPlants = 50;

    initializeEntities(predators, prey, plants);

    // Simulate the ecosystem
    simulateEcosystem(predators, prey, plants, numPredators, numPrey, numPlants);

    return 0;
}

void initializeEntities(Entity* predators, Entity* prey, Plant* plants) {
    for (int i = 0; i < MAX_ENTITIES; i++) {
        predators[i].x = rand() % 10;
        predators[i].y = rand() % 10;
        predators[i].health = 100;

        prey[i].x = rand() % 10;
        prey[i].y = rand() % 10;
        prey[i].health = 100;
    }

    for (int i = 0; i < MAX_PLANTS; i++) {
        plants[i].x = rand() % 10;
        plants[i].y = rand() % 10;
        plants[i].health = 100;
    }
}

void simulateEcosystem(Entity* predators, Entity* prey, Plant* plants, int numPredators, int numPrey, int numPlants) {
    for (int step = 0; step < TIME_STEPS; step++) {
        printf("Time Step: %d\n", step);
        printEcosystem(predators, prey, plants, numPredators, numPrey, numPlants);

        for (int i = 0; i < numPredators; i++) {
            movePredator(&predators[i], prey, numPrey, plants, numPlants);
        }

        for (int i = 0; i < numPrey; i++) {
            movePrey(&prey[i], plants, numPlants);
        }

        growPlants(plants, numPlants);

        // Check for dead entities and remove them
        for (int i = 0; i < numPredators; i++) {
            if (predators[i].health <= 0) {
                for (int j = i; j < numPredators - 1; j++) {
                    predators[j] = predators[j + 1];
                }
                numPredators--;
                i--;
            }
        }

        for (int i = 0; i < numPrey; i++) {
            if (prey[i].health <= 0) {
                for (int j = i; j < numPrey - 1; j++) {
                    prey[j] = prey[j + 1];
                }
                numPrey--;
                i--;
            }
        }
    }
}

void movePredator(Entity* predator, Entity* prey, int numPrey, Plant* plants, int numPlants) {
    int closestPrey = -1;
    int minDistance = 1000;

    for (int i = 0; i < numPrey; i++) {
        int distance = (prey[i].x - predator->x) * (prey[i].x - predator->x) + (prey[i].y - predator->y) * (prey[i].y - predator->y);
        if (distance < minDistance) {
            minDistance = distance;
            closestPrey = i;
        }
    }

    if (closestPrey != -1) {
        predator->x += (prey[closestPrey].x > predator->x) ? 1 : -1;
        predator->y += (prey[closestPrey].y > predator->y) ? 1 : -1;

        if (predator->x == prey[closestPrey].x && predator->y == prey[closestPrey].y) {
            prey[closestPrey].health -= 50;
            predator->health += 50;
        }
    } else {
        predator->x = rand() % 10;
        predator->y = rand() % 10;
    }

    predator->health -= 10;
}

void movePrey(Entity* prey, Plant* plants, int numPlants) {
    int closestPlant = -1;
    int minDistance = 1000;

    for (int i = 0; i < numPlants; i++) {
        int distance = (plants[i].x - prey->x) * (plants[i].x - prey->x) + (plants[i].y - prey->y) * (plants[i].y - prey->y);
        if (distance < minDistance) {
            minDistance = distance;
            closestPlant = i;
        }
    }

    if (closestPlant != -1) {
        prey->x += (plants[closestPlant].x > prey->x) ? 1 : -1;
        prey->y += (plants[closestPlant].y > prey->y) ? 1 : -1;

        if (prey->x == plants[closestPlant].x && prey->y == plants[closestPlant].y) {
            plants[closestPlant].health -= 50;
            prey->health += 50;
        }
    } else {
        prey->x = rand() % 10;
        prey->y = rand() % 10;
    }

    prey->health -= 10;
}

void growPlants(Plant* plants, int numPlants) {
    for (int i = 0; i < numPlants; i++) {
        plants[i].health += 10;
        if (plants[i].health > 100) {
            plants[i].health = 100;
        }
    }
}

void printEcosystem(Entity* predators, Entity* prey, Plant* plants, int numPredators, int numPrey, int numPlants) {
    char grid[10][10] = {0};

    for (int i = 0; i < numPlants; i++) {
        grid[plants[i].y][plants[i].x] = 'P';
    }

    for (int i = 0; i < numPrey; i++) {
        if (grid[prey[i].y][prey[i].x] == 'P') {
            grid[prey[i].y][prey[i].x] = 'R';
        } else {
            grid[prey[i].y][prey[i].x] = 'r';
        }
    }

    for (int i = 0; i < numPredators; i++) {
        if (grid[predators[i].y][predators[i].x] == 'P') {
            grid[predators[i].y][predators[i].x] = 'W';
        } else if (grid[predators[i].y][predators[i].x] == 'r' || grid[predators[i].y][predators[i].x] == 'R') {
            grid[predators[i].y][predators[i].x] = 'W';
        } else {
            grid[predators[i].y][predators[i].x] = 'w';
        }
    }

    for (int y = 0; y < 10; y++) {
        for (int x = 0; x < 10; x++) {
            if (grid[y][x] == 0) {
                printf(" ");
            } else {
                printf("%c", grid[y][x]);
            }
        }
        printf("\n");
    }
    printf("\n");
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <SDL2/SDL.h>

#define SCREEN_WIDTH 800
#define SCREEN_HEIGHT 600
#define MAX_OBJECTS 100
#define GRAVITY 9.8
#define TIMESTEP 0.016

typedef struct {
    float x, y;           // Position
    float vx, vy;         // Velocity
    float mass;           // Mass
    float radius;         // Radius for circular object
    SDL_Color color;      // Object color
    int is_static;        // Static or dynamic object
} PhysicsObject;

typedef struct {
    PhysicsObject objects[MAX_OBJECTS];
    int object_count;
} PhysicsWorld;

// Function prototypes
void init_physics_world(PhysicsWorld* world);
void add_object(PhysicsWorld* world, float x, float y, float mass, float radius, SDL_Color color, int is_static);
void update_physics(PhysicsWorld* world);
int check_collision(PhysicsObject* obj1, PhysicsObject* obj2);
void resolve_collision(PhysicsObject* obj1, PhysicsObject* obj2);
void render_objects(SDL_Renderer* renderer, PhysicsWorld* world);

void init_physics_world(PhysicsWorld* world) {
    world->object_count = 0;
}

void add_object(PhysicsWorld* world, float x, float y, float mass, float radius, SDL_Color color, int is_static) {
    if (world->object_count >= MAX_OBJECTS) return;

    PhysicsObject* obj = &world->objects[world->object_count++];
    obj->x = x;
    obj->y = y;
    obj->vx = 0;
    obj->vy = 0;
    obj->mass = mass;
    obj->radius = radius;
    obj->color = color;
    obj->is_static = is_static;
}

void update_physics(PhysicsWorld* world) {
    for (int i = 0; i < world->object_count; i++) {
        PhysicsObject* obj = &world->objects[i];

        // Skip static objects
        if (obj->is_static) continue;

        // Apply gravity
        obj->vy += GRAVITY * TIMESTEP;

        // Update position
        obj->x += obj->vx * TIMESTEP;
        obj->y += obj->vy * TIMESTEP;

        // Ground collision
        if (obj->y + obj->radius > SCREEN_HEIGHT) {
            obj->y = SCREEN_HEIGHT - obj->radius;
            obj->vy *= -0.7; // Damping
        }

        // Wall collisions
        if (obj->x - obj->radius < 0) {
            obj->x = obj->radius;
            obj->vx *= -0.7;
        }
        if (obj->x + obj->radius > SCREEN_WIDTH) {
            obj->x = SCREEN_WIDTH - obj->radius;
            obj->vx *= -0.7;
        }
    }

    // Object collision detection and resolution
    for (int i = 0; i < world->object_count; i++) {
        for (int j = i + 1; j < world->object_count; j++) {
            PhysicsObject* obj1 = &world->objects[i];
            PhysicsObject* obj2 = &world->objects[j];

            if (check_collision(obj1, obj2)) {
                resolve_collision(obj1, obj2);
            }
        }
    }
}

int check_collision(PhysicsObject* obj1, PhysicsObject* obj2) {
    float dx = obj2->x - obj1->x;
    float dy = obj2->y - obj1->y;
    float distance = sqrt(dx * dx + dy * dy);

    return distance < (obj1->radius + obj2->radius);
}

void resolve_collision(PhysicsObject* obj1, PhysicsObject* obj2) {
    if (obj1->is_static || obj2->is_static) return;

    float dx = obj2->x - obj1->x;
    float dy = obj2->y - obj1->y;
    float distance = sqrt(dx * dx + dy * dy);
    float overlap = (obj1->radius + obj2->radius) - distance;

    // Separate objects
    float nx = dx / distance;
    float ny = dy / distance;
    float tx = -ny;
    float ty = nx;

    // Relative velocity
    float dpTan1 = obj1->vx * tx + obj1->vy * ty;
    float dpTan2 = obj2->vx * tx + obj2->vy * ty;

    float dpNorm1 = obj1->vx * nx + obj1->vy * ny;
    float dpNorm2 = obj2->vx * nx + obj2->vy * ny;

    float m1 = (dpNorm1 * (obj1->mass - obj2->mass) + 2.0f * obj2->mass * dpNorm2) / (obj1->mass + obj2->mass);
    float m2 = (dpNorm2 * (obj2->mass - obj1->mass) + 2.0f * obj1->mass * dpNorm1) / (obj1->mass + obj2->mass);

    obj1->vx = tx * dpTan1 + nx * m1;
    obj1->vy = ty * dpTan1 + ny * m1;
    obj2->vx = tx * dpTan2 + nx * m2;
    obj2->vy = ty * dpTan2 + ny * m2;

    // Separate objects
    obj1->x -= overlap * nx * 0.5f;
    obj1->y -= overlap * ny * 0.5f;
    obj2->x += overlap * nx * 0.5f;
    obj2->y += overlap * ny * 0.5f;
}

void render_objects(SDL_Renderer* renderer, PhysicsWorld* world) {
    for (int i = 0; i < world->object_count; i++) {
        PhysicsObject* obj = &world->objects[i];
        SDL_SetRenderDrawColor(renderer, obj->color.r, obj->color.g, obj->color.b, 255);

        // Draw filled circle
        for (int w = 0; w < obj->radius * 2; w++) {
            for (int h = 0; h < obj->radius * 2; h++) {
                int dx = obj->radius - w;
                int dy = obj->radius - h;
                if ((dx*dx + dy*dy) <= (obj->radius * obj->radius)) {
                    SDL_RenderDrawPoint(renderer, obj->x - obj->radius + w, obj->y - obj->radius + h);
                }
            }
        }
    }
}

int main(int argc, char* argv[]) {
    SDL_Init(SDL_INIT_VIDEO);

    SDL_Window* window = SDL_CreateWindow("2D Physics Engine", 
        SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, 
        SCREEN_WIDTH, SCREEN_HEIGHT, 0);

    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    PhysicsWorld world;
    init_physics_world(&world);

    // Add some static ground
    add_object(&world, SCREEN_WIDTH/2, SCREEN_HEIGHT - 10, 0, 400, 
        (SDL_Color){100, 100, 100, 255}, 1);

    // Add dynamic objects
    for (int i = 0; i < 10; i++) {
        add_object(&world, rand() % SCREEN_WIDTH, 50 + rand() % 100, 
            10.0f, 10.0f, 
            (SDL_Color){rand()%255, rand()%255, rand()%255, 255}, 0);
    }

    SDL_Event event;
    int running = 1;
    while (running) {
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                running = 0;
            }
        }

        // Clear screen
        SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
        SDL_RenderClear(renderer);

        // Physics update
        update_physics(&world);

        // Render objects
        render_objects(renderer, &world);

        SDL_RenderPresent(renderer);
        SDL_Delay(16); // Cap to ~60 FPS
    }

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <stdbool.h>

#define GRAVITY 9.81f
#define TIME_STEP 0.01f
#define BOUNCINESS 0.8f

typedef struct {
    float x, y; // Position
    float vx, vy; // Velocity
    float mass; // Mass
    float radius; // Radius (for circular objects)
} Object;

void apply_gravity(Object *obj) {
    obj->vy += GRAVITY * TIME_STEP;
}

void update_position(Object *obj) {
    obj->x += obj->vx * TIME_STEP;
    obj->y += obj->vy * TIME_STEP;
}

bool check_collision(Object *obj1, Object *obj2) {
    float dx = obj1->x - obj2->x;
    float dy = obj1->y - obj2->y;
    float distance = sqrt(dx * dx + dy * dy);
    return distance < (obj1->radius + obj2->radius);
}

void resolve_collision(Object *obj1, Object *obj2) {
    // Calculate the normal vector
    float dx = obj2->x - obj1->x;
    float dy = obj2->y - obj1->y;
    float distance = sqrt(dx * dx + dy * dy);
    float nx = dx / distance;
    float ny = dy / distance;

    // Relative velocity
    float rvx = obj2->vx - obj1->vx;
    float rvy = obj2->vy - obj1->vy;

    // Velocity along the normal
    float vel_along_normal = rvx * nx + rvy * ny;

    // If objects are moving towards each other
    if (vel_along_normal > 0) return;

    // Calculate impulse
    float e = BOUNCINESS;
    float j = -(1 + e) * vel_along_normal;
    j /= (1 / obj1->mass + 1 / obj2->mass);

    // Apply impulse
    obj1->vx -= (j * nx) / obj1->mass;
    obj1->vy -= (j * ny) / obj1->mass;
    obj2->vx += (j * nx) / obj2->mass;
    obj2->vy += (j * ny) / obj2->mass;
}

void simulate(Object *objects, int num_objects, float duration) {
    float time = 0.0f;
    while (time < duration) {
        for (int i = 0; i < num_objects; i++) {
            apply_gravity(&objects[i]);
            update_position(&objects[i]);

            // Check for collisions with other objects
            for (int j = i + 1; j < num_objects; j++) {
                if (check_collision(&objects[i], &objects[j])) {
                    resolve_collision(&objects[i], &objects[j]);
                }
            }
        }
        time += TIME_STEP;
    }
}

int main() {
    Object objects[] = {
        {0.0f, 10.0f, 1.0f, 0.0f, 1.0f, 1.0f}, // Object 1
        {3.0f, 10.0f, -1.0f, 0.0f, 1.0f, 1.0f} // Object 2
    };
    int num_objects = sizeof(objects) / sizeof(Object);

    simulate(objects, num_objects, 5.0f);

    for (int i = 0; i < num_objects; i++) {
        printf("Object %d: x = %.2f, y = %.2f, vx = %.2f, vy = %.2f\n",
               i, objects[i].x, objects[i].y, objects[i].vx, objects[i].vy);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <unistd.h> // For usleep (on POSIX systems)
#include <termios.h> // For non-blocking input
#include <fcntl.h>   // For non-blocking input

// --- Constants ---
#define GRAVITY_ACCELERATION 9.81 // m/s^2 (downwards)
#define TIME_STEP 0.01            // seconds per simulation step (dt)
#define WINDOW_WIDTH 80           // Characters for console width
#define WINDOW_HEIGHT 25          // Characters for console height
#define WALL_BOUNCE_FACTOR 0.8    // How much velocity is retained after wall collision (0.0 to 1.0)
#define OBJECT_BOUNCE_FACTOR 0.9  // How much kinetic energy is retained after object collision
#define REST_THRESHOLD 0.05       // If speed is below this, objects "settle"
#define MAX_OBJECTS 10
#define PI 3.1415926535

// --- Structures ---

typedef struct {
    double x, y; // Position
} Vec2D;

typedef struct {
    Vec2D pos;     // Current position
    Vec2D vel;     // Current velocity
    Vec2D acc;     // Current acceleration (mass / force)
    double radius; // For circular objects
    double mass;   // Mass of the object
    char symbol;   // Character to represent the object
    int color;     // Ansi color code
} Object;

// --- Global Variables ---
Object objects[MAX_OBJECTS];
int numObjects = 0;
int running = 1; // Simulation running flag

// --- Function Prototypes ---
void initPhysicsEngine();
void addObject(double x, double y, double vx, double vy, double radius, double mass, char symbol, int color);
void updatePhysics();
void applyForces(Object *obj);
void integrate(Object *obj);
void handleCollisions();
void handleWallCollisions(Object *obj);
void handleObjectCollisions(Object *obj1, Object *obj2);
double distBetween(Object *obj1, Object *obj2);
void normalizeVector(Vec2D *vec);
double dotProduct(Vec2D v1, Vec2D v2);
Vec2D subtractVectors(Vec2D v1, Vec2D v2);
Vec2D addVectors(Vec2D v1, Vec2D v2);
Vec2D scaleVector(Vec2D v, double scalar);

void render();
void clearScreen();
void save_terminal_settings();
void restore_terminal_settings();
int kbhit(); // Check for key press without blocking
void set_non_blocking_input();
void set_blocking_input();

// --- Main Function ---
int main() {
    initPhysicsEngine();
    set_non_blocking_input(); // Enable non-blocking input
    save_terminal_settings(); // Save initial terminal state

    // Add some objects
    addObject(WINDOW_WIDTH / 4.0, WINDOW_HEIGHT / 4.0, 5.0, 0.0, 1.0, 5.0, 'O', 32); // Green 'O'
    addObject(WINDOW_WIDTH * 3.0 / 4.0, WINDOW_HEIGHT / 4.0, -5.0, 0.0, 1.0, 5.0, 'X', 33); // Yellow 'X'
    addObject(WINDOW_WIDTH / 2.0, WINDOW_HEIGHT / 8.0, 0.0, 0.0, 1.5, 10.0, '#', 34); // Blue '#'

    // Loop
    while (running) {
        updatePhysics();
        render();

        if (kbhit()) {
            char c = getchar();
            if (c == 'q' || c == 'Q') {
                running = 0; // Exit on 'q'
            } else if (c == 'r' || c == 'R') {
                // Reset simulation (simple way: re-init objects)
                numObjects = 0; // Clear existing objects
                addObject(WINDOW_WIDTH / 4.0, WINDOW_HEIGHT / 4.0, 5.0, 0.0, 1.0, 5.0, 'O', 32);
                addObject(WINDOW_WIDTH * 3.0 / 4.0, WINDOW_HEIGHT / 4.0, -5.0, 0.0, 1.0, 5.0, 'X', 33);
                addObject(WINDOW_WIDTH / 2.0, WINDOW_HEIGHT / 8.0, 0.0, 0.0, 1.5, 10.0, '#', 34);
            }
        }

        usleep(TIME_STEP * 1000000); // Sleep for TIME_STEP seconds
    }

    restore_terminal_settings(); // Restore terminal to original state
    set_blocking_input();        // Re-enable blocking input
    clearScreen();
    printf("Simulation ended.\n");

    return 0;
}

// --- Physics Engine Core Functions ---

void initPhysicsEngine() {
    // Nothing special to initialize globally beyond objects array
    printf("Physics Engine Initialized. Press 'q' to quit, 'r' to reset.\n");
}

void addObject(double x, double y, double vx, double vy, double radius, double mass, char symbol, int color) {
    if (numObjects < MAX_OBJECTS) {
        objects[numObjects].pos.x = x;
        objects[numObjects].pos.y = y;
        objects[numObjects].vel.x = vx;
        objects[numObjects].vel.y = vy;
        objects[numObjects].acc.x = 0.0;
        objects[numObjects].acc.y = 0.0;
        objects[numObjects].radius = radius;
        objects[numObjects].mass = mass;
        objects[numObjects].symbol = symbol;
        objects[numObjects].color = color;
        numObjects++;
    } else {
        printf("Max objects reached! Cannot add more.\n");
    }
}

void updatePhysics() {
    for (int i = 0; i < numObjects; i++) {
        applyForces(&objects[i]);
        integrate(&objects[i]);
    }
    handleCollisions();
}

void applyForces(Object *obj) {
    // Reset acceleration
    obj->acc.x = 0.0;
    obj->acc.y = 0.0;

    // Apply gravity
    obj->acc.y += GRAVITY_ACCELERATION; // Acceleration due to gravity (downwards)
}

void integrate(Object *obj) {
    // Apply acceleration to velocity (Euler integration)
    obj->vel.x += obj->acc.x * TIME_STEP;
    obj->vel.y += obj->acc.y * TIME_STEP;

    // Apply velocity to position
    obj->pos.x += obj->vel.x * TIME_STEP;
    obj->pos.y += obj->vel.y * TIME_STEP;

    // Small optimization for "resting" objects to prevent jitter
    if (fabs(obj->vel.x) < REST_THRESHOLD && fabs(obj->vel.y) < REST_THRESHOLD &&
        obj->pos.y >= WINDOW_HEIGHT - 1 - obj->radius) { // Approximately on the ground
        obj->vel.x = 0;
        obj->vel.y = 0;
    }
}

void handleCollisions() {
    // Handle wall collisions for all objects
    for (int i = 0; i < numObjects; i++) {
        handleWallCollisions(&objects[i]);
    }

    // Handle object-to-object collisions (O(N^2) complexity)
    for (int i = 0; i < numObjects; i++) {
        for (int j = i + 1; j < numObjects; j++) { // j starts from i+1 to avoid self-collision and duplicate checks
            handleObjectCollisions(&objects[i], &objects[j]);
        }
    }
}

void handleWallCollisions(Object *obj) {
    // Wall collision (circular objects hitting rectangular boundaries)
    // Left wall
    if (obj->pos.x - obj->radius < 0) {
        obj->pos.x = obj->radius;            // Reposition to just inside
        obj->vel.x *= -WALL_BOUNCE_FACTOR;   // Reverse X velocity and reduce
    }
    // Right wall
    if (obj->pos.x + obj->radius >= WINDOW_WIDTH - 1) {
        obj->pos.x = WINDOW_WIDTH - 1 - obj->radius;
        obj->vel.x *= -WALL_BOUNCE_FACTOR;
    }
    // Top wall
    if (obj->pos.y - obj->radius < 0) {
        obj->pos.y = obj->radius;
        obj->vel.y *= -WALL_BOUNCE_FACTOR;
    }
    // Bottom wall (ground)
    if (obj->pos.y + obj->radius >= WINDOW_HEIGHT - 1) {
        obj->pos.y = WINDOW_HEIGHT - 1 - obj->radius;
        obj->vel.y *= -WALL_BOUNCE_FACTOR;
        if (fabs(obj->vel.y) < REST_THRESHOLD) { // If velocity is very small after bounce, stop it
            obj->vel.y = 0;
        }
    }
}

void handleObjectCollisions(Object *obj1, Object *obj2) {
    double dist = distBetween(obj1, obj2);
    double min_dist = obj1->radius + obj2->radius;

    if (dist < min_dist) {
        // Collision detected!

        // 1. Resolve interpenetration (move objects apart)
        // Vector from obj2 to obj1
        Vec2D normal_axis = subtractVectors(obj1->pos, obj2->pos);
        normalizeVector(&normal_axis);

        double overlap = min_dist - dist;
        // Move each object half the overlap distance along the normal
        obj1->pos = addVectors(obj1->pos, scaleVector(normal_axis, overlap * 0.5));
        obj2->pos = subtractVectors(obj2->pos, scaleVector(normal_axis, overlap * 0.5));

        // 2. Calculate new velocities after collision (elastic collision formula)
        // Relative velocity
        Vec2D relative_vel = subtractVectors(obj1->vel, obj2->vel);

        // Relative velocity along the normal
        double vel_along_normal = dotProduct(relative_vel, normal_axis);

        // Do not resolve if velocities are separating
        if (vel_along_normal > 0) return;

        // Calculate impulse scalar
        double e = OBJECT_BOUNCE_FACTOR; // Coefficient of restitution (elasticity)
        double j = (-(1 + e) * vel_along_normal) / (dotProduct(normal_axis, normal_axis) * (1.0 / obj1->mass + 1.0 / obj2->mass));

        // Apply impulse
        Vec2D impulse = scaleVector(normal_axis, j);

        obj1->vel = addVectors(obj1->vel, scaleVector(impulse, 1.0 / obj1->mass));
        obj2->vel = subtractVectors(obj2->vel, scaleVector(impulse, 1.0 / obj2->mass));
    }
}

// --- Vector Math Helpers ---

double distBetween(Object *obj1, Object *obj2) {
    double dx = obj1->pos.x - obj2->pos.x;
    double dy = obj1->pos.y - obj2->pos.y;
    return sqrt(dx * dx + dy * dy);
}

void normalizeVector(Vec2D *vec) {
    double length = sqrt(vec->x * vec->x + vec->y * vec->y);
    if (length > 0) {
        vec->x /= length;
        vec->y /= length;
    }
}

double dotProduct(Vec2D v1, Vec2D v2) {
    return v1.x * v2.x + v1.y * v2.y;
}

Vec2D subtractVectors(Vec2D v1, Vec2D v2) {
    Vec2D result = {v1.x - v2.x, v1.y - v2.y};
    return result;
}

Vec2D addVectors(Vec2D v1, Vec2D v2) {
    Vec2D result = {v1.x + v2.x, v1.y + v2.y};
    return result;
}

Vec2D scaleVector(Vec2D v, double scalar) {
    Vec2D result = {v.x * scalar, v.y * scalar};
    return result;
}

// --- Rendering and Terminal Control Functions ---

void render() {
    clearScreen();

    char grid[WINDOW_HEIGHT][WINDOW_WIDTH];
    // Initialize grid with spaces
    for (int i = 0; i < WINDOW_HEIGHT; i++) {
        for (int j = 0; j < WINDOW_WIDTH; j++) {
            grid[i][j] = ' ';
        }
    }

    // Draw objects
    for (int i = 0; i < numObjects; i++) {
        int gx = (int)round(objects[i].pos.x);
        int gy = (int)round(objects[i].pos.y);

        // Draw object as a circle of characters
        for (double dy = -objects[i].radius; dy <= objects[i].radius; dy += 0.5) {
            for (double dx = -objects[i].radius; dx <= objects[i].radius; dx += 0.5) {
                if (sqrt(dx * dx + dy * dy) <= objects[i].radius) {
                    int px = gx + (int)round(dx);
                    int py = gy + (int)round(dy);

                    if (px >= 0 && px < WINDOW_WIDTH && py >= 0 && py < WINDOW_HEIGHT) {
                        grid[py][px] = objects[i].symbol;
                    }
                }
            }
        }
    }

    // Print buffer with colors
    for (int i = 0; i < WINDOW_HEIGHT; i++) {
        for (int j = 0; j < WINDOW_WIDTH; j++) {
            int printed_color = 0;
            for (int k = 0; k < numObjects; k++) {
                int obj_gx = (int)round(objects[k].pos.x);
                int obj_gy = (int)round(objects[k].pos.y);
                double distance_from_center = sqrt(pow(j - obj_gx, 2) + pow(i - obj_gy, 2));

                if (distance_from_center <= objects[k].radius) {
                    printf("\033[%dm%c\033[0m", objects[k].color, grid[i][j]);
                    printed_color = 1;
                    break; // Printed with color, move to next char
                }
            }
            if (!printed_color) {
                // If not part of any object, print walls and empty space
                 if (i == 0 || i == WINDOW_HEIGHT - 1 || j == 0 || j == WINDOW_WIDTH - 1) {
                    printf("\033[47;30m#\033[0m"); // White background, black foreground for walls
                } else {
                    printf("%c", grid[i][j]);
                }
            }
        }
        printf("\n");
    }
}

void clearScreen() {
    // ANSI escape code to clear screen and move cursor to top-left
    printf("\033[H\033[J");
}

// --- Terminal non-blocking input setup ---
static struct termios old_tio, new_tio;

void save_terminal_settings() {
    tcgetattr(STDIN_FILENO, &old_tio); // Save current terminal settings
}

void restore_terminal_settings() {
    tcsetattr(STDIN_FILENO, TCSANOW, &old_tio); // Restore saved settings
}

void set_non_blocking_input() {
    tcgetattr(STDIN_FILENO, &new_tio);
    new_tio.c_lflag &= (~ICANON & ~ECHO); // Disable canonical mode (line buffering) and echo
    tcsetattr(STDIN_FILENO, TCSANOW, &new_tio);

    // Set stdin to non-blocking
    int flags = fcntl(STDIN_FILENO, F_GETFL, 0);
    fcntl(STDIN_FILENO, F_SETFL, flags | O_NONBLOCK);
}

void set_blocking_input() {
    // Restore blocking input (and other flags from old_tio)
    tcsetattr(STDIN_FILENO, TCSANOW, &old_tio);
    // Restore blocking (remove O_NONBLOCK)
    int flags = fcntl(STDIN_FILENO, F_GETFL, 0);
    fcntl(STDIN_FILENO, F_SETFL, flags & ~O_NONBLOCK);
}

int kbhit() {
    struct timeval tv = {0L, 0L};
    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(STDIN_FILENO, &fds);
    return select(STDIN_FILENO + 1, &fds, NULL, NULL, &tv);
}

// 2D Physics Engine: Circles with Gravity & Collisions
#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Constants
#define N_BALLS 5
#define TIMESTEP 0.016f     // ~60 FPS
#define GRAVITY 200.0f      // pixels per sec^2
#define BOUNCE 0.8f         // wall bounce loss factor

#define WIDTH  800
#define HEIGHT 600

typedef struct {
    float x, y;     // Position
    float vx, vy;   // Velocity
    float r;        // Radius
    float m;        // Mass
} Ball;

// Utility: Clamp value
float clamp(float v, float lo, float hi) {
    return v < lo ? lo : (v > hi ? hi : v);
}

// Update Ball Physics
void update_ball(Ball* b, float dt) {
    b->vy += GRAVITY * dt;     // Gravity
    b->x  += b->vx * dt;
    b->y  += b->vy * dt;
}

// Handle boundary collisions (top, left, right, floor)
void handle_wall(Ball* b) {
    if(b->x - b->r < 0) {
        b->x = b->r;
        b->vx = -b->vx * BOUNCE;
    }
    if(b->x + b->r > WIDTH) {
        b->x = WIDTH - b->r;
        b->vx = -b->vx * BOUNCE;
    }
    if(b->y - b->r < 0) {
        b->y = b->r;
        b->vy = -b->vy * BOUNCE;
    }
    if(b->y + b->r > HEIGHT) {
        b->y = HEIGHT - b->r;
        b->vy = -b->vy * BOUNCE;
    }
}

// Elastic collision response between 2 balls
void handle_ball_collision(Ball* a, Ball* b) {
    float dx = b->x - a->x;
    float dy = b->y - a->y;
    float dist = sqrtf(dx*dx + dy*dy);
    float min_dist = a->r + b->r;
    if(dist < min_dist && dist > 0.0f) {
        // Overlap
        float overlap = 0.5f * (min_dist - dist);

        // Push balls apart along their connecting axis
        float nx = dx / dist;
        float ny = dy / dist;
        a->x -= overlap * nx;
        a->y -= overlap * ny;
        b->x += overlap * nx;
        b->y += overlap * ny;

        // Elastic velocity exchange along axis
        float dvx = b->vx - a->vx;
        float dvy = b->vy - a->vy;

        float dot = dvx*nx + dvy*ny;
        if(dot < 0) {
            float m1 = a->m, m2 = b->m;
            float total_mass = m1 + m2;
            float factor = (2.f*dot) / total_mass;
            a->vx += factor * m2 * nx;
            a->vy += factor * m2 * ny;
            b->vx -= factor * m1 * nx;
            b->vy -= factor * m1 * ny;
        }
    }
}

int main(void) {
    // Seed random
    srand((unsigned int)time(NULL));
    Ball balls[N_BALLS];

    // Init balls
    for(int i=0;i<N_BALLS;i++) {
        balls[i].r  = 30 + rand()%20;
        balls[i].m  = 3.14f * balls[i].r * balls[i].r;    // mass~area
        balls[i].x  = balls[i].r + rand() % (WIDTH-2*(int)balls[i].r);
        balls[i].y  = balls[i].r + rand() % (HEIGHT/2);
        balls[i].vx = -100 + rand()%200;
        balls[i].vy = -50 + rand()%100;
    }

    for(int frame = 0; frame < 600; frame++) {
        // 1. Physics, gravity, move
        for(int i=0; i<N_BALLS; i++)
            update_ball(&balls[i], TIMESTEP);

        // 2. Ball-ball collisions
        for(int i=0;i<N_BALLS;i++)
        for(int j=i+1;j<N_BALLS;j++)
            handle_ball_collision(&balls[i], &balls[j]);

        // 3. Walls
        for(int i=0;i<N_BALLS;i++)
            handle_wall(&balls[i]);

        // 4. Output
        printf("Frame %d\n", frame);
        for(int i=0;i<N_BALLS;i++)
            printf("  Ball %d: (%.1f, %.1f) v=(%.1f, %.1f)\n",
                   i, balls[i].x, balls[i].y, balls[i].vx, balls[i].vy);

        // Simulate 60fps
        #ifdef _WIN32
            Sleep(16);
        #else
            usleep(16000);
        #endif
    }

    return 0;
}

#include <stdio.h>
#include <math.h>

#define NUM_OBJECTS 2
#define GRAVITY 9.8
#define TIMESTEP 0.01
#define MAX_STEPS 1000
#define WIDTH 100.0
#define HEIGHT 100.0

typedef struct {
    double x;
    double y;
} Vector2D;

typedef struct {
    Vector2D position;
    Vector2D velocity;
    double radius;
} Object2D;

void apply_gravity(Object2D *obj) {
    obj->velocity.y -= GRAVITY * TIMESTEP;
}

void update_position(Object2D *obj) {
    obj->position.x += obj->velocity.x * TIMESTEP;
    obj->position.y += obj->velocity.y * TIMESTEP;

    // Reflect off the walls (simple boundary collision)
    if (obj->position.x < 0 || obj->position.x > WIDTH) {
        obj->velocity.x = -obj->velocity.x;
        obj->position.x = fmax(0, fmin(WIDTH, obj->position.x));
    }
    if (obj->position.y < 0 || obj->position.y > HEIGHT) {
        obj->velocity.y = -obj->velocity.y;
        obj->position.y = fmax(0, fmin(HEIGHT, obj->position.y));
    }
}

int detect_collision(Object2D *obj1, Object2D *obj2) {
    double dx = obj1->position.x - obj2->position.x;
    double dy = obj1->position.y - obj2->position.y;
    double distance = sqrt(dx*dx + dy*dy);
    return distance < (obj1->radius + obj2->radius);
}

void resolve_collision(Object2D *obj1, Object2D *obj2) {
    // Simplified elastic collision response
    Vector2D normal = { 
        obj2->position.x - obj1->position.x, 
        obj2->position.y - obj1->position.y
    };
    double distance = sqrt(normal.x * normal.x + normal.y * normal.y);

    if (distance == 0.0) return;

    // Normalize the normal vector
    normal.x /= distance;
    normal.y /= distance;

    double relativeVelocityX = obj2->velocity.x - obj1->velocity.x;
    double relativeVelocityY = obj2->velocity.y - obj1->velocity.y;

    double dot = relativeVelocityX * normal.x + relativeVelocityY * normal.y;

    if (dot > 0) return; // Objects are separating

    // Coefficient of restitution for the perfect elastic collision is 1
    double coefficient_of_restitution = 1.0;
    double impulse = -(1 + coefficient_of_restitution) * dot;

    // Adjust velocities based on impulse
    obj1->velocity.x += impulse * normal.x;
    obj1->velocity.y += impulse * normal.y;
    obj2->velocity.x -= impulse * normal.x;
    obj2->velocity.y -= impulse * normal.y;
}

int main() {
    Object2D objects[NUM_OBJECTS] = {
        {{10.0, 90.0}, {2.0, -3.0}, 5.0},
        {{50.0, 50.0}, {-1.0, 0.0}, 5.0}
    };

    for (int step = 0; step < MAX_STEPS; ++step) {
        // Apply gravity and update positions
        for (int i = 0; i < NUM_OBJECTS; ++i) {
            apply_gravity(&objects[i]);
            update_position(&objects[i]);
        }

        // Detect and resolve collisions
        for (int i = 0; i < NUM_OBJECTS; ++i) {
            for (int j = i + 1; j < NUM_OBJECTS; ++j) {
                if (detect_collision(&objects[i], &objects[j])) {
                    resolve_collision(&objects[i], &objects[j]);
                }
            }
        }

        // Print positions of objects
        printf("Step %d:\n", step);
        for (int i = 0; i < NUM_OBJECTS; ++i) {
            printf("Object %d Position: (%lf, %lf)\n", i, objects[i].position.x, objects[i].position.y);
        }
    }

    return 0;
}

