#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

// Structure to represent a 2D object
typedef struct {
    double x, y;      // position
    double vx, vy;    // velocity
    double radius;   // radius of the object
    double mass;     // mass of the object
} Object;

// Function to initialize a new object
Object* create_object(double x, double y, double vx, double vy, double radius, double mass) {
    Object* obj = (Object*)malloc(sizeof(Object));
    obj->x = x;
    obj->y = y;
    obj->vx = vx;
    obj->vy = vy;
    obj->radius = radius;
    obj->mass = mass;
    return obj;
}

// Function to update the position and velocity of an object based on gravity
void update_object(Object* obj, double dt, double gravity) {
    obj->vy += gravity * dt;
    obj->x += obj->vx * dt;
    obj->y += obj->vy * dt;
}

// Function to check for collision between two objects
int check_collision(Object* obj1, Object* obj2) {
    double dx = obj2->x - obj1->x;
    double dy = obj2->y - obj1->y;
    double distance = sqrt(dx * dx + dy * dy);
    if (distance <= obj1->radius + obj2->radius) {
        return 1;
    }
    return 0;
}

// Function to handle collision between two objects
void handle_collision(Object* obj1, Object* obj2) {
    // Simple elastic collision
    double temp_vx = obj1->vx;
    double temp_vy = obj1->vy;
    obj1->vx = obj2->vx;
    obj1->vy = obj2->vy;
    obj2->vx = temp_vx;
    obj2->vy = temp_vy;
}

// Function to simulate the physics engine
void simulate_physics_engine(Object** objects, int num_objects, double dt, double gravity, int num_steps) {
    for (int step = 0; step < num_steps; step++) {
        for (int i = 0; i < num_objects; i++) {
            update_object(objects[i], dt, gravity);
            // Check for collision with ground (y = 0)
            if (objects[i]->y - objects[i]->radius < 0) {
                objects[i]->y = objects[i]->radius;
                objects[i]->vy = -objects[i]->vy * 0.9; // simulate energy loss
            }
            for (int j = i + 1; j < num_objects; j++) {
                if (check_collision(objects[i], objects[j])) {
                    handle_collision(objects[i], objects[j]);
                }
            }
        }
        // Print current state
        printf("Step %d:\n", step);
        for (int i = 0; i < num_objects; i++) {
            printf("Object %d: (%f, %f) - (%f, %f)\n", i, objects[i]->x, objects[i]->y, objects[i]->vx, objects[i]->vy);
        }
        printf("\n");
    }
}

int main() {
    // Create objects
    Object* obj1 = create_object(0.0, 10.0, 2.0, 0.0, 1.0, 1.0);
    Object* obj2 = create_object(10.0, 10.0, -2.0, 0.0, 1.0, 1.0);

    // Set simulation parameters
    double dt = 0.01; // time step
    double gravity = -9.8; // gravity
    int num_steps = 100; // number of simulation steps

    // Create an array of objects
    Object* objects[] = {obj1, obj2};
    int num_objects = sizeof(objects) / sizeof(objects[0]);

    // Simulate physics engine
    simulate_physics_engine(objects, num_objects, dt, gravity, num_steps);

    // Free objects
    free(obj1);
    free(obj2);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define NUM_OBJECTS 2
#define GRAVITY 0.1
#define TIME_STEP 0.1

typedef struct {
    float x, y;
    float vx, vy;
    float width, height;
} Object;

// Function prototypes
void applyGravity(Object *obj);
void moveObject(Object *obj);
void resolveCollisions(Object *obj1, Object *obj2);
void printObject(const Object *obj);

int main() {
    Object objects[NUM_OBJECTS] = {
        {10, 10, 0, 0, 5, 5},
        {20, 20, 0, 0, 5, 5}
    };

    while (1) {
        // Apply gravity to each object
        for (int i = 0; i < NUM_OBJECTS; i++) {
            applyGravity(&objects[i]);
        }

        // Move each object
        for (int i = 0; i < NUM_OBJECTS; i++) {
            moveObject(&objects[i]);
        }

        // Resolve collisions between objects
        for (int i = 0; i < NUM_OBJECTS; i++) {
            for (int j = i + 1; j < NUM_OBJECTS; j++) {
                resolveCollisions(&objects[i], &objects[j]);
            }
        }

        // Print the positions of the objects
        for (int i = 0; i < NUM_OBJECTS; i++) {
            printObject(&objects[i]);
        }

        // Sleep for a short duration to slow down the loop
        sleep(1);

        // Clear the screen (for Unix-based systems)
        system("clear");
    }

    return 0;
}

void applyGravity(Object *obj) {
    obj->vy += GRAVITY * TIME_STEP;
}

void moveObject(Object *obj) {
    obj->x += obj->vx * TIME_STEP;
    obj->y += obj->vy * TIME_STEP;
}

void resolveCollisions(Object *obj1, Object *obj2) {
    float xDist = obj1->x - obj2->x;
    float yDist = obj1->y - obj2->y;
    float xOverlap = obj1->width / 2 + obj2->width / 2 - fabs(xDist);
    float yOverlap = obj1->height / 2 + obj2->height / 2 - fabs(yDist);

    if (xOverlap > 0 && yOverlap > 0) {
        if (xOverlap < yOverlap) {
            // Horizontal collision
            if (xDist > 0) {
                obj1->x += xOverlap;
                obj2->x -= xOverlap;
                obj1->vx = 0;
                obj2->vx = 0;
            } else {
                obj1->x -= xOverlap;
                obj2->x += xOverlap;
                obj1->vx = 0;
                obj2->vx = 0;
            }
        } else {
            // Vertical collision
            if (yDist > 0) {
                obj1->y += yOverlap;
                obj2->y -= yOverlap;
                obj1->vy = 0;
                obj2->vy = 0;
            } else {
                obj1->y -= yOverlap;
                obj2->y += yOverlap;
                obj1->vy = 0;
                obj2->vy = 0;
            }
        }
    }
}

void printObject(const Object *obj) {
    printf("Object at (%.2f, %.2f) with velocity (%.2f, %.2f)\n", obj->x, obj->y, obj->vx, obj->vy);
}

