#include <stdio.h> // Required for printf

// Function to swap two integers using pointers
void swap(int *ptr1, int *ptr2) {
    // Explanation of the swapping logic:
    // 1. A temporary variable `temp` is declared to hold one of the values
    //    while the other is being overwritten.
    // 2. The value pointed to by `ptr1` is stored in `temp`.
    //    (*ptr1 means "the value at the memory address stored in ptr1")
    // 3. The value pointed to by `ptr2` is assigned to the memory location
    //    pointed to by `ptr1`. Now, both original locations (ptr1 and ptr2)
    //    effectively hold the original value of ptr2.
    // 4. The value stored in `temp` (which was the original value of ptr1)
    //    is assigned to the memory location pointed to by `ptr2`.
    //    This completes the swap.
    int temp = *ptr1;
    *ptr1 = *ptr2;
    *ptr2 = temp;
}

int main() {
    int num1 = 10;
    int num2 = 20;

    printf("Before swap:\n");
    printf("num1 = %d\n", num1);
    printf("num2 = %d\n", num2);

    // Call the swap function, passing the addresses of num1 and num2
    // The & operator gets the memory address of the variable.
    swap(&num1, &num2);

    printf("\nAfter swap:\n");
    printf("num1 = %d\n", num1);
    printf("num2 = %d\n", num2);

    // Another example
    int a = 5;
    int b = 7;

    printf("\nBefore swap (a, b):\n");
    printf("a = %d\n", a);
    printf("b = %d\n", b);

    swap(&a, &b);

    printf("\nAfter swap (a, b):\n");
    printf("a = %d\n", a);
    printf("b = %d\n", b);

    return 0; // Indicate successful program execution
}

