#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <string.h>

#define SHARED_MEMORY_NAME "/my_shared_memory"
#define SHARED_MEMORY_SIZE 1024

// Structure to be shared between processes
typedef struct {
    int counter;
    char message[256];
} SharedData;

int main() {
    // Create shared memory file descriptor
    int fd = shm_open(SHARED_MEMORY_NAME, O_CREAT | O_RDWR, 0666);
    if (fd == -1) {
        perror("shm_open failed");
        exit(1);
    }

    // Set the size of the shared memory region
    if (ftruncate(fd, SHARED_MEMORY_SIZE) == -1) {
        perror("ftruncate failed");
        exit(1);
    }

    // Map the shared memory
    SharedData *shared_data = mmap(NULL, SHARED_MEMORY_SIZE, 
                                   PROT_READ | PROT_WRITE, 
                                   MAP_SHARED, fd, 0);

    if (shared_data == MAP_FAILED) {
        perror("mmap failed");
        exit(1);
    }

    // Fork a child process
    pid_t pid = fork();

    if (pid < 0) {
        // Fork failed
        perror("fork failed");
        exit(1);
    }
    else if (pid == 0) {
        // Child process
        printf("Child process started\n");

        // Initialize shared memory
        shared_data->counter = 0;
        strcpy(shared_data->message, "Hello from child!");

        // Increment counter
        for (int i = 0; i < 5; i++) {
            shared_data->counter++;
            printf("Child: Counter = %d\n", shared_data->counter);
            sleep(1);
        }

        exit(0);
    }
    else {
        // Parent process
        printf("Parent process started\n");

        // Wait for child to initialize
        sleep(2);

        // Read shared memory
        printf("Parent reading shared memory:\n");
        printf("Message: %s\n", shared_data->message);
        printf("Counter: %d\n", shared_data->counter);

        // Increment counter in parent
        for (int i = 0; i < 5; i++) {
            shared_data->counter++;
            printf("Parent: Counter = %d\n", shared_data->counter);
            sleep(1);
        }

        // Wait for child to finish
        wait(NULL);

        // Clean up
        munmap(shared_data, SHARED_MEMORY_SIZE);
        close(fd);
        shm_unlink(SHARED_MEMORY_NAME);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>

#define SHM_SIZE 1024  // Size of the shared memory segment

int main() {
    const char *name = "/my_shm";  // Name of the shared memory object
    const char *message = "Hello, shared memory!";

    // Create the shared memory object
    int shm_fd = shm_open(name, O_CREAT | O_RDWR, 0666);
    if (shm_fd == -1) {
        perror("shm_open");
        exit(EXIT_FAILURE);
    }

    // Configure the size of the shared memory object
    if (ftruncate(shm_fd, SHM_SIZE) == -1) {
        perror("ftruncate");
        exit(EXIT_FAILURE);
    }

    // Map the shared memory object into the address space of the process
    void *ptr = mmap(0, SHM_SIZE, PROT_WRITE, MAP_SHARED, shm_fd, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    // Write a message to the shared memory
    sprintf(ptr, "%s", message);

    // Wait for the child process to read the message
    printf("Parent: Message written to shared memory. Waiting for child to read...\n");
    sleep(2);

    // Unmap the shared memory object
    if (munmap(ptr, SHM_SIZE) == -1) {
        perror("munmap");
        exit(EXIT_FAILURE);
    }

    // Close the shared memory object
    if (close(shm_fd) == -1) {
        perror("close");
        exit(EXIT_FAILURE);
    }

    // Optionally, unlink the shared memory object
    if (shm_unlink(name) == -1) {
        perror("shm_unlink");
        exit(EXIT_FAILURE);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/wait.h> // For wait()

#define SHM_SIZE sizeof(int) // Size of the shared memory region (to hold one integer)

int main() {
    int *shared_data; // Pointer to the shared memory region
    pid_t pid;

    // 1. Create a shared memory mapping
    // MAP_ANONYMOUS: Not backed by any file. Suitable for parent-child IPC.
    // MAP_SHARED: Changes are visible to other processes using this mapping.
    // PROT_READ | PROT_WRITE: Read and write permissions.
    shared_data = mmap(NULL, SHM_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);

    if (shared_data == MAP_FAILED) {
        perror("mmap failed");
        return 1;
    }

    printf("Shared memory mapped at address: %p\n", (void *)shared_data);

    // 2. Initialize the shared data (only the parent does this initially)
    *shared_data = 0;
    printf("Parent: Initial value of shared_data = %d\n", *shared_data);

    // 3. Fork a new process
    pid = fork();

    if (pid < 0) {
        perror("fork failed");
        // Clean up mmap before exiting on error
        if (munmap(shared_data, SHM_SIZE) == -1) {
            perror("munmap failed during error handling");
        }
        return 1;
    } else if (pid == 0) {
        // Child process
        printf("\nChild: I am the child process (PID %d).\n", getpid());
        printf("Child: Reading shared_data before modification: %d\n", *shared_data);

        // Modify the shared data
        (*shared_data)++;
        printf("Child: Modified shared_data to: %d\n", *shared_data);

        // Attempt to write something else to demonstrate shared access
        sleep(1); // Give parent a chance to read before child exits
        *shared_data = 100;
        printf("Child: Final value set to %d. Child exiting.\n", *shared_data);

        // Child process exits
        // munmap is not strictly necessary for the child as memory is inherited
        // but it's good practice to cleanup if the child had a much longer lifespan
        if (munmap(shared_data, SHM_SIZE) == -1) {
            perror("child munmap failed");
            exit(1);
        }
        exit(0);

    } else {
        // Parent process
        printf("Parent: I am the parent process (PID %d).\n", getpid());
        printf("Parent: Forked child with PID %d.\n", pid);

        // Wait for the child to finish
        printf("Parent: Waiting for child to finish...\n");
        wait(NULL); // Wait for any child process to terminate

        // Read the modified shared data after child's termination
        printf("\nParent: Child has terminated.\n");
        printf("Parent: Reading shared_data after child's modification: %d\n", *shared_data);

        if (*shared_data == 100) {
            printf("Parent: Successfully observed child's changes in shared memory!\n");
        } else {
            printf("Parent: Shared memory did not reflect child's changes as expected. Value: %d\n", *shared_data);
        }

        // 4. Unmap the shared memory region (only the parent needs to do this for itself)
        if (munmap(shared_data, SHM_SIZE) == -1) {
            perror("parent munmap failed");
            return 1;
        }
        printf("Parent: Shared memory unmapped. Parent exiting.\n");
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include <string.h>

#define SHARED_MEM_SIZE 4096

int main() {
    // 1. Create shared memory region
    void *shm_addr = mmap(NULL, SHARED_MEM_SIZE,
                          PROT_READ | PROT_WRITE,
                          MAP_SHARED | MAP_ANONYMOUS, -1, 0);

    if (shm_addr == MAP_FAILED) {
        perror("mmap");
        exit(1);
    }

    printf("Shared memory address: %p\n", shm_addr);

    pid_t pid = fork();

    if (pid < 0) {
        perror("fork");
        munmap(shm_addr, SHARED_MEM_SIZE);
        exit(1);
    }

    if (pid == 0) {
        // Child process
        sleep(1); // Ensure parent runs first

        printf("Child: Reading from shared memory...\n");
        printf("Child: Message from parent: \"%s\"\n", (char *)shm_addr);

        // Write a response
        strcpy((char *)shm_addr, "Hello from child!");

        exit(0);
    } else {
        // Parent process
        strcpy((char *)shm_addr, "Hello from parent!");

        printf("Parent: Wrote message to shared memory, waiting for child...\n");

        wait(NULL); // Wait for child to finish

        printf("Parent: Child wrote: \"%s\"\n", (char *)shm_addr);

        munmap(shm_addr, SHARED_MEM_SIZE);
        return 0;
    }
}

