#define MEMORY_NAME "/my_shared_memory"
#define MEMORY_SIZE 1024

int main() {
    int shm_fd;
    void *ptr;

    // Create a shared memory object
    shm_fd = shm_open(MEMORY_NAME, O_CREAT | O_RDWR, 0666);
    if (shm_fd == -1) {
        perror("shm_open");
        exit(1);
    }

    // Configure the size of the shared memory
    if (ftruncate(shm_fd, MEMORY_SIZE) == -1) {
        perror("ftruncate");
        exit(1);
    }

    // Memory map the shared memory
    ptr = mmap(0, MEMORY_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, shm_fd, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        exit(1);
    }

    pid_t pid = fork();

    if (pid < 0) {
        perror("fork");
        exit(1);
    } else if (pid == 0) {
        // Child process: Read from shared memory
        sleep(1); // Sleep to ensure parent writes first
        printf("Child process reading from shared memory: %s\n", (char *)ptr);
    } else {
        // Parent process: Write to shared memory
        char *message = "Hello from parent!";
        snprintf((char *)ptr, MEMORY_SIZE, "%s", message);
        printf("Parent process wrote to shared memory: %s\n", message);

        // Wait for child to finish
        wait(NULL);

        // Clean up
        if (munmap(ptr, MEMORY_SIZE) == -1) {
            perror("munmap");
        }

        if (shm_unlink(MEMORY_NAME) == -1) {
            perror("shm_unlink");
        }
    }

    return 0;
}

