#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <sys/stat.h>        /* For mode constants */
#include <fcntl.h>           /* For O_* constants */
#include <unistd.h>
#include <string.h>
#include <sys/wait.h>

// Define the size of the shared memory region
#define SHARED_MEM_SIZE 1024

int main() {
    // Create a shared memory region
    int fd = shm_open("shared_mem", O_RDWR | O_CREAT, 0666);
    if (fd == -1) {
        perror("shm_open");
        exit(EXIT_FAILURE);
    }

    // Set the size of the shared memory region
    if (ftruncate(fd, SHARED_MEM_SIZE) == -1) {
        perror("ftruncate");
        exit(EXIT_FAILURE);
    }

    // Map the shared memory region into the parent's address space
    void* ptr = mmap(NULL, SHARED_MEM_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    // Write a message to the shared memory region
    strcpy(ptr, "Hello, child process!");

    // Create a child process
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) {
        // Child process

        // Map the shared memory region into the child's address space
        void* child_ptr = mmap(NULL, SHARED_MEM_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
        if (child_ptr == MAP_FAILED) {
            perror("mmap");
            exit(EXIT_FAILURE);
        }

        // Read the message from the shared memory region
        printf("Child process: %s\n", child_ptr);

        // Unmap the shared memory region from the child's address space
        if (munmap(child_ptr, SHARED_MEM_SIZE) == -1) {
            perror("munmap");
            exit(EXIT_FAILURE);
        }

        // Close the file descriptor
        close(fd);

        exit(EXIT_SUCCESS);
    }

    // Wait for the child process to finish
    wait(NULL);

    // Unmap the shared memory region from the parent's address space
    if (munmap(ptr, SHARED_MEM_SIZE) == -1) {
        perror("munmap");
        exit(EXIT_FAILURE);
    }

    // Close the file descriptor
    close(fd);

    // Remove the shared memory region
    if (shm_unlink("shared_mem") == -1) {
        perror("shm_unlink");
        exit(EXIT_FAILURE);
    }

    return 0;
}

