}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_SIZE 20
#define DELAY_MS 500000  // 500 milliseconds

// Color definitions for console output
#define RED     "\x1b[31m"
#define GREEN   "\x1b[32m"
#define YELLOW  "\x1b[33m"
#define BLUE    "\x1b[34m"
#define RESET   "\x1b[0m"

// Function prototypes
void printArray(int arr[], int size, int highlighted1, int highlighted2);
void bubbleSort(int arr[], int size);
void insertionSort(int arr[], int size);
void selectionSort(int arr[], int size);
void swap(int *a, int *b);
void clearScreen();

// Visualization function to display array state
void printArray(int arr[], int size, int highlighted1, int highlighted2) {
    for (int i = 0; i < size; i++) {
        if (i == highlighted1 || i == highlighted2) {
            printf(RED "[%d] " RESET, arr[i]);
        } else {
            printf("%d ", arr[i]);
        }
    }
    printf("\n");
    usleep(DELAY_MS);  // Delay to visualize steps
}

// Bubble Sort with step-by-step visualization
void bubbleSort(int arr[], int size) {
    printf(BLUE "Bubble Sort Visualization:\n" RESET);

    for (int i = 0; i < size - 1; i++) {
        for (int j = 0; j < size - i - 1; j++) {
            clearScreen();
            printf(YELLOW "Pass %d, Comparing %d and %d\n" RESET, i + 1, arr[j], arr[j + 1]);
            printArray(arr, size, j, j + 1);

            if (arr[j] > arr[j + 1]) {
                swap(&arr[j], &arr[j + 1]);

                clearScreen();
                printf(GREEN "Swapping %d and %d\n" RESET, arr[j], arr[j + 1]);
                printArray(arr, size, j, j + 1);
            }
        }
    }
}

// Insertion Sort with step-by-step visualization
void insertionSort(int arr[], int size) {
    printf(BLUE "Insertion Sort Visualization:\n" RESET);

    for (int i = 1; i < size; i++) {
        int key = arr[i];
        int j = i - 1;

        clearScreen();
        printf(YELLOW "Inserting %d\n" RESET, key);
        printArray(arr, size, i, -1);

        while (j >= 0 && arr[j] > key) {
            arr[j + 1] = arr[j];
            j--;

            clearScreen();
            printf(GREEN "Shifting elements\n" RESET);
            printArray(arr, size, j + 1, -1);
        }

        arr[j + 1] = key;
    }
}

// Selection Sort with step-by-step visualization
void selectionSort(int arr[], int size) {
    printf(BLUE "Selection Sort Visualization:\n" RESET);

    for (int i = 0; i < size - 1; i++) {
        int min_idx = i;

        for (int j = i + 1; j < size; j++) {
            clearScreen();
            printf(YELLOW "Finding minimum in unsorted portion\n" RESET);
            printArray(arr, size, min_idx, j);

            if (arr[j] < arr[min_idx]) {
                min_idx = j;
            }
        }

        if (min_idx != i) {
            swap(&arr[i], &arr[min_idx]);

            clearScreen();
            printf(GREEN "Swapping minimum element\n" RESET);
            printArray(arr, size, i, min_idx);
        }
    }
}

// Utility function to swap two elements
void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

// Function to clear console screen
void clearScreen() {
    #ifdef _WIN32
        system("cls");
    #else
        system("clear");
    #endif
}

int main() {
    int arr[MAX_SIZE];
    int size;

    // Input array from user
    printf("Enter the number of elements (max %d): ", MAX_SIZE);
    scanf("%d", &size);

    printf("Enter %d elements:\n", size);
    for (int i = 0; i < size; i++) {
        scanf("%d", &arr[i]);
    }

    // Original array
    printf("\nOriginal Array: ");
    printArray(arr, size, -1, -1);

    // Choose sorting algorithm
    int choice;
    printf("\nChoose Sorting Algorithm:\n");
    printf("1. Bubble Sort\n");
    printf("2. Insertion Sort\n");
    printf("3. Selection Sort\n");
    printf("Enter your choice: ");
    scanf("%d", &choice);

    // Create a copy of the original array
    int sorted_arr[MAX_SIZE];
    memcpy(sorted_arr, arr, sizeof(arr));

    // Perform sorting based on user choice
    switch(choice) {
        case 1:
            bubbleSort(sorted_arr, size);
            break;
        case 2:
            insertionSort(sorted_arr, size);
            break;
        case 3:
            selectionSort(sorted_arr, size);
            break;
        default:
            printf("Invalid choice!\n");
            return 1;
    }

    // Final sorted array
    printf(GREEN "\nSorted Array: " RESET);
    printArray(sorted_arr, size, -1, -1);

    return 0;
}

#include <stdio.h>
#include <stdbool.h>

// Function to print the array
void printArray(int arr[], int size) {
    for (int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

// Function to perform Bubble Sort and visualize each step
void bubbleSort(int arr[], int size) {
    bool swapped;
    for (int i = 0; i < size - 1; i++) {
        swapped = false;
        for (int j = 0; j < size - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                // Swap arr[j] and arr[j+1]
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
                swapped = true;
            }
            // Print the array after each step
            printf("Step %d: ", i * (size - 1) + j + 1);
            printArray(arr, size);
        }
        // If no two elements were swapped by inner loop, the array is sorted
        if (!swapped) {
            break;
        }
    }
}

int main() {
    int arr[] = {64, 34, 25, 12, 22, 11, 90};
    int size = sizeof(arr) / sizeof(arr[0]);

    printf("Original array: ");
    printArray(arr, size);

    printf("\nSorting process:\n");
    bubbleSort(arr, size);

    printf("\nSorted array: ");
    printArray(arr, size);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#ifdef _WIN32
#include <windows.h> // For Sleep on Windows
#define CLEAR_SCREEN system("cls")
#else
#include <unistd.h> // For usleep on Linux/macOS
#define CLEAR_SCREEN system("clear")
#endif

// --- Configuration ---
#define ARRAY_SIZE 30     // Number of elements in the array
#define MAX_VALUE ARRAY_SIZE // Max value for elements (makes bars scale nicely)
#define DELAY_MICROSECONDS 100000 // Delay between steps in microseconds (0.1 seconds)
#define BAR_CHAR '#'      // Character to draw array bars
#define EMPTY_SPACE ' '   // Character for empty space in bars
#define HIGHLIGHT_CHAR '*' // Character for highlighted elements

// --- Function Prototypes ---
void initialize_array(int arr[], int size);
void print_array(const int arr[], int size);
void draw_array(const int arr[], int size, int highlight1, int highlight2, int green_success);
void swap(int *a, int *b);
void bubble_sort(int arr[], int size);
void selection_sort(int arr[], int size);
void copy_array(const int source[], int destination[], int size);
void show_final_result(const int arr[], int size, const char *algo_name);

// --- Main Function ---
int main() {
    int arr[ARRAY_SIZE];
    int original_arr[ARRAY_SIZE]; // Store original array for reuse

    srand(time(NULL)); // Seed random number generator

    int choice;
    do {
        initialize_array(original_arr, ARRAY_SIZE); // Initialize original array
        copy_array(original_arr, arr, ARRAY_SIZE);  // Copy to working array

        printf("\n--- Sorting Algorithm Visualizer --- \n");
        printf("Current Array Size: %d\n", ARRAY_SIZE);
        printf("Delay per step: %.2f seconds\n", (float)DELAY_MICROSECONDS / 1000000.0);
        printf("\nSelect an algorithm:\n");
        printf("1. Bubble Sort\n");
        printf("2. Selection Sort\n");
        printf("3. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                CLEAR_SCREEN;
                printf("--- Bubble Sort Visualization ---\n");
                printf("Initial Array:\n");
                draw_array(arr, ARRAY_SIZE, -1, -1, 0); // -1 for no highlight
#ifdef _WIN32
                Sleep(2000); // Wait 2 seconds
#else
                usleep(2000000); // Wait 2 seconds
#endif
                bubble_sort(arr, ARRAY_SIZE);
                show_final_result(arr, ARRAY_SIZE, "Bubble Sort");
                break;
            case 2:
                CLEAR_SCREEN;
                printf("--- Selection Sort Visualization ---\n");
                printf("Initial Array:\n");
                draw_array(arr, ARRAY_SIZE, -1, -1, 0); // -1 for no highlight
#ifdef _WIN32
                Sleep(2000); // Wait 2 seconds
#else
                usleep(2000000); // Wait 2 seconds
#endif
                selection_sort(arr, ARRAY_SIZE);
                show_final_result(arr, ARRAY_SIZE, "Selection Sort");
                break;
            case 3:
                printf("Exiting...\n");
                break;
            default:
                printf("Invalid choice. Please try again.\n");
        }
        printf("\nPress Enter to continue...");
        // Clear input buffer (for the extra Enter keypress)
        while (getchar() != '\n'); // Consume newline left by scanf
        getchar(); // Wait for user to press Enter
    } while (choice != 3);

    return 0;
}

// --- Utility Functions ---

// Initializes the array with random distinct values
void initialize_array(int arr[], int size) {
    for (int i = 0; i < size; ++i) {
        arr[i] = i + 1; // Populate with sequential values
    }

    // Shuffle the array (Fisher-Yates shuffle)
    for (int i = size - 1; i > 0; --i) {
        int j = rand() % (i + 1);
        swap(&arr[i], &arr[j]);
    }
}

// Prints the array (for debug, not visualization)
void print_array(const int arr[], int size) {
    for (int i = 0; i < size; ++i) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

// Draws the array as bars in the console
// highlight1, highlight2: indices to highlight (or -1 for no highlight)
// green_success: if 1, draw the whole array in a "sorted/success" color (e.g., green if supported)
void draw_array(const int arr[], int size, int highlight1, int highlight2, int green_success) {
    CLEAR_SCREEN; // Clear console for next frame

    // Print top border for visual neatness
    printf("+");
    for (int i = 0; i < size; ++i) {
        printf("---");
    }
    printf("+\n");

    for (int h = MAX_VALUE; h >= 1; --h) { // Iterate from max height down to 1
        printf("|");
        for (int i = 0; i < size; ++i) {
            if (arr[i] >= h) {
                if (green_success) {
                    // ANSI escape code for green text
                    printf("\033[32m%c\033[0m  ", BAR_CHAR); // Green bar, then reset color
                } else if (i == highlight1 || i == highlight2) {
                    // ANSI escape code for red text (highlight)
                    printf("\033[31m%c\033[0m  ", HIGHLIGHT_CHAR); // Red highlight, then reset color
                } else {
                    printf("%c  ", BAR_CHAR); // Default bar
                }
            } else {
                printf("%c  ", EMPTY_SPACE); // Empty space
            }
        }
        printf("|\n");
    }

    // Print values at the bottom (optional, can be noisy for large arrays)
    printf("+");
    for (int i = 0; i < size; ++i) {
        printf("---");
    }
    printf("+\n");

    printf("|");
    for (int i = 0; i < size; ++i) {
        if (i == highlight1 || i == highlight2) {
            printf("%*d ", 2, arr[i]); // Print value right-aligned in 2 chars
        } else {
            printf("%*d ", 2, arr[i]); // Print value right-aligned in 2 chars
        }
    }
    printf("|\n");

    printf("+");
    for (int i = 0; i < size; ++i) {
        printf("---");
    }
    printf("+\n");

    // Add a delay for visualization
#ifdef _WIN32
    Sleep(DELAY_MICROSECONDS / 1000); // Sleep takes milliseconds
#else
    usleep(DELAY_MICROSECONDS); // usleep takes microseconds
#endif
}


