// --- Sorting Algorithms with Visualization ---

void bubble_sort(int arr[], int size) {
    int i, j;
    int swapped;
    for (i = 0; i < size - 1; i++) {
        swapped = 0;
        for (j = 0; j < size - i - 1; j++) {
            // Draw before comparison
            draw_array(arr, size, j, j + 1, 0);

            if (arr[j] > arr[j + 1]) {
                swap(&arr[j], &arr[j + 1]);
                swapped = 1;

                // Draw after swap
                draw_array(arr, size, j, j + 1, 0);
            }
        }
        // If no two elements were swapped by inner loop, then break
        if (swapped == 0)
            break;
    }
}

void selection_sort(int arr[], int size) {
    int i, j, min_idx;
    for (i = 0; i < size - 1; i++) {
        min_idx = i;
        // Draw the current position of `i` (considered sorted)
        draw_array(arr, size, i, min_idx, 0);
        for (j = i + 1; j < size; j++) {
            // Draw current elements being compared/scanned
            draw_array(arr, size, j, min_idx, 0);
            if (arr[j] < arr[min_idx]) {
                min_idx = j;
            }
        }
        // Swap the found minimum element with the first element of unsorted part
        if (min_idx != i) {
            swap(&arr[i], &arr[min_idx]);
            // Draw after swap
        }
        draw_array(arr, size, i, min_idx, 0); // Show elements after processing this pass
    }
}

