#define MAX_COMMAND_LENGTH 1024
#define MAX_ARGS 64

// Function to split command into tokens
int tokenize_command(char *command, char *tokens[]) {
    int token_count = 0;
    char *token = strtok(command, " \t\n");

    while (token != NULL && token_count < MAX_ARGS - 1) {
        tokens[token_count++] = token;
        token = strtok(NULL, " \t\n");
    }
    tokens[token_count] = NULL;

    return token_count;
}

// Implementation of cd command
void change_directory(char *path) {
    if (path == NULL) {
        // If no path specified, go to home directory
        path = getenv("HOME");
    }

    if (chdir(path) != 0) {
        perror("cd");
    }
}

// Implementation of ls command
void list_directory() {
    DIR *dir;
    struct dirent *entry;

    dir = opendir(".");
    if (dir == NULL) {
        perror("ls");
        return;
    }

    // Read and print directory entries
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_name[0] != '.') {  // Exclude hidden files
            printf("%s\n", entry->d_name);
        }
    }

    closedir(dir);
}

// Execute external commands
void execute_command(char *tokens[]) {
    pid_t pid = fork();

    if (pid < 0) {
        perror("fork");
        exit(1);
    } else if (pid == 0) {
        // Child process
        if (execvp(tokens[0], tokens) == -1) {
            perror("command");
            exit(1);
        }
    } else {
        // Parent process
        wait(NULL);
    }
}

int main() {
    char command[MAX_COMMAND_LENGTH];
    char *tokens[MAX_ARGS];
    int token_count;

    while (1) {
        // Print prompt
        printf("myshell> ");

        // Read command
        if (fgets(command, sizeof(command), stdin) == NULL) {
            break;
        }

        // Remove newline character
        command[strcspn(command, "\n")] = 0;

        // Skip empty commands
        if (strlen(command) == 0) {
            continue;
        }

        // Tokenize command
        token_count = tokenize_command(command, tokens);

        // Handle built-in commands
        if (strcmp(tokens[0], "cd") == 0) {
            change_directory(tokens[1]);
        } else if (strcmp(tokens[0], "ls") == 0) {
            list_directory();
        } else if (strcmp(tokens[0], "exit") == 0) {
            break;
        } else {
            // Execute external commands
            execute_command(tokens);
        }
    }

    return 0;
}

