    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h> // For chdir() and execvp()
#include <sys/wait.h> // For waitpid()
#include <dirent.h> // For opendir(), readdir(), closedir()

#define MAX_COMMAND_LENGTH 1024
#define MAX_ARGS 64
#define DELIM " \t\n"

// Function to handle the 'cd' command
void handle_cd(char **args) {
    if (args[1] == NULL) {
        // If no argument, change to home directory (or default to root)
        char *home_dir = getenv("HOME");
        if (home_dir == NULL) {
            fprintf(stderr, "cd: no home directory found, defaulting to /\n");
            home_dir = "/"; // Fallback to root
        }
        if (chdir(home_dir) != 0) {
            perror("cd");
        }
    } else {
        if (chdir(args[1]) != 0) {
            perror("cd");
        }
    }
}

// Function to handle the 'ls' command
void handle_ls(char **args) {
    DIR *d;
    struct dirent *dir;
    const char *path = "."; // Default to current directory

    if (args[1] != NULL) {
        path = args[1]; // If an argument is provided, use it as the path
    }

    d = opendir(path);
    if (d) {
        while ((dir = readdir(d)) != NULL) {
            // Exclude '.' and '..' for cleaner output
            if (strcmp(dir->d_name, ".") != 0 && strcmp(dir->d_name, "..") != 0) {
                printf("%s\n", dir->d_name);
            }
        }
        closedir(d);
    } else {
        perror("ls");
    }
}

// Function to parse the input command into arguments
char **parse_command(char *line) {
    char **args = (char **)malloc(MAX_ARGS * sizeof(char *));
    if (args == NULL) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    char *token;
    int i = 0;

    token = strtok(line, DELIM);
    while (token != NULL && i < MAX_ARGS - 1) {
        args[i] = token;
        i++;
        token = strtok(NULL, DELIM);
    }
    args[i] = NULL; // Null-terminate the array of arguments
    return args;
}

// Function to execute external commands
void execute_external_command(char **args) {
    pid_t pid, wpid;
    int status;

    pid = fork();
    if (pid == -1) {
        // Forking failed
        perror("fork failed");
        exit(EXIT_FAILURE);
    } else if (pid == 0) {
        // Child process
        if (execvp(args[0], args) == -1) {
            perror("Error executing command");
            exit(EXIT_FAILURE); // Exit child process if execvp fails
        }
    } else {
        // Parent process
        do {
            wpid = waitpid(pid, &status, WUNTRACED);
        } while (!WIFEXITED(status) && !WIFSIGNALED(status));
    }
}

int main() {
    char line[MAX_COMMAND_LENGTH];
    char cwd[MAX_COMMAND_LENGTH];
    char **args;
    int status = 1; // Keep the shell running

    while (status) {
        // Get current working directory
        if (getcwd(cwd, sizeof(cwd)) != NULL) {
            printf("\033[1;34m%s\033[0m$ ", cwd); // Blue color for prompt
        } else {
            perror("getcwd");
            printf("$ ");
        }

        // Read command from stdin
        if (fgets(line, sizeof(line), stdin) == NULL) {
            // Handle EOF (Ctrl+D)
            printf("\nExiting shell.\n");
            break;
        }

        // Remove trailing newline character
        line[strcspn(line, "\n")] = 0;

        // Skip empty lines
        if (strlen(line) == 0) {
            continue;
        }

        args = parse_command(line);

        if (args[0] == NULL) {
            // No command entered
            free(args);
            continue;
        }

        if (strcmp(args[0], "exit") == 0) {
            status = 0; // Set status to 0 to exit the loop
        } else if (strcmp(args[0], "cd") == 0) {
            handle_cd(args);
        } else if (strcmp(args[0], "ls") == 0) {
            handle_ls(args);
        } else {
            // Treat as an external command
            execute_external_command(args);
        }

        free(args);
    }

    return 0;
}

