    struct dirent *dir;
    char cwd[1024];
    if (getcwd(cwd, sizeof(cwd)) == NULL) {
        perror("getcwd");
        return;
    }
    d = opendir(cwd);
    if (d == NULL) {
        perror("ls");
        return;
    }
    while ((dir = readdir(d)) != NULL) {
        // Skip . and ..
        if (strcmp(dir->d_name, ".") && strcmp(dir->d_name, ".."))
            printf("%s  ", dir->d_name);
    }
