            strcpy(cwd, "?");
        }
        printf("%s$ ", cwd);
        if (fgets(line, sizeof(line), stdin) == NULL) {
            printf("\n");
            break;
        }

        trim_newline(line);

        // Tokenize input
        int argc = 0;
        char *token = strtok(line, " ");
        while (token != NULL && argc < 63) {
            args[argc++] = token;
            token = strtok(NULL, " ");
        }
        args[argc] = NULL;
        if (argc == 0) continue;

        // Built-in commands
        if (strcmp(args[0], "exit") == 0) {
            break;
        } else if (strcmp(args[0], "cd") == 0) {
            shell_cd(args[1]);
        } else if (strcmp(args[0], "ls") == 0) {
