#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>

#define MAX_LINE 1024
#define MAX_ARGS 64
#define DELIM " \t\r\n\a"

void execute_command(char **args);
char *read_line(void);
char **split_line(char *line);
void shell_loop(void);

int main(int argc, char **argv) {
    // Run the main loop of the shell
    shell_loop();

    return EXIT_SUCCESS;
}

void shell_loop(void) {
    char *line;
    char **args;
    int status = 1;

    do {
        printf("myshell> ");
        line = read_line();
        args = split_line(line);
        execute_command(args);

        free(line);
        free(args);
    } while (status);
}

char *read_line(void) {
    char *line = NULL;
    ssize_t bufsize = 0;  // getline will allocate a buffer for us
    getline(&line, &bufsize, stdin);
    return line;
}

char **split_line(char *line) {
    int bufsize = MAX_ARGS, position = 0;
    char **tokens = malloc(bufsize * sizeof(char*));
    char *token;

    if (!tokens) {
        fprintf(stderr, "myshell: allocation error\n");
        exit(EXIT_FAILURE);
    }

    token = strtok(line, DELIM);
    while (token != NULL) {
        tokens[position] = token;
        position++;

        if (position >= bufsize) {
            bufsize += MAX_ARGS;
            tokens = realloc(tokens, bufsize * sizeof(char*));
            if (!tokens) {
                fprintf(stderr, "myshell: allocation error\n");
                exit(EXIT_FAILURE);
            }
        }

        token = strtok(NULL, DELIM);
    }
    tokens[position] = NULL;
    return tokens;
}

void execute_command(char **args) {
    if (args[0] == NULL) {
        // No command entered
        return;
    }

    if (strcmp(args[0], "exit") == 0) {
        exit(EXIT_SUCCESS);
    } else if (strcmp(args[0], "cd") == 0) {
        if (args[1] == NULL) {
            fprintf(stderr, "myshell: expected argument to \"cd\"\n");
        } else {
            if (chdir(args[1]) != 0) {
                perror("myshell");
            }
        }
    } else {
        pid_t pid, wpid;
        int status;

        pid = fork();
        if (pid == 0) {
            // Child process
            if (execvp(args[0], args) == -1) {
                perror("myshell");
            }
            exit(EXIT_FAILURE);
        } else if (pid < 0) {
            // Error forking
            perror("myshell");
        } else {
            // Parent process
            do {
                wpid = waitpid(pid, &status, WUNTRACED);
            } while (!WIFEXITED(status) && !WIFSIGNALED(status));
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>

#define MAX_BUFFER 1024
#define MAX_ARGS 100

void execute_command(char **args) {
    pid_t pid = fork();

    if (pid < 0) {
        perror("Fork failed");
        exit(EXIT_FAILURE);
    } else if (pid == 0) { // Child process
        if (execvp(args[0], args) == -1) {
            perror("Execution failed");
        }
        exit(EXIT_FAILURE); // Exit the child process if exec fails
    } else { // Parent process
        wait(NULL); // Wait for the child process to finish
    }
}

void change_directory(char *path) {
    if (chdir(path) != 0) {
        perror("cd error");
    }
}

void parse_input(char *input, char **args) {
    char *token = strtok(input, " \n");
    int index = 0;

    while (token != NULL) {
        args[index++] = token;
        token = strtok(NULL, " \n");
    }
    args[index] = NULL; // NULL-terminate the array
}

int main() {
    char input[MAX_BUFFER];
    char *args[MAX_ARGS];

    while (1) {
        printf("my_shell> ");
        if (fgets(input, MAX_BUFFER, stdin) == NULL) {
            // Handle EOF or read error
            printf("\n");
            break;
        }

        parse_input(input, args);

        if (args[0] == NULL) {
            continue; // Empty command
        }

        if (strcmp(args[0], "exit") == 0) {
            break;
        } else if (strcmp(args[0], "cd") == 0) {
            if (args[1] == NULL) {
                fprintf(stderr, "cd: missing argument\n");
            } else {
                change_directory(args[1]);
            }
        } else {
            // Execute the command
            execute_command(args);
        }
    }

    return 0;
}

