#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <dirent.h>

#define MAX_COMMAND_LENGTH 1024
#define MAX_ARGUMENTS 64

void print_prompt() {
    printf("simple_shell> ");
}

void handle_cd(char *args[]) {
    if (args[1] == NULL) {
        fprintf(stderr, "cd: expected argument\n");
        return;
    }
    if (chdir(args[1]) != 0) {
        perror("cd");
    }
}

void handle_ls(char *args[]) {
    DIR *dir;
    struct dirent *entry;
    dir = opendir(".");
    if (dir == NULL) {
        perror("ls");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        printf("%s\n", entry->d_name);
    }

    closedir(dir);
}

void handle_exit() {
    exit(0);
}

int main() {
    char command[MAX_COMMAND_LENGTH];
    char *args[MAX_ARGUMENTS];
    int status;

    while (1) {
        print_prompt();
        fgets(command, MAX_COMMAND_LENGTH, stdin);

        // Remove trailing newline character
        command[strcspn(command, "\n")] = '\0';

        // Parse the input command
        args[0] = strtok(command, " ");
        int i = 1;
        while (i < MAX_ARGUMENTS - 1 && (args[i] = strtok(NULL, " ")) != NULL) {
            i++;
        }
        args[i] = NULL;

        // Handle built-in commands
        if (args[0] == NULL) {
            continue;
        } else if (strcmp(args[0], "cd") == 0) {
            handle_cd(args);
        } else if (strcmp(args[0], "ls") == 0) {
            handle_ls(args);
        } else if (strcmp(args[0], "exit") == 0) {
            handle_exit();
        } else {
            // Fork and execute other commands
            pid_t pid = fork();

            if (pid < 0) {
                perror("fork");
                continue;
            } else if (pid == 0) {
                // Child process
                if (execvp(args[0], args) < 0) {
                    perror("exec");
                    exit(1);
                }
            } else {
                // Parent process
                waitpid(pid, &status, 0);
                if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
                    fprintf(stderr, "Command '%s' failed with status %d\n", args[0], WEXITSTATUS(status));
                }
            }
        }
    }

    return 0;
}

#include <stdio.h>
#include <math.h>

// Function to calculate roots of quadratic equation
void calculateQuadraticRoots(double a, double b, double c) {
    // Variable to store discriminant
    double discriminant;

    // Check if a is zero (not a quadratic equation)
    if (a == 0) {
        printf("Error: Not a quadratic equation. 'a' cannot be zero.\n");
        return;
    }

    // Calculate discriminant
    discriminant = (b * b) - (4 * a * c);

    // Check discriminant value to determine roots
    if (discriminant > 0) {
        // Real and distinct roots
        double root1 = (-b + sqrt(discriminant)) / (2 * a);
        double root2 = (-b - sqrt(discriminant)) / (2 * a);

        printf("Roots are real and distinct:\n");
        printf("Root 1 = %.2f\n", root1);
        printf("Root 2 = %.2f\n", root2);
    }
    else if (discriminant == 0) {
        // Real and equal roots
        double root = -b / (2 * a);

        printf("Roots are real and equal:\n");
        printf("Root = %.2f\n", root);
    }
    else {
        // Complex roots
        double realPart = -b / (2 * a);
        double imaginaryPart = sqrt(-discriminant) / (2 * a);

        printf("Roots are complex and conjugate:\n");
        printf("Root 1 = %.2f + %.2fi\n", realPart, imaginaryPart);
        printf("Root 2 = %.2f - %.2fi\n", realPart, imaginaryPart);
    }
}

