#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 21
#define BUFFER_SIZE 1024
#define MAX_CONNECTIONS 5

// Function to send HTTP response
void send_response(int client_socket, const char* status, const char* content_type, const char* body) {
    char response[BUFFER_SIZE];

    // Construct HTTP response
    snprintf(response, sizeof(response), 
        "HTTP/1.1 %s\r\n"
        "Content-Type: %s\r\n"
        "Content-Length: %zu\r\n"
        "\r\n"
        "%s", 
        status, content_type, strlen(body), body);

    // Send response to client
    write(client_socket, response, strlen(response));
}

// Function to handle client request
void handle_request(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    // Read client request
    bytes_read = read(client_socket, buffer, sizeof(buffer) - 1);
    if (bytes_read < 0) {
        perror("Error reading request");
        return;
    }

    buffer[bytes_read] = '\0';

    // Simple request parsing
    if (strstr(buffer, "GET /") != NULL) {
        // Send a simple HTML response
        const char* response_body = 
            "<html>"
            "<head><title>Mini HTTP Server</title></head>"
            "<body>"
            "<h1>Welcome to Mini HTTP Server</h1>"
            "<p>This is a simple HTTP server implemented in C</p>"
            "</body>"
            "</html>";

        send_response(client_socket, "200 OK", "text/html", response_body);
    } else {
        // Send 404 Not Found
        const char* error_body = 
            "<html>"
            "<head><title>404 Not Found</title></head>"
            "<body>"
            "<h1>404 Not Found</h1>"
            "<p>The requested resource could not be found</p>"
            "</body>"
            "</html>";

        send_response(client_socket, "404 Not Found", "text/html", error_body);
    }

    // Close client socket
    close(client_socket);
}

int main() {
    int server_socket, client_socket;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_addr_len;

    // Create server socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("Error creating socket");
        exit(1);
    }

    // Set socket options to reuse address
    int opt = 1;
    if (setsockopt(server_socket, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt)) < 0) {
        perror("Error setting socket options");
        exit(1);
    }

    // Configure server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error binding socket");
        exit(1);
    }

    // Listen for connections
    if (listen(server_socket, MAX_CONNECTIONS) < 0) {
        perror("Error listening");
        exit(1);
    }

    printf("Server listening on port %d...\n", PORT);

    // Server main loop
    while (1) {
        // Accept client connection
        client_addr_len = sizeof(client_addr);
        client_socket = accept(server_socket, (struct sockaddr*)&client_addr, &client_addr_len);

        if (client_socket < 0) {
            perror("Error accepting connection");
            continue;
        }

        printf("Client connected: %s\n", inet_ntoa(client_addr.sin_addr));

        // Handle client request
        handle_request(client_socket);
    }

    // Close server socket
    close(server_socket);

    return 0;
}

