#define PORT 21         // THE PORT YOU WANT TO USE. BE CAREFUL WITH 21 (FTP).
                        // Consider 8080 or 8000 for general HTTP testing.
#define BUFFER_SIZE 4096
#define MAX_CONNECTIONS 5

// Function to handle a client request
void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;

    // Read the client's request
    bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Error receiving data");
        close(client_socket);
        return;
    }
    buffer[bytes_received] = '\0'; // Null-terminate the received data
    printf("Received request:\n%s\n", buffer);

    // --- Very basic HTTP request parsing ---
    // We're just checking if it starts with "GET"
    if (strncmp(buffer, "GET", 3) != 0) {
        // Not a GET request, send 400 Bad Request
        const char *bad_request_response =
            "HTTP/1.1 400 Bad Request\r\n"
            "Content-Type: text/plain\r\n"
            "Content-Length: 17\r\n"
            "\r\n"
            "Bad Request Only";
        send(client_socket, bad_request_response, strlen(bad_request_response), 0);
    } else {
        // --- Prepare the HTTP response ---
        const char *http_header =
            "HTTP/1.1 200 OK\r\n"
            "Content-Type: text/html\r\n"
            "Connection: close\r\n"; // Tell the browser we'll close the connection
        const char *html_content =
            "<!DOCTYPE html>\n"
            "<html>\n"
            "<head><title>Mini HTTP Server</title></head>\n"
            "<body>\n"
            "    <h1>Welcome to My Mini HTTP Server!</h1>\n"
            "    <p>This is a simple server written in C.</p>\n"
            "    <p>You requested path: <b>"; // We'll try to extract the path

        char path_buffer[256];
        char *first_space = strchr(buffer, ' '); // Find first space after "GET"
        if (first_space) {
            char *second_space = strchr(first_space + 1, ' '); // Find second space
            if (second_space) {
                int path_len = second_space - (first_space + 1);
                if (path_len < sizeof(path_buffer) - 1) {
                    strncpy(path_buffer, first_space + 1, path_len);
                    path_buffer[path_len] = '\0';
                } else {
                    strcpy(path_buffer, "/path-too-long");
                }
            } else {
                strcpy(path_buffer, "/malformed-request");
            }
        } else {
            strcpy(path_buffer, "/unknown");
        }

        char *html_content_end = 
            "</b></p>\n"
            "    <p>Current Port: " // Add the port number
            "</body>\n"
            "</html>\n";

        char port_str[10];
        snprintf(port_str, sizeof(port_str), "%d", PORT);

        // Combine parts for the full HTML response
        char full_html_response[BUFFER_SIZE * 2]; // Make it larger if needed
        snprintf(full_html_response, sizeof(full_html_response),
                 "%s%s%s%s%s%s",
                 html_content, path_buffer, html_content_end, port_str, "</p>", "");

        // Calculate Content-Length
        size_t content_length = strlen(full_html_response);
        char content_length_header[50];
        snprintf(content_length_header, sizeof(content_length_header), "Content-Length: %zu\r\n\r\n", content_length);

        // Send the header first
        send(client_socket, http_header, strlen(http_header), 0);
        send(client_socket, content_length_header, strlen(content_length_header), 0);
        // Send the HTML content
        send(client_socket, full_html_response, strlen(full_html_response), 0);
    }

    // Close the client socket
    close(client_socket);
    printf("Client disconnected.\n\n");
}

int main() {
    int server_socket, client_socket;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_addr_len = sizeof(client_addr);

    printf("Starting Mini HTTP Server on port %d...\n", PORT);

    // 1. Create socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("Error creating socket");
        exit(EXIT_FAILURE);
    }

    // Optional: Allow immediate reuse of port (useful for development)
    int optval = 1;
    if (setsockopt(server_socket, SOL_SOCKET, SO_REUSEADDR, &optval, sizeof(optval)) < 0) {
        perror("setsockopt failed");
        close(server_socket);
        exit(EXIT_FAILURE);
    }


    // 2. Configure server address
    memset(&server_addr, 0, sizeof(server_addr)); // Clear structure
    server_addr.sin_family = AF_INET;             // IPv4
    server_addr.sin_addr.s_addr = INADDR_ANY;     // Listen on all available network interfaces
    server_addr.sin_port = htons(PORT);           // Convert port number to network byte order

    // 3. Bind socket to address and port
    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error binding socket");
        fprintf(stderr, "Error code: %d\n", errno);
        if (errno == EACCES) {
            fprintf(stderr, "Permission denied. For ports below 1024 (like %d), you might need root privileges (e.g., 'sudo').\n", PORT);
        } else if (errno == EADDRINUSE) {
            fprintf(stderr, "Address already in use. Another program might be using port %d.\n", PORT);
        }
        close(server_socket);
        exit(EXIT_FAILURE);
    }

    // 4. Listen for incoming connections
    if (listen(server_socket, MAX_CONNECTIONS) < 0) {
        perror("Error listening on socket");
        close(server_socket);
        exit(EXIT_FAILURE);
    }

    printf("Server listening on http://127.0.0.1:%d\n", PORT);
    printf("Press Ctrl+C to stop.\n\n");

    // Main loop to accept and handle client connections
    while (1) {
        printf("Waiting for a connection...\n");
        // 5. Accept a client connection
        client_socket = accept(server_socket, (struct sockaddr *)&client_addr, &client_addr_len);
        if (client_socket < 0) {
            perror("Error accepting connection");
            continue; // Try to accept the next one
        }

        // Print client information
        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        printf("Connection accepted from %s:%d\n", client_ip, ntohs(client_addr.sin_port));

        // Handle the client request
        handle_client(client_socket);
        // Note: This server is sequential. To handle multiple clients concurrently,
        // you would typically use threads (pthreads) or fork() processes.
    }

    // 6. Close the server socket (unreachable in this infinite loop, but good practice)
    close(server_socket);
    printf("Server stopped.\n");

    return 0;
}

