        perror("bind failed (Try running as root for port 21)");
        exit(EXIT_FAILURE);
    }

    // 3. Listen
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        exit(EXIT_FAILURE);
    }

    printf("Mini HTTP server listening on port %d...\n", PORT);

    while (1) {
        // 4. Accept connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address,
                                (socklen_t*)&addrlen)) < 0) {
            perror("accept failed");
            continue;
        }
        // 5. Read HTTP request (simple, up to 1023 bytes)
        int valread = read(new_socket, buffer, 1023);
        buffer[valread] = '\0';

        // Optional: print request
        printf("Received request:\n%s\n", buffer);

        // 6. Send HTTP response
        send(new_socket, RESPONSE, strlen(RESPONSE), 0);

        // 7. Close connection
        close(new_socket);
    }

    return 0;
}

