#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <openssl/ssl.h>
#include <openssl/err.h>

#define PORT 443
#define BUFFER_SIZE 4096
#define MAX_CONNECTIONS 10

// Function prototypes
void handle_error(const char* message);
SSL_CTX* create_ssl_context();
void configure_ssl_context(SSL_CTX* ctx);
void load_certificates(SSL_CTX* ctx, const char* cert_file, const char* key_file);

int main() {
    int server_socket, client_socket;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_addr_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE];

    // Initialize OpenSSL
    SSL_library_init();
    SSL_load_error_strings();
    OpenSSL_add_all_algorithms();

    // Create SSL context
    SSL_CTX* ssl_context = create_ssl_context();

    // Load certificates
    load_certificates(ssl_context, "server.crt", "server.key");

    // Create server socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        handle_error("Socket creation failed");
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    // Bind socket
    if (bind(server_socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        handle_error("Binding failed");
    }

    // Listen for connections
    if (listen(server_socket, MAX_CONNECTIONS) < 0) {
        handle_error("Listening failed");
    }

    printf("HTTPS Server listening on port %d...\n", PORT);

    while (1) {
        // Accept client connection
        client_socket = accept(server_socket, 
                               (struct sockaddr*)&client_addr, 
                               &client_addr_len);

        if (client_socket < 0) {
            perror("Accept failed");
            continue;
        }

        // Create SSL connection
        SSL* ssl = SSL_new(ssl_context);
        SSL_set_fd(ssl, client_socket);

        // SSL handshake
        if (SSL_accept(ssl) <= 0) {
            ERR_print_errors_fp(stderr);
            SSL_free(ssl);
            close(client_socket);
            continue;
        }

        // Read client request
        memset(buffer, 0, sizeof(buffer));
        int bytes_received = SSL_read(ssl, buffer, sizeof(buffer) - 1);

        if (bytes_received > 0) {
            printf("Received request:\n%s\n", buffer);

            // Prepare HTTP response
            const char* response = 
                "HTTP/1.1 200 OK\r\n"
                "Content-Type: text/html\r\n"
                "\r\n"
                "<html><body><h1>Welcome to Mini HTTPS Server</h1></body></html>";

            // Send response
            SSL_write(ssl, response, strlen(response));
        }

        // Clean up SSL connection
        SSL_shutdown(ssl);
        SSL_free(ssl);
        close(client_socket);
    }

    // Clean up
    SSL_CTX_free(ssl_context);
    close(server_socket);

    return 0;
}

void handle_error(const char* message) {
    perror(message);
    exit(1);
}

SSL_CTX* create_ssl_context() {
    const SSL_METHOD* method = TLS_server_method();
    SSL_CTX* ctx = SSL_CTX_new(method);

    if (!ctx) {
        handle_error("Unable to create SSL context");
    }

    return ctx;
}

void configure_ssl_context(SSL_CTX* ctx) {
    // Configure SSL context options
    SSL_CTX_set_options(ctx, SSL_OP_SINGLE_DH_USE);
}

void load_certificates(SSL_CTX* ctx, const char* cert_file, const char* key_file) {
    // Load server certificate
    if (SSL_CTX_use_certificate_file(ctx, cert_file, SSL_FILETYPE_PEM) <= 0) {
        ERR_print_errors_fp(stderr);
        exit(1);
    }

    // Load private key
    if (SSL_CTX_use_PrivateKey_file(ctx, key_file, SSL_FILETYPE_PEM) <= 0) {
        ERR_print_errors_fp(stderr);
        exit(1);
    }

    // Verify private key
    if (!SSL_CTX_check_private_key(ctx)) {
        fprintf(stderr, "Private key does not match the certificate\n");
        exit(1);
    }
}

#include <stdio.h>
