    SSL_CTX *ctx;

    method = TLS_server_method();
    ctx = SSL_CTX_new(method);
    if (!ctx) {
        perror("Unable to create SSL context");
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    return ctx;
}

void configure_context(SSL_CTX *ctx) {
    /* Set the key and cert */
    if (SSL_CTX_use_certificate_file(ctx, "cert.pem", SSL_FILETYPE_PEM) <= 0) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    if (SSL_CTX_use_PrivateKey_file(ctx, "key.pem", SSL_FILETYPE_PEM) <= 0) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }
}

void handle_client(SSL *ssl) {
    char buffer[BUFFER_SIZE] = {0};
    const char *response = "HTTP/1.1 200 OK\r\n"
                           "Content-Type: text/plain\r\n"
                           "Connection: close\r\n"
                           "\r\n"
                           "Hello from mini HTTPS server!\r\n";

    /* Read client request */
    SSL_read(ssl, buffer, BUFFER_SIZE);
    printf("Received:\n%s\n", buffer);

    /* Send response */
    SSL_write(ssl, response, strlen(response));
}

int main() {
    int server_fd, client_fd;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);

    /* Initialize OpenSSL */
    SSL_CTX *ctx;
    SSL_library_init();
    OpenSSL_add_all_algorithms();
    SSL_load_error_strings();
    ctx = create_context();
    configure_context(ctx);

    /* Create socket */
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    /* Set socket options */
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    /* Bind socket to port */
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    /* Listen for connections */
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d...\n", PORT);

    while (1) {
        SSL *ssl;

        /* Accept connection */
        if ((client_fd = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue;
        }

        printf("Connection accepted from %s:%d\n", 
               inet_ntoa(address.sin_addr), ntohs(address.sin_port));

        /* Create SSL connection */
        ssl = SSL_new(ctx);
        SSL_set_fd(ssl, client_fd);

        /* Handle SSL handshake */
        if (SSL_accept(ssl) <= 0) {
            ERR_print_errors_fp(stderr);
            close(client_fd);
            SSL_free(ssl);
            continue;
        }

        /* Handle client request */
        handle_client(ssl);

        /* Clean up */
        SSL_shutdown(ssl);
        SSL_free(ssl);
        close(client_fd);
    }

    /* Clean up */
    close(server_fd);
    SSL_CTX_free(ctx);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/stat.h> // For stat() to check file existence and size

#define PORT 8080 // Using a non-privileged port for testing. For port 443, see notes below.
#define BACKLOG 10
#define BUFFER_SIZE 8192 // Larger buffer for requests/responses
#define WEB_ROOT "./www" // Directory to serve files from

// Function to get MIME type based on file extension
const char* get_mime_type(const char* file_path) {
    const char* dot = strrchr(file_path, '.');
    if (!dot || dot == file_path) return "application/octet-stream";
    if (strcmp(dot, ".html") == 0 || strcmp(dot, ".htm") == 0) return "text/html";
    if (strcmp(dot, ".txt") == 0) return "text/plain";
    if (strcmp(dot, ".jpg") == 0 || strcmp(dot, ".jpeg") == 0) return "image/jpeg";
    if (strcmp(dot, ".png") == 0) return "image/png";
    if (strcmp(dot, ".gif") == 0) return "image/gif";
    if (strcmp(dot, ".css") == 0) return "text/css";
    if (strcmp(dot, ".js") == 0) return "application/javascript";
    // Add more MIME types as needed
    return "application/octet-stream";
}

void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;

    bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
    if (bytes_received < 0) {
        perror("recv failed");
        close(client_socket);
        return;
    }
    buffer[bytes_received] = '\0'; // Null-terminate the received data

    printf("Received request:\n%s\n", buffer);

    char method[16], path[256], http_version[16];
    // Parse the request line: GET /index.html HTTP/1.1
    sscanf(buffer, "%15s %255s %15s", method, path, http_version);

    printf("Method: %s, Path: %s, Version: %s\n", method, path, http_version);

    if (strcmp(method, "GET") != 0) {
        // Only GET is supported for this simple server
        char *response = "HTTP/1.1 501 Not Implemented\r\nContent-Length: 21\r\n\r\n501 Not Implemented\n";
        send(client_socket, response, strlen(response), 0);
        close(client_socket);
        return;
    }

    // Construct the full file path
    char full_path[BUFFER_SIZE];
    snprintf(full_path, sizeof(full_path), "%s%s", WEB_ROOT, path);

    // If path is just "/", serve index.html
    if (strcmp(path, "/") == 0) {
        snprintf(full_path, sizeof(full_path), "%s/index.html", WEB_ROOT);
    }

    // Basic security: Prevent directory traversal (e.g., trying to access ../)
    if (strstr(full_path, "..") != NULL) {
        char *response = "HTTP/1.1 403 Forbidden\r\nContent-Length: 10\r\n\r\nForbidden\n";
        send(client_socket, response, strlen(response), 0);
        close(client_socket);
        return;
    }

    FILE *file = fopen(full_path, "rb"); // Open in binary mode
    if (file == NULL) {
        // File not found or cannot be opened
        char *not_found_response = "HTTP/1.1 404 Not Found\r\nContent-Length: 14\r\n\r\n404 Not Found\n";
        send(client_socket, not_found_response, strlen(not_found_response), 0);
        close(client_socket);
        printf("File not found: %s\n", full_path);
        return;
    }

    // Get file size
    struct stat st;
    stat(full_path, &st);
    long file_size = st.st_size;

    const char* mime_type = get_mime_type(full_path);

    // Send HTTP headers
    char header[BUFFER_SIZE];
    snprintf(header, sizeof(header),
             "HTTP/1.1 200 OK\r\n"
             "Content-Type: %s\r\n"
             "Content-Length: %ld\r\n"
             "Connection: close\r\n" // For simple servers, close connection after each request
             "\r\n",
             mime_type, file_size);
    send(client_socket, header, strlen(header), 0);

    // Send file content
    size_t bytes_read;
    while ((bytes_read = fread(buffer, 1, BUFFER_SIZE, file)) > 0) {
        send(client_socket, buffer, bytes_read, 0);
    }

    fclose(file);
    close(client_socket);
    printf("Served file: %s (size: %ld bytes)\n", full_path, file_size);
}

int main() {
    int server_sock, client_sock;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len;

    // 1. Create socket
    server_sock = socket(AF_INET, SOCK_STREAM, 0);
    if (server_sock < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Optional: Allow reuse of address (helps with rapid restarts)
    int optval = 1;
    if (setsockopt(server_sock, SOL_SOCKET, SO_REUSEADDR, &optval, sizeof(optval)) < 0) {
        perror("setsockopt SO_REUSEADDR failed");
        close(server_sock);
        exit(EXIT_FAILURE);
    }

    // 2. Prepare the sockaddr_in structure
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY; // Listen on all network interfaces
    server_addr.sin_port = htons(PORT);     // Convert port number to network byte order

    // 3. Bind the socket to the port
    if (bind(server_sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Socket bind failed");
        close(server_sock);
        exit(EXIT_FAILURE);
    }

    // 4. Listen for incoming connections
    if (listen(server_sock, BACKLOG) < 0) {
        perror("Listen failed");
        close(server_sock);
        exit(EXIT_FAILURE);
    }

    printf("Mini HTTP server listening on port %d...\n", PORT);
    printf("Serving files from: %s\n", WEB_ROOT);
    printf("Access at: http://127.0.0.1:%d/\n", PORT);

    while (1) {
        client_len = sizeof(client_addr);
        // 5. Accept a connection
        client_sock = accept(server_sock, (struct sockaddr *)&client_addr, &client_len);
        if (client_sock < 0) {
            perror("Accept failed");
            continue; // Try again
        }

        char *client_ip = inet_ntoa(client_addr.sin_addr);
        int client_port = ntohs(client_addr.sin_port);
        printf("\nAccepted connection from %s:%d\n", client_ip, client_port);

        // Handle the client request
        handle_client(client_sock);
        printf("Connection from %s:%d closed.\n", client_ip, client_port);
    }

    close(server_sock); // This will technically never be reached in the infinite loop
    return 0;
}

