#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>

#define MAX_TEMP_FILES 10
#define MAX_PATH_LENGTH 256
#define TEMP_THRESHOLD 80.0  // Temperature threshold in Celsius

// Function to find temperature sensor files
int find_temp_files(char temp_files[][MAX_PATH_LENGTH]) {
    FILE *fp;
    char path[MAX_PATH_LENGTH];
    int count = 0;

    // Execute shell command to find temperature files
    fp = popen("find /sys/class/thermal -name 'temp*_input'", "r");
    if (fp == NULL) {
        perror("Error finding temperature files");
        return 0;
    }

    // Read and store temperature file paths
    while (fgets(path, sizeof(path), fp) != NULL && count < MAX_TEMP_FILES) {
        // Remove newline character
        path[strcspn(path, "\n")] = 0;
        strcpy(temp_files[count], path);
        count++;
    }

    pclose(fp);
    return count;
}

// Function to read temperature from a file
float read_temperature(const char *filepath) {
    FILE *file;
    float temperature;

    file = fopen(filepath, "r");
    if (file == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fscanf(file, "%f", &temperature) != 1) {
        perror("Error reading temperature");
        fclose(file);
        return -1;
    }

    fclose(file);
    // Convert millidegrees to degrees Celsius
    return temperature / 1000.0;
}

// Function to get CPU name
void get_cpu_name(char *cpu_name) {
    FILE *fp;
    char path[MAX_PATH_LENGTH];

    fp = popen("cat /proc/cpuinfo | grep 'model name' | uniq", "r");
    if (fp == NULL) {
        strcpy(cpu_name, "Unknown CPU");
        return;
    }

    if (fgets(path, sizeof(path), fp) != NULL) {
        // Extract CPU name after ':'
        char *name_start = strchr(path, ':');
        if (name_start) {
            strcpy(cpu_name, name_start + 2);
            // Remove newline
            cpu_name[strcspn(cpu_name, "\n")] = 0;
        } else {
            strcpy(cpu_name, "Unknown CPU");
        }
    }

    pclose(fp);
}

int main() {
    char temp_files[MAX_TEMP_FILES][MAX_PATH_LENGTH];
    char cpu_name[MAX_PATH_LENGTH];
    int num_sensors;

    // Get CPU name
    get_cpu_name(cpu_name);

    // Find temperature sensor files
    num_sensors = find_temp_files(temp_files);

    if (num_sensors == 0) {
        fprintf(stderr, "No temperature sensors found.\n");
        return 1;
    }

    printf("CPU: %s\n", cpu_name);
    printf("Number of temperature sensors: %d\n", num_sensors);

    // Continuous monitoring
    while (1) {
        printf("\n--- CPU Temperature ---\n");

        for (int i = 0; i < num_sensors; i++) {
            float temp = read_temperature(temp_files[i]);

            if (temp >= 0) {
                printf("Sensor %d: %.1f°C", i + 1, temp);

                // Add warning for high temperature
                if (temp > TEMP_THRESHOLD) {
                    printf(" [HIGH TEMPERATURE WARNING]");
                }
                printf("\n");
            }
        }

        // Wait for 2 seconds before next reading
        sleep(2);
    }

    return 0;
}

