#include <unistd.h> // For sleep
#include <dirent.h> // For directory listing

// --- Configuration ---
#define SLEEP_INTERVAL_SECONDS 5 // How often to check the temperature
#define MAX_SENSOR_PATH_LEN    256 // Maximum length for a sensor file path

// --- Function Prototypes ---
int find_cpu_temp_path(char *temp_path, size_t max_len);
int read_cpu_temperature(const char *temp_path);

int main() {
    char temp_sensor_path[MAX_SENSOR_PATH_LEN];
    int temperature;

    printf("--- CPU Temperature Monitor (Linux Only) ---\n");

    if (find_cpu_temp_path(temp_sensor_path, sizeof(temp_sensor_path)) == 0) {
        fprintf(stderr, "Error: Could not find a CPU temperature sensor path.\n");
        fprintf(stderr, "This program relies on sysfs (`/sys/class/hwmon/` and `_temp_input` files).\n");
        fprintf(stderr, "Ensure 'lm-sensors' is installed and configured ('sensors-detect' might be needed).\n");
        return 1;
    }

    printf("Found CPU temperature sensor at: %s\n", temp_sensor_path);

    while (1) {
        temperature = read_cpu_temperature(temp_sensor_path);

        if (temperature != -1) {
            // Temperature is usually in millidegrees Celsius
            printf("Current CPU Temperature: %.2f °C\n", (float)temperature / 1000.0);
        } else {
            fprintf(stderr, "Warning: Could not read temperature from %s. Skipping this check.\n", temp_sensor_path);
        }

        sleep(SLEEP_INTERVAL_SECONDS);
    }

    return 0;
}

/**
 * @brief Attempts to find the CPU temperature sensor path in sysfs.
 *
 * This function iterates through common hwmon directories to find a file
 * ending with "_temp_input" that likely represents the CPU temperature.
 * It prioritizes paths containing "coretemp" or "k10temp" (common CPU sensors).
 *
 * @param temp_path A buffer to store the found path.
 * @param max_len The maximum length of the buffer.
 * @return 0 if a path is found and copied, -1 otherwise.
 */
int find_cpu_temp_path(char *temp_path, size_t max_len) {
    const char *hwmon_base_path = "/sys/class/hwmon/";
    DIR *hwmon_dir;
    struct dirent *entry;
    char sub_dir_path[MAX_SENSOR_PATH_LEN];
    char full_path[MAX_SENSOR_PATH_LEN];
    FILE *label_file;
    char label_content[128]; // Buffer for label file content

    hwmon_dir = opendir(hwmon_base_path);
    if (hwmon_dir == NULL) {
        perror("Error opening /sys/class/hwmon/");
        return -1;
    }

    char preferred_path[MAX_SENSOR_PATH_LEN] = {0}; // To store a path with "coretemp" or "k10temp"

    while ((entry = readdir(hwmon_dir)) != NULL) {
        if (entry->d_type == DT_LNK || entry->d_type == DT_DIR) { // LNK for symlinks, DIR for actual directories
            if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
                continue;
            }

            snprintf(sub_dir_path, sizeof(sub_dir_path), "%s%s/", hwmon_base_path, entry->d_name);

            DIR *sub_dir = opendir(sub_dir_path);
            if (sub_dir == NULL) {
                // Not always an error, some might not be accessible or relevant
                continue;
            }

            struct dirent *sub_entry;
            while ((sub_entry = readdir(sub_dir)) != NULL) {
                // Look for files ending with _input (e.g., temp1_input)
                if (strstr(sub_entry->d_name, "_input") != NULL && strstr(sub_entry->d_name, "temp") == sub_entry->d_name) {
                    snprintf(full_path, sizeof(full_path), "%s%s", sub_dir_path, sub_entry->d_name);

                    // Try to read the corresponding _label file to identify it
                    char label_path[MAX_SENSOR_PATH_LEN];
                    snprintf(label_path, sizeof(label_path), "%s%s_label", sub_dir_path, sub_entry->d_name);
                    // Remove "_input" and add "_label"
                    char *input_suffix = strstr(label_path, "_input");
                    if (input_suffix) {
                         const char *label_suffix = "_label";
                         size_t label_suffix_len = strlen(label_suffix);
                         size_t base_len = input_suffix - label_path;
                         if (base_len + label_suffix_len < sizeof(label_path)) {
                             strcpy(input_suffix, label_suffix);
                             label_file = fopen(label_path, "r");
                             if (label_file) {
                                 if (fgets(label_content, sizeof(label_content), label_file) != NULL) {
                                     label_content[strcspn(label_content, "\n")] = 0; // Remove newline
                                     // Common CPU labels
                                     if (strstr(label_content, "Core") || strstr(label_content, "Package") ||
                                         strstr(label_content, "Tdie") || strstr(label_content, "Tctl")) {
                                         strncpy(temp_path, full_path, max_len - 1);
                                         temp_path[max_len - 1] = '\0';
                                         closedir(sub_dir);
                                         closedir(hwmon_dir);
                                         return 0; // Found a good candidate
                                     }
                                 }
                                 fclose(label_file);
                             }
                        }
                    }

                    // Fallback: If no specific label, prefer paths from "coretemp" or "k10temp" modules
                    // This is a heuristic.
                    if (strstr(full_path, "coretemp") || strstr(full_path, "k10temp")) {
                         // Found a more specific CPU sensor path
                         strncpy(preferred_path, full_path, max_len - 1);
                         preferred_path[max_len - 1] = '\0';
                    } else if (preferred_path[0] == '\0') {
                        // If no preferred path yet, take the first valid temp_input we find
                        strncpy(temp_path, full_path, max_len - 1);
                        temp_path[max_len - 1] = '\0';
                    }
                }
            }
            closedir(sub_dir);
        }
    }
    closedir(hwmon_dir);

    if (preferred_path[0] != '\0') {
        strncpy(temp_path, preferred_path, max_len - 1);
        temp_path[max_len - 1] = '\0';
        return 0; // Return preferred path
    } else if (temp_path[0] != '\0') {
        return 0; // Return any found path
    }

    return -1; // No suitable path found
}


/**
 * @brief Reads the CPU temperature from the specified sysfs file.
 *
 * The temperature is usually reported in millidegrees Celsius.
 *
 * @param temp_path The full path to the temperature sensor file (e.g., /sys/class/hwmon/hwmon0/temp1_input).
 * @return The temperature in millidegrees Celsius, or -1 on error.
 */
int read_cpu_temperature(const char *temp_path) {
    FILE *fp;
    int temperature = -1;

    fp = fopen(temp_path, "r");
    if (fp == NULL) {
        perror("Error opening temperature sensor file");
        return -1;
    }

    if (fscanf(fp, "%d", &temperature) != 1) {
        fprintf(stderr, "Error reading temperature from file: %s\n", temp_path);
        temperature = -1;
    }

    fclose(fp);
    return temperature;
}

#include <stdio.h>
#include <stdlib.h>
#include <dirent.h>
#include <string.h>
#include <unistd.h>

#define THERMAL_ZONE_PATH "/sys/class/thermal"
#define TEMP_FILE_NAME "temp"
#define TYPE_FILE_NAME "type"

void monitor_cpu_temperature() {
    DIR *dir;
    struct dirent *entry;
    char filepath[256];
    char tempstr[16];
    char typestr[32];

    dir = opendir(THERMAL_ZONE_PATH);
    if (dir == NULL) {
        perror("Failed to open thermal directory");
        exit(EXIT_FAILURE);
    }

    printf("Monitoring CPU temperatures (press Ctrl+C to stop)...\n");

    while (1) {
        rewinddir(dir);
        printf("\n--- CPU Temperature Sensors ---\n");
        while ((entry = readdir(dir)) != NULL) {
            if (strncmp(entry->d_name, "thermal_zone", 12) == 0) {
                // Read type to filter for CPU-related zones
                snprintf(filepath, sizeof(filepath), "%s/%s/%s", THERMAL_ZONE_PATH, entry->d_name, TYPE_FILE_NAME);
                FILE *typefile = fopen(filepath, "r");
                if (!typefile)
                    continue;
                if (fgets(typestr, sizeof(typestr), typefile) == NULL) {
                    fclose(typefile);
                    continue;
                }
                typestr[strcspn(typestr, "\n")] = '\0'; // remove newline
                fclose(typefile);

                // Filter for relevant types (often 'x86_pkg_temp', 'cpu', 'soc', 'coretemp', etc.)
                if (strstr(typestr, "cpu") == NULL && strstr(typestr, "pkg") == NULL &&
                    strstr(typestr, "core") == NULL && strstr(typestr, "soc") == NULL)
                    continue;

                snprintf(filepath, sizeof(filepath), "%s/%s/%s", THERMAL_ZONE_PATH, entry->d_name, TEMP_FILE_NAME);
                FILE *tempfile = fopen(filepath, "r");
                if (!tempfile)
                    continue;
                if (fgets(tempstr, sizeof(tempstr), tempfile) != NULL) {
                    int temp_millic = atoi(tempstr);
                    printf("%s (%s): %.1f°C\n", entry->d_name, typestr, temp_millic / 1000.0);
                }
