    uint16_t flags;
    uint16_t questions;
    uint16_t answers;
    uint16_t authority_rrs;
    uint16_t additional_rrs;
} DNSHeader;

// DNS Record Type Mapping
typedef enum {
    A_RECORD = 1,
    AAAA_RECORD = 28,
    CNAME_RECORD = 5,
    MX_RECORD = 15,
    NS_RECORD = 2,
    PTR_RECORD = 12,
    SOA_RECORD = 6
} DNSRecordType;

// Function to convert record type to string
const char* get_record_type_str(uint16_t type) {
    switch (type) {
        case A_RECORD: return "A";
        case AAAA_RECORD: return "AAAA";
        case CNAME_RECORD: return "CNAME";
        case MX_RECORD: return "MX";
        case NS_RECORD: return "NS";
        case PTR_RECORD: return "PTR";
        case SOA_RECORD: return "SOA";
        default: return "Unknown";
    }
}

// Function to parse DNS flags
void parse_dns_flags(uint16_t flags) {
    printf("DNS Flags: 0x%04X\n", flags);
    printf("  QR: %d\n", (flags >> 15) & 1);        // Query/Response
    printf("  Opcode: %d\n", (flags >> 11) & 0xF);  // Operation code
    printf("  AA: %d\n", (flags >> 10) & 1);        // Authoritative Answer
    printf("  TC: %d\n", (flags >> 9) & 1);         // Truncation
    printf("  RD: %d\n", (flags >> 8) & 1);         // Recursion Desired
    printf("  RA: %d\n", (flags >> 7) & 1);         // Recursion Available
    printf("  Z: %d\n", (flags >> 4) & 0x7);        // Reserved
    printf("  RCODE: %d\n", flags & 0xF);           // Response Code
}

// Function to parse DNS packet from CSV line
void parse_dns_packet(char* line) {
    char* token;
    DNSHeader header;

    // Transaction ID
    token = strtok(line, ",");
    header.transaction_id = (uint16_t)strtol(token, NULL, 16);

    // Flags
    token = strtok(NULL, ",");
    header.flags = (uint16_t)strtol(token, NULL, 16);

    // Questions
    token = strtok(NULL, ",");
    header.questions = (uint16_t)atoi(token);

    // Answers
    token = strtok(NULL, ",");
    header.answers = (uint16_t)atoi(token);

    // Authority RRs
    token = strtok(NULL, ",");
    header.authority_rrs = (uint16_t)atoi(token);

    // Additional RRs
    token = strtok(NULL, ",");
    header.additional_rrs = (uint16_t)atoi(token);

    // Record Type
    token = strtok(NULL, ",");
    uint16_t record_type = (uint16_t)atoi(token);

    // Domain Name
    token = strtok(NULL, ",");
    char* domain_name = token;

    // Print parsed information
    printf("DNS Packet Details:\n");
    printf("Transaction ID: 0x%04X\n", header.transaction_id);
    parse_dns_flags(header.flags);
    printf("Questions: %d\n", header.questions);
    printf("Answers: %d\n", header.answers);
    printf("Authority RRs: %d\n", header.authority_rrs);
    printf("Additional RRs: %d\n", header.additional_rrs);
    printf("Record Type: %s\n", get_record_type_str(record_type));
    printf("Domain Name: %s\n\n", domain_name);
}

