// DNS Header structure (RFC 1035)
struct DNS_HEADER {
    uint16_t id;        // identification number

    uint16_t rd     :1; // recursion desired
    uint16_t tc     :1; // truncated message
    uint16_t aa     :1; // authoritive answer
    uint16_t opcode :4; // purpose of message
    uint16_t qr     :1; // query/response flag

    uint16_t rcode  :4; // response code
    uint16_t cd     :1; // checking disabled
    uint16_t ad     :1; // authenticated data
    uint16_t z      :1; // reserved (must be zero)
    uint16_t ra     :1; // recursion available

    uint16_t qdcount;   // number of question entries
    uint16_t ancount;   // number of answer entries
    uint16_t nscount;   // number of authority entries
    uint16_t arcount;   // number of resource entries
};

// Constant sized fields of a DNS question
struct QUESTION {
    uint16_t qtype;
    uint16_t qclass;
};

// Constant sized fields of a DNS RDATA record (Answer, Authority, Additional)
// Note: RDATA length variable, this is just the fixed part
struct R_DATA {
    uint16_t type;
    uint16_t _class;
    uint32_t ttl;
    uint16_t data_len; // Length of RDATA field (variable)
};

// Structure for a parsed DNS question
struct ParsedQuestion {
    char *qname;
    uint16_t qtype;
    uint16_t qclass;
};

// Structure for a parsed DNS answer record
struct ParsedAnswer {
    char *name;
    uint16_t type;
