// Structure to represent a DNS packet
typedef struct {
    uint16_t id;
    uint16_t flags;
    uint16_t qdcount;
    uint16_t ancount;
    uint16_t nscount;
    uint16_t arcount;
    uint8_t qname[256];
    uint16_t qtype;
    uint16_t qclass;
} dns_packet;

// Function to parse a DNS packet from a CSV file
dns_packet* parse_dns_packet(char* packet_data, int packet_len) {
    dns_packet* packet = (dns_packet*)malloc(sizeof(dns_packet));
    if (packet == NULL) {
        return NULL;
    }

    // Parse the ID field (2 bytes)
    packet->id = ((uint16_t)packet_data[0] << 8) | packet_data[1];

    // Parse the flags field (2 bytes)
    packet->flags = ((uint16_t)packet_data[2] << 8) | packet_data[3];

    // Parse the QDCOUNT field (2 bytes)
    packet->qdcount = ((uint16_t)packet_data[4] << 8) | packet_data[5];

    // Parse the ANCOUNT field (2 bytes)
    packet->ancount = ((uint16_t)packet_data[6] << 8) | packet_data[7];

    // Parse the NSCOUNT field (2 bytes)
    packet->nscount = ((uint16_t)packet_data[8] << 8) | packet_data[9];

    // Parse the ARCOUNT field (2 bytes)
    packet->arcount = ((uint16_t)packet_data[10] << 8) | packet_data[11];

    // Parse the QNAME field ( variable length)
    int qname_len = 0;
    for (int i = 12; i < packet_len; i++) {
        if (packet_data[i] == 0x00) {
            break;
        }
        packet->qname[qname_len] = packet_data[i];
        qname_len++;
    }
    packet->qname[qname_len] = '\0';

    // Parse the QTYPE field (2 bytes)
    packet->qtype = ((uint16_t)packet_data[12 + qname_len + 1] << 8) | packet_data[12 + qname_len + 2];

    // Parse the QCLASS field (2 bytes)
    packet->qclass = ((uint16_t)packet_data[12 + qname_len + 3] << 8) | packet_data[12 + qname_len + 4];

    return packet;
}

int main() {
    FILE* fp = fopen("output.csv", "r");
    if (fp == NULL) {
        printf("Error opening file\n");
        return -1;
    }

    char line[1024];
    while (fgets(line, sizeof(line), fp)) {
        // Remove the newline character
        line[strcspn(line, "\n")] = 0;

        // Convert the hexadecimal string to binary data
        int packet_len = strlen(line) / 2;
        uint8_t* packet_data = (uint8_t*)malloc(packet_len);
        for (int i = 0; i < packet_len; i++) {
            sscanf(line + i * 2, "%2hhx", &packet_data[i]);
        }

        // Parse the DNS packet
        dns_packet* packet = parse_dns_packet((char*)packet_data, packet_len);
        if (packet != NULL) {
            printf("ID: %u\n", packet->id);
            printf("Flags: %u\n", packet->flags);
            printf("QDCOUNT: %u\n", packet->qdcount);
