typedef struct {
    double population;  // Total population
    double beta;        // Infection rate
    double gamma;       // Recovery rate
    double initial_susceptible;
    double initial_infected;
    double initial_recovered;
} SIRParameters;

// SIR Model State
typedef struct {
    double susceptible;
    double infected;
    double recovered;
} SIRState;

// Function prototypes
void initialize_parameters(SIRParameters *params);
void simulate_sir_model(SIRParameters *params, SIRState *state, int time_steps);
void print_results(SIRState *state, int time_steps);
void save_results_to_file(SIRState *state, int time_steps);

// Runge-Kutta 4th order method for solving differential equations
void runge_kutta_4(SIRParameters *params, SIRState *state, double dt) {
    // Intermediate variables
    double k1_s, k2_s, k3_s, k4_s;
    double k1_i, k2_i, k3_i, k4_i;
    double k1_r, k2_r, k3_r, k4_r;

    // Current state
    double S = state->susceptible;
    double I = state->infected;
    double R = state->recovered;
    double N = params->population;

    // SIR model differential equations
    // dS/dt = -β * S * I / N
    k1_s = -params->beta * S * I / N;
    k2_s = -params->beta * (S + 0.5*dt*k1_s) * (I + 0.5*dt*k1_i) / N;
    k3_s = -params->beta * (S + 0.5*dt*k2_s) * (I + 0.5*dt*k2_i) / N;
    k4_s = -params->beta * (S + dt*k3_s) * (I + dt*k3_i) / N;

    // dI/dt = β * S * I / N - γ * I
    k1_i = params->beta * S * I / N - params->gamma * I;
    k2_i = params->beta * (S + 0.5*dt*k1_s) * (I + 0.5*dt*k1_i) / N - params->gamma * (I + 0.5*dt*k1_i);
    k3_i = params->beta * (S + 0.5*dt*k2_s) * (I + 0.5*dt*k2_i) / N - params->gamma * (I + 0.5*dt*k2_i);
    k4_i = params->beta * (S + dt*k3_s) * (I + dt*k3_i) / N - params->gamma * (I + dt*k3_i);

    // dR/dt = γ * I
    k1_r = params->gamma * I;
    k2_r = params->gamma * (I + 0.5*dt*k1_i);
    k3_r = params->gamma * (I + 0.5*dt*k2_i);
    k4_r = params->gamma * (I + dt*k3_i);

    // Update state using RK4 method
    state->susceptible += (k1_s + 2*k2_s + 2*k3_s + k4_s) * dt / 6.0;
    state->infected += (k1_i + 2*k2_i + 2*k3_i + k4_i) * dt / 6.0;
    state->recovered += (k1_r + 2*k2_r + 2*k3_r + k4_r) * dt / 6.0;
}

// Initialize simulation parameters
void initialize_parameters(SIRParameters *params) {
    params->population = 100000.0;        // Total population
    params->beta = 0.3;                   // Infection rate
    params->gamma = 0.1;                  // Recovery rate
    params->initial_susceptible = 99999.0;
    params->initial_infected = 1.0;
    params->initial_recovered = 0.0;
}

// Simulate SIR model over time
void simulate_sir_model(SIRParameters *params, SIRState *state, int time_steps) {
    double dt = 0.1;  // Time step

    // Set initial state
    state->susceptible = params->initial_susceptible;
    state->infected = params->initial_infected;
    state->recovered = params->initial_recovered;

    // Simulate for each time step
    for (int i = 0; i < time_steps; i++) {
        runge_kutta_4(params, state, dt);
    }
}

// Print simulation results
void print_results(SIRState *state, int time_steps) {
    printf("SIR Model Simulation Results:\n");
    printf("Susceptible Population: %.2f\n", state->susceptible);
    printf("Infected Population: %.2f\n", state->infected);
    printf("Recovered Population: %.2f\n", state->recovered);
}

// Save results to CSV file
void save_results_to_file(SIRState *state, int time_steps) {
    FILE *file = fopen("sir_model_results.csv", "w");
    if (file == NULL) {
        printf("Error opening file!\n");
        return;
    }

    fprintf(file, "Time Step,Susceptible,Infected,Recovered\n");
    fprintf(file, "0,%f,%f,%f\n", 
            state->susceptible, 
            state->infected, 
            state->recovered);

    fclose(file);
}

int main() {
    SIRParameters params;
    SIRState state;
    int time_steps = 200;

    // Initialize parameters
    initialize_parameters(&params);

    // Run simulation
    simulate_sir_model(&params, &state, time_steps);

    // Display results
    print_results(&state, time_steps);

    // Save results to file
    save_results_to_file(&state, time_steps);

    return 0;
}

