#define TIME_STEPS 500    // Number of simulation steps
#define DELTA_T 1.0       // dt: Time step size (e.g., 1.0 for daily steps)

// --- Function to perform one step of the SIR simulation ---
void sir_step(double *S, double *I, double *R, double N, double beta, double gamma, double dt) {
    // Calculate the change in each compartment
    double dS_dt = -beta * (*S) * (*I) / N;
    double dI_dt = beta * (*S) * (*I) / N - gamma * (*I);
    double dR_dt = gamma * (*I);

    // Update the values using Euler's method
    *S += dS_dt * dt;
    *I += dI_dt * dt;
    *R += dR_dt * dt;

    // Ensure no compartment falls below zero due to numerical precision
    if (*S < 0) *S = 0;
    if (*I < 0) *I = 0;
    if (*R < 0) *R = 0;

    // Optional: Re-normalize if floating point errors cause N to drift slightly
    // double current_N = *S + *I + *R;
    // double factor = N / current_N;
    // *S *= factor;
    // *I *= factor;
    // *R *= factor;
}

