// SIR model parameters
typedef struct {
    double beta; // transmission rate
    double gamma; // recovery rate
    double S; // susceptible
    double I; // infected
    double R; // recovered
    int total_population;
} SIRModel;

// Function to update the SIR model
void updateModel(SIRModel *model, double dt) {
    double new_infected = model->beta * model->S * model->I / model->total_population;
    double new_recovered = model->gamma * model->I;

    model->S -= new_infected * dt;
    model->I += (new_infected - new_recovered) * dt;
    model->R += new_recovered * dt;

    // Ensure populations remain non-negative
    if (model->S < 0) model->S = 0;
    if (model->I < 0) model->I = 0;
    if (model->R < 0) model->R = 0;
}

// Function to print the current state of the model
void printState(int day, SIRModel model) {
    printf("Day %d: Susceptible: %.2f, Infected: %.2f, Recovered: %.2f\n",
           day, model.S, model.I, model.R);
}

