    printf("Transmission Rate (Beta): %.2f\n", model.beta);
    printf("Recovery Rate (Gamma): %.2f\n\n", model.gamma);

    // Simulation loop
    for (int day = 0; day <= days; day++) {
        printState(day, model);
        updateModel(&model, dt);
    }

    return 0;
}

