// Structure to hold simulation parameters
typedef struct {
    double beta;  // infection rate
    double gamma; // recovery rate
    double N;     // total population size
    double t_max; // maximum simulation time
    double dt;    // time step
} SimulationParams;

// Structure to hold simulation state
typedef struct {
    double S; // number of susceptible individuals
    double I; // number of infected individuals
    double R; // number of recovered individuals
} SimulationState;

// Function to initialize simulation state
void init_simulation_state(SimulationState* state, SimulationParams* params) {
    state->S = params->N - 1; // initialize with one infected individual
    state->I = 1;
    state->R = 0;
}

// Function to update simulation state using Euler method
void update_simulation_state(SimulationState* state, SimulationParams* params) {
    double dSdt = -params->beta * state->S * state->I / params->N;
    double dIdt = params->beta * state->S * state->I / params->N - params->gamma * state->I;
    double dRdt = params->gamma * state->I;

    state->S += dSdt * params->dt;
    state->I += dIdt * params->dt;
    state->R += dRdt * params->dt;
}

// Function to run simulation
void run_simulation(SimulationParams* params) {
    SimulationState state;
    init_simulation_state(&state, params);

    printf("Time\tSusceptible\tInfected\tRecovered\n");
    printf("%f\t%f\t%f\t%f\n", 0.0, state.S, state.I, state.R);

    double t = 0.0;
    while (t < params->t_max) {
        update_simulation_state(&state, params);
        t += params->dt;

        printf("%f\t%f\t%f\t%f\n", t, state.S, state.I, state.R);

        // Check for termination conditions
        if (state.I < 1e-6) {
            break;
        }
    }
}

