// Parameters
#define POPULATION 1000
#define BETA 0.3    // Infection rate
#define GAMMA 0.1   // Recovery rate
#define DAYS 100    // Number of days to simulate

void SIR_model(double S[], double I[], double R[], int days, double beta, double gamma) {
    double dS, dI, dR;
    S[0] = POPULATION - 1; // Initial susceptible population
    I[0] = 1;              // Initial infected population
    R[0] = 0;              // Initial recovered population

    for (int t = 0; t < days - 1; t++) {
        dS = -beta * S[t] * I[t] / POPULATION;
        dI = beta * S[t] * I[t] / POPULATION - gamma * I[t];
        dR = gamma * I[t];

        S[t + 1] = S[t] + dS;
        I[t + 1] = I[t] + dI;
        R[t + 1] = R[t] + dR;
    }
}

