// Function prototype for the differential equation
typedef double (*DiffEquationFunc)(double x, double y);

// Euler's method implementation
void eulers_method(
    DiffEquationFunc diff_equation,  // Differential equation function
    double x0,                       // Initial x value
    double y0,                       // Initial y value
    double x_final,                  // Final x value
    int steps                        // Number of steps
) {
    // Calculate step size
    double h = (x_final - x0) / steps;

    // Initialize variables
    double x = x0;
    double y = y0;

    // Print header
    printf("Euler's Method Solution\n");
    printf("---------------------\n");
    printf("Step\t x\t\t y\n");
    printf("---------------------\n");

    // Print initial conditions
    printf("0\t %.4f\t\t %.4f\n", x, y);

    // Iterate through steps
    for (int i = 1; i <= steps; i++) {
        // Calculate next y value using Euler's formula
        // y(n+1) = y(n) + h * f(x(n), y(n))
        double dy = diff_equation(x, y);
        y = y + h * dy;
        x = x + h;

        // Print current step results
        printf("%d\t %.4f\t\t %.4f\n", i, x, y);
    }
}

