    }
    if (xn == x0 && steps > 1) {
        printf("Warning: xn is equal to x0. Only 1 step will be performed.\n");
        steps = 1;
    }


    // Calculate step size (h)
    double h = (xn - x0) / steps;

    printf("\n--- Euler's Method Calculation ---\n");
    printf("Initial: x = %.6f, y = %.6f\n", x0, y0);
    printf("Step size (h): %.6f\n", h);
    printf("----------------------------------\n");

    double current_x = x0;
    double current_y = y0;

    // Loop through the steps
    for (int i = 0; i < steps; i++) {
        // Apply Euler's formula: y_next = y_current + h * f(x_current, y_current)
        double next_y = current_y + h * f(current_x, current_y);

        // Update x for the next step
        double next_x = current_x + h;

        printf("Step %-3d: x = %.6f, y = %.6f\n", i + 1, next_x, next_y);

        // Prepare for the next iteration
        current_x = next_x;
        current_y = next_y;
    }

    printf("\n--- Final Result ---\n");
    printf("At x = %.6f, the approximate y is: %.6f\n", current_x, current_y);

    return 0; // Indicate successful execution
}

