// Function to convert a character to its corresponding phone dial digit
char letter_to_digit(char letter) {
    letter = toupper(letter);

    switch(letter) {
        case 'A': case 'B': case 'C':   return '2';
        case 'D': case 'E': case 'F':   return '3';
        case 'G': case 'H': case 'I':   return '4';
        case 'J': case 'K': case 'L':   return '5';
        case 'M': case 'N': case 'O':   return '6';
        case 'P': case 'Q': case 'R': case 'S':   return '7';
        case 'T': case 'U': case 'V':   return '8';
        case 'W': case 'X': case 'Y': case 'Z':   return '9';
        default:  return letter;
    }
}

// Function to convert name to phone dial format
void name_to_phone_dial(const char* name, char* result) {
    int result_index = 0;
    int word_count = 0;

    for (int i = 0; name[i] != '\0'; i++) {
        // Skip spaces between words
        if (name[i] == ' ') {
            word_count++;
            continue;
        }

        // Convert letters to digits
        if (isalpha(name[i])) {
            char digit = letter_to_digit(name[i]);
            result[result_index++] = digit;
        }
    }

    // Null-terminate the result string
    result[result_index] = '\0';
}

