    char phone_dial[100];

    // Example usage
    strcpy(name, "John Doe");
    name_to_phone_dial(name, phone_dial);
    printf("Name: %s\n", name);
    printf("Phone Dial: %s\n", phone_dial);

    strcpy(name, "Alice Smith");
    name_to_phone_dial(name, phone_dial);
    printf("Name: %s\n", name);
    printf("Phone Dial: %s\n", phone_dial);

    return 0;
}

