/**
 * @brief Converts a person's name into phone dial format.
 *        Example: "John Doe" -> "5646 363"
 *        Mappings:
 *        2: A, B, C
 *        3: D, E, F
 *        4: G, H, I
 *        5: J, K, L
 *        6: M, N, O
 *        7: P, Q, R, S
 *        8: T, U, V
 *        9: W, X, Y, Z
 *
 * @param name A pointer to the input string (the person's name).
 * @return A dynamically allocated string containing the phone dial format.
 *         Returns NULL if input is NULL or if memory allocation fails.
 *         The caller is responsible for freeing the returned string using free().
 */
char* nameToPhoneDial(const char* name) {
    if (name == NULL) {
        return NULL;
    }

    // A rough estimation for the maximum output string length.
    // Each char in input could be a digit or a space.
    // We add 1 for the null terminator.
    size_t name_len = strlen(name);
    char* result = (char*)malloc(name_len + 1); // Max possible length (if all are digits/spaces)
    if (result == NULL) {
        perror("Failed to allocate memory for result string");
        return NULL;
    }
    result[0] = '\0'; // Initialize as an empty string

    int result_idx = 0; // Current index for writing into the result string

    for (int i = 0; i < name_len; i++) {
        char ch = name[i];
        char upper_ch = toupper(ch); // Convert to uppercase for easier mapping

        if (isalpha(upper_ch)) {
            // Map letters to digits
            if (upper_ch >= 'A' && upper_ch <= 'C') {
                result[result_idx++] = '2';
            } else if (upper_ch >= 'D' && upper_ch <= 'F') {
                result[result_idx++] = '3';
            } else if (upper_ch >= 'G' && upper_ch <= 'I') {
                result[result_idx++] = '4';
            } else if (upper_ch >= 'J' && upper_ch <= 'L') {
                result[result_idx++] = '5';
            } else if (upper_ch >= 'M' && upper_ch <= 'O') {
                result[result_idx++] = '6';
            } else if (upper_ch >= 'P' && upper_ch <= 'S') {
                result[result_idx++] = '7';
            } else if (upper_ch >= 'T' && upper_ch <= 'V') {
                result[result_idx++] = '8';
            } else if (upper_ch >= 'W' && upper_ch <= 'Z') {
                result[result_idx++] = '9';
            }
        } else if (isspace(ch)) {
            // Handle spaces: only add a space if the previous character was a digit
            // (or if it's the very first character and we want to preserve leading spaces,
            // though usually we'd trim them. For this example, we'll mimic space behavior
            // as in the example 'John Doe' -> '5636 363', meaning a space appears).
            // Let's refine this: only add a space if it's not the first character
            // and the previous character written to result was not already a space.
            if (result_idx > 0 && result[result_idx - 1] != ' ') {
                result[result_idx++] = ' ';
            }
        }
        // Ignore other characters (numbers, punctuation, etc.) for this implementation.
    }

    result[result_idx] = '\0'; // Null-terminate the string

    // Optional: Reallocate to actual size to save memory, though not strictly necessary.
    // char* final_result = (char*)realloc(result, result_idx + 1);
    // if (final_result == NULL) {
    //     // If realloc fails, we still return the original `result` as it's valid.
    //     return result;
    // }
    // return final_result;

    // A final pass to trim potential trailing spaces if any were added
    // (though our logic above tries to prevent this for alphabet-only names).
    if (result_idx > 0 && result[result_idx - 1] == ' ') {
        result[result_idx - 1] = '\0'; // Remove trailing space
    }

    return result;
}

