// Fuzzy search function
int fuzzy_match(const char* pattern, const char* target) {
    if (!pattern || !target) return 0;

    // Convert both to lowercase for case-insensitive matching
    char* lower_pattern = strdup(pattern);
    char* lower_target = strdup(target);

    for (int i = 0; lower_pattern[i]; i++) 
        lower_pattern[i] = tolower(lower_pattern[i]);
    for (int i = 0; lower_target[i]; i++) 
        lower_target[i] = tolower(lower_target[i]);

    int p = 0, t = 0;
    while (pattern[p] && target[t]) {
        if (tolower(pattern[p]) == tolower(target[t])) {
            p++;
        }
        t++;
    }

    free(lower_pattern);
    free(lower_target);

    return p == strlen(pattern);
}

// Function to read process name from /proc/[pid]/comm
char* get_process_name(pid_t pid) {
    char path[256];
    snprintf(path, sizeof(path), "/proc/%d/comm", pid);

    FILE* file = fopen(path, "r");
    if (!file) return NULL;

    char* name = malloc(256);
    if (!fgets(name, 256, file)) {
        fclose(file);
        free(name);
        return NULL;
    }

    // Remove newline
    name[strcspn(name, "\n")] = 0;
    fclose(file);
    return name;
}

// Function to list processes
int list_processes(const char* name_filter) {
    DIR* proc_dir = opendir("/proc");
    if (!proc_dir) {
        perror("Could not open /proc directory");
        return -1;
    }

    struct dirent* entry;
    int process_count = 0;

    printf("%-6s %-20s %s\n", "PID", "NAME", "STATE");
    printf("--------------------------------\n");

    while ((entry = readdir(proc_dir)) != NULL) {
        // Skip non-numeric entries (non-process directories)
        if (entry->d_type != DT_DIR || !isdigit(entry->d_name[0])) 
            continue;

        pid_t pid = atoi(entry->d_name);

        // Get process name
        char* proc_name = get_process_name(pid);
        if (!proc_name) continue;

        // Check name filter
        if (!name_filter || fuzzy_match(name_filter, proc_name)) {
            char status_path[256];
            snprintf(status_path, sizeof(status_path), "/proc/%d/status", pid);

            FILE* status_file = fopen(status_path, "r");
            if (status_file) {
                char line[256];
                char state[32] = "Unknown";

                while (fgets(line, sizeof(line), status_file)) {
                    if (strncmp(line, "State:", 6) == 0) {
                        // Extract state
                        char* state_start = line + 6;
                        while (isspace(*state_start)) state_start++;

                        // Copy first word of state
                        sscanf(state_start, "%31[^ \n]", state);
                        break;
                    }
                }

                printf("%-6d %-20s %s\n", pid, proc_name, state);
                fclose(status_file);
                process_count++;
            }
        }

        free(proc_name);
    }

    closedir(proc_dir);

    printf("\nTotal Processes: %d\n", process_count);
    return process_count;
}

