// --- Helper for Fuzzy Search (very basic example) ---
// This is NOT a sophisticated fuzzy search. It just checks if the filter
// string is a substring of the process name (case-insensitive).
// For real fuzzy search (Levenshtein, n-gram, etc.), you'd need more complex logic.
int strmatch_fuzz_simple(const char *process_name, const char *filter_name) {
    if (!filter_name || strlen(filter_name) == 0) {
        return 1; // No filter, always match
    }

    if (!process_name) {
        return 0; // Cannot match if no process name
    }

    // Convert both to lowercase for case-insensitive comparison
    char *lower_process_name = strdup(process_name);
    char *lower_filter_name = strdup(filter_name);

    if (!lower_process_name || !lower_filter_name) {
        perror("strdup failed in fuzzy search");
        free(lower_process_name);
        free(lower_filter_name);
        return 0;
    }

    for (char *p = lower_process_name; *p; ++p) *p = tolower((unsigned char)*p);
    for (char *p = lower_filter_name; *p; ++p) *p = tolower((unsigned char)*p);

    int match = (strstr(lower_process_name, lower_filter_name) != NULL);

    free(lower_process_name);
    free(lower_filter_name);

    return match;
}

// --- Main Process Listing Function ---

/**
 * @brief Lists all running processes on Linux, with an optional fuzzy name filter.
 *
 * This function iterates through the /proc filesystem to find process directories,
 * reads their 'comm' file for the command name, and optionally filters them
 * using a basic fuzzy substring search.
 *
 * @param fuzzy_filter_name An optional string to filter process names. If NULL or empty,
 *                          all processes are listed. The search is case-insensitive
 *                          and looks for `fuzzy_filter_name` as a substring.
 * @return 0 on success, -1 on failure.
 */
int list_processes(const char *fuzzy_filter_name) {
    DIR *proc_dir;
    struct dirent *entry;
    char path[256];
    char comm_path[256];
    FILE *fp;
    char process_name[256];
    int pid;

    proc_dir = opendir("/proc");
    if (proc_dir == NULL) {
        perror("Error opening /proc directory");
        return -1;
    }

    printf("Listing Processes (Filtered by: '%s' %s):\n",
           fuzzy_filter_name ? fuzzy_filter_name : "",
           fuzzy_filter_name && strlen(fuzzy_filter_name) > 0 ? " (basic fuzzy substring match)" : "(no filter)");
    printf("--------------------------------------------------\n");

    while ((entry = readdir(proc_dir)) != NULL) {
        // Check if the directory name is a PID (all digits)
        if (entry->d_type == DT_DIR) {
            int is_pid = 1;
            for (int i = 0; entry->d_name[i] != '\0'; i++) {
                if (!isdigit((unsigned char)entry->d_name[i])) {
                    is_pid = 0;
                    break;
                }
            }

            if (is_pid) {
                pid = atoi(entry->d_name);
                snprintf(comm_path, sizeof(comm_path), "/proc/%d/comm", pid);

                fp = fopen(comm_path, "r");
                if (fp != NULL) {
                    // Read the command name (often without newline byte at end)
                    if (fgets(process_name, sizeof(process_name), fp) != NULL) {
                        // Remove trailing newline if present
                        process_name[strcspn(process_name, "\n")] = 0;

                        // Apply the fuzzy filter
                        if (strmatch_fuzz_simple(process_name, fuzzy_filter_name)) {
                            printf("PID: %5d | Name: %s\n", pid, process_name);
                        }
                    }
                    fclose(fp);
                }
                // else: Cannot open comm file (e.g., process died or permissions)
            }
        }
    }

    closedir(proc_dir);
    return 0;
}

