int fuzzy_match(const char *haystack, const char *needle) {
    if (!needle || !*needle)
        return 1; // Default: match everything if filter is empty/null

    char h[256], n[256];
    snprintf(h, sizeof(h), "%s", haystack);
    snprintf(n, sizeof(n), "%s", needle);

    // Convert both to lower case for case-insensitive
    for (char *p = h; *p; ++p) *p = (char)tolower(*p);
    for (char *p = n; *p; ++p) *p = (char)tolower(*p);
    return strstr(h, n) != NULL;
}

