// Function to list processes, with optional name filter.
void listProcesses(const char* nameFilter) {
    struct dirent* entry;
    DIR* proc = opendir("/proc");

    if (proc == NULL) {
        perror("opendir");
        return;
    }

    regex_t regex;
    int ret = 0;
    if (nameFilter) {
        // Compile the regex for the fuzzy search
        char regexPattern[256];
        snprintf(regexPattern, sizeof(regexPattern), ".*%s.*", nameFilter);
        ret = regcomp(&regex, regexPattern, REG_EXTENDED | REG_NOSUB);
        if (ret) {
            fprintf(stderr, "Could not compile regex\n");
            closedir(proc);
            return;
        }
    }

    while ((entry = readdir(proc)) != NULL) {
        // Filter only directories with numeric names (PIDs)
        if (entry->d_type == DT_DIR && strspn(entry->d_name, "0123456789") == strlen(entry->d_name)) {
            char path[256], cmdline[256];
            FILE* cmdlineFile;

            // Construct path to the cmdline file
            snprintf(path, sizeof(path), "/proc/%s/cmdline", entry->d_name);
            cmdlineFile = fopen(path, "r");
            if (cmdlineFile) {
                if (fgets(cmdline, sizeof(cmdline), cmdlineFile) != NULL) {
                    // Check if we have a filter and perform the regex match
                    if (nameFilter == NULL || regexec(&regex, cmdline, 0, NULL, 0) == 0) {
                        printf("PID: %s, Command: %s\n", entry->d_name, cmdline);
                    }
                }
                fclose(cmdlineFile);
            }
        }
    }

    if (nameFilter) {
        regfree(&regex);
    }
    closedir(proc);
}

