                // Construct the path to the cmdline file
                char cmdline_path[BUFFER_SIZE];
                snprintf(cmdline_path, sizeof(cmdline_path), "/proc/%s/cmdline", entry->d_name);

                // Open the cmdline file to read command
                FILE *cmdline_file = fopen(cmdline_path, "r");
                if (cmdline_file) {
                    char cmdline[BUFFER_SIZE];
                    if (fgets(cmdline, sizeof(cmdline), cmdline_file) != NULL) {
                        // Remove any trailing null characters
                        for (char *ptr = cmdline; *ptr; ptr++) {
                            if (*ptr == '\0') {
                                *ptr = ' '; // Replace null char with space for readability
                            }
                        }
                        // Check for the filter match if provided
                        if (!filter || fuzzy_match(cmdline, filter)) {
                            printf("%-10d %-20s\n", pid, cmdline);
                        }
                    }
                    fclose(cmdline_file);
                }
            }
        }
    }

    closedir(dir);
}

int main(int argc, char *argv[]) {
    // Check for optional filter argument
    const char *filter = (argc > 1) ? argv[1] : NULL;
    list_processes(filter);
    return 0;
}

#include <dirent.h>
