#include <sys/types.h>
#include <sys/stat.h>
#include <fnmatch.h>

// Structure to represent a process
typedef struct {
    int pid;
    char name[256];
} Process;

// Function to list all running processes
void list_processes(Process **processes, int *count, const char *filter) {
    DIR *dir;
    struct dirent *entry;
    char path[256];
    int i = 0;

    // Initialize process array and count
    *count = 0;
    *processes = (Process *)malloc(1024 * sizeof(Process)); // Allocate memory for 1024 processes

    // Open /proc directory
    dir = opendir("/proc");
    if (dir == NULL) {
        perror("opendir");
        exit(EXIT_FAILURE);
    }

    // Iterate through all directories in /proc
    while ((entry = readdir(dir)) != NULL) {
        // Check if entry is a directory and its name is a number (i.e., a process)
        if (entry->d_type == DT_DIR && atoi(entry->d_name) > 0) {
            // Construct path to /proc/<pid>/comm
            sprintf(path, "/proc/%s/comm", entry->d_name);

            // Open and read /proc/<pid>/comm to get the process name
            FILE *file = fopen(path, "r");
            if (file != NULL) {
                char name[256];
                if (fgets(name, sizeof(name), file) != NULL) {
                    name[strcspn(name, "\n")] = 0; // Remove newline character

                    // Check if filter is set and matches the process name
                    if (filter == NULL || fnmatch(filter, name, 0) == 0) {
                        // Add process to the list
                        (*processes)[i].pid = atoi(entry->d_name);
                        strcpy((*processes)[i].name, name);
                        i++;
                        (*count)++;
                    }
                }
                fclose(file);
            }
        }
    }

    // Close /proc directory
    closedir(dir);

    // Reallocate memory to fit the actual number of processes
    *processes = (Process *)realloc(*processes, (*count) * sizeof(Process));
}

// Example usage
int main() {
    Process *processes;
    int count;
    const char *filter = NULL; // Set to NULL for no filter, or a string for fuzzy search

    list_processes(&processes, &count, filter);

    printf("Running processes:\n");
    for (int i = 0; i < count; i++) {
        printf("%d: %s\n", processes[i].pid, processes[i].name);
    }

    // Free allocated memory
    free(processes);

    return 0;
}

