#include <ctype.h>

#define PROC_DIR "/proc"
#define CMDLINE_FILE "cmdline"
#define MAX_PATH 1024
#define MAX_CMDLINE 4096

// Function to check if a string contains another string (fuzzy search)
int contains(const char *haystack, const char *needle) {
    if (needle == NULL || *needle == '\0') {
        return 1;
    }
    for (int i = 0; ; i++) {
        if (haystack[i] == '\0') {
            return 0;
        }
        if (haystack[i] == *needle && memcmp(haystack + i, needle, strlen(needle)) == 0) {
            return 1;
        }
    }
    return 0;
}

// Function to list all running processes
void list_processes(const char *filter) {
    DIR *proc_dir;
    struct dirent *entry;
    char path[MAX_PATH];
    char cmdline[MAX_CMDLINE];
    FILE *cmdline_file;

    // Open the /proc directory
    proc_dir = opendir(PROC_DIR);
    if (proc_dir == NULL) {
        perror("opendir");
        return;
    }

    // Iterate through all entries in the /proc directory
    while ((entry = readdir(proc_dir)) != NULL) {
        // Check if the entry is a directory and represents a process
        if (isdigit(entry->d_name[0])) {
            // Construct the path to the process directory
            snprintf(path, MAX_PATH, "%s/%s", PROC_DIR, entry->d_name);

            // Open the cmdline file to get the command line of the process
            snprintf(path, MAX_PATH, "%s/%s", path, CMDLINE_FILE);
            cmdline_file = fopen(path, "r");
            if (cmdline_file == NULL) {
                continue;
            }

            // Read the command line
            if (fgets(cmdline, MAX_CMDLINE, cmdline_file) != NULL) {
                // Remove null characters and trailing newlines
                char *end = cmdline + strlen(cmdline);
                while (end > cmdline && (end[-1] == '\0' || end[-1] == '\n')) {
                    end--;
                }
                *end = '\0';

                // Check if the process matches the filter
                if (filter == NULL || contains(cmdline, filter)) {
                    printf("PID: %s, CMD: %s\n", entry->d_name, cmdline);
                }
            }

            fclose(cmdline_file);
        }
    }

    // Close the /proc directory
    closedir(proc_dir);
}

int main(int argc, char *argv[]) {
    const char *filter = NULL;

    // Check if a filter is provided
    if (argc > 1) {
        filter = argv[1];
    }

    // List all processes
    list_processes(filter);

    return 0;
}

