#include <unistd.h>
#include <termios.h>
#include <fcntl.h>

#define WIDTH 40
#define HEIGHT 20

// Function to check for keyboard input without blocking
int kbhit() {
    struct termios oldt, newt;
    int ch;
    int oldf;

    tcgetattr(STDIN_FILENO, &oldt);
    newt = oldt;
    newt.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &newt);
    oldf = fcntl(STDIN_FILENO, F_GETFL, 0);
    fcntl(STDIN_FILENO, F_SETFL, oldf | O_NONBLOCK);

    ch = getchar();

    tcsetattr(STDIN_FILENO, TCSANOW, &oldt);
    fcntl(STDIN_FILENO, F_SETFL, oldf);

    if(ch != EOF) {
        ungetc(ch, stdin);
        return 1;
    }

    return 0;
}

// Function to clear the console screen
void clearScreen() {
    #ifdef _WIN32
        system("cls");
    #else
        system("clear");
    #endif
}

int main() {
    // Ball position and velocity
    float x = WIDTH / 2.0;
    float y = HEIGHT / 2.0;
    float dx = 1.0;
    float dy = 1.0;

    // Game loop
    while (1) {
        // Clear the screen
        clearScreen();

        // Create the game board
        for (int row = 0; row < HEIGHT; row++) {
            for (int col = 0; col < WIDTH; col++) {
                // Check if current position is the ball's position
                if ((int)x == col && (int)y == row) {
                    printf("O");
                }
                // Draw borders
                else if (row == 0 || row == HEIGHT - 1) {
                    printf("-");
                }
                else if (col == 0 || col == WIDTH - 1) {
                    printf("|");
                }
                else {
                    printf(" ");
                }
            }
            printf("\n");
        }

        // Update ball position
        x += dx;
        y += dy;

        // Bounce off walls
        if (x <= 1 || x >= WIDTH - 2) {
            dx = -dx;
        }
        if (y <= 1 || y >= HEIGHT - 2) {
            dy = -dy;
        }

        // Check for exit
        if (kbhit()) {
            char ch = getchar();
            if (ch == 'q' || ch == 'Q') {
                break;
            }
        }

        // Slow down the animation
        usleep(100000);  // 100 milliseconds
    }

    return 0;
}

