// --- Platform-specific screen clearing ---
// For Windows
#ifdef _WIN32
#define CLEAR_SCREEN() system("cls")
#define SLEEP_MS(ms)   Sleep(ms) // Windows.h needed for Sleep
#include <windows.h> // Include if using Windows
#else
// For Unix-like systems (Linux, macOS)
#define CLEAR_SCREEN() system("clear")
#define SLEEP_MS(ms)   usleep(ms * 1000) // usleep takes microseconds
#endif
// -----------------------------------------


// Console dimensions (adjust as needed for your terminal)
// NOTE: These are approximate. Your terminal might resize,
// or have different actual character dimensions.
#define CONSOLE_WIDTH  78
#define CONSOLE_HEIGHT 23

// Ball properties
char BALL_CHAR = 'O'; // Character to represent the ball
int BALL_RADIUS = 0;  // For a single char, radius is 0
float GRAVITY_ACCEL = 0.5f; // How much Y velocity increases per frame
float BOUNCE_DAMPING = 0.8f; // How much velocity is lost on bounce (0.0 = no bounce, 1.0 = perfect bounce)

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Ball initial position (center-ish)
    float ball_x = CONSOLE_WIDTH / 2.0f;
    float ball_y = CONSOLE_HEIGHT / 2.0f;

    // Ball initial velocity (randomized slightly)
    float ball_vx = 3.0f * ((rand() % 2 == 0) ? 1 : -1); // Random initial direction (left/right)
    float ball_vy = 0.0f; // Starts falling down

    // Frame delay in milliseconds
    int frame_delay_ms = 50;

    // Main animation loop
    while (1) {
        CLEAR_SCREEN();

        // 1. Update ball position based on velocity
        ball_x += ball_vx;
        ball_y += ball_vy;

        // 2. Apply gravity (increase downward velocity)
        ball_vy += GRAVITY_ACCEL;

        // 3. Handle collisions with walls
        // Left wall
        if (ball_x < 0) {
            ball_x = 0;   // Correct position
            ball_vx *= -1; // Reverse velocity
        }
        // Right wall
        else if (ball_x >= CONSOLE_WIDTH - 1) { // -1 because positions are 0 to WIDTH-1
            ball_x = CONSOLE_WIDTH - 1; // Correct position
            ball_vx *= -1; // Reverse velocity
        }

        // Top wall
        if (ball_y < 0) {
            ball_y = 0;   // Correct position
            ball_vy *= -1; // Reverse velocity
        }
        // Bottom wall
        else if (ball_y >= CONSOLE_HEIGHT - 1) {
            ball_y = CONSOLE_HEIGHT - 1; // Correct position
            ball_vy *= -BOUNCE_DAMPING; // Reverse and dampen velocity
            // If ball velocity is too small after bounce, stop it to prevent jiggling
            if (fabs(ball_vy) < 1.0f) {
                 ball_vy = 0.0f;
                 ball_y = CONSOLE_HEIGHT - 1; // Ensure it stays on the ground
            }
        }


        // 4. Draw the console frame
        for (int y = 0; y < CONSOLE_HEIGHT; y++) {
            for (int x = 0; x < CONSOLE_WIDTH; x++) {
                // Check if current (x,y) is where the ball should be
                if (x == (int)round(ball_x) && y == (int)round(ball_y)) {
                    printf("%c", BALL_CHAR);
                } else if (x == 0 || x == CONSOLE_WIDTH - 1 || y == 0 || y == CONSOLE_HEIGHT - 1) {
                    // Draw borders
                    printf("#");
                } else {
                    printf(" "); // Empty space
                }
            }
            printf("\n"); // New line after each row
