// Node structure for AVL tree
typedef struct AVLNode {
    int data;
    struct AVLNode* left;
    struct AVLNode* right;
    int height;
} AVLNode;

// Function prototypes
int getHeight(AVLNode* node);
int getBalanceFactor(AVLNode* node);
AVLNode* createNode(int value);
AVLNode* rotateRight(AVLNode* y);
AVLNode* rotateLeft(AVLNode* x);
AVLNode* insertNode(AVLNode* root, int value);
void inorderTraversal(AVLNode* root);

// Get height of a node
int getHeight(AVLNode* node) {
    if (node == NULL)
        return 0;
    return node->height;
}

// Get balance factor of a node
int getBalanceFactor(AVLNode* node) {
    if (node == NULL)
        return 0;
    return getHeight(node->left) - getHeight(node->right);
}

// Create a new AVL tree node
AVLNode* createNode(int value) {
    AVLNode* newNode = (AVLNode*)malloc(sizeof(AVLNode));
    newNode->data = value;
    newNode->left = NULL;
    newNode->right = NULL;
    newNode->height = 1;
    return newNode;
}

// Right rotation
AVLNode* rotateRight(AVLNode* y) {
    AVLNode* x = y->left;
    AVLNode* T2 = x->right;

    // Perform rotation
    x->right = y;
    y->left = T2;

    // Update heights
    y->height = 1 + (getHeight(y->left) > getHeight(y->right) ? 
                     getHeight(y->left) : getHeight(y->right));
    x->height = 1 + (getHeight(x->left) > getHeight(x->right) ? 
                     getHeight(x->left) : getHeight(x->right));

    return x;
}

// Left rotation
AVLNode* rotateLeft(AVLNode* x) {
    AVLNode* y = x->right;
    AVLNode* T2 = y->left;

    // Perform rotation
    y->left = x;
    x->right = T2;

    // Update heights
    x->height = 1 + (getHeight(x->left) > getHeight(x->right) ? 
                     getHeight(x->left) : getHeight(x->right));
    y->height = 1 + (getHeight(y->left) > getHeight(y->right) ? 
                     getHeight(y->left) : getHeight(y->right));

    return y;
}

// Insert a node and balance the tree
AVLNode* insertNode(AVLNode* root, int value) {
    // Standard BST insertion
    if (root == NULL)
        return createNode(value);

    if (value < root->data)
        root->left = insertNode(root->left, value);
    else if (value > root->data)
        root->right = insertNode(root->right, value);
    else
        return root; // Duplicate values not allowed

    // Update height of current node
    root->height = 1 + (getHeight(root->left) > getHeight(root->right) ? 
                        getHeight(root->left) : getHeight(root->right));

    // Get balance factor
    int balance = getBalanceFactor(root);

    // Perform rotations if tree is unbalanced
    // Left Left Case
    if (balance > 1 && value < root->left->data)
        return rotateRight(root);

    // Right Right Case
    if (balance < -1 && value > root->right->data)
        return rotateLeft(root);

    // Left Right Case
    if (balance > 1 && value > root->left->data) {
        root->left = rotateLeft(root->left);
        return rotateRight(root);
    }

    // Right Left Case
    if (balance < -1 && value < root->right->data) {
        root->right = rotateRight(root->right);
        return rotateLeft(root);
    }

    return root;
}

// Inorder traversal of AVL tree
void inorderTraversal(AVLNode* root) {
    if (root != NULL) {
        inorderTraversal(root->left);
        printf("%d ", root->data);
        inorderTraversal(root->right);
    }
}

