#include <math.h>
#include <gmp.h>

void calculate_pi(int digits) {
    // Allocate GMP precision based on decimal digits
    int precision = digits * 3.33 + 1;  // Convert decimal digits to bits

    // Initialize GMP variables
    mpf_t pi, term;
    mpf_init2(pi, precision);
    mpf_init2(term, precision);

    // Set initial pi value to 0
    mpf_set_ui(pi, 0);

    // Leibniz formula variables
    mpf_t four, divisor;
    mpf_init2(four, precision);
    mpf_init2(divisor, precision);
    mpf_set_ui(four, 4);

    // Iteration variables
    int k;
    mpf_t sign;
    mpf_init2(sign, precision);

    // Number of iterations needed for desired precision
    int iterations = digits * 2;

    // Calculate pi using Leibniz formula
    for (k = 0; k < iterations; k++) {
        // Determine sign: (-1)^k
        mpf_set_ui(sign, (k % 2 == 0) ? 1 : -1);

        // Calculate term: 1 / (2k + 1)
        mpf_set_ui(divisor, 2 * k + 1);
        mpf_div(term, sign, divisor);

        // Add term to pi
        mpf_add(pi, pi, term);
    }

    // Multiply by 4 to get pi
    mpf_mul(pi, pi, four);

    // Print pi to specified decimal places
    printf("Pi to %d decimal places:\n", digits);

    // Use gmp_printf to print with specified precision
    gmp_printf("%.*Ff\n", digits, pi);

    // Clean up GMP variables
    mpf_clear(pi);
    mpf_clear(term);
    mpf_clear(four);
    mpf_clear(divisor);
    mpf_clear(sign);
}

