// Function to calculate pi using the Leibniz formula
double calculate_pi(int digits) {
    double pi = 0.0;
    double precision = pow(10, -digits); // Desired precision
    int sign = 1;
    long int n = 0;

    while (1) {
        double term = 1.0 / (2 * n + 1);
        pi += sign * term;
        if (term < precision) {
            break; // Stop when the term is smaller than the desired precision
        }
        sign = -sign; // Alternate the sign
        n++;
    }

    return 4 * pi;
}

int main() {
    int digits;
    printf("Enter the number of decimal places to calculate pi: ");
    scanf("%d", &digits);

    double pi = calculate_pi(digits);
    printf("Pi to %d decimal places is: %.*f\n", digits, digits, pi);

    return 0;
}

#include <stdio.h>
#include <gmp.h> // GNU Multiple Precision Arithmetic Library

/**
 * Calculates pi using the Leibniz formula:
 * pi/4 = 1 - 1/3 + 1/5 - 1/7 + 1/9 - ...
 *
 * The Leibniz formula is known for its slow convergence. For practical pi
 * calculations to high precision, other algorithms like Chudnovsky or
 * Borwein are much more efficient.
 *
 * This implementation uses the GMP library for arbitrary-precision arithmetic.
 *
 * @param digits The number of decimal places to calculate pi to.
 */
void calculate_pi_leibniz(int digits) {
    // Set the precision for GMP numbers.
    // The precision is in bits, not decimal digits.
    // To get 'digits' decimal places, we need approximately log2(10) * digits bits.
    // A rule of thumb is digits * 3.32 (log2(10)) bits, plus some headroom.
    // We'll use digits * 4 bits for a safer margin.
    unsigned long precision_bits = (unsigned long)digits * 4;

    // Initialize GMP variables
    mpf_t pi, term, sum, one, inv_denom;

    // Set precision for all GMP floating-point numbers
    mpf_init2(pi, precision_bits);
    mpf_init2(term, precision_bits);
    mpf_init2(sum, precision_bits);
    mpf_init2(one, precision_bits);
    mpf_init2(inv_denom, precision_bits); // To store 1/denominator

    // Initialize sum to 0
    mpf_set_ui(sum, 0);

    // Initialize one to 1.0
    mpf_set_ui(one, 1);

    long long k;
    long long max_iterations;

    // The Leibniz formula converges very slowly.
    // To get 'digits' decimal places, you typically need on the order of 10^digits iterations.
    // For practical purposes in this example, we'll cap the iterations
    // or estimate them for a reasonable runtime, but be aware this will
    // likely _not_ reach the requested precision for high 'digits'.
    // A heuristic for 'n' terms for 'd' digits is about 0.5 * 10^d terms.
    // For digits = 6, 0.5 * 10^6 = 500,000 iterations.
    // For digits = 10, 0.5 * 10^10 = 5,000,000,000 iterations (impractical).

    // Let's set a practical max_iterations.
    // For small 'digits' (e.g., up to 7), 500,000 terms might give some result.
    // For higher 'digits', this formula is entirely impractical.
    // We'll use a fixed large number or one derived from digits if it's not too big.
    if (digits <= 7) {
        max_iterations = 5000000; // Enough for maybe 6-7 decimal places
    } else {
        printf("\nWarning: The Leibniz formula converges extremely slowly.\n");
        printf("         Calculating pi to %d decimal places will require an\n", digits);
        printf("         impractical number of iterations (billions+).\n");
        printf("         The calculation will be capped at 100,000,000 iterations.\n");
        printf("         You will likely not reach the requested precision.\n");
        max_iterations = 100000000; // Even this is very unlikely to reach 8+ digits
    }


    printf("Calculating pi using Leibniz formula to %d decimal places...\n", digits);
    printf("Max iterations: %lld\n", max_iterations);
    printf("This will take a very long time and may not reach the desired precision.\n");

    // Loop for iterations
    for (k = 0; k < max_iterations; k++) {
        // term = 1 / (2k + 1)
        // If k is even, term is positive. If k is odd, term is negative.

        // Calculate denominator: 2*k + 1
        mpf_set_ui(term, 2 * k + 1); // Using 'term' temporarily for denominator

        // Calculate 1 / (2k + 1)
        mpf_ui_div(inv_denom, 1, term); // inv_denom = 1 / (2k + 1)

        // Apply alternating sign
        if (k % 2 == 0) {
            // Add if k is even
            mpf_add(sum, sum, inv_denom);
        } else {
            // Subtract if k is odd
            mpf_sub(sum, sum, inv_denom);
        }

        // Optional: print progress for very large number of iterations
        if (max_iterations > 100000 && k % (max_iterations / 100) == 0 && k != 0) {
            printf("\rIteration %lld / %lld (%.2f%%)", k, max_iterations, (double)k / max_iterations * 100.0);
            fflush(stdout); // Ensure the output is printed immediately
        }
    }
    printf("\nCalculation finished after %lld iterations.\n", k);


    // pi = sum * 4
    mpf_mul_ui(pi, sum, 4);

    // Print the result.
    // mpf_out_str(stdout, base, n_digits, x) where n_digits is number of digits after decimal point.
    // Include extra digits for potential rounding issues and to show full precision.
    unsigned long output_digits = digits + 5; // Print a few extra digits

    printf("Calculated pi: ");
    mpf_out_str(stdout, 10, output_digits, pi);
    printf("\n");

    // Clear GMP variables to free memory
    mpf_clear(pi);
    mpf_clear(term);
    mpf_clear(sum);
    mpf_clear(one);
    mpf_clear(inv_denom);
}

int main() {
    int digits;

    printf("Enter the number of decimal places for pi (e.g., 5): ");
    if (scanf("%d", &digits) != 1 || digits <= 0) {
        printf("Invalid input. Please enter a positive integer.\n");
        return 1;
    }

    calculate_pi_leibniz(digits);

    return 0;
}

