}

#include <stdio.h>
#include <math.h>
#include <stdlib.h>

// Function to calculate pi using the Leibniz formula
long double calculate_pi(int terms) {
    long double pi = 0.0;
    long double sign = 1.0;
    long double denominator;

    for (int i = 0; i < terms; i++) {
        denominator = 2 * i + 1;
        pi += sign * (1.0 / denominator);
        sign *= -1; // Alternate the sign
    }

    return 4 * pi;
}

// Function to print pi to a specified number of decimal places
void print_pi(long double pi, int digits) {
    printf("pi = %.Lf\n", pi);
    if (digits > 0) {
        printf("pi to %d decimal places: %.0Lf", digits, pi);
        for (int i = 0; i < digits; i++) {
            pi *= 10.0L;
            int digit = (int)pi;
            printf("%d", digit);
            pi -= digit;
        }
        printf("\n");
    }
}

