#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <time.h>

#define PORT 8080
#define LOG_FILE "http_traffic.log"

// Ethernet header structure
struct ethheader {
    u_char  ether_dhost[6];    // Destination host address
    u_char  ether_shost[6];    // Source host address
    u_short ether_type;        // IP? ARP? RARP? etc
};

// Packet capture and logging function
void packet_handler(u_char *user, const struct pcap_pkthdr *header, const u_char *packet) {
    struct ethheader *eth = (struct ethheader *)packet;
    struct iphdr *ip = (struct iphdr *)(packet + sizeof(struct ethheader));
    struct tcphdr *tcp = (struct tcphdr *)(packet + sizeof(struct ethheader) + (ip->ihl * 4));

    // Check if packet is TCP and on port 8080
    if (ntohs(tcp->source) == PORT || ntohs(tcp->dest) == PORT) {
        char source_ip[INET_ADDRSTRLEN];
        char dest_ip[INET_ADDRSTRLEN];

        // Convert IP addresses to readable format
        inet_ntop(AF_INET, &(ip->saddr), source_ip, INET_ADDRSTRLEN);
        inet_ntop(AF_INET, &(ip->daddr), dest_ip, INET_ADDRSTRLEN);

        // Open log file
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return;
        }

        // Get current timestamp
        time_t now;
        time(&now);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0';  // Remove newline

        // Log packet details
        fprintf(log_file, "[%s] Packet Captured:\n", timestamp);
        fprintf(log_file, "  Source IP: %s:%d\n", source_ip, ntohs(tcp->source));
        fprintf(log_file, "  Destination IP: %s:%d\n", dest_ip, ntohs(tcp->dest));
        fprintf(log_file, "  Packet Length: %d bytes\n", header->len);
        fprintf(log_file, "  TCP Flags: 0x%02x\n", tcp->th_flags);
        fprintf(log_file, "----------------------------\n");

        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    char *device = NULL;
    char error_buffer[PCAP_ERRBUF_SIZE];
    pcap_t *handle;

    // Find network device
    device = pcap_lookupdev(error_buffer);
    if (device == NULL) {
        fprintf(stderr, "Error finding network device: %s\n", error_buffer);
        return 1;
    }

    // Open network device for packet capture
    handle = pcap_open_live(device, BUFSIZ, 1, 1000, error_buffer);
    if (handle == NULL) {
        fprintf(stderr, "Error opening device %s: %s\n", device, error_buffer);
        return 1;
    }

    // Compile and set filter for port 8080
    struct bpf_program filter;
    char filter_exp[50];
    snprintf(filter_exp, sizeof(filter_exp), "port %d", PORT);

    if (pcap_compile(handle, &filter, filter_exp, 0, PCAP_NETMASK_UNKNOWN) == -1) {
        fprintf(stderr, "Error compiling filter: %s\n", pcap_geterr(handle));
        return 1;
    }

    if (pcap_setfilter(handle, &filter) == -1) {
        fprintf(stderr, "Error setting filter: %s\n", pcap_geterr(handle));
        return 1;
    }

    printf("Capturing HTTP traffic on port %d...\n", PORT);
    printf("Logging to %s\n", LOG_FILE);

    // Start packet capture loop
    pcap_loop(handle, 0, packet_handler, NULL);

    // Cleanup
    pcap_freecode(&filter);
    pcap_close(handle);

    return 0;
}

