#include <linux/if_ether.h>

#define PORT 8080
#define BUFFER_SIZE 65536
#define LOG_FILE "http_traffic.log"

// Function to log data to file
void log_data(const char *data, size_t length, const char *src_ip, const char *dst_ip, int src_port, int dst_port) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now;
    time(&now);
    fprintf(log_file, "\n\n[%s] %s:%d -> %s:%d\n", ctime(&now), src_ip, src_port, dst_ip, dst_port);
    fwrite(data, 1, length, log_file);
    fclose(log_file);
}

// Function to process TCP packet
void process_tcp(const unsigned char *buffer, size_t length, const char *src_ip, const char *dst_ip) {
    struct tcphdr *tcp_header = (struct tcphdr *)(buffer);
    int src_port = ntohs(tcp_header->source);
    int dst_port = ntohs(tcp_header->dest);

    // Check if it's port 8080 (either source or destination)
    if (dst_port == PORT || src_port == PORT) {
        // Calculate payload offset
        int tcp_header_length = tcp_header->doff * 4;
        const unsigned char *payload = buffer + tcp_header_length;
        size_t payload_length = length - tcp_header_length;

        if (payload_length > 0) {
            printf("HTTP traffic detected: %s:%d -> %s:%d (%zu bytes)\n", 
                   src_ip, src_port, dst_ip, dst_port, payload_length);
            log_data((const char *)payload, payload_length, src_ip, dst_ip, src_port, dst_port);
        }
    }
}

int main() {
    int raw_socket;
    struct sockaddr saddr;
    socklen_t saddr_size = sizeof(saddr);
    unsigned char buffer[BUFFER_SIZE];

    // Create raw socket
    raw_socket = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (raw_socket < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    printf("Starting HTTP traffic logger on port %d...\n", PORT);
    printf("Logging to file: %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (1) {
        // Receive packet
        int packet_size = recvfrom(raw_socket, buffer, BUFFER_SIZE, 0, &saddr, &saddr_size);
        if (packet_size < 0) {
            perror("Packet receive failed");
            continue;
        }

        // Parse Ethernet header
        struct ethhdr *eth_header = (struct ethhdr *)buffer;

        // Check for IP packets
        if (ntohs(eth_header->h_proto) == ETH_P_IP) {
            // Parse IP header
            struct iphdr *ip_header = (struct iphdr *)(buffer + sizeof(struct ethhdr));

            // Convert IP addresses to strings
            char src_ip[INET_ADDRSTRLEN];
            char dst_ip[INET_ADDRSTRLEN];
            inet_ntop(AF_INET, &(ip_header->saddr), src_ip, INET_ADDRSTRLEN);
            inet_ntop(AF_INET, &(ip_header->daddr), dst_ip, INET_ADDRSTRLEN);

            // Check for TCP protocol
            if (ip_header->protocol == IPPROTO_TCP) {
                // Calculate IP header length
                int ip_header_length = ip_header->ihl * 4;

                // Process TCP packet
                process_tcp(buffer + sizeof(struct ethhdr) + ip_header_length, 
                           packet_size - sizeof(struct ethhdr) - ip_header_length,
                           src_ip, dst_ip);
            }
        }
    }

    close(raw_socket);
    return 0;
}

#include <pcap.h>       // For libpcap functions
