#include <netinet/ip.h>     // For struct iphdr
#include <netinet/tcp.h>    // For struct tcphdr
#include <sys/time.h>   // For gettimeofday

// Define the port to capture
#define TARGET_PORT 8080

// Callback function to process each packet
void packet_handler(u_char *user, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    // Current time for logging
    struct timeval tv;
    gettimeofday(&tv, NULL);

    printf("\n--- Packet Captured at %lu.%06lu ---\n", (long)tv.tv_sec, (long)tv.tv_usec);
    printf("Packet length: %d bytes\n", pkthdr->len);

    // --- Ethernet Header ---
    struct ethhdr *eth_header;
    eth_header = (struct ethhdr *)packet;
    // We expect IPv4 (0x0800)
    if (ntohs(eth_header->h_proto) != ETH_P_IP) {
        printf("  Not an IP packet (protocol: 0x%04x). Skipping...\n", ntohs(eth_header->h_proto));
        return;
    }

    // --- IP Header ---
    struct iphdr *ip_header;
    // IP header starts after Ethernet header (14 bytes)
    ip_header = (struct iphdr *)(packet + sizeof(struct ethhdr));

    // Ensure it's a TCP packet (IP protocol 6)
    if (ip_header->protocol != IPPROTO_TCP) {
        printf("  Not a TCP packet (IP protocol: %d). Skipping...\n", ip_header->protocol);
        return;
    }

    // --- TCP Header ---
    struct tcphdr *tcp_header;
    // TCP header starts after IP header. IP header length is in 4-byte words.
    tcp_header = (struct tcphdr *)(packet + sizeof(struct ethhdr) + ip_header->ihl * 4);

    int src_port = ntohs(tcp_header->source);
    int dst_port = ntohs(tcp_header->dest);

    // Check if source or destination port matches TARGET_PORT
    if (src_port == TARGET_PORT || dst_port == TARGET_PORT) {
        printf("  Source IP: %s\n", inet_ntoa(*(struct in_addr *)&ip_header->saddr));
        printf("  Destination IP: %s\n", inet_ntoa(*(struct in_addr *)&ip_header->daddr));
        printf("  Source Port: %d\n", src_port);
        printf("  Destination Port: %d\n", dst_port);

        // --- HTTP Data (Payload) ---
        // TCP header length is in 4-byte words
        int tcp_header_len = tcp_header->doff * 4;
        const u_char *payload = packet + sizeof(struct ethhdr) + ip_header->ihl * 4 + tcp_header_len;
        int payload_len = pkthdr->len - (sizeof(struct ethhdr) + ip_header->ihl * 4 + tcp_header_len);

        if (payload_len > 0) {
            printf("  Payload Length: %d bytes\n", payload_len);

            // Print the first few bytes of the payload
            printf("  Partial Payload (HTTP data):\n");
            for (int i = 0; i < payload_len && i < 200; i++) { // Print up to 200 bytes
                if (payload[i] >= 32 && payload[i] <= 126) { // Printable ASCII
                    printf("%c", payload[i]);
                } else {
                    printf("."); // Non-printable
                }
            }
            printf("\n");

            // For deeper analysis, you would typically look for "GET ", "POST ", "HTTP/1.1", etc.
            // This is where robust HTTP parsing would begin.
        } else {
            printf("  No payload in this TCP segment.\n");
        }

    } else {
        // Not traffic on port 8080, silently ignore
        // printf("  Not traffic on target port %d. Skipping...\n", TARGET_PORT);
    }
}

int main() {
    char *dev, errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;
    struct bpf_program fp;
    char filter_exp[100]; // Filter expression string
    bpf_u_int32 net;       // IP address and subnet mask of the device

    // 1. Find a default network device
    dev = pcap_lookupdev(errbuf);
    if (dev == NULL) {
        fprintf(stderr, "Couldn't find default device: %s\n", errbuf);
        return(2);
    }
    printf("Found default device: %s\n", dev);

    // 2. Lookup network for the device (optional, but good practice)
    if (pcap_lookupnet(dev, &net, &net, errbuf) == -1) {
        fprintf(stderr, "Couldn't get netmask for device %s: %s\n", dev, errbuf);
        net = 0; // Fallback to 0 if we can't get it
    }

    // 3. Open the device for capturing
    // Arguments: device, snaplen (max bytes per packet), promiscuous mode, timeout, error buffer
    handle = pcap_open_live(dev, BUFSIZ, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Couldn't open device %s: %s\n", dev, errbuf);
        return(2);
    }

    // 4. Compile the filter expression
    // We want all TCP traffic to or from port TARGET_PORT
    snprintf(filter_exp, sizeof(filter_exp), "tcp port %d", TARGET_PORT);
    if (pcap_compile(handle, &fp, filter_exp, 0, net) == -1) {
        fprintf(stderr, "Couldn't parse filter %s: %s\n", filter_exp, pcap_geterr(handle));
        return(2);
    }

    // 5. Apply the compiled filter
    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "Couldn't install filter %s: %s\n", filter_exp, pcap_geterr(handle));
        return(2);
    }

    printf("Capturing HTTP traffic on interface '%s' for port %d...\n", dev, TARGET_PORT);
    printf("Press Ctrl+C to stop.\n");

    // 6. Start the capture loop
    // Arguments: handle, num_packets_to_capture (0 for infinite), callback function, user argument
    pcap_loop(handle, 0, packet_handler, NULL);

    // 7. Cleanup
    pcap_freecode(&fp);
    pcap_close(handle);

    return(0);
}

#include <stdio.h>
#include <stdlib.h>
#include <pcap.h>
