#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>

#define HTTP_PORT 8080
#define SNAP_LEN 1518
#define MAX_PAYLOAD 512

// Ethernet header
struct ethheader {
    u_char ether_dhost[6];
    u_char ether_shost[6];
    u_short ether_type;
};

// TCP/IP packet handler
void packet_handler(u_char *args, const struct pcap_pkthdr *header, const u_char *packet) {
    const struct ethheader *ethernet;
    const struct ip *ip;
    const struct tcphdr *tcp;
    const u_char *payload;
    u_int ip_header_len;
    u_int tcp_header_len;
    u_int payload_len;

    ethernet = (struct ethheader*)packet;

    // Only process IP packets (EtherType = 0x0800)
    if (ntohs(ethernet->ether_type) != 0x0800)
        return;

    ip = (struct ip*)(packet + sizeof(struct ethheader));
    ip_header_len = ip->ip_hl * 4;

    // Only handle TCP
    if (ip->ip_p != IPPROTO_TCP)
        return;

    tcp = (struct tcphdr*)(packet + sizeof(struct ethheader) + ip_header_len);
    tcp_header_len = tcp->th_off * 4;

    // Check for HTTP port 8080 in src or dst
    if (ntohs(tcp->th_sport) != HTTP_PORT && ntohs(tcp->th_dport) != HTTP_PORT)
        return;

    payload = (u_char *)(packet + sizeof(struct ethheader) + ip_header_len + tcp_header_len);
    payload_len = header->caplen - (sizeof(struct ethheader) + ip_header_len + tcp_header_len);
    if (payload_len > 0) {
        char srcip[INET_ADDRSTRLEN], dstip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &(ip->ip_src), srcip, INET_ADDRSTRLEN);
        inet_ntop(AF_INET, &(ip->ip_dst), dstip, INET_ADDRSTRLEN);

        printf("\n[%s:%d -> %s:%d] len=%d\n", 
            srcip, ntohs(tcp->th_sport), 
            dstip, ntohs(tcp->th_dport), 
            payload_len);

        // Print first MAX_PAYLOAD bytes of payload (should be HTTP)
        int printlen = payload_len < MAX_PAYLOAD ? payload_len : MAX_PAYLOAD;
        for (int i = 0; i < printlen; i++)
            putchar(isprint(payload[i]) ? payload[i] : '.');
        putchar('\n');
    }
}

int main(int argc, char **argv) {
    char *dev;
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;
    struct bpf_program fp;
    char filter_exp[] = "tcp port 8080";
    bpf_u_int32 net;

    // Find a capture device if not specified on command-line
    if (argc == 2)
        dev = argv[1];
    else {
        dev = pcap_lookupdev(errbuf);
        if (dev == NULL) {
            fprintf(stderr, "Couldn't find default device: %s\n", errbuf);
            return 2;
        }
