// Function to process packets
void process_packet(u_char *args, const struct pcap_pkthdr *header, const u_char *packet) {
    struct ip *ip_header;
    struct tcphdr *tcp_header;
    const char *payload;
    int size_ip;
    int size_tcp;
    int size_payload;

    // Retrieve the IP header
    ip_header = (struct ip*)(packet + SIZE_ETHERNET);
    size_ip = ip_header->ip_hl * 4;

    // Retrieve the TCP header
    tcp_header = (struct tcphdr*)(packet + SIZE_ETHERNET + size_ip);
    size_tcp = tcp_header->th_off * 4;

    // Calculate the payload size
    payload = (u_char *)(packet + SIZE_ETHERNET + size_ip + size_tcp);
    size_payload = ntohs(ip_header->ip_len) - (size_ip + size_tcp);

    if (size_payload > 0) {
        printf("Packet Capture:\n");
        printf("Source IP: %s\n", inet_ntoa(ip_header->ip_src));
        printf("Destination IP: %s\n", inet_ntoa(ip_header->ip_dst));
        printf("Payload (%d bytes):\n", size_payload);

        fwrite(payload, size_payload, 1, stdout);
        printf("\n\n");
    }
}

