// Structure to store HTTP packet information
typedef struct {
    char src_ip[INET_ADDRSTRLEN];
    char dst_ip[INET_ADDRSTRLEN];
    char src_port[6];
    char dst_port[6];
    char method[10];
    char uri[256];
    char version[10];
} http_packet_t;

// Function to handle captured packets
void packet_handler(u_char *args, const struct pcap_pkthdr *header, const u_char *packet) {
    // Extract IP and TCP headers
    struct iphdr *ip_header = (struct iphdr *)(packet + 14);
    struct tcphdr *tcp_header = (struct tcphdr *)(packet + 14 + ip_header->ihl * 4);

    // Check if packet is HTTP (port 8080)
    if (ntohs(tcp_header->dest) == 8080 || ntohs(tcp_header->source) == 8080) {
        // Extract HTTP packet information
        http_packet_t http_packet;
        inet_ntop(AF_INET, &(ip_header->saddr), http_packet.src_ip, INET_ADDRSTRLEN);
        inet_ntop(AF_INET, &(ip_header->daddr), http_packet.dst_ip, INET_ADDRSTRLEN);
        sprintf(http_packet.src_port, "%d", ntohs(tcp_header->source));
        sprintf(http_packet.dst_port, "%d", ntohs(tcp_header->dest));

        // Extract HTTP request line
        const u_char *http_data = packet + 14 + ip_header->ihl * 4 + tcp_header->doff * 4;
        const u_char *request_line = memchr(http_data, '\r', header->len - (packet + 14 + ip_header->ihl * 4 + tcp_header->doff * 4 - packet));
        if (request_line) {
            char *request_line_str = (char *)malloc(request_line - http_data + 2);
            memcpy(request_line_str, http_data, request_line - http_data);
            request_line_str[request_line - http_data] = '\0';

            // Parse HTTP request line
            char *method = strtok(request_line_str, " ");
            char *uri = strtok(NULL, " ");
            char *version = strtok(NULL, " ");
            sprintf(http_packet.method, "%s", method);
            sprintf(http_packet.uri, "%s", uri);
            sprintf(http_packet.version, "%s", version);

            free(request_line_str);

            // Log HTTP packet
            printf("HTTP Packet:\n");
            printf("  Source IP: %s\n", http_packet.src_ip);
            printf("  Destination IP: %s\n", http_packet.dst_ip);
            printf("  Source Port: %s\n", http_packet.src_port);
            printf("  Destination Port: %s\n", http_packet.dst_port);
            printf("  Method: %s\n", http_packet.method);
            printf("  URI: %s\n", http_packet.uri);
            printf("  Version: %s\n", http_packet.version);
        }
    }
}

int main() {
    // Initialize pcap
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle = pcap_open_live("any", 65535, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "pcap_open_live: %s\n", errbuf);
