#define BUFFER_SIZE 65536

void log_packet(const char *buffer, int length) {
    // Assuming the buffer contains a valid IP packet
    const struct ip *ip_header = (struct ip *)buffer;
    const struct tcphdr *tcp_header = (struct tcphdr *)(buffer + ip_header->ip_hl * 4);
    int ip_header_length = ip_header->ip_hl * 4;
    int tcp_header_length = tcp_header->th_off * 4;
    int payload_length = length - ip_header_length - tcp_header_length;

    if (payload_length > 0) {
        printf("Source IP: %s\n", inet_ntoa(ip_header->ip_src));
        printf("Destination IP: %s\n", inet_ntoa(ip_header->ip_dst));
        printf("Source Port: %d\n", ntohs(tcp_header->th_sport));
        printf("Destination Port: %d\n", ntohs(tcp_header->th_dport));
        printf("Payload Length: %d\n", payload_length);
        printf("Payload: %.*s\n", payload_length, buffer + ip_header_length + tcp_header_length);
    }
}

int main() {
    int sock = socket(AF_INET, SOCK_RAW, IPPROTO_TCP);
    if (sock == -1) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Allow the socket to capture packets for all interfaces
    int one = 1;
    const int *val = &one;
    if (setsockopt(sock, IPPROTO_IP, IP_HDRINCL, val, sizeof(one)) == -1) {
        perror("Setsockopt failed");
        close(sock);
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in addr;
    socklen_t addr_len = sizeof(addr);
    memset(&addr, 0, addr_len);
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_ANY);
    addr.sin_port = htons(8080);

    while (1) {
        char buffer[BUFFER_SIZE];
        int length = recvfrom(sock, buffer, BUFFER_SIZE, 0, (struct sockaddr *)&addr, &addr_len);
        if (length > 0) {
            log_packet(buffer, length);
        }
    }

    close(sock);
    return 0;
}

