// Function to convert a single character to its corresponding phone digit
char letterToDigit(char letter) {
    letter = toupper(letter); // Convert to uppercase for simplicity
    if (letter >= 'A' && letter <= 'C') return '2';
    if (letter >= 'D' && letter <= 'F') return '3';
    if (letter >= 'G' && letter <= 'I') return '4';
    if (letter >= 'J' && letter <= 'L') return '5';
    if (letter >= 'M' && letter <= 'O') return '6';
    if (letter >= 'P' && letter <= 'S') return '7';
    if (letter >= 'T' && letter <= 'V') return '8';
    if (letter >= 'W' && letter <= 'Z') return '9';
    return ' '; // Return space for non-letter characters
}

// Function to convert a name to phone dial format
void nameToPhoneDial(const char *name, char *phoneDial) {
    int i, j = 0;
    for (i = 0; name[i] != '\0'; i++) {
        if (isalpha(name[i])) {
            phoneDial[j++] = letterToDigit(name[i]);
        } else if (name[i] == ' ') {
            phoneDial[j++] = ' '; // Preserve spaces
        }
    }
    phoneDial[j] = '\0'; // Null terminate the string
}

