/**
 * @brief Cleans a string by converting to lowercase and keeping only
 *        alphanumeric characters.
 * @param dest The buffer where the cleaned string will be stored.
 * @param src The source string to clean.
 */
void cleanString(char *dest, const char *src) {
    int i = 0;
    int j = 0;

    // Filter out non-alphanumeric characters and convert to lowercase
    while (src[i] != '\0' && j < MAX_CLEAN_LENGTH - 1) {
        if (isalnum((unsigned char)src[i])) { // Check if it's alphanumeric
            dest[j++] = tolower((unsigned char)src[i]); // Convert to lowercase and add
        }
        i++;
    }
    dest[j] = '\0'; // Null-terminate the cleaned string
}

/**
 * @brief Checks if a string is a palindrome (case-insensitive, ignoring non-alphanumeric).
 * @param str The string to check.
 * @return 1 if the string is a palindrome, 0 otherwise.
 */
int isPalindrome(const char *str) {
    char cleaned_str[MAX_CLEAN_LENGTH];
    cleanString(cleaned_str, str);

    int length = strlen(cleaned_str);
    if (length == 0) {
        return 0; // An empty string or a string with only non-alphanumeric chars is not a palindrome for this purpose
    }

    int left = 0;
    int right = length - 1;

    while (left < right) {
        if (cleaned_str[left] != cleaned_str[right]) {
            return 0; // Not a palindrome
        }
        left++;
        right--;
    }
    return 1; // It's a palindrome
}

