// Function to generate a random hexadecimal digit
char random_hex_digit() {
    int r = rand() % 16;
    if (r < 10) {
        return r + '0';
    } else {
        return (r - 10) + 'a';
    }
}

// Function to generate a UUID
void generate_uuid(char* uuid) {
    // Set the version (4) and variant (8, 9, A, or B)
    uuid[8] = '-';
    uuid[13] = '-';
    uuid[18] = '-';
    uuid[23] = '-';

    // Generate random hex digits
    for (int i = 0; i < 36; i++) {
        if (i == 8 || i == 13 || i == 18 || i == 23) {
            continue;  // Skip the separator positions
        }
        uuid[i] = random_hex_digit();
    }

    // Set version 4 UUID specific bits
    uuid[14] = '4';  // Version 4

    // Set variant bits (bit 7 of the 8th group)
    switch (rand() % 4) {
        case 0:
            uuid[19] = '8';
            break;
        case 1:
            uuid[19] = '9';
            break;
        case 2:
            uuid[19] = 'a';
            break;
        case 3:
            uuid[19] = 'b';
            break;
    }

    // Null-terminate the string
    uuid[36] = '\0';
}

