#include <stdio.h>   // For printf, snprintf
#include <stdlib.h>  // For rand, srand
#include <time.h>    // For time (to seed srand)
#include <stdint.h>  // For uint8_t
#include <string.h>  // Not strictly needed for this version, but often useful with strings

// Define the required length for the UUID string buffer.
// 32 hexadecimal characters + 4 hyphens + 1 null terminator = 37 characters.
#define UUID_STRING_LEN 37

/**
 * @brief Generates a random UUID (version 4) and stores it in the provided string buffer.
 *
 * The UUID is generated as a string in the standard format: xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx.
 *
 * @param uuid_str A character array (buffer) of at least UUID_STRING_LEN bytes
 *                 where the generated UUID string will be stored.
 */
void generate_uuid(char *uuid_str) {
    uint8_t uuid_bytes[16]; // A UUID is 128 bits, or 16 bytes.

    // 1. Generate 16 random bytes.
    for (int i = 0; i < 16; i++) {
        uuid_bytes[i] = (uint8_t)(rand() % 256); // Generate random number from 0 to 255
    }

    // 2. Set UUID version 4 specific bits (UUID V4 is based on random numbers).
    // The 13th hexadecimal digit (first digit of the third group) must be '4'.
    // This corresponds to the 4 most significant bits of uuid_bytes[6].
    // We clear the top 4 bits and set them to 0100 (binary), which is 0x40.
    uuid_bytes[6] = (uuid_bytes[6] & 0x0F) | 0x40;

    // 3. Set UUID variant bits (RFC 4122 variant).
    // The 17th hexadecimal digit (first digit of the fourth group) must be
    // one of '8', '9', 'A', or 'B'.
    // This corresponds to the 2 most significant bits of uuid_bytes[8].
    // We clear the top 2 bits and set them to 10 (binary), which is 0x80.
    uuid_bytes[8] = (uuid_bytes[8] & 0x3F) | 0x80;

    // 4. Format the UUID as a string.
    // %02x prints a byte as two hexadecimal digits, padding with a leading zero if necessary.
    snprintf(uuid_str, UUID_STRING_LEN,
             "%02x%02x%02x%02x-"    // Bytes 0-3
             "%02x%02x-"          // Bytes 4-5
             "%02x%02x-"          // Bytes 6-7 (version byte is uuid_bytes[6])
             "%02x%02x-"          // Bytes 8-9 (variant byte is uuid_bytes[8])
             "%02x%02x%02x%02x%02x%02x", // Bytes 10-15
             uuid_bytes[0], uuid_bytes[1], uuid_bytes[2], uuid_bytes[3],
             uuid_bytes[4], uuid_bytes[5],
             uuid_bytes[6], uuid_bytes[7],
             uuid_bytes[8], uuid_bytes[9],
             uuid_bytes[10], uuid_bytes[11], uuid_bytes[12], uuid_bytes[13], uuid_bytes[14], uuid_bytes[15]);
}

int main() {
    // Seed the random number generator once at the beginning of the program.
    // Using time(NULL) provides a different seed each second, making the UUIDs vary.
    srand((unsigned int)time(NULL));

    char uuid[UUID_STRING_LEN]; // Declare a buffer to hold the UUID string

    // Generate and print a UUID
    generate_uuid(uuid);
    printf("Generated UUID: %s\n", uuid);

    // You can generate multiple UUIDs if needed:
    // for (int i = 0; i < 3; ++i) {
    //     generate_uuid(uuid);
    //     printf("Another UUID: %s\n", uuid);
    // }

    return 0;
}

