void generate_uuid(char *uuid) {
    const char *hex_digits = "0123456789abcdef";
    int i;

    for (i = 0; i < 36; i++) {
        switch(i) {
            case 8:
            case 13:
            case 18:
            case 23:
                uuid[i] = '-';
                break;
            case 14:
                uuid[i] = '4';  // Set the version to 4 -- signifies the UUID version
