#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <limits.h>

#define BOARD_SIZE 3

// Representation of game board
char board[BOARD_SIZE][BOARD_SIZE];

// Player and AI symbols
const char PLAYER = 'X';
const char AI = 'O';

// Function prototypes
void initializeBoard();
void displayBoard();
bool isMoveValid(int row, int col);
bool isBoardFull();
char checkWinner();
int minimax(char board[BOARD_SIZE][BOARD_SIZE], int depth, bool isMaximizing);
void getAIMove(int* row, int* col);
void playerMove();
void playGame();

// Initialize the board with empty spaces
void initializeBoard() {
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            board[i][j] = ' ';
        }
    }
}

// Display the current board state
void displayBoard() {
    printf("\n");
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            printf(" %c ", board[i][j]);
            if (j < BOARD_SIZE - 1) printf("|");
        }
        printf("\n");
        if (i < BOARD_SIZE - 1) printf("---+---+---\n");
    }
    printf("\n");
}

// Check if a move is valid
bool isMoveValid(int row, int col) {
    return (row >= 0 && row < BOARD_SIZE && 
            col >= 0 && col < BOARD_SIZE && 
            board[row][col] == ' ');
}

// Check if the board is full
bool isBoardFull() {
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[i][j] == ' ') return false;
        }
    }
    return true;
}

// Check for a winner
char checkWinner() {
    // Check rows
    for (int i = 0; i < BOARD_SIZE; i++) {
        if (board[i][0] == board[i][1] && board[i][1] == board[i][2] && board[i][0] != ' ')
            return board[i][0];
    }

    // Check columns
    for (int j = 0; j < BOARD_SIZE; j++) {
        if (board[0][j] == board[1][j] && board[1][j] == board[2][j] && board[0][j] != ' ')
            return board[0][j];
    }

    // Check diagonals
    if (board[0][0] == board[1][1] && board[1][1] == board[2][2] && board[0][0] != ' ')
        return board[0][0];
    if (board[0][2] == board[1][1] && board[1][1] == board[2][0] && board[0][2] != ' ')
        return board[0][2];

    return ' ';
}

// Minimax algorithm for AI move
int minimax(char board[BOARD_SIZE][BOARD_SIZE], int depth, bool isMaximizing) {
    char result = checkWinner();

    // Scoring
    if (result == AI) return 10 - depth;
    if (result == PLAYER) return depth - 10;
    if (isBoardFull()) return 0;

    if (isMaximizing) {
        int bestScore = INT_MIN;
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == ' ') {
                    board[i][j] = AI;
                    int score = minimax(board, depth + 1, false);
                    board[i][j] = ' ';
                    bestScore = (score > bestScore) ? score : bestScore;
                }
            }
        }
        return bestScore;
    } else {
        int bestScore = INT_MAX;
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == ' ') {
                    board[i][j] = PLAYER;
                    int score = minimax(board, depth + 1, true);
                    board[i][j] = ' ';
                    bestScore = (score < bestScore) ? score : bestScore;
                }
            }
        }
        return bestScore;
    }
}

// Get AI's best move using Minimax
void getAIMove(int* row, int* col) {
    int bestScore = INT_MIN;

    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[i][j] == ' ') {
                board[i][j] = AI;
                int score = minimax(board, 0, false);
                board[i][j] = ' ';

                if (score > bestScore) {
                    bestScore = score;
                    *row = i;
                    *col = j;
                }
            }
        }
    }
}

// Player's move input
void playerMove() {
    int row, col;

    do {
        printf("Enter your move (row [0-2] column [0-2]): ");
        scanf("%d %d", &row, &col);
    } while (!isMoveValid(row, col));

    board[row][col] = PLAYER;
}

// Main game loop
void playGame() {
    char winner;
    bool playerTurn = true;

    initializeBoard();

    while (true) {
        displayBoard();

        if (playerTurn) {
            playerMove();
            playerTurn = false;
        } else {
            int row, col;
            getAIMove(&row, &col);
            board[row][col] = AI;
            printf("AI chooses: %d %d\n", row, col);
            playerTurn = true;
        }

        winner = checkWinner();
        if (winner != ' ' || isBoardFull()) break;
    }

    displayBoard();

    if (winner == PLAYER) printf("You win!\n");
    else if (winner == AI) printf("AI wins!\n");
    else printf("It's a draw!\n");
}

int main() {
    srand(time(NULL));
    playGame();
    return 0;
}

