// Define constants for players and board state
#define PLAYER_X 'X'
#define PLAYER_O 'O'
#define EMPTY ' '

// Board size
#define BOARD_SIZE 3

// Global board
char board[BOARD_SIZE][BOARD_SIZE];

// Function prototypes
void initializeBoard();
void printBoard();
bool isBoardFull();
bool checkWin(char player);
int minimax(int depth, bool isMaximizingPlayer);
void findBestMove(int *row, int *col);
void getPlayerMove(int *row, int *col);

int main() {
    initializeBoard();
    printf("Welcome to Tic Tac Toe!\n");
    printf("You are '%c', the AI is '%c'.\n", PLAYER_X, PLAYER_O);
    printBoard();

    char currentPlayer = PLAYER_X; // User starts

    while (true) {
        if (currentPlayer == PLAYER_X) {
            // User's turn
            int row, col;
            getPlayerMove(&row, &col);
            board[row][col] = PLAYER_X;
        } else {
            // AI's turn
            int bestRow, bestCol;
            printf("AI is thinking...\n");
            findBestMove(&bestRow, &bestCol);
            board[bestRow][bestCol] = PLAYER_O;
            printf("AI placed '%c' at (%d, %d)\n", PLAYER_O, bestRow + 1, bestCol + 1);
        }

        printBoard();

        if (checkWin(currentPlayer)) {
            printf("Player %c wins!\n", currentPlayer);
            break;
        }

        if (isBoardFull()) {
            printf("It's a draw!\n");
            break;
        }

        // Switch turns
        currentPlayer = (currentPlayer == PLAYER_X) ? PLAYER_O : PLAYER_X;
    }

    return 0;
}

// Initialize the board with empty spaces
void initializeBoard() {
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            board[i][j] = EMPTY;
        }
    }
}

// Print the current state of the board
void printBoard() {
    printf("\n");
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            printf(" %c ", board[i][j]);
            if (j < BOARD_SIZE - 1) {
                printf("|");
            }
        }
        printf("\n");
        if (i < BOARD_SIZE - 1) {
            printf("---+---+---\n");
        }
    }
    printf("\n");
}

// Check if the board is full
bool isBoardFull() {
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[i][j] == EMPTY) {
                return false;
            }
        }
    }
    return true;
}

// Check if a player has won
bool checkWin(char player) {
    // Check rows
    for (int i = 0; i < BOARD_SIZE; i++) {
        if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
            return true;
        }
    }

    // Check columns
    for (int j = 0; j < BOARD_SIZE; j++) {
        if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
            return true;
        }
    }

    // Check diagonals
    if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
        return true;
    }
    if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
        return true;
    }

    return false;
}

// Minimax algorithm to find the optimal move
// depth: current depth of the search tree
// isMaximizingPlayer: true if it's the AI's turn (maximizing player), false if it's the user's turn (minimizing player)
int minimax(int depth, bool isMaximizingPlayer) {
    // Base cases
    if (checkWin(PLAYER_O)) { // AI wins
        return 10 - depth; // Prioritize quicker wins
    }
    if (checkWin(PLAYER_X)) { // User wins
        return -10 + depth; // Prioritize quicker losses (from AI's perspective)
    }
    if (isBoardFull()) { // Draw
        return 0;
    }

    if (isMaximizingPlayer) {
        int bestScore = INT_MIN;
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == EMPTY) {
                    board[i][j] = PLAYER_O; // Make the move
                    bestScore = (bestScore > minimax(depth + 1, false)) ? bestScore : minimax(depth + 1, false);
                    board[i][j] = EMPTY; // Undo the move (backtrack)
                }
            }
        }
        return bestScore;
    } else {
        int bestScore = INT_MAX;
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == EMPTY) {
                    board[i][j] = PLAYER_X; // Make the move
                    bestScore = (bestScore < minimax(depth + 1, true)) ? bestScore : minimax(depth + 1, true);
                    board[i][j] = EMPTY; // Undo the move (backtrack)
                }
            }
        }
        return bestScore;
    }
}

// Find the best move for the AI using minimax
void findBestMove(int *row, int *col) {
    int bestScore = INT_MIN;
    *row = -1;
    *col = -1;

    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[i][j] == EMPTY) {
                board[i][j] = PLAYER_O; // Try this move for the AI
                int currentScore = minimax(0, false); // Calculate score for this move
                board[i][j] = EMPTY; // Undo the move

                if (currentScore > bestScore) {
                    bestScore = currentScore;
                    *row = i;
                    *col = j;
                }
            }
        }
    }
}

// Get user's move input
void getPlayerMove(int *row, int *col) {
    int r, c;
    while (true) {
        printf("Enter your move (row column, e.g., 1 2): ");
        if (scanf("%d %d", &r, &c) != 2) {
            printf("Invalid input. Please enter two numbers.\n");
            // Clear input buffer
            while (getchar() != '\n');
            continue;
        }

        // Adjust to 0-indexed
        r--;
        c--;

        if (r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE && board[r][c] == EMPTY) {
            *row = r;
            *col = c;
            break;
        } else {
            printf("Invalid move. That cell is either out of bounds or already taken. Try again.\n");
        }
    }
}

