    }
    printf("\n");
}

// Check winner, returns 'X', 'O', or ' ' (no winner)
char checkWinner(char board[3][3]) {
    // Rows and Columns
    for (int i = 0; i < 3; i++) {
        if (board[i][0] == board[i][1] && board[i][1] == board[i][2] && board[i][0] != EMPTY)
            return board[i][0];
        if (board[0][i] == board[1][i] && board[1][i] == board[2][i] && board[0][i] != EMPTY)
            return board[0][i];
    }
    // Diagonals
    if (board[0][0] == board[1][1] && board[1][1] == board[2][2] && board[0][0] != EMPTY)
        return board[0][0];
    if (board[0][2] == board[1][1] && board[1][1] == board[2][0] && board[0][2] != EMPTY)
        return board[0][2];
    return EMPTY;
}

bool isMovesLeft(char board[3][3]) {
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++)
            if (board[i][j] == EMPTY)
                return true;
    return false;
}

// Evaluate score: +10 for AI win, -10 for player win, 0 otherwise
int evaluate(char board[3][3]) {
    char winner = checkWinner(board);
    if (winner == AI)
        return +10;
    else if (winner == PLAYER)
        return -10;
    else
        return 0;
}

// Minimax algorithm
int minimax(char board[3][3], bool isMaximizing) {
    int score = evaluate(board);
    if (score == 10 || score == -10)
        return score;
    if (!isMovesLeft(board))
        return 0;

    if (isMaximizing) {
        int best = INT_MIN;
        for (int i = 0; i < 3; i++)
            for (int j = 0; j < 3; j++)
                if (board[i][j] == EMPTY) {
                    board[i][j] = AI;
                    best = (best > minimax(board, false)) ? best : minimax(board, false);
                    board[i][j] = EMPTY;
                }
        return best;
    } else {
        int best = INT_MAX;
        for (int i = 0; i < 3; i++)
            for (int j = 0; j < 3; j++)
                if (board[i][j] == EMPTY) {
                    board[i][j] = PLAYER;
                    best = (best < minimax(board, true)) ? best : minimax(board, true);
                    board[i][j] = EMPTY;
                }
        return best;
    }
}

// Find the best move for computer
void findBestMove(char board[3][3], int *bestRow, int *bestCol) {
    int bestVal = INT_MIN;
    *bestRow = -1;
    *bestCol = -1;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            if (board[i][j] == EMPTY) {
                board[i][j] = AI;
                int moveVal = minimax(board, false);
                board[i][j] = EMPTY;
                if (moveVal > bestVal) {
                    *bestRow = i;
                    *bestCol = j;
                    bestVal = moveVal;
                }
            }
        }
    }
}

void userMove(char board[3][3]) {
    int row, col;
    while (true) {
        printf("Enter your move (row and col: 1-3 1-3): ");
        if (scanf("%d%d", &row, &col) != 2) {
