        }
        row--; col--;
        if (row < 0 || row > 2 || col < 0 || col > 2 || board[row][col] != EMPTY) {
            printf("Invalid move! Try again.\n");
        } else {
            board[row][col] = PLAYER;
            break;
        }
    }
}

void playGame() {
    char board[3][3];
    // Init
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++)
            board[i][j] = EMPTY;

    printf("You are 'O', computer is 'X'.\n");
    printf("Board positions are row col (1-3 1-3)\n");
    printBoard(board);

    while (true) {
        userMove(board);
        printBoard(board);

        if (checkWinner(board) == PLAYER) {
            printf("Congratulations! You won!\n");
            break;
        }
        if (!isMovesLeft(board)) {
            printf("It's a draw!\n");
            break;
        }

        int aiRow, aiCol;
        findBestMove(board, &aiRow, &aiCol);
        board[aiRow][aiCol] = AI;
        printf("Computer played at %d %d\n", aiRow+1, aiCol+1);
        printBoard(board);

        if (checkWinner(board) == AI) {
            printf("Computer wins!\n");
            break;
        }
        if (!isMovesLeft(board)) {
            printf("It's a draw!\n");
            break;
        }
    }
}

