            return -10;
    }

    // Return 0 if no one has won yet
    return 0;
}

int minimax(char board[3][3], int depth, int isMax) {
    int score = evaluate(board);

    // If AI has won the game
    if (score == 10)
        return score - depth;

    // If the player has won the game
    if (score == -10)
        return score + depth;

    // If there are no more moves and no winner
    if (!isMovesLeft(board))
        return 0;

    // If it's the AI's move
    if (isMax) {
        int best = INT_MIN;

        // Traverse all cells
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                // Check if cell is empty
                if (board[i][j] == EMPTY) {
                    // Make the move
                    board[i][j] = AI;

                    // Call minimax recursively and choose the maximum value
                    best = (best > minimax(board, depth + 1, !isMax)) ? best : minimax(board, depth + 1, !isMax);

                    // Undo the move
                    board[i][j] = EMPTY;
                }
            }
        }
        return best;
    }
    // If it's the player's move
    else {
        int best = INT_MAX;

        // Traverse all cells
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                // Check if cell is empty
                if (board[i][j] == EMPTY) {
                    // Make the move
                    board[i][j] = PLAYER;

                    // Call minimax recursively and choose the minimum value
                    best = (best < minimax(board, depth + 1, !isMax)) ? best : minimax(board, depth + 1, !isMax);

                    // Undo the move
                    board[i][j] = EMPTY;
                }
            }
        }
        return best;
    }
}

// This will determine the AI's move by analyzing all possible next moves
void findBestMove(char board[3][3], int *bestMoveRow, int *bestMoveCol) {
    int bestVal = INT_MIN;
    *bestMoveRow = -1;
    *bestMoveCol = -1;

    // Traverse all cells, evaluate the minimax function for all empty cells
    // and return the cell with the optimal value
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            // Check if cell is empty
            if (board[i][j] == EMPTY) {
                // Make the move
                board[i][j] = AI;

                // compute evaluation function for this move
                int moveVal = minimax(board, 0, 0);

                // Undo the move
                board[i][j] = EMPTY;

                // If the value of the current move is more than the best value, then update best 
                if (moveVal > bestVal) {
                    *bestMoveRow = i;
                    *bestMoveCol = j;
                    bestVal = moveVal;
                }
            }
        }
    }
}

