    bestMove[1] = -1;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            if (board[i][j] == EMPTY) {
                board[i][j] = AI;
                int moveVal = minimax(0, 0);
                board[i][j] = EMPTY; // Undo move
                if (moveVal > bestVal) {
                    bestMove[0] = i;
                    bestMove[1] = j;
                    bestVal = moveVal;
                }
            }
        }
    }
}

// Main game loop
int main() {
    int x, y;
    initializeBoard();
    printBoard();

    while (1) {
        // User's turn
        printf("Enter your move (row and column): ");
        scanf("%d %d", &x, &y);
        if (x < 0 || x > 2 || y < 0 || y > 2 || board[x][y] != EMPTY) {
            printf("Invalid move. Try again.\n");
            continue;
        }
        board[x][y] = PLAYER;
        printBoard();

        if (checkWinner() == PLAYER) {
            printf("You win!\n");
            break;
        }
        if (isBoardFull()) {
            printf("It's a tie!\n");
            break;
        }

        // AI's turn
        int bestMove[2];
