        board[bestMove[0]][bestMove[1]] = AI;
        printf("AI chose: %d %d\n", bestMove[0], bestMove[1]);
        printBoard();

        if (checkWinner() == AI) {
            printf("AI wins!\n");
            break;
        }
        if (isBoardFull()) {
            printf("It's a tie!\n");
            break;
        }
    }

    return 0;
}

