#define SIZE 3

// Function to draw the game board
void drawBoard(char board[SIZE][SIZE]) {
    printf(" %c | %c | %c\n", board[0][0], board[0][1], board[0][2]);
    printf("---+---+---\n");
    printf(" %c | %c | %c\n", board[1][0], board[1][1], board[1][2]);
    printf("---+---+---\n");
    printf(" %c | %c | %c\n", board[2][0], board[2][1], board[2][2]);
}

// Function to check if the game is won
int isWon(char board[SIZE][SIZE], char player) {
    // Check rows and columns
    for (int i = 0; i < SIZE; i++) {
        if (board[i][0] == player && board[i][1] == player && board[i][2] == player)
            return 1;
        if (board[0][i] == player && board[1][i] == player && board[2][i] == player)
            return 1;
    }
    // Check diagonals
    if ((board[0][0] == player && board[1][1] == player && board[2][2] == player) ||
        (board[0][2] == player && board[1][1] == player && board[2][0] == player))
        return 1;
    return 0;
}

// Function to check if the game is a draw
int isDraw(char board[SIZE][SIZE]) {
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            if (board[i][j] == ' ')
                return 0;
        }
    }
    return 1;
}

// Minimax function
int minimax(char board[SIZE][SIZE], int depth, int isMaximizing) {
    if (isWon(board, 'X'))
        return -10 + depth;
    if (isWon(board, 'O'))
        return 10 - depth;
    if (isDraw(board))
        return 0;

    if (isMaximizing) {
        int bestScore = -100;
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (board[i][j] == ' ') {
                    board[i][j] = 'O';
                    int score = minimax(board, depth + 1, 0);
                    board[i][j] = ' ';
                    bestScore = (score > bestScore) ? score : bestScore;
                }
            }
        }
        return bestScore;
    } else {
        int bestScore = 100;
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (board[i][j] == ' ') {
                    board[i][j] = 'X';
                    int score = minimax(board, depth + 1, 1);
                    board[i][j] = ' ';
                    bestScore = (score < bestScore) ? score : bestScore;
                }
            }
        }
        return bestScore;
    }
}

// Function to get the computer's move using Minimax
void getComputerMove(char board[SIZE][SIZE]) {
    int bestScore = -100;
    int bestMoveI, bestMoveJ;
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            if (board[i][j] == ' ') {
                board[i][j] = 'O';
                int score = minimax(board, 0, 0);
                board[i][j] = ' ';
                if (score > bestScore) {
                    bestScore = score;
                    bestMoveI = i;
                    bestMoveJ = j;
                }
            }
        }
    }
    board[bestMoveI][bestMoveJ] = 'O';
}

int main() {
    char board[SIZE][SIZE] = {{' ', ' ', ' '},
                              {' ', ' ', ' '},
                              {' ', ' ', ' '}};
    int playerMove;
    while (1) {
        drawBoard(board);
        printf("Enter your move (1-9): ");
        scanf("%d", &playerMove);
        if (playerMove < 1 || playerMove > 9) {
            printf("Invalid move. Please enter a number between 1 and 9.\n");
            continue;
        }
        int i = (playerMove - 1) / 3;
        int j = (playerMove - 1) % 3;
        if (board[i][j] != ' ') {
            printf("Invalid move. Position already occupied.\n");
            continue;
        }
        board[i][j] = 'X';
        if (isWon(board, 'X')) {
            drawBoard(board);
            printf("You win!\n");
            break;
        }
        if (isDraw(board)) {
            drawBoard(board);
            printf("It's a draw!\n");
            break;
        }
        getComputerMove(board);
        if (isWon(board, 'O')) {
            drawBoard(board);
            printf("Computer wins!\n");
            break;
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define PLAYER 'X'
#define AI 'O'
#define EMPTY ' '

char board[3][3];

// Function to initialize the board
void initializeBoard() {
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            board[i][j] = EMPTY;
        }
    }
}

// Function to print the board
void printBoard() {
    printf("-------------\n");
    for (int i = 0; i < 3; i++) {
        printf("| %c | %c | %c |\n", board[i][0], board[i][1], board[i][2]);
        printf("-------------\n");
    }
}

// Function to check if the board is full
int isBoardFull() {
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            if (board[i][j] == EMPTY) {
                return 0;
            }
        }
    }
    return 1;
}

// Function to check if a player has won
int checkWin(char player) {
    // Check rows
    for (int i = 0; i < 3; i++) {
        if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
            return 1;
        }
    }
    // Check columns
    for (int j = 0; j < 3; j++) {
        if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
            return 1;
        }
    }
    // Check diagonals
    if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
        return 1;
    }
    if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
        return 1;
    }
    return 0;
}

// Function to evaluate the board
int evaluate() {
    if (checkWin(PLAYER)) {
        return -10;
    } else if (checkWin(AI)) {
        return 10;
    } else {
        return 0;
    }
}

// Function to check if a move is valid
int isMoveValid(int x, int y) {
    if (x < 0 || x > 2 || y < 0 || y > 2 || board[x][y] != EMPTY) {
        return 0;
    }
    return 1;
}

// Minimax function
int minimax(int depth, int isMax) {
    int score = evaluate();

    if (score == 10) {
        return score - depth;
    }
    if (score == -10) {
        return score + depth;
    }
    if (isBoardFull()) {
        return 0;
    }

    if (isMax) {
        int best = -INT_MAX;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (board[i][j] == EMPTY) {
                    board[i][j] = AI;
                    best = (best > minimax(depth + 1, !isMax) ? best : minimax(depth + 1, !isMax));
                    board[i][j] = EMPTY;
                }
            }
        }
        return best;
    } else {
        int best = INT_MAX;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (board[i][j] == EMPTY) {
                    board[i][j] = PLAYER;
                    best = (best < minimax(depth + 1, !isMax) ? best : minimax(depth + 1, !isMax));
                    board[i][j] = EMPTY;
                }
            }
        }
        return best;
    }
}

// Function to find the best move for AI
void findBestMove() {
    int bestVal = -INT_MAX;
    int moveRow = -1, moveCol = -1;

    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            if (board[i][j] == EMPTY) {
                board[i][j] = AI;
                int moveVal = minimax(0, 0);
                board[i][j] = EMPTY;

                if (moveVal > bestVal) {
                    moveRow = i;
                    moveCol = j;
                    bestVal = moveVal;
                }
            }
        }
    }

    board[moveRow][moveCol] = AI;
}

// Function to take user input
void userMove() {
    int x, y;
    printf("Enter your move (row and column): ");
    scanf("%d %d", &x, &y);

    if (isMoveValid(x, y)) {
        board[x][y] = PLAYER;
    } else {
        printf("Invalid move. Try again.\n");
        userMove();
    }
}

// Main function
int main() {
    initializeBoard();
    printBoard();

    while (1) {
        userMove();
        printBoard();
        if (checkWin(PLAYER)) {
            printf("You win!\n");
            break;
        }
        if (isBoardFull()) {
            printf("It's a draw!\n");
            break;
        }

        findBestMove();
        printBoard();
        if (checkWin(AI)) {
            printf("AI wins!\n");
            break;
        }
        if (isBoardFull()) {
            printf("It's a draw!\n");
            break;
        }
    }

    return 0;
}

