}

// Function to count words in a single line
int count_words_in_line(char *line) {
    int word_count = 0;
    int in_word = 0;

    for (int i = 0; line[i] != '\0'; i++) {
        // If current character is a word character
        if (is_word_char(line[i])) {
            if (!in_word) {
                // Start of a new word
                word_count++;
                in_word = 1;
            }
        } else {
            // Not a word character, mark as outside a word
            in_word = 0;
        }
    }

    return word_count;
}

