#include <stdio.h> // For file operations (fopen, fclose, fgetc) and standard I/O (printf)
#include <stdbool.h> // For boolean type (true/false)

// Function to count words in a given file
long count_words(const char *filename) {
    FILE *file; // Pointer to the file
    long word_count = 0; // Initialize word count to 0
    int c; // To store each character read from the file
    bool in_word = false; // Flag to track if currently inside a word

    // Open the file in read mode ("r")
    file = fopen(filename, "r");

    // Check if the file opened successfully
    if (file == NULL) {
        perror("Error opening file"); // Print an error message if opening fails
        return -1; // Return -1 to indicate an error
    }

    // Loop through the file character by character until the end of the file (EOF) is reached
    while ((c = fgetc(file)) != EOF) {
        // Check if the current character is a whitespace character
        // We consider space, newline, tab, carriage return, form feed as word delimiters
        if (c == ' ' || c == '\n' || c == '\t' || c == '\r' || c == '\f') {
            // If we were inside a word and now encounter a whitespace, it means a word has ended
            if (in_word) {
                in_word = false; // Set in_word to false as we are no longer in a word
            }
        } else {
            // If the current character is not a whitespace
            // And we were not previously in a word, it means a new word has started
            if (!in_word) {
                in_word = true; // Set in_word to true
                word_count++;   // Increment the word count
            }
            // If already in a word, just continue as part of the same word
        }
    }

    // Close the file
    fclose(file);

    return word_count; // Return the total word count
}

int main() {
    const char *filename = "input.log"; // Define the name of the input file
    long total_words; // Variable to store the total word count

    // Call the count_words function to get the word count
    total_words = count_words(filename);

    // Check if there was an error opening the file
    if (total_words == -1) {
        return 1; // Exit with an error code
    } else {
        // Print the total number of words
        printf("Total words in '%s': %ld\n", filename, total_words);
    }

    return 0; // Exit successfully
}

