#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ACCOUNTS 100
#define MAX_NAME_LENGTH 50

// Account structure
typedef struct {
    int account_number;
    char account_holder[MAX_NAME_LENGTH];
    float balance;
} Account;

// Bank system structure
typedef struct {
    Account accounts[MAX_ACCOUNTS];
    int num_accounts;
} Bank;

// Function prototypes
void initialize_bank(Bank *bank);
int create_account(Bank *bank, const char *name, float initial_balance);
Account* find_account(Bank *bank, int account_number);
int deposit(Bank *bank, int account_number, float amount);
int withdraw(Bank *bank, int account_number, float amount);
void display_account_info(Bank *bank, int account_number);
void list_all_accounts(Bank *bank);

// Initialize the bank system
void initialize_bank(Bank *bank) {
    bank->num_accounts = 0;
}

// Create a new account
int create_account(Bank *bank, const char *name, float initial_balance) {
    // Check if bank is full
    if (bank->num_accounts >= MAX_ACCOUNTS) {
        printf("Error: Maximum number of accounts reached.\n");
        return -1;
    }

    // Create new account
    Account new_account;
    new_account.account_number = bank->num_accounts + 1;
    strncpy(new_account.account_holder, name, MAX_NAME_LENGTH - 1);
    new_account.balance = initial_balance;

    // Add account to bank
    bank->accounts[bank->num_accounts] = new_account;
    bank->num_accounts++;

    printf("Account created successfully. Account Number: %d\n", new_account.account_number);
    return new_account.account_number;
}

// Find an account by account number
Account* find_account(Bank *bank, int account_number) {
    for (int i = 0; i < bank->num_accounts; i++) {
        if (bank->accounts[i].account_number == account_number) {
            return &bank->accounts[i];
        }
    }
    return NULL;
}

// Deposit money into an account
int deposit(Bank *bank, int account_number, float amount) {
    Account* account = find_account(bank, account_number);

    if (account == NULL) {
        printf("Error: Account not found.\n");
        return 0;
    }

    if (amount <= 0) {
        printf("Error: Invalid deposit amount.\n");
        return 0;
    }

    account->balance += amount;
    printf("Deposit successful. New balance: %.2f\n", account->balance);
    return 1;
}

// Withdraw money from an account
int withdraw(Bank *bank, int account_number, float amount) {
    Account* account = find_account(bank, account_number);

    if (account == NULL) {
        printf("Error: Account not found.\n");
        return 0;
    }

    if (amount <= 0) {
        printf("Error: Invalid withdrawal amount.\n");
        return 0;
    }

    if (amount > account->balance) {
        printf("Error: Insufficient funds.\n");
        return 0;
    }

    account->balance -= amount;
    printf("Withdrawal successful. New balance: %.2f\n", account->balance);
    return 1;
}

// Display account information
void display_account_info(Bank *bank, int account_number) {
    Account* account = find_account(bank, account_number);

    if (account == NULL) {
        printf("Error: Account not found.\n");
        return;
    }

    printf("Account Information:\n");
    printf("Account Number: %d\n", account->account_number);
    printf("Account Holder: %s\n", account->account_holder);
    printf("Balance: %.2f\n", account->balance);
}

// List all accounts
void list_all_accounts(Bank *bank) {
    printf("Bank Accounts:\n");
    for (int i = 0; i < bank->num_accounts; i++) {
        printf("Account Number: %d, Holder: %s, Balance: %.2f\n", 
               bank->accounts[i].account_number, 
               bank->accounts[i].account_holder, 
               bank->accounts[i].balance);
    }
}

