#include <stdio.h>    // For standard input/output functions (printf, scanf, fgets)
#include <stdlib.h>   // For exit() function
#include <string.h>   // For string manipulation functions (strcpy, strcspn)

// Define constants for array sizes and initial account number
#define MAX_ACCOUNTS 100        // Maximum number of accounts the system can hold
#define MAX_NAME_LENGTH 50      // Maximum length for an account holder's name

// Structure to define an Account
typedef struct {
    int account_number;
    char account_holder_name[MAX_NAME_LENGTH];
    double balance;
} Account;

// Global array to store accounts and a counter for the number of active accounts
Account accounts[MAX_ACCOUNTS];
int num_accounts = 0; // Current number of accounts created

// Global variable for generating unique account numbers
// Starting from 1001 to make them easily distinguishable from array indices
int next_account_number = 1001;

// --- Function Prototypes ---
void display_menu();
void create_account();
void deposit();
void withdraw();
void check_balance();
void display_all_accounts();
int find_account_index(int account_num); // Helper function to find account by number

// Helper function to clear the input buffer
// Essential when mixing scanf() (which leaves newline) with fgets() (which reads newline)
void clear_input_buffer() {
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
}

// --- Main Function ---
int main() {
    int choice;

    do {
        display_menu();

        // Read user's choice
        // Check if scanf successfully read an integer
        if (scanf("%d", &choice) != 1) {
            printf("Invalid input. Please enter a number.\n");
            clear_input_buffer(); // Clear buffer in case of invalid input
            choice = 0; // Set choice to an invalid number to loop again
            continue;   // Skip the rest of the loop and re-display menu
        }
        clear_input_buffer(); // Clear the newline character left by scanf()

        // Handle user's choice using a switch statement
        switch (choice) {
            case 1:
                create_account();
                break;
            case 2:
                deposit();
                break;
            case 3:
                withdraw();
                break;
            case 4:
                check_balance();
                break;
            case 5:
                display_all_accounts();
                break;
            case 6:
                printf("\nExiting banking system. Goodbye!\n");
                break;
            default:
                printf("Invalid choice. Please try again.\n");
        }
    } while (choice != 6); // Loop until the user chooses to exit

    return 0;
}

// --- Function Definitions ---

// Displays the main menu options to the user
void display_menu() {
    printf("\n--- Banking System Menu ---\n");
    printf("1. Create New Account\n");
    printf("2. Deposit\n");
    printf("3. Withdraw\n");
    printf("4. Check Balance\n");
    printf("5. Display All Accounts\n");
    printf("6. Exit\n");
    printf("Enter your choice: ");
}

// Helper function to find an account by its account number
// Returns the index of the account in the 'accounts' array, or -1 if not found
int find_account_index(int account_num) {
    for (int i = 0; i < num_accounts; i++) {
        if (accounts[i].account_number == account_num) {
            return i; // Account found
        }
    }
    return -1; // Account not found
}

// Function to create a new bank account
void create_account() {
    // Check if the maximum number of accounts has been reached
    if (num_accounts >= MAX_ACCOUNTS) {
        printf("Error: Maximum number of accounts reached. Cannot create more accounts.\n");
        return;
    }

    // Assign a unique account number and increment for the next account
    accounts[num_accounts].account_number = next_account_number++;

    printf("Enter account holder name: ");
    // Use fgets to read the name safely, including spaces
    fgets(accounts[num_accounts].account_holder_name, MAX_NAME_LENGTH, stdin);
    // Remove the trailing newline character that fgets() might include
    accounts[num_accounts].account_holder_name[strcspn(accounts[num_accounts].account_holder_name, "\n")] = 0;

    // Initialize the new account's balance to zero
    accounts[num_accounts].balance = 0.0;

    // Increment the counter for total number of accounts
    num_accounts++;

    printf("\nAccount created successfully!\n");
    printf("Account Number: %d\n", accounts[num_accounts - 1].account_number);
    printf("Account Holder: %s\n", accounts[num_accounts - 1].account_holder_name);
    printf("Initial Balance: %.2f\n", accounts[num_accounts - 1].balance);
}

// Function to deposit money into an existing account
void deposit() {
    int account_num;
    double amount;

    printf("Enter account number: ");
    if (scanf("%d", &account_num) != 1) {
        printf("Invalid input. Please enter a number.\n");
        clear_input_buffer();
        return;
    }
    clear_input_buffer();

    int index = find_account_index(account_num);

    if (index == -1) {
        printf("Account not found.\n");
        return;
    }

    printf("Enter amount to deposit: ");
    if (scanf("%lf", &amount) != 1) {
        printf("Invalid input. Please enter a number.\n");
        clear_input_buffer();
        return;
    }
    clear_input_buffer();

    if (amount <= 0) {
        printf("Deposit amount must be positive.\n");
        return;
    }

    accounts[index].balance += amount;
    printf("\nDeposit successful!\n");
    printf("Account Number: %d\n", accounts[index].account_number);
    printf("New Balance: %.2f\n", accounts[index].balance);
}

// Function to withdraw money from an existing account
void withdraw() {
    int account_num;
    double amount;

    printf("Enter account number: ");
    if (scanf("%d", &account_num) != 1) {
        printf("Invalid input. Please enter a number.\n");
        clear_input_buffer();
        return;
    }
    clear_input_buffer();

    int index = find_account_index(account_num);

    if (index == -1) {
        printf("Account not found.\n");
        return;
    }

    printf("Enter amount to withdraw: ");
    if (scanf("%lf", &amount) != 1) {
        printf("Invalid input. Please enter a number.\n");
        clear_input_buffer();
        return;
    }
    clear_input_buffer();

    if (amount <= 0) {
        printf("Withdrawal amount must be positive.\n");
        return;
    }

    if (accounts[index].balance < amount) {
        printf("Insufficient balance.\n");
        printf("Current Balance: %.2f\n", accounts[index].balance);
        return;
    }

    accounts[index].balance -= amount;
    printf("\nWithdrawal successful!\n");
    printf("Account Number: %d\n", accounts[index].account_number);
    printf("New Balance: %.2f\n", accounts[index].balance);
}

// Function to check and display the balance of a specific account
void check_balance() {
    int account_num;

    printf("Enter account number: ");
    if (scanf("%d", &account_num) != 1) {
        printf("Invalid input. Please enter a number.\n");
        clear_input_buffer();
        return;
    }
    clear_input_buffer();

    int index = find_account_index(account_num);

    if (index == -1) {
        printf("Account not found.\n");
        return;
    }

    printf("\n--- Account Details ---\n");
    printf("Account Number: %d\n", accounts[index].account_number);
    printf("Account Holder: %s\n", accounts[index].account_holder_name);
    printf("Balance: %.2f\n", accounts[index].balance);
}

// Function to display details of all created accounts
void display_all_accounts() {
    if (num_accounts == 0) {
        printf("No accounts to display.\n");
        return;
    }

    printf("\n--- All Accounts ---\n");
    for (int i = 0; i < num_accounts; i++) {
        printf("Account Number: %d\n", accounts[i].account_number);
        printf("Account Holder: %s\n", accounts[i].account_holder_name);
        printf("Balance: %.2f\n", accounts[i].balance);
        printf("--------------------\n");
    }
}

