                } else {
                    printf("Account not found.\n");
                }
                break;
            case 5:
                displayAccounts(head);
                break;
            case 6:
                freeAccounts(head);
                exit(0);
            default:
                printf("Invalid choice. Please try again.\n");
        }
    }

    return 0;
}

// Function to create a new account
void createAccount(Account **head, int accountNumber, const char *name, float initialBalance) {
    Account *newAccount = (Account *)malloc(sizeof(Account));
    if (newAccount == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }
    newAccount->accountNumber = accountNumber;
    strncpy(newAccount->name, name, MAX_NAME_LENGTH);
    newAccount->balance = initialBalance;
    newAccount->next = *head;
    *head = newAccount;
    printf("Account created successfully.\n");
}

// Function to get the balance of an account
float getBalance(Account *head, int accountNumber) {
    Account *current = head;
    while (current != NULL) {
        if (current->accountNumber == accountNumber) {
            return current->balance;
        }
        current = current->next;
    }
    return -1; // Return -1 if account not found
}

// Function to deposit money into an account
void deposit(Account *head, int accountNumber, float amount) {
    Account *current = head;
    while (current != NULL) {
        if (current->accountNumber == accountNumber) {
            current->balance += amount;
            printf("Deposit successful. New balance: %.2f\n", current->balance);
            return;
        }
        current = current->next;
    }
    printf("Account not found.\n");
}

// Function to withdraw money from an account
void withdraw(Account *head, int accountNumber, float amount) {
    Account *current = head;
    while (current != NULL) {
        if (current->accountNumber == accountNumber) {
            if (current->balance >= amount) {
                current->balance -= amount;
                printf("Withdrawal successful. New balance: %.2f\n", current->balance);
            } else {
                printf("Insufficient funds.\n");
            }
            return;
        }
        current = current->next;
    }
    printf("Account not found.\n");
}

// Function to display all accounts
void displayAccounts(Account *head) {
    if (head == NULL) {
        printf("No accounts available.\n");
        return;
    }
    Account *current = head;
    printf("\nAccounts:\n");
    while (current != NULL) {
        printf("Account Number: %d, Name: %s, Balance: %.2f\n", current->accountNumber, current->name, current->balance);
        current = current->next;
    }
}

// Function to free all allocated memory for accounts
void freeAccounts(Account *head) {
    Account *current = head;
    Account *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
}

#include <stdio.h>
