// Enum to represent game choices
typedef enum {
    ROCK = 0,
    PAPER = 1,
    SCISSORS = 2
} Choice;

// Enum to represent game results
typedef enum {
    PLAYER1_WIN,
    PLAYER2_WIN,
    DRAW
} Result;

// Function to get a random choice
Choice get_random_choice() {
    return rand() % 3;
}

// Function to determine the winner
Result determine_winner(Choice player1_choice, Choice player2_choice) {
    if (player1_choice == player2_choice) {
        return DRAW;
    }

    switch (player1_choice) {
        case ROCK:
            return (player2_choice == SCISSORS) ? PLAYER1_WIN : PLAYER2_WIN;
        case PAPER:
            return (player2_choice == ROCK) ? PLAYER1_WIN : PLAYER2_WIN;
        case SCISSORS:
            return (player2_choice == PAPER) ? PLAYER1_WIN : PLAYER2_WIN;
        default:
            return DRAW;
    }
}

// Function to convert choice to string
const char* choice_to_string(Choice choice) {
    switch (choice) {
        case ROCK: return "Rock";
        case PAPER: return "Paper";
        case SCISSORS: return "Scissors";
        default: return "Unknown";
    }
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Game statistics variables
    int total_games = 0;
    int player1_wins = 0;
    int player2_wins = 0;
    int draws = 0;

    // Number of games to simulate
    int num_games = 1000;

    printf("Rock Paper Scissors Simulation\n");
    printf("------------------------------\n");

    // Simulate games
    for (int game = 1; game <= num_games; game++) {
        // Get random choices for both players
        Choice player1_choice = get_random_choice();
        Choice player2_choice = get_random_choice();

        // Determine the winner
        Result result = determine_winner(player1_choice, player2_choice);

        // Update game statistics
        total_games++;

        switch (result) {
            case PLAYER1_WIN:
                player1_wins++;
                printf("Game %d: Player 1 wins (", game);
                break;
            case PLAYER2_WIN:
                player2_wins++;
                printf("Game %d: Player 2 wins (", game);
                break;
            case DRAW:
                draws++;
                printf("Game %d: Draw (", game);
                break;
        }

        // Print choices for this game
        printf("Player 1: %s, Player 2: %s)\n", 
               choice_to_string(player1_choice), 
               choice_to_string(player2_choice));
    }

    // Print final statistics
    printf("\nGame Statistics\n");
    printf("---------------\n");
    printf("Total Games: %d\n", total_games);
    printf("Player 1 Wins: %d (%.2f%%)\n", player1_wins, 
           (float)player1_wins / total_games * 100);
    printf("Player 2 Wins: %d (%.2f%%)\n", player2_wins, 
           (float)player2_wins / total_games * 100);
    printf("Draws: %d (%.2f%%)\n", draws, 
           (float)draws / total_games * 100);

    return 0;
}

