 * @param comp1_choice The choice of Computer 1.
 * @param comp2_choice The choice of Computer 2.
 * @return 1 if Computer 1 wins, 2 if Computer 2 wins, 0 if it's a tie.
 */
int determineWinner(Choice comp1_choice, Choice comp2_choice) {
    if (comp1_choice == comp2_choice) {
        return 0; // It's a tie
    }

    // Check conditions for Computer 1 win
    if ((comp1_choice == ROCK && comp2_choice == SCISSORS) ||
        (comp1_choice == PAPER && comp2_choice == ROCK) ||
        (comp1_choice == SCISSORS && comp2_choice == PAPER)) {
        return 1; // Computer 1 wins
    } else {
