    if (rounds == 0) {
        printf("No rounds played yet.\n");
        return;
    }

    // Calculate percentages
    double comp1_win_percent = (double)comp1_wins / rounds * 100.0;
    double comp2_win_percent = (double)comp2_wins / rounds * 100.0;
    double tie_percent = (double)ties / rounds * 100.0;

