    printf("Computer 1 Wins: %d (%.2f%%)\n", comp1_wins, comp1_win_percent);
    printf("Computer 2 Wins: %d (%.2f%%)\n", comp2_wins, comp2_win_percent);
    printf("Ties: %d (%.2f%%)\n", ties, tie_percent);
}

