    if (player1 == player2) {
        return 0; // Draw
    }
    switch (player1) {
        case ROCK:
            return (player2 == SCISSORS) ? 1 : 2;
        case PAPER:
            return (player2 == ROCK) ? 1 : 2;
        case SCISSORS:
            return (player2 == PAPER) ? 1 : 2;
    }
    return -1; // Error
}

int main() {
    int num_rounds, i;
    int player1_wins = 0, player2_wins = 0, draws = 0;

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    // Get the number of rounds from the user
    printf("Enter the number of rounds to simulate: ");
    scanf("%d", &num_rounds);

    // Simulate the game for the specified number of rounds
    for (i = 0; i < num_rounds; i++) {
        Choice player1_choice = generate_choice();
        Choice player2_choice = generate_choice();

        int winner = determine_winner(player1_choice, player2_choice);

        switch (winner) {
            case 1:
                player1_wins++;
                break;
            case 2:
                player2_wins++;
                break;
            case 0:
                draws++;
                break;
        }
    }

    // Print the statistics
    printf("Simulation Results:\n");
    printf("Number of Rounds: %d\n", num_rounds);
    printf("Player 1 Wins: %d\n", player1_wins);
    printf("Player 2 Wins: %d\n", player2_wins);
    printf("Draws: %d\n", draws);

    return 0;
}

