#define GRID_SIZE 9

// Function to print the Sudoku grid
void printGrid(int grid[GRID_SIZE][GRID_SIZE]) {
    for (int row = 0; row < GRID_SIZE; row++) {
        if (row % 3 == 0 && row != 0) {
            printf("---------------------\n");
        }

        for (int col = 0; col < GRID_SIZE; col++) {
            if (col % 3 == 0 && col != 0) {
                printf("| ");
            }

            printf("%d ", grid[row][col]);
        }
        printf("\n");
    }
}

// Function to check if a number is valid in a specific cell
bool isValid(int grid[GRID_SIZE][GRID_SIZE], int row, int col, int num) {
    // Check row
    for (int x = 0; x < GRID_SIZE; x++) {
        if (grid[row][x] == num) {
            return false;
        }
    }

    // Check column
    for (int x = 0; x < GRID_SIZE; x++) {
        if (grid[x][col] == num) {
            return false;
        }
    }

    // Check 3x3 box
    int startRow = row - row % 3;
    int startCol = col - col % 3;

    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            if (grid[i + startRow][j + startCol] == num) {
                return false;
            }
        }
    }

    return true;
}

// Function to find an empty cell in the grid
bool findEmptyCell(int grid[GRID_SIZE][GRID_SIZE], int *row, int *col) {
    for (*row = 0; *row < GRID_SIZE; (*row)++) {
        for (*col = 0; *col < GRID_SIZE; (*col)++) {
            if (grid[*row][*col] == 0) {
                return true;
            }
        }
    }
    return false;
}

// Recursive function to solve Sudoku using backtracking
bool solveSudoku(int grid[GRID_SIZE][GRID_SIZE]) {
    int row, col;

    // Find an empty cell
    if (!findEmptyCell(grid, &row, &col)) {
        return true; // Puzzle solved
    }

    // Try placing numbers 1-9 in the empty cell
    for (int num = 1; num <= 9; num++) {
        // Check if the number is valid in this cell
        if (isValid(grid, row, col, num)) {
            // Place the number
            grid[row][col] = num;

            // Recursively solve the rest of the grid
            if (solveSudoku(grid)) {
                return true;
            }

            // If placing the number doesn't lead to a solution, backtrack
            grid[row][col] = 0;
        }
    }

    // No solution found
    return false;
}

