            return false;
        }
    }

    // Check column
    for (int x = 0; x < N; x++) {
        if (grid[x][col] == num) {
            return false;
        }
    }

    // Check 3x3 subgrid
    int startRow = row - row % 3;
    int startCol = col - col % 3;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            if (grid[i + startRow][j + startCol] == num) {
                return false;
            }
        }
    }

    return true; // It's safe to place the number
}

// Function to find an unassigned cell (empty cell)
// Returns true if an unassigned cell is found, and updates row and col
// Returns false if no unassigned cell is found (puzzle is solved or full)
bool findUnassignedLocation(int grid[N][N], int *row, int *col) {
    for (*row = 0; *row < N; (*row)++) {
        for (*col = 0; *col < N; (*col)++) {
            if (grid[*row][*col] == 0) { // 0 represents an empty cell
                return true;
            }
        }
    }
    return false; // No unassigned cell found
}

// Main Sudoku solving function using backtracking
bool solveSudoku(int grid[N][N]) {
    int row, col;

    // If there is no unassigned cell, the Sudoku is solved
    if (!findUnassignedLocation(grid, &row, &col)) {
        return true; // Puzzle solved!
    }

    // Try numbers from 1 to 9
    for (int num = 1; num <= 9; num++) {
        // If placing 'num' at (row, col) is safe
        if (isSafe(grid, row, col, num)) {
            // Make a tentative assignment
            grid[row][col] = num;

            // Recur to solve the rest of the puzzle
            if (solveSudoku(grid)) {
                return true; // Found a solution
            }

            // If the recursive call returns false, backtrack:
            // Unmake the assignment and try a different number
            grid[row][col] = 0; // Reset to empty
        }
    }

    return false; // No number can be placed in this cell, trigger backtracking
}

