// Function to check if a number can be placed on the grid
bool isSafe(int grid[N][N], int row, int col, int num) {
    // Check row for the same number
    for (int x = 0; x < N; x++)
        if (grid[row][x] == num)
            return false;

    // Check column for the same number
    for (int x = 0; x < N; x++)
        if (grid[x][col] == num)
            return false;

    // Check the 3x3 subgrid for the same number
    int startRow = row - row % 3;
    int startCol = col - col % 3;
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++)
            if (grid[i + startRow][j + startCol] == num)
                return false;

    return true;
}

// Function to solve the Sudoku
bool solveSudoku(int grid[N][N], int row, int col) {
    // If we've reached the 9th row, and the 9th column, we are done
    if (row == N - 1 && col == N)
        return true;

    // If column value is 9, move to next row and column start from 0
    if (col == N) {
        row++;
        col = 0;
    }

    // If the current position is already filled, move to the next column
    if (grid[row][col] != 0)
        return solveSudoku(grid, row, col + 1);

    for (int num = 1; num <= N; num++) {
        // Check if it's safe to place num in the cell
        if (isSafe(grid, row, col, num)) {
            grid[row][col] = num;

            // Recursively try to fill rest of the board
            if (solveSudoku(grid, row, col + 1))
                return true;
        }

        // Remove the number if not leading to a solution
        grid[row][col] = 0;
    }

    return false;
}

