// Function to check if a number is used in the given row
bool isUsedInRow(int grid[N][N], int row, int num) {
    for (int col = 0; col < N; col++) {
        if (grid[row][col] == num) {
            return true;
        }
    }
    return false;
}

// Function to check if a number is used in the given column
bool isUsedInCol(int grid[N][N], int col, int num) {
    for (int row = 0; row < N; row++) {
        if (grid[row][col] == num) {
            return true;
        }
    }
    return false;
}

// Function to check if a number is used in the given 3x3 box
bool isUsedInBox(int grid[N][N], int startRow, int startCol, int num) {
    for (int row = 0; row < 3; row++) {
        for (int col = 0; col < 3; col++) {
            if (grid[row + startRow][col + startCol] == num) {
                return true;
            }
        }
    }
    return false;
}

// Function to check if it is safe to place a number in a cell
bool isSafe(int grid[N][N], int row, int col, int num) {
    return !isUsedInRow(grid, row, num) &&
           !isUsedInCol(grid, col, num) &&
           !isUsedInBox(grid, row - row % 3, col - col % 3, num);
}

// Function to find an empty cell
bool findEmptyCell(int grid[N][N], int *row, int *col) {
    for (*row = 0; *row < N; (*row)++) {
        for (*col = 0; *col < N; (*col)++) {
            if (grid[*row][*col] == 0) {
                return true;
            }
        }
    }
    return false;
}

// Function to solve the Sudoku puzzle using backtracking
bool solveSudoku(int grid[N][N]) {
    int row, col;

    // Find an empty cell
    if (!findEmptyCell(grid, &row, &col)) {
        return true;  // No empty cell found, puzzle is solved
    }

    // Try numbers from 1 to 9
    for (int num = 1; num <= 9; num++) {
        if (isSafe(grid, row, col, num)) {
            grid[row][col] = num;  // Place the number

            // Recursively solve the rest of the puzzle
            if (solveSudoku(grid)) {
                return true;
            }

            grid[row][col] = 0;  // Backtrack and remove the number
        }
    }

    return false;  // No solution found
}

// Function to read the Sudoku grid from a file
void readGridFromFile(const char *filename, int grid[N][N]) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file!\n");
        return;
    }

    for (int row = 0; row < N; row++) {
        for (int col = 0; col < N; col++) {
            fscanf(file, "%d", &grid[row][col]);
        }
    }

    fclose(file);
}

// Main function
int main() {
    int grid[N][N];

    // Read the Sudoku grid from a file
    readGridFromFile("sudoku.txt", grid);

    printf("Original Sudoku Grid:\n");
    printGrid(grid);

    if (solveSudoku(grid)) {
        printf("Solved Sudoku Grid:\n");
        printGrid(grid);
    } else {
        printf("No solution exists for this Sudoku puzzle.\n");
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

// Token types
typedef enum {
    TOKEN_LBRACE,      // {
    TOKEN_RBRACE,      // }
    TOKEN_LBRACKET,    // [
    TOKEN_RBRACKET,    // ]
    TOKEN_COLON,       // :
    TOKEN_COMMA,       // ,
    TOKEN_STRING,      // "string"
    TOKEN_NUMBER,      // numeric value
    TOKEN_TRUE,        // true
    TOKEN_FALSE,       // false
    TOKEN_NULL,        // null
    TOKEN_EOF          // end of input
} TokenType;

// Token structure
typedef struct {
    TokenType type;
    char* value;
} Token;

// Parser context
typedef struct {
    Token* tokens;
    int token_count;
    int current_token;
} ParserContext;

// Function prototypes
Token* tokenize(const char* json, int* token_count);
void free_tokens(Token* tokens, int token_count);
void parse_json(ParserContext* context);
void parse_object(ParserContext* context);
void parse_array(ParserContext* context);
void parse_value(ParserContext* context);

// Tokenization function
Token* tokenize(const char* json, int* token_count) {
    Token* tokens = malloc(sizeof(Token) * strlen(json));
    *token_count = 0;
    int i = 0;

    while (json[i] != '\0') {
        // Skip whitespace
        while (isspace(json[i])) {
            i++;
        }

        // Check single-character tokens
        switch (json[i]) {
            case '{':
                tokens[*token_count].type = TOKEN_LBRACE;
                tokens[*token_count].value = strdup("{");
                (*token_count)++;
                i++;
                continue;
            case '}':
                tokens[*token_count].type = TOKEN_RBRACE;
                tokens[*token_count].value = strdup("}");
                (*token_count)++;
                i++;
                continue;
            case '[':
                tokens[*token_count].type = TOKEN_LBRACKET;
                tokens[*token_count].value = strdup("[");
                (*token_count)++;
                i++;
                continue;
            case ']':
                tokens[*token_count].type = TOKEN_RBRACKET;
                tokens[*token_count].value = strdup("]");
                (*token_count)++;
                i++;
                continue;
            case ':':
                tokens[*token_count].type = TOKEN_COLON;
                tokens[*token_count].value = strdup(":");
                (*token_count)++;
                i++;
                continue;
            case ',':
                tokens[*token_count].type = TOKEN_COMMA;
                tokens[*token_count].value = strdup(",");
                (*token_count)++;
                i++;
                continue;
        }

        // Strings
        if (json[i] == '"') {
            int start = i + 1;
            i++;
            while (json[i] != '"' && json[i] != '\0') {
                i++;
            }
            int length = i - start;
            tokens[*token_count].type = TOKEN_STRING;
            tokens[*token_count].value = malloc(length + 1);
            strncpy(tokens[*token_count].value, json + start, length);
            tokens[*token_count].value[length] = '\0';
            (*token_count)++;
            i++;
            continue;
        }

        // Numbers
        if (isdigit(json[i]) || json[i] == '-') {
            int start = i;
            while (isdigit(json[i]) || json[i] == '.' || json[i] == '-') {
                i++;
            }
            int length = i - start;
            tokens[*token_count].type = TOKEN_NUMBER;
            tokens[*token_count].value = malloc(length + 1);
            strncpy(tokens[*token_count].value, json + start, length);
            tokens[*token_count].value[length] = '\0';
            (*token_count)++;
            continue;
        }

        // Keywords
        if (strncmp(json + i, "true", 4) == 0) {
            tokens[*token_count].type = TOKEN_TRUE;
            tokens[*token_count].value = strdup("true");
            (*token_count)++;
            i += 4;
            continue;
        }
        if (strncmp(json + i, "false", 5) == 0) {
            tokens[*token_count].type = TOKEN_FALSE;
            tokens[*token_count].value = strdup("false");
            (*token_count)++;
            i += 5;
            continue;
        }
        if (strncmp(json + i, "null", 4) == 0) {
            tokens[*token_count].type = TOKEN_NULL;
            tokens[*token_count].value = strdup("null");
            (*token_count)++;
            i += 4;
            continue;
        }

        i++;
    }

    // Add EOF token
    tokens[*token_count].type = TOKEN_EOF;
    tokens[*token_count].value = NULL;
    (*token_count)++;

    return tokens;
}

// Free tokens memory
void free_tokens(Token* tokens, int token_count) {
    for (int i = 0; i < token_count; i++) {
        free(tokens[i].value);
    }
    free(tokens);
}

// Match and consume token
bool match(ParserContext* context, TokenType type) {
    if (context->tokens[context->current_token].type == type) {
        context->current_token++;
        return true;
    }
    return false;
}

// Parse JSON value
void parse_value(ParserContext* context) {
    Token current = context->tokens[context->current_token];

    switch (current.type) {
        case TOKEN_STRING:
            printf("String: %s\n", current.value);
            context->current_token++;
            break;
        case TOKEN_NUMBER:
            printf("Number: %s\n", current.value);
            context->current_token++;
            break;
        case TOKEN_TRUE:
            printf("Boolean: true\n");
            context->current_token++;
            break;
        case TOKEN_FALSE:
            printf("Boolean: false\n");
            context->current_token++;
            break;
        case TOKEN_NULL:
            printf("Null\n");
            context->current_token++;
            break;
        case TOKEN_LBRACE:
            parse_object(context);
            break;
        case TOKEN_LBRACKET:
            parse_array(context);
            break;
        default:
            printf("Unexpected token\n");
            exit(1);
    }
}

// Parse JSON object
void parse_object(ParserContext* context) {
    if (!match(context, TOKEN_LBRACE)) {
        printf("Expected '{'\n");
        exit(1);
    }

    printf("Object start\n");

    while (context->tokens[context->current_token].type != TOKEN_RBRACE) {
        // Parse key
        if (!match(context, TOKEN_STRING)) {
            printf("Expected string key\n");
            exit(1);
        }

        // Parse colon
        if (!match(context, TOKEN_COLON)) {
            printf("Expected ':'\n");
            exit(1);
        }

        // Parse value
        parse_value(context);

        // Optional comma
        if (!match(context, TOKEN_COMMA)) {
            break;
        }
    }

    if (!match(context, TOKEN_RBRACE)) {
        printf("Expected '}'\n");
        exit(1);
    }

    printf("Object end\n");
}

// Parse JSON array
void parse_array(ParserContext* context) {
    if (!match(context, TOKEN_LBRACKET)) {
        printf("Expected '['\n");
        exit(1);
    }

    printf("Array start\n");

    while (context->tokens[context->current_token].type != TOKEN_RBRACKET) {
        parse_value(context);

        // Optional comma
        if (!match(context, TOKEN_COMMA)) {
            break;
        }
    }

    if (!match(context, TOKEN_RBRACKET)) {
        printf("Expected ']'\n");
        exit(1);
    }

    printf("Array end\n");
}

int main() {
    const char* json_str = "{\"name\":\"John\",\"age\":30,\"city\":\"New York\",\"active\":true,\"tags\":[\"developer\",\"programmer\"]}";
    int token_count;
    Token* tokens = tokenize(json_str, &token_count);

    ParserContext context = {
        .tokens = tokens,
        .token_count = token_count,
        .current_token = 0
    };

    parse_json(&context);

    free_tokens(tokens, token_count);
    return 0;
}

void parse_json(ParserContext* context) {
    parse_value(context);

    if (context->tokens[context->current_token].type != TOKEN_EOF) {
        printf("Unexpected tokens after parsing\n");
        exit(1);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

#define MAX_TOKEN_LEN 100

typedef enum {
    TOKEN_STRING,
    TOKEN_NUMBER,
    TOKEN_LEFT_BRACE,
    TOKEN_RIGHT_BRACE,
    TOKEN_COLON,
    TOKEN_COMMA,
    TOKEN_EOF,
    TOKEN_ERROR
} TokenType;

typedef struct {
    TokenType type;
    char value[MAX_TOKEN_LEN];
} Token;

Token getToken(FILE *input) {
    Token token;
    int c;
    int i = 0;

    // Skip whitespace
    while (isspace(c = fgetc(input))) {}

    if (c == EOF) {
        token.type = TOKEN_EOF;
        return token;
    }

    if (c == '{') {
        token.type = TOKEN_LEFT_BRACE;
        token.value[0] = c;
        token.value[1] = '\0';
        return token;
    }

    if (c == '}') {
        token.type = TOKEN_RIGHT_BRACE;
        token.value[0] = c;
        token.value[1] = '\0';
        return token;
    }

    if (c == ':') {
        token.type = TOKEN_COLON;
        token.value[0] = c;
        token.value[1] = '\0';
        return token;
    }

    if (c == ',') {
        token.type = TOKEN_COMMA;
        token.value[0] = c;
        token.value[1] = '\0';
        return token;
    }

    if (c == '"') {
        token.type = TOKEN_STRING;
        while ((c = fgetc(input)) != '"' && c != EOF) {
            if (i < MAX_TOKEN_LEN - 1) {
                token.value[i++] = c;
            }
        }
        token.value[i] = '\0';
        return token;
    }

    if (isdigit(c) || c == '-') {
        token.type = TOKEN_NUMBER;
        token.value[i++] = c;
        while (isdigit(c = fgetc(input)) && i < MAX_TOKEN_LEN - 1) {
            token.value[i++] = c;
        }
        token.value[i] = '\0';
        ungetc(c, input);
        return token;
    }

    token.type = TOKEN_ERROR;
    return token;
}

void parseJSON(FILE *input) {
    Token token;
    while ((token = getToken(input)).type != TOKEN_EOF) {
        switch (token.type) {
            case TOKEN_LEFT_BRACE:
                printf("Object start\n");
                break;
            case TOKEN_RIGHT_BRACE:
                printf("Object end\n");
                break;
            case TOKEN_STRING:
                printf("String: %s\n", token.value);
                break;
            case TOKEN_NUMBER:
                printf("Number: %s\n", token.value);
                break;
            case TOKEN_COLON:
                printf("Colon\n");
                break;
            case TOKEN_COMMA:
                printf("Comma\n");
                break;
            case TOKEN_ERROR:
                printf("Error: Invalid token\n");
                return;
            case TOKEN_EOF:
                break;
        }
    }
}

int main() {
    FILE *input = fopen("input.json", "r");
    if (!input) {
        perror("Unable to open file");
        return EXIT_FAILURE;
    }

    parseJSON(input);

    fclose(input);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// --- Lexer (Tokenizer) ---

// Define token types
typedef enum {
    TOKEN_EOF = 0,
    TOKEN_LBRACE,       // {
    TOKEN_RBRACE,       // }
    TOKEN_LBRACKET,     // [
    TOKEN_RBRACKET,     // ]
    TOKEN_COLON,        // :
    TOKEN_COMMA,        // ,
    TOKEN_STRING,       // "abc"
    TOKEN_NUMBER,       // 123, 123.45
    TOKEN_TRUE,         // true
    TOKEN_FALSE,        // false
    TOKEN_NULL,         // null
    TOKEN_ERROR         // Lexing error
} TokenType;

// Structure to hold a token
typedef struct {
    TokenType type;
    char      *value; // For strings and numbers
    double    number_val; // For numbers
} Token;

// Global variables for lexer state
static const char *json_input;
static int         current_pos;

// Function to advance the lexer position
static void advance() {
    current_pos++;
}

// Function to get the current character
static char peek() {
    return json_input[current_pos];
}

// Function to skip whitespace
static void skip_whitespace() {
    while (isspace(peek())) {
        advance();
    }
}

// Function to create a string token
static Token make_string_token(TokenType type, const char *start, int length) {
    Token token;
    token.type = type;
    token.value = (char *)malloc(length + 1);
    strncpy(token.value, start, length);
    token.value[length] = '\0';
    return token;
}

// Function to get the next token
Token get_next_token() {
    skip_whitespace();

    char c = peek();
    if (c == '\0') {
        return (Token){TOKEN_EOF, NULL, 0.0};
    }

    switch (c) {
        case '{': advance(); return (Token){TOKEN_LBRACE, NULL, 0.0};
        case '}': advance(); return (Token){TOKEN_RBRACE, NULL, 0.0};
        case '[': advance(); return (Token){TOKEN_LBRACKET, NULL, 0.0};
        case ']': advance(); return (Token){TOKEN_RBRACKET, NULL, 0.0};
        case ':': advance(); return (Token){TOKEN_COLON, NULL, 0.0};
        case ',': advance(); return (Token){TOKEN_COMMA, NULL, 0.0};
        case '"': {
            advance(); // Consume '"'
            int start_pos = current_pos;
            while (peek() != '"' && peek() != '\0') {
                if (peek() == '\\') { // Simple escape sequence handling
                    advance();
                }
                advance();
            }
            if (peek() != '"') {
                return (Token){TOKEN_ERROR, strdup("Unterminated string"), 0.0};
            }
            int length = current_pos - start_pos;
            Token token = make_string_token(TOKEN_STRING, &json_input[start_pos], length);
            advance(); // Consume closing '"'
            return token;
        }
        case '0':
        case '1':
        case '2':
        case '3':
        case '4':
        case '5':
        case '6':
        case '7':
        case '8':
        case '9':
        case '-': {
            int start_pos = current_pos;
            if (c == '-') advance(); // Consume optional minus
            while (isdigit(peek())) advance();
            if (peek() == '.') {
                advance(); // Consume '.'
                while (isdigit(peek())) advance();
            }
            // No support for scientific notation (e/E) for simplicity
            int length = current_pos - start_pos;
            char *num_str = (char *)malloc(length + 1);
            strncpy(num_str, &json_input[start_pos], length);
            num_str[length] = '\0';

            Token token;
            token.type = TOKEN_NUMBER;
            token.value = num_str; // Store as string for flexibility/debugging
            token.number_val = strtod(num_str, NULL);
            return token;
        }
        case 't': {
            const char *true_str = "true";
            int len = strlen(true_str);
            if (strncmp(&json_input[current_pos], true_str, len) == 0) {
                current_pos += len;
                return (Token){TOKEN_TRUE, NULL, 0.0};
            }
            break; // Fall through to error
        }
        case 'f': {
            const char *false_str = "false";
            int len = strlen(false_str);
            if (strncmp(&json_input[current_pos], false_str, len) == 0) {
                current_pos += len;
                return (Token){TOKEN_FALSE, NULL, 0.0};
            }
            break; // Fall through to error
        }
        case 'n': {
            const char *null_str = "null";
            int len = strlen(null_str);
            if (strncmp(&json_input[current_pos], null_str, len) == 0) {
                current_pos += len;
                return (Token){TOKEN_NULL, NULL, 0.0};
            }
            break; // Fall through to error
        }
    }

    return (Token){TOKEN_ERROR, strdup("Unexpected character"), 0.0};
}

// --- Parser ---

// JSON Node Types
typedef enum {
    JSON_STRING,
    JSON_NUMBER,
    JSON_OBJECT,
    JSON_ARRAY,
    JSON_TRUE,
    JSON_FALSE,
    JSON_NULL
} JsonNodeType;

// Represent a key-value pair in an object
typedef struct JsonMember {
    char           *key;
    struct JsonNode *value;
    struct JsonMember *next; // For linked list of members
} JsonMember;

// Represent a JSON value (node)
typedef struct JsonNode {
    JsonNodeType type;
    union {
        char        *string_val;
        double       number_val;
        JsonMember  *object_val; // Head of linked list of members
        struct JsonNode **array_val; // Array of pointers to JsonNode
    } data;
    int array_size; // For arrays
} JsonNode;

// Global variables for parser state
static Token current_token;

// Forward declarations for recursive parsing functions
static JsonNode *parse_value();
static JsonNode *parse_object();
static JsonNode *parse_array();

// Helper to consume the current token and get the next one
static void consume_token() {
    if (current_token.type == TOKEN_STRING || current_token.type == TOKEN_NUMBER || current_token.type == TOKEN_ERROR) {
        free(current_token.value); // Free token value if it was allocated
    }
    current_token = get_next_token();
}

// Helper to match and consume an expected token type
static int match_token(TokenType expected_type, const char *error_msg) {
    if (current_token.type == expected_type) {
        consume_token();
        return 1;
    } else {
        fprintf(stderr, "Parsing Error: %s. Got %d\n", error_msg, current_token.type);
        return 0;
    }
}

// Parse a JSON string
static JsonNode *parse_string() {
    if (current_token.type != TOKEN_STRING) {
        fprintf(stderr, "Parsing Error: Expected string, got %d\n", current_token.type);
        return NULL;
    }
    JsonNode *node = (JsonNode *)malloc(sizeof(JsonNode));
    if (!node) return NULL;
    node->type = JSON_STRING;
    node->data.string_val = strdup(current_token.value); // Deep copy string
    consume_token();
    return node;
}

// Parse a JSON number
static JsonNode *parse_number() {
    if (current_token.type != TOKEN_NUMBER) {
        fprintf(stderr, "Parsing Error: Expected number, got %d\n", current_token.type);
        return NULL;
    }
    JsonNode *node = (JsonNode *)malloc(sizeof(JsonNode));
    if (!node) return NULL;
    node->type = JSON_NUMBER;
    node->data.number_val = current_token.number_val;
    consume_token();
    return node;
}

// Parse a JSON boolean (true)
static JsonNode *parse_true() {
    if (current_token.type != TOKEN_TRUE) return NULL;
    JsonNode *node = (JsonNode *)malloc(sizeof(JsonNode));
    if (!node) return NULL;
    node->type = JSON_TRUE;
    consume_token();
    return node;
}

// Parse a JSON boolean (false)
static JsonNode *parse_false() {
    if (current_token.type != TOKEN_FALSE) return NULL;
    JsonNode *node = (JsonNode *)malloc(sizeof(JsonNode));
    if (!node) return NULL;
    node->type = JSON_FALSE;
    consume_token();
    return node;
}

// Parse a JSON null
static JsonNode *parse_null() {
    if (current_token.type != TOKEN_NULL) return NULL;
    JsonNode *node = (JsonNode *)malloc(sizeof(JsonNode));
    if (!node) return NULL;
    node->type = JSON_NULL;
    consume_token();
    return node;
}

// Parse a JSON value
static JsonNode *parse_value() {
    switch (current_token.type) {
        case TOKEN_STRING:      return parse_string();
        case TOKEN_NUMBER:      return parse_number();
        case TOKEN_TRUE:        return parse_true();
        case TOKEN_FALSE:       return parse_false();
        case TOKEN_NULL:        return parse_null();
        case TOKEN_LBRACE:      return parse_object();
        case TOKEN_LBRACKET:    return parse_array();
        case TOKEN_ERROR:       fprintf(stderr, "Lexing error: %s\n", current_token.value); return NULL;
        default:                fprintf(stderr, "Parsing Error: Unexpected token type %d for value.\n", current_token.type); return NULL;
    }
}

// Parse a JSON object
static JsonNode *parse_object() {
    if (!match_token(TOKEN_LBRACE, "Expected '{'")) return NULL;

    JsonNode *object_node = (JsonNode *)malloc(sizeof(JsonNode));
    if (!object_node) return NULL;
    object_node->type = JSON_OBJECT;
    object_node->data.object_val = NULL; // Head of linked list of members

    JsonMember *last_member = NULL;

    while (current_token.type != TOKEN_RBRACE && current_token.type != TOKEN_EOF) {
        if (current_token.type != TOKEN_STRING) {
            fprintf(stderr, "Parsing Error: Expected string key in object, got %d.\n", current_token.type);
            // Free members allocated so far
            JsonMember *current = object_node->data.object_val;
            while(current) {
                JsonMember *next = current->next;
                free(current->key);
                // Assume free_json_node is available for node values
                // For now, simplify and just free member itself, potential leak
                free(current);
                current = next;
            }
            free(object_node);
            return NULL;
        }

        JsonMember *new_member = (JsonMember *)malloc(sizeof(JsonMember));
        if (!new_member) {
            // Free members allocated so far
            JsonMember *current = object_node->data.object_val;
            while(current) {
                JsonMember *next = current->next;
                free(current->key);
                free(current); // For now, just free member, not node value
                current = next;
            }
            free(object_node);
            return NULL; // Out of memory
        }

        new_member->key = strdup(current_token.value); // Deep copy key string
        consume_token(); // Consume string key

        if (!match_token(TOKEN_COLON, "Expected ':' after object key")) {
            free(new_member->key);
            free(new_member);
            // Free members allocated so far
            JsonMember *current = object_node->data.object_val;
            while(current) {
                JsonMember *next = current->next;
                free(current->key);
                free(current);
                current = next;
            }
            free(object_node);
            return NULL;
        }

        new_member->value = parse_value();
        if (!new_member->value) {
            free(new_member->key);
            free(new_member);
            // Free members allocated so far
            JsonMember *current = object_node->data.object_val;
            while(current) {
                JsonMember *next = current->next;
                free(current->key);
                free(current);
                current = next;
            }
            free(object_node);
            return NULL; // Value parsing failed
        }
        new_member->next = NULL;

        if (object_node->data.object_val == NULL) {
            object_node->data.object_val = new_member;
        } else {
            last_member->next = new_member;
        }
        last_member = new_member;

        if (current_token.type == TOKEN_COMMA) {
            consume_token(); // Consume comma
        } else if (current_token.type != TOKEN_RBRACE && current_token.type != TOKEN_EOF) {
            fprintf(stderr, "Parsing Error: Expected ',' or '}' in object, got %d.\n", current_token.type);
            // Free members allocated so far
            JsonMember *current = object_node->data.object_val;
            while(current) {
                JsonMember *next = current->next;
                free(current->key);
                free(current);
                current = next;
            }
            free(object_node);
            return NULL;
        }
    }

    if (!match_token(TOKEN_RBRACE, "Expected '}'")) {
         // Free members allocated so far
        JsonMember *current = object_node->data.object_val;
        while(current) {
            JsonMember *next = current->next;
            free(current->key);
            free(current);
            current = next;
        }
        free(object_node);
        return NULL;
    }

    return object_node;
}

// Parse a JSON array
static JsonNode *parse_array() {
    if (!match_token(TOKEN_LBRACKET, "Expected '['")) return NULL;

    JsonNode *array_node = (JsonNode *)malloc(sizeof(JsonNode));
    if (!array_node) return NULL;
    array_node->type = JSON_ARRAY;
    array_node->data.array_val = NULL;
    array_node->array_size = 0;

    int capacity = 4; // Initial capacity for array elements
    array_node->data.array_val = (JsonNode **)malloc(sizeof(JsonNode *) * capacity);
    if (!array_node->data.array_val) {
        free(array_node); return NULL;
    }

    while (current_token.type != TOKEN_RBRACKET && current_token.type != TOKEN_EOF) {
        if (array_node->array_size >= capacity) {
            capacity *= 2;
            JsonNode **new_array_val = (JsonNode **)realloc(array_node->data.array_val, sizeof(JsonNode *) * capacity);
            if (!new_array_val) {
                // Free already parsed array elements
                for(int i = 0; i < array_node->array_size; ++i) {
                    // free_json_node(array_node->data.array_val[i]); // Implement this!
                }
                free(array_node->data.array_val);
                free(array_node);
                return NULL; // Out of memory
            }
            array_node->data.array_val = new_array_val;
        }

        JsonNode *element = parse_value();
        if (!element) {
            // Free already parsed array elements
            for(int i = 0; i < array_node->array_size; ++i) {
                // free_json_node(array_node->data.array_val[i]); // Implement this!
            }
            free(array_node->data.array_val);
            free(array_node);
            return NULL; // Element parsing failed
        }
        array_node->data.array_val[array_node->array_size++] = element;

        if (current_token.type == TOKEN_COMMA) {
            consume_token(); // Consume comma
        } else if (current_token.type != TOKEN_RBRACKET && current_token.type != TOKEN_EOF) {
            fprintf(stderr, "Parsing Error: Expected ',' or ']' in array, got %d.\n", current_token.type);
            // Free already parsed array elements
            for(int i = 0; i < array_node->array_size; ++i) {
                // free_json_node(array_node->data.array_val[i]); // Implement this!
            }
            free(array_node->data.array_val);
            free(array_node);
            return NULL;
        }
    }

    if (!match_token(TOKEN_RBRACKET, "Expected ']'")) {
        // Free already parsed array elements
        for(int i = 0; i < array_node->array_size; ++i) {
            // free_json_node(array_node->data.array_val[i]); // Implement this!
        }
        free(array_node->data.array_val);
        free(array_node);
        return NULL;
    }

    return array_node;
}


// Public function to parse JSON
JsonNode *parse_json(const char *json_string) {
    json_input = json_string;
    current_pos = 0;
    current_token = get_next_token(); // Get the first token

    JsonNode *root = parse_value();

    if (current_token.type != TOKEN_EOF) {
        fprintf(stderr, "Parsing Error: Extra content after JSON root. Token type: %d\n", current_token.type);
        // Free root if it was successfully parsed, then return NULL
        // free_json_node(root); // Need to implement this function
        return NULL;
    }

    return root;
}

// Function to free the parsed JSON tree
void free_json_node(JsonNode *node) {
    if (!node) return;

    switch (node->type) {
        case JSON_STRING:
            free(node->data.string_val);
            break;
        case JSON_OBJECT: {
            JsonMember *current = node->data.object_val;
            while (current) {
                JsonMember *next = current->next;
                free(current->key);
                free_json_node(current->value);
                free(current);
                current = next;
            }
            break;
        }
        case JSON_ARRAY: {
            for (int i = 0; i < node->array_size; i++) {
                free_json_node(node->data.array_val[i]);
            }
            free(node->data.array_val);
            break;
        }
        case JSON_NUMBER:
        case JSON_TRUE:
        case JSON_FALSE:
        case JSON_NULL:
            // No additional memory to free for these types
            break;
    }
    free(node);
}

// --- Printer (for verification) ---

static void print_indent(int indent_level) {
    for (int i = 0; i < indent_level; i++) {
        printf("  "); // Two spaces per indent level
    }
}

void print_json_node(JsonNode *node, int indent_level) {
    if (!node) {
        printf("NULL NODE\n");
        return;
    }

    switch (node->type) {
        case JSON_STRING:
            printf("\"%s\"", node->data.string_val);
            break;
        case JSON_NUMBER:
            if (node->data.number_val == (long long)node->data.number_val) {
                printf("%lld", (long long)node->data.number_val); // Print as integer if no decimal
            } else {
                printf("%g", node->data.number_val); // Print as float
            }
            break;
        case JSON_TRUE:
            printf("true");
            break;
        case JSON_FALSE:
            printf("false");
            break;
        case JSON_NULL:
            printf("null");
            break;
        case JSON_OBJECT: {
            printf("{\n");
            JsonMember *current = node->data.object_val;
            while (current) {
                print_indent(indent_level + 1);
                printf("\"%s\": ", current->key);
                print_json_node(current->value, indent_level + 1);
                if (current->next) {
                    printf(",\n");
                } else {
                    printf("\n");
                }
                current = current->next;
            }
            print_indent(indent_level);
            printf("}");
            break;
        }
        case JSON_ARRAY: {
            printf("[\n");
            for (int i = 0; i < node->array_size; i++) {
                print_indent(indent_level + 1);
                print_json_node(node->data.array_val[i], indent_level + 1);
                if (i < node->array_size - 1) {
                    printf(",\n");
                } else {
                    printf("\n");
                }
            }
            print_indent(indent_level);
            printf("]");
            break;
        }
    }
}


