#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

// Token definitions
typedef enum {
    TOK_LBRACE,   // {
    TOK_RBRACE,   // }
    TOK_COLON,    // :
    TOK_COMMA,    // ,
    TOK_STRING,   // "abc"
    TOK_NUMBER,   // 1234.56
    TOK_EOF,
    TOK_ERROR
} TokenType;

typedef struct {
    TokenType type;
    char *lexeme;
} Token;

// ---------------- Tokenizer ----------------

typedef struct {
    const char *src;
    size_t idx;
} Lexer;

void skip_whitespace(Lexer *lexer) {
    while (isspace(lexer->src[lexer->idx])) lexer->idx++;
}

Token next_token(Lexer *lexer) {
    skip_whitespace(lexer);
    char c = lexer->src[lexer->idx];
    Token tok = {TOK_ERROR, NULL};

    if (c == '\0') {
        tok.type = TOK_EOF;
        return tok;
    }
    if (c == '{') {
        lexer->idx++;
        tok.type = TOK_LBRACE;
        return tok;
    }
    if (c == '}') {
        lexer->idx++;
        tok.type = TOK_RBRACE;
        return tok;
    }
    if (c == ':') {
        lexer->idx++;
        tok.type = TOK_COLON;
        return tok;
    }
    if (c == ',') {
        lexer->idx++;
        tok.type = TOK_COMMA;
        return tok;
    }
    if (c == '"') {
        lexer->idx++; // Skip opening quote
        size_t start = lexer->idx;
        while (lexer->src[lexer->idx] && lexer->src[lexer->idx] != '"')
            lexer->idx++;
        if (lexer->src[lexer->idx] != '"') {
            tok.type = TOK_ERROR; // Unterminated string
            return tok;
        }
        size_t len = lexer->idx - start;
        tok.type = TOK_STRING;
        tok.lexeme = (char*) malloc(len + 1);
        strncpy(tok.lexeme, lexer->src + start, len);
        tok.lexeme[len] = '\0';
        lexer->idx++; // Skip closing quote
        return tok;
    }
    if (isdigit(c) || c == '-') {
        size_t start = lexer->idx;
        if (c == '-') lexer->idx++;
        while (isdigit(lexer->src[lexer->idx])) lexer->idx++;
        if (lexer->src[lexer->idx] == '.') {
            lexer->idx++;
            while (isdigit(lexer->src[lexer->idx])) lexer->idx++;
        }
        size_t len = lexer->idx - start;
        tok.type = TOK_NUMBER;
        tok.lexeme = (char*) malloc(len + 1);
        strncpy(tok.lexeme, lexer->src + start, len);
        tok.lexeme[len] = '\0';
        return tok;
    }
    tok.type = TOK_ERROR;
    return tok;
}

void free_token(Token *tok) {
    if ((tok->type == TOK_STRING || tok->type == TOK_NUMBER) && tok->lexeme)
        free(tok->lexeme);
}

// ---------------- Parser ----------------

typedef enum {
    VAL_STRING,
    VAL_NUMBER,
    VAL_OBJECT
} ValueType;

struct JsonValue;

typedef struct JsonPair {
    char *key;
    struct JsonValue *value;
    struct JsonPair *next;
} JsonPair;

typedef struct JsonObject {
    JsonPair *pairs;
} JsonObject;

typedef struct JsonValue {
    ValueType type;
    union {
        char *str_val;
        double num_val;
        JsonObject *obj_val;
    };
} JsonValue;

// Forward declaration
JsonValue* parse_value(Lexer *lexer, Token *curtok);

// Parse STRING : value [, ...]
JsonObject* parse_object(Lexer *lexer, Token *curtok) {
    if (curtok->type != TOK_LBRACE) return NULL;
    free_token(curtok);
    *curtok = next_token(lexer);

    JsonObject *obj = malloc(sizeof(JsonObject));
    obj->pairs = NULL;
    JsonPair **tail = &obj->pairs;

    while (curtok->type != TOK_RBRACE && curtok->type != TOK_EOF) {
        if (curtok->type != TOK_STRING) { free_token(curtok); return NULL; }

        JsonPair *pair = malloc(sizeof(JsonPair));
        pair->key = strdup(curtok->lexeme);
        pair->next = NULL;
        free_token(curtok);

        *curtok = next_token(lexer);
        if (curtok->type != TOK_COLON) { free(pair->key); free(pair); free_token(curtok); return NULL; }

        free_token(curtok);
        *curtok = next_token(lexer);

        pair->value = parse_value(lexer, curtok);
        if (!pair->value) { free(pair->key); free(pair); free_token(curtok); return NULL; }

        *tail = pair;
        tail = &pair->next;

        *curtok = next_token(lexer);

        if (curtok->type == TOK_COMMA) {
            free_token(curtok);
            *curtok = next_token(lexer);
        } else if (curtok->type == TOK_RBRACE) {
            break;
        } else {
            free_token(curtok);
            return NULL;
        }
    }

    if (curtok->type != TOK_RBRACE) { return NULL; }
    free_token(curtok);
    return obj;
}

JsonValue* parse_value(Lexer *lexer, Token *curtok) {
    JsonValue *val = malloc(sizeof(JsonValue));
    if (curtok->type == TOK_STRING) {
        val->type = VAL_STRING;
        val->str_val = strdup(curtok->lexeme);
        free_token(curtok);
        return val;
    }
    if (curtok->type == TOK_NUMBER) {
        val->type = VAL_NUMBER;
        val->num_val = atof(curtok->lexeme);
        free_token(curtok);
        return val;
    }
    if (curtok->type == TOK_LBRACE) {
        val->type = VAL_OBJECT;
        val->obj_val = parse_object(lexer, curtok);
        return val;
    }
    free(val);
    return NULL;
}

// --------------- Printing -----------------
void print_json_value(JsonValue *val, int indent);

void print_indent(int n) {
    for (int i = 0; i < n; ++i) printf("  ");
}

void print_json_object(JsonObject *obj, int indent) {
    printf("{\n");
    JsonPair *pair = obj->pairs;
    while (pair) {
        print_indent(indent+1);
        printf("\"%s\": ", pair->key);
        print_json_value(pair->value, indent+1);
        if (pair->next) printf(",");
        printf("\n");
        pair = pair->next;
    }
    print_indent(indent);
    printf("}");
}

void print_json_value(JsonValue *val, int indent) {
    switch (val->type) {
        case VAL_STRING:
            printf("\"%s\"", val->str_val);
            break;
        case VAL_NUMBER:
            printf("%g", val->num_val);
            break;
        case VAL_OBJECT:
            print_json_object(val->obj_val, indent);
            break;
    }
}

// --------------- Memory Free -------------
void free_json_value(JsonValue *val);
void free_json_object(JsonObject *obj) {
    JsonPair *p = obj->pairs;
    while (p) {
        free(p->key);
        free_json_value(p->value);
        JsonPair *next = p->next;
        free(p);
        p = next;
    }
    free(obj);
}

void free_json_value(JsonValue *val) {
    if (val->type == VAL_STRING)
        free(val->str_val);
    else if (val->type == VAL_OBJECT)
        free_json_object(val->obj_val);
    free(val);
}

