        root->type = VAL_OBJECT;
        root->obj_val = parse_object(&lexer, &tok);
        if (!root->obj_val) {
            printf("Parse error\n");
            free(root);
            return 1;
        }
    } else {
        printf("Invalid JSON input (must start with '{')\n");
