#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Token types
typedef enum {
    TOKEN_OBJECT_START,  // {
    TOKEN_OBJECT_END,    // }
    TOKEN_STRING,        // "string"
    TOKEN_NUMBER,        // number
    TOKEN_COLON,         // :
    TOKEN_COMMA,         // ,
    TOKEN_EOF,           // end of file/input
    TOKEN_ERROR          // any error
} TokenType;

// Structure to hold a token
typedef struct {
    TokenType type;
    char *value;
} Token;

// Function to create a new token
Token *create_token(TokenType type, const char *value) {
    Token *token = (Token *)malloc(sizeof(Token));
    token->type = type;
    token->value = strdup(value);
    return token;
}

// Function to free a token
void free_token(Token *token) {
    if (token != NULL) {
        free(token->value);
        free(token);
    }
}

// Function to tokenize input
Token *get_next_token(const char **input) {
    // Skip whitespace
    while (isspace(**input)) {
        (*input)++;
    }

    // End of input
    if (**input == '\0') {
        return create_token(TOKEN_EOF, "");
    }

    switch (**input) {
        case '{':
            (*input)++;
            return create_token(TOKEN_OBJECT_START, "{");
        case '}':
            (*input)++;
            return create_token(TOKEN_OBJECT_END, "}");
        case ':':
            (*input)++;
            return create_token(TOKEN_COLON, ":");
        case ',':
            (*input)++;
            return create_token(TOKEN_COMMA, ",");
        case '"': { // String token
            (*input)++;
            const char *start = *input;
            while (**input != '"' && **input != '\0') {
                (*input)++;
            }
            if (**input == '"') {
                size_t length = *input - start;
                char *value = (char *)malloc(length + 1);
                strncpy(value, start, length);
                value[length] = '\0';
                (*input)++;
                return create_token(TOKEN_STRING, value);
            } else {
                return create_token(TOKEN_ERROR, "Unterminated string");
            }
        }
        default: { // Number token
            if (isdigit(**input) || **input == '-') {
                const char *start = *input;
                while (isdigit(**input) || **input == '.') {
                    (*input)++;
                }
                size_t length = *input - start;
                char *value = (char *)malloc(length + 1);
                strncpy(value, start, length);
                value[length] = '\0';
                return create_token(TOKEN_NUMBER, value);
            }
            return create_token(TOKEN_ERROR, "Unknown character");
        }
    }
}

// Function to parse JSON object and print its content
void parse_json(const char *input) {
    const char *current_input = input;
    Token *token = get_next_token(&current_input);
    if (token->type != TOKEN_OBJECT_START) {
        fprintf(stderr, "Error: Expected '{' at start of JSON\n");
        free_token(token);
        return;
    }
    free_token(token);

    while (1) {
        token = get_next_token(&current_input);
        if (token->type == TOKEN_OBJECT_END) {
            free_token(token);
            break; // End parsing when object ends
        } else if (token->type == TOKEN_STRING) {
            printf("Key: %s\n", token->value);
            free_token(token);

            token = get_next_token(&current_input);
            if (token->type != TOKEN_COLON) {
                fprintf(stderr, "Error: Expected ':' after key\n");
                free_token(token);
                break;
            }
            free_token(token);

            token = get_next_token(&current_input);
            if (token->type == TOKEN_STRING || token->type == TOKEN_NUMBER) {
                printf("Value: %s\n", token->value);
                free_token(token);
            } else {
                fprintf(stderr, "Error: Expected value\n");
                free_token(token);
                break;
            }

            token = get_next_token(&current_input);
            if (token->type == TOKEN_COMMA) {
                free_token(token);
                continue;
            } else if (token->type == TOKEN_OBJECT_END) {
                free_token(token);
                break;
            } else {
                fprintf(stderr, "Error: Expected ',' or '}'\n");
                free_token(token);
                break;
            }
        } else {
            fprintf(stderr, "Error: Expected string as key\n");
            free_token(token);
            break;
        }
    }
}

int main() {
    const char *json_input = "{ \"name\": \"John\", \"age\": 30 }";
    parse_json(json_input);
    return 0;
}

#include <stdio.h>
