#define MAX_BUFFER 1024

typedef enum {
    JSON_STRING,
    JSON_NUMBER,
    JSON_OBJECT,
    JSON_NULL,
    JSON_BOOL
} json_type;

typedef struct json_value {
    json_type type;
    union {
        char *string;
        double number;
        struct json_value *object; // Pointer to nested JSON object
        int boolean;  // 0 for false, 1 for true
    } value;
    struct json_value *next; // For linked list of values
} json_value;

void free_json(json_value *value) {
    if (!value) return;
    if (value->type == JSON_STRING) {
        free(value->value.string);
    }
    free_json(value->next);
    free(value);
}

json_value* parse_value(const char **json);
json_value* parse_object(const char **json);
void skip_whitespace(const char **json);

json_value* parse_json(const char *json) {
    return parse_value(&json);
}

void skip_whitespace(const char **json) {
    while (isspace(**json)) {
        (*json)++;
    }
}

json_value* parse_string(const char **json) {
    const char *start = ++(*json); // Skip the opening quote
    while (**json && **json != '"') {
        if (**json == '\\') {
            (*json)++; // Skip escape character
        }
        (*json)++;
    }
    if (**json == '"') {
        size_t length = *json - start;
        json_value *value = (json_value *)malloc(sizeof(json_value));
        value->type = JSON_STRING;
        value->value.string = (char *)malloc(length + 1);
        strncpy(value->value.string, start, length);
        value->value.string[length] = '\0';
        (*json)++; // Skip the closing quote
        return value;
    }
    return NULL; // Error, unterminated string
}

json_value* parse_number(const char **json) {
    const char *start = *json;

    while (isdigit(**json) || **json == '.' || **json == '-' || **json == '+') {
        (*json)++;
    }
    size_t length = *json - start;
    char *number_str = (char *)malloc(length + 1);
    strncpy(number_str, start, length);
    number_str[length] = '\0';

    json_value *value = (json_value *)malloc(sizeof(json_value));
    value->type = JSON_NUMBER;
    value->value.number = atof(number_str);

    free(number_str);
    return value;
}

json_value* parse_object(const char **json) {
    json_value *object = (json_value *)malloc(sizeof(json_value));
    object->type = JSON_OBJECT;
    object->next = NULL;

    (*json)++; // Skip '{'
    skip_whitespace(json);

    while (**json != '}' && **json) {
        json_value *key = parse_string(json);
        if (!key) {
            free_json(object);
            return NULL; // Parsing error
        }

        skip_whitespace(json);
        if (**json != ':') {
            free_json(object);
            return NULL; // Expected ':'
        }
        (*json)++; // Skip ':'
        skip_whitespace(json);

        json_value *value = parse_value(json);
        if (!value) {
            free_json(object);
            return NULL; // Parsing error
        }

        key->next = value;
        value->next = object->next; // Insert at the front
        object->next = key;

        skip_whitespace(json);
        if (**json == ',') {
            (*json)++; // Skip ','
            skip_whitespace(json);
        }
    }

    (*json)++; // Skip '}'
    return object;
}

json_value* parse_value(const char **json) {
    skip_whitespace(json);
    switch (**json) {
        case '"':
            return parse_string(json);
        case '{':
            return parse_object(json);
        case 't':
            (*json) += 4; // Skip "true"
            {
                json_value *value = (json_value *)malloc(sizeof(json_value));
                value->type = JSON_BOOL;
                value->value.boolean = 1; // true
                return value;
            }
        case 'f':
            (*json) += 5; // Skip "false"
            {
                json_value *value = (json_value *)malloc(sizeof(json_value));
                value->type = JSON_BOOL;
                value->value.boolean = 0; // false
                return value;
            }
        case 'n':
            (*json) += 4; // Skip "null"
            {
                json_value *value = (json_value *)malloc(sizeof(json_value));
                value->type = JSON_NULL;
                return value; // NULL value
            }
        default:
            return parse_number(json);
    }
}

void print_json(json_value *value) {
    if (!value) return;
    switch (value->type) {
        case JSON_STRING:
            printf("\"%s\"", value->value.string);
            break;
        case JSON_NUMBER:
            printf("%lf", value->value.number);
            break;
        case JSON_BOOL:
            printf(value->value.boolean ? "true" : "false");
            break;
        case JSON_NULL:
            printf("null");
            break;
        case JSON_OBJECT:
            printf("{");
            json_value *current = value->next;
            while (current) {
                print_json(current); // Print key-value pair
                if (current->next) printf(", ");
                current = current->next;
            }
            printf("}");
            break;
        default:
            break;
    }
}

int main() {
    const char *json_string = "{\"name\": \"John\", \"age\": 30, \"is_student\": false, \"address\": {\"city\": \"New York\", \"zip\": \"10001\"}}";
    json_value *json = parse_json(json_string);

    printf("Parsed JSON:\n");
    print_json(json);
    printf("\n");

    free_json(json);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// JSON token types
typedef enum {
    TOKEN_ERROR,
    TOKEN_STRING,
    TOKEN_NUMBER,
    TOKEN_BOOLEAN,
    TOKEN_NULL,
    TOKEN_OBJECT_OPEN,
    TOKEN_OBJECT_CLOSE,
    TOKEN_ARRAY_OPEN,
    TOKEN_ARRAY_CLOSE,
    TOKEN_COLON,
    TOKEN_COMMA
} token_type;

// JSON token structure
typedef struct {
    token_type type;
    char* value;
} token;

// JSON parser structure
typedef struct {
    char* input;
    int pos;
    token token;
} json_parser;

// Function to create a new JSON parser
json_parser* json_parser_create(const char* input) {
    json_parser* parser = malloc(sizeof(json_parser));
    parser->input = strdup(input);
    parser->pos = 0;
    parser->token.type = TOKEN_ERROR;
    parser->token.value = NULL;
    return parser;
}

// Function to free a JSON parser
void json_parser_free(json_parser* parser) {
    free(parser->input);
    if (parser->token.value!= NULL) {
        free(parser->token.value);
    }
    free(parser);
}

// Function to get the next token
token_type json_parser_get_next_token(json_parser* parser) {
    // Skip whitespace
    while (isspace(parser->input[parser->pos])) {
        parser->pos++;
    }

    // Check for end of input
    if (parser->input[parser->pos] == '\0') {
        parser->token.type = TOKEN_ERROR;
        return parser->token.type;
    }

    // Handle string token
    if (parser->input[parser->pos] == '"') {
        parser->pos++;
        int start = parser->pos;
        while (parser->input[parser->pos]!= '"') {
            parser->pos++;
            if (parser->input[parser->pos] == '\0') {
                parser->token.type = TOKEN_ERROR;
                return parser->token.type;
            }
        }
        parser->token.value = malloc(parser->pos - start + 1);
        strncpy(parser->token.value, &parser->input[start], parser->pos - start);
        parser->token.value[parser->pos - start] = '\0';
        parser->pos++;
        parser->token.type = TOKEN_STRING;
        return parser->token.type;
    }

    // Handle number token
    if (isdigit(parser->input[parser->pos]) || parser->input[parser->pos] == '-') {
        int start = parser->pos;
        while (isdigit(parser->input[parser->pos]) || parser->input[parser->pos] == '.' || parser->input[parser->pos] == 'e' || parser->input[parser->pos] == 'E' || parser->input[parser->pos] == '-' || parser->input[parser->pos] == '+') {
            parser->pos++;
        }
        parser->token.value = malloc(parser->pos - start + 1);
        strncpy(parser->token.value, &parser->input[start], parser->pos - start);
        parser->token.value[parser->pos - start] = '\0';
        parser->token.type = TOKEN_NUMBER;
        return parser->token.type;
    }

    // Handle boolean token
    if (strncmp(&parser->input[parser->pos], "true", 4) == 0) {
        parser->pos += 4;
        parser->token.type = TOKEN_BOOLEAN;
        parser->token.value = strdup("true");
        return parser->token.type;
    }
    if (strncmp(&parser->input[parser->pos], "false", 5) == 0) {
        parser->pos += 5;
        parser->token.type = TOKEN_BOOLEAN;
        parser->token.value = strdup("false");
        return parser->token.type;
    }

    // Handle null token
    if (strncmp(&parser->input[parser->pos], "null", 4) == 0) {
        parser->pos += 4;
        parser->token.type = TOKEN_NULL;
        parser->token.value = NULL;
        return parser->token.type;
    }

    // Handle object open token
    if (parser->input[parser->pos] == '{') {
        parser->pos++;
        parser->token.type = TOKEN_OBJECT_OPEN;
        parser->token.value = NULL;
        return parser->token.type;
    }

    // Handle object close token
    if (parser->input[parser->pos] == '}') {
        parser->pos++;
        parser->token.type = TOKEN_OBJECT_CLOSE;
        parser->token.value = NULL;
        return parser->token.type;
    }

    // Handle array open token
    if (parser->input[parser->pos] == '[') {
        parser->pos++;
        parser->token.type = TOKEN_ARRAY_OPEN;
        parser->token.value = NULL;
        return parser->token.type;
    }

    // Handle array close token
    if (parser->input[parser->pos] == ']') {
        parser->pos++;
        parser->token.type = TOKEN_ARRAY_CLOSE;
        parser->token.value = NULL;
        return parser->token.type;
    }

    // Handle colon token
    if (parser->input[parser->pos] == ':') {
        parser->pos++;
        parser->token.type = TOKEN_COLON;
        parser->token.value = NULL;
        return parser->token.type;
    }

    // Handle comma token
    if (parser->input[parser->pos] == ',') {
        parser->pos++;
        parser->token.type = TOKEN_COMMA;
        parser->token.value = NULL;
        return parser->token.type;
    }

    // Handle error
    parser->token.type = TOKEN_ERROR;
    return parser->token.type;
}

// Function to parse a JSON object
void json_parser_parse_object(json_parser* parser) {
    // Check for object open token
    if (json_parser_get_next_token(parser)!= TOKEN_OBJECT_OPEN) {
        printf("Error: Expected object open token\n");
        return;
    }

    // Parse object contents
    while (1) {
        // Check for string token (key)
        if (json_parser_get_next_token(parser)!= TOKEN_STRING) {
            printf("Error: Expected string token (key)\n");
            return;
        }

        // Check for colon token
        if (json_parser_get_next_token(parser)!= TOKEN_COLON) {
            printf("Error: Expected colon token\n");
            return;
        }

        // Recursively parse value
        json_parser_get_next_token(parser);
        switch (parser->token.type) {
            case TOKEN_STRING:
                printf("String value: %s\n", parser->token.value);
                break;
            case TOKEN_NUMBER:
                printf("Number value: %s\n", parser->token.value);
                break;
            case TOKEN_BOOLEAN:
                printf("Boolean value: %s\n", parser->token.value);
                break;
            case TOKEN_NULL:
                printf("Null value\n");
                break;
            case TOKEN_OBJECT_OPEN:
                json_parser_parse_object(parser);
                break;
            case TOKEN_ARRAY_OPEN:
                json_parser_parse_array(parser);
                break;
            default:
                printf("Error: Unexpected token type\n");
                return;
        }

        // Check for comma token or object close token
        if (json_parser_get_next_token(parser) == TOKEN_COMMA) {
            continue;
        } else if (parser->token.type == TOKEN_OBJECT_CLOSE) {
            break;
        } else {
            printf("Error: Expected comma token or object close token\n");
            return;
        }
    }
}

// Function to parse a JSON array
void json_parser_parse_array(json_parser* parser) {
    // Check for array open token
    if (json_parser_get_next_token(parser)!= TOKEN_ARRAY_OPEN) {
        printf("Error: Expected array open token\n");
        return;
    }

    // Parse array contents
    while (1) {
        // Recursively parse value
        json_parser_get_next_token(parser);
        switch (parser->token.type) {
            case TOKEN_STRING:
                printf("String value: %s\n", parser->token.value);
                break;
            case TOKEN_NUMBER:
                printf("Number value: %s\n", parser->token.value);
                break;
            case TOKEN_BOOLEAN:
                printf("Boolean value: %s\n", parser->token.value);
                break;
            case TOKEN_NULL:
                printf("Null value\n");
                break;
            case TOKEN_OBJECT_OPEN:
                json_parser_parse_object(parser);
                break;
            case TOKEN_ARRAY_OPEN:
                json_parser_parse_array(parser);
                break;
            default:
                printf("Error: Unexpected token type\n");
                return;
        }

        // Check for comma token or array close token
        if (json_parser_get_next_token(parser) == TOKEN_COMMA) {
            continue;
        } else if (parser->token.type == TOKEN_ARRAY_CLOSE) {
            break;
        } else {
            printf("Error: Expected comma token or array close token\n");
            return;
        }
    }
}

