#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef enum {
    TOKEN_NONE,
    TOKEN_OBJECT_START,
    TOKEN_OBJECT_END,
    TOKEN_ARRAY_START,
    TOKEN_ARRAY_END,
    TOKEN_STRING,
    TOKEN_NUMBER,
    TOKEN_TRUE,
    TOKEN_FALSE,
    TOKEN_NULL,
    TOKEN_COMMA,
    TOKEN_COLON,
    TOKEN_END
} TokenType;

typedef struct {
    TokenType type;
    char *value;
} Token;

typedef struct {
    char *input;
    size_t index;
} Lexer;

typedef struct {
    Token **tokens;
    size_t count;
} TokenStream;

void lexer_init(Lexer *lexer, const char *input) {
    lexer->input = strdup(input);
    lexer->index = 0;
}

void lexer_destroy(Lexer *lexer) {
    free(lexer->input);
}

char lexer_next_char(Lexer *lexer) {
    if (lexer->index < strlen(lexer->input)) {
        return lexer->input[lexer->index++];
    }
    return '\0';
}

void lexer_skip_whitespace(Lexer *lexer) {
    while (isspace(lexer->input[lexer->index])) {
        lexer->index++;
    }
}

Token *lexer_next_token(Lexer *lexer) {
    lexer_skip_whitespace(lexer);

    char c = lexer_next_char(lexer);
    if (c == '\0') {
        return NULL;
    }

    Token *token = (Token *)malloc(sizeof(Token));
    token->type = TOKEN_NONE;
    token->value = NULL;

    switch (c) {
        case '{':
            token->type = TOKEN_OBJECT_START;
            break;
        case '}':
            token->type = TOKEN_OBJECT_END;
            break;
        case '[':
            token->type = TOKEN_ARRAY_START;
            break;
        case ']':
            token->type = TOKEN_ARRAY_END;
            break;
        case '"':
            token->type = TOKEN_STRING;
            token->value = (char *)malloc(1);
            token->value[0] = '\0';
            while ((c = lexer_next_char(lexer)) != '"') {
                token->value = (char *)realloc(token->value, strlen(token->value) + 2);
                token->value[strlen(token->value)] = c;
                token->value[strlen(token->value) + 1] = '\0';
            }
            break;
        case ',':
            token->type = TOKEN_COMMA;
            break;
        case ':':
            token->type = TOKEN_COLON;
            break;
        case 't':
            if (lexer->input[lexer->index] == 'r' && lexer->input[lexer->index + 1] == 'u' && lexer->input[lexer->index + 2] == 'e') {
                token->type = TOKEN_TRUE;
                lexer->index += 3;
            }
            break;
        case 'f':
            if (lexer->input[lexer->index] == 'a' && lexer->input[lexer->index + 1] == 'l' && lexer->input[lexer->index + 2] == 's' && lexer->input[lexer->index + 3] == 'e') {
                token->type = TOKEN_FALSE;
                lexer->index += 4;
            }
            break;
        case 'n':
            if (lexer->input[lexer->index] == 'u' && lexer->input[lexer->index + 1] == 'l' && lexer->input[lexer->index + 2] == 'l') {
                token->type = TOKEN_NULL;
                lexer->index += 3;
            }
            break;
        default:
            if (isdigit(c) || c == '-') {
                token->type = TOKEN_NUMBER;
                token->value = (char *)malloc(1);
                token->value[0] = c;
                token->value[1] = '\0';
                while (isdigit(lexer->input[lexer->index]) || lexer->input[lexer->index] == '.') {
                    token->value = (char *)realloc(token->value, strlen(token->value) + 2);
                    token->value[strlen(token->value)] = lexer_next_char(lexer);
                    token->value[strlen(token->value) + 1] = '\0';
                }
            }
            break;
    }

    return token;
}

TokenStream *tokenize(const char *input) {
    Lexer lexer;
    lexer_init(&lexer, input);

    TokenStream *stream = (TokenStream *)malloc(sizeof(TokenStream));
    stream->tokens = NULL;
    stream->count = 0;

    Token *token;
    while ((token = lexer_next_token(&lexer)) != NULL) {
        stream->tokens = (Token **)realloc(stream->tokens, sizeof(Token *) * (stream->count + 1));
        stream->tokens[stream->count++] = token;
    }

    lexer_destroy(&lexer);
    return stream;
}

void print_token(Token *token) {
    switch (token->type) {
        case TOKEN_NONE:
            printf("TOKEN_NONE\n");
            break;
        case TOKEN_OBJECT_START:
            printf("TOKEN_OBJECT_START\n");
            break;
        case TOKEN_OBJECT_END:
            printf("TOKEN_OBJECT_END\n");
            break;
        case TOKEN_ARRAY_START:
            printf("TOKEN_ARRAY_START\n");
            break;
        case TOKEN_ARRAY_END:
            printf("TOKEN_ARRAY_END\n");
            break;
        case TOKEN_STRING:
            printf("TOKEN_STRING: %s\n", token->value);
            break;
        case TOKEN_NUMBER:
            printf("TOKEN_NUMBER: %s\n", token->value);
            break;
        case TOKEN_TRUE:
            printf("TOKEN_TRUE\n");
            break;
        case TOKEN_FALSE:
            printf("TOKEN_FALSE\n");
            break;
        case TOKEN_NULL:
            printf("TOKEN_NULL\n");
            break;
        case TOKEN_COMMA:
            printf("TOKEN_COMMA\n");
            break;
        case TOKEN_COLON:
            printf("TOKEN_COLON\n");
            break;
        case TOKEN_END:
            printf("TOKEN_END\n");
            break;
    }
}

void print_tokens(TokenStream *stream) {
    for (size_t i = 0; i < stream->count; i++) {
        print_token(stream->tokens[i]);
    }
}

void free_tokens(TokenStream *stream) {
    for (size_t i = 0; i < stream->count; i++) {
        free(stream->tokens[i]->value);
        free(stream->tokens[i]);
    }
    free(stream->tokens);
    free(stream);
}

int main() {
    const char *json = "{\"name\": \"John\", \"age\": 30, \"isStudent\": false, \"courses\": [\"Math\", \"Physics\"]}";
    TokenStream *stream = tokenize(json);
    print_tokens(stream);
    free_tokens(stream);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define GRID_SIZE 40
#define SPIRAL_LENGTH 20

// Directions: Right, Down, Left, Up
const int dx[4] = {1, 0, -1, 0};
const int dy[4] = {0, 1, 0, -1};

// Function to calculate Fibonacci numbers
unsigned long long fibonacci(int n) {
    if (n <= 1) return n;
    unsigned long long a = 0, b = 1, temp;
    for (int i = 2; i <= n; i++) {
        temp = a + b;
        a = b;
        b = temp;
    }
    return b;
}

// Function to create and draw the Fibonacci spiral
void drawFibonacciSpiral() {
    // Create a 2D grid for drawing
    char grid[GRID_SIZE][GRID_SIZE];

    // Initialize grid with spaces
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            grid[i][j] = ' ';
        }
    }

    // Starting position (center of the grid)
    int x = GRID_SIZE / 2;
    int y = GRID_SIZE / 2;

    // Initial direction and step variables
    int dir = 0;  // Start moving right
    int steps = 1;
    int step_count = 0;
    int direction_changes = 0;

    // Draw Fibonacci spiral
    for (int i = 0; i < SPIRAL_LENGTH; i++) {
        // Calculate Fibonacci number for current step
        unsigned long long fib = fibonacci(i);

        // Limit the size of the visualization
        int fib_steps = (fib > 10) ? 10 : fib;

        // Draw the current Fibonacci number's steps
        for (int j = 0; j < fib_steps; j++) {
            // Mark the current position
            grid[y][x] = '*';

            // Move to next position
            x += dx[dir];
            y += dy[dir];

            // Prevent out-of-bounds
            if (x < 0 || x >= GRID_SIZE || y < 0 || y >= GRID_SIZE) {
                printf("Spiral exceeded grid size!\n");
                return;
            }
        }

        // Change direction
        step_count++;
        if (step_count == steps) {
            dir = (dir + 1) % 4;
            direction_changes++;

            // Increase step length every two direction changes
            if (direction_changes % 2 == 0) {
                steps++;
            }

            step_count = 0;
        }
    }

    // Print the grid
    printf("Fibonacci Spiral Visualization:\n");
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            printf("%c", grid[i][j]);
        }
        printf("\n");
    }
}

// Main function
int main() {
    drawFibonacciSpiral();
    return 0;
}

#include <stdio.h>
