#define SIZE 100
#define PI 3.14159265358979323846

void draw_spiral(int n) {
    // Create a 2D array for our canvas
    char canvas[SIZE][SIZE];

    // Initialize canvas with spaces
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            canvas[i][j] = ' ';
        }
    }

    // Center of the spiral
    int center_x = SIZE / 2;
    int center_y = SIZE / 2;

    // Fibonacci sequence variables
    int a = 0, b = 1, c;

    // Draw the spiral
    for (int i = 0; i < n; i++) {
        if (i == 0) {
            c = a;
        } else if (i == 1) {
            c = b;
        } else {
            c = a + b;
            a = b;
            b = c;
        }

        // Calculate the angle increment based on the golden ratio
        double golden_angle = 2 * PI * (1 - 0.618033988749895);

        // Draw the current Fibonacci number as a quarter turn
        for (double angle = 0; angle < PI/2; angle += 0.01) {
            double radius = c * 0.3; // Scale factor to fit in the canvas

            // Calculate coordinates
            int x = center_x + (int)(radius * cos(i * PI/2 + angle));
            int y = center_y + (int)(radius * sin(i * PI/2 + angle));

            // Make sure we stay within bounds
            if (x >= 0 && x < SIZE && y >= 0 && y < SIZE) {
                canvas[y][x] = '*';
            }
        }
    }

    // Print the canvas
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            printf("%c", canvas[i][j]);
        }
        printf("\n");
    }
}

