// Function to generate Fibonacci numbers
void generate_fibonacci(long long fib_sequence[], int count) {
    if (count <= 0) return;
    fib_sequence[0] = 0;
    if (count == 1) return;
    fib_sequence[1] = 1;

    for (int i = 2; i < count; i++) {
        fib_sequence[i] = fib_sequence[i - 1] + fib_sequence[i - 2];
        // Basic overflow check for long long, though unlikely for MAX_FIB_COUNT 40
        if (fib_sequence[i] < fib_sequence[i-1]) {
            fprintf(stderr, "Warning: Fibonacci sequence overflowed around index %d. Truncating.\n", i);
            fib_sequence[i] = -1; // Mark as invalid
            return;
        }
    }
}

