int main() {
    // 1. Initialize ASCII grid
    char grid[GRID_SIZE][GRID_SIZE];
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            grid[i][j] = '.'; // Empty space
        }
    }

    // 2. Generate Fibonacci sequence
    long long fib_sequence[MAX_FIB_COUNT];
    generate_fibonacci(fib_sequence, MAX_FIB_COUNT);

    printf("Generated Fibonacci Sequence (first %d numbers):\n", MAX_FIB_COUNT);
    for (int i = 0; i < MAX_FIB_COUNT; i++) {
        if (fib_sequence[i] == -1) break; // Stop if overflowed
        printf("%lld ", fib_sequence[i]);
    }
    printf("\n\n");

    // 3. Spiral Placement Logic
    int center_x = GRID_SIZE / 2;
    int center_y = GRID_SIZE / 2;

    int current_x = center_x;
    int current_y = center_y;

    int dx[] = {1, 0, -1, 0}; // Change in x (Right, Up, Left, Down)
    int dy[] = {0, -1, 0, 1}; // Change in y (Right, Up, Left, Down)
    int direction = 0;        // 0: Right, 1: Up, 2: Left, 3: Down

    int steps_in_direction = 1;
    int steps_taken = 0;
    int turns_made = 0;

    // Place the first Fibonacci number (0) at the center
    if (MAX_FIB_COUNT > 0 && fib_sequence[0] != -1) {
        if (current_x >= 0 && current_x < GRID_SIZE && current_y >= 0 && current_y < GRID_SIZE) {
            grid[current_y][current_x] = (char)((fib_sequence[0] % 10) + '0');
        }
    }

    for (int i = 1; i < MAX_FIB_COUNT; i++) {
        if (fib_sequence[i] == -1) break; // Stop if overflowed

        // Move according to current direction
        current_x += dx[direction];
        current_y += dy[direction];

        // Check bounds before placing
        if (current_x < 0 || current_x >= GRID_SIZE || current_y < 0 || current_y >= GRID_SIZE) {
            fprintf(stderr, "Warning: Spiral out of bounds for Fib number %d. Stopping.\n", i);
            break; // Stop if we hit the edge
        }

        // Place the last digit of the Fibonacci number
        grid[current_y][current_x] = (char)((fib_sequence[i] % 10) + '0');

        steps_taken++;

        // time to turn?
        if (steps_taken == steps_in_direction) {
            steps_taken = 0;           // Reset steps for new direction
            direction = (direction + 1) % 4; // Turn
            turns_made++;

            // Increase steps_in_direction after every two turns (i.e., after forming two sides of the square)
            if (turns_made % 2 == 0) {
                steps_in_direction++;
            }
        }
    }

    // 4. Print the final grid
    printf("Fibonacci Spiral ASCII Art (last digit of number):\n");
    print_grid(grid);

    return 0;
}

