// Generate Fibonacci numbers up to a maximum value
void generateFibonacci(int fib[], int n) {
    fib[0] = 1;
    fib[1] = 1;
    for (int i = 2; i < n; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }
}

// Draw the Fibonacci Spiral
void drawFibonacciSpiral(int size) {
    // Create a grid
    char grid[2 * size][2 * size];

    // Initialize grid with spaces
    for (int i = 0; i < 2 * size; i++) {
        for (int j = 0; j < 2 * size; j++) {
            grid[i][j] = ' ';
        }
    }

    // Fibonacci numbers
    int fib[size];
    generateFibonacci(fib, size);

    // Starting point
    int x = size;
    int y = size;
    int direction = 0; // 0 = right, 1 = down, 2 = left, 3 = up

    for (int i = 0; i < size; i++) {
        int steps = fib[i];
        for (int j = 0; j < steps; j++) {
            if (x >= 0 && x < 2 * size && y >= 0 && y < 2 * size) {
                grid[y][x] = '#';
            }

            // Move in the current direction
            switch (direction) {
                case 0: x++; break; // right
                case 1: y++; break; // down
                case 2: x--; break; // left
                case 3: y--; break; // up
            }
        }

        // Change direction
        direction = (direction + 1) % 4;
    }

    // Print the grid
    for (int i = 0; i < 2 * size; i++) {
        for (int j = 0; j < 2 * size; j++) {
            putchar(grid[i][j]);
        }
        putchar('\n');
    }
}

