// Function to draw the Fibonacci spiral
void drawSpiral(int n) {
    int sequence[n];
    sequence[0] = 1;
    sequence[1] = 1;

    // Calculate Fibonacci sequence
    for (int i = 2; i < n; i++) {
        sequence[i] = sequence[i - 1] + sequence[i - 2];
    }

    // Calculate spiral points
    Point points[n];
    int x = 0, y = 0;
    int dx = 1, dy = 0;

    for (int i = 0; i < n; i++) {
        points[i].x = x;
        points[i].y = y;

        // Update direction
        if (i % 4 == 0 && i!= 0) {
            int temp = dx;
            dx = -dy;
            dy = temp;
        }

        // Update position
        x += dx;
        y += dy;
    }

    // Draw spiral
    clearConsole();
    for (int i = 0; i < n; i++) {
        drawPoint(points[i], '*');
        fflush(stdout); // Flush output buffer
        usleep(50000); // Pause for 50ms
    }
}

