// Function to check if a string is a palindrome
bool isPalindrome(const char* str) {
    // If string is NULL or empty, it's not a palindrome
    if (str == NULL || *str == '\0') {
        return false;
    }

    // Get the length of the string
    int length = strlen(str);

    // Compare characters from start and end moving towards center
    for (int i = 0; i < length / 2; i++) {
        // If characters don't match, it's not a palindrome
        if (str[i] != str[length - 1 - i]) {
            return false;
        }
    }

    // If we've made it through the loop, it's a palindrome
    return true;
}

int main() {
    // The string to check
    const char* testString = "securePass123";

    // Check if the string is a palindrome
    if (isPalindrome(testString)) {
        printf("'%s' is a palindrome.\n", testString);
    } else {
        printf("'%s' is not a palindrome.\n", testString);
    }

    return 0;
}

