#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

// Memory block structure
typedef struct MemoryBlock {
    size_t size;
    int is_free;
    struct MemoryBlock* next;
} MemoryBlock;

// Global variables
#define ALIGNMENT 8
#define BLOCK_SIZE sizeof(MemoryBlock)
#define MEMORY_POOL_SIZE 1024 * 1024  // 1 MB memory pool

static char memory_pool[MEMORY_POOL_SIZE];
static MemoryBlock* head = NULL;

// Align memory to 8 bytes
size_t align_size(size_t size) {
    return (size + ALIGNMENT - 1) & ~(ALIGNMENT - 1);
}

// Initialize memory pool
void initialize_memory_pool() {
    head = (MemoryBlock*)memory_pool;
    head->size = MEMORY_POOL_SIZE - BLOCK_SIZE;
    head->is_free = 1;
    head->next = NULL;
}

// Custom memory allocation
void* custom_malloc(size_t size) {
    // Initialize memory pool if not already done
    if (head == NULL) {
        initialize_memory_pool();
    }

    // Align requested size
    size = align_size(size);

    MemoryBlock* current = head;
    MemoryBlock* prev = NULL;

    // Find a free block
    while (current != NULL) {
        if (current->is_free && current->size >= size) {
            // Split block if it's much larger
            if (current->size >= size + BLOCK_SIZE + ALIGNMENT) {
                MemoryBlock* new_block = (MemoryBlock*)((char*)current + BLOCK_SIZE + size);
                new_block->size = current->size - size - BLOCK_SIZE;
                new_block->is_free = 1;
                new_block->next = current->next;

                current->size = size;
                current->is_free = 0;
                current->next = new_block;
            } else {
                current->is_free = 0;
            }

            return (void*)(current + 1);
        }

        prev = current;
        current = current->next;
    }

    // No suitable block found
    return NULL;
}

// Custom memory free
void custom_free(void* ptr) {
    if (ptr == NULL) return;

    // Get memory block header
    MemoryBlock* block = ((MemoryBlock*)ptr) - 1;
    block->is_free = 1;

    // Merge adjacent free blocks
    MemoryBlock* current = head;
    while (current != NULL && current->next != NULL) {
        if (current->is_free && current->next->is_free) {
            current->size += current->next->size + BLOCK_SIZE;
            current->next = current->next->next;
        } else {
            current = current->next;
        }
    }
}

// Custom memory reallocation
void* custom_realloc(void* ptr, size_t new_size) {
    if (ptr == NULL) {
        return custom_malloc(new_size);
    }

    MemoryBlock* old_block = ((MemoryBlock*)ptr) - 1;
    new_size = align_size(new_size);

    // If new size is smaller, just update block size
    if (new_size <= old_block->size) {
        old_block->size = new_size;
        return ptr;
    }

    // Allocate new memory and copy data
    void* new_ptr = custom_malloc(new_size);
    if (new_ptr == NULL) {
        return NULL;
    }

    memcpy(new_ptr, ptr, old_block->size);
    custom_free(ptr);

    return new_ptr;
}

// Debug function to print memory pool status
void print_memory_pool() {
    MemoryBlock* current = head;
    printf("Memory Pool Status:\n");

    while (current != NULL) {
        printf("Block: size = %zu, free = %d\n", 
               current->size, current->is_free);
        current = current->next;
    }
}

// Example usage
int main() {
    // Initialize memory pool
    initialize_memory_pool();

    // Allocate memory
    int* arr1 = (int*)custom_malloc(10 * sizeof(int));
    int* arr2 = (int*)custom_malloc(5 * sizeof(int));

    // Fill arrays
    for (int i = 0; i < 10; i++) {
        arr1[i] = i;
    }

    // Print memory pool status
    print_memory_pool();

    // Free memory
    custom_free(arr1);
    custom_free(arr2);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stddef.h>
#include <stdbool.h>

#define MEMORY_SIZE 1024 * 1024  // 1 MB of memory

typedef struct Block {
    size_t size;
    bool is_free;
    struct Block* next;
} Block;

static char memory[MEMORY_SIZE];
static Block* free_list = NULL;

void initialize_allocator() {
    free_list = (Block*)memory;
    free_list->size = MEMORY_SIZE - sizeof(Block);
    free_list->is_free = true;
    free_list->next = NULL;
}

void split_block(Block* block, size_t size) {
    Block* new_block = (Block*)((char*)block + sizeof(Block) + size);
    new_block->size = block->size - size - sizeof(Block);
    new_block->is_free = true;
    new_block->next = block->next;

    block->size = size;
    block->is_free = false;
    block->next = new_block;
}

void* custom_malloc(size_t size) {
    if (size <= 0 || !free_list) {
        return NULL;
    }

    Block* current = free_list;
    Block* previous = NULL;

    while (current) {
        if (current->is_free && current->size >= size) {
            if (current->size > size + sizeof(Block)) {
                split_block(current, size);
            }
            current->is_free = false;
            return (void*)(current + 1);
        }
        previous = current;
        current = current->next;
    }

    return NULL;  // No suitable block found
}

void merge_blocks(Block* block) {
    if (block->next && block->next->is_free) {
        block->size += sizeof(Block) + block->next->size;
        block->next = block->next->next;
    }
}

void custom_free(void* ptr) {
    if (!ptr) {
        return;
    }

    Block* block = (Block*)ptr - 1;
    block->is_free = true;

    // Merge with previous block if it's free
    Block* current = free_list;
    Block* previous = NULL;

    while (current) {
        if (current->is_free && current->next == block) {
            merge_blocks(current);
            return;
        }
        previous = current;
        current = current->next;
    }

    // Merge with next block if it's free
    if (block->next && block->next->is_free) {
        merge_blocks(block);
    }
}

void* custom_calloc(size_t num, size_t size) {
    size_t total_size = num * size;
    void* ptr = custom_malloc(total_size);
    if (ptr) {
        memset(ptr, 0, total_size);
    }
    return ptr;
}

void* custom_realloc(void* ptr, size_t size) {
    if (!ptr) {
        return custom_malloc(size);
    }

    Block* block = (Block*)ptr - 1;
    if (block->size >= size) {
        return ptr;
    }

    void* new_ptr = custom_malloc(size);
    if (new_ptr) {
        memcpy(new_ptr, ptr, block->size);
        custom_free(ptr);
    }
    return new_ptr;
}

