#define POOL_SIZE 1024  // Size of the memory pool

typedef struct BlockHeader {
    size_t size;
    int free;
    struct BlockHeader* next;
} BlockHeader;

static uint8_t memory_pool[POOL_SIZE];
static BlockHeader* free_list = NULL;

// Initialize allocator
void my_allocator_init() {
    free_list = (BlockHeader*)memory_pool;
    free_list->size = POOL_SIZE - sizeof(BlockHeader);
    free_list->free = 1;
    free_list->next = NULL;
}

void* my_malloc(size_t size) {
    BlockHeader* curr = free_list;
    BlockHeader* prev = NULL;

    while (curr) {
        if (curr->free && curr->size >= size) {
            // Found a big enough block
            if (curr->size >= size + sizeof(BlockHeader) + 8) { // Split if large enough
                BlockHeader* new_block = (BlockHeader*)((uint8_t*)curr + sizeof(BlockHeader) + size);
                new_block->size = curr->size - size - sizeof(BlockHeader);
                new_block->free = 1;
                new_block->next = curr->next;

                curr->size = size;
                curr->free = 0;
                curr->next = new_block;
            } else {
                // No splitting, just mark as used
                curr->free = 0;
            }
            return (void*)((uint8_t*)curr + sizeof(BlockHeader));
        }
        prev = curr;
        curr = curr->next;
    }
    // No suitable block found
    return NULL;
}

void my_free(void* ptr) {
    if (!ptr || ptr < (void*)memory_pool || ptr >= (void*)(memory_pool + POOL_SIZE))
        return;

    BlockHeader* block = (BlockHeader*)((uint8_t*)ptr - sizeof(BlockHeader));
    block->free = 1;

    // Optional: Coalesce with next if free (not required)
    if (block->next && block->next->free) {
        block->size += sizeof(BlockHeader) + block->next->size;
        block->next = block->next->next;
    }

    // Optional: Coalesce with previous (not implemented for simplicity)
}

