#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>

// Define a block of memory
typedef struct Block {
    size_t size;
    struct Block *next;
    int free;
} Block;

#define BLOCK_SIZE sizeof(Block)

Block *freeList = NULL;

// Extend heap if no block is big enough
Block *extendHeap(Block *last, size_t size) {
    // Allocate more memory using sbrk
    Block *block = (Block *)sbrk(0);
    void *request = sbrk(size + BLOCK_SIZE);

    if (request == (void*)-1) {
        return NULL; // sbrk failed
    }

    // Setting block metadata
    if (last) {
        last->next = block;
    }

    block->size = size;
    block->next = NULL;
    block->free = 0;

    return block;
}

// Find a free block or request more memory to push onto heap
Block *findFreeBlock(Block **last, size_t size) {
    Block *current = freeList;
    while (current && !(current->free && current->size >= size)) {
        *last = current;
        current = current->next;
    }
    return current;
}

// Align size to 8 bytes boundary
size_t align8(size_t size) {
    if (size & 0x7) {
        size &= ~0x7;
        size += 8;
    }
    return size;
}

// Allocate memory
void *customMalloc(size_t size) {
    if (size <= 0) {
        return NULL;
    }

    size = align8(size);

    Block *block;

    // If freeList is empty, create a new block
    if (!freeList) {
        block = extendHeap(NULL, size);
        if (!block) {
            return NULL;
        }
        freeList = block;
    } else {
        Block *last = freeList;
        block = findFreeBlock(&last, size);
        if (!block) {
            block = extendHeap(last, size);
            if (!block) {
                return NULL;
            }
        } else {
            block->free = 0;
        }
    }

    return (block + 1);
}

// Free memory
void customFree(void *ptr) {
    if (!ptr) {
        return;
    }

    Block *block = (Block*)ptr - 1;
    block->free = 1;
}

// Reallocate memory
void *customRealloc(void *ptr, size_t size) {
    if (!ptr) {
        return customMalloc(size);
    }

    Block *block = (Block*)ptr - 1;

    if (block->size >= size) {
        return ptr; // If the current block is large enough, just return.
    }

    void *newPtr = customMalloc(size);
    if (!newPtr) {
        return NULL;
    }

    memcpy(newPtr, ptr, block->size);
    customFree(ptr);

    return newPtr;
}

// Testing our custom memory allocator
