    int *array = (int *)customMalloc(10 * sizeof(int));
    if (!array) {
        fprintf(stderr, "customMalloc failed\n");
        return 1;
    }

    for (int i = 0; i < 10; i++) {
        array[i] = i;
    }

    for (int i = 0; i < 10; i++) {
        printf("%d ", array[i]);
    }
    printf("\n");

    customFree(array);

    return 0;
}

#include <stdio.h>
