// Define a block header structure
typedef struct Block {
    size_t size;          // Size of the block
    struct Block* next;   // Pointer to the next block
    int free;            // Free flag
} Block;

#define BLOCK_SIZE sizeof(Block)

// Memory pool
static Block* head = NULL;
static char* memoryPool = NULL;
static size_t poolSize = 0;

// Initialize the memory pool
void init_memory_pool(size_t size) {
    poolSize = size;
    memoryPool = (char*)malloc(size);
    head = (Block*)memoryPool;
    head->size = size - BLOCK_SIZE;
    head->next = NULL;
    head->free = 1;
}

// Allocate memory from the pool
void* my_malloc(size_t size) {
    size += BLOCK_SIZE; // Account for block header
    Block* current = head;

    while (current) {
        if (current->free && current->size >= size) {
            // If block is large enough, split it
            if (current->size > size + BLOCK_SIZE) {
                Block* newBlock = (Block*)((char*)current + size);
                newBlock->size = current->size - size;
                newBlock->next = current->next;
                newBlock->free = 1;

                current->size = size - BLOCK_SIZE;
                current->next = newBlock;
            }

            current->free = 0; // Mark block as allocated
            return (char*)current + BLOCK_SIZE; // Return pointer to memory after the header
        }
        current = current->next;
    }

    // No suitable block found
    return NULL;
}

// Deallocate memory back to the pool
void my_free(void* ptr) {
    if (ptr == NULL) return;

    Block* block = (Block*)((char*)ptr - BLOCK_SIZE);
    block->free = 1; // Mark the block as free

    // Optionally, coalesce free blocks
    Block* current = head;
    while (current) {
        if (current->free && current->next && current->next->free) {
            current->size += BLOCK_SIZE + current->next->size;
            current->next = current->next->next;
        } else {
            current = current->next;
        }
    }
}

// Cleanup memory pool
void cleanup_memory_pool() {
    free(memoryPool);
    head = NULL;
    memoryPool = NULL;
    poolSize = 0;
}

// Example usage
int main() {
    init_memory_pool(1024); // Initialize a memory pool of 1024 bytes

    int* a = (int*)my_malloc(sizeof(int));
    float* b = (float*)my_malloc(sizeof(float) * 10);
    char* c = (char*)my_malloc(20);

    if (a) *a = 42;
    if (b) memset(b, 0, sizeof(float) * 10);
    if (c) strcpy(c, "Hello");

    printf("a: %d\n", *a);
    printf("b[0]: %f\n", b[0]);
    printf("c: %s\n", c);

    my_free(a);
    my_free(b);
    my_free(c);

    cleanup_memory_pool(); // Free the memory pool

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure to represent a block of memory
typedef struct MemoryBlock {
    size_t size;
    int free;
    struct MemoryBlock* next;
} MemoryBlock;

// Global variable to store the head of the memory list
MemoryBlock* memoryHead = NULL;

// Function to initialize the custom memory allocator
void initAllocator(size_t size) {
    // Allocate a large block of memory
    memoryHead = malloc(size + sizeof(MemoryBlock));
    if (memoryHead == NULL) {
        printf("Error: Unable to initialize allocator.\n");
        exit(1);
    }

    // Initialize the memory block
    memoryHead->size = size;
    memoryHead->free = 1;
    memoryHead->next = NULL;
}

// Function to allocate memory
void* allocateMemory(size_t size) {
    // Check if the allocator is initialized
    if (memoryHead == NULL) {
        printf("Error: Allocator not initialized.\n");
        return NULL;
    }

    // Traverse the memory list to find a free block
    MemoryBlock* current = memoryHead;
    while (current != NULL) {
        if (current->free && current->size >= size) {
            // Split the block if it is larger than the requested size
            if (current->size > size + sizeof(MemoryBlock)) {
                MemoryBlock* newBlock = (MemoryBlock*)((char*)current + sizeof(MemoryBlock) + size);
                newBlock->size = current->size - size - sizeof(MemoryBlock);
                newBlock->free = 1;
                newBlock->next = current->next;
                current->size = size;
                current->next = newBlock;
            }

            // Mark the block as allocated
            current->free = 0;

            // Return the address of the allocated memory
            return (void*)((char*)current + sizeof(MemoryBlock));
        }
        current = current->next;
    }

    // If no free block is found, return NULL
    return NULL;
}

// Function to free memory
void freeMemory(void* ptr) {
    // Check if the allocator is initialized
    if (memoryHead == NULL) {
        printf("Error: Allocator not initialized.\n");
        return;
    }

    // Check if the pointer is valid
    if (ptr == NULL) {
        printf("Error: Invalid pointer.\n");
        return;
    }

    // Traverse the memory list to find the block corresponding to the pointer
    MemoryBlock* current = memoryHead;
    MemoryBlock* previous = NULL;
    while (current != NULL) {
        if ((void*)((char*)current + sizeof(MemoryBlock)) == ptr) {
            // Mark the block as free
            current->free = 1;

            // Merge adjacent free blocks
            if (previous != NULL && previous->free) {
                previous->size += current->size + sizeof(MemoryBlock);
                previous->next = current->next;
            } else if (current->next != NULL && current->next->free) {
                current->size += current->next->size + sizeof(MemoryBlock);
                current->next = current->next->next;
            }

            return;
        }
        previous = current;
        current = current->next;
    }

    // If the pointer is not found, print an error message
    printf("Error: Invalid pointer.\n");
}

// Function to check for memory leaks
void checkLeaks() {
    // Traverse the memory list to find allocated blocks
    MemoryBlock* current = memoryHead;
    while (current != NULL) {
        if (!current->free) {
            printf("Memory leak detected at address %p with size %lu bytes.\n", (void*)((char*)current + sizeof(MemoryBlock)), current->size);
        }
        current = current->next;
    }
}

int main() {
    // Initialize the custom memory allocator
    initAllocator(1024);

    // Allocate memory
    int* ptr1 = (int*)allocateMemory(sizeof(int));
    if (ptr1 != NULL) {
        *ptr1 = 10;
        printf("%d\n", *ptr1);
    }

    double* ptr2 = (double*)allocateMemory(sizeof(double));
    if (ptr2 != NULL) {
        *ptr2 = 20.5;
        printf("%f\n", *ptr2);
    }

    // Free memory
    freeMemory(ptr1);
    freeMemory(ptr2);

    // Check for memory leaks
    checkLeaks();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MEMORY_POOL_SIZE (1024 * 1024) // 1 MB memory pool

typedef struct BlockHeader {
    size_t size;        // Size of the block
    int is_free;       // Is the block free?
    struct BlockHeader *next; // Pointer to the next block
} BlockHeader;

BlockHeader *memory_pool = NULL;
BlockHeader *free_list = NULL;

void initialize_memory_pool() {
    if (memory_pool == NULL) {
        memory_pool = (BlockHeader *)malloc(MEMORY_POOL_SIZE);
        if (memory_pool == NULL) {
            fprintf(stderr, "Failed to allocate memory pool\n");
            exit(1);
        }
        memory_pool->size = MEMORY_POOL_SIZE - sizeof(BlockHeader);
        memory_pool->is_free = 1;
        memory_pool->next = NULL;
        free_list = memory_pool;
    }
}

void *custom_malloc(size_t size) {
    if (size == 0) return NULL;

    BlockHeader *current = free_list;
    BlockHeader *prev = NULL;

    while (current != NULL) {
        if (current->is_free && current->size >= size) {
            current->is_free = 0;
            if (current->size > size + sizeof(BlockHeader)) {
                BlockHeader *new_block = (BlockHeader *)((char *)current + sizeof(BlockHeader) + size);
                new_block->size = current->size - size - sizeof(BlockHeader);
                new_block->is_free = 1;
                new_block->next = current->next;
                current->next = new_block;
                current->size = size;
            }
            return (void *)((char *)current + sizeof(BlockHeader));
        }
        prev = current;
        current = current->next;
    }

    // No free block found, try to extend the memory pool
    BlockHeader *new_block = (BlockHeader *)malloc(size + sizeof(BlockHeader));
    if (new_block == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        return NULL;
    }
    new_block->size = size;
    new_block->is_free = 0;
    new_block->next = NULL;

    if (prev != NULL) {
        prev->next = new_block;
    } else {
        free_list = new_block;
    }

    return (void *)((char *)new_block + sizeof(BlockHeader));
}

void custom_free(void *ptr) {
    if (ptr == NULL) return;

    BlockHeader *block = (BlockHeader *)((char *)ptr - sizeof(BlockHeader));

    block->is_free = 1;

    // Merge adjacent free blocks
    BlockHeader *current = block;
    BlockHeader *next = current->next;
    while (next != NULL && next->is_free) {
        current->size += next->size + sizeof(BlockHeader);
        current->next = next->next;
        next = current->next;
    }

    if (block != memory_pool) {
        BlockHeader *prev = free_list;
        while (prev->next != block) {
            prev = prev->next;
        }
        prev->next = block;
    } else {
        free_list = block;
    }
}

void *custom_calloc(size_t num, size_t size) {
    size_t total_size = num * size;
    void *ptr = custom_malloc(total_size);
    if (ptr != NULL) {
        memset(ptr, 0, total_size);
    }
    return ptr;
}

void *custom_realloc(void *ptr, size_t new_size) {
    if (ptr == NULL) return custom_malloc(new_size);
    if (new_size == 0) {
        custom_free(ptr);
        return NULL;
    }

    BlockHeader *block = (BlockHeader *)((char *)ptr - sizeof(BlockHeader));
    if (block->size >= new_size) return ptr;

    BlockHeader *new_block = custom_malloc(new_size);
    if (new_block == NULL) return NULL;

    memcpy(new_block, ptr, block->size);
    custom_free(ptr);

    return new_block;
}

int main() {
    initialize_memory_pool();

    void *ptr1 = custom_malloc(100);
    if (ptr1) {
        printf("Allocated 100 bytes at %p\n", ptr1);
    }

    void *ptr2 = custom_malloc(200);
    if (ptr2) {
        printf("Allocated 200 bytes at %p\n", ptr2);
    }

    custom_free(ptr1);
    printf("Freed 100 bytes at %p\n", ptr1);

    void *ptr3 = custom_realloc(ptr2, 300);
    if (ptr3) {
        printf("Reallocated 300 bytes at %p\n", ptr3);
    }

    void *ptr4 = custom_calloc(5, sizeof(int));
    if (ptr4) {
        printf("Allocated 20 bytes (5 ints) at %p\n", ptr4);
    }

    custom_free(ptr4);
    printf("Freed 20 bytes at %p\n", ptr4);

    custom_free(ptr3);
    printf("Freed 300 bytes at %p\n", ptr3);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <dirent.h>
#include <string.h>
#include <unistd.h>

#define MAX_PATH 256
#define MAX_LINE 1024

// Function to read process name
void get_process_name(int pid, char *name) {
    char path[MAX_PATH];
    FILE *file;

    // Construct path to process status file
    snprintf(path, sizeof(path), "/proc/%d/status", pid);

    file = fopen(path, "r");
    if (file == NULL) {
        strcpy(name, "Unknown");
        return;
    }

    char line[MAX_LINE];
    while (fgets(line, sizeof(line), file)) {
        if (strncmp(line, "Name:", 5) == 0) {
            // Extract process name
            sscanf(line + 5, "%s", name);
            break;
        }
    }

    fclose(file);
}

// Function to read process status
void get_process_status(int pid, char *status) {
    char path[MAX_PATH];
    FILE *file;

    // Construct path to process status file
    snprintf(path, sizeof(path), "/proc/%d/status", pid);

    file = fopen(path, "r");
    if (file == NULL) {
        strcpy(status, "Unknown");
        return;
    }

    char line[MAX_LINE];
    while (fgets(line, sizeof(line), file)) {
        if (strncmp(line, "State:", 6) == 0) {
            // Extract process status
            sscanf(line + 6, " %[^\n]", status);
            break;
        }
    }

    fclose(file);
}

// Function to list all running processes
void list_processes() {
    DIR *dir;
    struct dirent *entry;

    // Open /proc directory
    dir = opendir("/proc");
    if (dir == NULL) {
        perror("Error opening /proc directory");
        exit(1);
    }

    // Print header
    printf("PID\tNAME\t\tSTATUS\n");
    printf("---\t----\t\t------\n");

    // Iterate through /proc entries
    while ((entry = readdir(dir)) != NULL) {
        int pid;
        char name[MAX_LINE] = {0};
        char status[MAX_LINE] = {0};

        // Check if entry is a process directory
        if (sscanf(entry->d_name, "%d", &pid) == 1) {
            get_process_name(pid, name);
            get_process_status(pid, status);

            // Print process information
            printf("%d\t%-15s\t%s\n", pid, name, status);
        }
    }

    // Close directory
    closedir(dir);
}

// Main function
int main() {
    // Check if running with root privileges
    if (geteuid() != 0) {
        fprintf(stderr, "Warning: Some processes may not be visible without root privileges.\n");
    }

    // List all processes
    list_processes();

    return 0;
}

#include <stdio.h>
#include <dirent.h>
#include <ctype.h>
#include <stdlib.h>
#include <string.h>

// Function to check if a string is numeric (process IDs are numeric)
int is_numeric(const char *str) {
    while (*str) {
        if (!isdigit(*str)) {
            return 0;
        }
        str++;
    }
    return 1;
}

// Function to read process name from /proc/[pid]/status
void get_process_name(char *pid, char *name_buffer, size_t buffer_size) {
    char path[256];
    FILE *status_file;
    char line[256];

    snprintf(path, sizeof(path), "/proc/%s/status", pid);
    status_file = fopen(path, "r");
    if (status_file == NULL) {
        snprintf(name_buffer, buffer_size, "[unknown]");
        return;
    }

    // Read the first line which contains the process name
    if (fgets(line, sizeof(line), status_file)) {
        // Format: Name:   process_name
        char *colon = strchr(line, ':');
        if (colon) {
            colon += 2; // Skip ": " after the colon
            char *end = strchr(colon, '\n');
            if (end) *end = '\0';
            snprintf(name_buffer, buffer_size, "%s", colon);
        } else {
            snprintf(name_buffer, buffer_size, "[unknown]");
        }
    } else {
        snprintf(name_buffer, buffer_size, "[unknown]");
    }

    fclose(status_file);
}

int main() {
    DIR *proc_dir;
    struct dirent *entry;
    int count = 0;

    printf("Listing all running processes:\n");
    printf("PID\tProcess Name\n");
    printf("----------------------------\n");

    proc_dir = opendir("/proc");
    if (proc_dir == NULL) {
        perror("opendir failed");
        return 1;
    }

    while ((entry = readdir(proc_dir)) != NULL) {
        // Only interested in directories with numeric names (process IDs)
        if (entry->d_type == DT_DIR && is_numeric(entry->d_name)) {
            char process_name[256];
            get_process_name(entry->d_name, process_name, sizeof(process_name));
            printf("%s\t%s\n", entry->d_name, process_name);
            count++;
        }
    }

    closedir(proc_dir);
    printf("\nTotal processes: %d\n", count);
    return 0;
}

