#include <unistd.h> // For unistd.h functions like access (optional, but good for error checking)

// Max length for process name
#define MAX_PROC_NAME_LEN 256
// Max path length for /proc/PID/stat
#define MAX_PATH_LEN 1024

// Function to get the process name from /proc/[pid]/stat
// Returns 0 on success, -1 on failure
int get_process_name(pid_t pid, char *name_buffer, size_t buffer_size) {
    char stat_path[MAX_PATH_LEN];
    FILE *fp;

    snprintf(stat_path, sizeof(stat_path), "/proc/%d/stat", pid);

    fp = fopen(stat_path, "r");
    if (fp == NULL) {
        perror("Error opening /proc/[pid]/stat file");
        return -1;
    }

    // The format of /proc/[pid]/stat is complex, but the process name is usually
    // the second field, enclosed in parentheses.
    // Example: 1 (systemd) S 0 1 1 0 -1 4227072 ...
    // We need to read up to the first parenthesis, then extract content
    // within the parentheses for the name.

    char line_buffer[MAX_PATH_LEN * 2]; // A bit larger for the whole line
    if (fgets(line_buffer, sizeof(line_buffer), fp) == NULL) {
        fclose(fp);
        return -1;
    }
    fclose(fp);

    // Find the first opening parenthesis
    char *open_paren = strchr(line_buffer, '(');
    if (open_paren == NULL) {
        return -1; // Malformed stat file
    }

    // Find the last closing parenthesis (as the name might contain spaces and parentheses)
    char *close_paren = strrchr(line_buffer, ')');
    if (close_paren == NULL || close_paren <= open_paren) {
        return -1; // Malformed stat file
    }

    // Calculate length of the name
    size_t name_len = close_paren - (open_paren + 1);

    // Copy the name into the buffer, ensuring null termination and buffer bounds
    if (name_len < buffer_size) {
        strncpy(name_buffer, open_paren + 1, name_len);
        name_buffer[name_len] = '\0';
    } else {
        strncpy(name_buffer, open_paren + 1, buffer_size - 1);
        name_buffer[buffer_size - 1] = '\0';
    }

    return 0; // Success
}

int main() {
    DIR *dir;
    struct dirent *entry;
    char process_name[MAX_PROC_NAME_LEN];
    pid_t pid;

    // Open the /proc directory
    dir = opendir("/proc");
    if (dir == NULL) {
        perror("Error opening /proc directory. Do you have sufficient permissions?");
        return EXIT_FAILURE;
    }

    printf("PID\tProcess Name\n");
    printf("---\t------------\n");

    // Iterate through entries in /proc
    while ((entry = readdir(dir)) != NULL) {
        // We are looking for directories whose names consist only of digits (which represent PIDs)
        // Check if the directory name contains only digits
        int is_pid_dir = 1;
        for (int i = 0; entry->d_name[i] != '\0'; i++) {
            if (entry->d_name[i] < '0' || entry->d_name[i] > '9') {
                is_pid_dir = 0;
                break;
            }
        }

        if (is_pid_dir) {
            pid = atoi(entry->d_name); // Convert the directory name to a PID

            // Get the process name
            if (get_process_name(pid, process_name, sizeof(process_name)) == 0) {
                printf("%d\t%s\n", pid, process_name);
            } else {
                // If get_process_name fails, the process might have exited
                // or there was a file system error.
                // We'll just print PID and indicate name couldn't be retrieved.
                // fprintf(stderr, "Warning: Could not retrieve name for PID %d\n", pid);
                printf("%d\t[Name not found or exited]\n", pid);

            }
        }
    }

    closedir(dir); // Close the /proc directory

    return EXIT_SUCCESS;
}

