    for (int i = 0; dirname[i] != '\0'; i++) {
        if (!isdigit(dirname[i])) {
            return 0;
        }
    }
    return 1;
}

// Function to read the process name from the /proc/PID/stat file
void read_process_name(const char *pid_path) {
    char stat_path[256];
    snprintf(stat_path, sizeof(stat_path), "%s/stat", pid_path);

    FILE *file = fopen(stat_path, "r");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    char comm[256];
    // Reading the process name (second field in the stat file)
    if (fscanf(file, "%*d (%[^)])", comm) != 1) {
        perror("fscanf");
        fclose(file);
        return;
    }

    printf("Process Name: %s\n", comm);
    fclose(file);
}

