// Structure to hold process information
typedef struct {
    int pid;
    char name[256];
} Process;

// Function to get process information from /proc/<pid>/status
void get_process_info(const char *pid_dir, Process *process) {
    FILE *status_file;
    char path[256], line[256];

    // Construct the path to the status file
    snprintf(path, sizeof(path), "/proc/%s/status", pid_dir);

    // Open the status file
    status_file = fopen(path, "r");
    if (status_file == NULL) {
        printf("Error opening %s\n", path);
        return;
    }

    // Read the status file line by line
    while (fgets(line, sizeof(line), status_file) != NULL) {
        // Extract the process name
        if (strncmp(line, "Name:", 5) == 0) {
            sscanf(line, "Name: %s", process->name);
            break;
        }
    }

    // Close the status file
    fclose(status_file);
}

// Function to list all running processes
void list_processes() {
    DIR *proc_dir;
    struct dirent *entry;
    Process process;

    // Open the /proc directory
    proc_dir = opendir("/proc");
    if (proc_dir == NULL) {
        printf("Error opening /proc directory\n");
        return;
    }

    // Iterate over all directories in /proc
    while ((entry = readdir(proc_dir)) != NULL) {
        // Check if the directory is a process directory (i.e., it's a number)
        if (isdigit(entry->d_name[0])) {
            // Extract the process ID
            process.pid = atoi(entry->d_name);

            // Get the process information
            get_process_info(entry->d_name, &process);

            // Print the process information
            printf("PID: %d, Name: %s\n", process.pid, process.name);
        }
    }

    // Close the /proc directory
    closedir(proc_dir);
}

