// Fuzzy search function
int fuzzy_match(const char* pattern, const char* text) {
    if (!pattern || !text) return 0;

    while (*pattern && *text) {
        // Skip non-matching characters
        if (tolower(*pattern) == tolower(*text)) {
            pattern++;
        }
        text++;
    }

    // Return true if all pattern characters were matched
    return *pattern == '\0';
}

// Function to read process name from /proc/[pid]/comm
int get_process_name(int pid, char* name, size_t size) {
    char path[256];
    FILE* file;

    snprintf(path, sizeof(path), "/proc/%d/comm", pid);
    file = fopen(path, "r");

    if (!file) {
        return 0;
    }

    if (fgets(name, size, file) == NULL) {
        fclose(file);
        return 0;
    }

    // Remove newline character
    name[strcspn(name, "\n")] = 0;
    fclose(file);
    return 1;
}

// Function to read process status from /proc/[pid]/status
int get_process_status(int pid, char* status, size_t size) {
    char path[256];
    FILE* file;
    char line[256];

    snprintf(path, sizeof(path), "/proc/%d/status", pid);
    file = fopen(path, "r");

    if (!file) {
        return 0;
    }

    while (fgets(line, sizeof(line), file)) {
        if (strncmp(line, "State:", 6) == 0) {
            char* state_start = line + 6;
            while (isspace(*state_start)) state_start++;

            strncpy(status, state_start, size);
            status[strcspn(status, "\n")] = 0;

            fclose(file);
            return 1;
        }
    }

    fclose(file);
    return 0;
}

void list_processes(const char* filter) {
    DIR* dir;
    struct dirent* entry;

    dir = opendir("/proc");
    if (dir == NULL) {
        perror("Unable to open /proc directory");
        exit(1);
    }

    printf("%-6s %-20s %-10s %s\n", "PID", "NAME", "STATUS", "COMMAND");
    printf("---------------------------------------------------\n");

    while ((entry = readdir(dir)) != NULL) {
        int pid;
        char name[256] = {0};
        char status[256] = {0};
        char cmdline[512] = {0};

        // Check if entry is a process directory (numeric)
        if (sscanf(entry->d_name, "%d", &pid) != 1) {
            continue;
        }

        // Get process name
        if (!get_process_name(pid, name, sizeof(name))) {
            continue;
        }

        // Apply name filter if provided
        if (filter && !fuzzy_match(filter, name)) {
            continue;
        }

        // Get process status
        get_process_status(pid, status, sizeof(status));

        // Read command line
        char cmdpath[256];
        snprintf(cmdpath, sizeof(cmdpath), "/proc/%d/cmdline", pid);
        FILE* cmdfile = fopen(cmdpath, "r");
        if (cmdfile) {
            fgets(cmdline, sizeof(cmdline), cmdfile);
            fclose(cmdfile);
        }

        printf("%-6d %-20s %-10s %s\n", 
               pid, 
               name, 
               status, 
               cmdline);
    }

    closedir(dir);
}

int main(int argc, char* argv[]) {
    const char* filter = NULL;

    // Parse command-line arguments
    if (argc > 1) {
        filter = argv[1];
    }

    // Check root/sudo privileges
    if (geteuid() != 0) {
        printf("Warning: Some process information might be limited without root privileges.\n");
    }

    list_processes(filter);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <ctype.h>
#include <stdbool.h>

#define MAX_PROCESSES 1024
#define MAX_NAME_LENGTH 256
#define MAX_PATH_LENGTH 512

// Function to check if a string contains another string (case-insensitive)
bool fuzzy_match(const char *str, const char *pattern) {
    if (!pattern || !*pattern) return true; // No filter means match everything

    const char *p = pattern;
    const char *s = str;

    while (*s) {
        if (tolower(*p) == tolower(*s)) {
            p++;
            if (!*p) return true; // All pattern characters matched
        }
        s++;
    }

    return false;
}

// Function to get the process name from /proc/[pid]/status
int get_process_name(pid_t pid, char *name, size_t name_len) {
    char path[MAX_PATH_LENGTH];
    FILE *status_file;
    char line[256];

    snprintf(path, sizeof(path), "/proc/%d/status", pid);

    status_file = fopen(path, "r");
    if (!status_file) {
        return -1;
    }

    while (fgets(line, sizeof(line), status_file)) {
        if (strncmp(line, "Name:", 5) == 0) {
            char *start = line + 5;
            while (*start == ' ' || *start == '\t') start++;
            char *end = strchr(start, '\n');
            if (end) *end = '\0';

            strncpy(name, start, name_len);
            name[name_len - 1] = '\0';
            fclose(status_file);
            return 0;
        }
    }

    fclose(status_file);
    return -1;
}

// Main function to list processes
void list_processes(const char *filter) {
    DIR *proc_dir;
    struct dirent *entry;
    pid_t pids[MAX_PROCESSES];
    int count = 0;

    proc_dir = opendir("/proc");
    if (!proc_dir) {
        perror("Failed to open /proc");
        exit(EXIT_FAILURE);
    }

    // First pass: collect all process IDs
    while ((entry = readdir(proc_dir)) != NULL && count < MAX_PROCESSES) {
        pid_t pid = atoi(entry->d_name);
        if (pid > 0) {
            pids[count++] = pid;
        }
    }
    closedir(proc_dir);

    // Second pass: get process names and print matching ones
    printf("%-8s %-20s %s\n", "PID", "Name", "Command Line");
    printf("----------------------------------------\n");

    for (int i = 0; i < count; i++) {
        char name[MAX_NAME_LENGTH];
        char cmdline[MAX_PATH_LENGTH] = {0};

        if (get_process_name(pids[i], name, sizeof(name)) == 0) {
            // Check if the name matches our filter
            if (fuzzy_match(name, filter)) {
                // Try to read the command line
                char path[MAX_PATH_LENGTH];
                snprintf(path, sizeof(path), "/proc/%d/cmdline", pids[i]);
                FILE *cmdline_file = fopen(path, "r");
                if (cmdline_file) {
                    size_t n = fread(cmdline, 1, sizeof(cmdline) - 1, cmdline_file);
                    fclose(cmdline_file);

                    // Replace null bytes with spaces for readability
                    for (size_t j = 0; j < n; j++) {
                        if (cmdline[j] == '\0') cmdline[j] = ' ';
                    }
                }

                printf("%-8d %-20s %s\n", pids[i], name, cmdline);
            }
        }
    }
}

int main(int argc, char *argv[]) {
    const char *filter = NULL;

    if (argc > 1) {
        if (strcmp(argv[1], "--help") == 0 || strcmp(argv[1], "-h") == 0) {
            printf("Usage: %s [filter]\n", argv[0]);
            printf("Lists all running processes, optionally filtered by name.\n");
            printf("The filter uses fuzzy matching (case-insensitive substring search).\n");
            return EXIT_SUCCESS;
        }
        filter = argv[1];
    }

    list_processes(filter);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <ctype.h>
#include <getopt.h> // For getopt_long

#define MAX_PROC_NAME 256
#define MAX_LINE_LENGTH 512

// Function to perform a simple fuzzy match (subsequence check)
// Returns 1 if 'query' is a fuzzy match for 'text', 0 otherwise.
int fuzzymatch(const char *text, const char *query) {
    if (!query || *query == '\0') {
        return 1; // Empty query matches everything
    }

    const char *t = text;
    const char *q = query;

    while (*q != '\0') {
        int found_char = 0;
        while (*t != '\0') {
            // Case-insensitive comparison
            if (tolower((unsigned char)*t) == tolower((unsigned char)*q)) {
                found_char = 1;
                t++; // Move to the next character in text
                break; // Found the current query character, move to the next query character
            }
            t++;
        }
        if (!found_char) {
            return 0; // Current query character not found in remaining text
        }
        q++; // Move to the next query character
    }
    return 1; // All query characters found in sequence within text
}

// Function to get process name from /proc/<pid>/comm
// Returns 1 on success, 0 on failure. Sets process_name.
int get_process_name(pid_t pid, char *process_name, size_t name_len) {
    char path[MAX_LINE_LENGTH];
    snprintf(path, sizeof(path), "/proc/%d/comm", pid);

    FILE *f = fopen(path, "r");
    if (f == NULL) {
        // Fallback to /proc/<pid>/stat if comm is not available or permissions issue
        snprintf(path, sizeof(path), "/proc/%d/stat", pid);
        f = fopen(path, "r");
        if (f == NULL) {
            return 0; // Cannot open comm or stat
        }
        // Read process name from stat file (it's the second field, enclosed in parentheses)
        // Format: pid (name) state ...
        char buffer[MAX_LINE_LENGTH];
        if (fgets(buffer, sizeof(buffer), f) == NULL) {
            fclose(f);
            return 0;
        }

        char *open_paren = strchr(buffer, '(');
        char *close_paren = strrchr(buffer, ')');
        if (open_paren && close_paren && close_paren > open_paren) {
            size_t len = close_paren - open_paren - 1;
            if (len >= name_len) len = name_len - 1; // Ensure buffer overflow protection
            strncpy(process_name, open_paren + 1, len);
            process_name[len] = '\0';
            fclose(f);
            return 1;
        }
        fclose(f);
        return 0;

    } else {
        // Read from comm file
        if (fgets(process_name, name_len, f) == NULL) {
            fclose(f);
            return 0;
        }
        // Remove trailing newline character if present
        process_name[strcspn(process_name, "\n")] = '\0';
        fclose(f);
        return 1;
    }
}


int main(int argc, char *argv[]) {
    DIR *dir;
    struct dirent *entry;
    char *filter_query = NULL;

    // Command-line options
    static struct option long_options[] = {
        {"filter", required_argument, 0, 'f'},
        {"help",   no_argument,       0, 'h'},
        {0, 0, 0, 0}
    };

    int opt;
    int option_index = 0;
    while ((opt = getopt_long(argc, argv, "f:h", long_options, &option_index)) != -1) {
        switch (opt) {
            case 'f':
                filter_query = optarg;
                printf("Filtering by: '%s'\n", filter_query);
                break;
            case 'h':
                printf("Usage: %s [--filter <name>] [OPTIONS]\n", argv[0]);
                printf("Lists all running processes on Linux.\n");
                printf("\nOptions:\n");
                printf("  -f, --filter <name>  Fuzzy search for process names matching <name>.\n");
                printf("  -h, --help           Display this help message.\n");
                return 0;
            case '?':
                // getopt_long already prints an error message
                return 1;
        }
    }

    dir = opendir("/proc");
    if (dir == NULL) {
        perror("Error opening /proc");
        return 1;
    }

    printf("%-8s %s\n", "PID", "NAME");
    printf("---------------------------\n");

    while ((entry = readdir(dir)) != NULL) {
        // Check if the directory name is a number (a PID)
        if (entry->d_type == DT_DIR) {
            pid_t pid = strtol(entry->d_name, NULL, 10);
            if (pid != 0) { // strtol returns 0 if conversion fails or if it's "0"
                char process_name[MAX_PROC_NAME];
                if (get_process_name(pid, process_name, sizeof(process_name))) {
                    if (filter_query == NULL || fuzzymatch(process_name, filter_query)) {
                        printf("%-8d %s\n", pid, process_name);
                    }
                }
            }
        }
    }

    closedir(dir);
    return 0;
}

