        char name[256];
        if (get_proc_name(pid, name, sizeof(name)) != 0)
            continue;

        // Fuzzy search (case-insensitive substring)
        if (filter && !strcasestr(name, filter))
            continue;

        printf("%-7d %s\n", pid, name);
    }
    closedir(proc);
    return 0;
}

