// Simple Levenshtein distance implementation
int levenshtein_distance(const char *s1, const char *s2) {
    int len1 = strlen(s1);
    int len2 = strlen(s2);
    int **dp = malloc((len1 + 1) * sizeof(int *));
    for (int i = 0; i <= len1; i++) {
        dp[i] = malloc((len2 + 1) * sizeof(int));
    }
    for (int i = 0; i <= len1; i++) {
        dp[i][0] = i;
    }
    for (int j = 0; j <= len2; j++) {
        dp[0][j] = j;
    }
    for (int i = 1; i <= len1; i++) {
        for (int j = 1; j <= len2; j++) {
            int cost = (s1[i - 1] == s2[j - 1]) ? 0 : 1;
            dp[i][j] = ((dp[i - 1][j] + 1) < (dp[i][j - 1] + 1)) ? (dp[i - 1][j] + 1) : (dp[i][j - 1] + 1);
            dp[i][j] = ((dp[i][j]) < (dp[i - 1][j - 1] + cost)) ? (dp[i][j]) : (dp[i - 1][j - 1] + cost);
        }
    }
    int distance = dp[len1][len2];
    for (int i = 0; i <= len1; i++) {
        free(dp[i]);
    }
    free(dp);
    return distance;
}

// Simple fuzzy search implementation
int fuzzy_search(const char *target, const char *pattern) {
    int distance = levenshtein_distance(target, pattern);
    int target_len = strlen(target);
    int pattern_len = strlen(pattern);
    // Simple heuristic: if the distance is less than or equal to the length of the pattern,
    // consider it a match
    return distance <= pattern_len;
}

// List all running processes
void list_processes(const char *filter) {
    FILE *fp;
    char command[256];
    sprintf(command, "ps -eo pid,comm");
    fp = popen(command, "r");
    if (fp == NULL) {
        perror("Failed to list processes");
        return;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Parse PID and process name from line
        char *pid_str = strtok(line, " ");
        char *comm = strtok(NULL, "\n");
        if (comm == NULL) continue;
        if (filter != NULL) {
            if (!fuzzy_search(comm, filter)) {
                continue;
            }
        }
        printf("%s %s\n", pid_str, comm);
    }
    pclose(fp);
}

