// Function to calculate Levenshtein distance
int levenshtein(const char *s1, const char *s2) {
    size_t len1 = strlen(s1);
    size_t len2 = strlen(s2);
    size_t i, j;
    int d[2][len2 + 1];

    for (j = 0; j <= len2; j++)
        d[0][j] = j;

    for (i = 1; i <= len1; i++) {
        d[i % 2][0] = i;
        for (j = 1; j <= len2; j++) {
            int cost = (s1[i - 1] == s2[j - 1]) ? 0 : 1;
            d[i % 2][j] = (d[(i - 1) % 2][j] + 1) < (d[i % 2][j - 1] + 1) ? (d[(i - 1) % 2][j] + 1) : (d[i % 2][j - 1] + 1);
            d[i % 2][j] = d[i % 2][j] < (d[(i - 1) % 2][j - 1] + cost) ? d[i % 2][j] : (d[(i - 1) % 2][j - 1] + cost);
        }
    }
    return d[len1 % 2][len2];
}

// Function to read the command name from /proc
char* read_command_name(pid_t pid) {
    char filename[64];
    char buffer[1024];
    char *cmdline = NULL;
    FILE *fp;

    snprintf(filename, sizeof(filename), "/proc/%d/cmdline", pid);
    fp = fopen(filename, "r");
    if (fp) {
        if (fgets(buffer, sizeof(buffer), fp)) {
            cmdline = strdup(buffer);
            for (char *p = cmdline; *p; ++p) {
                if (*p == '\0') {
                    *p = ' ';
                }
            }
            cmdline[strcspn(cmdline, "\n")] = 0; // Remove newline
        }
        fclose(fp);
    }
    return cmdline;
}

// Function to list processes
void list_processes(const char *filter) {
    DIR *dir;
    struct dirent *entry;
    char *cmdline;
    int threshold = 3; // Threshold for fuzzy search

    dir = opendir("/proc");
    if (dir == NULL) {
        perror("opendir");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_DIR) {
            long pid = atol(entry->d_name);
            if (pid > 0) {
                cmdline = read_command_name(pid);
                if (cmdline) {
                    if (filter == NULL || levenshtein(cmdline, filter) <= threshold) {
                        printf("%-6ld %s\n", pid, cmdline);
                    }
                    free(cmdline);
                }
            }
        }
    }

    closedir(dir);
}

