#define MAX_INTERFACES 10
#define PROC_NET_DEV "/proc/net/dev"

// Structure to store network interface statistics
typedef struct {
    char name[16];
    unsigned long long rx_bytes;
    unsigned long long tx_bytes;
} NetworkInterface;

// Function to read network interface statistics
int read_network_stats(NetworkInterface* interfaces) {
    FILE* fp;
    char line[256];
    int count = 0;

    fp = fopen(PROC_NET_DEV, "r");
    if (fp == NULL) {
        perror("Error opening /proc/net/dev");
        return -1;
    }

    // Skip header lines
    fgets(line, sizeof(line), fp);
    fgets(line, sizeof(line), fp);

    while (fgets(line, sizeof(line), fp) && count < MAX_INTERFACES) {
        char* token = strtok(line, ":");
        if (token != NULL) {
            strcpy(interfaces[count].name, token);
            token = strtok(NULL, " ");

            // Parse receive bytes
            interfaces[count].rx_bytes = strtoull(token, NULL, 10);

            // Skip some tokens to get to transmit bytes
            for (int i = 0; i < 7; i++) {
                token = strtok(NULL, " ");
            }

            // Parse transmit bytes
            interfaces[count].tx_bytes = strtoull(token, NULL, 10);

            count++;
        }
    }

    fclose(fp);
    return count;
}

// Function to calculate bandwidth usage
void calculate_bandwidth(NetworkInterface* prev, NetworkInterface* curr, int count, double interval) {
    printf("\n--- Network Bandwidth Usage ---\n");
    printf("Interface\tRx (KB/s)\tTx (KB/s)\n");

    for (int i = 0; i < count; i++) {
        // Calculate bytes transferred during interval
        unsigned long long rx_diff = curr[i].rx_bytes - prev[i].rx_bytes;
        unsigned long long tx_diff = curr[i].tx_bytes - prev[i].tx_bytes;

        // Convert to KB/s
        double rx_speed = (rx_diff / interval) / 1024.0;
        double tx_speed = (tx_diff / interval) / 1024.0;

        printf("%-10s\t%-10.2f\t%-10.2f\n", 
               curr[i].name, rx_speed, tx_speed);
    }
}

int main() {
    NetworkInterface prev_interfaces[MAX_INTERFACES];
    NetworkInterface curr_interfaces[MAX_INTERFACES];
    int interface_count;
    double interval = 1.0;  // 1 second interval

    // Initial network stats reading
    interface_count = read_network_stats(prev_interfaces);
    if (interface_count < 0) {
        return 1;
    }

    // Main monitoring loop
    while (1) {
        // Sleep for specified interval
        sleep(interval);

        // Read current network stats
        interface_count = read_network_stats(curr_interfaces);
        if (interface_count < 0) {
            break;
        }

        // Calculate and display bandwidth usage
        calculate_bandwidth(prev_interfaces, curr_interfaces, interface_count, interval);

        // Copy current stats to previous for next iteration
        memcpy(prev_interfaces, curr_interfaces, 
               sizeof(NetworkInterface) * interface_count);
    }

    return 0;
}

