#include <arpa/inet.h>
#endif

typedef struct {
    unsigned long long bytes_received;
    unsigned long long bytes_sent;
} NetworkStats;

void get_network_stats(NetworkStats *stats) {
#ifdef _WIN32
    MIB_IFTABLE *ifTable;
    DWORD dwSize = 0;
    DWORD dwRetVal = 0;

    // First call to get buffer size
    if (GetIfTable(NULL, &dwSize, 0) == ERROR_INSUFFICIENT_BUFFER) {
        ifTable = (MIB_IFTABLE *)malloc(dwSize);
    } else {
        perror("Error getting interface table size");
        return;
    }

    // Second call to get actual data
    if ((dwRetVal = GetIfTable(ifTable, &dwSize, 0)) != NO_ERROR) {
        free(ifTable);
        perror("Error getting interface table");
        return;
    }

    stats->bytes_received = 0;
    stats->bytes_sent = 0;

    for (int i = 0; i < ifTable->dwNumEntries; i++) {
        MIB_IFROW ifRow = ifTable->table[i];
        // Skip loopback interface
        if (ifRow.dwType != MIB_IF_TYPE_LOOPBACK) {
            stats->bytes_received += ifRow.dwInOctets;
            stats->bytes_sent += ifRow.dwOutOctets;
        }
    }

    free(ifTable);
#else
    FILE *fp = fopen("/proc/net/dev", "r");
    if (fp == NULL) {
        perror("Error opening /proc/net/dev");
        return;
    }

    char line[256];
    // Skip the first two lines (header)
    fgets(line, sizeof(line), fp);
    fgets(line, sizeof(line), fp);

    stats->bytes_received = 0;
    stats->bytes_sent = 0;

    while (fgets(line, sizeof(line), fp)) {
        char iface[32];
        unsigned long long rbytes, tbytes;

        // Parse the line
        if (sscanf(line, "%31[^:]: %llu %*u %*u %*u %*u %*u %*u %*u %llu",
                   iface, &rbytes, &tbytes) == 3) {
            // Skip loopback interface
            if (strncmp(iface, "lo", 2) != 0) {
                stats->bytes_received += rbytes;
                stats->bytes_sent += tbytes;
            }
        }
    }

    fclose(fp);
#endif
}

void format_bytes(unsigned long long bytes, char *buffer) {
    const char *units[] = {"B", "KB", "MB", "GB", "TB"};
    int unit = 0;
    double size = (double)bytes;

    while (size >= 1024 && unit < 4) {
        size /= 1024;
        unit++;
    }

    sprintf(buffer, "%.2f %s", size, units[unit]);
}

int main() {
    NetworkStats prev_stats, curr_stats;
    time_t prev_time, curr_time;
    double time_diff;
    char rx_str[32], tx_str[32];
    char rx_rate_str[32], tx_rate_str[32];

    // Get initial stats
    get_network_stats(&prev_stats);
    prev_time = time(NULL);

    printf("Network Bandwidth Monitor\n");
    printf("------------------------\n");
    printf("Press Ctrl+C to exit...\n\n");

    while (1) {
        sleep(1); // Wait for 1 second

        // Get current stats
        get_network_stats(&curr_stats);
        curr_time = time(NULL);

        // Calculate time difference
        time_diff = difftime(curr_time, prev_time);

        // Calculate rates (bytes per second)
        double rx_rate = (curr_stats.bytes_received - prev_stats.bytes_received) / time_diff;
        double tx_rate = (curr_stats.bytes_sent - prev_stats.bytes_sent) / time_diff;

        // Format the output
        format_bytes(curr_stats.bytes_received, rx_str);
        format_bytes(curr_stats.bytes_sent, tx_str);
        format_bytes((unsigned long long)rx_rate, rx_rate_str);
        format_bytes((unsigned long long)tx_rate, tx_rate_str);

        // Display the results
        printf("\033[2J\033[H"); // Clear screen (ANSI escape codes)
        printf("Network Bandwidth Usage:\n");
        printf("Total Received: %s\n", rx_str);
        printf("Total Sent:     %s\n", tx_str);
        printf("Receive Rate:   %s/s\n", rx_rate_str);
        printf("Transmit Rate:  %s/s\n", tx_rate_str);

        // Update previous stats
        prev_stats = curr_stats;
        prev_time = curr_time;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h> // For sleep()

#define MAX_LINE_LENGTH 256
#define FILE_PATH "/proc/net/dev"
#define INTERFACE "eth0" // Change this to your network interface (e.g., "wlan0", "eno1")

// Function to get RX and TX bytes for a given interface
int get_interface_bytes(const char *interface_name, unsigned long long *rx_bytes, unsigned long long *tx_bytes) {
    FILE *fp;
    char line[MAX_LINE_LENGTH];
    char *token;
    int found = 0;

    fp = fopen(FILE_PATH, "r");
    if (fp == NULL) {
        perror("Error opening /proc/net/dev");
        return -1;
    }

    // Skip the first two header lines
    fgets(line, sizeof(line), fp);
    fgets(line, sizeof(line), fp);

    while (fgets(line, sizeof(line), fp) != NULL) {
        // Find the interface name in the line
        if (strstr(line, interface_name) != NULL) {
            found = 1;
            // Tokenize the line to extract byte counts
            // Example line format:
            // "   eth0: 1234567890 123  456    7  8  9   10   11   1234567890 123  456    7  8  9   10   11"
            // We need the 1st (RX bytes) and 9th (TX bytes) tokens after the interface name.

            // Replace colon and remove leading/trailing spaces for simpler parsing
            char *colon_pos = strchr(line, ':');
            if (colon_pos) {
                *colon_pos = ' '; // Replace colon with space
            }

            token = strtok(line, " "); // First token is empty or interface name
            if (token == NULL || strcmp(token, interface_name) != 0) {
                 token = strtok(NULL, " "); // Get actual interface name if first was empty
            }

            if (token == NULL || strcmp(token, interface_name) != 0) {
                // Should not happen if strstr found it, but good for robustness
                continue;
            }

            // Read RX bytes (first value after interface name)
            token = strtok(NULL, " "); // bytes
            if (token) *rx_bytes = strtoull(token, NULL, 10); else found = 0;

            // Skip packets, errs, drop, fifo, frame, compressed, multicast (7 tokens)
            for (int i = 0; i < 7; ++i) {
                token = strtok(NULL, " ");
                if (!token) { found = 0; break; }
            }

            // Read TX bytes (first value after 7 skipped tokens)
            if (found) {
                token = strtok(NULL, " "); // bytes
                if (token) *tx_bytes = strtoull(token, NULL, 10); else found = 0;
            }
            break; // Interface found and data extracted
        }
    }

    fclose(fp);
    return found ? 0 : -1; // Return 0 on success, -1 on failure/not found
}

int main() {
    unsigned long long prev_rx_bytes = 0;
    unsigned long long prev_tx_bytes = 0;
    unsigned long long current_rx_bytes = 0;
    unsigned long long current_tx_bytes = 0;

    double rx_bandwidth_kbps;
    double tx_bandwidth_kbps;
    int interval_seconds = 1; // Sample every 1 second

    printf("Monitoring bandwidth for interface: %s\n", INTERFACE);
    printf("Press Ctrl+C to stop.\n");

    // Get initial bytes to calculate difference later
    if (get_interface_bytes(INTERFACE, &prev_rx_bytes, &prev_tx_bytes) != 0) {
        fprintf(stderr, "Error: Could not get initial data for interface %s. Make sure it's correct.\n", INTERFACE);
        return 1;
    }

    while (1) {
        sleep(interval_seconds); // Wait for the specified interval

        if (get_interface_bytes(INTERFACE, &current_rx_bytes, &current_tx_bytes) != 0) {
            fprintf(stderr, "Error: Could not get current data for interface %s. Skipping this interval.\n", INTERFACE);
            // Optionally, you might want to reset prev_bytes here if the interface reappears
            prev_rx_bytes = current_rx_bytes;
            prev_tx_bytes = current_tx_bytes;
            continue;
        }

        // Calculate differences
        unsigned long long delta_rx_bytes = current_rx_bytes - prev_rx_bytes;
        unsigned long long delta_tx_bytes = current_tx_bytes - prev_tx_bytes;

        // Calculate bandwidth in KB/s (Bytes/second / 1024)
        // Since interval is 1 second, delta_bytes is effectively bytes/second
        rx_bandwidth_kbps = (double)delta_rx_bytes / 1024.0;
        tx_bandwidth_kbps = (double)delta_tx_bytes / 1024.0;

        printf("RX: %.2f KB/s | TX: %.2f KB/s\n", rx_bandwidth_kbps, tx_bandwidth_kbps);

        // Update previous bytes for the next iteration
        prev_rx_bytes = current_rx_bytes;
        prev_tx_bytes = current_tx_bytes;
    }

    return 0;
}

#include <stdio.h>
