#define MAX_IFACES 32
#define IFACE_NAME_LEN 32

typedef struct {
    char name[IFACE_NAME_LEN];
    uint64_t rx_bytes;
    uint64_t tx_bytes;
} iface_stat;

int read_iface_stats(iface_stat stats[], int *iface_count) {
    FILE *fp = fopen("/proc/net/dev", "r");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    char line[256];
    int line_num = 0;
    *iface_count = 0;

    while (fgets(line, sizeof(line), fp)) {
        line_num++;
        if (line_num <= 2) continue; // Skip headers

        char *colon = strchr(line, ':');
        if (!colon) continue;
        *colon = '\0';

        char iface[IFACE_NAME_LEN];
        snprintf(iface, IFACE_NAME_LEN, "%s", line);
        iface[strcspn(iface, " ")] = '\0'; // Remove trailing spaces

        uint64_t rx_bytes, tx_bytes;
        sscanf(colon + 1,
               " %lu %*lu %*lu %*lu %*lu %*lu %*lu %*lu"
               " %lu",
               &rx_bytes, &tx_bytes);

        snprintf(stats[*iface_count].name, IFACE_NAME_LEN, "%s", iface);
        stats[*iface_count].rx_bytes = rx_bytes;
        stats[*iface_count].tx_bytes = tx_bytes;
        (*iface_count)++;

        if (*iface_count >= MAX_IFACES) break;
    }
    fclose(fp);
    return 0;
}

void print_stats(iface_stat prev[], iface_stat curr[], int count, double dt) {
    printf("%-12s %-14s %-14s\n", "Interface", "RX (KB/s)", "TX (KB/s)");
    printf("----------------------------------------------------\n");
    for (int i = 0; i < count; i++) {
        double rx_rate = (curr[i].rx_bytes - prev[i].rx_bytes) / 1024.0 / dt;
        double tx_rate = (curr[i].tx_bytes - prev[i].tx_bytes) / 1024.0 / dt;
        printf("%-12s %10.2f     %10.2f\n", curr[i].name, rx_rate, tx_rate);
    }
    printf("\n");
}

int main() {
    iface_stat prev[MAX_IFACES], curr[MAX_IFACES];
    int prev_count = 0, curr_count = 0;

    if (read_iface_stats(prev, &prev_count) != 0) {
        fprintf(stderr, "Failed to read network stats\n");
        return 1;
    }

    while (1) {
        sleep(1);
        if (read_iface_stats(curr, &curr_count) != 0) {
            fprintf(stderr, "Failed to read network stats\n");
            return 1;
        }

        // Only compare interfaces that exist in both snapshots
        int count = 0;
        for (int i = 0; i < curr_count; i++) {
            for (int j = 0; j < prev_count; j++) {
                if (strcmp(curr[i].name, prev[j].name) == 0) {
                    // Only keep matched interfaces in curr
                    curr[count] = curr[i];
                    prev[count] = prev[j];
                    count++;
                    break;
                }
            }
        }

        printf("\033[2J\033[H"); // Clear screen
        print_stats(prev, curr, count, 1.0);

        // Prepare for next iteration
        memcpy(prev, curr, sizeof(iface_stat) * count);
        prev_count = count;
    }
    return 0;
}

