#define INTERFACE "eth0" // replace with your network interface name

// Function to read network statistics for a specific interface
void get_network_usage(const char* interface, unsigned long *rx_bytes, unsigned long *tx_bytes) {
    FILE *fp = fopen("/proc/net/dev", "r");
    if (fp == NULL) {
        perror("Error opening /proc/net/dev");
        exit(EXIT_FAILURE);
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strstr(line, interface)) {
            sscanf(line, "%*s %lu %*lu %*lu %*lu %*lu %*lu %*lu %*lu %lu", rx_bytes, tx_bytes);
            break;
        }
    }
    fclose(fp);
}

// Function to print network usage
void print_usage(unsigned long rx_bytes, unsigned long tx_bytes, unsigned long rx_rate, unsigned long tx_rate) {
    printf("Download: %lu bytes (%lu bytes/sec)\n", rx_bytes, rx_rate);
    printf("Upload: %lu bytes (%lu bytes/sec)\n", tx_bytes, tx_rate);
}

int main() {
    unsigned long old_rx_bytes, old_tx_bytes;
    unsigned long new_rx_bytes, new_tx_bytes;
    unsigned long rx_rate, tx_rate;
    const int interval = 1; // Set interval in seconds

    // Initial read
    get_network_usage(INTERFACE, &old_rx_bytes, &old_tx_bytes);

    while (1) {
        sleep(interval);
        get_network_usage(INTERFACE, &new_rx_bytes, &new_tx_bytes);

        // Calculate rates
        rx_rate = (new_rx_bytes - old_rx_bytes) / interval;
        tx_rate = (new_tx_bytes - old_tx_bytes) / interval;

        // Print usage
        print_usage(new_rx_bytes, new_tx_bytes, rx_rate, tx_rate);

        // Update old values
        old_rx_bytes = new_rx_bytes;
        old_tx_bytes = new_tx_bytes;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define BUFFER_SIZE 1024
#define INTERVAL 1 // Update interval in seconds

void get_network_stats(long *rx_bytes, long *tx_bytes) {
    FILE *file = fopen("/proc/net/dev", "r");
    char buffer[BUFFER_SIZE];

    if (file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Skip the first two lines
    fgets(buffer, BUFFER_SIZE, file);
    fgets(buffer, BUFFER_SIZE, file);

    *rx_bytes = 0;
    *tx_bytes = 0;

    // Read the network statistics
    while (fgets(buffer, BUFFER_SIZE, file)) {
        char interface[32];
        long rx, tx;

        // Parse the line for interface, received bytes, and transmitted bytes
        sscanf(buffer, "%s %ld %*d %*d %*d %*d %*d %*d %ld", interface, &rx, &tx);

        *rx_bytes += rx;
        *tx_bytes += tx;
    }

    fclose(file);
}

void monitor_bandwidth() {
    long old_rx_bytes = 0, old_tx_bytes = 0;
    long rx_bytes, tx_bytes;

    get_network_stats(&old_rx_bytes, &old_tx_bytes);

    while (1) {
        sleep(INTERVAL);

        get_network_stats(&rx_bytes, &tx_bytes);

        long rx_diff = rx_bytes - old_rx_bytes;
        long tx_diff = tx_bytes - old_tx_bytes;

        // Calculate bandwidth in KB/s
        double rx_bandwidth = (rx_diff / 1024.0) / INTERVAL;
        double tx_bandwidth = (tx_diff / 1024.0) / INTERVAL;

        printf("Received: %.2f KB/s, Transmitted: %.2f KB/s\n", rx_bandwidth, tx_bandwidth);

        // Update old values
        old_rx_bytes = rx_bytes;
        old_tx_bytes = tx_bytes;
    }
}

int main() {
    monitor_bandwidth();
    return 0;
}

