// Function to get the network interface name
char* getInterfaceName() {
    DIR* dir;
    struct dirent* ent;
    struct stat sb;
    char* interfaceName = NULL;

    // Open the /sys/class/net directory
    dir = opendir("/sys/class/net");
    if (dir == NULL) {
        printf("Error opening /sys/class/net directory\n");
        exit(1);
    }

    // Iterate through the directory entries
    while ((ent = readdir(dir)) != NULL) {
        // Check if the entry is a directory
        if (stat(ent->d_name, &sb) == 0 && S_ISDIR(sb.st_mode)) {
            // Check if the directory contains "statistics" subdirectory
            if (chdir(ent->d_name) == 0) {
                struct stat st;
                if (stat("statistics", &st) == 0 && S_ISDIR(st.st_mode)) {
                    interfaceName = ent->d_name;
                    break;
                }
                chdir("..");
            }
        }
    }

    closedir(dir);
    return interfaceName;
}

// Function to get the network interface statistics
void getInterfaceStats(char* interfaceName) {
    char fileName[256];
    FILE* file;
    unsigned long rxBytes, txBytes;

    // Create the file path for the interface statistics
    sprintf(fileName, "/sys/class/net/%s/statistics/rx_bytes", interfaceName);

    // Open the file for reading
    file = fopen(fileName, "r");
    if (file == NULL) {
        printf("Error opening %s file\n", fileName);
        exit(1);
    }

    // Read the received bytes
    fscanf(file, "%lu", &rxBytes);
    fclose(file);

    // Create the file path for the interface statistics
    sprintf(fileName, "/sys/class/net/%s/statistics/tx_bytes", interfaceName);

    // Open the file for reading
    file = fopen(fileName, "r");
    if (file == NULL) {
        printf("Error opening %s file\n", fileName);
        exit(1);
    }

    // Read the transmitted bytes
    fscanf(file, "%lu", &txBytes);
    fclose(file);

    // Calculate the bandwidth
    unsigned long bandwidthRx = rxBytes / 1024;  // kilobytes
    unsigned long bandwidthTx = txBytes / 1024;  // kilobytes

    printf("Network Interface: %s\n", interfaceName);
    printf("Received Bandwidth: %lu KB/s\n", bandwidthRx);
    printf("Transmitted Bandwidth: %lu KB/s\n", bandwidthTx);
}

int main() {
    // Get the network interface name
    char* interfaceName = getInterfaceName();

    if (interfaceName != NULL) {
        // Get the network interface statistics
        getInterfaceStats(interfaceName);
    } else {
        printf("No network interface found\n");
    }

    return 0;
}

