} NetworkStats;

int read_network_stats(const char *interface, NetworkStats *stats) {
    FILE *fp;
    char line[256];
    char dev_name[16];

    fp = fopen(PROC_NET_DEV, "r");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    // Skip the first two header lines
    fgets(line, sizeof(line), fp);
    fgets(line, sizeof(line), fp);

    while (fgets(line, sizeof(line), fp)) {
        sscanf(line, "%15s %llu %*u %*u %*u %*u %*u %*u %*u %llu",
               dev_name, &stats->rx_bytes, &stats->tx_bytes);
        if (strcmp(dev_name, interface) == 0) {
            fclose(fp);
            return 0;
        }
    }

    fclose(fp);
    return -1;
}

void print_bandwidth(const char *interface, unsigned long long old_rx, unsigned long long old_tx,
                    unsigned long long new_rx, unsigned long long new_tx, double elapsed_time) {
    double rx_bandwidth = (new_rx - old_rx) / elapsed_time;
    double tx_bandwidth = (new_tx - old_tx) / elapsed_time;

    printf("Interface: %s\n", interface);
    printf("Download (RX): %.2f KB/s\n", rx_bandwidth / 1024.0);
    printf("Upload (TX): %.2f KB/s\n", tx_bandwidth / 1024.0);
}

int main() {
    NetworkStats old_stats, new_stats;
    double elapsed_time;
    time_t start_time, end_time;

    if (read_network_stats(INTERFACE_NAME, &old_stats) != 0) {
        fprintf(stderr, "Failed to read initial network stats.\n");
        return 1;
    }

    time(&start_time);

    while (1) {
        sleep(1);  // Sleep for 1 second

        if (read_network_stats(INTERFACE_NAME, &new_stats) != 0) {
            fprintf(stderr, "Failed to read updated network stats.\n");
            return 1;
        }

        time(&end_time);
        elapsed_time = difftime(end_time, start_time);

        print_bandwidth(INTERFACE_NAME, old_stats.rx_bytes, old_stats.tx_bytes,
                        new_stats.rx_bytes, new_stats.tx_bytes, elapsed_time);

        old_stats = new_stats;
        start_time = end_time;
    }

    return 0;
}

