// Function to calculate f(x) = x^power
double f(double x, int power) {
    return pow(x, power);
}

// Simpson's Rule for numerical integration
double simpsons_rule(double a, double b, int n, int power) {
    // Ensure n is even
    if (n % 2 != 0) {
        printf("Number of subintervals must be even. Incrementing by 1.\n");
        n++;
    }

    // Width of each subinterval
    double h = (b - a) / n;

    // Initialize sum
    double sum = f(a, power) + f(b, power);

    // Compute coefficients for interior points
    for (int i = 1; i < n; i++) {
        double x = a + i * h;

        // Alternate coefficient (4 for odd indices, 2 for even indices)
        if (i % 2 == 0) {
            sum += 2 * f(x, power);
        } else {
            sum += 4 * f(x, power);
        }
    }

    // Multiply by h/3
    return (h / 3) * sum;
}

int main() {
    double a, b;  // Integration limits
    int power, n;  // Power of x and number of subintervals

    // Input integration limits
    printf("Enter lower limit (a): ");
    scanf("%lf", &a);

    printf("Enter upper limit (b): ");
    scanf("%lf", &b);

    // Input power of x
    printf("Enter power of x: ");
    scanf("%d", &power);

    // Input number of subintervals
    printf("Enter number of subintervals (must be even): ");
    scanf("%d", &n);

    // Compute integral
    double result = simpsons_rule(a, b, n, power);

    // Analytical solution for comparison
    double analytical = (pow(b, power + 1) - pow(a, power + 1)) / (power + 1);

    // Print results
    printf("\nNumerical Integration Results:\n");
    printf("Function: f(x) = x^%d\n", power);
    printf("Integration Limits: [%.2f, %.2f]\n", a, b);
    printf("Number of Subintervals: %d\n", n);
    printf("Numerical Result (Simpson's Rule): %f\n", result);
    printf("Analytical Result: %f\n", analytical);
    printf("Absolute Error: %e\n", fabs(result - analytical));
    printf("Relative Error: %e%%\n", 100.0 * fabs((result - analytical) / analytical));

    return 0;
}

