    double sum = f(a, power) + f(b, power);  // First and last terms

    for (int i = 1; i < n; i++) {
        double x = a + i * h;
        if (i % 2 == 0) {
            sum += 2 * f(x, power);  // Even terms
        } else {
            sum += 4 * f(x, power);  // Odd terms
        }
    }

