// Function f(x) = x^power
double f(double x, int power) {
    return pow(x, power);
}

// Function to perform numerical integration using Simpson's Rule
// f: The function to integrate
// a: The lower limit of integration
// b: The upper limit of integration
// n: The number of subintervals (must be an even integer)
// power: The exponent for the function f(x) = x^power
double simpsonsRule(double (*func)(double, int), double a, double b, int n, int power) {
    if (n % 2 != 0) {
        printf("Error: Number of subintervals (n) must be an even integer for Simpson's Rule.\n");
        return 0.0; // Indicate an error
    }

    double h = (b - a) / n;
    double integral = func(a, power) + func(b, power); // f(x_0) + f(x_n)

    for (int i = 1; i < n; i++) {
        double x_i = a + i * h;
        if (i % 2 == 0) {
            integral += 2 * func(x_i, power); // Even terms (2 * f(x_even))
        } else {
            integral += 4 * func(x_i, power); // Odd terms (4 * f(x_odd))
        }
    }

    return (h / 3) * integral;
}

int main() {
    double a, b;
    int power;
    int n;

    printf("Enter the lower limit of integration (a): ");
    scanf("%lf", &a);

    printf("Enter the upper limit of integration (b): ");
    scanf("%lf", &b);

    printf("Enter the power for f(x) = x^power: ");
    scanf("%d", &power);

    printf("Enter the number of subintervals (n, must be even): ");
    scanf("%d", &n);

    if (n <= 0) {
        printf("Error: Number of subintervals (n) must be a positive integer.\n");
        return 1;
    }

    // Call Simpson's Rule function
    double result = simpsonsRule(f, a, b, n, power);

    if (result == 0.0 && n % 2 != 0) {
        // Error message already printed by simpsonsRule
        return 1;
    }

    printf("\nNumerical integration of f(x) = x^%d from %.2lf to %.2lf using Simpson's Rule with %d subintervals:\n", power, a, b, n);
    printf("Result: %.6lf\n", result);

    // Optional: Calculate and print the exact analytical result for comparison
    // For x^power, the integral is [1/(power+1)] * x^(power+1)
    if (power != -1) { // Avoid division by zero if power is -1
        double exact_result = (1.0 / (power + 1)) * (pow(b, power + 1) - pow(a, power + 1));
        printf("Exact Analytical Result: %.6lf\n", exact_result);
        printf("Absolute Error: %.6e\n", fabs(result - exact_result));
    } else {
        // Special case for integral of x^-1 = ln|x|
        if (a > 0 && b > 0) {
            double exact_result = log(b) - log(a);
            printf("Exact Analytical Result (for x^-1): %.6lf\n", exact_result);
            printf("Absolute Error: %.6e\n", fabs(result - exact_result));
        } else {
            printf("Exact analytical result (for x^-1) not calculated due to non-positive limits.\n");
        }
    }

    return 0;
}

