    if (server_socket < 0) {
        perror("Socket creation failed");
        exit(1);
    }

    // Configure server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    // Bind socket
    if (bind(server_socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Binding failed");
        exit(1);
    }

    // Listen for connections
    listen(server_socket, 1);
    printf("Server listening on port %d...\n", PORT);

    // Accept client connection
    client_socket = accept(server_socket, (struct sockaddr*)&client_addr, &client_addr_len);
    if (client_socket < 0) {
        perror("Connection acceptance failed");
        exit(1);
    }

    // Step 2: Receive SYN from client
    recv(client_socket, &recv_packet, sizeof(recv_packet), 0);
    if (recv_packet.flags & SYN_FLAG) {
        printf("Received SYN from client (Seq: %d)\n", recv_packet.seq_num);

        // Step 3: Send SYN-ACK
        send_packet.seq_num = 1000;  // Server's initial sequence number
        send_packet.ack_num = recv_packet.seq_num + 1;
        send_packet.flags = SYN_FLAG | ACK_FLAG;
        send(client_socket, &send_packet, sizeof(send_packet), 0);
        printf("Sent SYN-ACK to client (Seq: %d, Ack: %d)\n", send_packet.seq_num, send_packet.ack_num);
    }

    // Step 4: Receive ACK from client
    recv(client_socket, &recv_packet, sizeof(recv_packet), 0);
    if (recv_packet.flags & ACK_FLAG) {
        printf("Received ACK from client (Seq: %d, Ack: %d)\n", recv_packet.seq_num, recv_packet.ack_num);
        printf("Three-way handshake completed successfully!\n");
    }

    // Close sockets
    close(client_socket);
    close(server_socket);
}

