// Packet structure to simulate TCP segments
typedef struct {
    uint32_t seq_num;
    uint32_t ack_num;
    uint16_t flags;  // SYN, ACK, FIN bits
} tcp_packet;

void print_packet_info(const char* action, const tcp_packet* pkt) {
    printf("%s - SEQ: %u, ACK: %u, FLAGS: ", action, pkt->seq_num, pkt->ack_num);
    if (pkt->flags & 0x02) printf("SYN ");
    if (pkt->flags & 0x10) printf("ACK ");
    if (pkt->flags & 0x01) printf("FIN ");
    printf("\n");
}

int main() {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t addr_len = sizeof(client_addr);
    tcp_packet send_pkt, recv_pkt;
    char buffer[MAX_BUFFER];

    // Create server socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Configure server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    // Bind socket to the port
    if (bind(server_fd, (struct sockaddr*)&server_addr, sizeof(server_addr)) == -1) {
        perror("bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(server_fd, 1) == -1) {
        perror("listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d...\n", PORT);

    // Accept a client connection
    if ((client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &addr_len)) == -1) {
        perror("accept failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Client connected. Starting three-way handshake...\n");

    // Step 1: Receive SYN from client
    if (recv(client_fd, &recv_pkt, sizeof(recv_pkt), 0) == -1) {
        perror("recv failed");
        close(client_fd);
        close(server_fd);
        exit(EXIT_FAILURE);
    }
    print_packet_info("Received", &recv_pkt);

    if (!(recv_pkt.flags & 0x02)) { // Check SYN flag
        printf("Error: Expected SYN packet\n");
        close(client_fd);
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Step 2: Send SYN-ACK to client
    send_pkt.seq_num = 5000; // Server's initial sequence number
    send_pkt.ack_num = recv_pkt.seq_num + 1;
    send_pkt.flags = 0x12; // SYN and ACK flags set

    if (send(client_fd, &send_pkt, sizeof(send_pkt), 0) == -1) {
        perror("send failed");
        close(client_fd);
        close(server_fd);
        exit(EXIT_FAILURE);
    }
    print_packet_info("Sent", &send_pkt);

    // Step 3: Receive ACK from client
    if (recv(client_fd, &recv_pkt, sizeof(recv_pkt), 0) == -1) {
        perror("recv failed");
        close(client_fd);
        close(server_fd);
        exit(EXIT_FAILURE);
    }
    print_packet_info("Received", &recv_pkt);

    if (!(recv_pkt.flags & 0x10) || recv_pkt.ack_num != send_pkt.seq_num + 1) {
        printf("Error: Expected ACK packet with correct acknowledgment\n");
        close(client_fd);
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Three-way handshake completed. Connection established.\n");

    // Connection is now established - you can add data transfer here

    close(client_fd);
    close(server_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <time.h> // For srand/rand

#define PORT 8080
#define MAX_BUFFER_SIZE 1024

// --- Simulated TCP Segment Types ---
typedef enum {
    SYN,        // Client to Server: Synchronize
    SYN_ACK,    // Server to Client: Synchronize + Acknowledge
    ACK         // Client to Server: Acknowledge
} packet_type_t;

// --- Simulated TCP Segment Structure ---
typedef struct {
    packet_type_t type;
    int seq_num; // Sequence number being sent
    int ack_num; // Acknowledgment number (expected next sequence from peer)
} tcp_segment_t;

// --- Helper function to initialize a segment ---
tcp_segment_t init_segment(packet_type_t type, int seq, int ack) {
    tcp_segment_t segment;
    segment.type = type;
    segment.seq_num = seq;
    segment.ack_num = ack;
    return segment;
}

// --- Helper function to print segment details ---
void print_segment(const char* role, const char* direction, const tcp_segment_t* pkt) {
    printf("[%s] %s packet (Type: ", role, direction);
    switch (pkt->type) {
        case SYN:
            printf("SYN");
            break;
        case SYN_ACK:
            printf("SYN-ACK");
            break;
        case ACK:
            printf("ACK");
            break;
        default:
            printf("UNKNOWN");
            break;
    }
    printf(", Seq: %d", pkt->seq_num);
    if (pkt->type == SYN_ACK || pkt->type == ACK) {
        printf(", Ack: %d", pkt->ack_num);
    }
    printf(")\n");
}

// --- Server Logic ---
void start_server() {
    int sockfd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t addr_len = sizeof(client_addr);
    tcp_segment_t received_pkt, sent_pkt;
    int server_isn; // Server's Initial Sequence Number
    int client_isn; // Client's Initial Sequence Number

    // 1. Create UDP socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    // 2. Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET; // IPv4
    server_addr.sin_port = htons(PORT); // Port in network byte order
    server_addr.sin_addr.s_addr = INADDR_ANY; // Listen on all available interfaces

    // 3. Bind socket to address
    if (bind(sockfd, (const struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d...\n", PORT);
    printf("--- TCP 3-way Handshake Simulation (Server Side) ---\n\n");

    // --- Handshake Step 1: Server waits for SYN from client ---
    printf("Waiting for SYN from client...\n");
    ssize_t bytes_received = recvfrom(sockfd, &received_pkt, sizeof(received_pkt), 0, (struct sockaddr *)&client_addr, &addr_len);
    if (bytes_received < 0) {
        perror("recvfrom failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }
    print_segment("Server", "Received", &received_pkt);

    if (received_pkt.type != SYN) {
        fprintf(stderr, "[Server] Error: Expected SYN, but received type %d\n", received_pkt.type);
        close(sockfd);
        exit(EXIT_FAILURE);
    }
    client_isn = received_pkt.seq_num;
    printf("[Server] SYN received. Client ISN (Initial Sequence Number): %d\n\n", client_isn);

    // --- Handshake Step 2: Server sends SYN-ACK ---
    server_isn = rand() % 10000 + 1; // Generate Server's ISN
    sent_pkt = init_segment(SYN_ACK, server_isn, client_isn + 1);

    printf("Sending SYN-ACK to client...\n");
    ssize_t bytes_sent = sendto(sockfd, &sent_pkt, sizeof(sent_pkt), 0, (const struct sockaddr *)&client_addr, addr_len);
    if (bytes_sent < 0) {
        perror("sendto failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }
    print_segment("Server", "Sent", &sent_pkt);
    printf("[Server] SYN-ACK sent. Server ISN: %d, ACK for client ISN + 1: %d\n\n", server_isn, client_isn + 1);

    // --- Handshake Step 3: Server waits for final ACK from client ---
    printf("Waiting for final ACK from client...\n");
    bytes_received = recvfrom(sockfd, &received_pkt, sizeof(received_pkt), 0, (struct sockaddr *)&client_addr, &addr_len);
    if (bytes_received < 0) {
        perror("recvfrom failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }
    print_segment("Server", "Received", &received_pkt);

    if (received_pkt.type != ACK || received_pkt.ack_num != (server_isn + 1)) {
        fprintf(stderr, "[Server] Error: Expected ACK with ack_num %d, but received type %d and ack_num %d\n",
                server_isn + 1, received_pkt.type, received_pkt.ack_num);
        close(sockfd);
        exit(EXIT_FAILURE);
    }
    printf("[Server] ACK received. Client acknowledges Server's SYN-ACK (ack_num: %d)\n\n", received_pkt.ack_num);

    printf("--- TCP 3-way Handshake COMPLETE on Server side. Connection Established. ---\n");

    // Close the socket
    close(sockfd);
}

// --- Client Logic ---
void start_client(const char* server_ip) {
    int sockfd;
    struct sockaddr_in server_addr;
    tcp_segment_t received_pkt, sent_pkt;
    int client_isn; // Client's Initial Sequence Number
    int server_isn; // Server's Initial Sequence Number

    // 1. Create UDP socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    // 2. Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET; // IPv4
    server_addr.sin_port = htons(PORT); // Server port in network byte order
    if (inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
        perror("invalid server IP address/address not supported");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    printf("Client connecting to %s:%d...\n", server_ip, PORT);
    printf("--- TCP 3-way Handshake Simulation (Client Side) ---\n\n");

    // --- Handshake Step 1: Client sends SYN ---
    client_isn = rand() % 10000 + 1; // Generate Client's ISN
    sent_pkt = init_segment(SYN, client_isn, 0); // ACK is 0 as client doesn't expect anything yet

    printf("Sending SYN to server...\n");
    ssize_t bytes_sent = sendto(sockfd, &sent_pkt, sizeof(sent_pkt), 0, (const struct sockaddr *)&server_addr, sizeof(server_addr));
    if (bytes_sent < 0) {
        perror("sendto failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }
    print_segment("Client", "Sent", &sent_pkt);
    printf("[Client] SYN sent. Client ISN: %d\n\n", client_isn);

    // --- Handshake Step 2: Client waits for SYN-ACK from server ---
    printf("Waiting for SYN-ACK from server...\n");
    socklen_t server_addr_len = sizeof(server_addr); // Need a mutable socklen_t for recvfrom
    ssize_t bytes_received = recvfrom(sockfd, &received_pkt, sizeof(received_pkt), 0, (struct sockaddr *)&server_addr, &server_addr_len);
    if (bytes_received < 0) {
        perror("recvfrom failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }
    print_segment("Client", "Received", &received_pkt);

    if (received_pkt.type != SYN_ACK || received_pkt.ack_num != (client_isn + 1)) {
        fprintf(stderr, "[Client] Error: Expected SYN-ACK with ack_num %d, but received type %d and ack_num %d\n",
                client_isn + 1, received_pkt.type, received_pkt.ack_num);
        close(sockfd);
        exit(EXIT_FAILURE);
    }
    server_isn = received_pkt.seq_num;
    printf("[Client] SYN-ACK received. Server ISN: %d, Server acknowledges Client's ISN (ack_num: %d)\n\n",
           server_isn, received_pkt.ack_num);

    // --- Handshake Step 3: Client sends final ACK ---
    sent_pkt = init_segment(ACK, client_isn, server_isn + 1); // Client's original seq num, ACK for server's ISN + 1

    printf("Sending final ACK to server...\n");
    bytes_sent = sendto(sockfd, &sent_pkt, sizeof(sent_pkt), 0, (const struct sockaddr *)&server_addr, sizeof(server_addr));
    if (bytes_sent < 0) {
        perror("sendto failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }
    print_segment("Client", "Sent", &sent_pkt);
    printf("[Client] ACK sent. Client acknowledges Server's SYN-ACK (ack_num: %d)\n\n", server_isn + 1);

    printf("--- TCP 3-way Handshake COMPLETE on Client side. Connection Established. ---\n");

    // Close the socket
    close(sockfd);
}

// --- Main function to choose mode (server/client) ---
int main(int argc, char *argv[]) {
    // Seed the random number generator for sequence numbers
    srand(time(NULL));

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <server|client> [server_ip_for_client]\n", argv[0]);
        return EXIT_FAILURE;
    }

    if (strcmp(argv[1], "server") == 0) {
        start_server();
    } else if (strcmp(argv[1], "client") == 0) {
        if (argc < 3) {
            fprintf(stderr, "Usage: %s client <server_ip>\n", argv[0]);
            return EXIT_FAILURE;
        }
        start_client(argv[2]);
    } else {
        fprintf(stderr, "Invalid mode. Use 'server' or 'client'.\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

