// Function to handle errors
void error(const char* message) {
    perror(message);
    exit(1);
}

int main() {
    int serverSocket, clientSocket;
    struct sockaddr_in serverAddress, clientAddress;
    socklen_t clientAddressLength;
    char buffer[BUFFER_SIZE];

    // Create a TCP socket
    serverSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (serverSocket < 0) {
        error("Failed to create socket");
    }

    // Set up server address
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &serverAddress.sin_addr);

    // Bind the socket to the specified address and port
    if (bind(serverSocket, (struct sockaddr*)&serverAddress, sizeof(serverAddress)) < 0) {
        error("Failed to bind socket");
    }

    // Listen for incoming connections
    if (listen(serverSocket, 3) < 0) {
        error("Failed to listen for incoming connections");
    }

    printf("Server listening on port 8080...\n");

    while (1) {
        // Accept an incoming connection
        clientAddressLength = sizeof(clientAddress);
        clientSocket = accept(serverSocket, (struct sockaddr*)&clientAddress, &clientAddressLength);
        if (clientSocket < 0) {
            error("Failed to accept incoming connection");
        }

        printf("Connection accepted from client...\n");

        // Receive SYN packet from client
        if (recv(clientSocket, buffer, BUFFER_SIZE, 0) < 0) {
            error("Failed to receive SYN packet from client");
        }

        printf("Received SYN packet from client...\n");

        // Send SYN-ACK packet to client
        char synAck[] = "SYN-ACK";
        if (send(clientSocket, synAck, strlen(synAck), 0) < 0) {
            error("Failed to send SYN-ACK packet to client");
        }

        printf("Sent SYN-ACK packet to client...\n");

        // Receive ACK packet from client
        if (recv(clientSocket, buffer, BUFFER_SIZE, 0) < 0) {
            error("Failed to receive ACK packet from client");
        }

        printf("Received ACK packet from client...\n");

        // Connection established, handle data transfer
        printf("Connection established with client...\n");

        // Close the client socket
        close(clientSocket);
    }

    // Close the server socket
    close(serverSocket);

    return 0;
}

