        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d\n", PORT);

    // Accept a connection
    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t *)&addrlen)) < 0) {
            perror("Accept failed");
            close(server_fd);
            continue;
        }

        // Handle the client in a separate function
        handle_client(new_socket);

        close(new_socket);
    }

    return 0;
}

void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE] = {0};
    ssize_t valread;

    // Read the SYN packet from the client
    valread = read(client_socket, buffer, BUFFER_SIZE);
    if (valread > 0 && !strncmp(buffer, "SYN", 3)) {
        printf("Received SYN from client\n");

        // Send SYN-ACK back to the client
        const char *syn_ack = "SYN-ACK";
        send(client_socket, syn_ack, strlen(syn_ack), 0);
        printf("Sent SYN-ACK to client\n");

        // Read the ACK packet from the client
        memset(buffer, 0, BUFFER_SIZE);
        valread = read(client_socket, buffer, BUFFER_SIZE);
        if (valread > 0 && !strncmp(buffer, "ACK", 3)) {
            printf("Connection established with client\n");
        } else {
            printf("Failed to receive ACK from client\n");
        }
    } else {
        printf("Failed to receive SYN from client\n");
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <unistd.h>

#define MAX_FLOORS 10
#define MAX_PASSENGERS 5

// Elevator states
typedef enum {
    IDLE,
    MOVING_UP,
    MOVING_DOWN
} ElevatorState;

// Elevator structure
typedef struct {
    int current_floor;
    ElevatorState state;
    int passengers;
    bool floor_requests[MAX_FLOORS + 1];
} Elevator;

// Function prototypes
void initialize_elevator(Elevator* elevator);
void display_elevator_status(Elevator* elevator);
void request_floor(Elevator* elevator, int floor);
void move_elevator(Elevator* elevator);
void simulate_elevator(Elevator* elevator);

// Initialize elevator
void initialize_elevator(Elevator* elevator) {
    elevator->current_floor = 1;
    elevator->state = IDLE;
    elevator->passengers = 0;

    for (int i = 0; i <= MAX_FLOORS; i++) {
        elevator->floor_requests[i] = false;
    }
}

// Display current elevator status
void display_elevator_status(Elevator* elevator) {
    printf("\n--- Elevator Status ---\n");
    printf("Current Floor: %d\n", elevator->current_floor);

    switch (elevator->state) {
        case IDLE:
            printf("State: IDLE\n");
            break;
        case MOVING_UP:
            printf("State: MOVING UP\n");
            break;
        case MOVING_DOWN:
            printf("State: MOVING DOWN\n");
            break;
    }

    printf("Passengers: %d\n", elevator->passengers);

    printf("Floor Requests: ");
    for (int i = 1; i <= MAX_FLOORS; i++) {
        if (elevator->floor_requests[i]) {
            printf("%d ", i);
        }
    }
    printf("\n");
}

// Request a floor
void request_floor(Elevator* elevator, int floor) {
    if (floor < 1 || floor > MAX_FLOORS) {
        printf("Invalid floor request\n");
        return;
    }

    if (elevator->passengers < MAX_PASSENGERS) {
        elevator->floor_requests[floor] = true;
        printf("Floor %d requested\n", floor);
    } else {
        printf("Elevator is at max capacity\n");
    }
}

// Move elevator
void move_elevator(Elevator* elevator) {
    // Determine next state and movement
    bool has_requests = false;
    for (int i = 1; i <= MAX_FLOORS; i++) {
        if (elevator->floor_requests[i]) {
            has_requests = true;
            break;
        }
    }

    if (!has_requests) {
        elevator->state = IDLE;
        return;
    }

    // Decide direction
    if (elevator->state == IDLE) {
        for (int i = elevator->current_floor + 1; i <= MAX_FLOORS; i++) {
            if (elevator->floor_requests[i]) {
                elevator->state = MOVING_UP;
                break;
            }
        }

        if (elevator->state == IDLE) {
            for (int i = elevator->current_floor - 1; i >= 1; i--) {
                if (elevator->floor_requests[i]) {
                    elevator->state = MOVING_DOWN;
                    break;
                }
            }
        }
    }

    // Move elevator
    if (elevator->state == MOVING_UP) {
        elevator->current_floor++;
        printf("Moving UP to floor %d\n", elevator->current_floor);
    } else if (elevator->state == MOVING_DOWN) {
        elevator->current_floor--;
        printf("Moving DOWN to floor %d\n", elevator->current_floor);
    }

    // Stop at requested floor
    if (elevator->floor_requests[elevator->current_floor]) {
        printf("Stopped at floor %d\n", elevator->current_floor);
        elevator->floor_requests[elevator->current_floor] = false;
        elevator->passengers++;
    }

    // Update state after reaching floor
    bool has_up_requests = false;
    bool has_down_requests = false;

    for (int i = elevator->current_floor + 1; i <= MAX_FLOORS; i++) {
        if (elevator->floor_requests[i]) {
            has_up_requests = true;
            break;
        }
    }

    for (int i = 1; i < elevator->current_floor; i++) {
        if (elevator->floor_requests[i]) {
            has_down_requests = true;
            break;
        }
    }

    if (!has_up_requests && elevator->state == MOVING_UP) {
        elevator->state = MOVING_DOWN;
    }

    if (!has_down_requests && elevator->state == MOVING_DOWN) {
        elevator->state = MOVING_UP;
    }
}

// Simulate elevator
void simulate_elevator(Elevator* elevator) {
    int choice, floor;

    while (1) {
        display_elevator_status(elevator);

        printf("\nElevator Menu:\n");
        printf("1. Request Floor\n");
        printf("2. Move Elevator\n");
        printf("3. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                printf("Enter floor number: ");
                scanf("%d", &floor);
                request_floor(elevator, floor);
                break;
            case 2:
                move_elevator(elevator);
                break;
            case 3:
                printf("Exiting elevator simulation\n");
                return;
            default:
                printf("Invalid choice\n");
        }

        // Optional: Add delay for simulation
        sleep(1);
    }
}

int main() {
    Elevator elevator;
    initialize_elevator(&elevator);

    simulate_elevator(&elevator);

    return 0;
}

