#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <unistd.h> // For sleep()

// --- Configuration ---
#define MIN_FLOORS 2
#define MAX_FLOORS 20
#define IDLE_FLOOR 1 // Where the elevator waits when idle
#define TRAVEL_TIME_PER_FLOOR 1 // seconds

// --- Enums ---
typedef enum {
    IDLE,
    UP,
    DOWN
} Direction;

// --- Global Variables (for simplicity in this simulation) ---
int NUM_FLOORS;
int current_floor;
Direction current_direction;

// Using boolean arrays to track requests for each floor.
// A floor is "requested" if an outside button is pressed.
bool *call_requests;
// A floor is "destined" if a button inside the elevator is pressed.
bool *destination_requests;

// --- Function Prototypes ---
void initialize_elevator(int floors);
void print_status();
void add_call_request(int floor);
void add_destination_request(int floor);
void find_next_stop();
void move_elevator();
void simulate_user_input();
void free_resources();

int main() {
    printf("--- Elevator Simulation ---\n");

    // Get number of floors from user
    while (true) {
        printf("Enter number of floors (min %d, max %d): ", MIN_FLOORS, MAX_FLOORS);
        if (scanf("%d", &NUM_FLOORS) == 1 && NUM_FLOORS >= MIN_FLOORS && NUM_FLOORS <= MAX_FLOORS) {
            break;
        } else {
            printf("Invalid number of floors. Please try again.\n");
            // Clear input buffer
            while (getchar() != '\n');
        }
    }

    initialize_elevator(NUM_FLOORS);

    printf("\nStarting Elevator Simulation.\n");
    printf("Commands:\n");
    printf("  c <floor>: Call elevator from <floor>\n");
    printf("  d <floor>: Select <floor> as destination (assumes you are inside)\n");
    printf("  q: Quit\n");

    // Main simulation loop
    while (true) {
        print_status();
        find_next_stop(); // Determine where to go next
        move_elevator();  // Move the elevator
        simulate_user_input(); // Check for user commands

        // Small delay to make the simulation readable
        // usleep(500000); // 0.5 seconds
    }

    free_resources(); // Should be called before exiting, though currently unreachable in infinite loop
    return 0;
}

// --- Function Implementations ---

void initialize_elevator(int floors) {
    NUM_FLOORS = floors;
    current_floor = IDLE_FLOOR;
    current_direction = IDLE;

    call_requests = (bool *)malloc((NUM_FLOORS + 1) * sizeof(bool));
    destination_requests = (bool *)malloc((NUM_FLOORS + 1) * sizeof(bool));

    if (call_requests == NULL || destination_requests == NULL) {
        fprintf(stderr, "Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 1; i <= NUM_FLOORS; i++) {
        call_requests[i] = false;
        destination_requests[i] = false;
    }
}

void print_status() {
    printf("\n--- Elevator Status ---\n");
    printf("Current Floor: %d\n", current_floor);
    printf("Direction: %s\n", current_direction == IDLE ? "IDLE" : (current_direction == UP ? "UP" : "DOWN"));

    printf("Call Requests (Outside): [");
    for (int i = 1; i <= NUM_FLOORS; i++) {
        if (call_requests[i]) {
            printf("%d ", i);
        }
    }
    printf("]\n");

    printf("Destination Requests (Inside): [");
    for (int i = 1; i <= NUM_FLOORS; i++) {
        if (destination_requests[i]) {
            printf("%d ", i);
        }
    }
    printf("]\n");
    printf("-------------------------\n");
}

void add_call_request(int floor) {
    if (floor >= 1 && floor <= NUM_FLOORS) {
        if (!call_requests[floor]) {
            call_requests[floor] = true;
            printf("Call requested from floor %d.\n", floor);
        } else {
            printf("Call already requested from floor %d.\n", floor);
        }
    } else {
        printf("Invalid floor: %d\n", floor);
    }
}

void add_destination_request(int floor) {
    if (floor >= 1 && floor <= NUM_FLOORS) {
        if (!destination_requests[floor]) {
            destination_requests[floor] = true;
            printf("Destination floor %d added.\n", floor);
        } else {
            printf("Destination floor %d already requested.\n", floor);
        }
    } else {
        printf("Invalid destination floor: %d\n", floor);
    }
}

// This is the brain of the elevator. It decides where to go next.
void find_next_stop() {
    bool pending_requests = false;
    for (int i = 1; i <= NUM_FLOORS; i++) {
        if (call_requests[i] || destination_requests[i]) {
            pending_requests = true;
            break;
        }
    }

    if (!pending_requests) {
        current_direction = IDLE;
        return;
    }

    // Prioritize existing direction first
    if (current_direction == UP) {
        for (int i = current_floor; i <= NUM_FLOORS; i++) {
            if (destination_requests[i] || call_requests[i]) {
                return; // Has a stop in current UP direction
            }
        }
        // No more stops UP, so try going DOWN
        current_direction = DOWN;
    } else if (current_direction == DOWN) {
        for (int i = current_floor; i >= 1; i--) {
            if (destination_requests[i] || call_requests[i]) {
                return; // Has a stop in current DOWN direction
            }
        }
        // No more stops DOWN, so try going UP
        current_direction = UP;
    }

    // If IDLE or changed direction, find the closest request
    if (current_direction == IDLE || (current_direction == UP && current_floor == NUM_FLOORS) || (current_direction == DOWN && current_floor == 1)) {
        int closest_up = -1;
        int closest_down = -1;

        // Find closest requests in both directions
        for (int i = current_floor + 1; i <= NUM_FLOORS; i++) {
            if (call_requests[i] || destination_requests[i]) {
                closest_up = i;
                break;
            }
        }
        for (int i = current_floor - 1; i >= 1; i--) {
            if (call_requests[i] || destination_requests[i]) {
                closest_down = i;
                break;
            }
        }

        if (closest_up != -1 && (closest_down == -1 || abs(closest_up - current_floor) <= abs(closest_down - current_floor))) {
            current_direction = UP;
        } else if (closest_down != -1) {
            current_direction = DOWN;
        } else {
            current_direction = IDLE; // Should not happen if pending_requests is true
        }
    }
}

void move_elevator() {
    if (current_direction == IDLE) {
        printf("Elevator is idle.\n");
        return;
    }

    printf("Elevator moving %s from floor %d...\n",
           current_direction == UP ? "UP" : "DOWN", current_floor);

    // Simulate movement floor by floor
    while (true) {
        // Check for immediate stop on current floor
        if (destination_requests[current_floor] || call_requests[current_floor]) {
            printf("  ***DING!*** Arrived at floor %d.\n", current_floor);
            if (destination_requests[current_floor]) {
                printf("    Dropping off passenger.\n");
                destination_requests[current_floor] = false;
            }
            if (call_requests[current_floor]) {
                printf("    Picking up passenger.\n");
                call_requests[current_floor] = false;
            }
            sleep(2); // Simulate door open/close time
            return; // Stop at this floor
        }

        sleep(TRAVEL_TIME_PER_FLOOR); // Simulate travel time

        // Move one floor
        if (current_direction == UP) {
            if (current_floor < NUM_FLOORS) {
                current_floor++;
            } else {
                current_direction = DOWN; // Reached top, must reverse
                break; // Stop loop, re-evaluate direction on next cycle
            }
        } else if (current_direction == DOWN) {
            if (current_floor > 1) {
                current_floor--;
            } else {
                current_direction = UP; // Reached bottom, must reverse
                break; // Stop loop, re-evaluate direction on next cycle
            }
        }

        printf("  ...now at floor %d\n", current_floor);
    }
}

void simulate_user_input() {
    char command[10];
    int floor;

    // Use non-blocking input for a more continuous simulation
    // This is OS-specific; for portability we'll use a simple blocking scanf
    // and rely on the user to input 'q' to quit.
    // For a real-time system, you'd integrate with event loops or threads.

    printf("Enter command (c/d <floor>, q): ");
    // Clear newline from previous scanf calls
    // while (getchar() != '\n'); // Be careful, can consume prompt if not read cleanly

    if (scanf("%s", command) == 1) {
        if (command[0] == 'q' || command[0] == 'Q') {
            printf("Quitting simulation.\n");
            free_resources();
            exit(0);
        } else if (command[0] == 'c' || command[0] == 'C') {
            if (scanf("%d", &floor) == 1) {
                add_call_request(floor);
            } else {
                printf("Invalid floor number for call command.\n");
            }
        } else if (command[0] == 'd' || command[0] == 'D') {
            if (scanf("%d", &floor) == 1) {
                add_destination_request(floor);
            } else {
                printf("Invalid floor number for destination command.\n");
            }
        } else {
            printf("Unknown command: %s\n", command);
        }
    }
    // Clear any remaining characters in the buffer up to newline
    while (getchar() != '\n');
}

void free_resources() {
    free(call_requests);
    free(destination_requests);
    call_requests = NULL;
    destination_requests = NULL;
}

