typedef struct {
    int currentFloor;
    int requests[MAX_REQUESTS];
    int requestCount;
} Elevator;

void initializeElevator(Elevator *elevator) {
    elevator->currentFloor = 0; // Start at ground floor (0)
    elevator->requestCount = 0;
}

void requestFloor(Elevator *elevator, int floor) {
    if (floor < 0 || floor >= MAX_FLOORS) {
        printf("Invalid floor request.\n");
        return;
    }

    if (elevator->requestCount >= MAX_REQUESTS) {
        printf("Maximum request limit reached.\n");
        return;
    }

    elevator->requests[elevator->requestCount++] = floor;
    printf("Floor %d requested.\n", floor);
}

void moveToNextRequest(Elevator *elevator) {
    if (elevator->requestCount == 0) {
        printf("No pending requests.\n");
        return;
    }

    int nextFloor = elevator->requests[0];
    printf("Moving from floor %d to floor %d...\n", elevator->currentFloor, nextFloor);

    // Simulate moving to the requested floor
    elevator->currentFloor = nextFloor;

    // Remove the fulfilled request
    for (int i = 0; i < elevator->requestCount - 1; i++) {
        elevator->requests[i] = elevator->requests[i + 1];
    }
    elevator->requestCount--;

    printf("Arrived at floor %d.\n", elevator->currentFloor);
}

void displayCurrentState(Elevator *elevator) {
    printf("Elevator is currently on floor %d.\n", elevator->currentFloor);
    printf("Pending requests: ");
    for (int i = 0; i < elevator->requestCount; i++) {
