#define MAX_FLOORS 10

// Structure to represent the elevator
typedef struct {
    int current_floor;
    int max_floor;
} Elevator;

// Function to create a new elevator
Elevator* create_elevator(int max_floor) {
    Elevator* elevator = (Elevator*) malloc(sizeof(Elevator));
    elevator->current_floor = 1;
    elevator->max_floor = max_floor;
    return elevator;
}

// Function to move the elevator to a specific floor
void move_elevator(Elevator* elevator, int target_floor) {
    if (target_floor < 1 || target_floor > elevator->max_floor) {
        printf("Invalid floor request. Please enter a floor between 1 and %d.\n", elevator->max_floor);
        return;
    }

    if (elevator->current_floor < target_floor) {
        printf("Elevator moving up from floor %d to floor %d...\n", elevator->current_floor, target_floor);
    } else if (elevator->current_floor > target_floor) {
        printf("Elevator moving down from floor %d to floor %d...\n", elevator->current_floor, target_floor);
    }

    elevator->current_floor = target_floor;
    printf("Elevator arrived at floor %d.\n", elevator->current_floor);
}

// Function to free the elevator memory
void free_elevator(Elevator* elevator) {
    free(elevator);
}

