#define MAX_FLOORS 10

int currentFloor = 0;
int targetFloor = 0;
int direction = 1; // 1 for up, -1 for down

void moveElevator(int target) {
    if (target > currentFloor) {
        direction = 1;
    } else if (target < currentFloor) {
        direction = -1;
    }

    while (currentFloor != target) {
        currentFloor += direction;
        printf("Elevator is on floor %d\n", currentFloor);
        sleep(1); // Simulate time taken to move between floors
    }
    printf("Elevator has arrived at floor %d\n", currentFloor);
}

void requestElevator() {
    int requestFloor;
    int destinationFloor;

    printf("Enter the floor you are on (0 to %d): ", MAX_FLOORS - 1);
    scanf("%d", &requestFloor);

    if (requestFloor < 0 || requestFloor >= MAX_FLOORS) {
        printf("Invalid floor. Please enter a valid floor.\n");
        return;
    }

    moveElevator(requestFloor);

    printf("Enter your destination floor (0 to %d): ", MAX_FLOORS - 1);
    scanf("%d", &destinationFloor);

    if (destinationFloor < 0 || destinationFloor >= MAX_FLOORS) {
        printf("Invalid floor. Please enter a valid floor.\n");
        return;
    }

    moveElevator(destinationFloor);
}

