    int numCandidates = 2;

    // Array to track voter IDs to prevent multiple voting
    int voterIds[MAX_VOTERS] = {0};

    // Array of candidates
    Candidate candidates[2];

    // Initialize candidates
    initializeCandidates(candidates, numCandidates);

    int choice;
    int votingActive = 1;

    while (votingActive) {
        // Display menu
        printf("\n--- Voting Simulation ---\n");
        printf("1. Display Candidates\n");
        printf("2. Cast Vote\n");
        printf("3. Display Results\n");
        printf("4. Exit Voting\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                displayCandidates(candidates, numCandidates);
                break;

            case 2:
                castVote(candidates, numCandidates, voterIds);
                break;

            case 3:
                displayResults(candidates, numCandidates);
                break;

            case 4:
                votingActive = 0;
                printf("Voting process terminated.\n");
                break;

            default:
                printf("Invalid choice. Please try again.\n");
        }
    }

    // Final results
    displayResults(candidates, numCandidates);

    return 0;
}

// Initialize candidates with names
void initializeCandidates(Candidate candidates[], int numCandidates) {
    strcpy(candidates[0].name, "John Smith");
    strcpy(candidates[1].name, "Emily Johnson");

    // Reset vote counts
    for (int i = 0; i < numCandidates; i++) {
        candidates[i].votes = 0;
    }
}

// Display candidate list
void displayCandidates(Candidate candidates[], int numCandidates) {
    printf("\nCandidate List:\n");
    for (int i = 0; i < numCandidates; i++) {
        printf("%d. %s\n", i+1, candidates[i].name);
    }
}

// Cast vote function
void castVote(Candidate candidates[], int numCandidates, int voterIds[]) {
    int voterId, candidateChoice;

    // Get voter ID
    printf("Enter your voter ID (1-100): ");
    scanf("%d", &voterId);

    // Check if voter ID is valid
    if (voterId < 1 || voterId > MAX_VOTERS) {
        printf("Invalid voter ID!\n");
        return;
    }

    // Check if voter has already voted
    if (voterIds[voterId-1] == 1) {
        printf("You have already voted. Multiple voting is not allowed!\n");
        return;
    }

    // Display candidates
    displayCandidates(candidates, numCandidates);

    // Get candidate choice
    printf("Enter your candidate choice (1 or 2): ");
    scanf("%d", &candidateChoice);

    // Validate candidate choice
    if (candidateChoice < 1 || candidateChoice > numCandidates) {
        printf("Invalid candidate choice!\n");
        return;
    }

    // Record vote
    candidates[candidateChoice-1].votes++;
    voterIds[voterId-1] = 1;

    printf("Vote cast successfully!\n");
}

// Display voting results
void displayResults(Candidate candidates[], int numCandidates) {
    printf("\n--- Voting Results ---\n");

    for (int i = 0; i < numCandidates; i++) {
        printf("%s: %d votes\n", candidates[i].name, candidates[i].votes);
    }

    // Determine winner
    int maxVotes = candidates[0].votes;
    int winnerIndex = 0;

    for (int i = 1; i < numCandidates; i++) {
        if (candidates[i].votes > maxVotes) {
            maxVotes = candidates[i].votes;
            winnerIndex = i;
        }
    }

    // Check for tie
    int tieCount = 0;
    for (int i = 0; i < numCandidates; i++) {
        if (candidates[i].votes == maxVotes) {
            tieCount++;
        }
    }

    if (tieCount > 1) {
        printf("\nElection is a tie!\n");
    } else {
        printf("\nWinner: %s with %d votes\n", 
               candidates[winnerIndex].name, 
               candidates[winnerIndex].votes);
    }
}

