// Define constants for the number of candidates
#define NUM_CANDIDATES 3

// Function prototypes
void displayResults(int *votes, const char *candidateNames[], int numCandidates);
void clearInputBuffer();
void pressEnterToContinue();
void clearScreen();

int main() {
    // Array to store votes for each candidate, initialized to 0
    int votes[NUM_CANDIDATES] = {0};

    // Array of strings to store candidate names
    const char *candidateNames[NUM_CANDIDATES] = {"Alice", "Bob", "Charlie"};

    int choice; // Variable to store user's menu choice
    int i;      // Loop counter

    // Main program loop
    do {
        clearScreen(); // Clear the console screen for a cleaner display

        printf("--- Voting Simulation ---\n\n");
        printf("Please choose an option:\n");

        // Display voting options for each candidate
        for (i = 0; i < NUM_CANDIDATES; i++) {
            printf("%d. Vote for %s\n", i + 1, candidateNames[i]);
        }

        // Display other menu options
        printf("%d. Display Current Results\n", NUM_CANDIDATES + 1);
        printf("%d. Quit\n", NUM_CANDIDATES + 2);
        printf("\nEnter your choice: ");

        // Read user's choice
        // Check if scanf successfully read an integer
        if (scanf("%d", &choice) != 1) {
            printf("\nInvalid input. Please enter a number.\n");
            clearInputBuffer(); // Clear the invalid input from the buffer
            pressEnterToContinue();
            continue; // Skip the rest of this loop iteration and start a new one
        }
        clearInputBuffer(); // Clear any remaining characters in the input buffer (like newline)

        // Process user's choice
        if (choice >= 1 && choice <= NUM_CANDIDATES) {
            // User chose to vote for a candidate
            votes[choice - 1]++; // Increment vote count for the chosen candidate (adjust for 0-based index)
            printf("\nThank you for voting for %s!\n", candidateNames[choice - 1]);
            pressEnterToContinue();
        } else if (choice == NUM_CANDIDATES + 1) {
            // User chose to display results
            displayResults(votes, candidateNames, NUM_CANDIDATES);
        } else if (choice == NUM_CANDIDATES + 2) {
            // User chose to quit
            printf("\nExiting voting simulation. Goodbye!\n");
        } else {
            // Invalid choice
            printf("\nInvalid choice. Please enter a valid option.\n");
            pressEnterToContinue();
        }

    } while (choice != NUM_CANDIDATES + 2); // Continue loop until user chooses to quit

    // Display final results before exiting
    clearScreen();
    printf("--- Final Voting Results ---\n");
    displayResults(votes, candidateNames, NUM_CANDIDATES);
    printf("\nProgram finished. Thank you for using the voting simulator!\n");

    return 0; // Indicate successful program execution
}

// Function to display the current vote tally and determine the winner(s)
void displayResults(int *votes, const char *candidateNames[], int numCandidates) {
    int i;
    int totalVotes = 0;
    int maxVotes = 0;

    // Calculate total votes and find the maximum number of votes
    for (i = 0; i < numCandidates; i++) {
        totalVotes += votes[i];
        if (votes[i] > maxVotes) {
            maxVotes = votes[i];
        }
    }

    printf("\n--- Current Voting Tally ---\n");
    for (i = 0; i < numCandidates; i++) {
        printf("%s: %d votes\n", candidateNames[i], votes[i]);
    }
    printf("----------------------------\n");
    printf("Total Votes Cast: %d\n", totalVotes);

    // Determine and display the winner(s)
    if (totalVotes > 0) {
        printf("\n");
        int winnersFound = 0;
        printf("Winner(s): ");
        // Iterate through candidates to find who has the max votes
        for (i = 0; i < numCandidates; i++) {
            if (votes[i] == maxVotes) {
                if (winnersFound > 0) {
                    printf(" and "); // Add "and" for multiple winners (ties)
                }
                printf("%s", candidateNames[i]);
                winnersFound++;
            }
        }
        if (winnersFound > 1) {
             printf(" (Tie) with %d votes!\n", maxVotes);
        } else {
             printf(" with %d votes!\n", maxVotes);
        }
    } else {
        printf("\nNo votes have been cast yet.\n");
    }
    pressEnterToContinue();
}

// Function to clear any leftover characters in the input buffer (e.g., newline from scanf)
void clearInputBuffer() {
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
}

// Function to pause the program execution until the user presses Enter
void pressEnterToContinue() {
    printf("\nPress Enter to continue...");
    clearInputBuffer(); // Ensure any pending newline is read before waiting
}

