// Uses a platform-specific command: "cls" for Windows, "clear" for Unix-like systems (Linux, macOS)
void clearScreen() {
#ifdef _WIN32
    system("cls"); // For Windows
#else
    // Assume POSIX-compliant system (Linux, macOS)
    system("clear"); // For Linux/macOS
#endif
}

