    int maxVotes = 0;
    int winnerIndex = 0;
    int tieCount = 0;

    // Find maximum votes
    for (int i = 0; i < MAX_CANDIDATES; i++) {
        if (candidates[i].votes > maxVotes) {
            maxVotes = candidates[i].votes;
            winnerIndex = i;
            tieCount = 1;
        }
        else if (candidates[i].votes == maxVotes) {
            tieCount++;
        }
    }

    // Check for tie or winner
    if (tieCount > 1) {
        printf("It's a tie! Multiple candidates have the same number of votes.\n");
    }
    else {
        printf("Winner: %s with %d votes!\n", 
               candidates[winnerIndex].name, 
               candidates[winnerIndex].votes);
    }
