// Function to display the current vote counts
void display_results(int votes[], int num_candidates) {
    printf("\n--- Current Election Results ---\n");
    for (int i = 0; i < num_candidates; i++) {
        printf("Candidate %d: %d votes\n", i + 1, votes[i]);
    }
    printf("------------------------------\n");
}

// Function to determine and display the winner
void determine_winner(int votes[], int num_candidates) {
    int max_votes = -1;
    int winner_candidate_index = -1;
    int tie_count = 0; // To track if there's a tie for the highest votes

    // Find the maximum number of votes
    for (int i = 0; i < num_candidates; i++) {
        if (votes[i] > max_votes) {
            max_votes = votes[i];
            winner_candidate_index = i;
            tie_count = 1; // Reset tie count if a new max is found
        } else if (votes[i] == max_votes) {
            tie_count++; // Increment tie count if another candidate has the same max votes
        }
    }

    printf("\n==== FINAL ELECTION RESULTS ====\n");
    display_results(votes, num_candidates);

    if (max_votes == 0) {
        printf("\nNo votes were cast.\n");
    } else if (tie_count > 1) {
        printf("\nIt's a TIE between ");
        for (int i = 0; i < num_candidates; i++) {
            if (votes[i] == max_votes) {
                printf("Candidate %d ", i + 1);
            }
        }
        printf("with %d votes each!\n", max_votes);
    } else {
        printf("\nWINNER: Candidate %d with %d votes!\n", winner_candidate_index + 1, max_votes);
    }
    printf("================================\n");
}


