#include <stdio.h>
#include <math.h>
#include <stdlib.h>

#define MAX_ITERATIONS 100
#define EPSILON 1e-6
#define NUM_EQUATIONS 2

// Function to define the system of nonlinear equations
void equations(double x[], double f[]) {
    // Define your system of nonlinear equations here
    // Example: Two-equation system
    f[0] = x[0] * x[0] + x[1] * x[1] - 4;  // x^2 + y^2 = 4
    f[1] = x[0] - x[1];                    // x - y = 0
}

// Function to compute the Jacobian matrix
void jacobian(double x[], double J[][NUM_EQUATIONS]) {
    // Define the partial derivatives for the Jacobian matrix
    // Example: Partial derivatives for the given system
    J[0][0] = 2 * x[0];    // ∂f1/∂x
    J[0][1] = 2 * x[1];    // ∂f1/∂y
    J[1][0] = 1;           // ∂f2/∂x
    J[1][1] = -1;          // ∂f2/∂y
}

// Function to solve linear system using Gaussian elimination
int solveLinearSystem(double A[][NUM_EQUATIONS], double b[], double x[]) {
    // Gaussian elimination with partial pivoting
    for (int i = 0; i < NUM_EQUATIONS; i++) {
        // Find pivot row
        int maxRow = i;
        for (int j = i + 1; j < NUM_EQUATIONS; j++) {
            if (fabs(A[j][i]) > fabs(A[maxRow][i])) {
                maxRow = j;
            }
        }

        // Swap rows
        for (int k = i; k < NUM_EQUATIONS; k++) {
            double temp = A[maxRow][k];
            A[maxRow][k] = A[i][k];
            A[i][k] = temp;
        }
        double temp = b[maxRow];
        b[maxRow] = b[i];
        b[i] = temp;

        // Check for singularity
        if (fabs(A[i][i]) < EPSILON) {
            return 0;  // Singular matrix
        }

        // Eliminate column
        for (int j = i + 1; j < NUM_EQUATIONS; j++) {
            double factor = A[j][i] / A[i][i];
            for (int k = i; k < NUM_EQUATIONS; k++) {
                A[j][k] -= factor * A[i][k];
            }
            b[j] -= factor * b[i];
        }
    }

    // Back substitution
    for (int i = NUM_EQUATIONS - 1; i >= 0; i--) {
        x[i] = b[i];
        for (int j = i + 1; j < NUM_EQUATIONS; j++) {
            x[i] -= A[i][j] * x[j];
        }
        x[i] /= A[i][i];
    }

    return 1;
}

// Newton-Raphson method for solving nonlinear systems
int newtonRaphsonMethod(double initialGuess[], double solution[]) {
    double x[NUM_EQUATIONS];
    double f[NUM_EQUATIONS];
    double J[NUM_EQUATIONS][NUM_EQUATIONS];
    double delta[NUM_EQUATIONS];

    // Copy initial guess
    for (int i = 0; i < NUM_EQUATIONS; i++) {
        x[i] = initialGuess[i];
    }

    // Iterative process
    for (int iter = 0; iter < MAX_ITERATIONS; iter++) {
        // Compute function values
        equations(x, f);

        // Check convergence
        double norm = 0.0;
        for (int i = 0; i < NUM_EQUATIONS; i++) {
            norm += f[i] * f[i];
        }
        norm = sqrt(norm);

        if (norm < EPSILON) {
            for (int i = 0; i < NUM_EQUATIONS; i++) {
                solution[i] = x[i];
            }
            return 1;  // Converged
        }

        // Compute Jacobian matrix
        jacobian(x, J);

        // Solve linear system J * delta = -f
        for (int i = 0; i < NUM_EQUATIONS; i++) {
            delta[i] = -f[i];
        }

        // Solve linear system
        if (!solveLinearSystem(J, delta, delta)) {
            return 0;  // Failed to solve linear system
        }

        // Update solution
        for (int i = 0; i < NUM_EQUATIONS; i++) {
            x[i] += delta[i];
        }
    }

    return 0;  // Did not converge
}

int main() {
    double initialGuess[NUM_EQUATIONS] = {1.0, 1.0};
    double solution[NUM_EQUATIONS];

    printf("Newton-Raphson Method for Nonlinear Systems\n");
    printf("Initial Guess: ");
    for (int i = 0; i < NUM_EQUATIONS; i++) {
        printf("%f ", initialGuess[i]);
    }
    printf("\n");

    if (newtonRaphsonMethod(initialGuess, solution)) {
        printf("Solution found:\n");
        for (int i = 0; i < NUM_EQUATIONS; i++) {
            printf("x[%d] = %f\n", i, solution[i]);
        }
    } else {
        printf("Failed to find solution\n");
    }

    return 0;
}

#include <stdio.h>
#include <math.h>
#include <stdlib.h>

#define N 2  // Number of equations and variables
#define MAX_ITER 50
#define TOL 1e-6

// Function to evaluate the system of equations
void evaluate_f(double x[N], double f[N]) {
    // Example system:
    // f1(x,y) = x^2 + y^2 - 4 = 0
    // f2(x,y) = e^x + y - 1 = 0
    f[0] = x[0]*x[0] + x[1]*x[1] - 4.0;  // x^2 + y^2 - 4
    f[1] = exp(x[0]) + x[1] - 1.0;       // e^x + y - 1
}

// Function to compute the Jacobian matrix
void compute_jacobian(double x[N], double J[N][N]) {
    // Jacobian for the example system:
    // [ df1/dx  df1/dy ]   [ 2x    2y ]
    // [ df2/dx  df2/dy ] = [ e^x    1 ]
    J[0][0] = 2.0 * x[0];        // df1/dx = 2x
    J[0][1] = 2.0 * x[1];        // df1/dy = 2y
    J[1][0] = exp(x[0]);         // df2/dx = e^x
    J[1][1] = 1.0;               // df2/dy = 1
}

// Function to solve linear system J*dx = -f using Gaussian elimination
void solve_linear_system(double J[N][N], double f[N], double dx[N]) {
    // Forward elimination
    for (int k = 0; k < N-1; k++) {
        for (int i = k+1; i < N; i++) {
            double factor = J[i][k] / J[k][k];
            for (int j = k; j < N; j++) {
                J[i][j] -= factor * J[k][j];
            }
            f[i] -= factor * f[k];
        }
    }

    // Back substitution
    for (int i = N-1; i >= 0; i--) {
        dx[i] = f[i];
        for (int j = i+1; j < N; j++) {
            dx[i] -= J[i][j] * dx[j];
        }
        dx[i] /= J[i][i];
    }
}

// Newton-Raphson method implementation
int newton_raphson(double x[N]) {
    double f[N], dx[N], J[N][N];
    int iter = 0;
    double norm;

    printf("Iter\tx\t\ty\t\tf1\t\tf2\t\tNorm\n");

    do {
        // Evaluate functions at current point
        evaluate_f(x, f);

        // Compute Jacobian matrix
        compute_jacobian(x, J);

        // Compute norm of f to check convergence
        norm = 0.0;
        for (int i = 0; i < N; i++) {
            norm += f[i] * f[i];
        }
        norm = sqrt(norm);

        // Print current iteration information
        printf("%d\t%.6f\t%.6f\t%.6f\t%.6f\t%.6f\n", 
               iter, x[0], x[1], f[0], f[1], norm);

        // Check for convergence
        if (norm < TOL) {
            return 0;  // Success
        }

        // Solve J*dx = -f
        for (int i = 0; i < N; i++) {
            f[i] = -f[i];
        }
        solve_linear_system(J, f, dx);

        // Update solution
        for (int i = 0; i < N; i++) {
            x[i] += dx[i];
        }

        iter++;
    } while (iter < MAX_ITER);

    return -1;  // Did not converge
}

int main() {
    double x[N] = {1.0, 1.0};  // Initial guess

    printf("Solving system of nonlinear equations using Newton-Raphson method\n");
    printf("Initial guess: x = %.2f, y = %.2f\n", x[0], x[1]);

    int status = newton_raphson(x);

    if (status == 0) {
        printf("\nSolution converged:\n");
        printf("x = %.6f\n", x[0]);
        printf("y = %.6f\n", x[1]);
    } else {
        printf("\nSolution did not converge within %d iterations\n", MAX_ITER);
    }

    return 0;
}

