/* Define the two nonlinear equations */
double f1(double x, double y) {
    return x * x + y * y - 4;
}

double f2(double x, double y) {
    return x * y - 1;
}

/* Partial derivatives */
double df1_dx(double x, double y) {
    return 2 * x;
}

double df1_dy(double x, double y) {
    return 2 * y;
}

double df2_dx(double x, double y) {
    return y;
}

double df2_dy(double x, double y) {
    return x;
}

int main() {
    double x = 1.5, y = 1.0; // Initial guess
    int iter;

    for (iter = 0; iter < MAX_ITER; ++iter) {
        double F1 = f1(x, y);
        double F2 = f2(x, y);

        /* Compute Jacobian */
        double J11 = df1_dx(x, y); double J12 = df1_dy(x, y);
        double J21 = df2_dx(x, y); double J22 = df2_dy(x, y);

        /* Compute determinant of Jacobian */
        double detJ = J11 * J22 - J12 * J21;

        if (fabs(detJ) < 1e-12) {
            printf("Jacobian determinant is zero. Method fails.\n");
            return -1;
        }

        /* Compute Newton step:
           [dx] = -J^{-1} * [F1]
           [dy]            [F2]

           dx = -( J22*F1 - J12*F2 ) / detJ
           dy = -(-J21*F1 + J11*F2 ) / detJ
        */
        double dx = -( J22*F1 - J12*F2 ) / detJ;
        double dy = -(-J21*F1 + J11*F2 ) / detJ;

        x += dx;
        y += dy;

        printf("Iter %2d: x = %.8f, y = %.8f, |dx| = %.2e, |dy| = %.2e\n",
               iter+1, x, y, fabs(dx), fabs(dy));

        if (fabs(dx) < TOL && fabs(dy) < TOL)
            break;
    }

    printf("\nSolution after %d iterations:\n", iter+1);
    printf("x = %.10f\n", x);
    printf("y = %.10f\n", y);

    printf("f1(x, y) = %.10e\n", f1(x, y));
    printf("f2(x, y) = %.10e\n", f2(x, y));

    return 0;
}

