#define MAX_ITER 100

void evaluateFunctions(double x, double y, double *f1, double *f2) {
    *f1 = x*x + y*y - 4;
    *f2 = exp(x) - y - 1;
}

void evaluateJacobian(double x, double y, double J[2][2]) {
    J[0][0] = 2*x;
    J[0][1] = 2*y;
    J[1][0] = exp(x);
    J[1][1] = -1;
}

void solveLinearSystem(double J[2][2], double B[2], double X[2]) {
    // Using Cramer's rule to solve 2x2 linear system JX = B
    double det = J[0][0] * J[1][1] - J[0][1] * J[1][0];

    if (fabs(det) < 1e-14) {
        printf("Jacobian determinant is close to zero, the system may be singular.\n");
        return;
    }

    X[0] = (B[0] * J[1][1] - B[1] * J[0][1]) / det;
    X[1] = (J[0][0] * B[1] - J[1][0] * B[0]) / det;
}

void newtonRaphson(double x0, double y0) {
    double x = x0, y = y0;
    double f[2], J[2][2], dx[2];
    int iter = 0;

    for (iter = 0; iter < MAX_ITER; iter++) {
        evaluateFunctions(x, y, &f[0], &f[1]);
        evaluateJacobian(x, y, J);

        // Using the negative of the function values as the B vector
        double B[2] = {-f[0], -f[1]};

        solveLinearSystem(J, B, dx);

        // Update the estimates
        x += dx[0];
        y += dx[1];

        // Check for convergence
        if (sqrt(dx[0] * dx[0] + dx[1] * dx[1]) < TOLERANCE) {
            printf("Converged to solution (%.6f, %.6f) after %d iterations.\n", x, y, iter + 1);
            return;
        }
    }
    printf("Failed to converge after %d iterations.\n", MAX_ITER);
}

