        delta[1] = (F[0] * J[1][0] - J[0][0] * F[1]) / det;

        // Update x and y
        x += delta[0];
        y += delta[1];

        // Check for convergence
        if (fabs(delta[0]) < TOLERANCE && fabs(delta[1]) < TOLERANCE) {
            break;
        }
    }

    // Output the result
    if (iter < MAX_ITER) {
