// Function to perform one step of Newton-Raphson iteration
void newton_raphson_step(double *x, double *y) {
    double F[2] = { f1(*x, *y), f2(*x, *y) };
    double J[2][2] = { { df1_dx(*x, *y), df1_dy(*x, *y) },
                      { df2_dx(*x, *y), df2_dy(*x, *y) } };

    double detJ = J[0][0] * J[1][1] - J[0][1] * J[1][0];

    if (detJ == 0) {
        printf("Jacobian determinant is zero. Cannot proceed.\n");
        return;
    }

    double delta_x = (-F[0] * J[1][1] + F[1] * J[0][1]) / detJ;
    double delta_y = (F[0] * J[1][0] - F[1] * J[0][0]) / detJ;

    *x += delta_x;
    *y += delta_y;
}

// Function to check convergence
int has_converged(double x, double y) {
    double F[2] = { f1(x, y), f2(x, y) };
    return (fabs(F[0]) < EPSILON && fabs(F[1]) < EPSILON);
}

