// Memory block structure
typedef struct MemoryBlock {
    size_t size;               // Size of the memory block
    int is_free;               // Flag to indicate if block is free
    struct MemoryBlock* next;  // Pointer to next memory block
} MemoryBlock;

// Custom Memory Allocator Class
typedef struct {
    void* memory_pool;         // Base pointer to memory pool
    size_t pool_size;          // Total size of memory pool
    MemoryBlock* free_list;    // Head of free list
} MemoryAllocator;

// Function prototypes
MemoryAllocator* memory_allocator_create(size_t pool_size);
void* memory_allocator_alloc(MemoryAllocator* allocator, size_t size);
void memory_allocator_free(MemoryAllocator* allocator, void* ptr);
void memory_allocator_destroy(MemoryAllocator* allocator);
void memory_allocator_dump(MemoryAllocator* allocator);

// Create a new memory allocator
MemoryAllocator* memory_allocator_create(size_t pool_size) {
    // Allocate memory for the allocator
    MemoryAllocator* allocator = malloc(sizeof(MemoryAllocator));
    if (!allocator) {
        fprintf(stderr, "Failed to create memory allocator\n");
        return NULL;
    }

    // Allocate memory pool
    allocator->memory_pool = malloc(pool_size);
    if (!allocator->memory_pool) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        free(allocator);
        return NULL;
    }

    // Initialize allocator properties
    allocator->pool_size = pool_size;

    // Create initial free block covering entire pool
    allocator->free_list = (MemoryBlock*)allocator->memory_pool;
    allocator->free_list->size = pool_size;
    allocator->free_list->is_free = 1;
    allocator->free_list->next = NULL;

    return allocator;
}

// Allocate memory from the pool
void* memory_allocator_alloc(MemoryAllocator* allocator, size_t size) {
    // Align size to memory block header size
    size = (size + sizeof(MemoryBlock) + 7) & ~7;

    MemoryBlock* current = allocator->free_list;
    MemoryBlock* previous = NULL;

    while (current) {
        // Found a suitable free block
        if (current->is_free && current->size >= size) {
            // Split block if it's significantly larger
            if (current->size >= size + sizeof(MemoryBlock) + 8) {
                MemoryBlock* new_block = (MemoryBlock*)((char*)current + size);
                new_block->size = current->size - size;
                new_block->is_free = 1;
                new_block->next = current->next;

                current->size = size;
                current->next = new_block;
            }

            current->is_free = 0;
            return (void*)((char*)current + sizeof(MemoryBlock));
        }

        previous = current;
        current = current->next;
    }

    // No suitable block found
    fprintf(stderr, "Out of memory\n");
    return NULL;
}

// Free allocated memory
void memory_allocator_free(MemoryAllocator* allocator, void* ptr) {
    if (!ptr) return;

    // Get memory block header
    MemoryBlock* block = (MemoryBlock*)((char*)ptr - sizeof(MemoryBlock));
    block->is_free = 1;

    // Merge adjacent free blocks
    MemoryBlock* current = allocator->free_list;
    while (current && current->next) {
        if (current->is_free && current->next->is_free) {
            current->size += current->next->size;
            current->next = current->next->next;
        } else {
            current = current->next;
        }
    }
}

// Destroy memory allocator
void memory_allocator_destroy(MemoryAllocator* allocator) {
    if (allocator) {
        free(allocator->memory_pool);
        free(allocator);
    }
}

// Debug function to print memory allocation status
void memory_allocator_dump(MemoryAllocator* allocator) {
    MemoryBlock* current = allocator->free_list;
    printf("Memory Pool Dump:\n");

    while (current) {
        printf("Block: %p, Size: %zu, Status: %s\n", 
               (void*)current, 
               current->size, 
               current->is_free ? "Free" : "Allocated");
        current = current->next;
    }
}

