int main() {
    // Create memory allocator with 1MB pool
    size_t pool_size = 1024 * 1024;
    MemoryAllocator* allocator = memory_allocator_create(pool_size);

    // Allocate memory
    int* arr1 = memory_allocator_alloc(allocator, 100 * sizeof(int));
    char* str = memory_allocator_alloc(allocator, 50);

    // Use memory
    for (int i = 0; i < 100; i++) {
        arr1[i] = i;
    }
    strcpy(str, "Hello, Custom Allocator!");

    // Dump memory status
    memory_allocator_dump(allocator);

    // Free memory
    memory_allocator_free(allocator, arr1);
    memory_allocator_free(allocator, str);

    // Destroy allocator
    memory_allocator_destroy(allocator);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stddef.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/mman.h>

// Define alignment requirement (8 bytes for 64-bit systems)
#define ALIGNMENT 8
#define ALIGN(size) (((size) + (ALIGNMENT-1)) & ~(ALIGNMENT-1))

// Metadata structure for memory blocks
typedef struct block_meta {
    size_t size;
    struct block_meta *next;
    int free;
} block_meta;

#define META_SIZE ALIGN(sizeof(block_meta))

block_meta *global_base = NULL;

// Find a free block using first-fit strategy
block_meta *find_free_block(block_meta **last, size_t size) {
    block_meta *current = global_base;
    while (current && !(current->free && current->size >= size)) {
        *last = current;
        current = current->next;
    }
    return current;
}

// Request more memory from the OS using mmap
block_meta *request_space(block_meta *last, size_t size) {
    block_meta *block;

    // Use mmap to allocate memory (better than sbrk for custom allocators)
    size_t total_size = META_SIZE + size;
    void *request = mmap(NULL, total_size, 
                        PROT_READ | PROT_WRITE,
                        MAP_PRIVATE | MAP_ANONYMOUS, 
                        -1, 0);

    if (request == MAP_FAILED) {
        return NULL; // mmap failed
    }

    block = (block_meta*)request;
    block->size = size;
    block->next = NULL;
    block->free = 0;

    if (last) {
        last->next = block;
    }

    return block;
}

// Split a block if it's too big
void split_block(block_meta *block, size_t size) {
    if (block->size > size + META_SIZE + ALIGNMENT) {
        block_meta *new_block = (block_meta*)((char*)block + META_SIZE + size);
        new_block->size = block->size - size - META_SIZE;
        new_block->next = block->next;
        new_block->free = 1;

        block->size = size;
        block->next = new_block;
    }
}

// Custom malloc implementation
void *custom_malloc(size_t size) {
    if (size <= 0) {
        return NULL;
    }

    size = ALIGN(size);

    block_meta *block;
    block_meta *last = NULL;

    if (!global_base) {
        // First call
        block = request_space(NULL, size);
        if (!block) {
            return NULL;
        }
        global_base = block;
    } else {
        // Try to find a free block
        block = find_free_block(&last, size);
        if (!block) {
            // No free block found, request new space
            block = request_space(last, size);
            if (!block) {
                return NULL;
            }
        } else {
            // Found a free block, mark it as used
            block->free = 0;
            // Split if possible
            split_block(block, size);
        }
    }

    return (block + 1); // Return pointer after the metadata
}

// Merge consecutive free blocks
void merge_free_blocks() {
    block_meta *current = global_base;
    while (current && current->next) {
        if (current->free && current->next->free) {
            current->size += META_SIZE + current->next->size;
            current->next = current->next->next;
        } else {
            current = current->next;
        }
    }
}

// Custom free implementation
void custom_free(void *ptr) {
    if (!ptr) {
        return;
    }

    block_meta *block = (block_meta*)ptr - 1;
    block->free = 1;

    // Try to merge with adjacent free blocks
    merge_free_blocks();

    // Optional: unmap memory if the entire region is free
    // (This is a simplified version - a real implementation would need to track mmap regions)
}

// Custom realloc implementation
void *custom_realloc(void *ptr, size_t size) {
    if (!ptr) {
        return custom_malloc(size);
    }

    if (size == 0) {
        custom_free(ptr);
        return NULL;
    }

    size = ALIGN(size);

    block_meta *block = (block_meta*)ptr - 1;

    if (block->size >= size) {
        // Existing block is large enough
        split_block(block, size);
        return ptr;
    }

    // Need to allocate new space
    void *new_ptr = custom_malloc(size);
    if (!new_ptr) {
        return NULL;
    }

    // Copy old data
    memcpy(new_ptr, ptr, block->size);

    // Free old block
    custom_free(ptr);

    return new_ptr;
}

// Usage example
int main() {
    int *arr = (int*)custom_malloc(10 * sizeof(int));
    if (arr) {
        for (int i = 0; i < 10; i++) {
            arr[i] = i * i;
        }

        for (int i = 0; i < 10; i++) {
            printf("%d ", arr[i]);
        }
        printf("\n");

        arr = (int*)custom_realloc(arr, 20 * sizeof(int));
        for (int i = 10; i < 20; i++) {
            arr[i] = i * i;
        }

        for (int i = 0; i < 20; i++) {
            printf("%d ", arr[i]);
        }
        printf("\n");

        custom_free(arr);
    }

    return 0;
}

