// The minimum size of a block header.
// It must be at least the size of Block structure itself,
// and also account for alignment.
// We make it slightly larger than Block to cater for alignment requirements later.
#define MIN_BLOCK_SIZE  (sizeof(struct Block))

// A common alignment for many architectures
#define MEM_ALIGNMENT   (sizeof(void*)) // Align to pointer size

// Helper to align a size up to the nearest multiple of MEM_ALIGNMENT
#define ALIGN_UP(size)  (((size) + (MEM_ALIGNMENT - 1)) & ~(MEM_ALIGNMENT - 1))

// Structure for a free memory block.
// This block header is placed AT THE BEGINNING of a free memory chunk.
typedef struct Block {
    size_t size;          // Size of the free memory region (including this header)
    struct Block* next;   // Pointer to the next free block in the list
} Block;

// Structure for the custom memory allocator itself.
// This holds the context of our memory management.
typedef struct CustomAllocator {
    void*  memory_pool_start;     // Start address of the total memory managed
    size_t memory_pool_size;      // Total size of the memory pool
    Block* free_list_head;        // Head of the linked list of free blocks
} CustomAllocator;

// --- Function Prototypes ---

// Initializes the custom allocator with a given memory pool.
// Parameters:
//   allocator: Pointer to the CustomAllocator structure to initialize.
//   pool: The contiguous memory block to manage.
//   pool_size: The size of the memory block in bytes.
// Returns: true if initialization is successful, false otherwise.
bool ca_init(CustomAllocator* allocator, void* pool, size_t pool_size);

// Allocates memory from the custom pool.
// Parameters:
//   allocator: Pointer to the CustomAllocator structure.
//   size: The number of bytes to allocate.
// Returns: A pointer to the allocated memory, or NULL if allocation fails.
void* ca_malloc(CustomAllocator* allocator, size_t size);

// Frees previously allocated memory.
// Parameters:
//   allocator: Pointer to the CustomAllocator structure.
//   ptr: A pointer to the memory block to free (must have been returned by ca_malloc).
void ca_free(CustomAllocator* allocator, void* ptr);

// (Optional) Cleans up allocator resources. Not strictly needed for this design,
// but good practice for more complex allocators.
void ca_destroy(CustomAllocator* allocator);

// (Optional) Prints the current state of the free list for debugging.
void ca_print_free_list(const CustomAllocator* allocator);

