#include <stdio.h>
#include <stdlib.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>

// Simple block header for the free list
typedef struct BlockHeader {
    size_t size;                 // Size of the block (excluding header)
    struct BlockHeader* next;    // Next block in the free list
} BlockHeader;

// The "class" definition for our allocator
typedef struct {
    void* memory;                // Pointer to the entire pool
    size_t pool_size;            // Total pool size
    BlockHeader* free_list;      // Head of free list
} CustomAllocator;

// Helper macro for aligning sizes
#define ALIGN_UP(sz, algn) (((sz) + (algn - 1)) & ~(algn - 1))

// --- Allocator Methods ---

// Initialize the allocator
int allocator_init(CustomAllocator* alloc, size_t size) {
    alloc->pool_size = ALIGN_UP(size, sizeof(size_t));
    alloc->memory = malloc(alloc->pool_size);
    if(!alloc->memory) return 0;

    // First block: all available memory, excluding the space for the header itself
    alloc->free_list = (BlockHeader*) alloc->memory;
    alloc->free_list->size = alloc->pool_size - sizeof(BlockHeader);
    alloc->free_list->next = NULL;
    return 1;
}

// Allocate a block
void* allocator_allocate(CustomAllocator* alloc, size_t user_size) {
    size_t aligned_size = ALIGN_UP(user_size, sizeof(size_t));
    BlockHeader* prev = NULL;
    BlockHeader* curr = alloc->free_list;

    while(curr) {
        if(curr->size >= aligned_size) {
            // Split block if necessary
            if(curr->size >= aligned_size + sizeof(BlockHeader) + sizeof(size_t)) {
                BlockHeader* next = (BlockHeader*)(((char*)curr) + sizeof(BlockHeader) + aligned_size);
                next->size = curr->size - aligned_size - sizeof(BlockHeader);
                next->next = curr->next;

                curr->size = aligned_size;

                if(prev) prev->next = next;
                else alloc->free_list = next;
            } else { // Use entire block
                if(prev) prev->next = curr->next;
                else alloc->free_list = curr->next;
            }
            return (void*)(((char*)curr) + sizeof(BlockHeader)); // Return pointer after header
        }
        prev = curr;
        curr = curr->next;
    }
    // Out of memory
    return NULL;
}

// Deallocate a block
void allocator_deallocate(CustomAllocator* alloc, void* ptr) {
    if(!ptr) return;
    BlockHeader* block = (BlockHeader*)(((char*)ptr) - sizeof(BlockHeader));
    BlockHeader* curr = alloc->free_list;
    BlockHeader* prev = NULL;

    // Insert block in order (by address)
    while(curr && curr < block) {
        prev = curr;
        curr = curr->next;
    }

    // Merge with next if adjacent
    if(curr && (char*)block + sizeof(BlockHeader) + block->size == (char*)curr) {
        block->size += sizeof(BlockHeader) + curr->size;
        block->next = curr->next;
    } else {
        block->next = curr;
    }

    // Merge with previous if adjacent
    if(prev && (char*)prev + sizeof(BlockHeader) + prev->size == (char*)block) {
        prev->size += sizeof(BlockHeader) + block->size;
        prev->next = block->next;
    } else {
        if(prev) prev->next = block;
        else alloc->free_list = block;
    }
}

// Destroy the allocator
void allocator_destroy(CustomAllocator* alloc) {
    free(alloc->memory);
    alloc->memory = NULL;
    alloc->free_list = NULL;
    alloc->pool_size = 0;
}

// --- Sample Usage ---

int main(void) {
    CustomAllocator myAlloc;
    if(!allocator_init(&myAlloc, 1024)) {
        printf("Memory pool allocation failed!\n");
        return 1;
    }

    void* ptr1 = allocator_allocate(&myAlloc, 128);
    void* ptr2 = allocator_allocate(&myAlloc, 64);
    printf("ptr1 = %p, ptr2 = %p\n", ptr1, ptr2);

    allocator_deallocate(&myAlloc, ptr1);
    allocator_deallocate(&myAlloc, ptr2);

    // Test re-allocation
    void* ptr3 = allocator_allocate(&myAlloc, 200);
    printf("ptr3 = %p\n", ptr3);

    allocator_destroy(&myAlloc);
    return 0;
}

#include <stdio.h>
