#define MEMORY_POOL_SIZE 1024  // Total memory pool size
#define BLOCK_SIZE 32          // Block size

typedef struct memory_block {
    bool is_free;
    struct memory_block* next;
} memory_block_t;

typedef struct {
    memory_block_t* free_list;
    char memory_pool[MEMORY_POOL_SIZE];
} memory_allocator_t;

// Initialize the memory allocator
void init_allocator(memory_allocator_t* allocator) {
    if (allocator == NULL) return;

    int num_blocks = MEMORY_POOL_SIZE / BLOCK_SIZE;

    allocator->free_list = (memory_block_t*)allocator->memory_pool;
    memory_block_t* block = allocator->free_list;

    for (int i = 0; i < num_blocks; ++i) {
        block->is_free = true;
        block->next = (i == num_blocks - 1) ? NULL : (memory_block_t*)((char*)block + BLOCK_SIZE);
        block = block->next;
    }
}

// Allocate a block of memory
void* allocate(memory_allocator_t* allocator) {
    if (allocator == NULL || allocator->free_list == NULL) return NULL;

    memory_block_t* block_to_allocate = allocator->free_list;
    block_to_allocate->is_free = false;

    allocator->free_list = allocator->free_list->next;

    return (void*)block_to_allocate;
}

// Free a block of memory
void deallocate(memory_allocator_t* allocator, void* ptr) {
    if (allocator == NULL || ptr == NULL) return;

    memory_block_t* block_to_free = (memory_block_t*)ptr;
    block_to_free->is_free = true;

    block_to_free->next = allocator->free_list;
    allocator->free_list = block_to_free;
}

