    memory_allocator_t allocator;
    init_allocator(&allocator);

    // Allocate some blocks
    void* ptr1 = allocate(&allocator);
    void* ptr2 = allocate(&allocator);

    // Use the allocated memory
    if (ptr1) 
        strncpy((char*)ptr1, "Hello, World!", BLOCK_SIZE);

    // Example of using the memory
    printf("Pointer 1: %s\n", (char*)ptr1);

    // Deallocate the blocks
    deallocate(&allocator, ptr1);
    deallocate(&allocator, ptr2);

    return 0;
}

