void init_memory_allocator() {
    g_free_list = (Block *)g_memory_pool; // Initialize free list to the beginning of the pool.
    g_free_list->size = MEMORY_POOL_SIZE - sizeof(Block); // Set size of the first block
    g_free_list->next = NULL; // No next block yet
    g_free_list->free = 1;    // Mark as free
}

void *my_malloc(size_t size) {
    Block *current = g_free_list;

    // Align size to 8 bytes
    size = (size + 7) & ~7;

    // Traverse the free list to find a block that is large enough
    while (current) {
        if (current->free && current->size >= size) {
            // If the block is large enough
            if (current->size > size + sizeof(Block)) {
                // Split the block if there is enough space for a new block
                Block *new_block = (Block*)((char*)current + sizeof(Block) + size);
                new_block->size = current->size - size - sizeof(Block);
                new_block->next = current->next;
                new_block->free = 1;

                current->size = size;  // Update current block size
                current->next = new_block; // Link the new block

                // Free the current block
                current->free = 0;

                return (char*)current + sizeof(Block); // Return a pointer to the data
            }

            // Use the current block
            current->free = 0;
            return (char*)current + sizeof(Block); // Return a pointer to the data
        }
        current = current->next; // Move to the next block
    }

    // No suitable block found
    return NULL;
}

void my_free(void *ptr) {
    if (ptr == NULL) return;

    // Get the block header
    Block *block = (Block*)((char*)ptr - sizeof(Block));
    block->free = 1; // Mark block as free

    // Coalescing adjacent free blocks
    Block *current = g_free_list;
    while (current) {
        // Check if the next block is free
        if (current->next && current->free && current->next->free) {
            current->size += sizeof(Block) + current->next->size; // Merge the blocks
            current->next = current->next->next; // Remove next from free list
        } else {
            current = current->next; // Move to the next block
        }
    }
}

