#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure to represent a block of memory
typedef struct MemoryBlock {
    size_t size;  // Size of the block
    int free;     // Flag to indicate if the block is free (1) or allocated (0)
    struct MemoryBlock* next;  // Pointer to the next block in the list
} MemoryBlock;

// Global pointer to the head of the linked list of memory blocks
MemoryBlock* head = NULL;

// Custom malloc function
void* custom_malloc(size_t size) {
    // Create a new block if no memory is available
    if (head == NULL || size > head->size) {
        // Allocate memory for the new block
        MemoryBlock* new_block = (MemoryBlock*) sbrk(sizeof(MemoryBlock) + size);
        if (new_block == (void*) -1) {
            // Error: unable to allocate memory
            return NULL;
        }

        // Initialize the new block
        new_block->size = size;
        new_block->free = 0; // Mark the block as allocated
        new_block->next = NULL;

        // Add the new block to the end of the list
        if (head != NULL) {
            MemoryBlock* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_block;
        } else {
            head = new_block;
        }

        // Return a pointer to the start of the allocated memory
        return (void*) ((char*) new_block + sizeof(MemoryBlock));
    }

    // Search for a free block that is large enough
    MemoryBlock* current = head;
    while (current != NULL) {
        if (current->free && current->size >= size) {
            // Split the block if it is larger than the requested size
            if (current->size > size) {
                MemoryBlock* new_block = (MemoryBlock*) ((char*) current + sizeof(MemoryBlock) + size);
                new_block->size = current->size - size - sizeof(MemoryBlock);
                new_block->free = 1; // Mark the new block as free
                new_block->next = current->next;
                current->size = size;
                current->next = new_block;
            }

            // Mark the block as allocated
            current->free = 0;

            // Return a pointer to the start of the allocated memory
            return (void*) ((char*) current + sizeof(MemoryBlock));
        }
        current = current->next;
    }

    // Error: unable to allocate memory
    return NULL;
}

// Custom free function
void custom_free(void* ptr) {
    // Find the block that contains the pointer
    MemoryBlock* current = head;
    while (current != NULL) {
        if (ptr >= (void*) ((char*) current + sizeof(MemoryBlock)) &&
            ptr < (void*) ((char*) current + sizeof(MemoryBlock) + current->size)) {
            // Mark the block as free
            current->free = 1;

            // Merge adjacent free blocks
            if (current->next != NULL && current->next->free) {
                current->size += current->next->size + sizeof(MemoryBlock);
                current->next = current->next->next;
            }
            if (current == head) {
                head = current->next;
            } else {
                MemoryBlock* prev = head;
                while (prev->next != current) {
                    prev = prev->next;
                }
                prev->next = current->next;
            }

            return;
        }
        current = current->next;
    }

    // Error: pointer is not a valid block
}

// Custom realloc function
void* custom_realloc(void* ptr, size_t new_size) {
    // Check if the pointer is NULL
    if (ptr == NULL) {
        return custom_malloc(new_size);
    }

    // Find the block that contains the pointer
    MemoryBlock* current = head;
    while (current != NULL) {
        if (ptr >= (void*) ((char*) current + sizeof(MemoryBlock)) &&
            ptr < (void*) ((char*) current + sizeof(MemoryBlock) + current->size)) {
            // Check if the new size is equal to the current size
            if (new_size == current->size) {
                return ptr;
            }

            // Check if the adjacent block is free and large enough
            if (current->next != NULL && current->next->free) {
                size_t total_size = current->size + current->next->size + sizeof(MemoryBlock);
                if (new_size <= total_size) {
                    // Merge the adjacent block
                    current->size = new_size;
                    current->next = current->next->next;
                    return (void*) ((char*) current + sizeof(MemoryBlock));
                }
            }

            // Allocate a new block with the new size
            void* new_ptr = custom_malloc(new_size);
            if (new_ptr == NULL) {
                return NULL;
            }

            // Copy the contents of the old block to the new block
            size_t copy_size = (new_size < current->size) ? new_size : current->size;
            memcpy(new_ptr, ptr, copy_size);

            // Free the old block
            custom_free(ptr);

            return new_ptr;
        }
        current = current->next;
    }

    // Error: pointer is not a valid block
    return NULL;
}

// Example usage
int main() {
    // Allocate memory for an integer
    int* num = (int*) custom_malloc(sizeof(int));
    *num = 10;
    printf("%d\n", *num);

    // Reallocate memory for an array of integers
    int* arr = (int*) custom_realloc(num, sizeof(int) * 5);
    for (int i = 0; i < 5; i++) {
        arr[i] = i * 10;
    }
    for (int i = 0; i < 5; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    // Free the memory
    custom_free(arr);

    return 0;
}

