    size_t used_size;
} CustomAllocator;

// Function to initialize the custom allocator
void custom_allocator_init(CustomAllocator *allocator, size_t pool_size) {
    allocator->memory_pool = malloc(pool_size);
    if (allocator->memory_pool == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    allocator->pool_size = pool_size;
