// Function to allocate memory from the pool
void *custom_alloc(CustomAllocator *allocator, size_t size) {
    if (allocator->used_size + size > allocator->pool_size) {
        fprintf(stderr, "Not enough memory in the pool\n");
        return NULL;
    }
    void *ptr = (char *)allocator->memory_pool + allocator->used_size;
    allocator->used_size += size;
    return ptr;
}

// Function to free a previously allocated block (reset used size to 0)
void custom_free(CustomAllocator *allocator) {
    allocator->used_size = 0;
}

// Function to reallocate a block of memory
void *custom_realloc(CustomAllocator *allocator, void *ptr, size_t new_size) {
    if (new_size == 0) {
        return NULL;
    }
    if (ptr == NULL) {
        return custom_alloc(allocator, new_size);
    }
    if (new_size > allocator->pool_size) {
        fprintf(stderr, "Not enough memory in the pool for reallocation\n");
        return NULL;
    }
    // Find the block in the memory pool
    char *block_ptr = (char *)allocator->memory_pool;
    size_t block_offset = (char *)ptr - block_ptr;
    size_t old_size = allocator->used_size - block_offset;

    if (new_size < old_size) {
        // Shrink the block
        allocator->used_size -= (old_size - new_size);
    } else {
        // Grow the block or move it if there's not enough contiguous space
        if (block_offset + new_size > allocator->used_size) {
            // Not enough contiguous space, move the block
            void *new_ptr = custom_alloc(allocator, new_size);
            if (new_ptr == NULL) {
                return NULL;
            }
            memcpy(new_ptr, ptr, old_size);
            return new_ptr;
        } else {
            // Enough contiguous space, expand in place
            allocator->used_size += (new_size - old_size);
        }
    }
    return ptr;
}

// Function to clean up the custom allocator
void custom_allocator_destroy(CustomAllocator *allocator) {
    free(allocator->memory_pool);
    allocator->memory_pool = NULL;
    allocator->pool_size = 0;
    allocator->used_size = 0;
}

// Example usage
int main() {
    CustomAllocator allocator;
    custom_allocator_init(&allocator, 1024); // Initialize with 1KB pool

    char *str1 = custom_alloc(&allocator, 20);
    strcpy(str1, "Hello, World!");
    printf("str1: %s\n", str1);

    char *str2 = custom_alloc(&allocator, 30);
    strcpy(str2, "This is a custom allocator example.");
    printf("str2: %s\n", str2);

    // Reallocate str1 to a larger size
    str1 = custom_realloc(&allocator, str1, 30);
    strcat(str1, " It works!");
    printf("str1 (reallocated): %s\n", str1);

    // Free all allocated memory
    custom_free(&allocator);

    // Clean up the allocator
    custom_allocator_destroy(&allocator);

    return 0;
}

