// Function to compute (base^exp) % mod efficiently
long long power_mod(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;

    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }

    return result;
}

// Function to compute last digit of right-associative power tower
int compute_last_digit(int* arr, int n) {
    if (n == 0) return 1;
    if (n == 1) return arr[0] % 10;

    // Start from the rightmost element
    long long result = arr[n-1];

    // Work backwards through the array
    for (int i = n-2; i >= 0; i--) {
        // Compute exponentiation with clever modular arithmetic
        result = power_mod(arr[i], result, 10);
    }

    return result;
}

