// Function to compute (a^b) mod m efficiently
int modpow(int a, int b, int m) {
    if (m == 1) return 0;
    int result = 1;
    a = a % m;
    while (b > 0) {
        if (b % 2 == 1) {
            result = (result * a) % m;
        }
        a = (a * a) % m;
        b = b / 2;
    }
    return result;
}

// Function to compute the last digit of the tower exponentiation
int last_digit(const int *array, size_t n) {
    if (n == 0) return 1;
    if (n == 1) return array[0] % 10;

    // Handle cases where the exponent might be 0
    int current = array[n-1];
    for (int i = n-2; i >= 1; i--) {
        if (current == 0) {
            current = 1;
        } else if (current == 1) {
            // No change
        } else {
            // Compute mod 4 for the exponent part
            int exponent = array[i] % 4;
            if (exponent == 0 && array[i] != 0) {
                exponent = 4;
            }
            current = modpow(array[i], exponent, 4);
            if (current == 0) current = 4;
        }
    }

    // Now compute the final result
    int base = array[0] % 10;
    if (base == 0) return 0;

    // For exponents congruent to 0 mod 4, we use exponent 4
    if (current % 4 == 0 && current != 0) {
        current = 4;
    } else {
        current = current % 4;
    }

    return modpow(base, current, 10);
}

