// Function to calculate base^exp % 10 efficiently
int power_last_digit(int base, int exp) {
    if (exp == 0) return 1; // Any number to power 0 is 1 (conventionally)
    if (base == 0) return 0; // 0 to any positive power is 0

    base %= 10;
    if (base == 0) return 0;
    if (base == 1) return 1;
    if (base == 5) return 5;
    if (base == 6) return 6;

    // Cycle lengths:
    // 2: 2,4,8,6 (len 4)
    // 3: 3,9,7,1 (len 4)
    // 4: 4,6 (len 2)
    // 7: 7,9,3,1 (len 4)
    // 8: 8,4,2,6 (len 4)
    // 9: 9,1 (len 2)

    int cycle_len;
    if (base == 4 || base == 9) {
        cycle_len = 2;
    } else {
        cycle_len = 4;
    }

    // Adjust exponent based on cycle length.
    // If exp % cycle_len is 0, it means the actual exponent is a multiple of cycle_len.
    // In this case, we use 'cycle_len' as the effective exponent to get the last digit.
    // Why (exp - 1) % cycle_len + 1?
    // exp=1 -> (0)%C+1 = 1
    // exp=2 -> (1)%C+1 = 2
    // exp=C -> (C-1)%C+1 = C
    // exp=C+1 -> (C)%C+1 = 1
    int effective_exp = (exp == 0) ? 0 : ((exp - 1) % cycle_len + 1);

    int result = 1;
    for (int i = 0; i < effective_exp; i++) {
        result = (result * base) % 10;
    }
    return result;
}


