// Corrected and simplified logic for the main problem
// The key is that we don't need to compute the actual value of the nested exponentiation.
// We only need its properties for the next level: its actual value up to 4 (for modulo 4)
// and a flag indicating if it's truly a large number (i.e., >=2, effectively "infinity" for cycle purposes).

// Stores the last digit of the current tower segment
int last_digit_val;
// Stores the effective exponent for the previous level (mod 4)
// This value is `1` for 0, `1` for 1, `2` for 2, `3` for 3, `4` for 4, `>=4` for anything larger.
// This is done to correctly handle the `exp % cycle_len == 0` case.
long long effective_exponent_for_next_base;
// Flag to indicate if the evaluated exponent is truly a large number (i.e. >=4).
// This is critical because `X^0 = 1`, `X^4` has a certain last digit, which might be same as `X^0`'s but different from `X^1`.
// We need to differentiate `X^0`, `X^1`, `X^2`, `X^3`, and `X^large_multiple_of_4`.
// A large number >=4 will behave as "multiples of 4" for cycling purposes.
int is_prev_exp_truly_large;


// Core recursive function to compute the last digit
// This approach simplifies exponent calculation by passing down needed info.
// Returns the actual last digit.
int solve(int* arr, int start_idx, int n) {
    if (start_idx == n - 1) { // Base case: only one number left [xn]
        effective_exponent_for_next_base = (arr[start_idx] == 0) ? 0 : arr[start_idx] % 4;
        if (effective_exponent_for_next_base == 0 && arr[start_idx] != 0) {
            effective_exponent_for_next_base = 4; // If positive and mod 4 is 0, use 4.
        }
        is_prev_exp_truly_large = (arr[start_idx] >= 4); // If last number is >=4, it's large

        return arr[start_idx] % 10;
    }

    // Recursively compute the tower segment to the right: x_(start_idx+1) ^ (... ^ x_n)
    int next_power_result = solve(arr, start_idx + 1, n);

    // Now we need to compute arr[start_idx] ^ next_power_result
    // The exponent is `effective_exponent_for_next_base` (from the recursive call).
    // The base is `arr[start_idx]`.

    int base_val = arr[start_idx];
    int base_digit = base_val % 10;
    long long exp_val = effective_exponent_for_next_base; // This is the exponent we care about (mod 4 value)
    int is_exp_large = is_prev_exp_truly_large;       // Flag from the sub-problem

    // Handle special bases efficiently (0, 1, 5, 6)
    if (base_val == 0) {
        if (exp_val == 0 && !is_exp_large) { // Represents 0^0 case.
            effective_exponent_for_next_base = 1; // 0^0 = 1.
            is_prev_exp_truly_large = 0;
            return 1;
        } else { // 0 to any positive or large power is 0.
            effective_exponent_for_next_base = 0; // The result is 0, so for next level it's 0.
            is_prev_exp_truly_large = (exp_val > 0) || is_exp_large; // If original was pos or large, 0 is large.
            return 0;
        }
    }
    if (base_digit == 1) {
        effective_exponent_for_next_base = 1;
        is_prev_exp_truly_large = 0;
        return 1;
    }
    if (base_digit == 5) {
        effective_exponent_for_next_base = 1; // Any 5^X ends in 5.
        // For modulo 4, 5^1=1, 5^2=1, 5^3=1... so effectively 1.
        is_prev_exp_truly_large = (exp_val > 0) || is_exp_large; // If 'exp_val' was positive (or large), then the resultant 5 is 'large' compared to 0/1. For 5 it doesn't really matter.
        return 5;
    }
    if (base_digit == 6) {
        effective_exponent_for_next_base = 2; // Any 6^X ends in 6.
        // For modulo 4, 6^1=2, 6^2=0, 6^3=0... 
        // If exponent is actual 0, 6^0 = 1 (mod 4 is 1).
        // If exp is actual 1, 6^1 = 6 (mod 4 is 2).
        // If exp is actual 2+, 6^2 = 36 (mod 4 is 0).
        // So for 6^X, if X=0 then 1. If X=1 then 2. If X>=2 then 0.
        // Let's adjust this for `effective_exponent_for_next_base` (the mod 4 value for base).
        // If `exp_val` is 0 (meaning x_{i+1}^...x_n was 0): effective base is 6^0=1. So 1 mod 4.
        if (exp_val == 0 && !is_exp_large) { // True 0 exponent
            effective_exponent_for_next_base = 1; // 6^0 = 1, mod 4 is 1.
        } else if (exp_val == 1 && !is_exp_large) { // True 1 exponent
            effective_exponent_for_next_base = 2; // 6^1 = 6, mod 4 is 2.
        } else { // Exponent is 2 or more, or very large
            effective_exponent_for_next_base = 0; // 6^2=36, mod 4 is 0. 6^3=216, mod 4 is 0.
        }
        is_prev_exp_truly_large = (exp_val >= 2) || is_exp_large;
        return 6;
    }

    // For other bases: 2,3,4,7,8,9
    int actual_exponent_mod_for_last_digit; // This is the exponent for base_digit % 10.
                                         // It's `exp_val` (the passed mod 4 result)
                                         // BUT `exp_val` is 0 if the original exponent was a multiple of 4, or 0 itself.

    if (exp_val == 0 && !is_exp_large) { // Original exponent was truly 0 (e.g. 2^0)
        actual_exponent_mod_for_last_digit = 0; // This will return 1 from power_last_digit
    } else if (is_exp_large) { // Original exponent was very large (i.e. >=4)
                                // We use 4 as the effective exponent for calculating (X^Y) % 10 cycle.
        actual_exponent_mod_for_last_digit = 4;
    } else { // Original exponent was small (1, 2, 3) or mod 4 result
        actual_exponent_mod_for_last_digit = exp_val;
    }

    int current_last_digit = power_last_digit(base_digit, actual_exponent_mod_for_last_digit);

    // Now calculate the effective exponent for the previous level (base_val % 4).
    // This is the effective exponent for `base_{i-1} ^ (base_i ^ (...))`.
    // We need `(base_i ^ (...)) % 4`. This is effectively `base_val ^ (exp_val_true) % 4`.

    int base_val_mod_4 = base_val % 4;
    long long next_effective_exp;
    int next_is_exp_large;

    if (base_val_mod_4 == 0) { // e.g. base = 0, 4, 8.
       if (exp_val == 0 && !is_exp_large) { // 0^0 case (or 4^0, 8^0)
           next_effective_exp = 1;
           next_is_exp_large = 0;
       } else if (exp_val == 1 && !is_exp_large) { // Base X, exp 1. e.g. 4^1=4 (mod 4 is 0).
           next_effective_exp = 0; // X^1 is mod 4 is 0.
           next_is_exp_large = 0; // Not large yet.
       } else { // Exp is 2 or more, or already large
           next_effective_exp = 0; // e.g. 4^2 = 16 (mod 4 is 0).
           next_is_exp_large = 1; // It has become large.
       }
    } else if (base_val_mod_4 == 1) { // e.g. base = 1, 5, 9.
        next_effective_exp = 1; // Always 1.
        next_is_exp_large = 0; // Never large enough to affect cycles with 1.
    } else if (base_val_mod_4 == 2) { // e.g. base = 2, 6.
        if (exp_val == 0 && !is_exp_large) { // X^0=1
            next_effective_exp = 1;
            next_is_exp_large = 0;
        } else if (exp_val == 1 && !is_exp_large) { // 2^1=2, 6^1=2 (mod 4)
            next_effective_exp = 2;
            next_is_exp_large = 0;
        } else { // Exp is 2 or more, or already large. 2^2=4(0), 2^3=8(0), 6^2=36(0)
            next_effective_exp = 0;
            next_is_exp_large = 1;
        }
    } else { // base_val_mod_4 == 3 (e.g. base = 3, 7)
        if (exp_val == 0 && !is_exp_large) { // X^0=1
            next_effective_exp = 1;
            next_is_exp_large = 0;
        } else {
            // For odd bases (like 3, 7) mod 4, it follows exp mod 2.
            // 3^1=3, 3^2=1, 3^3=3, 3^4=1.
            // (exp_val - 1) % 2 + 1 to get 1 or 2 as effective power for mod 4.
            // Effective exponent for modulo 4 of previous base depends on `exp_val_true % 2`.
            // exp_val is usually 1,2,3,4. If exp_val was 1, it's 1. If 2, it's 2. If 3, it's 3. If 4, its 4.
            // But if `is_exp_large` it means the true exponent is large.
            // If `is_exp_large` is true, then `exp_val` represents its `mod 4` characteristics.
            // For Odd bases like 3, 7, the mod 4 values alternate based on exponent being odd/even.
            // If `exp_val` (the passed mod 4 result of the exponent) is itself `2` or `0` and `is_exp_large` is true (implies even):
            // 1, 3, 1, 3, ... (mod 4)
            // If `exp_val` is odd and `is_exp_large` is false: `(exp_val - 1) % 2 + 1` is 1. (e.g. 3^1 = 3 mod 4)
            // If `exp_val` is even and `is_exp_large` is false: `(exp_val - 1) % 2 + 1` is 2. (e.g. 3^2 = 9 = 1 mod 4)
            if ((exp_val % 2 == 1) && !is_exp_large) { // Original exponent was odd
                next_effective_exp = 3; // e.g. 3^1=3, 3^3=27=3 (mod 4)
            } else { // Original exponent was even or very large (behaves as even)
                next_effective_exp = 1; // e.g. 3^2=9=1, 3^4=81=1, (mod 4)
            }
            next_is_exp_large = (exp_val >= 2) || is_exp_large;
        }
    }

    effective_exponent_for_next_base = next_effective_exp;
    is_prev_exp_truly_large = next_is_exp_large;

    return current_last_digit;
}

