    int arr7[] = {7, 7, 7}; // 7 ^ (7 ^ 7). 7^7 ends in 3. So 7^3 ends in 3.
                           // Exponent 7^7 is massive and ends in 3. Mod 4: 7^exp behaves as 3^exp, so mod 4 is 3.
                           // 7^3 (mod 10) = 3.
    int n7 = sizeof(arr7) / sizeof(arr7[0]);
    printf("Input: [7, 7, 7], Last Digit: %d\n", solve(arr7, 0, n7)); // Expected: 3

    int arr8[] = {4, 3, 2, 1}; // 4 ^ (3 ^ (2 ^ 1)) = 4 ^ (3 ^ 2) = 4 ^ 9. Ends in 4.
    int n8 = sizeof(arr8) / sizeof(arr8[0]);
    printf("Input: [4, 3, 2, 1], Last Digit: %d\n", solve(arr8, 0, n8)); // Expected: 4

    int arr9[] = {2, 2, 2, 2}; // 2 ^ (2 ^ (2 ^ 2)) = 2 ^ (2 ^ 4) = 2 ^ 16. Ends in 6.
    int n9 = sizeof(arr9) / sizeof(arr9[0]);
    printf("Input: [2, 2, 2, 2], Last Digit: %d\n", solve(arr9, 0, n9)); // Expected: 6

    int arr10[] = {0}; // Single element
    int n10 = sizeof(arr10) / sizeof(arr10[0]);
    printf("Input: [0], Last Digit: %d\n", solve(arr10, 0, n10)); // Expected: 0

    int arr11[] = {13, 14, 15}; // 13 ^ (14 ^ 15) -> 3 ^ (4 ^ 5). 4^5 ends in 4. So 3^4 = 81. Ends in 1.
    int n11 = sizeof(arr11) / sizeof(arr11[0]);
    printf("Input: [13, 14, 15], Last Digit: %d\n", solve(arr11, 0, n11)); // Expected: 1

    int arr12[] = {2, 0}; // 2^0 = 1
    int n12 = sizeof(arr12) / sizeof(arr12[0]);
    printf("Input: [2, 0], Last Digit: %d\n", solve(arr12, 0, n12)); // Expected: 1

