#include <stdio.h>

// Precomputed cycle lengths for digits 0-9
const int cycle_len[] = {1, 1, 4, 4, 2, 1, 1, 4, 4, 2};

// Modular power: computes (base^exp) % mod for small mod efficently
int mod_pow(int base, int exp, int mod) {
    int result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int last_digit(int *arr, int n) {
    if (n == 0) return 1; // Empty product is 1
    int exp = arr[n-1];
    for (int i = n-2; i >= 0; --i) {
        int base = arr[i] % 10; // we only care about the last digit
        int cyc = cycle_len[base];

        // For cycle lengths 1, any exponent is fine; otherwise, get exponent mod cycle
        int cur_exp;
        if (cyc == 1) {
            cur_exp = 0; // exp doesn't matter
        } else {
            // Watch out, exponent mod cyc === 0 => need to use full cycle, not 0
            cur_exp = mod_pow(exp, 1, cyc);
            if (cur_exp == 0) cur_exp = cyc;
        }
        // Now "base" raised to cur_exp determines the last digit from this stage
        exp = mod_pow(base, cur_exp, 10);
    }
    return exp;
}

// Example main function
int main() {
    // Example: [3, 4, 2] -> should print 1
    int arr[] = {3, 4, 2};
    int n = sizeof(arr)/sizeof(arr[0]);
    printf("%d\n", last_digit(arr, n)); // Output: 1

    // Try with a huge exponent
    int arr2[] = {7, 6, 21, 1111};
    n = sizeof(arr2)/sizeof(arr2[0]);
    printf("%d\n", last_digit(arr2, n)); // Should work instantly

    return 0;
}

#include <stdio.h>

// Function to compute (base^exp) % mod using modular exponentiation
int modular_exponentiation(int base, int exp, int mod) {
    int result = 1;
    base = base % mod;

    while(exp > 0) {
        if(exp % 2 == 1) { // If exp is odd
            result = (result * base) % mod;
        }
        exp = exp >> 1; // exp = exp / 2
        base = (base * base) % mod;
    }

    return result;
}

// Function to find last digit of a^b
int last_digit_of_power(int a, int b) {
    if(b == 0) return 1; // a^0 = 1 for any non-zero a
    a = a % 10; // We only care about the last digit of the base
    int cycle_length = 0;
    int cycle[10]; // To store the cycle of last digits

    // Determine the cycle of last digits
    int current = a;
    do {
        cycle[cycle_length++] = current % 10;
        current = (current * a) % 10;
    } while(current != a);

    // Reduce the power modulo cycle length
    int effective_exponent = b % cycle_length;
    if(effective_exponent == 0) {
        effective_exponent = cycle_length; // Use the last element in the cycle if the exponent is a perfect multiple of the cycle length
    }

    return cycle[effective_exponent - 1]; // -1 for zero-based index
}

int find_last_digit(int arr[], int n) {
    if(n == 0) return 1; // If the list is empty, consider result as 1

    // Start with the last element
    int result = arr[n-1];

    // Traverse backwards
    for(int i = n - 2; i >= 0; --i) {
        result = last_digit_of_power(arr[i], result);
    }

    return result % 10; // Only return the last digit
}

int main() {
    int arr[] = {3, 4, 2}; // Example list
    int n = sizeof(arr)/sizeof(arr[0]);

    int last_digit = find_last_digit(arr, n);
    printf("Last decimal digit is: %d\n", last_digit);

    return 0;
}

#include <stdio.h>

// Function to compute last digit of a^b % 10
int last_digit_power(int a, int b) {
    if (b == 0) {
        return 1; // a^0 is 1
    }

    // Reduce a to its last digit since we only care about the last digit
    a = a % 10;

    // Handle the case when a is 0
    if (a == 0) {
        return 0;
    }

    // If b is very large, use properties of cyclicity
    // The last digit of powers of numbers can be cyclic.
    // Find cycle of last digits
    int cycle[10][4] = {
        {0},                  // last digit 0
        {1},                  // last digit 1
        {2, 4, 8, 6},        // last digit 2
        {3, 9, 7, 1},        // last digit 3
        {4, 6},              // last digit 4
        {5},                  // last digit 5
        {6},                  // last digit 6
        {7, 9, 3, 1},        // last digit 7
        {8, 4, 2, 6},        // last digit 8
        {9, 1}               // last digit 9
    };

    int cycle_length = 0;
    while (cycle[a][cycle_length] != 0) {
        cycle_length++;
    }

    // Determine the effective exponent in the cycle
    // Note: If cycle_length is 0, it means a is 0 which was handled earlier.
    int effective_exponent = (b % cycle_length == 0) ? cycle_length : (b % cycle_length);
    return cycle[a][effective_exponent - 1];
}

// Function to compute last digit of x1 ^ (x2 ^ (x3 ^ ... ^ xn))
int last_digit_of_full_expression(int arr[], int n) {
    if (n == 0) return 1; // edge case
    if (n == 1) return arr[0] % 10; // return last digit of single number

    // Start with the last number
    int result = arr[n - 1]; 

    // Compute the power from the end to the beginning
    for (int i = n - 2; i >= 0; i--) {
        result = last_digit_power(arr[i], result);
    }

    return result;
}

int main() {
    int arr[] = {3, 4, 2}; // Example input
    int n = sizeof(arr) / sizeof(arr[0]);

    int last_digit = last_digit_of_full_expression(arr, n);
    printf("The last digit is: %d\n", last_digit);

    return 0;
}

#include <stdio.h>

// Function to calculate the power in modular arithmetic with a cycle of 4
int mod_power(int x, int n) {
    int result = x;
    int cycle_length = 4;
    n = n % cycle_length;

    for (int i = 0; i < n - 1; i++) {
        result = (result * x) % 10;
    }
    return result;
}

// Function to calculate the last digit of the nested exponentiation
int last_digit_nested_exponentiation(int arr[], int size) {
    if (size == 1) {
        return arr[0] % 10;
    }

    int power = arr[size - 1];
    int base = last_digit_nested_exponentiation(arr, size - 1);

    if (base == 0) {
        return 0;
    } else if (base == 1) {
        return 1;
    } else if (base == 5) {
        return 5;
    } else if (base == 6) {
        return 6;
    } else {
        return mod_power(base, power);
    }
}

int main() {
    int arr[] = {3, 4, 2};
    int size = sizeof(arr) / sizeof(arr[0]);

    int result = last_digit_nested_exponentiation(arr, size);
    printf("Last digit of the nested exponentiation is: %d\n", result);

    return 0;
}

#include <stdio.h>

// Function to compute the last digit of a^b
int last_digit(int a, int b) {
    // The last digit of a^b repeats every 4 cycles
    int last_a = a % 10;
    if (b == 0) return 1; // Any number to the power of 0 is 1
    if (last_a == 0 || last_a == 1 || last_a == 5 || last_a == 6) return last_a; // Special cases
    int reduced_b = b % 4;
    if (reduced_b == 0) reduced_b = 4; // 4 is the cycle length
    return (int)pow(last_a, reduced_b) % 10;
}

// Function to compute the last digit of a power tower
int last_digit_tower(int *arr, int n) {
    if (n == 1) return arr[0] % 10; // Base case: single number
    int last_exp = 1;
    for (int i = n - 1; i > 0; i--) {
        last_exp = (last_exp * arr[i]) % 4; // Reduce the exponent modulo 4
    }
    return last_digit(arr[0], last_exp);
}

int main() {
    int arr[] = {3, 4, 2};
    int n = sizeof(arr) / sizeof(arr[0]);

    int result = last_digit_tower(arr, n);
    printf("The last digit is: %d\n", result);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_SEATS 50
#define MAX_NAME_LENGTH 50

// Passenger structure
typedef struct {
    char firstName[MAX_NAME_LENGTH];
    char lastName[MAX_NAME_LENGTH];
    int seatNumber;
} Passenger;

// Airplane reservation system structure
typedef struct {
    Passenger seats[MAX_SEATS];
    int totalSeats;
    int availableSeats;
} AirlineReservation;

// Function prototypes
void initializeReservation(AirlineReservation *airline, int seats);
void displayMenu();
void displaySeatingChart(AirlineReservation *airline);
bool bookSeat(AirlineReservation *airline);
bool cancelReservation(AirlineReservation *airline);
void saveReservations(AirlineReservation *airline);
void loadReservations(AirlineReservation *airline);

int main() {
    AirlineReservation airline;
    int seats;
    int choice;

    printf("Enter total number of seats (max %d): ", MAX_SEATS);
    scanf("%d", &seats);

    // Validate seat count
    if (seats <= 0 || seats > MAX_SEATS) {
        printf("Invalid seat count. Using default of 10 seats.\n");
        seats = 10;
    }

    initializeReservation(&airline, seats);
    loadReservations(&airline);

    while (1) {
        displayMenu();
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                displaySeatingChart(&airline);
                break;
            case 2:
                if (bookSeat(&airline)) {
                    printf("Seat booked successfully!\n");
                    saveReservations(&airline);
                }
                break;
            case 3:
                if (cancelReservation(&airline)) {
                    printf("Reservation cancelled successfully!\n");
                    saveReservations(&airline);
                }
                break;
            case 4:
                saveReservations(&airline);
                printf("Thank you for using the Airline Reservation System!\n");
                exit(0);
            default:
                printf("Invalid choice. Please try again.\n");
        }
    }

    return 0;
}

// Initialize airline reservation
void initializeReservation(AirlineReservation *airline, int seats) {
    airline->totalSeats = seats;
    airline->availableSeats = seats;

    for (int i = 0; i < seats; i++) {
        airline->seats[i].seatNumber = i + 1;
        strcpy(airline->seats[i].firstName, "");
        strcpy(airline->seats[i].lastName, "");
    }
}

// Display main menu
void displayMenu() {
    printf("\n--- Airline Reservation System ---\n");
    printf("1. View Seating Chart\n");
    printf("2. Book a Seat\n");
    printf("3. Cancel Reservation\n");
    printf("4. Exit\n");
}

// Display current seating chart
void displaySeatingChart(AirlineReservation *airline) {
    printf("\nSeating Chart:\n");
    for (int i = 0; i < airline->totalSeats; i++) {
        if (strlen(airline->seats[i].firstName) == 0) {
            printf("Seat %d: Available\n", airline->seats[i].seatNumber);
        } else {
            printf("Seat %d: Reserved by %s %s\n", 
                   airline->seats[i].seatNumber,
                   airline->seats[i].firstName,
                   airline->seats[i].lastName);
        }
    }
    printf("Available Seats: %d\n", airline->availableSeats);
}

// Book a seat
bool bookSeat(AirlineReservation *airline) {
    int seatChoice;
    Passenger newPassenger;

    if (airline->availableSeats == 0) {
        printf("Sorry, no seats available.\n");
        return false;
    }

    printf("Enter seat number (1-%d): ", airline->totalSeats);
    scanf("%d", &seatChoice);

    if (seatChoice < 1 || seatChoice > airline->totalSeats) {
        printf("Invalid seat number.\n");
        return false;
    }

    if (strlen(airline->seats[seatChoice - 1].firstName) != 0) {
        printf("Seat already reserved.\n");
        return false;
    }

    printf("Enter passenger first name: ");
    scanf("%s", newPassenger.firstName);
    printf("Enter passenger last name: ");
    scanf("%s", newPassenger.lastName);

    newPassenger.seatNumber = seatChoice;
    airline->seats[seatChoice - 1] = newPassenger;
    airline->availableSeats--;

    return true;
}

// Cancel reservation
bool cancelReservation(AirlineReservation *airline) {
    int seatChoice;

    printf("Enter seat number to cancel: ");
    scanf("%d", &seatChoice);

    if (seatChoice < 1 || seatChoice > airline->totalSeats) {
        printf("Invalid seat number.\n");
        return false;
    }

    if (strlen(airline->seats[seatChoice - 1].firstName) == 0) {
        printf("Seat is already available.\n");
        return false;
    }

    strcpy(airline->seats[seatChoice - 1].firstName, "");
    strcpy(airline->seats[seatChoice - 1].lastName, "");
    airline->availableSeats++;

    return true;
}

// Save reservations to file
void saveReservations(AirlineReservation *airline) {
    FILE *file = fopen("reservations.dat", "wb");
    if (file == NULL) {
        printf("Error saving reservations.\n");
        return;
    }

    fwrite(airline, sizeof(AirlineReservation), 1, file);
    fclose(file);
}

// Load reservations from file
void loadReservations(AirlineReservation *airline) {
    FILE *file = fopen("reservations.dat", "rb");
    if (file == NULL) {
        return;
    }

    fread(airline, sizeof(AirlineReservation), 1, file);
    fclose(file);
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

#define MAX_NAME_LENGTH 50
#define MAX_FLIGHTS 5

typedef struct {
    char name[MAX_NAME_LENGTH];
    int seatNumber;
    bool isBooked;
} Passenger;

typedef struct {
    int flightNumber;
    int totalSeats;
    int availableSeats;
    Passenger* passengers;
} Flight;

void initializeFlight(Flight* flight, int flightNum, int seats) {
    flight->flightNumber = flightNum;
    flight->totalSeats = seats;
    flight->availableSeats = seats;
    flight->passengers = (Passenger*)malloc(seats * sizeof(Passenger));

    for (int i = 0; i < seats; i++) {
        flight->passengers[i].isBooked = false;
        flight->passengers[i].seatNumber = i + 1;
        strcpy(flight->passengers[i].name, "");
    }
}

void displayFlightStatus(Flight flight) {
    printf("\nFlight %d Status:\n", flight.flightNumber);
    printf("Total seats: %d\n", flight.totalSeats);
    printf("Available seats: %d\n", flight.availableSeats);

    printf("\nSeat Map:\n");
    for (int i = 0; i < flight.totalSeats; i++) {
        if (flight.passengers[i].isBooked) {
            printf("Seat %d: Booked by %s\n", i+1, flight.passengers[i].name);
        } else {
            printf("Seat %d: Available\n", i+1);
        }
    }
}

bool bookSeat(Flight* flight, int seatNum, const char* name) {
    if (seatNum < 1 || seatNum > flight->totalSeats) {
        printf("Invalid seat number. Please try again.\n");
        return false;
    }

    if (flight->passengers[seatNum-1].isBooked) {
        printf("Seat %d is already booked.\n", seatNum);
        return false;
    }

    flight->passengers[seatNum-1].isBooked = true;
    strncpy(flight->passengers[seatNum-1].name, name, MAX_NAME_LENGTH-1);
    flight->passengers[seatNum-1].name[MAX_NAME_LENGTH-1] = '\0';
    flight->availableSeats--;

    printf("Seat %d successfully booked for %s.\n", seatNum, name);
    return true;
}

bool cancelBooking(Flight* flight, int seatNum) {
    if (seatNum < 1 || seatNum > flight->totalSeats) {
        printf("Invalid seat number. Please try again.\n");
        return false;
    }

    if (!flight->passengers[seatNum-1].isBooked) {
        printf("Seat %d is not booked.\n", seatNum);
        return false;
    }

    flight->passengers[seatNum-1].isBooked = false;
    strcpy(flight->passengers[seatNum-1].name, "");
    flight->availableSeats++;

    printf("Booking for seat %d has been cancelled.\n", seatNum);
    return true;
}

void freeFlight(Flight* flight) {
    free(flight->passengers);
}

int main() {
    int totalSeats;
