        scanf("%d", &choice);

        // Clear input buffer
        while (getchar() != '\n');

        switch(choice) {
            case 1:
                displayFlightStatus(myFlight);
                break;
            case 2:
                if (myFlight.availableSeats == 0) {
                    printf("Sorry, the flight is fully booked.\n");
                    break;
                }
                printf("Enter passenger name: ");
