#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>

#define MAX_LINE_LENGTH 1024
#define MAX_IP_LENGTH 50
#define MAX_UNIQUE_IPS 10000

// Structure to store IP information
typedef struct {
    char ip[MAX_IP_LENGTH];
    int count;
} IPEntry;

// Hash function to generate unique index for IP
unsigned int hash_ip(const char* ip, unsigned int max_size) {
    unsigned int hash = 0;
    MD5_CTX md5_ctx;
    unsigned char md5_digest[MD5_DIGEST_LENGTH];

    MD5_Init(&md5_ctx);
    MD5_Update(&md5_ctx, ip, strlen(ip));
    MD5_Final(md5_digest, &md5_ctx);

    // Convert first 4 bytes of MD5 digest to unsigned int
    for (int i = 0; i < 4; i++) {
        hash = (hash << 8) | md5_digest[i];
    }

    return hash % max_size;
}

// Function to extract IP from log line
int extract_ip(const char* line, char* ip) {
    char* token = strtok((char*)line, " ");
    if (token != NULL) {
        strncpy(ip, token, MAX_IP_LENGTH - 1);
        ip[MAX_IP_LENGTH - 1] = '\0';
        return 1;
    }
    return 0;
}

// Analyze log file for unique visitors
void analyze_log_file(const char* filename) {
    FILE* file;
    char line[MAX_LINE_LENGTH];
    char ip[MAX_IP_LENGTH];
    IPEntry ip_table[MAX_UNIQUE_IPS] = {0};
    int unique_visitor_count = 0;
    int total_visitors = 0;

    // Open log file
    file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening log file");
        exit(1);
    }

    // Process each line in log file
    while (fgets(line, sizeof(line), file)) {
        if (extract_ip(line, ip)) {
            total_visitors++;

            // Calculate hash index for IP
            unsigned int index = hash_ip(ip, MAX_UNIQUE_IPS);

            // Linear probing for collision resolution
            while (ip_table[index].ip[0] != '\0' && 
                   strcmp(ip_table[index].ip, ip) != 0) {
                index = (index + 1) % MAX_UNIQUE_IPS;
            }

            // Add new unique visitor or increment count
            if (ip_table[index].ip[0] == '\0') {
                strncpy(ip_table[index].ip, ip, MAX_IP_LENGTH - 1);
                ip_table[index].count = 1;
                unique_visitor_count++;
            } else {
                ip_table[index].count++;
            }
        }
    }

    // Close file
    fclose(file);

    // Print analysis results
    printf("Log File Analysis Report\n");
    printf("------------------------\n");
    printf("Total Visitors: %d\n", total_visitors);
    printf("Unique Visitors: %d\n", unique_visitor_count);

    // Print detailed visitor information
    printf("\nTop Visitors:\n");
    for (int i = 0; i < MAX_UNIQUE_IPS; i++) {
        if (ip_table[i].ip[0] != '\0') {
            printf("IP: %s, Visits: %d\n", 
                   ip_table[i].ip, ip_table[i].count);
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <log_file>\n", argv[0]);
        return 1;
    }

    analyze_log_file(argv[1]);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define HASH_SIZE 1000

typedef struct Node {
    char ip[16]; // IPv4 addresses are at most 15 characters long
    struct Node* next;
} Node;

unsigned int hash(const char* ip) {
    unsigned int hash_value = 0;
    for (int i = 0; ip[i] != '\0'; i++) {
        hash_value = (hash_value * 31 + ip[i]) % HASH_SIZE;
    }
    return hash_value;
}

Node* create_node(const char* ip) {
    Node* node = (Node*)malloc(sizeof(Node));
    strncpy(node->ip, ip, 15);
    node->ip[15] = '\0';
    node->next = NULL;
    return node;
}

void insert(Node** hash_table, const char* ip) {
    unsigned int index = hash(ip);
    Node* current = hash_table[index];

    while (current != NULL) {
        if (strcmp(current->ip, ip) == 0) {
            return; // IP already exists
        }
        current = current->next;
    }

    Node* new_node = create_node(ip);
    new_node->next = hash_table[index];
    hash_table[index] = new_node;
}

int count_unique_visitors(Node** hash_table) {
    int count = 0;
    for (int i = 0; i < HASH_SIZE; i++) {
        Node* current = hash_table[i];
        while (current != NULL) {
            count++;
            current = current->next;
        }
    }
    return count;
}

void free_hash_table(Node** hash_table) {
    for (int i = 0; i < HASH_SIZE; i++) {
        Node* current = hash_table[i];
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }
}

int main() {
    FILE* file = fopen("access.log", "r");
    if (file == NULL) {
        perror("Unable to open file");
        return 1;
    }

    Node* hash_table[HASH_SIZE] = { NULL };
    char line[1024];

    while (fgets(line, sizeof(line), file)) {
        char ip[16];
        if (sscanf(line, "%15s", ip) == 1) {
            insert(hash_table, ip);
        }
    }

    fclose(file);

    int unique_visitors = count_unique_visitors(hash_table);
    printf("Number of unique visitors: %d\n", unique_visitors);

    free_hash_table(hash_table);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h> // For 'bool' type

// --- Hash Table (Hash Set) Implementation ---
// We'll use a simple hash table with separate chaining
// to store the unique IP addresses.

#define HASH_TABLE_SIZE 10007 // A prime number for better distribution

// Node structure for linked list in hash table
typedef struct Node {
    char *ip_address;
    struct Node *next;
} Node;

// Hash table structure
typedef struct {
    Node *buckets[HASH_TABLE_SIZE];
} HashTable;

// Function to initialize the hash table
void init_hash_table(HashTable *ht) {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        ht->buckets[i] = NULL;
    }
}

// Simple hash function for IP addresses
unsigned int hash(const char *key) {
    unsigned int hash = 0;
    while (*key != '\0') {
        hash = (hash << 5) + *key++; // Classic DJB2 hash
    }
    return hash % HASH_TABLE_SIZE;
}

// Function to insert an IP into the hash table
// Returns true if the IP was new and inserted, false if it already existed.
bool insert_ip(HashTable *ht, const char *ip) {
    unsigned int index = hash(ip);
    Node *current = ht->buckets[index];

    // Check if IP already exists in this bucket
    while (current != NULL) {
        if (strcmp(current->ip_address, ip) == 0) {
            return false; // IP already exists
        }
        current = current->next;
    }

    // IP is new, so add it
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }
    new_node->ip_address = strdup(ip); // Allocate memory and copy the IP string
    if (new_node->ip_address == NULL) {
        perror("Failed to allocate memory for IP address string");
        free(new_node); // Free the node itself
        exit(EXIT_FAILURE);
    }
    new_node->next = ht->buckets[index];
    ht->buckets[index] = new_node;

    return true; // IP was new and inserted
}

// Function to free memory used by the hash table
void free_hash_table(HashTable *ht) {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        Node *current = ht->buckets[i];
        while (current != NULL) {
            Node *temp = current;
            current = current->next;
            free(temp->ip_address); // Free the duplicated IP string
            free(temp);             // Free the node itself
        }
    }
}

