// Function to check if an IP is already in the list
int already_exists(char **ip_list, int count, const char *ip) {
    for (int i = 0; i < count; ++i) {
        if (strcmp(ip_list[i], ip) == 0)
            return 1;
    }
    return 0;
}

int main() {
    FILE *fp = fopen("access.log", "r");
    if (!fp) {
        perror("Failed to open access.log");
        return 1;
    }

    char line[MAX_LINE];
    char ip[MAX_IP];

    int ip_list_size = INITIAL_IPS;
    int unique_count = 0;
    char **ip_list = malloc(ip_list_size * sizeof(char *));
    if (!ip_list) {
        fprintf(stderr, "Memory allocation failed!\n");
        fclose(fp);
        return 1;
    }

    while (fgets(line, sizeof(line), fp)) {
        // extract first token (IP address)
        char *token = strtok(line, " \t");
        if (token) {
            strncpy(ip, token, MAX_IP-1);
            ip[MAX_IP-1] = '\0';

            if (!already_exists(ip_list, unique_count, ip)) {
                if (unique_count >= ip_list_size) {
                    ip_list_size *= 2;
                    char **temp = realloc(ip_list, ip_list_size * sizeof(char *));
                    if (!temp) {
                        fprintf(stderr, "Memory reallocation failed!\n");
                        break;
                    }
                    ip_list = temp;
                }
                ip_list[unique_count] = strdup(ip);
                if (!ip_list[unique_count]) {
                    fprintf(stderr, "Memory allocation failed!\n");
                    break;
                }
                unique_count++;
            }
        }
    }

    fclose(fp);

    printf("Unique visitors: %d\n", unique_count);

    // Free memory
    for (int i = 0; i < unique_count; ++i) {
        free(ip_list[i]);
    }
    free(ip_list);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024
#define HASH_TABLE_SIZE 1000

typedef struct Node {
    char ip[16];
    struct Node* next;
} Node;

unsigned int hash(const char* ip) {
    unsigned int hash = 0;
    while (*ip) {
        hash = (hash << 5) + *ip++;
    }
    return hash % HASH_TABLE_SIZE;
}

Node* create_node(const char* ip) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    strcpy(new_node->ip, ip);
    new_node->next = NULL;
    return new_node;
}

int is_unique(Node* hash_table[], const char* ip) {
    unsigned int index = hash(ip);
    Node* current = hash_table[index];

    while (current != NULL) {
        if (strcmp(current->ip, ip) == 0) {
            return 0; // IP already exists
        }
        current = current->next;
    }

    // Add new IP to the hash table
    Node* new_node = create_node(ip);
    new_node->next = hash_table[index];
    hash_table[index] = new_node;
    return 1;
}

void free_hash_table(Node* hash_table[]) {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        Node* current = hash_table[i];
        while (current != NULL) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }
}

int main() {
    FILE* log_file = fopen("access.log", "r");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    Node* hash_table[HASH_TABLE_SIZE] = {NULL};
    char line[MAX_LINE_LENGTH];
    int unique_visitors = 0;

    while (fgets(line, sizeof(line), log_file)) {
        // Assuming IP addresses are at the beginning of each line
        char ip[16];
        sscanf(line, "%15s", ip); // Read up to 15 characters for IP

        if (is_unique(hash_table, ip)) {
            unique_visitors++;
        }
    }

    fclose(log_file);
    free_hash_table(hash_table);

    printf("Unique visitors: %d\n", unique_visitors);
    return EXIT_SUCCESS;
}

