#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024
#define TABLE_SIZE 1000003  // Prime number for hash table size

// Hash table entry structure
typedef struct Entry {
    char ip[16];  // IPv4 address (e.g., "192.168.1.1")
    struct Entry *next;  // Pointer to next entry in case of collision
} Entry;

// Hash table
Entry *ipTable[TABLE_SIZE];

// Hash function for IP addresses
unsigned int hashIP(const char *ip) {
    unsigned int hash = 0;
    for (int i = 0; i < strlen(ip); i++) {
        hash = (hash * 31 + ip[i]) % TABLE_SIZE;
    }
    return hash;
}

// Function to add an IP address to the hash table
void addIP(const char *ip) {
    unsigned int index = hashIP(ip);
    Entry *entry = ipTable[index];

    while (entry != NULL) {
        if (strcmp(entry->ip, ip) == 0) {
            return;  // IP already exists in the table
        }
        entry = entry->next;
    }

    // Allocate memory for new entry
    Entry *newEntry = (Entry *)malloc(sizeof(Entry));
    if (newEntry == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    // Copy IP to new entry and link it
    strncpy(newEntry->ip, ip, sizeof(newEntry->ip) - 1);
    newEntry->ip[sizeof(newEntry->ip) - 1] = '\0';
    newEntry->next = ipTable[index];
    ipTable[index] = newEntry;
}

// Function to free the hash table
void freeHashTable() {
    for (int i = 0; i < TABLE_SIZE; i++) {
        Entry *entry = ipTable[i];
        while (entry != NULL) {
            Entry *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }
}

// Function to parse the log file and count unique IPs
int countUniqueVisitors(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        return -1;
    }

    char line[MAX_LINE_LENGTH];
    int uniqueCount = 0;

    while (fgets(line, sizeof(line), file)) {
        char *ip = strtok(line, " ");  // Extract the first token (IP address)
        if (ip != NULL) {
            unsigned int index = hashIP(ip);
            Entry *entry = ipTable[index];

            while (entry != NULL) {
                if (strcmp(entry->ip, ip) == 0) {
                    break;  // IP already exists
                }
                entry = entry->next;
            }

            if (entry == NULL) {  // IP does not exist in the table
                uniqueCount++;
                addIP(ip);
            }
        }
    }

    fclose(file);
    return uniqueCount;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <logfile>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *filename = argv[1];
    int uniqueVisitors = countUniqueVisitors(filename);

    if (uniqueVisitors >= 0) {
        printf("Number of unique visitors: %d\n", uniqueVisitors);
    } else {
        fprintf(stderr, "Error counting unique visitors.\n");
        return EXIT_FAILURE;
    }

    // Clean up the hash table
    freeHashTable();

    return EXIT_SUCCESS;
}

