#define MAX_LINE_LENGTH 1024
#define MAX_IPS 1000
#define IP_LENGTH 16

typedef struct {
    char ip[IP_LENGTH];
    int count;
} Visitor;

int is_valid_ip(const char *ip) {
    int num, dots = 0;
    const char *ptr = ip;

    if (ip == NULL) return 0;

    while (*ptr) {
        if (*ptr == '.') {
            dots++;
            if (dots > 3) return 0;
            num = -1;
        } else if (isdigit(*ptr)) {
            if (num == -1) num = 0;
            num = num * 10 + (*ptr - '0');
            if (num > 255) return 0;
        } else {
            return 0;
        }
        ptr++;
    }

    return (dots == 3);
}

int find_visitor(Visitor visitors[], int count, const char *ip) {
    for (int i = 0; i < count; i++) {
        if (strcmp(visitors[i].ip, ip) == 0) {
            return i;
        }
    }
    return -1;
}

void process_log_file(const char *filename, Visitor visitors[], int *visitor_count) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        exit(1);
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        // Simple IP extraction - this may need adjustment based on your log format
        char *ip_start = line;
        char ip[IP_LENGTH] = {0};
        int i = 0;

        // Skip non-IP characters at start (like timestamp)
        while (*ip_start && !isdigit(*ip_start)) ip_start++;

        // Extract potential IP
        while (*ip_start && (isdigit(*ip_start) || *ip_start == '.') && i < IP_LENGTH-1) {
            ip[i++] = *ip_start++;
        }
        ip[i] = '\0';

        if (is_valid_ip(ip)) {
            int index = find_visitor(visitors, *visitor_count, ip);
            if (index >= 0) {
                visitors[index].count++;
            } else if (*visitor_count < MAX_IPS) {
                strncpy(visitors[*visitor_count].ip, ip, IP_LENGTH-1);
                visitors[*visitor_count].count = 1;
                (*visitor_count)++;
            } else {
                printf("Warning: Maximum number of unique IPs (%d) reached.\n", MAX_IPS);
                break;
            }
        }
    }

    fclose(file);
}

void print_unique_visitors(Visitor visitors[], int count) {
    printf("Unique Visitors Report:\n");
    printf("=======================\n");
    printf("%-15s %s\n", "IP Address", "Visits");
    printf("---------------- --------\n");

    for (int i = 0; i < count; i++) {
        printf("%-15s %d\n", visitors[i].ip, visitors[i].count);
    }

    printf("\nTotal unique visitors: %d\n", count);
