#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h> // For bool type

// --- Hash Table Implementation ---

// Maximum length for an IP address string (e.g., "255.255.255.255\0")
#define MAX_IP_LEN 16 
// Size of our hash table array. Choose a prime number for better distribution.
#define HASH_TABLE_SIZE 1009 

// Structure for a linked list node in our hash table
typedef struct Node {
    char ip_address[MAX_IP_LEN];
    struct Node *next;
} Node;

// Hash table structure
Node *hash_table[HASH_TABLE_SIZE];
int unique_visitors_count = 0;

// Simple hash function (FNV-1a is good, but simple sum is sufficient for this)
// This is a basic DJB2 hash function, commonly used for strings.
unsigned int hash(const char *str) {
    unsigned int hash_val = 5381; // Initial prime number
    int c;
    while ((c = *str++)) {
        hash_val = ((hash_val << 5) + hash_val) + c; // hash * 33 + c
    }
    return hash_val % HASH_TABLE_SIZE;
}

// Function to insert an IP address into the hash table
// Returns true if the IP was new and added, false if it already existed.
bool insert_ip(const char *ip) {
    unsigned int index = hash(ip);
    Node *current = hash_table[index];

    // Traverse the linked list at this index to check for duplicates
    while (current != NULL) {
        if (strcmp(current->ip_address, ip) == 0) {
            return false; // IP already exists
        }
        current = current->next;
    }

    // IP is unique, so add it
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed for new node!\n");
        exit(EXIT_FAILURE);
    }
    strncpy(new_node->ip_address, ip, MAX_IP_LEN - 1);
    new_node->ip_address[MAX_IP_LEN - 1] = '\0'; // Ensure null-termination
    new_node->next = hash_table[index]; // Add to the front of the list
    hash_table[index] = new_node;
    unique_visitors_count++;
    return true;
}

// Function to free the memory used by the hash table
void free_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        Node *current = hash_table[i];
        while (current != NULL) {
            Node *temp = current;
            current = current->next;
            free(temp);
        }
        hash_table[i] = NULL; // Clear the pointer
    }
}

