// Hash table node
typedef struct Node {
    char ip[MAX_IP_LEN];
    struct Node *next;
} Node;

// Simple hash function for string (IP)
unsigned hash(const char *str) {
    unsigned h = 0;
    while (*str)
        h = (h * 31) + (unsigned char)*str++;
    return h % HASH_SIZE;
}

// Insert IP to hash table if not present, return 1 if newly inserted
int insert(Node *table[], const char *ip) {
    unsigned h = hash(ip);
    Node *cur = table[h];
    while (cur) {
        if (strcmp(cur->ip, ip) == 0)
            return 0;  // Already present
        cur = cur->next;
    }
    // Insert new
    Node *n = malloc(sizeof(Node));
    if (!n) {
        fprintf(stderr, "Memory error\n");
        exit(1);
    }
    strcpy(n->ip, ip);
    n->next = table[h];
    table[h] = n;
    return 1;
}

// Free hash table
void free_table(Node *table[]) {
    for (int i = 0; i < HASH_SIZE; ++i) {
        Node *cur = table[i];
        while (cur) {
            Node *tmp = cur;
            cur = cur->next;
            free(tmp);
        }
    }
}

