typedef struct Visitor {
    char ip[IP_ADDRESS_LENGTH];
} Visitor;

typedef struct VisitorSet {
    Visitor *visitors;
    size_t capacity;
    size_t size;
} VisitorSet;

VisitorSet *create_visitor_set(size_t initial_capacity) {
    VisitorSet *set = (VisitorSet *)malloc(sizeof(VisitorSet));
    if (set == NULL) {
        perror("Failed to allocate memory for visitor set");
        exit(EXIT_FAILURE);
    }
    set->visitors = (Visitor *)malloc(initial_capacity * sizeof(Visitor));
    if (set->visitors == NULL) {
        perror("Failed to allocate memory for visitors");
        free(set);
        exit(EXIT_FAILURE);
    }
    set->capacity = initial_capacity;
    set->size = 0;
    return set;
}

void destroy_visitor_set(VisitorSet *set) {
    free(set->visitors);
    free(set);
}

int add_visitor(VisitorSet *set, const char *ip) {
    // Check if the IP is already in the set
    for (size_t i = 0; i < set->size; i++) {
        if (strcmp(set->visitors[i].ip, ip) == 0) {
            return 0; // IP already exists
        }
    }

    // If the set is full, resize it
    if (set->size >= set->capacity) {
        size_t new_capacity = set->capacity * 2;
        Visitor *new_visitors = (Visitor *)realloc(set->visitors, new_capacity * sizeof(Visitor));
        if (new_visitors == NULL) {
            perror("Failed to reallocate memory for visitors");
            exit(EXIT_FAILURE);
        }
        set->visitors = new_visitors;
        set->capacity = new_capacity;
    }

    // Add the new IP to the set
    strcpy(set->visitors[set->size].ip, ip);
    set->size++;
    return 1; // IP added successfully
}

