#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the maximum length of an IP address string
#define MAX_IP_LEN 16 // e.g., "255.255.255.255\0"
// Define the size of the hash table array
#define HASH_TABLE_SIZE 10007 // A prime number is often a good choice

// Structure for a node in the linked list (for hash table chaining)
typedef struct Node {
    char ip_address[MAX_IP_LEN]; // Store the IP address
    struct Node *next;           // Pointer to the next node in the chain
} Node;

// Hash table array (an array of pointers to Nodes)
Node *hash_table[HASH_TABLE_SIZE];

// Function to initialize the hash table
void init_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        hash_table[i] = NULL;
    }
}

// Simple hash function for IP addresses
unsigned int hash(const char *ip) {
    unsigned int hash_val = 0;
    // Iterate through the characters of the IP address
    for (int i = 0; ip[i] != '\0'; i++) {
        hash_val = (hash_val * 31) + ip[i]; // Multiply by a prime and add ASCII value
    }
    return hash_val % HASH_TABLE_SIZE; // Ensure the hash value is within table bounds
}

// Function to insert an IP address into the hash table
// Returns 1 if the IP was new, 0 if it already existed
int insert_ip(const char *ip) {
    unsigned int index = hash(ip);
    Node *current = hash_table[index];

    // Traverse the linked list at this hash index
    while (current != NULL) {
        if (strcmp(current->ip_address, ip) == 0) {
            // IP address already exists in the table
            return 0;
        }
        current = current->next;
    }

    // IP address is new, so add it to the beginning of the list
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Memory allocation failed for new node");
        exit(EXIT_FAILURE);
    }
    strncpy(new_node->ip_address, ip, MAX_IP_LEN - 1);
    new_node->ip_address[MAX_IP_LEN - 1] = '\0'; // Ensure null-termination
    new_node->next = hash_table[index]; // Point to the current head of the list
    hash_table[index] = new_node;      // Make new_node the new head

    return 1; // IP address was successfully added (it was new)
}

// Function to free all memory allocated for the hash table
void free_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        Node *current = hash_table[i];
        while (current != NULL) {
            Node *temp = current;
            current = current->next;
            free(temp); // Free each node in the linked list
        }
    }
}

int main() {
    FILE *log_file;
    char line[256]; // Buffer to read each line from the log file
    char ip_buffer[MAX_IP_LEN]; // Buffer to store the extracted IP address
    int unique_visitors = 0;

    // Initialize the hash table
    init_hash_table();

    // Open the log file in read mode
    log_file = fopen("server.log", "r");
    if (log_file == NULL) {
        perror("Error opening log file");
        return EXIT_FAILURE;
