        int i = 0;
        while (i < MAX_IP_LEN - 1 && line[i] != '\0' && line[i] != ' ' && line[i] != '\t') {
            ip_buffer[i] = line[i];
            i++;
        }
        ip_buffer[i] = '\0'; // Null-terminate the extracted IP address

        // Basic validation: Check if ip_buffer contains something and isn't just a newline
        if (strlen(ip_buffer) > 0) {
            if (insert_ip(ip_buffer)) {
