#include <string.h>

#define MAX_IP_LENGTH 16
#define MAX_LOG_LINES 10000

typedef struct {
    char ip[MAX_IP_LENGTH];
} Visitor;

// Function to read the log file and extract IP addresses
int readLogFile(FILE *file, Visitor visitors[], int *uniqueCount) {
    char line[1024];
    char *token;
    int count = 0;
    int size = 1000;

    while (fgets(line, sizeof(line), file)) {
        // Extract the IP address from the log line
        token = strtok(line, " ");
        if (token == NULL) continue;

        // Check if the IP is already in the list of visitors
        int isUnique = 1;
        for (int i = 0; i < count; i++) {
            if (strcmp(token, visitors[i].ip) == 0) {
                isUnique = 0;
                break;
            }
        }

        // If the IP is unique, add it to the list
        if (isUnique) {
            if (count >= size) {
                size += 1000;
                visitors = realloc(visitors, size * sizeof(Visitor));
                if (visitors == NULL) {
                    fprintf(stderr, "Memory allocation failed\n");
                    return -1;
                }
            }
            strcpy(visitors[count].ip, token);
            count++;
        }
    }

    *uniqueCount = count;
    return 0;
}

int main() {
    FILE *logFile;
    Visitor *visitors = malloc(1000 * sizeof(Visitor));
    int uniqueCount = 0;

    logFile = fopen("server.log", "r");
    if (logFile == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Read the log file and identify unique visitors
    if (readLogFile(logFile, visitors, &uniqueCount) != 0) {
        fclose(logFile);
        free(visitors);
        return EXIT_FAILURE;
    }

    fclose(logFile);

    // Print the number of unique visitors
    printf("Number of unique visitors: %d\n", uniqueCount);

    // Print the list of unique IP addresses
    for (int i = 0; i < uniqueCount; i++) {
        printf("%s\n", visitors[i].ip);
    }

    free(visitors);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <math.h>

// Function to draw the fractal tree
void drawFractalTree(int depth, int length, int x, int y, double angle) {
    // Base case: stop recursion when depth reaches 0
    if (depth == 0) return;

    // Calculate new endpoint coordinates using trigonometry
    int newX = x + (int)(length * cos(angle));
    int newY = y - (int)(length * sin(angle));

    // Create 2D character array to represent the tree
    char canvas[50][80] = {0};

    // Draw line between current point and new point
    int x1 = x, y1 = y;
    int x2 = newX, y2 = newY;

    // Bresenham's line drawing algorithm
    int dx = abs(x2 - x1);
    int dy = abs(y2 - y1);
    int sx = (x1 < x2) ? 1 : -1;
    int sy = (y1 < y2) ? 1 : -1;
    int err = dx - dy;

    while (1) {
        canvas[y1][x1] = '*';

        if (x1 == x2 && y1 == y2) break;

        int e2 = 2 * err;
        if (e2 > -dy) {
            err -= dy;
            x1 += sx;
        }
        if (e2 < dx) {
            err += dx;
            y1 += sy;
        }
    }

    // Recursively draw left and right branches
    drawFractalTree(depth - 1, length * 0.7, newX, newY, angle + M_PI / 6);
    drawFractalTree(depth - 1, length * 0.7, newX, newY, angle - M_PI / 6);

    // Print the canvas
    for (int i = 0; i < 50; i++) {
        for (int j = 0; j < 80; j++) {
            printf("%c", canvas[i][j] ? canvas[i][j] : ' ');
        }
        printf("\n");
    }
}

