void draw_tree(int x, int y, double angle, int length, int depth) {
    if (depth <= 0) return;

    // Calculate end point of the branch
    int x2 = x + (int)(length * cos(angle * M_PI / 180.0));
    int y2 = y + (int)(length * sin(angle * M_PI / 180.0));

    // Draw the branch
    // Simple ASCII representation - we'll just print the coordinates
    printf("Branch from (%d,%d) to (%d,%d) at depth %d\n", x, y, x2, y2, depth);

