#define BRANCH_DECAY 0.7       // How much smaller subsequent branches are
#define BRANCH_ANGLE 25.0      // Angle in degrees for new branches
#define MIN_BRANCH_LENGTH 1.0  // Stop drawing branches smaller than this

char canvas[HEIGHT][WIDTH + 1]; // +1 for null terminator

// Function to initialize the canvas
void init_canvas() {
    for (int i = 0; i < HEIGHT; i++) {
        for (int j = 0; j < WIDTH; j++) {
            canvas[i][j] = ' ';
        }
        canvas[i][WIDTH] = '\0'; // Null-terminate each row
    }
}

// Function to draw a point on the canvas
void draw_point(int x, int y, char c) {
    if (x >= 0 && x < WIDTH && y >= 0 && y < HEIGHT) {
        // We draw from top-left (0,0) to bottom-right (WIDTH-1, HEIGHT-1)
        // Tree usually grows upwards, so flip y for display
        canvas[HEIGHT - 1 - y][x] = c;
    }
}

// Function to draw a line using Bresenham's line algorithm
// Optimized version for ASCII characters
void draw_line(int x0, int y0, int x1, int y1, char c) {
    int dx = abs(x1 - x0);
    int sx = x0 < x1 ? 1 : -1;
    int dy = abs(y1 - y0);
    int sy = y0 < y1 ? 1 : -1;
    int err = (dx > dy ? dx : -dy) / 2;
    int e2;

    while (1) {
        draw_point(x0, y0, c);
        if (x0 == x1 && y0 == y1) break;
        e2 = err;
        if (e2 > -dx) {
            err -= dy;
            x0 += sx;
        }
        if (e2 < dy) {
            err += dx;
            y0 += sy;
        }
    }
}

// Recursive function to draw the fractal tree branches
// x, y: current position
// length: length of the current branch
// angle: angle of the current branch relative to the x-axis (in radians)
// depth: current recursion depth
// max_depth: desired maximum recursion depth
void draw_branch(double x, double y, double length, double angle, int depth, int max_depth) {
    if (depth > max_depth || length < MIN_BRANCH_LENGTH) { // Base case: stop recursion
        return;
    }

    // Calculate end point of the current branch
    double x_end = x + length * cos(angle);
    double y_end = y + length * sin(angle);

    // Draw the current branch
    draw_line((int)round(x), (int)round(y), (int)round(x_end), (int)round(y_end), '#');

    // Recursively draw two new branches
    // Left branch (decreased angle)
    draw_branch(x_end, y_end, length * BRANCH_DECAY, angle + (BRANCH_ANGLE * M_PI / 180.0), depth + 1, max_depth);
    // Right branch (increased angle)
    draw_branch(x_end, y_end, length * BRANCH_DECAY, angle - (BRANCH_ANGLE * M_PI / 180.0), depth + 1, max_depth);
}

// Function to print the canvas
void print_canvas() {
    for (int i = 0; i < HEIGHT; i++) {
        printf("%s\n", canvas[i]);
    }
}

int main(int argc, char *argv[]) {
    int depth = 5; // Default recursion depth

    if (argc > 1) {
        int input_depth = atoi(argv[1]);
        if (input_depth >= 0) { // Ensure depth is not negative
            depth = input_depth;
        } else {
            fprintf(stderr, "Warning: Invalid depth provided. Using default depth of %d.\n", depth);
        }
    }

    init_canvas();

    // Start drawing the tree from the bottom middle of the canvas
    // Initial branch points upwards (angle = 90 degrees or PI/2 radians)
    // The canvas Y-axis goes from bottom-left to top-right visually.
    // So, an initial Y of 0 means the bottom of the canvas.
    draw_branch(WIDTH / 2.0, 0.0, TRUNK_LENGTH, M_PI / 2.0, 0, depth);

    print_canvas();

    return 0;
}

