void draw_tree(int x, int y, int len, double angle, int depth) {
    if (depth == 0 || len < 1) return;
    int dx = (int)(len * -angle); // No true angle, so -1 (up), -0.5 (left up), 0.5 (right up)
    int dy = -len;                // Always up
    int nx = x, ny = y;
    for (int i = 0; i < len; ++i) {
        ny += -1;
        if (x > 0 && x < WIDTH && ny > 0 && ny < HEIGHT)
            canvas[ny][x] = '|'; // Draw trunk segment up
    }
    // Left branch
    int lx = x - len/2, ly = y - len;
    for (int i = 0; i < len/2; ++i) {
        lx -= 1;
        ly -= 1;
        if (lx > 0 && lx < WIDTH && ly > 0 && ly < HEIGHT)
            canvas[ly][lx] = '/';
    }
    // Right branch
    int rx = x + len/2, ry = y - len;
    for (int i = 0; i < len/2; ++i) {
        rx += 1;
        ry -= 1;
        if (rx > 0 && rx < WIDTH && ry > 0 && ry < HEIGHT)
            canvas[ry][rx] = '\\';
    }
    // Recurse for left & right branches
    draw_tree(x - len/2 - (len/2), y - len - (len/2), len/2, angle, depth-1);
    draw_tree(x + len/2 + (len/2), y - len - (len/2), len/2, angle, depth-1);
}

