// Rotate right macro
#define ROTR(x, n) (((x) >> (n)) | ((x) << (32 - (n))))

// SHA256 core functions
#define Ch(x, y, z) (((x) & (y)) ^ (~(x) & (z)))
#define Maj(x, y, z) (((x) & (y)) ^ ((x) & (z)) ^ ((y) & (z)))
#define Sigma0(x) (ROTR(x, 2) ^ ROTR(x, 13) ^ ROTR(x, 22))
#define Sigma1(x) (ROTR(x, 6) ^ ROTR(x, 11) ^ ROTR(x, 25))
#define sigma0(x) (ROTR(x, 7) ^ ROTR(x, 18) ^ ((x) >> 3))
#define sigma1(x) (ROTR(x, 17) ^ ROTR(x, 19) ^ ((x) >> 10))

// SHA256 initial hash values
static const uint32_t H0[8] = {
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 
    0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19
};

// SHA256 transform function
void sha256_transform(uint32_t* state, const uint8_t* block) {
    uint32_t a, b, c, d, e, f, g, h;
    uint32_t W[64];

    // Convert block to words
    for (int i = 0; i < 16; i++) {
        W[i] = (block[i*4] << 24) | (block[i*4+1] << 16) | 
               (block[i*4+2] << 8) | (block[i*4+3]);
    }

    // Extend the message schedule
    for (int i = 16; i < 64; i++) {
        W[i] = sigma1(W[i-2]) + W[i-7] + sigma0(W[i-15]) + W[i-16];
    }

    // Initialize working variables
    a = state[0]; b = state[1]; c = state[2]; d = state[3];
    e = state[4]; f = state[5]; g = state[6]; h = state[7];

    // Main compression loop
    for (int i = 0; i < 64; i++) {
        uint32_t T1 = h + Sigma1(e) + Ch(e, f, g) + K[i] + W[i];
        uint32_t T2 = Sigma0(a) + Maj(a, b, c);
        h = g; g = f; f = e; e = d + T1;
        d = c; c = b; b = a; a = T1 + T2;
    }

    // Update state
    state[0] += a; state[1] += b; state[2] += c; state[3] += d;
    state[4] += e; state[5] += f; state[6] += g; state[7] += h;
}

// SHA256 hash function
void sha256_hash(const uint8_t* data, size_t len, uint8_t* hash) {
    uint32_t state[8];
    memcpy(state, H0, sizeof(H0));

    // Preprocessing
    uint64_t total_bits = len * 8;
    uint8_t block[64];
    size_t block_len = 0;

    for (size_t i = 0; i < len; i++) {
        block[block_len++] = data[i];

        if (block_len == 64) {
            sha256_transform(state, block);
            block_len = 0;
        }
    }

    // Padding
    block[block_len++] = 0x80;
    if (block_len > 56) {
        memset(&block[block_len], 0, 64 - block_len);
        sha256_transform(state, block);
        memset(block, 0, 56);
    } else {
        memset(&block[block_len], 0, 56 - block_len);
    }

    // Append length
    for (int i = 0; i < 8; i++) {
        block[56 + i] = (total_bits >> (56 - i * 8)) & 0xFF;
    }
    sha256_transform(state, block);

    // Convert state to hash bytes
    for (int i = 0; i < 8; i++) {
        hash[i*4]   = (state[i] >> 24) & 0xFF;
        hash[i*4+1] = (state[i] >> 16) & 0xFF;
        hash[i*4+2] = (state[i] >> 8) & 0xFF;
        hash[i*4+3] = state[i] & 0xFF;
    }
}

// HMAC implementation
void hmac_sha256(const uint8_t* key, size_t key_len, 
                 const uint8_t* data, size_t data_len, 
                 uint8_t* hmac) {
    // Block size for SHA256
    const int BLOCK_SIZE = 64;

    // Temporary key and buffers
    uint8_t k_ipad[BLOCK_SIZE];
    uint8_t k_opad[BLOCK_SIZE];
    uint8_t temp_key[32];
    uint8_t inner_hash[32];

    // If key is longer than block size, hash it first
    if (key_len > BLOCK_SIZE) {
        sha256_hash(key, key_len, temp_key);
        key = temp_key;
        key_len = 32;
    }

    // Zero pad the key if it's shorter
    memset(k_ipad, 0, BLOCK_SIZE);
    memset(k_opad, 0, BLOCK_SIZE);
    memcpy(k_ipad, key, key_len);
    memcpy(k_opad, key, key_len);

    // XOR key with ipad and opad
    for (int i = 0; i < BLOCK_SIZE; i++) {
        k_ipad[i] ^= 0x36;
        k_opad[i] ^= 0x5c;
    }

    // Inner hash
    uint8_t inner_data[BLOCK_SIZE + 32];
    memcpy(inner_data, k_ipad, BLOCK_SIZE);
    memcpy(inner_data + BLOCK_SIZE, data, data_len);
    sha256_hash(inner_data, BLOCK_SIZE + data_len, inner_hash);

    // Outer hash
    uint8_t outer_data[BLOCK_SIZE + 32];
    memcpy(outer_data, k_opad, BLOCK_SIZE);
    memcpy(outer_data + BLOCK_SIZE, inner_hash, 32);
    sha256_hash(outer_data, BLOCK_SIZE + 32, hmac);
}

