        memcpy(k_prepared, key, key_len);
        memset(k_prepared + key_len, 0, SHA256_BLOCK_SIZE - key_len);
    }

    // 2. Compute ipad and opad
    uint8_t k_ipad[SHA256_BLOCK_SIZE]; // K' XOR ipad
    uint8_t k_opad[SHA256_BLOCK_SIZE]; // K' XOR opad

    for (size_t i = 0; i < SHA256_BLOCK_SIZE; i++) {
        k_ipad[i] = k_prepared[i] ^ 0x36;
        k_opad[i] = k_prepared[i] ^ 0x5c;
    }

    uint8_t inner_hash[SHA256_DIGEST_SIZE];

    // 3. Inner hash: H( (K' XOR ipad) || M )
    sha256_init(&ctx);
    sha256_update(&ctx, k_ipad, SHA256_BLOCK_SIZE);
    sha256_update(&ctx, data, data_len);
    sha256_final(&ctx, inner_hash);

    // 4. Outer hash: H( (K' XOR opad) || inner_hash )
    sha256_init(&ctx);
    sha256_update(&ctx, k_opad, SHA256_BLOCK_SIZE);
    sha256_update(&ctx, inner_hash, SHA256_DIGEST_SIZE);
    sha256_final(&ctx, hmac_output);

    return 0;
}

