#define SHA256_DIGEST_SIZE 32

void hmac_sha256(const uint8_t *key, size_t key_len,
                 const uint8_t *data, size_t data_len,
                 uint8_t *out_mac /* must be at least 32 bytes */)
{
    uint8_t kopad[SHA256_BLOCK_SIZE]; // padded key
    uint8_t kipad[SHA256_BLOCK_SIZE];
    uint8_t tk[SHA256_DIGEST_SIZE];
    size_t i;

    // Step 1: If key is longer than block size, hash it down
    if (key_len > SHA256_BLOCK_SIZE) {
        SHA256_CTX tctx;
        SHA256_Init(&tctx);
        SHA256_Update(&tctx, key, key_len);
        SHA256_Final(tk, &tctx);

        key = tk;
        key_len = SHA256_DIGEST_SIZE;
    }

    // Step 2: Pad key to block size with zeros
    memset(kopad, 0, SHA256_BLOCK_SIZE);
    memcpy(kopad, key, key_len);
    memcpy(kipad, kopad, SHA256_BLOCK_SIZE);

    // Step 3: XOR with ipad and opad values
    for (i = 0; i < SHA256_BLOCK_SIZE; i++) {
        kipad[i] ^= 0x36;
        kopad[i] ^= 0x5c;
    }

    // Step 4: Inner hash
    SHA256_CTX ctx;
    uint8_t innerhash[SHA256_DIGEST_SIZE];

    SHA256_Init(&ctx);
    SHA256_Update(&ctx, kipad, SHA256_BLOCK_SIZE);
    SHA256_Update(&ctx, data, data_len);
    SHA256_Final(innerhash, &ctx);

    // Step 5: Outer hash
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, kopad, SHA256_BLOCK_SIZE);
    SHA256_Update(&ctx, innerhash, SHA256_DIGEST_SIZE);
    SHA256_Final(out_mac, &ctx);
}

