void hmac_sha256(const uint8_t *key, size_t key_len,
                 const uint8_t *data, size_t data_len,
                 uint8_t *out) {
    uint8_t key_block[SHA256_BLOCK_SIZE] = {0};
    uint8_t o_key_pad[SHA256_BLOCK_SIZE];
    uint8_t i_key_pad[SHA256_BLOCK_SIZE];
    uint8_t temp_hash[SHA256_DIGEST_SIZE];

    // Step 1: Prepare key
    if (key_len > SHA256_BLOCK_SIZE) {
        // Hash key if longer than block size
        sha256(key, key_len, key_block);
    } else {
        // Otherwise, pad it with zeros
        memcpy(key_block, key, key_len);
    }

    // Step 2: Prepare inner and outer pads
    for (int i = 0; i < SHA256_BLOCK_SIZE; i++) {
        o_key_pad[i] = key_block[i] ^ 0x5c;
        i_key_pad[i] = key_block[i] ^ 0x36;
    }

    // Step 3: Inner hash
    // Inner hash is SHA256(i_key_pad || data)
    uint8_t inner_data[SHA256_BLOCK_SIZE + data_len];
    memcpy(inner_data, i_key_pad, SHA256_BLOCK_SIZE);
    memcpy(inner_data + SHA256_BLOCK_SIZE, data, data_len);
    sha256(inner_data, SHA256_BLOCK_SIZE + data_len, temp_hash);

    // Step 4: Outer hash
    // Outer hash is SHA256(o_key_pad || inner_hash)
    uint8_t outer_data[SHA256_BLOCK_SIZE + SHA256_DIGEST_SIZE];
    memcpy(outer_data, o_key_pad, SHA256_BLOCK_SIZE);
    memcpy(outer_data + SHA256_BLOCK_SIZE, temp_hash, SHA256_DIGEST_SIZE);
    sha256(outer_data, SHA256_BLOCK_SIZE + SHA256_DIGEST_SIZE, out);
}

