// Initialize SHA256 state
void sha256_init(uint32_t* state) {
    // SHA256 initial hash values
    state[0] = 0x6a09e667;
    state[1] = 0xbb67ae85;
    state[2] = 0x3c6ef372;
    state[3] = 0xa54ff53a;
    state[4] = 0x510e527f;
    state[5] = 0x9b05688c;
    state[6] = 0x1f83d9ab;
    state[7] = 0x5be0cd19;
}

// Update SHA256 state with new data
void sha256_update(uint32_t* state, const uint8_t* data, size_t size) {
    int block_size = SHA256_BLOCK_SIZE;
    uint8_t block[block_size];
    size_t block_offset = 0;

    // Process input data in blocks
    while (size >= block_size) {
        // Read a block from the input data
        memcpy(block, data, block_size);
        // Compress the block using the SHA256 compression function
        sha256_compress(state, block);

        // Move to the next block
        data += block_size;
        size -= block_size;
    }

    // Store any remaining data in the block
    memcpy(block, data, size);
    // Pad the block
    block[size] = 0x80; // Append a '1' bit

    // Pad with zeros and append the message length in bits
    int padding_size = block_size - size - 1;
    memset(block + size + 1, 0, padding_size);
    uint64_t message_length = (uint64_t)size * 8;
    memcpy(block + block_size - 8, &message_length, 8);

    // Compress the padded block using the SHA256 compression function
    sha256_compress(state, block);
}

// Finalize SHA256 state and generate digest
void sha256_final(uint32_t* state, uint8_t* digest) {
    // Output the SHA256 digest
    for (int i = 0; i < HMAC_DIGEST_SIZE; i += 4) {
        uint32_t* val = &state[i / 4];
        digest[i] = (*val) & 0xFF;
        digest[i + 1] = ((*val) >> 8) & 0xFF;
        digest[i + 2] = ((*val) >> 16) & 0xFF;
        digest[i + 3] = ((*val) >> 24) & 0xFF;
    }
}

// Calculate SHA256 hash
void sha256_hash(const uint8_t* data, size_t size, uint8_t* digest) {
    uint32_t state[8];
    sha256_init(state);
    sha256_update(state, data, size);
    sha256_final(state, digest);
}

// Initialize HMAC state
void hmac_sha256_init(const uint8_t* key, size_t key_size, uint32_t* state) {
    // Pad the key to HMAC_KEY_SIZE bytes (512 bits) with zeros
    uint8_t padded_key[HMAC_KEY_SIZE];
    memset(padded_key, 0, HMAC_KEY_SIZE);
    memcpy(padded_key, key, key_size);

    // XOR the key with the outer padding constant and the inner padding constant
    for (int i = 0; i < HMAC_BLOCK_SIZE; i++) {
        uint8_t outer_padding = 0x6c;
        uint8_t inner_padding = 0x36;
        padded_key[i] ^= outer_padding;
    }

    // Initialize the HMAC state with the padded key
    sha256_init(state);
    sha256_update(state, padded_key, HMAC_BLOCK_SIZE);
}

// Update HMAC state with new data
void hmac_sha256_update(uint32_t* state, const uint8_t* data, size_t size) {
    // Update the HMAC state with the input data
    sha256_update(state, data, size);
}

// Finalize HMAC state and generate digest
void hmac_sha256_final(uint32_t* state, uint8_t* digest) {
    uint8_t inner_block[HMAC_BLOCK_SIZE];
    for (int i = 0; i < HMAC_BLOCK_SIZE; i++) {
        uint8_t inner_padding = 0x36;
        inner_block[i] = inner_padding;
    }

    // Finalize the HMAC state with the inner padding
    sha256_final(state, digest);

    // Initialize the HMAC state for the outer padding
    uint32_t outer_state[8];
    uint8_t outer_block[HMAC_BLOCK_SIZE];
    for (int i = 0; i < HMAC_BLOCK_SIZE; i++) {
        uint8_t outer_padding = 0x6c;
        outer_block[i] = outer_padding;
    }

    // Update the HMAC state with the outer padding
    sha256_init(outer_state);
    sha256_update(outer_state, outer_block, HMAC_BLOCK_SIZE);
    sha256_update(outer_state, digest, HMAC_DIGEST_SIZE);
    sha256_final(outer_state, digest);
}

// Calculate HMAC-SHA256
void hmac_sha256(const uint8_t* key, size_t key_size, const uint8_t* data, size_t data_size, uint8_t* digest) {
    uint32_t state[8];
    hmac_sha256_init(key, key_size, state);
    hmac_sha256_update(state, data, data_size);
    hmac_sha256_final(state, digest);
}

// Left-rotate a 32-bit integer
void left_rotate(uint32_t* x, int bits) {
    *x = (*x << bits) | (*x >> (32 - bits));
}

// SHA256 compression function
void sha256_compress(uint32_t* state, const uint8_t* block) {
    uint32_t w[64];
    for (int i = 0; i < 16; i++) {
        w[i] = ((uint32_t*)block)[i];
    }
    for (int i = 16; i < 64; i++) {
        uint32_t s0 = w[i - 15];
        uint32_t s1 = w[i - 2];
        s0 = (s0 >> 7 | s0 << 25) ^ (s0 >> 18 | s0 << 14) ^ (s0 >> 3);
        s1 = (s1 >> 17 | s1 << 15) ^ (s1 >> 19 | s1 << 13) ^ (s1 >> 10);
        w[i] = w[i - 16] + s0 + w[i - 7] + s1;
    }

    uint32_t a = state[0];
    uint32_t b = state[1];
    uint32_t c = state[2];
    uint32_t d = state[3];
    uint32_t e = state[4];
    uint32_t f = state[5];
    uint32_t g = state[6];
    uint32_t h = state[7];

    for (int i = 0; i < 64; i++) {
        uint32_t S1 = (e >> 6 | e << 26) ^ (e >> 11 | e << 21) ^ (e >> 25 | e << 7);
        uint32_t ch = (e & f) ^ ((~e) & g);
        uint32_t temp1 = h + S1 + ch + 0x428a2f98 + w[i];
        uint32_t S0 = (a >> 2 | a << 30) ^ (a >> 13 | a << 19) ^ (a >> 22);
        uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
        uint32_t temp2 = S0 + maj;

        h = g;
        g = f;
        f = e;
        e = d + temp1;
        d = c;
        c = b;
        b = a;
        a = temp1 + temp2;
    }

    state[0] += a;
    state[1] += b;
    state[2] += c;
    state[3] += d;
    state[4] += e;
    state[5] += f;
    state[6] += g;
    state[7] += h;
}

