    uint32_t a = hash[0], b = hash[1], c = hash[2], d = hash[3], e = hash[4], f = hash[5], g = hash[6], h = hash[7];

    for (int t = 0; t < 64; t++) {
        uint32_t T1 = h + rightrotate(e, 6) ^ rightrotate(e, 11) ^ rightrotate(e, 25) + (e & f ^ ~e & g) + K[t] + w[t];
        uint32_t T2 = rightrotate(a, 2) ^ rightrotate(a, 13) ^ rightrotate(a, 22) + (a & b ^ a & c ^ b & c);
        h = g;
        g = f;
        f = e;
        e = d + T1;
        d = c;
        c = b;
        b = a;
        a = T1 + T2;
    }

    hash[0] += a;
    hash[1] += b;
    hash[2] += c;
    hash[3] += d;
    hash[4] += e;
    hash[5] += f;
    hash[6] += g;
    hash[7] += h;
}

void sha256(const uint8_t *data, size_t len, uint8_t *digest) {
    uint8_t buffer[64];
    uint32_t hash[8] = {H[0], H[1], H[2], H[3], H[4], H[5], H[6], H[7]};
    size_t total = 0;

    while (total < len) {
        size_t size = len - total;
        if (size > 64) size = 64;
        memcpy(buffer, data + total, size);
        total += size;
        if (size < 64) break;
        sha256_block(buffer, hash);
    }

    size_t padlen = 120 - (total % 64);
    if (padlen < 56) padlen += 64;

    buffer[0] = 0x80;
    memset(buffer + 1, 0, padlen - 1);
    uint64_t bits = len * 8;
    buffer[padlen - 8] = (bits >> 56) & 0xff;
    buffer[padlen - 7] = (bits >> 48) & 0xff;
    buffer[padlen - 6] = (bits >> 40) & 0xff;
    buffer[padlen - 5] = (bits >> 32) & 0xff;
    buffer[padlen - 4] = (bits >> 24) & 0xff;
    buffer[padlen - 3] = (bits >> 16) & 0xff;
    buffer[padlen - 2] = (bits >> 8) & 0xff;
    buffer[padlen - 1] = bits & 0xff;

    size_t i = 0;
    while (i < padlen) {
        size_t chunk = padlen - i;
        if (chunk > 64) chunk = 64;
        memcpy(buffer, buffer + i, chunk);
        sha256_block(buffer, hash);
        i += chunk;
    }

    for (int i = 0; i < 8; i++) {
        digest[i * 4] = (hash[i] >> 24) & 0xff;
        digest[i * 4 + 1] = (hash[i] >> 16) & 0xff;
        digest[i * 4 + 2] = (hash[i] >> 8) & 0xff;
        digest[i * 4 + 3] = hash[i] & 0xff;
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define BOARD_SIZE 8

// Piece representations
enum Piece {
    EMPTY = 0,
    WHITE_PAWN = 1,
    WHITE_ROOK = 2,
    WHITE_KNIGHT = 3,
    WHITE_BISHOP = 4,
    WHITE_QUEEN = 5,
    WHITE_KING = 6,
    BLACK_PAWN = -1,
    BLACK_ROOK = -2,
    BLACK_KNIGHT = -3,
    BLACK_BISHOP = -4,
    BLACK_QUEEN = -5,
    BLACK_KING = -6
};

// Board representation
int board[BOARD_SIZE][BOARD_SIZE];

// Initialize the chess board
void initBoard() {
    // Clear the board
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            board[i][j] = EMPTY;
        }
    }

    // Set up white pieces
    board[7][0] = WHITE_ROOK;
    board[7][1] = WHITE_KNIGHT;
    board[7][2] = WHITE_BISHOP;
    board[7][3] = WHITE_QUEEN;
    board[7][4] = WHITE_KING;
    board[7][5] = WHITE_BISHOP;
    board[7][6] = WHITE_KNIGHT;
    board[7][7] = WHITE_ROOK;

    for (int j = 0; j < BOARD_SIZE; j++) {
        board[6][j] = WHITE_PAWN;
    }

    // Set up black pieces
    board[0][0] = BLACK_ROOK;
    board[0][1] = BLACK_KNIGHT;
    board[0][2] = BLACK_BISHOP;
    board[0][3] = BLACK_QUEEN;
    board[0][4] = BLACK_KING;
    board[0][5] = BLACK_BISHOP;
    board[0][6] = BLACK_KNIGHT;
    board[0][7] = BLACK_ROOK;

    for (int j = 0; j < BOARD_SIZE; j++) {
        board[1][j] = BLACK_PAWN;
    }
}

// Print the chess board
void printBoard() {
    printf("  a b c d e f g h\n");
    for (int i = 0; i < BOARD_SIZE; i++) {
        printf("%d ", 8 - i);
        for (int j = 0; j < BOARD_SIZE; j++) {
            char piece = ' ';
            switch(board[i][j]) {
                case WHITE_PAWN: piece = 'P'; break;
                case WHITE_ROOK: piece = 'R'; break;
                case WHITE_KNIGHT: piece = 'N'; break;
                case WHITE_BISHOP: piece = 'B'; break;
                case WHITE_QUEEN: piece = 'Q'; break;
                case WHITE_KING: piece = 'K'; break;
                case BLACK_PAWN: piece = 'p'; break;
                case BLACK_ROOK: piece = 'r'; break;
                case BLACK_KNIGHT: piece = 'n'; break;
                case BLACK_BISHOP: piece = 'b'; break;
                case BLACK_QUEEN: piece = 'q'; break;
                case BLACK_KING: piece = 'k'; break;
                default: piece = '.'; break;
            }
            printf("%c ", piece);
        }
        printf("%d\n", 8 - i);
    }
    printf("  a b c d e f g h\n");
}

// Convert algebraic notation to board indices
int convertColumn(char col) {
    return tolower(col) - 'a';
}

int convertRow(char row) {
    return 8 - (row - '0');
}

// Simple move validation (very basic)
int isValidMove(int fromRow, int fromCol, int toRow, int toCol) {
    int piece = board[fromRow][fromCol];
    int target = board[toRow][toCol];

    // Can't move to a square with your own piece
    if ((piece > 0 && target > 0) || (piece < 0 && target < 0)) {
        return 0;
    }

    // Basic pawn movement
    if (abs(piece) == 1) {
        int direction = (piece > 0) ? -1 : 1;
        if (fromCol == toCol && target == EMPTY) {
            if (toRow == fromRow + direction) return 1;
            // First move can be two squares
            if ((piece > 0 && fromRow == 6) || (piece < 0 && fromRow == 1)) {
                if (toRow == fromRow + 2 * direction && target == EMPTY) return 1;
            }
        }
        // Diagonal capture
        if (abs(fromCol - toCol) == 1 && toRow == fromRow + direction && target != EMPTY) {
            return 1;
        }
    }

    return 1; // Simplified for this basic version
}

// Perform move
void makeMove(int fromRow, int fromCol, int toRow, int toCol) {
    board[toRow][toCol] = board[fromRow][fromCol];
    board[fromRow][fromCol] = EMPTY;
}

// Simple AI move (just moves a random piece)
void aiMove() {
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[i][j] < 0) {  // Black pieces
                for (int toRow = 0; toRow < BOARD_SIZE; toRow++) {
                    for (int toCol = 0; toCol < BOARD_SIZE; toCol++) {
                        if (isValidMove(i, j, toRow, toCol)) {
                            makeMove(i, j, toRow, toCol);
                            return;
                        }
                    }
                }
            }
        }
    }
}

int main() {
    initBoard();

    while (1) {
        // Player's turn
        printBoard();

        char fromCol, toCol;
        int fromRow, toRow;

        printf("Enter your move (e.g., e2e4): ");
        scanf(" %c%d%c%d", &fromCol, &fromRow, &toCol, &toRow);

        // Convert to board indices
        fromRow = convertRow(fromRow + '0');
        toRow = convertRow(toRow + '0');
        fromCol = convertColumn(fromCol);
        toCol = convertColumn(toCol);

        // Validate and make move
        if (isValidMove(fromRow, fromCol, toRow, toCol)) {
            makeMove(fromRow, fromCol, toRow, toCol);
        } else {
            printf("Invalid move!\n");
            continue;
        }

        // AI's turn
        aiMove();
    }

    return 0;
}

#include <stdio.h>
