    BISHOP,
    QUEEN,
    KING
};

enum Color {
    WHITE,
    BLACK
};

struct Square {
    enum Piece piece;
    enum Color color;
};

struct Square board[BOARD_SIZE][BOARD_SIZE];

void initializeBoard() {
    // Initialize pawns
    for (int i = 0; i < BOARD_SIZE; ++i) {
        board[1][i].piece = PAWN;
        board[1][i].color = WHITE;
        board[6][i].piece = PAWN;
        board[6][i].color = BLACK;
    }

    // Initialize other pieces for white
    board[0][0].piece = ROOK; board[0][0].color = WHITE;
    board[0][1].piece = KNIGHT; board[0][1].color = WHITE;
    board[0][2].piece = BISHOP; board[0][2].color = WHITE;
    board[0][3].piece = QUEEN; board[0][3].color = WHITE;
    board[0][4].piece = KING; board[0][4].color = WHITE;
    board[0][5].piece = BISHOP; board[0][5].color = WHITE;
    board[0][6].piece = KNIGHT; board[0][6].color = WHITE;
    board[0][7].piece = ROOK; board[0][7].color = WHITE;

    // Initialize other pieces for black
    board[7][0].piece = ROOK; board[7][0].color = BLACK;
    board[7][1].piece = KNIGHT; board[7][1].color = BLACK;
    board[7][2].piece = BISHOP; board[7][2].color = BLACK;
    board[7][3].piece = QUEEN; board[7][3].color = BLACK;
    board[7][4].piece = KING; board[7][4].color = BLACK;
    board[7][5].piece = BISHOP; board[7][5].color = BLACK;
    board[7][6].piece = KNIGHT; board[7][6].color = BLACK;
    board[7][7].piece = ROOK; board[7][7].color = BLACK;
}

void printBoard() {
    printf("  a b c d e f g h\n");
    for (int i = 0; i < BOARD_SIZE; ++i) {
        printf("%d ", i + 1);
        for (int j = 0; j < BOARD_SIZE; ++j) {
            if (board[i][j].piece == EMPTY) {
                printf(". ");
            } else {
                char piece = ' ';
                switch (board[i][j].piece) {
                    case PAWN: piece = 'P'; break;
                    case ROOK: piece = 'R'; break;
                    case KNIGHT: piece = 'N'; break;
                    case BISHOP: piece = 'B'; break;
                    case QUEEN: piece = 'Q'; break;
                    case KING: piece = 'K'; break;
                    default: break;
                }
                if (board[i][j].color == BLACK) {
                    piece = piece + 32; // Convert to lowercase for black pieces
                }
                printf("%c ", piece);
            }
        }
        printf("\n");
    }
}

bool isValidMove(int fromX, int fromY, int toX, int toY, enum Color color) {
    if (fromX < 0 || fromX >= BOARD_SIZE || fromY < 0 || fromY >= BOARD_SIZE ||
        toX < 0 || toX >= BOARD_SIZE || toY < 0 || toY >= BOARD_SIZE) {
        return false;
    }

    if (board[fromX][fromY].color != color) {
        return false;
    }

    if (board[toX][toY].color == color) {
        return false;
    }

    // Basic move validation (simplified)
    switch (board[fromX][fromY].piece) {
        case PAWN:
            if (color == WHITE) {
                if (fromX == 1 && toX == 3 && fromY == toY) return true;
                if (toX == fromX + 1 && fromY == toY && board[toX][toY].piece == EMPTY) return true;
                if (toX == fromX + 1 && abs(fromY - toY) == 1 && board[toX][toY].piece != EMPTY) return true;
            } else {
                if (fromX == 6 && toX == 4 && fromY == toY) return true;
                if (toX == fromX - 1 && fromY == toY && board[toX][toY].piece == EMPTY) return true;
                if (toX == fromX - 1 && abs(fromY - toY) == 1 && board[toX][toY].piece != EMPTY) return true;
            }
            break;
        case ROOK:
            if (fromX == toX || fromY == toY) return true;
            break;
        case KNIGHT:
            if ((abs(fromX - toX) == 2 && abs(fromY - toY) == 1) || (abs(fromX - toX) == 1 && abs(fromY - toY) == 2)) return true;
            break;
        case BISHOP:
            if (abs(fromX - toX) == abs(fromY - toY)) return true;
            break;
        case QUEEN:
            if (fromX == toX || fromY == toY || abs(fromX - toX) == abs(fromY - toY)) return true;
            break;
        case KING:
            if (abs(fromX - toX) <= 1 && abs(fromY - toY) <= 1) return true;
            break;
        default:
            return false;
    }
    return false;
}

void makeMove(int fromX, int fromY, int toX, int toY) {
    board[toX][toY] = board[fromX][fromY];
    board[fromX][fromY].piece = EMPTY;
}

void getRandomMove(int *fromX, int *fromY, int *toX, int *toY, enum Color color) {
    while (true) {
        *fromX = rand() % BOARD_SIZE;
        *fromY = rand() % BOARD_SIZE;
        *toX = rand() % BOARD_SIZE;
        *toY = rand() % BOARD_SIZE;
        if (isValidMove(*fromX, *fromY, *toX, *toY, color)) {
            break;
        }
    }
}

int main() {
    srand(time(NULL));
    initializeBoard();
    printBoard();

    enum Color currentPlayer = WHITE;

    while (true) {
        if (currentPlayer == WHITE) {
            int fromX, fromY, toX, toY;
            printf("Enter your move (e.g., '2 a 3 a'): ");
            scanf("%d %c %d %c", &fromX, &fromY, &toX, &toY);
            fromX -= 1;
            fromY -= 'a';
            toX -= 1;
            toY -= 'a';

            if (isValidMove(fromX, fromY, toX, toY, currentPlayer)) {
                makeMove(fromX, fromY, toX, toY);
                currentPlayer = BLACK;
            } else {
                printf("Invalid move. Try again.\n");
            }
        } else {
            int fromX, fromY, toX, toY;
            getRandomMove(&fromX, &fromY, &toX, &toY, currentPlayer);
            printf("Computer moves from %c%d to %c%d\n", 'a' + fromY, fromX + 1, 'a' + toY, toX + 1);
            makeMove(fromX, fromY, toX, toY);
            currentPlayer = WHITE;
        }

        printBoard();
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h> // For rand(), srand(), malloc(), realloc(), free()
#include <string.h> // For memcpy, strlen
#include <ctype.h>  // For tolower, toupper
#include <time.h>   // For time() to seed srand()

// --- Constants and Global Board ---
#define BOARD_SIZE 8

// Piece characters (capital = White, lowercase = Black)
#define WHITE_PAWN   'P'
#define WHITE_KNIGHT 'N'
#define WHITE_BISHOP 'B'
#define WHITE_ROOK   'R'
#define WHITE_QUEEN  'Q'
#define WHITE_KING   'K'

#define BLACK_PAWN   'p'
#define BLACK_KNIGHT 'n'
#define BLACK_BISHOP 'b'
#define BLACK_ROOK   'r'
#define BLACK_QUEEN  'q'
#define BLACK_KING   'k'

#define EMPTY_SQUARE ' '

// Player colors
#define WHITE_PLAYER 0
#define BLACK_PLAYER 1

char board[BOARD_SIZE][BOARD_SIZE];
int current_player = WHITE_PLAYER; // White starts

// Structure to hold a move
typedef struct {
    int r1, c1, r2, c2;
} Move;

// --- Helper Functions ---

// Get the color of a piece
int get_piece_color(char piece) {
    if (piece >= 'A' && piece <= 'Z') {
        return WHITE_PLAYER;
    } else if (piece >= 'a' && piece <= 'z') {
        return BLACK_PLAYER;
    }
    return -1; // Empty or invalid
}

// Check if a coordinate is within board bounds
int is_valid_coord(int r, int c) {
    return (r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE);
}

// Check if a square is empty on the current global board
int is_empty(int r, int c) {
    return board[r][c] == EMPTY_SQUARE;
}

// Check if a piece at a square belongs to given player_color
int is_own_piece(int r, int c, int player_color) {
    return get_piece_color(board[r][c]) == player_color;
}

// Check if a piece at a square belongs to the opponent of given player_color
int is_opponent_piece(int r, int c, int player_color) {
    return get_piece_color(board[r][c]) != -1 && get_piece_color(board[r][c]) != player_color;
}

// Function to make a move on a given target board (used for real moves and temporary checks)
void make_move_on_board(char target_board[BOARD_SIZE][BOARD_SIZE], int r1, int c1, int r2, int c2) {
    target_board[r2][c2] = target_board[r1][c1];
    target_board[r1][c1] = EMPTY_SQUARE;
}

// Function to find the current player's king's position on the global board
void find_king(int player_color, int* k_row, int* k_col) {
    char king_char = (player_color == WHITE_PLAYER) ? WHITE_KING : BLACK_KING;
    for (int r = 0; r < BOARD_SIZE; r++) {
        for (int c = 0; c < BOARD_SIZE; c++) {
            if (board[r][c] == king_char) {
                *k_row = r;
                *k_col = c;
                return;
            }
        }
    }
}

// Check if a square (r, c) is attacked by pieces of `attacker_color`
// This function operates on the current global 'board' state.
int is_square_attacked(int r, int c, int attacker_color) {
    int attacked = 0;

    // Pawn attacks
    if (attacker_color == WHITE_PLAYER) {
        if (is_valid_coord(r + 1, c - 1) && board[r + 1][c - 1] == WHITE_PAWN) { attacked = 1; goto cleanup_square_attacked; }
        if (is_valid_coord(r + 1, c + 1) && board[r + 1][c + 1] == WHITE_PAWN) { attacked = 1; goto cleanup_square_attacked; }
    } else { // BLACK_PLAYER
        if (is_valid_coord(r - 1, c - 1) && board[r - 1][c - 1] == BLACK_PAWN) { attacked = 1; goto cleanup_square_attacked; }
        if (is_valid_coord(r - 1, c + 1) && board[r - 1][c + 1] == BLACK_PAWN) { attacked = 1; goto cleanup_square_attacked; }
    }

    // Knight attacks
    int kr[] = {-2, -2, -1, -1, 1, 1, 2, 2};
    int kc[] = {-1, 1, -2, 2, -2, 2, -1, 1};
    for (int i = 0; i < 8; i++) {
        int nr = r + kr[i];
        int nc = c + kc[i];
        if (is_valid_coord(nr, nc) && get_piece_color(board[nr][nc]) == attacker_color) {
            char piece = toupper(board[nr][nc]);
            if (piece == WHITE_KNIGHT) {
                attacked = 1; goto cleanup_square_attacked;
            }
        }
    }

    // Sliding pieces (Rook, Bishop, Queen) and King attacks
    int dr[] = {-1, -1, -1, 0, 0, 1, 1, 1}; // All 8 directions
    int dc[] = {-1, 0, 1, -1, 1, -1, 0, 1}; // All 8 directions

    for (int i = 0; i < 8; i++) {
        int nr = r + dr[i]; // First step in this direction
        int nc = c + dc[i];

        // Check for King 1 step away first (King can only attack adjacent squares)
        if (is_valid_coord(nr, nc) && get_piece_color(board[nr][nc]) == attacker_color && toupper(board[nr][nc]) == WHITE_KING) {
            attacked = 1; goto cleanup_square_attacked;
        }

        // Now check for sliding pieces along the path
        int curr_r = nr; // Start checking from 1 step away
        int curr_c = nc;
        while (is_valid_coord(curr_r, curr_c)) {
            char piece_at_curr = board[curr_r][curr_c];
            if (!is_empty(curr_r, curr_c)) {
                if (get_piece_color(piece_at_curr) == attacker_color) {
                    char abs_piece = toupper(piece_at_curr);
                    // Check if it's a sliding piece that can attack in this direction
                    if (abs_piece == WHITE_QUEEN) { attacked = 1; goto cleanup_square_attacked; }
                    if ((dr[i] == 0 || dc[i] == 0) && abs_piece == WHITE_ROOK) { // Horizontal or vertical
                        attacked = 1; goto cleanup_square_attacked;
                    }
                    if ((abs(dr[i]) == abs(dc[i])) && abs_piece == WHITE_BISHOP) { // Diagonal
                        attacked = 1; goto cleanup_square_attacked;
                    }
                }
                break; // Path blocked regardless of ownership
            }
            curr_r += dr[i];
            curr_c += dc[i];
        }
    }

cleanup_square_attacked:
    return attacked;
}


// Check if the current player's king is in check
int is_king_in_check(int player_color) {
    int k_row, k_col;
    find_king(player_color, &k_row, &k_col);
    int opponent_color = (player_color == WHITE_PLAYER) ? BLACK_PLAYER : WHITE_PLAYER;
    return is_square_attacked(k_row, k_col, opponent_color);
}

// --- Piece Movement Validation Helpers ---

int is_pawn_move(int r1, int c1, int r2, int c2, int player_color) {
    int dr = r2 - r1;
    int dc = abs(c2 - c1);

    if (player_color == WHITE_PLAYER) { // White pawns move "up" (decreasing row index)
        if (dr == -1) { // 1 square forward
            if (dc == 0 && is_empty(r2, c2)) return 1; // Move straight
            if (dc == 1 && is_opponent_piece(r2, c2, player_color)) return 1; // Capture diagonally
        } else if (dr == -2 && r1 == 6) { // 2 squares forward from starting row
            if (dc == 0 && is_empty(r2, c2) && is_empty(r1 - 1, c1)) return 1; // Move straight and path clear
        }
    } else { // Black pawns move "down" (increasing row index)
        if (dr == 1) { // 1 square forward
            if (dc == 0 && is_empty(r2, c2)) return 1; // Move straight
            if (dc == 1 && is_opponent_piece(r2, c2, player_color)) return 1; // Capture diagonally
        } else if (dr == 2 && r1 == 1) { // 2 squares forward from starting row
            if (dc == 0 && is_empty(r2, c2) && is_empty(r1 + 1, c1)) return 1; // Move straight and path clear
        }
    }
    return 0;
}

int is_knight_move(int r1, int c1, int r2, int c2) {
    int dr = abs(r2 - r1);
    int dc = abs(c2 - c1);
    return (dr == 1 && dc == 2) || (dr == 2 && dc == 1);
}

// Helper for Bishop, Rook, Queen to check path and direction
int is_sliding_move(int r1, int c1, int r2, int c2, int player_color, int must_be_diagonal, int must_be_straight) {
    int dr = r2 - r1;
    int dc = c2 - c1;

    // Determine direction components
    int step_r = (dr == 0) ? 0 : (dr > 0 ? 1 : -1);
    int step_c = (dc == 0) ? 0 : (dc > 0 ? 1 : -1);

    // Check if move is straight or diagonal
    int is_move_straight = (dr == 0 || dc == 0);
    int is_move_diagonal = (abs(dr) == abs(dc));

    if (!( (must_be_diagonal && is_move_diagonal) || (must_be_straight && is_move_straight) ) ) return 0;
    if (dr == 0 && dc == 0) return 0; // Not moving

    // Check path for obstructions
    int curr_r = r1 + step_r;
    int curr_c = c1 + step_c;
    while (curr_r != r2 || curr_c != c2) {
        if (!is_empty(curr_r, curr_c)) {
            return 0; // Obstruction found
        }
        curr_r += step_r;
        curr_c += step_c;
    }
    return 1;
}

int is_bishop_move(int r1, int c1, int r2, int c2, int player_color) {
    return is_sliding_move(r1, c1, r2, c2, player_color, 1, 0); // Diagonal only
}

int is_rook_move(int r1, int c1, int r2, int c2, int player_color) {
    return is_sliding_move(r1, c1, r2, c2, player_color, 0, 1); // Straight only
}

int is_queen_move(int r1, int c1, int r2, int c2, int player_color) {
    return is_sliding_move(r1, c1, r2, c2, player_color, 1, 1); // Both diagonal and straight
}

int is_king_move(int r1, int c1, int r2, int c2) {
    int dr = abs(r2 - r1);
    int dc = abs(c2 - c1);
    return (dr <= 1 && dc <= 1 && (dr + dc > 0)); // Max 1 step in any direction, not standing still
}

// Full move legality check, including king safety
int is_legal_move(int r1, int c1, int r2, int c2, int player_color) {
    // 1. Basic boundary & piece ownership checks
    if (!is_valid_coord(r1, c1) || !is_valid_coord(r2, c2)) return 0;
    char piece = board[r1][c1];
    if (is_empty(r1, c1) || get_piece_color(piece) != player_color) return 0; // Must be player's piece
    if (get_piece_color(board[r2][c2]) == player_color) return 0; // Cannot capture your own piece
    if (r1 == r2 && c1 == c2) return 0; // Cannot move to the same square

    // 2. Piece-specific movement rules
    int valid_piece_move = 0;
    char abs_piece = toupper(piece); // Convert to uppercase for piece type check

    switch (abs_piece) {
        case WHITE_PAWN:   valid_piece_move = is_pawn_move(r1, c1, r2, c2, player_color); break;
        case WHITE_KNIGHT: valid_piece_move = is_knight_move(r1, c1, r2, c2);           break;
        case WHITE_BISHOP: valid_piece_move = is_bishop_move(r1, c1, r2, c2, player_color); break;
        case WHITE_ROOK:   valid_piece_move = is_rook_move(r1, c1, r2, c2, player_color);   break;
        case WHITE_QUEEN:  valid_piece_move = is_queen_move(r1, c1, r2, c2, player_color);  break;
        case WHITE_KING:   valid_piece_move = is_king_move(r1, c1, r2, c2);                break;
        default: return 0; // Should not happen with valid pieces
    }

    if (!valid_piece_move) return 0;

    // 3. King safety check: Does this move put/leave own king in check?
    char saved_board[BOARD_SIZE][BOARD_SIZE];
    memcpy(saved_board, board, sizeof(board)); // Save current global board state

    make_move_on_board(board, r1, c1, r2, c2); // Temporarily make the move on the GLOBAL board

    int king_stays_safe = !is_king_in_check(player_color); // Check if king is in check on this temp state

    memcpy(board, saved_board, sizeof(board)); // RESTORE the global board to its original state

    return king_stays_safe;
}

// --- Board Display and Initialization ---

void init_board() {
    // Initialize with empty squares
    for (int r = 0; r < BOARD_SIZE; r++) {
        for (int c = 0; c < BOARD_SIZE; c++) {
            board[r][c] = EMPTY_SQUARE;
        }
    }

    // Place pieces: R(ook) N(ight) B(ishop) Q(ueen) K(ing) B(ishop) N(ight) R(ook)
    char white_back_row[] = {WHITE_ROOK, WHITE_KNIGHT, WHITE_BISHOP, WHITE_QUEEN, WHITE_KING, WHITE_BISHOP, WHITE_KNIGHT, WHITE_ROOK};
    char black_back_row[] = {BLACK_ROOK, BLACK_KNIGHT, BLACK_BISHOP, BLACK_QUEEN, BLACK_KING, BLACK_BISHOP, BLACK_KNIGHT, BLACK_ROOK};

    // Black pieces
    for (int c = 0; c < BOARD_SIZE; c++) {
        board[0][c] = black_back_row[c];
        board[1][c] = BLACK_PAWN;
    }

    // White pieces
    for (int c = 0; c < BOARD_SIZE; c++) {
        board[7][c] = white_back_row[c];
        board[6][c] = WHITE_PAWN;
    }
}

