#include <stdio.h>
#include <string.h>

#define SIZE 8

// Structure to represent a piece on the board
typedef struct {
    char type; // 'K' for king, 'Q' for queen, 'R' for rook, 'B' for bishop, 'N' for knight, 'P' for pawn
    char color; // 'W' for white, 'B' for black
} Piece;

// Function to initialize the board
void initializeBoard(Piece board[SIZE][SIZE]) {
    // Initialize pawns
    for (int i = 0; i < SIZE; i++) {
        board[1][i].type = 'P';
        board[1][i].color = 'W';
        board[6][i].type = 'P';
        board[6][i].color = 'B';
    }

    // Initialize rooks
    board[0][0].type = board[0][7].type = 'R';
    board[0][0].color = board[0][7].color = 'W';
    board[7][0].type = board[7][7].type = 'R';
    board[7][0].color = board[7][7].color = 'B';

    // Initialize knights
    board[0][1].type = board[0][6].type = 'N';
    board[0][1].color = board[0][6].color = 'W';
    board[7][1].type = board[7][6].type = 'N';
    board[7][1].color = board[7][6].color = 'B';

    // Initialize bishops
    board[0][2].type = board[0][5].type = 'B';
    board[0][2].color = board[0][5].color = 'W';
    board[7][2].type = board[7][5].type = 'B';
    board[7][2].color = board[7][5].color = 'B';

    // Initialize queens
    board[0][3].type = 'Q';
    board[0][3].color = 'W';
    board[7][3].type = 'Q';
    board[7][3].color = 'B';

    // Initialize kings
    board[0][4].type = 'K';
    board[0][4].color = 'W';
    board[7][4].type = 'K';
    board[7][4].color = 'B';
}

// Function to print the board
void printBoard(Piece board[SIZE][SIZE]) {
    printf("  a b c d e f g h\n");
    for (int i = 0; i < SIZE; i++) {
        printf("%d ", i + 1);
        for (int j = 0; j < SIZE; j++) {
            if (board[i][j].type == '\0') {
                printf("- ");
            } else {
                printf("%c%c ", board[i][j].type, board[i][j].color);
            }
        }
        printf("\n");
    }
}

// Function to check if a move is valid
int isValidMove(Piece board[SIZE][SIZE], int x1, int y1, int x2, int y2) {
    // Check if the move is within the board
    if (x1 < 0 || x1 >= SIZE || y1 < 0 || y1 >= SIZE || x2 < 0 || x2 >= SIZE || y2 < 0 || y2 >= SIZE) {
        return 0;
    }

    // Check if the source square contains a piece of the same color as the player
    if (board[x1][y1].color == 'W' && x1 > 3) {
        return 0;
    }
    if (board[x1][y1].color == 'B' && x1 < 4) {
        return 0;
    }

    // Check if the destination square is empty or contains a piece of a different color
    if (board[x2][y2].color == board[x1][y1].color) {
        return 0;
    }

    // Check if the move is valid based on the type of piece
    if (board[x1][y1].type == 'P') {
        // Pawn
        if (board[x1][y1].color == 'W') {
            if (x2 == x1 + 1 && y2 == y1 && board[x2][y2].type == '\0') {
                return 1;
            }
            if (x2 == x1 + 1 && y2 == y1 + 1 && board[x2][y2].color == 'B') {
                return 1;
            }
            if (x2 == x1 + 1 && y2 == y1 - 1 && board[x2][y2].color == 'B') {
                return 1;
            }
        } else {
            if (x2 == x1 - 1 && y2 == y1 && board[x2][y2].type == '\0') {
                return 1;
            }
            if (x2 == x1 - 1 && y2 == y1 + 1 && board[x2][y2].color == 'W') {
                return 1;
            }
            if (x2 == x1 - 1 && y2 == y1 - 1 && board[x2][y2].color == 'W') {
                return 1;
            }
        }
    } else if (board[x1][y1].type == 'N') {
        // Knight
        if ((x2 == x1 + 2 && y2 == y1 + 1) || (x2 == x1 + 2 && y2 == y1 - 1) ||
            (x2 == x1 - 2 && y2 == y1 + 1) || (x2 == x1 - 2 && y2 == y1 - 1) ||
            (x2 == x1 + 1 && y2 == y1 + 2) || (x2 == x1 + 1 && y2 == y1 - 2) ||
            (x2 == x1 - 1 && y2 == y1 + 2) || (x2 == x1 - 1 && y2 == y1 - 2)) {
            return 1;
        }
    } else if (board[x1][y1].type == 'B') {
        // Bishop
        if (abs(x2 - x1) == abs(y2 - y1)) {
            int dx = (x2 > x1) ? 1 : -1;
            int dy = (y2 > y1) ? 1 : -1;
            int x = x1 + dx;
            int y = y1 + dy;
            while (x != x2) {
                if (board[x][y].type != '\0') {
                    return 0;
                }
                x += dx;
                y += dy;
            }
            return 1;
        }
    } else if (board[x1][y1].type == 'R') {
        // Rook
        if (x1 == x2 || y1 == y2) {
            if (x1 == x2) {
                int dy = (y2 > y1) ? 1 : -1;
                int y = y1 + dy;
                while (y != y2) {
                    if (board[x1][y].type != '\0') {
                        return 0;
                    }
                    y += dy;
                }
            } else {
                int dx = (x2 > x1) ? 1 : -1;
                int x = x1 + dx;
                while (x != x2) {
                    if (board[x][y1].type != '\0') {
                        return 0;
                    }
                    x += dx;
                }
            }
            return 1;
        }
    } else if (board[x1][y1].type == 'Q') {
        // Queen
        if (x1 == x2 || y1 == y2 || abs(x2 - x1) == abs(y2 - y1)) {
            if (x1 == x2) {
                int dy = (y2 > y1) ? 1 : -1;
                int y = y1 + dy;
                while (y != y2) {
                    if (board[x1][y].type != '\0') {
                        return 0;
                    }
                    y += dy;
                }
            } else if (y1 == y2) {
                int dx = (x2 > x1) ? 1 : -1;
                int x = x1 + dx;
                while (x != x2) {
                    if (board[x][y1].type != '\0') {
                        return 0;
                    }
                    x += dx;
                }
            } else {
                int dx = (x2 > x1) ? 1 : -1;
                int dy = (y2 > y1) ? 1 : -1;
                int x = x1 + dx;
                int y = y1 + dy;
                while (x != x2) {
                    if (board[x][y].type != '\0') {
                        return 0;
                    }
                    x += dx;
                    y += dy;
                }
            }
            return 1;
        }
    } else if (board[x1][y1].type == 'K') {
        // King
        if (abs(x2 - x1) <= 1 && abs(y2 - y1) <= 1) {
            return 1;
        }
    }

    return 0;
}

// Function to make a move
void makeMove(Piece board[SIZE][SIZE], int x1, int y1, int x2, int y2) {
    board[x2][y2] = board[x1][y1];
    board[x1][y1].type = '\0';
    board[x1][y1].color = '\0';
}

