#define ROWS 8
#define COLS 8

char board[ROWS][COLS];

// Function prototypes
void initialize_board();
void print_board();
int validate_move(int from_row, int from_col, int to_row, int to_col, char player);
void make_move(int from_row, int from_col, int to_row, int to_col, char player);
int random_move(char player);

// Initialize the chessboard with starting positions
void initialize_board() {
    // White pieces
    board[0][0] = 'R'; board[0][1] = 'N'; board[0][2] = 'B'; board[0][3] = 'Q'; board[0][4] = 'K'; board[0][5] = 'B'; board[0][6] = 'N'; board[0][7] = 'R';
    for (int i = 0; i < COLS; i++) {
        board[1][i] = 'P';
    }

    // Black pieces
    board[7][0] = 'r'; board[7][1] = 'n'; board[7][2] = 'b'; board[7][3] = 'q'; board[7][4] = 'k'; board[7][5] = 'b'; board[7][6] = 'n'; board[7][7] = 'r';
    for (int i = 0; i < COLS; i++) {
        board[6][i] = 'p';
    }

    // Empty squares
    for (int i = 2; i < 6; i++) {
        for (int j = 0; j < COLS; j++) {
            board[i][j] = '.';
        }
    }
}

// Print the chessboard
void print_board() {
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            printf("%c ", board[i][j]);
        }
        printf("\n");
    }
}

// Validate a move
int validate_move(int from_row, int from_col, int to_row, int to_col, char player) {
    if (from_row < 0 || from_row >= ROWS || from_col < 0 || from_col >= COLS || to_row < 0 || to_row >= ROWS || to_col < 0 || to_col >= COLS) {
        return 0;
    }

    if (board[from_row][from_col] == '.') {
        return 0;
    }

    if (player == 'w') {
        if (board[from_row][from_col] == 'p') {  // Pawn
            if (to_row == from_row + 1 && to_col == from_col && board[to_row][to_col] == '.') {
                return 1;
            } else if (from_row == 1 && to_row == 3 && to_col == from_col && board[2][from_col] == '.' && board[3][from_col] == '.') {
                return 1;
            } else if (to_row == from_row + 1 && (to_col == from_col - 1 || to_col == from_col + 1) && board[to_row][to_col] != '.' && islower(board[to_row][to_col])) {
                return 1;
            }
        } else if (board[from_row][from_col] == 'R') {  // Rook
            if (from_row == to_row) {
                for (int col = from_col + 1; col < to_col; col++) {
                    if (board[from_row][col] != '.') return 0;
                }
                for (int col = from_col - 1; col > to_col; col--) {
                    if (board[from_row][col] != '.') return 0;
                }
            } else if (from_col == to_col) {
                for (int row = from_row + 1; row < to_row; row++) {
                    if (board[row][from_col] != '.') return 0;
                }
                for (int row = from_row - 1; row > to_row; row--) {
                    if (board[row][from_col] != '.') return 0;
                }
            } else {
                return 0;
            }
        } else {
            return 0;  // Other pieces validation can be added here
        }
    } else if (player == 'b') {
        if (board[from_row][from_col] == 'p') {  // Pawn
            if (to_row == from_row - 1 && to_col == from_col && board[to_row][to_col] == '.') {
                return 1;
            } else if (from_row == 6 && to_row == 4 && to_col == from_col && board[5][from_col] == '.' && board[4][from_col] == '.') {
                return 1;
            } else if (to_row == from_row - 1 && (to_col == from_col - 1 || to_col == from_col + 1) && board[to_row][to_col] != '.' && isupper(board[to_row][to_col])) {
                return 1;
            }
        } else if (board[from_row][from_col] == 'r') {  // Rook
            if (from_row == to_row) {
                for (int col = from_col + 1; col < to_col; col++) {
                    if (board[from_row][col] != '.') return 0;
                }
                for (int col = from_col - 1; col > to_col; col--) {
                    if (board[from_row][col] != '.') return 0;
                }
            } else if (from_col == to_col) {
                for (int row = from_row + 1; row < to_row; row++) {
                    if (board[row][from_col] != '.') return 0;
                }
                for (int row = from_row - 1; row > to_row; row--) {
                    if (board[row][from_col] != '.') return 0;
                }
            } else {
                return 0;
            }
        } else {
            return 0;  // Other pieces validation can be added here
        }
    }

    return 1;
}

// Make a move
void make_move(int from_row, int from_col, int to_row, int to_col, char player) {
    board[to_row][to_col] = board[from_row][from_col];
    board[from_row][from_col] = '.';
}

// Generate a random move for the computer
int random_move(char player) {
    int attempts = 0;
    while (attempts < 100) {
        int from_row = rand() % ROWS;
        int from_col = rand() % COLS;
        int to_row = rand() % ROWS;
        int to_col = rand() % COLS;

        if (validate_move(from_row, from_col, to_row, to_col, player)) {
            make_move(from_row, from_col, to_row, to_col, player);
            return 1;
        }

        attempts++;
    }
    return 0;  // No valid move found
}

// Main function
int main() {
    initialize_board();
    char player = 'w';

    srand(time(0));

    while (1) {
        print_board();
        printf("Player %c, enter your move (from_row from_col to_row to_col): ", player);
        int from_row, from_col, to_row, to_col;
        scanf("%d %d %d %d", &from_row, &from_col, &to_row, &to_col);

        if (validate_move(from_row, from_col, to_row, to_col, player)) {
            make_move(from_row, from_col, to_row, to_col, player);
        } else {
            printf("Invalid move! Try again.\n");
            continue;
        }

        if (player == 'w') {
            player = 'b';
            if (!random_move(player)) {
                printf("Computer cannot find a valid move!\n");
                break;
            }
            player = 'w';
        }
    }

    printf("Game over!\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

// Function to perform Stalin Sort
int* stalinSort(int* arr, int* size) {
    // If array is empty or has only one element, return as is
    if (*size <= 1) {
        return arr;
    }

    // Index to track the current sorted portion
    int sortedIndex = 0;

    // Iterate through the array starting from the second element
    for (int i = 1; i < *size; i++) {
        // If current element is greater or equal to the last sorted element
        if (arr[i] >= arr[sortedIndex]) {
            // Move to the next position in the sorted portion
            sortedIndex++;

            // Copy the current element to the sorted portion
            arr[sortedIndex] = arr[i];
        }
        // If current element is smaller, it's "purged" (simply skipped)
    }

    // Update the size to reflect the number of remaining elements
    *size = sortedIndex + 1;

    // Reallocate the array to the new size
    arr = realloc(arr, (*size) * sizeof(int));

    return arr;
}

// Utility function to print the array
void printArray(int* arr, int size) {
    for (int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

int main() {
    // Example usage
    int size = 8;
    int* arr = malloc(size * sizeof(int));

    // Sample unsorted array
    arr[0] = 5;
    arr[1] = 3;
    arr[2] = 7;
    arr[3] = 1;
    arr[4] = 9;
    arr[5] = 2;
    arr[6] = 6;
    arr[7] = 4;

    printf("Original array: ");
    printArray(arr, size);

    // Perform Stalin Sort
    arr = stalinSort(arr, &size);

    printf("After Stalin Sort: ");
    printArray(arr, size);

    // Free the dynamically allocated memory
    free(arr);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

// Function to perform Stalin sort
int* stalin_sort(int* array, int size, int* new_size) {
    if (size == 0) {
        *new_size = 0;
        return NULL;
    }

    // Allocate memory for the result (worst case: same size as input)
    int* result = (int*)malloc(size * sizeof(int));
    if (result == NULL) {
        *new_size = 0;
        return NULL;
    }

    int count = 1;
    result[0] = array[0];
    int last = array[0];

    for (int i = 1; i < size; i++) {
        if (array[i] >= last) {
            result[count] = array[i];
            last = array[i];
            count++;
        }
    }

    *new_size = count;
    return result;
}

// Function to print an array
void print_array(int* array, int size) {
    printf("[");
    for (int i = 0; i < size; i++) {
        printf("%d", array[i]);
        if (i < size - 1) {
            printf(", ");
        }
    }
    printf("]\n");
}

int main() {
    int array[] = {1, 2, 4, 3, 6, 8, 0, 9, 5, 7};
    int size = sizeof(array) / sizeof(array[0]);
    int new_size;

    printf("Original array: ");
    print_array(array, size);

    int* sorted = stalin_sort(array, size, &new_size);

    printf("Sorted array: ");
    print_array(sorted, new_size);

    free(sorted);
    return 0;
}

#include <stdio.h>   // For printf
#include <stdlib.h>  // For malloc, free, realloc

/**
 * @brief Implements the Stalin Sort algorithm.
 *        Removes elements from the input array that are smaller than the
 *        last element successfully added to the result.
 *
 * @param arr The input array of integers (constant, not modified).
 * @param size The number of elements in the input array.
 * @param new_size A pointer to an integer where the size of the resulting
 *                 (Stalin-sorted) array will be stored.
 * @return A pointer to a new dynamically allocated array containing the
 *         Stalin-sorted elements, or NULL if input is invalid or memory
 *         allocation fails. The caller is responsible for freeing this memory.
 */
int* stalin_sort(const int* arr, int size, int* new_size) {
    // Handle invalid or empty input arrays
    if (arr == NULL || size <= 0) {
        *new_size = 0;
        return NULL;
    }

    // Allocate memory for the result array.
    // In the worst case, all elements are kept (e.g., if array is already sorted).
    // So, allocate enough space for the original size.
    int* result = (int*)malloc(sizeof(int) * size);
    if (result == NULL) {
        perror("Failed to allocate memory for result array");
        *new_size = 0;
        return NULL;
    }

    int current_write_idx = 0;
    int current_maximum_kept_value;

    // The first element is always kept (unless the array is empty, handled above).
    result[current_write_idx++] = arr[0];
    current_maximum_kept_value = arr[0];

    // Iterate through the rest of the input array
    for (int i = 1; i < size; ++i) {
        // If the current element is greater than or equal to the last kept element, keep it.
        if (arr[i] >= current_maximum_kept_value) {
            result[current_write_idx++] = arr[i];
            current_maximum_kept_value = arr[i];
        }
        // Else (arr[i] < current_maximum_kept_value), discard arr[i].
    }

    // Update the actual size of the new array.
    *new_size = current_write_idx;

    // Optionally, reallocate the result array to its exact size to save memory.
    // If realloc fails, we still return the originally allocated (possibly oversized) 'result' block.
    // Since current_write_idx will always be >= 1 for valid input size > 0, *new_size will be > 0.
    int* temp_result = (int*)realloc(result, sizeof(int) * (*new_size));
    if (temp_result == NULL) {
        // realloc failed. Return the original (potentially oversized) block.
        // It's still valid, just not optimally sized.
        return result;
    } else {
        // realloc succeeded. Use the new pointer.
        return temp_result;
    }
}

/**
 * @brief Helper function to print an array.
 *
 * @param label A label to print before the array.
 * @param arr The array to print.
 * @param size The number of elements in the array.
 */
void print_array(const char* label, const int* arr, int size) {
    printf("%s: [", label);
    if (arr != NULL) {
        for (int i = 0; i < size; ++i) {
            printf("%d", arr[i]);
            if (i < size - 1) {
                printf(", ");
            }
        }
    }
    printf("]\n");
}

int main() {
    // Test Case 1: General unsorted array
    int arr1[] = {10, 4, 8, 20, 5, 25};
    int size1 = sizeof(arr1) / sizeof(arr1[0]);
    int new_size1;
    int* sorted_arr1 = stalin_sort(arr1, size1, &new_size1);
    print_array("Original array 1", arr1, size1);
    print_array("Stalin-sorted array 1", sorted_arr1, new_size1);
    free(sorted_arr1); // Free the dynamically allocated memory

    printf("\n");

    // Test Case 2: Already sorted array
    int arr2[] = {1, 2, 3, 4, 5};
    int size2 = sizeof(arr2) / sizeof(arr2[0]);
    int new_size2;
    int* sorted_arr2 = stalin_sort(arr2, size2, &new_size2);
    print_array("Original array 2", arr2, size2);
    print_array("Stalin-sorted array 2", sorted_arr2, new_size2);
    free(sorted_arr2);

    printf("\n");

    // Test Case 3: Reverse sorted array
    int arr3[] = {5, 4, 3, 2, 1};
    int size3 = sizeof(arr3) / sizeof(arr3[0]);
    int new_size3;
    int* sorted_arr3 = stalin_sort(arr3, size3, &new_size3);
    print_array("Original array 3", arr3, size3);
    print_array("Stalin-sorted array 3", sorted_arr3, new_size3);
    free(sorted_arr3);

    printf("\n");

    // Test Case 4: Single element array
    int arr4[] = {7};
    int size4 = sizeof(arr4) / sizeof(arr4[0]);
    int new_size4;
    int* sorted_arr4 = stalin_sort(arr4, size4, &new_size4);
    print_array("Original array 4", arr4, size4);
    print_array("Stalin-sorted array 4", sorted_arr4, new_size4);
    free(sorted_arr4);

    printf("\n");

    // Test Case 5: Empty array (or invalid size input)
    // Expect NULL return and new_size to be 0
    int arr5[] = {}; // C99 allows zero-sized arrays at the end of structs, but not standalone globally.
                     // On most compilers, int arr5[0] might work, but it's cleaner to just pass size 0.
    int size5 = 0;
