// Stalin sort: Retains non-decreasing elements from the array.
// Returns new length of the array after "sorting".
size_t stalin_sort(int *arr, size_t len) {
    if (len == 0) return 0;
    size_t i, j = 1;
    int last = arr[0];

    for (i = 1; i < len; ++i) {
        if (arr[i] >= last) {
            arr[j++] = arr[i];
            last = arr[i];
        }
        // else discard arr[i] (do nothing)
    }
    return j;
}

