// Function to perform Stalin sort on an array
void stalinSort(int *arr, int *size) {
    if (*size <= 1) return; // No sorting needed for an array of size 0 or 1

    int keeper = arr[0]; // Keep the first element
    int writeIndex = 1; // Position to write the next valid element

    for (int i = 1; i < *size; i++) {
        if (arr[i] >= keeper) {
            keeper = arr[i]; // Update the last kept element
            arr[writeIndex++] = arr[i]; // Keep the element
        }
    }

    // Update the size of the array after removing elements
    *size = writeIndex;
}

