/**
 * Stalin sort algorithm implementation in C.
 *
 * The Stalin sort algorithm is an inefficient sorting algorithm that works by repeatedly
 * removing elements from the front of the array that are smaller than the last element.
 *
 * Time complexity: O(n^2) in the worst case
 * Space complexity: O(1) as it only uses a small amount of extra memory
 *
 * Parameters:
 * arr: The input array to be sorted
 * n: The size of the input array
 */
void stalin_sort(int* arr, int n) {
    int i, j;

    // Loop through the array, removing elements from the front that are smaller than the last element
    for (i = 1; i < n; i++) {
        if (arr[i - 1] > arr[i]) {
            // Shift elements to the left, effectively removing the smaller element
            for (j = i; j < n; j++) {
                arr[j - 1] = arr[j];
            }
            // Reduce the size of the array
            n--;
            // Decrement the loop counter to re-check the new element at index i
            i--;
        }
    }
}

