// Function to perform Stalin sort
void stalin_sort(int *array, int *size) {
    if (*size <= 1) {
        return; // Array is already sorted or empty
    }

    int *new_array = (int *)malloc(*size * sizeof(int));
    if (new_array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    new_array[0] = array[0];
    int new_size = 1;

    for (int i = 1; i < *size; i++) {
        if (array[i] >= new_array[new_size - 1]) {
            new_array[new_size] = array[i];
            new_size++;
        }
    }

    // Copy the sorted elements back to the original array
    for (int i = 0; i < new_size; i++) {
        array[i] = new_array[i];
    }

    // Update the size of the array
    *size = new_size;

    // Free the allocated memory
    free(new_array);
}

