/**
 * Calculates the public key in a finite-field Diffie-Hellman key exchange
 * 
 * @param prime The prime modulus of the finite field
 * @param base The base/generator of the multiplicative group
 * @param secret The secret exponent/private key
 * @return The calculated public key
 */
uint64_t diffie_hellman_public_key(uint64_t prime, uint64_t base, uint64_t secret) {
    // Use modular exponentiation to calculate (base^secret) mod prime
    uint64_t public_key = 1;
    base = base % prime;

    while (secret > 0) {
        // If secret is odd, multiply the result with base
        if (secret & 1) {
            public_key = (public_key * base) % prime;
        }

        // Square the base
        base = (base * base) % prime;

        // Divide secret by 2
        secret = secret >> 1;
    }

    return public_key;
}

