 *
 * @param prime The prime number used for the key exchange.
 * @param base  The base number used for the key exchange.
 * @param secret The secret key used for the key exchange.
 * @return The calculated public key.
 */
uint64_t calculate_public_key(uint64_t prime, uint64_t base, uint64_t secret) {
    // Calculate the public key using the formula: public_key = base ^ secret mod prime
    uint64_t public_key = 1;
    uint64_t current_base = base % prime;

    while (secret > 0) {
        if (secret % 2 == 1) {
            public_key = (public_key * current_base) % prime;
        }
        current_base = (current_base * current_base) % prime;
        secret /= 2;
    }

    return public_key;
}

