 * 
 * @param prime The prime modulus
 * @param base The primitive root (generator)
 * @param privateKey The private key of the party
 * @param otherPublicKey The public key from the other party
 * @return The shared secret key
 */
uint64_t diffie_hellman_shared_key(
    uint64_t prime, 
    uint64_t base, 
    uint64_t privateKey, 
    uint64_t otherPublicKey
) {
