    if (prime <= 1 || base < 2 || privateKey == 0 || otherPublicKey == 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return 0;
    }

    // Calculate the shared key using the other party's public key and our private key
    return mod_pow(otherPublicKey, privateKey, prime);
}

