 */
int calculateSharedKey(mpz_t sharedKey, const mpz_t prime, const mpz_t publicKey, const mpz_t privateKey) {
    // Input validation: Ensure parameters are not NULL or uninitialized.
    // While GMP functions handle some bad states, it's good practice to check.
    if (!prime || !publicKey || !privateKey || !sharedKey) {
        fprintf(stderr, "Error: One or more input mpz_t variables are uninitialized or NULL.\n");
        return -1;
    }

    // Perform the modular exponentiation: sharedKey = (publicKey ^ privateKey) % prime
    // In Diffie-Hellman, if your private key is 'a' and the other party's
    // public key is (g^b % p), then your shared key is (g^b)^a % p.
    // If your private key is 'b' and the other party's public key is (g^a % p),
    // then your shared key is (g^a)^b % p.
    // In both cases, this simplifies to (g^(a*b)) % p, which is the shared secret.
    mpz_powm_ui_gmp(sharedKey, publicKey, privateKey, prime);

    return 0; // Success
}

// Example Usage
int main() {
    mpz_t p, g, a, b;       // Prime, Base (generator), Alice's private key, Bob's private key
    mpz_t alicePublicKey;   // Alice's public key
    mpz_t bobPublicKey;     // Bob's public key
    mpz_t aliceSharedKey;   // Shared key calculated by Alice
    mpz_t bobSharedKey;     // Shared key calculated by Bob

    // Initialize GMP integers
    mpz_inits(p, g, a, b, alicePublicKey, bobPublicKey, aliceSharedKey, bobSharedKey, NULL);

    // 1. Agree on public parameters: p (prime) and g (base/generator)
    // For demonstration, use small values. In real-world, these would be very large.
    mpz_set_str(p, "23", 10);   // A prime number
    mpz_set_str(g, "5", 10);    // A base/generator

    printf("--- Diffie-Hellman Setup ---\n");
    gmp_printf("Prime (p): %Zd\n", p);
    gmp_printf("Base (g): %Zd\n", g);
    printf("\n");

    // 2. Alice's Part
    // Alice chooses a private key 'a' (secret)
    mpz_set_str(a, "6", 10); // Alice's private key
    gmp_printf("Alice's Private Key (a): %Zd\n", a);

    // Alice calculates her public key: A = (g^a) % p
    mpz_powm_ui_gmp(alicePublicKey, g, a, p);
    gmp_printf("Alice's Public Key (A = g^a %% p): %Zd\n", alicePublicKey);
    printf("\n");

    // 3. Bob's Part
    // Bob chooses a private key 'b' (secret)
    mpz_set_str(b, "15", 10); // Bob's private key
    gmp_printf("Bob's Private Key (b): %Zd\n", b);

    // Bob calculates his public key: B = (g^b) % p
    mpz_powm_ui_gmp(bobPublicKey, g, b, p);
    gmp_printf("Bob's Public Key (B = g^b %% p): %Zd\n", bobPublicKey);
    printf("\n");

    printf("--- Key Exchange ---\n");
    // Alice and Bob exchange their public keys (A and B).

    // 4. Alice calculates the shared secret key
    // Alice receives Bob's public key (B)
    // Alice computes: S_Alice = (B^a) % p
    printf("Alice calculates shared key...\n");
    if (calculateSharedKey(aliceSharedKey, p, bobPublicKey, a) == 0) {
        gmp_printf("Alice's Shared Key: %Zd\n", aliceSharedKey);
    } else {
        fprintf(stderr, "Error calculating Alice's shared key.\n");
        exit(EXIT_FAILURE);
    }
    printf("\n");

    // 5. Bob calculates the shared secret key
    // Bob receives Alice's public key (A)
    // Bob computes: S_Bob = (A^b) % p
    printf("Bob calculates shared key...\n");
    if (calculateSharedKey(bobSharedKey, p, alicePublicKey, b) == 0) {
        gmp_printf("Bob's Shared Key: %Zd\n", bobSharedKey);
    } else {
        fprintf(stderr, "Error calculating Bob's shared key.\n");
        exit(EXIT_FAILURE);
    }
    printf("\n");

    // 6. Verify that the shared keys are identical
    if (mpz_cmp(aliceSharedKey, bobSharedKey) == 0) {
        printf("Shared keys match! Diffie-Hellman successful.\n");
    } else {
        fprintf(stderr, "Error: Shared keys do NOT match! Something went wrong.\n");
    }

    // Free GMP integers to prevent memory leaks
    mpz_clears(p, g, a, b, alicePublicKey, bobPublicKey, aliceSharedKey, bobSharedKey, NULL);

    return 0;
}

