// Computes (base^exp) % mod using modular exponentiation (right-to-left binary method)
uint64_t mod_pow(uint64_t base, uint64_t exp, uint64_t mod) {
    uint64_t result = 1;
    base = base % mod;
    while (exp > 0) {
        if (exp % 2 == 1)
            result = (result * base) % mod;
        exp = exp >> 1;
        base = (base * base) % mod;
    }
    return result;
}

// Calculates the shared key in Diffie-Hellman
// public_key: the other party's public value (g^a mod p)
// private_key: your private value (b)
// prime: the prime modulus (p)
uint64_t dh_shared_key(uint64_t public_key, uint64_t private_key, uint64_t prime) {
    return mod_pow(public_key, private_key, prime);
}

