// prime: The prime number used in the exchange
// base: The base integer used in the exchange
// public_key: The other party's public key
// private_key: Your private key
unsigned long long calculate_shared_key(unsigned long long prime, unsigned long long base, unsigned long long public_key, unsigned long long private_key) {
    return mod_exp(public_key, private_key, prime);
}

