/**
 * Calculates the shared key in a finite-field Diffie-Hellman key exchange.
 *
 * @param prime   The prime number used in the key exchange.
 * @param base    The base number used in the key exchange.
 * @param public_key The public key to calculate the shared key from.
 * @param private_key The private key of the local user.
 * @return The calculated shared key.
 */
uint64_t calculate_shared_key(uint64_t prime, uint64_t base, uint64_t public_key, uint64_t private_key) {
    // Calculate the shared key using modular exponentiation
    uint64_t shared_key = 1;
    while (private_key > 0) {
        if (private_key & 1) {
            shared_key = (shared_key * public_key) % prime;
        }
        public_key = (public_key * public_key) % prime;
        private_key >>= 1;
    }
    return shared_key;
}

