#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>

#define BUFFER_SIZE 1024

// Function to create and manage pipes for communication
void create_chat_pipes(int *pipe_parent_to_child, int *pipe_child_to_parent) {
    // Create pipes for bidirectional communication
    if (pipe(pipe_parent_to_child) == -1) {
        perror("Pipe creation failed (parent to child)");
        exit(1);
    }

    if (pipe(pipe_child_to_parent) == -1) {
        perror("Pipe creation failed (child to parent)");
        exit(1);
    }
}

// Function to send messages through a pipe
void send_message(int pipe_fd, const char *message) {
    ssize_t bytes_written = write(pipe_fd, message, strlen(message) + 1);
    if (bytes_written == -1) {
        perror("Write to pipe failed");
        exit(1);
    }
}

// Function to receive messages from a pipe
ssize_t receive_message(int pipe_fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(pipe_fd, buffer, buffer_size);
    if (bytes_read == -1) {
        perror("Read from pipe failed");
        exit(1);
    }
    return bytes_read;
}

// Chat application main function
void start_chat() {
    int pipe_parent_to_child[2];  // Parent to child pipe
    int pipe_child_to_parent[2];  // Child to parent pipe

    // Create pipes
    create_chat_pipes(pipe_parent_to_child, pipe_child_to_parent);

    // Fork a child process
    pid_t pid = fork();

    if (pid < 0) {
        // Fork failed
        perror("Fork failed");
        exit(1);
    }

    if (pid > 0) {
        // Parent process (first user)
        close(pipe_parent_to_child[0]);  // Close read end
        close(pipe_child_to_parent[1]);  // Close write end

        char send_buffer[BUFFER_SIZE];
        char recv_buffer[BUFFER_SIZE];

        printf("Parent Process (User 1) Chat Started:\n");

        while (1) {
            // Send message
            printf("User 1 (Parent): ");
            fgets(send_buffer, BUFFER_SIZE, stdin);
            send_buffer[strcspn(send_buffer, "\n")] = 0;  // Remove newline

            if (strcmp(send_buffer, "exit") == 0) {
                send_message(pipe_parent_to_child[1], "exit");
                break;
            }

            send_message(pipe_parent_to_child[1], send_buffer);

            // Receive message
            ssize_t bytes_read = receive_message(pipe_child_to_parent[0], recv_buffer, BUFFER_SIZE);

            if (bytes_read > 0) {
                if (strcmp(recv_buffer, "exit") == 0) {
                    break;
                }
                printf("User 2 (Child): %s\n", recv_buffer);
            }
        }

        // Close pipe file descriptors
        close(pipe_parent_to_child[1]);
        close(pipe_child_to_parent[0]);

        // Wait for child process to terminate
        wait(NULL);
    }
    else {
        // Child process (second user)
        close(pipe_parent_to_child[1]);  // Close write end
        close(pipe_child_to_parent[0]);  // Close read end

        char send_buffer[BUFFER_SIZE];
        char recv_buffer[BUFFER_SIZE];

        printf("Child Process (User 2) Chat Started:\n");

        while (1) {
            // Receive message
            ssize_t bytes_read = receive_message(pipe_parent_to_child[0], recv_buffer, BUFFER_SIZE);

            if (bytes_read > 0) {
                if (strcmp(recv_buffer, "exit") == 0) {
                    break;
                }
                printf("User 1 (Parent): %s\n", recv_buffer);
            }

            // Send message
            printf("User 2 (Child): ");
            fgets(send_buffer, BUFFER_SIZE, stdin);
            send_buffer[strcspn(send_buffer, "\n")] = 0;  // Remove newline

            if (strcmp(send_buffer, "exit") == 0) {
                send_message(pipe_child_to_parent[1], "exit");
                break;
            }

            send_message(pipe_child_to_parent[1], send_buffer);
        }

        // Close pipe file descriptors
        close(pipe_parent_to_child[0]);
        close(pipe_child_to_parent[1]);

        exit(0);
    }
}

int main() {
    start_chat();
    return 0;
}

