// --- Global Pipes for simplicity in the chat app ---
// Parent writes to parent_write_pipe (fd[1]), child reads from parent_write_pipe (fd[0])
int parent_write_pipe[2];
// Child writes to child_write_pipe (fd[1]), parent reads from child_write_pipe (fd[0])
int child_write_pipe[2];

// Function to initialize pipes
// This function will be called once before forking.
int setup_pipes() {
    if (pipe(parent_write_pipe) == -1) {
        perror("pipe parent_write_pipe creation failed");
        return -1;
    }
    if (pipe(child_write_pipe) == -1) {
        perror("pipe child_write_pipe creation failed");
        return -1;
    }
    return 0; // Success
}

// Function to send a message through a pipe
// 'write_fd' is the file descriptor for the write end of the pipe
int send_message(int write_fd, const char *message) {
    ssize_t bytes_written = write(write_fd, message, strlen(message) + 1); // +1 for null terminator
    if (bytes_written == -1) {
        perror("write failed");
        return -1;
    }
    return 0; // Success
}

// Function to receive a message from a pipe
// 'read_fd' is the file descriptor for the read end of the pipe
// 'buffer' is where the received message will be stored
// 'buffer_size' is the maximum size of the buffer
// Returns the number of bytes read, or -1 on error.
ssize_t receive_message(int read_fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(read_fd, buffer, buffer_size - 1); // -1 to leave space for null terminator
    if (bytes_read == -1) {
        perror("read failed");
        return -1;
    }
    buffer[bytes_read] = '\0'; // Null-terminate the received string
    return bytes_read;
}

// Function to close all pipe ends (important for cleanup)
void close_all_pipes() {
    close(parent_write_pipe[0]);
    close(parent_write_pipe[1]);
    close(child_write_pipe[0]);
    close(child_write_pipe[1]);
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/types.h>

#define MSG_LEN 100

void chat_with_pipes() {
    int pipe_parent_to_child[2]; // pipe1: parent writes -> child reads
    int pipe_child_to_parent[2]; // pipe2: child writes -> parent reads
    char buffer[MSG_LEN];

    // Create pipes
    if (pipe(pipe_parent_to_child) == -1 || pipe(pipe_child_to_parent) == -1) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) {
        // ---- Child process ----
        close(pipe_parent_to_child[1]); // close write end (parent->child)
        close(pipe_child_to_parent[0]); // close read end (child->parent)

        while (1) {
            // Read from parent
            ssize_t n = read(pipe_parent_to_child[0], buffer, MSG_LEN);
            if (n <= 0) break;
            buffer[n] = '\0';
            printf("Parent: %s", buffer);

            // Exit if parent says bye
            if(strncmp(buffer, "bye", 3) == 0) {
                break;
            }

            // Child send message
            printf("Child: ");
            if (fgets(buffer, MSG_LEN, stdin) == NULL) break;
            write(pipe_child_to_parent[1], buffer, strlen(buffer));

            if(strncmp(buffer, "bye", 3) == 0) {
                break;
            }
        }
        close(pipe_parent_to_child[0]);
        close(pipe_child_to_parent[1]);
    } else {
        // ---- Parent process ----
        close(pipe_parent_to_child[0]); // close read end (parent->child)
        close(pipe_child_to_parent[1]); // close write end (child->parent)

        while (1) {
            // Parent send message
            printf("Parent: ");
            if (fgets(buffer, MSG_LEN, stdin) == NULL) break;
            write(pipe_parent_to_child[1], buffer, strlen(buffer));

            // Exit if parent says bye
            if(strncmp(buffer, "bye", 3) == 0) {
                break;
            }

            // Read from child
            ssize_t n = read(pipe_child_to_parent[0], buffer, MSG_LEN);
            if (n <= 0) break;
            buffer[n] = '\0';
            printf("Child: %s", buffer);

            if(strncmp(buffer, "bye", 3) == 0) {
                break;
            }
        }
        close(pipe_parent_to_child[1]);
        close(pipe_child_to_parent[0]);
    }
}

int main() {
    printf("Simple Parent-Child pipe chat (type 'bye' to quit).\n");
    chat_with_pipes();
    return 0;
}

