    if (pid == 0) { // Child process (receiver)
        close(pipe_fd[1]); // Close write end of the pipe
        chat(pipe_fd[0], -1); // Pass only the read end
    } else { // Parent process (sender)
        close(pipe_fd[0]); // Close read end of the pipe
        chat(-1, pipe_fd[1]); // Pass only the write end
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>

// Function to handle chat between parent and child processes
void chat(int pipe1[], int pipe2[]) {
    char message[100];

    // Parent process writes to pipe1 and reads from pipe2
    if (fork() == 0) {
        // Child process reads from pipe1 and writes to pipe2
        close(pipe1[1]); // Close writing end of pipe1
        close(pipe2[0]); // Close reading end of pipe2

        while (1) {
            read(pipe1[0], message, 100);
            printf("Parent: %s\n", message);
            if (strcmp(message, "exit") == 0) {
                break;
            }

            printf("Child: ");
            fgets(message, 100, stdin);
            write(pipe2[1], message, strlen(message) + 1);
        }

        close(pipe1[0]); // Close reading end of pipe1
        close(pipe2[1]); // Close writing end of pipe2
    } else {
        close(pipe1[0]); // Close reading end of pipe1
        close(pipe2[1]); // Close writing end of pipe2

        while (1) {
            printf("Parent: ");
            fgets(message, 100, stdin);
            write(pipe1[1], message, strlen(message) + 1);
            if (strcmp(message, "exit\n") == 0) {
                break;
            }

            read(pipe2[0], message, 100);
            printf("Child: %s\n", message);
        }

        close(pipe1[1]); // Close writing end of pipe1
        close(pipe2[0]); // Close reading end of pipe2
        wait(NULL); // Wait for child process to finish
    }
}

int main() {
    int pipe1[2];
    int pipe2[2];

    // Create pipes
    if (pipe(pipe1) == -1 || pipe(pipe2) == -1) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    chat(pipe1, pipe2);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/wait.h>

#define BUFFER_SIZE 1024

void read_from_pipe(int pipe_fd[2], char *buffer) {
    close(pipe_fd[1]); // Close the write end of the pipe in the reading process
    ssize_t bytes_read = read(pipe_fd[0], buffer, BUFFER_SIZE);
    if (bytes_read > 0) {
        buffer[bytes_read] = '\0'; // Null-terminate the string
        printf("Received: %s", buffer);
    }
    close(pipe_fd[0]); // Close the read end after reading
}

void write_to_pipe(int pipe_fd[2], const char *message) {
    close(pipe_fd[0]); // Close the read end of the pipe in the writing process
    write(pipe_fd[1], message, strlen(message));
    close(pipe_fd[1]); // Close the write end after writing
}

int main() {
    int pipe1[2], pipe2[2];
    pid_t pid;
    char buffer[BUFFER_SIZE];

    // Create the first pipe for parent to child communication
    if (pipe(pipe1) == -1) {
        perror("Pipe1 failed");
        exit(1);
    }

    // Create the second pipe for child to parent communication
    if (pipe(pipe2) == -1) {
        perror("Pipe2 failed");
        exit(1);
    }

    // Fork a child process
    pid = fork();
    if (pid == -1) {
        perror("Fork failed");
        exit(1);
    }

    if (pid == 0) { // Child process
        // Close unused ends of the pipes
        close(pipe1[1]); // Write end of pipe1
        close(pipe2[0]); // Read end of pipe2

        while (1) {
            printf("Child: ");
            fgets(buffer, BUFFER_SIZE, stdin);
            if (strcmp(buffer, "exit\n") == 0) {
                write_to_pipe(pipe2, "exit\n");
                break;
            }
            write_to_pipe(pipe2, buffer);
            read_from_pipe(pipe1, buffer);
        }

        // Close the remaining ends of the pipes
        close(pipe1[0]);
        close(pipe2[1]);

        exit(0);
    } else { // Parent process
        // Close unused ends of the pipes
        close(pipe1[0]); // Read end of pipe1
        close(pipe2[1]); // Write end of pipe2

        while (1) {
            printf("Parent: ");
            fgets(buffer, BUFFER_SIZE, stdin);
            if (strcmp(buffer, "exit\n") == 0) {
                write_to_pipe(pipe1, "exit\n");
                break;
            }
            write_to_pipe(pipe1, buffer);
            read_from_pipe(pipe2, buffer);
        }

        // Wait for the child process to finish
        wait(NULL);

        // Close the remaining ends of the pipes
        close(pipe1[1]);
        close(pipe2[0]);
    }

    return 0;
}

