/**
 * @brief Finds the maximum and minimum elements in an integer array.
 *
 * This function takes an array, its size, and pointers to two integer
 * variables. It calculates the maximum and minimum values in the array
 * and stores them in the memory locations pointed to by `max_val` and `min_val`.
 *
 * @param arr The integer array to search.
 * @param size The number of elements in the array.
 * @param max_val A pointer to an integer where the maximum value will be stored.
 * @param min_val A pointer to an integer where the minimum value will be stored.
 *
 * @note This function assumes `size` is greater than 0. The calling
 *       code should handle the case of an empty or invalid array.
 */
void findMaxMin(int arr[], int size, int *max_val, int *min_val) {
    // Initialize max and min with the first element of the array.
    // This correctly handles arrays with all positive, all negative,
    // or mixed numbers, and is robust for size = 1.
    *max_val = arr[0];
    *min_val = arr[0];

    // Iterate through the rest of the array starting from the second element
    for (int i = 1; i < size; i++) {
        if (arr[i] > *max_val) {
            *max_val = arr[i]; // Update max if a larger element is found
        }

        if (arr[i] < *min_val) {
            *min_val = arr[i]; // Update min if a smaller element is found
        }
    }
}

