    for (int i = 0; i < n; i++) {
        printf("Element %d: ", i + 1);
        if (scanf("%d", &arr[i]) != 1) {
            printf("Invalid input. Please enter an integer.\n");
            free(arr); // Free allocated memory before abnormal exit
            return 1; // Indicate error
        }
    }

    // Call the function to find max and min
    // We pass the addresses of max_value and min_value so the function
    // can modify them directly (pass-by-reference using pointers)
    findMaxMin(arr, n, &max_value, &min_value);

    // Print the results
    printf("\nResults:\n");
    printf("Maximum element: %d\n", max_value);
