#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <openssl/md5.h>

#define MAX_URL_LENGTH 2048
#define SHORT_URL_LENGTH 8

// Structure to store URL mapping
typedef struct {
    char original_url[MAX_URL_LENGTH];
    char short_url[SHORT_URL_LENGTH + 1];
} URLMapping;

// Global array to store URL mappings
URLMapping* url_database = NULL;
int url_count = 0;
int url_capacity = 0;

// Function to convert MD5 hash to base62 string
void md5_to_base62(unsigned char* md5_hash, char* short_url) {
    // Base62 character set
    const char base62[] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";

    // Use first 8 characters of MD5 hash
    unsigned long long hash_value = 0;
    for (int i = 0; i < 8; i++) {
        hash_value = (hash_value << 8) | md5_hash[i];
    }

    // Convert to base62
    for (int i = 0; i < SHORT_URL_LENGTH; i++) {
        short_url[i] = base62[hash_value % 62];
        hash_value /= 62;
    }
    short_url[SHORT_URL_LENGTH] = '\0';
}

// Function to generate short URL
char* generate_short_url(const char* original_url) {
    // Compute MD5 hash
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    MD5_CTX md5_ctx;
    MD5_Init(&md5_ctx);
    MD5_Update(&md5_ctx, original_url, strlen(original_url));
    MD5_Final(md5_hash, &md5_ctx);

    // Allocate memory for short URL
    char* short_url = malloc(SHORT_URL_LENGTH + 1);

    // Convert MD5 to base62 short URL
    md5_to_base62(md5_hash, short_url);

    return short_url;
}

// Function to store URL mapping
int store_url_mapping(const char* original_url, const char* short_url) {
    // Resize database if needed
    if (url_count >= url_capacity) {
        url_capacity = url_capacity == 0 ? 16 : url_capacity * 2;
        url_database = realloc(url_database, url_capacity * sizeof(URLMapping));
        if (url_database == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return 0;
        }
    }

    // Store mapping
    URLMapping* mapping = &url_database[url_count++];
    strncpy(mapping->original_url, original_url, MAX_URL_LENGTH - 1);
    mapping->original_url[MAX_URL_LENGTH - 1] = '\0';
    strncpy(mapping->short_url, short_url, SHORT_URL_LENGTH);
    mapping->short_url[SHORT_URL_LENGTH] = '\0';

    return 1;
}

// Function to find original URL by short URL
const char* find_original_url(const char* short_url) {
    for (int i = 0; i < url_count; i++) {
        if (strcmp(url_database[i].short_url, short_url) == 0) {
            return url_database[i].original_url;
        }
    }
    return NULL;
}

// URL shortener function
char* shorten_url(const char* original_url) {
    // Check if URL already exists
    for (int i = 0; i < url_count; i++) {
        if (strcmp(url_database[i].original_url, original_url) == 0) {
            return strdup(url_database[i].short_url);
        }
    }

    // Generate short URL
    char* short_url = generate_short_url(original_url);

    // Store mapping
    if (store_url_mapping(original_url, short_url)) {
        return short_url;
    }

    free(short_url);
    return NULL;
}

// Example usage
int main() {
    // Example URLs
    const char* url1 = "https://www.example.com/very/long/url/that/needs/shortening";
    const char* url2 = "https://another.example.com/another/long/url";

    // Shorten URLs
    char* short_url1 = shorten_url(url1);
    char* short_url2 = shorten_url(url2);

    // Print results
    printf("Original URL 1: %s\n", url1);
    printf("Shortened URL 1: %s\n", short_url1);
    printf("Original URL 2: %s\n", url2);
    printf("Shortened URL 2: %s\n", short_url2);

    // Retrieve original URLs
    printf("\nRetrieving original URLs:\n");
    printf("Short URL 1 maps to: %s\n", find_original_url(short_url1));
    printf("Short URL 2 maps to: %s\n", find_original_url(short_url2));

    // Free memory
    free(short_url1);
    free(short_url2);
    free(url_database);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>

#define SHORT_URL_LENGTH 8  // Length of the shortened URL

// Function to compute MD5 hash of a string
void compute_md5(const char *str, unsigned char *digest) {
    MD5_CTX context;
    MD5_Init(&context);
    MD5_Update(&context, str, strlen(str));
    MD5_Final(digest, &context);
}

// Function to convert MD5 digest to a hexadecimal string
void digest_to_hex(const unsigned char *digest, char *hex_str) {
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(hex_str + (i * 2), "%02x", digest[i]);
    }
    hex_str[MD5_DIGEST_LENGTH * 2] = '\0';
}

// Function to shorten a URL using MD5
void shorten_url(const char *long_url, char *short_url) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    char hex_digest[MD5_DIGEST_LENGTH * 2 + 1];

    // Compute MD5 hash of the long URL
    compute_md5(long_url, digest);

    // Convert the MD5 digest to a hexadecimal string
    digest_to_hex(digest, hex_digest);

    // Truncate the hexadecimal string to create a short URL
    strncpy(short_url, hex_digest, SHORT_URL_LENGTH);
    short_url[SHORT_URL_LENGTH] = '\0';
}

int main() {
    char long_url[] = "https://www.example.com/very/long/url/that/needs/to/be/shortened";
    char short_url[SHORT_URL_LENGTH + 1];

    shorten_url(long_url, short_url);

    printf("Long URL: %s\n", long_url);
    printf("Short URL: %s\n", short_url);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h> // For MD5 hashing

// Define the desired length of the "shortened" MD5 part
// MD5 produces 32 hex chars (128 bits). 8 chars is 4 bytes.
#define SHORT_MD5_LENGTH 8 // Adjust this for desired length (max 32)

/**
 * @brief Generates a "shortened" URL identifier using MD5.
 *        This function computes the MD5 hash of the original URL and returns
 *        a specified prefix of its hexadecimal representation.
 *        NOTE: This is a *demonstration* of using MD5. A real URL shortener
 *              requires a database for mapping and robust collision handling.
 *
 * @param originalUrl The original long URL to shorten.
 * @return A dynamically allocated string containing the (partial) MD5 hash.
 *         NULL if memory allocation fails or originalUrl is NULL.
 *         The caller is responsible for freeing this memory.
 */
char* md5_shorten_url(const char* originalUrl) {
    if (originalUrl == NULL) {
        fprintf(stderr, "Error: originalUrl cannot be NULL.\n");
        return NULL;
    }

    unsigned char digest[MD5_DIGEST_LENGTH]; // 16 bytes for MD5 hash
    char* md5string_full = (char*)malloc(MD5_DIGEST_LENGTH * 2 + 1); // 32 hex chars + null terminator
    if (md5string_full == NULL) {
        perror("Failed to allocate memory for full MD5 string");
        return NULL;
    }

    // Compute MD5 hash
    MD5((const unsigned char*)originalUrl, strlen(originalUrl), digest);

    // Convert the 16-byte digest to a 32-character hexadecimal string
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(&md5string_full[i * 2], "%02x", (unsigned int)digest[i]);
    }
    md5string_full[MD5_DIGEST_LENGTH * 2] = '\0'; // Null-terminate

    // Truncate the MD5 string to the desired SHORT_MD5_LENGTH
    // This is the "shortening" part; adjust SHORT_MD5_LENGTH macro
    if (SHORT_MD5_LENGTH > MD5_DIGEST_LENGTH * 2 || SHORT_MD5_LENGTH < 1) {
        fprintf(stderr, "Warning: SHORT_MD5_LENGTH is out of valid range (1 to 32). Using full MD5 string.\n");
        return md5string_full; // Return full hash if length is invalid
    }

    char* shortened_md5 = (char*)malloc(SHORT_MD5_LENGTH + 1);
    if (shortened_md5 == NULL) {
        perror("Failed to allocate memory for shortened MD5 string");
        free(md5string_full); // Clean up previously allocated memory
        return NULL;
    }

    strncpy(shortened_md5, md5string_full, SHORT_MD5_LENGTH);
    shortened_md5[SHORT_MD5_LENGTH] = '\0'; // Null-terminate the shortened string

    free(md5string_full); // Free the full MD5 string as we only need the shortened one

    return shortened_md5;
}

