// Generates a short code (short_url) of length short_len from the input url.
// short_url should have space for at least short_len+1 bytes (for null terminator).
void url_shorten(const char *url, char *short_url, size_t short_len) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((const unsigned char*)url, strlen(url), digest);

    for(size_t i = 0; i < short_len; ++i)
        sprintf(&short_url[i], "%1x", digest[i] & 0xF);  // Take only half of digest[i] hex for brevity

    short_url[short_len] = '\0';
}

