#define SHORT_URL_LENGTH 8

void md5_hash(const char *str, unsigned char *digest) {
    MD5_CTX context;
    MD5_Init(&context);
    MD5_Update(&context, str, strlen(str));
    MD5_Final(digest, &context);
}

char *base62_encode(unsigned int value, char *buffer, int bufferSize) {
    const char *base62chars = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    int i = 0;

    // Ensure the buffer is large enough
    if (bufferSize < 1) return NULL;

    buffer[i++] = base62chars[value % 62];
    value /= 62;

    while (value != 0 && i < (bufferSize - 1)) {
        buffer[i++] = base62chars[value % 62];
        value /= 62;
    }

    buffer[i] = '\0';

    // Reverse the buffer
    for (int j = 0; j < i / 2; ++j) {
        char temp = buffer[j];
        buffer[j] = buffer[i - j - 1];
        buffer[i - j - 1] = temp;
    }

    return buffer;
}

char *shorten_url(const char *url) {
    unsigned char md5_digest[MD5_DIGEST_LENGTH];
    char *short_url = (char *)malloc(SHORT_URL_LENGTH + 1);  // +1 for null terminator
    if (!short_url) {
        perror("Failed to allocate memory");
        return NULL;
    }

    md5_hash(url, md5_digest);

    unsigned int int_repr = (md5_digest[0] << 24) | (md5_digest[1] << 16) | (md5_digest[2] << 8) | md5_digest[3];

    if (!base62_encode(int_repr, short_url, SHORT_URL_LENGTH + 1)) {
        free(short_url);
        return NULL;
    }

    return short_url;
}

