    URLMapping* newMapping = (URLMapping*)malloc(sizeof(URLMapping));
    if (!newMapping) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    strncpy(newMapping->originalUrl, originalUrl, 256);
    strncpy(newMapping->shortUrl, shortUrl, 33);
    newMapping->next = head;
    head = newMapping;

    printf("Original URL: %s\n", originalUrl);
    printf("Short URL (MD5): %s\n", shortUrl);
}

