#define SHORT_URL_LENGTH 8

char *shorten_url(const char *long_url) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    char short_url[SHORT_URL_LENGTH + 1];
    char *p;

    // Compute the MD5 hash of the long URL
    MD5((const unsigned char *)long_url, strlen(long_url), (unsigned char *)&digest);

    // Convert the MD5 hash to a hexadecimal string
    for (int i = 0, j = 0; i < MD5_DIGEST_LENGTH && j < SHORT_URL_LENGTH; ++i) {
        // Convert each byte of the digest to two hexadecimal characters
        p = (char *)&digest[i];
        if (*p >= 0 && *p <= 15) {
            short_url[j++] = (*p < 10) ? '0' + *p : 'a' + (*p - 10);
        } else {
            short_url[j++] = (*p >> 4) < 10 ? '0' + (*p >> 4) : 'a' + ((*p >> 4) - 10);
            short_url[j++] = (*p & 0x0F) < 10 ? '0' + (*p & 0x0F) : 'a' + ((*p & 0x0F) - 10);
        }
    }

    // Null-terminate the short URL
    short_url[SHORT_URL_LENGTH] = '\0';

    // Allocate memory for the result and copy the short URL
    char *result = malloc(SHORT_URL_LENGTH + 1);
    if (result == NULL) {
        return NULL; // Return NULL if memory allocation fails
    }
    strcpy(result, short_url);

    return result;
}

