/**
 * @brief Counts the number of words in a given string.
 *
 * A "word" is defined as a sequence of non-whitespace characters.
 * Words are separated by one or more whitespace characters.
 *
 * @param str The input string to analyze.
 * @return The number of words in the string.
 */
int countWords(const char *str) {
    if (str == NULL) {
        return 0; // Handle null pointer case
    }

    int wordCount = 0;
    bool inWord = false; // Flag to track if we are currently inside a word

    // Iterate through each character of the string
    for (int i = 0; str[i] != '\0'; i++) {
        if (isspace((unsigned char)str[i])) {
            // If the current character is whitespace
            inWord = false; // We are no longer in a word
        } else {
            // If the current character is non-whitespace
            if (!inWord) {
                // If we were NOT in a word previously, this means we just started a new word
                wordCount++;
                inWord = true; // Now we are inside a word
            }
            // If we were already in a word, just continue (we're still in the same word)
        }
    }

    return wordCount;
}

