// Function to get rainfall input and calculate total
float calculateRainfallTotal(int months) {
    float totalRainfall = 0.0;
    float rainfall;

    for (int i = 1; i <= months; i++) {
        // Input validation loop
        while (1) {
            printf("Enter rainfall for month %d (in inches): ", i);

            // Check if input is valid
            if (scanf("%f", &rainfall) != 1) {
                // Clear input buffer
                while (getchar() != '\n');
                printf("Invalid input. Please enter a numeric value.\n");
                continue;
            }

            // Check for negative rainfall
            if (rainfall < 0) {
                printf("Rainfall cannot be negative. Please try again.\n");
                continue;
            }

            // Add valid rainfall to total
            totalRainfall += rainfall;
            break;
        }
    }

    return totalRainfall;
}

