#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

#define MAX_SIZE 100

// Stack implementation for parentheses checking
typedef struct {
    char items[MAX_SIZE];
    int top;
} Stack;

// Initialize stack
void initStack(Stack *s) {
    s->top = -1;
}

// Check if stack is empty
bool isEmpty(Stack *s) {
    return s->top == -1;
}

// Push element to stack
void push(Stack *s, char c) {
    if (s->top < MAX_SIZE - 1) {
        s->items[++(s->top)] = c;
    }
}

// Pop element from stack
char pop(Stack *s) {
    if (!isEmpty(s)) {
        return s->items[(s->top)--];
    }
    return '\0';
}

// Check if parentheses are balanced
bool areParenthesesBalanced(char *expr) {
    Stack s;
    initStack(&s);

    for (int i = 0; expr[i] != '\0'; i++) {
        // Push opening parenthesis onto stack
        if (expr[i] == '(') {
            push(&s, expr[i]);
        }
        // When closing parenthesis is found
        else if (expr[i] == ')') {
            // If stack is empty, closing parenthesis without matching opening
            if (isEmpty(&s)) {
                return false;
            }
            // Pop the top element
            pop(&s);
        }
    }

    // Stack should be empty for balanced parentheses
    return isEmpty(&s);
}

int main() {
    char expression[MAX_SIZE];

    // Input the expression
    printf("Enter an expression: ");
    fgets(expression, sizeof(expression), stdin);

    // Remove newline character if present
    expression[strcspn(expression, "\n")] = '\0';

    // Check and print result
    if (areParenthesesBalanced(expression)) {
        printf("Parentheses are balanced in '%s'\n", expression);
    } else {
        printf("Parentheses are not balanced in '%s'\n", expression);
    }

    return 0;
}

#include <stdio.h>
#include <stdbool.h>
#include <string.h>

bool isBalanced(const char *expression) {
    int balance = 0;

    for (int i = 0; expression[i] != '\0'; i++) {
        if (expression[i] == '(') {
            balance++;
        } else if (expression[i] == ')') {
            balance--;
            if (balance < 0) {
                return false; // More closing than opening parentheses
            }
        }
    }

    return balance == 0; // True if balanced
}

int main() {
    const char *expression = "(a+b)*c";

    if (isBalanced(expression)) {
        printf("The expression '%s' has balanced parentheses.\n", expression);
    } else {
        printf("The expression '%s' does NOT have balanced parentheses.\n", expression);
    }

    return 0;
}

#include <stdio.h>
#include <string.h>
#include <stdbool.h>

// Function to check if parentheses are balanced in a given expression
bool areParenthesesBalanced(const char* expr) {
    int balance = 0; // Initialize a counter for parentheses balance

    // Iterate through each character in the expression
    for (int i = 0; expr[i] != '\0'; i++) {
        char ch = expr[i]; // Get the current character

        // If the character is an opening parenthesis, increment the balance
        if (ch == '(') {
            balance++;
        }
        // If the character is a closing parenthesis, decrement the balance
        else if (ch == ')') {
            balance--;
        }

        // If at any point the balance becomes negative, it means a closing parenthesis
        // appeared without a corresponding opening one, so it's unbalanced.
        if (balance < 0) {
            return false;
        }
    }

    // After iterating through the entire expression, if the balance is 0,
    // it means all opening parentheses have a matching closing one.
    return balance == 0;
}

int main() {
    // Test cases
    const char* expr1 = "(a+b)*c"; // Balanced
    const char* expr2 = "((a+b)*c)"; // Balanced
    const char* expr3 = "(a+b)*c)"; // Unbalanced: extra ')'
    const char* expr4 = "((a+b)*c"; // Unbalanced: missing ')'
    const char* expr5 = "a+b*c"; // No parentheses, so balanced (trivially)
    const char* expr6 = "()) ("; // Unbalanced
    const char* expr7 = ""; // Empty string, balanced (trivially)

    // Check and print results for each test case
    printf("Expression \"%s\" is %s\n", expr1, areParenthesesBalanced(expr1) ? "BALANCED" : "UNBALANCED");
    printf("Expression \"%s\" is %s\n", expr2, areParenthesesBalanced(expr2) ? "BALANCED" : "UNBALANCED");
    printf("Expression \"%s\" is %s\n", expr3, areParenthesesBalanced(expr3) ? "BALANCED" : "UNBALANCED");
    printf("Expression \"%s\" is %s\n", expr4, areParenthesesBalanced(expr4) ? "BALANCED" : "UNBALANCED");
