#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>

#define BUFFER_SIZE 256

void chat_process(int read_fd, int write_fd, const char* name) {
    char buffer[BUFFER_SIZE];

    while (1) {
        // Clear the buffer
        memset(buffer, 0, BUFFER_SIZE);

        // Prompt for message
        printf("%s> ", name);

        // Read user input
        if (fgets(buffer, BUFFER_SIZE, stdin) == NULL) {
            break;
        }

        // Remove newline character
        buffer[strcspn(buffer, "\n")] = 0;

        // Check for exit condition
        if (strcmp(buffer, "exit") == 0) {
            break;
        }

        // Write message to pipe
        write(write_fd, buffer, strlen(buffer) + 1);

        // Read incoming message
        ssize_t bytes_read = read(read_fd, buffer, BUFFER_SIZE);
        if (bytes_read <= 0) {
            break;
        }

        // Print received message
        printf("Received: %s\n", buffer);
    }
}

int main() {
    int pipe1[2];  // Parent to Child pipe
    int pipe2[2];  // Child to Parent pipe
    pid_t pid;

    // Create pipes
    if (pipe(pipe1) == -1 || pipe(pipe2) == -1) {
        perror("Pipe creation failed");
        exit(1);
    }

    // Fork the process
    pid = fork();

    if (pid < 0) {
        // Fork failed
        perror("Fork failed");
        exit(1);
    }
    else if (pid > 0) {
        // Parent process

        // Close unused pipe ends
        close(pipe1[0]);  // Close read end of pipe1
        close(pipe2[1]);  // Close write end of pipe2

        // Start chat for parent
        printf("Parent process ready to chat.\n");
        chat_process(pipe2[0], pipe1[1], "Parent");

        // Close pipe ends
        close(pipe1[1]);
        close(pipe2[0]);

        // Wait for child to terminate
        wait(NULL);
    }
    else {
        // Child process

        // Close unused pipe ends
        close(pipe1[1]);  // Close write end of pipe1
        close(pipe2[0]);  // Close read end of pipe2

        // Start chat for child
        printf("Child process ready to chat.\n");
        chat_process(pipe1[0], pipe2[1], "Child");

        // Close pipe ends
        close(pipe1[0]);
        close(pipe2[1]);

        exit(0);
    }

    return 0;
}

