#define BUFFER_SIZE 1024

int main() {
    int pipe1[2];  // Pipe for parent to child communication
    int pipe2[2];  // Pipe for child to parent communication
    char buffer[BUFFER_SIZE];
    pid_t pid;

    // Create the pipes
    if (pipe(pipe1) == -1 || pipe(pipe2) == -1) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    // Fork the process
    pid = fork();
    if (pid < 0) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    if (pid > 0) {  // Parent process
        close(pipe1[0]);  // Close the read end of pipe1
        close(pipe2[1]);  // Close the write end of pipe2

        while (1) {
            printf("Parent: ");
            fgets(buffer, BUFFER_SIZE, stdin);
            write(pipe1[1], buffer, strlen(buffer) + 1);  // Send message to child

            if (strcmp(buffer, "exit\n") == 0) {
                break;
            }

            read(pipe2[0], buffer, BUFFER_SIZE);  // Read response from child
            printf("Child: %s", buffer);
        }

        close(pipe1[1]);
        close(pipe2[0]);
        wait(NULL);  // Wait for the child process to finish
    } else {  // Child process
        close(pipe1[1]);  // Close the write end of pipe1
        close(pipe2[0]);  // Close the read end of pipe2

        while (1) {
            read(pipe1[0], buffer, BUFFER_SIZE);  // Read message from parent
            printf("Child: %s", buffer);

            if (strcmp(buffer, "exit\n") == 0) {
                break;
            }

            printf("Child: ");
            fgets(buffer, BUFFER_SIZE, stdin);
            write(pipe2[1], buffer, strlen(buffer) + 1);  // Send response to parent
        }

