#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h> // For fcntl

#define BUFFER_SIZE 256

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <read_fd> <write_fd>\n", argv[0]);
        return 1;
    }

    int read_fd = atoi(argv[1]);  // File descriptor to read from (parent's write end)
    int write_fd = atoi(argv[2]); // File descriptor to write to (parent's read end)

    // Set read_fd and stdin to non-blocking mode
    if (fcntl(read_fd, F_SETFL, O_NONBLOCK) == -1) {
        perror("fcntl read_fd");
        return 1;
    }
    if (fcntl(STDIN_FILENO, F_SETFL, O_NONBLOCK) == -1) {
        perror("fcntl STDIN_FILENO client");
        return 1;
    }

    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    printf("Client started! Type 'exit' to quit.\n");

    while (1) {
        // Read from pipe (parent's message)
        bytes_read = read(read_fd, buffer, BUFFER_SIZE - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("SERVER: %s", buffer);
            if (strcmp(buffer, "exit\n") == 0) {
                printf("Client received 'exit'. Exiting.\n");
                break;
            }
        } else if (bytes_read == -1 && errno != EAGAIN && errno != EWOULDBLOCK) {
            perror("read from pipe (client)");
            break;
        }

        // Read from stdin (client's message)
        bytes_read = read(STDIN_FILENO, buffer, BUFFER_SIZE - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            write(write_fd, buffer, bytes_read); // Write to parent
            if (strcmp(buffer, "exit\n") == 0) {
                printf("Client sent 'exit'. Exiting.\n");
                break;
            }
        } else if (bytes_read == -1 && errno != EAGAIN && errno != EWOULDBLOCK) {
            perror("read from stdin (client)");
            break;
        }

        usleep(100000); // Small delay to prevent busy-waiting
    }

    close(read_fd);
    close(write_fd);
    return 0;
}

