            if (strcmp(msg, "exit") == 0) {
                printf("Child exited. Exiting chat.\n");
                break;
            }
            printf("Child: %s\n", msg);
        }

        close(pipe_p2c[1]);
        close(pipe_c2p[0]);
    } else {
        // CHILD PROCESS
        close(pipe_p2c[1]); // close write end of parent-to-child
        close(pipe_c2p[0]); // close read end of child-to-parent

        while (1) {
            // Child waits for parent message
            read(pipe_p2c[0], msg, MSGSIZE);
            if (strcmp(msg, "exit") == 0) {
                printf("Parent exited. Exiting chat.\n");
                break;
            }
            printf("Parent: %s\n", msg);

            // Child sends response
            printf("Child: ");
            fflush(stdout);
            if (fgets(msg, MSGSIZE, stdin) == NULL) {
                perror("fgets");
                break;
            }
            msg[strcspn(msg, "\n")] = 0;
            write(pipe_c2p[1], msg, MSGSIZE);

            if (strcmp(msg, "exit") == 0) {
                break;
            }
        }

        close(pipe_p2c[0]);
        close(pipe_c2p[1]);
    }

    return 0;
}

