#include <string.h>

#define MAX_KEY_LENGTH 256
#define BUFFER_SIZE 4096

void encrypt_file(const char* input_file, const char* output_file, const char* key) {
    FILE* infile;
    FILE* outfile;
    unsigned char buffer[BUFFER_SIZE];
    size_t bytes_read;
    size_t key_length;
    size_t key_index = 0;

    // Open input file
    infile = fopen(input_file, "rb");
    if (infile == NULL) {
        fprintf(stderr, "Error: Could not open input file '%s'\n", input_file);
        exit(1);
    }

    // Open output file
    outfile = fopen(output_file, "wb");
    if (outfile == NULL) {
        fprintf(stderr, "Error: Could not open output file '%s'\n", output_file);
        fclose(infile);
        exit(1);
    }

    // Calculate key length
    key_length = strlen(key);

    // Read input file and encrypt
    while ((bytes_read = fread(buffer, 1, BUFFER_SIZE, infile)) > 0) {
        // XOR encryption
        for (size_t i = 0; i < bytes_read; i++) {
            buffer[i] ^= key[key_index];
            key_index = (key_index + 1) % key_length;
        }

        // Write encrypted data to output file
        fwrite(buffer, 1, bytes_read, outfile);
    }

    // Close files
    fclose(infile);
    fclose(outfile);

    printf("File encryption completed successfully.\n");
}

