// Initialize the grid with empty spaces
void initializeGrid() {
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            grid[i][j] = '.';
        }
    }
    placedWordCount = 0;
}

// Check if a word can be placed at a specific position
bool canPlaceWord(const char* word, int row, int col, bool horizontal) {
    int len = strlen(word);

    // Check grid boundaries
    if (horizontal && col + len > GRID_SIZE) return false;
    if (!horizontal && row + len > GRID_SIZE) return false;

    // Check for overlaps and conflicts
    for (int i = 0; i < len; i++) {
        int r = horizontal ? row : row + i;
        int c = horizontal ? col + i : col;

        // Check if cell is already occupied by a different letter
        if (grid[r][c] != '.' && grid[r][c] != word[i]) {
            return false;
        }

        // Check adjacent cells
        if (horizontal) {
            if (r > 0 && grid[r-1][c] != '.') return false;
            if (r < GRID_SIZE - 1 && grid[r+1][c] != '.') return false;
        } else {
            if (c > 0 && grid[r][c-1] != '.') return false;
            if (c < GRID_SIZE - 1 && grid[r][c+1] != '.') return false;
        }
    }

    return true;
}

// Place a word on the grid
bool placeWord(const char* word, int row, int col, bool horizontal) {
    if (!canPlaceWord(word, row, col, horizontal)) {
        return false;
    }

    int len = strlen(word);
    for (int i = 0; i < len; i++) {
        int r = horizontal ? row : row + i;
        int c = horizontal ? col + i : col;
        grid[r][c] = word[i];
    }

    // Store word placement
    strcpy(placedWords[placedWordCount].word, word);
    placedWords[placedWordCount].row = row;
    placedWords[placedWordCount].col = col;
    placedWords[placedWordCount].horizontal = horizontal;
    placedWordCount++;

    return true;
}

// Generate the crossword puzzle
void generateCrossword(char words[][MAX_WORD_LENGTH], int wordCount) {
    srand(time(NULL));
    initializeGrid();

    // Place the first word in the center
    int centerRow = GRID_SIZE / 2;
    int centerCol = GRID_SIZE / 2;
    placeWord(words[0], centerRow, centerCol, true);

    // Try to place remaining words
    for (int i = 1; i < wordCount; i++) {
        bool placed = false;
        int attempts = 0;

        while (!placed && attempts < 100) {
            // Randomly choose placement orientation
            bool horizontal = rand() % 2 == 0;

            // Try to find intersections with existing words
            for (int j = 0; j < placedWordCount && !placed; j++) {
                for (int k = 0; k < strlen(words[i]); k++) {
                    for (int l = 0; l < strlen(placedWords[j].word); l++) {
                        if (words[i][k] == placedWords[j].word[l]) {
                            int row, col;

                            if (placedWords[j].horizontal) {
                                row = placedWords[j].row;
                                col = placedWords[j].col + l;

                                if (placeWord(words[i], row - k, col, !horizontal)) {
                                    placed = true;
                                    break;
                                }
                            } else {
                                row = placedWords[j].row + l;
                                col = placedWords[j].col;

                                if (placeWord(words[i], row, col - k, !horizontal)) {
                                    placed = true;
                                    break;
                                }
                            }
                        }
                    }
                    if (placed) break;
                }
            }

            // If no intersection found, try random placement
            if (!placed) {
                int row = rand() % GRID_SIZE;
                int col = rand() % GRID_SIZE;

                if (placeWord(words[i], row, col, horizontal)) {
                    placed = true;
                }
            }

            attempts++;
        }

        // If word couldn't be placed, skip it
        if (!placed) {
            printf("Could not place word: %s\n", words[i]);
        }
    }
}

// Print the crossword puzzle
void printCrossword() {
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            printf("%c ", grid[i][j]);
        }
        printf("\n");
    }

    // Print word list
    printf("\nWord List:\n");
    for (int i = 0; i < placedWordCount; i++) {
        printf("%s (%s at %d,%d)\n", 
               placedWords[i].word, 
               placedWords[i].horizontal ? "Horizontal" : "Vertical",
               placedWords[i].row, 
               placedWords[i].col);
    }
}

