#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>

#define MAX_GRID_SIZE 30
#define MAX_WORD_LENGTH 20
#define MAX_WORDS 50
#define EMPTY_CHAR '#'

// Structure to hold a word and its properties
typedef struct {
    char word[MAX_WORD_LENGTH];
    int length;
    int row;
    int col;
    bool placed;
    char orientation; // 'H' for Horizontal, 'V' for Vertical
} WordInfo;

// Global grid
char grid[MAX_GRID_SIZE][MAX_GRID_SIZE];
int grid_rows = 0;
int grid_cols = 0;

// Function Prototypes
void initialize_grid();
void print_grid();
void generate_crossword(WordInfo words[], int num_words);
bool can_place_word(const WordInfo *word, int r, int c, char orientation);
void place_word(WordInfo *word_info, int r, int c, char orientation);
int compare_words(const void *a, const void *b); // For sorting words
void shuffle_words(WordInfo words[], int num_words);

int main() {
    srand(time(NULL)); // Seed for random number generation

    printf("Enter grid dimensions (rows columns, e.g., 15 15): ");
    if (scanf("%d %d", &grid_rows, &grid_cols) != 2 || grid_rows <= 0 || grid_cols <= 0 ||
        grid_rows > MAX_GRID_SIZE || grid_cols > MAX_GRID_SIZE) {
        fprintf(stderr, "Invalid grid dimensions. Using default 15x15.\n");
        grid_rows = 15;
        grid_cols = 15;
    }
    // Consume the rest of the line from stdin
    while (getchar() != '\n'); 

    initialize_grid();

    WordInfo words[MAX_WORDS];
    int num_words = 0;
    char input_word[MAX_WORD_LENGTH];

    printf("Enter words (one per line, max %d words, max %d chars per word).\n", MAX_WORDS, MAX_WORD_LENGTH -1);
    printf("Enter 'DONE' to finish:\n");

    while (num_words < MAX_WORDS) {
        printf("Word %d: ", num_words + 1);
        if (scanf("%s", input_word) != 1) {
            continue; // Error reading input
        }

        if (strcmp(input_word, "DONE") == 0) {
            break;
        }

        int len = strlen(input_word);
        if (len == 0 || len >= MAX_WORD_LENGTH) {
            printf("Word too short or too long. Max %d chars.\n", MAX_WORD_LENGTH - 1);
            continue;
        }

        // Convert word to uppercase
        for (int i = 0; i < len; i++) {
            if (input_word[i] >= 'a' && input_word[i] <= 'z') {
                input_word[i] = input_word[i] - 32; // Convert to uppercase ASCII
            }
        }

        strcpy(words[num_words].word, input_word);
        words[num_words].length = len;
        words[num_words].placed = false;
        num_words++;
    }

    if (num_words == 0) {
        printf("No words entered. Exiting.\n");
        return 0;
    }

    printf("\nGenerating crossword...\n");

    // Sort words by length (longest first) - helps with placement
    qsort(words, num_words, sizeof(WordInfo), compare_words);

    // Shuffle words of the same length to add some randomness
    shuffle_words(words, num_words);

    generate_crossword(words, num_words);

    printf("\n--- Generated Crossword ---\n");
    print_grid();

    printf("\n--- Words Placed ---\n");
    for (int i = 0; i < num_words; i++) {
        if (words[i].placed) {
            printf("%s (%s) at (%d, %d)\n", words[i].word, 
                   words[i].orientation == 'H' ? "Across" : "Down",
                   words[i].row + 1, words[i].col + 1); // +1 because rows/cols are 0-indexed internally
        }
    }

    return 0;
}

// Initialize the grid with empty characters
void initialize_grid() {
    for (int i = 0; i < grid_rows; i++) {
        for (int j = 0; j < grid_cols; j++) {
            grid[i][j] = EMPTY_CHAR;
        }
    }
}

// Print the grid
void print_grid() {
    printf("  "); // Spacer for column numbers
    for (int j = 0; j < grid_cols; j++) {
        printf("%c ", 'A' + j); // Column headers A, B, C...
    }
    printf("\n");

    for (int i = 0; i < grid_rows; i++) {
        printf("%2d ", i + 1); // Row numbers
        for (int j = 0; j < grid_cols; j++) {
            printf("%c ", grid[i][j]);
        }
        printf("\n");
    }
}

// Comparison function for qsort (descending length)
int compare_words(const void *a, const void *b) {
    return ((WordInfo *)b)->length - ((WordInfo *)a)->length;
}

// Shuffles words while preserving relative order of words with different lengths
void shuffle_words(WordInfo words[], int num_words) {
    if (num_words <= 1) return;

    for (int i = 0; i < num_words; i++) {
        int r = i + (rand() % (num_words - i));

        // Swap words[i] and words[r]
        WordInfo temp = words[i];
        words[i] = words[r];
        words[r] = temp;
    }
}

// Attempts to place all words in the grid
void generate_crossword(WordInfo words[], int num_words) {
    // First word is placed in the center (approximately)
    if (num_words > 0) {
        int start_r = (grid_rows - 1) / 2;
        int start_c = (grid_cols - words[0].length) / 2;

        if (can_place_word(&words[0], start_r, start_c, 'H')) {
            place_word(&words[0], start_r, start_c, 'H');
            words[0].placed = true;
            words[0].orientation = 'H';
            words[0].row = start_r;
            words[0].col = start_c;
        } else {
             // Fallback: Try vertical if horizontal not possible
            start_r = (grid_rows - words[0].length) / 2;
            start_c = (grid_cols - 1) / 2;
            if (can_place_word(&words[0], start_r, start_c, 'V')) {
                place_word(&words[0], start_r, start_c, 'V');
                words[0].placed = true;
                words[0].orientation = 'V';
                words[0].row = start_r;
                words[0].col = start_c;
            }
        }
    }

    // Attempt to place remaining words
    for (int i = 1; i < num_words; i++) {
        // Iterate through all possible positions and orientations
        bool placed_current_word = false;

        // Try horizontal first
        for (int r = 0; r < grid_rows; r++) {
            for (int c = 0; c <= grid_cols - words[i].length; c++) {
                if (can_place_word(&words[i], r, c, 'H')) {
                    place_word(&words[i], r, c, 'H');
                    words[i].placed = true;
                    words[i].orientation = 'H';
                    words[i].row = r;
                    words[i].col = c;
                    placed_current_word = true;
                    goto next_word; // Break out of nested loops
                }
            }
        }

        // If not placed horizontally, try vertically
        if (!placed_current_word) {
            for (int r = 0; r <= grid_rows - words[i].length; r++) {
                for (int c = 0; c < grid_cols; c++) {
                    if (can_place_word(&words[i], r, c, 'V')) {
                        place_word(&words[i], r, c, 'V');
                        words[i].placed = true;
                        words[i].orientation = 'V';
                        words[i].row = r;
                        words[i].col = c;
                        placed_current_word = true;
                        goto next_word; // Break out of nested loops
                    }
                }
            }
        }
        next_word:; // Label to jump to
    }
}

// Checks if a word can be placed at a given position and orientation
bool can_place_word(const WordInfo *word_info, int r_start, int c_start, char orientation) {
    if (orientation == 'H') { // Horizontal
        if (c_start + word_info->length > grid_cols) return false; // Out of bounds

        for (int i = 0; i < word_info->length; i++) {
            char grid_char = grid[r_start][c_start + i];
            char word_char = word_info->word[i];

            if (grid_char != EMPTY_CHAR && grid_char != word_char) {
                return false; // Character conflict
            }
        }

        // Check for adjacent words that would break placement (e.g., a word immediately to the left/right,
        // or a letter immediately above/below that doesn't intersect)
        // This is a basic check. More robust crosswords need better boundary/adjacency checks.

        // Check left boundary
        if (c_start > 0 && grid[r_start][c_start - 1] != EMPTY_CHAR) return false;
        // Check right boundary
        if (c_start + word_info->length < grid_cols && grid[r_start][c_start + word_info->length] != EMPTY_CHAR) return false;

        // Check top/bottom boundaries of the word (for non-intersections)
        for (int i = 0; i < word_info->length; i++) {
            if (grid[r_start][c_start + i] == EMPTY_CHAR) { // Only check if this spot is currently empty
                if (r_start > 0 && grid[r_start - 1][c_start + i] != EMPTY_CHAR) return false; // Above
                if (r_start < grid_rows - 1 && grid[r_start + 1][c_start + i] != EMPTY_CHAR) return false; // Below
            }
        }


    } else if (orientation == 'V') { // Vertical
        if (r_start + word_info->length > grid_rows) return false; // Out of bounds

        for (int i = 0; i < word_info->length; i++) {
            char grid_char = grid[r_start + i][c_start];
            char word_char = word_info->word[i];

            if (grid_char != EMPTY_CHAR && grid_char != word_char) {
                return false; // Character conflict
            }
        }

        // Check top boundary
        if (r_start > 0 && grid[r_start - 1][c_start] != EMPTY_CHAR) return false;
        // Check bottom boundary
        if (r_start + word_info->length < grid_rows && grid[r_start + word_info->length][c_start] != EMPTY_CHAR) return false;

        // Check left/right boundaries of the word (for non-intersections)
        for (int i = 0; i < word_info->length; i++) {
            if (grid[r_start + i][c_start] == EMPTY_CHAR) { // Only check if this spot is currently empty
                if (c_start > 0 && grid[r_start + i][c_start - 1] != EMPTY_CHAR) return false; // Left
                if (c_start < grid_cols - 1 && grid[r_start + i][c_start + 1] != EMPTY_CHAR) return false; // Right
            }
        }
    } else {
        return false; // Invalid orientation
    }

    // Check if at least one intersection occurs, *unless* it's the very first word.
    // This dramatically improves the chances of a connected crossword.
    bool has_intersection = false;
    for (int i = 0; i < word_info->length; i++) {
        if (orientation == 'H') {
            if (grid[r_start][c_start + i] == word_info->word[i]) {
                has_intersection = true;
                break;
            }
        } else { // Vertical
            if (grid[r_start + i][c_start] == word_info->word[i]) {
                has_intersection = true;
                break;
            }
        }
    }

    // For the first word, no intersection is needed. For subsequent, an intersection is ideal.
    // If the grid is completely empty (no words placed yet), allow placement without intersection.
    bool grid_is_empty = true;
    for(int r=0; r<grid_rows; ++r) {
        for(int c=0; c<grid_cols; ++c) {
            if(grid[r][c] != EMPTY_CHAR) {
                grid_is_empty = false;
                break;
            }
        }
        if(!grid_is_empty) break;
    }

    if (!grid_is_empty && !has_intersection) {
        return false; // Not a good placement for subsequent words without an intersection
    }

    return true; // Can be placed
}

// Places a word into the grid
void place_word(WordInfo *word_info, int r_start, int c_start, char orientation) {
    if (orientation == 'H') {
        for (int i = 0; i < word_info->length; i++) {
            grid[r_start][c_start + i] = word_info->word[i];
        }
    } else { // Vertical
        for (int i = 0; i < word_info->length; i++) {
            grid[r_start + i][c_start] = word_info->word[i];
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define GRID_SIZE 10
#define MAX_WORDS 10
#define MAX_ATTEMPTS 50

char grid[GRID_SIZE][GRID_SIZE];

char *words[MAX_WORDS] = {
    "CAT", "DOG", "BIRD", "FISH", "LION", "TIGER", "HORSE", "SHEEP", "GOAT", "MOUSE"
};
int num_words = 10;

void init_grid() {
    for (int i = 0; i < GRID_SIZE; ++i)
        for (int j = 0; j < GRID_SIZE; ++j)
            grid[i][j] = ' ';
}

void print_grid() {
    printf("\n");
    for (int i = 0; i < GRID_SIZE; ++i) {
        for (int j = 0; j < GRID_SIZE; ++j) {
            printf(" %c", grid[i][j]);
        }
        printf("\n");
    }
    printf("\n");
}

// Check if a word can be placed at given position with given direction
// direction: 0 = horizontal, 1 = vertical
int can_place_word(const char *word, int row, int col, int direction) {
    int len = strlen(word);
    if (direction == 0) {
        if (col + len > GRID_SIZE)
            return 0;
        for (int i = 0; i < len; ++i) {
            char c = grid[row][col + i];
            if (c != ' ' && c != word[i])
                return 0;
        }
    } else {
        if (row + len > GRID_SIZE)
            return 0;
        for (int i = 0; i < len; ++i) {
            char c = grid[row + i][col];
            if (c != ' ' && c != word[i])
                return 0;
        }
    }
    return 1;
}

// Place the word on the grid
void place_word(const char *word, int row, int col, int direction) {
    int len = strlen(word);
    if (direction == 0) {
        for (int i = 0; i < len; ++i) {
            grid[row][col + i] = word[i];
        }
    } else {
        for (int i = 0; i < len; ++i) {
            grid[row + i][col] = word[i];
        }
    }
}

void shuffle_words() {
    for (int i = num_words - 1; i > 0; --i) {
        int j = rand() % (i + 1);
        char *tmp = words[i];
        words[i] = words[j];
        words[j] = tmp;
    }
}

int main() {
    srand((unsigned int) time(NULL));
    init_grid();
    shuffle_words();

    for (int w = 0; w < num_words; ++w) {
        int placed = 0;
        for (int attempt = 0; attempt < MAX_ATTEMPTS && !placed; ++attempt) {
            int direction = rand() % 2; // 0 = horizontal, 1 = vertical
            int len = strlen(words[w]);
            int row = (direction == 0) ? rand() % GRID_SIZE : rand() % (GRID_SIZE - len + 1);
            int col = (direction == 0) ? rand() % (GRID_SIZE - len + 1) : rand() % GRID_SIZE;

            if (can_place_word(words[w], row, col, direction)) {
                place_word(words[w], row, col, direction);
                placed = 1;
            }
        }
        if (!placed) {
            printf("Could not place word: %s\n", words[w]);
        }
    }

    printf("Random Crossword Puzzle:\n");
    print_grid();

    printf("Word List:\n");
    for (int i = 0; i < num_words; ++i) {
        printf("%s\n", words[i]);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define GRID_SIZE 10
#define MAX_WORD_LENGTH 10
#define MAX_WORDS 10

typedef struct {
    char word[MAX_WORD_LENGTH + 1];
    int x, y;
    char direction; // 'H' for horizontal, 'V' for vertical
} WordPlacement;

void initializeGrid(char grid[GRID_SIZE][GRID_SIZE]) {
    for (int i = 0; i < GRID_SIZE; i++)
        for (int j = 0; j < GRID_SIZE; j++)
            grid[i][j] = '.';
}

int canPlaceHorizontally(char grid[GRID_SIZE][GRID_SIZE], char *word, int x, int y) {
    int len = strlen(word);

    if (y + len > GRID_SIZE) return 0;  // Word extends beyond grid horizontally.

    for (int i = 0; i < len; i++) {
        if (grid[x][y + i] != '.' && grid[x][y + i] != word[i])
            return 0;
    }
    return 1;
}

int canPlaceVertically(char grid[GRID_SIZE][GRID_SIZE], char *word, int x, int y) {
    int len = strlen(word);

    if (x + len > GRID_SIZE) return 0;  // Word extends beyond grid vertically.

    for (int i = 0; i < len; i++) {
        if (grid[x + i][y] != '.' && grid[x + i][y] != word[i])
            return 0;
    }
    return 1;
}

void placeWordHorizontally(char grid[GRID_SIZE][GRID_SIZE], char *word, int x, int y) {
    for (int i = 0; word[i] != '\0'; i++) {
        grid[x][y + i] = word[i];
    }
}

void placeWordVertically(char grid[GRID_SIZE][GRID_SIZE], char *word, int x, int y) {
    for (int i = 0; word[i] != '\0'; i++) {
        grid[x + i][y] = word[i];
    }
}

void printGrid(char grid[GRID_SIZE][GRID_SIZE]) {
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            printf("%c ", grid[i][j]);
        }
        printf("\n");
    }
}

void generateCrossword(char grid[GRID_SIZE][GRID_SIZE], char words[MAX_WORDS][MAX_WORD_LENGTH + 1], int wordCount) {
    srand(time(NULL)); // Initialize random seed
    int placedWords = 0;

    while (placedWords < wordCount) {
        char *word = words[placedWords];
        int x = rand() % GRID_SIZE;
        int y = rand() % GRID_SIZE;
        int direction = rand() % 2; // 0 for horizontal, 1 for vertical

        if (direction == 0 && canPlaceHorizontally(grid, word, x, y)) {
            placeWordHorizontally(grid, word, x, y);
            placedWords++;
        } else if (direction == 1 && canPlaceVertically(grid, word, x, y)) {
            placeWordVertically(grid, word, x, y);
            placedWords++;
        }
    }
}

