        row = rand() % (GRID_SIZE - wordLength);
        col = rand() % GRID_SIZE;
        for (int i = 0; i < wordLength; i++) {
            if (grid[row + i][col] != '.' && grid[row + i][col] != word[i]) {
                return 0; // Collision
            }
        }
        for (int i = 0; i < wordLength; i++) {
