// Structure to represent a word
typedef struct {
    char word[MAX_WORD_LENGTH];
    int length;
} Word;

// Function to generate a random crossword puzzle
void generateCrossword(Word words[], int numWords) {
    // Initialize the grid with empty cells
    char grid[GRID_SIZE][GRID_SIZE];
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            grid[i][j] = '-';
        }
    }

    // Randomly place each word in the grid
    srand(time(NULL)); // seed the random number generator
    for (int i = 0; i < numWords; i++) {
        // Randomly choose a direction (0: across, 1: down)
        int direction = rand() % 2;
        int row, col;

        // Randomly choose a starting position
        if (direction == 0) { // across
            row = rand() % GRID_SIZE;
            col = rand() % (GRID_SIZE - words[i].length + 1);
        } else { // down
            row = rand() % (GRID_SIZE - words[i].length + 1);
            col = rand() % GRID_SIZE;
        }

        // Place the word in the grid
        for (int j = 0; j < words[i].length; j++) {
            if (direction == 0) { // across
                grid[row][col + j] = words[i].word[j];
            } else { // down
                grid[row + j][col] = words[i].word[j];
            }
        }

        // Print the updated grid
        printf("\nUpdated grid:\n");
        for (int k = 0; k < GRID_SIZE; k++) {
            for (int l = 0; l < GRID_SIZE; l++) {
                printf("%c ", grid[k][l]);
            }
            printf("\n");
        }
    }
}

// Function to load words from a file
int loadWords(char *filename, Word words[]) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file %s\n", filename);
        return 0;
    }

    int numWords = 0;
    char word[MAX_WORD_LENGTH];
    while (fgets(word, MAX_WORD_LENGTH, file) != NULL) {
        // Remove the newline character
        word[strcspn(word, "\n")] = 0;

        // Store the word and its length
        strcpy(words[numWords].word, word);
        words[numWords].length = strlen(word);
        numWords++;

        if (numWords >= MAX_WORDS) {
            printf("Maximum number of words reached\n");
            break;
        }
    }

    fclose(file);
    return numWords;
}

