void initializeGrid(char grid[GRID_SIZE][GRID_SIZE]) {
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            grid[i][j] = '-';
        }
    }
}

void printGrid(char grid[GRID_SIZE][GRID_SIZE]) {
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            printf("%c ", grid[i][j]);
        }
        printf("\n");
    }
}

int placeWord(char grid[GRID_SIZE][GRID_SIZE], const char *word, int *x, int *y, int direction) {
    int length = strlen(word);
    int startX, startY;

    // Try to find a valid position for the word
    while (1) {
        startX = rand() % (GRID_SIZE - (direction == 0 ? length : 1));
        startY = rand() % (GRID_SIZE - (direction == 1 ? length : 1));

        *x = startX;
        *y = startY;

        int valid = 1;
        for (int i = 0; i < length; i++) {
            int newX = startX + (direction == 0 ? i : 0);
            int newY = startY + (direction == 1 ? i : 0);

            if (grid[newY][newX] != '-' && grid[newY][newX] != word[i]) {
                valid = 0;
                break;
            }
        }

        if (valid) {
            // Place the word
            for (int i = 0; i < length; i++) {
                int newX = startX + (direction == 0 ? i : 0);
                int newY = startY + (direction == 1 ? i : 0);
                grid[newY][newX] = word[i];
            }
            return 1;
        }
    }
}

int generateCrossword(char grid[GRID_SIZE][GRID_SIZE], const char *words[], int numWords) {
    // Shuffle the word list
    for (int i = 0; i < numWords; i++) {
        int j = rand() % numWords;
        char *temp = words[i];
        words[i] = words[j];
        words[j] = temp;
    }

    // Place the first word randomly
    int x, y, direction;
    if (!placeWord(grid, words[0], &x, &y, direction = rand() % 2)) {
        return 0;
    }

    // Place the remaining words
    for (int i = 1; i < numWords; i++) {
        int placed = 0;
        for (int attempts = 0; attempts < 100; attempts++) {
            if (placeWord(grid, words[i], &x, &y, rand() % 2)) {
                placed = 1;
                break;
            }
        }
        if (!placed) {
            clearGrid(grid);
            return 0;
        }
    }

    return 1;
}

void clearGrid(char grid[GRID_SIZE][GRID_SIZE]) {
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            grid[i][j] = '-';
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

#define DUNGEON_WIDTH 20
#define DUNGEON_HEIGHT 15
#define MAX_ROOMS 10
#define MIN_ROOM_SIZE 3
#define MAX_ROOM_SIZE 8

// Tile types
typedef enum {
    TILE_WALL,
    TILE_FLOOR,
    TILE_DOOR,
    TILE_PLAYER_START,
    TILE_EXIT
} TileType;

// Room structure
typedef struct {
    int x, y;       // Top-left corner
    int width, height;
} Room;

// Dungeon map
TileType dungeon[DUNGEON_HEIGHT][DUNGEON_WIDTH];
Room rooms[MAX_ROOMS];
int num_rooms = 0;

// Function prototypes
void initialize_dungeon();
bool is_valid_room_placement(Room* room);
void create_room(Room* room);
void create_corridor(Room* room1, Room* room2);
void print_dungeon();
void generate_dungeon();

// Initialize dungeon with walls
void initialize_dungeon() {
    for (int y = 0; y < DUNGEON_HEIGHT; y++) {
        for (int x = 0; x < DUNGEON_WIDTH; x++) {
            dungeon[y][x] = TILE_WALL;
        }
    }
}

// Check if a room can be placed without overlapping
bool is_valid_room_placement(Room* room) {
    // Check room is within dungeon bounds
    if (room->x < 1 || room->x + room->width >= DUNGEON_WIDTH - 1 ||
        room->y < 1 || room->y + room->height >= DUNGEON_HEIGHT - 1) {
        return false;
    }

    // Check for overlap with existing rooms
    for (int i = 0; i < num_rooms; i++) {
        Room* existing_room = &rooms[i];
        if (!(room->x + room->width < existing_room->x ||
              room->x > existing_room->x + existing_room->width ||
              room->y + room->height < existing_room->y ||
              room->y > existing_room->y + existing_room->height)) {
            return false;
        }
    }
    return true;
}

// Create a room in the dungeon
void create_room(Room* room) {
    for (int y = room->y; y < room->y + room->height; y++) {
        for (int x = room->x; x < room->x + room->width; x++) {
            dungeon[y][x] = TILE_FLOOR;
        }
    }
}

// Create a corridor between two rooms
void create_corridor(Room* room1, Room* room2) {
    int x1 = room1->x + room1->width / 2;
    int y1 = room1->y + room1->height / 2;
    int x2 = room2->x + room2->width / 2;
    int y2 = room2->y + room2->height / 2;

    // Horizontal passage
    int start_x = (x1 < x2) ? x1 : x2;
    int end_x = (x1 > x2) ? x1 : x2;
    for (int x = start_x; x <= end_x; x++) {
        dungeon[y1][x] = TILE_FLOOR;
    }

    // Vertical passage
    int start_y = (y1 < y2) ? y1 : y2;
    int end_y = (y1 > y2) ? y1 : y2;
    for (int y = start_y; y <= end_y; y++) {
        dungeon[y][x2] = TILE_FLOOR;
    }
}

// Print the dungeon layout
void print_dungeon() {
    for (int y = 0; y < DUNGEON_HEIGHT; y++) {
        for (int x = 0; x < DUNGEON_WIDTH; x++) {
            switch (dungeon[y][x]) {
                case TILE_WALL:   printf("#"); break;
                case TILE_FLOOR:  printf("."); break;
                case TILE_DOOR:   printf("+"); break;
                case TILE_PLAYER_START: printf("@"); break;
                case TILE_EXIT:   printf("E"); break;
            }
        }
        printf("\n");
    }
}

// Generate dungeon layout
void generate_dungeon() {
    initialize_dungeon();
    srand(time(NULL));

    // Generate rooms
    while (num_rooms < MAX_ROOMS) {
        Room room;
        room.width = MIN_ROOM_SIZE + rand() % (MAX_ROOM_SIZE - MIN_ROOM_SIZE + 1);
        room.height = MIN_ROOM_SIZE + rand() % (MAX_ROOM_SIZE - MIN_ROOM_SIZE + 1);
        room.x = 1 + rand() % (DUNGEON_WIDTH - room.width - 2);
        room.y = 1 + rand() % (DUNGEON_HEIGHT - room.height - 2);

        if (is_valid_room_placement(&room)) {
            create_room(&room);
            rooms[num_rooms++] = room;
        }
    }

    // Connect rooms with corridors
    for (int i = 1; i < num_rooms; i++) {
        create_corridor(&rooms[i-1], &rooms[i]);
    }

    // Place player start and exit
    dungeon[rooms[0].y + 1][rooms[0].x + 1] = TILE_PLAYER_START;
    dungeon[rooms[num_rooms-1].y + rooms[num_rooms-1].height - 2]
           [rooms[num_rooms-1].x + rooms[num_rooms-1].width - 2] = TILE_EXIT;
}

int main() {
    generate_dungeon();
    print_dungeon();
    return 0;
}

#include <stdio.h>
