// Define the dungeon cell types
typedef enum {
    EMPTY,
    WALL,
    ROOM,
    CORRIDOR
} CellType;

// Function to initialize the dungeon with walls
void initializeDungeon(CellType dungeon[HEIGHT][WIDTH]) {
    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            dungeon[y][x] = WALL;
        }
    }
}

// Function to carve a room in the dungeon
void carveRoom(CellType dungeon[HEIGHT][WIDTH], int x, int y, int width, int height) {
    for (int i = y; i < y + height; i++) {
        for (int j = x; j < x + width; j++) {
            if (i >= 0 && i < HEIGHT && j >= 0 && j < WIDTH) {
                dungeon[i][j] = ROOM;
            }
        }
    }
}

// Function to carve a horizontal corridor
void carveHorizontalCorridor(CellType dungeon[HEIGHT][WIDTH], int x1, int x2, int y) {
    for (int x = x1; x <= x2; x++) {
        if (x >= 0 && x < WIDTH && y >= 0 && y < HEIGHT) {
            dungeon[y][x] = CORRIDOR;
        }
    }
}

// Function to carve a vertical corridor
void carveVerticalCorridor(CellType dungeon[HEIGHT][WIDTH], int y1, int y2, int x) {
    for (int y = y1; y <= y2; y++) {
        if (y >= 0 && y < HEIGHT && x >= 0 && x < WIDTH) {
            dungeon[y][x] = CORRIDOR;
        }
    }
}

// Function to print the dungeon
void printDungeon(CellType dungeon[HEIGHT][WIDTH]) {
    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            switch (dungeon[y][x]) {
                case EMPTY:
                    printf(" ");
                    break;
                case WALL:
                    printf("#");
                    break;
                case ROOM:
                    printf(".");
                    break;
                case CORRIDOR:
                    printf("+");
                    break;
            }
        }
        printf("\n");
    }
}

