#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h> // For true/false

// --- Configuration ---
#define DUNGEON_WIDTH 60
#define DUNGEON_HEIGHT 25
#define MAX_ROOMS 15
#define MIN_ROOM_SIZE 5
#define MAX_ROOM_SIZE 12
#define WALL '#'
#define FLOOR '.'
#define PLAYER_START '@'
#define EXIT_POINT 'E'

// --- Structures ---
typedef struct {
    int x1, y1, x2, y2; // Top-left (x1, y1), bottom-right (x2, y2)
    int width, height;
    int center_x, center_y;
} Room;

// --- Global Dungeon Array ---
char dungeon[DUNGEON_HEIGHT][DUNGEON_WIDTH];
Room rooms[MAX_ROOMS];
int num_rooms = 0;

// --- Function Prototypes ---
void initialize_dungeon();
void carve_rooms();
void create_room(int x, int y, int w, int h);
bool intersect(Room r1, Room r2);
bool place_room(int x, int y, int w, int h);
void connect_rooms();
void connect_two_rooms(Room r1, Room r2);
void place_player_and_exit();
void print_dungeon();
void draw_horizontal_corridor(int x1, int x2, int y);
void draw_vertical_corridor(int y1, int y2, int x);


// --- Main Function ---
int main() {
    srand(time(NULL)); // Seed the random number generator

    printf("Generating a new dungeon...\n");

    initialize_dungeon();
    carve_rooms();
    connect_rooms();
    place_player_and_exit();
    print_dungeon();

    printf("\nLegend:\n");
    printf("%c: Wall\n", WALL);
    printf("%c: Floor\n", FLOOR);
    printf("%c: Player Start\n", PLAYER_START);
    printf("%c: Exit\n", EXIT_POINT);

    return 0;
}

// --- Function Implementations ---

// Fills the entire dungeon with walls
void initialize_dungeon() {
    for (int y = 0; y < DUNGEON_HEIGHT; y++) {
        for (int x = 0; x < DUNGEON_WIDTH; x++) {
            dungeon[y][x] = WALL;
        }
    }
}

// Carves a rectangular room in the dungeon array
void create_room(int x, int y, int w, int h) {
    for (int dy = 0; dy < h; dy++) {
        for (int dx = 0; dx < w; dx++) {
            if (y + dy < DUNGEON_HEIGHT && x + dx < DUNGEON_WIDTH) {
                dungeon[y + dy][x + dx] = FLOOR;
            }
        }
    }
}

// Checks if two rooms intersect (including a 1-unit buffer)
bool intersect(Room r1, Room r2) {
    // Add a 1-unit buffer (for walls or corridors)
    return !(r2.x1 > r1.x2 + 1 ||
             r2.x2 < r1.x1 - 1 ||
             r2.y1 > r1.y2 + 1 ||
             r2.y2 < r1.y1 - 1);
}

// Tries to place a room. Returns true if successful, false otherwise (e.g., collision)
bool place_room(int x, int y, int w, int h) {
    // Create a temporary room struct for collision checking
    Room new_room_candidate = {x, y, x + w - 1, y + h - 1, w, h, x + w / 2, y + h / 2};

    // Check bounds
    if (new_room_candidate.x2 >= DUNGEON_WIDTH - 1 || new_room_candidate.y2 >= DUNGEON_HEIGHT - 1 ||
        new_room_candidate.x1 <= 0 || new_room_candidate.y1 <= 0) {
        return false; // Too close to the edge or out of bounds
    }

    // Check for intersections with existing rooms
    for (int i = 0; i < num_rooms; i++) {
        if (intersect(rooms[i], new_room_candidate)) {
            return false; // Collision detected
        }
    }

    // If no collision and within bounds, create the room
    create_room(x, y, w, h);
    rooms[num_rooms] = new_room_candidate;
    num_rooms++;
    return true;
}

// Attempts to carve random rooms
void carve_rooms() {
    for (int i = 0; i < MAX_ROOMS * 2; i++) { // Try more times than MAX_ROOMS to account for failures
        int w = (rand() % (MAX_ROOM_SIZE - MIN_ROOM_SIZE + 1)) + MIN_ROOM_SIZE;
        int h = (rand() % (MAX_ROOM_SIZE - MIN_ROOM_SIZE + 1)) + MIN_ROOM_SIZE;
        int x = rand() % (DUNGEON_WIDTH - w - 1) + 1;  // +1 and -1 to ensure room is not on edge (leaves space for walls)
        int y = rand() % (DUNGEON_HEIGHT - h - 1) + 1; // +1 and -1 to ensure room is not on edge

        if (num_rooms < MAX_ROOMS) {
            place_room(x, y, w, h);
        } else {
            break; // Max rooms reached
        }
    }
}

// Draws a horizontal corridor
void draw_horizontal_corridor(int x1, int x2, int y) {
    if (x1 > x2) { int temp = x1; x1 = x2; x2 = temp; } // Ensure x1 is smaller
    for (int x = x1; x <= x2; x++) {
        if (x >= 0 && x < DUNGEON_WIDTH && y >= 0 && y < DUNGEON_HEIGHT) {
            if (dungeon[y][x] == WALL) { // Only carve if it's a wall
                 dungeon[y][x] = FLOOR;
            }
        }
    }
}

// Draws a vertical corridor
void draw_vertical_corridor(int y1, int y2, int x) {
    if (y1 > y2) { int temp = y1; y1 = y2; y2 = temp; } // Ensure y1 is smaller
    for (int y = y1; y <= y2; y++) {
        if (x >= 0 && x < DUNGEON_WIDTH && y >= 0 && y < DUNGEON_HEIGHT) {
            if (dungeon[y][x] == WALL) { // Only carve if it's a wall
                dungeon[y][x] = FLOOR;
            }
        }
    }
}

// Connects two specified rooms with corridors
void connect_two_rooms(Room r1, Room r2) {
    int x1 = r1.center_x;
    int y1 = r1.center_y;
    int x2 = r2.center_x;
    int y2 = r2.center_y;

    // Randomly decide direction first (H then V or V then H)
    if (rand() % 2 == 0) { // Horizontal then Vertical
        draw_horizontal_corridor(x1, x2, y1);
        draw_vertical_corridor(y1, y2, x2);
    } else { // Vertical then Horizontal
        draw_vertical_corridor(y1, y2, x1);
        draw_horizontal_corridor(x1, x2, y2);
    }
}

// Connects all rooms (or attempts to)
void connect_rooms() {
    if (num_rooms < 2) return;

    // A simple method: Connect each room to its "closest" un-connected room.
    // This isn't perfect for guaranteed connectivity but is simple.
    // For a more robust solution, you might use a Minimum Spanning Tree (MST) algorithm
    // like Prim's or Kruskal's, where rooms are nodes and distances are edge weights.

    // For simplicity, let's just connect each room to the next one in the array
    // and sometimes to a random other room.
    for (int i = 0; i < num_rooms - 1; i++) {
        connect_two_rooms(rooms[i], rooms[i+1]);
        // Add some extra random connections to reduce isolated areas
        if (rand() % 4 == 0 && num_rooms > 2) { // 25% chance of extra connection
            int other_room_index = rand() % num_rooms;
            if (other_room_index != i && other_room_index != i + 1) {
                connect_two_rooms(rooms[i], rooms[other_room_index]);
            }
        }
    }
}

// Places the player and the exit randomly within existing floor tiles
void place_player_and_exit() {
    int player_x, player_y;
    int exit_x, exit_y;
    bool placed_player = false;
    bool placed_exit = false;

    // Place player
    while (!placed_player) {
        player_x = rand() % DUNGEON_WIDTH;
        player_y = rand() % DUNGEON_HEIGHT;
        if (dungeon[player_y][player_x] == FLOOR) {
            dungeon[player_y][player_x] = PLAYER_START;
            placed_player = true;
        }
    }

    // Place exit (ensure it's not on the player's spot)
    while (!placed_exit) {
        exit_x = rand() % DUNGEON_WIDTH;
        exit_y = rand() % DUNGEON_HEIGHT;
        if (dungeon[exit_y][exit_x] == FLOOR) { // Make sure it's a floor tile
            dungeon[exit_y][exit_x] = EXIT_POINT;
            placed_exit = true;
        }
    }
}

// Prints the dungeon to stdout
void print_dungeon() {
    for (int y = 0; y < DUNGEON_HEIGHT; y++) {
        for (int x = 0; x < DUNGEON_WIDTH; x++) {
            printf("%c", dungeon[y][x]);
        }
        printf("\n");
    }
}

#include <stdio.h>
