#include <time.h>

#define WIDTH  40
#define HEIGHT 20
#define NUM_ROOMS 8
#define MIN_ROOM_SIZE 3
#define MAX_ROOM_SIZE 7
#define NUM_TREASURES 5

typedef struct {
    int x, y, w, h;
} Room;

char dungeon[HEIGHT][WIDTH];

// Utility function
int rand_in_range(int min, int max) {
    return min + rand() % (max - min + 1);
}

// Fill dungeon with walls
void fill_dungeon() {
    for (int y = 0; y < HEIGHT; ++y)
        for (int x = 0; x < WIDTH; ++x)
            dungeon[y][x] = '#';
}

// Carve out a room
void carve_room(Room *r) {
    for (int y = r->y; y < r->y + r->h && y < HEIGHT-1; ++y) {
        for (int x = r->x; x < r->x + r->w && x < WIDTH-1; ++x) {
            dungeon[y][x] = '.';
        }
    }
}

// Connects two points with a corridor
void carve_corridor(int x1, int y1, int x2, int y2) {
    int x = x1;
    int y = y1;

    while (x != x2) {
        dungeon[y][x] = '.';
        x += (x2 > x) ? 1 : -1;
    }
    while (y != y2) {
        dungeon[y][x] = '.';
        y += (y2 > y) ? 1 : -1;
    }
}

// Check if a room overlaps existing rooms
int check_overlap(Room *rooms, int num, Room *test) {
    for (int i = 0; i < num; ++i) {
        if (test->x+test->w <= rooms[i].x || rooms[i].x+rooms[i].w <= test->x ||
            test->y+test->h <= rooms[i].y || rooms[i].y+rooms[i].h <= test->y)
            continue;
        return 1; // Overlaps
    }
    return 0; // No overlap
}

void place_treasures(int num) {
    for (int t = 0; t < num; ) {
        int x = rand_in_range(1, WIDTH-2);
        int y = rand_in_range(1, HEIGHT-2);
        if (dungeon[y][x] == '.') {
            dungeon[y][x] = '$';
            ++t;
        }
    }
}

int main() {
    srand(time(NULL));
    fill_dungeon();

    Room rooms[NUM_ROOMS];
    int num_rooms = 0;

    // Generate rooms
    for (int r = 0; r < NUM_ROOMS; ++r) {
        Room new_room;
        new_room.w = rand_in_range(MIN_ROOM_SIZE, MAX_ROOM_SIZE);
        new_room.h = rand_in_range(MIN_ROOM_SIZE, MAX_ROOM_SIZE);
        new_room.x = rand_in_range(1, WIDTH - new_room.w - 2);
        new_room.y = rand_in_range(1, HEIGHT - new_room.h - 2);

        if (!check_overlap(rooms, num_rooms, &new_room)) {
            carve_room(&new_room);

            // Connect to previous room
            if (num_rooms > 0) {
                int prev_x = rooms[num_rooms-1].x + rooms[num_rooms-1].w/2;
                int prev_y = rooms[num_rooms-1].y + rooms[num_rooms-1].h/2;
                int new_x = new_room.x + new_room.w/2;
                int new_y = new_room.y + new_room.h/2;
                carve_corridor(prev_x, prev_y, new_x, new_y);
            }
            rooms[num_rooms++] = new_room;
        } // else try again with next r
    }

    // Place player at center of first room
    int px = rooms[0].x + rooms[0].w/2;
    int py = rooms[0].y + rooms[0].h/2;
    dungeon[py][px] = '@';

    // Place exit at last room
    int ex = rooms[num_rooms-1].x + rooms[num_rooms-1].w/2;
    int ey = rooms[num_rooms-1].y + rooms[num_rooms-1].h/2;
    dungeon[ey][ex] = 'E';

    // Place treasures
    place_treasures(NUM_TREASURES);

    // Print dungeon
    for (int y = 0; y < HEIGHT; ++y) {
        for (int x = 0; x < WIDTH; ++x) {
            putchar(dungeon[y][x]);
        }
        putchar('\n');
    }

    return 0;
}

