int canPlaceRoom(int x, int y, int width, int height) {
    if (x + width >= WIDTH || y + height >= HEIGHT)
        return 0; // Out of bounds

    for (int j = y; j < y + height; j++) {
        for (int i = x; i < x + width; i++) {
            if (dungeon[j][i] != '#') // Space is already used
                return 0;
        }
    }
    return 1; // It is possible to place the room
}

void placeRoom(int x, int y, int width, int height) {
    for (int j = y; j < y + height; j++) {
        for (int i = x; i < x + width; i++) {
            dungeon[j][i] = '.'; // Create the room
        }
    }
}

void connectRooms(Room a, Room b) {
    int x1 = a.x + a.width / 2;
    int y1 = a.y + a.height / 2;
    int x2 = b.x + b.width / 2;
    int y2 = b.y + b.height / 2;

    while (x1 != x2) {
        dungeon[y1][x1] = 'D'; // Create a door
        x1 += (x2 > x1) ? 1 : -1; // Move horizontally
    }
    while (y1 != y2) {
        dungeon[y1][x1] = 'D'; // Create a door
        y1 += (y2 > y1) ? 1 : -1; // Move vertically
    }
}

