#include <time.h>

// Define constants for dungeon size and cell types
#define MAX_SIZE 20
#define ROOM 0
#define CORRIDOR 1
#define WALL 2

// Structure to represent a cell in the dungeon
typedef struct {
    int type;     // Cell type (ROOM, CORRIDOR, or WALL)
    int visited;  // Flag indicating whether the cell has been visited
} Cell;

// Function to initialize the dungeon with walls and random rooms
void initializeDungeon(Cell dungeon[MAX_SIZE][MAX_SIZE]) {
    for (int i = 0; i < MAX_SIZE; i++) {
        for (int j = 0; j < MAX_SIZE; j++) {
            dungeon[i][j].type = WALL;
            dungeon[i][j].visited = 0;
        }
    }

    // Create a few random rooms
    for (int i = 0; i < 5; i++) {
        int x = rand() % MAX_SIZE;
        int y = rand() % MAX_SIZE;
        dungeon[x][y].type = ROOM;
        dungeon[x][y].visited = 1;
    }
}

// Function to generate corridors between rooms
void generateCorridors(Cell dungeon[MAX_SIZE][MAX_SIZE]) {
    for (int i = 0; i < MAX_SIZE; i++) {
        for (int j = 0; j < MAX_SIZE; j++) {
            if (dungeon[i][j].type == ROOM) {
                // Check all neighboring cells
                if (i > 0 && dungeon[i-1][j].type == ROOM && rand() % 2 == 0) {
                    dungeon[i-1][j].type = CORRIDOR;
                    dungeon[i-1][j].visited = 1;
                }
                if (i < MAX_SIZE - 1 && dungeon[i+1][j].type == ROOM && rand() % 2 == 0) {
                    dungeon[i+1][j].type = CORRIDOR;
                    dungeon[i+1][j].visited = 1;
                }
                if (j > 0 && dungeon[i][j-1].type == ROOM && rand() % 2 == 0) {
                    dungeon[i][j-1].type = CORRIDOR;
                    dungeon[i][j-1].visited = 1;
                }
                if (j < MAX_SIZE - 1 && dungeon[i][j+1].type == ROOM && rand() % 2 == 0) {
                    dungeon[i][j+1].type = CORRIDOR;
                    dungeon[i][j+1].visited = 1;
                }
            }
        }
    }
}

// Function to print the dungeon layout
void printDungeon(Cell dungeon[MAX_SIZE][MAX_SIZE]) {
    for (int i = 0; i < MAX_SIZE; i++) {
        for (int j = 0; j < MAX_SIZE; j++) {
            if (dungeon[i][j].type == ROOM) {
                printf("R ");
            } else if (dungeon[i][j].type == CORRIDOR) {
                printf("- ");
            } else if (dungeon[i][j].type == WALL) {
                printf("# ");
            }
        }
        printf("\n");
    }
}

int main() {
    srand(time(NULL));  // Initialize random number generator
    Cell dungeon[MAX_SIZE][MAX_SIZE];

    initializeDungeon(dungeon);
    generateCorridors(dungeon);
    printDungeon(dungeon);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define WIDTH 80
#define HEIGHT 40
#define ROOM_MAX_WIDTH 10
#define ROOM_MAX_HEIGHT 7
#define MAX_ROOMS 20

// Directions for movement
enum Direction {
    NORTH,
    SOUTH,
    EAST,
    WEST
};

// Room structure
typedef struct {
    int x, y;
    int width, height;
} Room;

// Dungeon map
char map[HEIGHT][WIDTH];

// Function to clear the map
void clearMap() {
    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            map[y][x] = '#'; // Walls
        }
    }
}

// Function to create a room
void createRoom(Room *room) {
    for (int y = room->y; y < room->y + room->height; y++) {
        for (int x = room->x; x < room->x + room->width; x++) {
            map[y][x] = '.'; // Floor
        }
    }
}

// Function to check if a room can be placed at a given position
int canPlaceRoom(Room *room) {
    for (int y = room->y - 1; y <= room->y + room->height; y++) {
        for (int x = room->x - 1; x <= room->x + room->width; x++) {
            if (x < 0 || x >= WIDTH || y < 0 || y >= HEIGHT || map[y][x] == '.') {
                return 0; // Room overlaps or goes out of bounds
            }
        }
    }
    return 1; // Room can be placed
}

// Function to connect two rooms with a corridor
void connectRooms(Room *room1, Room *room2) {
    int startX = room1->x + room1->width / 2;
    int startY = room1->y + room1->height / 2;
    int endX = room2->x + room2->width / 2;
    int endY = room2->y + room2->height / 2;

    // Create a vertical corridor first
    for (int y = startY; y != endY; y += (endY > startY ? 1 : -1)) {
        map[y][startX] = '-';
    }

    // Then create a horizontal corridor
    for (int x = startX; x != endX; x += (endX > startX ? 1 : -1)) {
        map[endY][x] = '|';
    }
}

// Function to generate random rooms
void generateRooms(Room *rooms, int numRooms) {
    for (int i = 0; i < numRooms; i++) {
        Room room;
        room.width = 3 + rand() % ROOM_MAX_WIDTH;
        room.height = 2 + rand() % ROOM_MAX_HEIGHT;
        room.x = 1 + rand() % (WIDTH - room.width - 1);
        room.y = 1 + rand() % (HEIGHT - room.height - 1);

        while (!canPlaceRoom(&room)) {
            room.width = 3 + rand() % ROOM_MAX_WIDTH;
            room.height = 2 + rand() % ROOM_MAX_HEIGHT;
            room.x = 1 + rand() % (WIDTH - room.width - 1);
            room.y = 1 + rand() % (HEIGHT - room.height - 1);
        }

        rooms[i] = room;
        createRoom(&room);
    }
}

// Function to connect all rooms
void connectAllRooms(Room *rooms, int numRooms) {
    for (int i = 0; i < numRooms - 1; i++) {
        connectRooms(&rooms[i], &rooms[i + 1]);
    }
}

// Function to print the dungeon map
void printMap() {
    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            printf("%c", map[y][x]);
        }
        printf("\n");
    }
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    clearMap(); // Clear the map initially

    Room rooms[MAX_ROOMS];
    generateRooms(rooms, MAX_ROOMS); // Generate random rooms
    connectAllRooms(rooms, MAX_ROOMS); // Connect all the rooms

    printMap(); // Print the dungeon map

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

#define MAZE_SIZE 20
#define START_X 1
#define START_Y 1
#define END_X (MAZE_SIZE - 2)
#define END_Y (MAZE_SIZE - 2)

// Maze cell representation
typedef struct {
    bool wall;
    bool visited;
    int distance;
    int prev_x;
    int prev_y;
} Cell;

// Queue for BFS
typedef struct {
    int x, y;
} QueueItem;

Cell maze[MAZE_SIZE][MAZE_SIZE];
QueueItem queue[MAZE_SIZE * MAZE_SIZE];
int front = 0, rear = 0;

// Directions for movement (right, down, left, up)
int dx[] = {0, 1, 0, -1};
int dy[] = {1, 0, -1, 0};

// Function prototypes
void initialize_maze();
void generate_maze(int x, int y);
void print_maze();
bool find_shortest_path();
void mark_path();

void enqueue(int x, int y) {
    queue[rear].x = x;
    queue[rear].y = y;
    rear++;
}

QueueItem dequeue() {
    return queue[front++];
}

bool is_valid_move(int x, int y) {
    return (x >= 0 && x < MAZE_SIZE && 
            y >= 0 && y < MAZE_SIZE && 
            !maze[x][y].wall && 
            !maze[x][y].visited);
}

void initialize_maze() {
    // Initialize entire maze as walls
    for (int i = 0; i < MAZE_SIZE; i++) {
        for (int j = 0; j < MAZE_SIZE; j++) {
            maze[i][j].wall = true;
            maze[i][j].visited = false;
            maze[i][j].distance = -1;
            maze[i][j].prev_x = -1;
            maze[i][j].prev_y = -1;
        }
    }
}

void generate_maze(int x, int y) {
    maze[x][y].wall = false;
    maze[x][y].visited = true;

    // Random order of directions
    int directions[4] = {0, 1, 2, 3};
    for (int i = 0; i < 4; i++) {
        int j = rand() % 4;
        int temp = directions[i];
        directions[i] = directions[j];
        directions[j] = temp;
    }

    // Recursive maze generation
    for (int i = 0; i < 4; i++) {
        int nx = x + dx[directions[i]] * 2;
        int ny = y + dy[directions[i]] * 2;

        if (nx > 0 && nx < MAZE_SIZE - 1 && 
            ny > 0 && ny < MAZE_SIZE - 1 && 
            !maze[nx][ny].visited) {
            maze[x + dx[directions[i]]][y + dy[directions[i]]].wall = false;
            generate_maze(nx, ny);
        }
    }
}

void print_maze() {
    for (int i = 0; i < MAZE_SIZE; i++) {
        for (int j = 0; j < MAZE_SIZE; j++) {
            if (i == START_X && j == START_Y)
                printf("S ");
            else if (i == END_X && j == END_Y)
                printf("E ");
            else if (maze[i][j].wall)
                printf("# ");
            else
                printf(". ");
        }
        printf("\n");
    }
}

bool find_shortest_path() {
    // Reset visited and distance
    for (int i = 0; i < MAZE_SIZE; i++) {
        for (int j = 0; j < MAZE_SIZE; j++) {
            maze[i][j].visited = false;
            maze[i][j].distance = -1;
            maze[i][j].prev_x = -1;
            maze[i][j].prev_y = -1;
        }
    }

    // Start BFS
    front = rear = 0;
    enqueue(START_X, START_Y);
    maze[START_X][START_Y].visited = true;
    maze[START_X][START_Y].distance = 0;

    while (front < rear) {
        QueueItem current = dequeue();
        int x = current.x;
        int y = current.y;

        // Reached end
        if (x == END_X && y == END_Y)
            return true;

        // Check adjacent cells
        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i];
            int ny = y + dy[i];

            if (is_valid_move(nx, ny)) {
                enqueue(nx, ny);
                maze[nx][ny].visited = true;
                maze[nx][ny].distance = maze[x][y].distance + 1;
                maze[nx][ny].prev_x = x;
                maze[nx][ny].prev_y = y;
            }
        }
    }

    return false;
}

void mark_path() {
    int x = END_X, y = END_Y;
    while (x != START_X || y != START_Y) {
        maze[x][y].wall = false;  // Mark path
        int temp_x = maze[x][y].prev_x;
        int temp_y = maze[x][y].prev_y;
        x = temp_x;
        y = temp_y;
    }
}

int main() {
    srand(time(NULL));

    // Initialize and generate maze
    initialize_maze();
    generate_maze(START_X, START_Y);

    printf("Generated Maze:\n");
    print_maze();

    // Find and mark shortest path
    if (find_shortest_path()) {
        printf("\nShortest Path Found:\n");
        mark_path();
        print_maze();
        printf("\nPath Length: %d\n", maze[END_X][END_Y].distance);
    } else {
        printf("\nNo path found!\n");
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

#define ROWS 10
#define COLS 10

typedef struct {
    int x, y;
} Point;

typedef struct {
    Point parent;
    int dist;
} Node;

int dx[] = {-1, 1, 0, 0};
int dy[] = {0, 0, -1, 1};

void generateMaze(int maze[ROWS][COLS]) {
    srand(time(NULL));
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            maze[i][j] = rand() % 2; // 0 represents a path, 1 represents a wall
        }
    }
    maze[0][0] = 0; // Start point
    maze[ROWS-1][COLS-1] = 0; // End point
}

bool isValid(int x, int y) {
    return x >= 0 && x < ROWS && y >= 0 && y < COLS;
}

void printMaze(int maze[ROWS][COLS]) {
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            printf("%d ", maze[i][j]);
        }
        printf("\n");
    }
}

void printPath(Point path[], int pathLength) {
    for (int i = 0; i < pathLength; i++) {
        printf("(%d, %d) ", path[i].x, path[i].y);
    }
    printf("\n");
}

bool bfs(int maze[ROWS][COLS], Point start, Point end, Point path[], int *pathLength) {
    bool visited[ROWS][COLS] = {false};
    Node nodes[ROWS][COLS];
    Point queue[ROWS * COLS];
    int front = 0, rear = 0;

    queue[rear++] = start;
    visited[start.x][start.y] = true;
    nodes[start.x][start.y].dist = 0;

    while (front < rear) {
        Point current = queue[front++];

        if (current.x == end.x && current.y == end.y) {
            *pathLength = nodes[current.x][current.y].dist;
            Point p = current;
            for (int i = *pathLength - 1; i >= 0; i--) {
                path[i] = p;
                p = nodes[p.x][p.y].parent;
            }
            return true;
        }

        for (int i = 0; i < 4; i++) {
            int nx = current.x + dx[i];
            int ny = current.y + dy[i];

            if (isValid(nx, ny) && maze[nx][ny] == 0 && !visited[nx][ny]) {
                visited[nx][ny] = true;
                nodes[nx][ny].parent = current;
                nodes[nx][ny].dist = nodes[current.x][current.y].dist + 1;
                queue[rear++] = (Point){nx, ny};
            }
        }
    }

    return false;
}

int main() {
    int maze[ROWS][COLS];
    generateMaze(maze);

    printf("Generated Maze:\n");
    printMaze(maze);

    Point start = {0, 0};
    Point end = {ROWS-1, COLS-1};
    Point path[ROWS * COLS];
    int pathLength = 0;

    if (bfs(maze, start, end, path, &pathLength)) {
        printf("Shortest Path:\n");
        printPath(path, pathLength);
    } else {
        printf("No path found!\n");
    }

    return 0;
}

