// --- Maze Characters ---
#define WALL '#'
#define PATH ' '
#define START 'S'
#define END 'E'
#define SOLUTION '.'
#define VISITED_BFS '+' // Temporary marker for BFS

// --- Structure for a cell (used in both generation and pathfinding) ---
typedef struct {
    int x;
    int y;
} Cell;

// --- Queue for BFS ---
typedef struct QueueNode {
    Cell cell;
    struct QueueNode *next;
} QueueNode;

typedef struct {
    QueueNode *front;
    QueueNode *rear;
    int size;
} Queue;

// --- Function Prototypes ---
void initMaze(char maze[MAZE_HEIGHT][MAZE_WIDTH]);
