// Queue functions
void initQueue(Queue *q);
void enqueue(Queue *q, Cell cell);
Cell dequeue(Queue *q);
bool isQueueEmpty(Queue *q);

// Pathfinding functions
bool solveMazeBFS(char maze[MAZE_HEIGHT][MAZE_WIDTH], Cell start, Cell end);
void reconstructPath(char maze[MAZE_HEIGHT][MAZE_WIDTH], int parentX[MAZE_HEIGHT][MAZE_WIDTH], int parentY[MAZE_HEIGHT][MAZE_WIDTH], Cell end);

// Global for BFS parent tracking (can be passed as parameter too)
int parentX[MAZE_HEIGHT][MAZE_WIDTH];
int parentY[MAZE_HEIGHT][MAZE_WIDTH];

int main() {
