// --- Maze Generation Functions ---

void initMaze(char maze[MAZE_HEIGHT][MAZE_WIDTH]) {
    for (int y = 0; y < MAZE_HEIGHT; y++) {
        for (int x = 0; x < MAZE_WIDTH; x++) {
            maze[y][x] = WALL;
        }
    }
}

void generateMaze(char maze[MAZE_HEIGHT][MAZE_WIDTH]) {
    // Start recursion from a random odd coordinate
    // The top-left (1,1) is a common choice for consistency
    generateMazeRecursive(maze, 1, 1);
}

void generateMazeRecursive(char maze[MAZE_HEIGHT][MAZE_WIDTH], int x, int y) {
    maze[y][x] = PATH; // Mark current cell as path

    // Directions: (dx, dy) for right, down, left, up
    int dx[] = {2, 0, -2, 0};
    int dy[] = {0, 2, 0, -2};

    // Fisher-Yates shuffle for directions to randomize
    int directions[4] = {0, 1, 2, 3}; // 0=Right, 1=Down, 2=Left, 3=Up
    for (int i = 3; i > 0; i--) {
        int j = rand() % (i + 1);
        int temp = directions[i];
        directions[i] = directions[j];
        directions[j] = temp;
    }

    for (int i = 0; i < 4; i++) {
        int dir = directions[i];
        int nx = x + dx[dir];
        int ny = y + dy[dir];

        // Check bounds and if the next cell is a wall (unvisited)
        if (nx > 0 && nx < MAZE_WIDTH - 1 && ny > 0 && ny < MAZE_HEIGHT - 1 && maze[ny][nx] == WALL) {
            // Carve path between current cell and next cell
            maze[y + dy[dir] / 2][x + dx[dir] / 2] = PATH;
            generateMazeRecursive(maze, nx, ny);
        }
    }
}

void printMaze(char maze[MAZE_HEIGHT][MAZE_WIDTH]) {
    for (int y = 0; y < MAZE_HEIGHT; y++) {
        for (int x = 0; x < MAZE_WIDTH; x++) {
            printf("%c", maze[y][x]);
        }
        printf("\n");
    }
}

// --- Queue Implementation for BFS ---

void initQueue(Queue *q) {
    q->front = NULL;
    q->rear = NULL;
    q->size = 0;
}

void enqueue(Queue *q, Cell cell) {
    QueueNode *newNode = (QueueNode *)malloc(sizeof(QueueNode));
    if (newNode == NULL) {
        perror("Failed to allocate queue node");
        exit(EXIT_FAILURE);
    }
    newNode->cell = cell;
    newNode->next = NULL;

    if (isQueueEmpty(q)) {
        q->front = newNode;
        q->rear = newNode;
    } else {
        q->rear->next = newNode;
        q->rear = newNode;
    }
    q->size++;
}

Cell dequeue(Queue *q) {
    if (isQueueEmpty(q)) {
        fprintf(stderr, "Error: Dequeue from empty queue.\n");
        exit(EXIT_FAILURE);
    }
    QueueNode *temp = q->front;
    Cell cell = temp->cell;
    q->front = q->front->next;
    if (q->front == NULL) { // Last element dequeued
        q->rear = NULL;
    }
    free(temp);
    q->size--;
    return cell;
}

bool isQueueEmpty(Queue *q) {
    return q->front == NULL;
}

// --- Pathfinding (BFS) Functions ---

bool solveMazeBFS(char maze[MAZE_HEIGHT][MAZE_WIDTH], Cell start, Cell end) {
    Queue q;
    initQueue(&q);

    // Visited array to prevent cycles and redundant processing
    bool visited[MAZE_HEIGHT][MAZE_WIDTH];
    for (int y = 0; y < MAZE_HEIGHT; y++) {
        for (int x = 0; x < MAZE_WIDTH; x++) {
            visited[y][x] = false;
            parentX[y][x] = -1; // Initialize parent pointers
            parentY[y][x] = -1;
        }
    }

    // Enqueue start cell
    enqueue(&q, start);
    visited[start.y][start.x] = true;

    // Directions for moving (up, down, left, right)
    int dx[] = {0, 0, 1, -1};
    int dy[] = {-1, 1, 0, 0};

    while (!isQueueEmpty(&q)) {
        Cell current = dequeue(&q);

        // If we reached the end, reconstruct the path and return true
        if (current.x == end.x && current.y == end.y) {
            reconstructPath(maze, parentX, parentY, end);
            return true;
        }

        // Explore neighbors
        for (int i = 0; i < 4; i++) {
            int nx = current.x + dx[i];
            int ny = current.y + dy[i];

            // Check bounds
            if (nx >= 0 && nx < MAZE_WIDTH && ny >= 0 && ny < MAZE_HEIGHT) {
                // Check if it's a path, not visited, and not a wall (unless it's the end point itself)
                if (!visited[ny][nx] && (maze[ny][nx] == PATH || maze[ny][nx] == END)) {
                    visited[ny][nx] = true;
                    parentX[ny][nx] = current.x;
                    parentY[ny][nx] = current.y;
                    enqueue(&q, (Cell){nx, ny});
                }
            }
        }
    }

    // If the queue becomes empty and we haven't reached the end, no path exists
    return false;
}

void reconstructPath(char maze[MAZE_HEIGHT][MAZE_WIDTH], int parentX[MAZE_HEIGHT][MAZE_WIDTH], int parentY[MAZE_HEIGHT][MAZE_WIDTH], Cell end) {
    Cell current = end;
    // Walk back from end to start using parent pointers
    while (maze[current.y][current.x] != START) {
        if (maze[current.y][current.x] != END) { // Don't overwrite the 'E'
             maze[current.y][current.x] = SOLUTION;
        }

        int prevX = parentX[current.y][current.x];
        int prevY = parentY[current.y][current.x];

        // This check prevents infinite loops if there's an issue with parent tracking or reached start.
        if (prevX == -1 && prevY == -1) break;

        current.x = prevX;
        current.y = prevY;
    }
}

#include <stdio.h>
