#define N 20 // Maze size

// Directions: up, right, down, left
const int DX[4] = {0, 1, 0, -1};
const int DY[4] = {-1, 0, 1, 0};

// For maze generation and pathfinding
#define WALL 1
#define PATH 0
#define VISITED 2
#define SOLUTION 3

int maze[N][N];

// Generate maze using recursive backtracking
void generate_maze(int x, int y) {
    int d[4] = {0, 1, 2, 3};
    // Shuffle directions
    for (int i = 3; i > 0; --i) {
        int j = rand() % (i+1);
        int tmp = d[i]; d[i] = d[j]; d[j] = tmp;
    }
    for (int i = 0; i < 4; ++i) {
        int nx = x + DX[d[i]]*2;
        int ny = y + DY[d[i]]*2;
        if (nx >= 0 && nx < N && ny >= 0 && ny < N && maze[ny][nx] == WALL) {
            maze[y + DY[d[i]]][x + DX[d[i]]] = PATH;
            maze[ny][nx] = PATH;
            generate_maze(nx, ny);
        }
    }
}

// Data structure for BFS
typedef struct {
    int x, y, prev;
} Node;

#define QSIZE (N*N)
Node queue[QSIZE];
int front, back;

// Find shortest path using BFS
// Returns length of path, fills solution array
int bfs_solve(int solution[N][N]) {
    int visited[N][N] = {0};
    int prev_idx[N][N];
    front = back = 0;
    queue[back++] = (Node){0, 0, -1};
    visited[0][0] = 1;
    int found = 0, end_idx = -1;

    while (front < back) {
        Node cur = queue[front++];
        if (cur.x == N-1 && cur.y == N-1) {
            end_idx = front-1;
            found = 1;
            break;
        }
        for (int d = 0; d < 4; ++d) {
            int nx = cur.x + DX[d];
            int ny = cur.y + DY[d];
            if (nx >= 0 && nx < N && ny >= 0 && ny < N &&
                !visited[ny][nx] && maze[ny][nx] == PATH) {
                visited[ny][nx] = 1;
                queue[back] = (Node){nx, ny, front-1};
                prev_idx[ny][nx] = back;
                back++;
            }
        }
    }

    if (!found) return 0;

    // Backtrack to get path and fill solution
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            solution[i][j] = maze[i][j];

    int idx = end_idx;
    int length = 0;
    while (idx != -1) {
        Node n = queue[idx];
        solution[n.y][n.x] = SOLUTION;
        idx = queue[idx].prev;
        length++;
    }
    return length;
}

// Print maze (and path, if present)
void print_maze(int m[N][N]) {
    for (int y = 0; y < N; ++y) {
        for (int x = 0; x < N; ++x) {
            if (m[y][x] == WALL)
                printf("█");
            else if (m[y][x] == SOLUTION)
                printf("\033[1;32m*\033[0m"); // Green path
            else
                printf(" ");
        }
        printf("\n");
    }
}

int main() {
    srand(time(0));

    // Initialize maze with walls
    for (int y = 0; y < N; ++y)
        for (int x = 0; x < N; ++x)
            maze[y][x] = WALL;

    // Start at top-left
    maze[0][0] = PATH;
    generate_maze(0,0);

    printf("Generated maze:\n");
    print_maze(maze);

    int solution[N][N];
    int len = bfs_solve(solution);
    if (len) {
        printf("\nShortest path marked with * (%d steps):\n", len);
        print_maze(solution);
    } else {
        printf("\nNo path found!\n");
    }

    return 0;
}

