void generateMaze(int maze[HEIGHT][WIDTH]) {
    for (int y = 0; y < HEIGHT; y++)
        for (int x = 0; x < WIDTH; x++)
            maze[y][x] = 1; // Set all cells as walls initially

    carveMaze(maze, 1, 1);
    maze[1][0] = 0; // Entrance
    maze[HEIGHT-2][WIDTH-1] = 0; // Exit
}

void carveMaze(int maze[HEIGHT][WIDTH], int x, int y) {
    int dx[] = {2, 0, -2, 0};
    int dy[] = {0, 2, 0, -2};
    int order[4] = {0, 1, 2, 3};

    // Randomize direction order
    for (int i = 0; i < 4; i++) {
        int r = rand() % 4;
        int temp = order[i];
        order[i] = order[r];
        order[r] = temp;
    }

    maze[y][x] = 0; // Carve a cell

    for (int i = 0; i < 4; i++) {
        int nx = x + dx[order[i]];
        int ny = y + dy[order[i]];

        if (inRange(nx, ny) && maze[ny][nx] == 1) {
            maze[y + dy[order[i]]/2][x + dx[order[i]]/2] = 0; // Carve passage
            carveMaze(maze, nx, ny);
        }
    }
}

int inRange(int x, int y) {
    return x > 0 && x < WIDTH && y > 0 && y < HEIGHT;
}

int isWall(int maze[HEIGHT][WIDTH], int x, int y) {
    return maze[y][x] == 1;
}

int findPath(int maze[HEIGHT][WIDTH], Path *path) {
    int visited[HEIGHT][WIDTH] = {0};
    int queue[WIDTH * HEIGHT][2];
    int front = 0, back = 0;
    Point parents[HEIGHT][WIDTH];

    queue[back][0] = 1; queue[back++][1] = 0;
    visited[1][0] = 1;

    while (front < back) {
        int curX = queue[front][0];
        int curY = queue[front][1];
        front++;

        if (curX == WIDTH-1 && curY == HEIGHT-2) {
            // Reached the exit
            Point p = {curX, curY};
            while (!(p.x == 1 && p.y == 0)) {
                path->points[path->size++] = p;
                p = parents[p.y][p.x];
            }
            path->points[path->size++] = (Point){1, 0};
            return 1;
        }

        int dx[] = {-1, 1, 0, 0};
        int dy[] = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nx = curX + dx[i];
            int ny = curY + dy[i];

            if (inRange(nx, ny) && !visited[ny][nx] && !isWall(maze, nx, ny)) {
                queue[back][0] = nx;
                queue[back++][1] = ny;
                visited[ny][nx] = 1;
                parents[ny][nx] = (Point){curX, curY};
            }
        }
    }

    return 0;
}

void printMaze(int maze[HEIGHT][WIDTH], Path *path) {
    char display[HEIGHT][WIDTH];
    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            display[y][x] = maze[y][x] ? '#' : ' ';
        }
    }

    if (path != NULL) {
        for (int i = 0; i < path->size; i++) {
            display[path->points[i].y][path->points[i].x] = 'o';
        }
    }

    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            printf("%c", display[y][x]);
        }
        printf("\n");
    }
}

