bool bfs(Position start, Position end) {
    bool visited[HEIGHT][WIDTH] = {false};
    enqueue(start);
    visited[start.x][start.y] = true;

    int directions[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    while (!isEmpty()) {
        Position pos = dequeue();

        if (pos.x == end.x && pos.y == end.y) {
            return true; // Found the end
        }

        for (int i = 0; i < 4; i++) {
            int newX = pos.x + directions[i][0];
            int newY = pos.y + directions[i][1];

            if (newX >= 0 && newX < HEIGHT && newY >= 0 && newY < WIDTH && 
                maze[newX][newY] == PATH && !visited[newX][newY]) {
                visited[newX][newY] = true;
                enqueue((Position) {newX, newY});
            }
        }
    }
    return false; // No path found
}

