            maze[i][j].x = j;
            maze[i][j].y = i;
            maze[i][j].visited = 0;
            maze[i][j].wall = (i == 0 || i == HEIGHT - 1 || j == 0 || j == WIDTH - 1);
            if (maze[i][j].wall) continue;
            if (rand() % 2) maze[i][j].wall = 1;
        }
    }
