}

// Function to print the maze
void printMaze(Cell maze[HEIGHT][WIDTH]) {
    for (int i = 0; i < HEIGHT; i++) {
        for (int j = 0; j < WIDTH; j++) {
            if (maze[i][j].wall) printf("# ");
            else if (i == 1 && j == 1) printf("S ");
            else if (i == HEIGHT - 2 && j == WIDTH - 2) printf("E ");
            else printf(". ");
        }
        printf("\n");
    }
}

// Structure to represent a point in the maze
typedef struct Point {
    int x, y;
    struct Point* next;
} Point;

// Function to find the shortest path in the maze
Point* findPath(Cell maze[HEIGHT][WIDTH]) {
    Point* start = malloc(sizeof(Point));
    start->x = 1;
    start->y = 1;
    start->next = NULL;

    Point* end = NULL;
    Point* current = start;
    int queueX[HEIGHT * WIDTH], queueY[HEIGHT * WIDTH];
    int head = 0, tail = 0;

    int dirX[4] = {-1, 1, 0, 0};
    int dirY[4] = {0, 0, -1, 1};

    queueX[tail] = start->x;
    queueY[tail] = start->y;
    tail++;

    while (head < tail) {
        int x = queueX[head];
        int y = queueY[head];
        head++;

        if (x == WIDTH - 2 && y == HEIGHT - 2) break;

        for (int i = 0; i < 4; i++) {
            int newX = x + dirX[i];
            int newY = y + dirY[i];
            if (newX < 0 || newX >= WIDTH || newY < 0 || newY >= HEIGHT) continue;
            if (maze[newY][newX].wall || maze[newY][newX].visited) continue;
            maze[newY][newX].visited = 1;

            Point* newPoint = malloc(sizeof(Point));
            newPoint->x = newX;
            newPoint->y = newY;
            newPoint->next = NULL;

            queueX[tail] = newX;
            queueY[tail] = newY;
            tail++;

            Point* temp = current;
            while (temp->next) temp = temp->next;
            temp->next = newPoint;
            current = newPoint;
        }
    }

    Point* path = NULL;
    Point* temp = current;
    while (temp) {
        if (temp == start) {
            path = temp;
            break;
        }
        Point* prev = NULL;
        Point* curr = start;
        while (curr) {
            if (curr->next == temp) {
                prev = curr;
                break;
            }
            curr = curr->next;
        }
        temp = prev;
    }

    return path;
}

// Function to print the shortest path
void printPath(Point* path) {
    while (path) {
        printf("(%d, %d) ", path->x, path->y);
        path = path->next;
    }
    printf("\n");
}

int main() {
    srand(time(NULL));
    Cell maze[HEIGHT][WIDTH];
    generateMaze(maze);
    printf("Maze:\n");
    printMaze(maze);
    Point* path = findPath(maze);
    printf("Shortest Path: ");
    printPath(path);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

#define ROWS 10
#define COLS 10

typedef struct {
    int x, y;
} Point;

typedef struct {
    Point position;
    Point parent;
    int dist;
} Node;

bool is_valid(int x, int y) {
    return x >= 0 && y >= 0 && x < ROWS && y < COLS;
}

bool is_free(int maze[ROWS][COLS], int x, int y) {
    return maze[x][y] == 0;
}

void generate_maze(int maze[ROWS][COLS]) {
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            maze[i][j] = (rand() % 3) == 1 ? 1 : 0; // 1 is a wall, 0 is free space
        }
    }
    // Ensure start and end points are free
    maze[0][0] = 0;
    maze[ROWS - 1][COLS - 1] = 0;
}

void print_maze(int maze[ROWS][COLS], Point start, Point end, bool path[ROWS][COLS]) {
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            if (i == start.x && j == start.y) {
                printf("S");
            } else if (i == end.x && j == end.y) {
                printf("E");
            } else if (path[i][j]) {
                printf("x");
            } else if (maze[i][j] == 1) {
                printf("#");
            } else {
                printf(" ");
            }
        }
        printf("\n");
    }
}

bool bfs(int maze[ROWS][COLS], Point start, Point end, bool path[ROWS][COLS]) {
    Node queue[ROWS * COLS];
    int front = 0, rear = 0;
    bool visited[ROWS][COLS] = {false};
    queue[rear++] = (Node){start, {-1, -1}, 0};
    visited[start.x][start.y] = true;

    while (front < rear) {
        Node current = queue[front++];
        if (current.position.x == end.x && current.position.y == end.y) {
            // Reconstruct the path
            Point p = current.position;
            while (p.x != -1 && p.y != -1) {
                path[p.x][p.y] = true;
                p = current.parent;
            }
            return true;
        }

        int dx[] = {0, 0, 1, -1};
        int dy[] = {1, -1, 0, 0};

        for (int i = 0; i < 4; i++) {
            int new_x = current.position.x + dx[i];
            int new_y = current.position.y + dy[i];

            if (is_valid(new_x, new_y) && is_free(maze, new_x, new_y) && !visited[new_x][new_y]) {
                visited[new_x][new_y] = true;
                queue[rear++] = (Node){{new_x, new_y}, current.position, current.dist + 1};
            }
        }
    }

    return false;
}

int main() {
    srand(time(NULL));

    int maze[ROWS][COLS] = {0};
    Point start = {0, 0};
    Point end = {ROWS - 1, COLS - 1};
    bool path[ROWS][COLS] = {false};

    generate_maze(maze);

    printf("Generated Maze:\n");
    print_maze(maze, start, end, path);

    if (bfs(maze, start, end, path)) {
        printf("\nPath found:\n");
        print_maze(maze, start, end, path);
    } else {
        printf("\nNo path found.\n");
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>

#define MAX_URL_LENGTH 1000
#define SHORT_URL_LENGTH 8
#define MAX_ENTRIES 1000

// URL mapping structure
typedef struct {
    char original_url[MAX_URL_LENGTH];
    char short_url[SHORT_URL_LENGTH + 1];
} URLMapping;

// Global array to store URL mappings
URLMapping url_mappings[MAX_ENTRIES];
int mapping_count = 0;

// Function to generate MD5 hash
char* generate_md5_hash(const char* url) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    static char md5_string[33];

    // Create MD5 hash
    MD5_CTX md5_ctx;
    MD5_Init(&md5_ctx);
    MD5_Update(&md5_ctx, url, strlen(url));
    MD5_Final(digest, &md5_ctx);

    // Convert hash to hexadecimal string
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(&md5_string[i * 2], "%02x", digest[i]);
    }
    md5_string[32] = '\0';

    return md5_string;
}

// Function to generate short URL
char* generate_short_url(const char* original_url) {
    // Generate MD5 hash
    char* hash = generate_md5_hash(original_url);

    // Take first 8 characters as short URL
    static char short_url[SHORT_URL_LENGTH + 1];
    strncpy(short_url, hash, SHORT_URL_LENGTH);
    short_url[SHORT_URL_LENGTH] = '\0';

    return short_url;
}

// Function to shorten URL
char* shorten_url(const char* original_url) {
    // Check if URL already exists
    for (int i = 0; i < mapping_count; i++) {
        if (strcmp(url_mappings[i].original_url, original_url) == 0) {
            return url_mappings[i].short_url;
        }
    }

    // Generate short URL
    char* short_url = generate_short_url(original_url);

    // Add to mappings
    if (mapping_count < MAX_ENTRIES) {
        strcpy(url_mappings[mapping_count].original_url, original_url);
        strcpy(url_mappings[mapping_count].short_url, short_url);
        mapping_count++;
    }

    return short_url;
}

// Function to retrieve original URL
char* get_original_url(const char* short_url) {
    // Search for matching short URL
    for (int i = 0; i < mapping_count; i++) {
        if (strcmp(url_mappings[i].short_url, short_url) == 0) {
            return url_mappings[i].original_url;
        }
    }

    return NULL;
}

// Function to print all mappings
void print_mappings() {
    printf("\nURL Mappings:\n");
    for (int i = 0; i < mapping_count; i++) {
        printf("Short URL: %s -> Original URL: %s\n", 
               url_mappings[i].short_url, 
               url_mappings[i].original_url);
    }
}

int main() {
    char original_url[MAX_URL_LENGTH];
    char short_url[SHORT_URL_LENGTH + 1];

    while (1) {
        printf("\nURL Shortener Menu:\n");
        printf("1. Shorten URL\n");
        printf("2. Retrieve Original URL\n");
        printf("3. View All Mappings\n");
        printf("4. Exit\n");
        printf("Enter your choice: ");

        int choice;
        scanf("%d", &choice);
        getchar(); // Clear newline

        switch (choice) {
            case 1:
                printf("Enter URL to shorten: ");
                fgets(original_url, sizeof(original_url), stdin);
                original_url[strcspn(original_url, "\n")] = 0;

                char* shortened = shorten_url(original_url);
                printf("Shortened URL: %s\n", shortened);
                break;

            case 2:
                printf("Enter short URL: ");
                fgets(short_url, sizeof(short_url), stdin);
                short_url[strcspn(short_url, "\n")] = 0;

                char* original = get_original_url(short_url);
                if (original) {
                    printf("Original URL: %s\n", original);
                } else {
                    printf("Short URL not found.\n");
                }
                break;

            case 3:
                print_mappings();
                break;

            case 4:
                exit(0);

            default:
                printf("Invalid choice. Try again.\n");
        }
    }

    return 0;
}

