#define SHORT_URL_LENGTH 6  // We'll use first 6 chars of the MD5 hash

// Function to generate a short URL from MD5 hash
void generate_short_url(const char *original_url, char *short_url) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    char md5_string[MD5_DIGEST_LENGTH*2 + 1];

    // Compute MD5 hash
    MD5((unsigned char*)original_url, strlen(original_url), digest);

    // Convert the hash to a hex string
    for(int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(&md5_string[i*2], "%02x", (unsigned int)digest[i]);
    }

    // Take the first SHORT_URL_LENGTH characters as our short URL
    strncpy(short_url, md5_string, SHORT_URL_LENGTH);
    short_url[SHORT_URL_LENGTH] = '\0';
}

