#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h> // For MD5 hashing
#include <dirent.h>     // For dirent and checking file existence
#include <sys/stat.h>   // For stat and checking file existence

#define HASH_LENGTH 8      // Taking the first 8 characters of the MD5 hash for the short code
#define MAX_URL_LENGTH 2048
#define MAX_SHORT_CODE_LENGTH (HASH_LENGTH + 1) // +1 for null terminator
#define MAPPINGS_FILE "url_mappings.txt"

// Function to check if a file exists
int file_exists(const char *filename) {
    struct stat buffer;
    return (stat(filename, &buffer) == 0);
}

// Function to generate MD5 hash and return a hex string
void generate_md5_hash(const char *input, char *output_buffer) {
    unsigned char digest[MD5_DIGEST_LENGTH]; // 16 bytes for MD5
    MD5((unsigned char *)input, strlen(input), digest);

    for (int i = 0; i < HASH_LENGTH / 2; i++) { // HASH_LENGTH / 2 because each byte becomes 2 hex chars
        sprintf(&output_buffer[i * 2], "%02x", (unsigned int)digest[i]);
    }
    output_buffer[HASH_LENGTH] = '\0'; // Null-terminate the string
}

// Function to shorten a URL
void shorten_url(const char *original_url) {
    FILE *fp;
    char short_code[MAX_SHORT_CODE_LENGTH];
    char line[MAX_URL_LENGTH + MAX_SHORT_CODE_LENGTH + 2]; // For reading lines
    char existing_short_code[MAX_SHORT_CODE_LENGTH];
    char existing_original_url[MAX_URL_LENGTH];

    // Generate MD5 hash for the original URL
    generate_md5_hash(original_url, short_code);

    fp = fopen(MAPPINGS_FILE, "a+"); // Open in append and read mode
    if (fp == NULL) {
        perror("Error opening URL mappings file");
        return;
    }

    // Check if the original URL already exists
    fseek(fp, 0, SEEK_SET); // Go to the beginning of the file
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Strip newline character if present
        line[strcspn(line, "\n")] = 0;

        char *tab_ptr = strchr(line, '\t');
        if (tab_ptr != NULL) {
            *tab_ptr = '\0'; // Temporarily null-terminate to get short code
            strcpy(existing_short_code, line);
            strcpy(existing_original_url, tab_ptr + 1);

            if (strcmp(existing_original_url, original_url) == 0) {
                printf("URL already shortened: %s -> %s\n", original_url, existing_short_code);
                fclose(fp);
                return;
            }
        }
    }

    // If not found, write the new mapping
    fprintf(fp, "%s\t%s\n", short_code, original_url);
    printf("URL shortened successfully: %s -> %s\n", original_url, short_code);

    fclose(fp);
}

// Function to retrieve the original URL
void retrieve_url(const char *short_code) {
    FILE *fp;
    char line[MAX_URL_LENGTH + MAX_SHORT_CODE_LENGTH + 2];
    char existing_short_code[MAX_SHORT_CODE_LENGTH];
    char existing_original_url[MAX_URL_LENGTH];

    if (!file_exists(MAPPINGS_FILE)) {
        printf("No mappings found. Please shorten some URLs first.\n");
        return;
    }

    fp = fopen(MAPPINGS_FILE, "r");
    if (fp == NULL) {
        perror("Error opening URL mappings file");
        return;
    }

    while (fgets(line, sizeof(line), fp) != NULL) {
        // Strip newline character if present
        line[strcspn(line, "\n")] = 0;

        char *tab_ptr = strchr(line, '\t');
        if (tab_ptr != NULL) {
            *tab_ptr = '\0'; // Temporarily null-terminate to get short code
            strcpy(existing_short_code, line);
            strcpy(existing_original_url, tab_ptr + 1);

            if (strcmp(existing_short_code, short_code) == 0) {
                printf("Original URL for %s: %s\n", short_code, existing_original_url);
                fclose(fp);
                return;
            }
        }
    }

    printf("Short code '%s' not found.\n", short_code);
    fclose(fp);
}

// Function to list all mappings
void list_all_mappings() {
    FILE *fp;
    char line[MAX_URL_LENGTH + MAX_SHORT_CODE_LENGTH + 2];

    if (!file_exists(MAPPINGS_FILE)) {
        printf("No mappings found.\n");
        return;
    }

    fp = fopen(MAPPINGS_FILE, "r");
    if (fp == NULL) {
        perror("Error opening URL mappings file");
        return;
    }

    printf("\n--- URL Mappings ---\n");
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Strip newline character if present
        line[strcspn(line, "\n")] = 0;
        printf("%s\n", line);
    }
    printf("-------------------\n");

    fclose(fp);
}

void print_help() {
    printf("\nBasic URL Shortener (MD5 based)\n");
    printf("Usage:\n");
    printf("  ./url_shortener shorten <URL>    - Shortens the given URL.\n");
    printf("  ./url_shortener retrieve <CODE>  - Retrieves the original URL for a given short code.\n");
    printf("  ./url_shortener list             - Lists all stored URL mappings.\n");
    printf("  ./url_shortener help             - Displays this help message.\n");
    printf("\nExamples:\n");
    printf("  ./url_shortener shorten https://www.example.com/very/long/url/path\n");
    printf("  ./url_shortener retrieve c8438125\n");
    printf("  ./url_shortener list\n");
}


int main(int argc, char *argv[]) {
    if (argc < 2) {
        print_help();
        return 1;
    }

    if (strcmp(argv[1], "shorten") == 0) {
        if (argc < 3) {
            fprintf(stderr, "Usage: %s shorten <URL>\n", argv[0]);
            return 1;
        }
        shorten_url(argv[2]);
    } else if (strcmp(argv[1], "retrieve") == 0) {
        if (argc < 3) {
            fprintf(stderr, "Usage: %s retrieve <CODE>\n", argv[0]);
            return 1;
        }
        retrieve_url(argv[2]);
    } else if (strcmp(argv[1], "list") == 0) {
        list_all_mappings();
    } else if (strcmp(argv[1], "help") == 0) {
        print_help();
    }
    else {
        fprintf(stderr, "Unknown command: %s\n", argv[1]);
        print_help();
        return 1;
    }

    return 0;
}

