// Function to get MD5 hash
void md5_hash(const char *str, unsigned char *output) {
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, str, strlen(str));
    MD5_Final(output, &ctx);
}

// Convert hash to hex string
void hash_to_hex(const unsigned char *hash, char *output, int hex_len) {
    for (int i = 0; i < hex_len; i++) {
        sprintf(output + (i * 2), "%02x", hash[i]);
    }
    output[hex_len * 2] = '\0';
}

