#include <string.h>
#include <openssl/md5.h>

#define URL_PREFIX "http://short.url/"
#define HASH_LENGTH 8 // Define the length of the hash prefix for the short URL

// Function to calculate MD5 hash
unsigned char *calculate_md5(const char *str, size_t length) {
    unsigned char *digest = (unsigned char *)malloc(MD5_DIGEST_LENGTH);
    MD5((unsigned char *)str, length, digest);
    return digest;
}

// Function to convert the MD5 digest into a readable shortened URL
void create_short_url(const char *original_url, char *short_url) {
    unsigned char *digest = calculate_md5(original_url, strlen(original_url));

    // Convert the binary hash to a hex string
    char md5_string[MD5_DIGEST_LENGTH * 2 + 1];
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&md5_string[i * 2], "%02x", digest[i]);
    }

    md5_string[MD5_DIGEST_LENGTH * 2] = '\0'; // Null-terminate the string

    // Use only a part of the hash to create a short URL
    snprintf(short_url, strlen(URL_PREFIX) + HASH_LENGTH + 1, "%s%.*s", URL_PREFIX, HASH_LENGTH, md5_string);

    free(digest);
}

