#include <stdio.h>
#include <string.h>
#include <openssl/md5.h>
#include <ctype.h>

// Structure to store the original and shortened URLs
typedef struct {
    char original[1024];
    char shortened[7]; // 6 characters + null terminator
} url_t;

// Function to generate a shortened URL using MD5 hashing
void shorten_url(url_t* url) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)url->original, strlen(url->original), hash);

    // Convert the first 6 bytes of the hash to base36 for the shortened URL
    int i;
    for (i = 0; i < 6; i++) {
        unsigned char byte = hash[i];
        if (byte < 10) {
            url->shortened[i] = '0' + byte;
        } else {
            url->shortened[i] = 'a' + (byte - 10);
        }
    }
    url->shortened[6] = '\0'; // Null terminate the shortened URL
}

// Function to check if a URL is valid (contains only allowed characters)
int is_valid_url(const char* url) {
    const char* allowed_chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-._~:/?#[]@!$&'()*+,;%=";
    int i;
    for (i = 0; url[i]; i++) {
        if (strchr(allowed_chars, url[i]) == NULL) {
            return 0;
        }
    }
    return 1;
}

