    printf("Shortened URL: %s\n", url.shortened);

    return 0;
}

#include <stdio.h>
#include <string.h>
#include <openssl/md5.h>

#define URL_MAX_LENGTH 1024
#define SHORT_URL_LENGTH 6

// Function to generate a short URL from a full URL
char* generateShortURL(const char* url) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    char short_url[SHORT_URL_LENGTH + 1];
    char base62_chars[] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";

    // Compute MD5 hash of the URL
    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, url, strlen(url));
    MD5_Final(hash, &md5);

    // Convert the hash to a shorter alphanumeric string
    for (int i = 0; i < SHORT_URL_LENGTH; i++) {
        short_url[i] = base62_chars[hash[i % MD5_DIGEST_LENGTH] % 62];
    }
    short_url[SHORT_URL_LENGTH] = '\0';

    return strdup(short_url);
}

int main() {
    char url[URL_MAX_LENGTH];

    printf("Enter the URL: ");
    fgets(url, sizeof(url), stdin);
    url[strcspn(url, "\n")] = '\0';  // Remove newline character

    char* short_url = generateShortURL(url);
    printf("Short URL: http://example.com/%s\n", short_url);

    free(short_url);
