// Structure to store URL mapping
typedef struct URLEntry {
    char* original_url;
    char* short_url;
    struct URLEntry* next;  // For handling collisions
} URLEntry;

// Hash table
URLEntry* hash_table[HASH_TABLE_SIZE] = {NULL};

// Hash function
unsigned long hash_function(const char* str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    }

    return hash % HASH_TABLE_SIZE;
}

// Generate short URL
char* generate_short_url() {
    static char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char* short_url = malloc(7 * sizeof(char));

    for (int i = 0; i < 6; i++) {
        short_url[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    short_url[6] = '\0';

    return short_url;
}

// Add URL to hash table
bool add_url(const char* original_url) {
    // Check if URL already exists
    unsigned long hash_index = hash_function(original_url);
    URLEntry* current = hash_table[hash_index];

    while (current != NULL) {
        if (strcmp(current->original_url, original_url) == 0) {
            printf("URL already exists: %s\n", current->short_url);
            return false;
        }
        current = current->next;
    }

    // Create new entry
    URLEntry* new_entry = malloc(sizeof(URLEntry));
    new_entry->original_url = strdup(original_url);

    // Generate unique short URL
    char* short_url;
    bool unique;
    do {
        unique = true;
        short_url = generate_short_url();

        // Check for collision in hash table
        for (int i = 0; i < HASH_TABLE_SIZE; i++) {
            current = hash_table[i];
            while (current != NULL) {
                if (strcmp(current->short_url, short_url) == 0) {
                    unique = false;
                    break;
                }
                current = current->next;
            }
            if (!unique) break;
        }
    } while (!unique);

    new_entry->short_url = short_url;
    new_entry->next = hash_table[hash_index];
    hash_table[hash_index] = new_entry;

    printf("Original URL: %s\n", original_url);
    printf("Short URL: %s\n", short_url);

    return true;
}

// Retrieve original URL
char* get_original_url(const char* short_url) {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        URLEntry* current = hash_table[i];
        while (current != NULL) {
            if (strcmp(current->short_url, short_url) == 0) {
                return current->original_url;
            }
            current = current->next;
        }
    }
    return NULL;
}

// Free hash table memory
void free_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        URLEntry* current = hash_table[i];
        while (current != NULL) {
            URLEntry* temp = current;
            current = current->next;
            free(temp->original_url);
            free(temp->short_url);
            free(temp);
        }
        hash_table[i] = NULL;
    }
}

