// --- Function Definitions ---

/**
 * @brief Simple hash function (DJB2 algorithm)
 * @param key The string to hash (e.g., the long URL)
 * @return An unsigned int representing the hash value
 */
unsigned int hash(const char *key) {
    unsigned int hash_val = 5381; // Prime number
    int c;

    while ((c = *key++)) {
        hash_val = ((hash_val << 5) + hash_val) + c; // hash * 33 + c
    }
    return hash_val % TABLE_SIZE; // Ensure hash fits within table size
}

/**
 * @brief Initializes all hash table pointers to NULL.
 */
void init_hash_table() {
    for (int i = 0; i < TABLE_SIZE; i++) {
        hash_table[i] = NULL;
    }
}

/**
 * @brief Generates a short code from a numerical ID using Base62 encoding.
 *        Static buffer might be overwritten by successive calls, typical for return char*.
 *        In a real app, you'd allocate this or pass a buffer.
 * @param id The unique numerical ID to convert.
 * @return A string representing the short code (Base62 encoded).
 */
char* generate_short_code(unsigned long long id) {
    static char s_code[SHORT_CODE_LENGTH]; // Static so it persists beyond function call
    memset(s_code, 0, SHORT_CODE_LENGTH);   // Clear buffer

    int base = strlen(BASE62_CHARS);
    int i = SHORT_CODE_LENGTH - 2; // Last char is null terminator

    if (id == 0) { // Handle the case where ID is 0
        s_code[i--] = BASE62_CHARS[0]; // First char of BASE62_CHARS
    } else {
        while (id > 0 && i >= 0) {
            s_code[i--] = BASE62_CHARS[id % base];
            id /= base;
        }
    }
    // Pad with '0's if the generated code is too short
    // This makes the codes fixed length, improving predictability for a demo
    while (i >= 0) {
        s_code[i--] = BASE62_CHARS[0]; // Pad with first character (e.g., '0')
    }

    // Shift content to the beginning of the buffer
    // Example: if s_code is "000abc" (with null at the end), move "000abc" to s_code[0]
    memmove(s_code, s_code + i + 1, SHORT_CODE_LENGTH - (i + 1));
    s_code[SHORT_CODE_LENGTH - 1] = '\0'; // Ensure null termination

    return s_code;
}


/**
 * @brief Shortens a given long URL and stores it in the hash table.
 *        If the URL already exists, returns its existing short code.
 * @param long_url The URL to shorten.
 * @return The generated or existing short code, or NULL if an error occurs.
 */
char* shorten_url(const char *long_url) {
    if (long_url == NULL || strlen(long_url) >= MAX_LONG_URL_LENGTH) {
        fprintf(stderr, "Error: Invalid or too long URL \"%s\"\n", long_url);
        return NULL;
    }

    unsigned int index = hash(long_url);
    URLMapping *current = hash_table[index];

    // 1. Check if URL already exists in this bucket (collision chain)
    while (current != NULL) {
        if (strcmp(current->long_url, long_url) == 0) {
            printf("URL already shortened: %s -> %s\n", long_url, current->short_code);
            return current->short_code; // Found existing mapping
        }
        current = current->next;
    }

    // 2. If not found, create a new mapping
    URLMapping *new_mapping = (URLMapping *)malloc(sizeof(URLMapping));
    if (new_mapping == NULL) {
        perror("Failed to allocate memory for URL mapping");
        return NULL;
    }

    strncpy(new_mapping->long_url, long_url, MAX_LONG_URL_LENGTH - 1);
    new_mapping->long_url[MAX_LONG_URL_LENGTH - 1] = '\0'; // Ensure null termination

    // Generate a unique short code
    char *gen_code = generate_short_code(next_short_code_id++);
    strncpy(new_mapping->short_code, gen_code, SHORT_CODE_LENGTH - 1);
    new_mapping->short_code[SHORT_CODE_LENGTH - 1] = '\0'; // Ensure null termination

    // Add new mapping to the beginning of the linked list in the bucket
    new_mapping->next = hash_table[index];
    hash_table[index] = new_mapping;

    return new_mapping->short_code;
}

/**
 * @brief Retrieves the original long URL given a short code.
 *        NOTE: This is a linear scan across all buckets for simplicity.
 *        A real system would use a second hash table (short_code -> long_url)
 *        for efficient lookup.
 * @param short_code The short code to look up.
 * @return The original long URL, or NULL if not found.
 */
char* retrieve_long_url(const char *short_code) {
    if (short_code == NULL || strlen(short_code) >= SHORT_CODE_LENGTH) {
        fprintf(stderr, "Error: Invalid short code \"%s\"\n", short_code);
        return NULL;
    }

    // Iterate through all buckets and their chains to find the matching short code
    // This is inefficient but demonstrates the single hash table approach for this example.
    for (int i = 0; i < TABLE_SIZE; i++) {
        URLMapping *current = hash_table[i];
        while (current != NULL) {
            if (strcmp(current->short_code, short_code) == 0) {
                return current->long_url; // Found it!
            }
            current = current->next;
        }
    }
    return NULL; // Short code not found
}

/**
 * @brief Frees all allocated memory in the hash table.
 */
void free_hash_table() {
    for (int i = 0; i < TABLE_SIZE; i++) {
        URLMapping *current = hash_table[i];
        while (current != NULL) {
            URLMapping *to_free = current;
            current = current->next;
            free(to_free);
        }
        hash_table[i] = NULL; // Clear pointer after freeing
    }
    printf("\nHash table memory freed.\n");
}

/**
 * @brief Prints all mappings for debugging purposes.
 */
void print_all_mappings() {
    for (int i = 0; i < TABLE_SIZE; i++) {
        URLMapping *current = hash_table[i];
        if (current) {
            printf("Bucket %d:\n", i);
            while (current != NULL) {
                printf("  Short: %s -> Long: %s\n", current->short_code, current->long_url);
                current = current->next;
            }
        }
    }
}

