// Function to shorten a URL
char* shorten_url(Url** urls, int* size, char* original_url) {
    // Check if the URL is already shortened
    for (int i = 0; i < *size; i++) {
        if (strcmp((*urls)[i].original_url, original_url) == 0) {
            return (*urls)[i].shortened_url;
        }
    }

    // If not, shorten the URL and add it to the list
    Url* new_url = (Url*)malloc(sizeof(Url));
    strcpy(new_url->original_url, original_url);
    char* shortened_url = hash_url(original_url);
    strcpy(new_url->shortened_url, shortened_url);

    // Reallocate the list to add the new URL
    *urls = (Url*)realloc(*urls, (*size + 1) * sizeof(Url));
    (*urls)[*size] = *new_url;
    (*size)++;

    return shortened_url;
}

