#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

#define TABLE_SIZE 1000
#define MAX_URL_LENGTH 1000
#define MAX_KEY_LENGTH 10

// Hash table entry structure
typedef struct {
    char key[MAX_KEY_LENGTH];
    char url[MAX_URL_LENGTH];
    int occupied; // 0 if the slot is free, 1 if occupied
} Entry;

Entry hash_table[TABLE_SIZE];

// Hash function to generate a key from a URL
int hash(const char *url) {
    int hash = 0;
    for (int i = 0; url[i] != '\0'; i++) {
        hash = (hash * 31 + url[i]) % TABLE_SIZE;
    }
    return hash;
}

// Function to generate a unique key for a URL
char* generate_key(const char *url) {
    static char key[MAX_KEY_LENGTH];
    int index = hash(url);
    int original_index = index;
    int attempts = 0;

    while (hash_table[index].occupied && strcmp(hash_table[index].url, url) != 0) {
        index = (index + 1) % TABLE_SIZE;
        attempts++;
        if (attempts > TABLE_SIZE) {
            printf("Hash table is full or URL already exists.\n");
            return NULL;
        }
    }

    if (attempts == 0) {
        // Use the first 9 characters of the hashed value as the key
        snprintf(key, MAX_KEY_LENGTH, "%08x", hash(url));
    } else {
        // Use a combination of the hashed value and the index as the key
        snprintf(key, MAX_KEY_LENGTH, "%08x-%d", hash(url), attempts);
    }

    return key;
}

// Function to add a URL to the hash table
void add_url(const char *url) {
    char *key = generate_key(url);
    if (key == NULL) {
        return;
    }

    int index = hash(url);
    while (hash_table[index].occupied && strcmp(hash_table[index].url, url) != 0) {
        index = (index + 1) % TABLE_SIZE;
    }

    strcpy(hash_table[index].key, key);
    strcpy(hash_table[index].url, url);
    hash_table[index].occupied = 1;

    printf("URL '%s' shortened to '%s'\n", url, key);
}

// Function to retrieve a URL by its short key
const char* get_url_by_key(const char *key) {
    int index = 0;
    while (hash_table[index].occupied) {
        if (strcmp(hash_table[index].key, key) == 0) {
            return hash_table[index].url;
        }
        index = (index + 1) % TABLE_SIZE;
    }
    return NULL;
}

int main() {
    // Initialize the hash table
    for (int i = 0; i < TABLE_SIZE; i++) {
        hash_table[i].occupied = 0;
    }

    // Example usage
    add_url("https://www.example.com");
    add_url("https://www.example2.com");
    add_url("https://www.example3.com");

    char key[MAX_KEY_LENGTH];
    printf("Enter the short key to retrieve the URL: ");
    scanf("%s", key);

    const char *url = get_url_by_key(key);
    if (url) {
        printf("The URL for key '%s' is: '%s'\n", key, url);
    } else {
        printf("Key not found.\n");
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <arpa/inet.h>

#define MAX_RULES 100
#define MAX_IP_LENGTH 16

// Firewall rule structure
typedef struct {
    char ip[MAX_IP_LENGTH];
    bool is_allowed;
} FirewallRule;

// Firewall management structure
typedef struct {
    FirewallRule rules[MAX_RULES];
    int rule_count;
    bool default_policy; // Default policy when no rule matches (true = allow, false = block)
} Firewall;

// Function prototypes
void initialize_firewall(Firewall *fw, bool default_policy);
bool is_valid_ip(const char *ip);
int add_rule(Firewall *fw, const char *ip, bool is_allowed);
bool check_ip_allowed(Firewall *fw, const char *ip);
void list_rules(Firewall *fw);
void remove_rule(Firewall *fw, const char *ip);
void save_rules(Firewall *fw, const char *filename);
void load_rules(Firewall *fw, const char *filename);

// Initialize firewall with default policy
void initialize_firewall(Firewall *fw, bool default_policy) {
    fw->rule_count = 0;
    fw->default_policy = default_policy;
}

// Validate IP address format
bool is_valid_ip(const char *ip) {
    struct in_addr addr;
    return inet_pton(AF_INET, ip, &addr) == 1;
}

// Add a firewall rule
int add_rule(Firewall *fw, const char *ip, bool is_allowed) {
    // Check if IP is valid
    if (!is_valid_ip(ip)) {
        printf("Invalid IP address: %s\n", ip);
        return -1;
    }

    // Check if rule limit reached
    if (fw->rule_count >= MAX_RULES) {
        printf("Maximum rule limit reached\n");
        return -1;
    }

    // Check for duplicate rule
    for (int i = 0; i < fw->rule_count; i++) {
        if (strcmp(fw->rules[i].ip, ip) == 0) {
            printf("Rule for IP %s already exists\n", ip);
            return -1;
        }
    }

    // Add new rule
    strcpy(fw->rules[fw->rule_count].ip, ip);
    fw->rules[fw->rule_count].is_allowed = is_allowed;
    fw->rule_count++;

    printf("Rule added: %s %s\n", ip, is_allowed ? "ALLOW" : "BLOCK");
    return 0;
}

// Check if an IP is allowed based on firewall rules
bool check_ip_allowed(Firewall *fw, const char *ip) {
    // Check specific rules first
    for (int i = 0; i < fw->rule_count; i++) {
        if (strcmp(fw->rules[i].ip, ip) == 0) {
            return fw->rules[i].is_allowed;
        }
    }

    // Return default policy if no specific rule matches
    return fw->default_policy;
}

// List all firewall rules
void list_rules(Firewall *fw) {
    printf("Firewall Rules:\n");
    for (int i = 0; i < fw->rule_count; i++) {
        printf("%s: %s\n", 
               fw->rules[i].ip, 
               fw->rules[i].is_allowed ? "ALLOW" : "BLOCK");
    }
    printf("Default Policy: %s\n", fw->default_policy ? "ALLOW" : "BLOCK");
}

// Remove a rule for a specific IP
void remove_rule(Firewall *fw, const char *ip) {
    for (int i = 0; i < fw->rule_count; i++) {
        if (strcmp(fw->rules[i].ip, ip) == 0) {
            // Shift rules to fill the gap
            for (int j = i; j < fw->rule_count - 1; j++) {
                fw->rules[j] = fw->rules[j + 1];
            }
            fw->rule_count--;
            printf("Rule for IP %s removed\n", ip);
            return;
        }
    }
    printf("No rule found for IP %s\n", ip);
}

// Save rules to a file
void save_rules(Firewall *fw, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        printf("Error opening file for writing\n");
        return;
    }

    fprintf(file, "%d\n", fw->default_policy);
    fprintf(file, "%d\n", fw->rule_count);

    for (int i = 0; i < fw->rule_count; i++) {
        fprintf(file, "%s %d\n", fw->rules[i].ip, fw->rules[i].is_allowed);
    }

    fclose(file);
    printf("Rules saved to %s\n", filename);
}

// Load rules from a file
void load_rules(Firewall *fw, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        printf("Error opening file for reading\n");
        return;
    }

    // Reset firewall
    fw->rule_count = 0;

    // Read default policy
    fscanf(file, "%d", &fw->default_policy);

    // Read number of rules
    int rule_count;
    fscanf(file, "%d", &rule_count);

    // Read individual rules
    for (int i = 0; i < rule_count; i++) {
        char ip[MAX_IP_LENGTH];
        int is_allowed;
        fscanf(file, "%s %d", ip, &is_allowed);
        add_rule(fw, ip, is_allowed);
    }

    fclose(file);
    printf("Rules loaded from %s\n", filename);
}

int main() {
    Firewall fw;
    char ip[MAX_IP_LENGTH];
    int choice;

    // Initialize firewall with default ALLOW policy
    initialize_firewall(&fw, true);

    while (1) {
        printf("\nFirewall Management\n");
        printf("1. Add Allow Rule\n");
        printf("2. Add Block Rule\n");
        printf("3. Remove Rule\n");
        printf("4. List Rules\n");
        printf("5. Check IP\n");
        printf("6. Save Rules\n");
        printf("7. Load Rules\n");
        printf("8. Exit\n");
        printf("Enter choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                printf("Enter IP to allow: ");
                scanf("%s", ip);
                add_rule(&fw, ip, true);
                break;
            case 2:
                printf("Enter IP to block: ");
                scanf("%s", ip);
                add_rule(&fw, ip, false);
                break;
            case 3:
                printf("Enter IP to remove: ");
                scanf("%s", ip);
                remove_rule(&fw, ip);
                break;
            case 4:
                list_rules(&fw);
                break;
            case 5:
                printf("Enter IP to check: ");
                scanf("%s", ip);
                printf("IP %s is %s\n", ip, 
                       check_ip_allowed(&fw, ip) ? "ALLOWED" : "BLOCKED");
                break;
            case 6:
                save_rules(&fw, "firewall_rules.txt");
                break;
            case 7:
                load_rules(&fw, "firewall_rules.txt");
                break;
            case 8:
                exit(0);
            default:
                printf("Invalid choice\n");
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <signal.h>
#include <pthread.h>

#define MAX_RULES 100
#define BUFFER_SIZE 65536

typedef struct {
    char ip[16];    // IPv4 address in dotted notation
    int action;     // 0 = block, 1 = allow
} firewall_rule;

firewall_rule rules[MAX_RULES];
int rule_count = 0;
int running = 1;

// Function to add a new firewall rule
void add_rule(const char *ip, int action) {
    if (rule_count >= MAX_RULES) {
        printf("Firewall rule limit reached.\n");
        return;
    }

    strncpy(rules[rule_count].ip, ip, 15);
    rules[rule_count].ip[15] = '\0';
    rules[rule_count].action = action;
    rule_count++;

    printf("Added rule: %s -> %s\n", ip, action ? "ALLOW" : "BLOCK");
}

// Function to check if an IP matches any rule
int check_ip(const char *ip) {
    for (int i = 0; i < rule_count; i++) {
        if (strcmp(rules[i].ip, ip) == 0) {
            return rules[i].action;
        }
    }
    return 1; // Default to allow if no rule matches
}

// Function to print all current rules
void print_rules() {
    printf("\nCurrent Firewall Rules:\n");
    printf("-----------------------\n");
    for (int i = 0; i < rule_count; i++) {
        printf("%d. %s -> %s\n", i+1, rules[i].ip, 
               rules[i].action ? "ALLOW" : "BLOCK");
    }
    printf("-----------------------\n\n");
}

// Signal handler for clean exit
void handle_signal(int sig) {
    running = 0;
    printf("\nShutting down firewall...\n");
}

// Thread function to process incoming packets
void *packet_processor(void *arg) {
    int sockfd = *(int *)arg;
    unsigned char buffer[BUFFER_SIZE];
    struct sockaddr_in source_addr;
    socklen_t addr_len = sizeof(source_addr);

    printf("Firewall started. Processing packets...\n");

    while (running) {
        ssize_t packet_size = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, 
                                      (struct sockaddr *)&source_addr, &addr_len);
        if (packet_size < 0) {
            perror("recvfrom failed");
            continue;
        }

        char source_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &(source_addr.sin_addr), source_ip, INET_ADDRSTRLEN);

        int action = check_ip(source_ip);

        if (!action) {
            printf("Blocked packet from %s\n", source_ip);
            continue; // Drop the packet
        }

        // Here you would normally forward the packet to its destination
        // For this example, we'll just note that it was allowed
        printf("Allowed packet from %s\n", source_ip);
    }

    return NULL;
}

int main() {
    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Create raw socket
    int sockfd = socket(AF_INET, SOCK_RAW, IPPROTO_TCP);
    if (sockfd < 0) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Add some example rules
    add_rule("192.168.1.100", 1);  // Allow
    add_rule("10.0.0.5", 0);       // Block
    add_rule("172.16.0.10", 0);    // Block

    print_rules();

    // Start packet processing thread
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, packet_processor, &sockfd) != 0) {
        perror("pthread_create failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    // Simple command interface
    char command[32];
    char ip[16];
    int action;

    while (running) {
        printf("\nFirewall commands:\n");
        printf("  add <ip> <allow|block> - Add a new rule\n");
        printf("  list                   - Show all rules\n");
        printf("  exit                   - Quit the firewall\n");
        printf("> ");

        if (fgets(command, sizeof(command), stdin) == NULL) {
            break;
        }

        if (strncmp(command, "exit", 4) == 0) {
            running = 0;
            break;
        }
        else if (strncmp(command, "list", 4) == 0) {
            print_rules();
        }
        else if (strncmp(command, "add", 3) == 0) {
            if (sscanf(command, "add %15s %d", ip, &action) == 2) {
                add_rule(ip, action);
            } else {
                printf("Invalid add command. Usage: add <ip> <0|1>\n");
            }
        }
        else {
            printf("Unknown command.\n");
        }
    }

    // Clean up
    pthread_join(thread_id, NULL);
    close(sockfd);

    printf("Firewall stopped.\n");
    return 0;
}

#ifndef FIREWALL_RULES_H
#define FIREWALL_RULES_H

#include <stdbool.h>
#include <string.h>
#include <arpa/inet.h> // For inet_addr

// --- Firewall Policy ---
// Define your policy here:
// ALLOW_BY_DEFAULT: If true, only explicitly BLOCKED IPs are denied.
//                    If false, only explicitly ALLOWED IPs are permitted.
#define ALLOW_BY_DEFAULT false // Set to true for a Blacklist; false for a Whitelist

// --- Rules ---
// Define your blocked/allowed IPs and ports.
// Remember: For a user-level proxy, these rules apply to the *destination*
// the proxy is trying to connect to on behalf of the client.

// Maximum number of rules
#define MAX_RULES 10

typedef struct {
    char ip_address[INET_ADDRSTRLEN]; // IP address string
    in_addr_t net_order_ip;           // IP address in network byte order
    unsigned short port;              // 0 for any port, specific port otherwise
    bool block;                       // true to block, false to allow (if ALLOW_BY_DEFAULT is true)
} FirewallRule;

// Example Rules Array
// If ALLOW_BY_DEFAULT is false (Whitelist):
//   - Only connections to 8.8.8.8:53 are allowed.
//   - Everything else is blocked.
// If ALLOW_BY_DEFAULT is true (Blacklist):
//   - Connections to 192.168.1.100 on port 80 are blocked.
//   - Connections to 1.2.3.4 on any port are blocked.
//   - Everything else is allowed.
FirewallRule rules[] = {
    // Whitelist example (if ALLOW_BY_DEFAULT is false):
    {"8.8.8.8", 0, 53, false}, // Allow DNS to Google
    {"1.1.1.1", 0, 53, false}, // Allow DNS to Cloudflare

    // Blacklist example (if ALLOW_BY_DEFAULT is true):
    {"192.168.1.100", 0, 80, true}, // Block specific internal IP on port 80
    {"93.184.216.34", 0, 0, true},  // Block example.com (on any port)
    {"173.194.70.100", 0, 0, true}, // Block a specific Google IP (for testing block effect)

    // Sentinel to mark end of rules
    {"", 0, 0, false}
};
static int num_rules = 0; // Will be set dynamically

// Function to initialize rules (convert IP strings to network byte order)
void init_firewall_rules() {
    for (int i = 0; i < MAX_RULES; ++i) {
        if (strlen(rules[i].ip_address) == 0) {
            num_rules = i;
            break;
        }
        rules[i].net_order_ip = inet_addr(rules[i].ip_address);
        if (rules[i].net_order_ip == INADDR_NONE && strcmp(rules[i].ip_address, "255.255.255.255") != 0) {
            // inet_addr returns INADDR_NONE for "none" or 255.255.255.255
            // Handle error or special case for broadcast address if needed
            // For simplicity, we assume valid IP string.
            // A more robust solution would use inet_pton.
        }
    }
}

// Function to check if a connection to a target IP/Port is allowed
bool is_allowed(in_addr_t target_ip, unsigned short target_port) {
    bool explicitly_matched = false;
    bool policy_decision = ALLOW_BY_DEFAULT; // Start with default policy

    for (int i = 0; i < num_rules; ++i) {
        // Check if IP matches (or rule IP is "any" - though we don't have "any" yet)
        if (rules[i].net_order_ip == target_ip) {
            // Check if port matches (or rule port is 0 for any port)
            if (rules[i].port == 0 || rules[i].port == target_port) {
                // We have a match!
                explicitly_matched = true;
                policy_decision = !rules[i].block; // If rule is block, decision is false (deny). If rule is not block (allow), decision is true (allow).
                break; // Found a matching rule, apply it and stop
            }
        }
    }

    if (explicitly_matched) {
        return policy_decision;
    } else {
        // No explicit match found, apply default policy
        return ALLOW_BY_DEFAULT;
    }
}

