#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define PORT 8888
#define MAX_LIST 100
#define BUFFER_SIZE 1024

// --- Firewall lists ---
char *blocklist[MAX_LIST];
int blocklist_count = 0;

char *allowlist[MAX_LIST];
int allowlist_count = 0;

// Return 1 if IP is in the list, 0 otherwise
int ip_in_list(const char *ip, char *list[], int count) {
    for (int i = 0; i < count; i++) {
        if (strcmp(ip, list[i]) == 0)
            return 1;
    }
    return 0;
}

// block=1: blocklist, 0: allowlist
// Return: 1 = allowed, 0 = blocked
int firewall_check(const char *ip, int use_blocklist, int use_allowlist) {
    if (use_allowlist && !ip_in_list(ip, allowlist, allowlist_count)) {
        // Not in allowlist: block
        return 0;
    }
    if (use_blocklist && ip_in_list(ip, blocklist, blocklist_count)) {
        // In blocklist: block
        return 0;
    }
    // Allowed
    return 1;
}

void add_block_ip(const char *ip) {
    if (blocklist_count < MAX_LIST) blocklist[blocklist_count++] = strdup(ip);
}

void add_allow_ip(const char *ip) {
    if (allowlist_count < MAX_LIST) allowlist[allowlist_count++] = strdup(ip);
}

void usage(const char *prog) {
    printf("Usage: %s [-b ip_to_block]... [-a ip_to_allow]...\n", prog);
    printf("Example:\n  %s -b 192.168.1.100 -a 127.0.0.1\n", prog);
}

// Main server loop
int main(int argc, char *argv[]) {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE];
    char client_ip[INET_ADDRSTRLEN];

    int use_blocklist = 0, use_allowlist = 0;

    // Parse command line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-b") == 0 && i+1 < argc) {
            add_block_ip(argv[++i]);
            use_blocklist = 1;
        } else if (strcmp(argv[i], "-a") == 0 && i+1 < argc) {
            add_allow_ip(argv[++i]);
            use_allowlist = 1;
        } else if (strcmp(argv[i], "-h") == 0) {
            usage(argv[0]);
            exit(0);
        } else {
            usage(argv[0]);
            exit(1);
        }
    }

    printf("Starting simple firewall server on port %d...\n", PORT);
    printf("Using %s%slist%s\n",
           use_blocklist ? "block" : "",
           (use_blocklist && use_allowlist) ? " and " : "",
           use_allowlist ? "allow" : "",
           (!use_blocklist && !use_allowlist) ? " (All allowed)" : "");

    // Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address))<0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }
    if (listen(server_fd, 5) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    while (1) {
        struct sockaddr_in client_addr;
        int client_len = sizeof(client_addr);

        if ((new_socket = accept(server_fd, (struct sockaddr *)&client_addr, (socklen_t*)&client_len)) < 0) {
            perror("accept");
            continue;
        }

        // Get connecting IP address
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        printf("Connection from %s:", client_ip);

        if (!firewall_check(client_ip, use_blocklist, use_allowlist)) {
            printf(" BLOCKED\n");
            close(new_socket);
            continue;
        } else {
            printf(" ALLOWED\n");
            // Optional: Respond to allowed client
            snprintf(buffer, sizeof(buffer), "Welcome! Your IP (%s) is allowed.\n", client_ip);
            send(new_socket, buffer, strlen(buffer), 0);
            // For demo, just close
            close(new_socket);
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
