#define BUFFER_SIZE 65536

// Example IP lists for allow/block (usually, it would be loaded from config files)
const char* block_list[] = {"192.168.1.10", "10.0.0.2"};
const char* allow_list[] = {"192.168.1.5", "10.0.0.3"};
const int block_list_len = 2;
const int allow_list_len = 2;

// Check if IP is in the given list
int is_ip_in_list(const char *ip, const char **list, int list_size) {
    for (int i = 0; i < list_size; i++) {
        if (strcmp(ip, list[i]) == 0) {
            return 1;  // IP found in list
        }
    }
    return 0;  // IP not found in list
}

// Filter packet based on source IP
void filter_packet(struct iphdr* iph) {
    struct sockaddr_in src;
    src.sin_addr.s_addr = iph->saddr;

    // Convert source IP to human-readable form
    char *src_ip = inet_ntoa(src.sin_addr);

    printf("Packet from: %s\n", src_ip);

    // Check against block list
    if (is_ip_in_list(src_ip, block_list, block_list_len)) {
        printf("Blocking packet from: %s\n", src_ip);
        return;
    }

    // Check against allow list
    if (is_ip_in_list(src_ip, allow_list, allow_list_len)) {
        printf("Allowing packet from: %s\n", src_ip);
        return;
    }

    // Default action (e.g., allow or block)
