// Structure to store IP addresses and their corresponding rules
typedef struct {
    char ip[20];
    int rule; // 0: block, 1: allow
} FirewallRule;

// Function to add a new firewall rule
void add_rule(FirewallRule *rules, int *num_rules, char *ip, int rule) {
    rules[*num_rules].rule = rule;
    strcpy(rules[*num_rules].ip, ip);
    (*num_rules)++;
}

// Function to remove a firewall rule
void remove_rule(FirewallRule *rules, int *num_rules, char *ip) {
    int i;
    for (i = 0; i < *num_rules; i++) {
        if (strcmp(rules[i].ip, ip) == 0) {
            // Shift rules to the left
            for (int j = i; j < *num_rules - 1; j++) {
                rules[j] = rules[j + 1];
            }
            (*num_rules)--;
            break;
        }
    }
}

// Function to apply firewall rules
void apply_rules(FirewallRule *rules, int num_rules) {
    for (int i = 0; i < num_rules; i++) {
        if (rules[i].rule == 0) {
            // Block IP address
            char command[100];
            sprintf(command, "iptables -A INPUT -s %s -j DROP", rules[i].ip);
            system(command);
        } else {
            // Allow IP address
            char command[100];
            sprintf(command, "iptables -A INPUT -s %s -j ACCEPT", rules[i].ip);
            system(command);
        }
    }
}

// Function to reset firewall rules
void reset_rules() {
    system("iptables -F");
}

