void interpret_brainfuck(char* code) {
    unsigned char memory[MEMORY_SIZE] = {0};
    unsigned char* ptr = memory;
    char* code_ptr = code;
    int bracket_depth = 0;
    char* loop_start = NULL;

    while (*code_ptr) {
        switch (*code_ptr) {
            case '>':
                // Move data pointer to the right
                if (ptr < memory + MEMORY_SIZE - 1) {
                    ptr++;
                } else {
                    print_error("Memory pointer out of bounds");
                    return;
                }
                break;

            case '<':
                // Move data pointer to the left
                if (ptr > memory) {
                    ptr--;
                } else {
                    print_error("Memory pointer out of bounds");
                    return;
                }
                break;

            case '+':
                // Increment byte at data pointer
                (*ptr)++;
                break;

            case '-':
                // Decrement byte at data pointer
                (*ptr)--;
                break;

            case '.':
                // Output byte at data pointer
                putchar(*ptr);
                break;

            case ',':
                // Input byte and store at data pointer
                *ptr = getchar();
                break;

            case '[':
                // Begin loop
                if (*ptr == 0) {
                    // Skip to matching closing bracket
                    bracket_depth = 1;
                    loop_start = code_ptr;

                    while (bracket_depth > 0) {
                        code_ptr++;
                        if (*code_ptr == '[') bracket_depth++;
                        if (*code_ptr == ']') bracket_depth--;

                        if (*code_ptr == '\0') {
                            print_error("Unmatched opening bracket");
                            return;
                        }
                    }
                } else {
                    // Mark potential loop start
                    loop_start = code_ptr;
                }
                break;

            case ']':
                // End loop
                if (*ptr != 0 && loop_start != NULL) {
                    code_ptr = loop_start;
                }
                break;

            // Ignore other characters
            default:
                break;
        }

        code_ptr++;
    }
}

void print_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

