            case '+':
                ++(*ptr);
                break;
            case '-':
                --(*ptr);
                break;
            case '.':
                putchar(*ptr);
                break;
            case ',':
                *ptr = getchar();
                break;
            case '[':
                if (*ptr == 0) {
                    int loop = 1;
                    while (loop > 0) {
                        ++pc;
                        if (*pc == '[') ++loop;
                        if (*pc == ']') --loop;
                    }
                }
                break;
            case ']':
                if (*ptr != 0) {
                    int loop = 1;
                    while (loop > 0) {
                        --pc;
                        if (*pc == ']') ++loop;
                        if (*pc == '[') --loop;
                    }
                }
                break;
            default:
                // Ignore other characters
                break;
        }
        ++pc;
    }
}

