// --- Interpreter Function ---
void interpret_brainfuck(const char *code) {
    int code_ptr = 0; // Pointer to the current instruction in the code
    int code_len = strlen(code);

    while (code_ptr < code_len) {
        char command = code[code_ptr];

        switch (command) {
            case '>':
                data_ptr++;
                if (data_ptr >= TAPE_SIZE) {
                    fprintf(stderr, "\nError: Data pointer moved out of bounds (Tape Overflow!).\n");
                    exit(1); // Exit on critical error
                }
                break;
            case '<':
                data_ptr--;
                if (data_ptr < 0) {
                    fprintf(stderr, "\nError: Data pointer moved out of bounds (Tape Underflow!).\n");
                    exit(1); // Exit on critical error
                }
                break;
            case '+':
                tape[data_ptr]++; // Implicitly wraps around from 255 to 0 (unsigned char)
                break;
            case '-':
                tape[data_ptr]--; // Implicitly wraps around from 0 to 255 (unsigned char)
                break;
            case '.':
                putchar(tape[data_ptr]);
                fflush(stdout); // Ensure immediate output
                break;
            case ',': {
                int c = getchar(); // Read a single character from stdin
                if (c == EOF) {
                    fprintf(stderr, "\nWarning: EOF reached during Brainfuck input (',') operation. Cell will be zero.\n");
                    tape[data_ptr] = 0; // Or some other default, like 0
                } else {
                    tape[data_ptr] = (unsigned char)c;
                }
                break;
            }
            case '[':
                if (tape[data_ptr] == 0) {
                    // Find the matching ']' and jump to the character after it
                    int match_idx = find_matching_bracket(code, code_ptr, '[');
                    if (match_idx == -1) {
                        fprintf(stderr, "\nError: Unmatched '[' at instruction %d.\n", code_ptr);
                        exit(1);
                    }
                    code_ptr = match_idx; // Move code_ptr to the ']'
                }
                break; // If tape[data_ptr] is not 0, continue to the next instruction
            case ']':
                if (tape[data_ptr] != 0) {
                    // Find the matching '[' and jump to the character after it
                    int match_idx = find_matching_bracket(code, code_ptr, ']');
                    if (match_idx == -1) {
                        fprintf(stderr, "\nError: Unmatched ']' at instruction %d.\n", code_ptr);
                        exit(1);
                    }
                    code_ptr = match_idx; // Move code_ptr to the '['
                }
                break; // If tape[data_ptr] is 0, continue to the next instruction
            default:
                // Ignore any other characters (comments)
                break;
        }
        code_ptr++; // Move to the next instruction
    }
}

// --- Helper Function: Find Matching Bracket ---
// Finds the index of the matching ']' for a '[' or '[' for a ']'
int find_matching_bracket(const char *code, int start_idx, char command_type) {
    int balance = 0;
    int current_idx = start_idx;
    int code_len = strlen(code);

    if (command_type == '[') { // Looking for ']'
        balance = 1; // Count the starting '['
        while (++current_idx < code_len) {
            if (code[current_idx] == '[') {
                balance++;
            } else if (code[current_idx] == ']') {
                balance--;
            }
            if (balance == 0) {
                return current_idx; // Found matching ']'
            }
        }
    } else if (command_type == ']') { // Looking for '['
        balance = 1; // Count the starting ']'
        while (--current_idx >= 0) {
            if (code[current_idx] == ']') {
                balance++;
            } else if (code[current_idx] == '[') {
                balance--;
            }
            if (balance == 0) {
                return current_idx; // Found matching '['
            }
        }
    }
    return -1; // No matching bracket found
}

