#define TAPE_SIZE 30000

void brainfuck_interpreter(char *code) {
    int tape[TAPE_SIZE] = {0};
    int pointer = 0;
    int code_pointer = 0;
    int loop_stack[TAPE_SIZE];
    int loop_top = -1;

    while (code[code_pointer] != '\0') {
        switch (code[code_pointer]) {
            case '+':
                // Increment the value at the current pointer
                tape[pointer] = (tape[pointer] + 1) % 256;
                break;
            case '-':
                // Decrement the value at the current pointer
                tape[pointer] = (tape[pointer] + 255) % 256;
                break;
            case '>':
                // Move the pointer to the right
                pointer = (pointer + 1) % TAPE_SIZE;
                break;
            case '<':
                // Move the pointer to the left
                pointer = (pointer + TAPE_SIZE - 1) % TAPE_SIZE;
                break;
            case '.':
                // Output the value at the current pointer
                putchar(tape[pointer]);
                break;
            case ',':
                // Input a character and store it in the current pointer
                tape[pointer] = getchar();
                break;
            case '[':
                // If the value at the current pointer is 0, jump to the corresponding ']'
                if (tape[pointer] == 0) {
                    int count = 1;
                    while (count != 0) {
                        code_pointer++;
                        if (code[code_pointer] == '[') count++;
                        else if (code[code_pointer] == ']') count--;
                    }
                } else {
                    // Push the current code pointer to the loop stack
                    loop_stack[++loop_top] = code_pointer;
                }
                break;
            case ']':
                // If the value at the current pointer is not 0, jump to the corresponding '['
                if (tape[pointer] != 0) {
                    code_pointer = loop_stack[loop_top--];
                }
                break;
            default:
                break;
        }
        code_pointer++;
    }
}

