#include <stdio.h>
#include <stdlib.h>

#define TAPE_SIZE 30000

void brainfuck_interpreter(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    // Tape for memory cells
    unsigned char tape[TAPE_SIZE] = {0};
    // Pointer to the current cell
    unsigned char *ptr = tape;
    // Brainfuck code
    char command;
    // Loop stack for handling loops
    int loop_stack[1000];
    int loop_depth = 0;

    while ((command = fgetc(file)) != EOF) {
        switch (command) {
            case '>':
                ptr++;
                if (ptr - tape >= TAPE_SIZE) {
                    fprintf(stderr, "Error: Pointer out of bounds\n");
                    exit(1);
                }
                break;
            case '<':
                ptr--;
                if (ptr < tape) {
                    fprintf(stderr, "Error: Pointer out of bounds\n");
                    exit(1);
                }
                break;
            case '+':
                (*ptr)++;
                break;
            case '-':
                (*ptr)--;
                break;
            case '.':
                putchar(*ptr);
                break;
            case ',':
                *ptr = getchar();
                break;
            case '[':
                if (*ptr == 0) {
                    int balance = 1;
                    while (balance != 0) {
                        command = fgetc(file);
                        if (command == '[') balance++;
                        if (command == ']') balance--;
                    }
                } else {
                    loop_stack[loop_depth++] = ftell(file) - 1;
                }
                break;
            case ']':
                if (*ptr != 0) {
                    fseek(file, loop_stack[--loop_depth], SEEK_SET);
                }
                break;
            default:
                // Ignore any other characters
                break;
        }
    }

    fclose(file);
}

