#define BUFFER_SIZE 100

void chat(int read_fd, int write_fd, const char* process_name) {
    char buffer[BUFFER_SIZE];

    while (1) {
        // Read message
        memset(buffer, 0, BUFFER_SIZE);
        ssize_t bytes_read = read(read_fd, buffer, BUFFER_SIZE);

        if (bytes_read <= 0) {
            printf("%s: Connection closed\n", process_name);
            break;
        }

        // Print received message
        printf("%s received: %s", process_name, buffer);

        // Check for exit
        if (strncmp(buffer, "exit\n", 5) == 0) {
            break;
        }

        // Send reply
        printf("%s (type message): ", process_name);
        fgets(buffer, BUFFER_SIZE, stdin);
        write(write_fd, buffer, strlen(buffer));

        // Check for exit
        if (strncmp(buffer, "exit\n", 5) == 0) {
            break;
        }
    }
}

