int main() {
    int pipe_parent_to_child[2]; // Pipe for parent to write, child to read
    int pipe_child_to_parent[2]; // Pipe for child to write, parent to read
    pid_t pid;
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    // Create the first pipe (parent to child)
    if (pipe(pipe_parent_to_child) == -1) {
        perror("pipe_parent_to_child creation failed");
        exit(EXIT_FAILURE);
    }

    // Create the second pipe (child to parent)
    if (pipe(pipe_child_to_parent) == -1) {
        perror("pipe_child_to_parent creation failed");
        exit(EXIT_FAILURE);
    }

    // Fork a child process
    pid = fork();

    if (pid == -1) {
        perror("fork failed");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) { // Child process (Process A)
        // Close unused pipe ends
        close(pipe_parent_to_child[WRITE_END]); // Child won't write to this pipe
        close(pipe_child_to_parent[READ_END]);  // Child won't read from this pipe

        printf("Child Process (Process A) started. Type 'exit' to quit.\n");

        while (1) {
            // Read from parent
            bytes_read = read(pipe_parent_to_child[READ_END], buffer, BUFFER_SIZE - 1);
            if (bytes_read <= 0) {
                if (bytes_read == 0) {
                    printf("Parent closed the pipe. Exiting child.\n");
                } else {
                    perror("read from parent failed");
                }
                break; // Exit loop if read fails or pipe is closed
            }
            buffer[bytes_read] = '\0'; // Null-terminate the string
            printf("Process B says: %s\n", buffer);

            if (strcmp(buffer, "exit") == 0) {
                printf("Child received 'exit' from parent. Exiting.\n");
                break;
            }

            // Write to parent
            printf("Process A (You): ");
            if (fgets(buffer, BUFFER_SIZE, stdin) == NULL) {
                perror("fgets failed in child");
                break;
            }
            // Remove trailing newline character if present
            buffer[strcspn(buffer, "\n")] = '\0';

            write(pipe_child_to_parent[WRITE_END], buffer, strlen(buffer));

            if (strcmp(buffer, "exit") == 0) {
                printf("Process A sent 'exit'. Exiting.\n");
                break;
            }
        }

        // Close remaining pipe ends
        close(pipe_parent_to_child[READ_END]);
        close(pipe_child_to_parent[WRITE_END]);
        exit(EXIT_SUCCESS);

    } else { // Parent process (Process B)
        // Close unused pipe ends
        close(pipe_parent_to_child[READ_END]);  // Parent won't read from this pipe
        close(pipe_child_to_parent[WRITE_END]); // Parent won't write to this pipe

        printf("Parent Process (Process B) started. Type 'exit' to quit.\n");

        while (1) {
            // Write to child
            printf("Process B (You): ");
            if (fgets(buffer, BUFFER_SIZE, stdin) == NULL) {
                perror("fgets failed in parent");
                break;
            }
            // Remove trailing newline character if present
            buffer[strcspn(buffer, "\n")] = '\0';

            write(pipe_parent_to_child[WRITE_END], buffer, strlen(buffer));

            if (strcmp(buffer, "exit") == 0) {
                printf("Process B sent 'exit'. Exiting.\n");
                break;
            }

            // Read from child
            bytes_read = read(pipe_child_to_parent[READ_END], buffer, BUFFER_SIZE - 1);
            if (bytes_read <= 0) {
                if (bytes_read == 0) {
                    printf("Child closed the pipe. Exiting parent.\n");
                } else {
                    perror("read from child failed");
                }
                break; // Exit loop if read fails or pipe is closed
            }
            buffer[bytes_read] = '\0'; // Null-terminate the string
            printf("Process A says: %s\n", buffer);

            if (strcmp(buffer, "exit") == 0) {
                printf("Parent received 'exit' from child. Exiting.\n");
                break;
            }
        }

        // Close remaining pipe ends
        close(pipe_parent_to_child[WRITE_END]);
        close(pipe_child_to_parent[READ_END]);

        // Wait for the child process to terminate
        wait(NULL);
        printf("Child process terminated. Parent exiting.\n");
        exit(EXIT_SUCCESS);
    }

    return 0; // Should not be reached
}

