    fgets(message, MAX_MESSAGE_LENGTH, stdin);
    write(pipeFds[PARENT_WRITE_FD], message, strlen(message) + 1);

    close(pipeFds[PARENT_WRITE_FD]); // Close write end of parent pipe

    read(pipeFds[PARENT_READ_FD], message, MAX_MESSAGE_LENGTH);
    printf("Child: %s\n", message);

    close(pipeFds[PARENT_READ_FD]); // Close read end of parent pipe
}

// Function to handle child process
void childProcess(int pipeFds[]) {
    char message[MAX_MESSAGE_LENGTH];
    close(pipeFds[PARENT_READ_FD]);  // Close unused read end of parent pipe
    close(pipeFds[PARENT_WRITE_FD]); // Close unused write end of parent pipe

    read(pipeFds[CHILD_READ_FD], message, MAX_MESSAGE_LENGTH);
    printf("Parent: %s\n", message);

    printf("Child: ");
    fgets(message, MAX_MESSAGE_LENGTH, stdin);
    write(pipeFds[CHILD_WRITE_FD], message, strlen(message) + 1);

    close(pipeFds[CHILD_READ_FD]);  // Close read end of child pipe
    close(pipeFds[CHILD_WRITE_FD]); // Close write end of child pipe
}

int main() {
    int pipeFds[4];
    pid_t pid;

    // Create two pipes
    if (pipe(pipeFds) == -1 || pipe(pipeFds + 2) == -1) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    // Create child process
    pid = fork();
    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) {
        // Child process
        childProcess(pipeFds);
    } else {
        // Parent process
        parentProcess(pipeFds);
        wait(NULL); // Wait for child process to finish
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define BUFFER_SIZE 1024

int main() {
    int pipefd1[2], pipefd2[2];
    pid_t pid;
    char buffer[BUFFER_SIZE];
    int n;

    // Create the first pipe for parent to child communication
    if (pipe(pipefd1) == -1) {
        perror("pipe1");
        exit(EXIT_FAILURE);
    }

    // Create the second pipe for child to parent communication
    if (pipe(pipefd2) == -1) {
        perror("pipe2");
        exit(EXIT_FAILURE);
    }

    // Fork a child process
    pid = fork();

    if (pid < 0) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) {
        // Child process
        close(pipefd1[1]);  // Close the writing end of the first pipe
        close(pipefd2[0]);  // Close the reading end of the second pipe

        while (1) {
            // Read from the second pipe (parent to child)
            n = read(pipefd2[1], buffer, BUFFER_SIZE);
            if (n > 0) {
                buffer[n] = '\0';
                printf("Child received: %s", buffer);
            }

            // Write to the first pipe (child to parent)
            printf("Child: ");
            fgets(buffer, BUFFER_SIZE, stdin);
            write(pipefd1[0], buffer, strlen(buffer) + 1);

            // Check for exit condition
            if (strcmp(buffer, "exit\n") == 0) {
                break;
            }
        }

        close(pipefd1[0]);
        close(pipefd2[1]);
    } else {
        // Parent process
        close(pipefd1[0]);  // Close the reading end of the first pipe
        close(pipefd2[1]);  // Close the writing end of the second pipe

        while (1) {
            // Read from the first pipe (child to parent)
            n = read(pipefd1[1], buffer, BUFFER_SIZE);
            if (n > 0) {
                buffer[n] = '\0';
                printf("Parent received: %s", buffer);
            }

            // Write to the second pipe (parent to child)
            printf("Parent: ");
            fgets(buffer, BUFFER_SIZE, stdin);
            write(pipefd2[0], buffer, strlen(buffer) + 1);

            // Check for exit condition
            if (strcmp(buffer, "exit\n") == 0) {
                break;
            }
        }

        close(pipefd1[1]);
        close(pipefd2[0]);
    }

    return 0;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_FILES 10
#define MAX_FILENAME 50
#define MAX_CONTENT 1000

// File structure to represent a file in the file system
typedef struct {
    char filename[MAX_FILENAME];
    char content[MAX_CONTENT];
    int is_used;
    int size;
} File;

// File system structure
typedef struct {
    File files[MAX_FILES];
} FileSystem;

// Function prototypes
void initializeFileSystem(FileSystem *fs);
void createFile(FileSystem *fs, const char *filename);
void writeFile(FileSystem *fs, const char *filename, const char *content);
void readFile(FileSystem *fs, const char *filename);
void deleteFile(FileSystem *fs, const char *filename);
void listFiles(FileSystem *fs);

// Initialize the file system
void initializeFileSystem(FileSystem *fs) {
    for (int i = 0; i < MAX_FILES; i++) {
        fs->files[i].is_used = 0;
        strcpy(fs->files[i].filename, "");
        strcpy(fs->files[i].content, "");
        fs->files[i].size = 0;
    }
}

// Create a new file
void createFile(FileSystem *fs, const char *filename) {
    // Check if file system is full
    int free_slot = -1;
    for (int i = 0; i < MAX_FILES; i++) {
        if (!fs->files[i].is_used) {
            free_slot = i;
            break;
        }
    }

    if (free_slot == -1) {
        printf("File system is full. Cannot create more files.\n");
        return;
    }

    // Check if file already exists
    for (int i = 0; i < MAX_FILES; i++) {
        if (fs->files[i].is_used && strcmp(fs->files[i].filename, filename) == 0) {
            printf("File '%s' already exists.\n", filename);
            return;
        }
    }

    // Create the file
    strcpy(fs->files[free_slot].filename, filename);
    fs->files[free_slot].is_used = 1;
    fs->files[free_slot].size = 0;
    printf("File '%s' created successfully.\n", filename);
}

// Write content to a file
void writeFile(FileSystem *fs, const char *filename, const char *content) {
    // Find the file
    for (int i = 0; i < MAX_FILES; i++) {
        if (fs->files[i].is_used && strcmp(fs->files[i].filename, filename) == 0) {
            strcpy(fs->files[i].content, content);
            fs->files[i].size = strlen(content);
            printf("Content written to '%s' successfully.\n", filename);
            return;
        }
    }

    printf("File '%s' not found.\n", filename);
}

// Read content of a file
void readFile(FileSystem *fs, const char *filename) {
    // Find the file
    for (int i = 0; i < MAX_FILES; i++) {
        if (fs->files[i].is_used && strcmp(fs->files[i].filename, filename) == 0) {
            printf("Content of '%s':\n%s\n", filename, fs->files[i].content);
            return;
        }
    }

    printf("File '%s' not found.\n", filename);
}

// Delete a file
void deleteFile(FileSystem *fs, const char *filename) {
    // Find the file
    for (int i = 0; i < MAX_FILES; i++) {
        if (fs->files[i].is_used && strcmp(fs->files[i].filename, filename) == 0) {
            fs->files[i].is_used = 0;
            strcpy(fs->files[i].filename, "");
            strcpy(fs->files[i].content, "");
            fs->files[i].size = 0;
            printf("File '%s' deleted successfully.\n", filename);
            return;
        }
    }

    printf("File '%s' not found.\n", filename);
}

// List all files in the file system
void listFiles(FileSystem *fs) {
    printf("Files in the file system:\n");
    int file_count = 0;
    for (int i = 0; i < MAX_FILES; i++) {
        if (fs->files[i].is_used) {
            printf("%s (Size: %d bytes)\n", fs->files[i].filename, fs->files[i].size);
            file_count++;
        }
    }

    if (file_count == 0) {
        printf("No files in the file system.\n");
    }
}

// Main function to demonstrate file system operations
int main() {
    FileSystem fs;
