typedef struct {
    char name[MAX_FILENAME_LEN];
    char content[MAX_CONTENT_LEN];
    bool is_used;
    size_t size;
} File;

typedef struct {
    File files[MAX_FILES];
    int file_count;
} FileSystem;

void initialize_fs(FileSystem *fs) {
    fs->file_count = 0;
    for (int i = 0; i < MAX_FILES; i++) {
        fs->files[i].is_used = false;
        fs->files[i].name[0] = '\0';
        fs->files[i].content[0] = '\0';
        fs->files[i].size = 0;
    }
}

int find_free_slot(FileSystem *fs) {
    for (int i = 0; i < MAX_FILES; i++) {
        if (!fs->files[i].is_used) {
            return i;
        }
    }
    return -1;
}

int find_file(FileSystem *fs, const char *filename) {
    for (int i = 0; i < MAX_FILES; i++) {
        if (fs->files[i].is_used && strcmp(fs->files[i].name, filename) == 0) {
            return i;
        }
    }
    return -1;
}

bool create_file(FileSystem *fs, const char *filename) {
    if (fs->file_count >= MAX_FILES) {
        printf("File system is full. Cannot create more files.\n");
        return false;
    }

    if (find_file(fs, filename) != -1) {
        printf("File '%s' already exists.\n", filename);
        return false;
    }

    int slot = find_free_slot(fs);
    if (slot == -1) {
        printf("No free slots available.\n");
        return false;
    }

    strncpy(fs->files[slot].name, filename, MAX_FILENAME_LEN - 1);
    fs->files[slot].name[MAX_FILENAME_LEN - 1] = '\0';
    fs->files[slot].content[0] = '\0';
    fs->files[slot].size = 0;
    fs->files[slot].is_used = true;
    fs->file_count++;

    printf("File '%s' created successfully.\n", filename);
    return true;
}

bool delete_file(FileSystem *fs, const char *filename) {
    int index = find_file(fs, filename);
    if (index == -1) {
        printf("File '%s' not found.\n", filename);
        return false;
    }

    fs->files[index].is_used = false;
    fs->files[index].name[0] = '\0';
    fs->files[index].content[0] = '\0';
    fs->files[index].size = 0;
    fs->file_count--;

    printf("File '%s' deleted successfully.\n", filename);
    return true;
}

bool write_file(FileSystem *fs, const char *filename, const char *content) {
    int index = find_file(fs, filename);
    if (index == -1) {
        printf("File '%s' not found.\n", filename);
        return false;
    }

    strncpy(fs->files[index].content, content, MAX_CONTENT_LEN - 1);
    fs->files[index].content[MAX_CONTENT_LEN - 1] = '\0';
    fs->files[index].size = strlen(content);

    printf("Content written to file '%s' successfully.\n", filename);
    return true;
}

void read_file(FileSystem *fs, const char *filename) {
    int index = find_file(fs, filename);
    if (index == -1) {
        printf("File '%s' not found.\n", filename);
        return;
    }

    printf("Content of file '%s':\n%s\n", filename, fs->files[index].content);
}

void list_files(FileSystem *fs) {
    printf("\nFile System Contents:\n");
    printf("Total files: %d/%d\n", fs->file_count, MAX_FILES);
    printf("------------------------\n");

    for (int i = 0; i < MAX_FILES; i++) {
        if (fs->files[i].is_used) {
            printf("%d. %s (%zu bytes)\n", i+1, fs->files[i].name, fs->files[i].size);
        }
    }

    printf("------------------------\n");
}

