#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h> // For random content generation

#define MAX_FILES 10
#define FILENAME_MAX_LEN 16 // Including null terminator
#define FILE_CONTENT_MAX_SIZE 128 // Max bytes per file
#define MAX_COMMAND_LEN 64

// --- Data Structures ---

typedef struct {
    char filename[FILENAME_MAX_LEN];
    char content[FILE_CONTENT_MAX_SIZE];
    int size; // Current actual size of the content in bytes
    int in_use; // 1 if file entry is occupied, 0 otherwise
} FileEntry;

// Our simple file system "disk"
FileEntry file_system[MAX_FILES];

// --- Helper Functions ---

// Initializes the file system
void initialize_file_system() {
    for (int i = 0; i < MAX_FILES; i++) {
        file_system[i].in_use = 0; // Mark all entries as free
        memset(file_system[i].filename, 0, FILENAME_MAX_LEN);
        memset(file_system[i].content, 0, FILE_CONTENT_MAX_SIZE);
        file_system[i].size = 0;
    }
    printf("File system initialized.\n");
}

// Finds a free file entry, returns its index or -1 if none available
int find_free_entry() {
    for (int i = 0; i < MAX_FILES; i++) {
        if (file_system[i].in_use == 0) {
            return i;
        }
    }
    return -1; // No free entry
}

// Finds a file by name, returns its index or -1 if not found
int find_file_by_name(const char *filename) {
    for (int i = 0; i < MAX_FILES; i++) {
        if (file_system[i].in_use == 1 && strcmp(file_system[i].filename, filename) == 0) {
            return i;
        }
    }
    return -1; // File not found
}

// --- File System Operations ---

// Creates a new file
void create_file(const char *filename) {
    if (strlen(filename) >= FILENAME_MAX_LEN) {
        printf("Error: Filename '%s' is too long. Max %d characters.\n", filename, FILENAME_MAX_LEN - 1);
        return;
    }

    if (find_file_by_name(filename) != -1) {
        printf("Error: File '%s' already exists.\n", filename);
        return;
    }

    int free_index = find_free_entry();
    if (free_index == -1) {
        printf("Error: File system is full. Cannot create '%s'.\n", filename);
        return;
    }

    FileEntry *new_file = &file_system[free_index];
    strcpy(new_file->filename, filename);
    new_file->in_use = 1;
    new_file->size = 0; // Initially empty
    printf("File '%s' created successfully.\n", filename);
}

// Deletes a file
void delete_file(const char *filename) {
    int index = find_file_by_name(filename);
    if (index == -1) {
        printf("Error: File '%s' not found.\n", filename);
        return;
    }

    FileEntry *file_to_delete = &file_system[index];
    file_to_delete->in_use = 0;
    memset(file_to_delete->filename, 0, FILENAME_MAX_LEN);
    memset(file_to_delete->content, 0, FILE_CONTENT_MAX_SIZE);
    file_to_delete->size = 0;
    printf("File '%s' deleted successfully.\n", filename);
}

// Writes content to a file
void write_file(const char *filename, const char *content) {
    int index = find_file_by_name(filename);
    if (index == -1) {
        printf("Error: File '%s' not found.\n", filename);
        return;
    }

    FileEntry *file = &file_system[index];
    size_t content_len = strlen(content);

    if (content_len >= FILE_CONTENT_MAX_SIZE) {
        printf("Error: Content for '%s' is too large. Max %d bytes. Truncating.\n", filename, FILE_CONTENT_MAX_SIZE - 1);
        // Truncate content if it's too long
        strncpy(file->content, content, FILE_CONTENT_MAX_SIZE - 1);
        file->content[FILE_CONTENT_MAX_SIZE - 1] = '\0';
        file->size = FILE_CONTENT_MAX_SIZE - 1;
    } else {
        strcpy(file->content, content);
        file->size = content_len;
    }
    printf("Content written to file '%s'. Current size: %d bytes.\n", filename, file->size);
}

// Reads content from a file
void read_file(const char *filename) {
    int index = find_file_by_name(filename);
    if (index == -1) {
        printf("Error: File '%s' not found.\n", filename);
        return;
    }

    FileEntry *file = &file_system[index];
    if (file->size == 0) {
        printf("File '%s' is empty.\n", filename);
    } else {
        printf("--- Content of '%s' (Size: %d bytes) ---\n", filename, file->size);
        printf("%s\n", file->content);
        printf("---------------------------------------\n");
    }
}

// Lists all files in the file system
void list_files() {
    printf("\n--- Files in File System (%d/%d used) ---\n", MAX_FILES - find_free_entry(), MAX_FILES);
    int found_files = 0;
    for (int i = 0; i < MAX_FILES; i++) {
        if (file_system[i].in_use == 1) {
            printf("  - %s (Size: %d bytes)\n", file_system[i].filename, file_system[i].size);
            found_files++;
        }
    }
    if (found_files == 0) {
        printf("  No files present.\n");
    }
    printf("---------------------------------------\n");
}

// Generates random content for demonstration
void generate_random_content(char *buffer, int max_len) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 ";
    int len = rand() % (max_len - 1) + 1; // Random length between 1 and max_len-1
    for (int i = 0; i < len; i++) {
        buffer[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    buffer[len] = '\0';
}

// --- Main Program Loop ---

void display_help() {
    printf("\n--- File System Commands ---\n");
    printf("  create <filename>          - Creates a new file.\n");
    printf("  delete <filename>          - Deletes a file.\n");
    printf("  write <filename> <content> - Writes content to a file. Use quotes for multi-word content.\n");
    printf("  read <filename>            - Reads and displays file content.\n");
    printf("  list                       - Lists all files in the system.\n");
    printf("  help                       - Displays this help message.\n");
    printf("  exit                       - Exits the simulator.\n");
    printf("----------------------------\n");
}

int main() {
    srand(time(NULL)); // Seed for random content generation

    initialize_file_system();
    display_help();

    char command[MAX_COMMAND_LEN];
    char arg1[FILENAME_MAX_LEN];
    char arg2[FILE_CONTENT_MAX_SIZE];
    char *token;

    while (1) {
        printf("\nfs> ");
        if (fgets(command, sizeof(command), stdin) == NULL) {
            continue; // Handle EOF or error
        }

        // Remove newline character
        command[strcspn(command, "\n")] = '\0';

        // Tokenize the command
        char *cmd_copy = strdup(command); // Duplicate to preserve original for parsing
        if (cmd_copy == NULL) {
            perror("strdup");
            return 1;
        }

        token = strtok(cmd_copy, " ");

        if (token == NULL) {
            free(cmd_copy);
            continue; // Empty command
        }

        if (strcmp(token, "create") == 0) {
            token = strtok(NULL, " ");
            if (token) {
                create_file(token);
            } else {
                printf("Usage: create <filename>\n");
            }
        } else if (strcmp(token, "delete") == 0) {
            token = strtok(NULL, " ");
            if (token) {
                delete_file(token);
            } else {
                printf("Usage: delete <filename>\n");
            }
        } else if (strcmp(token, "write") == 0) {
            token = strtok(NULL, " "); // Get filename
            if (token) {
                strcpy(arg1, token); // Store filename

                // Get the rest of the line as content
                char *content_start = command + (token - cmd_copy) + strlen(token) + 1;
                if (content_start < command + strlen(command)) { // Check if there's content
                    // Handle quoted strings for content (optional but good idea)
                    if (*content_start == '"') { // If content starts with a quote
                        content_start++; // Skip the opening quote
                        char *end_quote = strchr(content_start, '"');
                        if (end_quote) {
                            *end_quote = '\0'; // Null-terminate at the closing quote
                        }
                    }
                    write_file(arg1, content_start);
                } else {
                    printf("Usage: write <filename> <content>. Use quotes around content for multiple words.\n");
                }
            } else {
                printf("Usage: write <filename> <content>. Use quotes around content for multiple words.\n");
            }
        } else if (strcmp(token, "read") == 0) {
            token = strtok(NULL, " ");
            if (token) {
                read_file(token);
            } else {
                printf("Usage: read <filename>\n");
            }
        } else if (strcmp(token, "list") == 0) {
            list_files();
        } else if (strcmp(token, "help") == 0) {
            display_help();
        } else if (strcmp(token, "exit") == 0) {
            printf("Exiting file system simulator.\n");
            free(cmd_copy);
            break;
        } else {
            printf("Unknown command: '%s'. Type 'help' for available commands.\n", token);
        }
        free(cmd_copy);
    }

    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAX_FILES 10
#define MAX_NAME 20
#define MAX_CONTENT 1024

typedef struct {
    char name[MAX_NAME];
    char content[MAX_CONTENT];
    int used; // 0 = free, 1 = used
} File;

File files[MAX_FILES];

void initialize_files() {
    for (int i = 0; i < MAX_FILES; i++) {
        files[i].used = 0;
    }
}

int find_file(const char *name) {
    for (int i = 0; i < MAX_FILES; i++) {
        if (files[i].used && strcmp(files[i].name, name) == 0)
            return i;
    }
    return -1;
}

int create_file(const char *name) {
    if (find_file(name) >= 0) {
        printf("File with that name already exists.\n");
        return -1;
    }
    for (int i = 0; i < MAX_FILES; i++) {
        if (!files[i].used) {
            strncpy(files[i].name, name, MAX_NAME);
            files[i].name[MAX_NAME-1] = '\0';
            files[i].content[0] = '\0';
            files[i].used = 1;
            printf("File '%s' created.\n", name);
            return i;
