#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define constants for the file system
#define MAX_FILES 6
#define FILENAME_MAX_LEN 16 // Including null terminator
#define FILE_CONTENT_MAX_LEN 256 // Max content for a file, including null terminator

// Structure to represent a file
typedef struct {
    char filename[FILENAME_MAX_LEN];
    char content[FILE_CONTENT_MAX_LEN];
    int in_use; // 0 if free, 1 if in use
    int size;   // Actual size of the content (excluding null terminator)
} File;

// Global array to represent our file system (simulated disk)
File file_system[MAX_FILES];

// --- Helper Functions ---

// Initializes the file system
void initialize_file_system() {
    for (int i = 0; i < MAX_FILES; i++) {
        file_system[i].in_use = 0; // Mark all files as free
        file_system[i].size = 0;
        memset(file_system[i].filename, 0, FILENAME_MAX_LEN);
        memset(file_system[i].content, 0, FILE_CONTENT_MAX_LEN);
    }
    printf("File system initialized. Ready to use %d files.\n", MAX_FILES);
}

// Finds a file by its name and returns its index, or -1 if not found
int find_file_index(const char *filename) {
    for (int i = 0; i < MAX_FILES; i++) {
        if (file_system[i].in_use && strcmp(file_system[i].filename, filename) == 0) {
            return i;
        }
    }
    return -1; // File not found
}

// Finds the first free slot and returns its index, or -1 if no free slot
int find_free_slot() {
    for (int i = 0; i < MAX_FILES; i++) {
        if (!file_system[i].in_use) {
            return i;
        }
    }
    return -1; // No free slot
}

// --- File System Operations ---

// Creates a new file
void create_file(const char *filename) {
    if (strlen(filename) >= FILENAME_MAX_LEN) {
        printf("Error: Filename '%s' is too long (max %d characters).\n", filename, FILENAME_MAX_LEN - 1);
        return;
    }

    if (find_file_index(filename) != -1) {
        printf("Error: File '%s' already exists.\n", filename);
        return;
    }

    int free_slot = find_free_slot();
    if (free_slot == -1) {
        printf("Error: File system is full. Cannot create '%s'.\n", filename);
        return;
    }

    strcpy(file_system[free_slot].filename, filename);
    file_system[free_slot].in_use = 1;
    file_system[free_slot].size = 0; // New file starts empty
    memset(file_system[free_slot].content, 0, FILE_CONTENT_MAX_LEN); // Ensure content is empty
    printf("File '%s' created successfully at slot %d.\n", filename, free_slot);
}

// Writes content to a file
void write_file(const char *filename, const char *content) {
    int index = find_file_index(filename);
    if (index == -1) {
        printf("Error: File '%s' not found.\n", filename);
        return;
    }

    int content_len = strlen(content);
    if (content_len >= FILE_CONTENT_MAX_LEN) {
        printf("Error: Content for '%s' is too long (max %d bytes). Content truncated.\n", filename, FILE_CONTENT_MAX_LEN - 1);
        strncpy(file_system[index].content, content, FILE_CONTENT_MAX_LEN - 1);
        file_system[index].content[FILE_CONTENT_MAX_LEN - 1] = '\0'; // Ensure null termination
        file_system[index].size = FILE_CONTENT_MAX_LEN - 1;
    } else {
        strcpy(file_system[index].content, content);
        file_system[index].size = content_len;
    }
    printf("Content written to file '%s'. (Size: %d bytes)\n", filename, file_system[index].size);
}

// Reads and displays content of a file
void read_file(const char *filename) {
    int index = find_file_index(filename);
    if (index == -1) {
        printf("Error: File '%s' not found.\n", filename);
        return;
    }

    printf("--- Content of '%s' ---\n", filename);
    if (file_system[index].size == 0) {
        printf("(Empty file)\n");
    } else {
        printf("%s\n", file_system[index].content);
    }
    printf("------------------------\n");
}

// Deletes a file
void delete_file(const char *filename) {
    int index = find_file_index(filename);
    if (index == -1) {
        printf("Error: File '%s' not found.\n", filename);
        return;
    }

    file_system[index].in_use = 0;
    file_system[index].size = 0;
    memset(file_system[index].filename, 0, FILENAME_MAX_LEN);
    memset(file_system[index].content, 0, FILE_CONTENT_MAX_LEN);
