// Structure to represent a file
typedef struct {
    char name[MAX_FILE_NAME];
    char content[MAX_FILE_CONTENT];
    int size;
} File;

// Function to create a new file
void createFile(File files[], int *numFiles) {
    if (*numFiles < MAX_FILES) {
        printf("Enter file name: ");
        fgets(files[*numFiles].name, MAX_FILE_NAME, stdin);
        files[*numFiles].name[strcspn(files[*numFiles].name, "\n")] = 0; // Remove newline character
        strcpy(files[*numFiles].content, "");
        files[*numFiles].size = 0;
        (*numFiles)++;
        printf("File created successfully.\n");
    } else {
        printf("Maximum number of files reached.\n");
    }
}

// Function to delete a file
void deleteFile(File files[], int *numFiles) {
    if (*numFiles > 0) {
        printf("Enter file name to delete: ");
        char fileName[MAX_FILE_NAME];
        fgets(fileName, MAX_FILE_NAME, stdin);
        fileName[strcspn(fileName, "\n")] = 0; // Remove newline character
        for (int i = 0; i < *numFiles; i++) {
            if (strcmp(files[i].name, fileName) == 0) {
                // Shift files to the left to fill the gap
                for (int j = i; j < *numFiles - 1; j++) {
                    strcpy(files[j].name, files[j + 1].name);
                    strcpy(files[j].content, files[j + 1].content);
                    files[j].size = files[j + 1].size;
                }
                (*numFiles)--;
                printf("File deleted successfully.\n");
                return;
            }
        }
        printf("File not found.\n");
    } else {
        printf("No files available.\n");
    }
}

// Function to display the list of files
void displayFiles(File files[], int numFiles) {
    if (numFiles > 0) {
        printf("List of files:\n");
        for (int i = 0; i < numFiles; i++) {
            printf("%d. %s\n", i + 1, files[i].name);
        }
    } else {
        printf("No files available.\n");
    }
}

// Function to edit the content of a file
void editFile(File files[], int numFiles) {
    if (numFiles > 0) {
        printf("Enter file name to edit: ");
        char fileName[MAX_FILE_NAME];
        fgets(fileName, MAX_FILE_NAME, stdin);
        fileName[strcspn(fileName, "\n")] = 0; // Remove newline character
        for (int i = 0; i < numFiles; i++) {
            if (strcmp(files[i].name, fileName) == 0) {
                printf("Enter new content: ");
                fgets(files[i].content, MAX_FILE_CONTENT, stdin);
                files[i].size = strlen(files[i].content) - 1; // Exclude newline character
                printf("File edited successfully.\n");
                return;
            }
        }
        printf("File not found.\n");
    } else {
        printf("No files available.\n");
    }
}

