#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

// --- Constants ---
#define MAX_FILES 7
#define FILENAME_MAX_LEN 16  // Including null terminator
#define FILE_CONTENT_MAX_LEN 256
#define BLOCK_SIZE 32        // Simulating fixed-size blocks
#define TOTAL_BLOCKS 20      // A small "disk" of 20 blocks

// --- Data Structures ---

// Represents a single file
typedef struct {
    char filename[FILENAME_MAX_LEN];
    int size;               // Size in bytes
    int start_block;        // Index of the first data block
    bool in_use;            // Is this file entry currently active?
} FileEntry;

// Represents a block on our simulated disk
typedef struct {
    char data[BLOCK_SIZE];
    bool in_use;            // Is this block allocated to a file?
} DiskBlock;

// --- Global Variables (Our file system state) ---
FileEntry file_system[MAX_FILES]; // Our "inode table" or file directory
DiskBlock disk[TOTAL_BLOCKS];     // Our simulated "disk"

// --- Helper Functions (Forward Declarations) ---
void initialize_file_system();
int find_free_file_entry();
int find_free_blocks(int num_blocks_needed);
void allocate_blocks(int start_block, int num_blocks);
void free_blocks(int start_block, int num_blocks);
int calculate_num_blocks(int size_bytes);
void write_content_to_blocks(const char *content, int start_block, int content_size);
void read_content_from_blocks(char *buffer, int start_block, int file_size);
void print_disk_usage();
void print_file_system_status();

// --- File System Operations ---
void create_file();
void read_file();
void write_file();
void delete_file();
void list_files();

// --- Main Program ---
int main() {
    initialize_file_system();

    int choice;
    do {
        printf("\n--- Simple File System Menu ---\n");
        printf("1. Create File\n");
        printf("2. Read File\n");
        printf("3. Write File (Append/Overwrite)\n");
        printf("4. Delete File\n");
        printf("5. List Files\n");
        printf("6. View Disk Usage\n");
        printf("0. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);
        while (getchar() != '\n'); // Consume newline

        switch (choice) {
            case 1: create_file(); break;
            case 2: read_file(); break;
            case 3: write_file(); break;
            case 4: delete_file(); break;
            case 5: list_files(); break;
            case 6: print_disk_usage(); break;
            case 0: printf("Exiting file system simulator.\n"); break;
            default: printf("Invalid choice. Please try again.\n");
        }
    } while (choice != 0);

    return 0;
}

// --- Implementation of Helper Functions ---

void initialize_file_system() {
    for (int i = 0; i < MAX_FILES; i++) {
        file_system[i].in_use = false;
        strcpy(file_system[i].filename, "");
        file_system[i].size = 0;
        file_system[i].start_block = -1;
    }

    for (int i = 0; i < TOTAL_BLOCKS; i++) {
        disk[i].in_use = false;
        memset(disk[i].data, 0, BLOCK_SIZE); // Clear block data
    }
    printf("File system initialized.\n");
}

int find_free_file_entry() {
    for (int i = 0; i < MAX_FILES; i++) {
        if (!file_system[i].in_use) {
            return i;
        }
    }
    return -1; // No free entry
}

// Finds a contiguous sequence of free blocks
// Returns the starting block index, or -1 if not enough blocks
int find_free_blocks(int num_blocks_needed) {
    if (num_blocks_needed <= 0) return -1;

    for (int i = 0; i <= TOTAL_BLOCKS - num_blocks_needed; i++) {
        bool contiguous_found = true;
        for (int j = 0; j < num_blocks_needed; j++) {
            if (disk[i + j].in_use) {
                contiguous_found = false;
                // Optimization: If a block is in use, jump past it
                i = i + j;
                break;
            }
        }
        if (contiguous_found) {
            return i; // Found a contiguous block of free space
        }
    }
    return -1; // Not enough contiguous free blocks
}

void allocate_blocks(int start_block, int num_blocks) {
    if (start_block == -1 || num_blocks <= 0) return;
    for (int i = 0; i < num_blocks; i++) {
        if (start_block + i < TOTAL_BLOCKS) {
            disk[start_block + i].in_use = true;
            // Optionally, memset to some pattern to show allocation
            memset(disk[start_block + i].data, 0, BLOCK_SIZE);
        }
    }
}

void free_blocks(int start_block, int num_blocks) {
    if (start_block == -1 || num_blocks <= 0) return;
    for (int i = 0; i < num_blocks; i++) {
        if (start_block + i < TOTAL_BLOCKS) {
            disk[start_block + i].in_use = false;
            memset(disk[start_block + i].data, 0, BLOCK_SIZE); // Clear content
        }
    }
}

int calculate_num_blocks(int size_bytes) {
    if (size_bytes <= 0) return 0;
    return (size_bytes + BLOCK_SIZE - 1) / BLOCK_SIZE; // Ceiling division
}

void write_content_to_blocks(const char *content, int start_block, int content_size) {
    if (start_block == -1 || content == NULL || content_size <= 0) return;

    int current_content_offset = 0;
    int current_block_index = start_block;

    while (current_content_offset < content_size && current_block_index < TOTAL_BLOCKS) {
        int bytes_to_write = BLOCK_SIZE;
        if (current_content_offset + bytes_to_write > content_size) {
            bytes_to_write = content_size - current_content_offset;
        }

        // Ensure the block is marked as in use by the file
        // (It should already be from allocation, but good for robustness)
        disk[current_block_index].in_use = true;
        memcpy(disk[current_block_index].data, content + current_content_offset, bytes_to_write);

        // Pad the rest of the block with zeros if content doesn't fill it
        if (bytes_to_write < BLOCK_SIZE) {
            memset(disk[current_block_index].data + bytes_to_write, 0, BLOCK_SIZE - bytes_to_write);
        }

        current_content_offset += bytes_to_write;
        current_block_index++;
    }
}

void read_content_from_blocks(char *buffer, int start_block, int file_size) {
    if (buffer == NULL || start_block == -1 || file_size <= 0) {
        buffer[0] = '\0'; // Ensure buffer is empty
        return;
    }

    int current_buffer_offset = 0;
    int current_block_index = start_block;

    while (current_buffer_offset < file_size && current_block_index < TOTAL_BLOCKS) {
        int bytes_to_read = BLOCK_SIZE;
        if (current_buffer_offset + bytes_to_read > file_size) {
            bytes_to_read = file_size - current_buffer_offset;
        }

        memcpy(buffer + current_buffer_offset, disk[current_block_index].data, bytes_to_read);

        current_buffer_offset += bytes_to_read;
        current_block_index++;
    }
    buffer[current_buffer_offset] = '\0'; // Null-terminate the string
}

void print_disk_usage() {
    printf("\n--- Disk Usage Map (Block %d to %d) ---\n", 0, TOTAL_BLOCKS - 1);
    for (int i = 0; i < TOTAL_BLOCKS; i++) {
        printf("[%c]", disk[i].in_use ? 'X' : '_'); // X for used, _ for free
        if ((i + 1) % 10 == 0) { // Print 10 blocks per line
            printf("  Block %d-%d\n", i - 9, i);
        }
    }
    if (TOTAL_BLOCKS % 10 != 0) {
        printf("\n");
    }

    int used_blocks = 0;
    for (int i = 0; i < TOTAL_BLOCKS; i++) {
        if (disk[i].in_use) {
            used_blocks++;
        }
    }
    printf("Total Blocks: %d\n", TOTAL_BLOCKS);
    printf("Used Blocks: %d (%.2f%%)\n", used_blocks, (float)used_blocks / TOTAL_BLOCKS * 100);
    printf("Free Blocks: %d\n", TOTAL_BLOCKS - used_blocks);
    printf("Block Size: %d bytes\n", BLOCK_SIZE);
    printf("----------------------------------------\n");
}

void print_file_system_status() {
    printf("\n--- File System Status ---\n");
    printf("%-5s %-16s %-10s %-12s %s\n", "Index", "Filename", "Size (B)", "Start Block", "Status");
    printf("----------------------------------------------------------------\n");
    for (int i = 0; i < MAX_FILES; i++) {
        if (file_system[i].in_use) {
            printf("%-5d %-16s %-10d %-12d %s\n",
                   i,
                   file_system[i].filename,
                   file_system[i].size,
                   file_system[i].start_block,
                   "USED");
        } else {
            printf("%-5d %-16s %-10s %-12s %s\n",
                   i,
                   "N/A",
                   "N/A",
                   "N/A",
                   "FREE");
        }
    }
    printf("----------------------------------------------------------------\n");
}

// --- Implementation of File System Operations ---

void create_file() {
    char filename[FILENAME_MAX_LEN];
    char content[FILE_CONTENT_MAX_LEN];
    int desired_size; // User-specified initial size

    printf("Enter filename (max %d chars): ", FILENAME_MAX_LEN - 1);
    fgets(filename, FILENAME_MAX_LEN, stdin);
    filename[strcspn(filename, "\n")] = 0; // Remove newline

    if (strlen(filename) == 0) {
        printf("Filename cannot be empty.\n");
        return;
    }

    // Check if file already exists
    for (int i = 0; i < MAX_FILES; i++) {
        if (file_system[i].in_use && strcmp(file_system[i].filename, filename) == 0) {
            printf("Error: File '%s' already exists.\n", filename);
            return;
        }
    }

    int file_entry_index = find_free_file_entry();
    if (file_entry_index == -1) {
        printf("Error: File system is full (max %d files).\n", MAX_FILES);
        return;
    }

    printf("Enter initial file content (max %d chars, leave empty for 0 size): ", FILE_CONTENT_MAX_LEN - 1);
    fgets(content, FILE_CONTENT_MAX_LEN, stdin);
    content[strcspn(content, "\n")] = 0; // Remove newline

    desired_size = strlen(content);
    if (desired_size == 0) {
        printf("Creating empty file.\n");
    }

    int blocks_needed = calculate_num_blocks(desired_size);
    if (blocks_needed == 0 && desired_size > 0) { // Should not happen with positive desired_size
        printf("Error: Could not calculate blocks for non-zero size.\n");
        return;
    }

    int start_block = -1;
    if (blocks_needed > 0) {
        start_block = find_free_blocks(blocks_needed);
        if (start_block == -1) {
            printf("Error: Not enough contiguous disk space to create file '%s' with size %d bytes (%d blocks needed).\n",
                   filename, desired_size, blocks_needed);
            return;
        }
        allocate_blocks(start_block, blocks_needed);
        write_content_to_blocks(content, start_block, desired_size);
    }

    // Update file entry
    file_system[file_entry_index].in_use = true;
    strcpy(file_system[file_entry_index].filename, filename);
    file_system[file_entry_index].size = desired_size;
    file_system[file_entry_index].start_block = start_block;

    printf("File '%s' created successfully! Size: %d bytes, Start Block: %d.\n",
           filename, file_system[file_entry_index].size, file_system[file_entry_index].start_block);
}

void read_file() {
    char filename[FILENAME_MAX_LEN];
    char buffer[FILE_CONTENT_MAX_LEN + 1]; // +1 for null terminator

    printf("Enter filename to read: ");
    fgets(filename, FILENAME_MAX_LEN, stdin);
    filename[strcspn(filename, "\n")] = 0; // Remove newline

    int file_index = -1;
    for (int i = 0; i < MAX_FILES; i++) {
        if (file_system[i].in_use && strcmp(file_system[i].filename, filename) == 0) {
            file_index = i;
            break;
        }
    }

    if (file_index == -1) {
        printf("Error: File '%s' not found.\n", filename);
        return;
    }

    if (file_system[file_index].size == 0) {
        printf("File '%s' is empty.\n", filename);
        return;
    }

    read_content_from_blocks(buffer, file_system[file_index].start_block, file_system[file_index].size);
    printf("--- Content of '%s' (%d bytes) ---\n", filename, file_system[file_index].size);
    printf("%s\n", buffer);
    printf("-----------------------------------\n");
}

void write_file() {
    char filename[FILENAME_MAX_LEN];
    char new_content[FILE_CONTENT_MAX_LEN];

    printf("Enter filename to write to: ");
    fgets(filename, FILENAME_MAX_LEN, stdin);
    filename[strcspn(filename, "\n")] = 0; // Remove newline

    int file_index = -1;
    for (int i = 0; i < MAX_FILES; i++) {
        if (file_system[i].in_use && strcmp(file_system[i].filename, filename) == 0) {
            file_index = i;
            break;
        }
    }

    if (file_index == -1) {
        printf("Error: File '%s' not found.\n", filename);
        return;
    }

    printf("Enter new content (max %d chars, current size: %d bytes):\n", FILE_CONTENT_MAX_LEN - 1, file_system[file_index].size);
    fgets(new_content, FILE_CONTENT_MAX_LEN, stdin);
    new_content[strcspn(new_content, "\n")] = 0; // Remove newline

    int new_size = strlen(new_content);
    int old_blocks = calculate_num_blocks(file_system[file_index].size);
    int new_blocks = calculate_num_blocks(new_size);

    // Case 1: New content fits within existing blocks
    if (new_blocks <= old_blocks) {
        write_content_to_blocks(new_content, file_system[file_index].start_block, new_size);
        // If content is smaller, we might need to clear trailing parts of the last block
        if (new_size < file_system[file_index].size) {
            // Calculate actual occupied bytes in the last block
            int last_block_idx = file_system[file_index].start_block + new_blocks - 1;
            int bytes_in_last_block = new_size % BLOCK_SIZE;
            if (bytes_in_last_block == 0 && new_size > 0) { // If new_size is a multiple of BLOCK_SIZE
                bytes_in_last_block = BLOCK_SIZE;
            } else if (new_size == 0) { // If new file is empty
                bytes_in_last_block = 0;
            }

            if (bytes_in_last_block > 0) {
                 memset(disk[last_block_idx].data + bytes_in_last_block, 0, BLOCK_SIZE - bytes_in_last_block);
            }
        }
        // If fewer blocks are now truly needed, free the excess blocks
        if (new_blocks < old_blocks) {
            free_blocks(file_system[file_index].start_block + new_blocks, old_blocks - new_blocks);
        }
    }
    // Case 2: New content requires more blocks
    else {
        // First, free old blocks
        if (file_system[file_index].start_block != -1) {
            free_blocks(file_system[file_index].start_block, old_blocks);
        }

        // Find new contiguous blocks
        int new_start_block = find_free_blocks(new_blocks);
        if (new_start_block == -1) {
            printf("Error: Not enough contiguous disk space to write updated content for '%s'.\n", filename);
            // Attempt to restore old state or mark file as corrupted? For simplicity, we just fail.
            file_system[file_index].in_use = false; // Mark as deleted due to write failure
            printf("File '%s' removed due to space limitations during write.\n", filename);
            return;
        }

        allocate_blocks(new_start_block, new_blocks);
        file_system[file_index].start_block = new_start_block;
        write_content_to_blocks(new_content, file_system[file_index].start_block, new_size);
    }

    file_system[file_index].size = new_size;
    printf("File '%s' updated successfully! New size: %d bytes.\n", filename, new_size);
}

void delete_file() {
    char filename[FILENAME_MAX_LEN];

    printf("Enter filename to delete: ");
    fgets(filename, FILENAME_MAX_LEN, stdin);
    filename[strcspn(filename, "\n")] = 0; // Remove newline

    int file_index = -1;
    for (int i = 0; i < MAX_FILES; i++) {
        if (file_system[i].in_use && strcmp(file_system[i].filename, filename) == 0) {
            file_index = i;
            break;
        }
    }

    if (file_index == -1) {
        printf("Error: File '%s' not found.\n", filename);
        return;
    }

    // Free disk blocks
    if (file_system[file_index].start_block != -1 && file_system[file_index].size > 0) {
        int num_blocks_occupied = calculate_num_blocks(file_system[file_index].size);
        free_blocks(file_system[file_index].start_block, num_blocks_occupied);
    }

    // Clear file entry
    file_system[file_index].in_use = false;
    strcpy(file_system[file_index].filename, "");
    file_system[file_index].size = 0;
    file_system[file_index].start_block = -1;

    printf("File '%s' deleted successfully.\n", filename);
}

void list_files() {
    printf("\n--- List of Files ---\n");
    bool any_files = false;
    printf("%-5s %-16s %-10s %s\n", "ID", "Filename", "Size (B)", "Start Block");
    printf("--------------------------------------------\n");
    for (int i = 0; i < MAX_FILES; i++) {
        if (file_system[i].in_use) {
            printf("%-5d %-16s %-10d %d\n",
                   i,
                   file_system[i].filename,
                   file_system[i].size,
                   file_system[i].start_block);
            any_files = true;
        }
    }
    if (!any_files) {
        printf("No files in the file system.\n");
    }
    printf("--------------------------------------------\n");
}

#include <stdio.h>
#include <string.h>

#define MAX_FILES 7
#define MAX_FILENAME_LEN 32
#define MAX_FILE_CONTENT 256

typedef struct {
    char name[MAX_FILENAME_LEN];
    char content[MAX_FILE_CONTENT];
    int used;
} File;

File files[MAX_FILES];

// Find a file by name, returns index or -1 if not found
int find_file(const char *name) {
    for (int i = 0; i < MAX_FILES; i++) {
        if (files[i].used && strcmp(files[i].name, name) == 0)
            return i;
    }
    return -1;
}

// Create new file
void create_file() {
    int slot = -1;
    for (int i = 0; i < MAX_FILES; i++) {
        if (!files[i].used) {
            slot = i;
            break;
        }
    }
    if (slot == -1) {
        printf("File system is full!\n");
        return;
    }

    char name[MAX_FILENAME_LEN];
    printf("Enter filename: ");
    scanf("%s", name);
    if (find_file(name) != -1) {
        printf("File already exists!\n");
        return;
    }
    strcpy(files[slot].name, name);
    files[slot].content[0] = '\0';
    files[slot].used = 1;
    printf("File '%s' created.\n", name);
}

// Write to file
void write_file() {
    char name[MAX_FILENAME_LEN];
    printf("Enter filename to write to: ");
    scanf("%s", name);

    int idx = find_file(name);
    if (idx == -1) {
        printf("File not found!\n");
        return;
    }

    getchar(); // remove leftover newline
    printf("Enter content (max %d chars): ", MAX_FILE_CONTENT-1);
    fgets(files[idx].content, MAX_FILE_CONTENT, stdin);
    // remove newline from fgets
    files[idx].content[strcspn(files[idx].content, "\n")] = 0;
    printf("Written to '%s'.\n", name);
}

// Read from file
void read_file() {
    char name[MAX_FILENAME_LEN];
    printf("Enter filename to read: ");
    scanf("%s", name);

    int idx = find_file(name);
    if (idx == -1) {
        printf("File not found!\n");
        return;
    }

    printf("Content of '%s':\n%s\n", name, files[idx].content);
}

// Delete file
void delete_file() {
    char name[MAX_FILENAME_LEN];
    printf("Enter filename to delete: ");
    scanf("%s", name);

    int idx = find_file(name);
    if (idx == -1) {
        printf("File not found!\n");
        return;
    }
    files[idx].used = 0;
    printf("File '%s' deleted.\n", name);
}

// List all files
void list_files() {
    printf("Files in system:\n");
    int found = 0;
    for (int i = 0; i < MAX_FILES; i++) {
        if (files[i].used) {
            printf(" - %s\n", files[i].name);
            found = 1;
        }
    }
    if (!found) {
        printf(" No files found.\n");
    }
}

