void menu() {
    printf("\nSimple File System (7 files)\n");
    printf("1. Create file\n");
    printf("2. Write to file\n");
    printf("3. Read file\n");
    printf("4. Delete file\n");
    printf("5. List files\n");
    printf("0. Exit\n");
}

