#define MAX_FILES 7
#define MAX_FILENAME_LENGTH 256
#define MAX_FILE_CONTENT_LENGTH 1024

typedef struct {
    char name[MAX_FILENAME_LENGTH];
    char content[MAX_FILE_CONTENT_LENGTH];
    int is_open;
} File;

File filesystem[MAX_FILES];
int file_count = 0;

void create_file(const char *name) {
    if (file_count >= MAX_FILES) {
        printf("File system is full. Cannot create more files.\n");
        return;
    }

    for (int i = 0; i < file_count; i++) {
        if (strcmp(filesystem[i].name, name) == 0) {
            printf("File already exists: %s\n", name);
            return;
        }
    }

    // Create a new file
    strcpy(filesystem[file_count].name, name);
    filesystem[file_count].is_open = 0;
    filesystem[file_count].content[0] = '\0';
    file_count++;
    printf("File created: %s\n", name);
}

int open_file(const char *name) {
    for (int i = 0; i < file_count; i++) {
        if (strcmp(filesystem[i].name, name) == 0 && !filesystem[i].is_open) {
            filesystem[i].is_open = 1;
            printf("File opened: %s\n", name);
            return i;
        } else if (strcmp(filesystem[i].name, name) == 0 && filesystem[i].is_open) {
            printf("File is already open: %s\n", name);
            return -1;
        }
    }

    printf("File not found: %s\n", name);
    return -1;
}

void close_file(int file_index) {
    if (file_index >= 0 && file_index < file_count && filesystem[file_index].is_open) {
        filesystem[file_index].is_open = 0;
        printf("File closed: %s\n", filesystem[file_index].name);
    } else {
        printf("Invalid file index or file is not open: %d\n", file_index);
    }
}

void read_file(int file_index) {
    if (file_index >= 0 && file_index < file_count && filesystem[file_index].is_open) {
        printf("Content of file %s:\n%s\n", filesystem[file_index].name, filesystem[file_index].content);
    } else {
        printf("Invalid file index or file is not open: %d\n", file_index);
    }
}

void write_file(int file_index, const char *content) {
    if (file_index >= 0 && file_index < file_count && filesystem[file_index].is_open) {
        strcpy(filesystem[file_index].content, content);
        printf("Content written to file %s\n", filesystem[file_index].name);
    } else {
        printf("Invalid file index or file is not open: %d\n", file_index);
    }
}

void delete_file(const char *name) {
    for (int i = 0; i < file_count; i++) {
        if (strcmp(filesystem[i].name, name) == 0) {
            if (filesystem[i].is_open) {
                printf("Cannot delete an open file: %s\n", name);
                return;
            }

            // Shift files to fill the gap
            for (int j = i; j < file_count - 1; j++) {
                filesystem[j] = filesystem[j + 1];
            }
            file_count--;
            printf("File deleted: %s\n", name);
            return;
        }
    }

    printf("File not found: %s\n", name);
}

void list_files() {
    printf("Files in the file system:\n");
    for (int i = 0; i < file_count; i++) {
        printf("%s (Open: %s)\n", filesystem[i].name, filesystem[i].is_open ? "Yes" : "No");
    }
}

