#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Function to generate a weighted random die roll
int weightedDieRoll(double weights[], int numSides) {
    // Validate input
    if (weights == NULL || numSides <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }

    // Calculate total weight
    double totalWeight = 0.0;
    for (int i = 0; i < numSides; i++) {
        if (weights[i] < 0) {
            fprintf(stderr, "Negative weight not allowed\n");
            return -1;
        }
        totalWeight += weights[i];
    }

    // Generate a random number between 0 and total weight
    double randomValue = ((double)rand() / RAND_MAX) * totalWeight;

    // Find which side the random value falls into
    double cumulativeWeight = 0.0;
    for (int i = 0; i < numSides; i++) {
        cumulativeWeight += weights[i];
        if (randomValue <= cumulativeWeight) {
            return i + 1;  // Return 1-indexed side
        }
    }

    // Fallback (should not happen)
    return numSides;
}

// Function to run multiple die rolls and track results
void runDieRollSimulation(double weights[], int numSides, int numRolls) {
    // Initialize roll count array
    int* rollCounts = calloc(numSides, sizeof(int));
    if (rollCounts == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Perform die rolls
    for (int i = 0; i < numRolls; i++) {
        int result = weightedDieRoll(weights, numSides);
        if (result > 0) {
            rollCounts[result - 1]++;
        }
    }

    // Print results
    printf("Die Roll Simulation Results (%d rolls):\n", numRolls);
    for (int i = 0; i < numSides; i++) {
        double percentage = (double)rollCounts[i] / numRolls * 100.0;
        printf("Side %d: %d rolls (%.2f%%)\n", 
               i + 1, rollCounts[i], percentage);
    }

    // Free memory
    free(rollCounts);
}

int main() {
    // Seed random number generator
    srand(time(NULL));

    // Example 1: Six-sided die with standard uniform weights
    printf("Standard Six-Sided Die:\n");
    double standardWeights[] = {1, 1, 1, 1, 1, 1};
    runDieRollSimulation(standardWeights, 6, 10000);

    printf("\n");

    // Example 2: Weighted six-sided die
    printf("Weighted Six-Sided Die:\n");
    double customWeights[] = {2, 1, 1, 1, 1, 4};  // More likely to roll 1 and 6
    runDieRollSimulation(customWeights, 6, 10000);

    return 0;
}

