// Function to simulate a weighted die roll
int weightedDieRoll(double probabilities[], int size) {
    double randomValue = (double)rand() / RAND_MAX;
    double cumulativeProbability = 0.0;

    for (int i = 0; i < size; i++) {
        cumulativeProbability += probabilities[i];
        if (randomValue < cumulativeProbability) {
            return i + 1; // Return the face of the die (1 to 6)
        }
    }

    return size; // In case of rounding errors, return the last face
}

