// Function to simulate rolling an unfair die
int roll_unfair_die(int weights[], int num_sides) {
    if (num_sides <= 0) {
        fprintf(stderr, "Error: Number of sides must be positive.\n");
        return -1; // Indicate an error
    }

    // 1. Calculate the total weight
    int total_weight = 0;
    for (int i = 0; i < num_sides; i++) {
        if (weights[i] < 0) {
            fprintf(stderr, "Error: Weights cannot be negative.\n");
            return -1; // Indicate an error
        }
        total_weight += weights[i];
    }

    if (total_weight == 0) {
        fprintf(stderr, "Error: Total weight cannot be zero. At least one side must have a positive weight.\n");
        return -1; // Indicate an error
    }

    // 2. Generate a random number within the total weight range
    // rand() % total_weight gives a number from 0 to (total_weight - 1)
    int random_value = rand() % total_weight;

    // 3. Determine which side was rolled based on the random value
    int cumulative_weight = 0;
    for (int i = 0; i < num_sides; i++) {
        cumulative_weight += weights[i];
        if (random_value < cumulative_weight) {
            return i + 1; // Die sides are 1-indexed (array is 0-indexed)
        }
    }

    // This part should technically not be reached if total_weight > 0
    // and random_value is correctly generated within [0, total_weight - 1]
    return -1;
}

int main() {
    // Seed the random number generator
    // Using time(NULL) ensures a different sequence of random numbers each time the program runs.
    srand((unsigned int)time(NULL));

    // Define the weights for a 6-sided die
    // Array index 0 corresponds to side 1, index 1 to side 2, etc.
    // Example: (1, 1, 2, 1, 1, 3) means:
    // Side 1: Weight 1
    // Side 2: Weight 1
    // Side 3: Weight 2 (twice as likely as 1 or 2)
    // Side 4: Weight 1
    // Side 5: Weight 1
    // Side 6: Weight 3 (three times as likely as 1 or 2)
    int die_weights[] = {1, 1, 2, 1, 1, 3}; // Weights for sides 1, 2, 3, 4, 5, 6
    int num_sides = sizeof(die_weights) / sizeof(die_weights[0]); // Calculates number of elements

    int num_rolls = 1000000; // Number of times to roll the die
    int results[num_sides];   // To store counts for each side

    // Initialize results array to zeros
    for (int i = 0; i < num_sides; i++) {
        results[i] = 0;
    }

    printf("Simulating rolling an unfair %d-sided die %d times...\n", num_sides, num_rolls);
    printf("Weights assigned (for sides 1 to %d):\n", num_sides);
    for (int i = 0; i < num_sides; i++) {
        printf("Side %d: Weight %d\n", i + 1, die_weights[i]);
    }
    printf("-------------------------------------------\n");

    for (int i = 0; i < num_rolls; i++) {
        int roll = roll_unfair_die(die_weights, num_sides);
        if (roll != -1) { // Check if the roll was successful
            results[roll - 1]++; // Decrement by 1 because outcomes are 1-indexed, array is 0-indexed
        }
    }

    printf("Simulation Results:\n");
    printf("-------------------------------------------\n");
    int total_weight_check = 0;
    for(int i = 0; i < num_sides; i++) {
        total_weight_check += die_weights[i];
    }


    for (int i = 0; i < num_sides; i++) {
        double actual_percentage = (double)results[i] / num_rolls * 100.0;
        double expected_percentage = (double)die_weights[i] / total_weight_check * 100.0;
        printf("Side %d: Count = %d (%.2f%%) | Expected: %.2f%%\n",
               i + 1, results[i], actual_percentage, expected_percentage);
    }
    printf("-------------------------------------------\n");

    // Example of a single roll
    printf("\nRolling the die once: %d\n", roll_unfair_die(die_weights, num_sides));

    return 0;
}

