int weighted_die_roll() {
    // Define cumulative weights for each side of the die
    // Suppose we define the weights as follows:
    // - Side 1: 1
    // - Side 2: 1
    // - Side 3: 2
    // - Side 4: 3
    // - Side 5: 2
    // - Side 6: 1

    int weights[] = {1, 1, 2, 3, 2, 1};
    int total_weight = 0;

    // Calculate total weight
    for (int i = 0; i < 6; i++) {
        total_weight += weights[i];
    }

    // Generate a random number in the range [1, total_weight]
    int rand_num = rand() % total_weight + 1;

    // Determine which side to return based on the cumulative weights
    int cumulative_sum = 0;
    for (int i = 0; i < 6; i++) {
        cumulative_sum += weights[i];
        if (rand_num <= cumulative_sum) {
            return i + 1; // Return the side (1 to 6)
        }
    }

    return 0; // This should never be reached
}

