// Structure to represent a weighted side of the die
typedef struct {
    int value;  // Value of the side (1-6)
    double weight;  // Weight of the side
} Side;

// Function to simulate rolling the die
int roll_die(Side sides[], int num_sides) {
    double random_value = (double)rand() / RAND_MAX;
    double cumulative_prob = 0.0;

    for (int i = 0; i < num_sides; i++) {
        cumulative_prob += sides[i].weight;
        if (random_value <= cumulative_prob) {
            return sides[i].value;
        }
    }

    // Should never reach this point, but return the last side's value just in case
    return sides[num_sides - 1].value;
}

