#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

// Structure to represent the graph
typedef struct Graph {
    int numNodes;
    bool** adjMatrix;
} Graph;

// Function to create a graph
Graph* createGraph(int nodes) {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    graph->numNodes = nodes;

    // Allocate memory for adjacency matrix
    graph->adjMatrix = (bool**)malloc(nodes * sizeof(bool*));
    for (int i = 0; i < nodes; i++) {
        graph->adjMatrix[i] = (bool*)calloc(nodes, sizeof(bool));
    }

    return graph;
}

// Function to add an edge to the graph
void addEdge(Graph* graph, int src, int dest) {
    graph->adjMatrix[src][dest] = true;
}

// DFS utility function to detect cycle
bool isCyclicUtil(Graph* graph, int v, bool* visited, bool* recursionStack) {
    // Mark the current node as visited and part of recursion stack
    if (!visited[v]) {
        visited[v] = true;
        recursionStack[v] = true;

        // Recur for all adjacent vertices
        for (int i = 0; i < graph->numNodes; i++) {
            // Check if there's an edge from v to i
            if (graph->adjMatrix[v][i]) {
                // If not visited, recursively check
                if (!visited[i] && isCyclicUtil(graph, i, visited, recursionStack))
                    return true;

                // If i is in recursion stack, cycle found
                else if (recursionStack[i])
                    return true;
            }
        }
    }

    // Remove from recursion stack
    recursionStack[v] = false;
    return false;
}

// Function to detect cycle in the graph
bool hasCycle(Graph* graph) {
    // Create arrays for tracking visited and recursion stack
    bool* visited = (bool*)calloc(graph->numNodes, sizeof(bool));
    bool* recursionStack = (bool*)calloc(graph->numNodes, sizeof(bool));

    // Check for cycle for each unvisited vertex
    for (int i = 0; i < graph->numNodes; i++) {
        if (isCyclicUtil(graph, i, visited, recursionStack)) {
            // Free memory
            free(visited);
            free(recursionStack);
            return true;
        }
    }

    // Free memory
    free(visited);
    free(recursionStack);
    return false;
}

// Function to free graph memory
void freeGraph(Graph* graph) {
    for (int i = 0; i < graph->numNodes; i++) {
        free(graph->adjMatrix[i]);
    }
    free(graph->adjMatrix);
    free(graph);
}

// Main function to demonstrate cycle detection
int main() {
    // Number of nodes in graph
    int nodes = 4;

    // Create graph
    Graph* graph = createGraph(nodes);

    // Add edges
    addEdge(graph, 0, 1);
    addEdge(graph, 1, 2);
    addEdge(graph, 2, 3);
    addEdge(graph, 3, 1);  // This creates a cycle

    // Check for cycle
    if (hasCycle(graph)) {
        printf("Graph contains a cycle\n");
    } else {
        printf("Graph does not contain a cycle\n");
    }

    // Free graph memory
    freeGraph(graph);

    return 0;
}

