// Structure to represent an adjacency list node
struct AdjListNode {
    int dest;
    struct AdjListNode* next;
};

// Structure to represent an adjacency list
struct AdjList {
    struct AdjListNode* head;
};

// Structure to represent a graph
struct Graph {
    int V;
    struct AdjList* array;
};

// Function to create a new adjacency list node
struct AdjListNode* newAdjListNode(int dest) {
    struct AdjListNode* newNode = (struct AdjListNode*)malloc(sizeof(struct AdjListNode));
    newNode->dest = dest;
    newNode->next = NULL;
    return newNode;
}

// Function to create a graph with V vertices
struct Graph* createGraph(int V) {
    struct Graph* graph = (struct Graph*)malloc(sizeof(struct Graph));
    graph->V = V;
    graph->array = (struct AdjList*)malloc(V * sizeof(struct AdjList));

    for (int i = 0; i < V; ++i)
        graph->array[i].head = NULL;

    return graph;
}

// Function to add an edge to the graph
void addEdge(struct Graph* graph, int src, int dest) {
    struct AdjListNode* newNode = newAdjListNode(dest);
    newNode->next = graph->array[src].head;
    graph->array[src].head = newNode;
}

// Utility function to detect cycle using DFS
bool isCyclicUtil(struct Graph* graph, int v, bool visited[], bool* recStack) {
    if (visited[v] == false) {
        // Mark the current node as visited and part of recursion stack
        visited[v] = true;
        recStack[v] = true;

        // Recur for all the vertices adjacent to this vertex
        struct AdjListNode* pCrawl = graph->array[v].head;
        while (pCrawl != NULL) {
            if (!visited[pCrawl->dest] && isCyclicUtil(graph, pCrawl->dest, visited, recStack))
                return true;
            else if (recStack[pCrawl->dest])
                return true;
            pCrawl = pCrawl->next;
        }
    }
    // Remove the vertex from recursion stack
    recStack[v] = false;
    return false;
}

// Function to detect cycle in the graph
bool isCyclic(struct Graph* graph) {
    // Mark all the vertices as not visited and not part of recursion stack
    bool* visited = (bool*)malloc(graph->V * sizeof(bool));
    bool* recStack = (bool*)malloc(graph->V * sizeof(bool));
    for (int i = 0; i < graph->V; i++) {
        visited[i] = false;
        recStack[i] = false;
    }

    // Call the recursive helper function to detect cycle in different DFS trees
    for (int i = 0; i < graph->V; i++)
        if (isCyclicUtil(graph, i, visited, recStack))
            return true;

    return false;
}

