#include <stdio.h>
#include <stdlib.h> // For malloc and free (if using dynamic lists)
#include <stdbool.h> // For bool type

// --- Configuration ---
// Replace {nodes} with your actual desired number of nodes
#define MAX_NODES 100 // Example: supporting up to 100 nodes

// --- Node States for DFS ---
#define UNVISITED 0 // Node has not been processed yet
#define VISITING  1 // Node is currently in the recursion stack (processing its neighbors)
#define VISITED   2 // Node has been fully processed and its subtree explored

// --- Graph Representation (Adjacency List) ---
typedef struct Node {
    int vertex;
    struct Node* next;
} Node;

Node* adj[MAX_NODES]; // Array of linked lists
int node_state[MAX_NODES]; // State of each node (UNVISITED, VISITING, VISITED)
int num_nodes;

// --- Function to add an edge to the adjacency list ---
void add_edge(int u, int v) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }
    new_node->vertex = v;
    new_node->next = adj[u];
    adj[u] = new_node;
}

// --- DFS function to detect cycles ---
// Returns true if a cycle is detected, false otherwise
bool dfs(int u) {
    node_state[u] = VISITING; // Mark current node as visiting (in recursion stack)

    Node* current = adj[u];
    while (current != NULL) {
        int v = current->vertex;

        if (node_state[v] == UNVISITED) {
            // If neighbor 'v' is unvisited, recurse on it
            if (dfs(v)) {
                return true; // Cycle found in the subtree rooted at 'v'
            }
        } else if (node_state[v] == VISITING) {
            // If neighbor 'v' is currently VISITING, it means we found a back-edge
            // to a node already in the current recursion stack. This indicates a cycle.
            return true;
        }
        // If node_state[v] == VISITED, it means 'v' and its subtree
        // have already been fully processed without finding a cycle.
        // We can ignore it for this path.

        current = current->next;
    }

    node_state[u] = VISITED; // Mark current node as fully visited (out of recursion stack)
    return false; // No cycle detected from this node downwards
}

// --- Function to initialize graph and free memory ---
void initialize_graph() {
    for (int i = 0; i < MAX_NODES; i++) {
        adj[i] = NULL;
        node_state[i] = UNVISITED;
    }
}

void free_graph_memory() {
    for (int i = 0; i < num_nodes; i++) {
        Node* current = adj[i];
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
        adj[i] = NULL; // Clear the head pointer
    }
}

// --- Main function ---
int main() {
    int num_edges;
    bool has_cycle = false;

    printf("Enter the number of nodes: ");
    scanf("%d", &num_nodes);

    if (num_nodes <= 0 || num_nodes > MAX_NODES) {
        printf("Invalid number of nodes. Must be between 1 and %d.\n", MAX_NODES);
        return 1;
    }

    printf("Enter the number of edges: ");
    scanf("%d", &num_edges);

    initialize_graph(); // Initialize adjacency lists to NULL and states to UNVISITED

    printf("Enter the edges (source destination):\n");
    for (int i = 0; i < num_edges; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        if (u < 0 || u >= num_nodes || v < 0 || v >= num_nodes) {
            printf("Invalid edge: (%d, %d). Nodes must be between 0 and %d.\n", u, v, num_nodes - 1);
            free_graph_memory();
            return 1;
        }
        add_edge(u, v);
    }

    // Iterate through all nodes to handle disconnected components
    for (int i = 0; i < num_nodes; i++) {
        if (node_state[i] == UNVISITED) {
            if (dfs(i)) {
                has_cycle = true;
                break; // Cycle found, no need to check further
            }
        }
    }

    if (has_cycle) {
        printf("The graph CONTAINS a cycle.\n");
    } else {
        printf("The graph DOES NOT contain a cycle.\n");
    }

    free_graph_memory(); // Clean up dynamically allocated memory
    return 0;
}

#include <stdio.h>
