#include <stdbool.h>

// Adjacency list node
typedef struct Node {
    int dest;
    struct Node* next;
} Node;

// Graph struct
typedef struct {
    int vertices;
    Node** adjList; // Array of adjacency lists
} Graph;

// Create a new node
Node* createNode(int dest) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->dest = dest;
    newNode->next = NULL;
    return newNode;
}

// Create graph with n vertices
Graph* createGraph(int vertices) {
    Graph* g = (Graph*)malloc(sizeof(Graph));
    g->vertices = vertices;
    g->adjList = (Node**)malloc(vertices * sizeof(Node*));
    for(int i = 0; i < vertices; i++)
        g->adjList[i] = NULL;
    return g;
}

// Add directed edge
void addEdge(Graph* g, int src, int dest) {
    Node* newNode = createNode(dest);
    newNode->next = g->adjList[src];
    g->adjList[src] = newNode;
}

// --- DFS based cycle detection ---
bool dfsCycleUtil(Graph* g, int v, bool visited[], bool recStack[]) {
    visited[v] = true;
    recStack[v] = true;

    Node* adj = g->adjList[v];
    while(adj != NULL) {
        int dest = adj->dest;
        if(!visited[dest] && dfsCycleUtil(g, dest, visited, recStack))
            return true;
        else if(recStack[dest])
            return true;
        adj = adj->next;
    }
    recStack[v] = false;
    return false;
}

bool hasCycle(Graph* g) {
    bool* visited = (bool*)calloc(g->vertices, sizeof(bool));
    bool* recStack = (bool*)calloc(g->vertices, sizeof(bool));

    for(int i = 0; i < g->vertices; i++)
        if(!visited[i])
            if(dfsCycleUtil(g, i, visited, recStack)) {
                free(visited);
                free(recStack);
                return true;
            }

    free(visited);
    free(recStack);
    return false;
}

