// A structure to represent an adjacency list node
typedef struct AdjListNode {
    int dest;
    struct AdjListNode* next;
} AdjListNode;

// A structure to represent an adjacency list
typedef struct AdjList {
    AdjListNode* head;
} AdjList;

// A structure to represent a graph
typedef struct Graph {
    int numNodes;
    AdjList* array;
} Graph;

// Function to create a new adjacency list node
AdjListNode* newAdjListNode(int dest) {
    AdjListNode* newNode = (AdjListNode*) malloc(sizeof(AdjListNode));
    newNode->dest = dest;
    newNode->next = NULL;
    return newNode;
}

// Function to create a graph of numNodes vertices
Graph* createGraph(int numNodes) {
    Graph* graph = (Graph*) malloc(sizeof(Graph));
    graph->numNodes = numNodes;

    // Create an array of adjacency lists
    graph->array = (AdjList*) malloc(numNodes * sizeof(AdjList));

    // Initialize each adjacency list as empty
    for(int i = 0; i < numNodes; ++i) {
        graph->array[i].head = NULL;
    }

    return graph;
}

// Function to add an edge to a directed graph
void addEdge(Graph* graph, int src, int dest) {
    // Add an edge from src to dest. A new node is added to the adjacency
    // list of src. The node is added at the beginning
    AdjListNode* newNode = newAdjListNode(dest);
    newNode->next = graph->array[src].head;
    graph->array[src].head = newNode;
}

// Utility function for DFS
bool isCyclicUtil(Graph* graph, int v, bool visited[], bool inRecStack[]) {
    if (visited[v] == false) {
        // Mark the current node as visited and add it to the recursion stack
        visited[v] = true;
        inRecStack[v] = true;

        // Recur for all the vertices adjacent to this vertex
        AdjListNode* current = graph->array[v].head;
        while (current != NULL) {
            int dest = current->dest;
            if (!visited[dest] && isCyclicUtil(graph, dest, visited, inRecStack)) {
                return true;
            } else if (inRecStack[dest]) {
                return true;
            }
            current = current->next;
        }
    }
    // Remove the vertex from recursion stack
    inRecStack[v] = false;
    return false;
}

// Main function to detect a cycle in a directed graph
bool isCyclic(Graph* graph) {
    // Mark all vertices as not visited and not part of recursion stack
    bool* visited = (bool*) malloc(graph->numNodes * sizeof(bool));
    bool* inRecStack = (bool*) malloc(graph->numNodes * sizeof(bool));

    for (int i = 0; i < graph->numNodes; i++) {
        visited[i] = false;
        inRecStack[i] = false;
    }

    // Call the recursive helper function to detect cycle in different DFS trees
    for (int i = 0; i < graph->numNodes; i++) {
        if (isCyclicUtil(graph, i, visited, inRecStack)) {
            free(visited);
            free(inRecStack);
            return true;
        }
    }

    free(visited);
    free(inRecStack);
    return false;
}

