struct Graph {
    int numVertices;
    int** adjMatrix;
};

// Function to create a graph with given number of vertices
struct Graph* createGraph(int vertices) {
    struct Graph* graph = (struct Graph*)malloc(sizeof(struct Graph));
    graph->numVertices = vertices;

    // Initialize adjacency matrix
    graph->adjMatrix = (int**)malloc(vertices * sizeof(int*));
    for (int i = 0; i < vertices; i++) {
        graph->adjMatrix[i] = (int*)calloc(vertices, sizeof(int));
    }
    return graph;
}

// Function to add an edge to the graph
void addEdge(struct Graph* graph, int src, int dest) {
    graph->adjMatrix[src][dest] = 1; // Mark the edge from src to dest
}

// Helper function for cycle detection
int dfs(int v, int visited[], int recStack[], struct Graph* graph) {
    if (recStack[v]) {
        return 1; // Cycle detected
    }
    if (visited[v]) {
        return 0; // Already visited node
    }

    // Mark the current node as visited and part of the recursion stack
    visited[v] = 1;
    recStack[v] = 1;

    // Recur for all adjacent vertices
    for (int i = 0; i < graph->numVertices; i++) {
        if (graph->adjMatrix[v][i]) { // There's an edge from v to i
            if (dfs(i, visited, recStack, graph)) {
                return 1;
            }
        }
    }

    // Remove from recursion stack before backtracking
    recStack[v] = 0;
    return 0;
}

// Function to detect cycle in the directed graph
int detectCycle(struct Graph* graph) {
    int visited[MAX_NODES] = {0};  // Mark all the vertices as not visited
    int recStack[MAX_NODES] = {0};  // Stack to track vertices in the current path

    // Call the recursive helper function to detect cycle for each vertex
    for (int i = 0; i < graph->numVertices; i++) {
        if (dfs(i, visited, recStack, graph)) {
            return 1; // Cycle found
        }
    }

    return 0; // No cycle found
}

