// Function to trim leading and trailing whitespaces
void trim(char *str) {
    int start = 0, end = strlen(str) - 1;

    // Trim leading whitespaces
    while (str[start] && (str[start] == ' ' || str[start] == '\t')) {
        start++;
    }

    // Trim trailing whitespaces
    while (end > start && (str[end] == ' ' || str[end] == '\t' || str[end] == '\n')) {
        end--;
    }

    // Shift the string
    int i;
    for (i = 0; i <= end - start; i++) {
        str[i] = str[start + i];
    }
    str[i] = '\0';
}

// Function to parse CSV line
int parseCSVLine(char *line, char *fields[]) {
    int fieldCount = 0;
    char *token;

    // Remove newline character
    line[strcspn(line, "\n")] = 0;

    // Tokenize the line by comma
    token = strtok(line, ",");
    while (token != NULL && fieldCount < MAX_FIELDS) {
        // Trim whitespaces from token
        trim(token);

        // Remove quotes if present
        if (token[0] == '"' && token[strlen(token) - 1] == '"') {
            token[strlen(token) - 1] = '\0';
            token++;
        }

        fields[fieldCount++] = strdup(token);
        token = strtok(NULL, ",");
    }

    return fieldCount;
}

// Function to print CSV record
void printRecord(char *fields[], int fieldCount) {
    printf("Record with %d fields:\n", fieldCount);
    for (int i = 0; i < fieldCount; i++) {
        printf("Field %d: %s\n", i + 1, fields[i]);
    }
    printf("\n");
}

// Function to free memory
void freeFields(char *fields[], int fieldCount) {
    for (int i = 0; i < fieldCount; i++) {
        free(fields[i]);
    }
}

int main() {
    FILE *file;
    char line[MAX_LINE_LENGTH];
    char *fields[MAX_FIELDS];
    int fieldCount;
    int lineNumber = 0;

    // Open the input file
    file = fopen("input.log", "r");
    if (file == NULL) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    // Read and parse each line
    while (fgets(line, sizeof(line), file) != NULL) {
        lineNumber++;

        // Skip empty lines
        if (strlen(line) <= 1) {
            continue;
        }

        // Parse CSV line
        fieldCount = parseCSVLine(line, fields);

        // Print record details
        printf("Line %d: ", lineNumber);
        printRecord(fields, fieldCount);

        // Free memory
        freeFields(fields, fieldCount);
    }

    // Close the file
    fclose(file);

    return EXIT_SUCCESS;
}

