#define MAX_LINE_LENGTH 1024 // Maximum assumed length of a CSV line
#define DELIMITER ','        // The CSV delimiter

int main() {
    FILE *file;
    char line[MAX_LINE_LENGTH];
    int record_count = 0;

    // Open the input file
    file = fopen("input.log", "r");
    if (file == NULL) {
        perror("Error opening input.log");
        return 1; // Indicate an error
    }

    printf("Parsing CSV data from 'input.log'...\n\n");

    // Read the file line by line
    while (fgets(line, sizeof(line), file) != NULL) {
        // Remove trailing newline character if present
        line[strcspn(line, "\n")] = 0;

        // Skip empty lines
        if (strlen(line) == 0) {
            continue;
        }

        record_count++;
        printf("Record %d: ", record_count);

        // --- Manual CSV Parsing ---
        // We'll iterate through the line and print fields.
        // This is more robust than strtok for CSV as it handles empty fields
        // and quoted fields (though this simple example doesn't fully handle quotes).
        char *ptr = line;
        char *start_of_field = line;
        int field_count = 0;

        while (*ptr != '\0') {
            if (*ptr == DELIMITER) {
                // Null-terminate the current field string
                *ptr = '\0';
                printf("'%s', ", start_of_field);
                start_of_field = ptr + 1; // Move to the character after the delimiter
                field_count++;
            }
            ptr++;
        }
        // Print the last field (or the only field if no delimiters)
        printf("'%s'\n", start_of_field);
        field_count++;

        // If you want to print the total number of fields for each record:
        // printf(" (Fields: %d)\n", field_count);
    }

    // Close the file
    fclose(file);

    if (record_count == 0) {
        printf("No records found in 'input.log'.\n");
    } else {
        printf("\nSuccessfully parsed %d records from 'input.log'.\n", record_count);
    }

    return 0; // Indicate success
}

