// Function to parse a CSV line and print each record
void parse_csv_line(const char *line) {
    char *token;
    char *str = strdup(line); // Duplicate the line to safely modify it
    char *delim = ",";

    // Use strtok to split the line by commas
    token = strtok(str, delim);
    while (token != NULL) {
        printf("%s\n", token);
        token = strtok(NULL, delim);
    }

    free(str); // Free the duplicated string
}

