    add_edge(graph, 1, 3);
    add_edge(graph, 2, 3);

    printf("Original Graph:\n");
    print_graph(graph);

    Graph* permuted_graph = calculate_graph_permutation(graph);

    printf("\nPermuted Graph:\n");
    print_graph(permuted_graph);

    free_graph(graph);
    free_graph(permuted_graph);

    return 0;
}

