bool isIsomorphic(int **graph, int *permutation, int n) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (graph[i][j] != graph[permutation[i]][permutation[j]]) {
                return false;
            }
        }
    }
