            printf("Valid permutation: ");
            for (int i = 0; i < n; i++) {
                printf("%d ", permutation[i]);
            }
            printf("\n");
        }
    } else {
        for (int i = start; i <= end; i++) {
            swap(&permutation[start], &permutation[i]);
            permute(graph, permutation, start + 1, end, n);
            swap(&permutation[start], &permutation[i]);
        }
    }
}

