#define N 5       // Number of vertices (example)
#define MAXDEG 10 // Maximum degree

// adj_list[u][i]: i-th neighbor of u
void apply_graph_permutation(
    int n, 
    int adj_list[][MAXDEG], 
    int deg[], 
    const int perm[], // perm[u] = new label for vertex u
    int new_adj_list[][MAXDEG], 
    int new_deg[]
) {
    int old_to_new[N];
    int new_to_old[N];

    // Build new_to_old mapping
    for (int old = 0; old < n; ++old) {
        int newv = perm[old];
        old_to_new[old] = newv;
        new_to_old[newv] = old;
    }

    // Build new adjacency list
    for (int newv = 0; newv < n; ++newv) {
        int oldv = new_to_old[newv];
        new_deg[newv] = deg[oldv];
        for (int i = 0; i < deg[oldv]; ++i) {
            int old_neighbor = adj_list[oldv][i];
            int new_neighbor = old_to_new[old_neighbor];
            new_adj_list[newv][i] = new_neighbor;
        }
    }
}

// Example usage:
int main() {
    int adj_list[N][MAXDEG] = {
        {1, 2},      // 0
        {0, 2},      // 1
        {0, 1, 3},   // 2
        {2, 4},      // 3
        {3}          // 4
    };
    int deg[N] = {2, 2, 3, 2, 1};

    int perm[N] = {2, 0, 4, 1, 3}; // permutation: vertex 0 becomes 2, 1->0, 2->4, 3->1, 4->3

    int new_adj_list[N][MAXDEG];
    int new_deg[N];

    apply_graph_permutation(N, adj_list, deg, perm, new_adj_list, new_deg);

    printf("Permuted adjacency list:\n");
    for (int u = 0; u < N; ++u) {
        printf("Vertex %d (was %d):", u, perm[u]);
        for (int j = 0; j < new_deg[u]; ++j) {
            printf(" %d", new_adj_list[u][j]);
        }
        printf("\n");
    }
    return 0;
}

