};

// A structure to represent an adjacency list
struct AdjList {
    struct AdjListNode* head;  // pointer to head node of list
};

// A structure to represent a graph. A graph is an array of adjacency lists.
// Size of array will be V (number of vertices in graph)
struct Graph {
    int V;
    struct AdjList* array;
};

// A utility function to create a new adjacency list node
struct AdjListNode* newAdjListNode(int dest) {
    struct AdjListNode* newNode = (struct AdjListNode*) malloc(sizeof(struct AdjListNode));
    newNode->dest = dest;
    newNode->next = NULL;
    return newNode;
}

// A utility function that creates a graph of V vertices
struct Graph* createGraph(int V) {
    struct Graph* graph = (struct Graph*) malloc(sizeof(struct Graph));
    graph->V = V;

    // Create an array of adjacency lists. Size of array will be V
    graph->array = (struct AdjList*) malloc(V * sizeof(struct AdjList));

    // Initialize each adjacency list as empty by making head as NULL
    for (int i = 0; i < V; ++i)
        graph->array[i].head = NULL;

    return graph;
}

// Adds an edge to a directed graph
void addEdge(struct Graph* graph, int src, int dest) {
    // Add an edge from src to dest. A new node is added to the adjacency
    // list of src. The node is added at the beginning
    struct AdjListNode* newNode = newAdjListNode(dest);
    newNode->next = graph->array[src].head;
    graph->array[src].head = newNode;
}

// A utility function to print the adjacency list representation of graph
void printGraph(struct Graph* graph) {
    for (int v = 0; v < graph->V; ++v) {
        struct AdjListNode* pCrawl = graph->array[v].head;
        printf("\n Adjacency list of vertex %d\n head ", v);
        while (pCrawl) {
            printf("-> %d", pCrawl->dest);
            pCrawl = pCrawl->next;
        }
        printf("\n");
    }
}

void topologicalSortUtil(struct Graph* graph, int v, int visited[], int* stack, int* stackIndex) {
    // Mark the current node as visited
    visited[v] = 1;

    // Recur for all the vertices adjacent to this vertex
    struct AdjListNode* adjListNode = graph->array[v].head;
    while (adjListNode != NULL) {
        int adjVertex = adjListNode->dest;
        if (!visited[adjVertex]) {
            topologicalSortUtil(graph, adjVertex, visited, stack, stackIndex);
        }
        adjListNode = adjListNode->next;
    }

    // Push current vertex to stack (storing the result)
    stack[(*stackIndex)++] = v;
}

// The function to do Topological Sort. It uses recursive
// topologicalSortUtil()
void topologicalSort(struct Graph* graph) {
    int* stack = (int*) malloc(graph->V * sizeof(int));
    int stackIndex = 0;

    // Mark all the vertices as not visited
    int* visited = (int*) malloc(graph->V * sizeof(int));
    for (int i = 0; i < graph->V; i++)
        visited[i] = 0;

    // Call the recursive helper function to store Topological Sort
    // starting from all vertices one by one
    for (int i = 0; i < graph->V; i++) {
        if (visited[i] == 0) {
            topologicalSortUtil(graph, i, visited, stack, &stackIndex);
        }
    }

    // Print the contents of the stack (Topological ordering)
    while (stackIndex > 0) {
        printf("%d ", stack[--stackIndex]);
    }

    free(stack);
    free(visited);
}

