// Function to calculate the graph permutation
void calculatePermutation(Graph* graph) {
    // Initialize a 2D array to store the permutations
    int** permutations = (int**) malloc(graph->numVertices * sizeof(int*));
    for (int i = 0; i < graph->numVertices; i++) {
        permutations[i] = (int*) malloc(graph->numVertices * sizeof(int));
    }

    // Calculate all possible permutations of vertices
    permute(graph, permutations, 0, graph->numVertices - 1);

    // Check if the graph is isomorphic to each permutation
    for (int i = 0; i < graph->numVertices; i++) {
        for (int j = i + 1; j < graph->numVertices; j++) {
            if (areIsomorphic(graph, permutations[i], permutations[j])) {
                printf("Graph permutation found: [");
                printPermutation(permutations[i], graph->numVertices);
                printf("]\n");
            }
        }
    }

    // Free the memory allocated for permutations
    for (int i = 0; i < graph->numVertices; i++) {
        free(permutations[i]);
    }
    free(permutations);
}

// Function to calculate all possible permutations of vertices
void permute(Graph* graph, int** permutations, int left, int right) {
    if (left == right) {
        // Store the permutation in the permutations array
        for (int i = 0; i < graph->numVertices; i++) {
            permutations[0][i] = i;
        }
        permute(graph, permutations, 0, right);
    } else {
        for (int i = left; i <= right; i++) {
            swap(permutations[0], left, i);
            permute(graph, permutations, left + 1, right);
        }
    }
}

// Function to swap two elements in an array
void swap(int* arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

// Function to check if two graphs are isomorphic
int areIsomorphic(Graph* graph1, int* perm1, int* perm2) {
    // Iterate through all vertices and edges
    for (int i = 0; i < graph1->numVertices; i++) {
        Edge* edge1 = graph1->adjacencyList[perm1[i]];
        Edge* edge2 = graph1->adjacencyList[perm2[i]];
        while (edge1!= NULL && edge2!= NULL) {
            if (edge1->vertex!= edge2->vertex) {
                return 0; // Not isomorphic
            }
            edge1 = edge1->next;
            edge2 = edge2->next;
        }
        if (edge1!= NULL || edge2!= NULL) {
            return 0; // Not isomorphic
        }
    }
    return 1; // Isomorphic
}

