    graph->numVertices = vertices;
    graph->adjLists = malloc(vertices * sizeof(Node*));
    for (int i = 0; i < vertices; i++) {
        graph->adjLists[i] = NULL;
    }
    return graph;
}

// Function to add an edge to the graph
void addEdge(Graph* graph, int src, int dest) {
    Node* newNode = createNode(dest);
    newNode->next = graph->adjLists[src];
    graph->adjLists[src] = newNode;

    newNode = createNode(src);
    newNode->next = graph->adjLists[dest];
    graph->adjLists[dest] = newNode;
}

// Function to check if a permutation is valid (an automorphism)
int isAutomorphism(Graph* graph, int* permutation, int numVertices) {
    for (int i = 0; i < numVertices; i++) {
        Node* current = graph->adjLists[i];
        while (current != NULL) {
            int u = permutation[i];
            int v = permutation[current->vertex];
            int found = 0;
            Node* temp = graph->adjLists[u];
            while (temp != NULL) {
                if (temp->vertex == v) {
                    found = 1;
                    break;
                }
                temp = temp->next;
            }
            if (!found) {
                return 0;
            }
            current = current->next;
        }
    }
    return 1;
}

// Function to print a permutation
void printPermutation(int* permutation, int numVertices) {
    for (int i = 0; i < numVertices; i++) {
        printf("%d ", permutation[i]);
    }
    printf("\n");
}

// Function to generate all permutations using backtracking
void generatePermutations(Graph* graph, int* permutation, int* used, int index, int numVertices) {
    if (index == numVertices) {
        if (isAutomorphism(graph, permutation, numVertices)) {
            printPermutation(permutation, numVertices);
        }
        return;
    }

    for (int i = 0; i < numVertices; i++) {
        if (!used[i]) {
            permutation[index] = i;
            used[i] = 1;
            generatePermutations(graph, permutation, used, index + 1, numVertices);
            used[i] = 0;
        }
    }
}

// Function to find all graph automorphisms
void findAutomorphisms(Graph* graph) {
    int* permutation = malloc(graph->numVertices * sizeof(int));
    int* used = malloc(graph->numVertices * sizeof(int));
    for (int i = 0; i < graph->numVertices; i++) {
        used[i] = 0;
    }
    generatePermutations(graph, permutation, used, 0, graph->numVertices);
    free(permutation);
    free(used);
}

// Function to free the graph
void freeGraph(Graph* graph) {
    for (int i = 0; i < graph->numVertices; i++) {
        Node* current = graph->adjLists[i];
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(graph->adjLists);
    free(graph);
}

