    Graph* graph = createGraph(vertices);
    addEdge(graph, 0, 1);
    addEdge(graph, 1, 2);
    addEdge(graph, 2, 3);
    addEdge(graph, 3, 0);

    findAutomorphisms(graph);

    freeGraph(graph);
    return 0;
}

