// Function to calculate standard deviation
double calculate_standard_deviation(double *numbers, int count) {
    // Check for invalid input
    if (numbers == NULL || count <= 0) {
        fprintf(stderr, "Invalid input for standard deviation calculation\n");
        return 0.0;
    }

    // Calculate the mean (average)
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += numbers[i];
    }
    double mean = sum / count;

    // Calculate variance (average of squared differences from mean)
    double variance_sum = 0.0;
    for (int i = 0; i < count; i++) {
        double difference = numbers[i] - mean;
        variance_sum += difference * difference;
    }
    double variance = variance_sum / count;

    // Take square root of variance to get standard deviation
    return sqrt(variance);
}

