#include <stdio.h>
#include <math.h> // For sqrt() and pow()

/**
 * @brief Calculates the standard deviation of a list of numbers.
 *
 * This function handles both population and sample standard deviation based on
 * the `is_sample` flag.
 *
 * @param data A pointer to the array of floating-point numbers.
 * @param n The number of elements in the `data` array.
 * @param is_sample A boolean flag:
 *                  - If 1 (true), calculates sample standard deviation (divides by n-1).
 *                  - If 0 (false), calculates population standard deviation (divides by n).
 * @return The standard deviation of the list of numbers.
 *         Returns 0.0 if n is 0 or 1 (as standard deviation is undefined or 0).
 */
double calculate_std_dev(const double data[], int n, int is_sample) {
    if (n <= 1) {
        // Standard deviation is 0 for n=1, and undefined for n=0.
        // Returning 0.0 for practical purposes.
        return 0.0;
    }

    // Step 1: Calculate the mean
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        sum += data[i];
    }
    double mean = sum / n;

    // Step 2: Calculate the sum of squared differences from the mean
    double sum_sq_diff = 0.0;
    for (int i = 0; i < n; i++) {
        double diff = data[i] - mean;
        sum_sq_diff += pow(diff, 2); // (xi - mean)^2
    }

    // Step 3: Calculate the variance
    double variance;
    if (is_sample) {
        // Sample standard deviation: divide by n-1
        // Handles case where n=1 by the initial check.
        variance = sum_sq_diff / (n - 1);
    } else {
        // Population standard deviation: divide by n
        variance = sum_sq_diff / n;
    }

    // Step 4: Calculate the standard deviation (square root of variance)
    return sqrt(variance);
}

