// Function to calculate standard deviation
double standard_deviation(const double *data, int n) {
    if (n <= 1) return 0.0;  // SD is not defined for <= 1 item

    double sum = 0.0, mean, sd = 0.0;

    // Calculate mean
    for (int i = 0; i < n; i++) {
        sum += data[i];
    }
    mean = sum / n;

    // Calculate squared differences
    for (int i = 0; i < n; i++) {
        sd += (data[i] - mean) * (data[i] - mean);
    }

    // Sample standard deviation (n-1 in denominator)
    return sqrt(sd / (n - 1));
}

