void convert_seconds(int total_seconds) {
    // Calculate hours, minutes, and remaining seconds
    int hours = total_seconds / 3600;
    int minutes = (total_seconds % 3600) / 60;
    int seconds = total_seconds % 60;

    // Create an output string to store the readable format
    char output[100] = {0};
    int first = 1; // Flag to track if this is the first non-zero component

    // Build the output string
    if (hours > 0) {
        sprintf(output + strlen(output), "%d hour%s", 
                hours, hours != 1 ? "s" : "");
        first = 0;
    }

    if (minutes > 0) {
        // Add separator if not the first component
        if (!first) {
            strcat(output, ", ");
        }
        sprintf(output + strlen(output), "%d minute%s", 
                minutes, minutes != 1 ? "s" : "");
        first = 0;
    }

    if (seconds > 0 || total_seconds == 0) {
        // Add separator if not the first component
        if (!first) {
            strcat(output, ", ");
        }
        sprintf(output + strlen(output), "%d second%s", 
                seconds, seconds != 1 ? "s" : "");
    }

    // Print the result
    printf("%d seconds = %s\n", total_seconds, 
           output[0] ? output : "0 seconds");
}

