#include <stdio.h>    // For snprintf
#include <stdlib.h>   // For malloc, free, strdup
#include <string.h>   // For strlen, strcat
#include <stdbool.h>  // For true/false

// Define constants for time units in seconds
// Using LL for long long literals to avoid implicit conversion issues
#define SECONDS_IN_MINUTE (60LL)
#define SECONDS_IN_HOUR   (SECONDS_IN_MINUTE * 60LL)
#define SECONDS_IN_DAY    (SECONDS_IN_HOUR * 24LL)
// Simplification: Ignores leap years. For precise year calculation involving specific dates,
// a more complex date/time library would be needed.
#define SECONDS_IN_YEAR   (SECONDS_IN_DAY * 365LL)

// Maximum buffer size for the formatted string.
// A typical string like "123 years, 300 days, 23 hours, 59 minutes, 59 seconds"
// would be well under 100 characters. 256 provides ample safety.
#define MAX_FORMAT_STRING_LEN 256

/**
 * @brief Converts a total number of seconds into a human-readable string.
 *
 * @param total_seconds The total number of seconds to convert (can be large).
 * @return A dynamically allocated string containing the human-readable time.
 *         Returns NULL if memory allocation fails.
 *         Returns "Invalid input: negative seconds" for negative input.
 *         The caller is responsible for freeing the returned string using free().
 */
char* format_seconds(long long total_seconds) {
    // Edge case: Negative input
    if (total_seconds < 0) {
        return strdup("Invalid input: negative seconds");
    }

    // Edge case: 0 seconds
    if (total_seconds == 0) {
        return strdup("0 seconds");
    }

    // Allocate memory for the final result string.
    // We use a fixed large size for simplicity; could use two-pass snprintf for exact size.
    char* result_str = (char*)malloc(MAX_FORMAT_STRING_LEN);
    if (result_str == NULL) {
        perror("Failed to allocate memory for result string");
        return NULL; // Indicates allocation failure
    }
    result_str[0] = '\0'; // Initialize as an empty string

    // Calculate time components using integer division and modulo
    long long years = total_seconds / SECONDS_IN_YEAR;
    total_seconds %= SECONDS_IN_YEAR;

    long long days = total_seconds / SECONDS_IN_DAY;
    total_seconds %= SECONDS_IN_DAY;

    long long hours = total_seconds / SECONDS_IN_HOUR;
    total_seconds %= SECONDS_IN_HOUR;

    long long minutes = total_seconds / SECONDS_IN_MINUTE;
    total_seconds %= SECONDS_IN_MINUTE;

    long long seconds = total_seconds; // Remaining seconds

    // Array to hold pointers to dynamically allocated strings for each component
    // (e.g., "1 year", "2 days", etc.)
    char* components[5]; // Max 5 components: years, days, hours, minutes, seconds
    int component_count = 0;
    char temp_buffer[30]; // Temporary buffer for snprintf for each component string

    // Populate the components array only with non-zero values
    if (years > 0) {
        snprintf(temp_buffer, sizeof(temp_buffer), "%lld %s", years, (years == 1) ? "year" : "years");
        components[component_count++] = strdup(temp_buffer); // Duplicate string for storage
    }
    if (days > 0) {
        snprintf(temp_buffer, sizeof(temp_buffer), "%lld %s", days, (days == 1) ? "day" : "days");
        components[component_count++] = strdup(temp_buffer);
    }
    if (hours > 0) {
        snprintf(temp_buffer, sizeof(temp_buffer), "%lld %s", hours, (hours == 1) ? "hour" : "hours");
        components[component_count++] = strdup(temp_buffer);
    }
    if (minutes > 0) {
        snprintf(temp_buffer, sizeof(temp_buffer), "%lld %s", minutes, (minutes == 1) ? "minute" : "minutes");
        components[component_count++] = strdup(temp_buffer);
    }
    if (seconds > 0) {
        snprintf(temp_buffer, sizeof(temp_buffer), "%lld %s", seconds, (seconds == 1) ? "second" : "seconds");
        components[component_count++] = strdup(temp_buffer);
    }

    // Combine the formatted component strings into the final result string
    for (int i = 0; i < component_count; ++i) {
        strcat(result_str, components[i]); // Append the current component's string

        // Add appropriate separators (commas and "and")
        if (i < component_count - 2) { // If not the last two components (e.g., "A, B, C, D")
            strcat(result_str, ", ");
        } else if (i == component_count - 2 && component_count > 1) { // If second to last and there's more than one component total
            strcat(result_str, " and ");
        }
    }

    // Free the dynamically allocated strings for individual components
    for (int i = 0; i < component_count; ++i) {
        free(components[i]);
    }

    // Reallocate result_str to the exact size to save memory and return it.
    // strdup allocates new memory of the precise size and copies the string.
    char* final_result = strdup(result_str);
    free(result_str); // Free the initially allocated, potentially oversized buffer

    return final_result; // Caller is responsible for freeing this memory
}

