        3660,                   // 1 hour, 1 minute
        3661,                   // 1 hour, 1 minute, 1 second
        7200,                   // 2 hours
        86399,                  // 23 hours, 59 minutes, 59 seconds
        86400,                  // 1 day
        86401,                  // 1 day, 1 second
        90061,                  // 1 day, 1 hour, 1 minute, 1 second
        SECONDS_IN_YEAR,        // 1 year
        SECONDS_IN_YEAR + SECONDS_IN_DAY + SECONDS_IN_HOUR + SECONDS_IN_MINUTE + 1, // 1 year, 1 day, 1 hour, 1 minute, 1 second
        (2 * SECONDS_IN_YEAR) + (3 * SECONDS_IN_DAY) + (5 * SECONDS_IN_MINUTE) + 25, // 2 years, 3 days, 5 minutes, 25 seconds
        (123LL * SECONDS_IN_YEAR) + (300LL * SECONDS_IN_DAY) + (23LL * SECONDS_IN_HOUR) + (59LL * SECONDS_IN_MINUTE) + 59LL, // Large example
        -100                    // Negative input test
    };

    int num_tests = sizeof(test_seconds) / sizeof(test_seconds[0]);

    for (int i = 0; i < num_tests; ++i) {
