void seconds_to_readable(int seconds, char *buffer, size_t bufsize) {
    int hours = seconds / 3600;
    int minutes = (seconds % 3600) / 60;
    int secs = seconds % 60;

    int len = 0;
    buffer[0] = '\0';

    if (hours > 0) {
        len += snprintf(buffer + len, bufsize - len, "%d hour%s", hours, hours == 1 ? "" : "s");
    }
    if (minutes > 0) {
        if (len > 0) len += snprintf(buffer + len, bufsize - len, ", ");
        len += snprintf(buffer + len, bufsize - len, "%d minute%s", minutes, minutes == 1 ? "" : "s");
    }
    if (secs > 0 || (hours == 0 && minutes == 0)) {
        // always display seconds if it's 0, to avoid empty output
        if (len > 0) len += snprintf(buffer + len, bufsize - len, ", ");
        len += snprintf(buffer + len, bufsize - len, "%d second%s", secs, secs == 1 ? "" : "s");
    }
}

