    int secs[] = {3661, 3600, 61, 1, 0};
    for(int i = 0; i < 5; ++i) {
        seconds_to_readable(secs[i], buffer, sizeof(buffer));
        printf("%d seconds -> %s\n", secs[i], buffer);
    }
    return 0;
}

