#include <stdio.h>

void convert_seconds(int total_seconds) {
    int hours, minutes, seconds;

    // Calculate hours
    hours = total_seconds / 3600;
    total_seconds %= 3600;

    // Calculate minutes
    minutes = total_seconds / 60;
    total_seconds %= 60;

    // Remaining seconds
    seconds = total_seconds;

    // Print the result in a human-readable format
    printf("%d hour(s), %d minute(s), %d second(s)\n", hours, minutes, seconds);
}

int main() {
    int total_seconds = 3661;
    convert_seconds(total_seconds);
    return 0;
}

