#include <windows.h>
#endif

char* create_temp_folder() {
    // Buffer to store the temp folder path
    char* temp_path = malloc(256 * sizeof(char));
    if (temp_path == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Get the system's temporary directory
#ifdef _WIN32
    // For Windows
    char sys_temp_dir[256];
    DWORD temp_dir_length = GetTempPathA(sizeof(sys_temp_dir), sys_temp_dir);
    if (temp_dir_length == 0) {
        fprintf(stderr, "Failed to get system temp directory\n");
        free(temp_path);
        return NULL;
    }
#else
    // For Unix-like systems
    const char* sys_temp_dir = "/tmp";
#endif

    // Seed random number generator
    srand(time(NULL) ^ getpid());

    // Create a unique folder name with high entropy
    // Combination of:
    // 1. Process ID
    // 2. Current timestamp
    // 3. Random number
    snprintf(temp_path, 256, "%s/temp_%d_%ld_%d", 
             sys_temp_dir, 
             getpid(),      // Process ID
             (long)time(NULL), // Current timestamp 
             rand());       // Random number

    // Attempt to create the directory
    // Use 0700 permissions (read/write/execute for owner only)
    #ifdef _WIN32
    int mkdir_result = _mkdir(temp_path);
    #else
    int mkdir_result = mkdir(temp_path, 0700);
    #endif

    if (mkdir_result != 0) {
        // If directory creation fails, try again with a different random number
        snprintf(temp_path, 256, "%s/temp_%d_%ld_%d", 
                 sys_temp_dir, 
                 getpid(), 
                 (long)time(NULL), 
                 rand());

        #ifdef _WIN32
        mkdir_result = _mkdir(temp_path);
        #else
        mkdir_result = mkdir(temp_path, 0700);
        #endif

        if (mkdir_result != 0) {
            fprintf(stderr, "Failed to create temporary directory\n");
            free(temp_path);
            return NULL;
        }
    }

    return temp_path;
}

// Optional: Function to clean up the temporary folder
void cleanup_temp_folder(char* temp_path) {
    if (temp_path == NULL) return;

    // Attempt to remove the directory and all its contents
    #ifdef _WIN32
    // On Windows, use RemoveDirectory for empty directories
    RemoveDirectoryA(temp_path);
    #else
    // On Unix-like systems, use system command to recursively remove
    char remove_cmd[512];
    snprintf(remove_cmd, sizeof(remove_cmd), "rm -rf %s", temp_path);
    system(remove_cmd);
    #endif

    // Free the allocated path string
    free(temp_path);
}

