    // Create a unique temporary folder
    char* my_temp_folder = create_temp_folder();

    if (my_temp_folder) {
        printf("Temporary folder created: %s\n", my_temp_folder);

        // Do some work with the temporary folder...

        // Clean up when done
        cleanup_temp_folder(my_temp_folder);
    }

    return 0;
}

