// Define MAX_PATH if not already defined (common practice for portability)
#ifndef MAX_PATH
#define MAX_PATH 260 // Max path length on Windows
#endif

// Helper function to convert TCHAR* to char* and allocate memory.
// This is necessary because Windows APIs often use TCHAR (which can be wchar_t),
// but the function's return type is char* for portability.
// Caller is responsible for freeing the returned char*.
static char* _tchar_to_char_alloc(const TCHAR* tstr) {
#ifdef _UNICODE
    // Calculate required buffer size for UTF-8 encoding
    int len = WideCharToMultiByte(CP_UTF8, 0, tstr, -1, NULL, 0, NULL, NULL);
    if (len == 0) {
        return NULL; // Failed to get length
    }
    char* cstr = (char*)malloc(len);
    if (!cstr) {
        return NULL; // Malloc failed
    }
    // Perform the conversion
    if (WideCharToMultiByte(CP_UTF8, 0, tstr, -1, cstr, len, NULL, NULL) == 0) {
        free(cstr); // Conversion failed, free allocated memory
        return NULL;
    }
    return cstr;
#else // ANSI build (TCHAR is char)
    return _strdup(tstr); // Use _strdup for ANSI builds (which is like strdup)
#endif
}

// Helper for error logging TCHAR paths safely into a char* buffer.
// This avoids dynamic allocation for temporary logging messages.
static void _tchar_to_char_buf(const TCHAR* tstr, char* buf, size_t buf_len) {
#ifdef _UNICODE
    WideCharToMultiByte(CP_UTF8, 0, tstr, -1, buf, (int)buf_len, NULL, NULL);
#else
    strncpy(buf, tstr, buf_len - 1);
    buf[buf_len - 1] = '\0';
#endif
}

#else // POSIX (Linux, macOS, BSD, etc.)

#include <string.h>  // For strcpy, strlen, strerror, strdup
#include <unistd.h>  // For rmdir (used for cleanup on strdup fail)
#include <errno.h>   // For errno

// PATH_MAX might be in limits.h
#ifndef PATH_MAX
#include <limits.h> // For PATH_MAX
#endif
#ifndef PATH_MAX
#define PATH_MAX 4096 // A reasonable fallback if PATH_MAX is not defined
#endif

#endif

/**
 * @brief Creates a unique temporary directory for the process.
 *
 * This function creates a temporary directory in the system's designated
 * temporary location (e.g., /tmp on POSIX, AppData/Local/Temp on Windows).
 * It uses platform-specific, secure methods to ensure the directory name
 * is unique and resistant to race conditions.
 *
 * @return A dynamically allocated string containing the full path to the
 *         newly created temporary directory on success. The caller **must**
 *         free this string using `free()`. Returns `NULL` on failure,
 *         with an error message printed to `stderr`.
 */
char* create_temp_dir() {
    char* result_path = NULL;

#ifdef _WIN32
    TCHAR temp_path_buffer[MAX_PATH];
    // Get the system's temporary file path (e.g., C:\Users\User\AppData\Local\Temp\)
    DWORD path_len = GetTempPath(MAX_PATH, temp_path_buffer);

    if (path_len == 0 || path_len > MAX_PATH) {
        fprintf(stderr, "create_temp_dir: Error getting temporary path. GetTempPath failed or buffer too small.\n");
        return NULL;
    }

    TCHAR temp_dir_name[MAX_PATH];
    // GetTempFileName generates a unique temporary file name and creates a 0-byte file.
    // We use this unique name for our directory. "myprog" is a prefix to identify our temp dirs.
    // The last argument (0) tells GetTempFileName to use a unique number.
    if (GetTempFileName(temp_path_buffer, TEXT("myprog"), 0, temp_dir_name) == 0) {
        fprintf(stderr, "create_temp_dir: Error creating unique temporary file name: %lu\n", GetLastError());
        return NULL;
    }

    // GetTempFileName created a file. We want a directory.
    // Delete the file first. We then create a directory with the same unique name.
    // This leverages GetTempFileName's uniqueness guarantees.
    if (!DeleteFile(temp_dir_name)) {
        // Log a warning if deletion fails, but proceed.
        // The file might be in use or have permissions issues, but its name is generated uniquely.
        char log_path_buf[MAX_PATH * 2]; // Roughly enough for UTF-8 conversion
        _tchar_to_char_buf(temp_dir_name, log_path_buf, sizeof(log_path_buf));
        fprintf(stderr, "create_temp_dir: Warning: Could not delete temporary file '%s': %lu\n",
                log_path_buf, GetLastError());
    }

    // Now, create a directory with the exact same unique name.
    if (!CreateDirectory(temp_dir_name, NULL)) {
        char log_path_buf[MAX_PATH * 2]; // Roughly enough for UTF-8 conversion
        _tchar_to_char_buf(temp_dir_name, log_path_buf, sizeof(log_path_buf));
        fprintf(stderr, "create_temp_dir: Error creating temporary directory '%s': %lu\n",
                log_path_buf, GetLastError());
        return NULL;
    }

    // Convert the TCHAR path to char* for the return value, as required by the function signature.
    result_path = _tchar_to_char_alloc(temp_dir_name);
    if (!result_path) {
        fprintf(stderr, "create_temp_dir: Error converting TCHAR path to char path (malloc/conversion error).\n");
        // Attempt to clean up the directory if conversion failed, to avoid leaving junk.
        RemoveDirectory(temp_dir_name); // This function takes TCHAR*
        return NULL;
    }

#else // POSIX (Linux, macOS, BSD, etc.)
    const char* tmpdir_base = getenv("TMPDIR");
    if (!tmpdir_base) {
        // Fallback to standard POSIX temporary directories if TMPDIR environment variable is not set.
        tmpdir_base = "/tmp";
    }

    // Construct the template string for mkdtemp.
    // It must end with "XXXXXX". mkdtemp will replace these with unique characters.
    // `myprog-temp-` serves as an identifier for directories created by this program.
    char template_buffer[PATH_MAX];
    int ret = snprintf(template_buffer, sizeof(template_buffer), "%s/myprog-temp-XXXXXX", tmpdir_base);

    if (ret < 0 || (size_t)ret >= sizeof(template_buffer)) {
        fprintf(stderr, "create_temp_dir: Error creating temporary directory template: snprintf failed or truncated buffer.\n");
        return NULL;
    }

    // mkdtemp modifies the template_buffer in place by replacing XXXXXX with unique characters,
    // and then creates the directory with 0700 permissions (read/write/execute for owner only).
    // It guarantees a unique name and handles race conditions.
    char* created_path_in_buffer = mkdtemp(template_buffer);

    if (created_path_in_buffer == NULL) {
        fprintf(stderr, "create_temp_dir: Error creating temporary directory: %s\n", strerror(errno));
        return NULL;
    }

    // Duplicate the string so the caller receives a dynamically allocated copy
    // that persists after this function returns and can be freed by the caller.
    result_path = strdup(created_path_in_buffer);

    if (result_path == NULL) {
        fprintf(stderr, "create_temp_dir: Error allocating memory for path string: %s\n", strerror(errno));
        // mkdtemp successfully created the directory, but strdup failed.
        // Try to remove the directory we just created to avoid leaving junk behind.
        rmdir(created_path_in_buffer);
        return NULL;
    }

#endif

    return result_path;
}

