#include <stdio.h>
#include <complex.h>

void mandelbrot(int width, int height, int max_iterations) {
    // Define the complex plane boundaries
    double x_min = -2.0;
    double x_max = 1.0;
    double y_min = -1.5;
    double y_max = 1.5;

    // Create the character map for visualization
    char *intensity_map = " .-:=+*#%@";
    int map_size = strlen(intensity_map) - 1;

    // Iterate through each pixel
    for (int py = 0; py < height; py++) {
        for (int px = 0; px < width; px++) {
            // Map pixel coordinates to complex plane coordinates
            double x0 = x_min + (x_max - x_min) * px / (width - 1.0);
            double y0 = y_min + (y_max - y_min) * py / (height - 1.0);

            // Complex number initialization
            double complex c = x0 + y0 * I;
            double complex z = 0;

            // Iterate and check for divergence
            int iteration = 0;
            while (iteration < max_iterations) {
                // Mandelbrot set formula: z = z^2 + c
                z = z * z + c;

                // Check if point escapes
                if (cabs(z) > 2.0) {
                    break;
                }
                iteration++;
            }

            // Choose character based on iteration count
            int intensity = (iteration == max_iterations) ? 0 : 
                            (iteration * map_size) / max_iterations;
            printf("%c", intensity_map[intensity]);
        }
        printf("\n");
    }
}

int main() {
    // Example usage
    int width = 80;
    int height = 40;
    int max_iterations = 100;

    mandelbrot(width, height, max_iterations);

    return 0;
}

#include <stdio.h>
#include <complex.h>

#define WIDTH 80
#define HEIGHT 40
#define X_MIN -2.0
#define X_MAX 1.0
#define Y_MIN -1.0
#define Y_MAX 1.0

void generate_mandelbrot(int iterations) {
    double x, y;
    double complex c, z;
    int i, j, k;
    char *chars = " .:-=+*#%@";

    for (i = 0; i < HEIGHT; i++) {
        for (j = 0; j < WIDTH; j++) {
            x = X_MIN + (X_MAX - X_MIN) * j / WIDTH;
            y = Y_MIN + (Y_MAX - Y_MIN) * i / HEIGHT;
            c = x + y * I;
            z = 0 + 0 * I;

            for (k = 0; k < iterations; k++) {
                z = z * z + c;
                if (creal(z) * creal(z) + cimag(z) * cimag(z) > 4.0) {
                    break;
                }
            }

            if (k == iterations) {
                printf("%c", chars[0]);
            } else {
                int index = (k % (sizeof(chars) - 1)) + 1;
                printf("%c", chars[index]);
            }
        }
        printf("\n");
    }
}

int main() {
    int iterations = 1000;
    generate_mandelbrot(iterations);
    return 0;
}

#include <stdio.h>
#include <stdlib.h> // For abs, but we'll implement our own for doubles
#include <math.h>   // For sqrt

// Structure to represent a complex number
typedef struct {
    double real;
    double imag;
} Complex;

// Function to calculate the (square of the) magnitude of a complex number
// We use magnitude squared to avoid sqrt for performance until the final check
double complex_magnitude_sq(Complex z) {
    return z.real * z.real + z.imag * z.imag;
}

// Function to multiply two complex numbers
Complex complex_multiply(Complex a, Complex b) {
    Complex result;
    result.real = a.real * b.real - a.imag * b.imag;
    result.imag = a.real * b.imag + a.imag * b.real;
    return result;
}

// Function to add two complex numbers
Complex complex_add(Complex a, Complex b) {
    Complex result;
    result.real = a.real + b.real;
    result.imag = a.imag + b.imag;
    return result;
}

/**
 * @brief Calculates the number of iterations for a given complex number 'c' to escape the Mandelbrot set.
 *
 * This function implements the core Mandelbrot iteration: z_n+1 = z_n^2 + c, starting with z_0 = 0.
 * It returns the number of iterations before the magnitude of z exceeds 2, or max_iterations if it doesn't escape.
 *
 * @param c The complex number to test.
 * @param max_iterations The maximum number of iterations to perform.
 * @return The number of iterations to escape, or max_iterations if it doesn't escape within the limit.
 */
int get_mandelbrot_iterations(Complex c, int max_iterations) {
    Complex z = {0.0, 0.0}; // z_0 = 0
    int iterations = 0;

    while (complex_magnitude_sq(z) < 4.0 && iterations < max_iterations) {
        z = complex_add(complex_multiply(z, z), c);
        iterations++;
    }

    return iterations;
}

