/**
 * @brief Generates and prints the Mandelbrot set in ASCII art.
 *
 * This function iterates through a grid of complex numbers, calculates their
 * escape times, and then maps these times to ASCII characters to render the set.
 *
 * @param max_iterations The maximum number of iterations for Mandelbrot calculation.
 * @param width The width of the ASCII art output (number of columns).
 * @param height The height of the ASCII art output (number of rows).
 * @param x_min The minimum real value for the Mandelbrot view.
 * @param x_max The maximum real value for the Mandelbrot view.
 * @param y_min The minimum imaginary value for the Mandelbrot view.
 * @param y_max The maximum imaginary value for the Mandelbrot view.
 */
void generate_mandelbrot_ascii(int max_iterations, int width, int height,
                                double x_min, double x_max, double y_min, double y_max) {
    // Character set for mapping iterations to ASCII art.
    // More characters provide finer "color" detail.
    const char *charset = " .:-=+*#%@";
    int charset_len = strlen(charset);

    printf("Generating Mandelbrot Set (Iterations: %d, Size: %dx%d)\n",
           max_iterations, width, height);

    double x_step = (x_max - x_min) / width;
    double y_step = (y_max - y_min) / height;

    for (int j = 0; j < height; j++) {
        double imag = y_min + j * y_step;
        for (int i = 0; i < width; i++) {
            double real = x_min + i * x_step;

            Complex c = {real, imag};
            int iterations = get_mandelbrot_iterations(c, max_iterations);

            // Map iterations to a character
            if (iterations == max_iterations) {
                // Inside the set (looks like a black dot)
                printf(" ");
            } else {
                // Outside the set, use a character from the charset based on escape time
                // The mapping scales the iterations to the available characters.
                // A higher iteration count (slower escape) will map to a character earlier in the charset.
                // Multiplying by 1.0 ensures floating-point division.
                int char_index = (int)((double)iterations / max_iterations * charset_len);
                // Clamp index to ensure it's within bounds
                if (char_index >= charset_len) {
                    char_index = charset_len - 1;
                }
                printf("%c", charset[char_index]);
            }
        }
        printf("\n"); // New line for each row
    }
}

