            double Z_re = 0, Z_im = 0;
            int n = 0;
            while (Z_re*Z_re + Z_im*Z_im <= 4.0 && n < iterations) {
                double Z_re2 = Z_re*Z_re - Z_im*Z_im + c_re;
                double Z_im2 = 2 * Z_re * Z_im + c_im;
                Z_re = Z_re2;
                Z_im = Z_im2;
                n++;
            }
            int index;
            if (n == iterations)
                index = charset_len - 1; // In the set (black/solid)
            else
                index = n * (charset_len - 1) / iterations; // Gradient
            putchar(charset[index]);
        }
        putchar('\n');
    }
