// Function to compute if a point is in the Mandelbrot set
int mandelbrot(double real, double imag, int max_iterations) {
    double zr = 0.0, zi = 0.0; // z = zr + zi*i
    int iter;
    for (iter = 0; iter < max_iterations; ++iter) {
        double temp = zr * zr - zi * zi + real;
        zi = 2.0 * zr * zi + imag;
        zr = temp;
        if (zr * zr + zi * zi > 4.0) {
            break; // Point is not in the Mandelbrot set
        }
    }
    return iter;
}

// Function to generate and print the Mandelbrot set in ASCII art
void generate_mandelbrot(int width, int height, int max_iterations) {
    double real_min = -2.0, real_max = 1.0;  // Real axis range
    double imag_min = -1.0, imag_max = 1.0;  // Imaginary axis range
    double real_factor = (real_max - real_min) / (width - 1);
    double imag_factor = (imag_max - imag_min) / (height - 1);

    for (int y = 0; y < height; ++y) {
        double imag = imag_max - y * imag_factor;
        for (int x = 0; x < width; ++x) {
            double real = real_min + x * real_factor;
            int iter = mandelbrot(real, imag, max_iterations);

            // Choose ASCII character based on the number of iterations
            if (iter == max_iterations) {
                printf("#"); // Point is in the Mandelbrot set
            } else if (iter > max_iterations / 2) {
                printf("+"); // Near set boundary
            } else if (iter > max_iterations / 4) {
                printf(".");
            } else {
                printf(" "); // Outside Mandelbrot set
            }
        }
        printf("\n");
    }
}

