void generateMandelbrot(int width, int height, int maxIterations) {
    // Define the range for the real and imaginary parts of the complex plane
    double minReal = -2.0;
    double maxReal = 1.0;
    double minImaginary = -1.5;
    double maxImaginary = 1.5;

    // Loop over each pixel in the specified width and height
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            // Map pixel coordinate to a point in the complex plane
            double real = minReal + (x / (double)width) * (maxReal - minReal);
            double imaginary = minImaginary + (y / (double)height) * (maxImaginary - minImaginary);

            double zReal = real, zImaginary = imaginary;
            int iterations = 0;

            // Determine the number of iterations until the point escapes
            while (zReal * zReal + zImaginary * zImaginary <= 4.0 && iterations < maxIterations) {
                double tempReal = zReal * zReal - zImaginary * zImaginary + real;
                zImaginary = 2 * zReal * zImaginary + imaginary;
                zReal = tempReal;
                iterations++;
            }

            // Map the number of iterations to an ASCII character
            char outputCharacter;
            if (iterations == maxIterations) {
                outputCharacter = '#'; // Inside the Mandelbrot set
            } else {
                // Use a gradient based on the number of iterations
                outputCharacter = ' ';
                if (iterations > 0 && iterations < maxIterations / 10) {
                    outputCharacter = '.';
                } else if (iterations < maxIterations / 5) {
                    outputCharacter = '*';
                } else if (iterations < maxIterations / 3) {
                    outputCharacter = 'o';
                } else if (iterations < maxIterations / 2) {
                    outputCharacter = 'x';
                } else {
                    outputCharacter = '@';
                }
            }

            // Print the ASCII character
            putchar(outputCharacter);
        }
        putchar('\n');
    }
}

