// Structure to represent a point in the complex plane
typedef struct {
    double real;
    double imaginary;
} Complex;

// Function to check if a complex number is in the Mandelbrot set
int is_in_mandelbrot(Complex c, int iterations) {
    Complex z = {0, 0};
    int i;

    for (i = 0; i < iterations; i++) {
        // Calculate z = z^2 + c
        double temp_real = z.real * z.real - z.imaginary * z.imaginary + c.real;
        double temp_imaginary = 2 * z.real * z.imaginary + c.imaginary;

        z.real = temp_real;
        z.imaginary = temp_imaginary;

        // Check if the magnitude of z exceeds 2 (i.e., it escapes the circle)
        if (z.real * z.real + z.imaginary * z.imaginary > 4) {
            return 0; // Not in the Mandelbrot set
        }
    }

    return 1; // In the Mandelbrot set
}

// Function to generate the Mandelbrot set in ASCII art
void generate_mandelbrot(int width, int height, int iterations) {
