            double real = (x - width / 2) * 3.5 / (width / 2);
            double imaginary = (y - height / 2) * 2.0 / (height / 2);

            Complex c = {real, imaginary};

            if (is_in_mandelbrot(c, iterations)) {
                printf("*"); // In the Mandelbrot set
            } else {
                printf(" "); // Not in the Mandelbrot set
            }
        }
        printf("\n");
    }
}

