// Function to check if a character is uppercase
bool is_uppercase(char c) {
    return (c >= 'A' && c <= 'Z');
}

// Function to convert camel case to snake case
void convert_camel_to_snake(char* input, char* output) {
    int input_len = strlen(input);
    int output_index = 0;

    for (int i = 0; i < input_len; i++) {
        if (i > 0 && is_uppercase(input[i])) {
            // Add underscore before uppercase letter
            output[output_index++] = '_';
            // Convert uppercase to lowercase
            output[output_index++] = tolower(input[i]);
        } else {
            // Directly copy lowercase or first letter
            output[output_index++] = tolower(input[i]);
        }
    }

    // Null-terminate the output string
    output[output_index] = '\0';
}

// Function to process the file and convert camel case to snake case
int convert_file_camel_to_snake(const char* input_filename, const char* output_filename) {
    FILE* input_file = fopen(input_filename, "r");
    if (input_file == NULL) {
        perror("Error opening input file");
        return -1;
    }

    FILE* output_file = fopen(output_filename, "w");
    if (output_file == NULL) {
        perror("Error opening output file");
        fclose(input_file);
        return -1;
    }

    char line[1024];
    char converted_line[1024];

    while (fgets(line, sizeof(line), input_file)) {
        char* token = strtok(line, " \t\n\r");

        while (token != NULL) {
            // Check if the token is a camel case word
            bool is_camel_case = false;
            for (int i = 1; token[i] != '\0'; i++) {
                if (is_uppercase(token[i])) {
                    is_camel_case = true;
                    break;
                }
            }

            // Convert to snake case if it's a camel case word
            if (is_camel_case) {
                convert_camel_to_snake(token, converted_line);
                fprintf(output_file, "%s ", converted_line);
            } else {
                fprintf(output_file, "%s ", token);
            }

            // Get next token
            token = strtok(NULL, " \t\n\r");
        }

        // Add newline at the end of each line
        fprintf(output_file, "\n");
    }

    // Close files
    fclose(input_file);
    fclose(output_file);

    return 0;
}

