void camel_to_snake(const char *filename) {
    FILE *file = fopen(filename, "r+");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    // Determine file size
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    // Allocate buffer for file content
    char *buffer = (char *)malloc(file_size + 1);
    if (buffer == NULL) {
        fclose(file);
        perror("Memory allocation failed");
        return;
    }

    // Read file into buffer
    size_t bytes_read = fread(buffer, 1, file_size, file);
    buffer[bytes_read] = '\0';

    // Process buffer
    char *result = (char *)malloc(2 * file_size + 1); // Worst case: every char is uppercase
    if (result == NULL) {
        free(buffer);
        fclose(file);
        perror("Memory allocation failed");
        return;
    }

    int result_index = 0;
    int in_word = 0;
    int word_start = 0;

    for (int i = 0; i < bytes_read; i++) {
        if (isalpha(buffer[i])) {
            if (!in_word) {
                word_start = i;
                in_word = 1;
            }
        } else {
            if (in_word) {
                // Process the word from word_start to i-1
                int word_len = i - word_start;
                if (word_len > 1 && isupper(buffer[word_start])) {
                    // Potential camel case word
                    int has_lower = 0;
                    int has_upper_after_lower = 0;

                    for (int j = word_start + 1; j < i; j++) {
                        if (islower(buffer[j])) {
                            has_lower = 1;
                        }
                        if (has_lower && isupper(buffer[j])) {
                            has_upper_after_lower = 1;
                            break;
                        }
                    }

                    if (has_upper_after_lower) {
                        // Convert camel case to snake case
                        for (int j = word_start; j < i; j++) {
                            if (isupper(buffer[j]) && j != word_start) {
                                result[result_index++] = '_';
                                result[result_index++] = tolower(buffer[j]);
                            } else {
                                result[result_index++] = tolower(buffer[j]);
                            }
                        }
                    } else {
                        // Not camel case, copy as is
                        for (int j = word_start; j < i; j++) {
                            result[result_index++] = buffer[j];
                        }
                    }
                } else {
                    // Not camel case, copy as is
                    for (int j = word_start; j < i; j++) {
                        result[result_index++] = buffer[j];
                    }
                }
            }
            in_word = 0;
            result[result_index++] = buffer[i];
        }
    }

    // Handle last word if file ends with a letter
    if (in_word) {
        int word_len = bytes_read - word_start;
        if (word_len > 1 && isupper(buffer[word_start])) {
            // Potential camel case word
            int has_lower = 0;
            int has_upper_after_lower = 0;

            for (int j = word_start + 1; j < bytes_read; j++) {
                if (islower(buffer[j])) {
                    has_lower = 1;
                }
                if (has_lower && isupper(buffer[j])) {
                    has_upper_after_lower = 1;
                    break;
                }
            }

            if (has_upper_after_lower) {
                // Convert camel case to snake case
                for (int j = word_start; j < bytes_read; j++) {
                    if (isupper(buffer[j]) && j != word_start) {
                        result[result_index++] = '_';
                        result[result_index++] = tolower(buffer[j]);
                    } else {
                        result[result_index++] = tolower(buffer[j]);
                    }
                }
            } else {
                // Not camel case, copy as is
                for (int j = word_start; j < bytes_read; j++) {
                    result[result_index++] = buffer[j];
                }
            }
        } else {
            // Not camel case, copy as is
            for (int j = word_start; j < bytes_read; j++) {
                result[result_index++] = buffer[j];
            }
        }
    }

    result[result_index] = '\0';

    // Write back to file
    fseek(file, 0, SEEK_SET);
    fwrite(result, 1, result_index, file);
    ftruncate(fileno(file), result_index); // Truncate in case new content is shorter

    // Clean up
    free(buffer);
    free(result);
    fclose(file);
}

