// Helper function: Duplicates a substring. Similar to strndup (GNU extension).
// Returns a dynamically allocated string, which must be freed by the caller.
char* my_strndup(const char* s, size_t n) {
    char* new_s = (char*)malloc(n + 1); // +1 for null terminator
    if (new_s == NULL) {
        perror("my_strndup: malloc failed");
        return NULL;
    }
    strncpy(new_s, s, n);
    new_s[n] = '\0'; // Ensure null-termination
    return new_s;
}

/**
 * @brief Converts a single camelCase string to snake_case.
 *
 * This function handles common camelCase patterns, including initial capitals,
 * mid-word capitals, and sequences of uppercase letters.
 *
 * @param camelStr The input string in camelCase.
 * @return A dynamically allocated string in snake_case. The caller is responsible for freeing this memory.
 *         Returns NULL if memory allocation fails.
 */
char* camel_to_snake(const char* camelStr) {
    if (!camelStr || *camelStr == '\0') {
        return strdup(""); // Return an empty, allocated string for empty input
    }

    size_t len = strlen(camelStr);
    // Max possible length: original_len + original_len - 1 (for underscores) + 1 (null terminator)
    // E.g., "ABC" -> "a_b_c" (len 3 -> 5)
    char* snakeStr = (char*)malloc(len * 2 + 1); // Allocate enough memory
    if (!snakeStr) {
        perror("camel_to_snake: malloc failed for snakeStr");
        return NULL;
    }

    size_t snake_idx = 0; // Current write position in snakeStr

    // Handle the first character: it's always lowercase (unless non-alpha)
    if (len > 0) {
        snakeStr[snake_idx++] = tolower(camelStr[0]);
    }

    // Iterate through the rest of the string
    for (size_t i = 1; i < len; ++i) {
        if (isupper(camelStr[i])) {
            // Rule 1: Insert '_' if the previous character was lowercase
            // E.g., "myVariable" -> "my_variable"
            if (islower(camelStr[i-1])) {
                snakeStr[snake_idx++] = '_';
            }
            // Rule 2: Insert '_' if current is uppercase, previous was uppercase, BUT next is lowercase.
            // This handles acronyms correctly, e.g., "HTTPRequest" -> "http_request"
            // The underscore goes BEFORE the capital letter that starts the new semantic "word".
            else if (i + 1 < len && isupper(camelStr[i-1]) && islower(camelStr[i+1])) {
                snakeStr[snake_idx++] = '_';
            }
            // Append the current character (converted to lowercase)
            snakeStr[snake_idx++] = tolower(camelStr[i]);
        } else {
            // If it's not an uppercase letter, just append it
            // This includes lowercase letters, numbers, and any other characters.
            // Also convert to lowercase to handle cases like "FooBAR" -> "foo_bar" not "foo_BAR".
            snakeStr[snake_idx++] = tolower(camelStr[i]);
        }
    }
    snakeStr[snake_idx] = '\0'; // Null-terminate the resulting snake_case string

    return snakeStr;
}

/**
 * @brief Reads a file, converts all camelCase words to snake_case within its content,
 *        and writes the modified content back to the same file.
 *
 * This function reads the entire file content into memory, identifies sequences of
 * alphanumeric characters (words), converts them using `camel_to_snake`, and then
 * reconstructs the file content before overwriting the original file.
 *
 * @param filename The path to the file to modify.
 * @return 0 on success, -1 on failure (e.g., file not found, memory allocation error,
 *         read/write error).
 */
int camel_to_snake_in_file(const char* filename) {
    FILE *fp_read = NULL;
    FILE *fp_write = NULL;
    char *file_content = NULL;
    char *modified_content = NULL;
    long file_size;

    // 1. Open the file for reading
    fp_read = fopen(filename, "r");
    if (fp_read == NULL) {
        perror("Error opening file for reading");
        return -1;
    }

    // 2. Determine file size
    fseek(fp_read, 0, SEEK_END);
    file_size = ftell(fp_read);
    if (file_size == -1L) { // ftell can return -1 on error
        perror("Error getting file size");
        fclose(fp_read);
        return -1;
    }
    rewind(fp_read); // Go back to the beginning of the file

    // 3. Allocate memory for file content (+1 for null terminator)
    file_content = (char*)malloc(file_size + 1);
    if (file_content == NULL) {
        perror("Error allocating memory for file content");
        fclose(fp_read);
        return -1;
    }

    // 4. Read file content into buffer
    if (fread(file_content, 1, file_size, fp_read) != (size_t)file_size) {
        perror("Error reading file content");
        free(file_content);
        fclose(fp_read);
        return -1;
    }
    file_content[file_size] = '\0'; // Null-terminate the content string

    // 5. Close the read file handle
    fclose(fp_read);
    fp_read = NULL; // Mark as closed

    // 6. Allocate initial memory for the modified content buffer.
    // Worst case expansion is roughly 2x (e.g., "ABC" becomes "a_b_c").
    // We'll use realloc if more space is needed.
    size_t current_modified_capacity = file_size * 2 + 1; 
    modified_content = (char*)malloc(current_modified_capacity);
    if (modified_content == NULL) {
        perror("Error allocating initial memory for modified content");
        free(file_content);
        return -1;
    }
    modified_content[0] = '\0'; // Start with an empty string

    size_t modified_idx = 0; // Current write position in modified_content
    size_t current_word_start = 0; // Start index of the current word in file_content
    char* snake_word = NULL; // To store the snake_case converted word

    // 7. Iterate through the file content to identify and convert words
    // Loop continues until (and including) the null terminator of file_content
    for (size_t i = 0; i <= file_size; ++i) {
        // If current character is non-alphanumeric OR it's the end of the string,
        // it marks the end of a potential word.
        if (i == file_size || !isalnum(file_content[i])) {
            // Check if we found a word (i.e., current_word_start is before i)
            if (i > current_word_start) { 
                // Extract the word using the my_strndup helper
                char* temp_word = my_strndup(file_content + current_word_start, i - current_word_start);
                if (temp_word == NULL) {
                    free(file_content);
                    free(modified_content);
                    return -1; // Memory allocation failed in my_strndup
                }

                // Convert the extracted word to snake_case
                snake_word = camel_to_snake(temp_word);
                free(temp_word); // Free the temporary word buffer

                if (snake_word == NULL) {
                    // camel_to_snake failed (memory error), clean up and return
                    free(file_content);
                    free(modified_content);
                    return -1;
                }

                size_t snake_word_len = strlen(snake_word);

                // Ensure enough space in modified_content for the snake_word
                if (modified_idx + snake_word_len + 1 > current_modified_capacity) {
                    current_modified_capacity *= 2; // Double the capacity
                    char* new_ptr = (char*)realloc(modified_content, current_modified_capacity);
                    if (new_ptr == NULL) {
                        perror("Error reallocating memory for modified content");
                        free(file_content);
                        free(snake_word);
                        free(modified_content); // Free the old pointer if realloc failed
                        return -1;
                    }
                    modified_content = new_ptr;
                }

                // Append the snake_word to modified_content
                strcpy(modified_content + modified_idx, snake_word);
                modified_idx += snake_word_len;
                free(snake_word); // Free the allocated snake_word
                snake_word = NULL;
            }

            // Append the non-alphanumeric character (if not end of string)
            if (i < file_size) {
                 // Ensure space for the non-alphanumeric char + null terminator
                 if (modified_idx + 1 + 1 > current_modified_capacity) { 
                    current_modified_capacity *= 2;
                    char* new_ptr = (char*)realloc(modified_content, current_modified_capacity);
                    if (new_ptr == NULL) {
                        perror("Error reallocating memory for modified content (trailer char)");
                        free(file_content);
                        free(modified_content);
                        return -1;
                    }
                    modified_content = new_ptr;
                }
                modified_content[modified_idx++] = file_content[i];
            }
            current_word_start = i + 1; // Move to the character after the non-alphanumeric one
        } else {
            // Keep accumulating characters into the current word.
            // `current_word_start` remains the same.
        }
    }
    modified_content[modified_idx] = '\0'; // Null-terminate the final modified string

    // 8. Open the file for writing (this truncates the file to zero length)
    fp_write = fopen(filename, "w");
    if (fp_write == NULL) {
        perror("Error opening file for writing");
        free(file_content);
        free(modified_content);
        return -1;
    }

    // 9. Write the modified content back to the file
    if (fwrite(modified_content, 1, modified_idx, fp_write) != modified_idx) {
        perror("Error writing modified content to file");
        // An error here means the file might be partially written or corrupted
        fclose(fp_write); 
        free(file_content);
        free(modified_content);
        return -1;
    }

    // 10. Clean up allocated memory and close file
    fclose(fp_write);
    free(file_content);
    free(modified_content);

    return 0; // Success
}

