#include <stdio.h>
#include <ctype.h>
#include <string.h>
#include <stdlib.h>

void camel_to_snake_in_file(const char *filename) {
    FILE *fin = fopen(filename, "r");
    if (!fin) {
        perror("Cannot open input file");
        return;
    }
    // Create temporary file
    char tmpname[FILENAME_MAX];
    snprintf(tmpname, sizeof(tmpname), "%s.tmp", filename);
    FILE *fout = fopen(tmpname, "w");
    if (!fout) {
        perror("Cannot open temp output file");
        fclose(fin);
        return;
    }

    int c, prev_is_word = 0;
    char word[512];
    int wlen = 0;

    while ((c = fgetc(fin)) != EOF) {
        if (isalnum(c) || c == '_') {
            word[wlen++] = c;
            prev_is_word = 1;
        } else {
            if (prev_is_word) {
                word[wlen] = 0;
                // --- Convert word to snake_case if it contains any uppercase after first char ---
                int has_camel = 0;
                for (int i = 1; i < wlen; ++i) {
                    if (isupper(word[i])) {
                        has_camel = 1;
                        break;
                    }
                }
                if (has_camel) {
                    // Write word converted to snake_case
                    for (int i = 0; i < wlen; ++i) {
                        if (isupper(word[i])) {
                            if (i > 0) fputc('_', fout);
                            fputc(tolower(word[i]), fout);
                        } else {
                            fputc(word[i], fout);
                        }
                    }
                } else {
                    fputs(word, fout);
                }
                wlen = 0;
                prev_is_word = 0;
            }
            fputc(c, fout);
        }
    }

    // Handle last word if file did not end with non-word
    if (wlen > 0) {
        word[wlen] = 0;
        int has_camel = 0;
        for (int i = 1; i < wlen; ++i) {
            if (isupper(word[i])) {
                has_camel = 1;
                break;
            }
        }
        if (has_camel) {
            for (int i = 0; i < wlen; ++i) {
                if (isupper(word[i])) {
                    if (i > 0) fputc('_', fout);
                    fputc(tolower(word[i]), fout);
                } else {
                    fputc(word[i], fout);
                }
            }
        } else {
            fputs(word, fout);
        }
    }

    fclose(fin);
    fclose(fout);

    // Overwrite the original file
    remove(filename);
    rename(tmpname, filename);
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

void camel_to_snake(const char* filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    // Determine the size of the file
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    // Allocate memory to hold the file content
    char *content = (char *)malloc(file_size + 1);
    if (content == NULL) {
        perror("Memory allocation failed");
        fclose(file);
        return;
    }

    // Read the entire file into memory
    fread(content, 1, file_size, file);
    content[file_size] = '\0';
    fclose(file);

    // Prepare buffer for the new content
    char *new_content = (char *)malloc(file_size * 2); // Allocate more space for underscores
    if (new_content == NULL) {
        perror("Memory allocation failed");
        free(content);
        return;
    }

    char *p = content;
    char *q = new_content;

    // Main conversion process
    while (*p) {
        if (isupper(*p)) {
            // Prepend an underscore for uppercase letters converting
            // to snake_case unless it's the start of the new content
            if (p != content && *(p - 1) != '_') {
                *q++ = '_';
            }
            *q++ = tolower(*p);
        } else {
            *q++ = *p;
        }
        p++;
    }
    *q = '\0';

    // Write the new content back to the file
    file = fopen(filename, "w");
    if (file == NULL) {
        perror("Error opening file");
        free(new_content);
        free(content);
        return;
    }
    fprintf(file, "%s", new_content);
    fclose(file);

    // Clean up
    free(new_content);
    free(content);
}

int main() {
    const char *filename = "example.txt";
    camel_to_snake(filename);
    return 0;
}

#include <stdio.h>
