#include <string.h>
#include <ctype.h>

void convertCamelToSnake(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Could not open file");
        return;
    }

    // Use a dynamic array to hold the file's contents
    size_t size = 1024;
    char *buffer = malloc(size);
    if (!buffer) {
        perror("Memory allocation failed");
        fclose(file);
        return;
    }

    // Read the file contents
    size_t length = fread(buffer, 1, size - 1, file);
    buffer[length] = '\0';  // Null-terminate the string

    fclose(file);

    // Prepare a new buffer for the output
    char *output = malloc(size * 2); // Allocate larger space for output
    if (!output) {
        perror("Memory allocation failed");
        free(buffer);
        return;
    }

    size_t outIndex = 0;

    for (size_t i = 0; i < length; i++) {
        if (isupper(buffer[i])) {
            // If the output buffer is not empty, add an underscore before the upper case char
            if (i != 0 && outIndex < size * 2 - 1) {
                output[outIndex++] = '_';
            }
            output[outIndex++] = tolower(buffer[i]); // Convert to lower case
        } else {
            output[outIndex++] = buffer[i]; // Copy the character as is
        }
    }
    output[outIndex] = '\0';  // Null-terminate the string

    // Write the modified contents back to the file
    file = fopen(filename, "w");
    if (!file) {
        perror("Could not open file for writing");
        free(buffer);
        free(output);
        return;
    }

    fwrite(output, 1, outIndex, file);

    fclose(file);
    free(buffer);
    free(output);
}

