    const char *filename = "example.txt"; // Change this to the target file name
    convertCamelToSnake(filename);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Function to convert camel case to snake case
void camel_to_snake(char* str) {
    for (int i = 1; i < strlen(str); i++) {
        if (isupper(str[i]) && (islower(str[i-1]) || (i > 1 && islower(str[i-2])))) {
            memmove(str+i+1, str+i, strlen(str+i) + 1);
            str[i] = '_';
            i++;
        }
    }
    for (int i = 0; i < strlen(str); i++) {
        str[i] = tolower(str[i]);
    }
}

// Function to get file contents
char* get_file_contents(const char* filename, int* size) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }
    fseek(file, 0, SEEK_END);
    *size = ftell(file);
    rewind(file);
    char* contents = malloc(*size + 1);
    if (contents == NULL) {
        perror("Error allocating memory");
        exit(EXIT_FAILURE);
    }
    if (fread(contents, 1, *size, file) != *size) {
        perror("Error reading file");
        exit(EXIT_FAILURE);
    }
    contents[*size] = '\0';
    fclose(file);
    return contents;
}

// Function to write to file
void write_to_file(const char* filename, const char* contents) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }
    if (fwrite(contents, 1, strlen(contents), file) != strlen(contents)) {
        perror("Error writing to file");
        exit(EXIT_FAILURE);
    }
    fclose(file);
}

// Main function to get a file name and change all camel case words to snake case
void convert_camel_case_to_snake_case(const char* filename) {
    int size;
    char* contents = get_file_contents(filename, &size);
    camel_to_snake(contents);
    write_to_file(filename, contents);
    free(contents);
}

int main() {
    convert_camel_case_to_snake_case("example.txt");
    return 0;
}

