    int outIndex = 0;

    for (int i = 0; i < len; i++) {
        if (isupper(input[i])) {
            if (i > 0) {
                output[outIndex++] = '_';
            }
            output[outIndex++] = tolower(input[i]);
        } else {
            output[outIndex++] = input[i];
        }
    }
    output[outIndex] = '\0';
