#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int sumOfMissingNumbers(int* arr, int size) {
    // If the array is empty or has only one element, return 0
    if (size <= 1) {
        return 0;
    }

    // Find the minimum and maximum values in the array
    int min = INT_MAX;
    int max = INT_MIN;

    for (int i = 0; i < size; i++) {
        if (arr[i] < min) {
            min = arr[i];
        }
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    // Create a boolean array to mark present numbers
    int* present = (int*)calloc(max - min + 1, sizeof(int));

    // Mark the numbers that are present in the array
    for (int i = 0; i < size; i++) {
        present[arr[i] - min] = 1;
    }

    // Calculate the sum of missing numbers
    int missingSum = 0;
    for (int num = min + 1; num < max; num++) {
        if (present[num - min] == 0) {
            missingSum += num;
        }
    }

    // Free the dynamically allocated memory
    free(present);

    return missingSum;
}

// Example usage
int main() {
    int arr1[] = {1, 2, 4, 6};
    int size1 = sizeof(arr1) / sizeof(arr1[0]);
    printf("Sum of missing numbers in arr1: %d\n", sumOfMissingNumbers(arr1, size1));

    int arr2[] = {1, 3, 5, 7, 9};
    int size2 = sizeof(arr2) / sizeof(arr2[0]);
    printf("Sum of missing numbers in arr2: %d\n", sumOfMissingNumbers(arr2, size2));

    int arr3[] = {10, 20};
    int size3 = sizeof(arr3) / sizeof(arr3[0]);
    printf("Sum of missing numbers in arr3: %d\n", sumOfMissingNumbers(arr3, size3));

    return 0;
}

#include <stdio.h>
#include <limits.h>

int sumOfMissingNumbers(int *list, int size) {
    if (size == 0) {
        return 0;
    }

    // Find the minimum and maximum values in the list
    int min = INT_MAX;
    int max = INT_MIN;
    for (int i = 0; i < size; i++) {
        if (list[i] < min) {
            min = list[i];
        }
        if (list[i] > max) {
            max = list[i];
        }
    }

    // If min and max are the same, there are no missing numbers between them
    if (min == max) {
        return 0;
    }

    // Create a presence array to mark which numbers are present
    int range = max - min + 1;
    int *present = (int *)calloc(range, sizeof(int));
    if (present == NULL) {
        return -1; // Memory allocation failed
    }

    for (int i = 0; i < size; i++) {
        present[list[i] - min] = 1;
    }

    // Calculate the sum of missing numbers
    int sum = 0;
    for (int i = 0; i < range; i++) {
        if (!present[i]) {
            sum += (min + i);
        }
    }

    free(present);
    return sum;
}

int main() {
    // Example usage
    int list[] = {1, 2, 4, 6};
    int size = sizeof(list) / sizeof(list[0]);
    int result = sumOfMissingNumbers(list, size);
    printf("Sum of missing numbers: %d\n", result); // Output should be 8 (3 + 5)
    return 0;
}

#include <stdio.h>
#include <stdlib.h> // For malloc, free, qsort
#include <stdbool.h> // For bool type

// Function to compare two integers for qsort
int compareIntegers(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

/**
 * @brief Calculates the sum of all missing numbers between the minimum and maximum
 *        values in a given list of integers.
 *
 * This function first sorts the input array to easily identify the minimum and
 * maximum values. Then, it iterates from the minimum value up to the maximum value
 * and checks if each number is present in the original list. If a number is not
 * found, it's considered missing, and its value is added to the total sum.
 *
 * @param numbers An array of integers.
 * @param count The number of elements in the 'numbers' array.
 * @return The sum of all missing numbers between the minimum and maximum values.
 *         Returns 0 if the input array is empty or contains only one element,
 *         as there can be no missing numbers in such cases.
 */
long long sumMissingNumbers(int *numbers, int count) {
    if (numbers == NULL || count <= 1) {
        return 0; // No missing numbers possible for empty or single-element lists
    }

    // Create a copy of the array to sort it without modifying the original
    int *sortedNumbers = (int *)malloc(count * sizeof(int));
    if (sortedNumbers == NULL) {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed in sumMissingNumbers.\n");
        return 0; // Or some error code
    }
    for (int i = 0; i < count; i++) {
        sortedNumbers[i] = numbers[i];
    }

    // Sort the array to easily find min and max
    qsort(sortedNumbers, count, sizeof(int), compareIntegers);

    int minVal = sortedNumbers[0];
    int maxVal = sortedNumbers[count - 1];

    long long missingSum = 0;

    // Use a boolean array to mark present numbers for efficient lookup
    // This approach is good if the range (maxVal - minVal) is not excessively large.
    // If the range is very large, a hash set (or a balanced BST) would be more efficient,
    // but requires more complex data structures. For typical integer ranges, this is fine.

    // Calculate the range size
    long long rangeSize = (long long)maxVal - minVal + 1;

    // Check for potential overflow if range is too large to allocate boolean array
    if (rangeSize > (long long)2 * 1024 * 1024 * 1024 / sizeof(bool)) { // Approx 2GB limit for example
        fprintf(stderr, "Range of numbers is too large for boolean array optimization. Consider alternative data structure.\n");
        // Fallback to less efficient but always working approach: iterate and search.
        // Or handle error as per application requirements.
        // For this example, let's proceed with the basic search if the boolean array is too large.
        free(sortedNumbers); // Free the sorted copy
        // Implement a linear search for each number if the boolean array is too big
        // This makes the overall complexity O(N * (max-min)), which can be bad.
        // However, the problem implies "between min and max", so this is the range of interest.
        // If the range is truly massive, another approach (e.g., using a hash table for O(1) avg lookup)
        // would be necessary.
        // For now, let's assume the boolean array is feasible based on typical problem constraints.
        // If it's not and we still want to proceed, we'd need a different loop structure.
        return 0; // Indicate error or provide a different implementation.
    }


    bool *isPresent = (bool *)calloc(rangeSize, sizeof(bool)); // Initialize all to false
    if (isPresent == NULL) {
        fprintf(stderr, "Memory allocation for isPresent array failed.\n");
        free(sortedNumbers);
        return 0; // Or handle error
    }

    // Mark all numbers from the input array as present
    for (int i = 0; i < count; i++) {
        // Offset by minVal to map the number to an index in isPresent array
        if (sortedNumbers[i] >= minVal && sortedNumbers[i] <= maxVal) {
            isPresent[sortedNumbers[i] - minVal] = true;
        }
    }

    // Iterate from minVal to maxVal and sum missing numbers
    for (int i = minVal; i <= maxVal; i++) {
        if (!isPresent[i - minVal]) {
            missingSum += i;
        }
    }

    free(isPresent);
    free(sortedNumbers); // Don't forget to free the allocated memory

    return missingSum;
}

