int sumOfMissingNumbers(int *arr, int length) {
    if (length < 2) {
        // If array has fewer than 2 elements, no missing numbers to sum
        return 0;
    }

    int min = arr[0];
    int max = arr[0];

    // Find the minimum and maximum values in the array
    for (int i = 1; i < length; ++i) {
        if (arr[i] < min) {
            min = arr[i];
        }
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    // Create a boolean array to track the presence of each number in the range
    int range = max - min + 1;
    int presence[range];
    for (int i = 0; i < range; ++i) {
        presence[i] = 0;
    }

    // Mark presence of elements in the array
    for (int i = 0; i < length; ++i) {
        presence[arr[i] - min] = 1;
    }

    // Calculate sum of missing numbers
    int sum = 0;
    for (int i = 0; i < range; ++i) {
        if (!presence[i]) {
            sum += (min + i);
        }
    }

    return sum;
}

