int sum_of_missing_numbers(int arr[], int size) {
    if (size == 0) return 0; // If the array is empty, return 0.

    int min = arr[0];
    int max = arr[0];
    int sum_of_list = 0;

    // Find min, max and calculate the sum of the input list
    for (int i = 0; i < size; i++) {
        if (arr[i] < min) {
            min = arr[i];
        }
        if (arr[i] > max) {
            max = arr[i];
        }
        sum_of_list += arr[i];
    }

    // Calculate the sum of all integers from min to max
    int total_sum = (max * (max + 1) / 2) - ((min - 1) * min / 2);

    // The sum of missing numbers is total_sum - sum_of_list
    return total_sum - sum_of_list;
}

