/**
 * Calculates the sum of all missing numbers between the minimum and maximum values in a list.
 *
 * @param list The list of integers.
 * @param size The number of elements in the list.
 * @return The sum of all missing numbers.
 */
int sum_of_missing_numbers(int list[], int size) {
    // Find the minimum and maximum values in the list
    int min_val = list[0];
    int max_val = list[0];
    for (int i = 1; i < size; i++) {
        if (list[i] < min_val) {
            min_val = list[i];
        }
        if (list[i] > max_val) {
            max_val = list[i];
        }
    }

    // Calculate the sum of all numbers in the range
    int total_sum = (max_val - min_val + 1) * (min_val + max_val) / 2;

    // Calculate the sum of the numbers in the list
    int list_sum = 0;
    for (int i = 0; i < size; i++) {
        list_sum += list[i];
    }

    // Return the difference between the total sum and the list sum
    return total_sum - list_sum;
}

