    int capacity = 10;
    int* numbers = malloc(capacity * sizeof(int));
    int count = 0;

    int current_number = 0;
    int has_digits = 0;

    // Iterate through each character in the string
    for (int i = 0; str[i] != '\0'; i++) {
        // Check if current character is a digit
        if (isdigit(str[i])) {
            // Build number by shifting and adding new digit
            current_number = current_number * 10 + (str[i] - '0');
            has_digits = 1;
        } else {
            // If we were building a number, add it to result
            if (has_digits) {
                // Resize array if needed
                if (count >= capacity) {
                    capacity *= 2;
                    numbers = realloc(numbers, capacity * sizeof(int));
                }

                numbers[count++] = current_number;

                // Reset for next number
                current_number = 0;
                has_digits = 0;
            }
        }
    }

    // Check if there's a number at the end of the string
    if (has_digits) {
        if (count >= capacity) {
            numbers = realloc(numbers, (capacity + 1) * sizeof(int));
        }
        numbers[count++] = current_number;
    }

    // Set the result size
    *result_size = count;

    return numbers;
}

