// Define a structure to hold the dynamic list of numbers
typedef struct {
    int* data;
    int size;
    int capacity;
} IntList;

// Function to initialize an IntList
void initIntList(IntList* list, int initialCapacity) {
    list->data = (int*)malloc(sizeof(int) * initialCapacity);
    if (list->data == NULL) {
        perror("Failed to allocate memory for IntList data");
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = initialCapacity;
}

// Function to add an element to an IntList (dynamic resizing)
void addToIntList(IntList* list, int value) {
    if (list->size == list->capacity) {
        // Double the capacity
        list->capacity *= 2;
        list->data = (int*)realloc(list->data, sizeof(int) * list->capacity);
        if (list->data == NULL) {
            perror("Failed to reallocate memory for IntList data");
            exit(EXIT_FAILURE);
        }
    }
    list->data[list->size++] = value;
}

// Function to free the memory of an IntList
void freeIntList(IntList* list) {
    free(list->data);
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
}

/**
 * @brief Extracts numbers from a string, combining consecutive digits to form the longest possible numbers.
 *
 * @param str The input string containing letters and numbers.
 * @return An IntList containing the extracted integer numbers. The caller is responsible for freeing the memory of the IntList.
 */
IntList getNumbersFromString(const char* str) {
    IntList result;
    initIntList(&result, 5); // Initial capacity for the list (can be adjusted)

    if (str == NULL) {
        return result; // Return an empty list for a NULL string
    }

    int len = strlen(str);
    long long currentNumber = 0; // Use long long to prevent overflow during digit accumulation
    int inNumber = 0;           // Flag to indicate if we are currently parsing a number

    for (int i = 0; i < len; ++i) {
        if (isdigit(str[i])) {
            // It's a digit, add it to the current number
            currentNumber = currentNumber * 10 + (str[i] - '0');
            inNumber = 1;
        } else {
            // It's not a digit
            if (inNumber) {
                // If we were parsing a number, it has ended
                addToIntList(&result, (int)currentNumber); // Cast to int; assume numbers fit in int
                currentNumber = 0; // Reset for the next number
                inNumber = 0;      // Reset the flag
            }
        }
    }

    // After the loop, check if the string ended with a number
    if (inNumber) {
        addToIntList(&result, (int)currentNumber);
    }

    return result;
}

