int* extract_numbers(const char* str, int* count) {
    int capacity = 10;            // starting capacity for the result array
    int* result = malloc(capacity * sizeof(int));
    *count = 0;

    const char* p = str;
    while (*p) {
        // If we find a digit, start parsing a number
        if (isdigit(*p)) {
            int number = 0;
            // Keep reading consecutive digits
            while (*p && isdigit(*p)) {
                number = number * 10 + (*p - '0');
                p++;
            }
            // Store the found number
            if (*count >= capacity) {
                capacity *= 2;
                result = realloc(result, capacity * sizeof(int));
            }
            result[(*count)++] = number;
        } else {
            p++; // Not a digit, move to next character
        }
    }
    return result;
}

