// Function to count the number of distinct numbers in the string
int countNumbers(const char *str) {
    int count = 0;
    int inNumber = 0;

    for (int i = 0; str[i] != '\0'; i++) {
        if (isdigit(str[i])) {
            if (!inNumber) {
                count++;
                inNumber = 1;
            }
        } else {
            inNumber = 0;
        }
    }

    return count;
}

// Function to extract and store the numbers from the string
void extractNumbers(const char *str, int *numbers) {
    int index = 0;
    int num = 0;
    int inNumber = 0;

    for (int i = 0; str[i] != '\0'; i++) {
        if (isdigit(str[i])) {
            if (!inNumber) {
                num = 0;
                inNumber = 1;
            }
            num = num * 10 + (str[i] - '0');
        } else {
            if (inNumber) {
                numbers[index++] = num;
                inNumber = 0;
            }
        }
    }

    // Handle the case where the string ends with a number
    if (inNumber) {
        numbers[index++] = num;
    }
}

