int* longestIncreasingSubsequence(int* arr, int n, int* resultLen) {
    // If array is empty, return NULL
    if (n <= 0) {
        *resultLen = 0;
        return NULL;
    }

    // Arrays to store LIS lengths and previous indices
    int* lengths = malloc(n * sizeof(int));
    int* prevIndices = malloc(n * sizeof(int));

    // Initialize lengths and previous indices
    for (int i = 0; i < n; i++) {
        lengths[i] = 1;
        prevIndices[i] = -1;
    }

    // Track the maximum length and its ending index
    int maxLen = 1;
    int maxLenIndex = 0;

    // Compute LIS
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            // If current element is greater and can extend the subsequence
            if (arr[i] > arr[j] && lengths[i] < lengths[j] + 1) {
                lengths[i] = lengths[j] + 1;
                prevIndices[i] = j;
            }
        }

        // Update max length if necessary
        if (lengths[i] > maxLen) {
            maxLen = lengths[i];
            maxLenIndex = i;
        }
    }

    // Reconstruct the subsequence
    int* result = malloc(maxLen * sizeof(int));
    *resultLen = maxLen;

    // Backtrack to find the subsequence
    int current = maxLenIndex;
    for (int i = maxLen - 1; i >= 0; i--) {
        result[i] = arr[current];
        current = prevIndices[current];
    }

    // Free temporary arrays
    free(lengths);
    free(prevIndices);

    return result;
}

