#include <stdio.h>
#include <stdlib.h> // For malloc, free
#include <string.h> // For memcpy (optional, could do manual copy)

/**
 * @brief Finds the longest increasing subsequence in an array of integers.
 *
 * This function uses dynamic programming to first determine the length of the LIS
 * ending at each position, and then reconstructs one such longest subsequence
 * using a parent array.
 *
 * @param nums The input array of integers.
 * @param numsSize The number of elements in the input array.
 * @param returnSize A pointer to an integer where the size of the returned LIS
 *                   will be stored. This is crucial for the caller to know
 *                   how many elements are in the dynamically allocated array.
 * @return A dynamically allocated array containing one of the longest increasing subsequences.
 *         Returns NULL if nums is NULL or numsSize is 0.
 *         The caller is responsible for freeing the returned array.
 */
int* longestIncreasingSubsequence(int* nums, int numsSize, int* returnSize) {
    // Handle edge cases: empty or NULL input
    if (nums == NULL || numsSize == 0) {
        *returnSize = 0;
        return NULL;
    }

    // dp[i] will store the length of the LIS ending at nums[i]
    int* dp = (int*)malloc(numsSize * sizeof(int));
    if (dp == NULL) {
        perror("Failed to allocate dp array");
        *returnSize = 0;
        return NULL;
    }

    // parent[i] will store the index of the element that precedes nums[i]
    // in the LIS ending at nums[i]
    int* parent = (int*)malloc(numsSize * sizeof(int));
    if (parent == NULL) {
        perror("Failed to allocate parent array");
        free(dp);
        *returnSize = 0;
        return NULL;
    }

    int maxLength = 0; // Stores the overall maximum LIS length found
    int lastIndex = 0; // Stores the index of the last element of the LIS of maxLength

    // Initialize dp and parent arrays
    for (int i = 0; i < numsSize; i++) {
        dp[i] = 1;         // Each element is an LIS of length 1
        parent[i] = -1;    // No predecessor initially

        // Update overall maxLength and lastIndex for single element case or for first element
        if (dp[i] > maxLength) {
            maxLength = dp[i];
            lastIndex = i;
        }
    }

    // Fill dp and parent arrays
    for (int i = 1; i < numsSize; i++) {
        for (int j = 0; j < i; j++) {
            if (nums[i] > nums[j]) { // Can extend the LIS ending at nums[j]
                if (1 + dp[j] > dp[i]) { // If extending offers a longer LIS
                    dp[i] = 1 + dp[j];
                    parent[i] = j;
                }
            }
        }
        // Update overall maxLength and lastIndex
        if (dp[i] > maxLength) {
            maxLength = dp[i];
            lastIndex = i;
        }
    }

    // *returnSize tells the caller the size of the returned array
    *returnSize = maxLength;

    // Allocate memory for the actual LIS subsequence
    int* result = (int*)malloc(maxLength * sizeof(int));
    if (result == NULL) {
        perror("Failed to allocate result array");
        free(dp);
        free(parent);
        return NULL;
    }

    // Reconstruct the LIS by backtracking through the parent array
    int currentIndex = lastIndex;
    int resultIndex = maxLength - 1; // Start filling result from the end

    while (currentIndex != -1 && resultIndex >= 0) {
        result[resultIndex--] = nums[currentIndex];
        currentIndex = parent[currentIndex];
    }

    // Free the temporary dp and parent arrays
    free(dp);
    free(parent);

    return result;
}

