// Returns the length of LIS, and sets *result to a newly allocated array with the LIS
int longest_increasing_subsequence(const int* arr, int n, int** result) {
    if (n == 0) {
        *result = NULL;
        return 0;
    }
    int* dp = malloc(n * sizeof(int));     // dp[i]: length of LIS ending at index i
    int* prev = malloc(n * sizeof(int));   // prev[i]: previous index in the LIS ending at i
    for (int i = 0; i < n; ++i) {
        dp[i] = 1;
        prev[i] = -1;
    }

    int max_len = 1, max_idx = 0;
    for (int i = 1; i < n; ++i) {
        for (int j = 0; j < i; ++j) {
            if (arr[j] < arr[i] && dp[j] + 1 > dp[i]) {
                dp[i] = dp[j] + 1;
                prev[i] = j;
            }
        }
        if (dp[i] > max_len) {
            max_len = dp[i];
            max_idx = i;
        }
    }

    // Reconstruct the LIS
    int* lis = malloc(max_len * sizeof(int));
    int k = max_len - 1;
    for (int i = max_idx; i >= 0; i = prev[i]) {
        lis[k--] = arr[i];
        if (prev[i] == -1) break;
    }

    free(dp);
    free(prev);

    *result = lis;
    return max_len;
}

