    for (int i = 1; i < numsSize; i++) {
        for (int j = 0; j < i; j++) {
            if (nums[i] > nums[j] && dp[i] < dp[j] + 1) {
                dp[i] = dp[j] + 1; // Update the dp array
            }
        }
    }

    // Find the maximum value in dp array, which is the length of LIS
    int maxLength = 0;
    for (int i = 0; i < numsSize; i++) {
        if (maxLength < dp[i]) {
            maxLength = dp[i];
        }
    }

