// Function to reconstruct the longest increasing subsequence
int* longestIncreasingSubsequence(int* nums, int numsSize, int* returnSize) {
    if (numsSize == 0) {
        *returnSize = 0;
        return NULL;
    }

    int* dp = (int*)malloc(numsSize * sizeof(int));
    int* prevIndex = (int*)malloc(numsSize * sizeof(int));
    int maxLength = 0;
    int maxLengthIndex = -1;

    for (int i = 0; i < numsSize; i++) {
        dp[i] = 1;         // Initialize dp array
        prevIndex[i] = -1; // Initialize previous index array
    }

    for (int i = 1; i < numsSize; i++) {
        for (int j = 0; j < i; j++) {
            if (nums[i] > nums[j] && dp[i] < dp[j] + 1) {
                dp[i] = dp[j] + 1;
                prevIndex[i] = j; // Store the index of the previous element
            }
        }
        // Track the maximum LIS length and its index
        if (dp[i] > maxLength) {
            maxLength = dp[i];
            maxLengthIndex = i;
        }
    }

    // Reconstruct the longest increasing subsequence
    int* lis = (int*)malloc(maxLength * sizeof(int));
    int k = maxLength - 1;
    for (int i = maxLengthIndex; i >= 0; i = prevIndex[i]) {
        lis[k--] = nums[i];
        if (prevIndex[i] == -1) break; // Reached the start of the subsequence
    }

    free(dp);
    free(prevIndex);
    *returnSize = maxLength;
    return lis;
}

