#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

char* remove_python_comments_and_docstrings(const char* input_file) {
    FILE* file = fopen(input_file, "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", input_file);
        return NULL;
    }

    // Allocate initial buffer
    size_t buffer_size = 1024;
    char* output_buffer = malloc(buffer_size);
    size_t output_pos = 0;

    char line[1024];
    bool in_multiline_comment = false;
    bool in_multiline_docstring = false;
    bool in_single_quoted_string = false;
    bool in_double_quoted_string = false;
    char quote_type = '\0';

    while (fgets(line, sizeof(line), file)) {
        size_t line_len = strlen(line);
        size_t i = 0;

        while (i < line_len) {
            // Check if we're in a string
            if (!in_multiline_comment && !in_multiline_docstring) {
                if (!in_single_quoted_string && !in_double_quoted_string) {
                    // Check for start of string
                    if (line[i] == '"' || line[i] == '\'') {
                        quote_type = line[i];
                        if (line[i] == '"') in_double_quoted_string = true;
                        else in_single_quoted_string = true;
                    }
                } else {
                    // Check for end of string, respecting escaped quotes
                    if (line[i] == quote_type && 
                        (i == 0 || line[i-1] != '\\')) {
                        if (line[i] == '"') in_double_quoted_string = false;
                        else in_single_quoted_string = false;
                        quote_type = '\0';
                    }
                }
            }

            // Handle multiline docstrings
            if (!in_single_quoted_string && !in_double_quoted_string) {
                if (!in_multiline_comment) {
                    // Check for start of triple-quoted docstring
                    if (i + 2 < line_len && 
                        ((line[i] == '\"' && line[i+1] == '\"' && line[i+2] == '\"') ||
                         (line[i] == '\'' && line[i+1] == '\'' && line[i+2] == '\''))) {
                        in_multiline_docstring = true;
                        i += 2;
                    }
                }

                // Check for end of multiline docstring
                if (in_multiline_docstring && 
                    i + 2 < line_len && 
                    ((line[i] == '\"' && line[i+1] == '\"' && line[i+2] == '\"') ||
                     (line[i] == '\'' && line[i+1] == '\'' && line[i+2] == '\''))) {
                    in_multiline_docstring = false;
                    i += 2;
                }
            }

            // Handle single-line comments
            if (!in_single_quoted_string && 
                !in_double_quoted_string && 
                !in_multiline_comment && 
                !in_multiline_docstring) {
                if (i + 1 < line_len && line[i] == '#') {
                    break;  // Ignore rest of the line
                }
            }

            // Ensure buffer has enough space
            if (output_pos + 2 >= buffer_size) {
                buffer_size *= 2;
                output_buffer = realloc(output_buffer, buffer_size);
            }

            // If not in a comment or docstring, add character
            if (!in_multiline_comment && !in_multiline_docstring) {
                output_buffer[output_pos++] = line[i];
            }

            i++;
        }

        // Add newline if not in a multiline comment/docstring
        if (!in_multiline_comment && !in_multiline_docstring) {
            output_buffer[output_pos++] = '\n';
        }
    }

    fclose(file);

    // Null-terminate the output buffer
    output_buffer[output_pos] = '\0';

    return output_buffer;
}

