        FILE* out = fopen(output_file, "w");
        if (out) {
            fputs(cleaned_code, out);
            fclose(out);
        }

        // Free the dynamically allocated memory
        free(cleaned_code);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to check if a character is a whitespace
int is_whitespace(char c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\r';
}

// Function to remove comments and docstrings
void remove_comments_and_docstrings(const char* input_file, const char* output_file) {
    FILE *in_file = fopen(input_file, "r");
    FILE *out_file = fopen(output_file, "w");
    char line[1024];
    int in_docstring = 0;

    if (in_file == NULL || out_file == NULL) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    while (fgets(line, sizeof(line), in_file)) {
        char *p = line;
        char *q = line;

        // Skip leading whitespace
        while (is_whitespace(*p)) {
            p++;
        }

        // Check if the line is a docstring
        if (strncmp(p, "\"\"\"", 3) == 0 || strncmp(p, "'''", 3) == 0) {
            in_docstring = !in_docstring;
            continue;
        }

        // If inside a docstring, skip the line
        if (in_docstring) {
            continue;
        }

        // Remove comments from the line
        while (*p) {
            if (*p == '#') {
                break; // Skip the rest of the line after the comment
            }
            *q++ = *p++;
        }
        *q = '\0'; // Null-terminate the modified line

        // Write the modified line to the output file
        fprintf(out_file, "%s", line);
    }

    fclose(in_file);
    fclose(out_file);
}

int main() {
    const char* input_file = "input.py";
    const char* output_file = "output.py";
    remove_comments_and_docstrings(input_file, output_file);
    printf("Comments and docstrings removed successfully.\n");
    return 0;
}

#include <stdio.h>    // For FILE operations (fopen, fgetc, fclose, perror)
#include <stdlib.h>   // For malloc, realloc, free, exit
#include <string.h>   // For strlen, strncmp
#include <stdbool.h>  // For bool type
#include <ctype.h>    // For isspace

#define INITIAL_BUFFER_SIZE 4096
#define LINE_BUFFER_SIZE 2048 // Max individual line length for fgets, practical limit

// Helper function to append a character to a dynamically growing buffer
static void append_char(char** buffer, size_t* current_size, size_t* current_len, char c) {
    // Check if buffer needs to be resized
    if (*current_len + 1 >= *current_size) {
        *current_size *= 2; // Double the buffer size
        char* new_buffer = (char*)realloc(*buffer, *current_size);
        if (!new_buffer) {
            perror("Memory re-allocation failed");
            free(*buffer); // Free the old buffer before exiting
            exit(EXIT_FAILURE); // Exit on critical memory error
        }
        *buffer = new_buffer;
    }
    // Append the character
    (*buffer)[(*current_len)++] = c;
    // Null termination will be done once at the very end of the main function (for efficiency)
}

/**
 * @brief Reads a Python code file and returns a new string with all comments
 *        and docstrings removed.
 *
 * This function implements a state machine to correctly identify and skip
 * comments and docstrings while preserving string literals.
 *
 * @param file_path The path to the Python code file.
 * @return A dynamically allocated string containing the cleaned Python code.
 *         Returns NULL if the file cannot be opened or memory allocation fails.
 *         The caller is responsible for freeing the returned string using `free()`.
 */
char* remove_python_comments_and_docstrings(const char* file_path) {
    FILE* fp = fopen(file_path, "r");
    if (!fp) {
        perror("Error opening file");
        return NULL;
    }

    char* output_buffer = (char*)malloc(INITIAL_BUFFER_SIZE);
    if (!output_buffer) {
        perror("Memory allocation failed");
        fclose(fp);
        return NULL;
    }
    size_t output_buffer_size = INITIAL_BUFFER_SIZE;
    size_t output_buffer_len = 0;
    output_buffer[0] = '\0'; // Initialize with null terminator

    char line_buffer[LINE_BUFFER_SIZE];

    // Global states (persistent across lines)
    bool in_multiline_triple_single_quote_literal = false; // True if inside '''...''' that is *not* a docstring
    bool in_multiline_triple_double_quote_literal = false; // True if inside """...""" that is *not* a docstring
    bool in_docstring_removal = false; // True if currently skipping chars because they belong to a docstring

    while (fgets(line_buffer, sizeof(line_buffer), fp) != NULL) {
        size_t line_len = strlen(line_buffer);
        size_t i = 0;

        // Per-line states (reset for each new line)
        bool in_single_quote = false;  // Inside '...' string
        bool in_double_quote = false;  // Inside "..." string
        bool escaped_char = false;     // True if previous char was '\'

        bool line_all_whitespace_so_far = true; // To detect first non-whitespace char on a line
        size_t current_line_content_start_idx = 0;

        // Find the first non-whitespace character on the line
        while (current_line_content_start_idx < line_len && isspace(line_buffer[current_line_content_start_idx])) {
            current_line_content_start_idx++;
        }

        // --- Docstring detection heuristic for new lines ---
        // If not already in an active multi-line string/docstring from a previous line:
        if (!(in_multiline_triple_single_quote_literal || in_multiline_triple_double_quote_literal || in_docstring_removal)) {
            // Check if the line starts (after leading whitespace) with a triple-quoted string
            if (current_line_content_start_idx + 2 < line_len) {
                char q1 = line_buffer[current_line_content_start_idx];
                char q2 = line_buffer[current_line_content_start_idx + 1];
                char q3 = line_buffer[current_line_content_start_idx + 2];

                if (q1 == q2 && q2 == q3 && (q1 == '\'' || q1 == '"')) {
                    // It's a triple-quoted string. Assume it's a docstring and start removal.
                    in_docstring_removal = true;
                    // Set the appropriate flag for which type of triple quote it is
                    if (q1 == '\'') in_multiline_triple_single_quote_literal = true; // Temporary use until it's 'removed'
                    else in_multiline_triple_double_quote_literal = true;
                }
            }
        }

        // --- Process the line character by character ---
        for (i = 0; i < line_len; ++i) {
            char c = line_buffer[i];

            // Update line_all_whitespace_so_far
            if (!isspace(c) && line_all_whitespace_so_far) {
                line_all_whitespace_so_far = false;
            }

            // Handle current character based on state
            if (in_single_quote) {
                // Inside a single-quoted string
                if (c == '\'' && !escaped_char) {
                    in_single_quote = false; // End of string
                }
                escaped_char = (c == '\\' && !escaped_char); // Update escape state
                append_char(&output_buffer, &output_buffer_size, &output_buffer_len, c);
            } else if (in_double_quote) {
                // Inside a double-quoted string
                if (c == '"' && !escaped_char) {
                    in_double_quote = false; // End of string
                }
                escaped_char = (c == '\\' && !escaped_char);
                append_char(&output_buffer, &output_buffer_size, &output_buffer_len, c);
            } else if (in_docstring_removal) {
                // Currently skipping characters because we are inside a docstring
                char q_type = in_multiline_triple_single_quote_literal ? '\'' : '"';

                if (c == q_type && !escaped_char) {
                    // Check for closing triple quotes
                    if (i + 2 < line_len && line_buffer[i+1] == q_type && line_buffer[i+2] == q_type) {
                        in_docstring_removal = false; // Docstring ends
                        in_multiline_triple_single_quote_literal = false; // Reset temporary flag
                        in_multiline_triple_double_quote_literal = false; // Reset temporary flag
                        i += 2; // Skip the two other quotes of the closing sequence
                        escaped_char = false; // Reset.
                        // Docstring ended. Continue processing remaining characters on this line, they are normal code.
                        continue; 
                    }
                }
                escaped_char = (c == '\\' && !escaped_char); // Update escape state. Skip docstring content.
            } else if (in_multiline_triple_single_quote_literal) {
                 // Inside a multi-line triple-single-quote string literal (not a docstring)
                 if (c == '\'' && !escaped_char) {
                    if (i + 2 < line_len && line_buffer[i+1] == '\'' && line_buffer[i+2] == '\'') {
                        in_multiline_triple_single_quote_literal = false; // Literal ends
                        append_char(&output_buffer, &output_buffer_size, &output_buffer_len, c); // Append the 3 quotes of the closing sequence
                        append_char(&output_buffer, &output_buffer_size, &output_buffer_len, '\'');
                        append_char(&output_buffer, &output_buffer_size, &output_buffer_len, '\'');
                        i += 2; // Skip the other two quotes
                        escaped_char = false; // Reset
                        continue;
                    }
                }
                escaped_char = (c == '\\' && !escaped_char);
                append_char(&output_buffer, &output_buffer_size, &output_buffer_len, c);
            } else if (in_multiline_triple_double_quote_literal) {
                 // Inside a multi-line triple-double-quote string literal (not a docstring)
                if (c == '"' && !escaped_char) {
                    if (i + 2 < line_len && line_buffer[i+1] == '"' && line_buffer[i+2] == '"') {
                        in_multiline_triple_double_quote_literal = false; // Literal ends
                        append_char(&output_buffer, &output_buffer_size, &output_buffer_len, c);
                        append_char(&output_buffer, &output_buffer_size, &output_buffer_len, '"');
                        append_char(&output_buffer, &output_buffer_size, &output_buffer_len, '"');
                        i += 2;
                        escaped_char = false;
                        continue;
                    }
                }
                escaped_char = (c == '\\' && !escaped_char);
                append_char(&output_buffer, &output_buffer_size, &output_buffer_len, c);
            } else { // S_NORMAL state (not in any string or docstring removal)
                if (c == '#') {
                    // Comment starts: skip the rest of the line, but preserve newline if present.
                    if (line_len > 0 && line_buffer[line_len - 1] == '\n') {
                        if (output_buffer_len > 0 && output_buffer[output_buffer_len - 1] != '\n') {
                            append_char(&output_buffer, &output_buffer_size, &output_buffer_len, '\n');
                        }
                    }
                    break; // Move to the next line
                } else if (c == '\'' || c == '"') {
                    // Potential start of a string literal
                    if (i + 2 < line_len && line_buffer[i+1] == c && line_buffer[i+2] == c) {
                        // It's a triple-quoted string
                        // Since we are not in `in_docstring_removal` here, this means it's considered a literal.
                        // (Because the 'beginning of line' docstring check already handled actual docstrings).
                        if (c == '\'') in_multiline_triple_single_quote_literal = true;
                        else in_multiline_triple_double_quote_literal = true;
                        append_char(&output_buffer, &output_buffer_size, &output_buffer_len, c); // Append the 3 quotes for literal
                        append_char(&output_buffer, &output_buffer_size, &output_buffer_len, c);
                        append_char(&output_buffer, &output_buffer_size, &output_buffer_len, c);
                        i += 2; // Skip the other two quotes
                    } else { // Single or double quote string
                        if (c == '\'') in_single_quote = true;
                        else in_double_quote = true;
                        append_char(&output_buffer, &output_buffer_size, &output_buffer_len, c);
                    }
                } else {
                    // Regular code character or whitespace
                    append_char(&output_buffer, &output_buffer_size, &output_buffer_len, c);
                }
                escaped_char = (c == '\\' && !escaped_char); // Reset escaped for next char unless it was the current char
            }
        } // End of line character loop
    } // End of file line loop

    fclose(fp);

    // Final null-termination of the output buffer
    if (output_buffer_len == 0) {
        // If file was empty or only contained comments/docstrings
        output_buffer[0] = '\0';
    } else {
        // Remove trailing newlines to ensure clean output without extra blank lines at EOF
        while (output_buffer_len > 0 && output_buffer[output_buffer_len - 1] == '\n') {
            output_buffer_len--;
        }
        output_buffer[output_buffer_len] = '\0';
    }

    return output_buffer;
}

