#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Returns '1' if line is all whitespace or empty
int is_line_empty(const char *line) {
    while (*line) {
        if (*line != ' ' && *line != '\t' && *line != '\n' && *line != '\r')
            return 0;
        line++;
    }
    return 1;
}

// Remove comments and docstrings from a Python source file
int remove_comments_docstrings(const char *input, const char *output) {
    FILE *fin = fopen(input, "r");
    if (!fin) return -1;

    FILE *fout = fopen(output, "w");
    if (!fout) { fclose(fin); return -2; }

    char line[4096];
    int in_triple = 0;
    char triple_quote[4] = "";  // To track which triple quote we're inside: ''', """

    while (fgets(line, sizeof(line), fin)) {
        char *p = line;
        char *outbuf = malloc(strlen(line) + 1);
        char *o = outbuf;
        int in_single = 0, in_double = 0;
        int i = 0;

        if (in_triple) {
            // Look for the end of the triple-quoted string
            char *end = strstr(p, triple_quote);
            if (end) {
                p = end + 3;
                in_triple = 0;
                strcpy(triple_quote, "");
                // Remove stuff up to and including end of triple quote
            } else {
                free(outbuf); // This line is completely inside docstring, skip
                continue;
            }
        }

        while (p[i]) {
            // Check for start of string literals
            if (!in_single && !in_double && !in_triple) {
                if (strncmp(&p[i], "'''", 3) == 0 || strncmp(&p[i], "\"\"\"", 3) == 0) {
                    in_triple = 1;
                    triple_quote[0] = p[i];
                    triple_quote[1] = p[i];
                    triple_quote[2] = p[i];
                    triple_quote[3] = 0;
                    i += 3;
                    // skip triple-quoted string
                    char *end = strstr(&p[i], triple_quote);
                    if (end) {
                        // End found in same line
                        i = end - p + 3;
                        in_triple = 0;
                        triple_quote[0] = '\0';
                        continue;
                    } else {
                        // Remainder of this line is inside docstring, skip the rest
                        break;
                    }
                } else if (p[i] == '\'') {
                    in_single = 1;
                    *(o++) = p[i++];
                } else if (p[i] == '"') {
                    in_double = 1;
                    *(o++) = p[i++];
                } else if (p[i] == '#') {
                    // Start of comment: ignore rest of line
                    break;
                } else {
                    *(o++) = p[i++];
                }
            } else if (in_single) {
                // Inside single quoted string
                if (p[i] == '\\' && p[i+1]) {
                    *(o++) = p[i++];
                    *(o++) = p[i++];
                } else if (p[i] == '\'') {
                    in_single = 0;
                    *(o++) = p[i++];
                } else {
                    *(o++) = p[i++];
                }
            } else if (in_double) {
                // Inside double quoted string
                if (p[i] == '\\' && p[i+1]) {
                    *(o++) = p[i++];
                    *(o++) = p[i++];
                } else if (p[i] == '"') {
                    in_double = 0;
                    *(o++) = p[i++];
                } else {
                    *(o++) = p[i++];
                }
            }
        }
        *o = '\0';
        // Only output if the line isn't inside a docstring and isn't empty
        if (!in_triple && !is_line_empty(outbuf))
            fputs(outbuf, fout);
        free(outbuf);
    }

    fclose(fin);
    fclose(fout);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_LINE_LENGTH 1024

void remove_comments_and_docstrings(const char *input_filename, const char *output_filename) {
    FILE *input_file = fopen(input_filename, "r");
    FILE *output_file = fopen(output_filename, "w");

    if (input_file == NULL || output_file == NULL) {
        fprintf(stderr, "Error opening file.\n");
        exit(EXIT_FAILURE);
    }

    char line[MAX_LINE_LENGTH];
    bool in_docstring = false;
    char docstring_char = '\0';  // Track whether it's """ or '''

    while (fgets(line, MAX_LINE_LENGTH, input_file)) {
        char *ptr = line;
        if (!in_docstring) { // Not currently inside a docstring
            while (*ptr != '\0') {
                if (!in_docstring && (*ptr == '"' || *ptr == '\'')) {
                    // Check for start of docstring
                    if (*(ptr + 1) == *ptr && *(ptr + 2) == *ptr) {
                        in_docstring = true;
                        docstring_char = *ptr;
                        ptr += 3; // Move past the triple quotes
                    } else {
                        break; // Regular string, not a docstring
                    }
                } else if (*ptr == '#') {
                    // Remove inline comments
                    *ptr = '\0';
                    break;
                } else {
                    ptr++;
                }
            }
            if (!in_docstring) {
                fprintf(output_file, "%s", line); // Write line if not inside a docstring
            }
        }

        // For handling multi-line docstrings
        if (in_docstring) {
            char *end_ptr;
            while ((end_ptr = strstr(ptr, (char[]){docstring_char, docstring_char, docstring_char, 0}))) {
                ptr = end_ptr + 3; // Move past the closing triple quotes
                in_docstring = false;
            }
        }
    }

    fclose(input_file);
    fclose(output_file);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_file> <output_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    remove_comments_and_docstrings(argv[1], argv[2]);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

// Function to check if a line contains a docstring
bool is_docstring(const char *line) {
    return (strstr(line, "\"\"\"") != NULL || strstr(line, "'''") != NULL);
}

// Function to remove comments and docstrings
void remove_comments_and_docstrings(const char *input_filename, const char *output_filename) {
    FILE *input_file = fopen(input_filename, "r");
    FILE *output_file = fopen(output_filename, "w");

    if (!input_file) {
        perror("Failed to open input file");
        return;
    }
    if (!output_file) {
        perror("Failed to open output file");
        fclose(input_file);
        return;
    }

    char line[1024];
    bool in_multiline_string = false;
    while (fgets(line, sizeof(line), input_file)) {
        char *comment_start = strstr(line, "#");

        // Check for multiline docstrings
        if (is_docstring(line)) {
            if (strstr(line, "\"\"\"") || strstr(line, "'''")) {
                // Handling multi-line strings
                if (in_multiline_string) {
                    in_multiline_string = false;
                } else {
                    in_multiline_string = true;
                }
                continue; // Skip the entire line
            }
        }

        // Skip line if we are inside a multiline docstring
        if (in_multiline_string) {
            continue;
        }

        // Remove inline comments
        if (comment_start) {
            *comment_start = '\0'; // Truncate the line at the start of the comment
        }

        // Remove leading/trailing whitespace
        char *trimmed_line = line;
        while (isspace(*trimmed_line)) {
            trimmed_line++;
        }

        if (*trimmed_line != '\0') {
            fprintf(output_file, "%s", trimmed_line);
        }
    }

    // Cleanup
    fclose(input_file);
    fclose(output_file);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_file.py> <output_file.py>\n", argv[0]);
        return EXIT_FAILURE;
    }

    remove_comments_and_docstrings(argv[1], argv[2]);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Structure to represent a file
typedef struct {
    char* content;
    size_t length;
} file_t;

// Read a file into memory
file_t read_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        printf("Could not open file %s\n", filename);
        exit(1);
    }

    fseek(file, 0, SEEK_END);
    size_t length = ftell(file);
    rewind(file);

    char* content = malloc(length + 1);
    if (!content) {
        printf("Memory allocation failed\n");
        exit(1);
    }

    size_t read = fread(content, 1, length, file);
    if (read != length) {
        printf("Failed to read file %s\n", filename);
        exit(1);
    }

    content[length] = '\0';
    fclose(file);

    return (file_t) { .content = content, .length = length };
}

// Free a file
void free_file(file_t* file) {
    free(file->content);
}

// Remove comments and docstrings from Python code
void remove_comments_and_docstrings(file_t* file) {
    char* content = file->content;
    size_t length = file->length;

    // State machine states
    typedef enum {
        CODE,
        COMMENT,
        DOCSTRING
    } state;

    state current_state = CODE;

    // Iterate over the characters in the code
    size_t write_index = 0;
    for (size_t i = 0; i < length; i++) {
        char c = content[i];

        // Handle the current state
        switch (current_state) {
            case CODE:
                // Check for comments
                if (c == '#' && (i == 0 || content[i - 1] != '\\')) {
                    current_state = COMMENT;
                }
                // Check for docstrings
                else if (c == '"' && (i == 0 || content[i - 1] != '\\') && (i + 2 < length && content[i + 1] == '"' && content[i + 2] == '"')) {
                    current_state = DOCSTRING;
                    i += 2; // Skip the docstring quotes
                }
                // Check for multiline comments
                else if (c == '"' && (i == 0 || content[i - 1] != '\\') && (i + 2 < length && content[i + 1] == '"' && content[i + 2] != '"')) {
                    current_state = DOCSTRING;
                }
                else if (c == '\'') {
                    // Check for single quoted strings
                    size_t j = i + 1;
                    while (j < length && content[j] != '\'') {
                        if (content[j] == '\\') {
                            j++; // Skip the escape character
                        }
                        j++;
                    }
                    if (j < length && content[j] == '\'') {
                        i = j;
                    }
                    else {
                        current_state = DOCSTRING;
                    }
                }
                // Write the character
                else {
                    content[write_index++] = c;
                }
                break;
            case COMMENT:
                // Check for the end of the line
                if (c == '\n') {
                    current_state = CODE;
                }
                break;
            case DOCSTRING:
                // Check for the end of the docstring
                if (c == '"' && (i == 0 || content[i - 1] != '\\') && (i + 2 < length && content[i + 1] == '"' && content[i + 2] == '"')) {
                    current_state = CODE;
                    i += 2; // Skip the docstring quotes
                }
                // Check for single quoted strings
                else if (c == '\'') {
                    size_t j = i + 1;
                    while (j < length && content[j] != '\'') {
                        if (content[j] == '\\') {
                            j++; // Skip the escape character
                        }
                        j++;
                    }
                    if (j < length && content[j] == '\'') {
                        i = j;
                    }
                    else {
                        current_state = DOCSTRING;
                    }
                }
                else if (c == '\n') {
                    current_state = CODE;
                }
                break;
            default:
                break;
        }
    }

    // Trim the content
    file->content[write_index] = '\0';
    file->length = write_index;

    // Write the modified content to a new file
    FILE* output_file = fopen("output.py", "w");
    if (!output_file) {
        printf("Could not open output file\n");
        exit(1);
    }

    fwrite(file->content, 1, file->length, output_file);
    fclose(output_file);
}

// Main function
int main() {
    file_t file = read_file("input.py");
    remove_comments_and_docstrings(&file);
    free_file(&file);
    return 0;
}

