#define BUFFER_SIZE 1024

// Function to check if the current position is the start of a docstring
int is_docstring_start(const char *line, int *state) {
    if (*state == 0) {
        if (line[0] == '\"' && line[1] == '\"' && line[2] == '\"') {
            *state = 1;
            return 1;
        } else if (line[0] == '\'' && line[1] == '\'' && line[2] == '\'') {
            *state = 1;
            return 1;
        }
    }
    return 0;
}

// Function to check if the current position is the end of a docstring
int is_docstring_end(const char *line, int *state) {
    if (*state == 1 && line[0] == '\"' && line[1] == '\"' && line[2] == '\"') {
        *state = 0;
        return 1;
    } else if (*state == 1 && line[0] == '\'' && line[1] == '\'' && line[2] == '\'') {
        *state = 0;
        return 1;
    }
    return 0;
}

// Function to remove comments and docstrings from a Python file
void remove_comments_and_docstrings(const char *input_file, const char *output_file) {
    FILE *in = fopen(input_file, "r");
    FILE *out = fopen(output_file, "w");

    if (in == NULL || out == NULL) {
        fprintf(stderr, "Error opening file.\n");
        exit(EXIT_FAILURE);
    }

    char buffer[BUFFER_SIZE];
    int state = 0; // 0: normal, 1: in docstring

    while (fgets(buffer, BUFFER_SIZE, in)) {
        int len = strlen(buffer);
        int write = 1;

        // Check for inline comments
        for (int i = 0; i < len - 1; i++) {
            if (state == 0 && buffer[i] == '#' && (i == 0 || !isalnum(buffer[i - 1]) && buffer[i - 1] != '_')) {
                buffer[i] = '\n';
                buffer[i + 1] = '\0';
                break;
            } else if (is_docstring_start(buffer + i, &state)) {
                i += 2;
            } else if (is_docstring_end(buffer + i, &state)) {
                i += 2;
            }
        }

        if (state == 0 && buffer[0] != '#' && buffer[0] != '\'' && buffer[0] != '\"') {
            // Not a comment or docstring, write the line
            fprintf(out, "%s", buffer);
        }
    }

    fclose(in);
    fclose(out);
}

