// Helper function to expand around center and find palindrome length
int expandAroundCenter(char* s, int left, int right) {
    int n = strlen(s);

    // Expand while characters match and within bounds
    while (left >= 0 && right < n && s[left] == s[right]) {
        left--;
        right++;
    }

    // Return length of palindrome
    return right - left - 1;
}

char* longestPalindrome(char* s) {
    if (s == NULL || strlen(s) < 1) {
        return "";
    }

    int start = 0;  // Starting index of longest palindrome
    int maxLen = 0; // Length of longest palindrome
    int n = strlen(s);

    // Try each character as potential center of palindrome
    for (int i = 0; i < n; i++) {
        // Check for odd-length palindromes
        int len1 = expandAroundCenter(s, i, i);

        // Check for even-length palindromes
        int len2 = expandAroundCenter(s, i, i+1);

        // Take the maximum length
        int currLen = (len1 > len2) ? len1 : len2;

        // Update longest palindrome if current is longer
        if (currLen > maxLen) {
            // Calculate start index 
            start = i - (currLen - 1) / 2;
            maxLen = currLen;
        }
    }

    // Allocate memory for the palindrome substring
    char* result = (char*)malloc((maxLen + 1) * sizeof(char));

    // Copy the palindromic substring
    strncpy(result, s + start, maxLen);
    result[maxLen] = '\0';  // Null terminate

    return result;
}

