// Function to find the longest palindromic substring
void longestPalindromicSubstring(char *s) {
    int n = strlen(s);
    if (n == 0) return;

    // Create a table to store results of subproblems
    bool dp[n][n];
    memset(dp, 0, sizeof(dp));

    // All substrings of length 1 are palindromes
    int maxLength = 1;
    for (int i = 0; i < n; i++) {
        dp[i][i] = true;
    }

    // Check for substrings of length 2
    int start = 0;
    for (int i = 0; i < n - 1; i++) {
        if (s[i] == s[i + 1]) {
            dp[i][i + 1] = true;
            start = i;
            maxLength = 2;
        }
    }

    // Check for substrings of length greater than 2
    for (int k = 3; k <= n; k++) {
        for (int i = 0; i < n - k + 1; i++) {
            int j = i + k - 1; // Ending index of the substring

            // Check if the characters at the ends are the same and the substring
            // between them is a palindrome
            if (s[i] == s[j] && dp[i + 1][j - 1]) {
                dp[i][j] = true;

                // Update the maximum length and starting index
                if (k > maxLength) {
                    start = i;
                    maxLength = k;
                }
            }
        }
    }

    // Print the longest palindromic substring
    printf("Longest Palindromic Substring: ");
    for (int i = start; i < start + maxLength; i++) {
        printf("%c", s[i]);
    }
    printf("\n");
}

