// Helper function to check if a substring is a palindrome
// Takes the string, a starting index, and an ending index
static int isPalindrome(const char* s, int start, int end) {
    if (s == NULL || start < 0 || end < 0 || start > end) {
        return 0; // Invalid input
    }
    while (start < end) {
        if (s[start] != s[end]) {
            return 0; // Not a palindrome
        }
        start++;
        end--;
    }
    return 1; // It's a palindrome
}

// Function to find the longest palindromic substring
// Returns a dynamically allocated string, which the caller must free.
char* longestPalindromicSubstring(const char* s) {
    if (s == NULL || *s == '\0') {
        // Return an empty string for null or empty input
        char* empty_str = (char*)malloc(1);
        if (empty_str == NULL) {
            perror("Failed to allocate memory for empty string");
            return NULL;
        }
        empty_str[0] = '\0';
        return empty_str;
    }

    int n = strlen(s);
    if (n == 1) {
        // A single character is always a palindrome
        char* single_char_str = (char*)malloc(2);
        if (single_char_str == NULL) {
            perror("Failed to allocate memory for single char string");
            return NULL;
        }
        single_char_str[0] = s[0];
        single_char_str[1] = '\0';
        return single_char_str;
    }

    int maxLength = 1; // Minimum length is 1 (any single character)
    int start = 0;     // Starting index of the longest palindrome found so far

    // Naive approach: Check all possible substrings
    // This has a time complexity of O(n^3) (O(n^2) for substrings, O(n) for isPalindrome)
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            if (isPalindrome(s, i, j)) {
                if (j - i + 1 > maxLength) {
                    maxLength = j - i + 1;
                    start = i;
                }
            }
        }
    }

    // Allocate memory for the longest palindromic substring
    char* result = (char*)malloc(maxLength + 1); // +1 for null terminator
    if (result == NULL) {
        perror("Failed to allocate memory for result string");
        return NULL;
    }

    // Copy the longest palindrome into the result buffer
    strncpy(result, s + start, maxLength);
    result[maxLength] = '\0'; // Null-terminate the string

    return result;
}

