// Structure to store the start and end index of the longest palindromic substring
typedef struct {
    int start;
    int end;
} Palindrome;

// Function to expand around the center to find the longest palindromic substring
Palindrome expandAroundCenter(char *str, int left, int right) {
    Palindrome palindrome;
    palindrome.start = left;
    palindrome.end = right;

    // Expand around the center until the characters are not equal
    while (left >= 0 && right < strlen(str) && str[left] == str[right]) {
        left--;
        right++;
    }

    // Adjust the start and end indices to include the last matching characters
    palindrome.start = left + 1;
    palindrome.end = right - 1;

    return palindrome;
}

// Function to find the longest palindromic substring
char *longestPalindromicSubstring(char *str) {
    Palindrome longest;
    longest.start = 0;
    longest.end = 0;

    // Iterate over the string to consider each character as a potential center of a palindrome
    for (int i = 0; i < strlen(str); i++) {
        // Consider odd-length palindromes
        Palindrome oddPalindrome = expandAroundCenter(str, i, i);
        if (oddPalindrome.end - oddPalindrome.start > longest.end - longest.start) {
            longest = oddPalindrome;
        }

        // Consider even-length palindromes
        if (i < strlen(str) - 1 && str[i] == str[i + 1]) {
            Palindrome evenPalindrome = expandAroundCenter(str, i, i + 1);
            if (evenPalindrome.end - evenPalindrome.start > longest.end - longest.start) {
                longest = evenPalindrome;
            }
        }
    }

    // Create a new string to store the longest palindromic substring
    char *result = (char *)malloc((longest.end - longest.start + 2) * sizeof(char));
    strncpy(result, str + longest.start, longest.end - longest.start + 1);
    result[longest.end - longest.start + 1] = '\0';

    return result;
}

