#include <stdio.h>
#include <stdlib.h>

// Extended Euclidean Algorithm to find modular inverse
int modular_inverse(int a, int m) {
    // Handles edge cases
    if (m <= 0) {
        fprintf(stderr, "Modulus must be positive\n");
        return -1;
    }

    // Ensure a is positive
    a = a % m;
    if (a < 0) {
        a += m;
    }

    // Variables for Extended Euclidean Algorithm
    int original_m = m;
    int x0 = 0, x1 = 1;
    int q, temp;

    // If a and m are not coprime, modular inverse doesn't exist
    while (a > 1) {
        // Divide m by a
        q = m / a;

        // Update m and a
        temp = m;
        m = a;
        a = temp % a;

        // Update x coefficients
        temp = x0;
        x0 = x1 - q * x0;
        x1 = temp;
    }

    // If a is 1, inverse exists
    if (a == 1) {
        // Make sure x1 is positive
        if (x1 < 0) {
            x1 += original_m;
        }
        return x1;
    }

    // No modular inverse exists
    return -1;
}

// Optional: Helper function to verify the result
int verify_modular_inverse(int a, int m, int inverse) {
    if (inverse == -1) {
        return 0;  // No inverse
    }

    // Check if (a * inverse) % m == 1
    long long result = ((long long)a * inverse) % m;
    return (result == 1);
}

