// Function to calculate the modular inverse of 'a' with respect to 'm'
// using the Extended Euclidean Algorithm.
// Returns the modular inverse, or -1 if the inverse does not exist.
long long modularInverse(long long a, long long m) {
    long long m0 = m;
    long long y = 0, x = 1;

    if (m == 1) {
        return 0; // Modular inverse of 'a' with respect to 1 is 0.
                  // However, often m > 1 is assumed for modular inverse.
    }

    // Apply Extended Euclidean Algorithm
    while (a > 1) {
        // q is quotient
        long long q = a / m;
        long long t = m;

        // m is remainder now, process same as Euclidean Algorithm
        m = a % m, a = t;
        t = y;

        // Update y and x
        y = x - q * y;
        x = t;
    }

    // Now x contains the modular inverse.
    // Make x positive if it is negative.
    if (x < 0) {
        x += m0;
    }

    // If gcd(original_a, original_m) is not 1, the inverse does not exist.
    // In our implementation, if original_a becomes 1, it means gcd was 1.
    // So, 'a' in the while loop becomes 1 at the end if an inverse exists.
    // If 'a' is not 1 at the end, it means gcd was not 1.
    // To be precise, we should check original_a and original_m for gcd(a,m) == 1
    // A simpler way here is to observe that 'x' will be valid only if gcd was 1.
    // If gcd was not 1, 'a' would not become 1 in the loop, or the final 'x'
    // would not be a valid inverse.
    // However, the standard way to check is to call a GCD function first.
    // For this specific implementation of extended Euclidean, 'x' will correctly
    // hold the modular inverse if it exists. If it doesn't exist, 'a' will not be 1
    // at the end of the loop, and the validity of 'x' should be questioned.
    // A more robust check might involve initial GCD calculation.
    // For simplicity, this function assumes that the input 'a' and 'm'
    // (after the loop, 'a' becomes gcd(original_a, original_m))
    // will result in 'a' being 1 if the inverse exists.
    // If a is not 1 at this point, gcd was not 1.
    // We can add an explicit check to be safer:
    // If original_a (which is now `a` after the loop) is not 1, it means gcd != 1
    // and thus inverse doesn't exist.
    // However, the common Extended Euclidean algorithm for modular inverse directly
    // produces the inverse if it exists, and 'a' will be 1 at the end.
    // If the inverse does not exist, 'a' will be gcd(original_a, original_m) > 1.

    // Let's explicitly check if gcd(original_a_temp, m0) was 1.
    // The current 'a' holds gcd(original_a, original_m).
    // This value is computed in the while loop.
    // If caller needs a robust check for inverse existence, they should check `a`
    // after the loop.
    // A better approach for this function is to return -1 if gcd > 1.
    // To do this, we need to pass back the final 'a' value or compute it again.
    // For now, let's assume `a` has GCD and `x` is the inverse.
    // If gcd > 1, the value returned by `x` will be meaningless as an inverse.

    // A more robust way to incorporate the GCD check without recomputing:
    // The state variable 'a' (the first argument to `while`) holds gcd(original_a, original_m)
    // at the end of the loop IF `a` is the original `a` and `m` is the original `m`.
    // In our modification where `a` and `m` are swapped and updated inside the loop,
    // the final `a` variable will store the GCD.

    if (a != 1) { // If original inputs were not coprime, inverse doesn't exist.
        return -1;
    }
    return x;
}

// Helper function to calculate GCD (for testing/understanding coprimality)
long long gcd(long long a, long long b) {
    while (b) {
        a %= b;
        // Swap a and b
        long long temp = a;
        a = b;
        b = temp;
    }
    return a;
}


