    // Initial check for 'm'
    if (m <= 0) {
        printf("Error: Modulus (m) must be a positive integer.\n");
        return 1;
    }

    // Ensure 'a' is in the range [0, m-1)
    a = a % m;
    if (a < 0) { // Handle negative 'a'
        a += m;
    }

    // Check if inverse exists
    long long common_divisor = gcd(a, m);
    if (common_divisor != 1) {
        printf("Modular inverse does not exist because %lld and %lld are not coprime (GCD is %lld).\n", a, m, common_divisor);
        return 0;
    }

    long long inv = modularInverse(a, m);

    if (inv == -1) {
        printf("Modular inverse of %lld with respect to %lld does not exist.\n", a, m);
    } else {
        printf("Modular inverse of %lld with respect to %lld is: %lld\n", a, m, inv);
        // Verify: (a * inv) % m should be 1
        printf("Verification: (%lld * %lld) %% %lld = %lld\n", a, inv, m, (a * inv) % m);
    }

    return 0;
}

