// Structure to hold the results of the Extended Euclidean Algorithm
typedef struct {
    int gcd;
    int x;
    int y;
} EEA_Result;

// Function to calculate the Extended Euclidean Algorithm
EEA_Result extended_euclidean(int a, int b) {
    // Base case: if b is 0, return the GCD and coefficients
    if (b == 0) {
        EEA_Result result = {a, 1, 0};
        return result;
    }

    // Recursive case: calculate the GCD and coefficients
    EEA_Result result = extended_euclidean(b, a % b);
    int x = result.y;
    int y = result.x - (a / b) * result.y;

    // Update the result
    result.x = x;
    result.y = y;

    return result;
}

