int* add_number_lists(int* list1, int list1_size, int* list2, int list2_size, int* result_size) {
    // Determine the maximum length of the lists
    int max_len = (list1_size > list2_size) ? list1_size : list2_size;

    // Allocate memory for the result list (might need one extra digit for carry)
    int* result = malloc((max_len + 1) * sizeof(int));
    *result_size = max_len + 1;

    // Initialize result list with zeros
    for (int i = 0; i < max_len + 1; i++) {
        result[i] = 0;
    }

    // Perform addition from right to left
    int carry = 0;
    int result_index = max_len;

    while (list1_size > 0 || list2_size > 0 || carry) {
        // Get current digits (or 0 if list is exhausted)
        int digit1 = (list1_size > 0) ? list1[list1_size - 1] : 0;
        int digit2 = (list2_size > 0) ? list2[list2_size - 1] : 0;

        // Add current digits and carry
        int sum = digit1 + digit2 + carry;

        // Update carry and current digit
        carry = sum / 10;
        result[result_index] = sum % 10;

        // Move to next digits
        if (list1_size > 0) list1_size--;
        if (list2_size > 0) list2_size--;
        result_index--;
    }

    // If the most significant digit is 0, shift the array
    if (result[0] == 0) {
        for (int i = 0; i < max_len; i++) {
            result[i] = result[i + 1];
        }
        *result_size = max_len;
    }

    return result;
}

// Helper function to print the result
void print_list(int* list, int size) {
    for (int i = 0; i < size; i++) {
        printf("%d", list[i]);
    }
    printf("\n");
}

int main() {
    // Example usage
    int list1[] = {1, 2, 3};  // represents 123
    int list2[] = {4, 5, 6};  // represents 456

    int result_size;
    int* result = add_number_lists(list1, 3, list2, 3, &result_size);

    printf("List 1: ");
    print_list(list1, 3);

    printf("List 2: ");
    print_list(list2, 3);

    printf("Result: ");
    print_list(result, result_size);

    // Free dynamically allocated memory
    free(result);

    return 0;
}

