int list_sum(int* list1, int len1, int* list2, int len2) {
    // Calculate the maximum length
    int max_len = (len1 > len2) ? len1 : len2;

    // Initialize result and carry variables
    int* result = (int*) malloc((max_len + 1) * sizeof(int));
    int carry = 0;

    // Iterate over the lists from last digit to first
    for (int i = 0; i < max_len; i++) {
        // Get the current digits from both lists (or 0 if out of bounds)
        int digit1 = (i < len1) ? list1[len1 - i - 1] : 0;
        int digit2 = (i < len2) ? list2[len2 - i - 1] : 0;

        // Calculate the sum of the current digits and the carry
        int sum = digit1 + digit2 + carry;

        // Update the result and carry
        result[max_len - i] = sum % 10;
        carry = sum / 10;
    }

    // If there's still a carry after the loop, add it to the beginning of the result
    if (carry > 0) {
        result[0] = carry;
    } else {
        // If no carry, the result is one digit shorter
        for (int i = 0; i < max_len; i++) {
            result[i] = result[i + 1];
        }
        max_len--;
    }

    // Print the result
    printf("Result: ");
    for (int i = 0; i <= max_len; i++) {
        printf("%d", result[i]);
    }
    printf("\n");

    free(result);
}

int main() {
    int list1[] = {1, 2, 3};
    int len1 = sizeof(list1) / sizeof(list1[0]);
    int list2[] = {4, 5, 6};
    int len2 = sizeof(list2) / sizeof(list2[0]);

    list_sum(list1, len1, list2, len2);

    return 0;
}

