// Function to convert a list of digits to an integer
int listToInt(int *list, int size) {
    int num = 0;
    for (int i = 0; i < size; i++) {
        num = num * 10 + list[i];
    }
    return num;
}

// Function to add two lists representing numbers
int addLists(int *list1, int size1, int *list2, int size2) {
    // Convert both lists to integers
    int num1 = listToInt(list1, size1);
    int num2 = listToInt(list2, size2);

