#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>
#include <math.h>

#define MAX_EXPR_LENGTH 100
#define MAX_STACK_SIZE 100

// Operator stack for converting infix to postfix
typedef struct {
    char operators[MAX_STACK_SIZE];
    int top;
} OperatorStack;

// Numeric value stack for evaluation
typedef struct {
    double values[MAX_STACK_SIZE];
    int top;
} ValueStack;

// Operator stack functions
void op_push(OperatorStack *stack, char op) {
    stack->operators[++stack->top] = op;
}

char op_pop(OperatorStack *stack) {
    return stack->operators[stack->top--];
}

char op_top(OperatorStack *stack) {
    return stack->operators[stack->top];
}

int op_empty(OperatorStack *stack) {
    return stack->top == -1;
}

// Value stack functions
void val_push(ValueStack *stack, double value) {
    stack->values[++stack->top] = value;
}

double val_pop(ValueStack *stack) {
    return stack->values[stack->top--];
}

int val_empty(ValueStack *stack) {
    return stack->top == -1;
}

// Check operator precedence
int precedence(char op) {
    switch(op) {
        case '+':
        case '-':
            return 1;
        case '*':
        case '/':
            return 2;
        case '^':
            return 3;
        default:
            return 0;
    }
}

// Perform arithmetic operation
double perform_operation(char op, double b, double a) {
    switch(op) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/': 
            if (b == 0) {
                printf("Error: Division by zero\n");
                exit(1);
            }
            return a / b;
        case '^': return pow(a, b);
        default: return 0;
    }
}

// Convert infix expression to postfix
void infix_to_postfix(char *infix, char *postfix) {
    OperatorStack op_stack = {.top = -1};
    int i, j = 0;

    for (i = 0; infix[i]; i++) {
        char ch = infix[i];

        // Skip whitespace
        if (isspace(ch)) continue;

        // Number or decimal point
        if (isdigit(ch) || ch == '.') {
            postfix[j++] = ch;
        }
        // Operator
        else if (strchr("+-*/^", ch)) {
            postfix[j++] = ' ';  // Separate numbers
            while (!op_empty(&op_stack) && 
                   precedence(op_top(&op_stack)) >= precedence(ch)) {
                postfix[j++] = op_pop(&op_stack);
                postfix[j++] = ' ';
            }
            op_push(&op_stack, ch);
        }
        // Open parenthesis
        else if (ch == '(') {
            op_push(&op_stack, ch);
        }
        // Close parenthesis
        else if (ch == ')') {
            while (!op_empty(&op_stack) && op_top(&op_stack) != '(') {
                postfix[j++] = ' ';
                postfix[j++] = op_pop(&op_stack);
            }
            if (!op_empty(&op_stack) && op_top(&op_stack) == '(') {
                op_pop(&op_stack);
            } else {
                printf("Error: Mismatched parentheses\n");
                exit(1);
            }
        }
    }

    // Pop remaining operators
    while (!op_empty(&op_stack)) {
        postfix[j++] = ' ';
        postfix[j++] = op_pop(&op_stack);
    }

    postfix[j] = '\0';
}

// Evaluate postfix expression
double evaluate_postfix(char *postfix) {
    ValueStack val_stack = {.top = -1};
    char *token;

    token = strtok(postfix, " ");
    while (token) {
        // Number
        if (isdigit(token[0]) || token[0] == '.') {
            val_push(&val_stack, atof(token));
        }
        // Operator
        else if (strchr("+-*/^", token[0])) {
            double b = val_pop(&val_stack);
            double a = val_pop(&val_stack);
            double result = perform_operation(token[0], b, a);
            val_push(&val_stack, result);
        }

        token = strtok(NULL, " ");
    }

    return val_pop(&val_stack);
}

// Main calculator function
double calculate(char *expression) {
    char postfix[MAX_EXPR_LENGTH];

    // Convert infix to postfix
    infix_to_postfix(expression, postfix);

    // Evaluate postfix expression
    return evaluate_postfix(postfix);
}

int main() {
    char expression[MAX_EXPR_LENGTH];

    while (1) {
        printf("Calculator> ");

        // Read input expression
        if (fgets(expression, sizeof(expression), stdin) == NULL) {
            break;
        }

        // Remove newline
        expression[strcspn(expression, "\n")] = 0;

        // Exit condition
        if (strcmp(expression, "exit") == 0) {
            break;
        }

        // Calculate and print result
        double result = calculate(expression);
        printf("Result: %g\n", result);
    }

    return 0;
}

