// Function prototypes
double expression(char **str);
double term(char **str);
double factor(char **str);
double number(char **str);

// Evaluate an expression
double expression(char **str) {
    double result = term(str);
    while (**str == '+' || **str == '-') {
        if (**str == '+') {
            (*str)++;
            result += term(str);
        } else if (**str == '-') {
            (*str)++;
            result -= term(str);
        }
    }
    return result;
}

// Evaluate a term (multiplication and division)
double term(char **str) {
    double result = factor(str);
    while (**str == '*' || **str == '/') {
        if (**str == '*') {
            (*str)++;
            result *= factor(str);
        } else if (**str == '/') {
            (*str)++;
            double divisor = factor(str);
            if (divisor == 0) {
                printf("Error: Division by zero\n");
                exit(EXIT_FAILURE);
            }
            result /= divisor;
        }
    }
    return result;
}

// Evaluate a factor (number or parenthesized expression)
double factor(char **str) {
    if (**str == '(') {
        (*str)++;
        double result = expression(str);
        if (**str != ')') {
            printf("Error: Missing closing parenthesis\n");
            exit(EXIT_FAILURE);
        }
        (*str)++;
        return result;
    } else if (isdigit(**str) || **str == '.') {
        return number(str);
    } else {
        printf("Error: Invalid character in expression\n");
        exit(EXIT_FAILURE);
    }
}

// Parse a number
double number(char **str) {
    char *end;
    double result = strtod(*str, &end);
    *str = end;
    return result;
}

