// --- Simple Stack Implementation for RPN Evaluation ---
#define MAX_STACK_SIZE 100
double stack[MAX_STACK_SIZE];
int top = -1;

void push(double value) {
    if (top >= MAX_STACK_SIZE - 1) {
        fprintf(stderr, "Stack overflow!\n");
        exit(EXIT_FAILURE);
    }
    stack[++top] = value;
}

double pop() {
    if (top < 0) {
        fprintf(stderr, "Stack underflow!\n");
        exit(EXIT_FAILURE);
    }
    return stack[top--];
}

// --- Operator Precedence Helper ---
int get_precedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0; // For other characters
}

// --- Function to perform arithmetic operation ---
double apply_operator(double a, double b, char op) {
    switch (op) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/':
            if (b == 0) {
                fprintf(stderr, "Division by zero!\n");
                exit(EXIT_FAILURE);
            }
            return a / b;
        default:
            fprintf(stderr, "Unknown operator: %c\n", op);
            exit(EXIT_FAILURE);
    }
}

// --- The core calculator function (simplistic approach for precedence) ---
// This function aims for basic precedence for operators (+,-,*,/) but
// does NOT fully implement the Shunting-Yard for arbitrary nested parentheses.
// For robust parentheses support, a full Shunting-Yard algorithm (converting to RPN)
// is necessary, which would make this single function much longer.
// This function assumes a well-formed expression without complex nested parentheses
// beyond what can be handled by a single pass with two stacks (one for numbers, one for ops).
double calculate_expression(const char *expression) {
    // We'll use two stacks: one for numbers, one for operators
    double num_stack[MAX_STACK_SIZE];
    char op_stack[MAX_STACK_SIZE];
    int num_top = -1;
    int op_top = -1;

    int i = 0;
    while (i < strlen(expression)) {
        if (isspace(expression[i])) {
            i++;
            continue;
        }

        if (isdigit(expression[i]) || (expression[i] == '-' && (i == 0 || !isdigit(expression[i-1]) && expression[i-1] != ')'))) {
            // Handle negative numbers or numbers at the start
            char *endptr;
            double num = strtod(&expression[i], &endptr);

            if (num_top >= MAX_STACK_SIZE - 1) { fprintf(stderr, "Number stack overflow!\n"); exit(EXIT_FAILURE); }
            num_stack[++num_top] = num;
            i += (int)(endptr - &expression[i]); // Move 'i' past the number
        } else if (expression[i] == '(') {
            if (op_top >= MAX_STACK_SIZE - 1) { fprintf(stderr, "Operator stack overflow!\n"); exit(EXIT_FAILURE); }
            op_stack[++op_top] = '(';
            i++;
        } else if (expression[i] == ')') {
            while (op_top >= 0 && op_stack[op_top] != '(') {
                if (num_top < 1) { fprintf(stderr, "Syntax Error: Not enough operands for operator.\n"); exit(EXIT_FAILURE); }
                double b = num_stack[num_top--];
                double a = num_stack[num_top--];
                num_stack[++num_top] = apply_operator(a, b, op_stack[op_top--]);
            }
            if (op_top < 0 || op_stack[op_top] != '(') {
                fprintf(stderr, "Syntax Error: Mismatched parentheses.\n");
                exit(EXIT_FAILURE);
            }
            op_top--; // Pop '('
            i++;
        } else if (expression[i] == '+' || expression[i] == '-' ||
                   expression[i] == '*' || expression[i] == '/') {
            char current_op = expression[i];
            while (op_top >= 0 && op_stack[op_top] != '(' &&
                   get_precedence(op_stack[op_top]) >= get_precedence(current_op)) {
                if (num_top < 1) { fprintf(stderr, "Syntax Error: Not enough operands for operator.\n"); exit(EXIT_FAILURE); }
                double b = num_stack[num_top--];
                double a = num_stack[num_top--];
                num_stack[++num_top] = apply_operator(a, b, op_stack[op_top--]);
            }
            if (op_top >= MAX_STACK_SIZE - 1) { fprintf(stderr, "Operator stack overflow!\n"); exit(EXIT_FAILURE); }
            op_stack[++op_top] = current_op;
            i++;
        } else {
            fprintf(stderr, "Invalid character in expression: %c\n", expression[i]);
            exit(EXIT_FAILURE);
        }
    }

    // Pop remaining operators from op_stack and apply them to num_stack
    while (op_top >= 0) {
        if (op_stack[op_top] == '(') {
            fprintf(stderr, "Syntax Error: Mismatched parentheses.\n");
            exit(EXIT_FAILURE);
        }
        if (num_top < 1) { fprintf(stderr, "Syntax Error: Not enough operands at end of expression.\n"); exit(EXIT_FAILURE); }
        double b = num_stack[num_top--];
        double a = num_stack[num_top--];
        num_stack[++num_top] = apply_operator(a, b, op_stack[op_top--]);
    }

    if (num_top != 0) {
        fprintf(stderr, "Syntax Error: Malformed expression or extra numbers/operators.\n");
        exit(EXIT_FAILURE);
    }

    return num_stack[num_top];
}

