#include <stdio.h>
#include <ctype.h>
#include <stdlib.h>

// Forward declarations
double expr(const char **s);

void skip_spaces(const char **s) {
    while (isspace(**s)) ++(*s);
}

// Parses numbers and parenthesis
double factor(const char **s) {
    skip_spaces(s);
    double result = 0.0;
    if (**s == '(') {
        ++(*s); // consume '('
        result = expr(s);
        skip_spaces(s);
        if (**s == ')') ++(*s); // consume ')'
        else {
            fprintf(stderr, "Error: Mismatched parentheses\n");
            exit(1);
        }
    } else if (isdigit(**s) || **s == '.') {
        char *endptr;
        result = strtod(*s, &endptr);
        *s = endptr;
    } else if (**s == '-' || **s == '+') { // unary +/- support
        char op = **s;
        ++(*s);
        result = factor(s);
        if (op == '-')
            result = -result;
    } else {
        fprintf(stderr, "Error: Unexpected character '%c'\n", **s);
        exit(1);
    }
    return result;
}

// Parses '*' and '/'
double term(const char **s) {
    double result = factor(s);
    skip_spaces(s);

    while (**s == '*' || **s == '/') {
        char op = **s;
        ++(*s);
        double rhs = factor(s);
        if (op == '*') result *= rhs;
        else {
            if (rhs == 0) {
                fprintf(stderr, "Error: Division by zero\n");
                exit(1);
            }
            result /= rhs;
        }
        skip_spaces(s);
    }
    return result;
}

// Parses '+' and '-'
double expr(const char **s) {
    double result = term(s);
    skip_spaces(s);

    while (**s == '+' || **s == '-') {
        char op = **s;
        ++(*s);
        double rhs = term(s);
        if (op == '+') result += rhs;
        else result -= rhs;
        skip_spaces(s);
    }
    return result;
}

// Top-level function
double eval(const char *s) {
    double result = expr(&s);
    skip_spaces(&s);
    if (*s != '\0') {
        fprintf(stderr, "Error: Unexpected data at: '%s'\n", s);
        exit(1);
    }
    return result;
}

