    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

typedef struct {
    const char *expr;
    size_t pos;
} Parser;

int parse_expr(Parser *parser);
int parse_term(Parser *parser);
int parse_factor(Parser *parser);
int parse_number(Parser *parser);

void skip_whitespace(Parser *parser) {
    while (isspace(parser->expr[parser->pos])) {
        parser->pos++;
    }
}

int parse_expr(Parser *parser) {
    int value = parse_term(parser);
    while (1) {
        skip_whitespace(parser);
        char op = parser->expr[parser->pos];
        if (op == '+' || op == '-') {
            parser->pos++;
            int next_value = parse_term(parser);
            if (op == '+') {
                value += next_value;
            } else {
                value -= next_value;
            }
        } else {
            break;
        }
    }
    return value;
}

int parse_term(Parser *parser) {
    int value = parse_factor(parser);
    while (1) {
        skip_whitespace(parser);
        char op = parser->expr[parser->pos];
        if (op == '*' || op == '/') {
            parser->pos++;
            int next_value = parse_factor(parser);
            if (op == '*') {
                value *= next_value;
            } else if (op == '/') {
                if (next_value == 0) {
                    fprintf(stderr, "Error: Division by zero\n");
                    exit(EXIT_FAILURE);
                }
                value /= next_value;
            }
        } else {
            break;
        }
    }
    return value;
}

int parse_factor(Parser *parser) {
    skip_whitespace(parser);
    if (parser->expr[parser->pos] == '(') {
        parser->pos++;  // consume '('
        int value = parse_expr(parser);
        skip_whitespace(parser);
        if (parser->expr[parser->pos] == ')') {
            parser->pos++;  // consume ')'
            return value;
        } else {
            fprintf(stderr, "Error: Mismatched parentheses\n");
            exit(EXIT_FAILURE);
        }
    } else {
        return parse_number(parser);
    }
}

int parse_number(Parser *parser) {
    skip_whitespace(parser);
    int start = parser->pos;
    while (isdigit(parser->expr[parser->pos])) {
        parser->pos++;
    }
    if (start == parser->pos) {
        fprintf(stderr, "Error: Expected number\n");
        exit(EXIT_FAILURE);
    }
    return strtol(&parser->expr[start], NULL, 10);
}

int calculate(const char *expression) {
    Parser parser = {expression, 0};
    int result = parse_expr(&parser);
    skip_whitespace(&parser);
    if (parser.expr[parser.pos] != '\0') {
        fprintf(stderr, "Error: Unexpected character '%c'\n", parser.expr[parser.pos]);
        exit(EXIT_FAILURE);
    }
    return result;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s \"expression\"\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *expression = argv[1];
    int result = calculate(expression);
    printf("Result: %d\n", result);

    return EXIT_SUCCESS;
}

#include <stdio.h>
