typedef enum { NUMBER, ADD, SUBTRACT, MULTIPLY, DIVIDE, LPAREN, RPAREN } TokenType;

typedef struct {
    TokenType type;
    double value; // Only for NUMBER
} Token;

typedef struct Node {
    TokenType type;
    double value; // Only for NUMBER
    struct Node *left, *right; // For expressions
} Node;

typedef struct {
    Token *tokens;
    size_t currentToken;
    size_t length;
} Parser;

// Function declarations
double evaluate(Node *node);
Node *parse_expression(Parser *parser);
Node *parse_term(Parser *parser);
Node *parse_factor(Parser *parser);
void free_tree(Node *node);
void tokenize(char *input, Token **tokens, size_t *length);
Token *get_next_token(char **input);
int precedence(TokenType type);

// Main Function
int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s \"expression\"\n", argv[0]);
        return 1;
    }

    Token *tokens = NULL;
    size_t length = 0;
    tokenize(argv[1], &tokens, &length);

    Parser parser = { tokens, 0, length };
    Node *root = parse_expression(&parser);
    double result = evaluate(root);
    printf("Result: %f\n", result);

    // Clean up
    free_tree(root);
    free(tokens);
    return 0;
}

// Tokenize function
void tokenize(char *input, Token **tokens, size_t *length) {
    size_t size = 10;
    *tokens = malloc(size * sizeof(Token));

    while (*input) {
        while (isspace(*input)) input++;
        if (isdigit(*input) || (*input == '.' && isdigit(*(input + 1)))) {
            double value = strtod(input, &input);
            if (*length >= size) {
                size *= 2;
                *tokens = realloc(*tokens, size * sizeof(Token));
            }
            (*tokens)[(*length)++] = (Token){ NUMBER, value };
        } else if (*input == '+') {
            (*tokens)[(*length)++] = (Token){ ADD, 0 };
            input++;
        } else if (*input == '-') {
            (*tokens)[(*length)++] = (Token){ SUBTRACT, 0 };
            input++;
        } else if (*input == '*') {
            (*tokens)[(*length)++] = (Token){ MULTIPLY, 0 };
            input++;
        } else if (*input == '/') {
            (*tokens)[(*length)++] = (Token){ DIVIDE, 0 };
            input++;
        } else if (*input == '(') {
            (*tokens)[(*length)++] = (Token){ LPAREN, 0 };
            input++;
        } else if (*input == ')') {
            (*tokens)[(*length)++] = (Token){ RPAREN, 0 };
            input++;
        } else {
            fprintf(stderr, "Unknown character: %c\n", *input);
            exit(1);
        }
    }
}

// Parser functions
Node *parse_expression(Parser *parser) {
    Node *node = parse_term(parser);
    while (parser->currentToken < parser->length) {
        Token *token = &parser->tokens[parser->currentToken];
        if (token->type == ADD || token->type == SUBTRACT) {
            parser->currentToken++;
            Node *newNode = malloc(sizeof(Node));
            newNode->type = token->type;
            newNode->left = node;
            newNode->right = parse_term(parser);
            node = newNode;
        } else {
            break;
        }
    }
    return node;
}

Node *parse_term(Parser *parser) {
    Node *node = parse_factor(parser);
    while (parser->currentToken < parser->length) {
        Token *token = &parser->tokens[parser->currentToken];
        if (token->type == MULTIPLY || token->type == DIVIDE) {
            parser->currentToken++;
            Node *newNode = malloc(sizeof(Node));
            newNode->type = token->type;
            newNode->left = node;
            newNode->right = parse_factor(parser);
            node = newNode;
        } else {
            break;
        }
    }
    return node;
}

Node *parse_factor(Parser *parser) {
    Token *token = &parser->tokens[parser->currentToken];
    parser->currentToken++;

    if (token->type == NUMBER) {
        Node *node = malloc(sizeof(Node));
        node->type = NUMBER;
        node->value = token->value;
        node->left = node->right = NULL;
        return node;
    } else if (token->type == LPAREN) {
        Node *node = parse_expression(parser);
        if (parser->tokens[parser->currentToken++].type != RPAREN) {
            fprintf(stderr, "Syntax error: unmatched parentheses\n");
            exit(1);
        }
        return node;
    }

    fprintf(stderr, "Syntax error: unexpected token\n");
    exit(1);
}

// Evaluate functions
double evaluate(Node *node) {
    if (!node) return 0.0;
    switch (node->type) {
        case NUMBER:
            return node->value;
        case ADD:
            return evaluate(node->left) + evaluate(node->right);
        case SUBTRACT:
            return evaluate(node->left) - evaluate(node->right);
        case MULTIPLY:
            return evaluate(node->left) * evaluate(node->right);
        case DIVIDE:
            return evaluate(node->left) / evaluate(node->right);
        default:
            fprintf(stderr, "Evaluation error: unknown node type\n");
            exit(1);
    }
}

void free_tree(Node *node) {
    if (node) {
        free_tree(node->left);
        free_tree(node->right);
        free(node);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

#define MAX_INPUT 100

// Structure for operators
typedef struct {
    char op;
    int precedence;
} Operator;

// Function to apply operators
void applyOperator(Operator op, double *a, double *b) {
    switch (op.op) {
        case '+':
            *a = *a + *b;
            break;
        case '-':
            *a = *a - *b;
            break;
        case '*':
            *a = *a * *b;
            break;
        case '/':
            if (*b == 0) {
                printf("Error: Division by zero.\n");
                exit(EXIT_FAILURE);
            }
            *a = *a / *b;
            break;
    }
}

// Function to check precedence
int precedence(char op) {
    switch (op) {
        case '+':
        case '-':
            return 1;
        case '*':
        case '/':
            return 2;
    }
    return 0; // For '(' and ')'
}

// Function to evaluate expression
void evaluate(char *expression) {
    double numbers[MAX_INPUT];
    Operator operators[MAX_INPUT];
    int numCount = 0, opCount = 0;
    int i = 0;

    // Parse expression
    while (expression[i] != '\0') {
        if (isdigit(expression[i])) {
            int num = 0;
            while (expression[i] != '\0' && (isdigit(expression[i]) || expression[i] == '.')) {
                if (expression[i] == '.') {
                    i++;
                    if (!isdigit(expression[i])) {
                        printf("Invalid input.\n");
                        return;
                    }
                }
                num = num * 10 + (expression[i] - '0');
                i++;
            }
            numbers[numCount++] = (double)num;
        } else if (expression[i] == '(') {
            operators[opCount].op = '(';
            operators[opCount].precedence = 0;
            opCount++;
            i++;
        } else if (expression[i] == ')') {
            // Apply operators until '(' is found
            while (opCount > 0 && operators[opCount - 1].op != '(') {
                applyOperator(operators[opCount - 1], &numbers[numCount - 2], &numbers[numCount - 1]);
                numCount--;
                opCount--;
            }
            if (opCount == 0 || operators[opCount - 1].op != '(') {
                printf("Invalid expression.\n");
                return;
            }
            opCount--; // Remove '('
            i++;
        } else if (expression[i] == '+' || expression[i] == '-' || expression[i] == '*' || expression[i] == '/') {
            // Apply operators with higher or equal precedence
            while (opCount > 0 && operators[opCount - 1].op != '(' && precedence(operators[opCount - 1].op) >= precedence(expression[i])) {
                applyOperator(operators[opCount - 1], &numbers[numCount - 2], &numbers[numCount - 1]);
                numCount--;
                opCount--;
            }

            operators[opCount].op = expression[i];
            operators[opCount].precedence = precedence(expression[i]);
            opCount++;
            i++;
        } else if (expression[i] == ' ') {
            i++;
        } else {
            printf("Invalid input.\n");
            return;
        }
    }

    // Apply remaining operators
    while (opCount > 0) {
        applyOperator(operators[opCount - 1], &numbers[numCount - 2], &numbers[numCount - 1]);
        numCount--;
        opCount--;
    }

    if (numCount != 1) {
        printf("Invalid expression.\n");
        return;
    }

    printf("Result: %.2f\n", numbers[0]);
}

int main() {
    char expression[MAX_INPUT];
    printf("Enter a mathematical expression: ");
    fgets(expression, sizeof(expression), stdin);

    // Remove newline character at the end
    for (int i = 0; i < strlen(expression); i++) {
        if (expression[i] == '\n') {
            expression[i] = '\0';
            break;
        }
    }

    evaluate(expression);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

// Function prototypes
double evaluateExpression(char *expression);
double evaluate(char *expression, int *index);
double term(char *expression, int *index);
double factor(char *expression, int *index);

// Main function to evaluate the expression
double evaluateExpression(char *expression) {
    int index = 0;
    return evaluate(expression, &index);
}

// Evaluate the expression
double evaluate(char *expression, int *index) {
    double result = term(expression, index);
    while (expression[*index] == '+' || expression[*index] == '-') {
        char op = expression[(*index)++];
        double nextTerm = term(expression, index);
        if (op == '+') {
            result += nextTerm;
        } else {
            result -= nextTerm;
        }
    }
    return result;
}

// Evaluate a term (multiplication and division)
double term(char *expression, int *index) {
    double result = factor(expression, index);
    while (expression[*index] == '*' || expression[*index] == '/') {
        char op = expression[(*index)++];
        double nextFactor = factor(expression, index);
        if (op == '*') {
            result *= nextFactor;
        } else {
            if (nextFactor == 0) {
                fprintf(stderr, "Error: Division by zero\n");
                exit(1);
            }
            result /= nextFactor;
        }
    }
    return result;
}

// Evaluate a factor (number or parentheses)
double factor(char *expression, int *index) {
    double result = 0.0;
    if (expression[*index] == '(') {
        (*index)++;
        result = evaluate(expression, index);
        if (expression[*index] != ')') {
            fprintf(stderr, "Error: Missing closing parenthesis\n");
            exit(1);
        }
        (*index)++;
    } else if (isdigit(expression[*index]) || expression[*index] == '.') {
        char *end;
        result = strtod(&expression[*index], &end);
        *index += end - &expression[*index];
    } else {
        fprintf(stderr, "Error: Unexpected character\n");
        exit(1);
    }
    return result;
}

