// Structure to hold conversion results
typedef struct {
    double celsius;
    double fahrenheit;
    double kelvin;
    bool is_valid;
} TemperatureConversion;

// Enum for temperature units
typedef enum {
    CELSIUS,
    FAHRENHEIT,
    KELVIN
} TemperatureUnit;

// Function to convert temperatures
TemperatureConversion convert_temperature(double value, TemperatureUnit input_unit) {
    TemperatureConversion result = {0.0, 0.0, 0.0, false};

    // Check for absolute zero
    switch(input_unit) {
        case CELSIUS:
            if (value < -273.15) {
                printf("Error: Temperature below absolute zero in Celsius\n");
                return result;
            }
            // Convert from Celsius
            result.celsius = value;
            result.fahrenheit = (value * 9.0/5.0) + 32.0;
            result.kelvin = value + 273.15;
            break;

        case FAHRENHEIT:
            if (value < -459.67) {
                printf("Error: Temperature below absolute zero in Fahrenheit\n");
                return result;
            }
            // Convert from Fahrenheit
            result.fahrenheit = value;
            result.celsius = (value - 32.0) * 5.0/9.0;
            result.kelvin = (value - 32.0) * 5.0/9.0 + 273.15;
            break;

        case KELVIN:
            if (value < 0) {
                printf("Error: Temperature below absolute zero in Kelvin\n");
                return result;
            }
            // Convert from Kelvin
            result.kelvin = value;
            result.celsius = value - 273.15;
            result.fahrenheit = (value - 273.15) * 9.0/5.0 + 32.0;
            break;

        default:
            printf("Error: Invalid temperature unit\n");
            return result;
    }

    // Mark conversion as valid
    result.is_valid = true;
    return result;
}

// Helper function to print conversion results
void print_temperature_conversion(TemperatureConversion conversion) {
    if (!conversion.is_valid) {
        printf("Conversion failed.\n");
        return;
    }

    printf("Temperature Conversions:\n");
    printf("Celsius:    %.2f °C\n", conversion.celsius);
    printf("Fahrenheit: %.2f °F\n", conversion.fahrenheit);
    printf("Kelvin:     %.2f K\n", conversion.kelvin);
}

// Example usage
int main() {
    // Test conversions
    TemperatureConversion conv1 = convert_temperature(25.0, CELSIUS);
    printf("\nConverting 25.0 °C:\n");
    print_temperature_conversion(conv1);

    TemperatureConversion conv2 = convert_temperature(98.6, FAHRENHEIT);
    printf("\nConverting 98.6 °F:\n");
    print_temperature_conversion(conv2);

    TemperatureConversion conv3 = convert_temperature(300.0, KELVIN);
    printf("\nConverting 300.0 K:\n");
    print_temperature_conversion(conv3);

    // Test error case (below absolute zero)
    TemperatureConversion conv4 = convert_temperature(-300.0, CELSIUS);
    printf("\nTesting below absolute zero:\n");
    print_temperature_conversion(conv4);

    return 0;
}

