#define ABSOLUTE_ZERO_CELSIUS -273.15
#define ABSOLUTE_ZERO_FAHRENHEIT -459.67
#define ABSOLUTE_ZERO_KELVIN 0.0

typedef struct {
    double celsius;
    double fahrenheit;
    double kelvin;
} Temperature;

bool convertTemperature(double value, char unit, Temperature *result) {
    // Check if the temperature is below absolute zero for the given unit
    if ((unit == 'C' && value < ABSOLUTE_ZERO_CELSIUS) ||
        (unit == 'F' && value < ABSOLUTE_ZERO_FAHRENHEIT) ||
        (unit == 'K' && value < ABSOLUTE_ZERO_KELVIN)) {
        return false; // Error: Temperature below absolute zero
    }

    // Convert the input temperature to Celsius, Fahrenheit, and Kelvin
    switch (unit) {
        case 'C':
            result->celsius = value;
            result->fahrenheit = (value * 9 / 5) + 32;
            result->kelvin = value + 273.15;
            break;
        case 'F':
            result->celsius = (value - 32) * 5 / 9;
            result->fahrenheit = value;
            result->kelvin = (value - 32) * 5 / 9 + 273.15;
            break;
        case 'K':
            result->celsius = value - 273.15;
            result->fahrenheit = (value - 273.15) * 9 / 5 + 32;
            result->kelvin = value;
            break;
        default:
            return false; // Error: Invalid unit
    }

    return true; // Success
}

