    double kelvin;
} ConvertedTemperatures;

// Define an enum for units to make the code more readable and robust
typedef enum {
    UNIT_CELSIUS,
    UNIT_FAHRENHEIT,
    UNIT_KELVIN,
    UNIT_UNKNOWN // For error handling if unit string is invalid
} TemperatureUnit;

// Function to convert a string unit to its enum representation
TemperatureUnit parseUnit(const char* unit_str) {
    if (unit_str == NULL) {
        return UNIT_UNKNOWN;
    }
    if (strcasecmp(unit_str, "celsius") == 0 || strcasecmp(unit_str, "c") == 0) {
        return UNIT_CELSIUS;
    } else if (strcasecmp(unit_str, "fahrenheit") == 0 || strcasecmp(unit_str, "f") == 0) {
        return UNIT_FAHRENHEIT;
    } else if (strcasecmp(unit_str, "kelvin") == 0 || strcasecmp(unit_str, "k") == 0) {
        return UNIT_KELVIN;
    }
    return UNIT_UNKNOWN;
}

/**
 * @brief Converts a temperature value from a given unit to Celsius, Fahrenheit, and Kelvin.
 *
 * @param value The temperature value to convert.
 * @param unit_str A string representing the input unit ("celsius", "fahrenheit", "kelvin", "c", "f", "k").
 * @param output A pointer to a ConvertedTemperatures structure where the results will be stored.
 *               The fields (celsius, fahrenheit, kelvin) will be populated upon successful conversion.
 * @return 0 on success, -1 if the input unit is unknown, -2 if the temperature is below absolute zero.
 */
int convertTemperature(double value, const char* unit_str, ConvertedTemperatures* output) {
    if (output == NULL) {
        // This indicates a programming error, as the output pointer should always be valid.
        fprintf(stderr, "Error: Output structure pointer is NULL.\n");
        return -1; // Or some other appropriate error code
    }

    TemperatureUnit unit = parseUnit(unit_str);

    switch (unit) {
        case UNIT_CELSIUS:
            // Check for absolute zero in Celsius
            if (value < -273.15) {
                return -2; // Below absolute zero
            }
            output->celsius = value;
            output->fahrenheit = (value * 9.0 / 5.0) + 32.0;
            output->kelvin = value + 273.15;
            break;

        case UNIT_FAHRENHEIT:
            // Check for absolute zero in Fahrenheit
            if (value < -459.67) {
                return -2; // Below absolute zero
            }
            output->celsius = (value - 32.0) * 5.0 / 9.0;
            output->fahrenheit = value;
            output->kelvin = (value + 459.67) * 5.0 / 9.0;
            break;

        case UNIT_KELVIN:
            // Check for absolute zero in Kelvin
            if (value < 0.0) {
                return -2; // Below absolute zero
            }
            output->celsius = value - 273.15;
            output->fahrenheit = (value * 9.0 / 5.0) - 459.67;
            output->kelvin = value;
            break;

        case UNIT_UNKNOWN:
        default:
            return -1; // Invalid unit
    }

    return 0; // Success
}


