} TemperatureConversionResult;

// Function to perform the conversion
TemperatureConversionResult convertTemperature(double value, TemperatureUnit unit) {
    TemperatureConversionResult result;
    result.error = 0; // Assume no error initially

    // Check for temperature below absolute zero for each scale
    switch (unit) {
        case CELSIUS:
            if (value < -273.15) {
                result.error = 1;
            }
            break;
        case FAHRENHEIT:
            if (value < -459.67) {
                result.error = 1;
            }
            break;
        case KELVIN:
            if (value < 0) {
                result.error = 1;
            }
            break;
    }

    if (result.error) {
        return result;
    }

    // Convert temperature to all scales
    switch (unit) {
        case CELSIUS:
            result.celsius = value;
            result.fahrenheit = (value * 9.0 / 5.0) + 32.0;
            result.kelvin = value + 273.15;
            break;
        case FAHRENHEIT:
            result.celsius = (value - 32.0) * 5.0 / 9.0;
            result.fahrenheit = value;
            result.kelvin = ((value - 32.0) * 5.0 / 9.0) + 273.15;
            break;
        case KELVIN:
            result.celsius = value - 273.15;
            result.fahrenheit = ((value - 273.15) * 9.0 / 5.0) + 32.0;
            result.kelvin = value;
            break;
    }

    return result;
}

