// Function to play the number guessing game
void playNumberGuessingGame() {
    int secretNumber;
    int guess;
    int numberOfTries = 0;
    const int MIN_NUMBER = 1;
    const int MAX_NUMBER = 100; // Define the range for the secret number

    // --- Seed the random number generator ---
    // This is crucial! Without seeding, rand() will produce the same sequence
    // of numbers every time the program runs. time(NULL) provides a
    // different seed each second, making the random numbers more unpredictable.
    srand(time(NULL));

    // --- Generate a random secret number ---
    // (rand() % (MAX_NUMBER - MIN_NUMBER + 1)) + MIN_NUMBER
    // This formula ensures the number is within the specified range [MIN_NUMBER, MAX_NUMBER].
    // Example for 1-100:
    // rand() % 100 produces 0-99
    // + 1 shifts it to 1-100
    secretNumber = (rand() % (MAX_NUMBER - MIN_NUMBER + 1)) + MIN_NUMBER;

    printf("Welcome to the Number Guessing Game!\n");
    printf("I have picked a secret number between %d and %d.\n", MIN_NUMBER, MAX_NUMBER);
    printf("Try to guess it!\n\n");

    // --- Game loop ---
    do {
        printf("Enter your guess: ");
        // Read the user's guess
        // We use an if-else structure to handle potential non-integer input
        if (scanf("%d", &guess) != 1) {
            printf("Invalid input. Please enter a whole number.\n");
            // Clear the invalid input from the buffer
            while (getchar() != '\n'); 
            continue; // Skip to the next iteration of the loop
        }

        numberOfTries++; // Increment the try counter after each valid guess

        if (guess > secretNumber) {
            printf("Too high! Try again.\n");
        } else if (guess < secretNumber) {
            printf("Too low! Try again.\n");
        } else {
            printf("\nCongratulations! You guessed the number %d in %d tries!\n", secretNumber, numberOfTries);
        }
    } while (guess != secretNumber); // Continue loop until the guess is correct

    printf("Thanks for playing!\n");
}

