#include <unistd.h>
#include <sys/time.h>
#include <sys/wait.h>
#include <string.h>

// Structure to store execution details
typedef struct {
    char* path;
    double execution_time;
} ExecutionResult;

// Function to compare execution times for sorting
int compare_execution_times(const void* a, const void* b) {
    ExecutionResult* result1 = (ExecutionResult*)a;
    ExecutionResult* result2 = (ExecutionResult*)b;

    if (result1->execution_time < result2->execution_time) return -1;
    if (result1->execution_time > result2->execution_time) return 1;
    return 0;
}

// Function to run executables and measure their performance
void run_and_measure_executables(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <executable1> <executable2> ...\n", argv[0]);
        exit(1);
    }

    // Allocate memory for results
    ExecutionResult* results = malloc((argc - 1) * sizeof(ExecutionResult));
    if (!results) {
        perror("Memory allocation failed");
        exit(1);
    }

    // Run each executable and measure its execution time
    for (int i = 1; i < argc; i++) {
        struct timeval start, end;
        pid_t pid;

        results[i-1].path = argv[i];

        // Start timer
        gettimeofday(&start, NULL);

        // Fork a child process
        pid = fork();

        if (pid == -1) {
            perror("Fork failed");
            exit(1);
        }
        else if (pid == 0) {
            // Child process: execute the program
            execl(argv[i], argv[i], NULL);

            // If execl fails
            perror("Execution failed");
            exit(1);
        }
        else {
            // Parent process: wait for child and measure time
            int status;
            waitpid(pid, &status, 0);

            // Stop timer
            gettimeofday(&end, NULL);

            // Calculate execution time
            double exec_time = (end.tv_sec - start.tv_sec) * 1000.0 +
                               (end.tv_usec - start.tv_usec) / 1000.0;

            results[i-1].execution_time = exec_time;

            // Check if child process exited normally
            if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
                fprintf(stderr, "Process %s did not exit successfully\n", argv[i]);
            }
        }
    }

    // Sort results by execution time
    qsort(results, argc - 1, sizeof(ExecutionResult), compare_execution_times);

    // Display results
    printf("\nExecutable Performance Ranking:\n");
    printf("--------------------------------\n");
    for (int i = 0; i < argc - 1; i++) {
        printf("%d. %s: %.2f ms\n", 
               i + 1, 
               results[i].path, 
               results[i].execution_time);
    }

    // Free allocated memory
    free(results);
}

int main(int argc, char* argv[]) {
    run_and_measure_executables(argc, argv);
    return 0;
}

