#include <errno.h>

typedef struct {
    char *path;
    double execution_time;
} ProgramResult;

// Function to compare two ProgramResult structures for qsort
int compare_results(const void *a, const void *b) {
    const ProgramResult *pa = (const ProgramResult *)a;
    const ProgramResult *pb = (const ProgramResult *)b;

    if (pa->execution_time < pb->execution_time) return -1;
    if (pa->execution_time > pb->execution_time) return 1;
    return 0;
}

void measure_execution_time(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <executable1> <executable2> ... <executableN>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    ProgramResult *results = malloc((argc - 1) * sizeof(ProgramResult));
    if (results == NULL) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    for (int i = 1; i < argc; i++) {
        pid_t pid = fork();

        if (pid == -1) {
            perror("fork failed");
            exit(EXIT_FAILURE);
        } else if (pid == 0) {
            // Child process - execute the program
            execl(argv[i], argv[i], (char *)NULL);
            // If execl returns, there was an error
            fprintf(stderr, "Failed to execute %s: %s\n", argv[i], strerror(errno));
            exit(EXIT_FAILURE);
        } else {
            // Parent process - measure execution time
            struct timeval start, end;
            gettimeofday(&start, NULL);

            int status;
            waitpid(pid, &status, 0);

            gettimeofday(&end, NULL);

            double elapsed = (end.tv_sec - start.tv_sec) + 
                           (end.tv_usec - start.tv_usec) / 1000000.0;

            results[i-1].path = argv[i];
            results[i-1].execution_time = elapsed;

            printf("Program: %-40s Execution time: %.6f seconds\n", 
                   argv[i], elapsed);
        }
    }

    // Sort the results by execution time
    qsort(results, argc - 1, sizeof(ProgramResult), compare_results);

    // Display the top list
    printf("\nTop list (fastest first):\n");
    printf("-------------------------------------------------\n");
