// Structure to store execution time and path for sorting
typedef struct {
    char *path;
    double time_taken;
} ExecutionResult;

// Comparison function for qsort (ascending order of time)
int compareExecutionResults(const void *a, const void *b) {
    ExecutionResult *resA = (ExecutionResult *)a;
    ExecutionResult *resB = (ExecutionResult *)b;
    if (resA->time_taken < resB->time_taken) return -1;
    if (resA->time_taken > resB->time_taken) return 1;
    return 0;
}

/**
 * @brief Executes a list of files, measures their execution time,
 *        and displays a toplist sorted by execution time.
 *
 * @param exec_paths An array of strings, where each string is a path to an executable file.
 * @param num_paths The number of executable file paths in the exec_paths array.
 */
void measure_and_toplist_executables(char *exec_paths[], int num_paths) {
    if (num_paths <= 0) {
        printf("No executable paths provided.\n");
        return;
    }

    ExecutionResult *results = (ExecutionResult *)malloc(sizeof(ExecutionResult) * num_paths);
    if (results == NULL) {
        perror("Failed to allocate memory for results");
        return;
    }

    // Loop through each executable path
    for (int i = 0; i < num_paths; ++i) {
        char *path = exec_paths[i];
        results[i].path = strdup(path); // Duplicate path for storage
        results[i].time_taken = -1.0;   // Initialize with a sentinel value

        if (results[i].path == NULL) {
            perror("Failed to duplicate path string");
            // Clean up already allocated memory for paths
            for (int j = 0; j < i; ++j) {
                free(results[j].path);
            }
            free(results);
            return;
        }

        struct timespec start_time, end_time;
        pid_t pid = fork();

        if (pid == -1) {
            perror("fork failed");
            results[i].time_taken = -2.0; // Indicate fork error
        } else if (pid == 0) {
            // Child process
            // Redirect stdout and stderr to /dev/null to prevent output clutter
            // If you want to see their output, remove these lines.
            fclose(stdout);
            fclose(stderr);
            freopen("/dev/null", "w", stdout);
            freopen("/dev/null", "w", stderr);

            // Execute the program
            // execlp requires the program name as the first argument, and then its arguments.
            // Since we're not passing explicit arguments to the executables here,
            // we pass the path itself as the program name and then NULL.
            execlp(path, path, (char *)NULL);

            // execlp only returns if an error occurred
            perror("execlp failed");
            // Exit with a non-zero status to indicate an error to the parent
            exit(EXIT_FAILURE);
        } else {
            // Parent process
            clock_gettime(CLOCK_MONOTONIC, &start_time);

            int status;
            pid_t child_pid = waitpid(pid, &status, 0); // Wait for the child to finish

            clock_gettime(CLOCK_MONOTONIC, &end_time);

            if (child_pid == -1) {
                perror("waitpid failed");
                results[i].time_taken = -2.0; // Indicate waitpid error
            } else if (WIFEXITED(status)) {
                if (WEXITSTATUS(status) != 0) {
                    printf("Child process for '%s' exited with non-zero status: %d\n", path, WEXITSTATUS(status));
                    results[i].time_taken = -3.0; // Indicate program exited with error
                } else {
                    // Calculate elapsed time
                    double elapsed_time = (end_time.tv_sec - start_time.tv_sec) +
                                          (end_time.tv_nsec - start_time.tv_nsec) / 1e9; // Convert nanoseconds to seconds
                    results[i].time_taken = elapsed_time;
                }
            } else if (WIFSIGNALED(status)) {
                printf("Child process for '%s' terminated by signal: %d\n", path, WTERMSIG(status));
                results[i].time_taken = -4.0; // Indicate terminated by signal
            } else {
                printf("Child process for '%s' ended in an unexpected way.\n", path);
                results[i].time_taken = -5.0; // Unexpected termination
            }
        }
    }

    // Sort the results
    qsort(results, num_paths, sizeof(ExecutionResult), compareExecutionResults);

    // Display the toplist
    printf("\n--- Executable Toplist by Execution Time ---\n");
    printf("Rank | Time (s) | Executable Path\n");
    printf("-----|----------|-------------------------------------------------\n");

    for (int i = 0; i < num_paths; ++i) {
        printf("%4d | ", i + 1);
        if (results[i].time_taken >= 0) {
            printf("%8.4f | %s\n", results[i].time_taken, results[i].path);
        } else if (results[i].time_taken == -1.0) {
            printf("  N/A     | %s (Error: Uninitialized)\n", results[i].path);
        } else if (results[i].time_taken == -2.0) {
            printf("  ERROR   | %s (Fork/Waitpid Error)\n", results[i].path);
        } else if (results[i].time_taken == -3.0) {
            printf("  FAILED  | %s (Program exited with error)\n", results[i].path);
        } else if (results[i].time_taken == -4.0) {
            printf("  SIGNAL  | %s (Terminated by signal)\n", results[i].path);
        } else {
            printf("  UNKNOWN | %s (Unknown Error)\n", results[i].path);
        }
        free(results[i].path); // Free the duplicated path string
    }

    free(results); // Free the array of results
    printf("--------------------------------------------------\n");
}

