#include <stdio.h>
#include <stdlib.h>
#include <sys/time.h>
#include <sys/wait.h>
#include <unistd.h>
#include <string.h>

struct ExecResult {
    char *path;
    double elapsed; // seconds
};

// Compare for ascending order
int cmp_elapsed(const void *a, const void *b) {
    const struct ExecResult *ea = a, *eb = b;
    if (ea->elapsed < eb->elapsed) return -1;
    if (ea->elapsed > eb->elapsed) return 1;
    return 0;
}

double measure_exec(const char *path) {
    struct timeval start, end;
    gettimeofday(&start, NULL);

    pid_t pid = fork();
    if (pid == 0) {
        // In child: exec
        execl(path, path, (char*)NULL);
        // If exec fails
        perror("execl");
        exit(127);
    }
    if (pid < 0) {
        perror("fork");
        return -1.0;
    }

    int status;
    waitpid(pid, &status, 0);

    gettimeofday(&end, NULL);
    double elapsed = (end.tv_sec - start.tv_sec) +
                     (end.tv_usec - start.tv_usec) / 1e6;
    return elapsed;
}

void toplist(int count, char *paths[]) {
    struct ExecResult *results = malloc(sizeof(struct ExecResult) * count);
    if (!results) {
        perror("malloc");
        exit(1);
    }

    printf("Running %d executables...\n", count);
    for (int i = 0; i < count; ++i) {
        printf("[%d/%d] Running: %s\n", i+1, count, paths[i]);
        double t = measure_exec(paths[i]);
        results[i].path = paths[i];
        results[i].elapsed = t;
    }

    qsort(results, count, sizeof(results[0]), cmp_elapsed);

    printf("\nToplist (fastest to slowest):\n");
    printf("%-4s %-8s %s\n", "Rank", "Time(s)", "Executable");
    for (int i = 0; i < count; ++i) {
        printf("%-4d %-8.3lf %s\n", i+1, results[i].elapsed, results[i].path);
    }
    free(results);
}

