#define MAX_PATH_SIZE 256

typedef struct {
    char path[MAX_PATH_SIZE];
    double duration;
} ExecResult;

// Compare function for sorting ExecResult by time
int compare_exec_time(const void *a, const void *b) {
    ExecResult *execA = (ExecResult *)a;
    ExecResult *execB = (ExecResult *)b;
    if (execA->duration < execB->duration) return -1;
    else if (execA->duration > execB->duration) return 1;
    else return 0;
}

void measure_execution_times(int argc, char *argv[]) {
    if(argc < 2) {
        fprintf(stderr, "Usage: %s <list_of_executables>\n", argv[0]);
        return;
    }

    ExecResult *results = calloc(argc - 1, sizeof(ExecResult));
    if (!results) {
        perror("Allocation failed");
        exit(EXIT_FAILURE);
    }

    for (int i = 1; i < argc; ++i) {
        struct timeval start, end;
        gettimeofday(&start, NULL);

        pid_t pid = fork();
        if (pid == 0) {
            // Child process: execute the given file
            execl(argv[i], argv[i], (char *)NULL);
            perror("Exec failed");
            exit(EXIT_FAILURE);
        } else if (pid < 0) {
            perror("Fork failed");
            free(results);
            exit(EXIT_FAILURE);
        }

        // Parent process: wait for the child to finish
        int status;
        waitpid(pid, &status, 0);

        gettimeofday(&end, NULL);

        double elapsedTime = (end.tv_sec - start.tv_sec) + 
                             (end.tv_usec - start.tv_usec) / 1000000.0;

        // Store the result
        strncpy(results[i - 1].path, argv[i], MAX_PATH_SIZE);
        results[i - 1].duration = elapsedTime;
    }

    // Sort results based on execution time
    qsort(results, argc - 1, sizeof(ExecResult), compare_exec_time);

    // Print the results
    printf("Toplist of execution times:\n");
    for (int i = 0; i < argc - 1; ++i) {
        printf("%s: %.6f seconds\n", results[i].path, results[i].duration);
    }

    free(results);
}

