} ProcessInfo;

// Compare function for qsort
int compare(const void* a, const void* b) {
    ProcessInfo* p1 = (ProcessInfo*)a;
    ProcessInfo* p2 = (ProcessInfo*)b;

    if (p1->execution_time < p2->execution_time)
        return -1;
    else if (p1->execution_time > p2->execution_time)
        return 1;
    else
        return 0;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <executable1> <executable2> ...\n", argv[0]);
        return 1;
    }

    // Create an array of ProcessInfo structures
    ProcessInfo* processes = (ProcessInfo*)malloc((argc - 1) * sizeof(ProcessInfo));

    // Initialize the processes array
    for (int i = 1; i < argc; i++) {
        processes[i - 1].path = argv[i];
        processes[i - 1].execution_time = 0.0;
    }

    // Run each process and measure its execution time
    for (int i = 0; i < argc - 1; i++) {
        pid_t pid;
        struct timespec start, finish;

        // Record the start time
        clock_gettime(CLOCK_REALTIME, &start);

        // Create a new process
        pid = fork();

        if (pid == 0) {
            // Child process
            execv(processes[i].path, &argv[i]);
            // If execv returns, it means an error occurred
            perror("execv");
            exit(1);
        } else if (pid > 0) {
            // Parent process
            wait(NULL);

            // Record the finish time
            clock_gettime(CLOCK_REALTIME, &finish);

            // Calculate the execution time
            double execution_time = (finish.tv_sec - start.tv_sec) + (finish.tv_nsec - start.tv_nsec) / 1e9;
            processes[i].execution_time = execution_time;
        } else {
            // Error creating process
            perror("fork");
            exit(1);
        }
    }

    // Sort the processes array by execution time
    qsort(processes, argc - 1, sizeof(ProcessInfo), compare);

    // Print the toplist
    printf("Toplist:\n");
    for (int i = 0; i < argc - 1; i++) {
        printf("%d. %s: %.6f seconds\n", i + 1, processes[i].path, processes[i].execution_time);
    }

    free(processes);
    return 0;
}

#include <stdio.h>
