// Structure to store the executable name and its execution time
typedef struct {
    char *name;
    double time;
} Executable;

// Function to compare two Executable structures based on their time
int compareExecutable(const void *a, const void *b) {
    Executable *exec1 = (Executable *)a;
    Executable *exec2 = (Executable *)b;
    return (exec1->time > exec2->time) - (exec1->time < exec2->time);
}

// Function to measure the execution time of an executable
double measureExecutionTime(const char *executable) {
    struct timeval start, end;
    double elapsedTime;

    // Start the timer
    gettimeofday(&start, NULL);

    // Fork a new process to run the executable
    pid_t pid = fork();
    if (pid < 0) {
        perror("Fork failed");
        exit(1);
    } else if (pid == 0) {
        // Child process
        execl(executable, executable, (char *)NULL);
        perror("Execl failed");
        exit(1);
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);

        // Stop the timer
        gettimeofday(&end, NULL);

        // Calculate the elapsed time
        elapsedTime = (end.tv_sec - start.tv_sec) + (end.tv_usec - start.tv_usec) / 1000000.0;
    }

    return elapsedTime;
}

// Function to display the toplist of execution times
void displayToplist(Executable *executables, int count) {
    printf("Toplist of Execution Times:\n");
    for (int i = 0; i < count; i++) {
        printf("%d. %s: %.6f seconds\n", i + 1, executables[i].name, executables[i].time);
    }
}

// Main function to measure the execution times of the given executables
void measureAndDisplayToplist(int argc, char *argv[]) {
