        fprintf(stderr, "Usage: %s <executable1> <executable2> ...\n", argv[0]);
        return;
    }

    Executable *executables = malloc((argc - 1) * sizeof(Executable));
    if (executables == NULL) {
        perror("Memory allocation failed");
        return;
    }

    for (int i = 1; i < argc; i++) {
        executables[i - 1].name = argv[i];
        executables[i - 1].time = measureExecutionTime(argv[i]);
    }

    // Sort the executables based on their execution times
    qsort(executables, argc - 1, sizeof(Executable), compareExecutable);

    // Display the toplist
    displayToplist(executables, argc - 1);

    // Free the allocated memory
    free(executables);
}

int main(int argc, char *argv[]) {
    measureAndDisplayToplist(argc, argv);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int** create_identity_matrix(int n) {
    // Determine the actual size (absolute value of n)
    int size = abs(n);

    // Allocate memory for the matrix rows
    int** matrix = (int**)malloc(size * sizeof(int*));
    if (matrix == NULL) {
        return NULL;  // Memory allocation failed
    }

    // Allocate memory for each row and initialize
    for (int i = 0; i < size; i++) {
        matrix[i] = (int*)calloc(size, sizeof(int));
        if (matrix[i] == NULL) {
            // Free previously allocated memory if allocation fails
            for (int j = 0; j < i; j++) {
                free(matrix[j]);
            }
            free(matrix);
            return NULL;
        }
    }

    // Fill the matrix based on the sign of n
    if (n >= 0) {
        // Regular identity matrix
        for (int i = 0; i < size; i++) {
            matrix[i][i] = 1;
        }
    } else {
        // Reversed identity matrix
        for (int i = 0; i < size; i++) {
            matrix[size - 1 - i][size - 1 - i] = 1;
        }
    }

    return matrix;
}

// Helper function to print the matrix
void print_matrix(int** matrix, int n) {
    int size = abs(n);

    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            printf("%d ", matrix[i][j]);
        }
        printf("\n");
    }
}

// Helper function to free the matrix memory
void free_matrix(int** matrix, int n) {
    int size = abs(n);

    for (int i = 0; i < size; i++) {
        free(matrix[i]);
    }
    free(matrix);
}

