int main() {
    // Test cases
    int test_cases[] = {3, -3, 4, -4, 0};

    for (int i = 0; i < sizeof(test_cases) / sizeof(test_cases[0]); i++) {
        int n = test_cases[i];

        printf("Identity matrix for n = %d:\n", n);

        // Create the identity matrix
        int** identity = create_identity_matrix(n);

        // Check if matrix creation was successful
        if (identity == NULL) {
            printf("Failed to create matrix\n");
            continue;
        }

        // Print the matrix
        print_matrix(identity, n);

        // Free the matrix memory
        free_matrix(identity, n);

        printf("\n");
    }

    return 0;
}

#include <stdlib.h>

int** create_identity_matrix(int n) {
    int size = (n > 0) ? n : -n;

    // Allocate memory for the matrix
    int** matrix = (int**)malloc(size * sizeof(int*));
    for (int i = 0; i < size; i++) {
        matrix[i] = (int*)malloc(size * sizeof(int));
    }

    // Fill the matrix
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            if (n > 0) {
                // Identity matrix: 1 on diagonal, 0 elsewhere
                matrix[i][j] = (i == j) ? 1 : 0;
            } else {
                // Reversed identity matrix: 1 on anti-diagonal, 0 elsewhere
                matrix[i][j] = (i + j == size - 1) ? 1 : 0;
            }
        }
    }

    return matrix;
}

#include <stdlib.h> // For malloc and free
#include <stdio.h>  // For potential debugging (can be removed)

/**
 * @brief Represents a dynamically allocated matrix.
 */
typedef struct {
    int** matrix;
    int size;
} Matrix;

/**
 * @brief Creates an identity matrix of a given size.
 *
 * @param n The size of the square matrix. If negative, returns a reversed identity matrix.
 * @return A Matrix struct containing the allocated square matrix and its size.
 *         Returns matrix=NULL and size=0 if allocation fails.
 */
Matrix createIdentityMatrix(int n) {
    Matrix result;
    result.matrix = NULL;
    result.size = 0;

    int abs_n = (n < 0) ? -n : n;

    if (abs_n == 0) {
        return result; // Identity matrix of size 0 is undefined or empty
    }

    // Allocate memory for rows
    result.matrix = (int**)malloc(abs_n * sizeof(int*));
    if (result.matrix == NULL) {
        perror("Failed to allocate memory for matrix rows");
        return result;
    }

    // Allocate memory for columns and initialize
    for (int i = 0; i < abs_n; i++) {
        result.matrix[i] = (int*)malloc(abs_n * sizeof(int));
        if (result.matrix[i] == NULL) {
            perror("Failed to allocate memory for matrix columns");
            // Clean up previously allocated rows
            for (int k = 0; k < i; k++) {
                free(result.matrix[k]);
            }
            free(result.matrix);
            result.matrix = NULL;
            return result;
        }

        // Initialize all elements to 0
        for (int j = 0; j < abs_n; j++) {
            result.matrix[i][j] = 0;
        }
    }

    // Populate the identity or reversed identity matrix
    if (n >= 0) {
        // Identity matrix
        for (int i = 0; i < abs_n; i++) {
            result.matrix[i][i] = 1;
        }
    } else {
        // Reversed identity matrix (anti-diagonal)
        for (int i = 0; i < abs_n; i++) {
            result.matrix[i][abs_n - 1 - i] = 1;
        }
    }

    result.size = abs_n;
    return result;
}

/**
 * @brief Frees the memory allocated for a Matrix.
 *
 * It's crucial to call this function after you are done using a Matrix
 * created by createIdentityMatrix to prevent memory leaks.
 *
 * @param mat A pointer to the Matrix struct to be freed.
 */
void freeMatrix(Matrix* mat) {
