#include <stdio.h>
#include <stdlib.h>

int** get_identity(int n) {
    if (n == 0) return NULL;

    int size = abs(n);
    int **matrix = malloc(size * sizeof(int *));
    if (!matrix) return NULL;
    for (int i = 0; i < size; ++i) {
        matrix[i] = calloc(size, sizeof(int)); // initializes with zeros
        if (!matrix[i]) {
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) free(matrix[j]);
            free(matrix);
            return NULL;
        }
    }

    if (n > 0) {
        // Identity matrix
        for (int i = 0; i < size; ++i)
            matrix[i][i] = 1;
    } else {
        // Reversed identity (diagonal from top-right to bottom-left)
        for (int i = 0; i < size; ++i)
            matrix[i][size - 1 - i] = 1;
    }
    return matrix;
}

// Utility to print and free matrix
void print_matrix(int **mat, int n) {
    if (!mat) {
        printf("NULL\n");
        return;
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j)
            printf("%d ", mat[i][j]);
        printf("\n");
    }
}

void free_matrix(int **mat, int n) {
    if (!mat) return;
    for (int i = 0; i < n; ++i)
        free(mat[i]);
    free(mat);
}

// Example usage
int main() {
    int n = 4;
    int **mat = get_identity(n);
    printf("Identity matrix %d x %d:\n", n, n);
    print_matrix(mat, n);
    free_matrix(mat, n);

    int neg_n = -4;
    int **rev_mat = get_identity(neg_n);
    printf("Reversed identity matrix %d x %d:\n", -neg_n, -neg_n);
    print_matrix(rev_mat, -neg_n);
    free_matrix(rev_mat, -neg_n);

    return 0;
}

