#include <stdbool.h>

// Enum to represent possible error codes
typedef enum {
    ARN_SUCCESS,
    ARN_INVALID_FORMAT,
    ARN_EMPTY_STRING
} ARNParseResult;

// Structure to return both result and service name
typedef struct {
    ARNParseResult result;
    char service[50];  // Adjust size as needed
} ARNParseOutput;

// Function to parse AWS ARN and extract service
ARNParseOutput parse_aws_arn(const char* arn) {
    ARNParseOutput output = {0};

    // Check for NULL or empty string
    if (arn == NULL || strlen(arn) == 0) {
        output.result = ARN_EMPTY_STRING;
        return output;
    }

    // Validate ARN starts with "arn:"
    if (strncmp(arn, "arn:", 4) != 0) {
        output.result = ARN_INVALID_FORMAT;
        return output;
    }

    // Find the partition (e.g., aws, aws-cn)
    const char* partition_start = arn + 4;
    const char* partition_end = strchr(partition_start, ':');
    if (partition_end == NULL) {
        output.result = ARN_INVALID_FORMAT;
        return output;
    }

    // Find the service
    const char* service_start = partition_end + 1;
    const char* service_end = strchr(service_start, ':');
    if (service_end == NULL) {
        output.result = ARN_INVALID_FORMAT;
        return output;
    }

    // Copy service name
    size_t service_length = service_end - service_start;
    if (service_length >= sizeof(output.service)) {
        output.result = ARN_INVALID_FORMAT;
        return output;
    }

    strncpy(output.service, service_start, service_length);
    output.service[service_length] = '\0';

    output.result = ARN_SUCCESS;
    return output;
}

