        switch (result.result) {
            case ARN_SUCCESS:
                printf("ARN: %s, Service: %s\n", test_arns[i], result.service);
                break;
            case ARN_INVALID_FORMAT:
                printf("ARN: %s, Invalid format\n", test_arns[i]);
                break;
            case ARN_EMPTY_STRING:
                printf("ARN: NULL or empty string\n");
                break;
        }
    }

