}

#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAX_ARN_LENGTH 1024
#define MAX_SERVICE_LENGTH 20

typedef enum {
    ARN_VALID,
    ARN_INVALID_FORMAT,
    ARN_INVALID_PARTITION,
    ARN_INVALID_SERVICE
} ARNStatus;

ARNStatus get_service_from_arn(const char* arn, char* service_out) {
    // Basic validation
    if (arn == NULL || strlen(arn) > MAX_ARN_LENGTH) {
        return ARN_INVALID_FORMAT;
    }

    // ARN format: arn:partition:service:region:account-id:resource
    // ARN format: arn:partition:service:region:account-id:resourcetype/resource
    // ARN format: arn:partition:service:region:account-id:resourcetype:resource

    // Check if it starts with "arn:"
    if (strncmp(arn, "arn:", 4) != 0) {
        return ARN_INVALID_FORMAT;
    }

    // Make a copy to avoid modifying the original
    char arn_copy[MAX_ARN_LENGTH];
    strncpy(arn_copy, arn, MAX_ARN_LENGTH);
    arn_copy[MAX_ARN_LENGTH - 1] = '\0';

    // Tokenize the ARN
    char* tokens[6];
    char* token = strtok(arn_copy, ":");
    int token_count = 0;

    while (token != NULL && token_count < 6) {
        tokens[token_count++] = token;
        token = strtok(NULL, ":");
    }

    // ARN must have at least 6 parts (some parts may be empty)
    if (token_count < 6) {
        return ARN_INVALID_FORMAT;
    }

    // Validate partition (second token)
    const char* partition = tokens[1];
    if (strlen(partition) == 0 || 
        (strcmp(partition, "aws") != 0 && 
         strcmp(partition, "aws-cn") != 0 && 
         strcmp(partition, "aws-us-gov") != 0)) {
        return ARN_INVALID_PARTITION;
    }

    // Extract service (third token)
    const char* service = tokens[2];
    if (strlen(service) == 0) {
        return ARN_INVALID_SERVICE;
    }

    // Copy the service name to output
    strncpy(service_out, service, MAX_SERVICE_LENGTH);
    service_out[MAX_SERVICE_LENGTH - 1] = '\0';

    return ARN_VALID;
}

int main() {
    const char* test_arns[] = {
        "arn:aws:ec2:us-east-1:123456789012:instance/i-1234567890abcdef0",
        "arn:aws:s3:::my-bucket",
        "arn:aws:lambda:us-west-2:123456789012:function:my-function",
        "arn:aws:iam::123456789012:user/JohnDoe",
        "arn:aws-cn:rds:cn-north-1:123456789012:db:my-db-instance",
        "arn:aws-us-gov:kms:us-gov-west-1:123456789012:key/12345678-1234-1234-1234-123456789012",
        "invalid-arn",
        "arn:invalid:partition:service:region:account:resource",
        "arn:aws::us-east-1:123456789012:resource",  // Missing service
        NULL
    };

    for (int i = 0; test_arns[i] != NULL; i++) {
        char service[MAX_SERVICE_LENGTH];
        ARNStatus status = get_service_from_arn(test_arns[i], service);

        printf("ARN: %s\n", test_arns[i]);
        if (status == ARN_VALID) {
            printf("  Service: %s\n", service);
        } else {
            printf("  Error: ");
            switch (status) {
                case ARN_INVALID_FORMAT: printf("Invalid ARN format\n"); break;
                case ARN_INVALID_PARTITION: printf("Invalid partition\n"); break;
                case ARN_INVALID_SERVICE: printf("Invalid or missing service\n"); break;
                default: printf("Unknown error\n");
            }
        }
        printf("\n");
    }

    return 0;
}

#include <stdio.h>
#include <string.h> // For strncmp, strncpy
#include <stdlib.h> // For size_t

// Define an enum for the function's return status
typedef enum {
    ARN_PARSE_SUCCESS,
    ARN_PARSE_ERROR_NULL_INPUT,      // Input ARN or buffer is NULL
    ARN_PARSE_ERROR_INVALID_FORMAT,  // ARN does not start with "arn:", is too short, or has an empty service segment
    ARN_PARSE_ERROR_BUFFER_TOO_SMALL // Provided buffer is too small to hold the service name
} ArnParseStatus;

/**
 * @brief Extracts the AWS service name from an AWS ARN string.
 *
 * An AWS ARN has the format: arn:partition:service:region:account-id:resource
 * This function extracts the 'service' part (the third component).
 *
 * @param arn The input AWS ARN string (e.g., "arn:aws:s3:::mybucket").
 * @param service_buffer A buffer to store the extracted service name.
 * @param buffer_size The size of the service_buffer in bytes.
 * @return ArnParseStatus indicating success or the type of error.
 *         - ARN_PARSE_SUCCESS: Service name extracted successfully.
 *         - ARN_PARSE_ERROR_NULL_INPUT: 'arn' or 'service_buffer' is NULL.
 *         - ARN_PARSE_ERROR_INVALID_FORMAT: 'arn' does not match expected format
 *                                           (e.g., too short, doesn't start with "arn:",
 *                                           or the service name segment is empty).
 *         - ARN_PARSE_ERROR_BUFFER_TOO_SMALL: 'service_buffer' is not large enough
 *                                             to store the extracted service name (including null terminator).
 */
ArnParseStatus get_aws_service_from_arn(const char *arn, char *service_buffer, size_t buffer_size) {
    if (arn == NULL || service_buffer == NULL) {
        return ARN_PARSE_ERROR_NULL_INPUT;
    }
    if (buffer_size == 0) {
        // A buffer of size 0 cannot store even a null terminator
        return ARN_PARSE_ERROR_BUFFER_TOO_SMALL;
    }

    // 1. Check for "arn:" prefix
    // An ARN must start with "arn:", and immediately be followed by at least one character
    // (i.e., not just "arn:\0" or "arn:").
    if (strncmp(arn, "arn:", 4) != 0 || arn[4] == '\0') {
        return ARN_PARSE_ERROR_INVALID_FORMAT;
    }

    const char *p_curr = arn + 4; // Start scanning after "arn:"
    int colon_count = 0;
    const char *service_start = NULL;
    const char *service_end = NULL;

    // We need to find the 2nd colon (which marks the end of the partition and start of service)
    // and the 3rd colon (which marks the end of service and start of region/account-id)
    while (*p_curr != '\0' && colon_count < 3) {
        if (*p_curr == ':') {
            colon_count++;
            if (colon_count == 2) { // Found the second colon, next char is service start
                service_start = p_curr + 1;
            } else if (colon_count == 3) { // Found the third colon, this is service end
                service_end = p_curr;
                break; // We have identified the service part
            }
        }
        p_curr++; // Move to the next character
    }

    // After scanning, service_start should point to the beginning of the service name.
    // If it's still NULL, it means the ARN format was too short to even reach the service part.
    if (service_start == NULL) {
        return ARN_PARSE_ERROR_INVALID_FORMAT;
    }

    // If service_end is NULL, it means the ARN ended after the service name
    // (e.g., "arn:aws:s3"). In this case, the service name extends to the end of the string.
    if (service_end == NULL) {
        service_end = p_curr; // p_curr would be pointing to the null terminator '\0'
    }

    size_t len = service_end - service_start;

    // Check for an empty service name (e.g., "arn:aws::...")
    if (len == 0) {
        return ARN_PARSE_ERROR_INVALID_FORMAT;
    }

    // Check if the provided buffer is large enough for the service name + null terminator
    if (len + 1 > buffer_size) {
        return ARN_PARSE_ERROR_BUFFER_TOO_SMALL;
    }

    // Copy the service name into the buffer
    strncpy(service_buffer, service_start, len);
    service_buffer[len] = '\0'; // Null-terminate the string

    return ARN_PARSE_SUCCESS;
}

