#define ARN_SERVICE_MAXLEN 64

// Returns 0 on success, nonzero on error
// service_out must point to char array of at least ARN_SERVICE_MAXLEN bytes
int extract_arn_service(const char *arn, char *service_out) {
    if (!arn || !service_out) return -1;

    // ARN structure: arn:partition:service:region:account-id:resource
    // Count fields
    const char *p = arn;
    size_t len = strlen(arn);
    int field = 0;
    int last_pos = 0;
    int i = 0;
    char token[ARN_SERVICE_MAXLEN];
    int found = 0;

    // Check prefix
    if (strncmp(arn, "arn:", 4) != 0)
        return -2;

    // We'll tokenize manually to avoid modifying input
    for (i=0; i<len; i++) {
        if (arn[i] == ':') {
            field++;
            if (field == 3) {
                // Field 3 starts at i+1, ends at next ':'
                int start = i+1;
                int end = start;
                while (end < len && arn[end] != ':') end++;
                int slen = end - start;
                if (slen <= 0 || slen >= ARN_SERVICE_MAXLEN)
                    return -3; // Invalid/empty or very long service field
                strncpy(token, arn + start, slen);
                token[slen] = '\0';
                strcpy(service_out, token);
                found = 1;
                break;
            }
        }
    }
    if (!found)
        return -4; // Not enough fields

    return 0; // Success
}

