#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_ARN_LENGTH 2048
#define ERROR_INVALID_ARN "Invalid ARN"

// Function to extract the service name from an ARN
const char* get_service_from_arn(const char* arn) {
    // Check if ARN is probably too long, which might be considered invalid
    if (strlen(arn) >= MAX_ARN_LENGTH) {
        return ERROR_INVALID_ARN;
    }

    // Create a copy of the ARN to tokenize
    char arn_copy[MAX_ARN_LENGTH];
    strncpy(arn_copy, arn, MAX_ARN_LENGTH);

    // Tokenize the ARN based on colons ':'
    char* token = strtok(arn_copy, ":");
    int token_count = 0;
    const char* service = NULL;

    while (token != NULL) {
        token_count++;
        if (token_count == 3) {
            service = token;  // The service is the third token in the ARN format
            break;
        }
        token = strtok(NULL, ":");
    }

    // Check if the ARN had at least 6 parts (`arn:partition:service:region:account-id:resource`)
    if (token_count < 3 || service == NULL) {
        return ERROR_INVALID_ARN;
    }

    // Return the service name
    return service;
}

