    const char* example_arn1 = "arn:aws:ec2:us-west-2:123456789012:instance/i-1234567890abcdef0";
    const char* example_arn2 = "arn:aws:s3:::my_corporate_bucket/exampleobject.png";
    const char* invalid_arn = "invalid:format";

