    printf("Service for ARN2: %s\n", get_service_from_arn(example_arn2));  // Expected output: s3
    printf("Service for Invalid ARN: %s\n", get_service_from_arn(invalid_arn));  // Expected output: Invalid ARN

    return 0;
}

