/**
 * Function to get the service from a valid AWS ARN.
 *
 * @param arn The AWS ARN to parse.
 * @return A pointer to the service name or NULL if an error occurred.
 */
const char* get_aws_service(const char* arn) {
    // Validate the arn length
    if (arn == NULL || strlen(arn) >= MAX_ARN_LENGTH) {
        return NULL; // Invalid ARN
    }

    // Split the ARN by ':' character
    char* token;
    char* temp_arn = strdup(arn); // Duplicate the string to avoid modifying the original
    char* service = NULL;
    int section_index = 0;

    // Tokenize using ':' to extract sections
    token = strtok(temp_arn, ":");
    while (token != NULL) {
        if (section_index == 2) {
            service = strdup(token); // Get the service name
            break;
        }
        token = strtok(NULL, ":");
        section_index++;
    }

    free(temp_arn); // Clean up the duplicated string

    // If we got the service name, return it. Otherwise, return NULL for errors
    if (service != NULL) {
        return service; // The service name has been extracted
    }
    return NULL; // Invalid ARN format
}

