// Define a struct to hold the ARN components
typedef struct {
    char* partition;
    char* service;
    char* region;
    char* account_id;
    char* resource;
} arn_components;

// Function to parse the ARN and return the service
const char* parse_arn(const char* arn) {
    // Check if the ARN is valid by checking its prefix
    if (strncmp(arn, "arn:", 4) != 0) {
        return "Error: Invalid ARN format.";
    }

    // Split the ARN into its components
    char* parts[6];
    char* token = strtok((char*)arn, ":");
    int i = 0;
    while (token != NULL && i < 6) {
        parts[i] = token;
        token = strtok(NULL, ":");
        i++;
    }

    // Check if the ARN has the correct number of parts
    if (i != 6) {
        return "Error: Invalid ARN format.";
    }

    // Extract the service from the ARN components
    return parts[2];
}

