// Function to check if the string starts with "arn:"
bool starts_with_arn(const char *arn) {
    const char prefix[] = "arn:";
    return strncmp(arn, prefix, sizeof(prefix) - 1) == 0;
}

// Function to validate and parse the ARN
const char* get_aws_service_from_arn(const char *arn) {
    // Check if the string starts with "arn:"
    if (!starts_with_arn(arn)) {
        return NULL; // Not a valid ARN
    }

    // Find the first colon after "arn:" to get the partition
    const char *partition_start = arn + 4;
    const char *partition_end = strchr(partition_start, ':');
    if (partition_end == NULL) {
        return NULL; // Invalid ARN
    }
    partition_end++;

    // Find the second colon to get the service
    const char *service_end = strchr(partition_end, ':');
    if (service_end == NULL) {
        return NULL; // Invalid ARN
    }

    // Calculate the length of the service part
    size_t service_length = service_end - partition_end;

    // Allocate memory for the service part
    char *service = malloc(service_length + 1);
    if (service == NULL) {
        return NULL; // Memory allocation failed
    }

    // Copy the service part into the allocated memory
    strncpy(service, partition_end, service_length);
    service[service_length] = '\0';

    return service;
}

// Function to free the allocated memory
void free_service_name(char *service) {
    if (service != NULL) {
        free(service);
    }
}

int main() {
    const char *arn = "arn:aws:s3:us-west-2:123456789012:mybucket";
    char *service = get_aws_service_from_arn(arn);

    if (service == NULL) {
        printf("Invalid ARN\n");
    } else {
        printf("Service: %s\n", service);
        free_service_name(service); // Don't forget to free the allocated memory
    }

    return 0;
}

