int shuffleDigits(int number) {
    // Handle special cases
    if (number == 0) return 0;
    if (number < 0) return -shuffleDigits(abs(number));

    // Extract digits
    int digits[10];  // Assuming max 10 digits
    int digitCount = 0;
    int original = number;

    // Extract digits
    while (number > 0) {
        digits[digitCount++] = number % 10;
        number /= 10;
    }

    // Seed random number generator
    static int seedInitialized = 0;
    if (!seedInitialized) {
        srand(time(NULL));
        seedInitialized = 1;
    }

    // Shuffle digits using Fisher-Yates algorithm
    for (int i = digitCount - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        int temp = digits[i];
        digits[i] = digits[j];
        digits[j] = temp;
    }

    // Reconstruct number from shuffled digits
    int shuffled = 0;
    for (int i = digitCount - 1; i >= 0; i--) {
        shuffled = shuffled * 10 + digits[i];
    }

    // Preserve leading zeros
    if (shuffled == 0 && original != 0) {
        return original;
    }

    return shuffled;
}

