#include <time.h>

int shuffle_digits(int num) {
    if (num == 0) {
        return 0;
    }

    // Count the number of digits
    int temp = num;
    int digit_count = 0;
    while (temp != 0) {
        temp /= 10;
        digit_count++;
    }

    // Extract digits into an array
    int digits[digit_count];
    temp = num;
    for (int i = digit_count - 1; i >= 0; i--) {
        digits[i] = temp % 10;
        temp /= 10;
    }

    // Fisher-Yates shuffle algorithm
    srand(time(NULL)); // Seed the random number generator
    for (int i = digit_count - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        // Swap digits[i] and digits[j]
        int temp_digit = digits[i];
        digits[i] = digits[j];
        digits[j] = temp_digit;
    }

    // Reconstruct the number from shuffled digits
    int result = 0;
    for (int i = 0; i < digit_count; i++) {
        result = result * 10 + digits[i];
    }

    return result;
}

