// Helper function to count digits in an integer
int count_digits(int n) {
    if (n == 0) {
        return 1;
    }
    int count = 0;
    n = abs(n); // Handle negative numbers
    while (n > 0) {
        n /= 10;
        count++;
    }
    return count;
}

// Helper function to convert an integer to a string of digits
void int_to_digits_string(int n, char *str) {
    sprintf(str, "%d", n);
}

// Helper function to convert a string of digits back to an integer
int digits_string_to_int(const char *str) {
    return atoi(str);
}

// Function to shuffle the digits of an integer
int shuffle_digits(int n) {
    if (n == 0) {
        return 0; // Shuffling '0' results in '0'
    }

    // Seed the random number generator
    srand(time(NULL));

    // Determine if the original number was negative
    int is_negative = 0;
    if (n < 0) {
        is_negative = 1;
        n = abs(n); // Work with the absolute value
    }

    int num_digits = count_digits(n);
    char *digits_str = (char *)malloc(num_digits + 1); // +1 for null terminator
    if (digits_str == NULL) {
        perror("Memory allocation failed");
        return 0; // Or handle error appropriately
    }

    int_to_digits_string(n, digits_str);

    // Perform the Fisher-Yates shuffle
    for (int i = num_digits - 1; i > 0; i--) {
        int j = rand() % (i + 1); // Generate a random index from 0 to i
        // Swap digits_str[i] and digits_str[j]
        char temp = digits_str[i];
        digits_str[i] = digits_str[j];
        digits_str[j] = temp;
    }

    // If the first digit becomes '0' and there's more than one digit,
    // we need to re-shuffle or find a non-zero digit to put at the beginning.
    // This simple shuffle might produce leading zeros. For a robust solution
    // that avoids leading zeros (unless the original number was 0),
    // you might need a more complex re-arrangement.
    // For now, we'll accept leading zeros if they occur naturally from the shuffle.

    int shuffled_num = digits_string_to_int(digits_str);

    free(digits_str);

    // Apply the original sign
    if (is_negative) {
        shuffled_num = -shuffled_num;
    }

    return shuffled_num;
}

