#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Helper function to swap two characters
void swap(char *a, char *b) {
    char tmp = *a;
    *a = *b;
    *b = tmp;
}

// Fisher-Yates shuffle
void shuffle(char *array, int n) {
    for (int i = n-1; i > 0; --i) {
        int j = rand() % (i + 1);
        swap(&array[i], &array[j]);
    }
}

// Main function
int shuffle_digits(int num) {
    int is_negative = (num < 0);
    if (is_negative) num = -num;

    // Convert integer to string
    char digits[20]; // should be big enough for any int
    sprintf(digits, "%d", num);

    // Count digits
    int len = 0;
    while (digits[len]) len++;

    // Shuffle
    shuffle(digits, len);

    // If leading digit is '0', swap with the first non-zero digit
    if (digits[0] == '0') {
        for (int i = 1; i < len; i++) {
            if (digits[i] != '0') {
                swap(&digits[0], &digits[i]);
                break;
            }
        }
    }

    // Convert back to integer
    int res = atoi(digits);
    return is_negative ? -res : res;
}

// Example usage
int main() {
    srand(time(NULL)); // seed random number generator
    int n = 12345;
    int shuffled = shuffle_digits(n);
    printf("Original: %d, Shuffled: %d\n", n, shuffled);
    return 0;
}

