int shuffle_integer(int num) {
    // Convert the integer to a string
    char str[12]; // Enough to hold INT_MAX (10 digits + sign + null terminator)
    sprintf(str, "%d", num);

    size_t length = strlen(str);
    char* digits = (char*)malloc(length + 1);
    if (digits == NULL) {
        return 0; // Return 0 if memory allocation fails
    }

    strcpy(digits, str);

    // Shuffle the digits
    for (size_t i = 0; i < length; i++) {
        size_t j = rand() % length; // Random index to swap with
        // Swap the characters
        char temp = digits[i];
        digits[i] = digits[j];
        digits[j] = temp;
    }

    // Convert the shuffled string back to integer
    int shuffled_int = atoi(digits);

    // Free the allocated memory
    free(digits);

    return shuffled_int;
}

