    // Allocate memory for the obfuscated code (potentially larger than input)
    size_t input_len = strlen(input);
    char* obfuscated = malloc(input_len * 2 + 1);  // Extra space for potential expansion
    if (obfuscated == NULL) return NULL;

    size_t out_index = 0;
    size_t i = 0;

    while (input[i] != '\0') {
        // Obfuscation strategies:

        // 1. Hex encoding for strings
        if (input[i] == '"' || input[i] == '\'') {
            char quote = input[i];
            obfuscated[out_index++] = quote;
            i++;

            while (input[i] != quote && input[i] != '\0') {
                // Convert each character to hex
                obfuscated[out_index++] = '\\';
                obfuscated[out_index++] = 'x';

                // Convert character to two-digit hex
                sprintf(obfuscated + out_index, "%02x", (unsigned char)input[i]);
                out_index += 2;

                i++;
            }

            if (input[i] == quote) {
                obfuscated[out_index++] = quote;
                i++;
            }
        }
        // 2. Rename common variable names
        else if (strncmp(input + i, "var ", 4) == 0 || 
                 strncmp(input + i, "let ", 4) == 0 || 
                 strncmp(input + i, "const ", 6) == 0) {
            // Copy the declaration keyword
            while (input[i] != ' ') {
                obfuscated[out_index++] = input[i++];
            }
            obfuscated[out_index++] = ' ';
            i++;

            // Generate a random variable name
            obfuscated[out_index++] = '_';
            obfuscated[out_index++] = 'v';

            // Add some random characters
            for (int j = 0; j < 5; j++) {
                obfuscated[out_index++] = 'a' + (rand() % 26);
            }

            // Copy rest of the line
            while (input[i] != ';' && input[i] != '\0') {
                obfuscated[out_index++] = input[i++];
            }

            if (input[i] == ';') {
                obfuscated[out_index++] = input[i++];
            }
        }
        // 3. Whitespace and newline obfuscation
        else if (isspace(input[i])) {
            // Randomly decide whether to keep or replace whitespace
            if (rand() % 2) {
                obfuscated[out_index++] = ' ';
            }
            i++;
        }
        // 4. Basic encoding for keywords
        else if (strncmp(input + i, "function", 8) == 0) {
            // Replace 'function' with obscure alternative
            strcpy(obfuscated + out_index, "_f_");
            out_index += 3;
            i += 8;
        }
        // 5. Fallback: copy character as-is
        else {
            obfuscated[out_index++] = input[i++];
        }
    }

    // Null-terminate the string
    obfuscated[out_index] = '\0';

    return obfuscated;
}

