#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h> // For isalnum, isalpha, isdigit

// --- Constants & Configuration ---
#define INITIAL_OUTPUT_BUFFER_SIZE 1024
#define IDENTIFIER_PREFIX "_" // Prefix for obfuscated names
#define MIN_IDENTIFIER_LENGTH 3 // Only rename identifiers longer than this
                                // Helps avoid renaming very short common things
                                // that might accidentally collide or be keywords.

// --- Data Structures ---

// A node in the linked list for identifier mapping
typedef struct IdentifierMapNode {
    char *original_name;
    char *obfuscated_name;
    struct IdentifierMapNode *next;
} IdentifierMapNode;

// --- Global State for Obfuscation Process (or pass as context) ---
static IdentifierMapNode *g_identifier_map = NULL;
static int g_obf_name_counter = 0; // Counter for generating unique obfuscated names

// --- Helper Functions ---

// Appends a string to the dynamic output buffer
// Handles reallocation if needed
static void append_to_output(char **output_ptr, size_t *current_len_ptr, size_t *capacity_ptr, const char *str_to_append, size_t len_to_append) {
    if (*current_len_ptr + len_to_append + 1 > *capacity_ptr) {
        *capacity_ptr *= 2; // Double the capacity
        *output_ptr = (char *)realloc(*output_ptr, *capacity_ptr);
        if (*output_ptr == NULL) {
            fprintf(stderr, "Memory reallocation failed during obfuscation.\n");
            exit(EXIT_FAILURE);
        }
    }
    memcpy(*output_ptr + *current_len_ptr, str_to_append, len_to_append);
    *current_len_ptr += len_to_append;
    (*output_ptr)[*current_len_ptr] = '\0'; // Null-terminate
}

// Checks if a character is a valid identifier start char in JS
static bool is_js_identifier_start(char c) {
    return isalpha(c) || c == '_' || c == '$';
}

// Checks if a character is a valid identifier continuation char in JS
static bool is_js_identifier_char(char c) {
    return isalnum(c) || c == '_' || c == '$';
}

// Generate a simple unique obfuscated name (e.g., _0, _1, _2, _a, _b...)
static char* generate_obfuscated_name() {
    char temp_name[32]; // Max length for generated name
    sprintf(temp_name, "%s%d", IDENTIFIER_PREFIX, g_obf_name_counter++);
    return strdup(temp_name);
}

// Adds a new mapping to the identifier map or retrieves an existing one
static char* get_or_create_obfuscated_name(const char *original_name) {
    IdentifierMapNode *current = g_identifier_map;
    while (current != NULL) {
        if (strcmp(current->original_name, original_name) == 0) {
            return current->obfuscated_name;
        }
        current = current->next;
    }

    // Not found, create a new mapping
    IdentifierMapNode *new_node = (IdentifierMapNode *)malloc(sizeof(IdentifierMapNode));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed for identifier map node.\n");
        exit(EXIT_FAILURE);
    }
    new_node->original_name = strdup(original_name);
    new_node->obfuscated_name = generate_obfuscated_name();
    new_node->next = g_identifier_map; // Add to the beginning of the list
    g_identifier_map = new_node;

    return new_node->obfuscated_name;
}

// Frees the memory used by the identifier map
static void free_identifier_map() {
    IdentifierMapNode *current = g_identifier_map;
    IdentifierMapNode *next;
    while (current != NULL) {
        next = current->next;
        free(current->original_name);
        free(current->obfuscated_name);
        free(current);
        current = next;
    }
    g_identifier_map = NULL;
    g_obf_name_counter = 0; // Reset counter
}

// A simplified list of common JavaScript keywords and global identifiers
// We should NOT rename these.
// This list is by no means exhaustive.
static const char* js_keywords[] = {
    "abstract", "arguments", "await", "boolean", "break", "byte", "case", "catch", "char",
    "class", "const", "continue", "debugger", "default", "delete", "do", "double", "else",
    "enum", "eval", "export", "extends", "false", "final", "finally", "float", "for",
    "function", "goto", "if", "implements", "import", "in", "instanceof", "int", "interface",
    "let", "long", "native", "new", "null", "package", "private", "protected", "public",
    "return", "short", "static", "super", "switch", "synchronized", "this", "throw", "throws",
    "transient", "true", "try", "typeof", "var", "void", "volatile", "while", "with", "yield",

    // Common built-in objects/functions (partial list)
    "arguments", "Array", "Boolean", "Date", "Error", "Function", "JSON", "Math", "Number",
    "Object", "Promise", "RegExp", "String", "Symbol", "WeakMap", "WeakSet", "Map", "Set",
    "ArrayBuffer", "DataView", "Float32Array", "Float64Array", "Int8Array", "Int16Array",
    "Int32Array", "Uint8Array", "Uint8ClampedArray", "Uint16Array", "Uint32Array",
    "console", "document", "window", "globalThis", "undefined", "Infinity", "NaN",
    "alert", "confirm", "prompt", "setTimeout", "clearTimeout", "setInterval", "clearInterval",
