    "isFinite", "isNaN", "parseFloat", "parseInt",
    NULL // Sentinel
};

// Checks if an identifier is a JavaScript keyword or common built-in name
static bool is_js_keyword(const char *identifier) {
    for (int i = 0; js_keywords[i] != NULL; ++i) {
        if (strcmp(identifier, js_keywords[i]) == 0) {
            return true;
        }
    }
    return false;
}

// --- Main Obfuscation Function ---

char* obfuscate_javascript(const char* js_code) {
    if (js_code == NULL) {
        return strdup("");
    }

    size_t input_len = strlen(js_code);
    char *output = (char *)malloc(INITIAL_OUTPUT_BUFFER_SIZE);
    if (output == NULL) {
        fprintf(stderr, "Memory allocation failed for output buffer.\n");
        return NULL;
    }
    size_t current_output_len = 0;
    size_t output_capacity = INITIAL_OUTPUT_BUFFER_SIZE;
    output[0] = '\0'; // Ensure it's an empty string initially

    // Reset global state for each call
    free_identifier_map();
    g_obf_name_counter = 0;

    enum {
        NORMAL,
        IN_SINGLE_LINE_COMMENT,
        IN_MULTI_LINE_COMMENT,
        IN_SINGLE_QUOTE_STRING,
        IN_DOUBLE_QUOTE_STRING,
        IN_REGEX,
        IN_IDENTIFIER
    } state = NORMAL;

    size_t i = 0;
    while (i < input_len) {
        char c = js_code[i];
        char next_c = (i + 1 < input_len) ? js_code[i+1] : '\0';

        switch (state) {
            case NORMAL:
                // Handle comments
                if (c == '/' && next_c == '/') {
                    state = IN_SINGLE_LINE_COMMENT;
                    i += 2; continue;
                } else if (c == '/' && next_c == '*') {
                    state = IN_MULTI_LINE_COMMENT;
                    i += 2; continue;
                }
                // Handle strings
                else if (c == '\'') {
                    state = IN_SINGLE_QUOTE_STRING;
                    append_to_output(&output, &current_output_len, &output_capacity, &c, 1);
                    i++; continue;
                } else if (c == '"') {
                    state = IN_DOUBLE_QUOTE_STRING;
                    append_to_output(&output, &current_output_len, &output_capacity, &c, 1);
                    i++; continue;
                }
                // Handle regex (very basic heuristic: / not preceded by ident/number, followed by non-space)
                // This is EXTREMELY fragile and will fail in many cases.
                // A correct JS parser is needed to distinguish regexp from division.
                else if (c == '/') {
                    bool potential_regex = true;
                    // Check previous non-whitespace character
                    if (current_output_len > 0) {
                        char prev_char = output[current_output_len - 1]; // Last char added to output
                        if (is_js_identifier_char(prev_char) || isdigit(prev_char)) {
                             potential_regex = false; // Likely division
                        }
                    }
                    if (potential_regex && next_c != '\0' && next_c != ' ' && next_c != '\t' && next_c != '\n' && next_c != '*') {
                        state = IN_REGEX;
                        append_to_output(&output, &current_output_len, &output_capacity, &c, 1);
                        i++; continue;
                    }
                    // If not a regex, fall through to normal char handling
                }
                // Handle identifiers
                if (is_js_identifier_start(c)) {
                    state = IN_IDENTIFIER;
                    // Fall through to IN_IDENTIFIER state logic (common for this loop)
                } else {
                    // Handle whitespace
                    if (isspace(c)) {
                        // Keep only one space if two identifiers/tokens are separated by it
                        // Or remove completely if it's just minifying
                        // For basic minification, remove all unneeded whitespace
                        if (i > 0 && !(isspace(js_code[i-1]))) { // Only if previous char wasn't a space
                            // Add a single space if it's important (e.g. `varx` vs `var x`)
                            // For this simple version, just remove extra spaces
                            char prev_output_char = current_output_len > 0 ? output[current_output_len - 1] : '\0';
                            if (isalnum(prev_output_char) && is_js_identifier_start(next_c)) {
                                append_to_output(&output, &current_output_len, &output_capacity, " ", 1);
                            }
                        }
                        i++; continue;
                    }
                    // All other characters (operators, numbers, etc.)
                    append_to_output(&output, &current_output_len, &output_capacity, &c, 1);
                    i++; continue;
                }
                // Fallthrough from state NORMAL if it transitions to IN_IDENTIFIER
            case IN_IDENTIFIER: {
                size_t ident_start = i;
                while (i < input_len && is_js_identifier_char(js_code[i])) {
                    i++;
                }
                size_t ident_len = i - ident_start;
                char *original_ident = (char *)malloc(ident_len + 1);
                if (original_ident == NULL) {
                    fprintf(stderr, "Memory allocation failed for identifier.\n");
                    // Clean up and exit or handle error appropriately.
                    free(output);
                    free_identifier_map();
                    return NULL;
                }
                strncpy(original_ident, js_code + ident_start, ident_len);
                original_ident[ident_len] = '\0';

                if (is_js_keyword(original_ident) || ident_len < MIN_IDENTIFIER_LENGTH) {
                    append_to_output(&output, &current_output_len, &output_capacity, original_ident, ident_len);
                } else {
                    char *obfuscated_ident = get_or_create_obfuscated_name(original_ident);
                    append_to_output(&output, &current_output_len, &output_capacity, obfuscated_ident, strlen(obfuscated_ident));
                }
                free(original_ident); // Free the temporary identifier buffer
                state = NORMAL;
                continue; // Continue outer loop from new position 'i'
            }
            case IN_SINGLE_LINE_COMMENT:
                if (c == '\n') {
                    state = NORMAL;
                    // Newline might be important for script semantics, but for obfuscation, remove.
                    i++; continue;
                }
                i++; continue;
            case IN_MULTI_LINE_COMMENT:
                if (c == '*' && next_c == '/') {
                    state = NORMAL;
                    i += 2; continue;
                }
                i++; continue;
            case IN_SINGLE_QUOTE_STRING:
                append_to_output(&output, &current_output_len, &output_capacity, &c, 1);
                if (c == '\\' && next_c != '\0') { // Handle escaped quote
                    append_to_output(&output, &current_output_len, &output_capacity, &next_c, 1);
                    i++; // Skip the escaped character
                } else if (c == '\'') {
                    state = NORMAL;
                }
                i++; continue;
            case IN_DOUBLE_QUOTE_STRING:
                append_to_output(&output, &current_output_len, &output_capacity, &c, 1);
                if (c == '\\' && next_c != '\0') { // Handle escaped quote
                    append_to_output(&output, &current_output_len, &output_capacity, &next_c, 1);
                    i++; // Skip the escaped character
                } else if (c == '"') {
                    state = NORMAL;
                }
                i++; continue;
            case IN_REGEX:
                append_to_output(&output, &current_output_len, &output_capacity, &c, 1);
                if (c == '\\' && next_c != '\0') { // Handle escaped slash
                    append_to_output(&output, &current_output_len, &output_capacity, &next_c, 1);
                    i++; // Skip the escaped character
                } else if (c == '/') {
                    // Check for flags immediately after regex (e.g., /pattern/gim)
                    while (i + 1 < input_len && isalpha(js_code[i+1])) {
                        append_to_output(&output, &current_output_len, &output_capacity, &js_code[i+1], 1);
                        i++;
                    }
                    state = NORMAL;
                }
                i++; continue;
        }
    }

    // Final null-termination and trimming to exact size
    output = (char *)realloc(output, current_output_len + 1);
    if (output == NULL) {
        fprintf(stderr, "Memory reallocation failed for final output trim.\n");
        return NULL;
    }
    output[current_output_len] = '\0';

    // Cleanup global state
    free_identifier_map();

    return output;
}

