#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_IDENT_LEN 64
#define MAX_GLOBALS 512

// Structure to store identifier renames
typedef struct {
    char original[MAX_IDENT_LEN];
    char obfuscated[MAX_IDENT_LEN];
} IdentMap;

static int is_identifier_start(char c) {
    return isalpha(c) || c == '_' || c == '$';
}

static int is_identifier_char(char c) {
    return isalnum(c) || c == '_' || c == '$';
}

// Check if a string is a reserved JS word (very basic list)
static int is_js_reserved(const char* str) {
    const char* reserved[] = {
        "var","let","const","function","if","else",
        "for","while","do","return","break","continue",
        "switch","case","default","true","false",
        "null","undefined","new","this","class",
        "export","import","from","super","extends",
        "try","catch","finally","throw","typeof",
        "in","of","with",
        NULL
    };
    for (int i=0; reserved[i]; i++)
        if (strcmp(reserved[i], str) == 0)
            return 1;
    return 0;
}

// Find or add to mapping
static const char* get_obfuscated(IdentMap *map, int *num, const char *orig) {
    for (int i = 0; i < *num; ++i)
        if (strcmp(map[i].original, orig) == 0)
            return map[i].obfuscated;

    // Add new
    snprintf(map[*num].original, MAX_IDENT_LEN, "%s", orig);
    snprintf(map[*num].obfuscated, MAX_IDENT_LEN, "_v%d", *num + 1);
    (*num)++;
    return map[*num-1].obfuscated;
}

// Hex encode string (simple)
void hex_encode_string(const char* src, char* dst) {
    *dst++ = '"';
    while (*src && *src != '"') {
        unsigned char c = *src++;
        sprintf(dst, "\\x%02x", c);
        dst += 4;
    }
    *dst++ = '"';
    *dst = 0;
}

// Main obfuscation function
char* js_obfuscate(const char* input) {
    IdentMap mapping[MAX_GLOBALS];
    int mapping_len = 0;

    size_t outcap = strlen(input)*3 + 128, outlen = 0;
    char* output = (char*)malloc(outcap);
    output[0] = 0;

    int i = 0, inside_string = 0;
    while (input[i]) {
        // Skip whitespace (replace with single space)
        if (isspace(input[i])) {
            // Avoid duplicate spaces
            if (outlen && output[outlen-1] != ' ')
                output[outlen++] = ' ';
            i++;
            continue;
        }

        // Handle identifiers
        if (is_identifier_start(input[i])) {
            char ident[MAX_IDENT_LEN] = {0};
            int j = 0;
            while (is_identifier_char(input[i]) && j < MAX_IDENT_LEN-1) {
                ident[j++] = input[i++];
            }
            ident[j] = 0;

            if (!is_js_reserved(ident)) {
                // Replace identifier
                const char* obf = get_obfuscated(mapping, &mapping_len, ident);
                outlen += sprintf(output+outlen, "%s", obf);
            } else {
                outlen += sprintf(output+outlen, "%s", ident);
            }
            continue;
        }

        // String literal
        if (input[i] == '"' || input[i] == '\'') {
            char quote = input[i];
            size_t s = i;
            output[outlen++] = input[i++];
            // Copy string literal and obfuscate inner content with hex
            char inner[MAX_IDENT_LEN*4] = {0};
            int inlen = 0;
            while (input[i] && input[i] != quote) {
                if (input[i] == '\\' && input[i+1]) {
                    inner[inlen++] = input[i++];
                }
                inner[inlen++] = input[i++];
            }
            inner[inlen] = 0;
            if (inlen) {
                // Hex encode here (optional, can just copy)
                char hexed[MAX_IDENT_LEN*6];
                hex_encode_string(inner, hexed);
                // Remove quotes from both sides (since we already put it)
                for (size_t k = 1; hexed[k] && hexed[k] != '"'; ++k)
                    output[outlen++] = hexed[k];
            }
            if (input[i] == quote) {
                output[outlen++] = quote;
                i++;
            }
            continue;
        }

        // Copy other chars
        output[outlen++] = input[i++];
    }

    output[outlen] = 0;
    return output;
}

