#define MAX_VAR_NAME 256

// Function prototypes
char *obfuscateJS(const char *input);
void renameVariables(char *code);
void removeWhitespace(char *code);

int main() {
    const char *jsCode = "function example() { var x = 10; var y = 20; var sum = x + y; console.log(sum); }";
    char *obfuscatedCode = obfuscateJS(jsCode);
    printf("Original JS Code:\n%s\n", jsCode);
    printf("Obfuscated JS Code:\n%s\n", obfuscatedCode);
