// Function to obfuscate JavaScript code
char *obfuscateJS(const char *input) {
    char *code = strdup(input);
    if (code == NULL) {
        fprintf(stderr, "Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }
    renameVariables(code);
    removeWhitespace(code);
    return code;
}

// Function to rename variables to obfuscated names
void renameVariables(char *code) {
    char originalVars[][MAX_VAR_NAME] = {"x", "y", "sum"};
    char obfuscatedVars[][MAX_VAR_NAME] = {"a", "b", "c"};

    for (int i = 0; i < 3; i++) {
        char *pos = strstr(code, originalVars[i]);
        while (pos != NULL) {
            // Replace the variable name
            strncpy(pos, obfuscatedVars[i], strlen(originalVars[i]));
            pos = strstr(pos + strlen(obfuscatedVars[i]), originalVars[i]);
        }
    }
}

// Function to remove unnecessary whitespace
void removeWhitespace(char *code) {
    char *src = code, *dst = code;
    int inString = 0;

    while (*src) {
        if (*src == '"' || *src == '\'') {
            inString = !inString;
        }

        if (!inString && isspace(*src)) {
            src++;
            continue;
        }

        *dst++ = *src++;
    }
    *dst = '\0';
}

