// Function to check if a year is a leap year
bool isLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

// Function to get the number of days in a month
int getDaysInMonth(int month, int year) {
    int daysInMonth[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

    if (month == 2 && isLeapYear(year)) {
        return 29;
    }

    return daysInMonth[month - 1];
}

// Function to calculate total days from a reference date (e.g., January 1st, 0000)
int getTotalDays(int day, int month, int year) {
    int totalDays = 0;

    // Calculate days for years
    for (int y = 0; y < year; y++) {
        totalDays += isLeapYear(y) ? 366 : 365;
    }

    // Add days for months in the current year
    for (int m = 1; m < month; m++) {
        totalDays += getDaysInMonth(m, year);
    }

    // Add days in the current month
    totalDays += day;

    return totalDays;
}

// Function to calculate days between two dates
int daysBetweenDates(int day1, int month1, int year1, 
                     int day2, int month2, int year2) {
    // Validate input dates
    if (year1 < 0 || year2 < 0 || 
        month1 < 1 || month1 > 12 || 
        month2 < 1 || month2 > 12 || 
        day1 < 1 || day1 > getDaysInMonth(month1, year1) || 
        day2 < 1 || day2 > getDaysInMonth(month2, year2)) {
        return -1;  // Invalid date
    }

    // Calculate total days for both dates
    int totalDays1 = getTotalDays(day1, month1, year1);
    int totalDays2 = getTotalDays(day2, month2, year2);

    // Return absolute difference
    return abs(totalDays2 - totalDays1);
}

