    int total = 0;

    // Add days from years
    for (int y = 0; y < date.year; y++) {
        total += isLeapYear(y) ? 366 : 365;
    }

    // Add days from months
    for (int m = 1; m < date.month; m++) {
        total += daysInMonth(m, date.year);
