//     int day;   // 1-31
// } Date;

/*
 * Calculates the number of days between two dates.
 *
 * @param date1_tm A pointer to a struct tm representing the first date.
 *                 The tm_year, tm_mon, and tm_mday fields should be set.
 *                 tm_year is years since 1900.
 *                 tm_mon is 0-11.
 *                 tm_mday is 1-31.
 * @param date2_tm A pointer to a struct tm representing the second date.
 *                 Same field requirements as date1_tm.
 * @return The absolute number of days between the two dates.
 *         Returns -1 if there's an error converting a date (e.g., invalid date).
 */
long days_between_dates(const struct tm *date1_tm, const struct tm *date2_tm) {
    // Make copies to avoid modifying the original struct tm objects
    struct tm temp_date1 = *date1_tm;
    struct tm temp_date2 = *date2_tm;

    // Normalize the struct tm objects using mktime
    // mktime populates other fields (wday, yday, isdst) and normalizes
    // the date if month/day is out of range. It converts the tm structure
    // to a time_t value (seconds since epoch).
    time_t time1 = mktime(&temp_date1);
    time_t time2 = mktime(&temp_date2);

    // Check for errors during mktime conversion
    if (time1 == (time_t)-1 || time2 == (time_t)-1) {
        fprintf(stderr, "Error: Invalid date provided to days_between_dates.\n");
        return -1; // Indicate an error
    }

    // Calculate the difference in seconds
    double diff_seconds = difftime(time1, time2);

    // Convert seconds to days.
    // There are 60 seconds/minute * 60 minutes/hour * 24 hours/day = 86400 seconds/day.
    // We use long long for the result and cast to avoid potential precision
    // issues with floating-point when taking the absolute value.
    long long diff_days = (long long)(diff_seconds / (60 * 60 * 24));

    // Return the absolute difference in days
    return (long)labs(diff_days);
}

