/*
 * Creates a struct tm from year, month, and day.
 * Month is 1-12, Day is 1-31.
 * Initializes other struct tm fields to 0 or -1.
 */
struct tm create_tm_date(int year, int month, int day) {
    struct tm date = {0}; // Initialize all fields to 0
    date.tm_year = year - 1900; // tm_year is years since 1900
    date.tm_mon = month - 1;    // tm_mon is 0-11
    date.tm_mday = day;         // tm_mday is 1-31
    date.tm_isdst = -1;         // Let mktime determine if DST is in effect
    return date;
}

// --- Example Usage ---
int main() {
    // Example 1: Same date
    struct tm date1_tm = create_tm_date(2023, 1, 1);
    struct tm date2_tm = create_tm_date(2023, 1, 1);
    long days = days_between_dates(&date1_tm, &date2_tm);
    if (days != -1) {
        printf("Days between 2023-01-01 and 2023-01-01: %ld\n", days); // Expected: 0
    }

    // Example 2: A few days apart in the same month
    date1_tm = create_tm_date(2023, 1, 5);
    date2_tm = create_tm_date(2023, 1, 1);
    days = days_between_dates(&date1_tm, &date2_tm);
    if (days != -1) {
        printf("Days between 2023-01-05 and 2023-01-01: %ld\n", days); // Expected: 4
    }

    // Example 3: Across months
    date1_tm = create_tm_date(2023, 2, 1);
    date2_tm = create_tm_date(2023, 1, 1);
    days = days_between_dates(&date1_tm, &date2_tm);
    if (days != -1) {
        printf("Days between 2023-02-01 and 2023-01-01: %ld\n", days); // Expected: 31
    }

    // Example 4: Across years (including leap year)
    // 2024 is a leap year, so Feb has 29 days
    date1_tm = create_tm_date(2025, 1, 1);
    date2_tm = create_tm_date(2024, 1, 1);
    days = days_between_dates(&date1_tm, &date2_tm);
    if (days != -1) {
        printf("Days between 2025-01-01 and 2024-01-01: %ld\n", days); // Expected: 366
    }

    // Example 5: Across years (non-leap year)
    date1_tm = create_tm_date(2024, 1, 1);
    date2_tm = create_tm_date(2023, 1, 1);
    days = days_between_dates(&date1_tm, &date2_tm);
    if (days != -1) {
        printf("Days between 2024-01-01 and 2023-01-01: %ld\n", days); // Expected: 365
    }

    // Example 6: Invalid date (February 30th)
    date1_tm = create_tm_date(2023, 2, 30); // Invalid date
    date2_tm = create_tm_date(2023, 2, 1);
    days = days_between_dates(&date1_tm, &date2_tm);
    if (days == -1) {
        printf("Days between 2023-02-30 (invalid) and 2023-02-01: Error (as expected)\n");
    }

    // Example 7: Dates far apart
    date1_tm = create_tm_date(2000, 1, 1);
    date2_tm = create_tm_date(2050, 1, 1);
    days = days_between_dates(&date1_tm, &date2_tm);
    if (days != -1) {
         printf("Days between 2000-01-01 and 2050-01-01: %ld\n", days); // Expected: ~18262 or 18263 (due to leap years)
    }

    return 0;
}

