// Helper function to fill a struct tm with date values
void fill_tm_struct(struct tm *date, int year, int month, int day) {
    date->tm_year = year - 1900;
    date->tm_mon = month - 1; // tm_mon is 0-based
    date->tm_mday = day;
    date->tm_hour = 0;
    date->tm_min = 0;
    date->tm_sec = 0;
    date->tm_isdst = -1; // Not considering daylight saving time
}

// Returns the absolute number of days between two dates
int days_between_dates(int year1, int month1, int day1, int year2, int month2, int day2) {
    struct tm date1 = {0}, date2 = {0};
    fill_tm_struct(&date1, year1, month1, day1);
    fill_tm_struct(&date2, year2, month2, day2);

    time_t t1 = mktime(&date1);
    time_t t2 = mktime(&date2);

    if (t1 == (time_t)(-1) || t2 == (time_t)(-1)) {
        // Invalid date
        return -1;
    }

    double difference = difftime(t2, t1);
    int days = abs((int)(difference / (60 * 60 * 24))); // Convert seconds to days

    return days;
}

