    // Allocate memory for the result list
    int* result = (int*)malloc(size * sizeof(int));

    // Check if memory allocation was successful
    if (result == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Compare each element of the lists
    for (int i = 0; i < size; i++) {
        // If elements are different, set result to 1
        // If elements are the same, set result to 0
        result[i] = (list1[i] != list2[i]) ? 1 : 0;
    }

    return result;
}

