/**
 * @brief Compares two integer lists element by element and returns a new list
 *        where each element indicates whether the corresponding elements
 *        in the input lists differ (1) or are the same (0).
 *
 * @param list1 A pointer to the first integer list.
 * @param list2 A pointer to the second integer list.
 * @param size The number of elements in both lists. It's assumed both lists
 *             have the same size.
 * @param result A pointer to a pointer that will store the address of the
 *               newly allocated result list. This function will allocate
 *               memory for the result list.
 *
 * @return 0 if successful, -1 if memory allocation fails or if size is non-positive.
 */
int compareLists(const int *list1, const int *list2, int size, int **result) {
    if (list1 == NULL || list2 == NULL || size <= 0) {
        fprintf(stderr, "Error: Invalid input lists or non-positive size.\n");
        *result = NULL; // Ensure result is null on error
        return -1;
    }

    // Allocate memory for the result list
    *result = (int *)malloc(size * sizeof(int));
    if (*result == NULL) {
        perror("Error: Memory allocation failed for result list");
        return -1;
    }

    for (int i = 0; i < size; i++) {
        if (list1[i] != list2[i]) {
            (*result)[i] = 1; // Elements differ
        } else {
            (*result)[i] = 0; // Elements are the same
        }
    }

    return 0; // Success
}

