        for (int i = 0; i < size; i++) {
            printf("%d ", diff_result[i]);
        }
        printf("\n");

        // Remember to free the dynamically allocated memory
        free(diff_result);
        diff_result = NULL; // Set to NULL after freeing
    } else {
        printf("Failed to compare lists.\n");
    }

    int listC[] = {10, 20, 30};
    int listD[] = {10, 20, 30};
    int size2 = sizeof(listC) / sizeof(listC[0]);
