#include <stdio.h>
#include <stdlib.h>

/**
 * Compare two integer lists and return a new list where each element is 1 if the
 * corresponding elements in the input lists are different, and 0 otherwise.
 *
 * @param list1 The first integer list.
 * @param list2 The second integer list.
 * @param length1 The length of the first list.
 * @param length2 The length of the second list.
 * @return A new list where each element is 1 if the corresponding elements in the
 * input lists are different, and 0 otherwise.
 */
int* compareLists(int* list1, int* list2, int length1, int length2, int* outputLength) {
    // Find the maximum length between the two lists
    int maxLength = (length1 > length2) ? length1 : length2;

    // Allocate memory for the output list
    int* output = (int*) malloc(maxLength * sizeof(int));

    // Iterate over the range of the maximum length
    for (int i = 0; i < maxLength; i++) {
        // Check if the current index is within the bounds of both lists
        if (i < length1 && i < length2) {
            // If the elements at the current index are different, set the output to 1
            output[i] = (list1[i] != list2[i]) ? 1 : 0;
        } else {
            // If the current index is out of bounds for one of the lists, set the output to 1
            output[i] = 1;
        }
    }

    // Set the output length
    *outputLength = maxLength;

    return output;
}

int main() {
    // Example usage
    int list1[] = {1, 2, 3, 4, 5};
    int list2[] = {1, 2, 3, 6, 7, 8};
    int length1 = sizeof(list1) / sizeof(list1[0]);
    int length2 = sizeof(list2) / sizeof(list2[0]);

    int outputLength;
    int* output = compareLists(list1, list2, length1, length2, &outputLength);

    // Print the output list
    printf("Output list: ");
    for (int i = 0; i < outputLength; i++) {
        printf("%d ", output[i]);
    }
    printf("\n");

    // Free the allocated memory
    free(output);

    return 0;
}

