// Function to print byte in binary format
void print_byte_binary(uint8_t byte) {
    for (int i = 7; i >= 0; i--) {
        printf("%d", (byte >> i) & 1);
    }
    printf("\n");
}

// Comprehensive byte manipulation function
void byte_operations_demo(uint8_t input_byte) {
    printf("Original Byte: ");
    print_byte_binary(input_byte);

    // 1. Bitwise AND (&)
    uint8_t and_result = input_byte & 0b10101010;
    printf("Bitwise AND with 0b10101010:   ");
    print_byte_binary(and_result);

    // 2. Bitwise OR (|)
    uint8_t or_result = input_byte | 0b01010101;
    printf("Bitwise OR with 0b01010101:    ");
    print_byte_binary(or_result);

    // 3. Bitwise XOR (^)
    uint8_t xor_result = input_byte ^ 0b11110000;
    printf("Bitwise XOR with 0b11110000:   ");
    print_byte_binary(xor_result);

    // 4. Bitwise NOT (~)
    uint8_t not_result = ~input_byte;
    printf("Bitwise NOT:                   ");
    print_byte_binary(not_result);

    // 5. Left Shift (<<)
    uint8_t left_shift_result = input_byte << 2;
    printf("Left Shift by 2:               ");
    print_byte_binary(left_shift_result);

    // 6. Right Shift (>>)
    uint8_t right_shift_result = input_byte >> 2;
    printf("Right Shift by 2:              ");
    print_byte_binary(right_shift_result);

    // 7. Circular Left Rotation (Rotate Left)
    uint8_t rotate_left_result = (input_byte << 3) | (input_byte >> 5);
    printf("Rotate Left by 3:              ");
    print_byte_binary(rotate_left_result);

    // 8. Circular Right Rotation (Rotate Right)
    uint8_t rotate_right_result = (input_byte >> 3) | (input_byte << 5);
    printf("Rotate Right by 3:             ");
    print_byte_binary(rotate_right_result);

    // 9. Set a specific bit
    uint8_t set_bit_result = input_byte | (1 << 4);
    printf("Set bit 4:                     ");
    print_byte_binary(set_bit_result);

    // 10. Clear a specific bit
    uint8_t clear_bit_result = input_byte & ~(1 << 2);
    printf("Clear bit 2:                   ");
    print_byte_binary(clear_bit_result);

    // 11. Toggle a specific bit
    uint8_t toggle_bit_result = input_byte ^ (1 << 6);
    printf("Toggle bit 6:                  ");
    print_byte_binary(toggle_bit_result);

    // 12. Check if a specific bit is set
    int bit_5_status = (input_byte & (1 << 5)) ? 1 : 0;
    printf("Bit 5 Status: %d\n", bit_5_status);
}

int main() {
    // Demonstrate byte operations with different input values
    printf("Demonstration with 0b10110011:\n");
    byte_operations_demo(0b10110011);

    printf("\nDemonstration with 0b01010101:\n");
    byte_operations_demo(0b01010101);

    return 0;
}

#include <stdio.h>
