// Function to print binary representation of a byte
void print_binary(uint8_t byte) {
    for (int i = 7; i >= 0; i--) {
        printf("%d", (byte >> i) & 1);
    }
}

// Function to rotate left (circular left shift)
uint8_t rotate_left(uint8_t byte, unsigned int count) {
    count %= 8; // Ensure count is within 0-7
    return (byte << count) | (byte >> (8 - count));
}

// Function to rotate right (circular right shift)
uint8_t rotate_right(uint8_t byte, unsigned int count) {
    count %= 8; // Ensure count is within 0-7
    return (byte >> count) | (byte << (8 - count));
}

// Function to demonstrate all binary operations
void demonstrate_byte_operations(uint8_t a, uint8_t b) {
    printf("Input values:\n");
    printf("a = %3u (0x%02X) = ", a, a); print_binary(a); printf("\n");
    printf("b = %3u (0x%02X) = ", b, b); print_binary(b); printf("\n\n");

    // Basic bitwise operations
    printf("Bitwise operations:\n");
    printf("a & b (AND)    = "); print_binary(a & b); printf("\n");
    printf("a | b (OR)     = "); print_binary(a | b); printf("\n");
    printf("a ^ b (XOR)    = "); print_binary(a ^ b); printf("\n");
    printf("~a (NOT)       = "); print_binary(~a); printf("\n");
    printf("~b (NOT)       = "); print_binary(~b); printf("\n\n");

    // Shift operations
    printf("Shift operations (on a):\n");
    printf("a << 1         = "); print_binary(a << 1); printf("\n");
    printf("a << 2         = "); print_binary(a << 2); printf("\n");
    printf("a >> 1         = "); print_binary(a >> 1); printf("\n");
    printf("a >> 2         = "); print_binary(a >> 2); printf("\n\n");

    // Rotation operations
    printf("Rotation operations (on a):\n");
    printf("rotate_left(a, 1)  = "); print_binary(rotate_left(a, 1)); printf("\n");
    printf("rotate_left(a, 2)  = "); print_binary(rotate_left(a, 2)); printf("\n");
    printf("rotate_right(a, 1) = "); print_binary(rotate_right(a, 1)); printf("\n");
    printf("rotate_right(a, 2) = "); print_binary(rotate_right(a, 2)); printf("\n\n");

    // Compound operations
    printf("Compound operations:\n");
    printf("a & ~b         = "); print_binary(a & ~b); printf("\n");
    printf("(a ^ b) & 0x0F = "); print_binary((a ^ b) & 0x0F); printf("\n");
    printf("(a | b) ^ 0xFF = "); print_binary((a | b) ^ 0xFF); printf("\n");
}

