#include <stdio.h>
#include <limits.h> // For CHAR_BIT

// Helper function to print a byte in binary format
void print_byte_binary(unsigned char byte, const char* label) {
    if (label) {
        printf("%s: ", label);
    }
    for (int i = 7; i >= 0; i--) {
        printf("%d", (byte >> i) & 1);
    }
    printf(" (0x%02X, %3d)\n", byte, byte);
}

// Function to perform a left rotation on a byte
unsigned char rotate_left(unsigned char byte, unsigned int n) {
    // Ensure n is within the 0-7 range (for an 8-bit byte)
    // No need for CHAR_BIT here, bytes are typically 8 bits.
    // However, for maximum portability, using CHAR_BIT is good practice.
    n %= 8; // Or n %= CHAR_BIT;

    // Shift left and OR with bits that wrapped around from the left
    return (byte << n) | (byte >> (8 - n)); // Or (CHAR_BIT - n)
}

// Function to perform a right rotation on a byte
unsigned char rotate_right(unsigned char byte, unsigned int n) {
    // Ensure n is within the 0-7 range (for an 8-bit byte)
    n %= 8; // Or n %= CHAR_BIT;

    // Shift right and OR with bits that wrapped around from the right
    return (byte >> n) | (byte << (8 - n)); // Or (CHAR_BIT - n)
}


void showcase_byte_binary_operations(unsigned char val1, unsigned char val2, unsigned int shift_amount) {
    printf("--- Showcasing Binary Operations on Bytes ---\n");

    // Input values
    print_byte_binary(val1, "Operand 1 (val1)");
    print_byte_binary(val2, "Operand 2 (val2)");
    printf("Shift/Rotation Amount : %u\n", shift_amount);
    printf("---------------------------------------------\n\n");

    unsigned char result;

    // 1. Bitwise AND (&)
    result = val1 & val2;
    print_byte_binary(result, "val1 & val2      (AND)");

    // 2. Bitwise OR (|)
    result = val1 | val2;
    print_byte_binary(result, "val1 | val2       (OR)");

    // 3. Bitwise XOR (^)
    result = val1 ^ val2;
    print_byte_binary(result, "val1 ^ val2      (XOR)");

    // 4. Bitwise NOT (~)
    result = ~val1; // Note: Tilde applies to the type, so it'll be 0xFF if val1 is 0
    print_byte_binary(result, "~val1            (NOT/Complement)");
    result = ~val2;
    print_byte_binary(result, "~val2            (NOT/Complement)");

    printf("\n--- Bit Shifts ---\n");

    // 5. Left Shift (<<)
    // Be careful with shift_amount >= CHAR_BIT (or 8 for byte) - behavior is undefined
    // We assume shift_amount is < 8 for this example.
    result = val1 << shift_amount;
    print_byte_binary(result, "val1 << shift_amount (Left Shift)");

    // 6. Right Shift (>>)
    // For unsigned types, right shift is always logical (fills with 0s)
    result = val1 >> shift_amount;
    print_byte_binary(result, "val1 >> shift_amount (Right Shift)");

    printf("\n--- Bit Rotations (Custom Functions) ---\n");

    // 7. Left Rotation
    result = rotate_left(val1, shift_amount);
    print_byte_binary(result, "val1 Rol shift_amount (Left Rotate)");

    // 8. Right Rotation
    result = rotate_right(val1, shift_amount);
    print_byte_binary(result, "val1 Ror shift_amount (Right Rotate)");

    printf("\n--- End of Showcase ---\n\n");
}

int main() {
