    showcase_byte_binary_operations(0b11001100, 0b00110011, 2);

    // Example 2: Another set of values
    showcase_byte_binary_operations(0x5A, 0xA5, 3); // 01011010 and 10100101

    // Example 3: Edge case for NOT and shifts
    showcase_byte_binary_operations(0x00, 0xFF, 1);

    // Example 4: Shifts by 0 and max (7)
    showcase_byte_binary_operations(0b10101010, 0b01010101, 0);
    showcase_byte_binary_operations(0b10101010, 0b01010101, 7);

