// Function to print a byte in binary format
void print_binary(uint8_t byte) {
    for (int i = 7; i >= 0; --i) {
        printf("%d", (byte >> i) & 1);
    }
    printf(" ");
}

// Function to rotate left a byte by n positions
uint8_t rotate_left(uint8_t byte, int n) {
    return (byte << n) | (byte >> (8 - n));
}

// Function to rotate right a byte by n positions
uint8_t rotate_right(uint8_t byte, int n) {
    return (byte >> n) | (byte << (8 - n));
}

