// Structure to represent a particle
typedef struct {
    double x;  // x-coordinate
    double y;  // y-coordinate
    double z;  // z-coordinate
    double vx; // velocity in x direction
    double vy; // velocity in y direction
    double vz; // velocity in z direction
} Particle;

// Function to generate random normally distributed number (Box-Muller transform)
double gaussian_random(double mean, double std_dev) {
    static int have_spare = 0;
    static double spare;

    if (have_spare) {
        have_spare = 0;
        return mean + std_dev * spare;
    }

    have_spare = 1;

    double u1, u2, v1, v2, s;
    do {
        u1 = rand() / ((double) RAND_MAX);
        u2 = rand() / ((double) RAND_MAX);

        v1 = 2 * u1 - 1;
        v2 = 2 * u2 - 1;

        s = v1 * v1 + v2 * v2;
    } while (s >= 1 || s == 0);

    s = sqrt(-2.0 * log(s) / s);

    spare = v2 * s;
    return mean + std_dev * v1 * s;
}

// Simulate Brownian motion for multiple particles
void simulate_brownian_motion(
    Particle* particles,     // Array of particles
    int num_particles,       // Number of particles
    double dt,               // Time step
    double diffusion_coeff,  // Diffusion coefficient
    int num_steps            // Number of simulation steps
) {
    // Initialize random seed
    srand(time(NULL));

    // Simulation loop
    for (int step = 0; step < num_steps; step++) {
        // Update each particle
        for (int i = 0; i < num_particles; i++) {
            // Compute random displacement using Gaussian distribution
            double dx = gaussian_random(0, sqrt(2 * diffusion_coeff * dt));
            double dy = gaussian_random(0, sqrt(2 * diffusion_coeff * dt));
            double dz = gaussian_random(0, sqrt(2 * diffusion_coeff * dt));

            // Update particle position
            particles[i].x += dx;
            particles[i].y += dy;
            particles[i].z += dz;

            // Update particle velocity (optional)
            particles[i].vx = dx / dt;
            particles[i].vy = dy / dt;
            particles[i].vz = dz / dt;
        }
    }
}

