void simulate_brownian_motion(int num_particles, int num_steps, double step_size) {
    // Seed the random number generator
    srand(time(NULL));

    // Allocate memory for particles
    Particle* particles = (Particle*)malloc(num_particles * sizeof(Particle));

    // Initialize all particles at origin (0,0)
    for (int i = 0; i < num_particles; i++) {
        particles[i].x = 0.0;
        particles[i].y = 0.0;
    }

    // Simulation loop
    for (int step = 0; step < num_steps; step++) {
        for (int i = 0; i < num_particles; i++) {
            // Generate random angle between 0 and 2π
            double angle = 2.0 * M_PI * ((double)rand() / RAND_MAX);

            // Update position based on random walk
            particles[i].x += step_size * cos(angle);
            particles[i].y += step_size * sin(angle);

            // Optional: Print particle positions (can be commented out for large simulations)
            // printf("Particle %d at step %d: (%.2f, %.2f)\n", i, step, particles[i].x, particles[i].y);
