#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

// Structure to represent a particle
typedef struct {
    double x;
    double y;
} Particle;

// Function to generate a random number from a standard normal distribution (mean=0, stddev=1)
// Using Box-Muller transform for better random number generation.
// This function returns two random numbers; we'll keep one for simplicity,
// or you can modify it to return both if you need them efficiently.
double rand_normal() {
    static int have_spare = 0;
    static double spare_val;

    if (have_spare) {
        have_spare = 0;
        return spare_val;
    }

    have_spare = 1;
    double u1, u2, s;
    do {
        u1 = rand() / (RAND_MAX + 1.0);
        u2 = rand() / (RAND_MAX + 1.0);
        s = u1 * u1 + u2 * u2;
    } while (s >= 1.0 || s == 0.0);

    double multiplier = sqrt(-2.0 * log(s) / s);
    spare_val = u2 * multiplier;
    return u1 * multiplier;
}

/**
 * @brief Simulates Brownian motion for a given number of particles.
 *        The particle positions are updated in place.
 *
 * @param particles An array of Particle structures. Each particle's initial
 *                  position should be set before calling this function.
 * @param num_particles The number of particles to simulate.
 * @param num_steps The total number of simulation steps.
 * @param dt The time step size (delta t).
 * @param diffusion_coefficient The diffusion coefficient (D). This affects
 *                            the magnitude of random movement.
 * @param history_filename (Optional) If not NULL, particle positions at each
 *                         step will be written to this file.
 *                         Format: step_idx, particle_idx, x, y
 */
void simulate_brownian_motion(Particle *particles, int num_particles,
                              int num_steps, double dt,
                              double diffusion_coefficient,
                              const char *history_filename) {
    if (particles == NULL || num_particles <= 0 || num_steps <= 0 || dt <= 0 || diffusion_coefficient < 0) {
        fprintf(stderr, "Error: Invalid parameters for simulate_brownian_motion.\n");
        return;
    }

    // Seed the random number generator only once
    srand((unsigned int)time(NULL));

    FILE *history_file = NULL;
    if (history_filename != NULL) {
        history_file = fopen(history_filename, "w");
        if (history_file == NULL) {
            fprintf(stderr, "Warning: Could not open history file '%s' for writing.\n", history_filename);
        } else {
            fprintf(history_file, "step,particle_id,x,y\n"); // CSV header
        }
    }

    // Calculate the standard deviation for the displacement in one step for each coordinate
    // For a 2D random walk, the mean squared displacement <r^2> = 4 * D * t
    // The displacement in one dimension is normally distributed with mean 0 and variance 2 * D * dt
    double stddev_per_step = sqrt(2.0 * diffusion_coefficient * dt);

    printf("Starting Brownian motion simulation for %d particles over %d steps.\n", num_particles, num_steps);
    printf("Time step (dt): %.4f, Diffusion Coefficient (D): %.4f\n", dt, diffusion_coefficient);
    printf("Standard deviation per step (x or y): %.6f\n", stddev_per_step);

    for (int step = 0; step < num_steps; ++step) {
        if (step % (num_steps / 10 + 1) == 0) { // Print progress
            printf("Simulating step %d/%d (%.1f%%)\n", step, num_steps, (double)step * 100 / num_steps);
        }

        for (int i = 0; i < num_particles; ++i) {
            // Generate random displacements for x and y using the normal distribution
            double dx = rand_normal() * stddev_per_step;
            double dy = rand_normal() * stddev_per_step;

            // Update particle position
            particles[i].x += dx;
            particles[i].y += dy;

            // Record history if file is open
            if (history_file != NULL) {
                fprintf(history_file, "%d,%d,%.6f,%.6f\n", step, i, particles[i].x, particles[i].y);
            }
        }
    }

    if (history_file != NULL) {
        fclose(history_file);
        printf("Simulation history written to '%s'.\n", history_filename);
    }

    printf("Brownian motion simulation completed.\n");
}


