// Generates a standard normal random number using Box-Muller transform
double randn() {
    static int haveSpare = 0;
    static double spare;

    if(haveSpare)
    {
        haveSpare = 0;
        return spare;
    }

    haveSpare = 1;
    double u, v, s;
    do {
        u = (rand() / ((double) RAND_MAX)) * 2.0 - 1.0;
        v = (rand() / ((double) RAND_MAX)) * 2.0 - 1.0;
        s = u * u + v * v;
    } while( s >= 1.0 || s == 0.0 );
    s = sqrt(-2.0 * log(s) / s);
    spare = v * s;
    return u * s;
}

// Simulates Brownian motion
void simulate_brownian(int particles, int nsteps, double step_std, double *x, double *y) {
    // Assume x and y are arrays of length [particles], initial positions
    for (int i = 0; i < particles; ++i) {
        x[i] = 0.0;
        y[i] = 0.0;
    }

    for (int t = 0; t < nsteps; ++t) {
        for (int i = 0; i < particles; ++i) {
            x[i] += randn() * step_std;
            y[i] += randn() * step_std;
        }
    }
}

