// Function to generate a random number from a normal (Gaussian) distribution
double random_normal(double mean, double std_dev) {
    double u1, u2, z;
    do {
        u1 = (double)rand() / RAND_MAX;
        u2 = (double)rand() / RAND_MAX;
    } while (u1 <= 1e-5); // Avoid log(0) and division by zero

    z = sqrt(-2.0 * log(u1)) * cos(2.0 * M_PI * u2);
    return z * std_dev + mean;
}

// Function to simulate Brownian motion for a given number of particles
void simulate_brownian_motion(int particles, int steps, double dt, double diffusion_coefficient) {
    // Seed the random number generator
    srand(time(0));

    // Allocate memory for particle positions
    double *x = (double *)malloc(particles * sizeof(double));
    double *y = (double *)malloc(particles * sizeof(double));

    // Initialize particle positions to the origin (0, 0)
    for (int i = 0; i < particles; i++) {
        x[i] = 0.0;
        y[i] = 0.0;
    }

    // Simulate Brownian motion
    for (int step = 0; step < steps; step++) {
        for (int i = 0; i < particles; i++) {
            // Generate random displacements
            double dx = random_normal(0.0, sqrt(2.0 * diffusion_coefficient * dt));
            double dy = random_normal(0.0, sqrt(2.0 * diffusion_coefficient * dt));

            // Update positions
            x[i] += dx;
            y[i] += dy;
        }

        // Optionally, print the positions at each time step
        if (step % 100 == 0) { // Print every 100 steps for example
            printf("Step %d:\n", step);
            for (int i = 0; i < particles; i++) {
                printf("Particle %d: (x = %f, y = %f)\n", i, x[i], y[i]);
            }
        }
    }

    // Free allocated memory
    free(x);
    free(y);
}

