// Comparison function for lexicographical comparison of sublists
int compare_sublists(int* list1, int* list2, int list_length) {
    for (int i = 0; i < list_length; i++) {
        if (list1[i] < list2[i]) return -1;  // list1 comes first
        if (list1[i] > list2[i]) return 1;   // list2 comes first
    }
    return 0;  // lists are identical
}

// Swap two rows in the 2D array
void swap_rows(int** arr, int row1, int row2, int list_length) {
    int* temp = arr[row1];
    arr[row1] = arr[row2];
    arr[row2] = temp;
}

// Lexicographical sort function using bubble sort
void lexicographical_sort(int** arr, int num_lists, int list_length) {
    // Bubble sort 
    for (int i = 0; i < num_lists - 1; i++) {
        for (int j = 0; j < num_lists - i - 1; j++) {
            // Compare adjacent sublists
            int comparison = compare_sublists(arr[j], arr[j+1], list_length);

            // If the current list should come after the next list, swap them
            if (comparison > 0) {
                swap_rows(arr, j, j+1, list_length);
            }
        }
    }
}

