// Function to compare two sublists lexicographically
int compare_sublists(const void *a, const void *b) {
    int *sublist_a = *(int **)a;
    int *sublist_b = *(int **)b;

    int i = 0;
    while (sublist_a[i] != -1 && sublist_b[i] != -1) { // Assuming -1 marks the end of a sublist
        if (sublist_a[i] < sublist_b[i]) {
            return -1;
        } else if (sublist_a[i] > sublist_b[i]) {
            return 1;
        }
        i++;
    }

    // If one sublist is a prefix of the other, the shorter one comes first
    if (sublist_a[i] == -1 && sublist_b[i] != -1) {
        return -1;
    } else if (sublist_b[i] == -1 && sublist_a[i] != -1) {
        return 1;
    }

    return 0; // Both sublists are equal
}

// Function to sort a 2D array in lexicographical order
void sort_2d_array(int **array, int num_sublists) {
    qsort(array, num_sublists, sizeof(int *), compare_sublists);
}

