// And each sublist has a fixed length

typedef struct {
    int* data;
    size_t length; // Length of the sublist
} Sublist;

// Comparison function for qsort
// Lexicographical comparison of two Sublist structures
// Returns:
//   < 0 if sublist_a comes before sublist_b
//   > 0 if sublist_a comes after sublist_b
//     0 if sublist_a and sublist_b are identical up to the length of the shorter one
int compareLexicographical(const void* a, const void* b) {
    const Sublist* sublist_a = (const Sublist*)a;
    const Sublist* sublist_b = (const Sublist*)b;

    size_t min_length = (sublist_a->length < sublist_b->length) ? sublist_a->length : sublist_b->length;

    for (size_t i = 0; i < min_length; ++i) {
        if (sublist_a->data[i] < sublist_b->data[i]) {
            return -1;
        } else if (sublist_a->data[i] > sublist_b->data[i]) {
            return 1;
        }
    }

    // If we reached here, all common elements are equal.
    // The shorter list comes first.
    if (sublist_a->length < sublist_b->length) {
        return -1;
    } else if (sublist_a->length > sublist_b->length) {
        return 1;
    } else {
        // Both lists are identical
        return 0;
    }
}

// Function to sort a list of lists of integers
// list_of_lists: An array of Sublist structures
// num_sublists: The number of sublists in the list_of_lists
void sortListOfLists(Sublist* list_of_lists, size_t num_sublists) {
    qsort(list_of_lists, num_sublists, sizeof(Sublist), compareLexicographical);
}

