// Compares two integer arrays lexicographically
int compare(const int* a, const int* b, int len) {
    for (int i = 0; i < len; ++i) {
        if (a[i] < b[i]) return -1;
        if (a[i] > b[i]) return 1;
    }
    return 0;
}

// Swaps two integer arrays of length len
void swap(int* a, int* b, int len) {
    for (int i = 0; i < len; ++i) {
        int tmp = a[i];
        a[i] = b[i];
        b[i] = tmp;
    }
}

// Sorts a 2D array lexicographically
void lexsort(int** arr, int N, int M) {
    for (int i = 0; i < N-1; ++i) {
        for (int j = i+1; j < N; ++j) {
            if (compare(arr[i], arr[j], M) > 0) {
                swap(arr[i], arr[j], M);
            }
        }
    }
}

