// Function to compare two arrays (sublists)
int compare(const void *a, const void *b) {
    const char **listA = *(const char ***)a;
    const char **listB = *(const char ***)b;

    // Compare elements of the sublists
    while (*listA && *listB) {
        int cmp = strcmp(*listA, *listB);
        if (cmp != 0) {
            return cmp;
        }
        listA++;
        listB++;
    }

    // If we reached the end of one of the sublists, 
    // the shorter sublist should come first.
    return (*listA == NULL) ? -1 : 1;
}

