// Function to compare two sublists
int compare_sublists(int **sublist1, int **sublist2, int *length1, int *length2) {
    int min_length = (*length1 < *length2)? *length1 : *length2;
    for (int i = 0; i < min_length; i++) {
        if ((*sublist1)[i] < (*sublist2)[i]) {
            return -1;
        } else if ((*sublist1)[i] > (*sublist2)[i]) {
            return 1;
        }
    }
    // If all elements are equal, the shorter sublist is considered smaller
    if (*length1 < *length2) {
        return -1;
    } else if (*length1 > *length2) {
        return 1;
    } else {
        return 0;
    }
}

// Swap function for two sublists
void swap_sublists(int **sublist1, int **sublist2, int *length1, int *length2) {
    int *temp = *sublist1;
    *sublist1 = *sublist2;
    *sublist2 = temp;
    int temp_length = *length1;
    *length1 = *length2;
    *length2 = temp_length;
}

// Bubble sort function for sorting sublists
void lexicographical_sort(int **sublists, int *lengths, int num_sublists) {
    for (int i = 0; i < num_sublists - 1; i++) {
        for (int j = 0; j < num_sublists - i - 1; j++) {
            if (compare_sublists(&sublists[j], &sublists[j + 1], &lengths[j], &lengths[j + 1]) > 0) {
                swap_sublists(&sublists[j], &sublists[j + 1], &lengths[j], &lengths[j + 1]);
            }
        }
    }
}

