// Function to create a dynamically allocated matrix (nxm)
// Initializes elements to 0 for safety, but caller will populate.
int** createMatrix(int rows, int cols) {
    if (rows <= 0 || cols <= 0) {
        fprintf(stderr, "Error: Matrix dimensions must be positive.\n");
        return NULL;
    }

    int** matrix = (int**)malloc(rows * sizeof(int*));
    if (matrix == NULL) {
        fprintf(stderr, "Error: Memory allocation failed for matrix rows.\n");
        return NULL;
    }

    for (int i = 0; i < rows; i++) {
        matrix[i] = (int*)malloc(cols * sizeof(int));
        if (matrix[i] == NULL) {
            fprintf(stderr, "Error: Memory allocation failed for matrix column %d.\n", i);
            // Free previously allocated rows before returning
            for (int j = 0; j < i; j++) {
                free(matrix[j]);
            }
            free(matrix);
            return NULL;
        }
    }
    return matrix;
}

// Function to print a matrix
void printMatrix(int** matrix, int rows, int cols, const char* name) {
    if (matrix == NULL) {
        printf("%s is NULL (empty).\n", name);
        return;
