    if (rows <= 0 || cols <= 0) {
        printf("%s is empty or has invalid dimensions.\n", name);
        return;
    }

    printf("\n%s (%dx%d):\n", name, rows, cols);
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            printf("%4d ", matrix[i][j]); // Adjust %4d for spacing
        }
        printf("\n");
    }
}

// Function to free the memory allocated for a matrix
void freeMatrix(int** matrix, int rows) {
    if (matrix == NULL) {
        return;
    }
    for (int i = 0; i < rows; i++) {
        free(matrix[i]);
    }
    free(matrix);
}

/**
 * @brief Transposes a given matrix.
 *
 * This function takes a dynamically allocated matrix, its number of rows,
 * and its number of columns, and returns a new dynamically allocated matrix
 * representing its transpose.
 *
 * @param matrix The original matrix (pointer to pointer to int).
 * @param rows The number of rows in the original matrix.
 * @param cols The number of columns in the original matrix.
 * @return A new dynamically allocated matrix (its transpose), or NULL if
 *         memory allocation fails or input is invalid.
 *         The caller is responsible for freeing the returned matrix using freeMatrix().
 */
int** transposeMatrix(int** matrix, int rows, int cols) {
    // Basic validation
    if (matrix == NULL || rows <= 0 || cols <= 0) {
        fprintf(stderr, "Error: Invalid input matrix or dimensions for transpose.\n");
        return NULL;
    }

    // The transposed matrix will have 'cols' rows and 'rows' columns
    int newRows = cols;
    int newCols = rows;

    // Allocate memory for the transposed matrix
    int** transposedMatrix = createMatrix(newRows, newCols);
    if (transposedMatrix == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for transposed matrix.\n");
        return NULL; // createMatrix already printed error
    }

    // Populate the transposed matrix
    for (int i = 0; i < rows; i++) {       // Iterate through original rows
        for (int j = 0; j < cols; j++) {   // Iterate through original columns
            transposedMatrix[j][i] = matrix[i][j]; // Swap indices
        }
    }

    return transposedMatrix;
}

