// Transpose an n x m matrix.
// 'matrix' is a pointer to an array of n pointers, each to an array of m ints.
// Returns a newly allocated matrix of size m x n (the transpose).
int** transpose(int** matrix, int n, int m) {
    // Allocate memory for the transpose matrix (m rows)
    int** transposed = (int**)malloc(m * sizeof(int*));
    if (!transposed) return NULL;
    for (int i = 0; i < m; ++i) {
        transposed[i] = (int*)malloc(n * sizeof(int));
        if (!transposed[i]) {
            // Clean up previously allocated rows if allocation fails
            for (int j = 0; j < i; ++j) free(transposed[j]);
            free(transposed);
            return NULL;
        }
    }
    // Perform the transpose
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            transposed[j][i] = matrix[i][j];
        }
    }
    return transposed;
}

