#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Structure to pass arguments to thread function
typedef struct {
    int row;
    int cols_a;
    int cols_b;
    double **matrix_a;
    double **matrix_b;
    double **result_matrix;
} thread_args;

// Function to perform matrix multiplication for a single row
void* matrix_mult_thread(void* args) {
    thread_args* thread_data = (thread_args*)args;

    int row = thread_data->row;
    int cols_a = thread_data->cols_a;
    int cols_b = thread_data->cols_b;

    // Compute row of the result matrix
    for (int j = 0; j < cols_b; j++) {
        thread_data->result_matrix[row][j] = 0;

        for (int k = 0; k < cols_a; k++) {
            thread_data->result_matrix[row][j] += 
                thread_data->matrix_a[row][k] * thread_data->matrix_b[k][j];
        }
    }

    return NULL;
}

// Function to perform parallel matrix multiplication
double** parallel_matrix_multiply(
    double** matrix_a, 
    double** matrix_b, 
    int rows_a, 
    int cols_a, 
    int rows_b, 
    int cols_b, 
    int num_threads
) {
    // Check matrix multiplication compatibility
    if (cols_a != rows_b) {
        fprintf(stderr, "Matrix multiplication incompatible\n");
        return NULL;
    }

    // Limit threads to number of rows
    if (num_threads > rows_a) {
        num_threads = rows_a;
    }

    // Allocate result matrix
    double** result_matrix = malloc(rows_a * sizeof(double*));
    for (int i = 0; i < rows_a; i++) {
        result_matrix[i] = malloc(cols_b * sizeof(double));
    }

    // Create thread pool
    pthread_t* threads = malloc(num_threads * sizeof(pthread_t));
    thread_args* thread_data = malloc(num_threads * sizeof(thread_args));

    // Distribute rows among threads
    for (int i = 0; i < num_threads; i++) {
        thread_data[i].row = i;
        thread_data[i].cols_a = cols_a;
        thread_data[i].cols_b = cols_b;
        thread_data[i].matrix_a = matrix_a;
        thread_data[i].matrix_b = matrix_b;
        thread_data[i].result_matrix = result_matrix;

        pthread_create(&threads[i], NULL, matrix_mult_thread, &thread_data[i]);
    }

    // Complete remaining rows with additional threads
    for (int i = num_threads; i < rows_a; i++) {
        thread_data[i % num_threads].row = i;
        pthread_create(&threads[i % num_threads], NULL, matrix_mult_thread, &thread_data[i % num_threads]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    free(threads);
    free(thread_data);

    return result_matrix;
}

