int main() {
    // Initialize random seed
    srand(time(NULL));

    // Matrix dimensions
    int rows_a = 1000;
    int cols_a = 1000;
    int rows_b = 1000;
    int cols_b = 1000;

    // Number of threads
    int num_threads = 8;

    // Create matrices
    double** matrix_a = create_matrix(rows_a, cols_a);
    double** matrix_b = create_matrix(rows_b, cols_b);

    // Perform parallel matrix multiplication
    clock_t start = clock();
    double** result_matrix = parallel_matrix_multiply(
        matrix_a, matrix_b, 
        rows_a, cols_a, 
        rows_b, cols_b, 
        num_threads
    );
    clock_t end = clock();

    // Print execution time
    double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC;
    printf("Time taken: %f seconds\n", time_taken);

    // Free memory
    free_matrix(matrix_a, rows_a);
    free_matrix(matrix_b, rows_b);
    free_matrix(result_matrix, rows_a);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Structure to pass data to threads
typedef struct {
    double **A;
    double **B;
    double **C;
    int a_rows;
    int a_cols;
    int b_cols;
    int start_row;
    int end_row;
} thread_data_t;

// Thread function to compute a portion of the matrix multiplication
void* multiply_portion(void* arg) {
    thread_data_t* data = (thread_data_t*)arg;

    for (int i = data->start_row; i < data->end_row; i++) {
        for (int j = 0; j < data->b_cols; j++) {
            data->C[i][j] = 0;
            for (int k = 0; k < data->a_cols; k++) {
                data->C[i][j] += data->A[i][k] * data->B[k][j];
            }
        }
    }

    pthread_exit(NULL);
}

// Parallel matrix multiplication function
void parallel_matrix_multiply(double** A, double** B, double** C, 
                             int a_rows, int a_cols, int b_cols, 
                             int num_threads) {
    pthread_t* threads = malloc(num_threads * sizeof(pthread_t));
    thread_data_t* thread_data = malloc(num_threads * sizeof(thread_data_t));

    // Calculate how many rows each thread will handle
    int rows_per_thread = a_rows / num_threads;
    int extra_rows = a_rows % num_threads;

    int start_row = 0;
    for (int i = 0; i < num_threads; i++) {
        // Determine the range of rows this thread will handle
        int end_row = start_row + rows_per_thread;
        if (i < extra_rows) {
            end_row++;
        }

        // Set up thread data
        thread_data[i].A = A;
        thread_data[i].B = B;
        thread_data[i].C = C;
        thread_data[i].a_rows = a_rows;
        thread_data[i].a_cols = a_cols;
        thread_data[i].b_cols = b_cols;
        thread_data[i].start_row = start_row;
        thread_data[i].end_row = end_row;

        // Create the thread
        if (pthread_create(&threads[i], NULL, multiply_portion, &thread_data[i])) {
            fprintf(stderr, "Error creating thread\n");
            exit(EXIT_FAILURE);
        }

        start_row = end_row;
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
    free(thread_data);
}

// Helper function to allocate a matrix
double** allocate_matrix(int rows, int cols) {
    double** matrix = malloc(rows * sizeof(double*));
    for (int i = 0; i < rows; i++) {
        matrix[i] = malloc(cols * sizeof(double));
    }
    return matrix;
}

// Helper function to free a matrix
void free_matrix(double** matrix, int rows) {
    for (int i = 0; i < rows; i++) {
        free(matrix[i]);
    }
    free(matrix);
}

// Example usage
int main() {
    int a_rows = 1000, a_cols = 1000, b_cols = 1000;
    int num_threads = 4; // Number of threads to use

    // Allocate matrices
    double** A = allocate_matrix(a_rows, a_cols);
    double** B = allocate_matrix(a_cols, b_cols);
    double** C = allocate_matrix(a_rows, b_cols);

    // Initialize matrices with some values (for demonstration)
    for (int i = 0; i < a_rows; i++) {
        for (int j = 0; j < a_cols; j++) {
            A[i][j] = i + j;
        }
