        for (int j = 0; j < b_cols; j++) {
            B[i][j] = i - j;
        }
    }

    // Perform parallel matrix multiplication
    parallel_matrix_multiply(A, B, C, a_rows, a_cols, b_cols, num_threads);

    // Print some results (optional)
