    free_matrix(A, a_rows);
    free_matrix(B, a_cols);
    free_matrix(C, a_rows);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <errno.h> // For error handling

// Structure to pass data to each thread
typedef struct {
    double *A;         // Pointer to matrix A
    double *B;         // Pointer to matrix B
    double *C;         // Pointer to matrix C (result)
    int m;             // Rows of A (and C)
    int k;             // Columns of A, Rows of B
    int n;             // Columns of B (and C)
    int start_row;     // Starting row for this thread to compute
    int end_row;       // Ending row (exclusive) for this thread to compute
} ThreadData;

// Thread function for matrix multiplication
void *multiply_rows(void *arg) {
    ThreadData *data = (ThreadData *)arg;

    // Dimensions
    int m = data->m;
    int k = data->k;
    int n = data->n;

    // Pointers to matrices
    double *A = data->A;
    double *B = data->B;
    double *C = data->C;

    // Loop through the rows assigned to this thread
    for (int i = data->start_row; i < data->end_row; ++i) {
        // Loop through columns of C (and B)
        for (int j = 0; j < n; ++j) {
            double sum = 0.0;
            // Loop through columns of A (and rows of B)
            for (int l = 0; l < k; ++l) {
                sum += A[i * k + l] * B[l * n + j];
            }
            C[i * n + j] = sum;
        }
    }

    pthread_exit(NULL);
}

/**
 * @brief Performs matrix multiplication C = A * B using pthreads for parallelization.
 *
 * @param A             Pointer to the first matrix (m x k).
 * @param B             Pointer to the second matrix (k x n).
 * @param C             Pointer to the result matrix (m x n). Must be pre-allocated by the caller.
 * @param m             Number of rows in matrix A.
 * @param k             Number of columns in matrix A (and rows in matrix B).
 * @param n             Number of columns in matrix B.
 * @param num_threads   Number of threads to use for parallelization.
 *
 * @return 0 on success, -1 on invalid input, -2 on thread creation failure.
 */
int parallel_matrix_multiply(double *A, double *B, double *C,
                             int m, int k, int n, int num_threads) {

    // Input validation
    if (A == NULL || B == NULL || C == NULL) {
        fprintf(stderr, "Error: Matrix pointers cannot be NULL.\n");
        return -1;
    }
    if (m <= 0 || k <= 0 || n <= 0) {
        fprintf(stderr, "Error: Matrix dimensions must be positive.\n");
        return -1;
    }
    if (num_threads <= 0) {
        fprintf(stderr, "Error: Number of threads must be positive.\n");
        return -1;
    }

    // Adjust num_threads if it's greater than the number of rows (no point in having more threads than rows)
    if (num_threads > m) {
        // We can't assign less than one row to a thread, so cap at 'm' threads.
        num_threads = m;
    }

    pthread_t *threads = (pthread_t *)malloc(sizeof(pthread_t) * num_threads);
    if (threads == NULL) {
        perror("Failed to allocate threads array");
        return -2;
    }

    ThreadData *thread_data = (ThreadData *)malloc(sizeof(ThreadData) * num_threads);
    if (thread_data == NULL) {
        perror("Failed to allocate thread data array");
        free(threads);
        return -2;
    }

    int rows_per_thread = m / num_threads;
    int remainder_rows = m % num_threads;
    int current_row = 0;

    for (int i = 0; i < num_threads; ++i) {
        thread_data[i].A = A;
        thread_data[i].B = B;
        thread_data[i].C = C;
        thread_data[i].m = m;
        thread_data[i].k = k;
        thread_data[i].n = n;
        thread_data[i].start_row = current_row;

        int num_rows_for_this_thread = rows_per_thread;
        if (i < remainder_rows) {
            num_rows_for_this_thread++; // Distribute remainder rows to the first few threads
        }
        thread_data[i].end_row = current_row + num_rows_for_this_thread;
        current_row = thread_data[i].end_row;

        // Create the thread
        int rc = pthread_create(&threads[i], NULL, multiply_rows, (void *)&thread_data[i]);
        if (rc) {
            fprintf(stderr, "Error: pthread_create failed for thread %d (error code: %d)\n", i, rc);
            // It's tricky to clean up already launched threads in a robust way here.
            // For simplicity, we'll just free allocated memory and return an error.
            // In a real-world critical application, you might try to join existing threads.
            free(threads);
            free(thread_data);
            return -2; // Signal failure
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    free(threads);
    free(thread_data);

    return 0; // Success
}

