#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int row;                 // The row this thread will compute
    int num_rows;            // Total number of rows assigned to this thread
    int m, n, p;             // Dimensions: A (m x n), B (n x p)
    double *A, *B, *C;       // Matrix pointers: A, B, C
} thread_data_t;

// Worker: computes all elements of assigned row
void* multiply_worker(void *arg) {
    thread_data_t *data = (thread_data_t *)arg;
    int i_start = data->row;
    int i_end = i_start + data->num_rows;
    int m = data->m, n = data->n, p = data->p;
    double *A = data->A, *B = data->B, *C = data->C;

    for (int i = i_start; i < i_end && i < m; ++i) {
        for (int j = 0; j < p; ++j) {
            double sum = 0.0;
            for (int k = 0; k < n; ++k)
                sum += A[i*n + k] * B[k*p + j];
            C[i*p + j] = sum;
        }
    }
    return NULL;
}

/// Parallel matrix multiplication: C = A x B
/// A: (m x n), B: (n x p), C: (m x p)
void parallel_matrix_multiply(double *A, double *B, double *C, int m, int n, int p, int num_threads) {
    pthread_t *threads = malloc(sizeof(pthread_t) * num_threads);
    thread_data_t *tdata = malloc(sizeof(thread_data_t) * num_threads);

    int rows_per_thread = m / num_threads;
    int extra = m % num_threads;
    int row = 0;

    for (int t = 0; t < num_threads; ++t) {
        int this_rows = rows_per_thread + (t < extra ? 1 : 0);
        tdata[t].row = row;
        tdata[t].num_rows = this_rows;
        tdata[t].m = m; tdata[t].n = n; tdata[t].p = p;
        tdata[t].A = A; tdata[t].B = B; tdata[t].C = C;

        pthread_create(&threads[t], NULL, multiply_worker, &tdata[t]);
        row += this_rows;
    }
    for (int t = 0; t < num_threads; ++t)
        pthread_join(threads[t], NULL);

    free(threads);
    free(tdata);
}

#include <stdio.h>
