typedef struct {
    int row;                 // Row index of the result matrix output to compute
    int numColumnsA;         // Number of columns in matrix A
    int numColumnsB;         // Number of columns in matrix B
    int *rowA;               // Pointer to the data of row in matrix A
    int **matrixB;           // Pointer to matrix B
    int *resultRow;          // Pointer to result matrix row
} ThreadData;

void* computeRow(void* arg) {
    ThreadData* data = (ThreadData*)arg;

    for (int j = 0; j < data->numColumnsB; ++j) {
        data->resultRow[j] = 0;
        for (int k = 0; k < data->numColumnsA; ++k) {
            data->resultRow[j] += data->rowA[k] * data->matrixB[k][j];
        }
    }

    pthread_exit(0);
}

