    for (int j = 0; j < data->N; j++) {
        sum = 0;
        for (int k = 0; k < data->N; k++) {
            sum += data->A[data->row][k] * data->B[k][j];
        }
        data->C[data->row][j] = sum;
    }

    pthread_exit(NULL);
}

