// Structure to hold thread arguments
typedef struct {
    int thread_id;
    int num_threads;
    int rows_a;
    int cols_a;
    int rows_b;
    int cols_b;
    double** matrix_a;
    double** matrix_b;
    double** result;
} thread_args;

// Function to perform matrix multiplication using pthreads
void* matrix_multiply(void* args) {
    thread_args* thread_args_ptr = (thread_args*)args;
    int start_row = (thread_args_ptr->thread_id * thread_args_ptr->rows_a) / thread_args_ptr->num_threads;
    int end_row = ((thread_args_ptr->thread_id + 1) * thread_args_ptr->rows_a) / thread_args_ptr->num_threads;

    for (int i = start_row; i < end_row; i++) {
        for (int j = 0; j < thread_args_ptr->cols_b; j++) {
            thread_args_ptr->result[i][j] = 0.0;
            for (int k = 0; k < thread_args_ptr->cols_a; k++) {
                thread_args_ptr->result[i][j] += thread_args_ptr->matrix_a[i][k] * thread_args_ptr->matrix_b[k][j];
            }
        }
    }
    return NULL;
}

// Function to parallelize matrix multiplication using pthreads
void parallel_matrix_multiply(double** matrix_a, double** matrix_b, double** result, int rows_a, int cols_a, int rows_b, int cols_b, int num_threads) {
    if (cols_a != rows_b) {
        printf("Error: Incompatible matrix dimensions for multiplication.\n");
        return;
    }

    pthread_t threads[num_threads];
    thread_args thread_args_array[num_threads];

    for (int i = 0; i < num_threads; i++) {
        thread_args_array[i].thread_id = i;
        thread_args_array[i].num_threads = num_threads;
        thread_args_array[i].rows_a = rows_a;
        thread_args_array[i].cols_a = cols_a;
        thread_args_array[i].rows_b = rows_b;
        thread_args_array[i].cols_b = cols_b;
        thread_args_array[i].matrix_a = matrix_a;
        thread_args_array[i].matrix_b = matrix_b;
        thread_args_array[i].result = result;

        pthread_create(&threads[i], NULL, matrix_multiply, &thread_args_array[i]);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
}

