#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Structure to hold the necessary data for each thread
typedef struct {
    int start_row;
    int end_row;
    int n_threads;
    int** A;
    int** B;
    int** C;
    int N;
    int M;
    int P;
} thread_data;

// Function to perform the matrix multiplication for a given range of rows
void* multiply_matrices(void* arg) {
    thread_data* data = (thread_data*) arg;
    int start_row = data->start_row;
    int end_row = data->end_row;
    int N = data->N;
    int M = data->M;
    int P = data->P;
    int** A = data->A;
    int** B = data->B;
    int** C = data->C;

    for (int i = start_row; i < end_row; i++) {
        for (int j = 0; j < P; j++) {
            C[i][j] = 0;
            for (int k = 0; k < M; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }

    pthread_exit(NULL);
}

// Function to allocate a 2D array
int** allocate_2d_array(int rows, int cols) {
    int** array = (int**) malloc(rows * sizeof(int*));
    for (int i = 0; i < rows; i++) {
        array[i] = (int*) malloc(cols * sizeof(int));
    }
    return array;
}

// Function to free a 2D array
void free_2d_array(int** array, int rows) {
    for (int i = 0; i < rows; i++) {
        free(array[i]);
    }
    free(array);
}

// Function to perform parallel matrix multiplication
void parallel_matrix_multiply(int** A, int** B, int** C, int N, int M, int P, int n_threads) {
    pthread_t* threads = (pthread_t*) malloc(n_threads * sizeof(pthread_t));
    thread_data* data = (thread_data*) malloc(n_threads * sizeof(thread_data));

    // Calculate the number of rows each thread will handle
    int rows_per_thread = N / n_threads;
    int remaining_rows = N % n_threads;

    int start_row = 0;
    for (int i = 0; i < n_threads; i++) {
        int end_row = start_row + rows_per_thread;
        if (i < remaining_rows) {
            end_row++;
        }

        data[i].start_row = start_row;
        data[i].end_row = end_row;
        data[i].A = A;
        data[i].B = B;
        data[i].C = C;
        data[i].N = N;
        data[i].M = M;
        data[i].P = P;
        data[i].n_threads = n_threads;

        pthread_create(&threads[i], NULL, multiply_matrices, (void*) &data[i]);

        start_row = end_row;
    }

    // Wait for all threads to finish
    for (int i = 0; i < n_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
    free(data);
}

// Example usage
int main() {
    int N = 4; // Number of rows in A
    int M = 3; // Number of columns in A and rows in B
    int P = 2; // Number of columns in B

