bool is_valid_email(const char* email) {
    // Check if email is NULL or empty
    if (email == NULL || strlen(email) == 0) {
        return false;
    }

    // Check basic length constraints
    if (strlen(email) > 254) {
        return false;
    }

    // Variables to track email components
    int at_count = 0;
    int dot_count = 0;
    int username_length = 0;
    int domain_length = 0;
    bool in_username = true;

    // Validate email structure
    for (int i = 0; email[i] != '\0'; i++) {
        char ch = email[i];

        // Check for valid characters
        if (!isalnum(ch) && 
            ch != '@' && 
            ch != '.' && 
            ch != '-' && 
            ch != '_') {
            return false;
        }

        // Count '@' symbol
        if (ch == '@') {
            at_count++;
            in_username = false;

            // '@' can appear only once and not at start/end
            if (at_count > 1 || i == 0 || email[i+1] == '\0') {
                return false;
            }
        }

        // Track length of username and domain
        if (in_username) {
            username_length++;
        } else {
            domain_length++;
        }

        // Validate dot placement
        if (ch == '.') {
            dot_count++;

            // Dot cannot be first/last character in username or domain
            if (i == 0 || email[i+1] == '\0' || 
                (in_username && (i == 1 || email[i-1] == '@')) ||
                (!in_username && (i == strlen(email)-2 || email[i-1] == '@'))) {
                return false;
            }
        }
    }

    // Validate component lengths and requirements
    if (at_count != 1 || 
        username_length < 1 || username_length > 64 || 
        domain_length < 1 || domain_length > 253 ||
        dot_count < 1) {
        return false;
    }

    return true;
}

