bool isValidEmail(const char *email) {
    if (email == NULL) return false;

    int atCount = 0;
    int dotCount = 0;
    int len = strlen(email);
    int atIndex = -1;
    int dotIndex = -1;

    // Check for the presence of exactly one '@'
    for (int i = 0; i < len; i++) {
        if (email[i] == '@') {
            atCount++;
            atIndex = i;
        }
    }
    if (atCount != 1) return false;

    // Check local part (before '@')
    if (atIndex == 0 || atIndex == len - 1) return false;
    for (int i = 0; i < atIndex; i++) {
        if (!isalnum(email[i]) && email[i] != '.' && email[i] != '_' && email[i] != '-') {
            return false;
        }
    }

    // Check domain part (after '@')
    for (int i = atIndex + 1; i < len; i++) {
        if (email[i] == '.') {
            dotCount++;
            dotIndex = i;
        }
        if (!isalnum(email[i]) && email[i] != '.' && email[i] != '-') {
            return false;
        }
    }
    if (dotCount < 1) return false;

    // Check that domain does not start or end with '.' or '-'
    if (email[atIndex + 1] == '.' || email[atIndex + 1] == '-' || 
        email[len - 1] == '.' || email[len - 1] == '-') {
        return false;
    }

    return true;
}

