// Helper function to check if a character is valid in the local part
bool is_valid_local_char(char c) {
    return isalnum(c) || c == '.' || c == '_' || c == '-' || c == '+';
}

// Helper function to check if a character is valid in the domain part
bool is_valid_domain_char(char c) {
    return isalnum(c) || c == '-' || c == '.';
}

/*
 * Verifies if an email address string is syntactically valid based on common rules.
 *
 * Args:
 *   email: The null-terminated string representing the email address.
 *
 * Returns:
 *   true if the email address is considered valid, false otherwise.
 *
 * Common Rules Implemented:
 * - Must not be NULL or empty.
 * - Must contain exactly one '@' symbol.
 * - '@' cannot be the first or last character.
 * - Local part (before '@'):
 *   - Cannot be empty.
 *   - Allowed characters: alphanumeric, '.', '_', '-', '+'.
 *   - Cannot start or end with '.'.
 *   - Cannot have consecutive dots (e.g., '..').
 * - Domain part (after '@'):
 *   - Cannot be empty.
 *   - Allowed characters: alphanumeric, '.', '-'.
 *   - Must contain at least one dot (e.g., 'example.com').
 *   - Cannot start or end with '.'.
 *   - Cannot have consecutive dots.
 *   - Each segment between dots must not start or end with a hyphen.
 * - TLD (Top-Level Domain) - part after the last dot:
 *   - Must be at least 2 characters long.
 *   - Must consist only of letters (for simplicity, doesn't handle all new gTLDs or IDNs).
 * - No spaces allowed anywhere.
 */
bool verify_email_address(const char *email) {
    if (email == NULL || *email == '\0') {
        return false; // Email is NULL or empty
    }

    size_t len = strlen(email);

    // 1. Check for basic length and @ position
    size_t at_pos = -1;
    int at_count = 0;
    for (size_t i = 0; i < len; ++i) {
        if (email[i] == '@') {
            at_count++;
            at_pos = i;
        } else if (isspace((unsigned char)email[i])) {
            return false; // No spaces allowed
        }
    }

    if (at_count != 1) {
        return false; // Must contain exactly one '@'
    }

    if (at_pos == 0 || at_pos == len - 1) {
        return false; // '@' cannot be the first or last character
    }

    // 2. Validate Local Part (before @)
    const char *local_part = email;
    size_t local_len = at_pos;

    if (local_len == 0) {
        return false; // Local part cannot be empty
    }

    if (local_part[0] == '.' || local_part[local_len - 1] == '.') {
        return false; // Local part cannot start or end with a dot
    }

    bool prev_char_was_dot = false;
    for (size_t i = 0; i < local_len; ++i) {
        if (!is_valid_local_char(local_part[i])) {
            return false; // Invalid character in local part
        }
        if (local_part[i] == '.') {
            if (prev_char_was_dot) {
                return false; // Consecutive dots in local part
            }
            prev_char_was_dot = true;
        } else {
            prev_char_was_dot = false;
        }
    }

    // 3. Validate Domain Part (after @)
    const char *domain_part = email + at_pos + 1;
    size_t domain_len = len - (at_pos + 1);

    if (domain_len == 0) {
        return false; // Domain part cannot be empty
    }

    if (domain_part[0] == '.' || domain_part[domain_len - 1] == '.') {
        return false; // Domain part cannot start or end with a dot
    }

    // Check for at least one dot in the domain part
    size_t last_dot_pos = -1;
    prev_char_was_dot = false;
    for (size_t i = 0; i < domain_len; ++i) {
        if (!is_valid_domain_char(domain_part[i])) {
            return false; // Invalid character in domain part
        }
        if (domain_part[i] == '.') {
            if (prev_char_was_dot) {
                return false; // Consecutive dots in domain part
            }
            last_dot_pos = i;
            prev_char_was_dot = true;
        } else if (domain_part[i] == '-') {
            // Hyphen cannot be at start or end of a domain segment
            if (i == 0 || i == domain_len - 1 || domain_part[i-1] == '.' || domain_part[i+1] == '.') {
                return false; // Hyphen at invalid position (ends/starts a segment)
            }
            prev_char_was_dot = false;
        }
        else {
            prev_char_was_dot = false;
        }
    }

    if (last_dot_pos == (size_t)-1) { // -1 cast to size_t is max value
        return false; // Domain part must contain at least one dot
    }

    // 4. Validate TLD (Top-Level Domain)
    // TLD is the part after the last dot in the domain part
    const char *tld = domain_part + last_dot_pos + 1;
    size_t tld_len = domain_len - (last_dot_pos + 1);

    if (tld_len < 2) {
        return false; // TLD must be at least 2 characters long
    }

    for (size_t i = 0; i < tld_len; ++i) {
        if (!isalpha((unsigned char)tld[i])) { // For simplicity, only allow letters in TLD
            return false;
        }
    }

    // All checks passed
    return true;
}

