int is_valid_email(const char *email) {
    if (email == NULL)
        return 0;

    int at_found = 0;
    int dot_after_at = 0;
    const char *p = email;

    // First character must not be '@' or '.'
    if (*p == '@' || *p == '.')
        return 0;

    while (*p) {
        // No spaces allowed
        if (isspace((unsigned char)*p))
            return 0;

        // Valid characters: alphanum, ., _, -, @
        if (!isalnum((unsigned char)*p) && *p != '@' && *p != '.' && *p != '_' && *p != '-')
            return 0;

        if (*p == '@') {
            // Only one '@' allowed
            if (at_found)
                return 0;
            at_found = 1;
            // '@' cannot be first or last character
            if (p == email || *(p+1) == '\0')
                return 0;
            // Next character cannot be '.'
            if (*(p+1) == '.')
                return 0;
        } else if (*p == '.') {
            // Dot cannot be the first or last character
            if (p == email || *(p+1) == '\0')
                return 0;
            // Dot cannot be immediately before or after '@'
            if (*(p-1) == '@' || *(p+1) == '@')
                return 0;
            if (at_found)
                dot_after_at = 1;
        }
        p++;
    }
    // Must have exactly one '@', and at least one dot after '@'
    return (at_found && dot_after_at);
}

