// Function to check if a character is allowed in the local part of an email
int is_valid_local_char(char c) {
    return (isalnum(c) || c == '_' || c == '-' || c == '.');
}

// Function to check if a character is allowed in the domain part of an email
int is_valid_domain_char(char c) {
    return (isalnum(c) || c == '-');
}

// Function to validate the email address
int is_valid_email(const char *email) {
    // Check if the email is empty or too long
    if (email == NULL || strlen(email) == 0 || strlen(email) > 254) {
        return 0;
    }

    int i = 0;
    int at_found = 0;
    int dot_found_after_at = 0;

    // Parse the local part
    while (email[i] != '\0' && email[i] != '@') {
        if (!is_valid_local_char(email[i])) {
            return 0;
        }
        i++;
    }

    // Ensure there is exactly one '@'
    if (email[i] == '@') {
        at_found = 1;
        i++;
    } else {
        return 0;
    }

    // Parse the domain part
    while (email[i] != '\0') {
        if (email[i] == '.') {
            dot_found_after_at = 1;
        } else if (!is_valid_domain_char(email[i])) {
            return 0;
        }
        i++;
    }

    // Ensure the domain part is non-empty and contains at least one '.'
    if (!at_found || !dot_found_after_at) {
        return 0;
    }

    // Ensure the domain part does not start or end with a '.'
    if (email[strlen(email) - 1] == '.' || *(email + i - 1) == '@') {
        return 0;
    }

    return 1;
}

