// Callback function for libcurl to write response
size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    char *response = (char *)userp;
    strncat(response, contents, real_size);
    return real_size;
}

// Function to extract DOI from arXiv page
int get_arxiv_doi_url(const char *arxiv_url, char *doi_url, size_t doi_url_size) {
    CURL *curl;
    CURLcode res;
    char response[10240] = {0};  // Buffer to store page content

    // Initialize curl
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if (!curl) {
        fprintf(stderr, "Could not initialize CURL\n");
        return 0;
    }

    // Set up curl options
    curl_easy_setopt(curl, CURLOPT_URL, arxiv_url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, response);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);

    // Perform the request
    res = curl_easy_perform(curl);

    // Check for errors
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return 0;
    }

    // Clean up curl
    curl_easy_cleanup(curl);
    curl_global_cleanup();

    // Compile regex to find DOI
    regex_t regex;
    int reti = regcomp(&regex, "https?://doi\\.org/10\\.[0-9]+/[^ \"'<>]+", REG_EXTENDED);
    if (reti) {
        fprintf(stderr, "Could not compile regex\n");
        return 0;
    }

    // Execute regex
    regmatch_t matches[1];
    if (regexec(&regex, response, 1, matches, 0) == 0) {
        // Extract DOI URL
        int start = matches[0].rm_so;
        int end = matches[0].rm_eo;

        // Copy DOI URL to output buffer
        if (end - start < doi_url_size) {
            strncpy(doi_url, response + start, end - start);
            doi_url[end - start] = '\0';
            regfree(&regex);
            return 1;
        }
    }

    regfree(&regex);
    return 0;
}

