// Function to extract the ArXiv ID from the URL and construct the DOI URL
// Returns a dynamically allocated string containing the DOI URL, or NULL on error.
char* getArxivDoiUrl(const char* arxivUrl) {
    if (arxivUrl == NULL) {
        fprintf(stderr, "Error: Input URL is NULL.\n");
        return NULL;
    }

    const char* start = strstr(arxivUrl, "arxiv.org/abs/");
    if (start == NULL) {
        start = strstr(arxivUrl, "arxiv.org/pdf/");
        if (start == NULL) {
            fprintf(stderr, "Error: Not a recognized ArXiv URL format (missing 'arxiv.org/abs/' or 'arxiv.org/pdf/').\n");
            return NULL;
        }
    }

    // Skip "arxiv.org/abs/" or "arxiv.org/pdf/"
    start += strlen("arxiv.org/abs/");

    const char* end = start;
    while (*end != '\0' && *end != '.' && *end != '/') { // ArXiv IDs can be like 1234.5678 or 9876543
        end++;
    }

    // Handle cases where there might be a trailing .pdf or version number like v1, v2
    // If the ID is like 1234.5678v1, we want 1234.5678
    // If the ID is like 9876543v1, we want 9876543
    const char* id_end = end;
    const char* v_pos = strchr(start, 'v');
    if (v_pos != NULL && v_pos < end) { // 'v' is within the extracted part
        id_end = v_pos;
    }

    int id_len = id_end - start;
    if (id_len <= 0) {
        fprintf(stderr, "Error: Could not extract ArXiv ID from URL.\n");
        return NULL;
    }

    char* arxivId = (char*)malloc(id_len + 1);
    if (arxivId == NULL) {
        perror("Failed to allocate memory for ArXiv ID");
        return NULL;
    }
    strncpy(arxivId, start, id_len);
    arxivId[id_len] = '\0';

    // Construct the DOI URL
    const char* doi_prefix = "https://doi.org/10.48550/arXiv.";
    size_t doi_url_len = strlen(doi_prefix) + strlen(arxivId) + 1;
    char* doiUrl = (char*)malloc(doi_url_len);
    if (doiUrl == NULL) {
        perror("Failed to allocate memory for DOI URL");
        free(arxivId);
        return NULL;
    }

    snprintf(doiUrl, doi_url_len, "%s%s", doi_prefix, arxivId);

    free(arxivId); // Free the temporary ArXiv ID string

    return doiUrl;
}

// Function to print the paper's DOI URL
void printArxivDoiUrl(const char* arxivUrl) {
    char* doiUrl = getArxivDoiUrl(arxivUrl);
    if (doiUrl != NULL) {
        printf("DOI URL: %s\n", doiUrl);
        free(doiUrl); // Free the dynamically allocated string
    } else {
        printf("Could not determine DOI URL for: %s\n", arxivUrl);
    }
}

