#define MAX_HTML_SIZE (1024*1024)

struct MemoryStruct {
    char *memory;
    size_t size;
};

static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct MemoryStruct *mem = (struct MemoryStruct *)userp;

    if(mem->size + realsize >= MAX_HTML_SIZE-1) {
        fprintf(stderr, "HTML too large\n");
        return 0;
    }
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;
    return realsize;
}

void print_arxiv_doi(const char* url) {
    CURL *curl_handle;
    CURLcode res;

    struct MemoryStruct chunk;
    chunk.memory = malloc(MAX_HTML_SIZE);
    if (!chunk.memory) {
        fprintf(stderr, "Not enough memory\n");
        return;
    }
    chunk.size = 0;

    curl_global_init(CURL_GLOBAL_ALL);
    curl_handle = curl_easy_init();
    if(!curl_handle) {
        fprintf(stderr, "Failed to initialize curl\n");
        free(chunk.memory);
        return;
    }

    curl_easy_setopt(curl_handle, CURLOPT_URL, url);
    curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
    curl_easy_setopt(curl_handle, CURLOPT_WRITEDATA, (void*)&chunk);
    curl_easy_setopt(curl_handle, CURLOPT_USERAGENT, "Mozilla/5.0");

    res = curl_easy_perform(curl_handle);

    if(res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl_handle);
        free(chunk.memory);
        return;
    }

    // Regex to capture DOI value (e.g., doi: 10.1234/xxxx)
    regex_t regex;
    regmatch_t matches[2];
    // Looks for e.g. 'doi.org/10.xxxx/yyyy' or doi:10.xxxx/yyyy
    const char* pat = "(doi\\.org/|doi:)(10\\.[0-9]+/[A-Za-z0-9._;()/:+-]+)";

    if (regcomp(&regex, pat, REG_EXTENDED|REG_ICASE) != 0) {
        fprintf(stderr, "Could not compile regex\n");
        curl_easy_cleanup(curl_handle);
        free(chunk.memory);
        return;
    }

    char* html = chunk.memory;
    if (regexec(&regex, html, 2, matches, 0) == 0) {
        // The second match is the real DOI
        int len = matches[2].rm_eo - matches[2].rm_so;
        char doi[256] = {0};
        if (len < sizeof(doi)) {
            strncpy(doi, html + matches[2].rm_so, len);
            doi[len] = 0;
            printf("https://doi.org/%s\n", doi);
        } else {
            fprintf(stderr, "DOI too long\n");
        }
    } else {
        printf("No DOI found on this page\n");
    }

    regfree(&regex);
    curl_easy_cleanup(curl_handle);
    free(chunk.memory);
}

