#define ARXIV_API_BASE "http://export.arxiv.org/api/query?id_list="

struct string {
    char *ptr;
    size_t len;
};

void init_string(struct string *s) {
    s->len = 0;
    s->ptr = malloc(s->len+1);
    if (s->ptr == NULL) {
        fprintf(stderr, "malloc() failed\n");
        exit(EXIT_FAILURE);
    }
    s->ptr[0] = '\0';
}

size_t writefunc(void *ptr, size_t size, size_t nmemb, struct string *s) {
    size_t new_len = s->len + size*nmemb;
    s->ptr = realloc(s->ptr, new_len+1);
    if (s->ptr == NULL) {
        fprintf(stderr, "realloc() failed\n");
        exit(EXIT_FAILURE);
    }
    memcpy(s->ptr+s->len, ptr, size*nmemb);
    s->ptr[new_len] = '\0';
    s->len = new_len;

    return size*nmemb;
}

char *extract_arxiv_id(const char *url) {
    const char *prefix = "arxiv.org/abs/";
    char *id_start = strstr(url, prefix);
    if (!id_start) {
        fprintf(stderr, "Invalid URL format\n");
        return NULL;
    }
    id_start += strlen(prefix);
    return strdup(id_start);
}

void print_doi_url(const char *arxiv_url) {
    char *arxiv_id = extract_arxiv_id(arxiv_url);
    if (!arxiv_id) {
        return;
    }

    CURL *curl = curl_easy_init();
    if (curl) {
        CURLcode res;
        struct string s;
        init_string(&s);

        char api_url[256];
        snprintf(api_url, sizeof(api_url), "%s%s", ARXIV_API_BASE, arxiv_id);

        curl_easy_setopt(curl, CURLOPT_URL, api_url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writefunc);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &s);

        res = curl_easy_perform(curl);

        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            char *doi_ptr = strstr(s.ptr, "<arxiv:doi>");
            if (doi_ptr) {
                doi_ptr += strlen("<arxiv:doi>");
                char *doi_end = strstr(doi_ptr, "</arxiv:doi>");
                if (doi_end) {
                    *doi_end = '\0';
                    printf("DOI URL: https://doi.org/%s\n", doi_ptr);
                }
            } else {
                printf("DOI not available for this paper.\n");
            }
        }

        free(s.ptr);
        curl_easy_cleanup(curl);
    }

    free(arxiv_id);
}

