// Function to extract the DOI URL from an arXiv paper URL
void extract_doi(const char *url) {
    // Regular expression pattern to match the arXiv paper ID
    const char *pattern = "https?://arxiv\\.org/abs/([0-9]+\\.[0-9]+)";
    regex_t regex;
    regcomp(&regex, pattern, REG_EXTENDED);
    regmatch_t matches[1];

    // Attempt to match the input URL against the pattern
    if (regexec(&regex, url, 1, matches, 0) == 0) {
        // Extract the matched paper ID
        int match_start = matches[0].rm_so + 24;  // Skip the "https://arxiv.org/abs/" prefix
        int match_end = matches[0].rm_eo;
        char paper_id[256];
        strncpy(paper_id, url + match_start, match_end - match_start);
        paper_id[match_end - match_start] = '\0';

        // Construct the DOI URL
        char doi_url[256];
        sprintf(doi_url, "https://doi.org/10.48550/arXiv.%s", paper_id);

        // Print the DOI URL
        printf("DOI URL: %s\n", doi_url);
    } else {
        printf("Error: Unable to extract DOI URL from the input URL.\n");
    }

    // Clean up
    regfree(&regex);
}

