#include <stdio.h>
#include <stdlib.h>

// Structure to represent a portfolio transaction
typedef struct {
    double amount;     // Transaction amount (purchase or sale)
    double timestamp;  // Timestamp of the transaction
} Transaction;

// Structure to represent a portfolio period
typedef struct {
    double start_value;
    double end_value;
    double cash_flow;
} PortfolioPeriod;

// Function to calculate time-weighted return
double calculate_time_weighted_return(Transaction* transactions, int num_transactions, double initial_value) {
    if (num_transactions <= 0 || transactions == NULL) {
        return 0.0;
    }

    // Allocate memory for portfolio periods
    PortfolioPeriod* periods = malloc((num_transactions + 1) * sizeof(PortfolioPeriod));
    if (periods == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 0.0;
    }

    // Initialize first period
    periods[0].start_value = initial_value;
    periods[0].cash_flow = 0;

    // Calculate portfolio periods
    for (int i = 0; i < num_transactions; i++) {
        // Set start value for next period
        if (i > 0) {
            periods[i].start_value = periods[i-1].end_value;
        }

        // Set cash flow
        periods[i].cash_flow = transactions[i].amount;

        // Calculate end value
        if (i < num_transactions - 1) {
            // For intermediate periods, calculate end value based on cash flow
            periods[i].end_value = periods[i].start_value + periods[i].cash_flow;
        } else {
            // For final period, use current portfolio value
            periods[i].end_value = periods[i].start_value + periods[i].cash_flow;
        }
    }

    // Calculate period returns
    double total_return = 1.0;
    for (int i = 0; i < num_transactions; i++) {
        if (periods[i].start_value != 0) {
            double period_return = (periods[i].end_value - periods[i].cash_flow) / periods[i].start_value;
            total_return *= period_return;
        }
    }

    // Calculate final time-weighted return
    double time_weighted_return = total_return - 1.0;

    // Free allocated memory
    free(periods);

    return time_weighted_return;
}

// Example usage
int main() {
    // Example portfolio transactions
    Transaction transactions[] = {
        {10000.0, 1609459200},   // Initial investment of $10,000 at start of 2021
        {2000.0, 1617235200},    // Additional $2,000 investment in April 2021
        {-5000.0, 1625097600}    // Withdrawal of $5,000 in July 2021
    };
    int num_transactions = sizeof(transactions) / sizeof(transactions[0]);
    double initial_value = 10000.0;

    // Calculate time-weighted return
    double twr = calculate_time_weighted_return(transactions, num_transactions, initial_value);

    // Print result
    printf("Time-Weighted Return: %.2f%%\n", twr * 100);

    return 0;
}

#include <stdio.h>
#include <math.h>

// Structure to represent a transaction
typedef struct {
    double amount;  // Amount of the transaction (positive for purchase, negative for sale)
    double value;   // Portfolio value immediately after the transaction
    int time;       // Time of the transaction (e.g., days since start)
} Transaction;

// Function to calculate the Time-Weighted Return
double calculateTWR(Transaction transactions[], int numTransactions) {
    if (numTransactions < 1) {
        return 0.0; // No transactions, return 0
    }

    double twr = 1.0; // Initialize TWR to 1 (100%)

    // Loop through transactions to calculate sub-period returns
    for (int i = 1; i < numTransactions; i++) {
        double startValue = transactions[i - 1].value;
        double endValue = transactions[i].value;
        double cashFlow = transactions[i].amount;

        // Calculate the sub-period return
        double subPeriodReturn = (endValue - cashFlow) / startValue;

        // Multiply the TWR by the sub-period return
        twr *= subPeriodReturn;
    }

    // Convert the final TWR to a percentage return
    return (twr - 1.0) * 100.0;
}

int main() {
    // Example transactions
    Transaction transactions[] = {
        {1000.0, 1000.0, 0},   // Initial purchase of $1000, portfolio value $1000
        {-200.0, 900.0, 30},   // Sale of $200, portfolio value $900
        {500.0, 1500.0, 60}    // Purchase of $500, portfolio value $1500
    };

    int numTransactions = sizeof(transactions) / sizeof(transactions[0]);

    // Calculate the Time-Weighted Return
    double twr = calculateTWR(transactions, numTransactions);

    // Print the result
    printf("Time-Weighted Return: %.2f%%\n", twr);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h> // For memcpy if needed, though not strictly in this simplified example

// --- Data Structures ---

// Represents an asset purchase or sale
typedef struct {
    long long timestamp_ms; // Unix timestamp in milliseconds
    double amount;          // Positive for purchase, negative for sale
} Transaction;

// Represents a portfolio valuation at a specific point in time
typedef struct {
    long long timestamp_ms; // Unix timestamp in milliseconds
    double value;           // Current market value of the portfolio
} Valuation;

// Represents a combined event for sorting
typedef enum {
    EVENT_TYPE_TXN,
    EVENT_TYPE_VALUATION
} EventType;

typedef struct {
    long long timestamp_ms;
    EventType type;
    union { // Used for flexible data storage based on event type
        Transaction txn;
        Valuation val;
    } data;
} PortfolioEvent;

// --- Helper Functions ---

// Comparison function for qsort to sort PortfolioEvent by timestamp
int comparePortfolioEvents(const void *a, const void *b) {
    PortfolioEvent *eventA = (PortfolioEvent *)a;
    PortfolioEvent *eventB = (PortfolioEvent *)b;
    if (eventA->timestamp_ms < eventB->timestamp_ms) return -1;
    if (eventA->timestamp_ms > eventB->timestamp_ms) return 1;
    return 0;
}

// --- Main TWR Calculation Function ---

/**
 * @brief Calculates the time-weighted return (TWR) of a portfolio.
 *
 * This function takes a list of transactions (purchases/sales) and
 * portfolio valuations, sorts them by date, and then calculates the
 * TWR by breaking the period into sub-periods based on these events.
 *
 * @param transactions An array of Transaction structs.
 * @param num_transactions The number of transactions.
 * @param valuations An array of Valuation structs.
 * @param num_valuations The number of valuations.
 * @param initial_portfolio_value The starting value of the portfolio *before* any transactions or valuations occur.
 *                                This is crucial if the first event is not a valuation or if the portfolio wasn't zero.
 *                                If zero, ensure the first real event is a purchase or initial valuation.
 * @return The time-weighted return as a decimal (e.g., 0.10 for 10%).
 *         Returns -2.0 if no valid periods to calculate.
 *         Returns -1.0 on memory allocation error.
 */
double calculate_time_weighted_return(
    Transaction *transactions, int num_transactions,
    Valuation *valuations, int num_valuations,
    double initial_portfolio_value) {

    // 1. Create a combined list of all events (transactions and valuations)
    int total_events = num_transactions + num_valuations;
    if (total_events == 0) {
        // If initial value isn't 0 and no other events, maybe initial value *is* the TWR.
        // But for actual TWR, we need more than one point.
        printf("Error: No events provided for TWR calculation.\n");
        return -2.0;
    }

    PortfolioEvent *events = (PortfolioEvent *)malloc(total_events * sizeof(PortfolioEvent));
    if (events == NULL) {
        printf("Error: Memory allocation failed for events.\n");
        return -1.0;
    }

    int i, j, k = 0;
    for (i = 0; i < num_transactions; ++i) {
        events[k].timestamp_ms = transactions[i].timestamp_ms;
        events[k].type = EVENT_TYPE_TXN;
        events[k].data.txn = transactions[i];
        k++;
    }
    for (j = 0; j < num_valuations; ++j) {
        events[k].timestamp_ms = valuations[j].timestamp_ms;
        events[k].type = EVENT_TYPE_VALUATION;
        events[k].data.val = valuations[j];
        k++;
    }

    // 2. Sort all events by timestamp
    qsort(events, total_events, sizeof(PortfolioEvent), comparePortfolioEvents);

    // 3. Initialize variables for TWR calculation
    double compounded_return_factor = 1.0;
    double current_portfolio_value = initial_portfolio_value;
    double net_cash_flow_in_period = 0.0; // This accumulates cash flow for a segment

    // TWR requires at least two valuation points or an initial value + a valuation.
    // If the first event is a transaction, we need an initial value or an implied zero value.
    if (num_valuations == 0 && initial_portfolio_value == 0.0) {
        printf("Warning: No valuation points or initial portfolio value provided. TWR may be inaccurate or impossible.\n");
        // This scenario means we can't establish a beginning/ending value for a period.
        // We'll proceed, but if `initial_portfolio_value` is 0 and the first event is a Txn,
        // we essentially assume the portfolio started with that Txn amount.
    }


    // 4. Iterate through sorted events to calculate sub-period returns
    // We need at least one valuation point and some activity to show a real return.
    // The loop iterates from the second event onwards as an "end" point for a period.
    // The "start" point is the previous event or the initial state.
    long long last_valuation_timestamp = -1; // Track the timestamp of the last *actual* valuation.
                                             // This helps to manage the "current_portfolio_value"
                                             // which should reflect the last known market value.

    // Find the first actual valuation to set the `current_portfolio_value` accurately,
    // *unless* the portfolio explicitly started at `initial_portfolio_value`.
    // If `initial_portfolio_value` is explicitly set and non-zero, it takes precedence as the "start".
    // Otherwise, we wait for the first `EVENT_TYPE_VALUATION`.

    long long first_valuation_or_initial_timestamp = -1;
    if (initial_portfolio_value != 0.0 && total_events > 0) {
        first_valuation_or_initial_timestamp = events[0].timestamp_ms; // Treat the point *before* the first event as start
    } else {
        // Find the first actual valuation to start the "real" calculation.
        // Transactions before the first valuation imply a zero value start.
        for (i = 0; i < total_events; ++i) {
            if (events[i].type == EVENT_TYPE_VALUATION) {
                current_portfolio_value = events[i].data.val.value;
                last_valuation_timestamp = events[i].timestamp_ms;
                first_valuation_or_initial_timestamp = events[i].timestamp_ms;
                break; // Found our starting valuation
            } else {
                // If the first event is a transaction before any valuation,
                // and initial_portfolio_value was 0, this portfolio has just started.
                // The money from this transaction is added to a zero beginning value.
                if (initial_portfolio_value == 0.0 && events[i].timestamp_ms == events[0].timestamp_ms) {
                    current_portfolio_value = 0.0; // Ensure it starts from 0 for the first transaction
                    first_valuation_or_initial_timestamp = events[i].timestamp_ms;
                }
            }
        }
    }

    if (first_valuation_or_initial_timestamp == -1 && initial_portfolio_value == 0.0 && total_events > 0) {
        // This means all events are transactions, and initial value is zero.
        // The effective beginning value will be the sum of initial transactions
        printf("Warning: No explicit initial value or valuation to start TWR.\n");
        // We'll proceed, but the first "period" might be strange if beginning value remains 0 after first transaction.
    }
    if (first_valuation_or_initial_timestamp == -1) {
        printf("Error: Cannot determine a valid start point for TWR calculation (no initial value and no valuations).\n");
        free(events);
        return -2.0;
    }


    // The core loop processes periods between significant events.
    // A "period" ends when we encounter a Valuation event.
    // Transactions *within* a period adjust the denominator for that period's return.

    // A crucial state variable: When was the last market value established?
    // This value is the *market value just before any cash flow in this period*.
    double market_value_at_period_start = initial_portfolio_value;
    if (initial_portfolio_value == 0.0) {
        // If initial value is 0, we effectively start with the first event's impact.
        // It's a common practice to assume the portfolio starts when the first money goes in.
        market_value_at_period_start = 0.0;
    }

    double cumulative_cash_flow_in_period = 0.0; // Sum of purchases/sales within the current period

    // Loop through events to process periods.
    // Each period ends with a Valuation event. Transactions *within* a period are handled by net cash flow.
    // The "market_value_at_period_start" is the value at the *start of the current sub-period*,
    // which effectively is the ending value of the *previous* sub-period.

    // We process events. When we hit a VALUATION, that marks the end of a period.
    // The previous `market_value_at_period_start` (or `initial_portfolio_value`) is the starting point.
    // All transactions since `market_value_at_period_start` contribute to `cumulative_cash_flow_in_period`.
    // The current valuation is the `ending_market_value`.

    int num_valid_periods = 0;
    for (i = 0; i < total_events; ++i) {
        PortfolioEvent *current_event = &events[i];

        if (current_event->type == EVENT_TYPE_TXN) {
            // Purchases/sales contribute to the cash flow for the *current* period.
            // These cash flows happen *during* the period, affecting the invested capital.
            cumulative_cash_flow_in_period += current_event->data.txn.amount;
        } else { // EVENT_TYPE_VALUATION
            // This valuation marks the END of a period.
            double ending_market_value = current_event->data.val.value;

            // Calculate sub-period return
            // denominator = market value just before current period's cash flows + cash flows in current period
            double denominator = market_value_at_period_start + cumulative_cash_flow_in_period;

            // Handle potential division by zero or very small denominators
            if (fabs(denominator) < 1e-9) { // If denominator is very close to zero
                if (ending_market_value != 0.0) {
                    // This means portfolio was zero, money was added, and now it has value.
                    // The return is effectively infinite in pure percentage terms.
                    // For TWR, we must handle this. A common way is to make the entire new value
                    // contribute directly to the return factor if the start was effectively zero.
                    // (This effectively means the first money in generated its current worth directly)
                    if (ending_market_value > 0) {
                        compounded_return_factor *= (ending_market_value / (cumulative_cash_flow_in_period == 0 ? 1 : cumulative_cash_flow_in_period));
                        printf("Warning: Denominator zero/near-zero (start + cash flow). Using value directly. Factor: %.4f\n", (ending_market_value / (cumulative_cash_flow_in_period == 0 ? 1 : cumulative_cash_flow_in_period)));
                    } else {
                        // If ending value is also zero, no return (factor 1).
                        // If it's negative (debt?), this scenario needs careful definition.
                        printf("Warning: Denominator and ending value zero/near-zero. Assuming no return for this period.\n");
                    }

                } else {
                    // Both denominator and ending value are zero: no change, return factor is 1.
                    printf("Info: Denominator and ending value zero/near-zero. Return factor for period is 1.0.\n");
                }
            } else {
                double sub_period_return_factor = ending_market_value / denominator;
                compounded_return_factor *= sub_period_return_factor;
            }

            num_valid_periods++;

            // Reset for the next period:
            // The starting value for the *next* period is the ending value of *this* period.
            market_value_at_period_start = ending_market_value;
            cumulative_cash_flow_in_period = 0.0; // Reset cash flow for the new period
        }
    }

    free(events);

    if (num_valid_periods == 0) {
        printf("Error: Could not calculate TWR. Insufficient complete periods (need at least one valuation point after initial value/first transaction).\n");
        return -2.0; // Indicate no meaningful return could be calculated
    }

    return compounded_return_factor - 1.0;
}

