#include <stdio.h>

typedef struct {
    double date;         // Time of cash flow (can be int, string, etc. for advanced)
    double cashflow;     // Positive for purchase, negative for sell (cash in/out)
    double port_value;   // Portfolio value *immediately after* cash flow, before market return
} CashFlowEvent;

// events[0...n-1], n events (cash flows), final_value is current total portfolio value
double compute_twr(CashFlowEvent *events, int n, double final_value) {
    double twr = 1.0;
    double period_return, start_value, end_value;
    int i;

    for (i = 0; i < n; i++) {
        start_value = events[i].port_value;

        // For last flow, end_value is final_value
        if (i == n - 1)
            end_value = final_value;
        else
            end_value = events[i+1].port_value;

        // The period return disregards any further cash flow; only market movement
        period_return = (end_value) / (start_value);

        twr *= period_return;
    }
    // TWR is compounded return minus one
    return twr - 1.0;
}

