#include <stdio.h>

typedef struct {
    double begin_value;  // Portfolio value at the beginning of the period
    double end_value;    // Portfolio value at the end of the period
    double cash_flow;    // Net cash flow during the period (positive for purchases, negative for sales)
} TransactionPeriod;

// Function to calculate time-weighted return
double calculateTimeWeightedReturn(TransactionPeriod periods[], int n) {
    if (n <= 0) return 0.0;

    // Compound each period's return
    double total_return = 1.0;

    for (int i = 0; i < n; ++i) {
        // Calculate return for the period
        double period_return;

        double adjusted_begin_value = periods[i].begin_value - periods[i].cash_flow;
        if (adjusted_begin_value != 0) {
            period_return = (periods[i].end_value / adjusted_begin_value);
        } else {
            // If the adjusted beginning value is zero (which theoretically shouldn't happen unless
            // there's an error in your inputs), it means there's an issue. For the sake of
            // defensive programming, continue to the next period.
            printf("Warning: Zero or negative adjusted beginning value in period %d.\n", i+1);
            continue;
        }

        // Accumulate the overall return
        total_return *= period_return;
    }

    // Return the time-weighted return minus one to reflect percentage change
    return total_return - 1.0;
}

int main() {
    // Example usage
    TransactionPeriod periods[] = {
        {10000.0, 10500.0, 0.0},    // No cash flow
        {10500.0, 12000.0, -1000.0}, // Net cash outflow of 1000 (sell)
        {11000.0, 13000.0, 2000.0}   // Net cash inflow of 2000 (buy)
    };

    int num_periods = sizeof(periods) / sizeof(periods[0]);
    double twr = calculateTimeWeightedReturn(periods, num_periods);

    printf("Time-weighted return: %.2f%%\n", twr * 100);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    double amount; // positive for purchase, negative for sale
    double value;  // current value of the asset after transaction
} Transaction;

// Function to calculate Time-Weighted Return
double calculateTimeWeightedReturn(Transaction* transactions, int numTransactions) {
    if (numTransactions <= 0) {
        return 0.0;
    }

    double overallReturn = 1.0; // Start with 1 as initial value for return

    for (int i = 0; i < numTransactions; i++) {
        // Calculate the geometric mean factor for each segment
        double cashFlow = transactions[i].amount;
        double currentValue = transactions[i].value;

        if (cashFlow != 0) {
            // Calculate the return factor only if there was a cash flow
            double returnFactor = currentValue / (currentValue - cashFlow);
            overallReturn *= returnFactor;
        }
    }

    // Calculate the overall TWR
    double timeWeightedReturn = overallReturn - 1.0; // Subtracting the initial value of 1

    return timeWeightedReturn * 100; // Convert to percentage
}

