    // Example usage of the function
    Transaction transactions[] = {
        {1000.0, 1200.0}, // Buy an asset for $1000, current value $1200
        {-500.0, 600.0},  // Sell an asset for $500, current value $600
        {0.0, 1500.0},    // Just a value on the current investment
    };
    int numTransactions = sizeof(transactions) / sizeof(transactions[0]);

    double twr = calculateTimeWeightedReturn(transactions, numTransactions);
    printf("Time-Weighted Return: %.2f%%\n", twr);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure to represent a transaction
typedef struct {
    int type;  // 0: purchase, 1: sale
    double amount;
    double price;
    double timestamp;
} Transaction;

// Function to calculate time-weighted return
double calculateTimeWeightedReturn(Transaction* transactions, int numTransactions, double currentValue) {
    double portfolioValue = 0.0;
    double previousValue = 0.0;
    double twr = 1.0;
    double previousTimestamp = transactions[0].timestamp;

    for (int i = 0; i < numTransactions; i++) {
        // Update portfolio value
        if (transactions[i].type == 0) {  // Purchase
            portfolioValue += transactions[i].amount;
        } else if (transactions[i].type == 1) {  // Sale
            portfolioValue -= transactions[i].amount;
        }

        // Calculate return for this sub-period
        double subPeriodReturn = (portfolioValue / previousValue) - 1.0;
        if (previousValue == 0.0) {
            subPeriodReturn = portfolioValue - 1.0;
        }

        // Compound returns
        twr *= (1.0 + subPeriodReturn);

        // Update previous values
        previousValue = portfolioValue;
        previousTimestamp = transactions[i].timestamp;
    }

    // Finalize time-weighted return calculation
    twr = (currentValue / previousValue) - 1.0;
    if (previousValue == 0.0) {
        twr = currentValue - 1.0;
    }

    return twr;
}

