    // Example usage:
    Transaction transactions[] = {
        {0, 1000.0, 10.0, 1.0},  // Purchase 100 units at $10 on day 1
        {1, 500.0, 12.0, 3.0},   // Sell 50 units at $12 on day 3
        {0, 2000.0, 11.0, 5.0}   // Purchase 200 units at $11 on day 5
    };

    int numTransactions = sizeof(transactions) / sizeof(transactions[0]);
    double currentValue = 2000.0;  // Current value of the portfolio

    double twr = calculateTimeWeightedReturn(transactions, numTransactions, currentValue);
    printf("Time-weighted return: %.4f\n", twr);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct {
    double amount;  // Amount of the transaction (positive for purchase, negative for sale)
    double value;   // Value of the portfolio at the time of the transaction
} Transaction;

double calculate_return(double starting_value, double ending_value) {
    return (ending_value - starting_value) / starting_value;
}

double calculate_time_weighted_return(Transaction transactions[], int num_transactions, double final_value) {
    double twr = 1.0;
    double starting_value = 0.0;
    double ending_value = 0.0;

    for (int i = 0; i < num_transactions; i++) {
        if (i == 0) {
            starting_value = transactions[i].value + transactions[i].amount;
            ending_value = transactions[i].value;
        } else {
            starting_value = ending_value;
            ending_value = transactions[i].value + transactions[i].amount;
        }

        double return_rate = calculate_return(starting_value, ending_value);
        twr *= (1 + return_rate);
    }

    // For the final sub-period, use the final value of the portfolio
    double final_return_rate = calculate_return(ending_value, final_value);
    twr *= (1 + final_return_rate);

    return twr - 1.0;  // Convert to a percentage return
}

int main() {
    Transaction transactions[] = {
        {10000, 10000},  // Purchase 10000 at value 10000
        {-5000, 15000}, // Sell 5000 at value 15000
        {2000, 10000}   // Purchase 2000 at value 10000
    };
    int num_transactions = sizeof(transactions) / sizeof(transactions[0]);
    double final_value = 17000;  // Current value of the portfolio

    double twr = calculate_time_weighted_return(transactions, num_transactions, final_value);

    printf("Time-Weighted Return: %.4f%%\n", twr * 100);

    return 0;
}

#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>

char* find_missing_letters(const char* input) {
    // Static array to store missing letters
    static char missing_letters[27] = {0}; 

    // Reset missing letters array
    memset(missing_letters, 0, sizeof(missing_letters));

    // Boolean array to track which letters are present
    bool present[26] = {false};

    // If input is NULL or empty, return all letters
    if (input == NULL || input[0] == '\0') {
        for (int i = 0; i < 26; i++) {
            missing_letters[i] = 'a' + i;
        }
        missing_letters[26] = '\0';
        return missing_letters;
    }

    // Mark letters present in the input string
    for (int i = 0; input[i] != '\0'; i++) {
        // Convert to lowercase and mark as present
        if (isalpha(input[i])) {
            present[tolower(input[i]) - 'a'] = true;
        }
    }

    // Collect missing letters
    int missing_count = 0;
    for (int i = 0; i < 26; i++) {
        if (!present[i]) {
            missing_letters[missing_count++] = 'a' + i;
        }
    }

    // Null-terminate the missing letters string
    missing_letters[missing_count] = '\0';

    return missing_letters;
}

// Example usage
int main() {
    // Test cases
    printf("Missing letters in 'The quick brown fox jumps over the lazy dog':\n%s\n", 
           find_missing_letters("The quick brown fox jumps over the lazy dog"));

    printf("\nMissing letters in 'abcdefghijklmnopqrstuvwxyz':\n%s\n", 
           find_missing_letters("abcdefghijklmnopqrstuvwxyz"));

    printf("\nMissing letters in an empty string:\n%s\n", 
           find_missing_letters(""));

    printf("\nMissing letters in 'Hello World':\n%s\n", 
           find_missing_letters("Hello World"));

    return 0;
}

#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

#define ALPHABET_SIZE 26

char* findMissingLetters(const char* input) {
    // Arrays to track presence of lowercase and uppercase letters
    int lowercasePresent[ALPHABET_SIZE] = {0};
    int uppercasePresent[ALPHABET_SIZE] = {0};

    // Iterate through the input string and mark the present letters
    for (int i = 0; input[i] != '\0'; i++) {
        if (islower(input[i])) {
            lowercasePresent[input[i] - 'a'] = 1;
        } else if (isupper(input[i])) {
            uppercasePresent[input[i] - 'A'] = 1;
        }
    }

    // Calculate the number of missing lowercase and uppercase letters
    int totalMissing = 0;
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        if (!lowercasePresent[i]) totalMissing++;
        if (!uppercasePresent[i]) totalMissing++;
    }

    // Allocate memory for the result string (+1 for null terminator)
    char* result = (char*)malloc((totalMissing + 1) * sizeof(char));
    if (result == NULL) {
        return NULL; // Memory allocation failed
    }

    // Collect the missing letters
    int index = 0;
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        if (!lowercasePresent[i]) {
            result[index++] = 'a' + i;
        }
    }
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        if (!uppercasePresent[i]) {
            result[index++] = 'A' + i;
        }
    }

    // Null-terminate the result string
    result[index] = '\0';

    return result;
}

int main() {
    // Example usage
    const char* input = "Abcxyz";
    char* missingLetters = findMissingLetters(input);

    printf("Missing letters: %s\n", missingLetters);

    // Free the allocated memory
    free(missingLetters);

    return 0;
}

