// Function to find missing letters in the alphabet from a given string
// Returns a dynamically allocated string of missing letters, or an empty string if none.
// The caller is responsible for freeing the returned string.
char* findMissingLetters(const char* inputString) {
    // Array to keep track of seen letters.
    // 'a' (or 'A') is index 0, 'b' (or 'B') is index 1, ..., 'z' (or 'Z') is index 25.
    int seen[26] = {0}; // Initialize all to 0 (not seen)

    // If the input string is not NULL and not empty, process it
    if (inputString != NULL && strlen(inputString) > 0) {
        for (int i = 0; inputString[i] != '\0'; i++) {
            char lowerChar = tolower(inputString[i]); // Convert to lowercase for consistent indexing

            if (lowerChar >= 'a' && lowerChar <= 'z') {
                seen[lowerChar - 'a'] = 1; // Mark the letter as seen
            }
        }
    } else {
        // If the string is empty or NULL, no letters have been seen,
        // so 'seen' array remains all zeros, which is correct for returning all letters.
    }

    // Now, build the string of missing letters
    char* missingLetters = (char*)malloc(27 * sizeof(char)); // Max 26 letters + null terminator
    if (missingLetters == NULL) {
        perror("Failed to allocate memory for missingLetters");
        return NULL; // Indicate an error
    }
    int missingIndex = 0;

    for (int i = 0; i < 26; i++) {
        if (seen[i] == 0) {
