char* findMissingLetters(const char* str) {
    // Initialize flags for lowercase and uppercase letters
    int lowercaseFlags[26] = {0};
    int uppercaseFlags[26] = {0};

    // Set flags for present letters
    for (const char* p = str; *p; ++p) {
        if (islower(*p)) {
            lowercaseFlags[*p - 'a'] = 1;
        } else if (isupper(*p)) {
            uppercaseFlags[*p - 'A'] = 1;
        }
    }

    // Allocate memory for missing letters
    int missingCount = 0;
    for (int i = 0; i < 26; ++i) {
        if (!lowercaseFlags[i] && !uppercaseFlags[i]) {
            ++missingCount;
        }
    }

    char* missingLetters = malloc((missingCount * 2) + 1); // +1 for null-terminator
    missingLetters[missingCount * 2] = '\0'; // null-terminate the string

    // Generate missing letters
    int index = 0;
    for (int i = 0; i < 26; ++i) {
        if (!lowercaseFlags[i] && !uppercaseFlags[i]) {
            missingLetters[index++] = 'a' + i;
            missingLetters[index++] = 'A' + i;
        }
    }

    return missingLetters;
}

