// Simplified memory allocation tracking structure
typedef struct MemoryBlock {
    void* ptr;           // Pointer to allocated memory
    size_t size;         // Size of allocated memory
    const char* file;    // File where allocation occurred
    int line;            // Line where allocation occurred
    struct MemoryBlock* next;
} MemoryBlock;

// Global memory tracking variables
static MemoryBlock* memoryTracker = NULL;
static int trackingEnabled = 0;

// Function to start memory tracking
void startMemoryTracking() {
    trackingEnabled = 1;
}

// Function to add memory block to tracking list
void trackMemoryAllocation(void* ptr, size_t size, const char* file, int line) {
    if (!trackingEnabled || ptr == NULL) return;

    MemoryBlock* newBlock = malloc(sizeof(MemoryBlock));
    if (newBlock == NULL) {
        fprintf(stderr, "Failed to track memory allocation\n");
        return;
    }

    newBlock->ptr = ptr;
    newBlock->size = size;
    newBlock->file = file;
    newBlock->line = line;
    newBlock->next = memoryTracker;
    memoryTracker = newBlock;
}

// Wrapped malloc with tracking
void* trackedMalloc(size_t size, const char* file, int line) {
    void* ptr = malloc(size);
    trackMemoryAllocation(ptr, size, file, line);
    return ptr;
}

// Wrapped free with tracking removal
void trackedFree(void* ptr, const char* file, int line) {
    if (!trackingEnabled || ptr == NULL) {
        free(ptr);
        return;
    }

    // Remove from tracking list
    MemoryBlock* current = memoryTracker;
    MemoryBlock* prev = NULL;

    while (current != NULL) {
        if (current->ptr == ptr) {
            if (prev == NULL) {
                memoryTracker = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            free(ptr);
            return;
        }
        prev = current;
        current = current->next;
    }

    // If not found in tracking list, regular free
    free(ptr);
}

// Function to detect and report memory leaks
void detectMemoryLeaks() {
    if (!trackingEnabled) return;

    MemoryBlock* current = memoryTracker;
    int leakCount = 0;
    size_t totalLeakedMemory = 0;

    printf("Memory Leak Detection Report:\n");
    printf("----------------------------\n");

    while (current != NULL) {
        printf("Leaked Memory Block:\n");
        printf("  Address: %p\n", current->ptr);
        printf("  Size: %zu bytes\n", current->size);
        printf("  Allocated at: %s:%d\n\n", 
               current->file ? current->file : "Unknown", 
               current->line);

        leakCount++;
        totalLeakedMemory += current->size;
        current = current->next;
    }

    printf("Summary:\n");
    printf("  Total Memory Leaks: %d\n", leakCount);
    printf("  Total Leaked Memory: %zu bytes\n", totalLeakedMemory);
}

// Macro wrappers for easier tracking
#define MALLOC(size) trackedMalloc(size, __FILE__, __LINE__)
#define FREE(ptr) trackedFree(ptr, __FILE__, __LINE__)

// Example usage and demonstration
void someFunction() {
    int* data1 = MALLOC(sizeof(int) * 10);     // Intentional leak
    char* data2 = MALLOC(sizeof(char) * 20);   // Another leak
}

int main() {
    // Start memory tracking
    startMemoryTracking();

    // Call function with memory allocations
    someFunction();

    // Detect and report memory leaks
    detectMemoryLeaks();

    return 0;
}

