#define MAX_ALLOCATIONS 1000

typedef struct {
    void *ptr;
    size_t size;
    const char *file;
    int line;
} AllocationInfo;

AllocationInfo allocations[MAX_ALLOCATIONS];
int allocation_count = 0;

void *track_malloc(size_t size, const char *file, int line) {
    void *ptr = malloc(size);
    if (ptr != NULL) {
        if (allocation_count < MAX_ALLOCATIONS) {
            allocations[allocation_count].ptr = ptr;
            allocations[allocation_count].size = size;
            allocations[allocation_count].file = file;
            allocations[allocation_count].line = line;
            allocation_count++;
        } else {
            fprintf(stderr, "Allocation tracking limit reached!\n");
        }
    }
    return ptr;
}

void track_free(void *ptr) {
    for (int i = 0; i < allocation_count; i++) {
        if (allocations[i].ptr == ptr) {
            free(ptr);
            allocations[i].ptr = NULL; // Mark as freed
            return;
        }
    }
    fprintf(stderr, "Attempt to free untracked memory!\n");
}

void report_memory_leaks() {
    int leaks = 0;
    for (int i = 0; i < allocation_count; i++) {
        if (allocations[i].ptr != NULL) {
            fprintf(stderr, "Memory leak detected: %zu bytes allocated at %s:%d\n",
                    allocations[i].size, allocations[i].file, allocations[i].line);
            leaks++;
        }
    }
    if (leaks == 0) {
        fprintf(stderr, "No memory leaks detected.\n");
    }
}

