typedef struct MemEntry {
    void *ptr;
    size_t size;
    const char *file;
    int line;
    struct MemEntry *next;
} MemEntry;

static MemEntry *mem_list = NULL;

// Internal helpers
void add_entry(void *ptr, size_t size, const char *file, int line) {
    MemEntry *e = malloc(sizeof(MemEntry));
    e->ptr = ptr;
    e->size = size;
    e->file = file;
    e->line = line;
    e->next = mem_list;
    mem_list = e;
}

void remove_entry(void *ptr) {
    MemEntry **pp = &mem_list;
    while (*pp) {
        if ((*pp)->ptr == ptr) {
            MemEntry *to_free = *pp;
            *pp = to_free->next;
            free(to_free);
            return;
        }
        pp = &(*pp)->next;
    }
}

void report_leaks() {
    MemEntry *e = mem_list;
    if (!e) {
        printf("No memory leaks detected.\n");
    }
    while (e) {
        printf("Memory leak detected: %p (%zu bytes) allocated at %s:%d\n",
               e->ptr, e->size, e->file, e->line);
        e = e->next;
    }
}

// Macros to track file/line
#define malloc(size) my_malloc(size, __FILE__, __LINE__)
#define calloc(nmemb, size) my_calloc(nmemb, size, __FILE__, __LINE__)
#define realloc(ptr, size) my_realloc(ptr, size, __FILE__, __LINE__)
#define free(ptr) my_free(ptr)

void *my_malloc(size_t size, const char *file, int line) {
    void *ptr = malloc(size); // Call the real malloc
    if (ptr) {
        add_entry(ptr, size, file, line);
    }
    return ptr;
}

void *my_calloc(size_t nmemb, size_t size, const char *file, int line) {
    void *ptr = calloc(nmemb, size);
    if (ptr) {
        add_entry(ptr, nmemb * size, file, line);
    }
    return ptr;
}

void *my_realloc(void *ptr, size_t size, const char *file, int line) {
    if (!ptr) return my_malloc(size, file, line); // Behave like malloc
    remove_entry(ptr);
    void *newptr = realloc(ptr, size);
    if (newptr) {
        add_entry(newptr, size, file, line);
    }
    return newptr;
}

void my_free(void *ptr) {
    if (ptr) {
        remove_entry(ptr);
        free(ptr);
    }
}

// Call this at exit to report leaks
__attribute__((destructor))
void onexit_report_leaks() {
    report_leaks();
}

#include <stdio.h>
