#include <string.h>

typedef struct MemoryBlock {
    void *ptr;
    size_t size;
    struct MemoryBlock *next;
} MemoryBlock;

MemoryBlock *head = NULL;

void* track_malloc(size_t size, const char *file, int line) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Malloc failed at %s:%d\n", file, line);
        return NULL;
    }

    MemoryBlock *new_block = (MemoryBlock *)malloc(sizeof(MemoryBlock));
    new_block->ptr = ptr;
    new_block->size = size;
    new_block->next = head;
    head = new_block;

    return ptr;
}

void* track_realloc(void *old_ptr, size_t size, const char *file, int line) {
    if (!old_ptr) return track_malloc(size, file, line);

    MemoryBlock *current = head;
    MemoryBlock *prev = NULL;
    while (current) {
        if (current->ptr == old_ptr) {
            void *new_ptr = realloc(old_ptr, size);
            if (!new_ptr) {
                fprintf(stderr, "Realloc failed at %s:%d\n", file, line);
                return NULL;
            }
            current->ptr = new_ptr;
            current->size = size;
            return new_ptr;
        }
        prev = current;
        current = current->next;
    }

    // If we reach here, old_ptr wasn't found
    fprintf(stderr, "Pointer not found for realloc: %s:%d\n", file, line);
    return NULL;
}

void track_free(void *ptr, const char *file, int line) {
    if (!ptr) return;

    MemoryBlock *current = head;
    MemoryBlock *prev = NULL;
    while (current) {
        if (current->ptr == ptr) {
            if (prev) {
                prev->next = current->next;
            } else {
                head = current->next;
            }
            free(current->ptr);
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }

    // If we reach here, ptr wasn't found
    fprintf(stderr, "Attempt to free non-allocated memory at %s:%d\n", file, line);
}

void report_memory_leaks() {
    MemoryBlock *current = head;
    while (current) {
        fprintf(stderr, "Memory leak detected: %p (%zu bytes)\n", current->ptr, current->size);
        current = current->next;
    }
}

