    size_t size;
    struct MemoryBlock *next;
} MemoryBlock;

static MemoryBlock *memory_list = NULL;

void *tracked_malloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr) {
        MemoryBlock *new_block = (MemoryBlock *)malloc(sizeof(MemoryBlock));
        if (new_block) {
            new_block->ptr = ptr;
            new_block->size = size;
            new_block->next = memory_list;
            memory_list = new_block;
        }
    }
    return ptr;
}

void tracked_free(void *ptr) {
    MemoryBlock **current = &memory_list;
    while (*current) {
        if ((*current)->ptr == ptr) {
            MemoryBlock *temp = *current;
            *current = (*current)->next;
            free(temp->ptr); // Free the allocated memory.
            free(temp);      // Free the block metadata.
            return;
        }
        current = &(*current)->next;
    }
    free(ptr); // If pointer not found, just free it.
}

void report_memory_leaks() {
    MemoryBlock *current = memory_list;
    if (current == NULL) {
        printf("No memory leaks detected.\n");
        return;
