    while (current) {
        printf("Leaked block: Address=%p, Size=%zu\n", current->ptr, current->size);
        current = current->next;
    }
}

void clean_up() {
    while (memory_list) {
        MemoryBlock *temp = memory_list;
        memory_list = memory_list->next;
        free(temp->ptr);
        free(temp);
    }
}

