// Linked list node structure to track allocations
typedef struct MemoryNode {
    void* ptr;
    size_t size;
    int line;
    char file[256];
    struct MemoryNode* next;
} MemoryNode;

// Global head of the linked list
MemoryNode* head = NULL;

// Function to add a new allocation to the linked list
void add_allocation(void* ptr, size_t size, int line, const char* file) {
    MemoryNode* node = malloc(sizeof(MemoryNode));
    node->ptr = ptr;
    node->size = size;
    node->line = line;
    strcpy(node->file, file);
    node->next = head;
    head = node;
}

// Function to remove a deallocation from the linked list
void remove_allocation(void* ptr) {
    if (head == NULL) return;

    if (head->ptr == ptr) {
        MemoryNode* temp = head;
        head = head->next;
        free(temp);
    } else {
        MemoryNode* current = head;
        while (current->next!= NULL) {
            if (current->next->ptr == ptr) {
                MemoryNode* temp = current->next;
                current->next = current->next->next;
                free(temp);
                return;
            }
            current = current->next;
        }
    }
}

// Function to report memory leaks
void report_leaks() {
    if (head == NULL) {
        printf("No memory leaks detected.\n");
        return;
    }

    printf("Memory leaks detected:\n");
    MemoryNode* current = head;
    while (current!= NULL) {
        printf("  - %p: %zu bytes, allocated at %s:%d\n", current->ptr, current->size, current->file, current->line);
        current = current->next;
    }
}

