#include <dlfcn.h>

// Define a structure to keep track of allocated memory blocks
typedef struct MemoryBlock {
    void *ptr;
    size_t size;
    struct MemoryBlock *next;
} MemoryBlock;

// Global head of the linked list of allocated memory blocks
static MemoryBlock *head = NULL;

// Function to add a new memory block to the list
static void add_memory_block(void *ptr, size_t size) {
    MemoryBlock *new_block = (MemoryBlock *)malloc(sizeof(MemoryBlock));
    if (new_block == NULL) {
        fprintf(stderr, "Failed to allocate memory for tracking block\n");
        exit(1);
    }
    new_block->ptr = ptr;
    new_block->size = size;
    new_block->next = head;
    head = new_block;
}

// Function to remove a memory block from the list
static void remove_memory_block(void *ptr) {
    MemoryBlock **current = &head;
    while (*current != NULL) {
        if ((*current)->ptr == ptr) {
            MemoryBlock *temp = *current;
            *current = (*current)->next;
            free(temp);
            return;
        }
        current = &(*current)->next;
    }
}

// Function to report memory leaks
static void report_memory_leaks() {
    if (head == NULL) {
        printf("No memory leaks detected.\n");
    } else {
        printf("Memory leaks detected:\n");
        MemoryBlock *current = head;
        while (current != NULL) {
            printf("Leaked block at %p with size %zu bytes\n", current->ptr, current->size);
            current = current->next;
        }
    }
}

// Override malloc
void *malloc(size_t size) {
    void *ptr = dlopen("libc.so.6", RTLD_LAZY);
    if (ptr == NULL) {
        fprintf(stderr, "Failed to load libc: %s\n", dlerror());
        exit(1);
    }
    void *(*real_malloc)(size_t) = dlsym(ptr, "malloc");
    if (real_malloc == NULL) {
        fprintf(stderr, "Failed to find malloc: %s\n", dlerror());
        exit(1);
    }
    void *result = real_malloc(size);
    if (result != NULL) {
        add_memory_block(result, size);
    }
    dlclose(ptr);
    return result;
}

// Override calloc
void *calloc(size_t nmemb, size_t size) {
    void *ptr = dlopen("libc.so.6", RTLD_LAZY);
    if (ptr == NULL) {
        fprintf(stderr, "Failed to load libc: %s\n", dlerror());
        exit(1);
    }
    void *(*real_calloc)(size_t, size_t) = dlsym(ptr, "calloc");
    if (real_calloc == NULL) {
        fprintf(stderr, "Failed to find calloc: %s\n", dlerror());
        exit(1);
    }
    void *result = real_calloc(nmemb, size);
    if (result != NULL) {
        add_memory_block(result, nmemb * size);
    }
    dlclose(ptr);
    return result;
}

// Override realloc
void *realloc(void *ptr, size_t size) {
    void *ptr_libc = dlopen("libc.so.6", RTLD_LAZY);
    if (ptr_libc == NULL) {
        fprintf(stderr, "Failed to load libc: %s\n", dlerror());
        exit(1);
    }
    void *(*real_realloc)(void *, size_t) = dlsym(ptr_libc, "realloc");
    if (real_realloc == NULL) {
        fprintf(stderr, "Failed to find realloc: %s\n", dlerror());
        exit(1);
    }
    void *result = real_realloc(ptr, size);
    if (result != NULL) {
        if (ptr != NULL) {
            remove_memory_block(ptr);
        }
        add_memory_block(result, size);
    }
    dlclose(ptr_libc);
    return result;
}

// Override free
void free(void *ptr) {
    if (ptr != NULL) {
        remove_memory_block(ptr);
    }
    void *ptr_libc = dlopen("libc.so.6", RTLD_LAZY);
    if (ptr_libc == NULL) {
        fprintf(stderr, "Failed to load libc: %s\n", dlerror());
        exit(1);
    }
    void (*real_free)(void *) = dlsym(ptr_libc, "free");
    if (real_free == NULL) {
        fprintf(stderr, "Failed to find free: %s\n", dlerror());
        exit(1);
    }
    real_free(ptr);
    dlclose(ptr_libc);
}

// Register the report_memory_leaks function to be called on exit
__attribute__((constructor))
static void register_at_exit() {
    atexit(report_memory_leaks);
}

