// Memory allocation tracking structure
typedef struct MemoryBlock {
    void* ptr;           // Pointer to allocated memory
    size_t size;         // Size of allocated memory
    const char* file;    // File where allocation occurred
    int line;            // Line number of allocation
    struct MemoryBlock* next;  // Pointer to next tracking node
} MemoryBlock;

// Global head of memory tracking list
static MemoryBlock* memoryTracker = NULL;

// Custom malloc wrapper for tracking
void* tracked_malloc(size_t size, const char* file, int line) {
    // Allocate memory
    void* ptr = malloc(size);

    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed at %s:%d\n", file, line);
        return NULL;
    }

    // Create new tracking node
    MemoryBlock* node = (MemoryBlock*)malloc(sizeof(MemoryBlock));
    if (node == NULL) {
        free(ptr);
        fprintf(stderr, "Tracking allocation failed at %s:%d\n", file, line);
        return NULL;
    }

    // Populate tracking node
    node->ptr = ptr;
    node->size = size;
    node->file = file;
    node->line = line;

    // Link into tracking list
    node->next = memoryTracker;
    memoryTracker = node;

    return ptr;
}

// Custom free wrapper for tracking
void tracked_free(void* ptr, const char* file, int line) {
    if (ptr == NULL) return;

    // Find and remove from tracking list
    MemoryBlock* current = memoryTracker;
    MemoryBlock* prev = NULL;

    while (current != NULL) {
        if (current->ptr == ptr) {
            // Remove from list
            if (prev == NULL) {
                memoryTracker = current->next;
            } else {
                prev->next = current->next;
            }

            // Free the memory and tracking node
            free(ptr);
            free(current);
            return;
        }

        prev = current;
        current = current->next;
    }

    // If not found in tracking list, report potential double-free or invalid free
    fprintf(stderr, "Attempt to free untracked pointer at %s:%d\n", file, line);
    free(ptr);  // Still attempt to free to prevent potential memory corruption
}

// Detect and report memory leaks
void detect_memory_leaks() {
    MemoryBlock* current = memoryTracker;
    int leakCount = 0;

    if (current == NULL) {
        printf("No memory leaks detected.\n");
        return;
    }

    printf("Memory Leaks Detected:\n");
    printf("-------------------\n");

    while (current != NULL) {
        leakCount++;
        printf("Leak at %s:%d - %zu bytes\n", 
               current->file, current->line, current->size);
        current = current->next;
    }

    printf("Total memory leaks: %d\n", leakCount);
}

