int allocation_count = 0;

void* custom_malloc(size_t size, const char* file, int line) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        return NULL;
    }

    if (allocation_count < MAX_ALLOCATIONS) {
        allocations[allocation_count].ptr = ptr;
        allocations[allocation_count].size = size;
        allocations[allocation_count].file = file;
        allocations[allocation_count].line = line;
        allocation_count++;
    } else {
        printf("Warning: Max allocations reached. Cannot track more allocations.\n");
    }

    return ptr;
}

void custom_free(void* ptr) {
    if (ptr == NULL) {
        return;
    }

    for (int i = 0; i < allocation_count; i++) {
        if (allocations[i].ptr == ptr) {
            allocations[i].ptr = NULL; // Mark as freed
            free(ptr);
            return;
        }
    }

    printf("Warning: Attempted to free an untracked or already freed pointer: %p\n", ptr);
    free(ptr); // Free it anyway
}

