    for (int i = 0; i < allocation_count; i++) {
        if (allocations[i].ptr != NULL) {
            printf("Memory leak detected: %zu bytes allocated at %s:%d\n",
                   allocations[i].size, allocations[i].file, allocations[i].line);
            leaks++;
        }
