// Function to add a memory block to the list
void add_memory_block(void *ptr, size_t size) {
    MemoryBlock *new_block = (MemoryBlock *)malloc(sizeof(MemoryBlock));
    if (new_block == NULL) {
        fprintf(stderr, "Failed to allocate memory for memory block tracking\n");
        exit(EXIT_FAILURE);
    }
    new_block->ptr = ptr;
    new_block->size = size;
    new_block->next = head;
    head = new_block;
}

// Function to remove a memory block from the list
void remove_memory_block(void *ptr) {
    MemoryBlock *current = head;
    MemoryBlock *previous = NULL;

    while (current != NULL) {
        if (current->ptr == ptr) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

// Overloaded malloc function
void *malloc(size_t size) {
    void *ptr = (void *)malloc(size);
    if (ptr != NULL) {
        add_memory_block(ptr, size);
    }
    return ptr;
}

