void *realloc(void *ptr, size_t size) {
    void *new_ptr = realloc(ptr, size);
    if (new_ptr != NULL) {
        if (ptr != NULL) {
            remove_memory_block(ptr);
        }
        add_memory_block(new_ptr, size);
    }
    return new_ptr;
}

