#include <stdio.h>
#include <stdbool.h>
#include <string.h>
#include <stdlib.h>

// Enum to represent IP address type
typedef enum {
    IP_INVALID,
    IP_PRIVATE,
    IP_PUBLIC
} IPAddressType;

// Function to check if an IP address is private or public
IPAddressType validateIPv4Address(const char* ipAddress) {
    // Check if input is NULL
    if (ipAddress == NULL) {
        return IP_INVALID;
    }

    // Create a copy of the input string for tokenization
    char* ipCopy = strdup(ipAddress);
    if (ipCopy == NULL) {
        return IP_INVALID;
    }

    // Variables to track parsing
    int octetCount = 0;
    char* token = NULL;
    unsigned int octets[4] = {0};

    // Tokenize the IP address
    token = strtok(ipCopy, ".");

    // Parse each octet
    while (token != NULL && octetCount < 4) {
        // Check if token is a valid number
        char* endptr;
        long value = strtol(token, &endptr, 10);

        // Validate the token
        if (*endptr != '\0' || 
            value < 0 || 
            value > 255 || 
            (token[0] == '0' && strlen(token) > 1)) {
            free(ipCopy);
            return IP_INVALID;
        }

        // Store the octet value
        octets[octetCount] = (unsigned int)value;

        // Move to next token
        token = strtok(NULL, ".");
        octetCount++;
    }

    // Free the copy
    free(ipCopy);

    // Validate total number of octets
    if (octetCount != 4 || token != NULL) {
        return IP_INVALID;
    }

    // Check for private IP address ranges
    // Private IP ranges:
    // 10.0.0.0 - 10.255.255.255
    // 172.16.0.0 - 172.31.255.255
    // 192.168.0.0 - 192.168.255.255
    if ((octets[0] == 10) || 
        (octets[0] == 172 && octets[1] >= 16 && octets[1] <= 31) ||
        (octets[0] == 192 && octets[1] == 168)) {
        return IP_PRIVATE;
    }

    // Loopback address
    if (octets[0] == 127) {
        return IP_PRIVATE;
    }

    // Link-local addresses (169.254.0.0 - 169.254.255.255)
    if (octets[0] == 169 && octets[1] == 254) {
        return IP_PRIVATE;
    }

    return IP_PUBLIC;
}

