bool isValidIPv4(const char *ip) {
    if (ip == NULL) return false;

    int num, dots = 0;
    const char *ptr = ip;

    while (*ptr) {
        if (!isdigit(*ptr) && *ptr != '.') return false;
        ptr++;
    }

    char ipCopy[16];
    strcpy(ipCopy, ip);
    char *token = strtok(ipCopy, ".");

    while (token != NULL) {
        if (!isdigit(token[0])) return false;
        num = atoi(token);
        if (num < 0 || num > 255) return false;
        token = strtok(NULL, ".");
        dots++;
    }

    return dots == 4;
}

bool isPrivateIPv4(const char *ip) {
    int octet1, octet2;
    if (sscanf(ip, "%d.%d", &octet1, &octet2) != 2) return false;

    if (octet1 == 10) return true;
    if (octet1 == 172 && (octet2 >= 16 && octet2 <= 31)) return true;
    if (octet1 == 192 && octet2 == 168) return true;

    return false;
}

