    if (!isValidIPv4(ip)) {
        printf("Invalid IPv4 address.\n");
        return;
    }

    if (isPrivateIPv4(ip)) {
        printf("The IPv4 address %s is private.\n", ip);
    } else {
        printf("The IPv4 address %s is public.\n", ip);
    }
}

