bool is_private_ip(const char *ip) {
    // Check if the given IP is a private IP address
    int first_octet, second_octet;

    sscanf(ip, "%d.%d", &first_octet, &second_octet);

    return (first_octet == 10) || 
           (first_octet == 172 && (second_octet >= 16 && second_octet <= 31)) ||
           (first_octet == 192 && second_octet == 168);
}

bool is_valid_ipv4(const char *ip) {
    int segments = 0; 
    int chCount = 0; 
    int accumulatedValue = 0; 
    int value;

    while (*ip) {
        if (*ip == '.') {
            if (chCount == 0 || chCount > 3) return false; // segment must have 1 to 3 digits
            segments++;
            if (segments > 3) return false; // there can only be 4 segments
            if (accumulatedValue > 255) return false; // value must not exceed 255
            accumulatedValue = 0;
            chCount = 0;
        } else if (*ip >= '0' && *ip <= '9') {
            value = *ip - '0';
            if (accumulatedValue == 0 && value == 0 && chCount > 0) return false; // leading zeros not allowed
            accumulatedValue = accumulatedValue * 10 + value;
            chCount++;
        } else {
            return false; // invalid character
        }
        ip++;
    }

    // Handle last segment
    if (chCount > 0) {
        segments++;
        if (accumulatedValue < 0 || accumulatedValue > 255) return false;
    }

    return segments == 4; // must have exactly 4 segments
}

void parse_ipv4(const char *ip) {
    if (!is_valid_ipv4(ip)) {
        printf("'%s' is not a valid IPv4 address.\n", ip);
        return;
    }

    if (is_private_ip(ip)) {
        printf("'%s' is a valid private IPv4 address.\n", ip);
    } else {
        printf("'%s' is a valid public IPv4 address.\n", ip);
    }
}

