// Function to parse and validate IPv4 address
ip_info parse_ipv4(const char* ip) {
    ip_info info;
    info.public = 1;
    info.private = 0;

    // Split the IP address into octets
    int octets[4];
    int count = sscanf(ip, "%d.%d.%d.%d", &octets[0], &octets[1], &octets[2], &octets[3]);

    // Check if the IP address has four octets
    if (count != 4) {
        printf("Invalid IP address format.\n");
        exit(1);
    }

    // Check each octet for validity
    for (int i = 0; i < 4; i++) {
        if (octets[i] < 0 || octets[i] > 255) {
            printf("Invalid IP address: octet %d out of range.\n", i + 1);
            exit(1);
        }
    }

    // Check for private IP address
    if ((octets[0] == 10) ||
        (octets[0] == 172 && octets[1] >= 16 && octets[1] <= 31) ||
        (octets[0] == 192 && octets[1] == 168)) {
        info.public = 0;
        info.private = 1;
    }

    return info;
}

