// Function to check if an IPv4 address is a private address
int is_private_ipv4(uint32_t ip) {
    uint32_t a = (ip >> 24) & 0xFF;
    uint32_t b = (ip >> 16) & 0xFF;

    // 10.0.0.0 - 10.255.255.255
    if (a == 10) {
        return 1;
    }

    // 172.16.0.0 - 172.31.255.255
    if (a == 172 && b >= 16 && b <= 31) {
        return 1;
    }

    // 192.168.0.0 - 192.168.255.255
    if (a == 192 && b == 168) {
        return 1;
    }

    // 127.0.0.0 - 127.255.255.255 (Loopback)
    if (a == 127) {
        return 1;
    }

    // 169.254.0.0 - 169.254.255.255 (Link-local)
    if (a == 169 && b == 254) {
        return 1;
    }

    return 0;
}

// Function to parse and validate an IPv4 address
int parse_ipv4(const char *ip_str, char **result) {
    struct in_addr ip_addr;
    if (inet_aton(ip_str, &ip_addr) == 0) {
        return -1; // Invalid IPv4 address
    }

    uint32_t ip = ntohl(ip_addr.s_addr);

    // Check if the IP is private
    int is_private = is_private_ipv4(ip);

    if (result) {
        if (is_private) {
            *result = "private";
        } else {
            *result = "public";
        }
    }

    return 0; // Success
}

