    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define MAX_BYTE_VALUES 256

// Function to calculate file entropy
double calculate_entropy(const char* filename) {
    // Open the file in binary read mode
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Error opening file");
        return -1.0;
    }

    // Initialize frequency array for byte counts
    unsigned long byte_freq[MAX_BYTE_VALUES] = {0};

    // Total number of bytes in the file
    unsigned long total_bytes = 0;

    // Read file byte by byte
    int current_byte;
    while ((current_byte = fgetc(file)) != EOF) {
        byte_freq[current_byte]++;
        total_bytes++;
    }

    // Close the file
    fclose(file);

    // If file is empty, return 0 entropy
    if (total_bytes == 0) {
        return 0.0;
    }

    // Calculate entropy
    double entropy = 0.0;
    for (int i = 0; i < MAX_BYTE_VALUES; i++) {
        if (byte_freq[i] > 0) {
            // Calculate probability of byte
            double prob = (double)byte_freq[i] / total_bytes;

            // Calculate entropy contribution
            entropy -= prob * log2(prob);
        }
    }

    return entropy;
}

// Function to print byte frequency distribution
void print_byte_distribution(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    // Initialize frequency array for byte counts
    unsigned long byte_freq[MAX_BYTE_VALUES] = {0};
    unsigned long total_bytes = 0;

    // Read file byte by byte
    int current_byte;
    while ((current_byte = fgetc(file)) != EOF) {
        byte_freq[current_byte]++;
        total_bytes++;
    }

    // Close the file
    fclose(file);

    // Print distribution
    printf("\nByte Frequency Distribution:\n");
    printf("Byte\tFrequency\tPercentage\n");
    printf("----\t---------\t----------\n");

    for (int i = 0; i < MAX_BYTE_VALUES; i++) {
        if (byte_freq[i] > 0) {
            double percentage = ((double)byte_freq[i] / total_bytes) * 100;
            printf("%3d\t%9lu\t\t%6.2f%%\n", i, byte_freq[i], percentage);
        }
    }
}

int main(int argc, char* argv[]) {
    // Check command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    // Get filename from command-line argument
    const char* filename = argv[1];

    // Calculate and display file entropy
    double entropy = calculate_entropy(filename);

    if (entropy >= 0) {
        printf("File: %s\n", filename);
        printf("Total Entropy: %.4f bits\n", entropy);

        // Interpret entropy
        if (entropy < 1.0) {
            printf("Low entropy: File contains very predictable data\n");
        } else if (entropy < 3.0) {
            printf("Moderate entropy: Some predictability in data\n");
        } else if (entropy < 5.0) {
            printf("High entropy: Relatively random data\n");
        } else {
            printf("Very high entropy: Highly random or compressed data\n");
        }

        // Print byte distribution
        print_byte_distribution(filename);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define NUM_BYTES 256

// Function to calculate the entropy of a file
double calculate_entropy(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    // Initialize an array to count the frequency of each byte
    unsigned long byte_count[NUM_BYTES] = {0};
    int total_bytes = 0;

    // Read the file byte by byte and count the frequency of each byte
    int byte;
    while ((byte = fgetc(file)) != EOF) {
        byte_count[byte]++;
        total_bytes++;
    }

    fclose(file);

    // Calculate the entropy
    double entropy = 0.0;
    for (int i = 0; i < NUM_BYTES; i++) {
        if (byte_count[i] > 0) {
            double probability = (double)byte_count[i] / total_bytes;
            entropy -= probability * log2(probability);
        }
    }

    return entropy;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *filename = argv[1];
    double entropy = calculate_entropy(filename);

    printf("Entropy of file '%s': %.5f bits per byte\n", filename, entropy);

    return EXIT_SUCCESS;
