#include <stdlib.h> // For EXIT_SUCCESS, EXIT_FAILURE, exit
#include <math.h>   // For log2 (log base 2)

// Function to calculate the Shannon entropy of a file
double calculate_file_entropy(const char *filename) {
    FILE *file = NULL;
    // Array to store the frequency (counts) of each of the 256 possible byte values
    int counts[256] = {0}; 
    long long total_bytes = 0; // Use long long for potentially very large files
    int byte;                  // Variable to hold the byte read from the file
    double entropy = 0.0;      // Initialize entropy

    // Open the file in binary read mode ("rb")
    file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Error opening file"); // Print system error message
        return -1.0; // Return a negative value to signal an error
    }

    // Read the file byte by byte until EOF (End Of File) is reached
    while ((byte = fgetc(file)) != EOF) {
        counts[byte]++;    // Increment the count for the read byte value
        total_bytes++;     // Increment the total byte count
    }

    // Close the file
    fclose(file);

    // Handle the case of an empty file
    if (total_bytes == 0) {
        fprintf(stderr, "The file '%s' is empty. Entropy is 0.0 bits/byte.\n", filename);
        return 0.0; // An empty file provides no information
    }

    // Calculate entropy using Shannon's formula
    // H = - SUM [ P(x_i) * log2(P(x_i)) ]
    for (int i = 0; i < 256; i++) {
        // Only consider byte values that actually appeared in the file
        if (counts[i] > 0) {
            double probability = (double)counts[i] / total_bytes;
            entropy -= probability * log2(probability);
        }
    }

    return entropy;
}

int main(int argc, char *argv[]) {
    // Check if the correct number of command-line arguments are provided
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE; // Indicate incorrect usage
    }

    // Calculate the entropy of the specified file
    double entropy = calculate_file_entropy(argv[1]);

    // Check if an error occurred during file processing
    if (entropy < 0) {
        return EXIT_FAILURE; // Propagate the error
    }

    // Print the calculated entropy
    printf("Entropy of '%s': %.4f bits/byte\n", argv[1], entropy);
    printf("Theoretical maximum entropy for an 8-bit byte stream: 8.0000 bits/byte\n");

    return EXIT_SUCCESS; // Indicate successful execution
}

