/**
 * Calculate the Shannon entropy of a byte array.
 * 
 * @param array The byte array to calculate entropy for.
 * @param length The length of the byte array.
 * 
 * @return The calculated entropy.
 */
double calculate_entropy(const uint8_t* array, size_t length) {
    // Create a frequency table for each possible byte value
    uint64_t frequency[256] = {0};

    // Count occurrences of each byte
    for (size_t i = 0; i < length; i++) {
        frequency[array[i]]++;
    }

    // Calculate entropy using Shannon's formula
    double entropy = 0.0;
    for (int i = 0; i < 256; i++) {
        if (frequency[i] > 0) {
            double probability = (double)frequency[i] / length;
            double log_probability = -probability * log2(probability);
            entropy += log_probability;
        }
    }

    return entropy;
}

int main(int argc, char* argv[]) {
    if (argc!= 2) {
        fprintf(stderr, "Usage: %s <file_name>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char* file_name = argv[1];
    int file_descriptor = open(file_name, O_RDONLY);

    if (file_descriptor == -1) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    // Get the file size
    off_t file_size = lseek(file_descriptor, 0, SEEK_END);
    if (file_size == -1) {
        perror("Failed to get file size");
        close(file_descriptor);
        return EXIT_FAILURE;
    }

    // Reset the file descriptor to the beginning of the file
    if (lseek(file_descriptor, 0, SEEK_SET) == -1) {
        perror("Failed to reset file descriptor");
        close(file_descriptor);
        return EXIT_FAILURE;
    }

    // Read the file into a byte array
    uint8_t* file_data = malloc((size_t)file_size);
    if (file_data == NULL) {
        fprintf(stderr, "Out of memory\n");
        close(file_descriptor);
        return EXIT_FAILURE;
    }

    ssize_t bytes_read = read(file_descriptor, file_data, (size_t)file_size);
    if (bytes_read!= file_size) {
        perror("Failed to read file");
        free(file_data);
        close(file_descriptor);
        return EXIT_FAILURE;
    }

    // Calculate and display the entropy
    double entropy = calculate_entropy(file_data, (size_t)file_size);
    printf("Entropy of %s: %.6f bits/byte\n", file_name, entropy);

    free(file_data);
    close(file_descriptor);

    return EXIT_SUCCESS;
}

