// Function to count words in text
int countWords(const char* text) {
    int wordCount = 0;
    int inWord = 0;

    while (*text) {
        if (isalpha(*text) && !inWord) {
            wordCount++;
            inWord = 1;
        } else if (!isalpha(*text)) {
            inWord = 0;
        }
        text++;
    }

    return wordCount;
}

// Function to count sentences in text
int countSentences(const char* text) {
    int sentenceCount = 0;

    while (*text) {
        if (*text == '.' || *text == '!' || *text == '?') {
            sentenceCount++;
        }
        text++;
    }

    return sentenceCount > 0 ? sentenceCount : 1;
}

// Function to count syllables in text
int countSyllables(const char* text) {
    int syllableCount = 0;
    int inWord = 0;
    int vowelSequence = 0;

    while (*text) {
        char c = tolower(*text);

        // Check for vowels
        if (strchr("aeiou", c)) {
            if (!inWord) {
                syllableCount++;
                inWord = 1;
            }
            vowelSequence++;
        } else {
            // Reset vowel sequence
            vowelSequence = 0;
            inWord = 0;
        }

        // Handle complex syllable cases
        if (vowelSequence > 2) {
            syllableCount--;
            vowelSequence = 1;
        }

        text++;
    }

    return syllableCount > 0 ? syllableCount : 1;
}

// Flesch-Kincaid Grade Level calculation
float calculateFleschKincaidGrade(const char* text) {
    int words = countWords(text);
    int sentences = countSentences(text);
    int syllables = countSyllables(text);

    float avgSentenceLength = (float)words / sentences;
    float avgSyllablesPerWord = (float)syllables / words;

    return (0.39 * avgSentenceLength) + (11.8 * avgSyllablesPerWord) - 15.59;
}

// Flesch Reading Ease calculation
float calculateFleschReadingEase(const char* text) {
    int words = countWords(text);
    int sentences = countSentences(text);
    int syllables = countSyllables(text);

    float avgSentenceLength = (float)words / sentences;
    float avgSyllablesPerWord = (float)syllables / words;

    return 206.835 - (1.015 * avgSentenceLength) - (84.6 * avgSyllablesPerWord);
}

// Gunning Fog Index calculation
float calculateGunningFogIndex(const char* text) {
    int words = countWords(text);
    int sentences = countSentences(text);
    int complexWords = countSyllables(text) > 2 ? countWords(text) / 10 : 0;

    float avgSentenceLength = (float)words / sentences;
    float percentComplexWords = ((float)complexWords / words) * 100;

    return 0.4 * (avgSentenceLength + percentComplexWords);
}

int main() {
    const char* text = "Lorem ipsum dolor sit amet, consectetur adipiscing elit.";

    printf("Text Analysis:\n");
    printf("Words: %d\n", countWords(text));
    printf("Sentences: %d\n", countSentences(text));
    printf("Syllables: %d\n\n", countSyllables(text));

    printf("Readability Metrics:\n");
    printf("Flesch-Kincaid Grade Level: %.2f\n", calculateFleschKincaidGrade(text));
    printf("Flesch Reading Ease: %.2f\n", calculateFleschReadingEase(text));
    printf("Gunning Fog Index: %.2f\n", calculateGunningFogIndex(text));

    return 0;
}

