// Function to count the number of syllables in a word
int count_syllables(const char *word) {
    int count = 0;
    int length = strlen(word);
    int i;

    for (i = 0; i < length; i++) {
        if (tolower(word[i]) == 'a' || tolower(word[i]) == 'e' || 
            tolower(word[i]) == 'i' || tolower(word[i]) == 'o' || 
            tolower(word[i]) == 'u') {
            count++;
            // Skip consecutive vowels
            while (i + 1 < length && (tolower(word[i + 1]) == 'a' || 
                   tolower(word[i + 1]) == 'e' || tolower(word[i + 1]) == 'i' || 
                   tolower(word[i + 1]) == 'o' || tolower(word[i + 1]) == 'u')) {
                i++;
            }
        }
    }
    // Subtract one if the word ends with 'e' and it's not the only vowel
    if (length > 1 && tolower(word[length - 1]) == 'e' && count > 1) {
        count--;
    }
    return count;
}

