// Function to check if a character is a vowel
bool is_vowel(char c) {
    c = tolower(c);
    return (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' || c == 'y');
}

// Function to count syllables in a word (simplified for estimation)
// This is a very basic heuristic and will not be accurate for all words.
// For a more accurate syllable count, you'd need a dictionary or more complex rules.
int count_syllables(const char *word) {
    int syllables = 0;
    int len = strlen(word);
    bool consecutive_vowels = false;

    if (len == 0) return 0;

    // Rule 1: Count groups of consecutive vowels.
    // Each group counts as one syllable.
    for (int i = 0; i < len; i++) {
        if (is_vowel(word[i])) {
            if (!consecutive_vowels) {
                syllables++;
                consecutive_vowels = true;
            }
        } else {
            consecutive_vowels = false;
        }
    }

    // Rule 2: If a word ends with 'e' (not 'le'), and there's no other vowel sound, subtract one syllable.
    // Example: "make" (1 syllable), "table" (2 syllables)
    // This rule is tricky to implement perfectly without more context.
    // A simpler approach for the 'e' rule: if it ends in 'e' and has more than 1 syllable
    // and the character before 'e' is not 'l' or 'r', then it's likely a silent 'e'.
    if (len > 1 && tolower(word[len - 1]) == 'e' && syllables > 1) {
        // Check if the 'e' is part of an 'le' ending or if it's a silent 'e'
        if (len > 2 && tolower(word[len - 2]) != 'l' && tolower(word[len - 2]) != 'r') {
             // Heuristic: If the last 'e' is preceded by a consonant, and it's not 'le', reduce syllable count.
             // This is still a simplification.
             // For example, "chocolate" -> 3 syllables, but this logic might reduce it to 2.
             // A better approach would be to check if the syllable before the 'e' is already complete.
             syllables--;
        }
    }

    // Rule 3: If syllables is 0, make it 1 (for words like "the", which our vowel count might miss if considered consonants).
    if (syllables == 0 && len > 0) {
        syllables = 1;
    }

    return syllables;
}

