// Function to count syllables in a single word (very simple heuristic)
int count_syllables(const char *word) {
    int count = 0;
    int length = strlen(word);
    int prev_vowel = 0;
    for (int i = 0; i < length; i++) {
        char ch = tolower(word[i]);
        if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u' || ch == 'y') {
            if (!prev_vowel) {
                count++;
                prev_vowel = 1;
            }
        }
        else prev_vowel = 0;
    }
    // Remove silent 'e'
    if (length > 1 && tolower(word[length-1]) == 'e' && !(
            tolower(word[length-2]) == 'l' &&
            length > 2 &&
            tolower(word[length-3]) == 'b'
        )) {
        count--;
    }
    if (count <= 0) count = 1;
    return count;
}

// Function to count words, sentences, syllables
void analyze_text(const char *text, int *n_sentences, int *n_words, int *n_syllables) {
    *n_sentences = 0;
    *n_words = 0;
    *n_syllables = 0;

    int in_word = 0;
    char word[64];
    int word_len = 0;
    for (int i = 0; text[i]; ++i) {
        if (isalpha(text[i])) {
            if (word_len < (int)sizeof(word)-1)
                word[word_len++] = text[i];
            in_word = 1;
        } else {
            if (in_word && word_len > 0) {
                word[word_len] = '\0';
                (*n_words)++;
                *n_syllables += count_syllables(word);
                word_len = 0;
            }
            in_word = 0;
            if (text[i] == '.' || text[i] == '!' || text[i] == '?')
                (*n_sentences)++;
        }
    }
    // Catch last word
    if (in_word && word_len > 0) {
        word[word_len] = '\0';
        (*n_words)++;
        *n_syllables += count_syllables(word);
    }
}

