int countSyllables(const char* text) {
    int count = 0;
    int inWord = 0;
    int syllablesCurrentWord = 0;

    while (*text) {
        if (isalpha(*text)) {
            if (!inWord) inWord = 1;

            if (syllablesCurrentWord == 0) {
                syllablesCurrentWord++;  // Start with assuming at least 1 syllable per word
            }

            if (strchr("aeiouy", tolower(*text))) {  // Counting vowels as possible syllables
                syllablesCurrentWord++;
            }
        } else {
            if (inWord) {
                inWord = 0;
                count += syllablesCurrentWord > 1 ? syllablesCurrentWord : 1;
                syllablesCurrentWord = 0;
            }
        }
        text++;
    }
    // For the last word (if there is one)
    count += syllablesCurrentWord > 1 ? syllablesCurrentWord : 1;

    return count;
}

double computeFleschReadingEase(int words, int sentences, int syllables) {
    return 206.835 - 1.015 * ((double)words / sentences) - 84.6 * ((double)syllables / words);
}

