// Function to count the number of syllables in a word
int count_syllables(const char *word) {
    int syllables = 0;
    int vowels = 0;

    for (int i = 0; word[i]; i++) {
        if (tolower(word[i]) == 'a' || tolower(word[i]) == 'e' || tolower(word[i]) == 'i' ||
            tolower(word[i]) == 'o' || tolower(word[i]) == 'u') {
            if (vowels == 0 || tolower(word[i-1]) != 'a' && tolower(word[i-1]) != 'e' &&
                tolower(word[i-1]) != 'i' && tolower(word[i-1]) != 'o' && tolower(word[i-1]) != 'u') {
                vowels++;
            }
        }
    }

    syllables = vowels;

    // Remove silent 'e' at the end of the word
    if (tolower(word[strlen(word) - 1]) == 'e') {
        syllables -= 1;
    }

    // Remove 'y' as a vowel at the end of the word
    if (tolower(word[strlen(word) - 1]) == 'y' && tolower(word[strlen(word) - 2]) != 'a' &&
        tolower(word[strlen(word) - 2]) != 'e' && tolower(word[strlen(word) - 2]) != 'i' &&
        tolower(word[strlen(word) - 2]) != 'o' && tolower(word[strlen(word) - 2]) != 'u') {
        syllables -= 1;
    }

    // Minimum syllable count is 1
    return (syllables <= 0) ? 1 : syllables;
}

// Function to estimate the reading level using the Flesch-Kincaid Grade Level test
double calculate_reading_level(const char *text) {
    const char *delimiters = " ,.:;?!\n";
    char *token;
    char *text_copy = (char *) malloc(strlen(text) + 1);
    strcpy(text_copy, text);

    int num_words = 0;
    int num_sentences = 0;
    int num_syllables = 0;

    // Count the number of words and sentences
    token = strtok(text_copy, delimiters);
    while (token != NULL) {
        num_words++;
        token = strtok(NULL, delimiters);
    }

    for (int i = 0; text[i]; i++) {
        if (text[i] == '.' || text[i] == '!' || text[i] == '?') {
            num_sentences++;
        }
    }

    // Calculate the number of syllables
    token = strtok(text_copy, delimiters);
    while (token != NULL) {
        num_syllables += count_syllables(token);
        token = strtok(NULL, delimiters);
    }

    free(text_copy);

    // Calculate the Flesch-Kincaid Grade Level
    double average_sentence_length = (double) num_words / num_sentences;
    double average_syllables_per_word = (double) num_syllables / num_words;

    double reading_level = (0.39 * average_sentence_length) + (0.11 * average_syllables_per_word) + 0.58;

    return reading_level;
}

int main() {
    const char *text = "Lorem ipsum dolor sit amet, consectetur adipiscing elit.";
    double reading_level = calculate_reading_level(text);

    printf("Text: %s\n", text);
    printf("Estimated reading level: %.2f grade level\n", reading_level);

    return 0;
}

