}

// Function to count the number of words in the text
int countWords(const char *text) {
    int count = 0;
    int inWord = 0;

    for (int i = 0; text[i]; i++) {
        if (isalpha(text[i])) {
            if (!inWord) {
                count++;
                inWord = 1;
            }
        } else {
            inWord = 0;
        }
    }

    return count;
}

// Function to count the number of syllables in a word
int countSyllablesInWord(const char *word) {
    int syllableCount = 0;
    int hasVowel = 0;

    for (int i = 0; word[i]; i++) {
        if (strchr("aeiouyAEIOUY", word[i])) {
            if (!hasVowel || (i > 0 && !strchr("aeiouyAEIOUY", word[i - 1]))) {
                syllableCount++;
            }
            hasVowel = 1;
        } else {
            hasVowel = 0;
        }
    }

    // If the last character is 'e' or 'E', it might not be a syllable
    if (syllableCount > 0 && (word[strlen(word) - 1] == 'e' || word[strlen(word) - 1] == 'E')) {
        syllableCount--;
    }

    // Ensure at least one syllable per word
    if (syllableCount == 0) {
        syllableCount = 1;
    }

    return syllableCount;
}

// Function to count the total number of syllables in the text
int countSyllables(const char *text) {
    int syllableCount = 0;
    int startIndex = 0;
    int inWord = 0;

    for (int i = 0; text[i]; i++) {
        if (isalpha(text[i])) {
            if (!inWord) {
                startIndex = i;
                inWord = 1;
            }
        } else {
            if (inWord) {
                syllableCount += countSyllablesInWord(&text[startIndex]);
                inWord = 0;
            }
        }
    }

    // Handle the last word if it ends without punctuation
    if (inWord) {
        syllableCount += countSyllablesInWord(&text[startIndex]);
    }

    return syllableCount;
}

// Function to calculate the Flesch-Kincaid Grade Level
double fleschKincaidGradeLevel(int wordCount, int sentenceCount, int syllableCount) {
    if (wordCount == 0 || sentenceCount == 0) {
        return 0.0;
    }
    double gradeLevel = 0.39 * (wordCount / sentenceCount) + 11.8 * (syllableCount / wordCount) - 15.59;
    return gradeLevel;
}

