    const char *text = "Lorem ipsum dolor sit amet, consectetur adipiscing elit.";

    int sentenceCount = countSentences(text);
    int wordCount = countWords(text);
    int syllableCount = countSyllables(text);

    printf("Number of sentences: %d\n", sentenceCount);
    printf("Number of words: %d\n", wordCount);
    printf("Number of syllables: %d\n", syllableCount);

    double gradeLevel = fleschKincaidGradeLevel(wordCount, sentenceCount, syllableCount);
