    return 0;
}

#include <stdio.h>
#include <limits.h>
#include <stdbool.h>

#define MAX_CITIES 15

// Function to find the minimum of two integers
int min(int a, int b) {
    return (a < b) ? a : b;
}

// Function to solve the Traveling Salesman Problem
int travelingSalesmanProblem(int graph[MAX_CITIES][MAX_CITIES], int n) {
    // All cities except starting city
    int vertices = n;

    // 2^n possible subsets of vertices
    int total_sets = 1 << vertices;

    // Dynamic programming table to store minimum cost
    int dp[total_sets][MAX_CITIES];

    // Initialize DP table with maximum values
    for (int i = 0; i < total_sets; i++) {
        for (int j = 0; j < vertices; j++) {
            dp[i][j] = INT_MAX;
        }
    }

    // Base case: start from first city
    dp[1][0] = 0;

    // Iterate through all possible subsets
    for (int set = 1; set < total_sets; set++) {
        // If current set doesn't include the starting city, skip
        if (!(set & 1)) continue;

        // Try all possible last cities for current subset
        for (int last = 1; last < vertices; last++) {
            // If last city is already in subset
            if (set & (1 << last)) {
                // Remove last city from current subset
                int prev_set = set ^ (1 << last);

                // Find minimum cost to reach last city
                for (int k = 0; k < vertices; k++) {
                    if (prev_set & (1 << k)) {
                        int temp_cost = dp[prev_set][k] + graph[k][last];
                        dp[set][last] = min(dp[set][last], temp_cost);
                    }
                }
            }
        }
    }

    // Find minimum cost to return to starting city
    int min_cost = INT_MAX;
    for (int i = 1; i < vertices; i++) {
        int temp_cost = dp[total_sets - 1][i] + graph[i][0];
        min_cost = min(min_cost, temp_cost);
    }

    return min_cost;
}

// Function to print the optimal route
void printOptimalRoute(int graph[MAX_CITIES][MAX_CITIES], int n) {
    int vertices = n;
    int total_sets = 1 << vertices;
    int dp[total_sets][MAX_CITIES];
    int route[MAX_CITIES];

    // Same initialization as previous function
    for (int i = 0; i < total_sets; i++) {
        for (int j = 0; j < vertices; j++) {
            dp[i][j] = INT_MAX;
        }
    }

    dp[1][0] = 0;

    for (int set = 1; set < total_sets; set++) {
        if (!(set & 1)) continue;

        for (int last = 1; last < vertices; last++) {
            if (set & (1 << last)) {
                int prev_set = set ^ (1 << last);

                for (int k = 0; k < vertices; k++) {
                    if (prev_set & (1 << k)) {
                        int temp_cost = dp[prev_set][k] + graph[k][last];
                        if (temp_cost < dp[set][last]) {
                            dp[set][last] = temp_cost;
                        }
                    }
                }
            }
        }
    }

    // Find the minimum cost route
    int min_cost = INT_MAX;
    int last_city = 0;
    for (int i = 1; i < vertices; i++) {
        int temp_cost = dp[total_sets - 1][i] + graph[i][0];
        if (temp_cost < min_cost) {
            min_cost = temp_cost;
            last_city = i;
        }
    }

    // Reconstruct the route
    int current_set = total_sets - 1;
    int current_city = last_city;
    route[vertices - 1] = current_city;

    for (int i = vertices - 2; i > 0; i--) {
        int prev_city = 0;
        for (int j = 0; j < vertices; j++) {
            if (current_set & (1 << j)) {
                int prev_set = current_set ^ (1 << current_city);
                if (dp[prev_set][j] + graph[j][current_city] == dp[current_set][current_city]) {
                    prev_city = j;
                    break;
                }
            }
        }
        route[i] = prev_city;
        current_city = prev_city;
        current_set = current_set ^ (1 << route[i]);
    }

    route[0] = 0;

    // Print the route
    printf("Optimal Route: ");
    for (int i = 0; i < vertices; i++) {
        printf("%d ", route[i]);
    }
    printf("\n");
    printf("Minimum Cost: %d\n", min_cost);
}

int main() {
    int n;
    printf("Enter number of cities: ");
    scanf("%d", &n);

    int graph[MAX_CITIES][MAX_CITIES];

    printf("Enter the distance matrix:\n");
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &graph[i][j]);
        }
    }

    int min_cost = travelingSalesmanProblem(graph, n);
    printf("Minimum Cost Route: %d\n", min_cost);

    printOptimalRoute(graph, n);

    return 0;
}

