int n; // Number of cities
int distance[MAX_CITIES][MAX_CITIES]; // Distance matrix
bool visited[MAX_CITIES]; // To keep track of visited cities
int min_path[MAX_CITIES + 1]; // To store the shortest path
int min_cost = INT_MAX; // To store the minimum cost

// Function to calculate the shortest route using backtracking
void tsp(int current_city, int count, int cost, int path[]) {
    if (count == n && distance[current_city][0] > 0) {
        if (cost + distance[current_city][0] < min_cost) {
            min_cost = cost + distance[current_city][0];
            for (int i = 0; i < n; i++) {
                min_path[i] = path[i];
            }
            min_path[n] = 0; // Return to the starting city
        }
        return;
    }

    for (int i = 0; i < n; i++) {
        if (!visited[i] && distance[current_city][i] > 0) {
            visited[i] = true;
            path[count] = i;
            tsp(i, count + 1, cost + distance[current_city][i], path);
            visited[i] = false;
        }
    }
}

