#include <math.h>
#include <limits.h> // For INT_MAX

// Structure to represent a city
typedef struct {
    int id;
    double x;
    double y;
} City;

// Function to calculate the Euclidean distance between two cities
double calculateDistance(City c1, City c2) {
    return sqrt(pow(c1.x - c2.x, 2) + pow(c1.y - c2.y, 2));
}

// Function to implement the Nearest Neighbor algorithm for TSP
void solveTSPNearestNeighbor(City *cities, int numCities) {
    if (numCities <= 0) {
        printf("No cities to process.\n");
        return;
    }

    int *visited = (int *)calloc(numCities, sizeof(int)); // 0: unvisited, 1: visited
    int *tour = (int *)malloc(numCities * sizeof(int)); // Stores the order of visited city IDs
    double totalDistance = 0.0;

    int currentCityIndex = 0; // Start with the first city (index 0)
    tour[0] = cities[currentCityIndex].id; // Add starting city to tour
    visited[currentCityIndex] = 1; // Mark as visited

    printf("Nearest Neighbor Tour:\n");
    printf("%d", cities[currentCityIndex].id); // Print starting city ID

    int i;
    for (i = 1; i < numCities; i++) {
        double minDistance = INT_MAX;
        int nextCityIndex = -1;

        // Find the nearest unvisited city
        int j;
        for (j = 0; j < numCities; j++) {
            if (!visited[j]) { // If city j is not visited
                double dist = calculateDistance(cities[currentCityIndex], cities[j]);
                if (dist < minDistance) {
                    minDistance = dist;
                    nextCityIndex = j;
                }
            }
        }

        // Add the nearest city to the tour
        tour[i] = cities[nextCityIndex].id;
        visited[nextCityIndex] = 1;
        totalDistance += minDistance;
        currentCityIndex = nextCityIndex; // Move to the newly visited city
        printf(" -> %d", cities[currentCityIndex].id);
    }

    // Return to the starting city to complete the cycle
    totalDistance += calculateDistance(cities[currentCityIndex], cities[0]);
    printf(" -> %d\n", cities[0].id); // Print return to start

    printf("\nTotal distance: %.2f\n", totalDistance);

    free(visited);
    free(tour);
}

int main() {
    int numCities;

    printf("Enter the number of cities: ");
    scanf("%d", &numCities);

    if (numCities <= 0) {
        printf("Please enter a positive number of cities.\n");
        return 1;
    }

    City *cities = (City *)malloc(numCities * sizeof(City));
    if (cities == NULL) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    int i;
    for (i = 0; i < numCities; i++) {
        cities[i].id = i; // Assign ID based on index
        printf("Enter coordinates for City %d (x y): ", i);
        scanf("%lf %lf", &cities[i].x, &cities[i].y);
    }

    solveTSPNearestNeighbor(cities, numCities);

    free(cities); // Free dynamically allocated memory for cities

    return 0;
}

#include <stdio.h>
#include <stdbool.h>
#include <limits.h>

#define N 4 // Number of cities (change as needed)

// Example graph: adjacency matrix (4 cities)
int graph[N][N] = {
    {0, 10, 15, 20},
    {10, 0, 35, 25},
    {15, 35, 0, 30},
    {20, 25, 30, 0}
};

int min_path = INT_MAX;
int best_path[N+1];

void swap(int *x, int *y) {
    int t = *x;
    *x = *y;
    *y = t;
}

int calculate_cost(int path[]) {
    int cost = 0;
    for (int i = 0; i < N-1; i++)
        cost += graph[path[i]][path[i+1]];
    cost += graph[path[N-1]][path[0]]; // Return to start
    return cost;
}

// Generate all permutations of cities (except first city which is fixed)
void tsp_permutations(int path[], int l, int r) {
    if (l == r) {
        int cost = calculate_cost(path);
        if (cost < min_path) {
            min_path = cost;
            for (int i = 0; i < N; i++)
                best_path[i] = path[i];
            best_path[N] = path[0]; // to return to start
        }
    } else {
        for (int i = l; i <= r; i++) {
            swap(&path[l], &path[i]);
            tsp_permutations(path, l+1, r);
            swap(&path[l], &path[i]);
        }
    }
}

int main() {
    int path[N];
    // Let's fix starting city as 0
    for (int i = 0; i < N; i++)
        path[i] = i;

    tsp_permutations(path, 1, N-1); // Fix first city
    printf("Minimum cost: %d\n", min_path);
    printf("Path: ");
    for (int i = 0; i <= N; i++)
        printf("%d ", best_path[i]);
    printf("\n");
    return 0;
}

