int tsp(int graph[][NUM_CITIES], int path[], int currentPos, int n, int count, int cost, int visited[], int *minCost) {
    if (count == n && graph[currentPos][0]) {
        if (cost + graph[currentPos][0] < *minCost) {
            *minCost = cost + graph[currentPos][0];
            for (int i = 0; i < n; i++) {
                path[i] = visited[i];
            }
        }
        return *minCost;
    }

    for (int i = 0; i < n; i++) {
        if (!visited[i] && graph[currentPos][i]) {
            visited[i] = 1;
            tsp(graph, path, i, n, count + 1, cost + graph[currentPos][i], visited, minCost);
            visited[i] = 0;
        }
    }
    return *minCost;
}

