int cost[MAX_CITIES][MAX_CITIES]; // Adjacency matrix to represent costs
int min_cost = INT_MAX; // Minimum cost found
int path[MAX_CITIES]; // Store the best path
int best_path[MAX_CITIES]; // Store the best path for the result

void tsp(int city, int visited[], int current_cost, int depth) {
    if (depth == n) {
        // Return to starting city
        current_cost += cost[city][0];
        if (current_cost < min_cost) {
            min_cost = current_cost;
            for (int i = 0; i < n; i++) {
                best_path[i] = path[i];
            }
            best_path[n] = 0; // Returning to the starting city
        }
        return;
    }

    for (int next_city = 0; next_city < n; next_city++) {
        if (!visited[next_city]) {
            visited[next_city] = 1;
            path[depth] = next_city; // Add city to path
            tsp(next_city, visited, current_cost + cost[city][next_city], depth + 1);
            visited[next_city] = 0; // Backtrack
        }
    }
}

int main() {
    printf("Enter the number of cities: ");
    scanf("%d", &n);

    printf("Enter the cost matrix (use 0 for no direct path):\n");
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &cost[i][j]);
        }
    }

    int visited[MAX_CITIES] = {0};
    path[0] = 0; // Starting from the first city
    visited[0] = 1; // Mark the starting city as visited

    tsp(0, visited, 0, 1); // Start the TSP recursion

    printf("Minimum cost: %d\n", min_cost);
    printf("Best path: ");
    for (int i = 0; i <= n; i++) { // Ensure to show return to the start
        printf("%d ", best_path[i]);
    }
    printf("\n");

    return 0;
}

