// Define the number of cities
#define NUM_CITIES 5

// Define the cities with their x and y coordinates
typedef struct {
    int x;
    int y;
} City;

// Function to calculate the distance between two cities
double calculate_distance(City city1, City city2) {
    int dx = city1.x - city2.x;
    int dy = city1.y - city2.y;
    return sqrt(dx * dx + dy * dy);
}

// Function to find the nearest neighbor of a city
int find_nearest_neighbor(City cities[], int current_city, int visited[]) {
    double min_distance = INFINITY;
    int nearest_city = -1;

    for (int i = 0; i < NUM_CITIES; i++) {
        if (i != current_city && !visited[i]) {
            double distance = calculate_distance(cities[current_city], cities[i]);
            if (distance < min_distance) {
                min_distance = distance;
                nearest_city = i;
            }
        }
    }

    return nearest_city;
}

// Function to solve the TSP using the nearest neighbor algorithm
void solve_tsp(City cities[]) {
    int visited[NUM_CITIES] = {0};
    int current_city = 0;
    visited[current_city] = 1;
    printf("Route: %d", current_city);

    for (int i = 1; i < NUM_CITIES; i++) {
        int nearest_city = find_nearest_neighbor(cities, current_city, visited);
        visited[nearest_city] = 1;
        printf(" -> %d", nearest_city);
        current_city = nearest_city;
    }

    // Return to the starting city
    printf(" -> %d\n", 0);
}

