    {0, 10, 15, 20},
    {10, 0, 35, 25},
    {15, 35, 0, 30},
    {20, 25, 30, 0}
};

// Function to calculate the total distance of a given tour
int calculateTotalDistance(int tour[], int n) {
    int totalDistance = 0;
    for (int i = 0; i < n - 1; i++) {
        totalDistance += distance[tour[i]][tour[i + 1]];
    }
    totalDistance += distance[tour[n - 1]][tour[0]]; // Return to the starting city
    return totalDistance;
}

// Function to generate permutations and find the minimum distance
void tsp(int start, int *minDistance, int tour[], int visited[], int pos, int n) {
    if (pos == n) {
        int currentDistance = calculateTotalDistance(tour, n);
        if (currentDistance < *minDistance) {
            *minDistance = currentDistance;
        }
        return;
    }

    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            tour[pos] = i;
            visited[i] = 1;
            tsp(start, minDistance, tour, visited, pos + 1, n);
            visited[i] = 0;
        }
    }
}

