// Function to compute the Riemann zeta function
double riemann_zeta(double s, int max_terms) {
    // Check for special cases
    if (s < 0) {
        // Use reflection formula for negative s
        double gamma_factor = tgamma(1 - s);
        double sin_factor = sin(M_PI * s / 2);
        double zeta_positive = riemann_zeta(1 - s, max_terms);
        return 2 * pow(2 * M_PI, -s) * sin_factor * gamma_factor * cos(M_PI * s / 2);
    }

    // Special case for s = 1 (divergent series)
    if (s == 1.0) {
        printf("Zeta function diverges at s = 1\n");
        return INFINITY;
    }

    // Series approximation
    double zeta = 0.0;
    int k;

    for (k = 1; k <= max_terms; k++) {
        zeta += 1.0 / pow(k, s);
    }

    return zeta;
}

