// Function to compute the Riemann zeta function zeta(s) using a series approximation
// for Re(s) > 1.
// N_terms: The number of terms to sum in the Dirichlet series.
// A larger N_terms leads to a more accurate approximation but takes longer.
complex double riemann_zeta_series(complex double s, int N_terms) {
    if (creal(s) <= 1.0) {
        fprintf(stderr, "Warning: The Dirichlet series approximation only converges for Re(s) > 1.\n");
        fprintf(stderr, "         Result for Re(s) <= 1 will be inaccurate/divergent.\n");
    }

    complex double sum = 0.0 + 0.0 * I; // Initialize sum to zero complex number

    for (long long n = 1; n <= N_terms; ++n) {
        // Calculate 1/n^s
        // n^s = exp(s * log(n))
        // complex double term = 1.0 / cpow(n, s); // cpow(n, s) works for complex s

        // Manual calculation of n^s could be like:
        // complex double log_n = log(n) + 0.0 * I; // log(n) is real, make it complex
        // complex double n_to_s = cexp(s * log_n);
        // complex double term = 1.0 / n_to_s;

        // Using cpow is generally safer and more optimized for complex exponents
        complex double term = 1.0 / cpowl(n, s); // Use cpowl for long double complex if needed, but cpow is usually fine for double complex

        sum += term;
    }

    return sum;
}

