// Riemann zeta function approximation using direct summation
double zeta(double s, int max_terms, double tolerance) {
    double sum = 0.0;
    double term;
    int n;

    for (n = 1; n <= max_terms; ++n) {
        term = 1.0 / pow(n, s);
        sum += term;
        if (term < tolerance)
            break;
    }
    return sum;
}

