#include <regex.h>

#define MAX_BUFFER_SIZE 4096

// Function to perform regex replacement
char* regex_replace(const char* str, const char* regex_pattern, const char* replacement) {
    regex_t regex;
    int reti;
    char* result = NULL;

    // Compile regex
    reti = regcomp(&regex, regex_pattern, REG_EXTENDED);
    if (reti != 0) {
        fprintf(stderr, "Could not compile regex\n");
        return NULL;
    }

    // Allocate memory for result
    result = malloc(MAX_BUFFER_SIZE * sizeof(char));
    if (result == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        regfree(&regex);
        return NULL;
    }

    // Execute regex substitution
    size_t nmatch = 1;
    regmatch_t pmatch[1];
    char* src = strdup(str);
    char* dst = result;

    while (*src) {
        if (regexec(&regex, src, nmatch, pmatch, 0) == 0) {
            // Copy part before match
            size_t prefix_len = pmatch[0].rm_so;
            strncpy(dst, src, prefix_len);
            dst += prefix_len;

            // Copy replacement
            strcpy(dst, replacement);
            dst += strlen(replacement);

            // Move source pointer
            src += pmatch[0].rm_eo;
        } else {
            // No more matches, copy remaining string
            strcpy(dst, src);
            break;
        }
    }

    regfree(&regex);
    free(src - strlen(str));
    return result;
}

// Function to copy file with optional regex replacement
int copy_file(const char* source_file, const char* dest_file, 
              const char* regex_pattern, const char* replacement) {
    FILE* src;
    FILE* dest;
    char buffer[MAX_BUFFER_SIZE];

    // Open source file
    src = fopen(source_file, "r");
    if (src == NULL) {
        fprintf(stderr, "Error: Could not open source file %s\n", source_file);
        return -1;
    }

    // Open destination file
    dest = fopen(dest_file, "w");
    if (dest == NULL) {
        fprintf(stderr, "Error: Could not open destination file %s\n", dest_file);
        fclose(src);
        return -1;
    }

    // Read and write file contents
    while (fgets(buffer, sizeof(buffer), src) != NULL) {
        // Apply regex replacement if pattern is provided
        if (regex_pattern != NULL && replacement != NULL) {
            char* replaced_text = regex_replace(buffer, regex_pattern, replacement);
            if (replaced_text != NULL) {
                fputs(replaced_text, dest);
                free(replaced_text);
            } else {
                fputs(buffer, dest);
            }
        } else {
            // Direct file copy
            fputs(buffer, dest);
        }
    }

    // Close files
    fclose(src);
    fclose(dest);
    return 0;
}

// Usage instructions
void print_usage(const char* program_name) {
    printf("Usage: %s <source_file> <destination_file> [regex_pattern] [replacement]\n", program_name);
    printf("  - source_file: Path to the source file\n");
    printf("  - destination_file: Path to the destination file\n");
    printf("  - regex_pattern (optional): Regex pattern for text replacement\n");
    printf("  - replacement (optional): Replacement text for regex pattern\n");
}

int main(int argc, char* argv[]) {
    // Check command-line arguments
    if (argc < 3) {
        print_usage(argv[0]);
        return EXIT_FAILURE;
    }

    const char* source_file = argv[1];
    const char* dest_file = argv[2];
    const char* regex_pattern = (argc > 3) ? argv[3] : NULL;
    const char* replacement = (argc > 4) ? argv[4] : NULL;

    // Perform file copy with optional regex replacement
    int result = copy_file(source_file, dest_file, regex_pattern, replacement);

    if (result == 0) {
        printf("File copied successfully from %s to %s\n", source_file, dest_file);
        if (regex_pattern != NULL && replacement != NULL) {
            printf("Regex replacement applied: %s -> %s\n", regex_pattern, replacement);
        }
        return EXIT_SUCCESS;
    } else {
        fprintf(stderr, "File copy failed\n");
        return EXIT_FAILURE;
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>

#define MAX_LINE_LENGTH 1024

void copy_file_with_regex(const char *src_file, const char *dest_file, const char *pattern, const char *replacement) {
    FILE *src = fopen(src_file, "r");
    FILE *dest = fopen(dest_file, "w");

    if (src == NULL || dest == NULL) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    regex_t regex;
    int reti;
    char buffer[MAX_LINE_LENGTH];

    // Compile the regular expression
    reti = regcomp(&regex, pattern, REG_EXTENDED);
    if (reti) {
        fprintf(stderr, "Could not compile regex\n");
        exit(EXIT_FAILURE);
    }

    // Read from source file line by line
    while (fgets(buffer, MAX_LINE_LENGTH, src) != NULL) {
        regmatch_t matches[1];
        char *line = buffer;
        char output[MAX_LINE_LENGTH] = {0};
        char *ptr = output;

        // Apply the regex to the line
        while (1) {
            reti = regexec(&regex, line, 1, matches, 0);
            if (reti == 0) {
                // Copy the part before the match
                strncat(ptr, line, matches[0].rm_so);
                ptr += matches[0].rm_so;

                // Append the replacement
                strcat(ptr, replacement);
                ptr += strlen(replacement);

                // Move the line pointer past the match
                line += matches[0].rm_eo;
            } else {
                // No more matches, copy the rest of the line
                strcat(ptr, line);
                break;
            }
        }

        // Write the modified line to the destination file
        fputs(output, dest);
    }

    // Clean up
    regfree(&regex);
    fclose(src);
    fclose(dest);
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <source_file> <destination_file> <regex_pattern> <replacement>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *src_file = argv[1];
    const char *dest_file = argv[2];
    const char *pattern = argv[3];
    const char *replacement = argv[4];

    copy_file_with_regex(src_file, dest_file, pattern, replacement);

    printf("File copied successfully with regex replacement.\n");

    return EXIT_SUCCESS;
}

