    // REG_ICASE for case-insensitive matching (optional, add if needed)
    ret = regcomp(&regex, pattern, REG_EXTENDED | REG_NEWLINE);
    if (ret != 0) {
        print_regex_error(ret, &regex, "compilation");
        fclose(source_file);
        fclose(dest_file);
        return EXIT_FAILURE;
    }

    // 4. Read file line by line, perform regex operation, and write
    printf("Processing file: %s -> %s\n", source_filename, dest_filename);
    if (perform_substitution) {
        printf("Performing substitution: /%s/ -> /%s/\n", pattern, replacement);
    } else {
        printf("Copying lines matching pattern: /%s/\n", pattern);
    }

    regmatch_t pmatch[10]; // To store match offsets (up to 9 captured groups + whole match)

    while (fgets(line_buffer, sizeof(line_buffer), source_file) != NULL) {
        // Remove trailing newline if present, fgets includes it
        size_t len = strlen(line_buffer);
        if (len > 0 && line_buffer[len - 1] == '\n') {
            line_buffer[len - 1] = '\0';
        }

        ret = regexec(&regex, line_buffer, sizeof(pmatch) / sizeof(pmatch[0]), pmatch, 0);

        if (ret == 0) { // Match found
            if (perform_substitution) {
                // Manually build the substituted string
                // Note: regex.h doesn't have a direct 'sub' function.
                // We concatenate parts before, the replacement, and parts after.
                // This simple implementation only replaces the *first* occurrence on a line.
                // For global replacement, you'd need a loop and adjust the search offset.

                if (pmatch[0].rm_so != -1 && pmatch[0].rm_eo != -1) {
                    // Calculate required buffer size for the new line
                    // Part before match + replacement length + part after match + null terminator
                    size_t new_line_len = (pmatch[0].rm_so) +
                                          strlen(replacement) +
                                          (len - pmatch[0].rm_eo) + 1;

                    char *new_line_buffer = (char *)malloc(new_line_len);
                    if (new_line_buffer == NULL) {
                        perror("Memory allocation failed for new line buffer");
                        // Continue to next line or exit, depending on desired error recovery
                        // For now, write original line if allocation fails
                        fprintf(dest_file, "%s\n", line_buffer);
                        continue;
                    }

                    int current_pos = 0;
                    // Copy part before the match
                    strncpy(new_line_buffer, line_buffer, pmatch[0].rm_so);
                    current_pos += pmatch[0].rm_so;

                    // Append the replacement string
                    strcpy(new_line_buffer + current_pos, replacement);
                    current_pos += strlen(replacement);

                    // Append the part after the match
                    strcpy(new_line_buffer + current_pos, line_buffer + pmatch[0].rm_eo);

                    fprintf(dest_file, "%s\n", new_line_buffer);
                    free(new_line_buffer); // Free dynamically allocated memory
                } else { // Should not happen if ret == 0, but as a safeguard
                    fprintf(dest_file, "%s\n", line_buffer);
                }
            } else { // No substitution, just copy if matches
                fprintf(dest_file, "%s\n", line_buffer);
            }
        } else if (ret == REG_NOMATCH) {
            // Line does not match the pattern.
            // If performing substitution, write the original non-matching line.
            // If just copying matching lines, do nothing (skip the line).
            if (perform_substitution) {
                fprintf(dest_file, "%s\n", line_buffer);
            }
            // else, do nothing for lines that don't match
        } else { // Other regex execution errors
            print_regex_error(ret, &regex, "execution");
            // Decide whether to continue or exit on such errors.
            // For robustness, you might want to skip the line or try to write it as is.
            fprintf(stderr, "Skipping line due to regex error: %s\n", line_buffer);
        }
    }

    // 5. Cleanup
    regfree(&regex); // Free regex memory
    fclose(source_file);
    fclose(dest_file);

    printf("File processing complete.\n");

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>

#define MAXBUF 8192

// Replace all occurrences of regex pattern in input, outputting into *result_ptr
// Only supports simple string replacement (no backrefs)
int regex_replace(const char *input, const char *pattern, const char *replacement, char **result_ptr) {
    regex_t regex;
    regmatch_t pmatch[1];
    int err, start = 0, count = 0;
    size_t replacement_len = strlen(replacement);

    // Compile regex (default: no flags, no multi-line)
    err = regcomp(&regex, pattern, REG_EXTENDED);
    if (err) {
        char errbuf[256];
        regerror(err, &regex, errbuf, sizeof(errbuf));
        fprintf(stderr, "Regex compilation failed: %s\n", errbuf);
        return -1;
    }

    // Allocate result (safe maximum: input length * 2)
    size_t result_sz = strlen(input) * 2 + 1;
    char *result = malloc(result_sz);
    if (!result) { regfree(&regex); return -1; }
    result[0] = '\0';

    // Walk through input
    start = 0;
    while (!regexec(&regex, input + start, 1, pmatch, 0)) {
        // Copy everything up to the match
        strncat(result, input + start, pmatch[0].rm_so);
        // Add the replacement
        strcat(result, replacement);
        // Move past the match
        start += pmatch[0].rm_eo;
        count++;

        // Prevent buffer overflow (in a real application, use dynamic buffer management)
        if (strlen(result) > result_sz - MAXBUF) {
            result_sz *= 2;
            result = realloc(result, result_sz);
            if (!result) { regfree(&regex); return -1; }
        }
    }
    // Copy the remainder
    strcat(result, input + start);
    regfree(&regex);
    *result_ptr = result;
    return count;
}

int main(int argc, char *argv[]) {
    if (argc != 3 && argc != 5) {
        printf("Usage: %s <source_file> <dest_file> [PATTERN REPLACEMENT]\n", argv[0]);
        return 1;
    }

    FILE *src = fopen(argv[1], "r");
    if (!src) {
        perror("Cannot open source file");
        return 1;
    }
    FILE *dst = fopen(argv[2], "w");
    if (!dst) {
        perror("Cannot open destination file");
        fclose(src);
        return 1;
    }

    char buf[MAXBUF];
    // No regex: copy line-by-line
    if (argc == 3) {
        while (fgets(buf, sizeof(buf), src)) {
            fputs(buf, dst);
        }
    } else {
        const char *pattern = argv[3];
        const char *replacement = argv[4];
        while (fgets(buf, sizeof(buf), src)) {
            char *newline = strchr(buf, '\n');
            if (newline) *newline = '\0'; // strip newline

            char *out = NULL;
            if (regex_replace(buf, pattern, replacement, &out) >= 0) {
                fputs(out, dst);
                fputc('\n', dst);
                free(out);
            } else {
                // If replacement fails, fallback to original
                fputs(buf, dst);
                fputc('\n', dst);
            }
        }
    }

    fclose(src);
    fclose(dst);
    return 0;
}

