#define BUFFER_SIZE 1024

void usage(const char *progName) {
    fprintf(stderr, "Usage: %s <source file> <dest file> <regex pattern> <replacement>\n", progName);
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        usage(argv[0]);
        return EXIT_FAILURE;
    }

    const char *sourceFile = argv[1];
    const char *destFile = argv[2];
    const char *pattern = argv[3];
    const char *replacement = argv[4];

    FILE *src = fopen(sourceFile, "r");
    if (!src) {
        perror("Failed to open source file");
        return EXIT_FAILURE;
    }

    FILE *dest = fopen(destFile, "w");
    if (!dest) {
        perror("Failed to open destination file");
        fclose(src);
        return EXIT_FAILURE;
    }

    regex_t regex;
    if (regcomp(&regex, pattern, REG_EXTENDED) != 0) {
        fprintf(stderr, "Could not compile regex\n");
        fclose(src);
        fclose(dest);
        return EXIT_FAILURE;
    }

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, src)) {
        regmatch_t pmatch[1];
        int offset = 0;
        int writelength;

        while (regexec(&regex, buffer + offset, 1, pmatch, 0) == 0) {
            fwrite(buffer + offset, 1, pmatch[0].rm_so, dest);
            fwrite(replacement, strlen(replacement), 1, dest);
            offset += pmatch[0].rm_eo;
        }
        writelength = strlen(buffer + offset);

        // Write the remainder of the buffer that doesn't match
        if (writelength > 0) {
            fwrite(buffer + offset, writelength, 1, dest);
        }
    }

    regfree(&regex);
    fclose(src);
    fclose(dest);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>

#define BUFFER_SIZE 1024

void replace_pattern(const char *src, char *dest, const char *pattern, const char *replacement) {
    regex_t regex;
    regmatch_t matches[10];
    size_t start = 0;
    size_t dest_pos = 0;

    // Compile the regular expression
    if (regcomp(&regex, pattern, REG_EXTENDED) != 0) {
        fprintf(stderr, "Could not compile regex\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Execute the regex
        if (regexec(&regex, src + start, 10, matches, 0) == REG_NOMATCH) {
            // No more matches, copy the remainder of the string
            strcpy(dest + dest_pos, src + start);
            break;
        }

        // Copy the part before the match
        size_t match_start = matches[0].rm_so + start;
        size_t match_end = matches[0].rm_eo + start;
        strncat(dest + dest_pos, src + start, match_start - start);
        dest_pos += match_start - start;

        // Copy the replacement
        strcpy(dest + dest_pos, replacement);
        dest_pos += strlen(replacement);

        // Move past the match
        start = match_end;
    }

    regfree(&regex);
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <source_file> <destination_file> <pattern> <replacement>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *source_file = argv[1];
    const char *dest_file = argv[2];
    const char *pattern = argv[3];
    const char *replacement = argv[4];

    // Open the source file for reading
    FILE *src_fp = fopen(source_file, "r");
    if (src_fp == NULL) {
        perror("Error opening source file");
        exit(EXIT_FAILURE);
    }

    // Open the destination file for writing
    FILE *dest_fp = fopen(dest_file, "w");
    if (dest_fp == NULL) {
        perror("Error opening destination file");
        fclose(src_fp);
        exit(EXIT_FAILURE);
    }

    char buffer[BUFFER_SIZE];
    char output_buffer[BUFFER_SIZE * 10]; // To hold replaced lines, increase if needed

    // Read from source file line by line
    while (fgets(buffer, sizeof(buffer), src_fp) != NULL) {
        output_buffer[0] = '\0'; // Reset output buffer
        replace_pattern(buffer, output_buffer, pattern, replacement);
        fputs(output_buffer, dest_fp);
    }

    fclose(src_fp);
    fclose(dest_fp);
    return 0;
}

