#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>

#define BUFSZ 1024

char *regsub(const regex_t *regexp, char *source, char *pattern) {
    int nmatches = 10;
    regmatch_t matches[nmatches];
    int i;
    int source_len = strlen(source);
    int offset = 0;
    char *result = NULL;
    char *temp = NULL;
    char *part = NULL;

    while (regexec(regexp, source + offset, nmatches, matches, 0) == 0) {
        if (result == NULL) {
            result = malloc(BUFSZ);
            temp = result;
        } else {
            temp = realloc(result, BUFSZ + strlen(result));
            result = temp;
            temp = result + strlen(result);
        }

        for (i = 0; i < nmatches; i++) {
            if (matches[i].rm_so == -1) break;
            if (i == 0) {
                if (matches[i].rm_so > offset) {
                    part = malloc(matches[i].rm_so - offset + 1);
                    strncpy(part, source + offset, matches[i].rm_so - offset);
                    part[matches[i].rm_so - offset] = '\0';
                    strcat(temp, part);
                    temp += strlen(part);
                    free(part);
                }
            } else {
                part = malloc(matches[i].rm_eo - matches[i].rm_so + 1);
                strncpy(part, source + offset + matches[i].rm_so, matches[i].rm_eo - matches[i].rm_so);
                part[matches[i].rm_eo - matches[i].rm_so] = '\0';
                strcat(temp, pattern);
                temp += strlen(pattern);
                free(part);
            }
        }
        offset += matches[0].rm_eo;
    }

    if (offset < source_len) {
        part = malloc(source_len - offset + 1);
        strncpy(part, source + offset, source_len - offset);
        part[source_len - offset] = '\0';
        strcat(temp, part);
        free(part);
    }

    return result;
}

int main(int argc, char *argv[]) {
    if (argc < 4 || argc > 5) {
        fprintf(stderr, "Usage: %s <source_file> <destination_file> <regex> [replacement]\n", argv[0]);
        return 1;
    }

    FILE *src, *dest;
    char buffer[BUFSZ];
    char *new_content;
    regex_t regex;
    int ret;

    src = fopen(argv[1], "r");
    if (src == NULL) {
        perror("Error opening source file");
        return 1;
    }

    dest = fopen(argv[2], "w");
    if (dest == NULL) {
        perror("Error opening destination file");
        fclose(src);
        return 1;
    }

    ret = regcomp(&regex, argv[3], REG_EXTENDED);
    if (ret) {
        fprintf(stderr, "Could not compile regex\n");
        fclose(src);
        fclose(dest);
        return 1;
    }

    char *replacement = (argc == 5) ? argv[4] : "";

    while (fgets(buffer, BUFSZ, src) != NULL) {
        new_content = regsub(&regex, buffer, replacement);
        if (new_content != NULL) {
            fprintf(dest, "%s", new_content);
            free(new_content);
        }
    }

    regfree(&regex);
    fclose(src);
    fclose(dest);

    return 0;
}

