    // 12-hour format with AM/PM
    strftime(time_string, sizeof(time_string), "%I:%M:%S %p", local_time);
    printf("Current time (HH:MM:SS AM/PM): %s\n", time_string);

    // Just the time (default locale format)
    strftime(time_string, sizeof(time_string), "%X", local_time);
    printf("Current time (locale default): %s\n", time_string);

    // Date and time with weekday and month names
    strftime(time_string, sizeof(time_string), "%A, %B %d, %Y %I:%M:%S %p", local_time);
