void generatePassword(char* password) {
    // Ensure at least one character from each type
    password[0] = getRandomChar(0);  // Lowercase
    password[1] = getRandomChar(1);  // Uppercase
    password[2] = getRandomChar(2);  // Number
    password[3] = getRandomChar(3);  // Special character

    // Fill the rest with random characters
    for (int i = 4; i < 9; i++) {
        password[i] = getRandomChar(rand() % 4);
    }

    // Null-terminate the string
    password[9] = '\0';
}

// Function to shuffle the password
void shufflePassword(char* password) {
    for (int i = 9 - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        char temp = password[i];
        password[i] = password[j];
        password[j] = temp;
    }
}

