pthread_mutex_t database_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a random phone number
void generate_phone_number(char* phone_number) {
    // Format: XXX-XXX-XXXX
    sprintf(phone_number, "%03d-%03d-%04d", 
        rand() % 1000,    // Area code
        rand() % 1000,    // Exchange code 
        rand() % 10000    // Subscriber number
    );
}

// Function to check if phone number already exists in database
int is_phone_number_exists(const char* phone_number) {
    for (int i = 0; i < MAX_PHONE_NUMBERS; i++) {
        if (phone_database[i].used && 
            strcmp(phone_database[i].number, phone_number) == 0) {
            return 1;  // Number exists
        }
    }
    return 0;  // Number does not exist
}

// Function to add phone number to database
int add_phone_number(const char* phone_number) {
    for (int i = 0; i < MAX_PHONE_NUMBERS; i++) {
        if (!phone_database[i].used) {
            strcpy(phone_database[i].number, phone_number);
            phone_database[i].used = 1;
            return 1;  // Successfully added
        }
    }
    return 0;  // Database is full
}

// Thread worker function
void* generate_unique_phone_numbers(void* arg) {
    int thread_id = *(int*)arg;
    int local_count = 0;

    for (int i = 0; i < 20; i++) {  // Each thread generates 20 unique numbers
        char phone_number[12];

        generate_phone_number(phone_number);

        // Thread-safe check and add
        pthread_mutex_lock(&database_mutex);

        if (!is_phone_number_exists(phone_number)) {
            if (add_phone_number(phone_number)) {
                printf("Thread %d: Generated unique number: %s\n", thread_id, phone_number);
                local_count++;
            }
        }

        pthread_mutex_unlock(&database_mutex);
    }

    printf("Thread %d: Generated %d unique phone numbers\n", thread_id, local_count);
    return NULL;
}

int main() {
    // Seed random number generator
    srand(time(NULL));

    // Initialize database
    memset(phone_database, 0, sizeof(phone_database));

    // Thread variables
    pthread_t threads[NUM_THREADS];
    int thread_ids[NUM_THREADS];

    // Create threads
    for (int i = 0; i < NUM_THREADS; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, generate_unique_phone_numbers, &thread_ids[i]);
    }

    // Wait for threads to complete
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Print final database contents
    printf("\nFinal Database Contents:\n");
    int unique_count = 0;
    for (int i = 0; i < MAX_PHONE_NUMBERS; i++) {
        if (phone_database[i].used) {
            printf("%s\n", phone_database[i].number);
            unique_count++;
        }
    }
    printf("\nTotal Unique Phone Numbers: %d\n", unique_count);

    // Clean up mutex
    pthread_mutex_destroy(&database_mutex);

    return 0;
}

