#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

// For a dynamic array of strings (simulating a set/hash table)
// In a real-world scenario, for performance with many entries,
// you'd use a more sophisticated data structure like a hash table
// or a balanced binary search tree, or a database connection.
// For simplicity in C and to demonstrate mutexes, we'll use
// a dynamically growing array and sort/bsearch for checks.
// Using a linked list of strings (less efficient for search) or
// an actual hash table implementation would be more robust.

// --- OPTION 1: Using a simple sorted dynamic array (less efficient for large data) ---
// For a very large number of phone numbers, searching this array would be slow (O(N)).
// A hash table or a true balanced binary search tree would be much better.

#define INITIAL_DB_CAPACITY 1000
char **phone_database = NULL;
size_t db_size = 0;
size_t db_capacity = 0;

// Mutex to protect access to the phone_database
pthread_mutex_t db_mutex;

// Function to generate a random 10-digit phone number as a string
void generate_random_phone_number(char *buffer, size_t buffer_len) {
    if (buffer_len < 11) { // 10 digits + null terminator
        fprintf(stderr, "Buffer too small for phone number.\n");
        return;
    }
    // Simple 10-digit number. Format: XXX-XXX-XXXX
    // We'll generate it as a plain 10-digit string first for easier comparison
    // and then format it optionally.
    // For simplicity, we'll just generate digits.
    // First digit is usually not '0' in most phone numbers
    buffer[0] = (char)('1' + (rand() % 9)); // 1-9
    for (int i = 1; i < 10; ++i) {
        buffer[i] = (char)('0' + (rand() % 10)); // 0-9
    }
    buffer[10] = '\0'; // Null-terminate the string
}

// Comparison function for qsort and bsearch
int compare_phone_numbers(const void *a, const void *b) {
    const char *str_a = *(const char **)a;
    const char *str_b = *(const char **)b;
    return strcmp(str_a, str_b);
}

// Adds a phone number to the database if it doesn't exist.
// Returns true if added, false if already exists.
bool add_phone_number_to_db(const char *phone_number) {
    bool added = false; // Assume not added initially

    pthread_mutex_lock(&db_mutex); // Acquire lock

    // Check if phone number already exists using binary search
    if (bsearch(&phone_number, phone_database, db_size, sizeof(char *), compare_phone_numbers) != NULL) {
        // Phone number already in database
        added = false;
    } else {
        // Phone number not found, add it
        if (db_size >= db_capacity) {
            // Reallocate if capacity is full
            db_capacity += INITIAL_DB_CAPACITY; // Grow by fixed amount
            char **new_phone_database = realloc(phone_database, db_capacity * sizeof(char *));
            if (new_phone_database == NULL) {
                perror("realloc failed");
                // Critical error, should handle gracefully or exit
                pthread_mutex_unlock(&db_mutex);
                return false;
            }
            phone_database = new_phone_database;
        }

        // Allocate memory for the new phone number string
        char *new_num = strdup(phone_number);
        if (new_num == NULL) {
            perror("strdup failed");
            pthread_mutex_unlock(&db_mutex);
            return false;
        }

        // Add to the end and then re-sort the array
        phone_database[db_size] = new_num;
        db_size++;

        // Keep the database sorted for binary search
        qsort(phone_database, db_size, sizeof(char *), compare_phone_numbers);
        added = true;
    }

    pthread_mutex_unlock(&db_mutex); // Release lock
    return added;
}

// Function for each thread
void *generator_thread(void *arg) {
    long thread_id = (long)arg;
    char phone_num_buffer[11]; // 10 digits + null terminator
    int attempts = 0;
    int successfully_added = 0;
    int num_to_generate = 1000; // Each thread tries to generate this many unique numbers

    printf("Thread %ld started.\n", thread_id);

    while (successfully_added < num_to_generate) {
        generate_random_phone_number(phone_num_buffer, sizeof(phone_num_buffer));
        attempts++;

        if (add_phone_number_to_db(phone_num_buffer)) {
            successfully_added++;
            // Optional: Print a dot for progress or the number itself for debugging
            // printf("Thread %ld added %s\n", thread_id, phone_num_buffer);
        } else {
            // printf("Thread %ld tried %s (exists)\n", thread_id, phone_num_buffer);
        }

        // Yield for fairness or to prevent excessive CPU usage if the database becomes full
        // sched_yield(); // Requires <sched.h>
    }

    printf("Thread %ld finished. Attempts: %d, Added: %d\n", thread_id, attempts, successfully_added);
    return NULL;
}

int main(int argc, char *argv[]) {
    srand(time(NULL)); // Seed the random number generator

    int num_threads = 4; // Default number of threads
    if (argc > 1) {
        num_threads = atoi(argv[1]);
        if (num_threads <= 0) {
            fprintf(stderr, "Invalid number of threads. Using default of %d.\n", num_threads);
            num_threads = 4;
        }
    }

    pthread_t threads[num_threads];

    // Initialize the mutex
    if (pthread_mutex_init(&db_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex init failed\n");
        return 1;
    }

    // Initialize phone database
    db_capacity = INITIAL_DB_CAPACITY;
    phone_database = (char **)malloc(db_capacity * sizeof(char *));
    if (phone_database == NULL) {
        perror("Initial phone_database malloc failed");
        pthread_mutex_destroy(&db_mutex);
        return 1;
    }
    db_size = 0;

    printf("Starting %d threads...\n", num_threads);

    // Create threads
    for (long i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, generator_thread, (void *)i) != 0) {
            fprintf(stderr, "Error creating thread %ld\n", i);
            return 1;
        }
    }

    // Wait for threads to finish
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("\nAll threads finished.\n");
    printf("Total unique phone numbers generated: %zu\n", db_size);

    // Optional: Print all unique phone numbers
    // printf("\nGenerated Phone Numbers:\n");
    // for (size_t i = 0; i < db_size; ++i) {
    //     printf("%s\n", phone_database[i]);
    // }

    // Free the allocated memory
    for (size_t i = 0; i < db_size; ++i) {
        free(phone_database[i]);
    }
    free(phone_database);

    // Destroy the mutex
    pthread_mutex_destroy(&db_mutex);

    return 0;
}

// random_phone_threads.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

#define PHONE_FORMAT "555-%07d"
#define PHONE_NUMBER_LENGTH 11  // e.g., "555-1234567"
#define HASH_TABLE_SIZE 100003  // Prime number for better distribution

typedef struct Node {
    char phone[PHONE_NUMBER_LENGTH + 1];
    struct Node* next;
} Node;

typedef struct {
    Node* table[HASH_TABLE_SIZE];
    pthread_mutex_t lock;
} HashSet;

// Hash function (djb2 by Dan Bernstein)
unsigned long hash(const char* str) {
    unsigned long hash = 5381;
    while (*str)
        hash = ((hash << 5) + hash) + (unsigned char)*str++;
    return hash % HASH_TABLE_SIZE;
}

// Initialize hash set
void hashset_init(HashSet* set) {
    memset(set->table, 0, sizeof(set->table));
    pthread_mutex_init(&set->lock, NULL);
}

// Add to hash set, return 1 if added, 0 if already present
int hashset_add(HashSet* set, const char* phone) {
    unsigned long idx = hash(phone);

    pthread_mutex_lock(&set->lock);

    Node* curr = set->table[idx];
    while (curr) {
        if (strcmp(curr->phone, phone) == 0) {
            pthread_mutex_unlock(&set->lock);
            return 0; // Found, not added
        }
        curr = curr->next;
    }
    // Not found, add new node
    Node* node = malloc(sizeof(Node));
    strncpy(node->phone, phone, PHONE_NUMBER_LENGTH);
    node->phone[PHONE_NUMBER_LENGTH] = '\0';
    node->next = set->table[idx];
    set->table[idx] = node;

    pthread_mutex_unlock(&set->lock);
    return 1; // Added
}

// Destroy hash set and free memory
void hashset_destroy(HashSet* set) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        Node* curr = set->table[i];
        while (curr) {
            Node* tmp = curr;
            curr = curr->next;
            free(tmp);
        }
    }
    pthread_mutex_destroy(&set->lock);
}

// Thread function arguments
typedef struct {
    HashSet* set;
    int count;
    FILE* file;
    pthread_mutex_t* file_lock;
    unsigned int seed;
    int thread_id;
} ThreadArg;

// Generate a random phone number in "555-XXXXXXX" format
void generate_phone(char* buffer, unsigned int* seed) {
    int number = rand_r(seed) % 10000000; // 0 to 9999999
    sprintf(buffer, PHONE_FORMAT, number);
}

void* thread_func(void* arg) {
    ThreadArg* t_arg = (ThreadArg*)arg;
    char phone[PHONE_NUMBER_LENGTH + 1];
    int added_numbers = 0;

    while (added_numbers < t_arg->count) {
        generate_phone(phone, &t_arg->seed);
        if (hashset_add(t_arg->set, phone)) {
            // New number, write to file
            pthread_mutex_lock(t_arg->file_lock);
            fprintf(t_arg->file, "%s\n", phone);
            fflush(t_arg->file); // ensure it's written in case of crash
            pthread_mutex_unlock(t_arg->file_lock);
            added_numbers++;
        }
    }
    printf("Thread %d completed! Generated %d unique numbers.\n", t_arg->thread_id, added_numbers);
    return NULL;
}

int main(int argc, char* argv[]) {
    int n_threads = 4;
    int n_numbers_per_thread = 10;

    if (argc == 3) {
        n_threads = atoi(argv[1]);
        n_numbers_per_thread = atoi(argv[2]);
        if (n_threads < 1 || n_numbers_per_thread < 1) {
            fprintf(stderr, "Usage: %s [num_threads] [per_thread_count]\n", argv[0]);
            return 1;
        }
    } else {
        printf("Usage: %s [num_threads] [per_thread_count]\nUsing default: %d threads, %d numbers per thread.\n",
               argv[0], n_threads, n_numbers_per_thread);
    }

    HashSet set;
    hashset_init(&set);

    FILE* file = fopen("numbers.txt", "a");
    if (!file) {
        perror("Error opening numbers.txt for writing");
        hashset_destroy(&set);
        return 1;
    }

    pthread_mutex_t file_lock;
    pthread_mutex_init(&file_lock, NULL);

    pthread_t threads[n_threads];
    ThreadArg args[n_threads];

    srand(time(NULL));
    // Spawn threads
    for (int i = 0; i < n_threads; ++i) {
        args[i].set = &set;
        args[i].count = n_numbers_per_thread;
        args[i].file = file;
        args[i].file_lock = &file_lock;
        args[i].seed = rand();
        args[i].thread_id = i;
        int rc = pthread_create(&threads[i], NULL, thread_func, &args[i]);
        if (rc != 0) {
            fprintf(stderr, "Error creating thread %d\n", i);
        }
    }

    // Join
    for (int i = 0; i < n_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    hashset_destroy(&set);
    fclose(file);
    pthread_mutex_destroy(&file_lock);

    printf("Done. Check numbers.txt for generated phone numbers.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the structure to store phone numbers in a linked list
typedef struct PhoneNumberNode {
    char phoneNumber[15]; // Format: 123-456-7890
    struct PhoneNumberNode *next;
} PhoneNumberNode;

PhoneNumberNode *head = NULL; // Head of the linked list
pthread_mutex_t lock;

// Function to generate a random phone number
void generateRandomPhoneNumber(char *phone) {
    snprintf(phone, 15, "%03d-%03d-%04d",
             rand() % 1000,
             rand() % 1000,
             rand() % 10000);
}

// Function to check if a phone number exists in the linked list
int phoneNumberExists(char *phone) {
    pthread_mutex_lock(&lock);

    PhoneNumberNode *current = head;
    while (current != NULL) {
        if (strcmp(current->phoneNumber, phone) == 0) {
            pthread_mutex_unlock(&lock);
            return 1;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
    return 0;
}

// Function to add a phone number to the linked list
void addPhoneNumberToList(char *phone) {
    pthread_mutex_lock(&lock);

    PhoneNumberNode *newNode = (PhoneNumberNode *)malloc(sizeof(PhoneNumberNode));
    strcpy(newNode->phoneNumber, phone);
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

// Function to generate and handle a phone number in a thread
void *handlePhoneNumber(void *arg) {
    char phone[15];
    generateRandomPhoneNumber(phone);

    if (!phoneNumberExists(phone)) {
        addPhoneNumberToList(phone);
        printf("New phone number generated and stored: %s\n", phone);
    } else {
        printf("Phone number already exists: %s\n", phone);
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_mutex_init(&lock, NULL);

    const int numThreads = 10;
    pthread_t threads[numThreads];

    // Create multiple threads
    for (int i = 0; i < numThreads; i++) {
        if (pthread_create(&threads[i], NULL, handlePhoneNumber, NULL)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < numThreads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up mutex
    pthread_mutex_destroy(&lock);

    // Free memory in the linked list
    PhoneNumberNode *current = head;
    while (current != NULL) {
        PhoneNumberNode *temp = current;
        current = current->next;
        free(temp);
    }

    return 0;
}

