#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>

// Structure to represent a phone number
typedef struct {
    char number[15];
} PhoneNumber;

// Structure to represent the database
typedef struct {
    PhoneNumber* numbers;
    int size;
    int capacity;
    pthread_mutex_t lock;
} Database;

// Function to initialize the database
Database* init_database(int capacity) {
    Database* db = (Database*) malloc(sizeof(Database));
    db->numbers = (PhoneNumber*) malloc(capacity * sizeof(PhoneNumber));
    db->size = 0;
    db->capacity = capacity;
    pthread_mutex_init(&db->lock, NULL);
    return db;
}

// Function to generate a random phone number
void generate_phone_number(PhoneNumber* number) {
    char prefix[] = "+1-";
    sprintf(number->number, "%s%d%d%d-%d%d%d-%d%d%d%d", prefix, rand() % 9 + 1, rand() % 10, rand() % 10, rand() % 10, rand() % 10, rand() % 10, rand() % 10, rand() % 10, rand() % 10, rand() % 10);
}

// Function to check if a phone number exists in the database
bool exists_in_database(Database* db, PhoneNumber* number) {
    pthread_mutex_lock(&db->lock);
    for (int i = 0; i < db->size; i++) {
        if (strcmp(db->numbers[i].number, number->number) == 0) {
            pthread_mutex_unlock(&db->lock);
            return true;
        }
    }
    pthread_mutex_unlock(&db->lock);
    return false;
}

// Function to add a phone number to the database
void add_to_database(Database* db, PhoneNumber* number) {
    pthread_mutex_lock(&db->lock);
    if (db->size < db->capacity) {
        db->numbers[db->size] = *number;
        db->size++;
    }
    pthread_mutex_unlock(&db->lock);
}

// Thread function to generate and save phone numbers
void* generate_and_save(void* arg) {
    Database* db = (Database*) arg;
    PhoneNumber number;
    srand(time(NULL)); // seed for rand()
    while (1) {
        generate_phone_number(&number);
        if (!exists_in_database(db, &number)) {
            add_to_database(db, &number);
            printf("Generated and saved phone number: %s\n", number.number);
        }
    }
