#define PHONE_NUMBER_LENGTH 11  // Example format: 12345678901
#define DATABASE_FILE "phone_numbers.txt"
#define MAX_THREADS 4
#define MAX_TRIES 100000  // Maximum number of tries to generate a unique phone number

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a random phone number
char* generate_phone_number() {
    char* phone_number = (char*)malloc(PHONE_NUMBER_LENGTH + 1);
    for (int i = 0; i < PHONE_NUMBER_LENGTH; i++) {
        phone_number[i] = '1' + (rand() % 9);  // Generate digits 1-9
    }
    phone_number[PHONE_NUMBER_LENGTH] = '\0';
    return phone_number;
}

// Function to check if a phone number is already in the database
bool is_phone_number_in_database(const char* phone_number) {
    FILE* file = fopen(DATABASE_FILE, "r");
    if (file == NULL) {
        return false;  // File does not exist, so the number is not in the database
    }

    char buffer[PHONE_NUMBER_LENGTH + 1];
    while (fgets(buffer, PHONE_NUMBER_LENGTH + 1, file)) {
        if (strcmp(buffer, phone_number) == 0) {
            fclose(file);
            return true;
        }
    }

    fclose(file);
    return false;
}

// Function to add a phone number to the database
void add_phone_number_to_database(const char* phone_number) {
    FILE* file = fopen(DATABASE_FILE, "a");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    fprintf(file, "%s\n", phone_number);
    fclose(file);
}

// Thread function to generate and save a unique phone number
void* generate_unique_phone_number(void* arg) {
    int thread_id = *(int*)arg;
    int tries = 0;
    char* phone_number;

    while (tries < MAX_TRIES) {
        phone_number = generate_phone_number();
        pthread_mutex_lock(&mutex);
        if (!is_phone_number_in_database(phone_number)) {
            add_phone_number_to_database(phone_number);
            printf("Thread %d: Generated unique phone number: %s\n", thread_id, phone_number);
            pthread_mutex_unlock(&mutex);
            free(phone_number);
            return NULL;
        }
        pthread_mutex_unlock(&mutex);
        free(phone_number);
        tries++;
    }

    printf("Thread %d: Failed to generate a unique phone number after %d tries.\n", thread_id, MAX_TRIES);
    return NULL;
}

int main() {
    srand(time(NULL));

    pthread_t threads[MAX_THREADS];
    int thread_ids[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; i++) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, generate_unique_phone_number, &thread_ids[i]) != 0) {
            perror("Error creating thread");
            return 1;
        }
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Error joining thread");
            return 1;
        }
    }

    pthread_mutex_destroy(&mutex);
    return 0;
}

