#include <stdio.h>
#include <complex.h>
#include <math.h>

#define WIDTH 80
#define HEIGHT 40
#define MAX_ITERATIONS 100

// Function to map the Mandelbrot set to ASCII characters
char get_mandelbrot_char(int iterations) {
    char chars[] = " .:-=+*#%@";
    int num_chars = sizeof(chars) - 1;

    if (iterations == MAX_ITERATIONS) 
        return '@';  // Fully inside the set

    // Map iterations to character based on depth
    return chars[(iterations * num_chars) / MAX_ITERATIONS];
}

void generate_mandelbrot() {
    // Define the viewing window for the Mandelbrot set
    double x_min = -2.0;
    double x_max = 1.0;
    double y_min = -1.5;
    double y_max = 1.5;

    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            // Map pixel coordinates to complex plane
            double real = x_min + (x_max - x_min) * x / WIDTH;
            double imag = y_min + (y_max - y_min) * y / HEIGHT;

            // Starting point for iteration
            double complex c = real + imag * I;
            double complex z = 0;

            // Iterate to check if point is in Mandelbrot set
            int iterations = 0;
            while (iterations < MAX_ITERATIONS) {
                z = z * z + c;

                // Check if point escapes
                if (cabs(z) > 2.0) {
                    break;
                }

                iterations++;
            }

            // Print corresponding character
            printf("%c", get_mandelbrot_char(iterations));
        }
        printf("\n");
    }
}

int main() {
    printf("Mandelbrot Set (ASCII Art)\n");
    printf("Resolution: %d x %d\n", WIDTH, HEIGHT);
    printf("Max Iterations: %d\n\n", MAX_ITERATIONS);

    generate_mandelbrot();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <complex.h>

#define WIDTH 80
#define HEIGHT 40
#define X_MIN -2.0
#define X_MAX 1.0
#define Y_MIN -1.0
#define Y_MAX 1.0

int mandelbrot(double complex c, int max_iter) {
    double complex z = 0;
    int n = 0;

    while (cabs(z) <= 2.0 && n < max_iter) {
        z = z * z + c;
        n++;
    }

    return n;
}

void generate_mandelbrot(int max_iter) {
    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            // Map pixel coordinates to complex plane coordinates
            double real = X_MIN + (X_MAX - X_MIN) * x / (WIDTH - 1);
            double imag = Y_MIN + (Y_MAX - Y_MIN) * y / (HEIGHT - 1);
            double complex c = real + imag * I;

            int iter = mandelbrot(c, max_iter);

            // Choose ASCII character based on iteration count
            char ch;
            if (iter == max_iter) {
                ch = '#';  // Inside the Mandelbrot set
            } else if (iter > max_iter * 0.9) {
                ch = '@';
            } else if (iter > max_iter * 0.7) {
                ch = '%';
            } else if (iter > max_iter * 0.5) {
                ch = '*';
            } else if (iter > max_iter * 0.3) {
                ch = '+';
            } else if (iter > max_iter * 0.1) {
                ch = '-';
            } else {
                ch = ' ';  // Far outside the set
            }

            printf("%c", ch);
        }
        printf("\n");
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <iterations>\n", argv[0]);
        return 1;
    }

    int max_iter = atoi(argv[1]);
    if (max_iter <= 0) {
        printf("Iterations must be a positive integer\n");
        return 1;
    }

    generate_mandelbrot(max_iter);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h> // For usleep on Linux/macOS, or <windows.h> for Sleep on Windows

// Structure to hold complex numbers
typedef struct {
    double real;
    double imag;
} Complex;

// Function to calculate Mandelbrot iterations for a given point
int mandelbrot_iterations(Complex c, int max_iterations) {
    Complex z = {0.0, 0.0};
    int iterations = 0;

    while (z.real * z.real + z.imag * z.imag < 4.0 && iterations < max_iterations) {
        double temp_real = z.real * z.real - z.imag * z.imag + c.real;
        z.imag = 2 * z.real * z.imag + c.imag;
        z.real = temp_real;
        iterations++;
    }
    return iterations;
}

// Function to map iteration count to an ASCII character for color/density
char get_ascii_char(int iterations, int max_iterations) {
    if (iterations == max_iterations) {
        return ' '; // Inside the set, usually black
    } else {
        // Map 0 to max_iterations-1 to a range of ASCII characters
        // You can customize this character set for different "color" effects
        const char *density = " .:-=+*#%@"; // From least dense to most dense
        int num_chars = strlen(density);
        int index = (iterations * num_chars) / max_iterations;
        if (index >= num_chars) { // Should not happen with integer division, but for safety
            index = num_chars - 1;
        }
        return density[index];
    }
}

int main(int argc, char *argv[]) {
    int width = 80;        // Default width of the ASCII art
    int height = 50;       // Default height
    int max_iterations = 100; // Default maximum iterations
    double x_min = -2.0;   // Default Mandelbrot x-range
    double x_max = 1.0;
    double y_min = -1.5;   // Default Mandelbrot y-range
    double y_max = 1.5;

    // Parse command line arguments
    // Example usage: ./mandelbrot_ascii -x -0.5 -y 0.5 -w 100 -h 40 -i 200
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-w") == 0 && i + 1 < argc) {
            width = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-h") == 0 && i + 1 < argc) {
