const char charset[] = " .:-=+*#%@"; // Characters from least to most "intense"
#define CHARSET_LEN (sizeof(charset)-1)

int main(int argc, char *argv[]) {
    int max_iter = 100; // Default

    if (argc > 1) {
        max_iter = atoi(argv[1]);
        if (max_iter < 1) max_iter = 1;
    }

    // Area (change if you want to zoom/pan)
    double r_start = -2.0, r_end = 1.0;
    double i_start = -1.0, i_end = 1.0;

    for (int y = 0; y < HEIGHT; y++) {
        double ci = i_start + (i_end - i_start) * y / (HEIGHT - 1);
        for (int x = 0; x < WIDTH; x++) {
            double cr = r_start + (r_end - r_start) * x / (WIDTH - 1);
            double zr = 0.0, zi = 0.0;
            int iter = 0;

            while (zr*zr + zi*zi <= 4.0 && iter < max_iter) {
                double tmp = zr*zr - zi*zi + cr;
                zi = 2.0*zr*zi + ci;
                zr = tmp;
                iter++;
            }

            int idx;
            if (iter >= max_iter)
                idx = CHARSET_LEN-1;
            else
                idx = iter * CHARSET_LEN / max_iter;
            if (idx >= CHARSET_LEN) idx = CHARSET_LEN-1;

            putchar(charset[idx]);
        }
        putchar('\n');
    }

    return 0;
}

