typedef struct {
    double real;
    double imaginary;
} Complex;

// Function to check if a point belongs to the Mandelbrot set
int is_mandelbrot(Complex c, int iterations) {
    Complex z = {0, 0};
    for (int i = 0; i < iterations; i++) {
        double temp_real = z.real * z.real - z.imaginary * z.imaginary + c.real;
        z.imaginary = 2 * z.real * z.imaginary + c.imaginary;
        z.real = temp_real;
        if (z.real * z.real + z.imaginary * z.imaginary > 4) {
            return 0;
        }
    }
    return 1;
}

