#define MAX_LINE_LENGTH 1000

// Function to convert a camel case word to snake case
void camel_to_snake(char* word, char* result) {
    int j = 0;
    int first_char = 1;

    for (int i = 0; word[i] != '\0'; i++) {
        // If it's an uppercase letter (except the first character)
        if (!first_char && isupper(word[i])) {
            result[j++] = '_';
            result[j++] = tolower(word[i]);
        }
        // If it's a lowercase letter or the first character
        else {
            result[j++] = tolower(word[i]);
        }

        first_char = 0;
    }

    result[j] = '\0';
}

// Function to check if a word is in camel case
int is_camel_case(const char* word) {
    // Must have at least 2 characters
    if (strlen(word) < 2) return 0;

    // First word should start with lowercase
    if (!islower(word[0])) return 0;

    // Check if there's at least one uppercase letter after the first character
    for (int i = 1; word[i] != '\0'; i++) {
        if (isupper(word[i])) return 1;
    }

    return 0;
}

// Function to process a single line
void process_line(char* line) {
    char processed_line[MAX_LINE_LENGTH] = {0};
    char* token;
    char* rest = line;
    int pos = 0;

    while ((token = strtok_r(rest, " \t\n", &rest))) {
        char snake_word[MAX_LINE_LENGTH] = {0};

        // If the word is in camel case, convert it
        if (is_camel_case(token)) {
            camel_to_snake(token, snake_word);
        }
        else {
            // If not camel case, keep the original word
            strcpy(snake_word, token);
        }

        // Add the processed word to the line
        if (pos > 0) {
            processed_line[pos++] = ' ';
        }
        strcpy(processed_line + pos, snake_word);
        pos += strlen(snake_word);
    }

    // Copy processed line back to original line
    strcpy(line, processed_line);
}

int main(int argc, char* argv[]) {
    // Check if filename is provided
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    // Open input file
    FILE* input_file = fopen(argv[1], "r");
