// Function to convert a single camelCase word to snake_case
// Modifies the buffer in-place
void camelToSnake(char *word) {
    if (word == NULL || *word == '\0') {
        return;
    }

    int len = strlen(word);
    // Rough estimate for max length after conversion: 2x original length + 1 (for null terminator)
    // Each uppercase could become '_lowercase', so approx. 2 chars for each, plus the original length of lowercase chars.
    char *new_word = (char *)malloc(len * 2 + 1);
    if (new_word == NULL) {
        perror("Failed to allocate memory for snake_case word");
        exit(EXIT_FAILURE);
    }
    int new_idx = 0;

    for (int i = 0; i < len; ++i) {
        if (isupper(word[i])) {
            if (i > 0 && new_idx > 0 && new_word[new_idx - 1] != '_') { // Add '_' before uppercase if not already at start or after a '_'
                new_word[new_idx++] = '_';
            }
            new_word[new_idx++] = tolower(word[i]);
        } else {
            new_word[new_idx++] = word[i];
        }
    }
    new_word[new_idx] = '\0';

    // Copy the converted word back to the original buffer
    // Ensure the original buffer has enough space, or handle truncation/reallocation
    // For simplicity, we assume original buffer `word` is large enough, or just print `new_word`.
    // In this context, we will copy it back to the line buffer later.
    strcpy(word, new_word); // This assumes 'word' can hold the new_word.
                            // If `word` was an arbitrary pointer to a smaller part of a line,
                            // this would be problematic. For our purpose, we'll process tokens.
    free(new_word);
}

// Function to process a line for camelCase words and convert them
void processLine(char *line) {
    char *token;
    char *rest = line;
    char buffer[2048]; // A temporary buffer to build the new line
    buffer[0] = '\0'; // Initialize buffer

    // Delimiters for words. Punctuation, spaces, etc.
    // We want to preserve these delimiters.
    char delimiters[] = " \t\n\r!@#$%^&*()_+-=[]{}|;':\",<.>/?`~";

    while ((token = strtok_r(rest, delimiters, &rest))) {
        char *start_of_token_in_line = strstr(line, token);
        if (start_of_token_in_line == NULL) {
            // Should not happen if strtok_r works correctly, but good for safety
            fprintf(stderr, "Error: Could not find token in line.\n");
            continue;
        }

        // Calculate the part of the string before the current token
        int pre_token_len = start_of_token_in_line - (line + strlen(buffer));

        // Append the non-delimiter characters (the token)
        // Check if the token potentially contains camelCase
        // (A simple check: if it has an uppercase letter not at the start, it *might* be camelCase)
        int has_uppercase_in_middle = 0;
        for (int i = 1; token[i] != '\0'; ++i) {
            if (isupper(token[i])) {
                has_uppercase_in_middle = 1;
                break;
            }
        }

        if (has_uppercase_in_middle) {
             // Create a temporary copy of the token to safely modify
            char temp_token[strlen(token) + 1];
            strcpy(temp_token, token);
            camelToSnake(temp_token);
            strcat(buffer, temp_token);
        } else {
            strcat(buffer, token);
        }

        // Append the delimiter characters after the token
        // This is tricky with strtok_r as it skips delimiters.
        // We need to re-scan the original line to find these.

        // Find the end of the current token in the original line
        char *end_of_token_in_line = start_of_token_in_line + strlen(token);

        // Find the beginning of the next token in the original line's 'rest'
        char *next_token_start_in_line = rest; // strtok_r updates `rest` to point here

        // Copy the delimiters that were between the current token and the next token
        // or up to the end of the line if no more tokens.
        int delimiter_len = 0;
        if (next_token_start_in_line != NULL) {
            delimiter_len = next_token_start_in_line - end_of_token_in_line;
        } else {
            delimiter_len = strlen(line) - (end_of_token_in_line - line);
        }

        if (delimiter_len > 0) {
            strncat(buffer, end_of_token_in_line, delimiter_len);
        }
    }
    strcpy(line, buffer); // Copy the modified line back
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
