// Function to check if a word is camel case
int is_camel_case(const char *word) {
    int has_upper = 0;
    int has_lower = 0;
    int has_underscore = 0;
    int len = strlen(word);

    if(len < 2) return 0; // Word too short
    if(!isalpha(word[0]) || !islower(word[0])) return 0; // Should start with lowercase letter

    for(int i = 0; i < len; i++) {
        if(word[i] == '_') has_underscore = 1;
        if(isupper(word[i]) && i > 0) has_upper = 1;
        if(islower(word[i])) has_lower = 1;
    }
    return has_upper && !has_underscore;
}

// Converts a camel case word to snake case
void camel_to_snake(const char *camel, char *snake) {
    int i = 0, j = 0;
    while(camel[i]) {
        if(isupper(camel[i])) {
            snake[j++] = '_';
            snake[j++] = tolower(camel[i]);
        } else {
            snake[j++] = camel[i];
        }
        i++;
    }
    snake[j] = '\0';
}

// Processes a buffer and replaces camel case words with snake case
char *process_buffer(const char *buffer) {
    // Allocate output buffer (twice the input size for safety)
    size_t len = strlen(buffer);
    size_t out_cap = len * 2 + 1;
    char *out = malloc(out_cap);
    if(!out) { fprintf(stderr, "Memory allocation failed\n"); exit(1); }

    size_t i = 0, j = 0;
    while(buffer[i]) {
        if(isalpha(buffer[i])) {
            // Start of a word
            char word[256] = {0};
            int wi = 0;
            int start = i;
            while(isalnum(buffer[i]) || buffer[i] == '_') {
                if(wi < 255) word[wi++] = buffer[i];
                i++;
            }
            word[wi] = '\0';

            if(is_camel_case(word)) {
                // Convert to snake case
                char snake[512];
                camel_to_snake(word, snake);
                size_t snakelen = strlen(snake);
                if(j + snakelen >= out_cap) { // Resize if necessary
                    out_cap *= 2;
                    out = realloc(out, out_cap);
                    if(!out) { fprintf(stderr, "Memory allocation failed\n"); exit(1); }
                }
                strcpy(out + j, snake);
                j += snakelen;
            } else {
                // Copy word as is
                if(j + wi >= out_cap) {
                    out_cap *= 2;
                    out = realloc(out, out_cap);
                    if(!out) { fprintf(stderr, "Memory allocation failed\n"); exit(1); }
                }
                strncpy(out + j, word, wi);
                j += wi;
            }
        } else {
            // Non-word character, copy as is
            if(j + 1 >= out_cap) {
                out_cap *= 2;
                out = realloc(out, out_cap);
                if(!out) { fprintf(stderr, "Memory allocation failed\n"); exit(1); }
            }
            out[j++] = buffer[i++];
        }
    }
    out[j] = '\0';
    return out;
}

