}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

#define MAX_LENGTH 1024

// Function to convert a camel case word to snake case
void to_snake_case(const char *camel, char *snake) {
    int i, j = 0;
    for (i = 0; camel[i] != '\0'; i++) {
        if (isupper(camel[i]) && i > 0) {
            snake[j++] = '_';
            snake[j++] = tolower(camel[i]);
        } else {
            snake[j++] = tolower(camel[i]);
        }
    }
    snake[j] = '\0';
}

// Function to process the file and convert camel case words to snake case
void process_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Cannot open file");
        exit(EXIT_FAILURE);
    }

    char buffer[MAX_LENGTH];
    char result[MAX_LENGTH * 2];  // Escaped content might be longer
    char word[MAX_LENGTH];
    int i, j, k;

    // Create a temporary file to store the processed output
    FILE *temp = tmpfile();
    if (!temp) {
        perror("Cannot open temporary file");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    // Process line by line
    while (fgets(buffer, sizeof(buffer), file)) {
        i = j = 0;
        while (buffer[i] != '\0') {
            if (isalpha(buffer[i])) {
                // Start of a word
                k = 0;
                while (isalnum(buffer[i])) {
                    word[k++] = buffer[i++];
                }
                word[k] = '\0';

                // Check if the word is camel case
                if (k > 1 && islower(word[0]) && strstr(word, "[A-Z]")) {
                    char snake_case[MAX_LENGTH];
                    to_snake_case(word, snake_case);
                    strcpy(&result[j], snake_case);
                    j += strlen(snake_case);
                } else {
                    strcpy(&result[j], word);
                    j += strlen(word);
                }
            } else {
                result[j++] = buffer[i++];
            }
        }
        result[j] = '\0';
        // Write processed line to temporary file
        fputs(result, temp);
    }

    // Close files
    fclose(file);

    // Replace original file with temp file content
    file = fopen(filename, "w");
    if (!file) {
        perror("Cannot rewrite original file");
        fclose(temp);
        exit(EXIT_FAILURE);
    }

    // Rewind temp file and copy over to original file
    rewind(temp);
    while (fgets(buffer, sizeof(buffer), temp)) {
        fputs(buffer, file);
    }

    // Clean up
    fclose(file);
    fclose(temp);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    process_file(argv[1]);

    return EXIT_SUCCESS;
}

