// Function to convert camel case to snake case
void convertCamelToSnake(const char *camel, char *snake) {
    int j = 0;
    int len = strlen(camel);

    for (int i = 0; i < len; i++) {
        if (isupper(camel[i])) { // If the character is uppercase
            if (i > 0) { // If it's not the first character, add an underscore
                snake[j++] = '_';
            }
            snake[j++] = tolower(camel[i]); // Convert to lowercase
        } else {
            snake[j++] = camel[i]; // Copy the character as is
        }
    }
    snake[j] = '\0'; // Null-terminate the string
}

// Function to check if a word is in camel case
int isCamelCase(const char *word) {
    int hasUpper = 0;
    int hasLower = 0;

    for (int i = 0; word[i]; i++) {
        if (isupper(word[i])) {
            hasUpper = 1;
        }
        if (islower(word[i])) {
            hasLower = 1;
        }
    }

    return hasUpper && hasLower; // Return true if the word has both uppercase and lowercase
}

