// Function to convert a string to snake case
void camelToSnake(char *str) {
    int len = strlen(str);
    for (int i = 0; i < len; i++) {
        // Check if character is uppercase and it's not the first character
        if (isupper(str[i]) && i != 0) {
            // Shift all characters after the current one to the right to make space for '_'
            memmove(str + i + 1, str + i, len - i);
            // Insert '_' before the uppercase letter
            str[i] = '_';
            // Convert the uppercase letter to lowercase
            str[i + 1] = tolower(str[i + 1]);
            // Update the length of the string since we added a character
            len++;
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    char *filename = argv[1];
    FILE *file = fopen(filename, "r+");
    if (!file) {
        perror("Failed to open file");
        return 1;
    }

    // Read the entire file into memory
    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);
    char *content = malloc(fileSize + 1);
    if (!content) {
        fclose(file);
        printf("Memory allocation failed\n");
        return 1;
    }
    fread(content, 1, fileSize, file);
    content[fileSize] = '\0'; // Ensure null-termination

    // Split content into words and convert each word
    char *token = strtok(content, " \n\t");
    while (token) {
        camelToSnake(token);
        token = strtok(NULL, " \n\t");
    }

    // Truncate the file
    ftruncate(fileno(file), 0);
    rewind(file);

    // Write the modified content back to the file
    fwrite(content, 1, strlen(content), file);

    free(content);
    fclose(file);
    return 0;
}

