// Function to convert a single character to lowercase
char toLower(char c) {
    return tolower(c);
}

// Function to convert camel case to snake case
char* camelToSnake(const char* str) {
    int len = strlen(str);
    char* result = (char*)malloc((len * 2 + 1) * sizeof(char)); // Allocate enough space
    int resultIndex = 0;

    for (int i = 0; i < len; i++) {
        if (isupper(str[i]) && i > 0) {
            result[resultIndex++] = '_';
            result[resultIndex++] = toLower(str[i]);
        } else {
            result[resultIndex++] = toLower(str[i]);
        }
    }
    result[resultIndex] = '\0';
    return result;
}

// Function to process the file and convert camel case to snake case
void processFile(const char* filename) {
    FILE* inputFile = fopen(filename, "r");
    if (inputFile == NULL) {
        perror("Error opening file");
        return;
    }

    // Read the file content
    char* buffer = NULL;
    long fileSize;
    fseek(inputFile, 0, SEEK_END);
    fileSize = ftell(inputFile);
    fseek(inputFile, 0, SEEK_SET);
    buffer = (char*)malloc(fileSize + 1);
    fread(buffer, 1, fileSize, inputFile);
    buffer[fileSize] = '\0';

    fclose(inputFile);

    // Process the buffer to convert camel case to snake case
    char* resultBuffer = (char*)malloc(fileSize * 2 + 1); // Allocate enough space
    int resultIndex = 0;
    char* token = strtok(buffer, " ");
    while (token != NULL) {
        char* snakeCaseToken = camelToSnake(token);
        strcat(resultBuffer + resultIndex, snakeCaseToken);
        free(snakeCaseToken);
        resultIndex += strlen(snakeCaseToken);
        if (strtok(NULL, " ") != NULL) {
            resultBuffer[resultIndex++] = ' ';
        }
        token = strtok(NULL, " ");
    }
    resultBuffer[resultIndex] = '\0';

    // Write the modified content back to the file
    FILE* outputFile = fopen(filename, "w");
    if (outputFile == NULL) {
        perror("Error opening file for writing");
        free(buffer);
        free(resultBuffer);
        return;
    }
    fprintf(outputFile, "%s", resultBuffer);

    fclose(outputFile);
    free(buffer);
    free(resultBuffer);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    processFile(argv[1]);

    return 0;
}

#include <stdio.h>
