// Card and hand definitions
#define SUITS 4
#define RANKS 13
#define HAND_SIZE 5

// Enum for hand rankings
typedef enum {
    HIGH_CARD,
    PAIR,
    TWO_PAIR,
    THREE_OF_A_KIND,
    STRAIGHT,
    FLUSH,
    FULL_HOUSE,
    FOUR_OF_A_KIND,
    STRAIGHT_FLUSH,
    ROYAL_FLUSH
} HandRank;

// Card structure
typedef struct {
    int rank;  // 0-12 (2-Ace)
    int suit;  // 0-3 (Hearts, Diamonds, Clubs, Spades)
} Card;

// Hand structure
typedef struct {
    Card cards[HAND_SIZE];
    HandRank rank;
    int rankValue;  // Additional value for tiebreaking
} PokerHand;

// Function prototypes
void sortHand(PokerHand *hand);
HandRank evaluateHand(PokerHand *hand);
int compareHands(const PokerHand *hand1, const PokerHand *hand2);
void printHand(PokerHand *hand);

// Rank and suit names for printing
const char *rankNames[] = {
    "2", "3", "4", "5", "6", "7", "8", "9", "10", "Jack", "Queen", "King", "Ace"
};
const char *suitNames[] = {
    "Hearts", "Diamonds", "Clubs", "Spades"
};

// Sort hand in descending order by rank
void sortHand(PokerHand *hand) {
    for (int i = 0; i < HAND_SIZE - 1; i++) {
        for (int j = 0; j < HAND_SIZE - i - 1; j++) {
            if (hand->cards[j].rank < hand->cards[j+1].rank) {
                Card temp = hand->cards[j];
                hand->cards[j] = hand->cards[j+1];
                hand->cards[j+1] = temp;
            }
        }
    }
}

// Check if hand is a flush
bool isFlush(PokerHand *hand) {
    int suit = hand->cards[0].suit;
    for (int i = 1; i < HAND_SIZE; i++) {
        if (hand->cards[i].suit != suit) return false;
    }
    return true;
}

// Check if hand is a straight
bool isStraight(PokerHand *hand) {
    for (int i = 1; i < HAND_SIZE; i++) {
        if (hand->cards[i-1].rank != hand->cards[i].rank + 1) {
            // Special case for Ace-low straight (A-2-3-4-5)
            if (!(hand->cards[0].rank == 12 && hand->cards[1].rank == 3 &&
                  hand->cards[2].rank == 2 && hand->cards[3].rank == 1 &&
                  hand->cards[4].rank == 0)) {
                return false;
            }
        }
    }
    return true;
}

// Evaluate hand ranking
HandRank evaluateHand(PokerHand *hand) {
    sortHand(hand);
    bool flush = isFlush(hand);
    bool straight = isStraight(hand);

    // Count rank frequencies
    int rankCount[RANKS] = {0};
    for (int i = 0; i < HAND_SIZE; i++) {
        rankCount[hand->cards[i].rank]++;
    }

    // Determine hand ranking
    int pairs = 0, threeKind = 0, fourKind = 0;
    for (int i = 0; i < RANKS; i++) {
        if (rankCount[i] == 2) pairs++;
        if (rankCount[i] == 3) threeKind++;
        if (rankCount[i] == 4) fourKind++;
    }

    if (flush && straight && hand->cards[0].rank == 12) 
        return ROYAL_FLUSH;
    if (flush && straight) 
        return STRAIGHT_FLUSH;
    if (fourKind) 
        return FOUR_OF_A_KIND;
    if (threeKind && pairs) 
        return FULL_HOUSE;
    if (flush) 
        return FLUSH;
    if (straight) 
        return STRAIGHT;
    if (threeKind) 
        return THREE_OF_A_KIND;
    if (pairs == 2) 
        return TWO_PAIR;
    if (pairs == 1) 
        return PAIR;
    return HIGH_CARD;
}

// Compare two hands
int compareHands(const PokerHand *hand1, const PokerHand *hand2) {
    if (hand1->rank != hand2->rank) {
        return hand1->rank - hand2->rank;
    }
    return hand1->rankValue - hand2->rankValue;
}

// Print hand details
void printHand(PokerHand *hand) {
    printf("Hand Rank: %d\n", hand->rank);
    for (int i = 0; i < HAND_SIZE; i++) {
        printf("%s of %s\n", 
               rankNames[hand->cards[i].rank], 
               suitNames[hand->cards[i].suit]);
    }
}

int main() {
    // Example hands
    PokerHand hand1 = {
        .cards = {
            {12, 0}, {11, 0}, {10, 0}, {9, 0}, {8, 0}
        }
    };

    PokerHand hand2 = {
        .cards = {
            {7, 1}, {6, 1}, {5, 1}, {4, 1}, {3, 1}
        }
    };

    // Evaluate hands
    hand1.rank = evaluateHand(&hand1);
    hand2.rank = evaluateHand(&hand2);

    // Compare hands
    int result = compareHands(&hand1, &hand2);

    printf("Hand 1:\n");
    printHand(&hand1);
    printf("\nHand 2:\n");
    printHand(&hand2);

    printf("\nComparison Result: %s\n", 
           result > 0 ? "Hand 1 Wins" : 
           result < 0 ? "Hand 2 Wins" : "Tie");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
