#define NUM_CARDS 5
#define NUM_HANDS 2

typedef enum {
    HIGH_CARD,
    ONE_PAIR,
    TWO_PAIR,
    THREE_OF_A_KIND,
    STRAIGHT,
    FLUSH,
    FULL_HOUSE,
    FOUR_OF_A_KIND,
    STRAIGHT_FLUSH
} HandRank;

typedef struct {
    char rank;
    char suit;
} Card;

typedef struct {
    Card cards[NUM_CARDS];
    HandRank rank;
    int highCard;
} Hand;

const char *rankNames[] = {
    "High Card", "One Pair", "Two Pair", "Three of a Kind", "Straight",
    "Flush", "Full House", "Four of a Kind", "Straight Flush"
};

int cardValue(char rank) {
    if (rank >= '2' && rank <= '9') return rank - '0';
    switch (rank) {
        case 'T': return 10;
        case 'J': return 11;
        case 'Q': return 12;
        case 'K': return 13;
        case 'A': return 14;
        default: return 0;
    }
}

int compareCards(const void *a, const void *b) {
    return cardValue(((Card *)b)->rank) - cardValue(((Card *)a)->rank);
}

void evaluateHand(Hand *hand) {
    qsort(hand->cards, NUM_CARDS, sizeof(Card), compareCards);

    int flush = 1;
    int straight = 1;
    int counts[15] = {0};
    int pairs = 0, three = 0, four = 0;

    for (int i = 0; i < NUM_CARDS; i++) {
        if (i > 0 && hand->cards[i].suit != hand->cards[i - 1].suit) flush = 0;
        if (i > 0 && cardValue(hand->cards[i].rank) != cardValue(hand->cards[i - 1].rank) - 1) straight = 0;
        counts[cardValue(hand->cards[i].rank)]++;
    }

    for (int i = 2; i <= 14; i++) {
        if (counts[i] == 2) pairs++;
        if (counts[i] == 3) three++;
        if (counts[i] == 4) four++;
    }

    if (flush && straight) {
        hand->rank = STRAIGHT_FLUSH;
    } else if (four) {
        hand->rank = FOUR_OF_A_KIND;
    } else if (three && pairs) {
        hand->rank = FULL_HOUSE;
    } else if (flush) {
        hand->rank = FLUSH;
    } else if (straight) {
        hand->rank = STRAIGHT;
    } else if (three) {
        hand->rank = THREE_OF_A_KIND;
    } else if (pairs == 2) {
        hand->rank = TWO_PAIR;
    } else if (pairs == 1) {
        hand->rank = ONE_PAIR;
    } else {
        hand->rank = HIGH_CARD;
    }

    hand->highCard = cardValue(hand->cards[0].rank);
}

int compareHands(const void *a, const void *b) {
    Hand *handA = (Hand *)a;
    Hand *handB = (Hand *)b;

    if (handA->rank != handB->rank) {
        return handB->rank - handA->rank;
    } else {
        return handB->highCard - handA->highCard;
    }
}

int main() {
    Hand hands[NUM_HANDS] = {
        {{{'A', 'H'}, {'K', 'H'}, {'Q', 'H'}, {'J', 'H'}, {'T', 'H'}}, HIGH_CARD, 0},
        {{{'A', 'D'}, {'A', 'S'}, {'K', 'D'}, {'K', 'S'}, {'Q', 'D'}}, HIGH_CARD, 0}
    };

    for (int i = 0; i < NUM_HANDS; i++) {
        evaluateHand(&hands[i]);
    }

    qsort(hands, NUM_HANDS, sizeof(Hand), compareHands);

    for (int i = 0; i < NUM_HANDS; i++) {
        printf("Hand %d: %s (High Card: %d)\n", i + 1, rankNames[hands[i].rank], hands[i].highCard);
    }

    return 0;
}

