typedef struct {
    int rank; // 2-14
    char suit; // 'C', 'D', 'H', 'S'
} Card;

typedef struct {
    Card cards[CARDS_IN_HAND];
    int values[6]; // Used to break ties (e.g. quads rank, etc)
    int handRank; // 1=high card..10=royal flush
    char handString[32];
} PokerHand;

int rankchar_to_value(char r) {
    if(r >= '2' && r <= '9') return r - '0';
    switch(r) {
        case 'T': return 10;
        case 'J': return 11;
        case 'Q': return 12;
        case 'K': return 13;
        case 'A': return 14;
    }
    return 0;
}

void parse_hand(const char *s, PokerHand *hand) {
    for(int i=0; i<CARDS_IN_HAND; i++) {
        int idx = i*3;
        hand->cards[i].rank = rankchar_to_value(s[idx]);
        hand->cards[i].suit = s[idx+1];
    }
    strncpy(hand->handString, s, 3*CARDS_IN_HAND-1);
    hand->handString[3*CARDS_IN_HAND-1]=0;
}

int cmp_desc(const void *a, const void *b) {
    return (*(int*)b) - (*(int*)a);
}
int cmp_card_desc(const void *a, const void *b) {
    const Card *ca = (const Card *)a, *cb = (const Card *)b;
    return cb->rank - ca->rank;
}

void evaluate_hand(PokerHand *hand) {
    int count[15]={0}; // 2-14
    int suitcount[4]={0}; // C, D, H, S
    char suits[]="CDHS";
    int i, valueidx=0;
    int sorted[5];
    int straight = 0, flush = 0;

    for(i=0;i<CARDS_IN_HAND;i++) {
        count[hand->cards[i].rank]++;
        switch(hand->cards[i].suit) {
            case 'C': suitcount[0]++; break;
            case 'D': suitcount[1]++; break;
            case 'H': suitcount[2]++; break;
            case 'S': suitcount[3]++; break;
        }
    }

    // Sort descending for easier analysis
    qsort(hand->cards, CARDS_IN_HAND, sizeof(Card), cmp_card_desc);

    for(i=0;i<CARDS_IN_HAND;i++) sorted[i]=hand->cards[i].rank;

    flush = (suitcount[0]==5||suitcount[1]==5||suitcount[2]==5||suitcount[3]==5);

    // Check straight
    if(sorted[0]-1==sorted[1] && sorted[1]-1==sorted[2] && 
       sorted[2]-1==sorted[3] && sorted[3]-1==sorted[4]) straight = 1;
    // Special: 5-4-3-2-A
    else if(sorted[0]==14 && sorted[1]==5 && sorted[2]==4 && sorted[3]==3 && sorted[4]==2)
        straight = 1;

    // Hand rank and tiebreakers
    if(straight && flush) {
        if(sorted[0]==14 && sorted[1]==13) {
            hand->handRank=10; // Royal Flush
            hand->values[0]=14;
        } else {
            hand->handRank=9; // Straight Flush
            hand->values[0]=sorted[0];
        }
        return;
    }
    // 4 of a kind
    for(i=2; i<=14; i++) 
        if(count[i]==4) {
            hand->handRank=8;
            hand->values[0]=i; // quad's number
            // kicker
            for(int j=2;j<=14;j++) if(count[j]==1) {
                hand->values[1]=j; break;
            }
            return;
        }
    // full house
    int pairVal=0, threeVal=0;
    for(i=2;i<=14;i++) {
        if(count[i]==3) threeVal=i;
        if(count[i]==2) pairVal=i;
    }
    if(threeVal && pairVal) {
        hand->handRank=7;
        hand->values[0]=threeVal;
        hand->values[1]=pairVal;
        return;
    }
    // flush?
    if(flush) {
        hand->handRank=6;
        memcpy(hand->values, sorted, sizeof(int)*5);
        return;
    }
    // straight?
    if(straight) {
        hand->handRank=5;
        // 5-high straight: value is 5
        hand->values[0] = (sorted[0]==14 && sorted[1]==5 ? 5 : sorted[0]);
        return;
    }
    // 3 of a kind
    if(threeVal) {
        hand->handRank=4;
        hand->values[0]=threeVal;
        valueidx=1;
        // kickers
        for(i=0;i<5;i++)
            if(hand->cards[i].rank!=threeVal)
                hand->values[valueidx++]=hand->cards[i].rank;
        return;
    }
    // 2 pair
    int pairs[2], npair=0, kicker=0;
    for(i=14;i>=2;i--) if(count[i]==2) pairs[npair++]=i;
    if(npair==2) {
        hand->handRank=3;
        hand->values[0]=pairs[0];
        hand->values[1]=pairs[1];
        for(i=2;i<=14;i++) if(count[i]==1) hand->values[2]=i;
        return;
    }
    // 1 pair
    if(npair==1) {
        hand->handRank=2;
        hand->values[0]=pairs[0];
        valueidx=1;
        for(i=0;i<5;i++)
            if(hand->cards[i].rank!=pairs[0])
                hand->values[valueidx++]=hand->cards[i].rank;
        return;
    }
    // high card
    hand->handRank=1;
    memcpy(hand->values, sorted, sizeof(int)*5);
}

// Compare hands (descending order: strongest first)
int compare_hands(const void *ha, const void *hb) {
    const PokerHand *a=(const PokerHand*)ha, *b=(const PokerHand*)hb;
    if(a->handRank != b->handRank)
        return b->handRank - a->handRank;
    for(int i=0;i<6;i++) {
        if(a->values[i] != b->values[i])
            return b->values[i] - a->values[i];
    }
    return 0;
}

