int cardValue(char value) {
    if (value >= '2' && value <= '9') return value - '0';
    switch (value) {
        case 'T': return 10;
        case 'J': return 11;
        case 'Q': return 12;
        case 'K': return 13;
        case 'A': return 14;
    }
    return 0; // Error handling, should not reach here
}

int compareHands(const void *a, const void *b) {
    Hand *handA = (Hand *)a;
    Hand *handB = (Hand *)b;
    return handB->rank - handA->rank; // descending order
}

HandRank evaluateHand(Hand *hand) {
    Card *cards = hand->cards;
    int values[15] = { 0 };
    int is_flush = isFlush(cards);
    int is_straight = isStraight(cards);

    for (int i = 0; i < CARDS_IN_HAND; i++) {
        values[cardValue(cards[i].value)]++;
    }

    if (is_flush && is_straight && cardValue(cards[0].value) == 10) {
        return ROYAL_FLUSH;
    } else if (is_flush && is_straight) {
        return STRAIGHT_FLUSH;
    }

    int four = 0, three = 0, pairs = 0;
    for (int i = 2; i <= 14; i++) {
        if (values[i] == 4) four++;
        if (values[i] == 3) three++;
        if (values[i] == 2) pairs++;
    }

    if (four) {
        return FOUR_OF_A_KIND;
    } else if (three && pairs) {
        return FULL_HOUSE;
    } else if (is_flush) {
        return FLUSH;
    } else if (is_straight) {
        return STRAIGHT;
    } else if (three) {
        return THREE_OF_A_KIND;
    } else if (pairs == 2) {
        return TWO_PAIR;
    } else if (pairs == 1) {
        return ONE_PAIR;
    }

    return HIGH_CARD;
}

int isFlush(Card *cards) {
    for (int i = 1; i < CARDS_IN_HAND; i++) {
        if (cards[i].suit != cards[0].suit) {
            return 0;
        }
    }
    return 1;
}

int isStraight(Card *cards) {
    int sorted_values[CARDS_IN_HAND];
    for (int i = 0; i < CARDS_IN_HAND; i++) {
        sorted_values[i] = cardValue(cards[i].value);
    }
    qsort(sorted_values, CARDS_IN_HAND, sizeof(int), compareHands);

    for (int i = 1; i < CARDS_IN_HAND; i++) {
        if (sorted_values[i] != sorted_values[i - 1] + 1) {
            return 0;
        }
    }
    return 1;
}

void printHandRank(HandRank rank) {
    switch (rank) {
        case HIGH_CARD:        printf("High Card\n"); break;
        case ONE_PAIR:         printf("One Pair\n"); break;
        case TWO_PAIR:         printf("Two Pair\n"); break;
