// Function to evaluate hand strength
int evaluate_hand(hand h) {
    int is_flush = 1;
    int is_straight = 1;
    int pairs = 0;
    int trips = 0;
    int quad = 0;
    int straight_count = 1;
    int highest_card = h.cards[0].r;

    // Check for flush
    for (int i = 1; i < 5; i++) {
        if (h.cards[i].s != h.cards[0].s) {
            is_flush = 0;
            break;
        }
    }

    // Check for straight
    for (int i = 1; i < 5; i++) {
        if (h.cards[i].r != h.cards[i - 1].r + 1) {
            is_straight = 0;
            break;
        }
        straight_count++;
    }

    // Check for pairs, trips, and quad
    int count[13] = {0};
    for (int i = 0; i < 5; i++) {
        count[h.cards[i].r]++;
    }
    for (int i = 0; i < 13; i++) {
        if (count[i] == 2) pairs++;
        if (count[i] == 3) trips++;
        if (count[i] == 4) quad++;
    }

    // Determine hand strength
    if (is_flush && is_straight) {
        if (h.cards[4].r == ACE) {
            return 10; // Royal Flush
        } else {
            return 9; // Straight Flush
        }
    } else if (quad) {
        return 8; // Four of a Kind
    } else if (trips && pairs) {
        return 7; // Full House
    } else if (is_flush) {
        return 6; // Flush
    } else if (is_straight) {
        return 5; // Straight
    } else if (trips) {
        return 4; // Three of a Kind
    } else if (pairs == 2) {
        return 3; // Two Pair
    } else if (pairs) {
        return 2; // One Pair
    } else {
        return 1; // High Card
    }
}

