typedef struct {
    char card[3];
} Card;

typedef struct {
    Card cards[5];
} PokerHand;

typedef enum {
    HIGH_CARD, ONE_PAIR, TWO_PAIR, THREE_OF_A_KIND, STRAIGHT, FLUSH, FULL_HOUSE, FOUR_OF_A_KIND, STRAIGHT_FLUSH, ROYAL_FLUSH
} HandRank;

typedef struct {
    HandRank rank;
    int highCard;
} HandStrength;

int valueOf(char card) {
    switch (card) {
        case '2': return 2;
        case '3': return 3;
        case '4': return 4;
        case '5': return 5;
        case '6': return 6;
        case '7': return 7;
        case '8': return 8;
        case '9': return 9;
        case 'T': return 10;
        case 'J': return 11;
        case 'Q': return 12;
        case 'K': return 13;
        case 'A': return 14;
        default: return 0;
    }
}

int suitOf(char card) {
    switch (card) {
        case 'S': return 1; // Spades
        case 'H': return 2; // Hearts
        case 'D': return 3; // Diamonds
        case 'C': return 4; // Clubs
        default: return 0;
    }
}

int compareCards(const void *a, const void *b) {
    char cardA[3], cardB[3];
    strncpy(cardA, ((Card *)a)->card, 3);
    strncpy(cardB, ((Card *)b)->card, 3);
    return valueOf(cardA[0]) - valueOf(cardB[0]);
}

HandStrength evaluateHand(PokerHand hand) {
    qsort(hand.cards, 5, sizeof(Card), compareCards);

    int values[5];
    int suits[5];
    for (int i = 0; i < 5; ++i) {
        values[i] = valueOf(hand.cards[i].card[0]);
        suits[i] = suitOf(hand.cards[i].card[1]);
    }

    int straight = 1;
    int flush = 1;
    for (int i = 0; i < 4; ++i) {
        if (values[i] + 1 != values[i + 1]) straight = 0;
        if (suits[i] != suits[i + 1]) flush = 0;
    }

    if (straight && flush) {
        if (values[0] == 10) return (HandStrength){ROYAL_FLUSH, values[4]};
        return (HandStrength){STRAIGHT_FLUSH, values[4]};
    }

    int counts[15] = {0};
    for (int i = 0; i < 5; ++i) {
        counts[values[i]]++;
    }

    int fourOfAKind = 0;
    int threeOfAKind = 0;
    int pair = 0;
    for (int i = 2; i <= 14; ++i) {
        if (counts[i] == 4) fourOfAKind = i;
        if (counts[i] == 3) threeOfAKind = i;
        if (counts[i] == 2) pair = i;
    }

    if (fourOfAKind) return (HandStrength){FOUR_OF_A_KIND, fourOfAKind};
    if (threeOfAKind && pair) return (HandStrength){FULL_HOUSE, threeOfAKind};
    if (flush) return (HandStrength){FLUSH, values[4]};
    if (straight) return (HandStrength){STRAIGHT, values[4]};
    if (threeOfAKind) return (HandStrength){THREE_OF_A_KIND, threeOfAKind};
    if (pair) {
        int pair2 = 0;
        for (int i = 2; i <= 14; ++i) {
            if (counts[i] == 2 && i != pair) pair2 = i;
        }
        if (pair2) return (HandStrength){TWO_PAIR, pair > pair2 ? pair : pair2};
        return (HandStrength){ONE_PAIR, pair};
    }

    return (HandStrength){HIGH_CARD, values[4]};
}

int compareHands(const void *a, const void *b) {
    HandStrength handA = evaluateHand(*(PokerHand *)a);
    HandStrength handB = evaluateHand(*(PokerHand *)b);

    if (handA.rank != handB.rank) return handB.rank - handA.rank;
    return handB.highCard - handA.highCard;
}

