// Function to convert string to lowercase
void toLowerCase(char* str) {
    for (int i = 0; str[i]; i++) {
        str[i] = tolower(str[i]);
    }
}

// Function to find the best matching response
char* findResponse(char* input) {
    // Convert input to lowercase
    toLowerCase(input);

    // Check for exact or partial matches
    for (int i = 0; i < sizeof(responses) / sizeof(responses[0]); i++) {
        // Check for exact match or if pattern is contained in input
        if (strstr(input, responses[i].pattern) != NULL && 
            strlen(responses[i].pattern) > 0) {
            return responses[i].response;
        }
    }

    // Return default response if no match found
    return responses[sizeof(responses) / sizeof(responses[0]) - 1].response;
}

// Main chatbot interaction function
void startChatbot() {
    char input[MAX_INPUT_LENGTH];

    printf("ChatBot: Hello! I'm a simple chatbot. Type 'bye' to exit.\n");

    while (1) {
        // Get user input
        printf("You: ");
        fgets(input, sizeof(input), stdin);

        // Remove newline character
        input[strcspn(input, "\n")] = 0;

        // Check for exit condition
        if (strcmp(input, "bye") == 0) {
            printf("ChatBot: Goodbye!\n");
            break;
        }

        // Find and print response
        char* response = findResponse(input);
        printf("ChatBot: %s\n", response);
    }
}

