#include <stdio.h>
#include <stdlib.h>

// Define the structure for a doubly linked list node
typedef struct Node {
    int data;               // Data stored in the node
    struct Node* prev;      // Pointer to previous node
    struct Node* next;      // Pointer to next node
} Node;

// Function prototypes
Node* createNode(int data);
void insertAtBeginning(Node** head, int data);
void insertAtEnd(Node** head, int data);
void insertAfterNode(Node* prevNode, int data);
void deleteNode(Node** head, int key);
void displayList(Node* head);
void displayListReverse(Node* head);
int searchList(Node* head, int key);
int getListLength(Node* head);

// Function to create a new node
Node* createNode(int data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed!\n");
        exit(1);
    }

    newNode->data = data;
    newNode->prev = NULL;
    newNode->next = NULL;

    return newNode;
}

// Function to insert a node at the beginning of the list
void insertAtBeginning(Node** head, int data) {
    Node* newNode = createNode(data);

    if (*head == NULL) {
        *head = newNode;
        return;
    }

    newNode->next = *head;
    (*head)->prev = newNode;
    *head = newNode;
}

// Function to insert a node at the end of the list
void insertAtEnd(Node** head, int data) {
    Node* newNode = createNode(data);

    if (*head == NULL) {
        *head = newNode;
        return;
    }

    Node* current = *head;
    while (current->next != NULL) {
        current = current->next;
    }

    current->next = newNode;
    newNode->prev = current;
}

// Function to insert a node after a given node
void insertAfterNode(Node* prevNode, int data) {
    if (prevNode == NULL) {
        printf("Previous node cannot be NULL\n");
        return;
    }

    Node* newNode = createNode(data);

    newNode->next = prevNode->next;
    newNode->prev = prevNode;

    if (prevNode->next != NULL) {
        prevNode->next->prev = newNode;
    }

    prevNode->next = newNode;
}

// Function to delete a node with a given key
void deleteNode(Node** head, int key) {
    if (*head == NULL) {
        printf("List is empty\n");
        return;
    }

    Node* current = *head;

    // If head node itself holds the key
    if (current->data == key) {
        *head = current->next;
        if (*head != NULL) {
            (*head)->prev = NULL;
        }
        free(current);
        return;
    }

    // Search for the node to be deleted
    while (current != NULL && current->data != key) {
        current = current->next;
    }

    // If key is not present
    if (current == NULL) {
        printf("Key not found in the list\n");
        return;
    }

    // Adjust links to remove the node
    if (current->prev != NULL) {
        current->prev->next = current->next;
    }

    if (current->next != NULL) {
        current->next->prev = current->prev;
    }

    free(current);
}

// Function to display the list in forward direction
void displayList(Node* head) {
    if (head == NULL) {
        printf("List is empty\n");
        return;
    }

    printf("List: ");
    while (head != NULL) {
        printf("%d <-> ", head->data);
        head = head->next;
    }
    printf("NULL\n");
}

// Function to display the list in reverse direction
void displayListReverse(Node* head) {
    if (head == NULL) {
        printf("List is empty\n");
        return;
    }

    // Find the last node
    while (head->next != NULL) {
        head = head->next;
    }

    printf("Reverse List: ");
    while (head != NULL) {
        printf("%d <-> ", head->data);
        head = head->prev;
    }
    printf("NULL\n");
}

// Function to search for a key in the list
int searchList(Node* head, int key) {
    int position = 1;

    while (head != NULL) {
        if (head->data == key) {
            return position;
        }
        head = head->next;
        position++;
    }

    return -1;  // Key not found
}

// Function to get the length of the list
int getListLength(Node* head) {
    int length = 0;

    while (head != NULL) {
        length++;
        head = head->next;
    }

    return length;
}

// Main function to demonstrate doubly linked list operations
int main() {
    Node* head = NULL;

    // Insert elements
    insertAtEnd(&head, 10);
    insertAtEnd(&head, 20);
    insertAtBeginning(&head, 5);
    insertAfterNode(head->next, 15);

    // Display list
    displayList(head);
    displayListReverse(head);

    // Search and get length
    int key = 15;
    int position = searchList(head, key);
    if (position != -1) {
        printf("%d found at position %d\n", key, position);
    } else {
        printf("%d not found in the list\n", key);
    }

    printf("List length: %d\n", getListLength(head));

    // Delete node
    deleteNode(&head, 20);
    displayList(head);

    return 0;
}

