    while (head) {
        printf("%d ", head->data);
        head = head->prev;
    }
    printf("\n");
}

// Free memory
void freeList(struct Node* head) {
    struct Node* tmp;
    while (head) {
        tmp = head;
        head = head->next;
        free(tmp);
    }
}

