// Define the structure for a doubly linked list node
typedef struct Node {
    int data;
    struct Node* next;
    struct Node* prev;
} Node;

// Define the structure for the doubly linked list
typedef struct {
    Node* head;
    Node* tail;
    int size;
} DoublyLinkedList;

// Function to create a new doubly linked list node
Node* createNode(int data) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory error\n");
        return NULL;
    }
    newNode->data = data;
    newNode->next = NULL;
    newNode->prev = NULL;
    return newNode;
}

// Function to initialize the doubly linked list
DoublyLinkedList* initDoublyLinkedList() {
    DoublyLinkedList* list = (DoublyLinkedList*) malloc(sizeof(DoublyLinkedList));
    if (!list) {
        printf("Memory error\n");
        return NULL;
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    return list;
}

// Function to insert a node at the beginning of the list
void insertAtHead(DoublyLinkedList* list, int data) {
    Node* newNode = createNode(data);
    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        newNode->next = list->head;
        list->head->prev = newNode;
        list->head = newNode;
    }
    list->size++;
}

// Function to insert a node at the end of the list
void insertAtTail(DoublyLinkedList* list, int data) {
    Node* newNode = createNode(data);
    if (list->tail == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        newNode->prev = list->tail;
        list->tail->next = newNode;
        list->tail = newNode;
    }
    list->size++;
}

// Function to delete a node from the list
void deleteNode(DoublyLinkedList* list, int data) {
    Node* temp = list->head;
    while (temp!= NULL) {
        if (temp->data == data) {
            if (temp->prev!= NULL) {
                temp->prev->next = temp->next;
            } else {
                list->head = temp->next;
            }
            if (temp->next!= NULL) {
                temp->next->prev = temp->prev;
            } else {
                list->tail = temp->prev;
            }
            free(temp);
            list->size--;
            return;
        }
        temp = temp->next;
    }
}

// Function to print the list in forward direction
void printForward(DoublyLinkedList* list) {
    Node* temp = list->head;
    while (temp!= NULL) {
        printf("%d ", temp->data);
        temp = temp->next;
    }
    printf("\n");
}

// Function to print the list in backward direction
void printBackward(DoublyLinkedList* list) {
    Node* temp = list->tail;
    while (temp!= NULL) {
        printf("%d ", temp->data);
        temp = temp->prev;
    }
    printf("\n");
}

int main() {
    DoublyLinkedList* list = initDoublyLinkedList();
    insertAtTail(list, 10);
    insertAtTail(list, 20);
    insertAtTail(list, 30);
    insertAtHead(list, 5);
    printForward(list);  // Output: 5 10 20 30
    printBackward(list);  // Output: 30 20 10 5
    deleteNode(list, 20);
    printForward(list);  // Output: 5 10 30
    printBackward(list);  // Output: 30 10 5
    return 0;
}

