#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>
#include <math.h>

#define MAX_EXPRESSION_LENGTH 100
#define MAX_STACK_SIZE 100

// Stack for operators and operands
typedef struct {
    double items[MAX_STACK_SIZE];
    int top;
} OperandStack;

typedef struct {
    char items[MAX_STACK_SIZE];
    int top;
} OperatorStack;

// Function prototypes
void initStack(OperandStack* operandStack);
void pushOperand(OperandStack* stack, double value);
double popOperand(OperandStack* stack);
int isOperandStackEmpty(OperandStack* stack);

void initOperatorStack(OperatorStack* operatorStack);
void pushOperator(OperatorStack* stack, char op);
char popOperator(OperatorStack* stack);
int isOperatorStackEmpty(OperatorStack* stack);
char topOperator(OperatorStack* stack);

int getPrecedence(char op);
double performOperation(double a, double b, char op);
double evaluateExpression(char* expression);
int isValidOperator(char op);

// Operand stack functions
void initStack(OperandStack* operandStack) {
    operandStack->top = -1;
}

void pushOperand(OperandStack* stack, double value) {
    if (stack->top < MAX_STACK_SIZE - 1) {
        stack->top++;
        stack->items[stack->top] = value;
    } else {
        printf("Operand stack overflow!\n");
        exit(1);
    }
}

double popOperand(OperandStack* stack) {
    if (!isOperandStackEmpty(stack)) {
        double value = stack->items[stack->top];
        stack->top--;
        return value;
    }
    printf("Operand stack underflow!\n");
    exit(1);
}

int isOperandStackEmpty(OperandStack* stack) {
    return stack->top == -1;
}

// Operator stack functions
void initOperatorStack(OperatorStack* operatorStack) {
    operatorStack->top = -1;
}

void pushOperator(OperatorStack* stack, char op) {
    if (stack->top < MAX_STACK_SIZE - 1) {
        stack->top++;
        stack->items[stack->top] = op;
    } else {
        printf("Operator stack overflow!\n");
        exit(1);
    }
}

char popOperator(OperatorStack* stack) {
    if (!isOperatorStackEmpty(stack)) {
        char op = stack->items[stack->top];
        stack->top--;
        return op;
    }
    printf("Operator stack underflow!\n");
    exit(1);
}

int isOperatorStackEmpty(OperatorStack* stack) {
    return stack->top == -1;
}

char topOperator(OperatorStack* stack) {
    if (!isOperatorStackEmpty(stack)) {
        return stack->items[stack->top];
    }
    return '\0';
}

// Helper functions
int getPrecedence(char op) {
    switch (op) {
        case '+':
        case '-':
            return 1;
        case '*':
        case '/':
            return 2;
        case '^':
            return 3;
        default:
            return 0;
    }
}

int isValidOperator(char op) {
    return op == '+' || op == '-' || op == '*' || op == '/' || op == '^';
}

double performOperation(double a, double b, char op) {
    switch (op) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/':
            if (b == 0) {
                printf("Error: Division by zero\n");
                exit(1);
            }
            return a / b;
        case '^': return pow(a, b);
        default:
            printf("Invalid operator\n");
            exit(1);
    }
}

double evaluateExpression(char* expression) {
    OperandStack operandStack;
    OperatorStack operatorStack;

    initStack(&operandStack);
    initOperatorStack(&operatorStack);

    for (int i = 0; expression[i] != '\0'; i++) {
        // Skip whitespace
        if (isspace(expression[i])) continue;

        // Handle numbers
        if (isdigit(expression[i]) || expression[i] == '.') {
            char numBuffer[20];
            int j = 0;

            while (isdigit(expression[i]) || expression[i] == '.') {
                numBuffer[j++] = expression[i++];
            }
            numBuffer[j] = '\0';
            i--;

            pushOperand(&operandStack, atof(numBuffer));
        }

        // Handle operators and parentheses
        else if (isValidOperator(expression[i]) || expression[i] == '(' || expression[i] == ')') {
            if (expression[i] == '(') {
                pushOperator(&operatorStack, expression[i]);
            }
            else if (expression[i] == ')') {
                while (!isOperatorStackEmpty(&operatorStack) && topOperator(&operatorStack) != '(') {
                    char op = popOperator(&operatorStack);
                    double b = popOperand(&operandStack);
                    double a = popOperand(&operandStack);
                    pushOperand(&operandStack, performOperation(a, b, op));
                }

                if (!isOperatorStackEmpty(&operatorStack) && topOperator(&operatorStack) == '(') {
                    popOperator(&operatorStack);
                }
            }
            else {
                while (!isOperatorStackEmpty(&operatorStack) && 
                       topOperator(&operatorStack) != '(' && 
                       getPrecedence(topOperator(&operatorStack)) >= getPrecedence(expression[i])) {
                    char op = popOperator(&operatorStack);
                    double b = popOperand(&operandStack);
                    double a = popOperand(&operandStack);
                    pushOperand(&operandStack, performOperation(a, b, op));
                }
                pushOperator(&operatorStack, expression[i]);
            }
        }
        else if (!isspace(expression[i])) {
            printf("Invalid character: %c\n", expression[i]);
            exit(1);
        }
    }

    // Process remaining operators
    while (!isOperatorStackEmpty(&operatorStack)) {
        char op = popOperator(&operatorStack);
        double b = popOperand(&operandStack);
        double a = popOperand(&operandStack);
        pushOperand(&operandStack, performOperation(a, b, op));
    }

    return popOperand(&operandStack);
}

int main() {
    char expression[MAX_EXPRESSION_LENGTH];

    printf("Simple Calculator\n");
    printf("Supported operations: +, -, *, /, ^ (power)\n");
    printf("Use parentheses () for grouping\n");

    while (1) {
        printf("\nEnter an expression (or 'q' to quit): ");
        fgets(expression, sizeof(expression), stdin);

        // Remove newline character
        expression[strcspn(expression, "\n")] = '\0';

        // Check for quit
        if (strcmp(expression, "q") == 0) {
            break;
        }

        // Evaluate and print result
        double result = evaluateExpression(expression);
        printf("Result: %g\n", result);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <math.h>
#include <string.h>

// Function prototypes
double expression();
double term();
double factor();
void skip_whitespace();

// Global variables
char *input;
char buffer[256];

// Skip whitespace characters
void skip_whitespace() {
    while (*input == ' ') {
        input++;
    }
}

// Parse a factor (number or parenthesized expression)
double factor() {
    double result;
    int sign = 1;

    skip_whitespace();

    // Handle unary minus
    if (*input == '-') {
        sign = -1;
        input++;
        skip_whitespace();
    }

    if (*input == '(') {
        input++;
        result = expression();
        skip_whitespace();
        if (*input != ')') {
            printf("Error: Missing closing parenthesis\n");
            exit(1);
        }
        input++;
    } else {
        // Parse number
        char *endptr;
        result = strtod(input, &endptr);
        if (input == endptr) {
            printf("Error: Expected number\n");
            exit(1);
        }
        input = endptr;
    }

    return sign * result;
}

// Parse a term (* and / operations)
double term() {
    double result = factor();

    while (1) {
        skip_whitespace();
        char op = *input;
        if (op == '*' || op == '/') {
            input++;
            double next_factor = factor();
            if (op == '*') {
                result *= next_factor;
            } else {
                if (next_factor == 0.0) {
                    printf("Error: Division by zero\n");
                    exit(1);
                }
                result /= next_factor;
            }
        } else {
            break;
        }
    }

    return result;
}

// Parse an expression (+ and - operations)
double expression() {
    double result = term();

    while (1) {
        skip_whitespace();
        char op = *input;
        if (op == '+' || op == '-') {
            input++;
            double next_term = term();
            if (op == '+') {
                result += next_term;
            } else {
                result -= next_term;
            }
        } else {
            break;
        }
    }

    return result;
}

int main() {
    printf("Simple Calculator\n");
    printf("Enter expressions with +, -, *, /, and parentheses\n");
    printf("Enter 'exit' to quit\n\n");

    while (1) {
        printf("> ");
        fgets(buffer, sizeof(buffer), stdin);

        // Remove newline character
        buffer[strcspn(buffer, "\n")] = 0;

        if (strcmp(buffer, "exit") == 0) {
            break;
        }

        input = buffer;
        double result = expression();

        // Check if we parsed the entire input
        skip_whitespace();
        if (*input != '\0') {
            printf("Error: Unexpected character '%c'\n", *input);
        } else {
            printf("= %g\n", result);
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h> // For atof, exit
#include <string.h> // For strlen
#include <ctype.h>  // For isspace, isdigit

// Global pointer to the current position in the input expression string
static char *input_ptr;

// Function prototypes for the recursive descent parser
double parse_expression();
double parse_term();
double parse_factor();
double parse_number();
void skip_whitespace();

// --- Helper Functions ---

// Skips any whitespace characters from the current input_ptr position
void skip_whitespace() {
    while (*input_ptr != '\0' && isspace((unsigned char)*input_ptr)) {
        input_ptr++;
    }
}

// Reports an error and exits the program
void error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    exit(EXIT_FAILURE);
}

// --- Parsing Functions (Recursive Descent) ---

// Parses a number (integer or floating point)
double parse_number() {
    skip_whitespace();
    double value = 0.0;
    int sign = 1;

    // Handle leading sign (unary plus/minus)
    if (*input_ptr == '-') {
        sign = -1;
        input_ptr++;
    } else if (*input_ptr == '+') {
        input_ptr++;
    }

    // Check if the current character is a digit after sign (if any)
    if (!isdigit((unsigned char)*input_ptr)) {
        error("Expected a number or an opening parenthesis");
    }

    // Read the integer part
    while (isdigit((unsigned char)*input_ptr)) {
        value = value * 10.0 + (*input_ptr - '0');
        input_ptr++;
    }

    // Read the fractional part (if any)
    if (*input_ptr == '.') {
        input_ptr++;
        double fraction_divisor = 10.0;
        while (isdigit((unsigned char)*input_ptr)) {
            value += (*input_ptr - '0') / fraction_divisor;
            fraction_divisor *= 10.0;
            input_ptr++;
        }
    }

    // Unary minus for positive numbers
    return value * sign;
}

// Parses a factor: a number or a parenthesized expression
double parse_factor() {
    skip_whitespace();
    double result;

    if (*input_ptr == '(') {
        input_ptr++; // Consume '('
        result = parse_expression(); // Recursively parse the expression inside
        skip_whitespace();
        if (*input_ptr != ')') {
            error("Mismatched parentheses: Expected ')'");
        }
        input_ptr++; // Consume ')'
    } else {
        // It's a number (can be unary minus too, handled in parse_number)
        result = parse_number();
    }
    return result;
}

// Parses a term: factors combined with multiplication or division
double parse_term() {
    double result = parse_factor();

    skip_whitespace();
    while (*input_ptr == '*' || *input_ptr == '/') {
        char op = *input_ptr;
        input_ptr++; // Consume operator
        double next_factor = parse_factor();

        if (op == '*') {
            result *= next_factor;
        } else { // op == '/'
            if (next_factor == 0.0) {
                error("Division by zero");
            }
            result /= next_factor;
        }
        skip_whitespace();
    }
    return result;
}

// Parses an expression: terms combined with addition or subtraction
double parse_expression() {
    double result = parse_term();

    skip_whitespace();
    while (*input_ptr == '+' || *input_ptr == '-') {
        char op = *input_ptr;
        input_ptr++; // Consume operator
        double next_term = parse_term();

        if (op == '+') {
            result += next_term;
        } else { // op == '-'
            result -= next_term;
        }
        skip_whitespace();
    }
    return result;
}

// --- Main Function ---

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s \"<expression>\"\n", argv[0]);
        fprintf(stderr, "Example: %s \"3 + 4 * (2 - 1) / 2\"\n", argv[0]);
        return EXIT_FAILURE;
    }

    input_ptr = argv[1]; // Set the global pointer to the input expression

    double result = parse_expression();

    skip_whitespace();
    // After parsing the entire expression, input_ptr should point to the end of the string
    if (*input_ptr != '\0') {
        fprintf(stderr, "Error: Unexpected characters at the end of expression: '%s'\n", input_ptr);
        return EXIT_FAILURE;
    }

    printf("Result: %.4f\n", result); // Print with 4 decimal places for precision

    return EXIT_SUCCESS;
}

#include <stdio.h>
