// --- Parser state ---
const char *input;
int pos = 0;

// --- Helpers ---
void skip_whitespace() {
    while (isspace(input[pos])) pos++;
}

// --- Parsing functions (recursive descent parser) ---

double expr();      // Forward declaration

double number() {
    skip_whitespace();
    double val = 0;
    int sign = 1;

    // Handle unary plus/minus
    if (input[pos] == '+' || input[pos] == '-') {
        if (input[pos] == '-') sign = -1;
        pos++;
        skip_whitespace();
    }

    if (isdigit(input[pos]) || input[pos] == '.') {
        char buf[64];
        int len = 0;
        while (isdigit(input[pos]) || input[pos] == '.') {
            if (len < (int)(sizeof(buf)-1))
                buf[len++] = input[pos];
            pos++;
        }
        buf[len] = '\0';
        val = atof(buf);
    }

    // Parentheses
    skip_whitespace();
    if (input[pos] == '(') {
        pos++;
        val = expr();
        skip_whitespace();
        if (input[pos] == ')') {
            pos++;
        } else {
            printf("Error: expected ')'\n");
            exit(1);
        }
    }

    return sign * val;
}

// factor = number | '(' expr ')'
double factor() {
    return number();
}

// term = factor {* ('*'|'/') factor}
double term() {
    skip_whitespace();
    double result = factor();
    skip_whitespace();
    while (input[pos] == '*' || input[pos] == '/') {
        char op = input[pos++];
        skip_whitespace();
        double rhs = factor();
        if (op == '*')
            result *= rhs;
        else {
            if (rhs == 0) {
                printf("Error: division by zero\n");
                exit(1);
            }
            result /= rhs;
        }
        skip_whitespace();
    }
    return result;
}

// expr = term {('+'|'-') term}
double expr() {
    skip_whitespace();
    double result = term();
    skip_whitespace();
    while (input[pos] == '+' || input[pos] == '-') {
        char op = input[pos++];
        skip_whitespace();
        double rhs = term();
        if (op == '+')
            result += rhs;
        else
            result -= rhs;
        skip_whitespace();
    }
    return result;
}

int main() {
    char line[256];
    printf("Simple Calculator (supports +, -, *, /, parentheses)\n");
    printf("Enter expression (or empty line to quit):\n");
    while (1) {
        printf("> ");
        if (!fgets(line, sizeof(line), stdin)) break;
        // Remove newline
        char *p = line;
        while (*p && *p != '\n') p++;
        *p = '\0';

        if (line[0] == '\0') break;

        input = line;
        pos = 0;
        double result = expr();
        skip_whitespace();
        if (input[pos] != '\0') {
            printf("Error: unexpected character '%c' at position %d\n", input[pos], pos);
        } else {
            printf("= %g\n", result);
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <math.h>

#define MAX_STACK_SIZE 100
#define MAX_EXPR_SIZE 256

typedef struct {
    double numbers[MAX_STACK_SIZE];
    int top;
} NumStack;

typedef struct {
    char operators[MAX_STACK_SIZE];
    int top;
} OpStack;

void push_num(NumStack *s, double value) {
    if (s->top < MAX_STACK_SIZE - 1) {
        s->numbers[++(s->top)] = value;
    } else {
        fprintf(stderr, "Number stack overflow\n");
        exit(EXIT_FAILURE);
    }
}

double pop_num(NumStack *s) {
    if (s->top >= 0) {
        return s->numbers[(s->top)--];
    } else {
        fprintf(stderr, "Number stack underflow\n");
        exit(EXIT_FAILURE);
    }
}

void push_op(OpStack *s, char op) {
    if (s->top < MAX_STACK_SIZE - 1) {
        s->operators[++(s->top)] = op;
    } else {
        fprintf(stderr, "Operator stack overflow\n");
        exit(EXIT_FAILURE);
    }
}

char pop_op(OpStack *s) {
    if (s->top >= 0) {
        return s->operators[(s->top)--];
    } else {
        fprintf(stderr, "Operator stack underflow\n");
        exit(EXIT_FAILURE);
    }
}

char peek_op(OpStack *s) {
    if (s->top >= 0) {
        return s->operators[s->top];
    }
    return '\0';
}

int is_empty_op(OpStack *s) {
    return s->top == -1;
}

int precedence(char op) {
    switch (op) {
        case '+':
        case '-':
            return 1;
        case '*':
        case '/':
            return 2;
        default:
            return 0;
    }
}

int is_operator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/';
}

void apply_operator(NumStack *numbers, char operator) {
    double right = pop_num(numbers);
    double left = pop_num(numbers);
    switch (operator) {
        case '+': push_num(numbers, left + right); break;
        case '-': push_num(numbers, left - right); break;
        case '*': push_num(numbers, left * right); break;
        case '/':
            if (right == 0) {
                fprintf(stderr, "Division by zero\n");
                exit(EXIT_FAILURE);
            }
            push_num(numbers, left / right);
            break;
        default:
            fprintf(stderr, "Unknown operator %c\n", operator);
            exit(EXIT_FAILURE);
    }
}

double evaluate_expression(const char *expression) {
    NumStack numbers = {.top = -1};
    OpStack operators = {.top = -1};
    char token[MAX_EXPR_SIZE];
    int i = 0;
    int len = strlen(expression);

    while (i < len) {
        if (isspace(expression[i])) {
            i++;
            continue;
        }

        if (isdigit(expression[i]) || (expression[i] == '.' && i + 1 < len && isdigit(expression[i + 1]))) {
            int j = 0;
            while (i < len && (isdigit(expression[i]) || expression[i] == '.')) {
                token[j++] = expression[i++];
            }
            token[j] = '\0';
            push_num(&numbers, atof(token));
        } else if (is_operator(expression[i])) {
            while (!is_empty_op(&operators) &&
                   precedence(peek_op(&operators)) >= precedence(expression[i])) {
                apply_operator(&numbers, pop_op(&operators));
            }
            push_op(&operators, expression[i]);
            i++;
        } else if (expression[i] == '(') {
            push_op(&operators, expression[i]);
            i++;
        } else if (expression[i] == ')') {
            while (!is_empty_op(&operators) && peek_op(&operators) != '(') {
                apply_operator(&numbers, pop_op(&operators));
            }
            if (!is_empty_op(&operators) && peek_op(&operators) == '(') {
                pop_op(&operators);
            }
            i++;
        } else {
            fprintf(stderr, "Invalid character %c\n", expression[i]);
            exit(EXIT_FAILURE);
        }
    }

    while (!is_empty_op(&operators)) {
        apply_operator(&numbers, pop_op(&operators));
    }

    return pop_num(&numbers);
}

int main() {
    char expression[MAX_EXPR_SIZE];

    printf("Enter an expression: ");
    fgets(expression, MAX_EXPR_SIZE, stdin);

    double result = evaluate_expression(expression);
    printf("Result: %lf\n", result);

    return 0;
}

#include <stdio.h>
