#define MAX_EXPR_LENGTH 256
#define MAX_STACK_SIZE 256

typedef struct {
    double data[MAX_STACK_SIZE];
    int top;
} Stack;

void init_stack(Stack* stack) {
    stack->top = -1;
}

int is_empty(Stack* stack) {
    return stack->top == -1;
}

void push(Stack* stack, double value) {
    if (stack->top < MAX_STACK_SIZE - 1) {
        stack->data[++stack->top] = value;
    }
}

double pop(Stack* stack) {
    if (!is_empty(stack)) {
        return stack->data[stack->top--];
    }
    return 0; // or handle underflow error
}

double peek(Stack* stack) {
    if (!is_empty(stack)) {
        return stack->data[stack->top];
    }
    return 0; // or handle empty stack error
}

int precedence(char op) {
    switch (op) {
        case '+':
        case '-':
            return 1;
        case '*':
        case '/':
            return 2;
        case '^':
            return 3;
    }
    return 0;
}

int is_operator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/' || c == '^';
}

double apply_operator(double a, double b, char op) {
    switch (op) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/': if (b != 0) return a / b; else {
            printf("Error: Division by zero!\n");
            exit(1);
        }
        case '^': return pow(a, b);
        default: return 0;
    }
}

void evaluate_expression(const char* expr) {
    Stack values;
    Stack ops;
    init_stack(&values);
    init_stack(&ops);

    for (int i = 0; i < strlen(expr); i++) {
        if (isspace(expr[i])) continue;

        if (isdigit(expr[i])) {
            double val = 0;
            while (i < strlen(expr) && (isdigit(expr[i]) || expr[i] == '.')) {
                if (expr[i] == '.') {
                    double decimal_place = 0.1;
                    i++;
                    while (i < strlen(expr) && isdigit(expr[i])) {
                        val += (expr[i] - '0') * decimal_place;
                        decimal_place /= 10;
                        i++;
                    }
                } else {
                    val = (val * 10) + (expr[i] - '0');
                    i++;
                }
            }
            push(&values, val);
            i--; // Adjust for the extra increment in the loop
        } else if (expr[i] == '(') {
            push(&ops, expr[i]);
        } else if (expr[i] == ')') {
            while (!is_empty(&ops) && peek(&ops) != '(') {
                double val2 = pop(&values);
                double val1 = pop(&values);
                char op = pop(&ops);
                push(&values, apply_operator(val1, val2, op));
            }
            pop(&ops); // pop the '('
        } else if (is_operator(expr[i])) {
            while (!is_empty(&ops) && precedence(peek(&ops)) >= precedence(expr[i])) {
                double val2 = pop(&values);
                double val1 = pop(&values);
                char op = pop(&ops);
                push(&values, apply_operator(val1, val2, op));
            }
            push(&ops, expr[i]);
        }
    }

    while (!is_empty(&ops)) {
        double val2 = pop(&values);
        double val1 = pop(&values);
        char op = pop(&ops);
        push(&values, apply_operator(val1, val2, op));
    }

    printf("Result: %.2f\n", pop(&values));
}

