// Function to apply an operator
double applyOperator(double num1, double num2, char operator) {
    switch (operator) {
        case '+':
            return num1 + num2;
        case '-':
            return num1 - num2;
        case '*':
            return num1 * num2;
        case '/':
            if (num2 != 0)
                return num1 / num2;
            else {
                printf("Error: Division by zero\n");
                exit(1);
            }
        default:
            printf("Error: Invalid operator\n");
            exit(1);
    }
}

// Function to get precedence of an operator
int getPrecedence(char operator) {
    if (operator == '+' || operator == '-')
        return 1;
    else if (operator == '*' || operator == '/')
        return 2;
    return 0;
}

// Function to evaluate an expression
double evaluateExpression(char *expression) {
    int numStack[100], operatorStack[100], numTop = -1, operatorTop = -1;
    int i = 0, num = 0;
    double num1, num2, result;

    while (expression[i] != '\0') {
        if (isdigit(expression[i]) || expression[i] == '.') {
            num = num * 10 + (expression[i] - '0');
            i++;
            if (expression[i] == '.') {
                int decimalPlaces = 0;
                i++;
                while (isdigit(expression[i])) {
                    num = num * 10 + (expression[i] - '0');
                    decimalPlaces++;
                    i++;
                }
                for (int j = 0; j < decimalPlaces; j++)
                    num /= 10;
            }
        } else if (expression[i] == '(') {
            operatorStack[++operatorTop] = '(';
            i++;
        } else if (expression[i] == ')') {
            while (operatorStack[operatorTop] != '(') {
                num2 = (double)numStack[numTop--];
                num1 = (double)numStack[numTop--];
                char op = operatorStack[operatorTop--];
                numStack[++numTop] = applyOperator(num1, num2, op);
            }
            operatorTop--;
            i++;
        } else {
            while (operatorTop != -1 && operatorStack[operatorTop] != '(' && getPrecedence(expression[i]) <= getPrecedence(operatorStack[operatorTop])) {
                num2 = (double)numStack[numTop--];
                num1 = (double)numStack[numTop--];
                char op = operatorStack[operatorTop--];
                numStack[++numTop] = applyOperator(num1, num2, op);
            }
            operatorStack[++operatorTop] = expression[i];
            numStack[++numTop] = num;
            num = 0;
            i++;
        }
    }

    while (operatorTop != -1) {
        num2 = (double)numStack[numTop--];
        num1 = (double)numStack[numTop--];
        char op = operatorStack[operatorTop--];
        numStack[++numTop] = applyOperator(num1, num2, op);
    }

    return numStack[numTop];
}

