#define MAX_EXPRESSION_LENGTH 1024

// Function to perform arithmetic operations
double performOperation(double a, double b, char op) {
    switch (op) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/':
            if (b == 0) {
                fprintf(stderr, "Error: Division by zero\n");
                exit(EXIT_FAILURE);
            }
            return a / b;
        default:
            fprintf(stderr, "Error: Invalid operator %c\n", op);
            exit(EXIT_FAILURE);
    }
}

// Function to check if a character is an operator
int isOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/';
}

// Function to get the precedence of an operator
int precedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

// Function to evaluate the expression using two stacks
double evaluateExpression(const char *expression) {
    char operators[MAX_EXPRESSION_LENGTH];
    double values[MAX_EXPRESSION_LENGTH];
    int otop = -1, vtop = -1;

    for (int i = 0; i < strlen(expression); i++) {
        // Skip spaces
        if (expression[i] == ' ') continue;

        // Handle numbers
        if (isdigit(expression[i]) || expression[i] == '.') {
            double num = 0.0;
            for (; i < strlen(expression) && (isdigit(expression[i]) || expression[i] == '.'); i++) {
                if (expression[i] == '.') {
                    double decimal = 0.1;
                    i++;
                    for (; i < strlen(expression) && isdigit(expression[i]); i++) {
                        num += (expression[i] - '0') * decimal;
                        decimal *= 0.1;
                    }
                    break;
                } else {
                    num = num * 10.0 + (expression[i] - '0');
                }
            }
            values[++vtop] = num;
            i--;
        }

        // Handle operators
        else if (isOperator(expression[i])) {
            while (otop != -1 && precedence(operators[otop]) >= precedence(expression[i])) {
                double val2 = values[vtop--];
                double val1 = values[vtop--];
                char op = operators[otop--];
                values[++vtop] = performOperation(val1, val2, op);
            }
            operators[++otop] = expression[i];
        }

        // Handle parentheses
        else if (expression[i] == '(') {
            operators[++otop] = expression[i];
        }

        else if (expression[i] == ')') {
            while (otop != -1 && operators[otop] != '(') {
                double val2 = values[vtop--];
                double val1 = values[vtop--];
                char op = operators[otop--];
                values[++vtop] = performOperation(val1, val2, op);
            }
            if (otop != -1) otop--; // Pop the '('
        }

        // Handle invalid characters
        else {
            fprintf(stderr, "Error: Invalid character %c in expression\n", expression[i]);
            exit(EXIT_FAILURE);
        }
    }

    // Perform remaining operations
    while (otop != -1) {
        double val2 = values[vtop--];
        double val1 = values[vtop--];
        char op = operators[otop--];
        values[++vtop] = performOperation(val1, val2, op);
    }

    return values[vtop];
}

