// Structure to represent BMP file header
typedef struct {
    unsigned short signature;      // File signature
    unsigned int fileSize;         // File size
    unsigned short reserved1;      // Reserved field
    unsigned short reserved2;      // Reserved field
    unsigned int dataOffset;       // Offset to image data
} BMPHeader;

// Structure to represent BMP info header
typedef struct {
    unsigned int headerSize;       // Size of info header
    int width;                     // Image width
    int height;                    // Image height
    unsigned short planes;         // Number of color planes
    unsigned short bitsPerPixel;   // Bits per pixel
} BMPInfoHeader;

// Function to encode a message into an image
int encodeMessage(const char* imagePath, const char* message) {
    FILE* inputFile = fopen(imagePath, "rb");
    if (inputFile == NULL) {
        printf("Error: Unable to open input image file.\n");
        return 0;
    }

    // Read BMP headers
    BMPHeader header;
    BMPInfoHeader infoHeader;
    fread(&header.signature, sizeof(unsigned short), 1, inputFile);
    fread(&header.fileSize, sizeof(unsigned int), 1, inputFile);
    fread(&header.reserved1, sizeof(unsigned short), 1, inputFile);
    fread(&header.reserved2, sizeof(unsigned short), 1, inputFile);
    fread(&header.dataOffset, sizeof(unsigned int), 1, inputFile);

    fread(&infoHeader.headerSize, sizeof(unsigned int), 1, inputFile);
    fread(&infoHeader.width, sizeof(int), 1, inputFile);
    fread(&infoHeader.height, sizeof(int), 1, inputFile);
    fread(&infoHeader.planes, sizeof(unsigned short), 1, inputFile);
    fread(&infoHeader.bitsPerPixel, sizeof(unsigned short), 1, inputFile);

    // Check if image is suitable for steganography
    if (infoHeader.bitsPerPixel != 24) {
        printf("Error: Only 24-bit BMP images are supported.\n");
        fclose(inputFile);
        return 0;
    }

    // Create output file
    FILE* outputFile = fopen("stego_image.bmp", "wb");
    if (outputFile == NULL) {
        printf("Error: Unable to create output image file.\n");
        fclose(inputFile);
        return 0;
    }

    // Copy headers to output file
    rewind(inputFile);
    unsigned char headerBuffer[54];
    fread(headerBuffer, 1, 54, inputFile);
    fwrite(headerBuffer, 1, 54, outputFile);

    // Calculate padding
    int padding = (4 - (infoHeader.width * 3) % 4) % 4;

    // Message encoding variables
    int messageLength = strlen(message);
    int messageBitIndex = 0;
    unsigned char currentByte = 0;
    int bitCount = 0;

    // Encode message length first
    for (int i = 0; i < 32; i++) {
        unsigned char pixel;
        fread(&pixel, 1, 1, inputFile);
        pixel = (pixel & 0xFE) | ((messageLength >> (31 - i)) & 1);
        fwrite(&pixel, 1, 1, outputFile);
    }

    // Encode message
    for (int y = 0; y < infoHeader.height; y++) {
        for (int x = 0; x < infoHeader.width; x++) {
            unsigned char blue, green, red;

            // Read pixel
            fread(&blue, 1, 1, inputFile);
            fread(&green, 1, 1, inputFile);
            fread(&red, 1, 1, inputFile);

            // Encode message bits
            if (messageBitIndex < messageLength * 8) {
                // Extract current message bit
                if (bitCount == 0) {
                    currentByte = message[messageBitIndex / 8];
                    bitCount = 8;
                }

                // Modify least significant bits
                blue = (blue & 0xFE) | ((currentByte >> 7) & 1);
                green = (green & 0xFE) | ((currentByte >> 6) & 1);
                red = (red & 0xFE) | ((currentByte >> 5) & 1);

                currentByte <<= 3;
                bitCount -= 3;
                messageBitIndex += 3;
            }

            // Write modified pixel
            fwrite(&blue, 1, 1, outputFile);
            fwrite(&green, 1, 1, outputFile);
            fwrite(&red, 1, 1, outputFile);
        }

        // Handle padding
        for (int p = 0; p < padding; p++) {
            unsigned char paddingByte;
            fread(&paddingByte, 1, 1, inputFile);
            fwrite(&paddingByte, 1, 1, outputFile);
        }
    }

    fclose(inputFile);
    fclose(outputFile);

    printf("Message encoded successfully in stego_image.bmp\n");
    return 1;
}

// Function to decode a message from an image
int decodeMessage(const char* imagePath) {
    FILE* inputFile = fopen(imagePath, "rb");
    if (inputFile == NULL) {
        printf("Error: Unable to open input image file.\n");
        return 0;
    }

    // Read and skip headers
    unsigned char headerBuffer[54];
    fread(headerBuffer, 1, 54, inputFile);

    // Read message length
    int messageLength = 0;
    for (int i = 0; i < 32; i++) {
        unsigned char pixel;
        fread(&pixel, 1, 1, inputFile);
        messageLength = (messageLength << 1) | (pixel & 1);
    }

    // Allocate message buffer
    char* message = malloc(messageLength + 1);
    memset(message, 0, messageLength + 1);

    // Decode message
    unsigned char currentByte = 0;
    int bitCount = 0;
    int messageBitIndex = 0;

    for (int y = 0; y < messageLength; y++) {
        unsigned char blue, green, red;

        // Read pixel
        fread(&blue, 1, 1, inputFile);
        fread(&green, 1, 1, inputFile);
        fread(&red, 1, 1, inputFile);

        // Extract least significant bits
        currentByte = (currentByte << 1) | (blue & 1);
        currentByte = (currentByte << 1) | (green & 1);
        currentByte = (currentByte << 1) | (red & 1);

        bitCount += 3;

        // Store complete byte
        if (bitCount >= 8) {
            message[messageBitIndex++] = currentByte;
            currentByte = 0;
            bitCount = 0;
        }
    }

    printf("Decoded message: %s\n", message);

    free(message);
    fclose(inputFile);
    return 1;
}

