    // Example usage
    const char* inputImage = "input.bmp";
    const char* secretMessage = "Hello, this is a secret message!";

    // Encode message
    if (!encodeMessage(inputImage, secretMessage)) {
        printf("Message encoding failed.\n");
        return 1;
    }

    // Decode message
    if (!decodeMessage("stego_image.bmp")) {
        printf("Message decoding failed.\n");
        return 1;
    }

    return 0;
}

