// Function to hide a message in the image
void hideMessage(unsigned char *image, const char *message) {
    int i, j;
    int messageLength = strlen(message);

    for (i = 0; i < messageLength; i++) {
        char currentChar = message[i];
        for (j = 0; j < 8; j++) {
            // Get the j-th bit of the current character
            int bit = (currentChar >> j) & 1;
            // Modify the LSB of the pixel
            image[i * 8 + j] = (image[i * 8 + j] & 0xFE) | bit;
        }
    }
}

// Function to extract the hidden message from the image
void extractMessage(const unsigned char *image, char *message, int messageLength) {
    int i, j;

    for (i = 0; i < messageLength; i++) {
        char currentChar = 0;
        for (j = 0; j < 8; j++) {
            // Extract the LSB of the pixel
            int bit = image[i * 8 + j] & 1;
            // Reconstruct the character
            currentChar |= (bit << j);
        }
        message[i] = currentChar;
    }
    message[messageLength] = '\0';  // Null-terminate the string
}

