        image[i] = i % 256;  // Simple pattern for demonstration
    }

    // Hide the message in the image
    hideMessage(image, message);
    printf("Message hidden in the image.\n");

    // Extract the message from the image
    extractMessage(image, extractedMessage, strlen(message));
    printf("Extracted message: %s\n", extractedMessage);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// --- BMP Structures ---

// BMP File Header (14 bytes)
#pragma pack(push, 1) // Ensures no padding between struct members
typedef struct {
    unsigned short bfType;      // Specifies the file type (0x4D42 for "BM")
    unsigned int bfSize;        // Specifies the size of the file in bytes
    unsigned short bfReserved1; // Reserved; must be 0
    unsigned short bfReserved2; // Reserved; must be 0
    unsigned int bfOffBits;     // Specifies the offset in bytes from the BMP file header to the pixel array
} BMPFileHeader;
#pragma pack(pop)

// BMP Info Header (40 bytes)
#pragma pack(push, 1)
typedef struct {
    unsigned int biSize;         // Specifies the size of the BITMAPINFOHEADER structure (40 bytes)
    int biWidth;                 // Specifies the width of the bitmap, in pixels
    int biHeight;                // Specifies the height of the bitmap, in pixels
    unsigned short biPlanes;     // Specifies the number of planes for the target device (must be 1)
    unsigned short biBitCount;   // Specifies the number of bits per pixel (e.g., 24 for 24-bit BMP)
    unsigned int biCompression;  // Specifies the type of compression (0 for BI_RGB - no compression)
    unsigned int biSizeImage;    // Specifies the size of the image, in bytes. Can be set to 0 for uncompressed RGB bitmaps
    int biXPelsPerMeter;         // Specifies the horizontal resolution, in pixels per meter
    int biYPelsPerMeter;         // Specifies the vertical resolution, in pixels per meter
    unsigned int biClrUsed;      // Specifies the number of color indexes in the color table that are actually used by the bitmap
    unsigned int biClrImportant; // Specifies the number of color indexes that are required for displaying the bitmap
} BMPInfoHeader;
#pragma pack(pop)

// Pixel structure (for 24-bit BMP, BGR order)
typedef struct {
    unsigned char blue;
    unsigned char green;
    unsigned char red;
} Pixel;

// --- Helper Functions ---

// Reads a BMP file
Pixel* readBMP(const char* filename, BMPFileHeader* fileHeader, BMPInfoHeader* infoHeader) {
    FILE* fp = fopen(filename, "rb");
    if (!fp) {
        perror("Error opening BMP file");
        return NULL;
    }

    fread(fileHeader, sizeof(BMPFileHeader), 1, fp);
    fread(infoHeader, sizeof(BMPInfoHeader), 1, fp);

    // Basic validation for 24-bit or 32-bit uncompressed BMP
    if (fileHeader->bfType != 0x4D42 || infoHeader->biCompression != 0 ||
        (infoHeader->biBitCount != 24 && infoHeader->biBitCount != 32)) {
        fprintf(stderr, "Error: Only 24-bit or 32-bit uncompressed BMP files are supported.\n");
        fclose(fp);
        return NULL;
    }

    // Calculate row padding for 24-bit BMP (each row must be a multiple of 4 bytes)
    // 32-bit BMPs naturally align to a 4-byte boundary, so padding is 0.
    int row_padding = (4 - (infoHeader->biWidth * infoHeader->biBitCount / 8) % 4) % 4;

    Pixel* pixels = (Pixel*)malloc(infoHeader->biWidth * abs(infoHeader->biHeight) * sizeof(Pixel));
    if (!pixels) {
        perror("Error allocating memory for pixels");
        fclose(fp);
        return NULL;
    }

    fseek(fp, fileHeader->bfOffBits, SEEK_SET);

    for (int i = 0; i < abs(infoHeader->biHeight); i++) {
        for (int j = 0; j < infoHeader->biWidth; j++) {
            if (infoHeader->biBitCount == 24) {
                 // Read 3 bytes for BGR
                fread(&pixels[i * infoHeader->biWidth + j], sizeof(Pixel), 1, fp);
            } else if (infoHeader->biBitCount == 32) {
                // For 32-bit, read BGR and skip the alpha byte
                fread(&pixels[i * infoHeader->biWidth + j].blue, 1, 1, fp);
                fread(&pixels[i * infoHeader->biWidth + j].green, 1, 1, fp);
                fread(&pixels[i * infoHeader->biWidth + j].red, 1, 1, fp);
                fseek(fp, 1, SEEK_CUR); // Skip alpha byte
            }
        }
        fseek(fp, row_padding, SEEK_CUR); // Apply padding
    }

    fclose(fp);
    return pixels;
}

// Writes a BMP file
int writeBMP(const char* filename, const BMPFileHeader* fileHeader, const BMPInfoHeader* infoHeader, const Pixel* pixels) {
    FILE* fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error creating output BMP file");
        return 0;
    }

    fwrite(fileHeader, sizeof(BMPFileHeader), 1, fp);
    fwrite(infoHeader, sizeof(BMPInfoHeader), 1, fp);

    // Calculate row padding
    int row_padding = (4 - (infoHeader->biWidth * infoHeader->biBitCount / 8) % 4) % 4;
    unsigned char padding_byte = 0x00; // Padding bytes are usually 0

    fseek(fp, fileHeader->bfOffBits, SEEK_SET); // Seek to pixel data start

    for (int i = 0; i < abs(infoHeader->biHeight); i++) {
        for (int j = 0; j < infoHeader->biWidth; j++) {
            if (infoHeader->biBitCount == 24) {
                fwrite(&pixels[i * infoHeader->biWidth + j], sizeof(Pixel), 1, fp);
            } else if (infoHeader->biBitCount == 32) {
                // For 32-bit, write BGR and add a dummy alpha byte (e.g., 0xFF)
                fwrite(&pixels[i * infoHeader->biWidth + j].blue, 1, 1, fp);
                fwrite(&pixels[i * infoHeader->biWidth + j].green, 1, 1, fp);
                fwrite(&pixels[i * infoHeader->biWidth + j].red, 1, 1, fp);
                unsigned char alpha_byte = 0xFF; // Non-transparent
                fwrite(&alpha_byte, 1, 1, fp);
            }
        }
        // Write padding bytes
        for (int k = 0; k < row_padding; k++) {
            fwrite(&padding_byte, 1, 1, fp);
        }
    }

    fclose(fp);
    return 1;
}

// --- Steganography Functions ---

// Hides a message in the image
int hideMessage(Pixel* pixels, int width, int height, const char* message) {
    long total_pixels = (long)width * abs(height);
    long total_bits_available = total_pixels * 3; // Each pixel has R, G, B channels, each can hold 1 bit

    // Add 1 to message length for null terminator, then multiply by 8 for bits
    long message_bits = (strlen(message) + 1) * 8;
    // We need to store the message length itself. Let's use 4 bytes (32 bits) for length.
    long length_storage_bits = sizeof(int) * 8; // For storing the message length (e.g., 32 bits)

    if ((message_bits + length_storage_bits) > total_bits_available) {
        fprintf(stderr, "Error: Message is too long for the image size.\n");
        return 0;
    }

    unsigned int current_bit_index = 0;
    unsigned char current_byte_of_message;
    int message_len = strlen(message);

    // 1. Embed message length
    // We'll hide (message_len + 1) to account for the null terminator.
    // This allows us to read exactly the number of bytes needed for the string + null.
    unsigned int len_to_hide = message_len + 1; // Include null terminator

    for (int i = 0; i < length_storage_bits; i++) {
        unsigned char bit_to_hide = (len_to_hide >> (length_storage_bits - 1 - i)) & 0x01; // Get bit from length

        int pixel_idx = current_bit_index / 3;
        int color_channel = current_bit_index % 3;

        if (pixel_idx >= total_pixels) {
            fprintf(stderr, "Error: Not enough space to embed length.\n");
            return 0;
        }

        switch (color_channel) {
            case 0: // Blue channel
                pixels[pixel_idx].blue = (pixels[pixel_idx].blue & 0xFE) | bit_to_hide;
                break;
            case 1: // Green channel
                pixels[pixel_idx].green = (pixels[pixel_idx].green & 0xFE) | bit_to_hide;
                break;
            case 2: // Red channel
                pixels[pixel_idx].red = (pixels[pixel_idx].red & 0xFE) | bit_to_hide;
                break;
        }
        current_bit_index++;
    }

    // 2. Embed the message itself (including null terminator)
    for (int i = 0; i <= message_len; i++) { // Loop <= to include null terminator
        current_byte_of_message = (i == message_len) ? '\0' : message[i]; // Get current char or null

        for (int bit = 0; bit < 8; bit++) {
            unsigned char bit_to_hide = (current_byte_of_message >> (7 - bit)) & 0x01; // Get bit (MSB first)

            int pixel_idx = current_bit_index / 3;
            int color_channel = current_bit_index % 3;

            if (pixel_idx >= total_pixels) {
                 fprintf(stderr, "Error: Not enough pixel data available to store message after length.\n");
                 return 0;
            }

            switch (color_channel) {
                case 0: // Blue channel
                    pixels[pixel_idx].blue = (pixels[pixel_idx].blue & 0xFE) | bit_to_hide;
                    break;
                case 1: // Green channel
                    pixels[pixel_idx].green = (pixels[pixel_idx].green & 0xFE) | bit_to_hide;
                    break;
                case 2: // Red channel
                    pixels[pixel_idx].red = (pixels[pixel_idx].red & 0xFE) | bit_to_hide;
                    break;
            }
            current_bit_index++;
        }
    }

    printf("Message successfully hidden.\n");
    return 1;
}

// Reveals a message from the image
char* revealMessage(const Pixel* pixels, int width, int height) {
    long total_pixels = (long)width * abs(height);

    unsigned int current_bit_index = 0;

    // 1. Extract message length
    unsigned int revealed_len = 0;
    long length_storage_bits = sizeof(int) * 8;

    for (int i = 0; i < length_storage_bits; i++) {
        int pixel_idx = current_bit_index / 3;
        int color_channel = current_bit_index % 3;

        if (pixel_idx >= total_pixels) {
            fprintf(stderr, "Error: Image too small or corrupt len. Could not read full message length.\n");
            return NULL;
        }

        unsigned char bit;
        switch (color_channel) {
            case 0: // Blue channel
                bit = pixels[pixel_idx].blue & 0x01;
                break;
            case 1: // Green channel
                bit = pixels[pixel_idx].green & 0x01;
                break;
            case 2: // Red channel
                bit = pixels[pixel_idx].red & 0x01;
                break;
            default: // Should not happen
                bit = 0;
        }
        revealed_len = (revealed_len << 1) | bit; // Shift left and add new bit
        current_bit_index++;
    }

    if (revealed_len == 0 || revealed_len > (total_pixels * 3 / 8)) {
        fprintf(stderr, "Error: Corrupt message length detected (%u). Image possibly not containing a message or too large.\n", revealed_len);
        return NULL;
    }

    char* message = (char*)malloc(revealed_len * sizeof(char));
    if (!message) {
        perror("Error allocating memory for revealed message");
        return NULL;
    }

    // 2. Extract the message itself
    for (int i = 0; i < revealed_len; i++) {
        unsigned char current_char = 0;
        for (int bit = 0; bit < 8; bit++) {
            int pixel_idx = current_bit_index / 3;
            int color_channel = current_bit_index % 3;

            if (pixel_idx >= total_pixels) {
                fprintf(stderr, "Error: Ran out of pixel data while extracting message.\n");
                free(message);
                return NULL;
            }

            unsigned char bit_extracted;
            switch (color_channel) {
                case 0: // Blue channel
                    bit_extracted = pixels[pixel_idx].blue & 0x01;
                    break;
                case 1: // Green channel
                    bit_extracted = pixels[pixel_idx].green & 0x01;
                    break;
                case 2: // Red channel
                    bit_extracted = pixels[pixel_idx].red & 0x01;
                    break;
                default:
                    bit_extracted = 0;
            }
            current_char = (current_char << 1) | bit_extracted; // Shift left and add new bit
            current_bit_index++;
        }
        message[i] = current_char;
        if (current_char == '\0') { // Check for null terminator
            // If the null terminator is found before 'revealed_len', it's okay (sometimes padding).
            // But we allocated based on revealed_len, so we fill all of it.
            break;
        }
    }
    message[revealed_len - 1] = '\0'; // Ensure null termination (might overwrite last char if not null)

    printf("Message successfully revealed.\n");
    return message;
}

// --- Main Program ---
int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage:\n");
        fprintf(stderr, "  %s -hide <input_bmp> <output_bmp> <message_string>\n", argv[0]);
        fprintf(stderr, "  %s -reveal <input_bmp>\n", argv[0]);
        return 1;
    }

    BMPFileHeader fileHeader;
    BMPInfoHeader infoHeader;
    Pixel* pixels = NULL;

    if (strcmp(argv[1], "-hide") == 0) {
        if (argc != 5) {
            fprintf(stderr, "Usage: %s -hide <input_bmp> <output_bmp> <message_string>\n", argv[0]);
            return 1;
        }
        const char* input_bmp = argv[2];
        const char* output_bmp = argv[3];
        const char* message = argv[4];

        pixels = readBMP(input_bmp, &fileHeader, &infoHeader);
        if (!pixels) {
            return 1;
        }

        if (hideMessage(pixels, infoHeader.biWidth, infoHeader.biHeight, message)) {
            writeBMP(output_bmp, &fileHeader, &infoHeader, pixels);
            printf("Hidden message in '%s' and saved to '%s'.\n", input_bmp, output_bmp);
        } else {
            fprintf(stderr, "Failed to hide message.\n");
        }

    } else if (strcmp(argv[1], "-reveal") == 0) {
        if (argc != 3) {
            fprintf(stderr, "Usage: %s -reveal <input_bmp>\n", argv[0]);
            return 1;
        }
        const char* input_bmp = argv[2];

        pixels = readBMP(input_bmp, &fileHeader, &infoHeader);
        if (!pixels) {
            return 1;
        }

        char* revealed_message = revealMessage(pixels, infoHeader.biWidth, infoHeader.biHeight);
        if (revealed_message) {
            printf("Revealed message: \"%s\"\n", revealed_message);
            free(revealed_message);
        } else {
            fprintf(stderr, "Failed to reveal message.\n");
        }

    } else {
        fprintf(stderr, "Invalid option. Use -hide or -reveal.\n");
        return 1;
    }

    if (pixels) {
        free(pixels);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#pragma pack(push,1)
typedef struct {
    uint16_t type;
    uint32_t size;
    uint16_t reserved1, reserved2;
    uint32_t offset;
} BMPHeader;

typedef struct {
    uint32_t size;
    int32_t  width, height;
    uint16_t planes;
    uint16_t bitcount;
    uint32_t compression;
    uint32_t imagesize;
    int32_t  xres, yres;
    uint32_t clrused, clrimportant;
} DIBHeader;
#pragma pack(pop)

void encode(const char *infile, const char *outfile, const char *message) {
    FILE *fin = fopen(infile, "rb");
    if (!fin) { perror("Input image"); exit(1); }
    FILE *fout = fopen(outfile, "wb");
    if (!fout) { perror("Output image"); exit(1); }

    BMPHeader bh;
    DIBHeader dh;
    fread(&bh, sizeof(bh), 1, fin);
    fread(&dh, sizeof(dh), 1, fin);

    if (bh.type != 0x4D42 || dh.bitcount != 24) {
        printf("Only 24-bit BMP files are supported.\n");
        exit(1);
    }

    // Copy headers to output file, then start reading pixel data
    fwrite(&bh, sizeof(bh), 1, fout);
    fwrite(&dh, sizeof(dh), 1, fout);

    // Set file pointer to pixel array
    fseek(fin, bh.offset, SEEK_SET);
    fseek(fout, bh.offset, SEEK_SET);

    // Calculate how much space we have
    unsigned int width = dh.width;
    unsigned int height = dh.height < 0 ? -dh.height : dh.height;
    unsigned int row_padded = (width*3 + 3) & (~3);
    unsigned int data_capacity = width*height*3/8; // in bytes

    size_t message_len = strlen(message) + 1; // Include NULL terminator

    if (message_len > data_capacity) {
        printf("Message too long to encode in this image (%zu > %d bytes)\n", message_len, data_capacity);
        exit(1);
    }

    // Start encoding
    int ch, msg_idx = 0, bit_idx = 0;
    uint8_t byte_to_hide = message[msg_idx];
    for (unsigned int row = 0; row < height; row++) {
        for (unsigned int col = 0; col < row_padded; col++) {
            ch = fgetc(fin);
            if (col < width * 3 && msg_idx < message_len) {
                // Hide bit in LSB
                ch = (ch & ~1) | ((byte_to_hide >> bit_idx) & 1);
                bit_idx++;
                if (bit_idx == 8) {
                    bit_idx = 0;
                    msg_idx++;
                    byte_to_hide = message[msg_idx];
                }
            }
            fputc(ch, fout);
        }
    }
    // Copy rest if any
    while ((ch = fgetc(fin)) != EOF)
        fputc(ch, fout);

    fclose(fin);
    fclose(fout);
    printf("Encoding done.\n");
}

void decode(const char *infile) {
    FILE *fin = fopen(infile, "rb");
    if (!fin) { perror("Input image"); exit(1); }
    BMPHeader bh;
    DIBHeader dh;
    fread(&bh, sizeof(bh), 1, fin);
    fread(&dh, sizeof(dh), 1, fin);

    if (bh.type != 0x4D42 || dh.bitcount != 24) {
        printf("Only 24-bit BMP files are supported.\n");
        exit(1);
    }

    fseek(fin, bh.offset, SEEK_SET);

    unsigned int width = dh.width;
    unsigned int height = dh.height < 0 ? -dh.height : dh.height;
    unsigned int row_padded = (width*3 + 3) & (~3);

    char message[10000], ch = 0;
    int bit_idx = 0, msg_idx = 0, pixval;
    for (unsigned int row = 0; row < height; row++) {
        for (unsigned int col = 0; col < row_padded; col++) {
            pixval = fgetc(fin);
            if (col < width * 3) {
                ch |= (pixval & 1) << bit_idx;
                bit_idx++;
                if (bit_idx == 8) {
                    message[msg_idx] = ch;
                    if (ch == '\0') goto done;
                    msg_idx++;
                    ch = 0;
                    bit_idx = 0;
                }
            }
        }
    }
done:
    message[msg_idx] = '\0';
    fclose(fin);
    printf("Decoded message: %s\n", message);
}

void usage(const char *prog) {
    printf("Usage:\n");
    printf("Encode: %s encode <input.bmp> <output.bmp> <message>\n", prog);
    printf("Decode: %s decode <input.bmp>\n", prog);
}

int main(int argc, char **argv) {
    if (argc < 3) {
        usage(argv[0]);
        return 1;
    }
    if (strcmp(argv[1], "encode") == 0) {
        if (argc != 5) { usage(argv[0]); return 1; }
        encode(argv[2], argv[3], argv[4]);
    } else if (strcmp(argv[1], "decode") == 0) {
        if (argc != 3) { usage(argv[0]); return 1; }
        decode(argv[2]);
    } else {
        usage(argv[0]);
        return 1;
    }
    return 0;
}

