void hideMessageInImage(const char *inputImagePath, const char *outputImagePath, const char *message) {
    FILE *inputFile = fopen(inputImagePath, "rb");
    if (!inputFile) {
        perror("Error opening input file");
        exit(1);
    }

    FILE *outputFile = fopen(outputImagePath, "wb");
    if (!outputFile) {
        perror("Error opening output file");
        fclose(inputFile);
        exit(1);
    }

    // Copy BMP header from input to output
    unsigned char bmpHeader[54];
    fread(bmpHeader, sizeof(unsigned char), 54, inputFile);
    fwrite(bmpHeader, sizeof(unsigned char), 54, outputFile);

    // Calculate image size
    int width = *(int *)&bmpHeader[18];
    int height = *(int *)&bmpHeader[22];
    int imageSize = 3 * width * height;

    // Read pixel data
    unsigned char *data = (unsigned char *)malloc(imageSize * sizeof(unsigned char));
    fread(data, sizeof(unsigned char), imageSize, inputFile);

    // Hide message in image
    int messageLength = strlen(message);
    int bitIndex = 0;// Bit index for the entire message
    for (int i = 0; i < imageSize && bitIndex < messageLength * 8; i++) {
        // Clear the least significant bit
        data[i] &= 0xFE;

        // Set the least significant bit to the message bit
        data[i] |= (message[bitIndex / 8] >> (bitIndex % 8)) & 1;
        bitIndex++;
    }

    // Copy modified data to output file
    fwrite(data, sizeof(unsigned char), imageSize, outputFile);

    // Free dynamically allocated memory
    free(data);

    // Close files
    fclose(inputFile);
    fclose(outputFile);
}

#include <stdio.h>
