#pragma pack(push, 1)
typedef struct {
    unsigned short bfType;      // BMP file type
    unsigned int bfSize;        // Size of the BMP file in bytes
    unsigned short bfReserved1; // Reserved; must be 0
    unsigned short bfReserved2; // Reserved; must be 0
    unsigned int bfOffBits;     // Offset to start of pixel data
} BMPFileHeader;

typedef struct {
    unsigned int biSize;          // Size of this header (in bytes)
    int biWidth;                  // Width of the bitmap in pixels
    int biHeight;                 // Height of the bitmap in pixels
    unsigned short biPlanes;      // Number of color planes (must be 1)
    unsigned short biBitCount;    // Number of bits per pixel
    unsigned int biCompression;    // Compression type
    unsigned int biSizeImage;     // Size of image data in bytes
    int biXPelsPerMeter;          // Horizontal resolution
    int biYPelsPerMeter;          // Vertical resolution
    unsigned int biClrUsed;        // Number of colors in the color palette
    unsigned int biClrImportant;   // Important colors
} BMPInfoHeader;
#pragma pack(pop)

void hideMessage(const char *inputFile, const char *outputFile, const char *message) {
    FILE *input = fopen(inputFile, "rb");
    if (!input) {
        perror("Error opening input file");
        return;
    }

    BMPFileHeader fileHeader;
    BMPInfoHeader infoHeader;

    fread(&fileHeader, sizeof(BMPFileHeader), 1, input);
    fread(&infoHeader, sizeof(BMPInfoHeader), 1, input);

    // Check if the file is a valid BMP image
    if (fileHeader.bfType != 0x4D42) {
        fprintf(stderr, "Not a BMP file\n");
        fclose(input);
        return;
    }

    // Prepare to read pixel data
    int width = infoHeader.biWidth;
    int height = infoHeader.biHeight;
    int paddingSize = (4 - (width * 3) % 4) % 4;

    // Number of bytes required to hold the message
    int messageLength = strlen(message);
    int messageBitLength = messageLength * 8;

    if (messageBitLength + 1 > width * height * 3) {
        fprintf(stderr, "Message is too long to hide in the image\n");
        fclose(input);
        return;
    }

    // Append a null terminator to the message
    char *messageWithNull = malloc(messageBitLength + 1);
    strcpy(messageWithNull, message);
    messageWithNull[messageBitLength] = '\0';

    fseek(input, fileHeader.bfOffBits, SEEK_SET); // Move to pixel data
    unsigned char *pixelData = malloc(width * height * 3);
    fread(pixelData, sizeof(unsigned char), width * height * 3, input);
    fclose(input);

    // Hide the message into the pixel data
    int bitCount = 0;
    for (int i = 0; i < messageBitLength; i++) {
        int byteIndex = i / 8;
        int bitIndex = i % 8;
        unsigned char bitToHide = (messageWithNull[byteIndex] >> (7 - bitIndex)) & 1;

        // Modify the least significant bit
        pixelData[bitCount] = (pixelData[bitCount] & 0xFE) | bitToHide;
        bitCount++;

        if (bitCount >= width * height * 3) {
            break; // We should have enough space from previous checks
        }
    }

    // Save the new image with the hidden message
    FILE *output = fopen(outputFile, "wb");
    if (!output) {
        perror("Error opening output file");
        free(pixelData);
        free(messageWithNull);
        return;
    }

    fwrite(&fileHeader, sizeof(BMPFileHeader), 1, output);
    fwrite(&infoHeader, sizeof(BMPInfoHeader), 1, output);
    fwrite(pixelData, sizeof(unsigned char), width * height * 3, output);
    fclose(output);

    free(pixelData);
    free(messageWithNull);
    printf("Message hidden successfully!\n");
}

int main() {
    const char *inputFile = "input.bmp";  // Input BMP file
    const char *outputFile = "output.bmp"; // Output BMP file
    const char *message = "Hello";         // Message to hide

