#define PI 3.14159265359
#define MAX_PIXELS 10000
#define MAX_MESSAGE_LENGTH 100

// Function to convert a pixel value to a 32-bit integer
int pixelTo32(unsigned char pixel) {
    return (int)pixel;
}

// Function to convert a 32-bit integer to a pixel value
unsigned char pixel32To8(int pixel) {
    return (unsigned char)(pixel & 0xFF);
}

// Function to clear the least significant bit of a pixel value
unsigned char clearLSB(unsigned char pixel) {
    return pixel & 0xFE;
}

// Function to x-y-m modificar
void xyModificar(unsigned char *pixel, int x, int y) {
    pixel[x] = clearLSB(pixel[x]);
    pixel[y] = clearLSB(pixel[y]);
}

int main() {
    int fd1, fd2, fd3, fd4;
    unsigned char buffer[MAX_PIXELS];
    struct stat sb;
    int lsb, i, j, x, y;
    char message[MAX_MESSAGE_LENGTH];
    int message_length;
    srand(time(NULL)); // seed random number generator

    // Open the original image file for reading and create a copy for writing
    fd1 = open("imagen.bmp", O_RDONLY);
    if (fd1 < 0) {
        perror("Error opening imagen.bmp");
        return 1;
    }
    fd2 = open("imagen2.bmp", O_WRONLY | O_CREAT, 0644);
    if (fd2 < 0) {
        perror("Error creating imagen2.bmp");
        return 1;
    }

    // Read the image file into a buffer and write it to the copy file
    read(fd1, buffer, MAX_PIXELS);
    write(fd2, buffer, MAX_PIXELS);

    // Get the file status of the copy file
    fstat(fd2, &sb);

    // Get user input for the message to hide
    printf("Enter a message to hide: ");
    fgets(message, MAX_MESSAGE_LENGTH, stdin);
    message_length = strlen(message);

    // Hide the message in the image
    for (i = 0; i < message_length; i++) {
        lsb = message[i] & 0x01;
        x = rand() % MAX_PIXELS;
        y = rand() % MAX_PIXELS;
        xyModificar(buffer, x, y);
        buffer[x] |= lsb;
    }

    // Write the modified buffer to the output file
    write(fd3, buffer, MAX_PIXELS);

    // Read the output image file
    fd3 = open("imagen3.bmp", O_RDONLY);
    if (fd3 < 0) {
        perror("Error opening imagen3.bmp");
        return 1;
    }
    read(fd3, buffer, MAX_PIXELS);

    // Read the message from the image
    printf("Recovered message: ");
    for (i = 0; i < message_length; i++) {
        lsb = buffer[i] & 0x01;
        printf("%c", lsb ? '1' : '0');
    }
    printf("\n");

    // Open an additional file for reading
    fd4 = open("imagen2.bmp", O_RDONLY);
    if (fd4 < 0) {
        perror("Error opening imagen2.bmp");
        return 1;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_MESSAGE_LENGTH 1024

// Function to convert a character to its binary representation
void charToBinary(char c, char *binary) {
    for (int i = 7; i >= 0; i--) {
        binary[i] = (c & (1 << i)) ? '1' : '0';
    }
}

// Function to convert a binary string to a character
char binaryToChar(const char *binary) {
    int value = 0;
    for (int i = 0; i < 8; i++) {
        value = (value << 1) | (binary[i] - '0');
    }
    return value;
}

// Function to embed a message into the image
void embedMessageInImage(FILE *inputImage, FILE *outputImage, const char *message) {
    // Read the header of the PPM file
    char header[100];
    fscanf(inputImage, "%s", header);
    fprintf(outputImage, "%s\n", header);

    int width, height, maxColorValue;
    fscanf(inputImage, "%d %d %d", &width, &height, &maxColorValue);
    fprintf(outputImage, "%d %d %d\n", width, height, maxColorValue);

    // Skip any comments in the header
    char buffer;
    while ((buffer = getc(inputImage)) != '\n') {
        ungetc(buffer, inputImage);
        if (buffer == '#') {
            while ((buffer = getc(inputImage)) != '\n');
        } else {
            break;
        }
    }

    // Embed the message length first
    int messageLength = strlen(message);
    char messageLengthBinary[32];
    for (int i = 31; i >= 0; i--) {
        messageLengthBinary[i] = (messageLength & (1 << (31 - i))) ? '1' : '0';
    }

    // Embed the message length into the image
    int bitIndex = 0;
    for (int i = 0; i < 32; i++) {
        unsigned char pixel;
        fread(&pixel, 1, 1, inputImage);
        pixel &= 0xFE; // Clear the LSB
        pixel |= (messageLengthBinary[i] == '1' ? 1 : 0);
        fwrite(&pixel, 1, 1, outputImage);
    }

    // Embed the actual message into the image
    for (int i = 0; i < messageLength; i++) {
        char messageBinary[9];
        memset(messageBinary, '0', 8);
        charToBinary(message[i], messageBinary);

        for (int j = 0; j < 8; j++) {
            unsigned char pixel;
            fread(&pixel, 1, 1, inputImage);
            pixel &= 0xFE; // Clear the LSB
            pixel |= (messageBinary[j] == '1' ? 1 : 0);
            fwrite(&pixel, 1, 1, outputImage);
        }
    }

    // Copy the rest of the image data
    unsigned char pixel;
    while (fread(&pixel, 1, 1, inputImage) == 1) {
        fwrite(&pixel, 1, 1, outputImage);
    }
}

// Function to extract a message from the image
void extractMessageFromImage(FILE *image, char *message) {
    // Read the header of the PPM file
    char header[100];
    fscanf(image, "%s", header);

    int width, height, maxColorValue;
    fscanf(image, "%d %d %d", &width, &height, &maxColorValue);

    // Skip any comments in the header
    char buffer;
    while ((buffer = getc(image)) != '\n') {
        ungetc(buffer, image);
        if (buffer == '#') {
            while ((buffer = getc(image)) != '\n');
        } else {
            break;
        }
    }

    // Extract the message length
    char messageLengthBinary[32];
    memset(messageLengthBinary, '0', 32);
    for (int i = 0; i < 32; i++) {
        unsigned char pixel;
        fread(&pixel, 1, 1, image);
        messageLengthBinary[i] = (pixel & 1) ? '1' : '0';
    }

    int messageLength = binaryToChar(messageLengthBinary);

    // Extract the actual message
    for (int i = 0; i < messageLength; i++) {
        char messageBinary[9];
        memset(messageBinary, '0', 8);
        for (int j = 0; j < 8; j++) {
            unsigned char pixel;
            fread(&pixel, 1, 1, image);
            messageBinary[j] = (pixel & 1) ? '1' : '0';
        }
        message[i] = binaryToChar(messageBinary);
    }

    message[messageLength] = '\0'; // Null-terminate the message
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s [embed|extract] <input_image.ppm> <output_image.ppm> [message]\n", argv[0]);
        return 1;
    }

    const char *mode = argv[1];
    const char *inputImageName = argv[2];
    const char *outputImageName = argv[3];

    FILE *inputImage = fopen(inputImageName, "rb");
    if (!inputImage) {
        perror("Error opening input image file");
        return 1;
    }

    FILE *outputImage = fopen(outputImageName, "wb");
    if (!outputImage) {
        perror("Error opening output image file");
        fclose(inputImage);
        return 1;
    }

    if (strcmp(mode, "embed") == 0) {
        if (argc < 5) {
            fprintf(stderr, "Usage: %s embed <input_image.ppm> <output_image.ppm> <message>\n", argv[0]);
            fclose(inputImage);
            fclose(outputImage);
            return 1;
        }

        const char *message = argv[4];
        embedMessageInImage(inputImage, outputImage, message);
    } else if (strcmp(mode, "extract") == 0) {
        char extractedMessage[MAX_MESSAGE_LENGTH];
        extractMessageFromImage(inputImage, extractedMessage);
        printf("Extracted Message: %s\n", extractedMessage);
    } else {
        fprintf(stderr, "Invalid mode. Use 'embed' or 'extract'.\n");
        fclose(inputImage);
        fclose(outputImage);
        return 1;
    }

    fclose(inputImage);
    fclose(outputImage);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Structure to store parsed key-value pairs
typedef struct {
    char* key;
    char* value;
} JSONPair;

// Function to trim whitespace from the beginning and end of a string
char* trim(char* str) {
    char* start = str;
    char* end = str + strlen(str) - 1;

    // Trim leading whitespace
    while (isspace(*start)) {
        start++;
    }

    // Trim trailing whitespace
    while (end > start && isspace(*end)) {
        *end = '\0';
        end--;
    }

    // Move the trimmed string to the beginning
    if (start != str) {
        memmove(str, start, strlen(start) + 1);
    }

    return str;
}

// Function to parse JSON-like string
void parseJSON(const char* jsonStr) {
    // Remove braces
    char* str = strdup(jsonStr + 1);
    str[strlen(str) - 1] = '\0';

    // Array to store parsed key-value pairs
    JSONPair pairs[10];
    int pairCount = 0;

    // Split the string into key-value pairs
    char* token = strtok(str, ",");
    while (token != NULL) {
        // Split each pair into key and value
        char* colonPos = strchr(token, ':');
        if (colonPos != NULL) {
            *colonPos = '\0';
            char* key = trim(token);
            char* value = trim(colonPos + 1);

            // Remove quotes from key and value
            if (key[0] == '"') {
                key++;
                key[strlen(key) - 1] = '\0';
            }
            if (value[0] == '"') {
                value++;
                value[strlen(value) - 1] = '\0';
            }

            // Store the pair
            pairs[pairCount].key = strdup(key);
            pairs[pairCount].value = strdup(value);
            pairCount++;
        }
        token = strtok(NULL, ",");
    }

    // Print parsed key-value pairs
    printf("Parsed JSON:\n");
    for (int i = 0; i < pairCount; i++) {
        printf("%s: %s\n", pairs[i].key, pairs[i].value);

        // Free dynamically allocated memory
        free(pairs[i].key);
        free(pairs[i].value);
    }

    // Free the duplicated string
    free(str);
}

int main() {
    const char* jsonStr = "{\"name\": \"John\", \"age\": 30, \"city\": \"New York\"}";

    parseJSON(jsonStr);

    return 0;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// Function to trim whitespace from the beginning and end of a string
void trim(char *str) {
    int i = 0, j = 0;
    while (str[i] == ' ' || str[i] == '\t' || str[i] == '\n') i++;
    while (str[i] != '\0') {
        str[j++] = str[i++];
    }
    str[j] = '\0';
    j--;
    while (j >= 0 && (str[j] == ' ' || str[j] == '\t' || str[j] == '\n')) j--;
    str[j + 1] = '\0';
}

// Function to parse the JSON-like string
void parse_json(char *json) {
    char *token;
    char *key, *value;
    char *rest = json;

    // Remove the outer curly braces
    rest = strchr(rest, '{');
    if (rest) rest++;
    rest = strtok(rest, "}");
    if (!rest) return;

    // Tokenize the string by commas
    token = strtok(rest, ",");
    while (token != NULL) {
        // Split the token into key and value
        key = strtok(token, ":");
        value = strtok(NULL, ":");

        // Trim whitespace from key and value
        if (key) trim(key);
        if (value) trim(value);

        // Remove quotes from key and value if present
        if (key && key[0] == '"') key++;
        if (key && key[strlen(key) - 1] == '"') key[strlen(key) - 1] = '\0';
        if (value && value[0] == '"') value++;
        if (value && value[strlen(value) - 1] == '"') value[strlen(value) - 1] = '\0';

        // Print the key-value pair
        if (key && value) {
            printf("Key: %s, Value: %s\n", key, value);
        }

        // Get the next token
        token = strtok(NULL, ",");
    }
}

int main() {
    char json[] = "{\"name\": \"John\", \"age\": 30, \"city\": \"New York\"}";
    parse_json(json);
    return 0;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h> // For atoi

// A simple structure to hold parsed key-value pairs
typedef struct {
    char key[50];   // Assuming keys are not longer than 49 chars
    char value[100]; // Assuming values are not longer than 99 chars
    int type;       // 0 for string, 1 for integer (simple classification)
} JsonKeyValuePair;

// Function to extract a substring
char* substring(const char *str, int start, int length) {
    if (start < 0 || length < 0 || start + length > strlen(str)) {
        return NULL; // Invalid arguments
    }
    char *sub = (char *)malloc(length + 1);
    if (sub == NULL) {
        perror("Failed to allocate memory for substring");
        return NULL;
    }
    strncpy(sub, str + start, length);
    sub[length] = '\0';
    return sub;
}

// Function to parse the simple JSON-like string
// This function is custom-tailored for the *given* JSON structure.
// It will not work for arbitrary valid JSON.
int parse_simple_json(const char *json_string, JsonKeyValuePair *pairs, int max_pairs) {
    int pair_count = 0;
    const char *ptr = json_string;

    // Skip leading '{' and whitespace
    while (*ptr != '\0' && (*ptr == '{' || isspace((unsigned char)*ptr))) {
        ptr++;
    }

    while (pair_count < max_pairs) {
        // Find key start (first quote)
        const char *key_start_quote = strchr(ptr, '"');
        if (!key_start_quote) break; // No more keys

        // Find key end (second quote)
        const char *key_end_quote = strchr(key_start_quote + 1, '"');
        if (!key_end_quote) break; // Malformed JSON

        // Extract key
        int key_length = key_end_quote - (key_start_quote + 1);
        if (key_length >= sizeof(pairs[pair_count].key)) {
            fprintf(stderr, "Error: Key too long.\n");
            return -1;
        }
        strncpy(pairs[pair_count].key, key_start_quote + 1, key_length);
        pairs[pair_count].key[key_length] = '\0';

        // Find colon
        const char *colon_ptr = strchr(key_end_quote + 1, ':');
        if (!colon_ptr) break; // Malformed JSON

        // Find value start (either quote for string, or first non-space for number)
        const char *value_start = colon_ptr + 1;
        while (*value_start != '\0' && isspace((unsigned char)*value_start)) {
            value_start++;
        }

        if (*value_start == '"') { // It's a string value
            pairs[pair_count].type = 0; // String type
            const char *value_end_quote = strchr(value_start + 1, '"');
            if (!value_end_quote) {
                fprintf(stderr, "Error: Unterminated string value for key '%s'.\n", pairs[pair_count].key);
                return -1; // Malformed string
            }
            int value_length = value_end_quote - (value_start + 1);
            if (value_length >= sizeof(pairs[pair_count].value)) {
                fprintf(stderr, "Error: Value too long for key '%s'.\n", pairs[pair_count].key);
                return -1;
            }
            strncpy(pairs[pair_count].value, value_start + 1, value_length);
            pairs[pair_count].value[value_length] = '\0';
            ptr = value_end_quote + 1; // Move pointer past this value
        } else if (isdigit((unsigned char)*value_start) || (*value_start == '-' && isdigit((unsigned char)*(value_start + 1)))) { // It's a number
            pairs[pair_count].type = 1; // Integer type
            const char *value_end = value_start;
            while (*value_end != '\0' && (isdigit((unsigned char)*value_end) || *value_end == '.' || *value_end == '-' || *value_end == 'E' || *value_end == 'e')) {
                // Simplified for integers, but a full parser would handle floats
                // and exponents. For the given example, simple digit check is enough.
                value_end++;
            }
            // Backtrack to find the actual end, skipping whitespace and potential comma
            while (value_end > value_start && (isspace((unsigned char)*value_end) || *value_end == ',' || *value_end == '}')) {
                value_end--;
            }
            value_end++; // Move one step forward to include the last digit

            int value_length = value_end - value_start;
            if (value_length >= sizeof(pairs[pair_count].value)) {
                 fprintf(stderr, "Error: Value too long for key '%s'.\n", pairs[pair_count].key);
                 return -1;
            }
            strncpy(pairs[pair_count].value, value_start, value_length);
            pairs[pair_count].value[value_length] = '\0';
            ptr = value_end; // Move pointer past this value
        } else {
             fprintf(stderr, "Error: Unexpected value type for key '%s'. Received '%c'\n", pairs[pair_count].key, *value_start);
             return -1; // Not a string or number, could be boolean/null/array/object (unsupported)
        }

        pair_count++;

        // Find comma or closing brace
        while (*ptr != '\0' && (*ptr == ',' || isspace((unsigned char)*ptr))) {
            ptr++;
        }
        if (*ptr == '}') {
            break; // End of object
        }
    }
    return pair_count;
}

int main() {
    const char *json_string = "{\"name\": \"John\", \"age\": 30, \"city\": \"New York\"}";
    int max_pairs = 10; // Max number of key-value pairs we expect
    JsonKeyValuePair parsed_data[max_pairs];

    int num_parsed = parse_simple_json(json_string, parsed_data, max_pairs);

    if (num_parsed > 0) {
        printf("Parsed JSON Data:\n");
        for (int i = 0; i < num_parsed; ++i) {
            printf("  Key: \"%s\", ", parsed_data[i].key);
            if (parsed_data[i].type == 0) { // String
                printf("Value: \"%s\" (String)\n", parsed_data[i].value);
            } else if (parsed_data[i].type == 1) { // Integer
                printf("Value: %d (Integer)\n", atoi(parsed_data[i].value));
            }
        }
    } else if (num_parsed == 0) {
        printf("No data parsed (empty object or malformed).\n");
    } else {
        printf("Error parsing JSON string.\n");
    }

    printf("\nTrying with a slightly different string:\n");
    const char *json_string2 = "{ \"product\": \"Laptop\", \"price\": 1200, \"available\": true }";
    // This simple parser will incorrectly parse 'true' as a string.
    // It's meant to show limitations.
    JsonKeyValuePair parsed_data2[max_pairs];
    int num_parsed2 = parse_simple_json(json_string2, parsed_data2, max_pairs);

    if (num_parsed2 > 0) {
        printf("Parsed JSON Data:\n");
        for (int i = 0; i < num_parsed2; ++i) {
            printf("  Key: \"%s\", ", parsed_data2[i].key);
            if (parsed_data2[i].type == 0) { // String
                printf("Value: \"%s\" (String)\n", parsed_data2[i].value);
            } else if (parsed_data2[i].type == 1) { // Integer
                printf("Value: %d (Integer)\n", atoi(parsed_data2[i].value));
            }
        }
    } else if (num_parsed2 == 0) {
        printf("No data parsed (empty object or malformed).\n");
    } else {
        printf("Error parsing JSON string.\n");
    }

    return 0;
}

