#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Structure to hold key-value pairs
typedef struct {
    char* key;
    char* value;
    int isString; // Flag to indicate if value is a string
} KeyValuePair;

// Function to trim whitespace from a string
void trim(char* str) {
    int len = strlen(str);
    int start = 0;
    int end = len - 1;
    while (start < len && isspace(str[start])) start++;
    while (end >= 0 && isspace(str[end])) end--;
    memmove(str, str + start, end - start + 1);
    str[end - start + 1] = '\0';
}

// Function to remove quotes from a string
void removeQuotes(char* str) {
    int len = strlen(str);
    if (str[0] == '\"' && str[len - 1] == '\"') {
        memmove(str, str + 1, len - 1);
        str[len - 2] = '\0';
    }
}

// Function to parse the JSON-like string
void parseJson(const char* jsonStr) {
    char str[256]; // Assuming max key-value length is less than 256
    strcpy(str, jsonStr);

    // Remove opening and closing curly braces
    str[0] = '\0';
    strcpy(str, str + 1);
    str[strlen(str) - 1] = '\0';

    KeyValuePair* pairs = NULL;
    int pairCount = 0;

    // Tokenize by comma
    char* token = strtok(str, ",");
    while (token) {
        // Allocate and copy the token
        char* pairStr = malloc(strlen(token) + 1);
        strcpy(pairStr, token);

        // Find the colon to separate key and value
        char* colon = strstr(pairStr, ":");
        if (colon) {
            *colon = '\0'; // Split the string at the colon
            char* key = pairStr;
            char* value = colon + 1;

            trim(key); // Remove whitespace from key
            trim(value); // Remove whitespace from value

            removeQuotes(value); // Remove any quotes from the value

            // Determine if the value is a string or number
            int isString = 0;
            if (value[0] == '\"') {
                isString = 1;
            }

            // Save the key-value pair
            KeyValuePair pair;
            pair.key = malloc(strlen(key) + 1);
            strcpy(pair.key, key);
            pair.value = malloc(strlen(value) + 1);
            strcpy(pair.value, value);
            pair.isString = isString;

            // Add the pair to the list
            pairCount++;
            pairs = realloc(pairs, sizeof(KeyValuePair) * pairCount);
            pairs[pairCount - 1] = pair;

            free(pairStr); // Free the allocated token string
        }

        token = strtok(NULL, ",");
    }

    // Print the parsed key-value pairs
    printf("Parsed Key-Value Pairs:\n");
    for (int i = 0; i < pairCount; i++) {
        if (pairs[i].isString) {
            printf("%s: \"%s\"\n", pairs[i].key, pairs[i].value);
        } else {
            printf("%s: %s\n", pairs[i].key, pairs[i].value);
        }
    }

    // Free allocated memory
    for (int i = 0; i < pairCount; i++) {
        free(pairs[i].key);
        free(pairs[i].value);
    }
    free(pairs);
}

