#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// Function to parse the JSON-like string
void parse_json(const char *json) {
    // Struct to hold the parsed data
    struct Person {
        char name[50];
        int age;
        char city[50];
    } person;

    // Pointers to track positions in the string
    const char *start, *end;

    // Find and extract 'name'
    start = strstr(json, "\"name\": \"");
    if (start != NULL) {
        start += strlen("\"name\": \"");
        end = strchr(start, '"');
        if (end != NULL) {
            strncpy(person.name, start, end - start);
            person.name[end - start] = '\0';
        }
    }

    // Find and extract 'age'
    start = strstr(json, "\"age\": ");
    if (start != NULL) {
        start += strlen("\"age\": ");
        end = strchr(start, ',');
        if (end != NULL) {
            person.age = atoi(start);
        } else {
            // If 'age' is the last element, it won't have a comma
            person.age = atoi(start);
        }
    }

    // Find and extract 'city'
    start = strstr(json, "\"city\": \"");
    if (start != NULL) {
        start += strlen("\"city\": \"");
        end = strchr(start, '"');
        if (end != NULL) {
            strncpy(person.city, start, end - start);
            person.city[end - start] = '\0';
        }
    }

    // Print the parsed data
    printf("Name: %s\n", person.name);
    printf("Age: %d\n", person.age);
    printf("City: %s\n", person.city);
}

int main() {
    const char *json = "{\"name\": \"John\", \"age\": 30, \"city\": \"New York\"}";
    parse_json(json);
    return 0;
}

