int main() {
    // 1. Declare variables
    int secretNumber;
    int guess;
    int numberOfAttempts = 0;
    const int MAX_ATTEMPTS = 10; // You can adjust this for difficulty
    const int MIN_RANGE = 1;     // Minimum number in the range
    const int MAX_RANGE = 100;   // Maximum number in the range

    // 2. Seed the random number generator
    //    `time(NULL)` provides a different seed each time,
    //    making the random numbers truly random across runs.
    srand(time(NULL));

    // 3. Generate a random secret number
    //    `rand() % (MAX_RANGE - MIN_RANGE + 1)` gives a number from 0 to (MAX_RANGE - MIN_RANGE)
    //    Adding `MIN_RANGE` shifts it to the desired range (e.g., 1 to 100).
    secretNumber = (rand() % (MAX_RANGE - MIN_RANGE + 1)) + MIN_RANGE;

    // 4. Welcome message
    printf("Welcome to the Number Guessing Game!\n");
    printf("I have picked a secret number between %d and %d.\n", MIN_RANGE, MAX_RANGE);
    printf("Can you guess it within %d attempts?\n\n", MAX_ATTEMPTS);

    // 5. Game loop
    //    The loop continues until the user guesses correctly OR runs out of attempts.
    do {
        printf("Attempt %d of %d: Enter your guess: ", numberOfAttempts + 1, MAX_ATTEMPTS);
        scanf("%d", &guess); // Read the user's guess

        numberOfAttempts++; // Increment attempt counter

        // 6. Provide feedback to the user
        if (guess < secretNumber) {
            printf("Too low! Try again.\n");
        } else if (guess > secretNumber) {
            printf("Too high! Try again.\n");
        } else {
            // Correct guess!
            printf("\nCongratulations! You guessed the number %d in %d attempts!\n", secretNumber, numberOfAttempts);
            break; // Exit the loop as the game is won
        }

        // Optional: Check if attempts are exhausted (only applies if loop didn't break due to correct guess)
        if (numberOfAttempts >= MAX_ATTEMPTS && guess != secretNumber) {
            printf("\nSorry, you ran out of attempts! The secret number was %d.\n", secretNumber);
            break; // Exit the loop
        }

        printf("\n"); // Add a newline for better readability between attempts

    } while (guess != secretNumber && numberOfAttempts < MAX_ATTEMPTS); // Loop condition

    printf("\nThanks for playing!\n");

    return 0; // Indicate successful program execution
}

