#include <stdbool.h>

#define MAX_LINE_LENGTH 10000
#define MAX_FIELD_LENGTH 1000

// Function to escape double quotes within a field
char* escape_quotes(const char* input) {
    // Allocate a new string to store the escaped field
    char* escaped = malloc(strlen(input) * 2 + 1);
    if (escaped == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    // Iterate through input and escape double quotes
    int j = 0;
    for (int i = 0; input[i] != '\0'; i++) {
        if (input[i] == '"') {
            escaped[j++] = '"';  // Double the quote
        }
        escaped[j++] = input[i];
    }
    escaped[j] = '\0';

    return escaped;
}

// Function to process a single CSV file
void process_csv_file(const char* input_filename, const char* output_filename) {
    FILE* input_file = fopen(input_filename, "r");
    if (input_file == NULL) {
        fprintf(stderr, "Error opening input file: %s\n", input_filename);
        exit(1);
    }

    FILE* output_file = fopen(output_filename, "w");
    if (output_file == NULL) {
        fprintf(stderr, "Error opening output file: %s\n", output_filename);
        fclose(input_file);
        exit(1);
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), input_file) != NULL) {
        char* processed_line = malloc(MAX_LINE_LENGTH * 2);
        if (processed_line == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            fclose(input_file);
            fclose(output_file);
            exit(1);
        }

        int line_index = 0;
        int processed_index = 0;
        bool in_quotes = false;
        char field[MAX_FIELD_LENGTH];
        int field_index = 0;

        // Process each character in the line
        for (int i = 0; line[i] != '\0'; i++) {
            if (line[i] == '"') {
                in_quotes = !in_quotes;
            }

            if (line[i] == ',' || line[i] == '\n' || line[i] == '\r') {
                // End of field
                field[field_index] = '\0';

                if (field_index > 0) {
                    char* escaped_field = escape_quotes(field);

                    // Add quotes around the field
                    processed_line[processed_index++] = '"';
                    strcpy(processed_line + processed_index, escaped_field);
                    processed_index += strlen(escaped_field);
                    processed_line[processed_index++] = '"';
                    free(escaped_field);
                }

                // Add delimiter or line ending
                processed_line[processed_index++] = line[i];

                // Reset field
                field_index = 0;
            } else {
                // Collect field characters
                field[field_index++] = line[i];
            }
        }

        // Null-terminate the processed line
        processed_line[processed_index] = '\0';

        // Write processed line to output file
        fputs(processed_line, output_file);

        free(processed_line);
    }

    fclose(input_file);
    fclose(output_file);
}

int main(int argc, char* argv[]) {
    // Check command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_file> <output_file>\n", argv[0]);
        return 1;
    }

    const char* input_filename = argv[1];
    const char* output_filename = argv[2];

    // Process the CSV file
    process_csv_file(input_filename, output_filename);

    printf("CSV file processed successfully.\n");

    return 0;
}

#include <stdio.h>
