#include <string.h>

#define MAX_LINE_LENGTH 1024

void fix_csv_formatting(FILE *input, FILE *output) {
    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, input)) {
        char *token;
        int first_token = 1;

        // Remove newline character if present
        line[strcspn(line, "\n")] = 0;

        token = strtok(line, ",");
        while (token != NULL) {
            if (!first_token) {
                fprintf(output, ",");
            }
            first_token = 0;

            // Check if the token is already quoted
            if (token[0] != '"' || token[strlen(token) - 1] != '"') {
                fprintf(output, "\"%s\"", token);
            } else {
                fprintf(output, "%s", token);
            }

            token = strtok(NULL, ",");
        }
        fprintf(output, "\n");
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_csv_file> <output_csv_file>\n", argv[0]);
        return 1;
    }

    FILE *input = fopen(argv[1], "r");
    if (input == NULL) {
        perror("Error opening input file");
        return 1;
    }

    FILE *output = fopen(argv[2], "w");
    if (output == NULL) {
        perror("Error opening output file");
        fclose(input);
        return 1;
    }

    fix_csv_formatting(input, output);

    fclose(input);
    fclose(output);

    printf("CSV formatting fixed successfully. Output saved to %s\n", argv[2]);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_LINE_LENGTH 4096
#define MAX_FIELD_LENGTH 1024

// Function to check if a character is part of a delimiter
bool is_delimiter(char c, const char* delimiters) {
    return strchr(delimiters, c) != NULL;
}

// Function to process a single field:
// If it contains a quote or a delimiter, it needs to be enclosed in quotes.
// If it's already enclosed in quotes, it handles internal quotes by doubling them.
void process_field(char* output_buffer, const char* field_content, const char* delimiters) {
    bool needs_quoting = false;
    bool contains_double_quote = false;
    const char* ptr = field_content;

    // Check if quoting is necessary or if internal quotes need handling
    while (*ptr) {
        if (*ptr == '"') {
            needs_quoting = true;
            contains_double_quote = true;
        } else if (is_delimiter(*ptr, delimiters)) {
            needs_quoting = true;
        } else if (*ptr == '\n' || *ptr == '\r') { // Newlines typically require quoting in CSV
            needs_quoting = true;
        }
        ptr++;
    }

    if (needs_quoting) {
        *output_buffer++ = '"';
        ptr = field_content;
        while (*ptr) {
            if (*ptr == '"') {
                *output_buffer++ = '"'; // Double the internal quote
            }
            *output_buffer++ = *ptr;
            ptr++;
        }
        *output_buffer++ = '"';
    } else {
        strcpy(output_buffer, field_content);
    }
    *output_buffer = '\0'; // Null-terminate the output field
}

// Function to read and process the CSV file
void process_csv(const char* input_filename, const char* output_filename, const char* delimiters) {
    FILE* input_file = NULL;
    FILE* output_file = NULL;
    char line[MAX_LINE_LENGTH];
    char processed_field[MAX_FIELD_LENGTH * 2]; // Max field length * 2 for quoting
    char* token;
    bool first_field_in_line;
    int line_num = 0;

    input_file = fopen(input_filename, "r");
    if (input_file == NULL) {
        fprintf(stderr, "Error: Could not open input file '%s'\n", input_filename);
        return;
    }

    output_file = fopen(output_filename, "w");
    if (output_file == NULL) {
        fprintf(stderr, "Error: Could not open output file '%s'\n", output_filename);
        fclose(input_file);
        return;
    }

    fprintf(stdout, "Processing '%s' and writing to '%s'...\n", input_filename, output_filename);

    while (fgets(line, sizeof(line), input_file) != NULL) {
        line_num++;
        first_field_in_line = true;

        // Remove trailing newline or carriage return
        line[strcspn(line, "\r\n")] = '\0';

        // Use strtok_r for thread-safety and to allow nested tokenizing if needed
        char* rest_of_line = line;
        while ((token = strtok_r(rest_of_line, delimiters, &rest_of_line)) != NULL) {
            if (!first_field_in_line) {
                fputc(',', output_file); // Always use comma as the output delimiter
            }

            process_field(processed_field, token, delimiters);
            fputs(processed_field, output_file);
            first_field_in_line = false;
        }
        fputc('\n', output_file); // Add a newline at the end of each processed line
    }

    fclose(input_file);
    fclose(output_file);
    fprintf(stdout, "Processing complete. Processed %d lines.\n", line_num);
}

int main(int argc, char* argv[]) {
    if (argc < 3 || argc > 4) {
        fprintf(stderr, "Usage: %s <input_csv_file> <output_csv_file> [delimiters]\n", argv[0]);
        fprintf(stderr, "  [delimiters]: Optional. A string of characters to consider as delimiters (e.g., \",\\t\").\n");
        fprintf(stderr, "                Defaults to ',' if not provided.\n");
        return 1;
    }

    const char* input_file = argv[1];
    const char* output_file = argv[2];
    const char* delimiters = (argc == 4) ? argv[3] : ",";

    process_csv(input_file, output_file, delimiters);

    return 0;
}

#include <stdio.h>
