#define MAX_LINE_LEN 4096   // Adjust according to your largest row length

// Escape quotes and enclose in quotes
void write_quoted(FILE* out, const char* field) {
    fputc('"', out);
    for (const char* p = field; *p; ++p) {
        if (*p == '"') // double up double quotes
            fputc('"', out);
        fputc(*p, out);
    }
    fputc('"', out);
}

int main(void) {
    FILE *in = fopen("input.csv", "r");
    FILE *out = fopen("output.csv", "w");
    if (!in || !out) {
        perror("File error");
        return 1;
    }
    char buf[MAX_LINE_LEN];

    while (fgets(buf, sizeof(buf), in)) {
        size_t len = strlen(buf);
        // Remove trailing newline (if present)
        if (len && (buf[len-1] == '\n' || buf[len-1] == '\r')) {
            buf[--len] = '\0';
            if (len && buf[len-1] == '\r') buf[--len] = '\0';
        }

        int first_field = 1;
        char *field = buf;
        char *next;
        // Split fields by comma
        while (field) {
            next = strchr(field, ',');
            if (next) *next = '\0';

            if (!first_field)
                fputc(',', out);
            first_field = 0;

            // Strip leading/trailing spaces for cleanliness
            char *start = field;
            while (*start == ' ') ++start;
            char *end = start + strlen(start) - 1;
            while (end > start && *end == ' ') *end-- = '\0';

            // Remove outer quotes if present
            if (start[0] == '"' && end > start && *end == '"') {
                ++start;
                *end = '\0';
            }

            // Write quoted (re-quoting all fields)
            write_quoted(out, start);

            if (next)
                field = next + 1;
            else
                field = NULL;
        }
        fputc('\n', out);
    }

    fclose(in);
    fclose(out);
    printf("CSV formatting fixed and written to output.csv.\n");
    return 0;
}

#include <stdio.h>
