#include <string.h>

#define BUFFER_SIZE 1024

// Function to trim whitespace from the start and end of a string
char* trim_whitespace(char* str) {
    char* end;

    // Trim leading space
    while (*str == ' ') str++;

    // Trim trailing space
    if (*str) {
        end = str + strlen(str) - 1;
        while (end > str && *end == ' ') end--;
        *(end + 1) = '\0';
    }

    return str;
}

// Function to quote a string if not already quoted
void quote_string(char* dest, const char* src) {
    if (src[0] == '"' && src[strlen(src) - 1] == '"') {
        strcpy(dest, src);
    } else {
        sprintf(dest, "\"%s\"", src);
    }
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_csv> <output_csv>\n", argv[0]);
        return 1;
    }

    FILE* inputFile = fopen(argv[1], "r");
    if (inputFile == NULL) {
        perror("Error opening input file");
        return 1;
    }

    FILE* outputFile = fopen(argv[2], "w");
    if (outputFile == NULL) {
        perror("Error opening output file");
        fclose(inputFile); // Close the opened input file
        return 1;
    }

    char line[BUFFER_SIZE];
    while (fgets(line, sizeof(line), inputFile)) {
        char* token;
        char* rest = line;
        int first = 1;

        while ((token = strtok_r(rest, ",", &rest))) {
            char trimmedToken[BUFFER_SIZE];
            char quotedToken[BUFFER_SIZE];

            strcpy(trimmedToken, trim_whitespace(token));
            quote_string(quotedToken, trimmedToken);

            if (!first) {
                fprintf(outputFile, ",");
            }
            fprintf(outputFile, "%s", quotedToken);

            first = 0;
        }
        fprintf(outputFile, "\n");
    }

    fclose(inputFile);
    fclose(outputFile);

    return 0;
}

