#include <string.h>

// Function to read a CSV file and print the formatted output
void fix_csv_file(const char *filename) {
    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Could not open file %s for reading.\n", filename);
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Strip newline character
        line[strcspn(line, "\n")] = 0;

        // Initialize variables to track the current cell and whether we are inside a quoted cell
        char *cell_start = line;
        char *cell_end = line;
        int inside_quote = 0;

        // Iterate over the characters in the line
        while (*cell_end != '\0') {
            // Check if we are entering or leaving a quoted cell
            if (*cell_end == '"') {
                inside_quote = !inside_quote;
                cell_end++;
            }
            // If we are not inside a quoted cell and encounter a comma, print the current cell
            else if (*cell_end == ',' && !inside_quote) {
                // Print the cell with quotes if it contains a comma or a quote
                char *quote_ptr = cell_start;
                int print_quotes = 0;
                while (*quote_ptr != '\0' && *quote_ptr != ',') {
                    if (*quote_ptr == '"' || *quote_ptr == ',') {
                        print_quotes = 1;
                        break;
                    }
                    quote_ptr++;
                }
                if (print_quotes) {
                    printf("\"");
                }
                printf("%.*s", (int)(cell_end - cell_start), cell_start);
                if (print_quotes) {
                    printf("\"");
                }
                printf(",");
                // Move to the next cell
                cell_start = cell_end + 1;
            }
            // Move to the next character
            else {
                cell_end++;
            }
        }

        // Print the last cell
        // Print the cell with quotes if it contains a comma or a quote
        char *quote_ptr = cell_start;
        int print_quotes = 0;
        while (*quote_ptr != '\0') {
            if (*quote_ptr == '"' || *quote_ptr == ',') {
                print_quotes = 1;
                break;
            }
            quote_ptr++;
        }
        if (print_quotes) {
            printf("\"");
        }
        printf("%s", cell_start);
        if (print_quotes) {
            printf("\"");
        }
        printf("\n");
    }

    // Close the file
    fclose(file);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    fix_csv_file(argv[1]);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BUFFER_SIZE 1024

void fix_csv_file(const char *input_file, const char *output_file) {
    FILE *input = fopen(input_file, "r");
    if (input == NULL) {
        perror("Error opening input file");
        exit(EXIT_FAILURE);
    }

    FILE *output = fopen(output_file, "w");
    if (output == NULL) {
        perror("Error opening output file");
        fclose(input);
        exit(EXIT_FAILURE);
    }

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, input) != NULL) {
        char *token = buffer;
        while (*token == ' ' || *token == '\t') {
            token++;  // Skip leading spaces and tabs
        }

        while (1) {
            // Find the next comma or end of line
            char *delimiter = strchr(token, ',');
            if (delimiter == NULL) {
                delimiter = strchr(token, '\n');
                if (delimiter == NULL) {
                    delimiter = strchr(token, '\0');
                }
            }

            // Write the token with double quotes
            if (token < delimiter) {
                fprintf(output, "\"");
                for (char *p = token; p < delimiter; p++) {
                    if (*p == '"') {
                        fprintf(output, "\"\"");  // Escape double quotes
                    } else {
                        fputc(*p, output);
                    }
                }
                fprintf(output, "\"");
            }

            // Move to the next token
            if (*delimiter == '\n' || *delimiter == '\0') {
                fputc(*delimiter, output);
                break;
            } else {
                token = delimiter + 1;
                while (*token == ' ' || *token == '\t') {
                    token++;  // Skip spaces and tabs
                }
                fputc(',', output);
            }
        }
    }

    fclose(input);
    fclose(output);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_csv_file> <output_csv_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input_file = argv[1];
    const char *output_file = argv[2];

    fix_csv_file(input_file, output_file);

    printf("CSV file formatting fixed and saved to %s\n", output_file);
    return EXIT_SUCCESS;
}

