#define MAX_ITEMS 100
#define MAX_NAME_LENGTH 50

// Structure to represent a grocery item
typedef struct {
    char name[MAX_NAME_LENGTH];
    float price;
} GroceryItem;

// Function to find the price of an item in the dictionary
float find_item_price(GroceryItem* dictionary, int dict_size, const char* item_name) {
    for (int i = 0; i < dict_size; i++) {
        if (strcmp(dictionary[i].name, item_name) == 0) {
            return dictionary[i].price;
        }
    }
    return -1.0; // Item not found
}

// Function to calculate total price and create a detailed shopping list
char** calculate_total_price(GroceryItem* dictionary, int dict_size, 
                              char** shopping_list, int list_size, 
                              float* total_price, int* detailed_list_size) {
    // Allocate memory for the detailed shopping list
    char** detailed_list = malloc(MAX_ITEMS * sizeof(char*));
    for (int i = 0; i < MAX_ITEMS; i++) {
        detailed_list[i] = malloc(MAX_NAME_LENGTH * sizeof(char));
    }

    // Initialize tracking variables
    *total_price = 0.0;
    *detailed_list_size = 0;

    // Create a frequency count for each item
    int item_count[MAX_ITEMS] = {0};

    // Count occurrences of each item
    for (int i = 0; i < list_size; i++) {
        int found = 0;
        for (int j = 0; j < *detailed_list_size; j++) {
            if (strcmp(detailed_list[j], shopping_list[i]) == 0) {
                item_count[j]++;
                found = 1;
                break;
            }
        }

        if (!found) {
            strcpy(detailed_list[*detailed_list_size], shopping_list[i]);
            item_count[*detailed_list_size] = 1;
            (*detailed_list_size)++;
        }
    }

    // Calculate total price and modify detailed list
    for (int i = 0; i < *detailed_list_size; i++) {
        float item_price = find_item_price(dictionary, dict_size, detailed_list[i]);

        if (item_price < 0) {
            printf("Error: Item %s not found in dictionary\n", detailed_list[i]);
            continue;
        }

        // Modify item name if quantity > 1
        if (item_count[i] > 1) {
            char new_name[MAX_NAME_LENGTH];
            sprintf(new_name, "%sx%d", detailed_list[i], item_count[i]);
            strcpy(detailed_list[i], new_name);
        }

        *total_price += item_price * item_count[i];
    }

    return detailed_list;
}

// Function to free the detailed list
void free_detailed_list(char** detailed_list, int detailed_list_size) {
    for (int i = 0; i < detailed_list_size; i++) {
        free(detailed_list[i]);
    }
    free(detailed_list);
}

