#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h> // For isdigit

// Structure to store grocery item and its price
typedef struct {
    char name[50];
    double price;
} GroceryItem;

// Function to parse the dictionary string and populate the GroceryItem array
int parseDictionary(const char *dictionary_str, GroceryItem **items_out) {
    // Make a mutable copy of the dictionary string
    char *dict_copy = strdup(dictionary_str);
    if (dict_copy == NULL) {
        perror("Failed to allocate memory for dictionary copy");
        return -1;
    }

    // Count the number of items to allocate memory
    int num_items = 0;
    char *temp_ptr = dict_copy;
    while (*temp_ptr != '\0') {
        if (*temp_ptr == '{' || *temp_ptr == ',' || *temp_ptr == ' ') {
            temp_ptr++;
            continue;
        }
        num_items++;
        // Skip to the next item or end of string
        while (*temp_ptr != ',' && *temp_ptr != '}' && *temp_ptr != '\0') {
            temp_ptr++;
        }
    }
    free(dict_copy); // Free the temp copy after counting

    if (num_items == 0) {
        *items_out = NULL;
        return 0; // No items in dictionary
    }

    *items_out = (GroceryItem *)malloc(sizeof(GroceryItem) * num_items);
    if (*items_out == NULL) {
        perror("Failed to allocate memory for grocery items");
        return -1;
    }

    dict_copy = strdup(dictionary_str); // Recreate mutable copy for parsing
    if (dict_copy == NULL) {
        perror("Failed to allocate memory for dictionary copy");
        free(*items_out);
        *items_out = NULL;
        return -1;
    }

    char *token = strtok(dict_copy, "{}, ");
    int i = 0;
    while (token != NULL) {
        char *colon_pos = strchr(token, ':');
        if (colon_pos != NULL) {
            *colon_pos = '\0'; // Null-terminate item name
            strcpy((*items_out)[i].name, token);
            (*items_out)[i].price = atof(colon_pos + 1);
            i++;
        }
        token = strtok(NULL, "{}, ");
    }

    free(dict_copy);
    return num_items;
}

// Function to calculate the total price of the shopping list
double calculateTotalPrice(const char *dictionary_str, const char *shopping_list_str) {
    GroceryItem *grocery_items = NULL;
    int num_grocery_items = parseDictionary(dictionary_str, &grocery_items);

    if (num_grocery_items == -1) {
        fprintf(stderr, "Error parsing dictionary.\n");
        return -1.0; // Indicate error
    }

    if (num_grocery_items == 0) {
        printf("Dictionary is empty. Total price: 0.00\n");
        return 0.0;
    }

    double total_price = 0.0;

    // Create a mutable copy of the shopping list string
    char *list_copy = strdup(shopping_list_str);
    if (list_copy == NULL) {
        perror("Failed to allocate memory for shopping list copy");
        free(grocery_items);
        return -1.0;
    }

    // Use a temporary array to store unique items and their counts in the shopping list
    typedef struct {
        char name[50];
        int count;
    } ShoppingItemCount;

    ShoppingItemCount *shopping_item_counts = NULL;
    int num_unique_shopping_items = 0;
    int current_capacity = 10; // Initial capacity for shopping_item_counts

    shopping_item_counts = (ShoppingItemCount *)malloc(sizeof(ShoppingItemCount) * current_capacity);
    if (shopping_item_counts == NULL) {
        perror("Failed to allocate memory for shopping item counts");
        free(grocery_items);
        free(list_copy);
        return -1.0;
    }

    char *token = strtok(list_copy, ", ");
    while (token != NULL) {
        char item_name[50];
        int count = 1;

        // Check for "itemxN" format
        char *x_pos = strchr(token, 'x');
        if (x_pos != NULL && isdigit(*(x_pos + 1))) {
            *x_pos = '\0'; // Null-terminate item name
            strcpy(item_name, token);
            count = atoi(x_pos + 1);
        } else {
            strcpy(item_name, token);
        }

        // Add to or update shopping_item_counts
        int found = 0;
        for (int i = 0; i < num_unique_shopping_items; i++) {
            if (strcmp(shopping_item_counts[i].name, item_name) == 0) {
                shopping_item_counts[i].count += count;
                found = 1;
                break;
            }
        }

        if (!found) {
            if (num_unique_shopping_items >= current_capacity) {
                current_capacity *= 2;
                ShoppingItemCount *temp = (ShoppingItemCount *)realloc(shopping_item_counts, sizeof(ShoppingItemCount) * current_capacity);
                if (temp == NULL) {
                    perror("Failed to reallocate memory for shopping item counts");
                    free(grocery_items);
                    free(list_copy);
                    free(shopping_item_counts);
                    return -1.0;
                }
                shopping_item_counts = temp;
            }
            strcpy(shopping_item_counts[num_unique_shopping_items].name, item_name);
            shopping_item_counts[num_unique_shopping_items].count = count;
            num_unique_shopping_items++;
        }

        token = strtok(NULL, ", ");
    }

    // Now calculate the total price based on counted items
    for (int i = 0; i < num_unique_shopping_items; i++) {
        const char *item_name_counted = shopping_item_counts[i].name;
        int item_count = shopping_item_counts[i].count;
        int found_in_dictionary = 0;

        for (int j = 0; j < num_grocery_items; j++) {
            if (strcmp(grocery_items[j].name, item_name_counted) == 0) {
                total_price += grocery_items[j].price * item_count;
                found_in_dictionary = 1;
                break;
            }
        }

        if (!found_in_dictionary) {
