#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// Structure to represent a grocery item and its price
typedef struct {
    char* name;
    double price;
} GroceryItem;

// Function to calculate the total price of a shopping list
double calculateTotalPrice(GroceryItem* prices, int numPrices, char** shoppingList, int numItems) {
    double totalPrice = 0.0;
    int* itemCounts = (int*) calloc(numItems, sizeof(int));
    char** processedList = (char**) malloc(numItems * sizeof(char*));

    // Count occurrences of each item in the shopping list
    for (int i = 0; i < numItems; i++) {
        for (int j = 0; j < numItems; j++) {
            if (i != j && strcmp(shoppingList[i], shoppingList[j]) == 0) {
                itemCounts[i]++;
            }
        }
    }

    // Process the shopping list to concatenate quantities
    for (int i = 0; i < numItems; i++) {
        char* itemName = strdup(shoppingList[i]);
        if (itemCounts[i] > 0) {
            char* quantityStr = (char*) malloc(10 * sizeof(char));
            sprintf(quantityStr, "x%d", itemCounts[i] + 1);
            char* processedItemName = (char*) malloc((strlen(itemName) + strlen(quantityStr) + 1) * sizeof(char));
            strcpy(processedItemName, itemName);
            strcat(processedItemName, quantityStr);
            processedList[i] = processedItemName;
            free(quantityStr);
        } else {
            processedList[i] = itemName;
        }
        free(itemName);
    }

    // Free item counts array
    free(itemCounts);

    // Calculate the total price
    for (int i = 0; i < numItems; i++) {
        for (int j = 0; j < numPrices; j++) {
            char* baseItemName = processedList[i];
            // Remove the quantity part if present
            if (strchr(baseItemName, 'x') != NULL) {
                baseItemName = strtok(baseItemName, "x");
            }
            if (strcmp(baseItemName, prices[j].name) == 0) {
                // Extract the quantity if present
                char* quantityStr = strchr(processedList[i], 'x');
                int quantity = 1;
                if (quantityStr != NULL) {
                    quantity = atoi(quantityStr + 1);
                }
                totalPrice += prices[j].price * quantity;
                break;
            }
        }
    }

    // Free processed list
    for (int i = 0; i < numItems; i++) {
        free(processedList[i]);
    }
    free(processedList);

    return totalPrice;
}

int main() {
    // Example usage:
    GroceryItem prices[] = {
        {"milk", 2.99},
        {"eggs", 1.99},
        {"bread", 3.99}
    };
    int numPrices = sizeof(prices) / sizeof(prices[0]);

    char* shoppingList[] = {"milk", "milk", "eggs", "bread", "milk"};
    int numItems = sizeof(shoppingList) / sizeof(shoppingList[0]);

    double totalPrice = calculateTotalPrice(prices, numPrices, shoppingList, numItems);
    printf("Total price: $%.2f\n", totalPrice);

    return 0;
}

