#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>
#include <sys/wait.h>
#include <unistd.h>

// Structure to store execution information
typedef struct {
    char* path;
    double execution_time;
} ExecutableInfo;

// Comparison function for qsort to sort by execution time in descending order
int compare_execution_time(const void* a, const void* b) {
    const ExecutableInfo* exec1 = (const ExecutableInfo*)a;
    const ExecutableInfo* exec2 = (const ExecutableInfo*)b;

    if (exec1->execution_time < exec2->execution_time) return 1;
    if (exec1->execution_time > exec2->execution_time) return -1;
    return 0;
}

// Function to run an executable and measure its execution time
double run_and_measure_time(const char* path) {
    struct timeval start, end;
    pid_t pid;
    int status;

    // Get start time
    gettimeofday(&start, NULL);

    // Fork a child process
    pid = fork();

    if (pid == -1) {
        perror("fork");
        return -1;
    }

    if (pid == 0) {
        // Child process
        // Execute the program
        execl(path, path, NULL);

        // If execl fails
        perror("execl");
        exit(1);
    } else {
        // Parent process
        // Wait for child to complete
        waitpid(pid, &status, 0);

        // Get end time
        gettimeofday(&end, NULL);

        // Calculate execution time
        double exec_time = (end.tv_sec - start.tv_sec) * 1000.0;
        exec_time += (end.tv_usec - start.tv_usec) / 1000.0;

        return exec_time;
    }
}

int main(int argc, char* argv[]) {
    // Check if any executables are provided
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <executable1> [executable2] ...\n", argv[0]);
        return 1;
    }

    // Allocate memory for executable info array
    ExecutableInfo* executables = malloc((argc - 1) * sizeof(ExecutableInfo));
    if (!executables) {
        perror("Memory allocation failed");
        return 1;
    }

    // Run each executable and measure its time
    for (int i = 1; i < argc; i++) {
        // Store the path
        executables[i-1].path = strdup(argv[i]);

        // Measure execution time
        executables[i-1].execution_time = run_and_measure_time(argv[i]);

        // Check if measurement was successful
        if (executables[i-1].execution_time < 0) {
            fprintf(stderr, "Failed to measure time for %s\n", argv[i]);
        }
    }

    // Sort executables by execution time
    qsort(executables, argc - 1, sizeof(ExecutableInfo), compare_execution_time);

    // Print results
    printf("Execution Time Toplist:\n");
    printf("--------------------\n");
    for (int i = 0; i < argc - 1; i++) {
        printf("%d. %s: %.2f ms\n", 
               i + 1, 
               executables[i].path, 
               executables[i].execution_time);
    }

    // Free allocated memory
    for (int i = 0; i < argc - 1; i++) {
        free(executables[i].path);
    }
    free(executables);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>
#include <unistd.h>
#include <sys/wait.h>

typedef struct {
    char *path;
    double time;
} ProgramResult;

double get_time() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return tv.tv_sec + tv.tv_usec / 1000000.0;
}

void run_program(char *path, ProgramResult *result) {
    double start_time = get_time();
    pid_t pid = fork();

    if (pid == 0) {
        // Child process
        execl(path, path, (char *)NULL);
        perror("execl");
        exit(EXIT_FAILURE);
    } else if (pid > 0) {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        double end_time = get_time();
        result->path = path;
        result->time = end_time - start_time;
    } else {
        perror("fork");
        exit(EXIT_FAILURE);
    }
}

int compare_results(const void *a, const void *b) {
    ProgramResult *resultA = (ProgramResult *)a;
    ProgramResult *resultB = (ProgramResult *)b;
    return (resultA->time > resultB->time) ? 1 : -1;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <executable1> <executable2> ... <executableN>\n", argv[0]);
        return EXIT_FAILURE;
    }

    ProgramResult results[argc - 1];

    for (int i = 1; i < argc; i++) {
        run_program(argv[i], &results[i - 1]);
    }

    qsort(results, argc - 1, sizeof(ProgramResult), compare_results);

    printf("Toplist of execution times:\n");
    for (int i = 0; i < argc - 1; i++) {
        printf("%d. %s: %.6f seconds\n", i + 1, results[i].path, results[i].time);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>     // For fork, execve, waitpid
#include <sys/wait.h>   // For waitpid
#include <sys/time.h>   // For gettimeofday
#include <errno.h>      // For errno

// Structure to store program name and its execution time
typedef struct {
    char *path;
    double execution_time_ms; // Time in milliseconds
    int exit_status;          // Exit status of the program
    int ran_successfully;     // Flag if program actually started and exited cleanly
} ProgramResult;

// Comparison function for qsort (ascending order of time)
int compareProgramResults(const void *a, const void *b) {
    ProgramResult *resultA = (ProgramResult *)a;
    ProgramResult *resultB = (ProgramResult *)b;

    // Prioritize programs that ran successfully
    if (resultA->ran_successfully && !resultB->ran_successfully) return -1;
    if (!resultA->ran_successfully && resultB->ran_successfully) return 1;

    // If both ran successfully or both failed, sort by time
    if (resultA->execution_time_ms < resultB->execution_time_ms) return -1;
    if (resultA->execution_time_ms > resultB->execution_time_ms) return 1;
    return 0; // If times are equal
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <executable1> [<executable2> ...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    int num_programs = argc - 1;
    ProgramResult *results = (ProgramResult *)malloc(sizeof(ProgramResult) * num_programs);
    if (results == NULL) {
        perror("Failed to allocate memory for results");
        return EXIT_FAILURE;
    }

    struct timeval start_time, end_time;

    // Iterate through each executable path
    for (int i = 0; i < num_programs; ++i) {
        const char *program_path = argv[i + 1];
        pid_t pid;
        int status;

        results[i].path = strdup(program_path); // Duplicate string for storage
        if (results[i].path == NULL) {
            perror("Failed to duplicate program path string");
            // Clean up already allocated paths and exit
            for (int k = 0; k < i; ++k) free(results[k].path);
            free(results);
            return EXIT_FAILURE;
        }
        results[i].execution_time_ms = 0.0;
        results[i].exit_status = -1; // Default to unknown
        results[i].ran_successfully = 0; // Default to not run successfully

        printf("Running program: %s\n", program_path);

        gettimeofday(&start_time, NULL); // Get start time

        pid = fork();

        if (pid == -1) {
            perror("fork failed");
            results[i].ran_successfully = 0;
            // Continue to next program, but mark this one as failed
        } else if (pid == 0) { // Child process
            // It's good practice to close standard I/O if the child
            // shouldn't print to the parent's console, but for simple
            // execution, we'll let it print.
            // Example: close(STDOUT_FILENO); close(STDERR_FILENO);

            // execve needs a null-terminated array of arguments
            // For simple execution, we just pass the program path itself as the first arg.
            char *const program_args[] = {(char *)program_path, NULL};
            char *const program_env[] = {NULL}; // No specific environment variables

            // The 'e' in execve means you provide the environment
            // The 'v' means you provide args as an array
            // If the executable is in PATH, you might use execvp instead.
            execve(program_path, program_args, program_env);

            // execve only returns if an error occurred
            perror("execve failed");
            _exit(EXIT_FAILURE); // Use _exit in child to avoid flushing parent's buffers
        } else { // Parent process
            if (waitpid(pid, &status, 0) == -1) {
                perror("waitpid failed");
                results[i].ran_successfully = 0;
            } else {
                gettimeofday(&end_time, NULL); // Get end time

                results[i].execution_time_ms = (double)(end_time.tv_sec - start_time.tv_sec) * 1000.0 +
                                               (double)(end_time.tv_usec - start_time.tv_usec) / 1000.0;

                if (WIFEXITED(status)) {
                    results[i].exit_status = WEXITSTATUS(status);
                    if (results[i].exit_status == 0) {
                        results[i].ran_successfully = 1;
                    } else {
                        printf("Program '%s' exited with non-zero status: %d\n", program_path, results[i].exit_status);
                    }
                } else if (WIFSIGNALED(status)) {
                    results[i].exit_status = WTERMSIG(status);
                    printf("Program '%s' terminated by signal: %d\n", program_path, results[i].exit_status);
                } else {
                    printf("Program '%s' terminated abnormally.\n", program_path);
                }
            }
        }
    }

    // Sort the results
    qsort(results, num_programs, sizeof(ProgramResult), compareProgramResults);

    // Display toplist
    printf("\n--- Execution Toplist ---\n");
    printf("%-4s %-40s %-15s %-10s %-10s\n", "Rank", "Program Path", "Time (ms)", "Exit Code", "Status");
    printf("----------------------------------------------------------------------------------\n");

    for (int i = 0; i < num_programs; ++i) {
        printf("%-4d %-40s %-15.3f %-10d %-10s\n",
               i + 1,
               results[i].path,
               results[i].execution_time_ms,
               results[i].exit_status,
               results[i].ran_successfully ? "SUCCESS" : "FAILED");
    }
    printf("----------------------------------------------------------------------------------\n");

    // Clean up allocated memory
    for (int i = 0; i < num_programs; ++i) {
        free(results[i].path);
    }
    free(results);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/wait.h>

#define MAX_EXECS 256

typedef struct {
    char *path;
    double elapsed_sec;
    int exit_status;
} ExecResult;

int compare_exec_result(const void *a, const void *b) {
    const ExecResult *ea = (const ExecResult *)a;
    const ExecResult *eb = (const ExecResult *)b;
    if (ea->elapsed_sec < eb->elapsed_sec) return -1;
    if (ea->elapsed_sec > eb->elapsed_sec) return 1;
    return 0;
}

double diff_seconds(struct timespec start, struct timespec end) {
    return (end.tv_sec - start.tv_sec) + 
           (end.tv_nsec - start.tv_nsec) / 1e9;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s executable1 [executable2 ...]\n", argv[0]);
        return 1;
    }

    if (argc > MAX_EXECS + 1) {
        fprintf(stderr, "Too many executables (max %d).\n", MAX_EXECS);
        return 1;
    }

    ExecResult results[MAX_EXECS];

    for (int i = 1; i < argc; ++i) {
        struct timespec t1, t2;
        if (clock_gettime(CLOCK_MONOTONIC, &t1) < 0) {
            perror("clock_gettime");
            return 1;
        }

        pid_t pid = fork();
        if (pid < 0) {
            perror("fork");
            return 1;
        } else if (pid == 0) {
            execl(argv[i], argv[i], (char *)NULL);
            // If execl fails
            perror("execl");
            exit(127);
        }

        int status;
        if (waitpid(pid, &status, 0) < 0) {
            perror("waitpid");
            return 1;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &t2) < 0) {
            perror("clock_gettime");
            return 1;
        }

        results[i-1].path = argv[i];
        results[i-1].elapsed_sec = diff_seconds(t1, t2);
        if (WIFEXITED(status))
            results[i-1].exit_status = WEXITSTATUS(status);
        else
            results[i-1].exit_status = -1;
    }

    // Sort results by execution time
    int num = argc - 1;
    qsort(results, num, sizeof(ExecResult), compare_exec_result);

    printf("Toplist (fastest to slowest):\n");
    printf("%-4s %-40s %-10s %s\n", "Rank", "Executable", "Seconds", "Exit");
    for (int i = 0; i < num; ++i) {
        printf("%-4d %-40s %-10.6f %d\n", i+1,
               results[i].path,
               results[i].elapsed_sec,
               results[i].exit_status);
    }

    return 0;
}

#include <stdio.h>
