#include <sys/time.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
#include <string.h>

// Structure to hold info about each executed program
typedef struct {
    char *path;
    double execution_time;
} ExecInfo;

// Comparison function for sorting by execution time
int compare_execution_time(const void *a, const void *b) {
    const ExecInfo *execA = (const ExecInfo *)a;
    const ExecInfo *execB = (const ExecInfo *)b;
    return (execA->execution_time > execB->execution_time) - (execA->execution_time < execB->execution_time);
}

// Function to run a program and measure time
double run_and_measure(const char *program_path) {
    pid_t pid = fork();
    struct timeval start, end;

    if (pid < 0) {
        perror("fork failed");
        return -1.0;
    } else if (pid == 0) {
        // Child process
        execl(program_path, program_path, (char *)NULL);
        perror("exec failed");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        gettimeofday(&start, NULL);
        wait(NULL);
        gettimeofday(&end, NULL);

        double elapsed = (end.tv_sec - start.tv_sec) + ((end.tv_usec - start.tv_usec) / 1000000.0);
        return elapsed;
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <program_path> [<program_path> ...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    int num_programs = argc - 1;
    ExecInfo *exec_infos = malloc(num_programs * sizeof(ExecInfo));

    for (int i = 0; i < num_programs; i++) {
        exec_infos[i].path = argv[i + 1];
        exec_infos[i].execution_time = run_and_measure(argv[i + 1]);
        if (exec_infos[i].execution_time < 0) {
            fprintf(stderr, "Error executing program: %s\n", argv[i + 1]);
            free(exec_infos);
            return EXIT_FAILURE;
        }
    }

    // Sort by execution time
    qsort(exec_infos, num_programs, sizeof(ExecInfo), compare_execution_time);

    // Display the toplist of execution times
    printf("\nExecution time toplist:\n");
    for (int i = 0; i < num_programs; i++) {
        printf("%s: %.6f seconds\n", exec_infos[i].path, exec_infos[i].execution_time);
    }

    free(exec_infos);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define MAX_NAME_LENGTH 256
#define MAX_EXECUTABLES 100

typedef struct {
    char name[MAX_NAME_LENGTH];
    double time_taken;
} ExecutableInfo;

void execute_and_measure(const char *path, ExecutableInfo *exec_info) {
    clock_t start, end;

    start = clock();
    int ret = system(path);
    end = clock();

    if (ret == -1) {
        perror("Failed to execute command");
        exec_info->time_taken = -1;  // Use -1 to indicate failure in execution
    } else {
        exec_info->time_taken = ((double)(end - start)) / CLOCKS_PER_SEC; // Calculate time taken in seconds
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <executable1> <executable2> ... <executableN>\n", argv[0]);
        return EXIT_FAILURE;
    }

    ExecutableInfo exec_infos[MAX_EXECUTABLES];
    int count = 0;

    for (int i = 1; i < argc && count < MAX_EXECUTABLES; i++, count++) {
        strncpy(exec_infos[count].name, argv[i], MAX_NAME_LENGTH);
        exec_infos[count].name[MAX_NAME_LENGTH - 1] = '\0';  // Ensure null-termination
        execute_and_measure(exec_infos[count].name, &exec_infos[count]);
    }

    // Sort the executables by time taken (simple selection sort)
    for (int i = 0; i < count - 1; i++) {
        for (int j = i + 1; j < count; j++) {
            if (exec_infos[i].time_taken > exec_infos[j].time_taken) {
                ExecutableInfo temp = exec_infos[i];
                exec_infos[i] = exec_infos[j];
                exec_infos[j] = temp;
            }
        }
    }

    // Display the toplist
    printf("\nToplist of Executables Executed:\n");
    printf("%-30s %s\n", "Executable", "Execution Time (seconds)");
    printf("------------------------------------------------------\n");
    for (int i = 0; i < count; i++) {
        if (exec_infos[i].time_taken >= 0) {
            printf("%-30s %.6f\n", exec_infos[i].name, exec_infos[i].time_taken);
        } else {
            printf("%-30s %s\n", exec_infos[i].name, "Failed to execute");
        }
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
