#include <time.h>

// Structure to hold information about each executable
typedef struct {
    char* name;
    double executionTime;
} ExecutableInfo;

// Function to run an executable and measure its execution time
double runExecutable(const char* path, char** argv) {
    pid_t pid;
    int status;
    struct timespec start, end;

    // Record start time
    clock_gettime(CLOCK_REALTIME, &start);

    // Create a new process
    pid = fork();

    if (pid == -1) {
        // Fork failed
        printf("Could not fork process for %s\n", path);
        return -1.0; // Indicate failure
    } else if (pid == 0) {
        // Child process
        // Execute the executable
        execvp(path, argv);
        // If execvp returns, it means an error occurred
        printf("Could not execute %s\n", path);
        exit(1);
    } else {
        // Parent process
        // Wait for the child to finish
        waitpid(pid, &status, 0);
        // Record end time
        clock_gettime(CLOCK_REALTIME, &end);

        // Calculate execution time in seconds
        double executionTime = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1.0e9;

        return executionTime;
    }
}

int main(int argc, char** argv) {
    if (argc < 2) {
        printf("Usage: %s executable_path [executable_path ...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    int numExecutables = argc - 1;
    ExecutableInfo* executables = malloc(numExecutables * sizeof(ExecutableInfo));
    if (!executables) {
        printf("Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < numExecutables; i++) {
        executables[i].name = argv[i + 1];
        char** executableArgs = (char**)malloc(3 * sizeof(char*));
        executableArgs[0] = argv[i + 1];
        executableArgs[1] = "--test"; // Example argument, modify as needed
        executableArgs[2] = NULL;

        executables[i].executionTime = runExecutable(argv[i + 1], executableArgs);
        free(executableArgs);
    }

    // Sort executables based on execution time
    for (int i = 0; i < numExecutables - 1; i++) {
        for (int j = i + 1; j < numExecutables; j++) {
            if (executables[i].executionTime > executables[j].executionTime) {
                // Swap
                ExecutableInfo temp = executables[i];
                executables[i] = executables[j];
                executables[j] = temp;
            }
        }
    }

    // Display toplist
    printf("Toplist of executables by execution time:\n");
    for (int i = 0; i < numExecutables; i++) {
        printf("%d. %s: %.6f seconds\n", i + 1, executables[i].name, executables[i].executionTime);
    }

    free(executables);

    return EXIT_SUCCESS;
}

