    // Calculate and print days between dates
    int daysDifference = daysBetweenDates(day1, month1, year1, 
                                          day2, month2, year2);

    if (daysDifference != -1) {
        printf("Number of days between the dates: %d\n", daysDifference);
    }

    return 0;
}

#include <stdio.h>
#include <stdbool.h>

// Structure to hold a date
struct Date {
    int day;
    int month;
    int year;
};

// Function to check if a year is a leap year
bool isLeapYear(int year) {
    if (year % 4 != 0) {
        return false;
    } else if (year % 100 != 0) {
        return true;
    } else {
        return (year % 400 == 0);
    }
}

// Function to get the number of days in a month
int daysInMonth(int month, int year) {
    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            return 31;
        case 4: case 6: case 9: case 11:
            return 30;
        case 2:
            return isLeapYear(year) ? 29 : 28;
        default:
            return 0; // invalid month
    }
}

// Function to check if a date is valid
bool isValidDate(struct Date date) {
    if (date.year < 1) return false;
    if (date.month < 1 || date.month > 12) return false;
    if (date.day < 1 || date.day > daysInMonth(date.month, date.year)) return false;
    return true;
}

// Function to convert a date to the number of days since a reference date
long dateToDays(struct Date date) {
    long days = 0;

    // Add days from years
    for (int y = 1; y < date.year; y++) {
        days += isLeapYear(y) ? 366 : 365;
    }

    // Add days from months
    for (int m = 1; m < date.month; m++) {
        days += daysInMonth(m, date.year);
    }

    // Add days
    days += date.day;

    return days;
}

// Function to calculate the difference between two dates in days
long daysBetweenDates(struct Date date1, struct Date date2) {
    long days1 = dateToDays(date1);
    long days2 = dateToDays(date2);
    return days2 - days1;
}

