    if (!isValidDate(date1) || !isValidDate(date2)) {
        printf("Invalid date entered!\n");
        return 1;
    }

    long difference = daysBetweenDates(date1, date2);

    printf("Number of days between the two dates: %ld\n", difference < 0 ? -difference : difference);

    return 0;
}

#include <stdio.h>
#include <stdlib.h> // For exit()
#include <stdbool.h> // For bool type

// Structure to represent a date
typedef struct {
    int day;
    int month;
    int year;
} Date;

// Function to check if a year is a leap year
bool isLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

// Function to get the number of days in a given month of a given year
int getDaysInMonth(int month, int year) {
    switch (month) {
        case 1:  // January
        case 3:  // March
        case 5:  // May
        case 7:  // July
        case 8:  // August
        case 10: // October
        case 12: // December
            return 31;
        case 4:  // April
        case 6:  // June
        case 9:  // September
        case 11: // November
            return 30;
        case 2:  // February
            return isLeapYear(year) ? 29 : 28;
        default:
            return 0; // Invalid month
    }
}

// Function to validate a date
bool isValidDate(Date d) {
    if (d.year < 1 || d.month < 1 || d.month > 12 || d.day < 1) {
        return false;
    }
    return d.day <= getDaysInMonth(d.month, d.year);
}

// Function to read a date from the user
Date readDate(const char *prompt) {
    Date d;
    printf("%s (DD MM YYYY): ", prompt);
    while (scanf("%d %d %d", &d.day, &d.month, &d.year) != 3 || !isValidDate(d)) {
        printf("Invalid date. Please enter again (DD MM YYYY): ");
        // Clear input buffer
        while (getchar() != '\n');
    }
    return d;
}

// Function to compare two dates
// Returns -1 if d1 < d2, 0 if d1 == d2, 1 if d1 > d2
int compareDates(Date d1, Date d2) {
    if (d1.year != d2.year) {
        return d1.year - d2.year;
    }
    if (d1.month != d2.month) {
        return d1.month - d2.month;
    }
    return d1.day - d2.day;
}

// Function to calculate the number of days from a reference date (e.g., 00/00/0000)
// This is a common approach to find the difference between two dates:
// 1. Convert both dates to a total number of days since a common epoch.
// 2. Subtract the two total day counts.
long int countDaysFromEpoch(Date d) {
    long int total_days = 0;
    int i;

    // Add days for full years passed
    for (i = 1; i < d.year; i++) {
        total_days += isLeapYear(i) ? 366 : 365;
    }

    // Add days for full months passed in the current year
    for (i = 1; i < d.month; i++) {
        total_days += getDaysInMonth(i, d.year);
    }

    // Add days for the current month
    total_days += d.day;

    return total_days;
}

int main() {
    Date date1, date2;
    long int days1, days2;
    int diff_days;

    printf("--- Calculate Days Between Two Dates ---\n");

    date1 = readDate("Enter the first date");
    date2 = readDate("Enter the second date");

    // Ensure date1 is chronologically before or equal to date2 for consistent calculation
    // Although the absolute difference will be the same regardless,
    // this helps in understanding the calculation
    if (compareDates(date1, date2) > 0) {
        Date temp = date1;
        date1 = date2;
        date2 = temp;
        printf("\nDates swapped to ensure first date is chronologically earlier.\n");
    }

    days1 = countDaysFromEpoch(date1);
    days2 = countDaysFromEpoch(date2);

    diff_days = abs(days2 - days1); // Use abs to ensure a positive difference

    printf("\n");
    printf("Date 1: %02d/%02d/%04d\n", date1.day, date1.month, date1.year);
    printf("Date 2: %02d/%02d/%04d\n", date2.day, date2.month, date2.year);
    printf("Number of days between them: %d days\n", diff_days);

    return 0;
}

#include <stdio.h>
