// Function to check for leap year
int isLeap(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

// Number of days in all months from January to Dec
const int monthDays[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

// This function counts number of days since the 0000/00/00 to given date
int countDays(int d, int m, int y) {
    int n = y * 365 + d;

    // Add days for months in current year
    for (int i=0; i<m-1; i++)
        n += monthDays[i];

    // Add a day for every leap year
    n += (y/4) - (y/100) + (y/400);

    // If current year is leap and month <= 2, subtract 1 day
    if (m <= 2) {
        if (isLeap(y))
            n -= 1;
    }

    return n;
}

int main() {
    int d1, m1, y1;
    int d2, m2, y2;

    printf("Enter first date (DD MM YYYY): ");
    scanf("%d %d %d", &d1, &m1, &y1);

    printf("Enter second date (DD MM YYYY): ");
    scanf("%d %d %d", &d2, &m2, &y2);

    // Count days for both dates
    int n1 = countDays(d1, m1, y1);
    int n2 = countDays(d2, m2, y2);

    printf("Number of days between: %d\n", abs(n1 - n2));

    return 0;
}

#include <stdio.h>

// Function to check for leap year
int isLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

// Function to convert date to Julian Day Number
int dateToJulian(int day, int month, int year) {
    const int daysPerMonth[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

    // Adjust February for leap years
    int daysInMonth = daysPerMonth[month - 1];
    if (month == 2 && isLeapYear(year)) {
        daysInMonth = 29;
    }

    // Julian Day Number calculation
    int julianDay = day;
    for (int i = 0; i < month - 1; ++i) {
        julianDay += daysPerMonth[i];
        if (i == 1 && isLeapYear(year)) {
            julianDay += 1; // Add extra day for leap February
        }
    }

    // Add days for each of the years passed since the beginning
    julianDay += (year - 1) * 365;
    julianDay += (year - 1) / 4;  // Leap years
    julianDay -= (year - 1) / 100; // Non-leap centuries
    julianDay += (year - 1) / 400; // Leap centuries

    return julianDay;
}

// Function to calculate difference in days between two dates
int daysBetween(int day1, int month1, int year1, int day2, int month2, int year2) {
    int julian1 = dateToJulian(day1, month1, year1);
    int julian2 = dateToJulian(day2, month2, year2);

    return julian2 - julian1;
}

int main() {
    int day1, month1, year1;
    int day2, month2, year2;

    printf("Enter first date (day month year): ");
    scanf("%d %d %d", &day1, &month1, &year1);

    printf("Enter second date (day month year): ");
    scanf("%d %d %d", &day2, &month2, &year2);

    int result = daysBetween(day1, month1, year1, day2, month2, year2);
    printf("Number of days between: %d\n", result);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

struct Date {
    int year;
    int month;
    int day;
};

// Function to read a date from user input
void readDate(struct Date *date) {
    printf("Enter date (YYYY MM DD): ");
    scanf("%d %d %d", &date->year, &date->month, &date->day);
}

// Function to calculate the difference in days between two dates
int daysBetween(struct Date date1, struct Date date2) {
    struct tm tm1 = {0}, tm2 = {0};

    // Set the first date
    tm1.tm_year = date1.year - 1900; // year since 1900
    tm1.tm_mon = date1.month - 1;    // months since January (0-11)
    tm1.tm_mday = date1.day;

    // Set the second date
    tm2.tm_year = date2.year - 1900; // year since 1900
    tm2.tm_mon = date2.month - 1;    // months since January (0-11)
    tm2.tm_mday = date2.day;

    // Convert to time_t
    time_t time1 = mktime(&tm1);
    time_t time2 = mktime(&tm2);

    // Calculate the difference in seconds and convert to days
    double difference = difftime(time2, time1);
    return difference / (60 * 60 * 24); // convert seconds to days
}

int main() {
    struct Date date1, date2;

    // Read the first date
    readDate(&date1);
    // Read the second date
    readDate(&date2);

    // Calculate the number of days between the two dates
    int days = daysBetween(date1, date2);

    // Display the result
    printf("The number of days between the two dates is: %d days\n", days);

    return 0;
}

#include <stdio.h>
#include <time.h>

// Structure to represent a date
typedef struct {
    int day;
    int month;
    int year;
} Date;

// Function to calculate the number of days between two dates
int date_diff(Date date1, Date date2) {
    struct tm t1 = {0};
    t1.tm_mday = date1.day;
    t1.tm_mon = date1.month - 1;  // months are 0-based
    t1.tm_year = date1.year - 1900;  // years are numbered from 1900

    struct tm t2 = {0};
    t2.tm_mday = date2.day;
    t2.tm_mon = date2.month - 1;  // months are 0-based
    t2.tm_year = date2.year - 1900;  // years are numbered from 1900

    time_t time1 = mktime(&t1);
    time_t time2 = mktime(&t2);

    return difftime(time2, time1) / (60 * 60 * 24);
}

int main() {
    Date date1, date2;

    printf("Enter first date (dd mm yyyy): ");
    scanf("%d %d %d", &date1.day, &date1.month, &date1.year);

    printf("Enter second date (dd mm yyyy): ");
    scanf("%d %d %d", &date2.day, &date2.month, &date2.year);

    int diff = date_diff(date1, date2);

    if (diff > 0) {
        printf("There are %d days between the two dates.\n", diff);
    } else if (diff < 0) {
        printf("There are %d days between the two dates (date2 is earlier).\n", -diff);
    } else {
        printf("The two dates are the same.\n");
    }

    return 0;
}

#include <stdio.h>

// Function to check if a year is a leap year
int isLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

// Function to get the number of days in a month
int daysInMonth(int month, int year) {
    int days[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (month == 2 && isLeapYear(year)) {
        return 29;
    }
    return days[month - 1];
}

// Function to calculate the number of days from the start of year 0 to a given date
int daysFromStart(int day, int month, int year) {
    int days = 0;
    for (int y = 0; y < year; y++) {
        days += 365 + isLeapYear(y);
    }
    for (int m = 1; m < month; m++) {
        days += daysInMonth(m, year);
    }
    days += day;
    return days;
}

// Function to calculate the number of days between two dates
int daysBetweenDates(int day1, int month1, int year1, int day2, int month2, int year2) {
    int days1 = daysFromStart(day1, month1, year1);
    int days2 = daysFromStart(day2, month2, year2);
    return abs(days1 - days2);
}

int main() {
    int day1, month1, year1;
    int day2, month2, year2;

    printf("Enter the first date (day month year): ");
    scanf("%d %d %d", &day1, &month1, &year1);

    printf("Enter the second date (day month year): ");
    scanf("%d %d %d", &day2, &month2, &year2);

    int daysBetween = daysBetweenDates(day1, month1, year1, day2, month2, year2);

    printf("Number of days between the two dates: %d\n", daysBetween);

    return 0;
}

