#include <stdio.h>
#include <limits.h> // For CHAR_BIT (number of bits in a char)

// --- Helper function to print a byte in binary format ---
void print_byte_binary(unsigned char byte, const char* label) {
    if (label) {
        printf("%-20s: ", label);
    }
    for (int i = CHAR_BIT - 1; i >= 0; i--) {
        printf("%d", (byte >> i) & 1);
    }
    printf(" (0x%02X, %d)\n", byte, byte);
}

// --- Bit Rotation Functions ---

// Rotate a byte left by 'n' positions
unsigned char rotate_left(unsigned char byte, int n) {
    // Ensure n is within 0 to CHAR_BIT-1
    n %= CHAR_BIT;
    // (byte << n) shifts the bits left
    // (byte >> (CHAR_BIT - n)) brings the 'rotated off' bits from the left back to the right
    return (byte << n) | (byte >> (CHAR_BIT - n));
}

// Rotate a byte right by 'n' positions
unsigned char rotate_right(unsigned char byte, int n) {
    // Ensure n is within 0 to CHAR_BIT-1
    n %= CHAR_BIT;
    // (byte >> n) shifts the bits right
    // (byte << (CHAR_BIT - n)) brings the 'rotated off' bits from the right back to the left
    return (byte >> n) | (byte << (CHAR_BIT - n));
}

int main() {
    unsigned char byte1 = 0b10110010; // 0xB2 in hex, 178 in decimal
    unsigned char byte2 = 0b01011101; // 0x5D in hex, 93 in decimal
    unsigned char result;

    printf("--- Demonstrating Binary Operations on Bytes (8-bit unsigned char) ---\n\n");

    // Print initial bytes
    print_byte_binary(byte1, "Initial Byte 1");
    print_byte_binary(byte2, "Initial Byte 2");
    printf("\n");

    // --- 1. Bitwise AND (&) ---
    printf("--- Bitwise AND (&) ---\n");
    //     10110010 (byte1)
    // AND 01011101 (byte2)
    // -----------
    //     00010000
    result = byte1 & byte2;
    print_byte_binary(result, "byte1 & byte2");
    printf("  (Sets a bit if the corresponding bits in *both* operands are 1)\n\n");

    // --- 2. Bitwise OR (|) ---
    printf("--- Bitwise OR (|) ---\n");
    //    10110010 (byte1)
    // OR 01011101 (byte2)
    // -----------
    //    11111111
    result = byte1 | byte2;
    print_byte_binary(result, "byte1 | byte2");
    printf("  (Sets a bit if the corresponding bit in *either* operand is 1)\n\n");

    // --- 3. Bitwise XOR (^) ---
    printf("--- Bitwise XOR (^) ---\n");
    //     10110010 (byte1)
    // XOR 01011101 (byte2)
    // -----------
    //     11101111
    result = byte1 ^ byte2;
    print_byte_binary(result, "byte1 ^ byte2");
    printf("  (Sets a bit if the corresponding bits are *different*)\n\n");

    // --- 4. Bitwise NOT (~) ---
    printf("--- Bitwise NOT (~) ---\n");
    // ~10110010 (byte1)
    // -----------
    //  01001101
    result = ~byte1; // Applying NOT to byte1
    print_byte_binary(result, "~byte1 (NOT)");
    printf("  (Inverts all bits: 0 becomes 1, 1 becomes 0)\n");
    // Demonstrate NOT on byte2 as well
    result = ~byte2;
    print_byte_binary(result, "~byte2 (NOT)");
    printf("\n");

    // --- 5. Left Shift (<<) ---
    printf("--- Left Shift (<<) ---\n");
    int shift_amount_left = 3;
    // Original: 10110010
    // Shifted:  10010000 (after 3 shifts to the left, 3 zeros fill on the right)
    result = byte1 << shift_amount_left;
    printf("  byte1 << %d:\n", shift_amount_left);
    print_byte_binary(byte1, "  Original byte1");
    print_byte_binary(result, "  Shifted result");
    printf("  (Equivalent to multiplying by 2^%d, fills with zeros on the right)\n", shift_amount_left);

    shift_amount_left = 5;
    result = byte2 << shift_amount_left;
    printf("  byte2 << %d:\n", shift_amount_left);
    print_byte_binary(byte2, "  Original byte2");
    print_byte_binary(result, "  Shifted result");
    printf("\n");

    // --- 6. Right Shift (>>) ---
    printf("--- Right Shift (>>) ---\n");
    int shift_amount_right = 2;
    // Original: 10110010
    // Shifted:  00101100 (after 2 shifts to the right, 2 zeros fill on the left for unsigned)
    result = byte1 >> shift_amount_right;
    printf("  byte1 >> %d:\n", shift_amount_right);
    print_byte_binary(byte1, "  Original byte1");
    print_byte_binary(result, "  Shifted result");
    printf("  (Equivalent to dividing by 2^%d, fills with zeros on the left for unsigned)\n", shift_amount_right);

    shift_amount_right = 4;
    result = byte2 >> shift_amount_right;
    printf("  byte2 >> %d:\n", shift_amount_right);
    print_byte_binary(byte2, "  Original byte2");
    print_byte_binary(result, "  Shifted result");
    printf("\n");

    // --- 7. Bit Rotation Left (Custom Function) ---
    printf("--- Bit Rotation Left (ror_left) ---\n");
    int rotate_amount_left = 3;
    // Original: 10110010
    // After 3 left rotations:
    // Move 101 to the right:  10110010 -> 10010 (left 3 bits shifted out: 101)
    //                        ->    101 (wrap around)
    // Result: 10010 + 101 = 10010101
    result = rotate_left(byte1, rotate_amount_left);
    printf("  rotate_left(byte1, %d):\n", rotate_amount_left);
    print_byte_binary(byte1, "  Original byte1");
    print_byte_binary(result, "  Rotated result");
    printf("  (Bits shifted off the left end wrap around to the right end)\n");

    rotate_amount_left = 5;
    result = rotate_left(byte2, rotate_amount_left);
    printf("  rotate_left(byte2, %d):\n", rotate_amount_left);
    print_byte_binary(byte2, "  Original byte2");
    print_byte_binary(result, "  Rotated result");
    printf("\n");

    // --- 8. Bit Rotation Right (Custom Function) ---
    printf("--- Bit Rotation Right (ror_right) ---\n");
    int rotate_amount_right = 2;
    // Original: 10110010
    // After 2 right rotations:
    // Move 10 to the left:  10110010 -> 101100 (right 2 bits shifted out: 10)
    //                       -> 10   (wrap around)
    // Result: 10 + 101100 = 10101100
    result = rotate_right(byte1, rotate_amount_right);
    printf("  rotate_right(byte1, %d):\n", rotate_amount_right);
    print_byte_binary(byte1, "  Original byte1");
    print_byte_binary(result, "  Rotated result");
    printf("  (Bits shifted off the right end wrap around to the left end)\n");

    rotate_amount_right = 4;
    result = rotate_right(byte2, rotate_amount_right);
    printf("  rotate_right(byte2, %d):\n", rotate_amount_right);
    print_byte_binary(byte2, "  Original byte2");
    print_byte_binary(result, "  Rotated result");
    printf("\n");

    return 0;
}

