// Rotate left for 8-bit values
uint8_t rotate_left(uint8_t value, unsigned int n) {
    return (value << n) | (value >> (8 - n));
}

// Rotate right for 8-bit values
uint8_t rotate_right(uint8_t value, unsigned int n) {
    return (value >> n) | (value << (8 - n));
}

// Helper: print byte as binary
