    for (int i = 7; i >= 0; i--)
        putchar((x & (1 << i)) ? '1' : '0');
}

int main() {
    uint8_t a = 0x5A; // 01011010
    uint8_t b = 0x3C; // 00111100

    printf("a        = 0x%02X = ", a); print_binary(a); printf("\n");
    printf("b        = 0x%02X = ", b); print_binary(b); printf("\n\n");

    // Bitwise AND
    printf("a & b    = 0x%02X = ", a & b); print_binary(a & b); printf("   (AND)\n");
    // Bitwise OR
    printf("a | b    = 0x%02X = ", a | b); print_binary(a | b); printf("   (OR)\n");
    // Bitwise XOR
    printf("a ^ b    = 0x%02X = ", a ^ b); print_binary(a ^ b); printf("   (XOR)\n");
    // Bitwise NOT
    printf("~a       = 0x%02X = ", (uint8_t)~a); print_binary((uint8_t)~a); printf("   (NOT)\n\n");

    // Bitshift left (2 bits)
    printf("a << 2   = 0x%02X = ", a << 2); print_binary(a << 2); printf("   (Left shift)\n");
    // Bitshift right (2 bits)
    printf("a >> 2   = 0x%02X = ", a >> 2); print_binary(a >> 2); printf("   (Right shift)\n\n");

    // Rotate left (2 bits)
    printf("rol(a,2) = 0x%02X = ", rotate_left(a, 2)); print_binary(rotate_left(a, 2)); printf("   (Left rotate)\n");
    // Rotate right (2 bits)
    printf("ror(a,2) = 0x%02X = ", rotate_right(a, 2)); print_binary(rotate_right(a, 2)); printf("   (Right rotate)\n");

    return 0;
}

