// Function to perform left rotation
unsigned char left_rotate(unsigned char value, unsigned int shift) {
    return (value << shift) | (value >> (8 - shift));
}

// Function to perform right rotation
unsigned char right_rotate(unsigned char value, unsigned int shift) {
    return (value >> shift) | (value << (8 - shift));
}

