#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

#define DIMENSIONS 2  // 2D simulation
#define NUM_PARTICLES 100
#define NUM_STEPS 1000
#define STEP_SIZE 1.0

// Particle structure to track position
typedef struct {
    double position[DIMENSIONS];
} Particle;

// Function to initialize particles at origin
void initialize_particles(Particle particles[], int num_particles) {
    for (int i = 0; i < num_particles; i++) {
        for (int j = 0; j < DIMENSIONS; j++) {
            particles[i].position[j] = 0.0;
        }
    }
}

// Generate random step
void generate_random_step(double step[]) {
    for (int i = 0; i < DIMENSIONS; i++) {
        // Uniform distribution between -1 and 1
        step[i] = (2.0 * rand() / RAND_MAX - 1.0) * STEP_SIZE;
    }
}

// Move particle
void move_particle(Particle *particle, double step[]) {
    for (int i = 0; i < DIMENSIONS; i++) {
        particle->position[i] += step[i];
    }
}

// Calculate particle displacement
double calculate_displacement(Particle *particle) {
    double displacement = 0.0;
    for (int i = 0; i < DIMENSIONS; i++) {
        displacement += particle->position[i] * particle->position[i];
    }
    return sqrt(displacement);
}

// Simulate Brownian motion
void simulate_brownian_motion(Particle particles[], int num_particles, int num_steps) {
    double step[DIMENSIONS];

    for (int step_count = 0; step_count < num_steps; step_count++) {
        for (int i = 0; i < num_particles; i++) {
            // Generate random step
            generate_random_step(step);

            // Move particle
            move_particle(&particles[i], step);
        }
    }
}

// Print particle statistics
void print_particle_statistics(Particle particles[], int num_particles, int num_steps) {
    printf("Brownian Motion Simulation Results:\n");
    printf("Number of Particles: %d\n", num_particles);
    printf("Number of Steps: %d\n", num_steps);
    printf("Step Size: %f\n\n", STEP_SIZE);

    double total_displacement = 0.0;
    double max_displacement = 0.0;
    double min_displacement = INFINITY;

    for (int i = 0; i < num_particles; i++) {
        double displacement = calculate_displacement(&particles[i]);
        total_displacement += displacement;

        if (displacement > max_displacement) {
            max_displacement = displacement;
        }
        if (displacement < min_displacement) {
            min_displacement = displacement;
        }
    }

    double mean_displacement = total_displacement / num_particles;

    printf("Displacement Statistics:\n");
    printf("Mean Displacement: %f\n", mean_displacement);
    printf("Maximum Displacement: %f\n", max_displacement);
    printf("Minimum Displacement: %f\n", min_displacement);
}

int main() {
    // Seed random number generator
    srand(time(NULL));

    // Create array of particles
    Particle particles[NUM_PARTICLES];

    // Initialize particles at origin
    initialize_particles(particles, NUM_PARTICLES);

    // Simulate Brownian motion
    simulate_brownian_motion(particles, NUM_PARTICLES, NUM_STEPS);

    // Print statistics
    print_particle_statistics(particles, NUM_PARTICLES, NUM_STEPS);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

#define DIM 2          // 2D space
#define DT 0.01        // Time step
#define DIFFUSION 1.0  // Diffusion coefficient

// Structure to represent a particle
typedef struct {
    double position[DIM];
} Particle;

// Function to initialize particles
void initialize_particles(Particle *particles, int num_particles) {
    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < num_particles; i++) {
        for (int j = 0; j < DIM; j++) {
            particles[i].position[j] = 0.0; // Initialize all particles at the origin
        }
    }
}

// Function to update particle positions based on Brownian motion
void update_particles(Particle *particles, int num_particles) {
    for (int i = 0; i < num_particles; i++) {
        for (int j = 0; j < DIM; j++) {
            // Generate a random displacement using a normal distribution
            double displacement = sqrt(2 * DIFFUSION * DT) * (2.0 * rand() / RAND_MAX - 1.0);
            particles[i].position[j] += displacement;
        }
    }
}

// Function to print particle positions
void print_particles(Particle *particles, int num_particles, int step) {
    printf("Step %d:\n", step);
    for (int i = 0; i < num_particles; i++) {
        printf("Particle %d: (%.2f, %.2f)\n", i, particles[i].position[0], particles[i].position[1]);
    }
    printf("\n");
}

int main() {
    int num_particles = 100; // Number of particles
    int num_steps = 100;     // Number of time steps

    // Allocate memory for particles
    Particle *particles = (Particle *)malloc(num_particles * sizeof(Particle));
    if (particles == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Initialize particles
    initialize_particles(particles, num_particles);

    // Simulate Brownian motion
    for (int step = 0; step < num_steps; step++) {
        update_particles(particles, num_particles);
        if (step % 10 == 0) { // Print positions every 10 steps
            print_particles(particles, num_particles, step);
        }
    }

    // Free allocated memory
    free(particles);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
