// Structure to represent a particle
typedef struct {
    double x; // x-coordinate
    double y; // y-coordinate
} Particle;

// Function to initialize particles randomly within a given range
void initialize_particles(Particle *particles, int num_particles, double x_min, double x_max, double y_min, double y_max) {
    for (int i = 0; i < num_particles; i++) {
        particles[i].x = x_min + (x_max - x_min) * ((double)rand() / RAND_MAX);
        particles[i].y = y_min + (y_max - y_min) * ((double)rand() / RAND_MAX);
    }
}

// Function to simulate one step of Brownian motion for a single particle
void simulate_brownian_step(Particle *p, double step_size) {
    // Generate two random numbers for dx and dy
    // Using Box-Muller transform for Gaussian distribution
    double u1 = (double)rand() / RAND_MAX;
    double u2 = (double)rand() / RAND_MAX;

    // Ensure u1 is not zero to avoid log(0)
    if (u1 == 0.0) u1 = 1e-6; 

    // Gaussian random numbers (mean 0, std dev 1)
    double z1 = sqrt(-2.0 * log(u1)) * cos(2.0 * M_PI * u2);
    double z2 = sqrt(-2.0 * log(u1)) * sin(2.0 * M_PI * u2);

    // Apply the step size to the Gaussian random numbers
    p->x += step_size * z1;
    p->y += step_size * z2;
}

// Function to print the current state of particles (for small simulations)
void print_particles(const Particle *particles, int num_particles) {
    printf("Particle Positions:\n");
    for (int i = 0; i < num_particles; i++) {
        printf("Particle %d: (%.4f, %.4f)\n", i + 1, particles[i].x, particles[i].y);
    }
    printf("\n");
}

// Function to save particle positions to a CSV file
void save_particles_to_csv(const Particle *particles, int num_particles, const char *filename, int step) {
    FILE *fp = fopen(filename, "a"); // Append mode
    if (fp == NULL) {
        perror("Error opening file");
        return;
    }

    if (step == 0) { // Write header only for the first step
        fprintf(fp, "Step,ParticleID,X,Y\n");
    }

    for (int i = 0; i < num_particles; i++) {
        fprintf(fp, "%d,%d,%.6f,%.6f\n", step, i + 1, particles[i].x, particles[i].y);
    }

    fclose(fp);
}

