#define SQUARE_SIZE      100.0

typedef struct {
    double x, y;
} Particle;

// Generate a random double between min and max
double rand_double(double min, double max) {
    return min + (double)rand() / ((double)RAND_MAX / (max - min));
}

int main() {
    Particle particles[NUM_PARTICLES];
    srand((unsigned int) time(NULL));

    // Initialize particle positions randomly within the square
    for (int i = 0; i < NUM_PARTICLES; ++i) {
        particles[i].x = rand_double(0, SQUARE_SIZE);
        particles[i].y = rand_double(0, SQUARE_SIZE);
    }

    // Simulate Brownian motion
    for (int step = 0; step < NUM_STEPS; ++step) {
        for (int i = 0; i < NUM_PARTICLES; ++i) {
            double theta = rand_double(0, 2 * M_PI);
            double r = rand_double(0, MAX_STEP);

            // Optionally: constant step size (set r = MAX_STEP)
            // Update positions
            particles[i].x += r * cos(theta);
            particles[i].y += r * sin(theta);

            // Keep the particle inside the square
            if (particles[i].x < 0) particles[i].x = 0;
            if (particles[i].y < 0) particles[i].y = 0;
            if (particles[i].x > SQUARE_SIZE) particles[i].x = SQUARE_SIZE;
            if (particles[i].y > SQUARE_SIZE) particles[i].y = SQUARE_SIZE;
