#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Number of particles and steps in the simulation
#define NUM_PARTICLES 100
#define NUM_STEPS 1000

// Function to simulate the random walk of particles
void simulateBrownianMotion(int numParticles, int numSteps, double (*positions)[2]) {
    for (int i = 0; i < numParticles; ++i) {
        // Initial positions are set to the origin (0,0)
        positions[i][0] = 0.0;
        positions[i][1] = 0.0;
    }

    for (int step = 0; step < numSteps; ++step) {
        for (int i = 0; i < numParticles; ++i) {
            // Generate random steps: -1, 0, or 1
            double dx = (rand() % 3) - 1;
            double dy = (rand() % 3) - 1;

            // Update particle position
            positions[i][0] += dx;
            positions[i][1] += dy;
        }
    }
}

// Function to print the final positions of the particles
void printParticlePositions(int numParticles, double (*positions)[2]) {
    printf("Final positions of the particles:\n");
    for (int i = 0; i < numParticles; ++i) {
        printf("Particle %d: x = %.2f, y = %.2f\n", i, positions[i][0], positions[i][1]);
    }
}

int main() {
    // Seed the random number generator
    srand((unsigned int)time(NULL));

    // Array to store the positions of the particles
    double positions[NUM_PARTICLES][2];

    // Simulate the Brownian motion
    simulateBrownianMotion(NUM_PARTICLES, NUM_STEPS, positions);

    // Print the results
    printParticlePositions(NUM_PARTICLES, positions);

    return 0;
}

#include <SDL2/SDL.h>
#include <stdlib.h>
#include <time.h>

#define WIDTH 800
#define HEIGHT 600
#define NUM_PARTICLES 100

typedef struct {
    float x;
    float y;
} Particle;

void initialize_particles(Particle particles[], int num_particles) {
    for (int i = 0; i < num_particles; i++) {
        particles[i].x = WIDTH / 2;
        particles[i].y = HEIGHT / 2;
    }
}

void update_particles(Particle particles[], int num_particles) {
    for (int i = 0; i < num_particles; i++) {
        float angle = (rand() % 360) * (3.14159f / 180.0f); // Random angle in radians
        float speed = 2.0f; // Step size
        particles[i].x += speed * cos(angle);
        particles[i].y += speed * sin(angle);

        // Keep particles within bounds
        if (particles[i].x < 0) particles[i].x = 0;
        if (particles[i].x >= WIDTH) particles[i].x = WIDTH - 1;
        if (particles[i].y < 0) particles[i].y = 0;
        if (particles[i].y >= HEIGHT) particles[i].y = HEIGHT - 1;
    }
}

void draw_particles(SDL_Renderer *renderer, Particle particles[], int num_particles) {
    SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255); // Set color to white
    for (int i = 0; i < num_particles; i++) {
        SDL_RenderDrawPoint(renderer, (int)particles[i].x, (int)particles[i].y);
    }
}

int main(int argc, char *argv[]) {
    // Initialize random seed
    srand(time(NULL));

    // SDL initialization
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("Could not initialize SDL: %s\n", SDL_GetError());
        return 1;
    }

    SDL_Window *window = SDL_CreateWindow("Brownian Motion", SDL_WINDOWPOS_UNDEFINED, SDL_WINDOWPOS_UNDEFINED, WIDTH, HEIGHT, 0);
    if (!window) {
        printf("Could not create window: %s\n", SDL_GetError());
        SDL_Quit();
        return 1;
    }

    SDL_Renderer *renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (!renderer) {
        printf("Could not create renderer: %s\n", SDL_GetError());
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 1;
    }

    Particle particles[NUM_PARTICLES];
    initialize_particles(particles, NUM_PARTICLES);

    int running = 1;
    SDL_Event event;

    while (running) {
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                running = 0;
            }
        }

        update_particles(particles, NUM_PARTICLES);

        SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255); // Set background color to black
        SDL_RenderClear(renderer);

        draw_particles(renderer, particles, NUM_PARTICLES);

        SDL_RenderPresent(renderer);
        SDL_Delay(10); // Control the speed of the simulation
    }

    // Clean up
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define DIMENSION 100 // The size of our 2D environment
#define MAX_STEP 10   // Maximum step size in any direction

// Structure to represent a particle
typedef struct {
    int x;
    int y;
} Particle;

// Function to initialize particles with random positions within the environment
void initializeParticles(Particle* particles, int numParticles) {
    for (int i = 0; i < numParticles; i++) {
        particles[i].x = rand() % DIMENSION;
        particles[i].y = rand() % DIMENSION;
    }
}

// Function to move a particle in a random direction
void moveParticle(Particle* particle) {
    int dx = (rand() % (2 * MAX_STEP + 1)) - MAX_STEP; // Random movement between -MAX_STEP and MAX_STEP
    int dy = (rand() % (2 * MAX_STEP + 1)) - MAX_STEP;

    // Ensure particle stays within the boundaries of the environment
    particle->x = (particle->x + dx + DIMENSION) % DIMENSION;
    particle->y = (particle->y + dy + DIMENSION) % DIMENSION;
}

// Function to simulate Brownian motion for all particles
void simulateBrownianMotion(Particle* particles, int numParticles, int steps) {
    for (int step = 0; step < steps; step++) {
        for (int i = 0; i < numParticles; i++) {
            moveParticle(&particles[i]);
        }
        // Optionally print positions at each step to visualize the movement
        // printf("Step %d:\n", step);
        // for (int i = 0; i < numParticles; i++) {
        //     printf("Particle %d: (%d, %d)\n", i, particles[i].x, particles[i].y);
        // }
    }
}

int main() {
    int numParticles;
    printf("Enter the number of particles: ");
    scanf("%d", &numParticles);

    int steps;
    printf("Enter the number of steps for the simulation: ");
    scanf("%d", &steps);

    srand(time(NULL)); // Seed for random number generation

    Particle* particles = malloc(numParticles * sizeof(Particle));
    if (!particles) {
        printf("Memory allocation failed\n");
        return 1;
    }

    initializeParticles(particles, numParticles);

    printf("Initial positions:\n");
    for (int i = 0; i < numParticles; i++) {
        printf("Particle %d: (%d, %d)\n", i, particles[i].x, particles[i].y);
    }

    simulateBrownianMotion(particles, numParticles, steps);

    printf("\nFinal positions:\n");
    for (int i = 0; i < numParticles; i++) {
        printf("Particle %d: (%d, %d)\n", i, particles[i].x, particles[i].y);
    }

    free(particles);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>

#define WIDTH 100
#define HEIGHT 100
#define MAX_TIME_STEPS 1000
#define MAX_PARTICLES 100

typedef struct {
    double x;
    double y;
} Particle;

void initialize_particles(Particle *particles, int num_particles) {
    for (int i = 0; i < num_particles; i++) {
        particles[i].x = (double)rand() / RAND_MAX * WIDTH;
        particles[i].y = (double)rand() / RAND_MAX * HEIGHT;
    }
}

void update_particles(Particle *particles, int num_particles) {
    for (int i = 0; i < num_particles; i++) {
        double dx = (double)rand() / RAND_MAX * 2 - 1; // Random displacement between -1 and 1
        double dy = (double)rand() / RAND_MAX * 2 - 1; // Random displacement between -1 and 1

        particles[i].x += dx;
        particles[i].y += dy;

        // Ensure particles stay within the bounds
        if (particles[i].x < 0) particles[i].x = 0;
        if (particles[i].x > WIDTH) particles[i].x = WIDTH;
        if (particles[i].y < 0) particles[i].y = 0;
        if (particles[i].y > HEIGHT) particles[i].y = HEIGHT;
    }
}

void print_particles(Particle *particles, int num_particles) {
    for (int i = 0; i < num_particles; i++) {
        printf("Particle %d: (x, y) = (%.2f, %.2f)\n", i, particles[i].x, particles[i].y);
    }
}

int main() {
    int num_particles;
    printf("Enter the number of particles: ");
    scanf("%d", &num_particles);

    if (num_particles < 1 || num_particles > MAX_PARTICLES) {
        printf("Number of particles must be between 1 and %d\n", MAX_PARTICLES);
        return 1;
    }

    Particle particles[MAX_PARTICLES];
    srand(time(NULL)); // Seed the random number generator

    initialize_particles(particles, num_particles);

    printf("Initial positions:\n");
    print_particles(particles, num_particles);

    for (int t = 0; t < MAX_TIME_STEPS; t++) {
        printf("Time step %d:\n", t);
        update_particles(particles, num_particles);
        print_particles(particles, num_particles);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_COMPANIES 50
#define MAX_NAME_LENGTH 50

// Structure to represent a company's stock
typedef struct {
    char name[MAX_NAME_LENGTH];
    double current_price;
    double initial_price;
    double market_cap;
    int total_shares;
} Stock;

// Structure to manage the stock market
typedef struct {
    Stock companies[MAX_COMPANIES];
    int num_companies;
} StockMarket;

// Function prototypes
void initialize_market(StockMarket *market);
void add_company(StockMarket *market);
void display_market(StockMarket *market);
void update_stock_prices(StockMarket *market);
void buy_stocks(StockMarket *market);
void sell_stocks(StockMarket *market);
void simulate_market_trends(StockMarket *market);

int main() {
    StockMarket market;
    int choice;

    // Initialize random seed
    srand(time(NULL));

    // Initialize market
    initialize_market(&market);

    while (1) {
        printf("\n--- Stock Market Simulation ---\n");
        printf("1. Add Company\n");
        printf("2. Display Market\n");
        printf("3. Update Stock Prices\n");
        printf("4. Buy Stocks\n");
        printf("5. Sell Stocks\n");
        printf("6. Simulate Market Trends\n");
        printf("7. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                add_company(&market);
                break;
            case 2:
                display_market(&market);
                break;
            case 3:
                update_stock_prices(&market);
                break;
            case 4:
                buy_stocks(&market);
                break;
            case 5:
                sell_stocks(&market);
                break;
            case 6:
                simulate_market_trends(&market);
                break;
            case 7:
                printf("Exiting stock market simulation...\n");
                exit(0);
            default:
                printf("Invalid choice. Please try again.\n");
        }
    }

    return 0;
}

// Initialize the stock market
void initialize_market(StockMarket *market) {
    market->num_companies = 0;
}

// Add a new company to the stock market
void add_company(StockMarket *market) {
    if (market->num_companies >= MAX_COMPANIES) {
        printf("Maximum number of companies reached!\n");
        return;
    }

    Stock new_company;
    printf("Enter company name: ");
    scanf("%s", new_company.name);
    printf("Enter initial stock price: ");
    scanf("%lf", &new_company.initial_price);
    printf("Enter total number of shares: ");
    scanf("%d", &new_company.total_shares);

    new_company.current_price = new_company.initial_price;
    new_company.market_cap = new_company.current_price * new_company.total_shares;

    market->companies[market->num_companies++] = new_company;
    printf("Company added successfully!\n");
}

// Display market information
void display_market(StockMarket *market) {
    if (market->num_companies == 0) {
        printf("No companies in the market.\n");
        return;
    }

    printf("\n--- Stock Market Overview ---\n");
    for (int i = 0; i < market->num_companies; i++) {
        Stock *company = &market->companies[i];
        printf("Company: %s\n", company->name);
        printf("Current Price: $%.2f\n", company->current_price);
        printf("Initial Price: $%.2f\n", company->initial_price);
        printf("Market Cap: $%.2f\n", company->market_cap);
        printf("Total Shares: %d\n\n", company->total_shares);
    }
}

// Simulate stock price updates
void update_stock_prices(StockMarket *market) {
    for (int i = 0; i < market->num_companies; i++) {
        Stock *company = &market->companies[i];

        // Random price fluctuation between -5% and +5%
        double change_percentage = (rand() % 1000 - 500) / 1000.0;
        company->current_price *= (1 + change_percentage);
        company->market_cap = company->current_price * company->total_shares;
    }
    printf("Stock prices updated!\n");
}

// Buy stocks
void buy_stocks(StockMarket *market) {
    char company_name[MAX_NAME_LENGTH];
    int shares;

    printf("Enter company name: ");
    scanf("%s", company_name);

    for (int i = 0; i < market->num_companies; i++) {
        if (strcmp(market->companies[i].name, company_name) == 0) {
            printf("Enter number of shares to buy: ");
            scanf("%d", &shares);
            printf("Total cost: $%.2f\n", 
                   market->companies[i].current_price * shares);
            return;
        }
    }
    printf("Company not found.\n");
}

// Sell stocks
void sell_stocks(StockMarket *market) {
    char company_name[MAX_NAME_LENGTH];
    int shares;

    printf("Enter company name: ");
    scanf("%s", company_name);

    for (int i = 0; i < market->num_companies; i++) {
        if (strcmp(market->companies[i].name, company_name) == 0) {
            printf("Enter number of shares to sell: ");
            scanf("%d", &shares);
            printf("Total sale amount: $%.2f\n", 
                   market->companies[i].current_price * shares);
            return;
        }
    }
    printf("Company not found.\n");
}

// Simulate overall market trends
void simulate_market_trends(StockMarket *market) {
    // Simulate a market-wide trend
    double market_trend = (rand() % 200 - 100) / 1000.0;
    printf("Market trend: %.2f%%\n", market_trend * 100);

    for (int i = 0; i < market->num_companies; i++) {
        Stock *company = &market->companies[i];
        company->current_price *= (1 + market_trend);
        company->market_cap = company->current_price * company->total_shares;
    }
    printf("Market trend applied to all stocks.\n");
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <ctype.h>

#define MAX_COMPANIES 50
#define MAX_NAME_LENGTH 50
#define INITIAL_PRICE_MIN 10.0
#define INITIAL_PRICE_MAX 500.0
#define PRICE_CHANGE_PERCENT 5.0

typedef struct {
    char name[MAX_NAME_LENGTH];
    double price;
    double previous_price;
} Company;

Company companies[MAX_COMPANIES];
int num_companies = 0;

void clearInputBuffer() {
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
}

void addCompany() {
    if (num_companies >= MAX_COMPANIES) {
        printf("Maximum number of companies reached!\n");
        return;
    }

    printf("Enter company name: ");
    fgets(companies[num_companies].name, MAX_NAME_LENGTH, stdin);
    companies[num_companies].name[strcspn(companies[num_companies].name, "\n")] = '\0'; // Remove newline

    // Generate a random initial price
    companies[num_companies].price = INITIAL_PRICE_MIN + 
                                    ((double)rand() / RAND_MAX) * 
                                    (INITIAL_PRICE_MAX - INITIAL_PRICE_MIN);
    companies[num_companies].previous_price = companies[num_companies].price;

    printf("Added company '%s' with initial price $%.2f\n", 
           companies[num_companies].name, companies[num_companies].price);
    num_companies++;
}

void updatePrices() {
    for (int i = 0; i < num_companies; i++) {
        companies[i].previous_price = companies[i].price;

        // Calculate a random price change (-PRICE_CHANGE_PERCENT% to +PRICE_CHANGE_PERCENT%)
        double change_percent = ((double)rand() / RAND_MAX) * 
                               PRICE_CHANGE_PERCENT * 2 - PRICE_CHANGE_PERCENT;
        double change = companies[i].price * (change_percent / 100.0);

        companies[i].price += change;

        // Ensure price doesn't go below $0.01
        if (companies[i].price < 0.01) {
            companies[i].price = 0.01;
        }
    }
}

void displayMarket() {
    printf("\n=== STOCK MARKET ===\n");
    printf("%-30s %-15s %-15s %-15s\n", "Company", "Price", "Previous", "Change");
    printf("------------------------------------------------------------\n");

    for (int i = 0; i < num_companies; i++) {
        double change = companies[i].price - companies[i].previous_price;
        double change_percent = (change / companies[i].previous_price) * 100.0;

        printf("%-30s $%-14.2f $%-14.2f ", 
               companies[i].name, companies[i].price, companies[i].previous_price);

        if (change >= 0) {
            printf("\033[0;32m+$%.2f (+%.2f%%)\033[0m\n", change, change_percent);
        } else {
            printf("\033[0;31m-$%.2f (%.2f%%)\033[0m\n", -change, change_percent);
        }
    }
    printf("\n");
}

void displayMenu() {
    printf("\nStock Market Simulator\n");
    printf("1. Add a company\n");
    printf("2. Update stock prices\n");
    printf("3. View current market\n");
    printf("4. Exit\n");
    printf("Enter your choice: ");
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    int choice;

    do {
        displayMenu();
        scanf("%d", &choice);
        clearInputBuffer();

        switch (choice) {
            case 1:
                addCompany();
                break;
            case 2:
                if (num_companies == 0) {
                    printf("No companies in the market. Add some first.\n");
                } else {
                    updatePrices();
                    printf("Stock prices have been updated!\n");
                    displayMarket();
                }
                break;
            case 3:
                if (num_companies == 0) {
                    printf("No companies in the market. Add some first.\n");
                } else {
                    displayMarket();
                }
                break;
            case 4:
                printf("Exiting the stock market simulator. Goodbye!\n");
                break;
            default:
                printf("Invalid choice. Please try again.\n");
        }
    } while (choice != 4);

    return 0;
}

#include <stdio.h>
#include <stdlib.h> // For malloc, free, exit
#include <string.h> // For strcpy, strcmp

// --- Constants ---
#define MAX_COMPANIES 10 // Maximum number of different stock companies
#define MAX_NAME_LEN 50  // Maximum length for a company name
#define INITIAL_MONEY 1000.0 // Starting money for the user

// --- Structures ---
typedef struct {
    char name[MAX_NAME_LEN];
    double price;
    int shares_available; // A simple way to track "supply" for simulation
} Stock;

typedef struct {
    double cash;
    // For a more robust portfolio, you'd have an array/list of structs
    // like { Stock *stock_ptr; int shares_owned; }
    // For simplicity, we'll track shares of one specific company
    // This is NOT a full portfolio, just a basic example.
    char held_company_name[MAX_NAME_LEN];
    int held_shares;
} UserPortfolio;

// --- Global Variables (for simplicity in this small program) ---
Stock g_stocks[MAX_COMPANIES];
int g_num_companies = 0; // Current number of companies in the market
UserPortfolio g_user_portfolio;

// --- Function Prototypes ---
void display_menu();
void add_company();
void view_stocks();
void buy_stock();
void sell_stock();
void update_price();
int find_stock_index(const char *name);
void display_portfolio();

// --- Main Function ---
int main() {
    int choice;

    // Initialize user portfolio
    g_user_portfolio.cash = INITIAL_MONEY;
    strcpy(g_user_portfolio.held_company_name, "None");
    g_user_portfolio.held_shares = 0;

    printf("Welcome to the C Stock Market Simulator!\n");
    printf("Starting with $%.2f cash.\n", g_user_portfolio.cash);

    do {
        display_menu();
        printf("Enter your choice: ");
        if (scanf("%d", &choice) != 1) {
            printf("Invalid input. Please enter a number.\n");
            // Clear the input buffer
            while (getchar() != '\n');
            choice = -1; // Set an invalid choice to re-prompt
            continue;
        }
        // Consume the newline character left by scanf
        while (getchar() != '\n'); 

        switch (choice) {
            case 1: add_company(); break;
            case 2: view_stocks(); break;
            case 3: buy_stock(); break;
            case 4: sell_stock(); break;
            case 5: update_price(); break;
            case 6: display_portfolio(); break;
            case 7: printf("Exiting simulator. Goodbye!\n"); break;
            default: printf("Invalid choice. Please try again.\n");
        }
        printf("\n"); // Add a newline for better readability between operations

    } while (choice != 7);

    return 0;
}

// --- Function Implementations ---

void display_menu() {
    printf("--- Stock Market Menu ---\n");
    printf("1. Add New Company Stock\n");
    printf("2. View All Stocks\n");
    printf("3. Buy Stock\n");
    printf("4. Sell Stock\n");
    printf("5. Update Stock Price\n");
    printf("6. View Portfolio\n");
    printf("7. Exit\n");
    printf("-------------------------\n");
}

void add_company() {
    if (g_num_companies >= MAX_COMPANIES) {
        printf("Market is full! Cannot add more companies.\n");
        return;
    }

    printf("Enter company name (max %d chars): ", MAX_NAME_LEN - 1);
    char name_buffer[MAX_NAME_LEN];
    fgets(name_buffer, MAX_NAME_LEN, stdin);
    name_buffer[strcspn(name_buffer, "\n")] = 0; // Remove newline character

    // Check if company already exists
    if (find_stock_index(name_buffer) != -1) {
        printf("Error: Company '%s' already exists.\n", name_buffer);
        return;
    }

    strcpy(g_stocks[g_num_companies].name, name_buffer);

    double price;
    printf("Enter initial price for %s: $", g_stocks[g_num_companies].name);
    if (scanf("%lf", &price) != 1 || price <= 0) {
        printf("Invalid price. Price must be a positive number.\n");
        // Clear input buffer
        while (getchar() != '\n'); 
        return;
    }
    while (getchar() != '\n'); // Consume newline

    g_stocks[g_num_companies].price = price;
    g_stocks[g_num_companies].shares_available = 10000; // Arbitrary initial shares
    g_num_companies++;
    printf("Company '%s' added successfully with price $%.2f.\n", name_buffer, price);
}

void view_stocks() {
    if (g_num_companies == 0) {
        printf("No stocks currently listed in the market.\n");
        return;
    }

    printf("--- Current Stocks ---\n");
    for (int i = 0; i < g_num_companies; i++) {
        printf("%d. %s - Price: $%.2f (Available: %d shares)\n", 
               i + 1, g_stocks[i].name, g_stocks[i].price, g_stocks[i].shares_available);
    }
    printf("----------------------\n");
}

void buy_stock() {
    if (g_num_companies == 0) {
        printf("No stocks available to buy.\n");
        return;
    }

    printf("Enter the name of the company you want to buy: ");
    char name_buffer[MAX_NAME_LEN];
    fgets(name_buffer, MAX_NAME_LEN, stdin);
    name_buffer[strcspn(name_buffer, "\n")] = 0;

    int index = find_stock_index(name_buffer);
    if (index == -1) {
        printf("Company '%s' not found.\n", name_buffer);
        return;
    }

    int shares_to_buy;
    printf("Current price of %s: $%.2f\n", g_stocks[index].name, g_stocks[index].price);
    printf("Available shares: %d\n", g_stocks[index].shares_available);
    printf("Your cash: $%.2f\n", g_user_portfolio.cash);
    printf("Enter number of shares to buy: ");
    if (scanf("%d", &shares_to_buy) != 1 || shares_to_buy <= 0) {
        printf("Invalid number of shares. Must be a positive integer.\n");
        while (getchar() != '\n');
        return;
    }
    while (getchar() != '\n'); // Consume newline

    double total_cost = shares_to_buy * g_stocks[index].price;

    if (total_cost > g_user_portfolio.cash) {
        printf("Not enough cash to buy %d shares of %s. You need $%.2f.\n",
               shares_to_buy, g_stocks[index].name, total_cost - g_user_portfolio.cash);
        return;
    }

    if (shares_to_buy > g_stocks[index].shares_available) {
        printf("Not enough shares available from %s. Only %d shares left.\n",
               g_stocks[index].name, g_stocks[index].shares_available);
        return;
    }

    // --- Simulate transaction ---
    g_user_portfolio.cash -= total_cost;
    g_stocks[index].shares_available -= shares_to_buy;

    // Basic portfolio update (only tracks one company at a time)
    if (strcmp(g_user_portfolio.held_company_name, g_stocks[index].name) == 0 ||
        strcmp(g_user_portfolio.held_company_name, "None") == 0) {
        strcpy(g_user_portfolio.held_company_name, g_stocks[index].name);
        g_user_portfolio.held_shares += shares_to_buy;
        printf("Successfully bought %d shares of %s for $%.2f.\n",
               shares_to_buy, g_stocks[index].name, total_cost);
    } else {
        printf("You already hold shares of %s. For this simple simulation, you can only track one company's shares in your 'portfolio'.\n", 
               g_user_portfolio.held_company_name);
        printf("Transaction of %d shares of %s for $%.2f still processed for cash and available shares.\n",
               shares_to_buy, g_stocks[index].name, total_cost);
    }

    printf("Your remaining cash: $%.2f\n", g_user_portfolio.cash);
}

void sell_stock() {
    if (g_num_companies == 0) {
        printf("No stocks available to sell.\n");
        return;
    }
    if (g_user_portfolio.held_shares == 0) {
        printf("You don't hold any shares to sell.\n");
        return;
    }

    printf("Enter the name of the company you want to sell: ");
    char name_buffer[MAX_NAME_LEN];
    fgets(name_buffer, MAX_NAME_LEN, stdin);
    name_buffer[strcspn(name_buffer, "\n")] = 0;

    int index = find_stock_index(name_buffer);
    if (index == -1) {
        printf("Company '%s' not found.\n", name_buffer);
        return;
    }

    if (strcmp(g_user_portfolio.held_company_name, g_stocks[index].name) != 0) {
        printf("You do not hold shares of %s in your tracked portfolio. You hold %s.\n",
               g_stocks[index].name, g_user_portfolio.held_company_name);
        return;
    }

    int shares_to_sell;
    printf("You currently hold %d shares of %s.\n", g_user_portfolio.held_shares, g_user_portfolio.held_company_name);
    printf("Current price of %s: $%.2f\n", g_stocks[index].name, g_stocks[index].price);
    printf("Enter number of shares to sell: ");
    if (scanf("%d", &shares_to_sell) != 1 || shares_to_sell <= 0) {
        printf("Invalid number of shares. Must be a positive integer.\n");
        while (getchar() != '\n');
        return;
    }
    while (getchar() != '\n'); // Consume newline

    if (shares_to_sell > g_user_portfolio.held_shares) {
        printf("You only have %d shares of %s to sell.\n",
               g_user_portfolio.held_shares, g_stocks[index].name);
        return;
    }

    // --- Simulate transaction ---
    double total_revenue = shares_to_sell * g_stocks[index].price;
    g_user_portfolio.cash += total_revenue;
    g_stocks[index].shares_available += shares_to_sell; // Shares return to market supply
    g_user_portfolio.held_shares -= shares_to_sell;

    if (g_user_portfolio.held_shares == 0) {
        strcpy(g_user_portfolio.held_company_name, "None");
    }

    printf("Successfully sold %d shares of %s for $%.2f.\n",
           shares_to_sell, g_stocks[index].name, total_revenue);
    printf("Your new cash balance: $%.2f\n", g_user_portfolio.cash);
