#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

// Neural Network Hyperparameters
#define INPUT_SIZE 784    // 28x28 pixel image
#define HIDDEN_SIZE 128   // Hidden layer neurons
#define OUTPUT_SIZE 10    // 10 digit classes
#define LEARNING_RATE 0.01
#define EPOCHS 10

// Random weight initialization function
float random_weight() {
    return (float)rand() / RAND_MAX - 0.5;
}

// Activation functions
float sigmoid(float x) {
    return 1.0f / (1.0f + exp(-x));
}

float sigmoid_derivative(float x) {
    return x * (1.0f - x);
}

// Neural Network structure
typedef struct {
    float input[INPUT_SIZE];
    float hidden_weights[INPUT_SIZE][HIDDEN_SIZE];
    float hidden_layer[HIDDEN_SIZE];
    float output_weights[HIDDEN_SIZE][OUTPUT_SIZE];
    float output_layer[OUTPUT_SIZE];
} NeuralNetwork;

// Initialize neural network weights
void initialize_network(NeuralNetwork* nn) {
    srand(time(NULL));

    // Initialize hidden layer weights
    for (int i = 0; i < INPUT_SIZE; i++) {
        for (int j = 0; j < HIDDEN_SIZE; j++) {
            nn->hidden_weights[i][j] = random_weight();
        }
    }

    // Initialize output layer weights
    for (int i = 0; i < HIDDEN_SIZE; i++) {
        for (int j = 0; j < OUTPUT_SIZE; j++) {
            nn->output_weights[i][j] = random_weight();
        }
    }
}

// Forward propagation
void forward_propagation(NeuralNetwork* nn) {
    // Hidden layer computation
    for (int j = 0; j < HIDDEN_SIZE; j++) {
        float sum = 0.0f;
        for (int i = 0; i < INPUT_SIZE; i++) {
            sum += nn->input[i] * nn->hidden_weights[i][j];
        }
        nn->hidden_layer[j] = sigmoid(sum);
    }

    // Output layer computation
    for (int j = 0; j < OUTPUT_SIZE; j++) {
        float sum = 0.0f;
        for (int i = 0; i < HIDDEN_SIZE; i++) {
            sum += nn->hidden_layer[i] * nn->output_weights[i][j];
        }
        nn->output_layer[j] = sigmoid(sum);
    }
}

// Backpropagation
void backpropagation(NeuralNetwork* nn, float* expected_output) {
    // Output layer error
    float output_errors[OUTPUT_SIZE];
    for (int j = 0; j < OUTPUT_SIZE; j++) {
        float error = expected_output[j] - nn->output_layer[j];
        output_errors[j] = error * sigmoid_derivative(nn->output_layer[j]);
    }

    // Hidden layer error
    float hidden_errors[HIDDEN_SIZE];
    for (int j = 0; j < HIDDEN_SIZE; j++) {
        float error = 0.0f;
        for (int k = 0; k < OUTPUT_SIZE; k++) {
            error += output_errors[k] * nn->output_weights[j][k];
        }
        hidden_errors[j] = error * sigmoid_derivative(nn->hidden_layer[j]);
    }

    // Update output layer weights
    for (int i = 0; i < HIDDEN_SIZE; i++) {
        for (int j = 0; j < OUTPUT_SIZE; j++) {
            nn->output_weights[i][j] += LEARNING_RATE * 
                output_errors[j] * nn->hidden_layer[i];
        }
    }

    // Update hidden layer weights
    for (int i = 0; i < INPUT_SIZE; i++) {
        for (int j = 0; j < HIDDEN_SIZE; j++) {
            nn->hidden_weights[i][j] += LEARNING_RATE * 
                hidden_errors[j] * nn->input[i];
        }
    }
}

// Predict digit
int predict_digit(NeuralNetwork* nn) {
    int max_index = 0;
    float max_value = nn->output_layer[0];

    for (int i = 1; i < OUTPUT_SIZE; i++) {
        if (nn->output_layer[i] > max_value) {
            max_value = nn->output_layer[i];
            max_index = i;
        }
    }

    return max_index;
}

// Training function
void train_network(NeuralNetwork* nn, float* training_data, float* labels, int num_samples) {
    for (int epoch = 0; epoch < EPOCHS; epoch++) {
        for (int sample = 0; sample < num_samples; sample++) {
            // Copy input
            for (int i = 0; i < INPUT_SIZE; i++) {
                nn->input[i] = training_data[sample * INPUT_SIZE + i];
            }

            // Create expected output
            float expected_output[OUTPUT_SIZE] = {0};
            int label = (int)labels[sample];
            expected_output[label] = 1.0f;

            // Forward and backward pass
            forward_propagation(nn);
            backpropagation(nn, expected_output);
        }
    }
}

int main() {
    NeuralNetwork nn;
    initialize_network(&nn);

    // Here you would load MNIST training data
    // Simulating data for demonstration
    float training_data[INPUT_SIZE * 10];
    float labels[10];

    // Simulate training
    train_network(&nn, training_data, labels, 10);

    // Prediction example
    for (int i = 0; i < INPUT_SIZE; i++) {
        nn.input[i] = training_data[i];
    }
    forward_propagation(&nn);
    int predicted_digit = predict_digit(&nn);

    printf("Predicted Digit: %d\n", predicted_digit);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

#define INPUT_SIZE 784  // 28x28 pixels
#define HIDDEN_SIZE 128
#define OUTPUT_SIZE 10
#define LEARNING_RATE 0.01
#define EPOCHS 10

// Sigmoid activation function
double sigmoid(double x) {
    return 1.0 / (1.0 + exp(-x));
}

// Derivative of the sigmoid function
double sigmoid_derivative(double x) {
    return x * (1.0 - x);
}

// Initialize weights randomly
void initialize_weights(double *weights, int n) {
    for (int i = 0; i < n; i++) {
        weights[i] = ((double)rand() / RAND_MAX) - 0.5;
    }
}

// Feedforward pass
void feedforward(double *input, double *hidden, double *output, 
                 double *w1, double *w2) {
    // Compute hidden layer activations
    for (int i = 0; i < HIDDEN_SIZE; i++) {
        hidden[i] = 0.0;
        for (int j = 0; j < INPUT_SIZE; j++) {
            hidden[i] += input[j] * w1[i * INPUT_SIZE + j];
        }
        hidden[i] = sigmoid(hidden[i]);
    }

    // Compute output layer activations
    for (int i = 0; i < OUTPUT_SIZE; i++) {
        output[i] = 0.0;
        for (int j = 0; j < HIDDEN_SIZE; j++) {
            output[i] += hidden[j] * w2[i * HIDDEN_SIZE + j];
        }
        output[i] = sigmoid(output[i]);
    }
}

// Backpropagation
void backpropagate(double *input, double *hidden, double *output, 
                   double *target, double *w1, double *w2) {
    double output_error[OUTPUT_SIZE];
    double hidden_error[HIDDEN_SIZE];

    // Calculate output layer error
    for (int i = 0; i < OUTPUT_SIZE; i++) {
        output_error[i] = (target[i] - output[i]) * sigmoid_derivative(output[i]);
    }

    // Calculate hidden layer error
    for (int i = 0; i < HIDDEN_SIZE; i++) {
        hidden_error[i] = 0.0;
        for (int j = 0; j < OUTPUT_SIZE; j++) {
            hidden_error[i] += output_error[j] * w2[j * HIDDEN_SIZE + i];
        }
        hidden_error[i] *= sigmoid_derivative(hidden[i]);
    }

    // Update weights between hidden and output layers
    for (int i = 0; i < OUTPUT_SIZE; i++) {
        for (int j = 0; j < HIDDEN_SIZE; j++) {
            w2[i * HIDDEN_SIZE + j] += LEARNING_RATE * output_error[i] * hidden[j];
        }
    }

    // Update weights between input and hidden layers
    for (int i = 0; i < HIDDEN_SIZE; i++) {
        for (int j = 0; j < INPUT_SIZE; j++) {
            w1[i * INPUT_SIZE + j] += LEARNING_RATE * hidden_error[i] * input[j];
        }
    }
}

// Load MNIST dataset (simplified)
void load_mnist(double *images, double *labels, int n) {
    // In a real implementation, you would load the MNIST dataset from the binary files
    // For simplicity, we just initialize random data here
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < INPUT_SIZE; j++) {
            images[i * INPUT_SIZE + j] = (double)rand() / RAND_MAX;
        }
        labels[i] = rand() % OUTPUT_SIZE;
    }
}

int main() {
    srand(time(NULL));

    double w1[HIDDEN_SIZE * INPUT_SIZE];
    double w2[OUTPUT_SIZE * HIDDEN_SIZE];

    initialize_weights(w1, HIDDEN_SIZE * INPUT_SIZE);
    initialize_weights(w2, OUTPUT_SIZE * HIDDEN_SIZE);

    int num_samples = 60000;  // MNIST training set size
    double images[num_samples * INPUT_SIZE];
    double labels[num_samples];

    load_mnist(images, labels, num_samples);

    for (int epoch = 0; epoch < EPOCHS; epoch++) {
        for (int i = 0; i < num_samples; i++) {
            double input[INPUT_SIZE];
            for (int j = 0; j < INPUT_SIZE; j++) {
                input[j] = images[i * INPUT_SIZE + j];
            }

            double target[OUTPUT_SIZE] = {0};
            target[(int)labels[i]] = 1.0;

            double hidden[HIDDEN_SIZE];
            double output[OUTPUT_SIZE];

            feedforward(input, hidden, output, w1, w2);
            backpropagate(input, hidden, output, target, w1, w2);
        }
        printf("Epoch %d completed.\n", epoch + 1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>
#include <string.h> // For memcpy

// --- Constants ---
#define INPUT_NODES       784 // 28x28 pixels
#define HIDDEN_NODES      128 // Number of neurons in the hidden layer
#define OUTPUT_NODES      10  // Digits 0-9

#define LEARNING_RATE     0.001
#define EPOCHS            10

#define NUM_TRAIN_IMAGES  60000
#define NUM_TEST_IMAGES   10000

// MNIST file paths (adjust if your files are elsewhere)
#define TRAIN_IMAGES_FILE_PATH "train-images-idx3-ubyte"
#define TRAIN_LABELS_FILE_PATH "train-labels-idx1-ubyte"
#define TEST_IMAGES_FILE_PATH  "t10k-images-idx3-ubyte"
#define TEST_LABELS_FILE_PATH  "t10k-labels-idx1-ubyte"

// --- Global Network Structures ---
// Weights and biases are dynamically allocated
double **weights_ih; // Input to Hidden weights [INPUT_NODES][HIDDEN_NODES]
double *biases_h;    // Hidden layer biases [HIDDEN_NODES]
double **weights_ho; // Hidden to Output weights [HIDDEN_NODES][OUTPUT_NODES]
double *biases_o;    // Output layer biases [OUTPUT_NODES]

// Activations and Z-values (pre-activation sums) for a single example
double *input_activations;  // [INPUT_NODES]
double *hidden_z;           // Pre-activation sums for hidden layer [HIDDEN_NODES]
double *hidden_activations; // Activated values for hidden layer [HIDDEN_NODES]
double *output_z;           // Pre-activation sums for output layer [OUTPUT_NODES]
double *output_activations; // Activated probabilities for output layer [OUTPUT_NODES]

// Gradient values for backpropagation (for a single example)
double *delta_output;       // Error term for output layer [OUTPUT_NODES]
double *delta_hidden;       // Error term for hidden layer [HIDDEN_NODES]

// --- MNIST Data Storage ---
unsigned char **train_images; // [NUM_TRAIN_IMAGES][INPUT_NODES]
unsigned char *train_labels;  // [NUM_TRAIN_IMAGES]
unsigned char **test_images;  // [NUM_TEST_IMAGES][INPUT_NODES]
unsigned char *test_labels;   // [NUM_TEST_IMAGES]


// --- Utility Functions ---

// Function to reverse byte order (MNIST data is big-endian)
unsigned int reverse_int(unsigned int i) {
    unsigned char c1, c2, c3, c4;
    c1 = i & 255;
    c2 = (i >> 8) & 255;
    c3 = (i >> 16) & 255;
    c4 = (i >> 24) & 255;
    return ((unsigned int)c1 << 24) + ((unsigned int)c2 << 16) + ((unsigned int)c3 << 8) + c4;
}

// Loads MNIST images from a specified file path
unsigned char** load_mnist_images(const char* file_path, int num_images) {
    FILE* fp = fopen(file_path, "rb");
    if (!fp) {
        perror("Error opening image file");
        exit(EXIT_FAILURE);
    }

    unsigned int magic_number = 0;
    unsigned int num_items = 0;
    unsigned int num_rows = 0;
    unsigned int num_cols = 0;

    fread(&magic_number, sizeof(magic_number), 1, fp);
    magic_number = reverse_int(magic_number);
    if (magic_number != 2051) {
        fprintf(stderr, "Invalid magic number for image file: %s\n", file_path);
        fclose(fp);
        exit(EXIT_FAILURE);
    }

    fread(&num_items, sizeof(num_items), 1, fp);
    num_items = reverse_int(num_items);
    if (num_items != num_images) {
        fprintf(stderr, "Mismatched number of images: %d vs expected %d\n", num_items, num_images);
        fclose(fp);
        exit(EXIT_FAILURE);
    }

    fread(&num_rows, sizeof(num_rows), 1, fp);
    num_rows = reverse_int(num_rows);
    fread(&num_cols, sizeof(num_cols), 1, fp);
    num_cols = reverse_int(num_cols);

    if (num_rows != 28 || num_cols != 28) {
        fprintf(stderr, "Unexpected image dimensions: %dx%d instead of 28x28\n", num_rows, num_cols);
        fclose(fp);
        exit(EXIT_FAILURE);
    }

    unsigned char** data = (unsigned char**)malloc(num_images * sizeof(unsigned char*));
    if (!data) {
        perror("Failed to allocate memory for image pointers");
        fclose(fp);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_images; ++i) {
        data[i] = (unsigned char*)malloc(num_rows * num_cols * sizeof(unsigned char));
        if (!data[i]) {
            perror("Failed to allocate memory for image data");
            // Clean up previously allocated images
            for(int j=0; j<i; ++j) free(data[j]);
            free(data);
            fclose(fp);
            exit(EXIT_FAILURE);
        }
        fread(data[i], sizeof(unsigned char), num_rows * num_cols, fp);
    }

    fclose(fp);
    printf("Loaded %d images from %s\n", num_items, file_path);
    return data;
}

// Loads MNIST labels from a specified file path
unsigned char* load_mnist_labels(const char* file_path, int num_labels) {
    FILE* fp = fopen(file_path, "rb");
    if (!fp) {
        perror("Error opening label file");
        exit(EXIT_FAILURE);
    }

    unsigned int magic_number = 0;
    unsigned int num_items = 0;

    fread(&magic_number, sizeof(magic_number), 1, fp);
    magic_number = reverse_int(magic_number);
    if (magic_number != 2049) {
        fprintf(stderr, "Invalid magic number for label file: %s\n", file_path);
        fclose(fp);
        exit(EXIT_FAILURE);
    }

    fread(&num_items, sizeof(num_items), 1, fp);
    num_items = reverse_int(num_items);
    if (num_items != num_labels) {
        fprintf(stderr, "Mismatched number of labels: %d vs expected %d\n", num_items, num_labels);
        fclose(fp);
        exit(EXIT_FAILURE);
    }

    unsigned char* data = (unsigned char*)malloc(num_labels * sizeof(unsigned char));
    if (!data) {
        perror("Failed to allocate memory for label data");
        fclose(fp);
        exit(EXIT_FAILURE);
    }
    fread(data, sizeof(unsigned char), num_labels, fp);

    fclose(fp);
    printf("Loaded %d labels from %s\n", num_items, file_path);
    return data;
}

// Random double between min and max
double rand_double(double min, double max) {
    return min + ((double)rand() / RAND_MAX) * (max - min);
}

// ReLU activation function
double relu(double x) {
    return x > 0 ? x : 0;
}

// Derivative of ReLU
double d_relu(double x) {
    return x > 0 ? 1 : 0;
}

// Softmax activation function
void softmax(double* input, double* output, int size) {
    double sum_exp = 0.0;
    double max_val = input[0];
    for (int i = 1; i < size; ++i) {
        if (input[i] > max_val) {
            max_val = input[i];
        }
    }

    // Subtract max_val for numerical stability
    for (int i = 0; i < size; ++i) {
        output[i] = exp(input[i] - max_val);
        sum_exp += output[i];
    }

    for (int i = 0; i < size; ++i) {
        output[i] /= sum_exp;
    }
}

// Initializes the neural network's weights and biases
void init_network() {
    srand(time(NULL)); // Seed the random number generator

    // Allocate memory for weights and biases
    weights_ih = (double**)malloc(INPUT_NODES * sizeof(double*));
    for (int i = 0; i < INPUT_NODES; ++i) {
        weights_ih[i] = (double*)malloc(HIDDEN_NODES * sizeof(double));
    }
    biases_h = (double*)malloc(HIDDEN_NODES * sizeof(double));

    weights_ho = (double**)malloc(HIDDEN_NODES * sizeof(double*));
    for (int i = 0; i < HIDDEN_NODES; ++i) {
        weights_ho[i] = (double*)malloc(OUTPUT_NODES * sizeof(double));
    }
    biases_o = (double*)malloc(OUTPUT_NODES * sizeof(double));

    // Allocate memory for activation buffers for one example
    input_activations = (double*)malloc(INPUT_NODES * sizeof(double));
    hidden_z = (double*)malloc(HIDDEN_NODES * sizeof(double));
    hidden_activations = (double*)malloc(HIDDEN_NODES * sizeof(double));
    output_z = (double*)malloc(OUTPUT_NODES * sizeof(double));
    output_activations = (double*)malloc(OUTPUT_NODES * sizeof(double));

    // Allocate memory for error terms
    delta_output = (double*)malloc(OUTPUT_NODES * sizeof(double));
    delta_hidden = (double*)malloc(HIDDEN_NODES * sizeof(double));

    if (!weights_ih || !biases_h || !weights_ho || !biases_o ||
        !input_activations || !hidden_activations || !hidden_z ||
        !output_activations || !output_z || !delta_output || !delta_hidden) {
        fprintf(stderr, "Memory allocation failed for network components.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize weights and biases
    // Using simple random initialization between -0.5 and 0.5
    for (int i = 0; i < INPUT_NODES; ++i) {
        for (int j = 0; j < HIDDEN_NODES; ++j) {
            weights_ih[i][j] = rand_double(-0.5, 0.5);
        }
    }
    for (int j = 0; j < HIDDEN_NODES; ++j) {
        biases_h[j] = rand_double(-0.5, 0.5);
    }

    for (int i = 0; i < HIDDEN_NODES; ++i) {
        for (int j = 0; j < OUTPUT_NODES; ++j) {
            weights_ho[i][j] = rand_double(-0.5, 0.5);
        }
    }
    for (int j = 0; j < OUTPUT_NODES; ++j) {
        biases_o[j] = rand_double(-0.5, 0.5);
    }
}

// Frees all allocated memory
void free_network() {
    for (int i = 0; i < INPUT_NODES; ++i) {
        free(weights_ih[i]);
    }
    free(weights_ih);
    free(biases_h);

    for (int i = 0; i < HIDDEN_NODES; ++i) {
        free(weights_ho[i]);
    }
    free(weights_ho);
    free(biases_o);

    free(input_activations);
    free(hidden_z);
    free(hidden_activations);
    free(output_z);
    free(output_activations);

    free(delta_output);
    free(delta_hidden);
}

// --- Forward Pass ---
void forward_pass(const unsigned char* image_data) {
    // Input Layer
    for (int i = 0; i < INPUT_NODES; ++i) {
        input_activations[i] = (double)image_data[i] / 255.0; // Normalize pixel to 0-1
    }

    // Hidden Layer
    for (int j = 0; j < HIDDEN_NODES; ++j) {
        hidden_z[j] = biases_h[j]; // Start with bias
        for (int i = 0; i < INPUT_NODES; ++i) {
            hidden_z[j] += input_activations[i] * weights_ih[i][j];
        }
        hidden_activations[j] = relu(hidden_z[j]);
    }

    // Output Layer
    for (int k = 0; k < OUTPUT_NODES; ++k) {
        output_z[k] = biases_o[k]; // Start with bias
        for (int j = 0; j < HIDDEN_NODES; ++j) {
            output_z[k] += hidden_activations[j] * weights_ho[j][k];
        }
    }
    softmax(output_z, output_activations, OUTPUT_NODES);
}

// --- Backward Pass and Weight Update ---
void backward_pass(unsigned char true_label) {
    double target[OUTPUT_NODES] = {0.0};
    target[true_label] = 1.0; // One-hot encode the true label

    // Calculate output layer error (delta_output)
    // For Softmax + Cross-Entropy, error is (predicted - actual)
    for (int k = 0; k < OUTPUT_NODES; ++k) {
        delta_output[k] = output_activations[k] - target[k];
    }

    // Calculate hidden layer error (delta_hidden)
    for (int j = 0; j < HIDDEN_NODES; ++j) {
        delta_hidden[j] = 0.0;
        for (int k = 0; k < OUTPUT_NODES; ++k) {
            delta_hidden[j] += delta_output[k] * weights_ho[j][k];
        }
        delta_hidden[j] *= d_relu(hidden_z[j]); // Apply derivative of activation function
    }

    // Update weights and biases for Hidden to Output layer
    for (int j = 0; j < HIDDEN_NODES; ++j) {
        for (int k = 0; k < OUTPUT_NODES; ++k) {
            weights_ho[j][k] -= LEARNING_RATE * delta_output[k] * hidden_activations[j];
        }
    }
    for (int k = 0; k < OUTPUT_NODES; ++k) {
        biases_o[k] -= LEARNING_RATE * delta_output[k];
    }

    // Update weights and biases for Input to Hidden layer
    for (int i = 0; i < INPUT_NODES; ++i) {
        for (int j = 0; j < HIDDEN_NODES; ++j) {
            weights_ih[i][j] -= LEARNING_RATE * delta_hidden[j] * input_activations[i];
        }
    }
    for (int j = 0; j < HIDDEN_NODES; ++j) {
        biases_h[j] -= LEARNING_RATE * delta_hidden[j];
    }
}

// --- Training Function ---
void train() {
    printf("\nStarting training...\n");
    for (int epoch = 0; epoch < EPOCHS; ++epoch) {
        double total_loss = 0.0;
        printf("Epoch %d/%d\n", epoch + 1, EPOCHS);

        for (int i = 0; i < NUM_TRAIN_IMAGES; ++i) {
            // Forward pass
            forward_pass(train_images[i]);

            // Calculate loss (optional, for monitoring)
            double current_loss = -log(output_activations[train_labels[i]]);
            total_loss += current_loss;

            // Backward pass and update weights
            backward_pass(train_labels[i]);

            if (i % (NUM_TRAIN_IMAGES / 10) == 0) {
                printf(".");
                fflush(stdout);
            }
        }
        printf("\nEpoch %d finished. Average Loss: %lf\n", epoch + 1, total_loss / NUM_TRAIN_IMAGES);
    }
    printf("\nTraining complete!\n");
}

// --- Prediction/Testing Function ---
int predict(const unsigned char* image_data) {
    forward_pass(image_data); // Perform forward pass

    int predicted_digit = 0;
    double max_prob = 0.0;
    for (int k = 0; k < OUTPUT_NODES; ++k) {
        if (output_activations[k] > max_prob) {
            max_prob = output_activations[k];
            predicted_digit = k;
        }
    }
    return predicted_digit;
}

void test() {
    int correct_predictions = 0;
    printf("\nStarting testing...\n");
    for (int i = 0; i < NUM_TEST_IMAGES; ++i) {
        if (predict(test_images[i]) == test_labels[i]) {
            correct_predictions++;
        }
    }
    double accuracy = (double)correct_predictions / NUM_TEST_IMAGES * 100.0;
    printf("Testing complete! Accuracy: %d/%d (%.2f%%)\n", correct_predictions, NUM_TEST_IMAGES, accuracy);
}

// --- Main Function ---
int main() {
    // Load MNIST data
    printf("Loading MNIST data...\n");
    train_images = load_mnist_images(TRAIN_IMAGES_FILE_PATH, NUM_TRAIN_IMAGES);
    train_labels = load_mnist_labels(TRAIN_LABELS_FILE_PATH, NUM_TRAIN_IMAGES);
    test_images = load_mnist_images(TEST_IMAGES_FILE_PATH, NUM_TEST_IMAGES);
    test_labels = load_mnist_labels(TEST_LABELS_FILE_PATH, NUM_TEST_IMAGES);

    // Initialize network
    init_network();

    // Train the network
    train();

    // Test the network
    test();

    // Clean up memory
    printf("\nCleaning up memory...\n");
    for (int i = 0; i < NUM_TRAIN_IMAGES; ++i) free(train_images[i]);
    free(train_images);
    free(train_labels);
    for (int i = 0; i < NUM_TEST_IMAGES; ++i) free(test_images[i]);
    free(test_images);
    free(test_labels);

    free_network();

    printf("Done!\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>
#include <time.h>

// Network parameters
#define INPUT_SIZE 784     // MNIST image size (28x28)
#define HIDDEN_SIZE 128    // Size of hidden layer
#define OUTPUT_SIZE 10     // Digits 0-9
#define TRAIN_SIZE 1000    // Training sample count (for demo!)—should be 60000 for full MNIST
#define EPOCHS 10
#define LEARNING_RATE 0.01f

// Activation functions
float sigmoid(float x) {
    return 1.0f / (1.0f + expf(-x));
}

float dsigmoid(float y) {
    return y * (1.0f - y); // y = sigmoid(x)
}

void softmax(float* x, int len) {
    float max = x[0];
    for (int i = 1; i < len; ++i) if (x[i] > max) max = x[i];
    float sum = 0.0f;
    for (int i = 0; i < len; ++i) {
        x[i] = expf(x[i] - max);
        sum += x[i];
    }
    for (int i = 0; i < len; ++i)
        x[i] /= sum;
}

// Utility for random floats in [-1,1]
float randf() {
    return 2.0f * rand() / (float)RAND_MAX - 1.0f;
}

void initialize(float* arr, int n, float scale) {
    for (int i = 0; i < n; ++i)
        arr[i] = scale * randf();
}

// Main network structure
typedef struct {
    float w1[INPUT_SIZE][HIDDEN_SIZE];
    float b1[HIDDEN_SIZE];
    float w2[HIDDEN_SIZE][OUTPUT_SIZE];
    float b2[OUTPUT_SIZE];
} Net;

void net_init(Net* net) {
    initialize(&net->w1[0][0], INPUT_SIZE * HIDDEN_SIZE, 0.01f);
    initialize(net->b1, HIDDEN_SIZE, 0.01f);
    initialize(&net->w2[0][0], HIDDEN_SIZE * OUTPUT_SIZE, 0.01f);
    initialize(net->b2, OUTPUT_SIZE, 0.01f);
}

void net_forward(Net* net, float* input, float* hidden, float* output) {
    // Hidden layer
    for (int h = 0; h < HIDDEN_SIZE; ++h) {
        float sum = net->b1[h];
        for (int i = 0; i < INPUT_SIZE; ++i)
            sum += input[i] * net->w1[i][h];
        hidden[h] = sigmoid(sum);
    }
    // Output layer
    for (int o = 0; o < OUTPUT_SIZE; ++o) {
        float sum = net->b2[o];
        for (int h = 0; h < HIDDEN_SIZE; ++h)
            sum += hidden[h] * net->w2[h][o];
        output[o] = sum; // Will be softmaxed outside
    }
    softmax(output, OUTPUT_SIZE);
}

// One-hot encode label
void one_hot(int label, float* out) {
    for (int i = 0; i < OUTPUT_SIZE; ++i) out[i] = 0.0f;
    out[label] = 1.0f;
}

// Performs one SGD update
void net_train(Net* net, float* input, int label) {
    float hidden[HIDDEN_SIZE], output[OUTPUT_SIZE], target[OUTPUT_SIZE];
    float d_out[OUTPUT_SIZE], d_hidden[HIDDEN_SIZE];

    // --- Forward
    net_forward(net, input, hidden, output);

    // --- Loss gradient (cross-entropy)
    one_hot(label, target);
    for (int o = 0; o < OUTPUT_SIZE; ++o) {
        d_out[o] = output[o] - target[o];
    }

    // --- Grad for w2 and b2, and backprop to hidden
    for (int h = 0; h < HIDDEN_SIZE; ++h)
        d_hidden[h] = 0.0f;

    for (int o = 0; o < OUTPUT_SIZE; ++o) {
        net->b2[o] -= LEARNING_RATE * d_out[o];
        for (int h = 0; h < HIDDEN_SIZE; ++h) {
            net->w2[h][o] -= LEARNING_RATE * d_out[o] * hidden[h];
            d_hidden[h] += net->w2[h][o] * d_out[o];
        }
    }

    // Grad for w1 and b1
    for (int h = 0; h < HIDDEN_SIZE; ++h) {
        d_hidden[h] *= dsigmoid(hidden[h]);
        net->b1[h] -= LEARNING_RATE * d_hidden[h];
        for (int i = 0; i < INPUT_SIZE; ++i) {
            net->w1[i][h] -= LEARNING_RATE * d_hidden[h] * input[i];
        }
    }
}

// Evaluate accuracy
float net_eval(Net* net, float* X, unsigned char* Y, int n) {
    int correct = 0;
    float hidden[HIDDEN_SIZE], output[OUTPUT_SIZE];
    for (int i = 0; i < n; ++i) {
        net_forward(net, X + i * INPUT_SIZE, hidden, output);
        int pred = 0;
        float max = output[0];
        for (int o = 1; o < OUTPUT_SIZE; ++o)
            if (output[o] > max) { max = output[o]; pred = o; }
        if (pred == Y[i]) ++correct;
    }
    return (float)correct / n;
}

// --- A demo MNIST-like dataset with random numbers
void fake_mnist(float* X, unsigned char* Y, int n) {
    for (int i = 0; i < n; ++i) {
        for (int p = 0; p < INPUT_SIZE; ++p)
            X[i * INPUT_SIZE + p] = rand() / (float)RAND_MAX;
        Y[i] = rand() % OUTPUT_SIZE;
    }
}

int main() {
    srand(time(0));
    Net net;
    net_init(&net);

    // Allocate fake MNIST data for demo
    float* X = (float*)malloc(TRAIN_SIZE * INPUT_SIZE * sizeof(float));
    unsigned char* Y = (unsigned char*)malloc(TRAIN_SIZE * sizeof(unsigned char));
    fake_mnist(X, Y, TRAIN_SIZE);

    // --- Training
    for (int epoch = 0; epoch < EPOCHS; ++epoch) {
        for (int i = 0; i < TRAIN_SIZE; ++i) {
            net_train(&net, X + i * INPUT_SIZE, Y[i]);
        }
        // Evaluate
        float acc = net_eval(&net, X, Y, TRAIN_SIZE);
        printf("Epoch %d, Accuracy: %.2f%%\n", epoch + 1, 100 * acc);
    }

    // Clean up
    free(X);
    free(Y);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

// Define Neural Network structure
#define INPUT_NODES 784  // 28x28 pixels for each MNIST image
#define HIDDEN_NODES 128
#define OUTPUT_NODES 10  // Digits 0-9
#define LEARNING_RATE 0.01

// Sigmoid activation function
double sigmoid(double x) {
    return 1.0 / (1.0 + exp(-x));
}

// Derivative of sigmoid function
double sigmoid_derivative(double x) {
    return x * (1.0 - x);
}

// Initialize weights with random values
void initialize_weights(double *weights, int n) {
    for (int i = 0; i < n; i++) {
        weights[i] = ((double)rand() / RAND_MAX) * 2.0 - 1.0;
    }
}

// Perform feedforward pass
void feedforward(double input[INPUT_NODES], double hidden[HIDDEN_NODES], double output[OUTPUT_NODES],
                 double weights_ih[INPUT_NODES][HIDDEN_NODES], double weights_ho[HIDDEN_NODES][OUTPUT_NODES]) {
    for (int i = 0; i < HIDDEN_NODES; i++) {
        double activation = 0.0;
        for (int j = 0; j < INPUT_NODES; j++) {
            activation += input[j] * weights_ih[j][i];
        }
        hidden[i] = sigmoid(activation);
    }

    for (int i = 0; i < OUTPUT_NODES; i++) {
        double activation = 0.0;
        for (int j = 0; j < HIDDEN_NODES; j++) {
            activation += hidden[j] * weights_ho[j][i];
        }
        output[i] = sigmoid(activation);
    }
}

// Perform backpropagation and update weights
void backpropagate(double input[INPUT_NODES], double hidden[HIDDEN_NODES], double output[OUTPUT_NODES], double target[OUTPUT_NODES],
                   double weights_ih[INPUT_NODES][HIDDEN_NODES], double weights_ho[HIDDEN_NODES][OUTPUT_NODES]) {
    double delta_output[OUTPUT_NODES];
    double delta_hidden[HIDDEN_NODES];

    // Calculate error and delta for output layer
    for (int i = 0; i < OUTPUT_NODES; i++) {
        double error = target[i] - output[i];
        delta_output[i] = error * sigmoid_derivative(output[i]);
    }

    // Update weights between hidden and output layer
    for (int i = 0; i < HIDDEN_NODES; i++) {
        for (int j = 0; j < OUTPUT_NODES; j++) {
            weights_ho[i][j] += LEARNING_RATE * delta_output[j] * hidden[i];
        }
    }

    // Calculate delta for hidden layer
    for (int i = 0; i < HIDDEN_NODES; i++) {
        double error = 0.0;
        for (int j = 0; j < OUTPUT_NODES; j++) {
            error += delta_output[j] * weights_ho[i][j];
        }
        delta_hidden[i] = error * sigmoid_derivative(hidden[i]);
    }

    // Update weights between input and hidden layer
    for (int i = 0; i < INPUT_NODES; i++) {
        for (int j = 0; j < HIDDEN_NODES; j++) {
            weights_ih[i][j] += LEARNING_RATE * delta_hidden[j] * input[i];
        }
    }
}

