#define HIDDEN_SIZE 128 // Example hidden layer size
#define OUTPUT_SIZE 10 // 10 digits (0-9)
#define LEARNING_RATE 0.01
#define EPOCHS 10
#define BATCH_SIZE 32

// Activation function: Sigmoid
double sigmoid(double x) {
    return 1.0 / (1.0 + exp(-x));
}

double sigmoid_derivative(double x) {
    return x * (1.0 - x);
}

// Forward declaration
void train(double inputs[][INPUT_SIZE], int labels[], int num_samples);
void predict(double inputs[][INPUT_SIZE], int num_samples);

// Global weights and biases
double hidden_weights[INPUT_SIZE][HIDDEN_SIZE];
double output_weights[HIDDEN_SIZE][OUTPUT_SIZE];
double hidden_bias[HIDDEN_SIZE];
double output_bias[OUTPUT_SIZE];

void initialize_weights() {
    for (int i = 0; i < INPUT_SIZE; i++)
        for (int j = 0; j < HIDDEN_SIZE; j++)
            hidden_weights[i][j] = (double)rand() / (double)RAND_MAX;

    for (int i = 0; i < HIDDEN_SIZE; i++)
        for (int j = 0; j < OUTPUT_SIZE; j++)
            output_weights[i][j] = (double)rand() / (double)RAND_MAX;

    for (int i = 0; i < HIDDEN_SIZE; i++)
        hidden_bias[i] = (double)rand() / (double)RAND_MAX;

    for (int i = 0; i < OUTPUT_SIZE; i++)
        output_bias[i] = (double)rand() / (double)RAND_MAX;
}

void train(double inputs[][INPUT_SIZE], int labels[], int num_samples) {
    for (int epoch = 0; epoch < EPOCHS; epoch++) {
        for (int i = 0; i < num_samples; i += BATCH_SIZE) {
            double hidden_layer[HIDDEN_SIZE];
            double output_layer[OUTPUT_SIZE];
            double output_error[OUTPUT_SIZE];
            double hidden_error[HIDDEN_SIZE];

            // Forward propagation
            for (int j = 0; j < HIDDEN_SIZE; j++) {
                hidden_layer[j] = 0.0;
                for (int k = 0; k < INPUT_SIZE; k++) {
                    hidden_layer[j] += inputs[i + j][k] * hidden_weights[k][j];
                }
                hidden_layer[j] = sigmoid(hidden_layer[j] + hidden_bias[j]);
            }

            for (int j = 0; j < OUTPUT_SIZE; j++) {
                output_layer[j] = 0.0;
                for (int k = 0; k < HIDDEN_SIZE; k++) {
                    output_layer[j] += hidden_layer[k] * output_weights[k][j];
                }
                output_layer[j] = sigmoid(output_layer[j] + output_bias[j]);
            }

            // Calculate Output Error
            for (int j = 0; j < OUTPUT_SIZE; j++) {
                double target = (labels[i] == j) ? 1.0 : 0.0;
                output_error[j] = target - output_layer[j];
            }

            // Backpropagation
            for (int j = 0; j < OUTPUT_SIZE; j++) {
                for (int k = 0; k < HIDDEN_SIZE; k++) {
                    output_weights[k][j] += LEARNING_RATE * output_error[j] * sigmoid_derivative(output_layer[j]) * hidden_layer[k];
                }
                output_bias[j] += LEARNING_RATE * output_error[j] * sigmoid_derivative(output_layer[j]);
            }

            for (int j = 0; j < HIDDEN_SIZE; j++) {
                hidden_error[j] = 0.0;
                for (int k = 0; k < OUTPUT_SIZE; k++) {
                    hidden_error[j] += output_error[k] * output_weights[j][k];
                }
                for (int k = 0; k < INPUT_SIZE; k++) {
                    hidden_weights[k][j] += LEARNING_RATE * hidden_error[j] * sigmoid_derivative(hidden_layer[j]) * inputs[i + j][k];
                }
                hidden_bias[j] += LEARNING_RATE * hidden_error[j] * sigmoid_derivative(hidden_layer[j]);
            }
        }
        printf("Epoch %d completed.\n", epoch + 1);
    }
}

void predict(double inputs[][INPUT_SIZE], int num_samples) {
    // Similar to forward propagation, but only to classify.
    for (int i = 0; i < num_samples; i++) {
        double hidden_layer[HIDDEN_SIZE];
        double output_layer[OUTPUT_SIZE];

        // Forward propagation
        for (int j = 0; j < HIDDEN_SIZE; j++) {
            hidden_layer[j] = 0.0;
            for (int k = 0; k < INPUT_SIZE; k++) {
                hidden_layer[j] += inputs[i][k] * hidden_weights[k][j];
            }
            hidden_layer[j] = sigmoid(hidden_layer[j] + hidden_bias[j]);
        }

        for (int j = 0; j < OUTPUT_SIZE; j++) {
            output_layer[j] = 0.0;
            for (int k = 0; k < HIDDEN_SIZE; k++) {
                output_layer[j] += hidden_layer[k] * output_weights[k][j];
            }
            output_layer[j] = sigmoid(output_layer[j] + output_bias[j]);
        }

        // Output the predicted digit
        int predicted_digit = 0;
        for (int j = 1; j < OUTPUT_SIZE; j++) {
            if (output_layer[j] > output_layer[predicted_digit]) {
                predicted_digit = j;
            }
        }
        printf("Predicted Digit: %d\n", predicted_digit);
    }
}

