#include <math.h>
#include <stdio.h>
#include <stdlib.h>

// Define constants
#define NUM_INPUTS 784  // 28x28 images
#define NUM_HIDDEN 256
#define NUM_OUTPUTS 10  // 10 digits (0-9)
#define LEARNING_RATE 0.001
#define TRAINING_SET_SIZE 60000
#define TEST_SET_SIZE 10000

// Define the neural network structure
typedef struct {
    double inputs[NUM_INPUTS];
    double hidden[NUM_HIDDEN];
    double outputs[NUM_OUTPUTS];
} Network;

// Function to initialize the network
void init_network(Network* network) {
    for (int i = 0; i < NUM_INPUTS; i++) {
        network->inputs[i] = 0.0;
    }
    for (int i = 0; i < NUM_HIDDEN; i++) {
        network->hidden[i] = 0.0;
    }
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        network->outputs[i] = 0.0;
    }
}

// Function to load MNIST dataset
void load_dataset(double* inputs, double* labels, int size, char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Error opening file\n");
        exit(1);
    }

    int magic_number;
    int num_images;
    int width;
    int height;

    fread(&magic_number, 4, 1, file);
    fread(&num_images, 4, 1, file);
    fread(&width, 4, 1, file);
    fread(&height, 4, 1, file);

    for (int i = 0; i < size; i++) {
        for (int j = 0; j < NUM_INPUTS; j++) {
            unsigned char pixel;
            fread(&pixel, 1, 1, file);
            inputs[i * NUM_INPUTS + j] = (double)pixel / 255.0;
        }
        fread(&labels[i], 4, 1, file);
    }

    fclose(file);
}

// Sigmoid activation function
double sigmoid(double x) {
    return 1.0 / (1.0 + exp(-x));
}

// Softmax activation function
void softmax(double* outputs) {
    double sum = 0.0;
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        sum += exp(outputs[i]);
    }
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        outputs[i] = exp(outputs[i]) / sum;
    }
}

// Feedforward pass
void forward_pass(Network* network) {
    for (int i = 0; i < NUM_HIDDEN; i++) {
        double sum = 0.0;
        for (int j = 0; j < NUM_INPUTS; j++) {
            sum += network->inputs[j];
        }
        network->hidden[i] = sigmoid(sum);
    }
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        double sum = 0.0;
        for (int j = 0; j < NUM_HIDDEN; j++) {
            sum += network->hidden[j];
        }
        network->outputs[i] = sum;
    }
    softmax(network->outputs);
}

// Backpropagation
void backpropagation(Network* network, int label) {
    double output_errors[NUM_OUTPUTS];
    double hidden_errors[NUM_HIDDEN];

    for (int i = 0; i < NUM_OUTPUTS; i++) {
        output_errors[i] = network->outputs[i] - (i == label ? 1.0 : 0.0);
    }

    for (int i = 0; i < NUM_HIDDEN; i++) {
        double sum = 0.0;
        for (int j = 0; j < NUM_OUTPUTS; j++) {
            sum += output_errors[j];
        }
        hidden_errors[i] = sum;
    }

    for (int i = 0; i < NUM_HIDDEN; i++) {
        network->hidden[i] -= LEARNING_RATE * hidden_errors[i];
    }
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        network->outputs[i] -= LEARNING_RATE * output_errors[i];
    }
}

// Training function
void train(Network* network, double* inputs, int* labels, int size) {
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < NUM_INPUTS; j++) {
            network->inputs[j] = inputs[i * NUM_INPUTS + j];
        }
        forward_pass(network);
        backpropagation(network, labels[i]);
    }
}

// Testing function
int test(Network* network, double* inputs, int* labels, int size) {
    int correct = 0;
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < NUM_INPUTS; j++) {
            network->inputs[j] = inputs[i * NUM_INPUTS + j];
        }
        forward_pass(network);
        int predicted = 0;
        double max = network->outputs[0];
        for (int j = 1; j < NUM_OUTPUTS; j++) {
            if (network->outputs[j] > max) {
                predicted = j;
                max = network->outputs[j];
            }
        }
        if (predicted == labels[i]) {
            correct++;
        }
    }
    return correct;
}

int main() {
    Network network;
    init_network(&network);

    double training_inputs[TRAINING_SET_SIZE * NUM_INPUTS];
    int training_labels[TRAINING_SET_SIZE];
    load_dataset(training_inputs, training_labels, TRAINING_SET_SIZE, "train-images-idx3-ubyte");

    double test_inputs[TEST_SET_SIZE * NUM_INPUTS];
    int test_labels[TEST_SET_SIZE];
    load_dataset(test_inputs, test_labels, TEST_SET_SIZE, "t10k-images-idx3-ubyte");

    for (int i = 0; i < 10; i++) {
        train(&network, training_inputs, training_labels, TRAINING_SET_SIZE);
    }

    int correct = test(&network, test_inputs, test_labels, TEST_SET_SIZE);
    printf("Accuracy: %f%%\n", (double)correct / TEST_SET_SIZE * 100.0);

    return 0;
}

