#define EPOCHS 10

typedef struct {
    double *data;
    int label;
} MnistImage;

void load_mnist_images(const char *filename, MnistImage *images) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file");
        exit(1);
    }

    unsigned char bytes[4];
    fread(bytes, sizeof(unsigned char), 4, file);
    int magic_number = (bytes[0] << 24) + (bytes[1] << 16) + (bytes[2] << 8) + bytes[3];
    if (magic_number != 2051) {
        fprintf(stderr, "Invalid image file format\n");
        exit(1);
    }

    fread(bytes, sizeof(unsigned char), 4, file);
    int num_images = (bytes[0] << 24) + (bytes[1] << 16) + (bytes[2] << 8) + bytes[3];
    fread(bytes, sizeof(unsigned char), 4, file);
    int num_rows = (bytes[0] << 24) + (bytes[1] << 16) + (bytes[2] << 8) + bytes[3];
    fread(bytes, sizeof(unsigned char), 4, file);
    int num_cols = (bytes[0] << 24) + (bytes[1] << 16) + (bytes[2] << 8) + bytes[3];

    int total_pixels = num_rows * num_cols;
    for (int i = 0; i < num_images; i++) {
        images[i].data = (double *)malloc(total_pixels * sizeof(double));
        fread(images[i].data, sizeof(unsigned char), total_pixels, file);
        for (int j = 0; j < total_pixels; j++) {
            images[i].data[j] /= 255.0;
        }
    }

    fclose(file);
}

void load_mnist_labels(const char *filename, int *labels) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file");
        exit(1);
    }

    unsigned char bytes[4];
    fread(bytes, sizeof(unsigned char), 4, file);
    int magic_number = (bytes[0] << 24) + (bytes[1] << 16) + (bytes[2] << 8) + bytes[3];
    if (magic_number != 2049) {
        fprintf(stderr, "Invalid label file format\n");
        exit(1);
    }

    fread(bytes, sizeof(unsigned char), 4, file);
    int num_labels = (bytes[0] << 24) + (bytes[1] << 16) + (bytes[2] << 8) + bytes[3];

    fread(labels, sizeof(unsigned char), num_labels, file);

    fclose(file);
}

double sigmoid(double x) {
    return 1.0 / (1.0 + exp(-x));
}

double sigmoid_derivative(double x) {
    double s = sigmoid(x);
    return s * (1 - s);
}

void initialize_weights(double *weights, int size) {
    for (int i = 0; i < size; i++) {
        weights[i] = ((double)rand() / RAND_MAX) * 0.01;
    }
}

void forward_propagate(double *input, double *hidden_weights, double *output_weights, double *hidden_layer, double *output_layer) {
    // Hidden layer
    for (int i = 0; i < HIDDEN_SIZE; i++) {
        hidden_layer[i] = 0.0;
        for (int j = 0; j < INPUT_SIZE; j++) {
            hidden_layer[i] += input[j] * hidden_weights[i * INPUT_SIZE + j];
        }
        hidden_layer[i] = sigmoid(hidden_layer[i]);
    }

    // Output layer
    for (int i = 0; i < OUTPUT_SIZE; i++) {
        output_layer[i] = 0.0;
        for (int j = 0; j < HIDDEN_SIZE; j++) {
            output_layer[i] += hidden_layer[j] * output_weights[i * HIDDEN_SIZE + j];
        }
        output_layer[i] = sigmoid(output_layer[i]);
    }
}

void backward_propagate(double *input, double *hidden_weights, double *output_weights, double *hidden_layer, double *output_layer, int label) {
    double target[OUTPUT_SIZE] = {0.0};
    target[label] = 1.0;

    double output_errors[OUTPUT_SIZE];
    for (int i = 0; i < OUTPUT_SIZE; i++) {
        output_errors[i] = (target[i] - output_layer[i]) * sigmoid_derivative(output_layer[i]);
    }

    double hidden_errors[HIDDEN_SIZE];
    for (int i = 0; i < HIDDEN_SIZE; i++) {
        hidden_errors[i] = 0.0;
        for (int j = 0; j < OUTPUT_SIZE; j++) {
            hidden_errors[i] += output_errors[j] * output_weights[j * HIDDEN_SIZE + i];
        }
        hidden_errors[i] *= sigmoid_derivative(hidden_layer[i]);
    }

    // Update output weights
    for (int i = 0; i < OUTPUT_SIZE; i++) {
        for (int j = 0; j < HIDDEN_SIZE; j++) {
            output_weights[i * HIDDEN_SIZE + j] += LEARNING_RATE * output_errors[i] * hidden_layer[j];
        }
    }

    // Update hidden weights
    for (int i = 0; i < HIDDEN_SIZE; i++) {
        for (int j = 0; j < INPUT_SIZE; j++) {
            hidden_weights[i * INPUT_SIZE + j] += LEARNING_RATE * hidden_errors[i] * input[j];
        }
    }
}

int predict(double *input, double *hidden_weights, double *output_weights, double *hidden_layer, double *output_layer) {
    forward_propagate(input, hidden_weights, output_weights, hidden_layer, output_layer);
    int max_index = 0;
    double max_value = output_layer[0];
    for (int i = 1; i < OUTPUT_SIZE; i++) {
        if (output_layer[i] > max_value) {
            max_value = output_layer[i];
            max_index = i;
        }
    }
    return max_index;
}

