// DNS Record Types
typedef enum {
    A_RECORD,      // IPv4 Address
    AAAA_RECORD,   // IPv6 Address
    CNAME_RECORD,  // Canonical Name
    MX_RECORD      // Mail Exchange
} RecordType;

// DNS Record Structure
typedef struct {
    char domain[100];
    RecordType type;
    char value[100];
} DNSRecord;

// Predefined DNS Records
DNSRecord dnsDatabase[] = {
    {"example.com", A_RECORD, "192.168.1.100"},
    {"example.com", AAAA_RECORD, "2001:0db8:85a3:0000:0000:8a2e:0370:7334"},
    {"example.com", CNAME_RECORD, "www.example.com"},
    {"www.example.com", A_RECORD, "192.168.1.101"},
    {"mail.example.com", MX_RECORD, "mailserver.example.com"},
    {"mailserver.example.com", A_RECORD, "192.168.1.102"}
};

// Database size
const int DATABASE_SIZE = sizeof(dnsDatabase) / sizeof(dnsDatabase[0]);

// Function Prototypes
DNSRecord* lookupDNSRecord(const char* domain, RecordType type);
void printDNSRecord(const DNSRecord* record);
void resolveAndPrintRecords(const char* domain);

// DNS Resolver Function
DNSRecord* lookupDNSRecord(const char* domain, RecordType type) {
    for (int i = 0; i < DATABASE_SIZE; i++) {
        if (strcmp(dnsDatabase[i].domain, domain) == 0 && dnsDatabase[i].type == type) {
            return &dnsDatabase[i];
        }
    }
    return NULL;
}

// Print DNS Record Details
void printDNSRecord(const DNSRecord* record) {
    if (record == NULL) {
        printf("Record not found.\n");
        return;
    }

    switch (record->type) {
        case A_RECORD:
            printf("A Record: %s -> %s\n", record->domain, record->value);
            break;
        case AAAA_RECORD:
            printf("AAAA Record: %s -> %s\n", record->domain, record->value);
            break;
        case CNAME_RECORD:
            printf("CNAME Record: %s -> %s\n", record->domain, record->value);
            break;
        case MX_RECORD:
            printf("MX Record: %s -> %s\n", record->domain, record->value);
            break;
        default:
            printf("Unknown record type\n");
    }
}

// Resolve and Print All Available Records
void resolveAndPrintRecords(const char* domain) {
    RecordType recordTypes[] = {A_RECORD, AAAA_RECORD, CNAME_RECORD, MX_RECORD};
    int numTypes = sizeof(recordTypes) / sizeof(recordTypes[0]);

    printf("DNS Resolution for %s:\n", domain);
    for (int i = 0; i < numTypes; i++) {
        DNSRecord* record = lookupDNSRecord(domain, recordTypes[i]);
        if (record != NULL) {
            printDNSRecord(record);
        }
    }
}

// Advanced Recursive Resolver
void recursiveResolve(const char* domain) {
    DNSRecord* record = lookupDNSRecord(domain, CNAME_RECORD);

    if (record != NULL) {
        printf("Following CNAME: %s -> %s\n", domain, record->value);
        resolveAndPrintRecords(record->value);
    } else {
        resolveAndPrintRecords(domain);
    }
}

