    printf("Simple DNS Resolver Simulation\n");
    printf("------------------------------\n");

    // Direct Domain Resolution
    printf("\nDirect Domain Resolution:\n");
    recursiveResolve("example.com");

    // Subdomain Resolution
    printf("\nSubdomain Resolution:\n");
    recursiveResolve("www.example.com");

    // Mail Server Resolution
    printf("\nMail Server Resolution:\n");
    recursiveResolve("mail.example.com");

    return 0;
}

