#include <stdio.h>
#include <string.h>
#include <time.h>
#include <stdlib.h> // For rand() and srand()

// --- Constants ---
#define MAX_DOMAIN_LEN 256
#define MAX_IP_LEN 16 // e.g., "255.255.255.255\0"
#define MAX_CACHE_SIZE 10

// --- Data Structures ---

// Represents a single DNS record (domain, IP, TTL)
typedef struct {
    char domain[MAX_DOMAIN_LEN];
    char ip_address[MAX_IP_LEN];
    time_t expiration_time; // When the record expires in the cache
    int is_valid;           // 1 if valid, 0 if empty/invalid
} DNSRecord;

// Our simple DNS cache (an array of records)
DNSRecord dns_cache[MAX_CACHE_SIZE];
int cache_count = 0; // Current number of valid entries in cache

// --- Helper Functions ---

// Get current time in seconds since epoch
time_t get_current_time() {
    return time(NULL);
}

// --- DNS Cache Management ---

// Initializes the DNS cache
void init_dns_cache() {
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        dns_cache[i].is_valid = 0; // Mark all entries as empty
        memset(dns_cache[i].domain, 0, MAX_DOMAIN_LEN);
        memset(dns_cache[i].ip_address, 0, MAX_IP_LEN);
        dns_cache[i].expiration_time = 0;
    }
    cache_count = 0;
    printf("DNS Cache initialized.\n");
}

// Looks up a domain in the cache. Returns pointer to record if found and valid, else NULL.
DNSRecord* lookup_in_cache(const char* domain) {
    time_t current_time = get_current_time();

    printf("  [Cache] Looking up '%s'...\n", domain);
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        if (dns_cache[i].is_valid && strcmp(dns_cache[i].domain, domain) == 0) {
            if (dns_cache[i].expiration_time > current_time) {
                printf("  [Cache] Hit for '%s'! IP: %s (Expires in %ld seconds)\n",
                       domain, dns_cache[i].ip_address, dns_cache[i].expiration_time - current_time);
                return &dns_cache[i]; // Found and still valid
            } else {
                printf("  [Cache] Stale entry for '%s' found. Removing.\n", domain);
                dns_cache[i].is_valid = 0; // Mark as invalid
                cache_count--;
                return NULL; // Found but expired
            }
        }
    }
    printf("  [Cache] Miss for '%s'.\n", domain);
    return NULL; // Not found
}

// Adds or updates a record in the cache. Simple FIFO replacement if full.
void add_to_cache(const char* domain, const char* ip_address, int ttl_seconds) {
    // First, check if already exists to update
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        if (dns_cache[i].is_valid && strcmp(dns_cache[i].domain, domain) == 0) {
            strncpy(dns_cache[i].ip_address, ip_address, MAX_IP_LEN - 1);
            dns_cache[i].ip_address[MAX_IP_LEN - 1] = '\0';
            dns_cache[i].expiration_time = get_current_time() + ttl_seconds;
            printf("  [Cache] Updated '%s' in cache. IP: %s (TTL: %d)\n", domain, ip_address, ttl_seconds);
            return;
        }
    }

    // If not found, add a new entry
    if (cache_count < MAX_CACHE_SIZE) {
        // Find the first empty slot
        for (int i = 0; i < MAX_CACHE_SIZE; i++) {
            if (!dns_cache[i].is_valid) {
                 strncpy(dns_cache[i].domain, domain, MAX_DOMAIN_LEN - 1);
                 dns_cache[i].domain[MAX_DOMAIN_LEN - 1] = '\0';
                 strncpy(dns_cache[i].ip_address, ip_address, MAX_IP_LEN - 1);
                 dns_cache[i].ip_address[MAX_IP_LEN - 1] = '\0';
                 dns_cache[i].expiration_time = get_current_time() + ttl_seconds;
                 dns_cache[i].is_valid = 1;
                 cache_count++;
                 printf("  [Cache] Added '%s' to cache. IP: %s (TTL: %d)\n", domain, ip_address, ttl_seconds);
                 return;
            }
        }
    } else {
        // Cache is full, simple FIFO: remove the oldest (or just overwrite the first slot for simplicity)
        // A more advanced cache would use LRU (Least Recently Used)
        printf("  [Cache] Cache full. Evicting oldest entry to add '%s'.\n", domain);
        // For simplicity, we just overwrite the first slot. In a real FIFO, we'd shift entries.
        // Or find the entry with the smallest expiration_time and replace it.
        // Let's just overwrite the first one for demonstration.
        strncpy(dns_cache[0].domain, domain, MAX_DOMAIN_LEN - 1);
        dns_cache[0].domain[MAX_DOMAIN_LEN - 1] = '\0';
        strncpy(dns_cache[0].ip_address, ip_address, MAX_IP_LEN - 1);
        dns_cache[0].ip_address[MAX_IP_LEN - 1] = '\0';
        dns_cache[0].expiration_time = get_current_time() + ttl_seconds;
        dns_cache[0].is_valid = 1;
        printf("  [Cache] Overwritten slot 0 with '%s'. IP: %s (TTL: %d)\n", domain, ip_address, ttl_seconds);
    }
}

// --- Simulated Authoritative Server ---

// Simulates querying an authoritative DNS server for example.com
// This function hardcodes the IP for example.com.
const char* query_authoritative_server(const char* domain) {
    printf("  [Auth Server] Querying authoritative server for '%s'...\n", domain);
    // In a real scenario, this would be a network request.
    // Here, we hardcode the known IP for example.com.
    if (strcmp(domain, "example.com") == 0) {
        // Return a fixed IP address for example.com
        printf("  [Auth Server] Found IP for '%s': 93.184.216.34\n", domain);
        return "93.184.216.34"; // Known IP for example.com
    } else if (strcmp(domain, "example.org") == 0) {
         printf("  [Auth Server] Found IP for '%s': 93.184.217.20\n", domain);
         return "93.184.217.20"; // A different example domain
    } else {
        printf("  [Auth Server] Domain '%s' not found.\n", domain);
        return NULL; // Domain not found
    }
}

// --- Main DNS Resolver Logic ---

// Resolves a domain name to an IP address.
// Returns a dynamically allocated string with the IP, or NULL if not found.
// The caller is responsible for freeing the returned string.
char* resolve_dns(const char* domain) {
    char* result_ip = NULL;
    DNSRecord* cached_record;

    printf("\n[Resolver] Attempting to resolve '%s'...\n", domain);

    // 1. Check DNS cache
    cached_record = lookup_in_cache(domain);
    if (cached_record != NULL) {
        // Found in cache and valid
        result_ip = (char*)malloc(MAX_IP_LEN * sizeof(char));
        if (result_ip) {
            strncpy(result_ip, cached_record->ip_address, MAX_IP_LEN);
            result_ip[MAX_IP_LEN - 1] = '\0';
        }
        printf("[Resolver] Resolved '%s' from cache: %s\n", domain, result_ip);
        return result_ip;
    }

    // 2. If not in cache or expired, query authoritative server
    printf("[Resolver] Cache miss or expired. Querying authoritative server...\n");
    const char* authoritative_ip = query_authoritative_server(domain);

    if (authoritative_ip != NULL) {
        // Record found, add to cache
        int ttl = 60; // Example TTL: 60 seconds
        add_to_cache(domain, authoritative_ip, ttl);

        result_ip = (char*)malloc(MAX_IP_LEN * sizeof(char));
        if (result_ip) {
            strncpy(result_ip, authoritative_ip, MAX_IP_LEN);
            result_ip[MAX_IP_LEN - 1] = '\0';
        }
        printf("[Resolver] Resolved '%s' from authoritative source: %s\n", domain, result_ip);
        return result_ip;
    } else {
        printf("[Resolver] Could not resolve '%s'.\n", domain);
        return NULL; // Domain not found by authoritative server
    }
}

