#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <unistd.h>

#define DNS_SERVER "8.8.8.8"  // Google's public DNS server
#define DNS_PORT 53
#define BUFSIZE 512

// DNS header structure
struct DNS_HEADER {
    unsigned short id;     // Identification number

    unsigned char rd :1;   // Recursion Desired
    unsigned char tc :1;   // Truncated message
    unsigned char aa :1;   // Authoritative Answer
    unsigned char opcode :4; // Purpose of message
    unsigned char qr :1;   // Query/Response Flag

    unsigned char rcode :4; // Response code
    unsigned char cd :1;    // Checking Disabled
    unsigned char ad :1;    // Authenticated Data
    unsigned char z :1;     // Reserved
    unsigned char ra :1;    // Recursion Available

    unsigned short q_count; // Number of question entries
    unsigned short ans_count; // Number of answer entries
    unsigned short auth_count; // Number of authority entries
    unsigned short add_count; // Number of resource entries
};

// Question structure
struct QUESTION {
    unsigned short qtype;
    unsigned short qclass;
};

// Resource Record structure
#pragma pack(push, 1)
struct R_DATA {
    unsigned short type;
    unsigned short _class;
    unsigned int ttl;
    unsigned short data_len;
};
#pragma pack(pop)

// Address structure to hold a resolved IP
struct RES_RECORD {
    unsigned char *name;
    struct R_DATA *resource;
    unsigned char *rdata;
};

// Function prototypes
void dns_query(const char *host, int query_type);
void change_to_dns_format(unsigned char *dns, const unsigned char *host);
unsigned char* read_dns_name(unsigned char *reader, unsigned char *buffer, int *count);

int main() {
    const char *host = "example.com";
    dns_query(host, 1); // Type A query for IPv4 address
    return 0;
}

void dns_query(const char *host, int query_type) {
    unsigned char buf[BUFSIZE], *qname;
    struct DNS_HEADER *dns = NULL;
    struct QUESTION *qinfo = NULL;
    int sockfd, i;
    struct sockaddr_in dest;

    sockfd = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP); // UDP packet for DNS queries

    dest.sin_family = AF_INET;
    dest.sin_port = htons(DNS_PORT);
    dest.sin_addr.s_addr = inet_addr(DNS_SERVER); // DNS server's IP

    // Set up the DNS request
    dns = (struct DNS_HEADER *)&buf;
    dns->id = (unsigned short) htons(getpid());
    dns->qr = 0;     // This is a query
    dns->opcode = 0; // Standard query
    dns->aa = 0;     // Not Authoritative
    dns->tc = 0;     // Not Truncated
    dns->rd = 1;     // Recursion Desired
    dns->ra = 0;
    dns->z = 0;
    dns->ad = 0;
    dns->cd = 0;
    dns->rcode = 0;
    dns->q_count = htons(1);    // One question
    dns->ans_count = 0;
    dns->auth_count = 0;
    dns->add_count = 0;

    // Point to the query section
    qname = (unsigned char *)&buf[sizeof(struct DNS_HEADER)];
    change_to_dns_format(qname, host);
    qinfo = (struct QUESTION *)&buf[sizeof(struct DNS_HEADER) + (strlen((const char *)qname) + 1)]; 
    qinfo->qtype = htons(query_type); // Query type (A)
    qinfo->qclass = htons(1); // Internet class

    if (sendto(sockfd, buf, sizeof(struct DNS_HEADER) + (strlen((const char *)qname) + 1) + sizeof(struct QUESTION), 0, (struct sockaddr *)&dest, sizeof(dest)) < 0) {
        perror("Send failed");
    } else {
        printf("Query Sent\n");
    }

    // Receive the response
    i = sizeof(dest);
    if (recvfrom(sockfd, buf, BUFSIZE, 0, (struct sockaddr *)&dest, (socklen_t*)&i) < 0) {
        perror("Receive failed");
    } else {
        printf("Response received\n");
    }

    dns = (struct DNS_HEADER*) buf;

    // Move ahead of the DNS header and the query field
    unsigned char *reader = &buf[sizeof(struct DNS_HEADER) + (strlen((const char *)qname) + 1) + sizeof(struct QUESTION)];
    struct RES_RECORD answers[20]; // Allocate space for answers

    printf("The response contains : ");
    printf("\n %d Questions.", ntohs(dns->q_count));
    printf("\n %d Answers.", ntohs(dns->ans_count));
    printf("\n %d Authoritative Servers.", ntohs(dns->auth_count));
    printf("\n %d Additional records.\n\n", ntohs(dns->add_count));

    // Read through the answers
    for (i = 0; i < ntohs(dns->ans_count); i++) {
        answers[i].name = read_dns_name(reader, buf, &i);
        reader = reader + i;

        printf("\nName : %s", answers[i].name);

        answers[i].resource = (struct R_DATA *)(reader);
        reader = reader + sizeof(struct R_DATA);

        if (ntohs(answers[i].resource->type) == 1) { // If the response is an IPv4 address
            answers[i].rdata = (unsigned char *)malloc(ntohs(answers[i].resource->data_len));

            for (int j = 0; j < ntohs(answers[i].resource->data_len); j++) {
                answers[i].rdata[j] = reader[j];
            }
            answers[i].rdata[ntohs(answers[i].resource->data_len)] = '\0';
            reader = reader + ntohs(answers[i].resource->data_len);

            printf("\nIPv4 Address : %d.%d.%d.%d\n",
                    answers[i].rdata[0], answers[i].rdata[1], answers[i].rdata[2], answers[i].rdata[3]);
        } else {
            reader = reader + ntohs(answers[i].resource->data_len);
        }
    }

    close(sockfd);
}

// Convert a host name into a DNS name format
void change_to_dns_format(unsigned char *dns, const unsigned char *host) {
    int lock = 0;
    strcat((char *)host, ".");
    for (int i = 0; i < strlen((char *)host); i++) {
        if (host[i] == '.') {
            *dns++ = i - lock;
            for (; lock < i; lock++) {
                *dns++ = host[lock];
            }
            lock++;
        }
    }
    *dns++ = '\0';
}

// Read the name field in the DNS response
unsigned char* read_dns_name(unsigned char *reader, unsigned char *buffer, int *count) {
    unsigned char *name;
    int p = 0, jumped = 0, offset;
    *count = 1;
    name = (unsigned char *)malloc(256);
    name[0] = '\0';

    while (*reader != 0) {
        if (*reader >= 192) { // If it's an offset
            offset = (*reader)*256 + *(reader+1) - 49152; // Remove the two most significant bits
            reader = buffer + offset - 1;
            jumped = 1;
        } else {
            name[p++] = *reader;
        }

        reader++;
        if (jumped == 0) {
            *count = *count + 1;
        }
    }

    name[p] = '\0';
    if (jumped == 1) {
        *count = *count + 1;
    }

    // Convert the DNS name format back into a readable format
    int name_length = strlen((const char *)name);
    for (int i = 0; i < name_length; i++) {
        int len = name[i];
        for (int j = 0; j < len; j++) {
            name[i] = name[i+1];
            i++;
        }
        name[i] = '.';
    }
    name[name_length - 1] = '\0'; // Remove the last dot

    return name;
}

