#include <netdb.h>

// Structure to store DNS resolver result
typedef struct {
    char ip_address[INET_ADDRSTRLEN];
} dns_result;

// Function to resolve a domain name
dns_result* resolve_domain(const char* domain) {
    struct addrinfo hints, *res;
    int status;
    dns_result* result = NULL;

    // Initialize hints
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;  // IPv4
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = 0;      // Any protocol

    // Resolve domain name
    status = getaddrinfo(domain, NULL, &hints, &res);
    if (status != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return NULL;
    }

    // Get the IP address
    result = malloc(sizeof(dns_result));
    if (result == NULL) {
        freeaddrinfo(res);
        return NULL;
    }

    // Get the first IP address
    inet_ntop(res->ai_family, &((struct sockaddr_in*)res->ai_addr)->sin_addr, result->ip_address, INET_ADDRSTRLEN);

    // Free addrinfo
    freeaddrinfo(res);

    return result;
}

int main() {
    const char* domain = "example.com";
    dns_result* result = resolve_domain(domain);

    if (result != NULL) {
        printf("The IP address of %s is: %s\n", domain, result->ip_address);
        free(result);
    } else {
        printf("Failed to resolve %s\n", domain);
    }

    return 0;
