#define BUFFER_SIZE 512
#define DNS_PORT 53

// Function to create a DNS response for myserver.local
void create_dns_response(unsigned char *response, int *response_size) {
    unsigned char response_data[] = {
        0x00, 0x01, // Identifier: Just a random ID
        0x81, 0x80, // Flags: Standard query response, No error
        0x00, 0x01, // Questions: 1
        0x00, 0x01, // Answer RRs: 1
        0x00, 0x00, // Authority RRs: 0
        0x00, 0x00, // Additional RRs: 0
        0x07, 'm', 'y', 's', 'e', 'r', 'v', 'e', 'r', // QNAME: myserver
        0x05, 'l', 'o', 'c', 'a', 'l',              // QNAME: local
        0x00, // End of QNAME
        0x00, 0x01, // QTYPE: A
        0x00, 0x01, // QCLASS: IN
        0xC0, 0x0C, // Name (pointer to offset 12)
        0x00, 0x01, // TYPE: A
        0x00, 0x01, // CLASS: IN
        0x00, 0x00, 0x00, 0x3C, // TTL: 60 seconds
        0x00, 0x04, // RDLENGTH: 4 bytes
        0x7F, 0x00, 0x00, 0x01  // RDATA: 127.0.0.1
    };

    *response_size = sizeof(response_data);
    memcpy(response, response_data, *response_size);
}

int main() {
    int sockfd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_addr_len = sizeof(client_addr);
    unsigned char buffer[BUFFER_SIZE];

    // Create a UDP socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Set up the server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(DNS_PORT);

    // Bind the socket to the address and port
    if (bind(sockfd, (const struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    printf("DNS Resolver for 'myserver.local' is running\n");

    while (1) {
        int n = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, (struct sockaddr *)&client_addr, &client_addr_len);
        if (n < 0) {
            perror("recvfrom failed");
            continue;
        }

        printf("Received DNS query\n");

        // Create a DNS response
        unsigned char response[BUFFER_SIZE];
        int response_size;
        create_dns_response(response, &response_size);

        // Send the DNS response back to the client
        if (sendto(sockfd, response, response_size, 0, (struct sockaddr *)&client_addr, client_addr_len) < 0) {
            perror("sendto failed");
        } else {
            printf("Sent DNS response for 'myserver.local'\n");
        }
    }

    // Close the socket (this part is never reached in this loop)
    close(sockfd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <unistd.h>

#define DNS_SERVER "8.8.8.8" // Google's public DNS server
#define DNS_PORT 53
#define BUFFER_SIZE 512

// DNS header structure
struct DNSHeader {
    unsigned short id; // Identification
    unsigned char rd : 1; // Recursion Desired
    unsigned char tc : 1; // TrunCation
    unsigned char aa : 1; // Authoritative Answer
    unsigned char opcode : 4; // Purpose of message
    unsigned char qr : 1; // Query/Response flag
    unsigned short rcode : 4; // Response code
    unsigned short qcount; // Question Count
    unsigned short ancount; // Answer Count
    unsigned short nscount; // Authority Record Count
    unsigned short arcount; // Additional Record Count
};

// DNS question structure
struct DNSQuestion {
    unsigned short qtype; // Query Type
    unsigned short qclass; // Query class
};

// Function to create a DNS query
void create_dns_query(unsigned char *buffer, const char *domain) {
    struct DNSHeader *dns = (struct DNSHeader *)buffer;
    dns->id = htons(getpid()); // Random id
    dns->rd = 1; // Recursion Desired
    dns->qcount = htons(1); // One question

    // Format the domain name
    unsigned char *qname = buffer + sizeof(struct DNSHeader);
    char *token = strtok((char *)domain, ".");
    while (token) {
        *qname++ = strlen(token);
        strcpy((char *)qname, token);
        qname += strlen(token);
        token = strtok(NULL, ".");
    }
    *qname++ = 0; // Null-terminator

    // Set the question type and class
    struct DNSQuestion *question = (struct DNSQuestion *)qname;
    question->qtype = htons(1); // A record
    question->qclass = htons(1); // Internet
}

// Function to resolve the domain
void resolve_domain(const char *domain) {
    unsigned char buffer[BUFFER_SIZE];
    int sockfd;
    struct sockaddr_in dest;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("Socket creation failed");
        return;
    }

    // Set destination address
    dest.sin_family = AF_INET;
    dest.sin_port = htons(DNS_PORT);
    dest.sin_addr.s_addr = inet_addr(DNS_SERVER);

    // Create DNS query
    create_dns_query(buffer, domain);

    // Send DNS query
    if (sendto(sockfd, buffer, sizeof(struct DNSHeader) + strlen(domain) + 2 + sizeof(struct DNSQuestion), 0,
               (struct sockaddr *)&dest, sizeof(dest)) < 0) {
        perror("Send failed");
        close(sockfd);
        return;
    }

    // Receive DNS response
    socklen_t addr_len = sizeof(dest);
    int response_length = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, (struct sockaddr *)&dest, &addr_len);
    if (response_length < 0) {
        perror("Receive failed");
        close(sockfd);
        return;
    }

    struct DNSHeader *response_dns = (struct DNSHeader *)buffer;

    // Check if the response is valid
    if (ntohs(response_dns->ancount) > 0) {
        unsigned char *answer = buffer + sizeof(struct DNSHeader) + strlen(domain) + 2 + sizeof(struct DNSQuestion);
        struct in_addr ip_addr;
        memcpy(&ip_addr, answer + 12, 4); // An A record is 12 bytes after the answer

        printf("IP address for %s: %s\n", domain, inet_ntoa(ip_addr));
    } else {
        printf("No valid response received\n");
    }

    // Close the socket
    close(sockfd);
}

int main() {
    const char *domain = "myserver.local";
    resolve_domain(domain);
    return 0;
}

