// DNS record types
typedef enum {
    A_RECORD,     // IPv4 address record
    AAAA_RECORD,  // IPv6 address record
    CNAME_RECORD  // Canonical name record
} RecordType;

// DNS record structure
typedef struct {
    char domain[100];
    RecordType type;
    union {
        char ipv4[16];     // For A records
        char ipv6[40];     // For AAAA records
        char cname[100];   // For CNAME records
    } data;
} DNSRecord;

// Simulated DNS cache
DNSRecord dns_cache[] = {
    {"openai.com", A_RECORD, .data.ipv4 = "20.119.152.68"},
    {"openai.com", AAAA_RECORD, .data.ipv6 = "2600:1409:a:49c::d6c"},
    {"www.openai.com", CNAME_RECORD, .data.cname = "openai.com"}
};

// Number of records in the DNS cache
const int NUM_RECORDS = sizeof(dns_cache) / sizeof(dns_cache[0]);

// Function to resolve domain name
void resolve_domain(const char* domain, RecordType record_type) {
    int found = 0;

    printf("Resolving %s (Type: %s):\n", 
           domain, 
           record_type == A_RECORD ? "A" : 
           record_type == AAAA_RECORD ? "AAAA" : "CNAME");

    // Simulate DNS lookup in the cache
    for (int i = 0; i < NUM_RECORDS; i++) {
        // Check if domain and record type match
        if (strcmp(dns_cache[i].domain, domain) == 0 && 
            dns_cache[i].type == record_type) {

            found = 1;

            // Print resolved record based on type
            switch (record_type) {
                case A_RECORD:
                    printf("IPv4 Address: %s\n", dns_cache[i].data.ipv4);
                    break;
                case AAAA_RECORD:
                    printf("IPv6 Address: %s\n", dns_cache[i].data.ipv6);
                    break;
                case CNAME_RECORD:
                    printf("Canonical Name: %s\n", dns_cache[i].data.cname);
                    break;
            }
        }
    }

    // If no record found
    if (!found) {
        printf("No record found for %s\n", domain);
    }
}

// Function to perform actual DNS resolution using system resolver
void system_resolve(const char* domain) {
    struct hostent *host;
    struct in_addr **addr_list;

    // Use gethostbyname for DNS resolution
    host = gethostbyname(domain);

    if (host == NULL) {
        herror("DNS Resolution Failed");
        return;
    }

    // Print IP addresses
    addr_list = (struct in_addr **)host->h_addr_list;
    for (int i = 0; addr_list[i] != NULL; i++) {
        printf("Resolved IP: %s\n", inet_ntoa(*addr_list[i]));
    }
}

