// --- Function Implementations ---

// Initializes the random seed for simulate_delay
void init_cache() {
    srand(time(NULL));
}

// Adds a new record to the cache. Handles simple cache size limit (removes oldest).
void add_to_cache(DNSRecord new_record) {
    if (strlen(new_record.domain) == 0) return; // Don't add empty records

    // Check if domain already exists and update it
    CacheNode *current = cache_head;
    while (current != NULL) {
        if (strcmp(current->record.domain, new_record.domain) == 0) {
            printf("  Updating existing cache entry for '%s'.\n", new_record.domain);
            strcpy(current->record.ip_address, new_record.ip_address);
            current->record.ttl = new_record.ttl;
            current->record.last_lookup_time = new_record.last_lookup_time;
            return;
        }
        current = current->next;
    }

    CacheNode *new_node = (CacheNode *)malloc(sizeof(CacheNode));
    if (new_node == NULL) {
        perror("Failed to allocate memory for cache node");
        return;
    }
    new_node->record = new_record;
    new_node->next = NULL;

    // Simple cache size management: if cache is full, remove the "oldest" (tail) node.
    // In a real-world scenario, you'd use LRU (Least Recently Used) or similar.
    int count = 0;
    current = cache_head;
    while (current != NULL) {
        count++;
        current = current->next;
    }

    if (count >= CACHE_SIZE_LIMIT) {
        printf("  Cache size limit reached (%d). Removing oldest entry.\n", CACHE_SIZE_LIMIT);
        CacheNode *prev = NULL;
        CacheNode *temp = cache_head;
        if (temp == NULL) { // Should not happen if count > 0
            printf("  Cache is empty, cannot remove oldest.\n");
        } else if (temp->next == NULL) { // Only one item
            printf("  Removing single item from cache: %s\n", temp->record.domain);
            free(temp);
            cache_head = NULL;
        } else {
            while (temp->next != NULL) {
                prev = temp;
                temp = temp->next;
            }
            if (prev) {
                printf("  Removing oldest cache entry for '%s'.\n", temp->record.domain);
                prev->next = NULL;
                free(temp);
            }
        }
    }

    // Add new node to the head (most recently used, for this simple FIFO-like behavior)
    new_node->next = cache_head;
    cache_head = new_node;
    printf("  Added '%s' to cache.\n", new_record.domain);
}


// Searches for a domain in the cache. Returns pointer to record if found and valid, else NULL.
DNSRecord* search_cache(const char *domain) {
    CacheNode *current = cache_head;
    while (current != NULL) {
        if (strcmp(current->record.domain, domain) == 0) {
            time_t current_time = time(NULL);
            if ((current_time - current->record.last_lookup_time) < current->record.ttl) {
                printf("  Cache Hit for '%s'. Record is valid (TTL remaining: %lds).\n",
                       domain, (long)(current->record.ttl - (current_time - current->record.last_lookup_time)));
                return &(current->record);
            } else {
                printf("  Cache Hit for '%s', but record has EXPIRED (TTL passed).\n", domain);
                // In a more sophisticated resolver, you might mark this for refresh
                // and return a stale record while fetching a new one.
                // For simplicity, we treat it as not found if expired.
                return NULL;
            }
        }
        current = current->next;
    }
    printf("  Cache Miss for '%s'.\n", domain);
    return NULL;
}

// Displays the current contents of the DNS cache
void display_cache() {
    if (cache_head == NULL) {
        printf("  Cache is empty.\n");
        return;
    }
    CacheNode *current = cache_head;
    int i = 1;
    while (current != NULL) {
        time_t current_time = time(NULL);
        long time_since_lookup = (long)(current_time - current->record.last_lookup_time);
        long ttl_remaining = current->record.ttl - time_since_lookup;
        printf("  %d. Domain: %s, IP: %s, TTL: %ds (Remaining: %lds)\n",
               i++, current->record.domain, current->record.ip_address,
               current->record.ttl, ttl_remaining > 0 ? ttl_remaining : 0);
        current = current->next;
    }
}

// Simulates network latency
void simulate_delay(int milliseconds) {
    long pause_time_us = milliseconds * 1000 + (rand() % 1000); // Add some jitter
    usleep(pause_time_us); // usleep takes microseconds
}

// Simulates querying an upstream DNS server
char* resolve_domain_from_upstream(const char *domain) {
    printf("  Querying upstream DNS servers for '%s'...\n", domain);

    char *resolved_ip = NULL;

    // Simulate trying each DNS server
    for (int i = 0; i < MAX_DNS_SERVERS; ++i) {
        printf("    Trying DNS server: %s (%s) with latency %dms\n",
               dns_servers[i].name, dns_servers[i].ip_address, dns_servers[i].latency_ms);
        simulate_delay(dns_servers[i].latency_ms); // Simulate network latency

        // Simulate success or failure
        if (rand() % 10 < 8) { // 80% chance of success
            resolved_ip = (char *)malloc(16 * sizeof(char));
            if (resolved_ip == NULL) {
                perror("Failed to allocate memory for IP address");
                return NULL;
            }

            // Simulate different IPs for different domains, but consistent ones
            // For 'openai.com', always return a specific IP.
            // For others, return a mock IP based on their hash or something.
            if (strcmp(domain, "openai.com") == 0) {
                strcpy(resolved_ip, "104.18.9.155"); // Example IP for openai.com
            } else if (strcmp(domain, "example.com") == 0) {
                strcpy(resolved_ip, "93.184.216.34"); // Example IP for example.com
            } else {
                snprintf(resolved_ip, 16, "192.0.2.%d", (rand() % 254) + 1); // Mock IP
            }

            printf("    Successfully resolved '%s' to '%s' from %s.\n",
                   domain, resolved_ip, dns_servers[i].name);
            return resolved_ip;
        } else {
            printf("    DNS server %s timed out or failed for '%s'. Trying next...\n",
                   dns_servers[i].name, domain);
            // Simulate waiting for timeout (DNS_SERVER_TIMEOUT)
            simulate_delay(DNS_SERVER_TIMEOUT * 1000);
        }
    }

    printf("  All upstream DNS servers failed for '%s'.\n", domain);
    return NULL; // Failed to resolve
}

// Main DNS resolver function
char* dns_resolver(const char *domain) {
    // 1. Check Cache
    DNSRecord *cached_record = search_cache(domain);
    if (cached_record != NULL) {
        char *ip_copy = (char *)malloc(16 * sizeof(char));
        if (ip_copy == NULL) {
            perror("Failed to allocate memory for IP address copy");
            return NULL;
        }
        strcpy(ip_copy, cached_record->ip_address);
        return ip_copy; // Return IP from cache
    }

    // 2. If not in cache or expired, resolve from upstream
    char *upstream_ip = resolve_domain_from_upstream(domain);
    if (upstream_ip != NULL) {
        DNSRecord new_record;
        strncpy(new_record.domain, domain, sizeof(new_record.domain) - 1);
        new_record.domain[sizeof(new_record.domain) - 1] = '\0';
        strncpy(new_record.ip_address, upstream_ip, sizeof(new_record.ip_address) - 1);
        new_record.ip_address[sizeof(new_record.ip_address) - 1] = '\0';
        new_record.ttl = TTL_DEFAULT; // Set default TTL
        new_record.last_lookup_time = time(NULL); // Mark current time

        add_to_cache(new_record); // Add new record to cache
        return upstream_ip; // Return IP from upstream
    }

    return NULL; // Resolution failed
}

// Frees all memory allocated for the cache
void cleanup_cache() {
    CacheNode *current = cache_head;
    CacheNode *next;
    while (current != NULL) {
        next = current->next;
        printf("Freeing cache entry for '%s'.\n", current->record.domain);
        free(current);
        current = next;
    }
    cache_head = NULL;
    printf("DNS cache cleaned up.\n");
}

