#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netdb.h>
#include <arpa/inet.h>

// Function to perform DNS resolution
void resolve_domain(const char *domain) {
    struct addrinfo hints, *res;
    char ipstr[INET_ADDRSTRLEN];
    int status;

    // Zero out the hints structure
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // AF_INET for IPv4, AF_INET6 for IPv6
    hints.ai_socktype = SOCK_STREAM; // TCP stream sockets

    // Perform the DNS resolution
    if ((status = getaddrinfo(domain, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return;
    }

    // Extract the IP address from the results and convert it to a string
    void *addr;
    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    addr = &(ipv4->sin_addr);

    // Convert the IP to a string
    inet_ntop(res->ai_family, addr, ipstr, sizeof ipstr);
    printf("%s has IPv4 address: %s\n", domain, ipstr);

    // Free the memory allocated by getaddrinfo
    freeaddrinfo(res);
}

int main() {
    const char *domain = "openai.com";
    resolve_domain(domain);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <arpa/inet.h>

void resolve_domain(const char *domain) {
    struct addrinfo hints, *res;
    int status;

    // Set up the hints
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    // Resolve the domain name
    if ((status = getaddrinfo(domain, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return;
    }

    // Loop through the results and convert the IP to a readable string
    char ipstr[INET6_ADDRSTRLEN];
    for (struct addrinfo *p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char *ipver;

        // Get the pointer to the address itself
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // Convert the IP to a string and print it
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("%s: %s\n", ipver, ipstr);
    }

    // Free the linked list
    freeaddrinfo(res);
}

