#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Card structure
typedef struct {
    char* suit;
    char* value;
    int rank;
} Card;

// Deck structure
typedef struct {
    Card cards[52];
    int top;
} Deck;

// Function prototypes
void initializeDeck(Deck* deck);
void shuffleDeck(Deck* deck);
void dealCards(Deck* deck, Deck* player1, Deck* player2);
Card drawCard(Deck* deck);
void printCard(Card card);
int compareCards(Card card1, Card card2);
void playWar(Deck* player1, Deck* player2);

// Initialize the deck with 52 cards
void initializeDeck(Deck* deck) {
    char* suits[] = {"Hearts", "Diamonds", "Clubs", "Spades"};
    char* values[] = {"2", "3", "4", "5", "6", "7", "8", "9", "10", "Jack", "Queen", "King", "Ace"};

    deck->top = 0;

    for (int s = 0; s < 4; s++) {
        for (int v = 0; v < 13; v++) {
            deck->cards[deck->top].suit = suits[s];
            deck->cards[deck->top].value = values[v];
            deck->cards[deck->top].rank = v + 2;
            deck->top++;
        }
    }
}

// Shuffle the deck using Fisher-Yates algorithm
void shuffleDeck(Deck* deck) {
    for (int i = deck->top - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        Card temp = deck->cards[i];
        deck->cards[i] = deck->cards[j];
        deck->cards[j] = temp;
    }
}

// Deal cards equally between two players
void dealCards(Deck* deck, Deck* player1, Deck* player2) {
    player1->top = 0;
    player2->top = 0;

    for (int i = 0; i < deck->top; i++) {
        if (i % 2 == 0) {
            player1->cards[player1->top++] = deck->cards[i];
        } else {
            player2->cards[player2->top++] = deck->cards[i];
        }
    }
}

// Draw a card from the top of the deck
Card drawCard(Deck* deck) {
    return deck->cards[--deck->top];
}

// Print a card's details
void printCard(Card card) {
    printf("%s of %s", card.value, card.suit);
}

// Compare two cards and return the winner
int compareCards(Card card1, Card card2) {
    if (card1.rank > card2.rank) return 1;
    if (card1.rank < card2.rank) return -1;
    return 0;
}

// Play the War card game
void playWar(Deck* player1, Deck* player2) {
    int round = 1;

    while (player1->top > 0 && player2->top > 0) {
        printf("\nRound %d:\n", round);

        // Draw cards from each player
        Card p1Card = drawCard(player1);
        Card p2Card = drawCard(player2);

        printf("Player 1 drew: ");
        printCard(p1Card);
        printf("\nPlayer 2 drew: ");
        printCard(p2Card);
        printf("\n");

        // Compare cards
        int result = compareCards(p1Card, p2Card);

        if (result > 0) {
            printf("Player 1 wins the round!\n");
            player1->cards[player1->top++] = p1Card;
            player1->cards[player1->top++] = p2Card;
        } else if (result < 0) {
            printf("Player 2 wins the round!\n");
            player2->cards[player2->top++] = p1Card;
            player2->cards[player2->top++] = p2Card;
        } else {
            printf("War! Each player draws 3 cards.\n");

            // War scenario: draw 3 cards face down and one face up
            for (int i = 0; i < 3; i++) {
                if (player1->top > 0 && player2->top > 0) {
                    drawCard(player1);
                    drawCard(player2);
                } else {
                    break;
                }
            }
        }

        round++;

        // Optional: Add a pause between rounds
        // system("pause");
    }

    // Determine the winner
    if (player1->top == 0) {
        printf("\nPlayer 2 wins the game!\n");
    } else {
        printf("\nPlayer 1 wins the game!\n");
    }
}

int main() {
    // Seed random number generator
    srand(time(NULL));

    // Create decks
    Deck mainDeck, player1Deck, player2Deck;

    // Initialize and shuffle the main deck
    initializeDeck(&mainDeck);
    shuffleDeck(&mainDeck);

    // Deal cards to players
    dealCards(&mainDeck, &player1Deck, &player2Deck);

    // Play the game
    playWar(&player1Deck, &player2Deck);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define NUM_CARDS 52
#define NUM_SUITS 4
#define NUM_RANKS 13

typedef struct {
    int suit;
    int rank;
} Card;

typedef struct {
    Card *cards;
    int top;
    int size;
} Deck;

// Function prototypes
void initialize_deck(Deck *deck);
void shuffle_deck(Deck *deck);
void deal_cards(Deck *deck, Deck *player1, Deck *player2);
int compare_cards(Card card1, Card card2);
void play_war(Deck *player1, Deck *player2);
void add_card_to_deck(Deck *deck, Card card);
Card draw_card(Deck *deck);
void print_card(Card card);
void print_deck(Deck deck);

int main() {
    srand(time(NULL)); // Seed the random number generator

    Deck deck, player1, player2;

    // Initialize decks
    deck.cards = malloc(NUM_CARDS * sizeof(Card));
    player1.cards = malloc(NUM_CARDS * sizeof(Card));
    player2.cards = malloc(NUM_CARDS * sizeof(Card));

    deck.size = NUM_CARDS;
    player1.size = 0;
    player2.size = 0;
    deck.top = 0;
    player1.top = 0;
    player2.top = 0;

    // Set up the game
    initialize_deck(&deck);
    shuffle_deck(&deck);
    deal_cards(&deck, &player1, &player2);

    // Play the game
    play_war(&player1, &player2);

    // Determine the winner
    if (player1.size > player2.size) {
        printf("\nPlayer 1 wins with %d cards!\n", player1.size);
    } else if (player2.size > player1.size) {
        printf("\nPlayer 2 wins with %d cards!\n", player2.size);
    } else {
        printf("\nIt's a tie! Both players have %d cards.\n", player1.size);
    }

    // Free allocated memory
    free(deck.cards);
    free(player1.cards);
    free(player2.cards);

    return 0;
}

void initialize_deck(Deck *deck) {
    int i = 0;
    for (int suit = 0; suit < NUM_SUITS; suit++) {
        for (int rank = 0; rank < NUM_RANKS; rank++) {
            deck->cards[i].suit = suit;
            deck->cards[i].rank = rank;
            i++;
        }
    }
    deck->size = NUM_CARDS;
}

void shuffle_deck(Deck *deck) {
    for (int i = 0; i < NUM_CARDS; i++) {
        int j = rand() % NUM_CARDS;
        Card temp = deck->cards[i];
        deck->cards[i] = deck->cards[j];
        deck->cards[j] = temp;
    }
}

void deal_cards(Deck *deck, Deck *player1, Deck *player2) {
    for (int i = 0; i < NUM_CARDS; i++) {
        if (i % 2 == 0) {
            add_card_to_deck(player1, deck->cards[i]);
        } else {
            add_card_to_deck(player2, deck->cards[i]);
        }
    }
}

int compare_cards(Card card1, Card card2) {
    if (card1.rank > card2.rank) {
        return 1;
    } else if (card1.rank < card2.rank) {
        return -1;
    } else {
        return 0; // War!
    }
}

void play_war(Deck *player1, Deck *player2) {
    int round = 1;
    Card card1, card2;
    Deck war_pile;
    war_pile.cards = malloc(NUM_CARDS * sizeof(Card));
    war_pile.size = 0;
    war_pile.top = 0;

    while (player1->size > 0 && player2->size > 0) {
        printf("\nRound %d:\n", round++);

        // Draw cards
        card1 = draw_card(player1);
        card2 = draw_card(player2);

        printf("Player 1 plays: ");
        print_card(card1);
        printf("\nPlayer 2 plays: ");
        print_card(card2);
        printf("\n");

        // Add cards to war pile
        add_card_to_deck(&war_pile, card1);
        add_card_to_deck(&war_pile, card2);

        int result = compare_cards(card1, card2);

        if (result > 0) {
            // Player 1 wins the round
            printf("Player 1 wins this round!\n");
            while (war_pile.size > 0) {
                add_card_to_deck(player1, draw_card(&war_pile));
            }
        } else if (result < 0) {
            // Player 2 wins the round
            printf("Player 2 wins this round!\n");
            while (war_pile.size > 0) {
                add_card_to_deck(player2, draw_card(&war_pile));
            }
        } else {
            // War!
            printf("WAR!\n");

            // Each player puts down 3 cards (if they have them)
            for (int i = 0; i < 3; i++) {
                if (player1->size > 0) {
                    card1 = draw_card(player1);
                    add_card_to_deck(&war_pile, card1);
                }
                if (player2->size > 0) {
                    card2 = draw_card(player2);
                    add_card_to_deck(&war_pile, card2);
                }
            }
        }

        printf("Player 1 has %d cards. Player 2 has %d cards.\n", 
               player1->size, player2->size);
    }

    free(war_pile.cards);
}

void add_card_to_deck(Deck *deck, Card card) {
    deck->cards[deck->size++] = card;
}

Card draw_card(Deck *deck) {
