// --- Enums and Structs for Cards ---

// Enum for card suits
typedef enum {
    CLUBS,
    DIAMONDS,
    HEARTS,
    SPADES,
    NUM_SUITS // Sentinel for iterating or counting
} Suit;

// Enum for card ranks
// Assigning explicit values for easier comparison
typedef enum {
    TWO = 2, THREE, FOUR, FIVE, SIX, SEVEN, EIGHT, NINE, TEN,
    JACK, QUEEN, KING, ACE, // ACE is highest
    NUM_RANKS // Sentinel
} Rank;

// Struct to represent a playing card
typedef struct {
    Suit suit;
    Rank rank;
} Card;

// --- Helper Functions for Card Management ---

// Function to get the string representation of a suit
const char* getSuitString(Suit suit) {
    switch (suit) {
        case CLUBS:    return "Clubs";
        case DIAMONDS: return "Diamonds";
        case HEARTS:   return "Hearts";
        case SPADES:   return "Spades";
        default:       return "Unknown";
    }
}

// Function to get the string representation of a rank
const char* getRankString(Rank rank) {
    switch (rank) {
        case TWO:   return "Two";
        case THREE: return "Three";
        case FOUR:  return "Four";
        case FIVE:  return "Five";
        case SIX:   return "Six";
        case SEVEN: return "Seven";
        case EIGHT: return "Eight";
        case NINE:  return "Nine";
        case TEN:   return "Ten";
        case JACK:  return "Jack";
        case QUEEN: return "Queen";
        case KING:  return "King";
        case ACE:   return "Ace";
        default:    return "Unknown";
    }
}

// Function to print a card
void printCard(const Card* card) {
    printf("%s of %s", getRankString(card->rank), getSuitString(card->suit));
}

// --- Deck and Player Pile Management ---

#define DECK_SIZE 52
#define MAX_PLAYER_CARDS DECK_SIZE // Each player can theoretically hold all cards

// Initializes a standard 52-card deck
void initializeDeck(Card deck[]) {
    int cardIndex = 0;
    for (Suit s = CLUBS; s < NUM_SUITS; s++) {
        for (Rank r = TWO; r < NUM_RANKS; r++) {
            deck[cardIndex].suit = s;
            deck[cardIndex].rank = r;
            cardIndex++;
        }
    }
}

// Shuffles the deck using Fisher-Yates algorithm
void shuffleDeck(Card deck[], int numCards) {
    for (int i = numCards - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        Card temp = deck[i];
        deck[i] = deck[j];
        deck[j] = temp;
    }
}

// Deals cards to two players
// cards: The source deck
// player1_pile, player2_pile: Arrays to store player cards
// player1_count, player2_count: Pointers to update card counts
void dealCards(Card cards[], Card player1_pile[], int* player1_count,
               Card player2_pile[], int* player2_count) {
    *player1_count = 0;
    *player2_count = 0;

    for (int i = 0; i < DECK_SIZE; i++) {
        if (i % 2 == 0) { // Player 1
            player1_pile[*player1_count] = cards[i];
            (*player1_count)++;
        } else { // Player 2
            player2_pile[*player2_count] = cards[i];
            (*player2_count)++;
        }
    }
}

// Removes the top card from a player's pile
// player_pile: The array of cards
// player_count: Pointer to the player's card count
// Returns the card, or an invalid card if pile is empty
Card drawCard(Card player_pile[], int* player_count) {
    if (*player_count == 0) {
        Card empty_card = { .suit = -1, .rank = -1 }; // Sentinel for an invalid card
        return empty_card;
    }

    Card drawn_card = player_pile[0]; // Get the top card

    // Shift all remaining cards up one position
    for (int i = 0; i < *player_count - 1; i++) {
        player_pile[i] = player_pile[i + 1];
    }
    (*player_count)--; // Decrement card count

    return drawn_card;
}

// Adds cards to the bottom of a player's pile
// player_pile: The player's card array
// player_count: Pointer to player's card count
// won_cards: Array of cards to add
// won_count: Number of cards to add
void addCardsToPile(Card player_pile[], int* player_count,
                    const Card won_cards[], int won_count) {
    if (*player_count + won_count > MAX_PLAYER_CARDS) {
        // This should not happen in War unless a player has way too many cards.
        // For simplicity, we'll just add as many as possible within bounds.
        // In this specific War simulation, MAX_PLAYER_CARDS is DECK_SIZE, so it's always fine.
        printf("Warning: Player pile full, cannot add all cards.\n");
        won_count = MAX_PLAYER_CARDS - *player_count; // Add only what fits
    }

    // Add cards to the end of the pile
    memcpy(&player_pile[*player_count], won_cards, sizeof(Card) * won_count);
    (*player_count) += won_count;
}

// --- Game Logic ---

// Compares two cards based on rank for War
// Returns 1 if card1 wins, -1 if card2 wins, 0 for tie
int compareCards(const Card* card1, const Card* card2) {
    if (card1->rank > card2->rank) {
        return 1;
    } else if (card1->rank < card2->rank) {
        return -1;
    } else {
        return 0; // Tie
    }
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // --- Game Setup ---
    Card deck[DECK_SIZE];
    initializeDeck(deck);
    shuffleDeck(deck, DECK_SIZE);

    Card player1_pile[MAX_PLAYER_CARDS];
    int player1_count;
    Card player2_pile[MAX_PLAYER_CARDS];
    int player2_count;

    dealCards(deck, player1_pile, &player1_count, player2_pile, &player2_count);

    printf("--- WAR! The Card Game ---\n\n");
    printf("Player 1 starts with %d cards.\n", player1_count);
    printf("Player 2 starts with %d cards.\n", player2_count);
    printf("\n");

    int round = 0;
    Card common_pile[DECK_SIZE]; // Temporary pile for cards in current round/war
    int common_pile_count;

    // --- Game Loop ---
    while (player1_count > 0 && player2_count > 0) {
        round++;
        printf("--- Round %d ---\n", round);

        common_pile_count = 0; // Reset common pile for each round

        Card p1_card = drawCard(player1_pile, &player1_count);
        Card p2_card = drawCard(player2_pile, &player2_count);

        // Add the drawn cards to the common pile
        addCardsToPile(common_pile, &common_pile_count, &p1_card, 1);
        addCardsToPile(common_pile, &common_pile_count, &p2_card, 1);

        printf("Player 1 plays: ");
        printCard(&p1_card);
        printf("\n");
        printf("Player 2 plays: ");
        printCard(&p2_card);
        printf("\n");

        int comparison_result = compareCards(&p1_card, &p2_card);

        if (comparison_result == 1) { // Player 1 wins
            printf("Player 1 wins the round!\n");
            addCardsToPile(player1_pile, &player1_count, common_pile, common_pile_count);
        } else if (comparison_result == -1) { // Player 2 wins
            printf("Player 2 wins the round!\n");
            addCardsToPile(player2_pile, &player2_count, common_pile, common_pile_count);
        } else { // Tie - War!
            printf("It's a WAR!!!\n");
            int war_tie_count = 0; // To track consecutive wars

            while (comparison_result == 0) { // Continue war until a winner is determined
                war_tie_count++;
                printf("--- War %d ---\n", war_tie_count);

                // Check if players have enough cards for War (1 burn + 1 battle)
                if (player1_count < 2) {
                    printf("Player 1 doesn't have enough cards to go to war! Player 2 wins the game!\n");
                    player1_count = 0; // Eliminate player 1
                    break;
                }
                if (player2_count < 2) {
                    printf("Player 2 doesn't have enough cards to go to war! Player 1 wins the game!\n");
                    player2_count = 0; // Eliminate player 2
                    break;
                }

                // Players put one card face down (burn card)
                Card p1_burn_card = drawCard(player1_pile, &player1_count);
                Card p2_burn_card = drawCard(player2_pile, &player2_count);
                addCardsToPile(common_pile, &common_pile_count, &p1_burn_card, 1);
                addCardsToPile(common_pile, &common_pile_count, &p2_burn_card, 1);
                printf("Players place one card face down...\n");

                // Players put one card face up (battle card)
                p1_card = drawCard(player1_pile, &player1_count);
                p2_card = drawCard(player2_pile, &player2_count);
                addCardsToPile(common_pile, &common_pile_count, &p1_card, 1);
                addCardsToPile(common_pile, &common_pile_count, &p2_card, 1);

                printf("Player 1's battle card: ");
                printCard(&p1_card);
                printf("\n");
                printf("Player 2's battle card: ");
                printCard(&p2_card);
                printf("\n");

                comparison_result = compareCards(&p1_card, &p2_card);

                if (comparison_result == 1) { // Player 1 wins the war
                    printf("Player 1 wins the war, taking %d cards!\n", common_pile_count);
                    addCardsToPile(player1_pile, &player1_count, common_pile, common_pile_count);
                } else if (comparison_result == -1) { // Player 2 wins the war
                    printf("Player 2 wins the war, taking %d cards!\n", common_pile_count);
                    addCardsToPile(player2_pile, &player2_count, common_pile, common_pile_count);
                } else {
                    printf("Another tie! Continuing the war...\n");
                }
            } // End of war loop
        }

        printf("Player 1 has %d cards. Player 2 has %d cards.\n", player1_count, player2_count);
        printf("---------------------------\n\n");
        // Optional: Add a delay to make it easier to follow
        // #include <unistd.h> // For sleep()
        // sleep(1); // Sleep for 1 second
    } // End of game loop

    // --- Game End ---
    printf("--- Game Over ---\n");
    if (player1_count == 0 && player2_count == 0) {
        printf("Both players ran out of cards simultaneously? (Should not happen in normal War).\n");
    } else if (player1_count == 0) {
        printf("Player 1 ran out of cards. Player 2 wins the game in %d rounds!\n", round);
    } else { // player2_count == 0
        printf("Player 2 ran out of cards. Player 1 wins the game in %d rounds!\n", round);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define DECK_SIZE 52
#define MAX_TURNS 10000

typedef struct {
    int cards[DECK_SIZE];
    int size;
} Deck;

void initialize_deck(int *deck) {
    // 0-12: 2-Ace of Hearts, 13-25: 2-Ace of Diamonds, etc.
    for (int i = 0; i < DECK_SIZE; ++i)
        deck[i] = i % 13 + 2; // Value 2-14 (J=11, Q=12, K=13, A=14)
}

void shuffle_deck(int *deck) {
    for (int i = DECK_SIZE-1; i > 0; --i) {
        int j = rand() % (i + 1);
        int temp = deck[i];
        deck[i] = deck[j];
        deck[j] = temp;
    }
}

void deck_add_bottom(Deck *d, int card) {
    d->cards[d->size++] = card;
}

int deck_draw_top(Deck *d) {
    int card = d->cards[0];
    for (int i = 1; i < d->size; ++i)
        d->cards[i-1] = d->cards[i];
    d->size--;
    return card;
}

void deal(Deck *player1, Deck *player2, int *shuffled_deck) {
    player1->size = 0;
    player2->size = 0;
    for (int i = 0; i < DECK_SIZE; ++i) {
        if (i % 2 == 0)
            player1->cards[player1->size++] = shuffled_deck[i];
        else
            player2->cards[player2->size++] = shuffled_deck[i];
    }
}

void print_card(int val) {
    if (val <= 10)
        printf("%d", val);
    else if (val == 11)
        printf("J");
    else if (val == 12)
        printf("Q");
    else if (val == 13)
        printf("K");
    else if (val == 14)
        printf("A");
}

int main() {
    srand((unsigned int)time(NULL));

    int deck[DECK_SIZE];
    initialize_deck(deck);
    shuffle_deck(deck);

    Deck p1, p2;
    deal(&p1, &p2, deck);

    int turn = 0;
    while (p1.size > 0 && p2.size > 0 && turn < MAX_TURNS) {
        turn++;
        int pile[DECK_SIZE*2];
        int pile_size = 0;

        // Each player draws top card
        int c1 = deck_draw_top(&p1);
        int c2 = deck_draw_top(&p2);
        pile[pile_size++] = c1;
        pile[pile_size++] = c2;

        // Uncomment next line to see detailed output
        // printf("Turn %d: Player1: ", turn); print_card(c1); printf(" vs Player2: "); print_card(c2); printf("\n");

        // Handle war
        while (c1 == c2) {
            // War: each player puts 1 card face down (if possible), then one card face up
            if (p1.size < 2 || p2.size < 2) {
                // Player cannot continue war, loses
                if (p1.size < 2) {
                    printf("Player 1 cannot continue war. Player 2 wins!\n");
                    return 0;
                } else {
                    printf("Player 2 cannot continue war. Player 1 wins!\n");
                    return 0;
                }
            }
            pile[pile_size++] = deck_draw_top(&p1); // face down
            pile[pile_size++] = deck_draw_top(&p2); // face down
            c1 = deck_draw_top(&p1);
            c2 = deck_draw_top(&p2);
            pile[pile_size++] = c1;
            pile[pile_size++] = c2;
        }

        // Winner collects pile
        if (c1 > c2) {
            for (int i = 0; i < pile_size; ++i)
                deck_add_bottom(&p1, pile[i]);
        } else {
            for (int i = 0; i < pile_size; ++i)
                deck_add_bottom(&p2, pile[i]);
        }
    }

    printf("Game ended after %d turns.\n", turn);
    if (p1.size == 0)
        printf("Player 2 wins!\n");
    else if (p2.size == 0)
        printf("Player 1 wins!\n");
    else
        printf("Game is a draw.\n");
    return 0;
}

