#define DECK_SIZE 52
#define RANKS 13

typedef struct {
    int cards[DECK_SIZE];
    int size;
} Deck;

void initializeDeck(Deck *deck) {
    for (int i = 0; i < DECK_SIZE; i++) {
        deck->cards[i] = i % RANKS;
    }
    deck->size = DECK_SIZE;
}

void shuffleDeck(Deck *deck) {
    for (int i = 0; i < deck->size; i++) {
        int randIdx = rand() % deck->size;
        int temp = deck->cards[i];
        deck->cards[i] = deck->cards[randIdx];
        deck->cards[randIdx] = temp;
    }
}

void dealDecks(Deck *deck, Deck *deck1, Deck *deck2) {
    for (int i = 0; i < deck->size; i++) {
        if (i % 2 == 0) {
            deck1->cards[deck1->size++] = deck->cards[i];
        } else {
            deck2->cards[deck2->size++] = deck->cards[i];
        }
    }
}

void playWar(Deck *deck1, Deck *deck2) {
    while (deck1->size > 0 && deck2->size > 0) {
        int card1 = deck1->cards[0], card2 = deck2->cards[0];

        // Move top card from each deck to bottom
        for (int i = 1; i < deck1->size; i++) deck1->cards[i - 1] = deck1->cards[i];
        deck1->size--;

        for (int i = 1; i < deck2->size; i++) deck2->cards[i - 1] = deck2->cards[i];
        deck2->size--;

        if (card1 > card2) {
            deck1->cards[deck1->size++] = card1;
            deck1->cards[deck1->size++] = card2;
            printf("Player 1 wins the round! (%d vs %d)\n", card1, card2);
        } else if (card2 > card1) {
            deck2->cards[deck2->size++] = card1;
            deck2->cards[deck2->size++] = card2;
            printf("Player 2 wins the round! (%d vs %d)\n", card2, card1);
        } else {
            printf("War! (%d vs %d)\n", card1, card2);
            int warCards1[4] = {card1}, warCards2[4] = {card2};
            int addedSize = 1;

            while (deck1->size > 3 && deck2->size > 3) {
                for (int i = 0; i < 3; i++) {
                    warCards1[addedSize] = deck1->cards[0];
                    for (int j = 1; j < deck1->size; j++) deck1->cards[j-1] = deck1->cards[j];
                    warCards2[addedSize++] = deck2->cards[0];
                    for (int j = 1; j < deck2->size; j++) deck2->cards[j-1] = deck2->cards[j];
                }

                if (deck1->size > 0 && deck2->size > 0) {
                    warCards1[addedSize] = deck1->cards[0];
                    warCards2[addedSize] = deck2->cards[0];

                    if (warCards1[addedSize] > warCards2[addedSize]) {
                        printf("Player 1 wins the war! (%d vs %d)\n", warCards1[addedSize], warCards2[addedSize]);
                        for(int i = 0; i <= addedSize; i++) {
                            deck1->cards[deck1->size++] = warCards1[i];
                            deck1->cards[deck1->size++] = warCards2[i];
                        }
                        break;
                    } else if (warCards2[addedSize] > warCards1[addedSize]) {
                        printf("Player 2 wins the war! (%d vs %d)\n", warCards2[addedSize], warCards1[addedSize]);
                        for(int i = 0; i <= addedSize; i++) {
                            deck2->cards[deck2->size++] = warCards1[i];
                            deck2->cards[deck2->size++] = warCards2[i];
                        }
                        break;
                    }
                }
                addedSize++;
            }
        }
    }
}

