// Define the ranks and suits of a deck
typedef enum {
    ACE = 1,
    TWO,
    THREE,
    FOUR,
    FIVE,
    SIX,
    SEVEN,
    EIGHT,
    NINE,
    TEN,
    JACK,
    QUEEN,
    KING
} Rank;

typedef enum {
    HEARTS,
    DIAMONDS,
    CLUBS,
    SPADES
} Suit;

// Define a card structure
typedef struct {
    Rank rank;
    Suit suit;
} Card;

// Define a deck structure
typedef struct {
    Card cards[52];
    int size;
} Deck;

// Function to create a new deck
Deck create_deck() {
    Deck deck;
    deck.size = 0;

    for (int i = 0; i < 4; i++) {
        for (int j = 1; j <= 13; j++) {
            deck.cards[deck.size].rank = j;
            deck.cards[deck.size].suit = i;
            deck.size++;
        }
    }

    return deck;
}

// Function to shuffle the deck
void shuffle_deck(Deck* deck) {
    srand(time(NULL));

    for (int i = deck->size - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        Card temp = deck->cards[i];
        deck->cards[i] = deck->cards[j];
        deck->cards[j] = temp;
    }
}

// Function to deal a card from the deck
Card deal_card(Deck* deck) {
    Card card = deck->cards[0];
    for (int i = 0; i < deck->size - 1; i++) {
        deck->cards[i] = deck->cards[i + 1];
    }
    deck->size--;
    return card;
}

// Function to determine the winner of a round
void determine_winner(Card player1_card, Card player2_card, Deck* player1_deck, Deck* player2_deck) {
    if (player1_card.rank > player2_card.rank) {
        printf("Player 1 wins this round!\n");
        player1_deck->cards[player1_deck->size].rank = player1_card.rank;
        player1_deck->cards[player1_deck->size].suit = player1_card.suit;
        player1_deck->size++;
        player1_deck->cards[player1_deck->size].rank = player2_card.rank;
        player1_deck->cards[player1_deck->size].suit = player2_card.suit;
        player1_deck->size++;
    } else if (player1_card.rank < player2_card.rank) {
        printf("Player 2 wins this round!\n");
        player2_deck->cards[player2_deck->size].rank = player1_card.rank;
        player2_deck->cards[player2_deck->size].suit = player1_card.suit;
        player2_deck->size++;
        player2_deck->cards[player2_deck->size].rank = player2_card.rank;
        player2_deck->cards[player2_deck->size].suit = player2_card.suit;
        player2_deck->size++;
    } else {
        printf("It's a tie! Going to war...\n");
        // Simulate the war
        for (int i = 0; i < 3; i++) {
            if (player1_deck->size > 0 && player2_deck->size > 0) {
