#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define card ranks and suits
typedef enum {
    ACE, TWO, THREE, FOUR, FIVE, SIX, SEVEN, EIGHT, NINE, TEN, JACK, QUEEN, KING
} Rank;

typedef enum {
    HEARTS, DIAMONDS, CLUBS, SPADES
} Suit;

// Define a card structure
typedef struct {
    Rank rank;
    Suit suit;
} Card;

// Function to initialize a deck of cards
void initializeDeck(Card deck[]) {
    int index = 0;
    for (Suit suit = HEARTS; suit <= SPADES; suit++) {
        for (Rank rank = ACE; rank <= KING; rank++) {
            deck[index].rank = rank;
            deck[index].suit = suit;
            index++;
        }
    }
}

// Function to shuffle the deck
void shuffleDeck(Card deck[]) {
    for (int i = 0; i < 52; i++) {
        int j = rand() % 52;
        Card temp = deck[i];
        deck[i] = deck[j];
        deck[j] = temp;
    }
}

// Function to compare two cards
int compareCards(Card card1, Card card2) {
    return card1.rank - card2.rank;
}

// Function to print a card
void printCard(Card card) {
    const char *rankNames[] = {"Ace", "2", "3", "4", "5", "6", "7", "8", "9", "10", "Jack", "Queen", "King"};
    const char *suitNames[] = {"Hearts", "Diamonds", "Clubs", "Spades"};
    printf("%s of %s", rankNames[card.rank], suitNames[card.suit]);
}

// Function to play a round of War
void playRound(Card player1Deck[], Card player2Deck[], int *player1Count, int *player2Count) {
    if (*player1Count <= 0 || *player2Count <= 0) {
        return;
    }

    Card card1 = player1Deck[0];
    Card card2 = player2Deck[0];

    printf("Player 1: ");
    printCard(card1);
    printf(" vs. Player 2: ");
    printCard(card2);
    printf("\n");

    int result = compareCards(card1, card2);

    if (result > 0) {
        printf("Player 1 wins the round!\n");
        *player1Count += 1;
        *player2Count -= 1;
    } else if (result < 0) {
        printf("Player 2 wins the round!\n");
        *player1Count -= 1;
        *player2Count += 1;
    } else {
        printf("War!\n");
        int warCount = 3;
        if (*player1Count < warCount || *player2Count < warCount) {
            printf("Not enough cards for war. Player 1 wins!\n");
            *player1Count += *player2Count;
            *player2Count = 0;
            return;
        }

        for (int i = 0; i < warCount; i++) {
            if (compareCards(player1Deck[i], player2Deck[i]) != 0) {
                if (compareCards(player1Deck[i], player2Deck[i]) > 0) {
                    printf("Player 1 wins the war!\n");
                    *player1Count += warCount + 1;
                    *player2Count -= warCount + 1;
                } else {
                    printf("Player 2 wins the war!\n");
                    *player1Count -= warCount + 1;
                    *player2Count += warCount + 1;
                }
                return;
            }
        }

        printf("War is a tie. No cards change hands.\n");
    }

    // Move cards to the end of the deck
    for (int i = 0; i < *player1Count - 1; i++) {
        player1Deck[i] = player1Deck[i + 1];
    }
    for (int i = 0; i < *player2Count - 1; i++) {
        player2Deck[i] = player2Deck[i + 1];
    }
}

// Main function
int main() {
    Card deck[52];
    Card player1Deck[26];
    Card player2Deck[26];

    initializeDeck(deck);
    shuffleDeck(deck);

    for (int i = 0; i < 26; i++) {
        player1Deck[i] = deck[i];
        player2Deck[i] = deck[i + 26];
    }

    int player1Count = 26;
    int player2Count = 26;

    srand(time(NULL));

    while (player1Count > 0 && player2Count > 0) {
        playRound(player1Deck, player2Deck, &player1Count, &player2Count);
        printf("Player 1 cards: %d, Player 2 cards: %d\n", player1Count, player2Count);
        printf("Press Enter to continue...\n");
        getchar();
    }

    if (player1Count == 0) {
        printf("Player 2 wins the game!\n");
    } else {
        printf("Player 1 wins the game!\n");
    }

    return 0;
}

