// Initialize vending machine
void initializeVendingMachine(VendingMachine *vm) {
    vm->itemCount = 0;
    vm->balance = 0.0;
}

// Add item to vending machine
void addItem(VendingMachine *vm, const char *name, float price, int quantity) {
    if (vm->itemCount < MAX_ITEMS) {
        strcpy(vm->items[vm->itemCount].name, name);
        vm->items[vm->itemCount].price = price;
        vm->items[vm->itemCount].quantity = quantity;
        vm->itemCount++;
    } else {
        printf("Vending machine is full. Cannot add more items.\n");
    }
}

// Display available items
void displayItems(VendingMachine *vm) {
    printf("\n--- Available Items ---\n");
    for (int i = 0; i < vm->itemCount; i++) {
        printf("%d. %s - $%.2f (Qty: %d)\n", 
               i + 1, 
               vm->items[i].name, 
               vm->items[i].price, 
               vm->items[i].quantity);
    }
}

// Select and purchase an item
int selectItem(VendingMachine *vm, int index) {
    // Check if index is valid
    if (index < 0 || index >= vm->itemCount) {
        printf("Invalid item selection.\n");
        return -1;
    }

    // Check item availability
    if (vm->items[index].quantity <= 0) {
        printf("Item out of stock.\n");
        return -1;
    }

    // Check sufficient balance
    if (vm->balance < vm->items[index].price) {
        printf("Insufficient balance. Please insert more money.\n");
        return -1;
    }

    // Deduct price from balance
    vm->balance -= vm->items[index].price;

    // Reduce item quantity
    vm->items[index].quantity--;

    printf("Dispensing %s\n", vm->items[index].name);
    return 0;
}

// Insert money into vending machine
void insertMoney(VendingMachine *vm, float amount) {
    if (amount > 0) {
        vm->balance += amount;
        printf("Current balance: $%.2f\n", vm->balance);
    } else {
        printf("Invalid amount.\n");
    }
}

// Return change
void returnChange(VendingMachine *vm) {
    if (vm->balance > 0) {
        printf("Returning change: $%.2f\n", vm->balance);
        vm->balance = 0.0;
    } else {
        printf("No change to return.\n");
    }
}

