// Handles the payment process
void processPayment(int itemIndex, float itemPrice) {
    float amountPaid = 0.0;
    float remainingPayment = itemPrice;

    printf("--- Payment ---\n");
    printf("Item: %s - Price: $%.2f\n", items[itemIndex].name, itemPrice);

    while (remainingPayment > 0.001) { // Use a small epsilon for float comparison
        printf("Remaining: $%.2f. Enter amount (e.g., 1.00, 0.25): ", remainingPayment);
        float inputAmount;
        scanf("%f", &inputAmount);

        if (inputAmount <= 0) {
            printf("Invalid amount. Please enter a positive value.\n");
            continue;
        }

        amountPaid += inputAmount;
        remainingPayment -= inputAmount;

        if (remainingPayment > 0.001) {
            printf("Current amount inserted: $%.2f. Need $%.2f more.\n", amountPaid, remainingPayment);
        }
    }

    float change = amountPaid - itemPrice;

    if (change < -0.001) { // Should not happen with the loop, but a safeguard
        printf("Error: Insufficient payment. Transaction cancelled.\n");
        printf("Returning $%.2f.\n", amountPaid);
        return;
    }

    if (cashInTray < change) {
        printf("Sorry, the machine does not have enough change for your purchase.\n");
        printf("Returning your money: $%.2f\n", amountPaid);
        return;
    }

    // Successful purchase
    items[itemIndex].quantity--;
    cashInTray += itemPrice; // Add the item's price to the machine's cash
    printf("\nDispensing %s...\n", items[itemIndex].name);
    printf("Enjoy your %s!\n", items[itemIndex].name);

    if (change > 0.001) {
        printf("Your change: $%.2f\n", change);
        returnChange(change);
        cashInTray -= change; // Deduct change from machine's cash
    } else {
        printf("No change needed.\n");
    }
    printf("Transaction complete.\n");
}

