                printf("Could not find a unique ID. Max items reached or unusual ID mapping.\n");
                return;
            }
        }
        printf("Assigning new ID: %d\n", id);
    } else { // Edit existing item
        for (int i = 0; i < numItems; i++) {
            if (items[i].id == id) {
                foundIndex = i;
