        strcpy(items[foundIndex].name, name);
        items[foundIndex].price = price;
        items[foundIndex].quantity = quantity;
        printf("Item ID %d updated successfully.\n", id);
    } else { // Add new
        addItemToMachine(id, name, price, quantity);
        printf("New item ID %d added successfully.\n", id);
    }
}

