#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_GENERATIONS 1000
#define MAX_CELLS 1000

// Function to convert decimal to binary
void decimalToBinary(int decimal, char *binary, int bits) {
    for (int i = bits - 1; i >= 0; i--) {
        binary[bits - 1 - i] = ((decimal >> i) & 1) + '0';
    }
    binary[bits] = '\0';
}

// Function to apply cellular automata rules
void applyCellularAutomataRules(int *currentGeneration, int *nextGeneration, 
                                 int cells, int *rules, int ruleCount) {
    for (int i = 0; i < cells; i++) {
        // Get left, center, and right cell values with wrap-around
        int left = (i == 0) ? currentGeneration[cells - 1] : currentGeneration[i - 1];
        int center = currentGeneration[i];
        int right = (i == cells - 1) ? currentGeneration[0] : currentGeneration[i + 1];

        // Create neighborhood pattern
        int pattern = (left << 2) | (center << 1) | right;

        // Check if pattern matches any defined rule
        nextGeneration[i] = 0;
        for (int j = 0; j < ruleCount; j++) {
            if (pattern == rules[j]) {
                nextGeneration[i] = 1;
                break;
            }
        }
    }
}

// Function to print cellular automata generations
void printGeneration(int *generation, int cells) {
    for (int i = 0; i < cells; i++) {
        printf("%c", generation[i] ? '#' : '.');
    }
    printf("\n");
}

// Main cellular automata simulation function
void simulateCellularAutomata() {
    int cells, generations, ruleCount;
    int *currentGeneration, *nextGeneration, *rules;
    char ruleInput[256];

    // Get user input for simulation parameters
    printf("Enter number of cells: ");
    scanf("%d", &cells);
    if (cells <= 0 || cells > MAX_CELLS) {
        printf("Invalid number of cells.\n");
        return;
    }

    printf("Enter number of generations: ");
    scanf("%d", &generations);
    if (generations <= 0 || generations > MAX_GENERATIONS) {
        printf("Invalid number of generations.\n");
        return;
    }

    // Allocate memory for generations and rules
    currentGeneration = malloc(cells * sizeof(int));
    nextGeneration = malloc(cells * sizeof(int));
    rules = malloc(cells * sizeof(int));

    // Initialize first generation (all zeros with a single cell in the middle)
    memset(currentGeneration, 0, cells * sizeof(int));
    currentGeneration[cells / 2] = 1;

    // Get user-defined rules
    printf("Enter cellular automata rules (space-separated binary patterns, e.g. 110 101):\n");
    getchar(); // Consume newline
    fgets(ruleInput, sizeof(ruleInput), stdin);

    // Parse rules
    ruleCount = 0;
    char *token = strtok(ruleInput, " \n");
    while (token != NULL && ruleCount < cells) {
        rules[ruleCount] = (int)strtol(token, NULL, 2);
        ruleCount++;
        token = strtok(NULL, " \n");
    }

    // Simulate cellular automata
    printf("Initial Generation:\n");
    printGeneration(currentGeneration, cells);

    for (int gen = 1; gen <= generations; gen++) {
        applyCellularAutomataRules(currentGeneration, nextGeneration, cells, rules, ruleCount);

        // Copy next generation to current generation
        memcpy(currentGeneration, nextGeneration, cells * sizeof(int));

        printf("Generation %d:\n", gen);
        printGeneration(currentGeneration, cells);
    }

    // Free allocated memory
    free(currentGeneration);
    free(nextGeneration);
    free(rules);
}

// Bonus function to visualize rule patterns
void visualizeRuleset() {
    int ruleNumber;
    printf("Enter Rule Number (0-255): ");
    scanf("%d", &ruleNumber);

    if (ruleNumber < 0 || ruleNumber > 255) {
        printf("Invalid rule number.\n");
        return;
    }

    char ruleBinary[9];
    decimalToBinary(ruleNumber, ruleBinary, 8);
    printf("Rule %d (Binary): %s\n", ruleNumber, ruleBinary);

    printf("Input Patterns | Output\n");
    printf("--------------|-------\n");
    for (int i = 0; i < 8; i++) {
        char pattern[4];
        decimalToBinary(i, pattern, 3);
        int output = (ruleNumber >> i) & 1;
        printf("   %s       |   %d\n", pattern, output);
    }
}

int main() {
    int choice;

    while (1) {
        printf("\nCellular Automata Simulator\n");
        printf("1. Simulate Cellular Automata\n");
        printf("2. Visualize Rule Patterns\n");
        printf("3. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                simulateCellularAutomata();
                break;
            case 2:
                visualizeRuleset();
                break;
            case 3:
                exit(0);
            default:
                printf("Invalid choice. Try again.\n");
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_WIDTH 1000
#define MAX_GENERATIONS 1000

void printGeneration(bool *cells, int width) {
    for (int i = 0; i < width; i++) {
        printf("%c", cells[i] ? '#' : ' ');
    }
    printf("\n");
}

bool getRule(bool left, bool center, bool right, int ruleNumber) {
    // Convert neighborhood to index (0-7)
    int index = (left ? 4 : 0) + (center ? 2 : 0) + (right ? 1 : 0);
    // Check if the bit at position 'index' is set in ruleNumber
    return (ruleNumber >> index) & 1;
}

void simulate(int width, int generations, int ruleNumber, bool initialCenter) {
    bool *current = malloc(width * sizeof(bool));
    bool *next = malloc(width * sizeof(bool));

    if (!current || !next) {
        printf("Memory allocation failed\n");
        free(current);
        free(next);
        return;
    }

    // Initialize with all false except center cell
    memset(current, false, width * sizeof(bool));
    if (initialCenter && width > 0) {
        current[width/2] = true;
    }

    printGeneration(current, width);

    for (int gen = 1; gen < generations; gen++) {
        for (int i = 0; i < width; i++) {
            bool left = (i == 0) ? false : current[i-1];
            bool center = current[i];
            bool right = (i == width-1) ? false : current[i+1];

            next[i] = getRule(left, center, right, ruleNumber);
        }

        printGeneration(next, width);

        // Swap current and next
        bool *temp = current;
        current = next;
        next = temp;
    }

    free(current);
    free(next);
}

int main() {
    int width, generations, ruleNumber;
    char initial;
    bool initialCenter;

    printf("Cellular Automata Simulator\n");
    printf("===========================\n");

    // Get user input
    printf("Enter grid width (max %d): ", MAX_WIDTH);
