}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h> // For usleep/sleep
#include <time.h>   // For srand

// Define cell states
#define DEAD 0
#define ALIVE 1

// Neighborhood types
#define MOORE 8
#define VON_NEUMANN 4

// Function prototypes
void initializeGrid(int **grid, int width, int height, int initial_type);
void printGrid(int **grid, int width, int height);
int countLiveNeighbors(int **grid, int x, int y, int width, int height, int neighborhood_type);
void applyRules(int **current_grid, int **next_grid, int width, int height,
                int *birth_rules, int num_birth_rules,
                int *survival_rules, int num_survival_rules,
                int neighborhood_type);
void copyGrid(int **dest, int **src, int width, int height);
int parseRules(char *rule_str, int *rules_array);
void clearScreen();

int main() {
    int width, height;
    char neighborhood_choice;
    int neighborhood_type;
    char birth_rule_str[32]; // Max 32 chars for birth rules
    char survival_rule_str[32]; // Max 32 chars for survival rules
    int birth_rules[9]; // Max 9 rules (0-8 neighbors)
    int survival_rules[9];
    int num_birth_rules = 0;
    int num_survival_rules = 0;
    int initial_type_choice;
    int generations;

    printf("--- Cellular Automata Simulator ---\n\n");

    // 1. Get Grid Size
    printf("Enter grid width (e.g., 80): ");
    scanf("%d", &width);
    printf("Enter grid height (e.g., 24): ");
    scanf("%d", &height);

    if (width <= 0 || height <= 0) {
        printf("Grid dimensions must be positive.\n");
        return 1;
    }

    // Allocate memory for grids
    int **current_grid = (int **)malloc(height * sizeof(int *));
    int **next_grid = (int **)malloc(height * sizeof(int *));
    for (int i = 0; i < height; i++) {
        current_grid[i] = (int *)malloc(width * sizeof(int));
        next_grid[i] = (int *)malloc(width * sizeof(int));
    }

    if (current_grid == NULL || next_grid == NULL) {
        perror("Failed to allocate memory for grids");
        return 1;
    }

    // 2. Choose Neighborhood Type
    printf("\nChoose neighborhood type:\n");
    printf("  'M' for Moore (8 neighbors)\n");
    printf("  'V' for Von Neumann (4 neighbors)\n");
    printf("Enter choice (M/V): ");
    scanf(" %c", &neighborhood_choice); // Space before %c to consume newline

    if (neighborhood_choice == 'M' || neighborhood_choice == 'm') {
        neighborhood_type = MOORE;
    } else if (neighborhood_choice == 'V' || neighborhood_choice == 'v') {
        neighborhood_type = VON_NEUMANN;
    } else {
        printf("Invalid neighborhood choice. Defaulting to Moore.\n");
        neighborhood_type = MOORE;
    }

    // 3. Define Rules
    printf("\nEnter BIRTH rules (e.g., \"3\" for B3, or \"135\" for B135): ");
    scanf("%s", birth_rule_str);
    num_birth_rules = parseRules(birth_rule_str, birth_rules);
    if (num_birth_rules == 0) {
        printf("No valid birth rules entered. Simulation might not run.\n");
    }

    printf("Enter SURVIVAL rules (e.g., \"23\" for S23, or \"456\" for S456): ");
    scanf("%s", survival_rule_str);
    num_survival_rules = parseRules(survival_rule_str, survival_rules);
    if (num_survival_rules == 0) {
        printf("No valid survival rules entered. Simulation might not run.\n");
    }

    // 4. Initial State
    printf("\nChoose initial state:\n");
    printf("  1. Random (sparse)\n");
    printf("  2. Random (dense)\n"); // More alive cells
    printf("  3. Glider (requires min 3x3 for Glider, 5x5 for Glider Gun)\n");
    printf("  4. Pulsar (requires min 17x17, but visually more complex)\n");
    printf("Enter choice (1-4): ");
    scanf("%d", &initial_type_choice);

    initializeGrid(current_grid, width, height, initial_type_choice);

    // 5. Simulation Steps
    printf("Enter number of generations to simulate: ");
    scanf("%d", &generations);

    // Simulation Loop
    for (int gen = 0; gen < generations; gen++) {
        clearScreen();
        printf("Generation: %d\n", gen);
        printGrid(current_grid, width, height);

        applyRules(current_grid, next_grid, width, height,
                   birth_rules, num_birth_rules,
                   survival_rules, num_survival_rules,
                   neighborhood_type);

        copyGrid(current_grid, next_grid, width, height);

        usleep(100000); // Sleep for 100 milliseconds
    }

    printf("\nSimulation Finished after %d generations.\n", generations);
    printGrid(current_grid, width, height); // Show final state


    // Free memory
    for (int i = 0; i < height; i++) {
        free(current_grid[i]);
        free(next_grid[i]);
    }
    free(current_grid);
    free(next_grid);

    return 0;
}

// Function Implementations

// Clears the console screen (platform-dependent)
void clearScreen() {
#ifdef _WIN32
    system("cls");
#else
    // Assume POSIX
    system("clear");
#endif
}

// Parses a string of digits into an integer array (e.g., "23" -> {2, 3})
// Returns the number of rules parsed.
int parseRules(char *rule_str, int *rules_array) {
    int count = 0;
    for (int i = 0; rule_str[i] != '\0'; i++) {
        if (rule_str[i] >= '0' && rule_str[i] <= '8') { // Neighbors 0-8
            rules_array[count++] = rule_str[i] - '0';
        }
    }
    return count;
}

// Initializes the grid based on user's choice
void initializeGrid(int **grid, int width, int height, int initial_type) {
    srand(time(NULL)); // Seed random number generator

    // Initialize all cells to DEAD
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            grid[i][j] = DEAD;
        }
    }

    switch (initial_type) {
        case 1: // Random (sparse)
            for (int i = 0; i < height; i++) {
                for (int j = 0; j < width; j++) {
                    if (rand() % 10 == 0) { // ~10% alive
                        grid[i][j] = ALIVE;
                    }
                }
            }
            break;
        case 2: // Random (dense)
            for (int i = 0; i < height; i++) {
                for (int j = 0; j < width; j++) {
                    if (rand() % 3 == 0) { // ~33% alive
                        grid[i][j] = ALIVE;
                    }
                }
            }
            break;
        case 3: // Glider (typical Conway's Game of Life pattern)
            // Glider pattern (requires at least 3x3)
            if (height >= 3 && width >= 3) {
                grid[0][1] = ALIVE;
                grid[1][2] = ALIVE;
                grid[2][0] = ALIVE;
                grid[2][1] = ALIVE;
                grid[2][2] = ALIVE;
            } else {
                printf("Grid too small for Glider. Using random (sparse) instead.\n");
                initializeGrid(grid, width, height, 1);
            }
            break;
        case 4: // Pulsar (periodic pattern)
            // Pulsar pattern (requires at least 17x17 for a full 3-period pulsar)
            if (height >= 17 && width >= 17) {
                int center_y = height / 2;
                int center_x = width / 2;

                // Relative coordinates for a 3-period pulsar centered at (0,0)
                // Offset these by center_y, center_x
                int pattern_coords[] = {
                    -6, -1,  -6,  0,  -6,  1,
                    -1, -6,  0, -6,   1, -6,

                    -1,  6,  0,  6,   1,  6,
                     6, -1,  6,  0,   6,  1,

                    -6, -3,  -6, -4,  -6, -5,
                    -3, -6,  -4, -6,  -5, -6,

                    -3,  6, -4,  6,  -5,  6,
                     6, -3,  6, -4,   6, -5,

                     3, -6,  4, -6,   5, -6,
                     6,  3,  6,  4,   6,  5,

                     3,  6,  4,  6,   5,  6,
                    -6,  3, -6,  4,  -6,  5
                };
                int num_points = sizeof(pattern_coords) / sizeof(int) / 2;

                for (int i = 0; i < num_points; ++i) {
                    int r = center_y + pattern_coords[i * 2];
                    int c = center_x + pattern_coords[i * 2 + 1];
                    // Ensure coordinates are within grid bounds
                    if (r >= 0 && r < height && c >= 0 && c < width) {
                        grid[r][c] = ALIVE;
                    }
                }
            } else {
                printf("Grid too small for Pulsar. Using random (sparse) instead.\n");
                initializeGrid(grid, width, height, 1);
            }
            break;
        default: // Default to random (sparse)
            printf("Invalid initial state choice. Using random (sparse) instead.\n");
            initializeGrid(grid, width, height, 1);
            break;
    }
}

// Prints the grid to the console
void printGrid(int **grid, int width, int height) {
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            printf("%c ", (grid[i][j] == ALIVE) ? '#' : '.');
        }
        printf("\n");
    }
}

// Counts live neighbors for a given cell (x, y)
int countLiveNeighbors(int **grid, int x, int y, int width, int height, int neighborhood_type) {
    int live_neighbors = 0;
    // Define relative coordinates for neighbors (dy, dx)
    int dy[] = {-1, -1, -1,  0,  0,  1,  1,  1}; // Rows
    int dx[] = {-1,  0,  1, -1,  1, -1,  0,  1}; // Cols

    int num_directions = (neighborhood_type == MOORE) ? 8 : 4;

    for (int i = 0; i < num_directions; i++) {
        // For Von Neumann, skip diagonal neighbors
        if (neighborhood_type == VON_NEUMANN && (dy[i] != 0 && dx[i] != 0)) {
            continue;
        }

        int neighbor_x = x + dx[i];
        int neighbor_y = y + dy[i];

        // Check boundary conditions (toroidal wrapping)
        if (neighbor_x < 0) neighbor_x += width;
        if (neighbor_x >= width) neighbor_x -= width;
        if (neighbor_y < 0) neighbor_y += height;
        if (neighbor_y >= height) neighbor_y -= height;

        // Old boundary check (non-toroidal)
        /*
        if (neighbor_x >= 0 && neighbor_x < width &&
            neighbor_y >= 0 && neighbor_y < height) {
            if (grid[neighbor_y][neighbor_x] == ALIVE) {
                live_neighbors++;
            }
        }
        */

        // New boundary check (toroidal, i.e., wrap around)
        if (grid[neighbor_y][neighbor_x] == ALIVE) {
             live_neighbors++;
        }
    }
    return live_neighbors;
}

// Applies the user-defined rules to evolve the grid
void applyRules(int **current_grid, int **next_grid, int width, int height,
                int *birth_rules, int num_birth_rules,
                int *survival_rules, int num_survival_rules,
                int neighborhood_type) {

    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int neighbors = countLiveNeighbors(current_grid, x, y, width, height, neighborhood_type);

            if (current_grid[y][x] == ALIVE) {
                // Check survival rules
                int survives = 0;
                for (int i = 0; i < num_survival_rules; i++) {
                    if (neighbors == survival_rules[i]) {
                        survives = 1;
                        break;
                    }
                }
                next_grid[y][x] = survives ? ALIVE : DEAD;
            } else { // Cell is DEAD
                // Check birth rules
                int born = 0;
                for (int i = 0; i < num_birth_rules; i++) {
                    if (neighbors == birth_rules[i]) {
                        born = 1;
                        break;
                    }
                }
                next_grid[y][x] = born ? ALIVE : DEAD;
            }
        }
    }
}

// Copies the contents of one grid to another
void copyGrid(int **dest, int **src, int width, int height) {
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            dest[i][j] = src[i][j];
        }
    }
}

