int getNextState(int left, int center, int right, int rule) {
    int index = (left << 2) | (center << 1) | right;  // Calculate the index
    return (rule >> index) & 1;  // Get the corresponding rule output
}

void simulate(int *cells, int size, int rule, int generations) {
    int *newCells = (int *)malloc(size * sizeof(int));
    for (int gen = 0; gen < generations; gen++) {
        printGeneration(cells, size);  // Print current generation
        // Calculate new state
        for (int i = 0; i < size; i++) {
            int left = (i == 0) ? 0 : cells[i - 1];  // Left neighbor
            int center = cells[i];                   // Current cell
            int right = (i == size - 1) ? 0 : cells[i + 1];  // Right neighbor
            newCells[i] = getNextState(left, center, right, rule);
        }
        // Swap cells
        int *temp = cells;
        cells = newCells;
        newCells = temp;
    }
    free(newCells);
}

