    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define RULE_SIZE 8
#define GRID_SIZE 100
#define GENERATIONS 100

// Function to convert a binary number to decimal
int binary_to_decimal(char *binary) {
    int decimal = 0;
    for (int i = 0; i < RULE_SIZE; i++) {
        decimal += (binary[i] - '0') * (1 << (RULE_SIZE - 1 - i));
    }
    return decimal;
}

// Function to generate the next generation of the automaton
void generate_next_generation(int *grid, int *next_grid, int rule) {
    for (int i = 0; i < GRID_SIZE; i++) {
        int left = (i - 1 + GRID_SIZE) % GRID_SIZE;
        int right = (i + 1) % GRID_SIZE;
        int neighborhood = (grid[left] << 2) | (grid[i] << 1) | grid[right];
        next_grid[i] = (rule >> (7 - neighborhood)) & 1;
    }
}

// Function to print the current generation of the automaton
void print_generation(int *grid) {
    for (int i = 0; i < GRID_SIZE; i++) {
        printf("%d ", grid[i]);
    }
    printf("\n");
}

int main() {
    // Get the user-defined rule
    char rule_binary[RULE_SIZE + 1];
    printf("Enter the binary rule (8 bits): ");
    scanf("%s", rule_binary);
    int rule = binary_to_decimal(rule_binary);

    // Initialize the grid with random values
    int grid[GRID_SIZE];
    int next_grid[GRID_SIZE];
    srand(time(NULL));
    for (int i = 0; i < GRID_SIZE; i++) {
        grid[i] = rand() % 2;
    }

    // Run the simulation for the specified number of generations
    for (int generation = 0; generation < GENERATIONS; generation++) {
        printf("Generation %d:\n", generation);
        print_generation(grid);

        // Generate the next generation
        generate_next_generation(grid, next_grid, rule);

        // Swap the grids for the next iteration
        for (int i = 0; i < GRID_SIZE; i++) {
            grid[i] = next_grid[i];
        }
    }

    return 0;
}

#include <stdio.h>
