#include <string.h>

#define MAX_RULES 256
#define MAX_GEN 1000
#define GRID_SIZE 100

// Function to apply the user-defined rules to the current generation
void apply_rules(int *grid, int *new_grid, int *rules, int size) {
    for (int i = 0; i < size; i++) {
        int left = (i == 0) ? grid[size - 1] : grid[i - 1];
        int center = grid[i];
        int right = (i == size - 1) ? grid[0] : grid[i + 1];

        // Compute the index for the rule based on the neighborhood pattern
        int pattern = (left << 2) | (center << 1) | right;
        new_grid[i] = rules[pattern];
    }
}

// Function to print the current generation of the grid
void print_grid(int *grid, int size) {
    for (int i = 0; i < size; i++) {
        printf("%c", grid[i] ? '*' : ' ');
    }
    printf("\n");
}

// Function to initialize the grid with a single cell in the center
void initialize_grid(int *grid, int size) {
    for (int i = 0; i < size; i++) {
        grid[i] = 0;
    }
    grid[size / 2] = 1; // Start with a single cell in the center
}

int main() {
    int grid[GRID_SIZE];
    int new_grid[GRID_SIZE];
    int rules[MAX_RULES];
    int num_generations;

    // Read the rule set from the user
    printf("Enter the rule set (256 binary values, 0 or 1, separated by spaces):\n");
    for (int i = 0; i < 256; i++) {
