            fprintf(stderr, "Invalid input. Please enter 0 or 1.\n");
            return 1;
        }
    }

    // Read the number of generations to simulate
    printf("Enter the number of generations to simulate (max %d): ", MAX_GEN);
    if (scanf("%d", &num_generations) != 1 || num_generations <= 0 || num_generations > MAX_GEN) {
        fprintf(stderr, "Invalid input. Please enter a positive integer less than or equal to %d.\n", MAX_GEN);
        return 1;
    }

    // Initialize the grid
    initialize_grid(grid, GRID_SIZE);

    // Simulate the cellular automaton
    for (int gen = 0; gen < num_generations; gen++) {
        print_grid(grid, GRID_SIZE);
        apply_rules(grid, new_grid, rules, GRID_SIZE);
        memcpy(grid, new_grid, sizeof(int) * GRID_SIZE);
    }

    return 0;
}

