// Request elevator
void requestElevator(Elevator *elevator, int currentFloor, int destinationFloor, int priority) {
    // Check if elevator can accommodate passenger
    if (canAddPassenger(elevator)) {
        // Add passenger to elevator
        Passenger newPassenger = {
            .currentFloor = currentFloor,
            .destinationFloor = destinationFloor,
            .priority = priority,
            .isInElevator = true
        };

        elevator->passengers[elevator->passengerCount++] = newPassenger;
        printf("Passenger added: Floor %d to Floor %d (Priority: %d)\n", 
               currentFloor, destinationFloor, priority);
    } else {
        printf("Elevator is full. Cannot add passenger.\n");
    }
}

// Move elevator
void moveElevator(Elevator *elevator) {
    int nextFloor = selectNextFloor(elevator);

    if (nextFloor == elevator->currentFloor) {
        elevator->state = IDLE;
        return;
    }

    // Determine elevator direction
    if (nextFloor > elevator->currentFloor) {
        elevator->state = MOVING_UP;
        elevator->currentFloor++;
    } else {
        elevator->state = MOVING_DOWN;
        elevator->currentFloor--;
    }

    // Check if any passengers need to exit
    for (int i = 0; i < elevator->passengerCount; i++) {
        if (elevator->passengers[i].destinationFloor == elevator->currentFloor) {
            printf("Passenger reached destination at Floor %d\n", elevator->currentFloor);
            // Remove passenger
            for (int j = i; j < elevator->passengerCount - 1; j++) {
                elevator->passengers[j] = elevator->passengers[j + 1];
            }
            elevator->passengerCount--;
            i--;
        }
    }
}

// Select next floor based on priority
int selectNextFloor(Elevator *elevator) {
    if (elevator->passengerCount == 0) {
        return elevator->currentFloor;
    }

    // Find highest priority passenger's destination
    int highestPriority = 3;
    int nextFloor = elevator->currentFloor;

    for (int i = 0; i < elevator->passengerCount; i++) {
        if (elevator->passengers[i].priority < highestPriority) {
            highestPriority = elevator->passengers[i].priority;
            nextFloor = elevator->passengers[i].destinationFloor;
        }
    }

    return nextFloor;
}

// Check if elevator can add passenger
bool canAddPassenger(Elevator *elevator) {
    return elevator->passengerCount < MAX_PASSENGERS;
}

// Display elevator status
void displayElevatorStatus(Elevator *elevator) {
    printf("\nElevator Status:\n");
    printf("Current Floor: %d\n", elevator->currentFloor);

    switch (elevator->state) {
        case IDLE:
            printf("State: IDLE\n");
            break;
        case MOVING_UP:
            printf("State: MOVING UP\n");
            break;
        case MOVING_DOWN:
            printf("State: MOVING DOWN\n");
            break;
    }

    printf("Passengers: %d\n", elevator->passengerCount);
}

int main() {
    Elevator elevator;
    initializeElevator(&elevator);

    // Simulate elevator requests
    requestElevator(&elevator, 1, 5, 2);  // Medium priority
    displayElevatorStatus(&elevator);

    moveElevator(&elevator);
    displayElevatorStatus(&elevator);

    moveElevator(&elevator);
    displayElevatorStatus(&elevator);

    return 0;
}

