void request_floor(int floor) {
    if (floor < 0 || floor >= MAX_FLOORS) {
        printf("Invalid floor request. Please choose a floor between 0 and %d.\n", MAX_FLOORS - 1);
        return;
    }
    requested_floor = floor;
    printf("Floor %d requested.\n", floor);
}

void move_elevator() {
    if (requested_floor == -1) {
        printf("No floor requested. Elevator remains at floor %d.\n", current_floor);
        return;
    }

    if (requested_floor > current_floor) {
        printf("Elevator moving up...\n");
        while (current_floor < requested_floor) {
            current_floor++;
            printf("Now at floor %d\n", current_floor);
        }
    } else if (requested_floor < current_floor) {
        printf("Elevator moving down...\n");
        while (current_floor > requested_floor) {
            current_floor--;
            printf("Now at floor %d\n", current_floor);
        }
    } else {
        printf("Elevator is already at the requested floor %d.\n", current_floor);
    }

    requested_floor = -1; // Reset the request after reaching the floor
}

