#include <stdio.h>
#include <stdlib.h>
#include <unistd.h> // For sleep()

#define MAX_FLOORS 10
#define GROUND_FLOOR 1
#define SIMULATION_SPEED_SECONDS 1 // How long each "tick" takes

// Enumerations for clarity
typedef enum {
    IDLE,
    MOVING_UP,
    MOVING_DOWN
} ElevatorState;

typedef enum {
    REQUEST_DOWN,
    REQUEST_UP,
    NO_REQUEST
} RequestDirection;

// Struct to represent an elevator request (from outside or inside)
typedef struct {
    int floor;
    RequestDirection direction; // For external calls (button pressed)
    int isValid;               // 1 if request is active, 0 otherwise
} ElevatorRequest;

// Struct to represent the elevator's current state
typedef struct {
    int currentFloor;
    ElevatorState state;
    int destinationFloor;     // Where the person inside wants to go, or next pickup
    ElevatorRequest requests[MAX_FLOORS + 1][2]; // [floor][0 for UP, 1 for DOWN] (simulates buttons)
    // For simplicity, let's just have one internal destination request for the person
    int internalDestination;
    int hasInternalDestination; // 1 if person is inside and has set a destination
} Elevator;

// Global Elevator instance
Elevator elevator;

// --- Function Prototypes ---
void initializeElevator();
void simulatePersonRequest(int currentFloor, int destinationFloor);
void processElevatorLogic();
void handleStops();
void moveElevator();
void findNextDestination();
void printElevatorStatus();
int hasPendingRequests();

// --- Functions ---

void initializeElevator() {
    elevator.currentFloor = GROUND_FLOOR;
    elevator.state = IDLE;
    elevator.destinationFloor = GROUND_FLOOR;
    elevator.internalDestination = -1;
    elevator.hasInternalDestination = 0;

    // Initialize all requests as invalid
    for (int i = GROUND_FLOOR; i <= MAX_FLOORS; i++) {
        elevator.requests[i][0].isValid = 0; // UP button
        elevator.requests[i][1].isValid = 0; // DOWN button
    }
    printf("Elevator initialized at Floor %d, State: IDLE\n", GROUND_FLOOR);
}

// Simulates a person making a request
void simulatePersonRequest(int currentFloor, int destinationFloor) {
    if (currentFloor < GROUND_FLOOR || currentFloor > MAX_FLOORS ||
        destinationFloor < GROUND_FLOOR || destinationFloor > MAX_FLOORS ||
        currentFloor == destinationFloor) {
        printf("Invalid request: From Floor %d to Floor %d.\n", currentFloor, destinationFloor);
        return;
    }

    printf("\nPerson arrives at Floor %d and wants to go to Floor %d.\n", currentFloor, destinationFloor);

    // Simulate external button press
    if (destinationFloor > currentFloor) {
        printf("Person presses UP button at Floor %d.\n", currentFloor);
        elevator.requests[currentFloor][0].isValid = 1;
        elevator.requests[currentFloor][0].floor = currentFloor;
        elevator.requests[currentFloor][0].direction = REQUEST_UP;
    } else {
        printf("Person presses DOWN button at Floor %d.\n", currentFloor);
        elevator.requests[currentFloor][1].isValid = 1;
        elevator.requests[currentFloor][1].floor = currentFloor;
        elevator.requests[currentFloor][1].direction = REQUEST_DOWN;
    }

    // Store their ultimate destination for later
    elevator.internalDestination = destinationFloor;
    elevator.hasInternalDestination = 0; // Not inside yet
}

// Main logic for elevator control
void processElevatorLogic() {
    printElevatorStatus();
    handleStops(); // Check if we need to stop at the current floor
    moveElevator(); // Move if not stopped or if we need to find a new destination
    findNextDestination(); // Determine where to go next
}

// Checks if the elevator needs to stop at the current floor
void handleStops() {
    int stop_made = 0;

    // Priority 1: Person inside needs to get off
    if (elevator.hasInternalDestination && elevator.currentFloor == elevator.internalDestination) {
        printf("Elevator stopped at Floor %d. Person exited.\n", elevator.currentFloor);
        elevator.internalDestination = -1;
        elevator.hasInternalDestination = 0;
        elevator.state = IDLE; // Back to IDLE after dropping off
        stop_made = 1;
    }

    // Priority 2: Pick up a person if they pressed a button for the current direction
    if (!elevator.hasInternalDestination) { // Only pick up if nobody is inside yet
        if (elevator.state == MOVING_UP && elevator.requests[elevator.currentFloor][0].isValid) {
            printf("Elevator stopped at Floor %d. Picking up person (UP request).\n", elevator.currentFloor);
            elevator.requests[elevator.currentFloor][0].isValid = 0; // Clear the request
            elevator.hasInternalDestination = 1; // Person is now inside
            stop_made = 1;
            // The ultimate destination is already stored in elevator.internalDestination
        } else if (elevator.state == MOVING_DOWN && elevator.requests[elevator.currentFloor][1].isValid) {
            printf("Elevator stopped at Floor %d. Picking up person (DOWN request).\n", elevator.currentFloor);
            elevator.requests[elevator.currentFloor][1].isValid = 0; // Clear the request
            elevator.hasInternalDestination = 1; // Person is now inside
            stop_made = 1;
            // The ultimate destination is already stored in elevator.internalDestination
        } else if (elevator.state == IDLE && (elevator.requests[elevator.currentFloor][0].isValid || elevator.requests[elevator.currentFloor][1].isValid)) {
            // If IDLE, and there's any request on this floor, pick them up
            printf("Elevator stopped at Floor %d. Picking up person (IDLE request).\n", elevator.currentFloor);
            if(elevator.requests[elevator.currentFloor][0].isValid) elevator.requests[elevator.currentFloor][0].isValid = 0;
            if(elevator.requests[elevator.currentFloor][1].isValid) elevator.requests[elevator.currentFloor][1].isValid = 0;
            elevator.hasInternalDestination = 1; // Person is now inside
            stop_made = 1;
        }
    }

    if (stop_made) {
        elevator.state = IDLE; // Briefly go idle for stopping/picking up
        sleep(SIMULATION_SPEED_SECONDS * 2); // Simulate door open/close time
    }
}

// Moves the elevator one floor in its current direction
void moveElevator() {
    if (elevator.state == MOVING_UP) {
        if (elevator.currentFloor < MAX_FLOORS) {
            elevator.currentFloor++;
            printf("Elevator moving UP... Now at Floor %d\n", elevator.currentFloor);
        } else {
            elevator.state = MOVING_DOWN; // Reached top, must go down eventually
            printf("Elevator reached top floor. Changing direction.\n");
        }
    } else if (elevator.state == MOVING_DOWN) {
        if (elevator.currentFloor > GROUND_FLOOR) {
            elevator.currentFloor--;
            printf("Elevator moving DOWN... Now at Floor %d\n", elevator.currentFloor);
        } else {
            elevator.state = MOVING_UP; // Reached bottom, must go up eventually
            printf("Elevator reached ground floor. Changing direction.\n");
        }
    }
    // If IDLE, it won't move until a new destination is found
}

// Determines the next floor the elevator should go to based on priorities
void findNextDestination() {
    if (elevator.state == IDLE) {
        // Priority 1: If person is inside, go to their destination
        if (elevator.hasInternalDestination && elevator.internalDestination != -1) {
            if (elevator.currentFloor < elevator.internalDestination) {
                elevator.state = MOVING_UP;
                printf("Elevator now MOVING_UP to internal destination Floor %d.\n", elevator.internalDestination);
            } else if (elevator.currentFloor > elevator.internalDestination) {
                elevator.state = MOVING_DOWN;
                printf("Elevator now MOVING_DOWN to internal destination Floor %d.\n", elevator.internalDestination);
            }
            return; // Destination set, exit
        }

        // Priority 2: Look for any pending requests
        // First, check for requests in the current direction (or up if IDLE)
        for (int i = elevator.currentFloor; i <= MAX_FLOORS; i++) {
            if (elevator.requests[i][0].isValid) { // UP request
                elevator.state = MOVING_UP;
                printf("Elevator now MOVING_UP for external request at Floor %d.\n", elevator.requests[i][0].floor);
                return;
            }
        }
        // Then, check for requests downwards
        for (int i = elevator.currentFloor; i >= GROUND_FLOOR; i--) {
            if (elevator.requests[i][1].isValid) { // DOWN request
                elevator.state = MOVING_DOWN;
                printf("Elevator now MOVING_DOWN for external request at Floor %d.\n", elevator.requests[i][1].floor);
                return;
            }
        }
        // If still no requests, and it was IDLE, maybe it needs to clear other requests
        // A more advanced system would track actual next logical stops.
        printf("Elevator is IDLE and no new immediate requests found.\n");
    } else {
        // If moving, continue in that direction, stopping for internal destinations
        // or external requests in the same direction.
        // This logic is mostly handled by handleStops()
    }
}

int hasPendingRequests() {
    if (elevator.hasInternalDestination) return 1;

    for (int i = GROUND_FLOOR; i <= MAX_FLOORS; i++) {
        if (elevator.requests[i][0].isValid || elevator.requests[i][1].isValid) {
            return 1;
        }
    }
    return 0;
}

void printElevatorStatus() {
    printf("--- Floor %d -- State: ", elevator.currentFloor);
    switch (elevator.state) {
        case IDLE:
            printf("IDLE");
            break;
        case MOVING_UP:
            printf("MOVING UP");
            break;
        case MOVING_DOWN:
            printf("MOVING DOWN");
            break;
    }
    if (elevator.hasInternalDestination) {
        printf(" (Person wants to go to: %d)", elevator.internalDestination);
    }
    printf(" ---\n");

    printf("Pending External Requests:\n");
    int found_request = 0;
    for (int i = GROUND_FLOOR; i <= MAX_FLOORS; i++) {
        if (elevator.requests[i][0].isValid) {
            printf("  [Floor %d] UP\n", i);
            found_request = 1;
        }
        if (elevator.requests[i][1].isValid) {
            printf("  [Floor %d] DOWN\n", i);
            found_request = 1;
        }
    }
    if (!found_request) {
        printf("  None.\n");
    }
}

// --- Main Program ---
int main() {
    initializeElevator();

    // --- Test Scenario 1: Person at 3 wants to go to 8 ---
    simulatePersonRequest(3, 8);

    int simulation_ticks = 0;
    // Elevator will continue running as long as there are pending requests or a person is inside
    while (elevator.hasInternalDestination || hasPendingRequests() || elevator.state != IDLE || simulation_ticks < 50) {
        printf("\n--- Simulation Tick %d ---\n", ++simulation_ticks);
        processElevatorLogic();
        sleep(SIMULATION_SPEED_SECONDS);

        // Add more requests dynamically for longer simulation or specific tests
        if (simulation_ticks == 10 && !elevator.hasInternalDestination && !hasPendingRequests()) {
             printf("\n--- Adding new request: Person at 7 wants to go to 2 ---\n");
             simulatePersonRequest(7, 2);
        }
    }

    printf("\nSimulation finished. Elevator is IDLE and no pending requests.\n");

    return 0;
}

