void simulate_movement(int from, int to, int priority) {
    int step = (to > from) ? 1 : -1;
    int delay = (priority == 1) ? 1 : 2; // High priority is faster

    for(int f = from; f != to; f += step) {
        display_status(f);
        sleep(delay);
    }
    display_status(to);
}

