#include <stdio.h>

// Structure to represent a person
typedef struct {
    int id;
    int priority;
    int destination_floor;
} Person;

// Structure to represent the elevator
typedef struct {
    int current_floor;
    int max_capacity;
    Person people[10]; // assuming max 10 people can be in the elevator
    int people_count;
} Elevator;

// Function to add a person to the elevator
void add_person(Elevator* elevator, Person person) {
    if (elevator->people_count < elevator->max_capacity) {
        elevator->people[elevator->people_count] = person;
        elevator->people_count++;
        printf("Person %d added to the elevator with priority %d and destination floor %d\n", person.id, person.priority, person.destination_floor);
    } else {
        printf("Elevator is full. Cannot add person %d\n", person.id);
    }
}

// Function to control the elevator
void control_elevator(Elevator* elevator) {
    // Sort the people in the elevator based on priority
    for (int i = 0; i < elevator->people_count; i++) {
        for (int j = i + 1; j < elevator->people_count; j++) {
            if (elevator->people[i].priority < elevator->people[j].priority) {
                Person temp = elevator->people[i];
                elevator->people[i] = elevator->people[j];
                elevator->people[j] = temp;
            }
        }
    }

    // Move the elevator to the destination floor of the person with highest priority
    for (int i = 0; i < elevator->people_count; i++) {
        printf("Moving elevator to floor %d for person %d with priority %d\n", elevator->people[i].destination_floor, elevator->people[i].id, elevator->people[i].priority);
        elevator->current_floor = elevator->people[i].destination_floor;
        printf("Elevator reached floor %d. Person %d is getting off\n", elevator->current_floor, elevator->people[i].id);
    }
}

