}

#include <stdio.h>

#define GROUND_FLOOR 0
#define TOTAL_FLOORS 10

int currentFloor = GROUND_FLOOR;
int targetFloor = GROUND_FLOOR;
int priorityFloor = -1; // -1 indicates no priority request

void moveElevator(int destination) {
    if (destination < 0 || destination >= TOTAL_FLOORS) {
        printf("Invalid floor request. Please enter a floor between 0 and %d.\n", TOTAL_FLOORS - 1);
        return;
    }

    if (currentFloor == destination) {
        printf("You are already on floor %d.\n", currentFloor);
        return;
    }

    printf("Elevator moving from floor %d to floor %d.\n", currentFloor, destination);

    if (currentFloor < destination) {
        for (int i = currentFloor + 1; i <= destination; i++) {
            currentFloor = i;
            printf("Elevator is now on floor %d.\n", currentFloor);
        }
    } else {
        for (int i = currentFloor - 1; i >= destination; i--) {
            currentFloor = i;
            printf("Elevator is now on floor %d.\n", currentFloor);
        }
    }
}

void handlePriorityRequest(int priority) {
    if (priority < 0 || priority >= TOTAL_FLOORS) {
        printf("Invalid priority floor request. Please enter a floor between 0 and %d.\n", TOTAL_FLOORS - 1);
        return;
    }

    if (priorityFloor == -1) {
        priorityFloor = priority;
        printf("Priority request received for floor %d. Elevator will move there immediately.\n", priorityFloor);
        moveElevator(priorityFloor);
        priorityFloor = -1; // Reset priority after handling
    } else {
        printf("Another priority request is already being handled. Please wait.\n");
    }
}

void handleNormalRequest(int normal) {
    if (priorityFloor != -1) {
        printf("A priority request is active. Normal request for floor %d is queued.\n", normal);
        return;
    }

    printf("Normal request received for floor %d.\n", normal);
    moveElevator(normal);
}

int main() {
    int requestType, floor;

    printf("Welcome to the Elevator Control System!\n");
    printf("Total floors: 0 to %d\n", TOTAL_FLOORS - 1);

    while (1) {
        printf("\nCurrent floor: %d\n", currentFloor);
        printf("Enter 1 for priority request, 2 for normal request, or 0 to exit: ");
        scanf("%d", &requestType);

        if (requestType == 0) {
            printf("Exiting the Elevator Control System.\n");
            break;
        } else if (requestType == 1 || requestType == 2) {
            printf("Enter the floor number (0 to %d): ", TOTAL_FLOORS - 1);
            scanf("%d", &floor);

            if (requestType == 1) {
                handlePriorityRequest(floor);
            } else if (requestType == 2) {
                handleNormalRequest(floor);
            }
        } else {
            printf("Invalid request type. Please enter 1 for priority, 2 for normal, or 0 to exit.\n");
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_FLOORS 10
#define NUM_PASSENGERS 3

// Structure to represent a passenger
typedef struct {
    int id;
    int current_floor;
    int destination_floor;
    int priority;  // 0 (low) to 10 (high)
    bool in_elevator;
} Passenger;

// Elevator structure
typedef struct {
    int current_floor;
    bool is_moving;
    int direction;  // 1 for up, -1 for down, 0 for idle
    Passenger passengers[NUM_PASSENGERS];
} Elevator;

// Function prototypes
void initialize_elevator(Elevator *elevator);
void display_elevator_status(Elevator *elevator);
bool add_passenger(Elevator *elevator, Passenger *passenger);
bool remove_passenger(Elevator *elevator, int id);
void move_elevator(Elevator *elevator);
int select_next_floor(Elevator *elevator);
void simulate_elevator();

// Initialize elevator
void initialize_elevator(Elevator *elevator) {
    elevator->current_floor = 1;
    elevator->is_moving = false;
    elevator->direction = 0;

    for (int i = 0; i < NUM_PASSENGERS; i++) {
        elevator->passengers[i].id = -1;
        elevator->passengers[i].in_elevator = false;
    }
}

// Display current elevator status
void display_elevator_status(Elevator *elevator) {
    printf("\nElevator Status:\n");
    printf("Current Floor: %d\n", elevator->current_floor);
    printf("Direction: %s\n", 
           elevator->direction == 1 ? "UP" : 
           (elevator->direction == -1 ? "DOWN" : "IDLE"));

    printf("Passengers in Elevator:\n");
    for (int i = 0; i < NUM_PASSENGERS; i++) {
        if (elevator->passengers[i].in_elevator) {
            printf("ID: %d, Destination: %d, Priority: %d\n", 
                   elevator->passengers[i].id,
                   elevator->passengers[i].destination_floor,
                   elevator->passengers[i].priority);
        }
    }
}

// Add passenger to elevator
bool add_passenger(Elevator *elevator, Passenger *passenger) {
    for (int i = 0; i < NUM_PASSENGERS; i++) {
        if (!elevator->passengers[i].in_elevator) {
            elevator->passengers[i] = *passenger;
            elevator->passengers[i].in_elevator = true;
            return true;
        }
    }
    return false;  // Elevator is full
}

// Remove passenger from elevator
bool remove_passenger(Elevator *elevator, int id) {
    for (int i = 0; i < NUM_PASSENGERS; i++) {
        if (elevator->passengers[i].id == id && 
            elevator->passengers[i].in_elevator) {
            elevator->passengers[i].in_elevator = false;
            return true;
        }
    }
    return false;
}

// Determine next floor based on passenger priorities
int select_next_floor(Elevator *elevator) {
    int next_floor = elevator->current_floor;
    int max_priority = -1;

    // Check passenger destinations
    for (int i = 0; i < NUM_PASSENGERS; i++) {
        if (elevator->passengers[i].in_elevator && 
            elevator->passengers[i].priority > max_priority) {
            next_floor = elevator->passengers[i].destination_floor;
            max_priority = elevator->passengers[i].priority;
        }
    }

    return next_floor;
}

// Move elevator
void move_elevator(Elevator *elevator) {
    int next_floor = select_next_floor(elevator);

    if (next_floor > elevator->current_floor) {
        elevator->direction = 1;
        elevator->current_floor++;
    } else if (next_floor < elevator->current_floor) {
        elevator->direction = -1;
        elevator->current_floor--;
    } else {
        elevator->direction = 0;
    }

    // Remove passengers at destination floor
    for (int i = 0; i < NUM_PASSENGERS; i++) {
        if (elevator->passengers[i].in_elevator && 
            elevator->passengers[i].destination_floor == elevator->current_floor) {
            remove_passenger(elevator, elevator->passengers[i].id);
        }
    }
}

// Simulation
void simulate_elevator() {
    Elevator elevator;
    initialize_elevator(&elevator);

    // Sample passengers
    Passenger passengers[] = {
        {1, 3, 7, 8, false},   // High priority
        {2, 5, 2, 3, false},   // Low priority
        {3, 1, 9, 6, false}    // Medium priority
    };

    // Add passengers to elevator
    for (int i = 0; i < NUM_PASSENGERS; i++) {
        add_passenger(&elevator, &passengers[i]);
    }

    // Simulate elevator movement
    while (1) {
        display_elevator_status(&elevator);
        move_elevator(&elevator);

        // Exit condition: No passengers left
        bool passengers_remaining = false;
        for (int i = 0; i < NUM_PASSENGERS; i++) {
            if (elevator.passengers[i].in_elevator) {
                passengers_remaining = true;
                break;
            }
        }

        if (!passengers_remaining) break;
    }
}

int main() {
    simulate_elevator();
    return 0;
}

