#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h> // For sleep()

// --- Configuration ---
#define NUM_FLOORS 10
#define NUM_PEOPLE 3
#define SIMULATION_TICKS 50 // How many simulation steps
#define SIMULATION_DELAY_MS 500 // Delay between steps in milliseconds

// --- Enums ---
typedef enum {
    IDLE,
    MOVING_UP,
    MOVING_DOWN
} ElevatorState;

typedef enum {
    LOW_PRIORITY = 0,
    MEDIUM_PRIORITY = 1,
    HIGH_PRIORITY = 2
} Priority;

typedef enum {
    WAITING_FOR_PICKUP,
    IN_ELEVATOR,
    ARRIVED_AT_DESTINATION
} PersonState;

// --- Structs ---
typedef struct {
    int id;
    int current_floor;
    int destination_floor;
    Priority priority;
    PersonState state;
    bool needs_pickup; // True if waiting to be picked up
    bool needs_dropoff; // True if in elevator and needs to be dropped off
} Person;

typedef struct {
    int current_floor;
    ElevatorState state;
    bool doors_open;
    int onboard_people_count;
    // In a real system, you'd have a list of onboard people
} Elevator;

// --- Global Variables ---
Elevator g_elevator;
Person g_people[NUM_PEOPLE];
bool g_floor_requests[NUM_FLOORS + 1]; // To mark floors with pending requests

// --- Function Prototypes ---
void initialize_elevator();
void initialize_people();
void print_status();
int get_next_stop();
void simulate_step();
bool all_people_arrived();
void ms_sleep(int ms);

// --- Main Function ---
int main() {
    srand(time(NULL)); // Seed random number generator

    initialize_elevator();
    initialize_people();

    printf("--- Elevator Simulation Start ---\n");
    print_status();

    for (int tick = 1; tick <= SIMULATION_TICKS; ++tick) {
        printf("\n--- Simulation Tick %d ---\n", tick);
        simulate_step();
        print_status();

        if (all_people_arrived()) {
            printf("\n--- All people have reached their destinations! ---\n");
            break;
        }
        ms_sleep(SIMULATION_DELAY_MS);
    }

    printf("\n--- Elevator Simulation End ---\n");
    return 0;
}

// --- Function Implementations ---

void initialize_elevator() {
    g_elevator.current_floor = 1; // Start at floor 1
    g_elevator.state = IDLE;
    g_elevator.doors_open = false;
    g_elevator.onboard_people_count = 0;
    for (int i = 0; i <= NUM_FLOORS; ++i) {
        g_floor_requests[i] = false;
    }
}

void initialize_people() {
    // Manually assign priorities and random initial/destination floors
    // You can make these random too.
    g_people[0].id = 1;
    g_people[0].priority = HIGH_PRIORITY; // High priority
    g_people[0].current_floor = rand() % NUM_FLOORS + 1;
    do { // Ensure destination is different from current
        g_people[0].destination_floor = rand() % NUM_FLOORS + 1;
    } while (g_people[0].destination_floor == g_people[0].current_floor);
    g_people[0].state = WAITING_FOR_PICKUP;
    g_people[0].needs_pickup = true;
    g_people[0].needs_dropoff = false;
    g_floor_requests[g_people[0].current_floor] = true;

    g_people[1].id = 2;
    g_people[1].priority = MEDIUM_PRIORITY; // Medium priority
    g_people[1].current_floor = rand() % NUM_FLOORS + 1;
    do {
        g_people[1].destination_floor = rand() % NUM_FLOORS + 1;
    } while (g_people[1].destination_floor == g_people[1].current_floor);
    g_people[1].state = WAITING_FOR_PICKUP;
    g_people[1].needs_pickup = true;
    g_people[1].needs_dropoff = false;
    g_floor_requests[g_people[1].current_floor] = true;

    g_people[2].id = 3;
    g_people[2].priority = LOW_PRIORITY; // Low priority
    g_people[2].current_floor = rand() % NUM_FLOORS + 1;
    do {
        g_people[2].destination_floor = rand() % NUM_FLOORS + 1;
    } while (g_people[2].destination_floor == g_people[2].current_floor);
    g_people[2].state = WAITING_FOR_PICKUP;
    g_people[2].needs_pickup = true;
    g_people[2].needs_dropoff = false;
    g_floor_requests[g_people[2].current_floor] = true;
}

void print_status() {
    printf("Elevator [Floor: %2d, State: %s, Doors: %s]\n",
           g_elevator.current_floor,
           g_elevator.state == IDLE ? "IDLE" : (g_elevator.state == MOVING_UP ? "UP  " : "DOWN"),
           g_elevator.doors_open ? "OPEN" : "CLOSED");

    for (int i = 0; i < NUM_PEOPLE; ++i) {
        const char *p_state;
        switch (g_people[i].state) {
            case WAITING_FOR_PICKUP: p_state = "WAITING"; break;
            case IN_ELEVATOR: p_state = "IN_ELEV"; break;
            case ARRIVED_AT_DESTINATION: p_state = "ARRIVED"; break;
            default: p_state = "UNKNOWN"; break;
        }

        const char *p_priority;
        switch (g_people[i].priority) {
            case HIGH_PRIORITY: p_priority = "HIGH"; break;
            case MEDIUM_PRIORITY: p_priority = "MED "; break;
            case LOW_PRIORITY: p_priority = "LOW "; break;
            default: p_priority = "UNKNOWN"; break;
        }

        printf("  Person %d [Prio: %s, Curr: %2d, Dest: %2d, State: %s]\n",
               g_people[i].id, p_priority, g_people[i].current_floor,
               g_people[i].destination_floor, p_state);
    }
}

// Determines the next floor the elevator should go to, considering priorities and direction.
// Returns 0 if no pending requests.
int get_next_stop() {
    int best_next_floor = 0;
    Priority highest_priority_found = (Priority)-1; // Will be LOW_PRIORITY (0) initially

    // 1. Prioritize people currently in the elevator (drop-offs)
    for (int i = 0; i < NUM_PEOPLE; ++i) {
        if (g_people[i].state == IN_ELEVATOR && g_people[i].needs_dropoff) {
            if (g_elevator.state == MOVING_UP && g_people[i].destination_floor >= g_elevator.current_floor) {
                if (best_next_floor == 0 || g_people[i].destination_floor < best_next_floor) {
                    best_next_floor = g_people[i].destination_floor;
                }
            } else if (g_elevator.state == MOVING_DOWN && g_people[i].destination_floor <= g_elevator.current_floor) {
                if (best_next_floor == 0 || g_people[i].destination_floor > best_next_floor) {
                    best_next_floor = g_people[i].destination_floor;
                }
            } else if (g_elevator.state == IDLE) { // If idle, drop them off immediately
                return g_people[i].destination_floor;
            }
        }
    }
    if (best_next_floor != 0) return best_next_floor; // Found a drop-off in current direction

    // 2. Prioritize pick-ups based on priority and direction
    for (int i = 0; i < NUM_PEOPLE; ++i) {
        if (g_people[i].state == WAITING_FOR_PICKUP && g_people[i].needs_pickup) {
            bool person_wants_up = (g_people[i].destination_floor > g_people[i].current_floor);
            bool person_wants_down = (g_people[i].destination_floor < g_people[i].current_floor);

            // Check if this person has higher priority than what we've seen
            if (g_people[i].priority > highest_priority_found) {
                highest_priority_found = g_people[i].priority;
                best_next_floor = g_people[i].current_floor; // Tentatively set this as the target
            } else if (g_people[i].priority == highest_priority_found) {
                // If same priority, prioritize based on direction
                // If moving UP: find closest UP request >= current floor
                if (g_elevator.state == MOVING_UP && person_wants_up && g_people[i].current_floor >= g_elevator.current_floor) {
                    if (best_next_floor == 0 || g_people[i].current_floor < best_next_floor) {
                        best_next_floor = g_people[i].current_floor;
                    }
                }
                // If moving DOWN: find closest DOWN request <= current floor
                else if (g_elevator.state == MOVING_DOWN && person_wants_down && g_people[i].current_floor <= g_elevator.current_floor) {
                    if (best_next_floor == 0 || g_people[i].current_floor > best_next_floor) {
                        best_next_floor = g_people[i].current_floor;
                    }
                }
                // If elevator is IDLE or going opposite direction, consider it, but less priority
                else if (g_elevator.state == IDLE) {
                    if (best_next_floor == 0 ||
                        abs(g_people[i].current_floor - g_elevator.current_floor) < abs(best_next_floor - g_elevator.current_floor)) {
                        best_next_floor = g_people[i].current_floor;
                    }
                }
            }
        }
    }

    if (best_next_floor != 0) return best_next_floor;

    // 3. Fallback: If no direct requests in current direction, check for any request
    // This is for when the elevator changes direction or picks up "out of the way" requests.
    // Re-evaluate all waiting people for the highest priority one, regardless of current_floor/direction.
    highest_priority_found = (Priority)-1;
    int closest_floor = 0; // The target floor closest to the elevator

    for (int i = 0; i < NUM_PEOPLE; ++i) {
        if (g_people[i].state == WAITING_FOR_PICKUP && g_people[i].needs_pickup) {
            if (g_people[i].priority > highest_priority_found) {
                highest_priority_found = g_people[i].priority;
                closest_floor = g_people[i].current_floor;
            } else if (g_people[i].priority == highest_priority_found) {
                // If priorities are equal, pick the closest one
                if (closest_floor == 0 || abs(g_people[i].current_floor - g_elevator.current_floor) < abs(closest_floor - g_elevator.current_floor)) {
                    closest_floor = g_people[i].current_floor;
                }
            }
        }
    }
    return closest_floor;
}

void simulate_step() {
    int target_floor = get_next_stop();

    // If no one needs anything, the elevator is idle
    if (target_floor == 0) {
        g_elevator.state = IDLE;
        g_elevator.doors_open = false;
        printf("Elevator is IDLE.\n");
        return;
    }

    // Determine elevator's new state if it was idle, or continue moving
    if (g_elevator.state == IDLE) {
        if (target_floor > g_elevator.current_floor) {
            g_elevator.state = MOVING_UP;
        } else if (target_floor < g_elevator.current_floor) {
            g_elevator.state = MOVING_DOWN;
        } else { // target_floor == current_floor, someone is waiting/needs drop-off here
            g_elevator.state = IDLE; // Will open doors at current floor
        }
    }

    // Move the elevator one floor towards the target
    if (g_elevator.current_floor < target_floor && g_elevator.state == MOVING_UP) {
        g_elevator.current_floor++;
        g_elevator.doors_open = false;
        printf("Elevator moving UP to %d.\n", g_elevator.current_floor);
    } else if (g_elevator.current_floor > target_floor && g_elevator.state == MOVING_DOWN) {
        g_elevator.current_floor--;
        g_elevator.doors_open = false;
        printf("Elevator moving DOWN to %d.\n", g_elevator.current_floor);
    }

    // Check if elevator arrived at a target floor (pickup or dropoff)
    if (g_elevator.current_floor == target_floor) {
        g_elevator.doors_open = true;
        printf("Elevator arrived at Floor %d. Doors OPEN.\n", g_elevator.current_floor);

        // Handle drop-offs first
        for (int i = 0; i < NUM_PEOPLE; ++i) {
            if (g_people[i].state == IN_ELEVATOR && g_people[i].destination_floor == g_elevator.current_floor) {
                g_people[i].state = ARRIVED_AT_DESTINATION;
                g_people[i].current_floor = g_elevator.current_floor; // Update current floor
                g_people[i].needs_dropoff = false;
                g_elevator.onboard_people_count--;
                printf("  Person %d (Priority %d) dropped off at Floor %d.\n",
                       g_people[i].id, g_people[i].priority, g_people[i].current_floor);
            }
        }

        // Handle pick-ups based on priority for this floor
        // We'll pick up the highest priority person at this floor
        Priority highest_pickup_priority_on_floor = (Priority)-1;
        int person_to_pickup_index = -1;

        for (int i = 0; i < NUM_PEOPLE; ++i) {
            if (g_people[i].state == WAITING_FOR_PICKUP && g_people[i].current_floor == g_elevator.current_floor) {
                // Check if this person is waiting and wants to go in the current elevator direction (if not idle)
                bool person_wants_up_from_here = (g_people[i].destination_floor > g_people[i].current_floor);
                bool person_wants_down_from_here = (g_people[i].destination_floor < g_people[i].current_floor);

                if (g_people[i].priority > highest_pickup_priority_on_floor) {
                    if (g_elevator.state == MOVING_UP && person_wants_up_from_here) {
                         highest_pickup_priority_on_floor = g_people[i].priority;
                         person_to_pickup_index = i;
                    } else if (g_elevator.state == MOVING_DOWN && person_wants_down_from_here) {
                         highest_pickup_priority_on_floor = g_people[i].priority;
                         person_to_pickup_index = i;
                    } else if (g_elevator.state == IDLE) { // If idle, pick up highest priority regardless of direction
                        highest_pickup_priority_on_floor = g_people[i].priority;
                        person_to_pickup_index = i;
                    }
                }
            }
        }

        if (person_to_pickup_index != -1) {
            g_people[person_to_pickup_index].state = IN_ELEVATOR;
            g_people[person_to_pickup_index].needs_pickup = false;
            g_people[person_to_pickup_index].needs_dropoff = true;
            g_elevator.onboard_people_count++;
            printf("  Person %d (Priority %d) picked up at Floor %d, going to %d.\n",
                   g_people[person_to_pickup_index].id,
                   g_people[person_to_pickup_index].priority,
                   g_people[person_to_pickup_index].current_floor,
                   g_people[person_to_pickup_index].destination_floor);
        }

        // After pickup/dropoff, set elevator state to IDLE temporarily
        // It will re-evaluate for the next move in the next tick
        g_elevator.state = IDLE;
    }
}

bool all_people_arrived() {
    for (int i = 0; i < NUM_PEOPLE; ++i) {
        if (g_people[i].state != ARRIVED_AT_DESTINATION) {
            return false;
        }
    }
    return true;
}

// Custom sleep for milliseconds
void ms_sleep(int ms) {
    usleep(ms * 1000); // usleep takes microseconds
}

