        if (people[i].priority < 1 || people[i].priority > NUM_PEOPLE) {
            printf("  Invalid priority, setting to 3 (lowest).\n");
            people[i].priority = NUM_PEOPLE;
        }
    }

    // Sort people by priority (ascending)
    sort_by_priority(people, NUM_PEOPLE);

    printf("\nRequests sorted by priority:\n");
    for (i = 0; i < NUM_PEOPLE; ++i) {
        printf("  %s (Priority: %d) -> Floor %d\n", people[i].name, people[i].priority, people[i].desired_floor);
    }

    printf("\nElevator starting at floor 0.\n\n");

    // Serve requests
    for (i = 0; i < NUM_PEOPLE; ++i) {
        printf("Serving %s (Priority %d):\n", people[i].name, people[i].priority);
        printf("  Moving from floor %d to floor %d...\n", current_floor, people[i].desired_floor);
        current_floor = people[i].desired_floor;
        printf("  Arrived at floor %d. %s exits.\n\n", current_floor, people[i].name);
    }

    printf("All requests served. Elevator simulation finished.\n");

    return 0;
}

#include <stdio.h>
