#include <stdbool.h>

#define MAX_FLOORS 10

typedef struct {
    int person_id;
    int current_floor;
    int destination_floor;
    int priority; // Lower number indicates higher priority
} Person;

void moveElevator(Person people[], int num_people, int *elevator_position) {
    // Determine who to serve next based on priority
    int highest_priority = 999;
    int next_person_id = -1;

    for (int i = 0; i < num_people; i++) {
        if (people[i].current_floor != people[i].destination_floor &&
            people[i].priority < highest_priority) {
            highest_priority = people[i].priority;
            next_person_id = i;
        }
    }

    if (next_person_id != -1) {
        if (*elevator_position < people[next_person_id].current_floor) {
            printf("Elevator moving up to floor %d to pick up person %d\n", 
                    people[next_person_id].current_floor, people[next_person_id].person_id);
            *elevator_position = people[next_person_id].current_floor;
        } else if (*elevator_position > people[next_person_id].current_floor) {
            printf("Elevator moving down to floor %d to pick up person %d\n", 
                    people[next_person_id].current_floor, people[next_person_id].person_id);
            *elevator_position = people[next_person_id].current_floor;
        }

        // Move to destination
        if (*elevator_position < people[next_person_id].destination_floor) {
            printf("Elevator moving up to destination floor %d for person %d\n",
                    people[next_person_id].destination_floor, people[next_person_id].person_id);
            *elevator_position = people[next_person_id].destination_floor;
        } else if (*elevator_position > people[next_person_id].destination_floor) {
            printf("Elevator moving down to destination floor %d for person %d\n",
                    people[next_person_id].destination_floor, people[next_person_id].person_id);
            *elevator_position = people[next_person_id].destination_floor;
        }

        // Mark person as served
        people[next_person_id].current_floor = people[next_person_id].destination_floor;
        printf("Person %d has reached their destination.\n", people[next_person_id].person_id);
    } else {
        printf("No more people to serve.\n");
    }
}

