typedef struct {
    int id;         // Person ID
    int priority;   // Priority (1, 2, or 3)
    int requestedFloor; // Floor they want to go to
} Person;

void sortByPriority(Person people[], int n) {
    // Simple selection sort by priority (higher priority = lower number)
    for (int i = 0; i < n - 1; i++) {
        int minIndex = i;
        for (int j = i + 1; j < n; j++) {
            if (people[j].priority < people[minIndex].priority) {
                minIndex = j;
            }
        }
        // Swap if needed
        if (minIndex != i) {
            Person temp = people[i];
            people[i] = people[minIndex];
            people[minIndex] = temp;
        }
    }
}

