void moveElevator(int *current_floor, int target_floor) {
    if (*current_floor < target_floor) {
        printf("Elevator moving up from floor %d to floor %d\n", *current_floor, target_floor);
        *current_floor = target_floor;
    } else if (*current_floor > target_floor) {
        printf("Elevator moving down from floor %d to floor %d\n", *current_floor, target_floor);
        *current_floor = target_floor;
