    }
}

// Function to handle the requests of people
void handleRequests(Person people[], int num_people, int *current_floor) {
    // Sort people based on priority (higher priority first)
    for (int i = 0; i < num_people - 1; i++) {
        for (int j = 0; j < num_people - 1 - i; j++) {
            if (people[j].priority < people[j + 1].priority) {
                Person temp = people[j];
                people[j] = people[j + 1];
                people[j + 1] = temp;
            }
        }
    }

    // Process each person's request
    for (int i = 0; i < num_people; i++) {
        // Move elevator to the person's current floor
        moveElevator(current_floor, people[i].current_floor);
        printf("Person %d has entered the elevator on floor %d\n", people[i].id, *current_floor);

        // Move elevator to the person's destination floor
        moveElevator(current_floor, people[i].destination_floor);
        printf("Person %d has exited the elevator on floor %d\n", people[i].id, *current_floor);
    }
}

