#define MAX_PASSENGERS 9

// Passenger structure
typedef struct {
    int id;
    int currentFloor;
    int destinationFloor;
    int priority;  // 1-10, with 10 being highest priority
    bool inElevator;
} Passenger;

// Elevator structure
typedef struct {
    int currentFloor;
    int capacity;
    Passenger passengers[MAX_PASSENGERS];
} Elevator;

// Function prototypes
void initializeElevator(Elevator *elevator);
void addPassenger(Elevator *elevator, Passenger passenger);
void removePassenger(Elevator *elevator, int passengerId);
void moveElevator(Elevator *elevator, int targetFloor);
void displayElevatorStatus(Elevator *elevator);
int selectNextFloor(Elevator *elevator);
Passenger createPassenger(int id, int currentFloor, int destinationFloor, int priority);

int main() {
    Elevator elevator;
    initializeElevator(&elevator);

    // Creating sample passengers with different priorities
    Passenger passengers[] = {
        createPassenger(1, 1, 5, 7),
        createPassenger(2, 3, 8, 5),
        createPassenger(3, 2, 6, 9),
        createPassenger(4, 4, 7, 3),
        createPassenger(5, 6, 2, 6),
        createPassenger(6, 5, 9, 8),
        createPassenger(7, 7, 1, 4),
        createPassenger(8, 8, 3, 2),
        createPassenger(9, 9, 4, 1)
    };

    // Add passengers to elevator based on priority and current floor
    for (int i = 0; i < 9; i++) {
        addPassenger(&elevator, passengers[i]);
    }

    // Simulate elevator movement
    while (elevator.capacity > 0) {
        int nextFloor = selectNextFloor(&elevator);
        moveElevator(&elevator, nextFloor);
        displayElevatorStatus(&elevator);
    }

    return 0;
}

// Initialize elevator
void initializeElevator(Elevator *elevator) {
    elevator->currentFloor = 1;
    elevator->capacity = 0;
    for (int i = 0; i < MAX_PASSENGERS; i++) {
        elevator->passengers[i].inElevator = false;
    }
}

// Create a passenger
Passenger createPassenger(int id, int currentFloor, int destinationFloor, int priority) {
    Passenger passenger;
    passenger.id = id;
    passenger.currentFloor = currentFloor;
    passenger.destinationFloor = destinationFloor;
    passenger.priority = priority;
    passenger.inElevator = false;
    return passenger;
}

// Add passenger to elevator
void addPassenger(Elevator *elevator, Passenger passenger) {
    if (elevator->capacity < MAX_PASSENGERS && passenger.currentFloor == elevator->currentFloor) {
        elevator->passengers[elevator->capacity] = passenger;
        elevator->passengers[elevator->capacity].inElevator = true;
        elevator->capacity++;
    }
}

// Remove passenger from elevator
void removePassenger(Elevator *elevator, int passengerId) {
    for (int i = 0; i < elevator->capacity; i++) {
        if (elevator->passengers[i].id == passengerId) {
            for (int j = i; j < elevator->capacity - 1; j++) {
                elevator->passengers[j] = elevator->passengers[j + 1];
            }
            elevator->capacity--;
            break;
        }
    }
}

// Move elevator to target floor
void moveElevator(Elevator *elevator, int targetFloor) {
    elevator->currentFloor = targetFloor;

    // Remove passengers at destination floor
    for (int i = 0; i < elevator->capacity; i++) {
        if (elevator->passengers[i].destinationFloor == targetFloor) {
            removePassenger(elevator, elevator->passengers[i].id);
            i--;
        }
    }
}

// Select next floor based on passenger priorities
int selectNextFloor(Elevator *elevator) {
    if (elevator->capacity == 0) return elevator->currentFloor;

    // Sort passengers by priority and destination floor
    for (int i = 0; i < elevator->capacity - 1; i++) {
        for (int j = 0; j < elevator->capacity - i - 1; j++) {
            if (elevator->passengers[j].priority < elevator->passengers[j + 1].priority) {
                Passenger temp = elevator->passengers[j];
                elevator->passengers[j] = elevator->passengers[j + 1];
                elevator->passengers[j + 1] = temp;
            }
        }
    }

    return elevator->passengers[0].destinationFloor;
}

// Display elevator status
void displayElevatorStatus(Elevator *elevator) {
    printf("Current Floor: %d, Passengers: %d\n", elevator->currentFloor, elevator->capacity);
    for (int i = 0; i < elevator->capacity; i++) {
        printf("Passenger %d: Destination Floor %d, Priority %d\n", 
               elevator->passengers[i].id, 
               elevator->passengers[i].destinationFloor, 
               elevator->passengers[i].priority);
    }
    printf("\n");
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

#define NUM_FLOORS 10
#define NUM_PEOPLE 9
#define ELEVATOR_CAPACITY 3

typedef struct {
    int id;
    int current_floor;
    int destination_floor;
    int priority; // Higher number means higher priority
    bool in_elevator;
} Person;

typedef struct {
    int current_floor;
    bool moving_up;
    Person *passengers[ELEVATOR_CAPACITY];
    int num_passengers;
} Elevator;

void initialize_people(Person people[]) {
    srand(time(0));
    for (int i = 0; i < NUM_PEOPLE; i++) {
        people[i].id = i + 1;
        people[i].current_floor = rand() % NUM_FLOORS;
        do {
            people[i].destination_floor = rand() % NUM_FLOORS;
        } while (people[i].destination_floor == people[i].current_floor);
        people[i].priority = rand() % 5 + 1; // Priorities 1-5 (1=lowest, 5=highest)
        people[i].in_elevator = false;
    }
}

void initialize_elevator(Elevator *elevator) {
    elevator->current_floor = 0;
    elevator->moving_up = true;
    elevator->num_passengers = 0;
    for (int i = 0; i < ELEVATOR_CAPACITY; i++) {
        elevator->passengers[i] = NULL;
    }
}

void print_status(Person people[], Elevator *elevator) {
    printf("\nElevator at floor %d, direction: %s, passengers: %d\n",
           elevator->current_floor,
           elevator->moving_up ? "UP" : "DOWN",
           elevator->num_passengers);

    printf("People waiting:\n");
    for (int i = 0; i < NUM_PEOPLE; i++) {
        if (!people[i].in_elevator) {
            printf("  Person %d: at floor %d, going to %d, priority %d\n",
                   people[i].id, people[i].current_floor, 
                   people[i].destination_floor, people[i].priority);
        }
    }

    printf("People in elevator:\n");
    for (int i = 0; i < ELEVATOR_CAPACITY; i++) {
        if (elevator->passengers[i] != NULL) {
            printf("  Person %d: going to %d, priority %d\n",
                   elevator->passengers[i]->id,
                   elevator->passengers[i]->destination_floor,
                   elevator->passengers[i]->priority);
        }
    }
}

void board_passengers(Person people[], Elevator *elevator) {
    // Sort people by priority (higher first) and then by distance to elevator
    for (int i = 0; i < NUM_PEOPLE - 1; i++) {
        for (int j = 0; j < NUM_PEOPLE - i - 1; j++) {
            if (people[j].priority < people[j+1].priority || 
                (people[j].priority == people[j+1].priority && 
                 abs(people[j].current_floor - elevator->current_floor) > 
                 abs(people[j+1].current_floor - elevator->current_floor))) {
                Person temp = people[j];
                people[j] = people[j+1];
                people[j+1] = temp;
            }
        }
    }

    // Board people who are at current floor and want to go in current direction
    for (int i = 0; i < NUM_PEOPLE && elevator->num_passengers < ELEVATOR_CAPACITY; i++) {
        if (!people[i].in_elevator && 
            people[i].current_floor == elevator->current_floor &&
            ((elevator->moving_up && people[i].destination_floor > people[i].current_floor) ||
             (!elevator->moving_up && people[i].destination_floor < people[i].current_floor))) {

            // Find empty spot in elevator
            for (int j = 0; j < ELEVATOR_CAPACITY; j++) {
                if (elevator->passengers[j] == NULL) {
                    elevator->passengers[j] = &people[i];
                    people[i].in_elevator = true;
                    elevator->num_passengers++;
                    printf("Person %d boarded the elevator (priority %d)\n", 
                           people[i].id, people[i].priority);
                    break;
                }
            }
        }
    }
}

void unload_passengers(Person people[], Elevator *elevator) {
    for (int i = 0; i < ELEVATOR_CAPACITY; i++) {
        if (elevator->passengers[i] != NULL && 
            elevator->passengers[i]->destination_floor == elevator->current_floor) {

            printf("Person %d left the elevator\n", elevator->passengers[i]->id);
            elevator->passengers[i]->in_elevator = false;
            elevator->passengers[i] = NULL;
            elevator->num_passengers--;
        }
    }
}

void move_elevator(Elevator *elevator) {
    if (elevator->moving_up) {
        if (elevator->current_floor < NUM_FLOORS - 1) {
            elevator->current_floor++;
        } else {
            elevator->moving_up = false;
            elevator->current_floor--;
        }
    } else {
        if (elevator->current_floor > 0) {
            elevator->current_floor--;
        } else {
            elevator->moving_up = true;
            elevator->current_floor++;
        }
    }
}

bool all_people_delivered(Person people[]) {
    for (int i = 0; i < NUM_PEOPLE; i++) {
        if (people[i].current_floor != people[i].destination_floor) {
            return false;
        }
    }
    return true;
}

int main() {
    Person people[NUM_PEOPLE];
    Elevator elevator;

    initialize_people(people);
    initialize_elevator(&elevator);

    printf("Elevator Simulation with %d people and %d floors\n", NUM_PEOPLE, NUM_FLOORS);
    printf("Initial state:\n");
    print_status(people, &elevator);

    int step = 0;
    while (!all_people_delivered(people)) {
        printf("\n--- Step %d ---\n", ++step);

        // Unload passengers who have arrived
        unload_passengers(people, &elevator);

        // Board new passengers
        board_passengers(people, &elevator);

        // Move elevator
        move_elevator(&elevator);

        // Print current status
        print_status(people, &elevator);
    }

    printf("\nSimulation complete! All people have reached their destinations.\n");
    return 0;
}

