// --- Priority Queue Implementation (Min-Heap) ---

void pq_init(PriorityQueue *pq) {
    pq->size = 0;
}

void swap_pq_elements(WaitingPerson_PQ *a, WaitingPerson_PQ *b) {
    WaitingPerson_PQ temp = *a;
    *a = *b;
    *b = temp;
}

void pq_heapify_up(PriorityQueue *pq, int index) {
    int parent = (index - 1) / 2;
    while (index > 0 &&
           (pq->heap[index].priority < pq->heap[parent].priority ||
            (pq->heap[index].priority == pq->heap[parent].priority &&
             pq->heap[index].entry_time < pq->heap[parent].entry_time))) { // Tie-break by entry_time
        swap_pq_elements(&pq->heap[index], &pq->heap[parent]);
        index = parent;
        parent = (index - 1) / 2;
    }
}

void pq_heapify_down(PriorityQueue *pq, int index) {
    int min_child_idx;
    int left_child = 2 * index + 1;
    int right_child = 2 * index + 2;

    while (left_child < pq->size) {
        min_child_idx = left_child;
        if (right_child < pq->size &&
            (pq->heap[right_child].priority < pq->heap[left_child].priority ||
             (pq->heap[right_child].priority == pq->heap[left_child].priority &&
              pq->heap[right_child].entry_time < pq->heap[left_child].entry_time))) {
            min_child_idx = right_child;
        }

        if (pq->heap[min_child_idx].priority < pq->heap[index].priority ||
            (pq->heap[min_child_idx].priority == pq->heap[index].priority &&
             pq->heap[min_child_idx].entry_time < pq->heap[index].entry_time)) {
            swap_pq_elements(&pq->heap[index], &pq->heap[min_child_idx]);
            index = min_child_idx;
            left_child = 2 * index + 1;
            right_child = 2 * index + 2;
        } else {
            break;
        }
    }
}

void pq_push(PriorityQueue *pq, int person_id, int priority, int entry_time) {
    if (pq->size >= MAX_WAIT_QUEUE_SIZE) {
        printf("Error: Priority queue is full!\n");
        return;
    }
    pq->heap[pq->size].person_id = person_id;
    pq->heap[pq->size].priority = priority;
    pq->heap[pq->size].entry_time = entry_time;
    pq->size++;
    pq_heapify_up(pq, pq->size - 1);
}

int pq_pop(PriorityQueue *pq) {
    if (pq->size == 0) {
        return -1; // Indicate empty
    }
    int person_id_popped = pq->heap[0].person_id;
    pq->heap[0] = pq->heap[pq->size - 1];
    pq->size--;
    pq_heapify_down(pq, 0);
    return person_id_popped;
}

bool pq_is_empty(PriorityQueue *pq) {
    return pq->size == 0;
}

// --- Elevator Control Functions ---

void initialize_building_and_people() {
    g_elevator.current_floor = 1;
    g_elevator.direction = IDLE;
    g_elevator.num_passengers = 0;
    for (int i = 1; i <= NUM_FLOORS; i++) {
        g_elevator.requests_up[i] = false;
        g_elevator.requests_down[i] = false;
    }

    // Initialize people with varying current_floor, destination_floor, and priority
    // Lower priority number = higher priority
    g_people[0] = (Person){.id = 1, .current_floor = 1, .destination_floor = 7, .priority = 2, .status = WAITING};
    g_people[1] = (Person){.id = 2, .current_floor = 5, .destination_floor = 1, .priority = 1, .status = WAITING}; // High priority
    g_people[2] = (Person){.id = 3, .current_floor = 2, .destination_floor = 8, .priority = 3, .status = WAITING};
    g_people[3] = (Person){.id = 4, .current_floor = 9, .destination_floor = 3, .priority = 2, .status = WAITING};
    g_people[4] = (Person){.id = 5, .current_floor = 1, .destination_floor = 10, .priority = 4, .status = WAITING};
    g_people[5] = (Person){.id = 6, .current_floor = 6, .destination_floor = 2, .priority = 1, .status = WAITING}; // High priority
    g_people[6] = (Person){.id = 7, .current_floor = 3, .destination_floor = 5, .priority = 3, .status = WAITING};
    g_people[7] = (Person){.id = 8, .current_floor = 8, .destination_floor = 1, .priority = 5, .status = WAITING};
    g_people[8] = (Person){.id = 9, .current_floor = 4, .destination_floor = 9, .priority = 2, .status = WAITING};

    // Set initial entry_time for everyone
    for (int i = 0; i < NUM_PEOPLE; i++) {
        g_people[i].entry_time = g_time_step;
    }
}

// Adds a person to the global waiting priority queue and sets their request
void add_person_to_queue(int person_idx) {
    Person *p = &g_people[person_idx];
    if (p->status == WAITING) {
        pq_push(&g_waiting_queue, p->id, p->priority, p->entry_time); // Use g_people[person_id].entry_time
        if (p->destination_floor > p->current_floor) {
            g_elevator.requests_up[p->current_floor] = true;
        } else if (p->destination_floor < p->current_floor) {
            g_elevator.requests_down[p->current_floor] = true;
        }
        printf("[Time %d] Person %d (Prio %d) registered call from floor %d to %d.\n",
               g_time_step, p->id, p->priority, p->current_floor, p->destination_floor);
    }
}

// Simulates elevator moving one floor
void elevator_move() {
    if (g_elevator.direction == UP) {
        g_elevator.current_floor++;
        if (g_elevator.current_floor > NUM_FLOORS) {
            g_elevator.current_floor = NUM_FLOORS; // Should not happen with proper direction/stops
            g_elevator.direction = DOWN;
        }
    } else if (g_elevator.direction == DOWN) {
        g_elevator.current_floor--;
        if (g_elevator.current_floor < 1) {
            g_elevator.current_floor = 1; // Should not happen
            g_elevator.direction = UP;
        }
    }
    printf("[Time %d] Elevator moved to floor %d. Direction: %s\n",
           g_time_step, g_elevator.current_floor,
           g_elevator.direction == UP ? "UP" : (g_elevator.direction == DOWN ? "DOWN" : "IDLE"));
}

void elevator_open_doors() {
    printf("[Time %d] Elevator doors opened at floor %d.\n", g_time_step, g_elevator.current_floor);

    // 1. Drop off passengers
    // Iterate backwards to make removal easier
    for (int i = g_elevator.num_passengers - 1; i >= 0; i--) {
        Person *p = &g_people[get_person_idx(g_elevator.passengers[i].id)];
        if (p->destination_floor == g_elevator.current_floor) {
            p->status = COMPLETED;
            printf("  - Person %d exited at floor %d (destination reached).\n", p->id, p->destination_floor);

            // Remove passenger from elevator (shift elements)
            for (int k = i; k < g_elevator.num_passengers - 1; k++) {
                g_elevator.passengers[k] = g_elevator.passengers[k + 1];
            }
            g_elevator.num_passengers--;

            // Clear the internal request for this floor now that passenger is off
            if (p->destination_floor > g_elevator.current_floor) { // Was going up to a floor
                g_elevator.requests_up[p->destination_floor] = false;
            } else if (p->destination_floor < g_elevator.current_floor) { // Was going down to a floor
                g_elevator.requests_down[p->destination_floor] = false;
            }
        }
    }

    // 2. Pick up waiting passengers (based on current direction and priority)
    // Create a temporary list of waiting people at this floor
    int waiting_at_this_floor[NUM_PEOPLE];
    int num_waiting_at_this_floor = 0;

    // First: Identify people waiting at this floor.
    // Important: DO NOT remove from g_waiting_queue yet, as we need to re-add if not picked up.
    for (int i = 0; i < g_waiting_queue.size; i++) {
        int person_id_in_pq = g_waiting_queue.heap[i].person_id;
        Person *p = &g_people[get_person_idx(person_id_in_pq)];
        if (p->current_floor == g_elevator.current_floor && p->status == WAITING) {
            waiting_at_this_floor[num_waiting_at_this_floor++] = p->id;
        }
    }

    // Now, iterate through the *original* g_waiting_queue, pop people if they are at this floor
    // and match the elevator's current direction, or if elevator is IDLE.
    // We need to re-add those who are skipped back into the queue.
    PriorityQueue temp_pq;
    pq_init(&temp_pq); // Temporary queue to hold people not picked up

    while (!pq_is_empty(&g_waiting_queue) && g_elevator.num_passengers < MAX_PEOPLE_IN_ELEVATOR) {
        int current_person_id_from_pq = pq_pop(&g_waiting_queue);
        Person *p = &g_people[get_person_idx(current_person_id_from_pq)];

        if (p->status == WAITING && p->current_floor == g_elevator.current_floor) {
            bool pick_up = false;
            if (g_elevator.direction == IDLE) { // Pick up anyone if idle
                pick_up = true;
                // Once a person is picked up while IDLE, set elevator direction
                if (p->destination_floor > p->current_floor) {
                    g_elevator.direction = UP;
                } else if (p->destination_floor < p->current_floor) {
                    g_elevator.direction = DOWN;
                }
            } else if (g_elevator.direction == UP && p->destination_floor > p->current_floor) {
                // Pick up if going UP and person wants to go UP
                pick_up = true;
            } else if (g_elevator.direction == DOWN && p->destination_floor < p->current_floor) {
                // Pick up if going DOWN and person wants to go DOWN
                pick_up = true;
            }

            if (pick_up) {
                // Pick up the person
                g_elevator.passengers[g_elevator.num_passengers++] = *p;
                p->status = IN_ELEVATOR;
                printf("  - Person %d (Prio %d) entered elevator at floor %d (to %d).\n",
                       p->id, p->priority, p->current_floor, p->destination_floor);

                // Add passenger's destination to elevator's internal requests
                if (p->destination_floor > g_elevator.current_floor) {
                    g_elevator.requests_up[p->destination_floor] = true;
                } else if (p->destination_floor < g_elevator.current_floor) {
                    g_elevator.requests_down[p->destination_floor] = true;
                }
                // Clear active call for this floor for the direction they were waiting
                if (p->destination_floor > p->current_floor) {
                    g_elevator.requests_up[p->current_floor] = false;
                } else if (p->destination_floor < p->current_floor) {
                    g_elevator.requests_down[p->current_floor] = false;
                }
            } else {
                // Person is waiting at this floor but not going in the current direction.
                // Re-add to a temporary queue.
                pq_push(&temp_pq, p->id, p->priority, p->entry_time);
            }
        } else {
            // Person is not at this floor, or not WAITING anymore (maybe taken by another elevator in future scenario)
            // Re-add to temporary queue
            pq_push(&temp_pq, p->id, p->priority, p->entry_time);
        }
    }
    // All remaining elements from g_waiting_queue are now in temp_pq, or picked up.
    // Copy them back to g_waiting_queue.
    g_waiting_queue = temp_pq; // Shallow copy of struct is sufficient here

    printf("[Time %d] Elevator doors closed at floor %d.\n", g_time_step, g_elevator.current_floor);
}

// Determines the elevator's next strategic move (floor and direction)
Direction get_next_destination() {
    bool up_requests_exist = false;
    bool down_requests_exist = false;
    for (int i = 1; i <= NUM_FLOORS; i++) {
        if (g_elevator.requests_up[i]) up_requests_exist = true;
        if (g_elevator.requests_down[i]) down_requests_exist = true;
    }

    // Check for passenger destinations in current direction first (highest priority for in-transit people)
    if (g_elevator.direction == UP || g_elevator.direction == IDLE) {
        for (int f = g_elevator.current_floor; f <= NUM_FLOORS; f++) {
            // Check for passengers wanting to get off
            for (int i = 0; i < g_elevator.num_passengers; i++) {
                if (g_elevator.passengers[i].destination_floor == f) return UP;
            }
            // Check for potential pickups in UP direction
            if (g_elevator.requests_up[f]) return UP;
        }
    }
    if (g_elevator.direction == DOWN || g_elevator.direction == IDLE) {
        for (int f = g_elevator.current_floor; f >= 1; f--) {
            // Check for passengers wanting to get off
            for (int i = 0; i < g_elevator.num_passengers; i++) {
                if (g_elevator.passengers[i].destination_floor == f) return DOWN;
            }
            // Check for potential pickups in DOWN direction
            if (g_elevator.requests_down[f]) return DOWN;
        }
    }

    // If no requests in current direction or passengers, then reverse direction if there are requests.
    if (g_elevator.direction == UP) { // Was going up, no new requests there, check for down requests
        if (down_requests_exist) return DOWN;
    } else if (g_elevator.direction == DOWN) { // Was going down, no new requests there, check for up requests
        if (up_requests_exist) return UP;
    }

    // If still IDLE or no clear direction, re-evaluate based on the highest priority waiting person.
    if (pq_is_empty(&g_waiting_queue)) {
        return IDLE; // Nothing to do
    } else {
        // Peek at the highest priority person
        int next_person_id = g_waiting_queue.heap[0].person_id;
        Person *p = &g_people[get_person_idx(next_person_id)];

        if (p->current_floor == g_elevator.current_floor) {
             // If the highest priority person is on the current floor, and wasn't picked up
             // (e.g. because elevator was full or going wrong direction),
             // try to pick them up now if possible.
             // This can also happen if direct call for current floor was not handled.
             if (g_elevator.num_passengers < MAX_PEOPLE_IN_ELEVATOR) {
                 // The logic in open_doors should prioritize picking up if idle
                 // or if matches direction. This is a tie-breaker for *next* direction.
                 if (p->destination_floor > p->current_floor) return UP;
                 if (p->destination_floor < p->current_floor) return DOWN;
                 // If destination is current floor, they should already be off/not requesting
                 return IDLE;
             } else {
                 // Elevator is full, or they want wrong direction. Find the next closest request.
                 // This is a simplification; a full simulation would need more complex routing.
                 // For now, if no one can be picked up here, look elsewhere.
                 if (p->current_floor > g_elevator.current_floor) return UP;
                 if (p->current_floor < g_elevator.current_floor) return DOWN;
             }
        } else if (p->current_floor > g_elevator.current_floor) {
             return UP; // Go up to pick up highest priority person
        } else if (p->current_floor < g_elevator.current_floor) {
             return DOWN; // Go down to pick up highest priority person
        }
    }

    // If all else fails and no one is waiting, stay IDLE
    return IDLE;
}

// Main simulation loop
void simulate_elevator() {
    printf("\n--- Starting Simulation ---\n");

    while (!is_simulation_complete()) {
        g_time_step++;
        printf("\n--- Time Step %d ---\n", g_time_step);
        print_elevator_state();
        print_people_state();


        // Determine next action
        Direction next_direction = IDLE;
        bool should_open_doors = false;

        // Check if elevator needs to open doors (drop-off or pick-up)
        for (int i = 0; i < g_elevator.num_passengers; i++) {
            if (g_elevator.passengers[i].destination_floor == g_elevator.current_floor) {
                should_open_doors = true;
                break;
            }
        }
        if (!should_open_doors) {
             // Check if someone is waiting at this floor and we should pick them up
             // This needs to align with elevator's current direction, unless IDLE
            if ((g_elevator.direction == UP && g_elevator.requests_up[g_elevator.current_floor]) ||
                (g_elevator.direction == DOWN && g_elevator.requests_down[g_elevator.current_floor]) ||
                (g_elevator.direction == IDLE && (g_elevator.requests_up[g_elevator.current_floor] || g_elevator.requests_down[g_elevator.current_floor]))) {
                should_open_doors = true;
            }
        }

        if (should_open_doors) {
            elevator_open_doors();
        } else {
            // Find next direction.
            // If elevator is currently moving, it should maintain current direction
            // unless all requests in that direction are fulfilled.
            if (g_elevator.direction != IDLE) { // Check if we still have stops in current direction
                bool continue_current_direction = false;
                if (g_elevator.direction == UP) {
                    for (int f = g_elevator.current_floor + 1; f <= NUM_FLOORS; f++) {
                        if (g_elevator.requests_up[f]) { continue_current_direction = true; break; }
                        // Also check for passengers to drop off above current floor
                        for (int i = 0; i < g_elevator.num_passengers; i++) {
                            if (g_elevator.passengers[i].destination_floor == f) { continue_current_direction = true; break; }
                        }
                        if (continue_current_direction) break;
                    }
                } else if (g_elevator.direction == DOWN) {
                    for (int f = g_elevator.current_floor - 1; f >= 1; f--) {
                        if (g_elevator.requests_down[f]) { continue_current_direction = true; break; }
                        // Also check for passengers to drop off below current floor
                        for (int i = 0; i < g_elevator.num_passengers; i++) {
                            if (g_elevator.passengers[i].destination_floor == f) { continue_current_direction = true; break; }
                        }
                        if (continue_current_direction) break;
                    }
                }
                if (continue_current_direction) {
                    next_direction = g_elevator.direction;
                } else {
                    next_direction = get_next_destination(); // Find new direction
                }
            } else { // Elevator is IDLE, find next direction
                next_direction = get_next_destination();
            }

            g_elevator.direction = next_direction;
            if (g_elevator.direction != IDLE) {
                elevator_move();
            } else {
                printf("[Time %d] Elevator is IDLE at floor %d.\n", g_time_step, g_elevator.current_floor);
            }
        }
    }
}

// Checks if all people have reached their destinations
bool is_simulation_complete() {
    for (int i = 0; i < NUM_PEOPLE; i++) {
        if (g_people[i].status != COMPLETED) {
            return false;
        }
    }
    return true;
}

// --- Helper Functions for Debugging/Output ---

void print_elevator_state() {
    printf("Elevator State: Floor %d, Direction %s, Passengers (%d/%d): [",
           g_elevator.current_floor,
           g_elevator.direction == UP ? "UP" : (g_elevator.direction == DOWN ? "DOWN" : "IDLE"),
           g_elevator.num_passengers, MAX_PEOPLE_IN_ELEVATOR);
    for (int i = 0; i < g_elevator.num_passengers; i++) {
        printf("P%d(to%d)%s", g_elevator.passengers[i].id, g_elevator.passengers[i].destination_floor,
               i == g_elevator.num_passengers - 1 ? "" : ", ");
    }
    printf("]. WAITING: %d.\n", g_waiting_queue.size);

    printf("  Up requests: ");
    for (int i = 1; i <= NUM_FLOORS; i++) {
        if (g_elevator.requests_up[i]) printf("%d ", i);
    }
    printf("\n  Down requests: ");
    for (int i = 1; i <= NUM_FLOORS; i++) {
        if (g_elevator.requests_down[i]) printf("%d ", i);
    }
    printf("\n");
}

void print_people_state() {
    printf("People State:\n");
    for (int i = 0; i < NUM_PEOPLE; i++) {
        const char *status_str;
        switch (g_people[i].status) {
            case WAITING: status_str = "WAITING"; break;
            case IN_ELEVATOR: status_str = "IN_ELEVATOR"; break;
            case COMPLETED: status_str = "COMPLETED"; break;
            default: status_str = "UNKNOWN"; break;
        }
        printf("  Person %d: From %d to %d (Prio %d) - Status: %s%s\n",
               g_people[i].id, g_people[i].current_floor,
               g_people[i].destination_floor, g_people[i].priority,
               status_str,
               g_people[i].status == WAITING ?
                   (g_people[i].destination_floor > g_people[i].current_floor ? " (Call UP)" :
                       (g_people[i].destination_floor < g_people[i].current_floor ? " (Call DOWN)" : "") )
                   : "");
    }
}

// Helper to get array index from person ID
int get_person_idx(int person_id) {
    for (int i = 0; i < NUM_PEOPLE; i++) {
        if (g_people[i].id == person_id) {
            return i;
        }
    }
    return -1; // Should not happen in this controlled simulation
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define NUM_PEOPLE 9
#define MIN_FLOOR 2
#define MAX_FLOOR 10

typedef struct {
    int id;
    int priority;      // 1 = highest
    int dest_floor;
    int waiting;       // 1 = waiting to ride, 0 = already delivered
} Person;

// Find index of waiting person with highest priority (lowest number)
int find_next_passenger(Person *people, int count) {
    int i, idx = -1;
    int high_priority = 1000;
    for (i = 0; i < count; i++) {
        if (people[i].waiting && people[i].priority < high_priority) {
            high_priority = people[i].priority;
            idx = i;
        }
    }
    return idx;
}

int main() {
    Person people[NUM_PEOPLE];
    int delivered = 0, next;
    int trip = 0;
    srand(time(NULL));

    // Initialize people with random priorities & destination floors
    for (int i = 0; i < NUM_PEOPLE; i++) {
        people[i].id = i + 1;
        people[i].priority = rand() % NUM_PEOPLE + 1;      // priorities: 1 to 9
        people[i].dest_floor = rand() % (MAX_FLOOR - MIN_FLOOR + 1) + MIN_FLOOR;
        people[i].waiting = 1;
    }

    printf("Initial status:\n");
    for (int i = 0; i < NUM_PEOPLE; i++) {
        printf("Person %d: Priority=%d, Destination=Floor %d\n",
            people[i].id, people[i].priority, people[i].dest_floor);
    }

    printf("\nElevator starts operating\n");

    while (delivered < NUM_PEOPLE) {
        next = find_next_passenger(people, NUM_PEOPLE);
        if (next == -1) break; // All done

        trip++;
        printf("Trip %d: Picking Person %d (Priority %d) to Floor %d\n",
               trip, people[next].id, people[next].priority, people[next].dest_floor);

        people[next].waiting = 0;
        delivered++;
    }

    printf("All people have reached their destination.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAX_PEOPLE 9
#define MAX_FLOORS 10

typedef struct {
    int id;
    int currentFloor;
    int targetFloor;
    int priority; // Lower number means higher priority
} Person;

// Function to compare people based on their priority
int comparePriority(const void *a, const void *b) {
    Person *personA = (Person*)a;
    Person *personB = (Person*)b;
    return personA->priority - personB->priority;
}

void moveElevator(Person people[], int size) {
    int currentFloor = 0;
    int targetFloors[MAX_PEOPLE];
    int traveled = 0;

    // Initialize targetFloors
    for (int i = 0; i < size; i++) {
        targetFloors[i] = people[i].targetFloor;
    }

    while (traveled < size) {
        // Move elevator to the target floor with the highest priority person
        for (int i = 0; i < size; i++) {
            if (targetFloors[i] != -1) {
                currentFloor = targetFloors[i];
                printf("Moving to floor %d for Person %d with priority %d.\n",
                       currentFloor, people[i].id, people[i].priority);
                targetFloors[i] = -1;
                traveled++;
                break;
            }
        }
