// Add a new request to the list
void add_request(Person requests[], int *request_count, int floor, int priority) {
    if (floor < 0 || floor >= FLOORS || priority < 1 || priority > 9) {
        printf("Invalid input. Please enter valid floor (0-9) and priority (1-9).\n");
        return;
    }

    requests[*request_count].floor = floor;
    requests[*request_count].priority = priority;
    (*request_count)++;
    printf("Request added.\n");
}

// Sort the requests based on priority (higher priority first)
void sort_requests(Person requests[], int request_count) {
    for (int i = 0; i < request_count - 1; i++) {
        for (int j = 0; j < request_count - 1 - i; j++) {
            if (requests[j].priority > requests[j + 1].priority) {
                Person temp = requests[j];
                requests[j] = requests[j + 1];
                requests[j + 1] = temp;
            }
        }
    }
}

// Service the requests in the sorted order
void service_requests(Person requests[], int *request_count) {
    printf("Servicing requests:\n");
    for (int i = 0; i < *request_count; i++) {
        printf("Going to floor %d (Priority: %d)\n", requests[i].floor, requests[i].priority);
    }
    *request_count = 0; // Clear the request list after servicing
}

