// Function to compare two sublists lexicographically
int compare_lists(int* list1, int* list2, int list_size) {
    for (int i = 0; i < list_size; i++) {
        if (list1[i] < list2[i]) {
            return -1;  // list1 comes before list2
        } else if (list1[i] > list2[i]) {
            return 1;   // list1 comes after list2
        }
    }
    return 0;  // lists are identical
}

// Function to swap two rows in the 2D array
void swap_rows(int** arr, int row1, int row2, int list_size) {
    int* temp = malloc(list_size * sizeof(int));

    // Copy row1 to temp
    for (int i = 0; i < list_size; i++) {
        temp[i] = arr[row1][i];
    }

    // Copy row2 to row1
    for (int i = 0; i < list_size; i++) {
        arr[row1][i] = arr[row2][i];
    }

    // Copy temp to row2
    for (int i = 0; i < list_size; i++) {
        arr[row2][i] = temp[i];
    }

    free(temp);
}

// Function to sort 2D array lexicographically using bubble sort
void sort_lexicographically(int** arr, int num_lists, int list_size) {
    for (int i = 0; i < num_lists - 1; i++) {
        for (int j = 0; j < num_lists - i - 1; j++) {
            // Compare adjacent rows
            if (compare_lists(arr[j], arr[j+1], list_size) > 0) {
                // Swap rows if current row is lexicographically larger
                swap_rows(arr, j, j+1, list_size);
            }
        }
    }
}

