// Function to compare two rows (sublists) of the 2D array
int compare(const void *a, const void *b) {
    int *row1 = *(int **)a;
    int *row2 = *(int **)b;
    int i = 0;

    // Compare elements of the rows until a difference is found
    while (row1[i] == row2[i]) {
        i++;
        // If we reach the end of both rows without finding a difference, they are equal
        if (row1[i] == -1 && row2[i] == -1) {
            return 0;
        }
    }

    // Return the difference between the current elements
    return row1[i] - row2[i];
}

