// Function to compare two sublists (rows) lexicographically
// Returns:
//   -1 if sublist1 < sublist2
//    0 if sublist1 == sublist2
//    1 if sublist1 > sublist2
int compareSublists(const int *sublist1, const int *sublist2, int sublistLength) {
    for (int i = 0; i < sublistLength; i++) {
        if (sublist1[i] < sublist2[i]) {
            return -1; // sublist1 is smaller
        } else if (sublist1[i] > sublist2[i]) {
            return 1; // sublist1 is larger
        }
        // If elements are equal, continue to the next element
    }
    return 0; // Sublists are identical up to sublistLength
}

// Comparison function for qsort
// This function casts void pointers back to int** (pointers to int arrays)
int qsortComparison(const void *a, const void *b) {
    // Cast void pointers to pointers to int arrays (the rows)
    const int *sublist1 = *(const int **)a;
    const int *sublist2 = *(const int **)b;

    // We need to know the length of the sublists to compare them.
    // In a real-world scenario, you might pass a struct containing
    // the 2D array and its dimensions, or make `sublistLength` global.
    // For this example, let's assume `sublistLength` is fixed.
    // A better approach for general use would be to pass it as a context
    // parameter if C's qsort allowed it directly, or wrap it in a struct.
    // For competitive programming or simpler tasks, a global variable is common.
    // Let's define a global for demonstration, but acknowledge its limitations.
    extern int globalSublistLength; // Declared here, defined below main.

    return compareSublists(sublist1, sublist2, globalSublistLength);
}

// Global variable to pass sublist length to qsortComparison
// (A common workaround for qsort when extra parameters are needed)
int globalSublistLength;

