// Custom comparator function for lexicographical sorting
int compare(const void *a, const void *b) {
    const int *listA = *(const int **)a;
    const int *listB = *(const int **)b;

    int i = 0;
    // Compare elements of the two lists one by one
    while (listA[i] != -1 && listB[i] != -1) {
        if (listA[i] < listB[i]) return -1;
        if (listA[i] > listB[i]) return 1;
        i++;
    }

    // If we reach here, either both lists are equal in compared sections or a list ends.
    // Consider shorter lists preceding longer lists if they match in all compared values.
    if (listA[i] == -1 && listB[i] != -1) return -1; // listA ends before listB
    if (listA[i] != -1 && listB[i] == -1) return 1;  // listB ends before listA
    return 0; // Lists are exactly the same
}

