    // Number of sublists
    int num_sublists = 5;

    // Length of each sublist
    int sublist_length = 3;

    // Convert the 2D array to an array of pointers
    int *sublists[num_sublists];
    for (int i = 0; i < num_sublists; i++) {
        sublists[i] = array[i];
