// Structure to pass arguments to thread function
typedef struct {
    int row;
    int col;
    int** matrix1;
    int** matrix2;
    int** result_matrix;
    int common_dim;
} thread_args;

// Function to allocate a 2D matrix dynamically
int** create_matrix(int rows, int cols) {
    int** matrix = (int**)malloc(rows * sizeof(int*));
    for (int i = 0; i < rows; i++) {
        matrix[i] = (int*)malloc(cols * sizeof(int));
    }
    return matrix;
}

// Function to free a dynamically allocated matrix
void free_matrix(int** matrix, int rows) {
    for (int i = 0; i < rows; i++) {
        free(matrix[i]);
    }
    free(matrix);
}

// Function to initialize a matrix with random values
void initialize_matrix(int** matrix, int rows, int cols) {
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            matrix[i][j] = rand() % 10;  // Random values between 0-9
        }
    }
}

// Thread function for matrix multiplication
void* matrix_mult_thread(void* args) {
    thread_args* data = (thread_args*)args;
    int row = data->row;
    int col = data->col;
    int common_dim = data->common_dim;

    // Compute dot product for specific cell
    int cell_value = 0;
    for (int k = 0; k < common_dim; k++) {
        cell_value += data->matrix1[row][k] * data->matrix2[k][col];
    }

    // Store result in result matrix
    data->result_matrix[row][col] = cell_value;

    free(args);  // Free thread argument memory
    return NULL;
}

// Function to perform parallel matrix multiplication
int** parallel_matrix_multiply(int** matrix1, int** matrix2, int rows1, int cols1, int rows2, int cols2) {
    // Check matrix multiplication compatibility
    if (cols1 != rows2) {
        printf("Matrix multiplication not possible!\n");
        return NULL;
    }

    // Create result matrix
    int** result_matrix = create_matrix(rows1, cols2);

    // Create threads for each cell of result matrix
    pthread_t** threads = malloc(rows1 * sizeof(pthread_t*));
    for (int i = 0; i < rows1; i++) {
        threads[i] = malloc(cols2 * sizeof(pthread_t));
        for (int j = 0; j < cols2; j++) {
            // Create arguments for each thread
            thread_args* args = malloc(sizeof(thread_args));
            args->row = i;
            args->col = j;
            args->matrix1 = matrix1;
            args->matrix2 = matrix2;
            args->result_matrix = result_matrix;
            args->common_dim = cols1;

            // Create thread for each matrix cell
            pthread_create(&threads[i][j], NULL, matrix_mult_thread, (void*)args);
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < rows1; i++) {
        for (int j = 0; j < cols2; j++) {
            pthread_join(threads[i][j], NULL);
        }
        free(threads[i]);
    }
    free(threads);

    return result_matrix;
}

// Function to print a matrix
void print_matrix(int** matrix, int rows, int cols) {
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            printf("%4d ", matrix[i][j]);
        }
        printf("\n");
    }
}

int main() {
    // Set random seed
    srand(time(NULL));

    // Matrix dimensions
    int rows1 = 3, cols1 = 4;
    int rows2 = 4, cols2 = 3;

    // Create and initialize matrices
    int** matrix1 = create_matrix(rows1, cols1);
