}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s <matrix_size> <num_threads>\n", argv[0]);
        return 1;
    }

    int size = atoi(argv[1]);
    int num_threads = atoi(argv[2]);

    if (size <= 0 || num_threads <= 0) {
        printf("Both matrix size and number of threads must be positive integers.\n");
        return 1;
    }

    // Allocate matrices
    double **A = allocate_matrix(size);
    double **B = allocate_matrix(size);
    double **C = allocate_matrix(size);

    // Initialize matrices with random values
    initialize_matrix(A, size);
    initialize_matrix(B, size);

    printf("Matrix A:\n");
    print_matrix(A, size);
    printf("\nMatrix B:\n");
    print_matrix(B, size);

    // Create threads
    pthread_t threads[num_threads];
    thread_data_t thread_data[num_threads];

    // Calculate rows per thread
    int rows_per_thread = size / num_threads;
    int extra_rows = size % num_threads;

    int start_row = 0;
    for (int i = 0; i < num_threads; i++) {
        thread_data[i].A = A;
        thread_data[i].B = B;
        thread_data[i].C = C;
        thread_data[i].size = size;
        thread_data[i].start_row = start_row;

        // Distribute extra rows among the first few threads
        int end_row = start_row + rows_per_thread + (i < extra_rows ? 1 : 0);
        thread_data[i].end_row = end_row;

        start_row = end_row;

        // Create thread
        int rc = pthread_create(&threads[i], NULL, matrix_multiply_thread, (void *)&thread_data[i]);
        if (rc) {
            printf("Error: unable to create thread, %d\n", rc);
            exit(-1);
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("\nResult Matrix C:\n");
    print_matrix(C, size);

    // Free memory
    free_matrix(A, size);
    free_matrix(B, size);
    free_matrix(C, size);

    return 0;
}

