    for (int i = args->start_row; i < args->end_row; i++) {
        for (int j = 0; j < args->B_cols; j++) {
            args->C[i][j] = 0.0; // Initialize element
            for (int k = 0; k < args->A_cols; k++) {
                args->C[i][j] += args->A[i][k] * args->B[k][j];
            }
        }
    }

    pthread_exit(NULL);
}

