int main() {
    int A_rows, A_cols, B_cols; // Dimensions: A (A_rows x A_cols), B (A_cols x B_cols), C (A_rows x B_cols)
    int num_threads;

    printf("Enter dimensions for Matrix A (rows cols): ");
    if (scanf("%d %d", &A_rows, &A_cols) != 2 || A_rows <= 0 || A_cols <= 0) {
        fprintf(stderr, "Invalid dimensions for Matrix A.\n");
        return 1;
    }

    printf("Enter dimensions for Matrix B (cols only, rows will match A_cols): ");
    if (scanf("%d", &B_cols) != 1 || B_cols <= 0) {
        fprintf(stderr, "Invalid columns for Matrix B.\n");
        return 1;
    }

    printf("Enter number of threads: ");
    if (scanf("%d", &num_threads) != 1 || num_threads <= 0) {
        fprintf(stderr, "Invalid number of threads.\n");
        return 1;
    }

    if (num_threads > A_rows) {
        printf("Warning: Number of threads (%d) is greater than total rows in C (%d). Some threads will be idle.\n",
               num_threads, A_rows);
        num_threads = A_rows; // Cap threads at total rows
    }

    double **A, **B, **C;

    // Allocate matrices
    A = allocate_matrix(A_rows, A_cols);
    B = allocate_matrix(A_cols, B_cols); // B_rows == A_cols for multiplication
    C = allocate_matrix(A_rows, B_cols); // C_rows == A_rows, C_cols == B_cols

    if (!A || !B || !C) {
        fprintf(stderr, "Failed to allocate one or more matrices. Exiting.\n");
        if (A) free_matrix(A, A_rows);
        if (B) free_matrix(B, A_cols);
        if (C) free_matrix(C, A_rows);
        return 1;
    }

    // Initialize matrices A and B with random values
    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < A_rows; i++) {
        for (int j = 0; j < A_cols; j++) {
            A[i][j] = (double)rand() / RAND_MAX * 100.0; // Values between 0 and 100
        }
    }
    for (int i = 0; i < A_cols; i++) {
        for (int j = 0; j < B_cols; j++) {
            B[i][j] = (double)rand() / RAND_MAX * 100.0;
        }
    }

    // Print matrices (if small enough)
    // print_matrix(A, A_rows, A_cols, "A");
    // print_matrix(B, A_cols, B_cols, "B");

    pthread_t *threads = (pthread_t *)malloc(num_threads * sizeof(pthread_t));
    if (threads == NULL) {
        perror("Failed to allocate thread array");
        free_matrix(A, A_rows);
        free_matrix(B, A_cols);
        free_matrix(C, A_rows);
        return 1;
    }

    ThreadArgs *thread_args = (ThreadArgs *)malloc(num_threads * sizeof(ThreadArgs));
    if (thread_args == NULL) {
        perror("Failed to allocate thread args array");
        free(threads);
        free_matrix(A, A_rows);
        free_matrix(B, A_cols);
        free_matrix(C, A_rows);
        return 1;
    }

    struct timeval start_time, end_time;
    gettimeofday(&start_time, NULL); // Start timing

    int rows_per_thread = A_rows / num_threads;
    int remaining_rows = A_rows % num_threads;
    int current_row = 0;

    for (int i = 0; i < num_threads; i++) {
        thread_args[i].A = A;
        thread_args[i].B = B;
        thread_args[i].C = C;
        thread_args[i].A_rows = A_rows;
        thread_args[i].A_cols = A_cols;
        thread_args[i].B_cols = B_cols;
        thread_args[i].start_row = current_row;
        thread_args[i].end_row = current_row + rows_per_thread + (i < remaining_rows ? 1 : 0);

        if (pthread_create(&threads[i], NULL, matrix_multiply_thread, (void *)&thread_args[i]) != 0) {
            perror("Failed to create thread");
            // Attempt to join any threads already created before exiting
            for (int j = 0; j < i; j++) {
                pthread_join(threads[j], NULL);
            }
            free(threads);
            free(thread_args);
            free_matrix(A, A_rows);
            free_matrix(B, A_cols);
            free_matrix(C, A_rows);
            return 1;
        }
        current_row = thread_args[i].end_row;
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_threads; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            // Continue joining remaining threads, but an error occurred
        }
    }

    gettimeofday(&end_time, NULL); // End timing

    double elapsed_time = (end_time.tv_sec - start_time.tv_sec) +
                          (end_time.tv_usec - start_time.tv_usec) / 1000000.0;

    // print_matrix(C, A_rows, B_cols, "C"); // Print result matrix if small enough

    printf("\nMatrix multiplication complete.\n");
    printf("Matrices: A(%dx%d), B(%dx%d), C(%dx%d)\n", A_rows, A_cols, A_cols, B_cols, A_rows, B_cols);
    printf("Number of threads used: %d\n", num_threads);
    printf("Time taken: %f seconds\n", elapsed_time);

    // Free all allocated memory
    free(threads);
    free(thread_args);
    free_matrix(A, A_rows);
    free_matrix(B, A_cols);
    free_matrix(C, A_rows);

    return 0;
}

#include <stdio.h>
