// Structure to store data for each thread
typedef struct {
    int row;              // Row of result to compute
    int M, N, P;          // Matrix sizes
    int **A, **B, **C;    // Matrices
} ThreadData;

// Thread function to compute one row of C
void* multiply_row(void* arg) {
    ThreadData* data = (ThreadData*)arg;
    int i = data->row;
    for (int j = 0; j < data->P; ++j) {
        data->C[i][j] = 0;
        for (int k = 0; k < data->N; ++k) {
            data->C[i][j] += data->A[i][k] * data->B[k][j];
        }
    }
    pthread_exit(0);
}

