#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_SIZE 100 // Define maximum size for the matrix

// Structure to hold data passed to threads
typedef struct {
    int row;  // Row index of the output matrix
    int size; // Size of the matrices
    int (*a)[MAX_SIZE]; // Pointer to the first matrix
    int (*b)[MAX_SIZE]; // Pointer to the second matrix
    int (*result)[MAX_SIZE]; // Pointer to the result matrix
} ThreadData;

// Function for matrix multiplication
void *multiply(void *arg) {
    ThreadData *data = (ThreadData *)arg;
    int row = data->row;
    int size = data->size;
    int (*a)[MAX_SIZE] = data->a;
    int (*b)[MAX_SIZE] = data->b;
    int (*result)[MAX_SIZE] = data->result;

    for (int j = 0; j < size; j++) {
        result[row][j] = 0; // Initialize result cell
        for (int k = 0; k < size; k++) {
            result[row][j] += a[row][k] * b[k][j];
        }
    }
    return NULL;
}

int main() {
    int size;
    printf("Enter the size of matrices (n x n): ");
    scanf("%d", &size);

    // Declare matrices
    int a[MAX_SIZE][MAX_SIZE], b[MAX_SIZE][MAX_SIZE], result[MAX_SIZE][MAX_SIZE] = {0};

    // Input first matrix
    printf("Enter elements of first matrix:\n");
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            scanf("%d", &a[i][j]);
        }
    }

    // Input second matrix
