    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            scanf("%d", &b[i][j]);
        }
    }

    // Create an array of thread data
    pthread_t threads[size];
    ThreadData threadData[size];

    // Create threads for each row of the result
    for (int i = 0; i < size; i++) {
        threadData[i].row = i;
        threadData[i].size = size;
        threadData[i].a = a;
        threadData[i].b = b;
        threadData[i].result = result;
        pthread_create(&threads[i], NULL, multiply, (void *)&threadData[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < size; i++) {
        pthread_join(threads[i], NULL);
    }

    // Print the result matrix
