// Structure to pass arguments to threads
typedef struct {
    int row;
    int col;
    double **result;
    double **matrix1;
    double **matrix2;
    int n;
    int m;
    int p;
} ThreadArgs;

// Function to perform multiplication of a single element
void* multiply_element(void* args) {
    ThreadArgs* thread_args = (ThreadArgs*) args;
    int row = thread_args->row;
    int col = thread_args->col;
    double sum = 0.0;

    for (int i = 0; i < thread_args->n; i++) {
        sum += thread_args->matrix1[row][i] * thread_args->matrix2[i][col];
    }

    thread_args->result[row][col] = sum;

    free(args);
    return NULL;
}

// Function to perform matrix multiplication
void matrix_multiply(double **result, double **matrix1, double **matrix2, int m, int n, int p) {
    pthread_t* threads = (pthread_t*) malloc(m * p * sizeof(pthread_t));
    ThreadArgs* thread_args_array = (ThreadArgs*) malloc(m * p * sizeof(ThreadArgs));

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < p; j++) {
            thread_args_array[i * p + j].row = i;
            thread_args_array[i * p + j].col = j;
            thread_args_array[i * p + j].result = result;
            thread_args_array[i * p + j].matrix1 = matrix1;
            thread_args_array[i * p + j].matrix2 = matrix2;
            thread_args_array[i * p + j].n = n;
            thread_args_array[i * p + j].m = m;
            thread_args_array[i * p + j].p = p;

            pthread_create(&threads[i * p + j], NULL, multiply_element, &thread_args_array[i * p + j]);
        }
    }

    for (int i = 0; i < m * p; i++) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
    free(thread_args_array);
}

// Function to print a matrix
void print_matrix(double **matrix, int rows, int cols) {
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            printf("%.2f ", matrix[i][j]);
        }
        printf("\n");
    }
}

