#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Matrix dimensions
#define N 100  // Number of rows in matrix A and number of rows in result matrix C
#define M 100  // Number of columns in matrix A and number of rows in matrix B
#define P 100  // Number of columns in matrix B and number of columns in result matrix C

// Structure to pass data to threads
typedef struct {
    int start_row;
    int end_row;
    int *A;
    int *B;
    int *C;
} ThreadData;

// Function to multiply a row of A with all columns of B
void *matrix_multiply(void *arg) {
    ThreadData *data = (ThreadData *)arg;
    int start_row = data->start_row;
    int end_row = data->end_row;
    int *A = data->A;
    int *B = data->B;
    int *C = data->C;

    for (int i = start_row; i < end_row; i++) {
        for (int j = 0; j < P; j++) {
            int sum = 0;
            for (int k = 0; k < M; k++) {
                sum += A[i * M + k] * B[k * P + j];
            }
            C[i * P + j] = sum;
        }
    }

    pthread_exit(NULL);
}

int main() {
    // Initialize matrices
    int A[N][M];
    int B[M][P];
    int C[N][P];

    // Initialize random values for matrices A and B
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            A[i][j] = rand() % 100;
        }
    }
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < P; j++) {
            B[i][j] = rand() % 100;
        }
    }

    // Number of threads
    int num_threads = 4;  // Adjust this value as needed
    pthread_t threads[num_threads];
    ThreadData tdata[num_threads];

    // Calculate the number of rows each thread will handle
    int rows_per_thread = N / num_threads;
    int extra_rows = N % num_threads;

    for (int i = 0; i < num_threads; i++) {
        int start_row = i * rows_per_thread + (i < extra_rows ? i : extra_rows);
        int end_row = start_row + rows_per_thread + (i < extra_rows ? 1 : 0);

        tdata[i].start_row = start_row;
        tdata[i].end_row = end_row;
        tdata[i].A = (int *)A;
        tdata[i].B = (int *)B;
        tdata[i].C = (int *)C;

        pthread_create(&threads[i], NULL, matrix_multiply, (void *)&tdata[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Print the result matrix C
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < P; j++) {
            printf("%d ", C[i][j]);
        }
        printf("\n");
    }

    return 0;
}

#include <stdio.h>
