// Maximum matrix size
#define MAX_SIZE 1000

// Matrix structures
int matrixA[MAX_SIZE][MAX_SIZE];
int matrixB[MAX_SIZE][MAX_SIZE];
int resultMatrix[MAX_SIZE][MAX_SIZE];

// Thread arguments structure
typedef struct {
    int threadID;
    int numThreads;
    int matrixSize;
} ThreadArgs;

// Function to initialize matrices with random values
void initializeMatrices(int size) {
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            matrixA[i][j] = rand() % 10;
            matrixB[i][j] = rand() % 10;
        }
    }
}

// Function to print a matrix
void printMatrix(int matrix[MAX_SIZE][MAX_SIZE], int size) {
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            printf("%d ", matrix[i][j]);
        }
        printf("\n");
    }
}

// Thread function for matrix multiplication
void* multiplyMatrixThread(void* args) {
    ThreadArgs* threadArgs = (ThreadArgs*)args;
    int threadID = threadArgs->threadID;
    int numThreads = threadArgs->numThreads;
    int size = threadArgs->matrixSize;

    // Calculate row range for this thread
    int rowStart = threadID * (size / numThreads);
    int rowEnd = (threadID == numThreads - 1) ? size : rowStart + (size / numThreads);

    // Perform matrix multiplication for assigned rows
    for (int i = rowStart; i < rowEnd; i++) {
        for (int j = 0; j < size; j++) {
            resultMatrix[i][j] = 0;
            for (int k = 0; k < size; k++) {
                resultMatrix[i][j] += matrixA[i][k] * matrixB[k][j];
            }
        }
    }

    return NULL;
}

// Sequential matrix multiplication for verification
void sequentialMatrixMultiplication(int size) {
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            resultMatrix[i][j] = 0;
            for (int k = 0; k < size; k++) {
                resultMatrix[i][j] += matrixA[i][k] * matrixB[k][j];
            }
        }
    }
}

int main() {
    // Set random seed
    srand(time(NULL));

    // Matrix size and number of threads
    int matrixSize, numThreads;

    // Input matrix size and number of threads
    printf("Enter matrix size: ");
    scanf("%d", &matrixSize);
    printf("Enter number of threads: ");
    scanf("%d", &numThreads);

    // Validate input
    if (matrixSize <= 0 || matrixSize > MAX_SIZE || numThreads <= 0) {
        printf("Invalid input!\n");
        return 1;
    }

    // Initialize matrices
    initializeMatrices(matrixSize);

    // Create thread array
    pthread_t* threads = malloc(numThreads * sizeof(pthread_t));
    ThreadArgs* threadArgs = malloc(numThreads * sizeof(ThreadArgs));

    // Start timing for parallel multiplication
    clock_t parallelStart = clock();

    // Create threads for matrix multiplication
    for (int i = 0; i < numThreads; i++) {
        threadArgs[i].threadID = i;
        threadArgs[i].numThreads = numThreads;
        threadArgs[i].matrixSize = matrixSize;

        pthread_create(&threads[i], NULL, multiplyMatrixThread, &threadArgs[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < numThreads; i++) {
        pthread_join(threads[i], NULL);
    }

    // End timing for parallel multiplication
    clock_t parallelEnd = clock();
    double parallelTime = ((double)(parallelEnd - parallelStart)) / CLOCKS_PER_SEC;

    // Start timing for sequential multiplication
    clock_t sequentialStart = clock();
    sequentialMatrixMultiplication(matrixSize);
    clock_t sequentialEnd = clock();
    double sequentialTime = ((double)(sequentialEnd - sequentialStart)) / CLOCKS_PER_SEC;

    // Print performance comparison
    printf("\nPerformance Comparison:\n");
    printf("Parallel Multiplication Time: %.4f seconds\n", parallelTime);
    printf("Sequential Multiplication Time: %.4f seconds\n", sequentialTime);
    printf("Speedup: %.2fx\n", sequentialTime / parallelTime);

    // Optional: Print matrices for small sizes
    if (matrixSize <= 10) {
        printf("\nMatrix A:\n");
        printMatrix(matrixA, matrixSize);
        printf("\nMatrix B:\n");
        printMatrix(matrixB, matrixSize);
        printf("\nResult Matrix:\n");
        printMatrix(resultMatrix, matrixSize);
    }

    // Free dynamically allocated memory
    free(threads);
    free(threadArgs);

    return 0;
}

