    int **B = data->B;
    int **C = data->C;
    int row_start = data->row_start;
    int row_end = data->row_end;
    int cols_A = data->cols_A;
    int cols_B = data->cols_B;

    for (int i = row_start; i < row_end; i++) {
        for (int j = 0; j < cols_B; j++) {
            C[i][j] = 0;
            for (int k = 0; k < cols_A; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }

    pthread_exit(NULL);
}

