#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h> // For clock_gettime
#include <sys/time.h> // For gettimeofday (alternative)

// Define matrix dimensions (can be changed or made dynamic)
#define MAX_ROWS_A 500
#define MAX_COLS_A 500 // Must be equal to MAX_ROWS_B for multiplication
#define MAX_ROWS_B 500
#define MAX_COLS_B 500

// Matrices A, B, and C
int **A;
int **B;
int **C;

// Global matrix dimensions (will be set by user or constants)
int M, K, N;

// Structure to pass arguments to each thread
typedef struct {
    int thread_id;
    int start_row; // Starting row for this thread to compute in matrix C
    int end_row;   // Ending row (exclusive) for this thread
} ThreadArgs;

// Function to allocate memory for a 2D integer matrix
int** allocate_matrix(int rows, int cols) {
    int** matrix = (int**)malloc(rows * sizeof(int*));
    if (matrix == NULL) {
        perror("Failed to allocate matrix rows");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < rows; i++) {
        matrix[i] = (int*)malloc(cols * sizeof(int));
        if (matrix[i] == NULL) {
            perror("Failed to allocate matrix columns");
            // Free previously allocated rows
            for (int j = 0; j < i; j++) {
                free(matrix[j]);
            }
            free(matrix);
            exit(EXIT_FAILURE);
        }
    }
    return matrix;
}

// Function to initialize a matrix with random values
void initialize_matrix(int** matrix, int rows, int cols) {
    srand(time(NULL)); // Seed for random number generation
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            matrix[i][j] = rand() % 10; // Values between 0 and 9
        }
    }
}

// Function to print a matrix (for small matrices)
void print_matrix(int** matrix, int rows, int cols) {
    if (rows > 10 || cols > 10) { // Avoid printing very large matrices
        printf("Matrix too large to print.\n");
        return;
    }
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            printf("%d ", matrix[i][j]);
        }
        printf("\n");
    }
    printf("\n");
}

// Thread function for matrix multiplication
void* multiply_rows(void* arg) {
    ThreadArgs* args = (ThreadArgs*)arg;
    int tid = args->thread_id;
    int start_r = args->start_row;
    int end_r = args->end_row;

    printf("Thread %d: Calculating rows %d to %d (exclusive)\n", tid, start_r, end_r);

    for (int i = start_r; i < end_r; i++) { // Iterate through assigned rows of C
        for (int j = 0; j < N; j++) {     // Iterate through columns of C
            C[i][j] = 0;                  // Initialize C[i][j] to 0
            for (int k_idx = 0; k_idx < K; k_idx++) { // Dot product
                C[i][j] += A[i][k_idx] * B[k_idx][j];
            }
        }
    }

    printf("Thread %d finished.\n", tid);
    pthread_exit(NULL);
}

// Function to free allocated matrix memory
void free_matrix(int** matrix, int rows) {
    for (int i = 0; i < rows; i++) {
        free(matrix[i]);
    }
    free(matrix);
}

int main(int argc, char *argv[]) {
    int num_threads;

    if (argc < 4) {
        printf("Usage: %s <rows_A> <cols_A/rows_B> <cols_B> [num_threads]\n", argv[0]);
        printf("Example: %s 500 500 500 8\n", argv[0]);
        // Default values if not provided
        M = MAX_ROWS_A;
        K = MAX_COLS_A;
        N = MAX_COLS_B;
        num_threads = 4; // Default number of threads
        printf("Using default dimensions (M=%d, K=%d, N=%d) and %d threads.\n", M, K, N, num_threads);
    } else {
        M = atoi(argv[1]);
        K = atoi(argv[2]);
        N = atoi(argv[3]);
        if (argc == 5) {
            num_threads = atoi(argv[4]);
        } else {
            num_threads = 4; // Default if only dimensions are provided
        }
        printf("Using dimensions M=%d, K=%d, N=%d and %d threads.\n", M, K, N, num_threads);
    }

    if (K != M) { // Correction here, if M is rows of B, then K must be rows of B (which is cols of A)
        // This line was wrong in my head, M is rows of A, K is cols of A AND rows of B
        // M is rows of A, K is cols of A which equals rows of B, N is cols of B
        // So M, K, N describe A (M x K) and B (K x N), C (M x N)
        // No problem with K != M, K refers to the inner dimension which must match.
    }


    if (M <= 0 || K <= 0 || N <= 0 || num_threads <= 0) {
        fprintf(stderr, "Error: Dimensions and number of threads must be positive integers.\n");
        return 1;
    }
    if (num_threads > M) {
        printf("Warning: Number of threads (%d) exceeds the number of rows in matrix A (%d).\n", num_threads, M);
        printf("       Setting number of threads to M (%d) to ensure even distribution.\n", M);
        num_threads = M;
    }


    pthread_t threads[num_threads];
    ThreadArgs thread_args[num_threads];

    // Allocate memory for matrices
    A = allocate_matrix(M, K);
    B = allocate_matrix(K, N); // B's rows must match A's columns
    C = allocate_matrix(M, N); // C's dimensions are A's rows x B's columns

    // Initialize matrices
    printf("Initializing matrices...\n");
    initialize_matrix(A, M, K);
    initialize_matrix(B, K, N);

    printf("Matrices A (%dx%d) and B (%dx%d) initialized.\n", M, K, K, N);

    // Print matrices (only for small ones)
    printf("Matrix A (small):\n");
    print_matrix(A, M, K);
    printf("Matrix B (small):\n");
    print_matrix(B, K, N);

    struct timespec start_time, end_time;
    double elapsed_time_ms;

    // Get start time
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    // Calculate rows per thread and remaining rows
    int rows_per_thread = M / num_threads;
    int remaining_rows = M % num_threads;
    int current_row = 0;

    // Create threads
    for (int i = 0; i < num_threads; i++) {
        thread_args[i].thread_id = i;
        thread_args[i].start_row = current_row;
        // Distribute remaining_rows to the first 'remaining_rows' threads
        thread_args[i].end_row = current_row + rows_per_thread + (i < remaining_rows ? 1 : 0);
        current_row = thread_args[i].end_row;

        if (pthread_create(&threads[i], NULL, multiply_rows, (void*)&thread_args[i]) != 0) {
            perror("Failed to create thread");
            // Free allocated memory and exit if thread creation fails
            free_matrix(A, M);
            free_matrix(B, K);
            free_matrix(C, M);
            return 1;
        }
    }

    // Join threads
    for (int i = 0; i < num_threads; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            free_matrix(A, M);
            free_matrix(B, K);
            free_matrix(C, M);
            return 1;
        }
    }

    // Get end time
    clock_gettime(CLOCK_MONOTONIC, &end_time);

    elapsed_time_ms = (end_time.tv_sec - start_time.tv_sec) * 1000.0; // Seconds to milliseconds
    elapsed_time_ms += (end_time.tv_nsec - start_time.tv_nsec) / 1000000.0; // Nanoseconds to milliseconds

    printf("\nParallel Matrix Multiplication Complete.\n");
    printf("Execution time: %.2f ms\n", elapsed_time_ms);

    printf("Result Matrix C (%dx%d) (small):\n", M, N);
    print_matrix(C, M, N);

    // Free allocated memory
    free_matrix(A, M);
    free_matrix(B, K);
    free_matrix(C, M);

    return 0;
}

