// Structure to pass data to threads
typedef struct {
    int thread_id;
    int num_threads;
    int rows;
    int cols;
    double **matrix1;
    double **matrix2;
    double **result;
} thread_data;

// Function to calculate a portion of the result matrix
void* calculate_portion(void* arg) {
    thread_data* data = (thread_data*) arg;
    int thread_id = data->thread_id;
    int num_threads = data->num_threads;
    int rows = data->rows;
    int cols = data->cols;
    double **matrix1 = data->matrix1;
    double **matrix2 = data->matrix2;
    double **result = data->result;

    // Calculate the portion of the result matrix for this thread
    int start_row = (thread_id * rows) / num_threads;
    int end_row = ((thread_id + 1) * rows) / num_threads;

    for (int i = start_row; i < end_row; i++) {
        for (int j = 0; j < cols; j++) {
            result[i][j] = 0.0;
            for (int k = 0; k < rows; k++) {
                result[i][j] += matrix1[i][k] * matrix2[k][j];
            }
        }
    }

    return NULL;
}

// Function to multiply two matrices using pthreads
void matrix_multiply(double **matrix1, double **matrix2, double **result, int rows, int cols, int num_threads) {
    pthread_t* threads = (pthread_t*) malloc(num_threads * sizeof(pthread_t));
    thread_data* data = (thread_data*) malloc(num_threads * sizeof(thread_data));

    // Create threads
    for (int i = 0; i < num_threads; i++) {
        data[i].thread_id = i;
        data[i].num_threads = num_threads;
        data[i].rows = rows;
        data[i].cols = cols;
        data[i].matrix1 = matrix1;
        data[i].matrix2 = matrix2;
        data[i].result = result;

        pthread_create(&threads[i], NULL, calculate_portion, &data[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
    free(data);
}

