        return;
    }

    // Trim trailing whitespace
    int i = strlen(s) - 1;
    while (i >= 0 && isspace((unsigned char)s[i])) {
        s[i] = '\0';
        i--;
    }

    // Trim leading whitespace
    int j = 0;
    while (s[j] != '\0' && isspace((unsigned char)s[j])) {
