int main(int argc, char *argv[]) {
    // Check if the correct number of arguments is provided
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    FILE *input_file = NULL;
    FILE *temp_file = NULL;
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    int line_num = 0;

    // Open the input file for reading
    input_file = fopen(argv[1], "r");
    if (input_file == NULL) {
        perror("Error opening input file");
        return 1;
    }

    // Create a temporary file for writing processed content
    temp_file = tmpfile(); // tmpfile() creates a temporary file that is automatically deleted when closed
    if (temp_file == NULL) {
        perror("Error creating temporary file");
        fclose(input_file);
        return 1;
    }

    // Read the input file line by line
    while ((read = getline(&line, &len, input_file)) != -1) {
        line_num++;
        // Remove trailing newline character if present
        if (read > 0 && line[read - 1] == '\n') {
            line[read - 1] = '\0';
        }

        // Trim leading and trailing whitespace
        trim_whitespace(line);

        // If the line is not empty after trimming, write it to the temporary file
        if (strlen(line) > 0) {
            fprintf(temp_file, "%s\n", line);
        }
    }

    // Free the dynamically allocated line buffer
    if (line != NULL) {
        free(line);
        line = NULL; // Good practice to nullify after freeing
    }

    // Close the input file
    fclose(input_file);
    input_file = NULL;

    // Rewind the temporary file to the beginning
    rewind(temp_file);

    // Reopen the input file in write mode to overwrite it
    // Using "w" mode truncates the file, so we need to be careful.
    // It's safer to create a new file and then rename it, but for simplicity,
    // we'll overwrite the original.
    input_file = fopen(argv[1], "w");
    if (input_file == NULL) {
        perror("Error opening input file for writing");
        fclose(temp_file);
        return 1;
    }

    // Copy the content from the temporary file back to the original file
    char buffer[4096];
    size_t bytes_read;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), temp_file)) > 0) {
        fwrite(buffer, 1, bytes_read, input_file);
    }

    // Close both files
    fclose(input_file);
    fclose(temp_file);

    printf("Successfully processed file '%s'. Extra whitespace and empty lines removed.\n", argv[1]);

    return 0;
}

