void packet_handler(u_char *args, const struct pcap_pkthdr *header, const u_char *packet) {
    // Print packet timestamp
    printf("\nPacket Captured at: %s", ctime((const time_t *)&header->ts.tv_sec));
    printf("Packet Length: %d bytes\n", header->len);

    // Print Ethernet header
    print_ethernet_header(packet);

    // Check IP packet
    struct ether_header *eth_header = (struct ether_header *)packet;
    if (ntohs(eth_header->ether_type) == ETHERTYPE_IP) {
        print_ip_header(packet);

        // Get IP header
        struct ip *ip_header = (struct ip *)(packet + ETHER_HDR_LEN);

        // Check transport layer protocol
        switch (ip_header->ip_p) {
            case IPPROTO_TCP:
                print_tcp_header(packet);
                break;
            case IPPROTO_UDP:
                print_udp_header(packet);
                break;
            default:
                printf("Other transport layer protocol\n");
                break;
        }
    }
}

void print_ethernet_header(const u_char *packet) {
    struct ether_header *eth_header = (struct ether_header *)packet;

    printf("Ethernet Header:\n");
    printf("Source MAC: %02x:%02x:%02x:%02x:%02x:%02x\n",
           eth_header->ether_shost[0], eth_header->ether_shost[1],
           eth_header->ether_shost[2], eth_header->ether_shost[3],
           eth_header->ether_shost[4], eth_header->ether_shost[5]);
    printf("Destination MAC: %02x:%02x:%02x:%02x:%02x:%02x\n",
           eth_header->ether_dhost[0], eth_header->ether_dhost[1],
           eth_header->ether_dhost[2], eth_header->ether_dhost[3],
           eth_header->ether_dhost[4], eth_header->ether_dhost[5]);
}

void print_ip_header(const u_char *packet) {
    struct ip *ip_header = (struct ip *)(packet + ETHER_HDR_LEN);
    char src_ip[INET_ADDRSTRLEN];
    char dst_ip[INET_ADDRSTRLEN];

    inet_ntop(AF_INET, &(ip_header->ip_src), src_ip, INET_ADDRSTRLEN);
    inet_ntop(AF_INET, &(ip_header->ip_dst), dst_ip, INET_ADDRSTRLEN);

    printf("IP Header:\n");
    printf("Source IP: %s\n", src_ip);
    printf("Destination IP: %s\n", dst_ip);
    printf("Protocol: %d\n", ip_header->ip_p);
}

void print_tcp_header(const u_char *packet) {
    struct ip *ip_header = (struct ip *)(packet + ETHER_HDR_LEN);
    struct tcphdr *tcp_header = (struct tcphdr *)(packet + ETHER_HDR_LEN + (ip_header->ip_hl * 4));

    printf("TCP Header:\n");
    printf("Source Port: %d\n", ntohs(tcp_header->source));
    printf("Destination Port: %d\n", ntohs(tcp_header->dest));
}

void print_udp_header(const u_char *packet) {
    struct ip *ip_header = (struct ip *)(packet + ETHER_HDR_LEN);
    struct udphdr *udp_header = (struct udphdr *)(packet + ETHER_HDR_LEN + (ip_header->ip_hl * 4));

    printf("UDP Header:\n");
    printf("Source Port: %d\n", ntohs(udp_header->source));
    printf("Destination Port: %d\n", ntohs(udp_header->dest));
}

