void packet_handler(u_char *args, const struct pcap_pkthdr *header, const u_char *packet) {
    struct ether_header *eth_header;
    struct ip *ip_header;
    struct tcphdr *tcp_header;
    struct udphdr *udp_header;
    char src_ip[INET_ADDRSTRLEN];
    char dst_ip[INET_ADDRSTRLEN];
    int ip_header_len, tcp_header_len;
    u_int size_ip;
    u_int size_tcp;
    u_int size_payload;

    eth_header = (struct ether_header *)packet;

    // Check if this is an IP packet (Ethernet type 0x0800)
    if (ntohs(eth_header->ether_type) == ETHERTYPE_IP) {
        ip_header = (struct ip*)(packet + sizeof(struct ether_header));
        size_ip = ip_header->ip_hl * 4;

        inet_ntop(AF_INET, &(ip_header->ip_src), src_ip, INET_ADDRSTRLEN);
        inet_ntop(AF_INET, &(ip_header->ip_dst), dst_ip, INET_ADDRSTRLEN);

        printf("Packet captured (length: %d)\n", header->len);
        printf("Source IP: %s\n", src_ip);
        printf("Destination IP: %s\n", dst_ip);

        switch(ip_header->ip_p) {
            case IPPROTO_TCP:
                tcp_header = (struct tcphdr*)(packet + sizeof(struct ether_header) + size_ip);
                tcp_header_len = tcp_header->th_off * 4;

                printf("Protocol: TCP\n");
                printf("Source Port: %d\n", ntohs(tcp_header->th_sport));
                printf("Destination Port: %d\n", ntohs(tcp_header->th_dport));

                size_payload = ntohs(ip_header->ip_len) - (size_ip + tcp_header_len);
                if (size_payload > 0) {
                    printf("Payload size: %d bytes\n", size_payload);
                }
                break;

            case IPPROTO_UDP:
                udp_header = (struct udphdr*)(packet + sizeof(struct ether_header) + size_ip);

                printf("Protocol: UDP\n");
                printf("Source Port: %d\n", ntohs(udp_header->uh_sport));
                printf("Destination Port: %d\n", ntohs(udp_header->uh_dport));

                size_payload = ntohs(udp_header->uh_ulen) - sizeof(struct udphdr);
                if (size_payload > 0) {
                    printf("Payload size: %d bytes\n", size_payload);
                }
                break;

            case IPPROTO_ICMP:
                printf("Protocol: ICMP\n");
                break;

            default:
                printf("Protocol: Unknown (%d)\n", ip_header->ip_p);
                break;
        }

        printf("\n");
    }
}

