// Function to print MAC addresses
void print_mac(const unsigned char *mac_addr) {
    printf("%02x:%02x:%02x:%02x:%02x:%02x",
           mac_addr[0], mac_addr[1], mac_addr[2],
           mac_addr[3], mac_addr[4], mac_addr[5]);
}

// Callback function executed for each captured packet
void packet_handler(u_char *user_data, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    printf("\n--- Packet Captured (Length: %d) ---\n", pkthdr->len);

    // 1. Ethernet Header (14 bytes)
    struct ethhdr *eth_header = (struct ethhdr *)packet;
    printf("  Ethernet Header:\n");
    printf("    Source MAC: ");
    print_mac(eth_header->h_source);
    printf("\n");
    printf("    Destination MAC: ");
    print_mac(eth_header->h_dest);
    printf("\n");
    printf("    Type: 0x%04x ", ntohs(eth_header->h_proto));

    // Check if it's IP (0x0800)
    if (ntohs(eth_header->h_proto) == ETHERTYPE_IP) {
        printf("(IP)\n");

        // 2. IP Header
        // IP header starts right after Ethernet header
        struct iphdr *ip_header = (struct iphdr *)(packet + ETH_HLEN); // ETH_HLEN is 14 bytes

        unsigned int ip_header_len_bytes = ip_header->ihl * 4; // IHL is in 4-byte words

        printf("  IP Header:\n");
        printf("    Version: %d\n", ip_header->version);
        printf("    Header Length: %d bytes\n", ip_header_len_bytes);
        printf("    Source IP: %s\n", inet_ntoa(*(struct in_addr *)&ip_header->saddr));
        printf("    Destination IP: %s\n", inet_ntoa(*(struct in_addr *)&ip_header->daddr));
        printf("    Protocol: %d ", ip_header->protocol);

        // 3. TCP or UDP Header
        // Transport layer header starts after IP header
        u_char *transport_header_start = (u_char *)(packet + ETH_HLEN + ip_header_len_bytes);

        if (ip_header->protocol == IPPROTO_TCP) {
            printf("(TCP)\n");
            struct tcphdr *tcp_header = (struct tcphdr *)transport_header_start;
            printf("    TCP Header:\n");
            printf("      Source Port: %d\n", ntohs(tcp_header->source));
            printf("      Destination Port: %d\n", ntohs(tcp_header->dest));
            printf("      Flags: ");
            if (tcp_header->syn) printf("SYN ");
            if (tcp_header->ack) printf("ACK ");
            if (tcp_header->fin) printf("FIN ");
            if (tcp_header->rst) printf("RST ");
            if (tcp_header->psh) printf("PSH ");
            if (tcp_header->urg) printf("URG ");
            printf("\n");
            // You can add more TCP header parsing here (sequence number, ack number, window size, etc.)

        } else if (ip_header->protocol == IPPROTO_UDP) {
            printf("(UDP)\n");
            struct udphdr *udp_header = (struct udphdr *)transport_header_start;
            printf("    UDP Header:\n");
            printf("      Source Port: %d\n", ntohs(udp_header->source));
            printf("      Destination Port: %d\n", ntohs(udp_header->dest));
            printf("      Length: %d\n", ntohs(udp_header->len));

        } else if (ip_header->protocol == IPPROTO_ICMP) {
            printf("(ICMP)\n");
            // For ICMP, you'd parse the icmphdr struct here
        } else {
            printf("(Other)\n");
        }

    } else if (ntohs(eth_header->h_proto) == ETHERTYPE_ARP) {
        printf("(ARP)\n");
    } else {
        printf("(Unknown/Other)\n");
    }
}

int main(int argc, char *argv[]) {
    pcap_t *handle;                // Session handle
    char *dev;                     // The device to sniff on
    char errbuf[PCAP_ERRBUF_SIZE]; // Error string
    struct bpf_program fp;         // The compiled filter
    // char filter_exp[] = "port 80 or port 443"; // Example filter: HTTP/HTTPS traffic
    // char filter_exp[] = "src host 192.168.1.1 and tcp port 22"; // Example: SSH from specific host
    char filter_exp[] = "";        // No filter (capture all)
    bpf_u_int32 net;               // Our IP
    bpf_u_int32 mask;              // Our netmask

    // Determine the device
    if (argc == 2) {
        dev = argv[1]; // Use specified device
    } else {
        dev = pcap_lookupdev(errbuf); // Find a suitable device
        if (dev == NULL) {
            fprintf(stderr, "Couldn't find default device: %s\n", errbuf);
            return(2);
        }
    }

    printf("Sniffing on device: %s\n", dev);

    // Get network address and mask
    if (pcap_lookupnet(dev, &net, &mask, errbuf) == -1) {
        fprintf(stderr, "Couldn't get netmask for device %s: %s\n", dev, errbuf);
        net = 0;
        mask = 0;
    }

    // Open the session in promiscuous mode (0 for non-promiscuous)
    // 65535 is the snaplen (capture whole packet up to max Ethernet frame size)
    // 1000 is the timeout in milliseconds
    handle = pcap_open_live(dev, BUFSIZ, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Couldn't open device %s: %s\n", dev, errbuf);
        return(2);
    }

    // Make sure we're on an Ethernet device (important for parsing)
    if (pcap_datalink(handle) != DLT_EN10MB) {
        fprintf(stderr, "Device %s doesn't provide Ethernet headers - not supported by this program.\n", dev);
        return(2);
    }

    // Compile and apply the filter
    if (strcmp(filter_exp, "") != 0) {
        if (pcap_compile(handle, &fp, filter_exp, 0, net) == -1) {
            fprintf(stderr, "Couldn't parse filter %s: %s\n", filter_exp, pcap_geterr(handle));
            return(2);
        }

        if (pcap_setfilter(handle, &fp) == -1) {
            fprintf(stderr, "Couldn't install filter %s: %s\n", filter_exp, pcap_geterr(handle));
            return(2);
        }
        printf("Applied filter: \"%s\"\n", filter_exp);
    }

    printf("Starting packet capture. Press Ctrl+C to stop.\n");

    // Loop forever capturing packets
    // -1 means loop indefinitely
    // packet_handler is the callback function
    // NULL is user data passed to the callback (not used here)
    pcap_loop(handle, -1, packet_handler, NULL);

    // Cleanup
    pcap_freecode(&fp);
    pcap_close(handle);

    printf("\nCapture finished.\n");
    return(0);
}

