// Function to handle each captured packet
void packet_handler(u_char* arg, const struct pcap_pkthdr* header, const u_char* packet) {
    // Print packet details
    printf("Packet captured: ");
    printf("Length: %d bytes, Timestamp: %d.%d seconds\n", header->len, header->ts.tv_sec, header->ts.tv_usec);

    // Extract and print IP information
    struct ip_header {
        u_char  ver_len;
        u_char  tos;
        u_short tot_len;
        u_short id;
        u_short frag_off;
        u_char  ttl;
        u_char  proto;
        u_short check;
        u_int   src_ip;
        u_int   dst_ip;
    };
    struct ip_header* ip = (struct ip_header*)(packet + 14); // Skip Ethernet header
    printf("IP Source: %d.%d.%d.%d, Destination: %d.%d.%d.%d\n",
           (ip->src_ip >> 24) & 0xFF, (ip->src_ip >> 16) & 0xFF, (ip->src_ip >> 8) & 0xFF, ip->src_ip & 0xFF,
           (ip->dst_ip >> 24) & 0xFF, (ip->dst_ip >> 16) & 0xFF, (ip->dst_ip >> 8) & 0xFF, ip->dst_ip & 0xFF);

    // Extract and print TCP/UDP information (if applicable)
    if (ip->proto == 6) { // TCP
        struct tcp_header {
            u_short src_port;
            u_short dst_port;
            u_int   seq_num;
            u_int   ack_num;
            u_char  reserved:4;
            u_char  flags:4;
            u_char  window;
            u_char  check;
            u_char  urgent;
        };
        struct tcp_header* tcp = (struct tcp_header*)((char*)ip + sizeof(struct ip_header));
        printf("TCP Source Port: %d, Destination Port: %d\n", ntohs(tcp->src_port), ntohs(tcp->dst_port));
    } else if (ip->proto == 17) { // UDP
        struct udp_header {
            u_short src_port;
            u_short dst_port;
            u_short length;
