#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pcap.h>       // libpcap header
#include <netinet/if_ether.h> // For Ethernet header structure
#include <netinet/ip.h>     // For IP header structure
#include <netinet/tcp.h>    // For TCP header structure
#include <netinet/udp.h>    // For UDP header structure
#include <arpa/inet.h>      // For inet_ntoa

// Callback function for pcap_loop
void packet_handler(u_char *user_data, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    static int count = 1;
    printf("\n--- Packet #%d ---\n", count++);
    printf("Packet length: %d\n", pkthdr->len);
    printf("Capture length: %d (bytes captured)\n", pkthdr->caplen);
    printf("Timestamp: %ld.%06ld\n", pkthdr->ts.tv_sec, pkthdr->ts.tv_usec);

    // --- Ethernet Header ---
    int eth_header_len = sizeof(struct ethhdr);
    if (pkthdr->caplen < eth_header_len) {
        printf("Packet too short to contain full Ethernet header.\n");
        return;
    }
    struct ethhdr *ethernet = (struct ethhdr *)packet;

    printf("Source MAC: %02x:%02x:%02x:%02x:%02x:%02x\n",
           ethernet->h_source[0], ethernet->h_source[1], ethernet->h_source[2],
           ethernet->h_source[3], ethernet->h_source[4], ethernet->h_source[5]);
    printf("Destination MAC: %02x:%02x:%02x:%02x:%02x:%02x\n",
           ethernet->h_dest[0], ethernet->h_dest[1], ethernet->h_dest[2],
           ethernet->h_dest[3], ethernet->h_dest[4], ethernet->h_dest[5]);
    printf("Ethernet Type: 0x%04x\n", ntohs(ethernet->h_proto));

    // Check for IP (IPv4)
    if (ntohs(ethernet->h_proto) == ETHERTYPE_IP) {
        // --- IP Header ---
        int ip_header_len;
        if (pkthdr->caplen < eth_header_len + sizeof(struct iphdr)) {
            printf("Packet too short to contain full IP header.\n");
            return;
        }
        struct iphdr *ip = (struct iphdr *)(packet + eth_header_len);
        ip_header_len = ip->ihl * 4; // ip->ihl is in 32-bit words

        if (pkthdr->caplen < eth_header_len + ip_header_len) {
            printf("Packet too short for proclaimed IP header length.\n");
            return;
        }

        printf("IP Version: %d\n", ip->version);
        printf("IP Header Length: %d bytes\n", ip_header_len);
        printf("Source IP: %s\n", inet_ntoa(*(struct in_addr *)&ip->saddr));
        printf("Destination IP: %s\n", inet_ntoa(*(struct in_addr *)&ip->daddr));
        printf("Protocol: %d ", ip->protocol);

        // --- TCP/UDP Headers ---
        int total_headers_len = eth_header_len + ip_header_len;

        if (ip->protocol == IPPROTO_TCP) {
            printf("(TCP)\n");
            if (pkthdr->caplen < total_headers_len + sizeof(struct tcphdr)) {
                printf("Packet too short to contain full TCP header.\n");
                return;
            }
            struct tcphdr *tcp = (struct tcphdr *)(packet + total_headers_len);
            printf("Source Port: %d\n", ntohs(tcp->source));
            printf("Destination Port: %d\n", ntohs(tcp->dest));
            printf("TCP Header Length: %d bytes\n", tcp->doff * 4); // doff is in 32-bit words

        } else if (ip->protocol == IPPROTO_UDP) {
            printf("(UDP)\n");
            if (pkthdr->caplen < total_headers_len + sizeof(struct udphdr)) {
                printf("Packet too short to contain full UDP header.\n");
                return;
            }
            struct udphdr *udp = (struct udphdr *)(packet + total_headers_len);
            printf("Source Port: %d\n", ntohs(udp->source));
            printf("Destination Port: %d\n", ntohs(udp->dest));

        } else if (ip->protocol == IPPROTO_ICMP) {
            printf("(ICMP)\n");
            // You can add ICMP header parsing here if needed
        } else {
            printf("(Other IP Protocol)\n");
        }
    } else if (ntohs(ethernet->h_proto) == ETHERTYPE_ARP) {
        printf("ARP Packet\n");
    } else {
        printf("Non-IP/ARP packet (Ethernet Type: 0x%04x)\n", ntohs(ethernet->h_proto));
    }
}

int main(int argc, char *argv[]) {
    char *dev = "wlan0"; // Interface to capture from
    char errbuf[PCAP_ERRBUF_SIZE]; // Error buffer
    pcap_t *handle;                // Session handle
    int count = 0;                 // Number of packets to capture (0 for infinite)

    // Find a suitable device if `wlan0` is not available or you want to auto-detect
    // char *dev;
    // dev = pcap_lookupdev(errbuf);
    // if (dev == NULL) {
    //     fprintf(stderr, "Couldn't find default device: %s\n", errbuf);
    //     return(EXIT_FAILURE);
    // }
    // printf("Device: %s\n", dev);


    // Open the device for sniffing
    // Arguments:
    // - dev: the device name
    // - 65535: snaplen (maximum number of bytes to capture per packet). Max useful value is 65535.
    // - 1: promisc (1 for promiscuous mode, 0 for non-promiscuous)
    //        Promiscuous mode means capturing all packets seen on the network, not just those
    //        addressed to this machine. Essential for sniffing most traffic.
    // - 1000: to_ms (read timeout in milliseconds, 0 means no timeout)
    // - errbuf: error buffer
    handle = pcap_open_live(dev, 65535, 1, 1000, errbuf);

    if (handle == NULL) {
        fprintf(stderr, "Couldn't open device %s: %s\n", dev, errbuf);
        fprintf(stderr, "You might need 'sudo' or permissions to access network interfaces.\n");
        // Check if the device is `wlan0` and suggests monitor mode if applicable
        if (strcmp(dev, "wlan0") == 0) {
            fprintf(stderr, "For 'wlan0', you might also need to put it into monitor mode first.\n");
            fprintf(stderr, "  e.g., sudo airmon-ng start wlan0; then use the new monitor interface (e.g., wlan0mon)\n");
            fprintf(stderr, "  or sudo iwconfig wlan0 mode monitor\n");
        }
        return(EXIT_FAILURE);
    }

    // Ensure we're capturing Ethernet packets
    if (pcap_datalink(handle) != DLT_EN10MB) {
        fprintf(stderr, "Device %s doesn't provide Ethernet headers - some parsing may fail.\n", dev);
        // On some wireless interfaces, especially if not in monitor mode or certain drivers/firmware,
        // you might get DLT_IEEE802_11_RADIO or similar, which includes 802.11 headers.
        // Parsing those is more complex. For this simplified program, we assume Ethernet.
        // If you encounter this, you'll need to adapt the parsing of the initial header.
    }

    printf("Capturing packets on interface %s...\n", dev);
    printf("Press Ctrl+C to stop.\n");

    // Loop forever capturing packets, calling packet_handler for each
    // Arguments:
    // - handle: the session handle
    // - count: number of packets to capture (0 means infinite)
    // - packet_handler: callback function to process each packet
    // - user_data: pointer to user data passed to the callback (optional)
    pcap_loop(handle, count, packet_handler, NULL);

    // Close the capture device
    pcap_close(handle);

    printf("\nCapture finished.\n");

    return 0;
}

