/* Ethernet header */
struct ethheader {
    unsigned char  ether_dhost[6]; // Destination host address
    unsigned char  ether_shost[6]; // Source host address
    unsigned short ether_type;     // IP? ARP? RARP?
};

/* Print MAC address in readable format */
void print_mac(const unsigned char *mac) {
    printf("%02x:%02x:%02x:%02x:%02x:%02x",
           mac[0], mac[1], mac[2], mac[3], mac[4], mac[5]);
}

/* Callback function invoked by libpcap for every incoming packet */
void got_packet(u_char *args, const struct pcap_pkthdr *header, const u_char *packet) {
    struct ethheader *eth = (struct ethheader *)packet;
    time_t pkt_time = header->ts.tv_sec;
    struct tm *ltime = localtime(&pkt_time);
    char timestr[16];
    strftime(timestr, sizeof timestr, "%H:%M:%S", ltime);

    printf("\n=== Packet captured at %s ===\n", timestr);
    printf("Src MAC: ");
    print_mac(eth->ether_shost);
    printf(" -> Dest MAC: ");
    print_mac(eth->ether_dhost);
    printf("\nEthernet Type: 0x%04x", ntohs(eth->ether_type));
    printf("\nPacket length: %d bytes\n", header->len);
}

