// Structure to hold packet information
typedef struct {
    char src_ip[16];
    char dst_ip[16];
    int protocol;
    int src_port;
    int dst_port;
} packet_info;

// Function to analyze a packet
void analyze_packet(u_char* args, const struct pcap_pkthdr* header, const u_char* packet) {
    packet_info info;
    struct iphdr* ip_header = (struct iphdr*)(packet + 14); // 14 bytes for Ethernet header
    info.protocol = ip_header->protocol;

    // Extract source and destination IP addresses
    inet_ntop(AF_INET, &(ip_header->saddr), info.src_ip, sizeof(info.src_ip));
    inet_ntop(AF_INET, &(ip_header->daddr), info.dst_ip, sizeof(info.dst_ip));

    // Extract source and destination port numbers
    if (info.protocol == IPPROTO_TCP) {
        struct tcphdr* tcp_header = (struct tcphdr*)((char*)ip_header + (ip_header->ihl * 4));
        info.src_port = ntohs(tcp_header->source);
        info.dst_port = ntohs(tcp_header->dest);
    } else if (info.protocol == IPPROTO_UDP) {
        struct udphdr* udp_header = (struct udphdr*)((char*)ip_header + (ip_header->ihl * 4));
        info.src_port = ntohs(udp_header->source);
        info.dst_port = ntohs(udp_header->dest);
    }

    // Print packet information
    printf("Source IP: %s\n", info.src_ip);
    printf("Destination IP: %s\n", info.dst_ip);
    printf("Protocol: %d\n", info.protocol);
    if (info.protocol == IPPROTO_TCP || info.protocol == IPPROTO_UDP) {
        printf("Source Port: %d\n", info.src_port);
        printf("Destination Port: %d\n", info.dst_port);
    }
    printf("\n");
}

