    if (pcap == NULL) {
        fprintf(stderr, "Couldn't open device %s: %s\n", dev, errbuf);
        return 1;
    }

    // Start capturing packets
    printf("Capturing packets on interface %s...\n", dev);
    pcap_loop(pcap, 0, analyze_packet, NULL);

    // Close the pcap handle
    pcap_close(pcap);

    return 0;
}

#include <pcap.h>
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <arpa/inet.h>

void packet_handler(u_char *user_data, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    // Get the timestamp and packet length
    struct timespec ts = {
        .tv_sec = pkthdr->ts.tv_sec,
        .tv_nsec = pkthdr->ts.tv_usec * 1000
    };
    int packet_length = pkthdr->len;

    // Print packet information
    printf("Timestamp: %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
    printf("Packet length: %d\n", packet_length);

    // Print the first 60 bytes of the packet in hexadecimal
    for (int i = 0; i < 60 && i < packet_length; i++) {
        printf("%02x ", packet[i]);
        if ((i + 1) % 16 == 0) {
            printf("\n");
        }
    }
    printf("\n");
}

int main(int argc, char *argv[]) {
    char *dev = "wlan0";
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;
    struct bpf_program fp;
    char filter_exp[] = "ip";  // Filter for IP packets
    bpf_u_int32 net;

    // Open the device for capturing
    handle = pcap_open_live(dev, BUFSIZ, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Couldn't open device %s: %s\n", dev, errbuf);
        return(2);
    }

    // Compile and apply the filter
    if (pcap_compile(handle, &fp, filter_exp, 0, net) == -1) {
        fprintf(stderr, "Couldn't parse filter %s: %s\n", filter_exp, pcap_geterr(handle));
        return(2);
    }
    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "Couldn't install filter %s: %s\n", filter_exp, pcap_geterr(handle));
        return(2);
    }

    // Start the packet capture
    if (pcap_loop(handle, 0, packet_handler, NULL) == -1) {
        fprintf(stderr, "pcap_loop: %s\n", pcap_geterr(handle));
        return(2);
    }

    // Close the handle
    pcap_close(handle);

    return 0;
}

#include <stdio.h>
