// Function to convert string to lowercase
void toLowercase(char *str) {
    for (int i = 0; str[i]; i++) {
        str[i] = tolower(str[i]);
    }
}

// Function to remove punctuation from word
void removePunctuation(char *str) {
    int i, j;
    for (i = 0, j = 0; str[i] != '\0'; i++) {
        if (!ispunct(str[i])) {
            str[j++] = str[i];
        }
    }
    str[j] = '\0';
}

// Compare function for sorting word frequencies
int compareWordCount(const void *a, const void *b) {
    WordCount *wordA = (WordCount *)a;
    WordCount *wordB = (WordCount *)b;
    return wordB->frequency - wordA->frequency;
}

int main() {
    FILE *file;
    char filename[] = "data.txt";
    char word[MAX_WORD_LENGTH];
    WordCount wordCounts[MAX_WORDS];
    int uniqueWordCount = 0;
    int totalWordCount = 0;

    // Open file
    file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", filename);
        return 1;
    }

    // Initialize word counts
    for (int i = 0; i < MAX_WORDS; i++) {
        wordCounts[i].frequency = 0;
        wordCounts[i].word[0] = '\0';
    }

    // Read words from file
    while (fscanf(file, "%49s", word) == 1) {
        // Preprocess word
        toLowercase(word);
        removePunctuation(word);

        // Skip empty words
        if (strlen(word) == 0) continue;

        totalWordCount++;

        // Check if word already exists
        int found = 0;
        for (int i = 0; i < uniqueWordCount; i++) {
            if (strcmp(wordCounts[i].word, word) == 0) {
                wordCounts[i].frequency++;
                found = 1;
                break;
            }
        }

        // Add new word if not found
        if (!found && uniqueWordCount < MAX_WORDS) {
            strcpy(wordCounts[uniqueWordCount].word, word);
            wordCounts[uniqueWordCount].frequency = 1;
            uniqueWordCount++;
        }
    }

    // Close file
    fclose(file);

    // Sort words by frequency
    qsort(wordCounts, uniqueWordCount, sizeof(WordCount), compareWordCount);

    // Print analysis results
