#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_WORDS 1000
#define MAX_WORD_LENGTH 50

typedef struct {
    char word[MAX_WORD_LENGTH];
    int count;
} WordFrequency;

// Function to convert string to lowercase
void toLowercase(char *str) {
    for (int i = 0; str[i]; i++) {
        str[i] = tolower(str[i]);
    }
}

// Function to check if a character is a word character (letter or apostrophe)
int isWordChar(int c) {
    return isalpha(c) || c == '\'';
}

// Function to add or update word in the frequency list
void updateWordFrequency(WordFrequency *frequencies, int *uniqueCount, const char *word) {
    // Check if word already exists in the list
    for (int i = 0; i < *uniqueCount; i++) {
        if (strcmp(frequencies[i].word, word) == 0) {
            frequencies[i].count++;
            return;
        }
    }

    // Add new word if there's space
    if (*uniqueCount < MAX_WORDS) {
        strncpy(frequencies[*uniqueCount].word, word, MAX_WORD_LENGTH - 1);
        frequencies[*uniqueCount].word[MAX_WORD_LENGTH - 1] = '\0';
        frequencies[*uniqueCount].count = 1;
        (*uniqueCount)++;
    } else {
        fprintf(stderr, "Warning: Maximum number of unique words reached. Some words may not be counted.\n");
    }
}

// Comparison function for qsort (sort by frequency descending, then alphabetically)
int compareWordFrequency(const void *a, const void *b) {
    const WordFrequency *wa = (const WordFrequency *)a;
    const WordFrequency *wb = (const WordFrequency *)b;

    if (wb->count != wa->count) {
        return wb->count - wa->count;
    }
    return strcmp(wa->word, wb->word);
}

int main() {
    FILE *file;
    char filename[] = "data.txt";
    WordFrequency frequencies[MAX_WORDS];
    int uniqueCount = 0;

    // Initialize frequencies array
    memset(frequencies, 0, sizeof(frequencies));

    // Open the file
    file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return 1;
    }

    // Read words from file
    char word[MAX_WORD_LENGTH];
    int wordPos = 0;
    int c;

    while ((c = fgetc(file)) != EOF) {
        if (isWordChar(c)) {
            // Add character to current word
            if (wordPos < MAX_WORD_LENGTH - 1) {
                word[wordPos++] = tolower(c);
            }
        } else if (wordPos > 0) {
            // End of word found
            word[wordPos] = '\0';
            updateWordFrequency(frequencies, &uniqueCount, word);
            wordPos = 0;
        }
    }

    // Check for the last word in case file ends without delimiter
    if (wordPos > 0) {
        word[wordPos] = '\0';
        updateWordFrequency(frequencies, &uniqueCount, word);
    }

    // Close the file
    fclose(file);

    // Sort the frequencies
    qsort(frequencies, uniqueCount, sizeof(WordFrequency), compareWordFrequency);

    // Print the results
    printf("Word Frequency Analysis:\n");
    printf("=======================\n");
    printf("%-20s %s\n", "Word", "Frequency");
    printf("-------------------- -----\n");

    for (int i = 0; i < uniqueCount; i++) {
        printf("%-20s %5d\n", frequencies[i].word, frequencies[i].count);
    }

    printf("\nTotal unique words: %d\n", uniqueCount);

    return 0;
}

#include <stdio.h>    // For file I/O (fopen, fclose, printf, etc.)
#include <stdlib.h>   // For dynamic memory allocation (malloc, realloc, free)
#include <string.h>   // For string manipulation (strlen, strcpy, strcmp, strtok)
#include <ctype.h>    // For character classification and conversion (isalnum, tolower)

// --- Constants ---
#define INITIAL_CAPACITY 100 // Initial capacity for our word list
#define MAX_WORD_LENGTH 100  // Maximum length of a single word

// --- Data Structures ---

// Structure to hold a word and its frequency
typedef struct {
    char *word;
    int frequency;
} Word;

// Structure to manage a dynamic array of Word structs
typedef struct {
    Word *words;        // Pointer to the array of Word structs
    int count;          // Current number of words in the list
    int capacity;       // Current allocated capacity of the list
} WordList;

// --- Helper Functions ---

// Function to initialize a WordList
void init_word_list(WordList *list) {
    list->words = (Word *)malloc(INITIAL_CAPACITY * sizeof(Word));
    if (list->words == NULL) {
        perror("Failed to allocate initial memory for word list");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = INITIAL_CAPACITY;
}

// Function to normalize a word (lowercase, remove non-alphanumeric)
// Modifies the input string in place.
void normalize_word(char *word) {
    if (word == NULL) return;

    int i, j = 0;
    for (i = 0; word[i] != '\0'; i++) {
        if (isalnum((unsigned char)word[i])) { // Check if alphanumeric
            word[j++] = tolower((unsigned char)word[i]); // Convert to lowercase
        }
    }
    word[j] = '\0'; // Null-terminate the normalized word
}

// Function to find a word in the WordList
// Returns the index if found, -1 otherwise.
int find_word_index(const WordList *list, const char *target_word) {
    for (int i = 0; i < list->count; i++) {
        // Case-sensitive comparison, but our words are already normalized to lowercase
        if (strcmp(list->words[i].word, target_word) == 0) {
            return i;
        }
    }
    return -1; // Not found
}

// Function to add a word to the WordList or increment its frequency
void add_word_to_list(WordList *list, const char *new_word_str) {
    // Don't add empty strings after normalization
    if (new_word_str == NULL || strlen(new_word_str) == 0) {
        return;
    }

    int index = find_word_index(list, new_word_str);

    if (index != -1) {
        // Word found, increment frequency
        list->words[index].frequency++;
    } else {
        // Word not found, add new entry
        // Check if we need to resize the list
        if (list->count == list->capacity) {
            list->capacity *= 2; // Double the capacity
            list->words = (Word *)realloc(list->words, list->capacity * sizeof(Word));
            if (list->words == NULL) {
                perror("Failed to reallocate memory for word list");
                exit(EXIT_FAILURE);
            }
        }

        // Allocate memory for the new word string
        list->words[list->count].word = (char *)malloc((strlen(new_word_str) + 1) * sizeof(char));
        if (list->words[list->count].word == NULL) {
            perror("Failed to allocate memory for word string");
            exit(EXIT_FAILURE);
        }
        strcpy(list->words[list->count].word, new_word_str);
        list->words[list->count].frequency = 1;
        list->count++;
    }
}

// Function to print word frequencies
void print_word_frequencies(const WordList *list) {
    printf("\n--- Word Frequencies ---\n");
    if (list->count == 0) {
        printf("No words found or analyzed.\n");
        return;
    }
    for (int i = 0; i < list->count; i++) {
        printf("'%s': %d\n", list->words[i].word, list->words[i].frequency);
    }
}

// Function to free all dynamically allocated memory
void free_word_list(WordList *list) {
    if (list == NULL) return;

    for (int i = 0; i < list->count; i++) {
        free(list->words[i].word); // Free memory for each word string
    }
    free(list->words); // Free the array of Word structs
    list->words = NULL;
    list->count = 0;
    list->capacity = 0;
}

