// Remove leading & trailing punctuation from a word
void clean_word(char *word) {
    int start = 0, end = strlen(word) - 1;

    // Remove leading non-alphanumeric
    while (start <= end && !isalnum((unsigned char)word[start])) start++;
    // Remove trailing non-alphanumeric
    while (end >= start && !isalnum((unsigned char)word[end])) end--;

    if (start > end) {
        word[0] = '\0'; // word has no valid characters
        return;
    }
    memmove(word, word + start, end - start + 1);
    word[end - start + 1] = '\0';
}

