#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_WORD_LENGTH 100
#define HASH_TABLE_SIZE 1000

// Struct for each word and its count
typedef struct WordCount {
    char word[MAX_WORD_LENGTH];
    int count;
    struct WordCount* next;
} WordCount;

// Hash table for storing word counts
WordCount* hashTable[HASH_TABLE_SIZE];

// Simple hash function
unsigned int hash(const char* word) {
    unsigned int hash = 0;
    while (*word) {
        hash = (hash << 5) + *word++;
    }
    return hash % HASH_TABLE_SIZE;
}

// Function to add a word to the hash table
void addWord(const char* word) {
    unsigned int index = hash(word);
    WordCount* current = hashTable[index];

    // Check if the word already exists in the hash table
    while (current != NULL) {
        if (strcmp(current->word, word) == 0) {
            current->count++;
            return;
        }
        current = current->next;
    }

    // If the word is not found, create a new entry
    WordCount* newWordCount = (WordCount*)malloc(sizeof(WordCount));
    strcpy(newWordCount->word, word);
    newWordCount->count = 1;
    newWordCount->next = hashTable[index];
    hashTable[index] = newWordCount;
}

// Function to clean and split the text into words
void processFile(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open file");
        return;
    }

    char buffer[256];
    while (fscanf(file, "%255s", buffer) == 1) {
        // Convert to lowercase and strip punctuation
        for (int i = 0; buffer[i]; i++) {
            buffer[i] = tolower(buffer[i]);
        }

        // Strip punctuation from the edges of the word
        char* start = buffer;
        while (*start && ispunct(*start)) start++;

        char* end = start + strlen(start) - 1;
        while (end > start && ispunct(*end)) end--;

        *(end + 1) = '\0'; // Null-terminate the valid part

        if (strlen(start) > 0) {
            addWord(start);
        }
    }

    fclose(file);
}

// Function to print the word frequency
void printWordFrequency() {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        WordCount* current = hashTable[i];
        while (current != NULL) {
            printf("%s: %d\n", current->word, current->count);
            current = current->next;
        }
    }
}

int main() {
    processFile("data.txt");
    printWordFrequency();

    // Free allocated memory
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        WordCount* current = hashTable[i];
        while (current != NULL) {
            WordCount* toDelete = current;
            current = current->next;
            free(toDelete);
        }
    }

    return 0;
}

