    return hash_value;
}

// Function to add or update a word in the hash table
void add_word(Node *hash_table[], const char *word) {
    int index = hash(word);
    Node *current = hash_table[index];

    while (current != NULL) {
        if (strcmp(current->word, word) == 0) {
            current->count++;
            return;
        }
        current = current->next;
    }

    // Word not found, create a new node
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    strcpy(new_node->word, word);
    new_node->count = 1;
    new_node->next = hash_table[index];
    hash_table[index] = new_node;
}

// Function to free the memory used by the hash table
void free_hash_table(Node *hash_table[]) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        Node *current = hash_table[i];
        while (current != NULL) {
            Node *temp = current;
            current = current->next;
            free(temp);
        }
    }
}

// Function to print the word frequencies
void print_frequencies(Node *hash_table[]) {
    printf("Word Frequency Analysis:\n");
    for (int i = 0; i < TABLE_SIZE; i++) {
        Node *current = hash_table[i];
        while (current != NULL) {
            printf("%s: %d\n", current->word, current->count);
            current = current->next;
        }
    }
}

// Function to read words from a file and process them
void process_file(const char *filename, Node *hash_table[]) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        exit(1);
    }

    char word[MAX_WORD_LENGTH];
    while (fscanf(file, "%99s", word) != EOF) {
        // Convert word to lowercase
        for (int i = 0; word[i] != '\0'; i++) {
            word[i] = tolower(word[i]);
        }

        // Remove punctuation from the end of the word
        int len = strlen(word);
        while (len > 0 && ispunct(word[len - 1])) {
            word[len - 1] = '\0';
            len--;
        }

        // Add the word to the hash table
        add_word(hash_table, word);
    }

    fclose(file);
}

int main() {
    Node *hash_table[TABLE_SIZE] = {NULL};

    process_file("data.txt", hash_table);

    print_frequencies(hash_table);

    free_hash_table(hash_table);

    return 0;
}

