#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h> // For tolower() and isalpha()

// Max length for a word
#define MAX_WORD_LEN 100
// Initial capacity for our word list (will be resized if needed)
#define INITIAL_MAP_CAPACITY 100

// Structure to store a word and its frequency
typedef struct {
    char word[MAX_WORD_LEN];
    int frequency;
} WordEntry;

// Structure to manage our dynamic array of WordEntry (our "hash map" substitute)
typedef struct {
    WordEntry *entries;
    int count;      // Number of unique words found
    int capacity;   // Current allocated capacity
} WordMap;

// Function to initialize a WordMap
void initWordMap(WordMap *map) {
    map->count = 0;
    map->capacity = INITIAL_MAP_CAPACITY;
    map->entries = (WordEntry *)malloc(map->capacity * sizeof(WordEntry));
    if (map->entries == NULL) {
        perror("Failed to allocate memory for WordMap");
        exit(EXIT_FAILURE);
    }
}

// Function to resize the WordMap
void resizeWordMap(WordMap *map) {
    map->capacity *= 2;
    map->entries = (WordEntry *)realloc(map->entries, map->capacity * sizeof(WordEntry));
    if (map->entries == NULL) {
        perror("Failed to reallocate memory for WordMap");
        exit(EXIT_FAILURE);
    }
}

// Function to add or update a word in the WordMap
void addWord(WordMap *map, const char *word) {
    // Convert word to lowercase for case-insensitive counting
    char lowerWord[MAX_WORD_LEN];
    int len = strlen(word);
    if (len >= MAX_WORD_LEN) { // Handle words too long
        len = MAX_WORD_LEN - 1;
    }
    for (int i = 0; i < len; i++) {
        lowerWord[i] = tolower((unsigned char)word[i]);
    }
    lowerWord[len] = '\0';

    // Search for the word in our map
    for (int i = 0; i < map->count; i++) {
        if (strcmp(map->entries[i].word, lowerWord) == 0) {
            map->entries[i].frequency++;
            return; // Word found, frequency updated
        }
    }

    // Word not found, add new entry
    if (map->count == map->capacity) {
        resizeWordMap(map);
    }

    strcpy(map->entries[map->count].word, lowerWord);
    map->entries[map->count].frequency = 1;
    map->count++;
}

// Comparison function for qsort (descending frequency, then ascending word)
int compareWordEntries(const void *a, const void *b) {
    WordEntry *entryA = (WordEntry *)a;
    WordEntry *entryB = (WordEntry *)b;

    if (entryA->frequency != entryB->frequency) {
        return entryB->frequency - entryA->frequency; // Descending frequency
    }
    return strcmp(entryA->word, entryB->word); // Ascending word for tie-breaking
}

int main() {
    FILE *file;
    char filename[100];
    char line[1024]; // Max line length for reading, adjust if needed
    WordMap wordMap;
    initWordMap(&wordMap);

    printf("Enter the name of the CSV/text file (e.g., dataset.csv): ");
    scanf("%s", filename);

    file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    printf("Analyzing file...\n");

    // Read file line by line
    while (fgets(line, sizeof(line), file) != NULL) {
        char *token;
        // Simple tokenization: Split by non-alphanumeric characters.
        // This is a basic approach. More robust parsing is needed for complex CSVs.
        // For CSVs, you might first strtok by ',' to get column values,
        // then analyze each column. For this generic example, we'll just scan the whole line.

        char *ptr = line;
        char wordBuffer[MAX_WORD_LEN];
        int i = 0;

        while (*ptr != '\0') {
            if (isalpha((unsigned char)*ptr)) {
                // Collect characters of a word
                if (i < MAX_WORD_LEN - 1) {
                    wordBuffer[i++] = *ptr;
                }
            } else {
                // End of a word or non-alphabetic character
                if (i > 0) {
                    wordBuffer[i] = '\0';
                    addWord(&wordMap, wordBuffer);
                    i = 0; // Reset buffer index for next word
                }
            }
            ptr++;
        }
        // Handle last word in line if it ends without a non-alpha char
        if (i > 0) {
            wordBuffer[i] = '\0';
            addWord(&wordMap, wordBuffer);
        }
    }

    fclose(file);

    printf("\nAnalysis Complete. Sorting results...\n");

    // Sort the word entries
    qsort(wordMap.entries, wordMap.count, sizeof(WordEntry), compareWordEntries);

    printf("\nWord Frequency Analysis:\n");
    printf("------------------------\n");
    for (int i = 0; i < wordMap.count; i++) {
        printf("%-20s : %d\n", wordMap.entries[i].word, wordMap.entries[i].frequency);
    }
    printf("------------------------\n");
    printf("Total unique words: %d\n", wordMap.count);

    // Free allocated memory
    free(wordMap.entries);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_WORD_LEN 100
#define MAX_LINE_LEN 1024
#define HASH_SIZE 10007

typedef struct WordNode {
    char *word;
    int count;
    struct WordNode *next;
} WordNode;

// Hash function for string
unsigned int hash(const char *str) {
    unsigned int h = 0;
    while (*str)
        h = (h * 31) + tolower(*str++);
    return h % HASH_SIZE;
}

// Convert string to lowercase
void to_lowercase(char *str) {
    while (*str) {
        *str = tolower(*str);
        str++;
    }
}

// Insert or update word in hash table
void insert_word(WordNode *table[], const char *word) {
    unsigned int idx = hash(word);
    WordNode *node = table[idx];
    while (node) {
        if (strcmp(node->word, word) == 0) {
            node->count++;
            return;
        }
        node = node->next;
    }
    // New word
    node = malloc(sizeof(WordNode));
    node->word = strdup(word);
    node->count = 1;
    node->next = table[idx];
    table[idx] = node;
}

// Free hash table memory
void free_table(WordNode *table[]) {
    for (int i = 0; i < HASH_SIZE; i++) {
        WordNode *node = table[i];
        while (node) {
            WordNode *tmp = node;
            node = node->next;
            free(tmp->word);
            free(tmp);
        }
    }
}

int main() {
    FILE *fp = fopen("dataset.csv", "r");
    if (!fp) {
        printf("Failed to open dataset.csv\n");
        return 1;
    }

    WordNode *table[HASH_SIZE] = {0};
    char line[MAX_LINE_LEN];

    while (fgets(line, sizeof(line), fp)) {
        char *token = strtok(line, " ,.\t\r\n\""); // Add delimiters as required
        while (token != NULL) {
            char word[MAX_WORD_LEN];
            strncpy(word, token, MAX_WORD_LEN - 1);
            word[MAX_WORD_LEN - 1] = '\0';
            to_lowercase(word);
            insert_word(table, word);
            token = strtok(NULL, " ,.\t\r\n\"");
        }
    }

    fclose(fp);

    // Print word frequencies
    printf("Word Frequency:\n");
    for (int i = 0; i < HASH_SIZE; i++) {
        WordNode *node = table[i];
        while (node) {
            printf("%s : %d\n", node->word, node->count);
            node = node->next;
        }
    }

    free_table(table);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define BUFFER_SIZE 1024
#define MAX_WORD_LENGTH 100
#define INITIAL_CAPACITY 100

typedef struct {
    char word[MAX_WORD_LENGTH];
    int count;
} WordFreq;

void to_lower_and_remove_punctuation(char *str) {
    char *src = str, *dst = str;
    while (*src) {
        if (ispunct((unsigned char)*src)) {
            src++;
        } else if (isupper((unsigned char)*src)) {
            *dst++ = tolower((unsigned char)*src++);
        } else if (islower((unsigned char)*src) || isdigit((unsigned char)*src)) {
            *dst++ = *src++;
        } else {
            src++;
        }
    }
    *dst = '\0';
}

int find_word(WordFreq *words, int size, const char *word) {
    for (int i = 0; i < size; i++) {
        if (strcmp(words[i].word, word) == 0) {
            return i;
        }
    }
    return -1;
}

void add_word(WordFreq **words, int *size, int *capacity, const char *word) {
    if (*size >= *capacity) {
        *capacity *= 2;
        *words = realloc(*words, sizeof(WordFreq) * (*capacity));
    }
    strcpy((*words)[*size].word, word);
    (*words)[*size].count = 1;
    (*size)++;
}

void update_word_frequency(WordFreq **words, int *size, int *capacity, const char *word) {
    int index = find_word(*words, *size, word);
    if (index >= 0) {
        (*words)[index].count++;
    } else {
        add_word(words, size, capacity, word);
    }
}

void print_word_frequencies(WordFreq *words, int size) {
    for (int i = 0; i < size; i++) {
        printf("%s: %d\n", words[i].word, words[i].count);
    }
}

int main() {
    FILE *file = fopen("dataset.csv", "r");
    if (!file) {
        perror("Could not open file");
        return EXIT_FAILURE;
    }

    WordFreq *words = malloc(sizeof(WordFreq) * INITIAL_CAPACITY);
    int size = 0;
    int capacity = INITIAL_CAPACITY;

    char buffer[BUFFER_SIZE];
    char *token;
    const char delimiters[] = " ,\n";

    while (fgets(buffer, BUFFER_SIZE, file)) {
        token = strtok(buffer, delimiters);
        while (token) {
            to_lower_and_remove_punctuation(token);
            if (strlen(token) > 0) {
                update_word_frequency(&words, &size, &capacity, token);
            }
            token = strtok(NULL, delimiters);
        }
    }

    fclose(file);
    print_word_frequencies(words, size);

    free(words);
    return EXIT_SUCCESS;
}

