} WordFrequency;

int is_word_char(char c) {
    return isalpha(c) || c == '\'' || c == '-';
}

int is_valid_word(char *word) {
    return strlen(word) > 0;
}

void to_lowercase(char *word) {
    for (int i = 0; word[i]; i++) {
        word[i] = tolower(word[i]);
    }
}

void add_word(WordFrequency *frequencies, int *size, const char *word) {
    for (int i = 0; i < *size; i++) {
        if (strcmp(frequencies[i].word, word) == 0) {
            frequencies[i].count++;
            return;
        }
    }

    strcpy(frequencies[*size].word, word);
    frequencies[*size].count = 1;
    (*size)++;
}

void process_line(const char *line, WordFrequency *frequencies, int *size) {
    char word[MAX_WORD_LENGTH];
    int word_len = 0;

    for (int i = 0; line[i] != '\0'; i++) {
        if (is_word_char(line[i])) {
            // Collecting a word
            if (word_len < MAX_WORD_LENGTH - 1) {
                word[word_len++] = line[i];
            }
        } else {
            // If we hit a non-word character, finalize the word
            if (word_len > 0) {
                word[word_len] = '\0'; // Null terminate
                to_lowercase(word);
                if (is_valid_word(word)) {
                    add_word(frequencies, size, word);
                }
                word_len = 0; // Reset for the next word
            }
        }
    }
    // Check for the last word at the end of the line
    if (word_len > 0) {
        word[word_len] = '\0';
        to_lowercase(word);
        if (is_valid_word(word)) {
            add_word(frequencies, size, word);
        }
    }
}

void print_word_frequencies(WordFrequency *frequencies, int size) {
    for (int i = 0; i < size; i++) {
        printf("%s: %d\n", frequencies[i].word, frequencies[i].count);
    }
}

