}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define HASH_TABLE_SIZE 10000
#define WORD_LENGTH 100

// Structure to represent a word and its frequency
typedef struct WordFrequency {
    char word[WORD_LENGTH];
    int frequency;
} WordFrequency;

// Hash table to store word frequencies
WordFrequency hashTable[HASH_TABLE_SIZE];

// Function to create a hash from a word
unsigned int hashFunction(const char *word) {
    unsigned int hash = 0;
    while (*word) {
        hash = hash * 31 + *word;
        word++;
    }
    return hash % HASH_TABLE_SIZE;
}

// Initialize hash table
void initializeHashTable() {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        hashTable[i].frequency = 0;
        hashTable[i].word[0] = '\0';
    }
}

// Function to insert or update word frequency in the hash table
void insertIntoHashTable(const char *word) {
    unsigned int hash = hashFunction(word);
    // Check if the word is already in the table
    if (strcmp(hashTable[hash].word, word) == 0) {
        // If the word is already present, increment its frequency
        hashTable[hash].frequency++;
    } else if (hashTable[hash].word[0] == '\0') {
        // If the slot is empty, insert the word and set its frequency to 1
        strcpy(hashTable[hash].word, word);
        hashTable[hash].frequency = 1;
    } else {
        // Handle collisions (simple linear probing)
        int index = (hash + 1) % HASH_TABLE_SIZE;
        while (index!= hash) {
            if (strcmp(hashTable[index].word, word) == 0) {
                hashTable[index].frequency++;
                return;
            } else if (hashTable[index].word[0] == '\0') {
                strcpy(hashTable[index].word, word);
                hashTable[index].frequency = 1;
                return;
            }
            index = (index + 1) % HASH_TABLE_SIZE;
        }
        // If the hash table is full and we've reached the starting point again, handle the error
        printf("Error: Hash table is full. Cannot insert word '%s'.\n", word);
    }
}

// Function to print the word frequencies
void printFrequencies() {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        if (hashTable[i].word[0]!= '\0') {
            printf("Word: %s, Frequency: %d\n", hashTable[i].word, hashTable[i].frequency);
        }
    }
}

int main() {
    FILE *file;
    char filename[] = "dataset.txt"; // Change to your text file
    char word[WORD_LENGTH];

    initializeHashTable();

    file = fopen(filename, "r");
    if (file == NULL) {
        printf("Could not open file %s.\n", filename);
        return 1;
    }

    while (fscanf(file, "%s", word) == 1) {
        // Convert word to lowercase to treat "Word" and "word" as the same word
        for (int i = 0; i < strlen(word); i++) {
            word[i] = tolower(word[i]);
        }
        insertIntoHashTable(word);
    }

    fclose(file);

    printFrequencies();

    return 0;
}

