    }
}

// Function to remove punctuation from word
void removePunctuation(char *str) {
    int i, j;
    for (i = 0, j = 0; str[i] != '\0'; i++) {
        if (!ispunct(str[i])) {
            str[j++] = str[i];
        }
    }
    str[j] = '\0';
}

// Function to find word in array
int findWord(WordFrequency words[], int count, const char *word) {
    for (int i = 0; i < count; i++) {
        if (strcmp(words[i].word, word) == 0) {
            return i;
        }
    }
    return -1;
}

// Function to analyze word frequency
void analyzeWordFrequency(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", filename);
        return;
    }

    WordFrequency words[MAX_WORDS] = {0};
    int wordCount = 0;
    char word[MAX_WORD_LENGTH];

    // Read words from file
    while (fscanf(file, "%49s", word) == 1) {
        // Preprocess word
        toLowerCase(word);
        removePunctuation(word);

        // Skip empty words
        if (strlen(word) == 0) continue;

        // Find word in array
        int index = findWord(words, wordCount, word);

        // Add or increment word frequency
        if (index != -1) {
            words[index].count++;
        } else if (wordCount < MAX_WORDS) {
            strcpy(words[wordCount].word, word);
            words[wordCount].count = 1;
            wordCount++;
        }
    }

    fclose(file);

    // Sort words by frequency (descending)
    for (int i = 0; i < wordCount - 1; i++) {
        for (int j = 0; j < wordCount - i - 1; j++) {
            if (words[j].count < words[j + 1].count) {
                WordFrequency temp = words[j];
                words[j] = words[j + 1];
                words[j + 1] = temp;
            }
        }
    }

    // Print word frequencies
    printf("Word Frequency Analysis:\n");
    printf("--------------------\n");
    for (int i = 0; i < wordCount; i++) {
        printf("%s: %d\n", words[i].word, words[i].count);
    }
}

