// Define a structure for a word and its frequency
typedef struct WordFrequency {
    char *word;
    int frequency;
    struct WordFrequency *next; // For linked list
} WordFrequency;

// Function to create a new WordFrequency node
WordFrequency *createWordNode(const char *word) {
    WordFrequency *newNode = (WordFrequency *)malloc(sizeof(WordFrequency));
    if (newNode == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    newNode->word = strdup(word); // Duplicate the string
    if (newNode->word == NULL) {
        perror("Memory allocation for word failed");
        free(newNode);
        exit(EXIT_FAILURE);
    }
    newNode->frequency = 1;
    newNode->next = NULL;
    return newNode;
}

// Function to add or update a word in the frequency list
void addOrUpdateWord(WordFrequency **head, const char *word) {
    WordFrequency *current = *head;
    while (current != NULL) {
        if (strcmp(current->word, word) == 0) {
            current->frequency++;
            return;
        }
        current = current->next;
    }
    // Word not found, add it to the beginning of the list
    WordFrequency *newNode = createWordNode(word);
    newNode->next = *head;
    *head = newNode;
}

// Function to free the memory allocated for the word frequency list
void freeWordList(WordFrequency *head) {
    WordFrequency *current = head;
    while (current != NULL) {
        WordFrequency *temp = current;
        free(current->word); // Free the duplicated string
        current = current->next;
        free(temp); // Free the node
    }
}

// Function to tokenize and process the log file
void analyzeWordFrequency(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    WordFrequency *wordList = NULL;
    char buffer[256]; // Buffer to read words (adjust size if needed)
    int c;
    int buffer_pos = 0;

    while ((c = fgetc(file)) != EOF) {
        if (isalnum(c)) { // Check if it's an alphanumeric character
            if (buffer_pos < sizeof(buffer) - 1) { // Avoid buffer overflow
                buffer[buffer_pos++] = tolower(c); // Convert to lowercase
            }
        } else {
            if (buffer_pos > 0) { // If a word was collected
                buffer[buffer_pos] = '\0'; // Null-terminate the word
                addOrUpdateWord(&wordList, buffer);
                buffer_pos = 0; // Reset buffer position
            }
        }
    }

    // Process any remaining word in the buffer after EOF
    if (buffer_pos > 0) {
        buffer[buffer_pos] = '\0';
        addOrUpdateWord(&wordList, buffer);
    }

    fclose(file);

    // Print the word frequencies
    printf("Word Frequencies in '%s':\n", filename);
    printf("----------------------------------\n");
    WordFrequency *current = wordList;
    while (current != NULL) {
        printf("Word: %-20s Frequency: %d\n", current->word, current->frequency);
        current = current->next;
    }
    printf("----------------------------------\n");

    // Free allocated memory
    freeWordList(wordList);
}

