#define MAX_WORD_LEN 128
#define HASH_TABLE_SIZE 10007 // A prime number for better distribution

typedef struct Node {
    char word[MAX_WORD_LEN];
    int count;
    struct Node *next;
} Node;

Node* hash_table[HASH_TABLE_SIZE] = { NULL };

// Simple case-insensitive hash function
unsigned int hash(const char *word) {
    unsigned int h = 0;
    while (*word) {
        h = h * 31 + tolower(*word);
        word++;
    }
    return h % HASH_TABLE_SIZE;
}

void insert_word(const char *word) {
    unsigned int idx = hash(word);
    Node *curr = hash_table[idx];
    while (curr) {
        if (strcasecmp(curr->word, word) == 0) {
            curr->count++;
            return;
        }
        curr = curr->next;
    }
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Out of memory!\n");
        exit(1);
    }
    strncpy(new_node->word, word, MAX_WORD_LEN);
    new_node->word[MAX_WORD_LEN-1] = '\0';
    new_node->count = 1;
    new_node->next = hash_table[idx];
    hash_table[idx] = new_node;
}

void free_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        Node *curr = hash_table[i];
        while (curr) {
            Node *tmp = curr;
            curr = curr->next;
            free(tmp);
        }
        hash_table[i] = NULL;
    }
}

void print_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        Node *curr = hash_table[i];
        while (curr) {
            printf("%s: %d\n", curr->word, curr->count);
            curr = curr->next;
        }
    }
}

