    if (!fp) {
        perror("input.log");
        return 1;
    }

    char word[MAX_WORD_LEN];
    int c, idx = 0;

    while ((c = fgetc(fp)) != EOF) {
        if (isalnum(c) || c == '_') {
            if (idx < MAX_WORD_LEN - 1) {
                word[idx++] = (char)c;
            }
        } else {
            if (idx > 0) {
                word[idx] = '\0';
                // Convert to lowercase
                for (int i = 0; word[i]; i++) word[i] = tolower((unsigned char)word[i]);
                insert_word(word);
                idx = 0;
            }
        }
    }
    // If file ended and a word remains
    if (idx > 0) {
        word[idx] = '\0';
        for (int i = 0; word[i]; i++) word[i] = tolower((unsigned char)word[i]);
        insert_word(word);
    }

    fclose(fp);

    print_table();
    free_table();
