// Define a struct to hold word frequency information
typedef struct {
    char *word;
    int count;
} WordFrequency;

// Function to check and add word to the frequency table
void addWord(WordFrequency **words, int *size, int *capacity, const char *word) {
    // Search for the word in the current list
    for (int i = 0; i < *size; ++i) {
        if (strcmp((*words)[i].word, word) == 0) {
            (*words)[i].count++;
            return;
        }
    }

    // If the word is not found, add it to the list
    if (*size >= *capacity) {
        // Dynamically allocate more space if needed
        *capacity *= 2;
        *words = realloc(*words, (*capacity) * sizeof(WordFrequency));
    }

    // Add new word
    (*words)[*size].word = strdup(word);
    (*words)[*size].count = 1;
    (*size)++;
}

// Helper function to read the next word from a file
int getNextWord(FILE *file, char *buffer, int size) {
    int index = 0;
    int ch;

    // Skip non-alphabetic characters
    while ((ch = fgetc(file)) != EOF && !isalpha(ch));

    if (ch == EOF) {
        return 0;
    }

    // Start forming the word
    buffer[index++] = tolower(ch);

    // Read the word
    while ((ch = fgetc(file)) != EOF && isalpha(ch) && index < size - 1) {
        buffer[index++] = tolower(ch);
    }

    buffer[index] = '\0';
    return index;
}

