#define HASH_SIZE 1024
#define MAX_WORD_LENGTH 100

// Structure to store a word and its frequency
typedef struct WordEntry {
    char word[MAX_WORD_LENGTH];
    int frequency;
    struct WordEntry *next;
} WordEntry;

// Hash function to map words to indices
unsigned int hash(const char *word) {
    unsigned int hash_value = 0;
    for (int i = 0; word[i]; i++) {
        hash_value = 31 * hash_value + word[i];
    }
    return hash_value % HASH_SIZE;
}

// Function to insert a word into the hash table
void insertWord(WordEntry *hashTable[], const char *word) {
    unsigned int index = hash(hash(word));
    WordEntry *entry = hashTable[index];

    while (entry) {
        if (strcmp(entry->word, word) == 0) {
            entry->frequency++;
            return;
        }
        entry = entry->next;
    }

    // If the word is not found, create a new entry
    entry = (WordEntry *)malloc(sizeof(WordEntry));
    strcpy(entry->word, word);
    entry->frequency = 1;
    entry->next = hashTable[index];
    hashTable[index] = entry;
}

// Function to read words from a file and insert them into the hash table
void readWordsFromFile(const char *filename, WordEntry *hashTable[]) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        exit(1);
    }

    char word[MAX_WORD_LENGTH];
    while (fscanf(file, "%s", word) != EOF) {
        // Convert word to lowercase
        for (int i = 0; word[i]; i++) {
            word[i] = tolower(word[i]);
        }
        insertWord(hashTable, word);
    }

    fclose(file);
}

// Function to print the word frequency
void printWordFrequency(WordEntry *hashTable[]) {
    for (int i = 0; i < HASH_SIZE; i++) {
        WordEntry *entry = hashTable[i];
        while (entry) {
            printf("%s: %d\n", entry->word, entry->frequency);
            entry = entry->next;
        }
    }
}

// Function to free the memory allocated for the hash table
void freeHashTable(WordEntry *hashTable[]) {
    for (int i = 0; i < HASH_SIZE; i++) {
        WordEntry *entry = hashTable[i];
        while (entry) {
            WordEntry *next = entry->next;
            free(entry);
            entry = next;
        }
    }
}

