#include <stdio.h>
#include <string.h>

void rle_compress(const char* input, char* compressed) {
    int input_len = strlen(input);
    int compressed_index = 0;

    for (int i = 0; i < input_len; i++) {
        int count = 1;

        // Count consecutive occurrences of the current character
        while (i + 1 < input_len && input[i] == input[i + 1]) {
            count++;
            i++;
        }

        // If count > 1, add count before the character
        if (count > 1) {
            // Convert count to string
            int temp_index = compressed_index;
            do {
                compressed[temp_index++] = (count % 10) + '0';
                count /= 10;
            } while (count > 0);

            // Reverse the count digits
            int start = compressed_index;
            int end = temp_index - 1;
            while (start < end) {
                char temp = compressed[start];
                compressed[start] = compressed[end];
                compressed[end] = temp;
                start++;
                end--;
            }

            compressed_index = temp_index;
        }

        // Add the character
        compressed[compressed_index++] = input[i];
    }

    // Null-terminate the compressed string
    compressed[compressed_index] = '\0';
}

int main() {
    const char* original = "OpenAI2025!";
    char compressed[100] = {0};  // Buffer for compressed string

    printf("Original string: %s\n", original);

    rle_compress(original, compressed);

    printf("Compressed string: %s\n", compressed);

    return 0;
}

#include <stdio.h>
#include <string.h>

void rle_encode(const char *input, char *output) {
    int len = strlen(input);
    int count;
    int pos = 0; // position in output buffer

    for (int i = 0; i < len; i++) {
        count = 1;
        // Count consecutive characters
        while (i + 1 < len && input[i] == input[i+1]) {
            i++;
            count++;
        }

        // Store character and its count in output
        if (count > 1) {
            pos += sprintf(output + pos, "%d%c", count, input[i]);
        } else {
            pos += sprintf(output + pos, "%c", input[i]);
        }
    }
    output[pos] = '\0'; // Null-terminate the output string
}

int main() {
    const char *input = "OpenAI2025!";
    char output[256]; // Buffer for encoded output

    printf("Original string: %s\n", input);

    rle_encode(input, output);

    printf("RLE encoded: %s\n", output);

    return 0;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h> // For malloc and free (good practice for dynamic memory)

// Function to perform RLE compression
char* rle_encode(const char* input_string) {
    if (input_string == NULL || strlen(input_string) == 0) {
        return NULL; // Handle empty or null input
    }

    // Estimate maximum possible compressed size:
    // In the worst case (no consecutive characters), each char becomes "1X"
    // So, length * 2. Plus 1 for null terminator.
    // e.g., "ABC" -> "1A1B1C" (length 3, compressed length 6)
    size_t input_len = strlen(input_string);
    size_t max_compressed_len = input_len * 2 + 1; // +1 for null terminator

    // Allocate memory for the compressed string
    // We'll reallocate later if this is too big, or use a more precise build-up
    char* compressed_string = (char*)malloc(max_compressed_len);
    if (compressed_string == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    int i = 0; // Pointer for the input string
    int k = 0; // Pointer for the compressed string

    while (i < input_len) {
        char current_char = input_string[i];
        int count = 0;

        // Count consecutive occurrences of the current character
