// Function to perform RLE compression
char* rle_compress(const char *input) {
    int input_length = strlen(input);
    int output_length = 0;
    char *output = (char *)malloc(input_length * 2 + 1); // Worst case: each character is followed by a count

    if (output == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    char current_char = input[0];
    int count = 1;

    for (int i = 1; i < input_length; ++i) {
        if (input[i] == current_char) {
            count++;
        } else {
            output[output_length++] = current_char;
            output[output_length++] = count + '0'; // Convert count to character
            current_char = input[i];
            count = 1;
        }
    }

    // Add the last group
    output[output_length++] = current_char;
    output[output_length++] = count + '0'; // Convert count to character

    output[output_length] = '\0'; // Null-terminate the string

    // Reallocate memory to fit the actual output length
    output = (char *)realloc(output, output_length + 1);
    if (output == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        return NULL;
    }

    return output;
}

