    for(int i = 0; infix[i]; i++) {
        // If current character is an operand, add to postfix
        if(isOperand(infix[i])) {
            postfix[j++] = infix[i];
        }

        // If current character is '(', push to stack
        else if(infix[i] == '(') {
            stack[++top] = infix[i];
        }

        // If current character is ')', pop and output from stack 
        // until '(' is encountered
        else if(infix[i] == ')') {
            while(top > -1 && stack[top] != '(') {
                postfix[j++] = stack[top--];
            }

            // Pop '('
            if(top > -1 && stack[top] == '(') {
                top--;
            }
        }

        // If current character is an operator
        else {
            // Pop operators with higher or equal precedence
            while(top > -1 && getPrecedence(stack[top]) >= getPrecedence(infix[i])) {
                postfix[j++] = stack[top--];
            }

            // Push current operator to stack
            stack[++top] = infix[i];
        }
    }

    // Pop remaining operators from stack
    while(top > -1) {
        postfix[j++] = stack[top--];
    }

    // Null terminate the postfix string
    postfix[j] = '\0';
}

