// Define a simple stack structure
typedef struct Stack {
    int top;
    unsigned capacity;
    char* array;
} Stack;

// Function to create a stack of given capacity.
Stack* createStack(unsigned capacity) {
    Stack* stack = (Stack*)malloc(sizeof(Stack));
    if (!stack) {
        printf("Memory allocation failed for stack\n");
        exit(EXIT_FAILURE);
    }
    stack->capacity = capacity;
    stack->top = -1; // Initialize top as -1 indicating an empty stack
    stack->array = (char*)malloc(stack->capacity * sizeof(char));
    if (!stack->array) {
        printf("Memory allocation failed for stack array\n");
        exit(EXIT_FAILURE);
    }
    return stack;
}

// Stack is empty when top is -1
int isEmpty(Stack* stack) {
    return stack->top == -1;
}

// Function to add an item to stack. It increases top by 1
void push(Stack* stack, char item) {
    if (stack->top == stack->capacity - 1) { // Stack Overflow
        printf("Stack Overflow! Cannot push %c\n", item);
        return;
    }
    stack->array[++stack->top] = item;
}

// Function to remove an item from stack. It decreases top by 1
char pop(Stack* stack) {
    if (isEmpty(stack)) {
        printf("Stack Underflow! Cannot pop from empty stack\n");
        return '\0'; // Return null character or handle error appropriately
    }
    return stack->array[stack->top--];
}

// Function to return the top element from stack without removing it
char peek(Stack* stack) {
    if (isEmpty(stack)) {
        return '\0'; // Return null character for empty stack
    }
    return stack->array[stack->top];
}

