void infixToPostfix(char* infix) {
    char postfix[100]; // Assuming postfix expression won't exceed 100 characters
    int i, j = 0;
    Stack* stack = createStack(strlen(infix)); // Stack to hold operators and parentheses

    for (i = 0; infix[i] != '\0'; i++) {
        char ch = infix[i];

        // 1. If the scanned character is an operand, add it to the postfix expression.
        if (isOperand(ch)) {
            postfix[j++] = ch;
        }
        // 2. If the scanned character is an '(', push it to stack.
        else if (ch == '(') {
            push(stack, ch);
        }
        // 3. If the scanned character is an ')', pop and output from the stack
        //    until an '(' is encountered.
        else if (ch == ')') {
            while (!isEmpty(stack) && peek(stack) != '(') {
                postfix[j++] = pop(stack);
            }
            if (!isEmpty(stack) && peek(stack) != '(') { // Invalid expression
                printf("Invalid Infix Expression: Mismatched parentheses.\n");
                free(stack->array);
                free(stack);
                return;
            } else {
                pop(stack); // Pop '('
            }
        }
        // 4. If the scanned character is an operator
        else {
            while (!isEmpty(stack) && precedence(ch) <= precedence(peek(stack))) {
                postfix[j++] = pop(stack);
            }
            push(stack, ch);
        }
    }

    // 5. Pop all the remaining operators from the stack
    while (!isEmpty(stack)) {
        if (peek(stack) == '(') { // Invalid expression (unmatched '(')
            printf("Invalid Infix Expression: Unmatched parentheses.\n");
            free(stack->array);
            free(stack);
            return;
        }
        postfix[j++] = pop(stack);
    }

    postfix[j] = '\0'; // Null-terminate the postfix string
    printf("Infix expression: %s\n", infix);
    printf("Postfix expression: %s\n", postfix);

