    }
    return stack->arr[stack->top--];
}

// Function to get the top element of stack
char peek(Stack* stack) {
    if (isEmpty(stack)) {
        printf("Stack is empty\n");
        return '\0';
    }
    return stack->arr[stack->top];
}

// Function to get the precedence of an operator
int getPrecedence(char c) {
    if (c == '+' || c == '-') {
        return 1;
    } else if (c == '*' || c == '/') {
        return 2;
    }
    return 0;
}

// Function to convert infix to postfix
void infixToPostfix(char* infix) {
    int length = strlen(infix);
    int i = 0;
    Stack* stack = createStack(length);

    while (i < length) {
        if (isalpha(infix[i])) {
            printf("%c ", infix[i]);
        } else if (infix[i] == '(') {
            push(stack, infix[i]);
        } else if (infix[i] == ')') {
            while (peek(stack) != '(') {
                printf("%c ", pop(stack));
            }
            pop(stack); // Remove '('
        } else {
            while (!isEmpty(stack) && peek(stack) != '(' && getPrecedence(infix[i]) <= getPrecedence(peek(stack))) {
                printf("%c ", pop(stack));
            }
            push(stack, infix[i]);
        }
        i++;
    }

    while (!isEmpty(stack)) {
        printf("%c ", pop(stack));
    }
}

int main() {
    char infix[] = "x*(y+z)-w";
    printf("Infix Expression: %s\n", infix);
    printf("Postfix Expression: ");
    infixToPostfix(infix);
    return 0;
}

