// Custom memory tracking structure
typedef struct MemoryBlock {
    void* ptr;
    size_t size;
    char* allocation_trace[32];
    int trace_size;
    struct MemoryBlock* next;
} MemoryBlock;

// Global memory tracking variables
static MemoryBlock* head = NULL;
static int total_allocations = 0;
static size_t total_memory_allocated = 0;

// Function prototypes
void* tracked_malloc(size_t size);
void tracked_free(void* ptr);
void print_memory_leaks();
void capture_stack_trace(MemoryBlock* block);
void add_memory_block(void* ptr, size_t size);
void remove_memory_block(void* ptr);

// Override malloc to track memory allocations
void* tracked_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr) {
        add_memory_block(ptr, size);
    }
    return ptr;
}

// Override free to track memory deallocations
void tracked_free(void* ptr) {
    if (ptr) {
        remove_memory_block(ptr);
        free(ptr);
    }
}

// Add memory block to tracking list
void add_memory_block(void* ptr, size_t size) {
    MemoryBlock* block = malloc(sizeof(MemoryBlock));
    block->ptr = ptr;
    block->size = size;

    // Capture stack trace
    capture_stack_trace(block);

    // Link to global list
    block->next = head;
    head = block;

    total_allocations++;
    total_memory_allocated += size;
}

// Remove memory block from tracking list
void remove_memory_block(void* ptr) {
    MemoryBlock* current = head;
    MemoryBlock* prev = NULL;

    while (current) {
        if (current->ptr == ptr) {
            if (prev) {
                prev->next = current->next;
            } else {
                head = current->next;
            }

            total_allocations--;
            total_memory_allocated -= current->size;

            // Free stack trace memory
            for (int i = 0; i < current->trace_size; i++) {
                free(current->allocation_trace[i]);
            }

            free(current);
            return;
        }

        prev = current;
        current = current->next;
    }
}

// Capture stack trace for memory allocation
void capture_stack_trace(MemoryBlock* block) {
    void* trace[32];
    block->trace_size = backtrace(trace, 32);
    block->allocation_trace[0] = NULL;

    char** symbols = backtrace_symbols(trace, block->trace_size);
    if (symbols) {
        for (int i = 0; i < block->trace_size; i++) {
            block->allocation_trace[i] = strdup(symbols[i]);
        }
        free(symbols);
    }
}

// Print memory leak details
void print_memory_leaks() {
    MemoryBlock* current = head;

    printf("\n--- Memory Leak Report ---\n");
    printf("Total Allocations: %d\n", total_allocations);
    printf("Total Memory Allocated: %zu bytes\n", total_memory_allocated);

    while (current) {
        printf("\nLEAKED Memory Block:\n");
        printf("Address: %p\n", current->ptr);
        printf("Size: %zu bytes\n", current->size);

        printf("Allocation Trace:\n");
        for (int i = 0; i < current->trace_size; i++) {
            printf("  %s\n", current->allocation_trace[i]);
        }

        current = current->next;
    }
}

// Memory leak detection function
void detect_memory_leaks() {
    // Register memory leak reporting at program exit
    atexit(print_memory_leaks);
}

// Example function to demonstrate memory allocation
void test_memory_allocation() {
    void* ptr1 = tracked_malloc(100);
    void* ptr2 = tracked_malloc(200);
    void* ptr3 = tracked_malloc(300);

    // Intentionally leak ptr2 and ptr3
    tracked_free(ptr1);
}

int main() {
    // Initialize memory leak detection
    detect_memory_leaks();

    // Perform memory allocations
    test_memory_allocation();

    return 0;
}

#include <stdio.h>
