// Structure to track memory allocations
typedef struct {
    void *ptr;
    size_t size;
    const char *file;
    int line;
} AllocationRecord;

// Global variables for tracking
static AllocationRecord *allocations = NULL;
static size_t num_allocations = 0;
static size_t max_allocations = 0;

// Override standard memory functions
void *track_malloc(size_t size, const char *file, int line);
void *track_calloc(size_t num, size_t size, const char *file, int line);
void *track_realloc(void *ptr, size_t size, const char *file, int line);
void track_free(void *ptr, const char *file, int line);

// Macro replacements
#define malloc(size) track_malloc(size, __FILE__, __LINE__)
#define calloc(num, size) track_calloc(num, size, __FILE__, __LINE__)
#define realloc(ptr, size) track_realloc(ptr, size, __FILE__, __LINE__)
#define free(ptr) track_free(ptr, __FILE__, __LINE__)

// Initialize memory tracking
void init_memory_tracking() {
    allocations = (AllocationRecord *)calloc(100, sizeof(AllocationRecord));
    max_allocations = 100;
    num_allocations = 0;
}

// Report memory leaks
void report_memory_leaks() {
    size_t leaks = 0;
    size_t total_leaked = 0;

    printf("\n=== Memory Leak Report ===\n");

    for (size_t i = 0; i < num_allocations; i++) {
        if (allocations[i].ptr != NULL) {
            printf("Leak %zu: %zu bytes allocated at %s:%d\n",
                   ++leaks, allocations[i].size, allocations[i].file, allocations[i].line);
            total_leaked += allocations[i].size;
        }
    }

    if (leaks == 0) {
        printf("No memory leaks detected!\n");
    } else {
        printf("\nTotal leaks: %zu\n", leaks);
        printf("Total leaked memory: %zu bytes\n", total_leaked);
    }

    free(allocations);
}

// Find allocation record
static size_t find_allocation(void *ptr) {
    for (size_t i = 0; i < num_allocations; i++) {
        if (allocations[i].ptr == ptr) {
            return i;
        }
    }
    return num_allocations; // Not found
}

// Add allocation record
static void add_allocation(void *ptr, size_t size, const char *file, int line) {
    if (num_allocations >= max_allocations) {
        max_allocations *= 2;
        allocations = (AllocationRecord *)realloc(allocations, max_allocations * sizeof(AllocationRecord));
    }

    allocations[num_allocations].ptr = ptr;
    allocations[num_allocations].size = size;
    allocations[num_allocations].file = file;
    allocations[num_allocations].line = line;
    num_allocations++;
}

// Remove allocation record
static void remove_allocation(void *ptr) {
    size_t i = find_allocation(ptr);
    if (i < num_allocations) {
        allocations[i] = allocations[num_allocations - 1];
        num_allocations--;
    }
}

// Tracked malloc
void *track_malloc(size_t size, const char *file, int line) {
    void *ptr = malloc(size);
    if (ptr != NULL) {
        add_allocation(ptr, size, file, line);
    }
    return ptr;
}

// Tracked calloc
void *track_calloc(size_t num, size_t size, const char *file, int line) {
    void *ptr = calloc(num, size);
    if (ptr != NULL) {
        add_allocation(ptr, num * size, file, line);
    }
    return ptr;
}

// Tracked realloc
void *track_realloc(void *ptr, size_t size, const char *file, int line) {
    void *new_ptr;

    if (ptr == NULL) {
        return track_malloc(size, file, line);
    }

    size_t i = find_allocation(ptr);
    if (i == num_allocations) {
        // Not tracked, just do regular realloc
        return realloc(ptr, size);
    }

    new_ptr = realloc(ptr, size);
    if (new_ptr != NULL) {
        allocations[i].ptr = new_ptr;
        allocations[i].size = size;
        allocations[i].file = file;
        allocations[i].line = line;
    } else {
        remove_allocation(ptr);
    }

    return new_ptr;
}

// Tracked free
void track_free(void *ptr, const char *file, int line) {
    (void)file; (void)line; // Unused parameters

    if (ptr == NULL) {
        return;
    }

    size_t i = find_allocation(ptr);
    if (i < num_allocations) {
        remove_allocation(ptr);
    }
    free(ptr);
}

// Example usage
int main() {
    init_memory_tracking();

    // Some memory operations
    char *str1 = (char *)malloc(100);
    int *nums = (int *)calloc(10, sizeof(int));
    str1 = (char *)realloc(str1, 200);

    // Intentionally leak some memory
    void *leak1 = malloc(50);
    void *leak2 = calloc(5, sizeof(double));

    // Free some memory
    free(nums);

    // Report leaks (should find 2 leaks)
    report_memory_leaks();

    return 0;
}

#ifndef LEAK_DETECTOR_H
#define LEAK_DETECTOR_H

// We need the standard library prototypes *before* redefining them.
// So, we include stdlib.h here first.
#include <stdlib.h>
#include <stdio.h> // For stderr by detector

// Internal flag to prevent recursion when our custom wrappers
// allocate memory for their own tracking data.
// It's extern because it's defined in leak_detector.c
extern int __leak_detector_internal_call;

// Prototypes for our wrapper functions. These are what the macros will expand to.
void *__ld_malloc(size_t size, const char *file, int line, const char *func);
void __ld_free(void *ptr, const char *file, int line, const char *func);
void *__ld_calloc(size_t nmemb, size_t size, const char *file, int line, const char *func);
void *__ld_realloc(void *ptr, size_t size, const char *file, int line, const char *func);
char *__ld_strdup(const char *s, const char *file, int line, const char *func);

// Undefine the original standard library functions before redefining them.
// This is crucial to avoid conflicts and ensure our macros take precedence.
#ifdef malloc
#undef malloc
#endif
#ifdef free
#undef free
#endif
#ifdef calloc
#undef calloc
#endif
#ifdef realloc
#undef realloc
#endif
#ifdef strdup
#undef strdup
#endif

// Redefine standard allocation functions to our tracking versions.
// __FILE__, __LINE__, and __func__ provide useful debugging information.
#define malloc(size) __ld_malloc(size, __FILE__, __LINE__, __func__)
#define free(ptr) __ld_free(ptr, __FILE__, __LINE__, __func__)
#define calloc(nmemb, size) __ld_calloc(nmemb, size, __FILE__, __LINE__, __func__)
#define realloc(ptr, size) __ld_realloc(ptr, size, __FILE__, __LINE__, __func__)
#define strdup(s) __ld_strdup(s, __FILE__, __LINE__, __func__)

// Public API for initializing and reporting.
void leak_detector_init(void);
void leak_detector_report(void); // Can be called manually if needed before exit

#endif // LEAK_DETECTOR_H

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Track each allocation
typedef struct Allocation {
    void *ptr;
    size_t size;
    const char *file;
    int line;
    struct Allocation *next;
} Allocation;

static Allocation *head = NULL;

// Helper to add an allocation
void add_allocation(void *ptr, size_t size, const char *file, int line) {
    Allocation *a = (Allocation *)malloc(sizeof(Allocation));
    a->ptr  = ptr;
    a->size = size;
    a->file = file;
    a->line = line;
    a->next = head;
    head = a;
}

// Helper to remove an allocation
void remove_allocation(void *ptr) {
    Allocation **curr = &head;
    while (*curr) {
        if ((*curr)->ptr == ptr) {
            Allocation *to_delete = *curr;
            *curr = (*curr)->next;
            free(to_delete);
            return;
        }
        curr = &(*curr)->next;
    }
}

// Check if there are leaks at exit
void report_leaks(void) {
    Allocation *curr = head;
    if (curr == NULL) {
        printf("No memory leaks detected.\n");
        return;
    }
    printf("Memory leaks detected:\n");
    while (curr) {
        printf(" Leak of %zu bytes allocated at %s:%d (address: %p)\n",
                curr->size, curr->file, curr->line, curr->ptr);
        curr = curr->next;
    }
}

// Macros to override default functions
#define malloc(s) my_malloc(s, __FILE__, __LINE__)
#define calloc(n, s) my_calloc(n, s, __FILE__, __LINE__)
#define realloc(p, s) my_realloc(p, s, __FILE__, __LINE__)
#define free(p) my_free(p)

// Wrappers
void *my_malloc(size_t size, const char *file, int line) {
    void *ptr = (void *)malloc(size);
    if (ptr) add_allocation(ptr, size, file, line);
    return ptr;
}

void *my_calloc(size_t n, size_t size, const char *file, int line) {
    void *ptr = (void *)calloc(n, size);
    if (ptr) add_allocation(ptr, n * size, file, line);
    return ptr;
}

void *my_realloc(void *ptr, size_t size, const char *file, int line) {
    if (ptr) remove_allocation(ptr);
    void *new_ptr = (void *)realloc(ptr, size);
    if (new_ptr)
        add_allocation(new_ptr, size, file, line);
    return new_ptr;
}

void my_free(void *ptr) {
    if (ptr) remove_allocation(ptr);
    free(ptr);
}

// Example usage
int main(void) {
    atexit(report_leaks);

    int *arr = malloc(10 * sizeof(int));  // Not freed: leak
    char *buf = malloc(50);
    free(buf);

    void *p = calloc(20, 4); // Not freed: leak
    p = realloc(p, 500);
    free(p);

    // No leaks for p/buf, arr intentionally leaked

    return 0;
}

