        exit(1);
    }
    new_block->ptr = ptr;
    new_block->size = size;
    new_block->file = file;
    new_block->line = line;
    new_block->next = head;
    head = new_block;
}

void remove_mem_block(void *ptr) {
    MemBlock **current = &head;
    while (*current) {
        if ((*current)->ptr == ptr) {
            MemBlock *freed = *current;
            *current = (*current)->next;
            free(freed);
            return;
        }
        current = &((*current)->next);
    }
    fprintf(stderr, "Attempted to free untracked memory at pointer %p.\n", ptr);
}

