#define _GNU_SOURCE // For RTLD_NEXT on Linux, necessary for dlsym
#include <stdio.h>
#include <stdlib.h>
#include <dlfcn.h>      // For dlsym
#include <string.h>     // For memset
#include <pthread.h>    // For mutex (thread safety)
#include <execinfo.h>   // For backtrace (optional, for debugging)

// A simple linked list to track allocations
typedef struct Allocation {
    void* ptr;
    size_t size;
    // For more advanced debugging, store stack trace or allocation site name
    // char backtrace_symbols[256]; 
    struct Allocation* next;
} Allocation;

static Allocation* head = NULL;
static size_t total_allocated = 0;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Pointers to the original malloc/free functions
static void* (*real_malloc)(size_t) = NULL;
static void (*real_free)(void*) = NULL;
static void* (*real_calloc)(size_t, size_t) = NULL;
static void* (*real_realloc)(void*, size_t) = NULL;

// Helper to get real functions
static void init_real_functions() {
    // dlsym(RTLD_NEXT, ...) finds the *next* occurrence of the symbol
    // in the search order. This is crucial to call the actual libc functions.
    if (!real_malloc) {
        real_malloc = (void* (*)(size_t))dlsym(RTLD_NEXT, "malloc");
        if (!real_malloc) {
            fprintf(stderr, "Error: Could not find real malloc. Aborting.\n");
            exit(1);
        }
    }
    if (!real_free) {
        real_free = (void (*)(void*))dlsym(RTLD_NEXT, "free");
        if (!real_free) {
            fprintf(stderr, "Error: Could not find real free. Aborting.\n");
            exit(1);
        }
    }
    if (!real_calloc) {
        real_calloc = (void* (*)(size_t, size_t))dlsym(RTLD_NEXT, "calloc");
        if (!real_calloc) {
            fprintf(stderr, "Error: Could not find real calloc. Aborting.\n");
            exit(1);
        }
    }
    if (!real_realloc) {
        real_realloc = (void* (*)(void*, size_t))dlsym(RTLD_NEXT, "realloc");
        if (!real_realloc) {
            fprintf(stderr, "Error: Could not find real realloc. Aborting.\n");
            exit(1);
        }
    }
}

// Function to add a new allocation to our list
static void add_allocation(void* ptr, size_t size) {
    if (!ptr || ptr == NULL) return; // Should not happen for valid malloc

    pthread_mutex_lock(&list_mutex);
    Allocation* new_alloc = real_malloc(sizeof(Allocation)); // Use real_malloc to avoid recursion
    if (new_alloc == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for tracking. Exiting.\n");
        // We are in a critical path, cannot just return
        abort(); 
    }
    new_alloc->ptr = ptr;
    new_alloc->size = size;
    new_alloc->next = head;
    head = new_alloc;
    total_allocated += size;
    pthread_mutex_unlock(&list_mutex);
}

// Function to remove an allocation from our list
static void remove_allocation(void* ptr) {
    if (ptr == NULL) return;

    pthread_mutex_lock(&list_mutex);
    Allocation* current = head;
    Allocation* prev = NULL;

    while (current != NULL) {
        if (current->ptr == ptr) {
            if (prev == NULL) {
                head = current->next;
            } else {
                prev->next = current->next;
            }
            total_allocated -= current->size;
            real_free(current); // Use real_free to avoid recursion
            pthread_mutex_unlock(&list_mutex);
            return;
        }
        prev = current;
        current = current->next;
    }
    // If ptr was not found, it might be a double free or freeing of non-malloc'd memory
    // In a real detector, this would be an error report.
    // For now, print to stderr.
    fprintf(stderr, "WARNING: Attempted to free %p which was not tracked by our detector (possibly double free or invalid free).\n", ptr);
    pthread_mutex_unlock(&list_mutex);
}

// --- Overridden Malloc/Free Functions ---

void* malloc(size_t size) {
    init_real_functions(); // Ensure real functions are initialized
    void* ptr = real_malloc(size);
    add_allocation(ptr, size);
    return ptr;
}

void free(void* ptr) {
    init_real_functions();
    remove_allocation(ptr);
    real_free(ptr);
}

void* calloc(size_t nmemb, size_t size) {
    init_real_functions();
    void* ptr = real_calloc(nmemb, size);
    add_allocation(ptr, nmemb * size);
    return ptr;
}

void* realloc(void* ptr, size_t size) {
    init_real_functions();
    // Realloc is tricky:
    // 1. If ptr is NULL, it acts like malloc.
    // 2. If size is 0 and ptr is not NULL, it acts like free.
    // 3. Otherwise, it resizes the old block and might return a new address.
    remove_allocation(ptr); // Remove old allocation if it existed
    void* new_ptr = real_realloc(ptr, size);
    if (size > 0) { // Only add if it's not effectively a free
        add_allocation(new_ptr, size);
    }
    return new_ptr;
}

// --- Leak Report on Exit ---

// This function is typically called by the dynamic linker when the library is unloaded.
// For the main executable, this happens at program exit.
__attribute__((destructor))
static void report_leaks(void) {
    pthread_mutex_lock(&list_mutex);
    if (head == NULL) {
        fprintf(stderr, "\n--- Leak Detector Report ---\n");
        fprintf(stderr, "No memory leaks detected. All tracked memory was freed.\n");
    } else {
        fprintf(stderr, "\n--- Leak Detector Report (Total Leaked: %zu bytes) ---\n", total_allocated);
        Allocation* current = head;
        int leak_count = 0;
        while (current != NULL) {
            leak_count++;
            fprintf(stderr, "Leak #%d: Leaked %zu bytes at address %p\n", leak_count, current->size, current->ptr);
            // Optionally, print backtrace if stored
            // fprintf(stderr, "  Backtrace: %s\n", current->backtrace_symbols);
            current = current->next;
        }
        fprintf(stderr, "--- End Leak Detector Report ---\n");
    }

    // Clean up our internal tracking list (using real_free)
    Allocation* current = head;
    while (current != NULL) {
        Allocation* next = current->next;
        real_free(current);
        current = next;
    }
    head = NULL;
    pthread_mutex_unlock(&list_mutex);
}

#ifndef LEAK_DETECTOR_H
#define LEAK_DETECTOR_H

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct MemInfo {
    void *ptr;
    size_t size;
    const char *file;
    int line;
    struct MemInfo *next;
} MemInfo;

static MemInfo *head = NULL;

// Helper: Internal add and remove
static void add_meminfo(void *ptr, size_t size, const char *file, int line) {
    MemInfo *mi = (MemInfo*)malloc(sizeof(MemInfo));
    mi->ptr = ptr;
    mi->size = size;
    mi->file = file;
    mi->line = line;
    mi->next = head;
    head = mi;
}
static void remove_meminfo(void *ptr) {
    MemInfo **cur = &head;
    while (*cur) {
        if ((*cur)->ptr == ptr) {
            MemInfo *tmp = *cur;
            *cur = tmp->next;
            free(tmp);
            return;
        }
        cur = &((*cur)->next);
    }
}

// Redefine malloc/free/calloc/realloc
#define malloc(s) my_malloc((s), __FILE__, __LINE__)
#define calloc(n, s) my_calloc((n), (s), __FILE__, __LINE__)
#define realloc(p, s) my_realloc((p), (s), __FILE__, __LINE__)
#define free(p) my_free((p))

void *my_malloc(size_t size, const char *file, int line) {
    void *ptr = (malloc)(size); // call actual malloc!
    if (ptr)
        add_meminfo(ptr, size, file, line);
    return ptr;
}

void *my_calloc(size_t n, size_t size, const char *file, int line) {
    void *ptr = (calloc)(n, size);
    if (ptr)
        add_meminfo(ptr, n*size, file, line);
    return ptr;
}

void *my_realloc(void *ptr, size_t size, const char *file, int line) {
    if (ptr)
        remove_meminfo(ptr);
    void *nptr = (realloc)(ptr, size);
    if (nptr)
        add_meminfo(nptr, size, file, line);
    return nptr;
}

void my_free(void *ptr) {
    if (ptr)
        remove_meminfo(ptr);
    (free)(ptr);
}

static void report_mem_leaks(void) {
    MemInfo *mi = head;
    int leaks = 0;
    while (mi) {
        fprintf(stderr, "[LEAK] %p: %zu bytes allocated at %s:%d and not freed\n",
                mi->ptr, mi->size, mi->file, mi->line);
        leaks++;
        mi = mi->next;
    }
    if (leaks == 0)
        fprintf(stderr, "No memory leaks detected.\n");
    else
        fprintf(stderr, "%d leaks detected.\n", leaks);
}
__attribute__((constructor)) static void setup_leak_detector(void) {
    atexit(report_mem_leaks);
}

