typedef struct MemNode {
    void *ptr;
    size_t size;
    const char *file;
    int line;
    struct MemNode *next;
} MemNode;

MemNode *head = NULL;

void add_record(void *ptr, size_t size, const char *file, int line) {
    MemNode *node = malloc(sizeof(MemNode));
    if (node) {
        node->ptr = ptr;
        node->size = size;
        node->file = file;
        node->line = line;
        node->next = head;
        head = node;
    }
}

void remove_record(void *ptr) {
    MemNode **curr = &head;
    while (*curr) {
        MemNode *entry = *curr;
        if (entry->ptr == ptr) {
            *curr = entry->next;
            free(entry);
            return;
        }
        curr = &entry->next;
    }
    fprintf(stderr, "Attempt to free non-allocated pointer: %p\n", ptr);
}

void report_leaks() {
    MemNode *curr = head;
    while (curr) {
        printf("Memory leak detected: %zu bytes allocated at %s:%d not freed\n",
               curr->size, curr->file, curr->line);
        curr = curr->next;
    }
}

void cleanup() {
    MemNode *curr = head;
    while (curr) {
        MemNode *next = curr->next;
        free(curr);
        curr = next;
    }
}

#define malloc(x) my_malloc(x, __FILE__, __LINE__)
#define free(x) my_free(x)
#define calloc(n, x) my_calloc(n, x, __FILE__, __LINE__)
#define realloc(ptr, x) my_realloc(ptr, x, __FILE__, __LINE__)

void *my_malloc(size_t size, const char *file, int line) {
    void *ptr = malloc(size);
    if (ptr) add_record(ptr, size, file, line);
    return ptr;
}

void my_free(void *ptr) {
    remove_record(ptr);
    free(ptr);
}

void *my_calloc(size_t nitems, size_t size, const char *file, int line) {
    void *ptr = calloc(nitems, size);
    if (ptr) add_record(ptr, nitems * size, file, line);
    return ptr;
}

void *my_realloc(void *ptr, size_t size, const char *file, int line) {
    if (!ptr) return my_malloc(size, file, line);
    remove_record(ptr);
    void *new_ptr = realloc(ptr, size);
    if (new_ptr) add_record(new_ptr, size, file, line);
    return new_ptr;
}

