    // Example usage
    int *example = malloc(10 * sizeof(int));
    int *example2 = malloc(5 * sizeof(int));
    example2 = realloc(example2, 10 * sizeof(int));
    free(example);

    // Check for leaks
    report_leaks();

    // Cleanup allocated records
    cleanup();

    return 0;
}

