        return NULL; // malloc failed
    }

    // Create a new MemoryBlock
    MemoryBlock *newBlock = (MemoryBlock*)malloc(sizeof(MemoryBlock));
    if (!newBlock) {
        free(ptr); // Free memory if block allocation fails
        return NULL;
    }

    newBlock->ptr = ptr;
    newBlock->size = size;
    newBlock->next = head;
    head = newBlock;

    return ptr;
}

void my_free(void *ptr) {
    if (!ptr) return;

    // Find the block to free
    MemoryBlock *current = head;
    MemoryBlock *previous = NULL;

    while (current) {
        if (current->ptr == ptr) {
            // Found the block to free
            if (previous) {
                previous->next = current->next;
            } else {
                head = current->next;
            }
            free(current);
            free(ptr);
            return;
        }
        previous = current;
        current = current->next;
    }

    // If we reach this point, ptr wasn't found
    fprintf(stderr, "Warning: memory block not found for free().\n");
}

void report_leaks() {
    if (head) {
        printf("Memory Leak Detected:\n");
        MemoryBlock *current = head;
        while (current) {
            printf("Leaked block: %zu bytes\n", current->size);
            current = current->next;
        }
    } else {
        printf("No memory leaks detected.\n");
    }
}

