// Structure to represent a memory block
typedef struct MemoryBlock {
    void* address;
    size_t size;
    struct MemoryBlock* next;
} MemoryBlock;

// Linked list to track memory blocks
MemoryBlock* memory_blocks = NULL;

// Function to add a memory block to the list
void add_memory_block(void* address, size_t size) {
    MemoryBlock* new_block = (MemoryBlock*) malloc(sizeof(MemoryBlock));
    new_block->address = address;
    new_block->size = size;
    new_block->next = memory_blocks;
    memory_blocks = new_block;
}

// Function to remove a memory block from the list
void remove_memory_block(void* address) {
    if (memory_blocks == NULL) return;

    if (memory_blocks->address == address) {
        MemoryBlock* temp = memory_blocks;
        memory_blocks = memory_blocks->next;
        free(temp);
        return;
    }

    MemoryBlock* current = memory_blocks;
    while (current->next != NULL) {
        if (current->next->address == address) {
            MemoryBlock* temp = current->next;
            current->next = current->next->next;
            free(temp);
            return;
        }
        current = current->next;
    }
}

// Overridden malloc function
void* malloc_hook(size_t size) {
    void* address = malloc(size);
    add_memory_block(address, size);
    return address;
}

// Overridden free function
void free_hook(void* address) {
    remove_memory_block(address);
    free(address);
}

// Overridden calloc function
void* calloc_hook(size_t num, size_t size) {
    void* address = calloc(num, size);
    add_memory_block(address, num * size);
    return address;
}

// Overridden realloc function
void* realloc_hook(void* address, size_t size) {
    if (address != NULL) {
        remove_memory_block(address);
    }
    void* new_address = realloc(address, size);
    add_memory_block(new_address, size);
    return new_address;
}

