    if (memory_blocks == NULL) {
        printf("No memory leaks detected.\n");
        return;
    }

    printf("Memory leaks detected:\n");
    MemoryBlock* current = memory_blocks;
    while (current != NULL) {
        printf("  - Address: %p, Size: %zu bytes\n", current->address, current->size);
        current = current->next;
    }
}

