// Memory tracking structure
typedef struct MemoryBlock {
    void* ptr;             // Pointer to allocated memory
    size_t size;           // Size of allocated memory
    const char* file;      // File where allocation occurred
    int line;              // Line number of allocation
    struct MemoryBlock* next;  // Next block in linked list
} MemoryBlock;

// Global head of memory tracking list
static MemoryBlock* memoryList = NULL;

// Function to track memory allocations
void* track_malloc(size_t size, const char* file, int line) {
    // Allocate memory
    void* ptr = malloc(size);

    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed at %s:%d\n", file, line);
        return NULL;
    }

    // Create a new memory block tracking entry
    MemoryBlock* block = malloc(sizeof(MemoryBlock));
    if (block == NULL) {
        free(ptr);
        fprintf(stderr, "Tracking allocation failed at %s:%d\n", file, line);
        return NULL;
    }

    // Populate memory block information
    block->ptr = ptr;
    block->size = size;
    block->file = file;
    block->line = line;

    // Link into memory tracking list
    block->next = memoryList;
    memoryList = block;

    return ptr;
}

// Function to track memory frees
void track_free(void* ptr, const char* file, int line) {
    if (ptr == NULL) return;

    // Find and remove from tracking list
    MemoryBlock* current = memoryList;
    MemoryBlock* prev = NULL;

    while (current != NULL) {
        if (current->ptr == ptr) {
            // Remove from list
            if (prev == NULL) {
                memoryList = current->next;
            } else {
                prev->next = current->next;
            }

            // Free the memory and tracking block
            free(ptr);
            free(current);
            return;
        }

        prev = current;
        current = current->next;
    }

    // If not found in tracking list, it's an invalid free
    fprintf(stderr, "Invalid free at %s:%d\n", file, line);
}

