#define MAX_ALLOCATIONS 1000
static AllocationRecord allocations[MAX_ALLOCATIONS];
static int num_allocations = 0;

// Custom malloc wrapper
void *tracked_malloc(size_t size, const char *file, int line) {
    void *ptr = malloc(size);
    if (ptr != NULL) {
        if (num_allocations < MAX_ALLOCATIONS) {
            allocations[num_allocations].ptr = ptr;
            allocations[num_allocations].size = size;
            allocations[num_allocations].file = file;
            allocations[num_allocations].line = line;
            num_allocations++;
        } else {
            fprintf(stderr, "Warning: Allocation tracking limit reached\n");
        }
    }
    return ptr;
}

// Custom free wrapper
void tracked_free(void *ptr, const char *file, int line) {
    if (ptr == NULL) return;

    for (int i = 0; i < num_allocations; i++) {
        if (allocations[i].ptr == ptr) {
            // Remove from tracking by shifting remaining elements
            for (int j = i; j < num_allocations - 1; j++) {
                allocations[j] = allocations[j + 1];
            }
            num_allocations--;
            free(ptr);
            return;
        }
    }

    fprintf(stderr, "Warning: Attempt to free untracked pointer %p at %s:%d\n", 
            ptr, file, line);
    free(ptr); // Still free it to avoid crashes
}

