// --- Data Structure for Tracking Allocations ---

// A node in our linked list of allocated memory blocks
typedef struct AllocationInfo {
    void* ptr;                // Pointer to the allocated memory
    size_t size;              // Size of the allocated block
    const char* file;         // Source file where allocation occurred
    int line;                 // Line number where allocation occurred
    struct AllocationInfo* next; // Pointer to the next node in the list
} AllocationInfo;

// Head of our linked list of active allocations
static AllocationInfo* g_allocations_head = NULL;
static size_t g_total_allocated_bytes = 0;
static size_t g_total_freed_bytes = 0;

// --- Helper Functions for Tracking List ---

// Adds an allocation to the tracking list
static void add_allocation(void* ptr, size_t size, const char* file, int line) {
    if (ptr == NULL) {
        return; // Don't track NULL allocations
    }
    AllocationInfo* new_node = (AllocationInfo*)malloc(sizeof(AllocationInfo));
    if (new_node == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for AllocationInfo node.\n");
        // This is a critical error, but for a leak detector it might just crash
        // Or we could try to free the 'ptr'
        return;
    }
    new_node->ptr = ptr;
    new_node->size = size;
    new_node->file = file;
    new_node->line = line;
    new_node->next = g_allocations_head; // Add to the beginning of the list
    g_allocations_head = new_node;
    g_total_allocated_bytes += size;

    // Optional: Print a debug message for each allocation
    // printf("ALLOC: %p (size %zu) at %s:%d\n", ptr, size, file, line);
}

// Removes an allocation from the tracking list
// Returns true if found and removed, false otherwise
static bool remove_allocation(void* ptr, const char* file, int line) {
    if (ptr == NULL) {
        return false; // Cannot free NULL
    }

    AllocationInfo* current = g_allocations_head;
    AllocationInfo* prev = NULL;

    while (current != NULL) {
        if (current->ptr == ptr) {
            // Found the allocation to remove
            if (prev == NULL) {
                // It's the head of the list
                g_allocations_head = current->next;
            } else {
                prev->next = current->next;
            }
            g_total_freed_bytes += current->size;

            // Optional: Print a debug message for each free
            // printf("FREE:  %p (size %zu) from %s:%d (called by %s:%d)\n",
            //        ptr, current->size, current->file, current->line, file, line);

            free(current); // Free the AllocationInfo node itself
            return true;
        }
        prev = current;
        current = current->next;
    }
    // If we reach here, ptr was not found in our tracking list
    fprintf(stderr, "!!!!!!!!!!!!!!!!!!!!!!!!!! MEMORY ERROR !!!!!!!!!!!!!!!!!!!!!!!!!!\n");
    fprintf(stderr, "Attempted to free unallocated or already freed memory: %p\n", ptr);
    fprintf(stderr, "Called from %s:%d\n", file, line);
    fprintf(stderr, "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!\n");
    return false;
}

// --- Custom Malloc/Free Wrappers ---

// Important: Use macros to capture file and line number
#define mymalloc(size) _mymalloc(size, __FILE__, __LINE__)
#define myfree(ptr) _myfree(ptr, __FILE__, __LINE__)

void* _mymalloc(size_t size, const char* file, int line) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Error: Real malloc failed to allocate %zu bytes at %s:%d\n", size, file, line);
    } else {
        add_allocation(ptr, size, file, line);
    }
    return ptr;
}

void _myfree(void* ptr, const char* file, int line) {
    if (ptr == NULL) {
        // Freeing NULL is explicitly allowed by C standard and harmless
        return;
    }
    if (remove_allocation(ptr, file, line)) {
        free(ptr); // Only free if we successfully tracked it
    } else {
        // We already printed an error inside remove_allocation
        // Do NOT call free(ptr) here to avoid double-freeing if it was
        // found in a previous run and already freed or was never ours.
        // It's safer to let the user know about the untracked free.
        // A real debugger might halt execution here.
    }
}

// --- Leak Report Function ---

void report_memory_leaks() {
    printf("\n--- Memory Leak Report ---\n");
    if (g_allocations_head == NULL) {
        printf("No memory leaks detected. All allocated memory was freed.\n");
    } else {
        printf("The following memory blocks were allocated but not freed:\n");
        AllocationInfo* current = g_allocations_head;
        int leak_count = 0;
        size_t total_leaked_size = 0;

        while (current != NULL) {
            leak_count++;
            total_leaked_size += current->size;
            printf("  Leak %d: %p, Size: %zu bytes, Allocated at: %s:%d\n",
                   leak_count, current->ptr, current->size, current->file, current->line);
            current = current->next;
        }
        printf("Total %d leaks found, total leaked size: %zu bytes.\n",
               leak_count, total_leaked_size);
    }

    // Clean up our tracking list to prevent leaks in the reporter itself
    AllocationInfo* current = g_allocations_head;
    while (current != NULL) {
        AllocationInfo* next_node = current->next;
        free(current);
        current = next_node;
    }
    g_allocations_head = NULL; // Ensure head is NULL after cleanup

    printf("\n--- Memory Usage Summary ---\n");
    printf("Total bytes allocated: %zu\n", g_total_allocated_bytes);
    printf("Total bytes freed:     %zu\n", g_total_freed_bytes);
    printf("Net unfreed bytes:     %zu\n", g_total_allocated_bytes - g_total_freed_bytes);
    printf("--------------------------\n");
}

