    size_t size;
    const char *file;
    int line;
    struct Allocation *next;
} Allocation;

static Allocation *alloc_list = NULL;

// Internal function to add a new allocation to the list
void add_allocation(void *ptr, size_t size, const char *file, int line) {
    Allocation *node = (Allocation *)malloc(sizeof(Allocation));
    node->ptr = ptr;
    node->size = size;
    node->file = file;
    node->line = line;
    node->next = alloc_list;
    alloc_list = node;
}

// Internal function to remove an allocation from the list
void remove_allocation(void *ptr) {
    Allocation **p = &alloc_list, *tmp;
    while(*p) {
        if((*p)->ptr == ptr) {
            tmp = *p;
            *p = (*p)->next;
            free(tmp);
            return;
        }
        p = &(*p)->next;
    }
    fprintf(stderr, "Warning: Attempt to free untracked pointer %p\n", ptr);
}

// Allocation wrappers with file/line info
void *my_malloc(size_t size, const char *file, int line) {
    void *ptr = malloc(size);
    if(ptr) add_allocation(ptr, size, file, line);
    return ptr;
}

