MemoryBlock *head = NULL; // Head of the linked list to keep track of allocated memory.

void* my_malloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr != NULL) {
        MemoryBlock *block = (MemoryBlock *)malloc(sizeof(MemoryBlock));
        if (block != NULL) {
            block->ptr = ptr;
            block->size = size;
            block->next = head;
            head = block;
        } else {
            // If we cannot allocate a MemoryBlock, free the allocated memory.
            free(ptr);
            return NULL;
        }
    }
    return ptr;
}

void my_free(void *ptr) {
    if (ptr == NULL) return;

    MemoryBlock *current = head;
    MemoryBlock *prev = NULL;

    while (current != NULL) {
        if (current->ptr == ptr) {
            // Found the matching pointer; free the memory and remove from the list.
            free(ptr);
            if (prev == NULL) {
                // If this is the first block in the list.
                head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current); // Free the MemoryBlock itself.
            return;
        }
        prev = current;
        current = current->next;
    }
    // Pointer was not found; we may want to output an error message here.
    printf("Warning: Attempting to free untracked memory at %p\n", ptr);
}

void check_memory_leaks() {
    MemoryBlock *current = head;
    if (current == NULL) {
        printf("No memory leaks detected.\n");
        return;
    }

    printf("Memory leaks detected:\n");
    while (current != NULL) {
        printf("Leaked memory of size %zu at address %p\n", current->size, current->ptr);
        current = current->next;
    }
}

int main() {
    // Example usage of custom malloc/free functions
    char *data = (char *)my_malloc(100);
    // Intentionally not freeing the allocated memory to create a leak

    int *arr = (int *)my_malloc(10 * sizeof(int));
    my_free(arr); // Properly freeing the allocated array.

    // At the end of the program, check for memory leaks
    check_memory_leaks();

    // Clean up before exiting (not feasible for actual leaks but makes the example cleaner)
    // In a real scenario, you should free everything you've allocated.
    my_free(data); // Uncommenting this would not show a leak for `data`

    return 0;
}

