#include <string.h>

// Structure to keep track of allocated memory blocks
typedef struct MemoryBlock {
    void *ptr;
    size_t size;
    char *file;
    int line;
    struct MemoryBlock *next;
} MemoryBlock;

// Global head of the linked list of memory blocks
static MemoryBlock *head = NULL;

// Function to add a memory block to the list
void add_memory_block(void *ptr, size_t size, const char *file, int line) {
    MemoryBlock *new_block = (MemoryBlock *)malloc(sizeof(MemoryBlock));
    if (new_block == NULL) {
        fprintf(stderr, "Failed to allocate memory for memory block tracking\n");
        exit(1);
    }
    new_block->ptr = ptr;
    new_block->size = size;
    new_block->file = strdup(file);
    new_block->line = line;
    new_block->next = head;
    head = new_block;
}

// Function to remove a memory block from the list
void remove_memory_block(void *ptr) {
    MemoryBlock *current = head;
    MemoryBlock *previous = NULL;

    while (current != NULL) {
        if (current->ptr == ptr) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current->file);
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

// Custom malloc function
void *my_malloc(size_t size, const char *file, int line) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed at %s:%d\n", file, line);
        exit(1);
    }
    add_memory_block(ptr, size, file, line);
    return ptr;
}

// Custom free function
void my_free(void *ptr) {
    if (ptr == NULL) {
        return;
    }
    free(ptr);
    remove_memory_block(ptr);
}

// Function to report memory leaks
void report_memory_leaks() {
    MemoryBlock *current = head;
    while (current != NULL) {
        fprintf(stderr, "Memory leak detected: %zu bytes allocated at %s:%d\n",
                current->size, current->file, current->line);
        current = current->next;
    }
}

