    int *a = my_malloc(sizeof(int), __FILE__, __LINE__);
    int *b = my_malloc(sizeof(int) * 10, __FILE__, __LINE__);
    int *c = my_malloc(sizeof(int) * 100, __FILE__, __LINE__);

    *a = 1;
    my_free(a);

    // Intentionally not freeing b and c to demonstrate memory leak detection

    report_memory_leaks();

    return 0;
}

