// Function to encrypt a message using XOR with a key
void xor_encrypt(char* message, char* key) {
    int message_len = strlen(message);
    int key_len = strlen(key);
    int key_index = 0;

    // Iterate over each character in the message
    for (int i = 0; i < message_len; i++) {
        // XOR the current character with the current key character
        message[i] = message[i] ^ key[key_index];

        // Move to the next key character, wrapping around to the start if necessary
        key_index = (key_index + 1) % key_len;
    }
}

