// ASCII characters used for rendering, from darkest to lightest
const char* ASCII_CHARS[] = {
    " ", ".", ":", "-", "=", "+", "*", "#", "%", "@"
};
const int NUM_ASCII_CHARS = sizeof(ASCII_CHARS) / sizeof(ASCII_CHARS[0]);

// Function to map pixel intensity to ASCII character
char* getASCIIChar(int intensity) {
    int index = (intensity * NUM_ASCII_CHARS) / 256;
    return (char*)ASCII_CHARS[index];
}

// Function to convert image to ASCII art
int convertToASCIIArt(const char* imagePath, int maxWidth, int maxHeight) {
    // Initialize SDL
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("SDL could not initialize! SDL Error: %s\n", SDL_GetError());
        return 1;
    }

    // Initialize SDL_image
    int imgFlags = IMG_INIT_PNG | IMG_INIT_JPG;
    if (!(IMG_Init(imgFlags) & imgFlags)) {
        printf("SDL_image could not initialize! SDL_image Error: %s\n", IMG_GetError());
        return 1;
    }

    // Load image
    SDL_Surface* surface = IMG_Load(imagePath);
    if (!surface) {
        printf("Unable to load image %s! SDL_image Error: %s\n", imagePath, IMG_GetError());
        return 1;
    }

    // Convert surface to grayscale
    SDL_Surface* grayscaleSurface = SDL_CreateRGBSurface(
        0, surface->w, surface->h, 32, 0, 0, 0, 0
    );
    SDL_LockSurface(surface);
    SDL_LockSurface(grayscaleSurface);

    // Resize image while maintaining aspect ratio
    float aspectRatio = (float)surface->w / surface->h;
    int newWidth = maxWidth;
    int newHeight = maxWidth / aspectRatio;

    if (newHeight > maxHeight) {
        newHeight = maxHeight;
        newWidth = maxHeight * aspectRatio;
    }

    // Create output file
    FILE* outputFile = fopen("ascii_art.txt", "w");
    if (!outputFile) {
        printf("Could not create output file!\n");
        return 1;
    }

    // Process each pixel and convert to ASCII
    for (int y = 0; y < newHeight; y++) {
        for (int x = 0; x < newWidth; x++) {
            // Map source image coordinates
            int srcX = x * surface->w / newWidth;
            int srcY = y * surface->h / newHeight;

            // Get pixel color
            Uint32 pixel = ((Uint32*)surface->pixels)[srcY * surface->w + srcX];
            Uint8 r, g, b;
            SDL_GetRGB(pixel, surface->format, &r, &g, &b);

            // Convert to grayscale
            int intensity = (r + g + b) / 3;

            // Write ASCII character to file
            fprintf(outputFile, "%s", getASCIIChar(intensity));
        }
        fprintf(outputFile, "\n");
    }

    // Cleanup
    fclose(outputFile);
    SDL_FreeSurface(surface);
    SDL_FreeSurface(grayscaleSurface);
    IMG_Quit();
    SDL_Quit();

    printf("ASCII art generated successfully in ascii_art.txt!\n");
    return 0;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <image_path> [max_width] [max_height]\n", argv[0]);
        return 1;
    }

    // Set default dimensions
    int maxWidth = 100;
    int maxHeight = 50;

    // Allow optional width and height parameters
    if (argc >= 3) {
        maxWidth = atoi(argv[2]);
    }
    if (argc >= 4) {
        maxHeight = atoi(argv[3]);
    }

    // Convert image to ASCII art
    return convertToASCIIArt(argv[1], maxWidth, maxHeight);
}

