#include <stdio.h>
#include <stdlib.h>
#include <stdint.h> // For fixed-width integer types (uint8_t, uint16_t, uint32_t)
#include <string.h> // For strlen

// Define a struct for the BMP File Header (14 bytes)
// We'll read these fields individually to avoid padding issues with structs
// on different compilers/architectures, though __attribute__((packed)) could be used.
typedef struct {
    uint16_t bfType;       // "BM"
    uint32_t bfSize;       // File size in bytes
    uint16_t bfReserved1;  // Reserved, should be 0
    uint16_t bfReserved2;  // Reserved, should be 0
    uint32_t bfOffBits;    // Offset to pixel data
} BMPFileHeader;

// Define a struct for the BMP Info Header (40 bytes for BITMAPINFOHEADER)
typedef struct {
    uint32_t biSize;           // Size of this header in bytes
    int32_t biWidth;           // Image width in pixels
    int32_t biHeight;          // Image height in pixels
    uint16_t biPlanes;         // Number of color planes (must be 1)
    uint16_t biBitCount;       // Bits per pixel (e.g., 24 for true color)
    uint32_t biCompression;    // Compression method (0 for BI_RGB - no compression)
    uint32_t biSizeImage;      // Image size in bytes (can be 0 for BI_RGB)
    int32_t biXPelsPerMeter;   // Horizontal resolution
    int32_t biYPelsPerMeter;   // Vertical resolution
    uint32_t biClrUsed;        // Number of colors in the palette (0 for 24-bit)
    uint32_t biClrImportant;   // Number of important colors (0 for all)
} BMPInfoHeader;


// ASCII character set for mapping grayscale values.
// From lightest to darkest. You can experiment with different sets.
// This one has 69 characters.
const char *ASCII_CHARS = " .'`^\",:;Il!i><~+_-?][}{1)(|\\/tfjrxnuvczXYUJCLQ0OZmwqpdbkhao*#MW&8%B@$";

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <input_image.bmp>\n", argv[0]);
        return 1;
    }

    FILE *fp = fopen(argv[1], "rb");
    if (!fp) {
        perror("Error opening BMP file");
        return 1;
    }

    BMPFileHeader fileHeader;
    BMPInfoHeader infoHeader;

    // --- Read BMP File Header ---
    if (fread(&fileHeader.bfType, sizeof(fileHeader.bfType), 1, fp) != 1 ||
        fread(&fileHeader.bfSize, sizeof(fileHeader.bfSize), 1, fp) != 1 ||
        fread(&fileHeader.bfReserved1, sizeof(fileHeader.bfReserved1), 1, fp) != 1 ||
        fread(&fileHeader.bfReserved2, sizeof(fileHeader.bfReserved2), 1, fp) != 1 ||
        fread(&fileHeader.bfOffBits, sizeof(fileHeader.bfOffBits), 1, fp) != 1)
    {
        fprintf(stderr, "Error reading BMP file header.\n");
        fclose(fp);
        return 1;
    }

    if (fileHeader.bfType != 0x4D42) { // "BM" in little-endian is 0x4D42
        fprintf(stderr, "Not a valid BMP file (invalid signature).\n");
        fclose(fp);
        return 1;
    }

    // --- Read BMP Info Header ---
    if (fread(&infoHeader.biSize, sizeof(infoHeader.biSize), 1, fp) != 1 ||
        fread(&infoHeader.biWidth, sizeof(infoHeader.biWidth), 1, fp) != 1 ||
        fread(&infoHeader.biHeight, sizeof(infoHeader.biHeight), 1, fp) != 1 ||
        fread(&infoHeader.biPlanes, sizeof(infoHeader.biPlanes), 1, fp) != 1 ||
        fread(&infoHeader.biBitCount, sizeof(infoHeader.biBitCount), 1, fp) != 1 ||
        fread(&infoHeader.biCompression, sizeof(infoHeader.biCompression), 1, fp) != 1 ||
        fread(&infoHeader.biSizeImage, sizeof(infoHeader.biSizeImage), 1, fp) != 1 ||
        fread(&infoHeader.biXPelsPerMeter, sizeof(infoHeader.biXPelsPerMeter), 1, fp) != 1 ||
        fread(&infoHeader.biYPelsPerMeter, sizeof(infoHeader.biYPelsPerMeter), 1, fp) != 1 ||
        fread(&infoHeader.biClrUsed, sizeof(infoHeader.biClrUsed), 1, fp) != 1 ||
        fread(&infoHeader.biClrImportant, sizeof(infoHeader.biClrImportant), 1, fp) != 1)
    {
        fprintf(stderr, "Error reading BMP info header.\n");
        fclose(fp);
        return 1;
    }

    if (infoHeader.biBitCount != 24 || infoHeader.biCompression != 0) {
        fprintf(stderr, "Only 24-bit uncompressed BMP files are supported.\n");
        fclose(fp);
        return 1;
    }

    // Calculate row padding for 24-bit BMPs
    // Each row must be a multiple of 4 bytes.
    int row_stride = infoHeader.biWidth * 3; // 3 bytes per pixel (BGR)
    int padding = (4 - (row_stride % 4)) % 4;

    // Allocate memory for the entire image (BGR format)
    // BMP stores images bottom-up, so we'll read it into memory and then
    // iterate from the top row for printing.
    uint8_t *pixel_data = (uint8_t *)malloc(row_stride * infoHeader.biHeight + infoHeader.biHeight * padding);
    if (!pixel_data) {
        fprintf(stderr, "Error: Could not allocate memory for image data.\n");
        fclose(fp);
        return 1;
    }

    // Seek to the beginning of the pixel data
    fseek(fp, fileHeader.bfOffBits, SEEK_SET);

    // Read pixel data row by row
    for (int i = 0; i < infoHeader.biHeight; i++) {
        if (fread(&pixel_data[i * row_stride], 1, row_stride, fp) != (size_t)row_stride) {
             fprintf(stderr, "Error reading pixel data for row %d.\n", i);
             free(pixel_data);
             fclose(fp);
             return 1;
        }
        if (fseek(fp, padding, SEEK_CUR) != 0) {
             fprintf(stderr, "Error seeking past padding for row %d.\n", i);
             free(pixel_data);
             fclose(fp);
             return 1;
        }
    }

    fclose(fp); // File is no longer needed

    int ascii_chars_len = strlen(ASCII_CHARS);

    // Iterate through the pixels and convert to ASCII art
    // BMP stores bottom-up, so we iterate from height-1 down to 0 for top-down output
    for (int y = infoHeader.biHeight - 1; y >= 0; y--) {
        for (int x = 0; x < infoHeader.biWidth; x++) {
            // Pixels are BGR, so:
            uint8_t blue = pixel_data[(y * row_stride) + (x * 3) + 0];
            uint8_t green = pixel_data[(y * row_stride) + (x * 3) + 1];
            uint8_t red = pixel_data[(y * row_stride) + (x * 3) + 2];

            // Convert to grayscale using luminance formula
            // (More perceptually accurate than simple average)
            uint8_t grayscale = (uint8_t)(0.299 * red + 0.587 * green + 0.114 * blue);

            // Map grayscale value (0-255) to an index in the ASCII_CHARS string
            // 0 (black) maps to the darkest char (end of string)
            // 255 (white) maps to the lightest char (beginning of string)
            int char_index = (int)((double)grayscale / 255.0 * (ascii_chars_len - 1));

            // Print the ASCII character
            // Print twice for better aspect ratio on most consoles (chars are taller than wide)
            printf("%c%c", ASCII_CHARS[char_index], ASCII_CHARS[char_index]);
        }
        printf("\n"); // Newline after each row
    }

    free(pixel_data); // Clean up allocated memory
    return 0;
}

