#define MAX_ASCII_CHARS 70
// Used for mapping grayscale to ASCII characters (from dark to light)
const char ascii_chars[MAX_ASCII_CHARS + 1] =
    "$@B%8&WM#*oahkbdpqwmZO0QLCJUYXzcvunxrjft/\\|()1{}[]?-_+~<>i!lI;:,\"^`'. ";

void skip_comments(FILE *fp) {
    int ch;
    char line[1024];
    while ((ch = fgetc(fp)) != EOF && isspace(ch));
    if (ch == '#') {
        fgets(line, sizeof(line), fp);
        skip_comments(fp);
    } else {
        fseek(fp, -1, SEEK_CUR);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <input.pgm>\n", argv[0]);
        return 1;
    }

    FILE *fp = fopen(argv[1], "rb");
    if (!fp) {
        perror("Cannot open input file");
        return 1;
    }

    char magic[3];
    fscanf(fp, "%2s", magic);

    if (strcmp(magic, "P2") != 0 && strcmp(magic, "P5") != 0) {
        fprintf(stderr, "Unsupported PGM format. Only P2 and P5 are supported.\n");
        fclose(fp);
        return 1;
    }

    // Read width, height, maxval
    int width, height, maxval;
    skip_comments(fp);
    fscanf(fp, "%d", &width);
    skip_comments(fp);
    fscanf(fp, "%d", &height);
    skip_comments(fp);
    fscanf(fp, "%d", &maxval);
    fgetc(fp); // Skip a single whitespace/newline

    // Allocate pixel data
    unsigned char *data = (unsigned char *)malloc(width * height);
    if (!data) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(fp);
        return 1;
    }

    if (strcmp(magic, "P2") == 0) {
        // ASCII PGM
        for (int i = 0; i < width * height; i++) {
            int v = 0;
            fscanf(fp, "%d", &v);
            data[i] = (unsigned char)v;
        }
    } else {
        // Binary PGM
        fread(data, 1, width * height, fp);
    }

    fclose(fp);

    // Print ASCII Art
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            // Get grayscale, scale to ascii_chars
            int pixel = data[y * width + x];
            int idx = (pixel * MAX_ASCII_CHARS) / (maxval > 0 ? maxval : 255);
            if (idx > MAX_ASCII_CHARS) idx = MAX_ASCII_CHARS;
            putchar(ascii_chars[idx]);
        }
        putchar('\n');
    }

    free(data);
    return 0;
}

#include <stdio.h>
