char* grayToASCII = " .:-=+*%@#"; // From light to dark

void generateASCIIArt(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file.\n");
        return;
    }

    // Read the PGM file header
    char format[3];
    int width, height, maxVal;
    fscanf(file, "%2s", format);
    if (format[0] != 'P' || format[1] != '5') {
        fprintf(stderr, "Not a valid PGM format.\n");
        fclose(file);
        return;
    }

    // Skipping comments in the file if any
    char c = fgetc(file);
    while (c == '#') {
        while (fgetc(file) != '\n');
        c = fgetc(file);
    }
    ungetc(c, file);

    fscanf(file, "%d %d %d", &width, &height, &maxVal);
    fgetc(file); // Skip a single whitespace character after maxVal

    // Read pixel data
    unsigned char* imgData = (unsigned char*)malloc(width * height);
    fread(imgData, sizeof(unsigned char), width * height, file);
    fclose(file);

    // Convert pixel data to ASCII characters
    for (int i = 0; i < height; ++i) {
        for (int j = 0; j < width; ++j) {
            int pixelValue = imgData[i * width + j];
            float grayScale = (float)pixelValue / maxVal;
            int index = (int)(grayScale * (strlen(grayToASCII) - 1));
            printf("%c", grayToASCII[index]);
        }
        printf("\n");
    }

    free(imgData);
}

