#define WIDTH 80     // Width of the ASCII output
#define HEIGHT 40    // Height of the ASCII output
#define ASCII_CHARS "@%#*+=-:. "  // ASCII characters to map grayscale levels

typedef unsigned char BYTE;
typedef struct {
    BYTE r, g, b;
} Pixel;

// Function to map a grayscale value to an ASCII character
char mapToASCII(int value) {
    // Map the value (0-255) to the appropriate ASCII character
    int index = (value * (sizeof(ASCII_CHARS) - 1)) / 255; // Normalize to ASCII_CHAR range
    return ASCII_CHARS[index];
}

// Function to read a BMP file and convert it to ASCII art
void generateASCIIArt(const char *filename) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        perror("Error opening file");
        return;
    }

    // BMP header (54 bytes) + DIB header (40 bytes)
    fseek(fp, 18, SEEK_SET); // Move to width/height
    int width, height;
    fread(&width, sizeof(int), 1, fp);
    fread(&height, sizeof(int), 1, fp);

    printf("Width: %d, Height: %d\n", width, height);

    // Check if the output dimensions are valid
    if (width < WIDTH || height < HEIGHT) {
        printf("Image dimensions are too small for the ASCII art.\n");
        fclose(fp);
        return;
    }

    // Move to Pixel Data (Offset is 54 bytes but can vary, assuming 54 bytes here)
    fseek(fp, 54, SEEK_SET);

    // Read pixel data
    Pixel **pixels = malloc(height * sizeof(Pixel *));
    for (int i = 0; i < height; ++i) {
        pixels[i] = malloc(width * sizeof(Pixel));
        fread(pixels[i], sizeof(Pixel), width, fp);
    }

    // Create ASCII art
    printf("\nASCII Art:\n");
    for (int i = 0; i < height; i += (height / HEIGHT)) {
        for (int j = 0; j < width; j += (width / WIDTH)) {
            // Average RGB to get grayscale
            int gray = (pixels[i][j].r + pixels[i][j].g + pixels[i][j].b) / 3;
            putchar(mapToASCII(gray));
        }
        putchar('\n');
    }

    // Clean up
    for (int i = 0; i < height; ++i) {
        free(pixels[i]);
    }
    free(pixels);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <bmp file>\n", argv[0]);
        return 1;
    }

    generateASCIIArt(argv[1]);
    return 0;
}

