// Define a struct to represent an image
typedef struct {
    int width;
    int height;
    unsigned char *pixels;
} Image;

// Function to read a PGM image file
Image *read_pgm(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        return NULL;
    }

    char header[256];
    if (!fgets(header, 256, file) || strcmp(header, "P5\n")!= 0) {
        fclose(file);
        return NULL;
    }

    int width, height;
    if (fscanf(file, "%d %d\n", &width, &height)!= 2) {
        fclose(file);
        return NULL;
    }

    unsigned char max_value;
    if (fscanf(file, "%hhu\n", &max_value)!= 1) {
        fclose(file);
        return NULL;
    }

    unsigned char *pixels = malloc(width * height);
    if (fread(pixels, 1, width * height, file)!= width * height) {
        free(pixels);
        fclose(file);
        return NULL;
    }

    fclose(file);

    Image *image = malloc(sizeof(Image));
    image->width = width;
    image->height = height;
    image->pixels = pixels;

    return image;
}

// Function to generate ASCII art from an image
void generate_ascii(Image *image) {
    int width = image->width;
    int height = image->height;
    unsigned char *pixels = image->pixels;

    // Define ASCII characters used to create the ASCII art
    char ascii_chars[] = "@%#*+=-:. ";

    // Print ASCII art
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            unsigned char pixel = pixels[y * width + x];

            // Map pixel value to ASCII character
            int index = (int)((pixel / 255.0) * (sizeof(ascii_chars) - 2));

            printf("%c", ascii_chars[sizeof(ascii_chars) - 2 - index]);
        }
        printf("\n");
    }
}

int main() {
    const char *filename = "image.pgm";

    Image *image = read_pgm(filename);
    if (!image) {
        printf("Failed to read %s\n", filename);
        return 1;
    }

    generate_ascii(image);

    free(image->pixels);
    free(image);

    return 0;
}

