// ASCII characters used for rendering
const char *ascii_chars = " .'`^\",:;Il!i><~+_-?][}{1)(|\/tfjrxnuvczXYUJCLQ0OZMWK$@B%8&WM#*oahkbdpqwmzcvunxrjft\\|{}[]><i!lI;:,\",'^`'.";

// Function to read a grayscale PNG image
int read_grayscale_png(const char *filename, unsigned char **image_data, int *width, int *height) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        fprintf(stderr, "Failed to open file %s\n", filename);
        return 1;
    }

    png_structp png = png_create_read_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
    if (!png) {
        fclose(fp);
        fprintf(stderr, "Failed to create PNG read struct\n");
        return 1;
    }

    png_infop info = png_create_info_struct(png);
    if (!info) {
        png_destroy_read_struct(&png, NULL, NULL);
        fclose(fp);
        fprintf(stderr, "Failed to create PNG info struct\n");
        return 1;
    }

    if (setjmp(png_jmpbuf(png))) {
        png_destroy_read_struct(&png, &info, NULL);
        fclose(fp);
        fprintf(stderr, "Error during PNG read\n");
        return 1;
    }

    png_init_io(png, fp);
    png_read_info(png, info);

    *width = png_get_image_width(png, info);
    *height = png_get_image_height(png, info);
    int bit_depth = png_get_bit_depth(png, info);
    int color_type = png_get_color_type(png, info);

    // Convert to grayscale if not already
    if (color_type == PNG_COLOR_TYPE_RGB || color_type == PNG_COLOR_TYPE_RGB_ALPHA) {
        png_set_gray_to_rgb(png);
        png_set_strip_alpha(png);
        png_set_expand_gray_1_2_4_to_8(png);
    }

    png_read_update_info(png, info);
    int row_bytes = png_get_row_bytes(png, info);

    *image_data = (unsigned char *)malloc(row_bytes * *height);
    if (!*image_data) {
        png_destroy_read_struct(&png, &info, NULL);
        fclose(fp);
        fprintf(stderr, "Failed to allocate memory for image data\n");
        return 1;
    }

    png_bytepp rows = png_alloc_rows(png, *width, *height);
    for (int y = 0; y < *height; y++) {
        rows[y] = *image_data + y * row_bytes;
    }

    png_read_image(png, rows);
    png_read_end(png, NULL);

    png_destroy_read_struct(&png, &info, NULL);
    fclose(fp);

    // If the image was originally grayscale, convert back to single channel
    if (bit_depth == 8 && color_type == PNG_COLOR_TYPE_GRAY) {
        for (int y = 0; y < *height; y++) {
            for (int x = 0; x < *width; x++) {
                (*image_data)[y * *width + x] = (*image_data)[y * row_bytes + x * 3];
            }
        }
    }

    // Free allocated rows array
    png_free_rows(png, rows, *height);

    return 0;
}

// Function to convert grayscale value to ASCII character
char get_ascii_char(int grayscale_value) {
    int index = round(grayscale_value * (strlen(ascii_chars) - 1) / 255.0);
    return ascii_chars[index];
}

// Function to print ASCII art
void print_ascii_art(unsigned char *image_data, int width, int height) {
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            printf("%c", get_ascii_char(image_data[y * width + x]));
        }
        printf("\n");
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <grayscale_image_file>\n", argv[0]);
        return 1;
    }

    unsigned char *image_data;
    int width, height;

    if (read_grayscale_png(argv[1], &image_data, &width, &height)) {
        return 1;
    }

    print_ascii_art(image_data, width, height);

    free(image_data);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

// Maximum length of the L-system string
#define MAX_LENGTH 10000

// Structure to define L-system rules and parameters
typedef struct {
    char *axiom;       // Starting string
    char **rules;      // Rewriting rules
    int num_rules;     // Number of rules
    int iterations;    // Number of iterations
    double angle;      // Turning angle
} LSystem;

// Function to expand L-system string based on rules
char* expand_lsystem(LSystem *lsystem) {
    char *current = strdup(lsystem->axiom);
    char *next = malloc(MAX_LENGTH * sizeof(char));

    for (int iter = 0; iter < lsystem->iterations; iter++) {
        next[0] = '\0';
        int next_len = 0;

        for (int i = 0; current[i] != '\0'; i++) {
            int found_rule = 0;

            // Apply rewriting rules
            for (int j = 0; j < lsystem->num_rules; j++) {
                if (current[i] == lsystem->rules[j][0]) {
                    strcat(next, lsystem->rules[j] + 2);
                    next_len += strlen(lsystem->rules[j] + 2);
                    found_rule = 1;
                    break;
                }
            }

            // If no rule matches, keep the original character
            if (!found_rule) {
                next[next_len++] = current[i];
                next[next_len] = '\0';
            }
        }

        // Swap current and next strings
        char *temp = current;
        current = next;
        next = temp;
    }

    free(next);
    return current;
}

// Function to draw L-system fractal pattern
void draw_lsystem(char *pattern, double angle) {
    int width = 80;
    int height = 40;
    char canvas[height][width + 1];

    // Initialize canvas
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            canvas[y][x] = ' ';
        }
        canvas[y][width] = '\0';
    }

    // Current position and direction
    double x = width / 2.0;
    double y = height / 2.0;
    double current_angle = -90.0;  // Start pointing upwards

    // Drawing stack
    struct {
        double x, y, angle;
    } stack[1000];
    int stack_top = -1;

    // Draw the pattern
    for (int i = 0; pattern[i] != '\0'; i++) {
        switch (pattern[i]) {
            case 'F':  // Move forward and draw
                {
                    double new_x = x + cos(current_angle * M_PI / 180.0);
                    double new_y = y + sin(current_angle * M_PI / 180.0);

                    // Bresenham's line drawing algorithm
                    int x0 = round(x), y0 = round(y);
                    int x1 = round(new_x), y1 = round(new_y);
                    int dx = abs(x1 - x0), sx = x0 < x1 ? 1 : -1;
                    int dy = -abs(y1 - y0), sy = y0 < y1 ? 1 : -1;
                    int err = dx + dy;

                    while (1) {
                        if (x0 >= 0 && x0 < width && y0 >= 0 && y0 < height)
                            canvas[y0][x0] = '*';

                        if (x0 == x1 && y0 == y1) break;
                        int e2 = 2 * err;
                        if (e2 >= dy) { err += dy; x0 += sx; }
                        if (e2 <= dx) { err += dx; y0 += sy; }
                    }

                    x = new_x;
                    y = new_y;
                }
                break;
            case '+':  // Turn right
                current_angle += angle;
                break;
            case '-':  // Turn left
                current_angle -= angle;
                break;
            case '[':  // Save current state
                stack[++stack_top].x = x;
                stack[stack_top].y = y;
                stack[stack_top].angle = current_angle;
                break;
            case ']':  // Restore previous state
                x = stack[stack_top].x;
                y = stack[stack_top].y;
                current_angle = stack[stack_top].angle;
                stack_top--;
                break;
        }
    }

    // Print the canvas
    for (int y = 0; y < height; y++) {
        printf("%s\n", canvas[y]);
    }
}

