#define MAX_ITERATIONS 4
#define INITIAL_STRING "F"

// Function to apply the L-system rules
void apply_rules(const char *current, char *next) {
    int i = 0;
    while (*current) {
        if (*current == 'F') {
            strcat(next, "F+F-F-F+F");
        } else {
            strncat(next, current, 1);
        }
        current++;
    }
}

// Function to generate the L-system string
void generate_lsystem(char *lsystem, int iterations) {
    char next[10000] = ""; // Adjust size as needed
    strcpy(lsystem, INITIAL_STRING);

    for (int i = 0; i < iterations; i++) {
        apply_rules(lsystem, next);
        strcpy(lsystem, next);
        next[0] = '\0'; // Reset the next string
    }
}

// Function to draw the L-system in ASCII
void draw_lsystem(const char *lsystem, int angle) {
    int x = 0, y = 0;
    int direction = 0; // 0 degrees (right)

    for (const char *c = lsystem; *c; c++) {
        if (*c == 'F') {
            // Move forward
            switch (direction) {
                case 0: x++; break;
                case 90: y++; break;
                case 180: x--; break;
                case 270: y--; break;
            }
            printf("(%d, %d)\n", x, y);
        } else if (*c == '+') {
            // Turn right
            direction = (direction + angle) % 360;
        } else if (*c == '-') {
            // Turn left
            direction = (direction - angle + 360) % 360;
        }
    }
}

