}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h> // For sin, cos

// --- Constants ---
#define MAX_RULES 10
#define MAX_L_STRING_LEN 1000000 // Max length of generated L-system string
#define MAX_GRID_WIDTH 100
#define MAX_GRID_HEIGHT 100
#define TURTLE_STACK_SIZE 50    // Max nesting for [ ]
#define PI 3.14159265358979323846

// --- Data Structures ---

typedef struct {
    char key;
    char *value;
} Rule;

typedef struct {
    char *axiom;
    Rule rules[MAX_RULES];
    int num_rules;
    double angle_degrees;
    int generations;
} LSystem;

typedef struct {
    int x, y;
} Point;

typedef struct {
    Point pos;
    double angle_radians; // Angle in radians
} TurtleState;

// Simple stack for turtle states
typedef struct {
    TurtleState states[TURTLE_STACK_SIZE];
    int top;
} TurtleStack;

// Global grid
char grid[MAX_GRID_HEIGHT][MAX_GRID_WIDTH];
int min_x_drawn, max_x_drawn, min_y_drawn, max_y_drawn;

// --- Stack Operations ---

void initStack(TurtleStack *s) {
    s->top = -1;
}

void push(TurtleStack *s, TurtleState state) {
    if (s->top < TURTLE_STACK_SIZE - 1) {
        s->states[++s->top] = state;
    } else {
        fprintf(stderr, "Turtle stack overflow!\n");
    }
}

TurtleState pop(TurtleStack *s) {
    if (s->top >= 0) {
        return s->states[s->top--];
    } else {
        fprintf(stderr, "Turtle stack underflow!\n");
        // Return a dummy state or exit, depending on desired error handling
        TurtleState dummy = {{0,0}, 0.0};
        return dummy;
    }
}

// --- L-system Transformation ---

char* applyRules(const char *current_string, const LSystem *lsys) {
    size_t current_len = strlen(current_string);
    char *next_string = (char *)malloc(MAX_L_STRING_LEN);
    if (!next_string) {
        fprintf(stderr, "Memory allocation failed for next_string!\n");
        exit(EXIT_FAILURE);
    }
    next_string[0] = '\0'; // Initialize as empty string

    for (size_t i = 0; i < current_len; i++) {
        char current_char = current_string[i];
        int rule_applied = 0;
        for (int j = 0; j < lsys->num_rules; j++) {
            if (lsys->rules[j].key == current_char) {
                strcat(next_string, lsys->rules[j].value);
                rule_applied = 1;
                break;
            }
        }
        if (!rule_applied) {
            // If no rule applies, append the character as is
            size_t next_len = strlen(next_string);
            if (next_len + 1 < MAX_L_STRING_LEN) {
                next_string[next_len] = current_char;
                next_string[next_len + 1] = '\0';
            } else {
                fprintf(stderr, "Generated string too long. Truncating.\n");
                // You might want more sophisticated handling here
                break;
            }
        }
        if (strlen(next_string) >= MAX_L_STRING_LEN - 1) {
             fprintf(stderr, "Generated string reached max length. Truncating further expansion.\n");
             break;
        }
    }
    return next_string;
}

char* generateLSystemString(const LSystem *lsys) {
    char *current = strdup(lsys->axiom);
    if (!current) {
        fprintf(stderr, "Memory allocation failed for initial axiom!\n");
        exit(EXIT_FAILURE);
    }

    for (int gen = 0; gen < lsys->generations; gen++) {
        char *next = applyRules(current, lsys);
        free(current); // Free the previous generation string
        current = next;
        if (strlen(current) >= MAX_L_STRING_LEN - 1) {
             fprintf(stderr, "L-system string reached max length during generation %d. Stopping.\n", gen + 1);
             break;
        }
    }
    return current;
}

// --- Drawing ---

void initGrid() {
    for (int i = 0; i < MAX_GRID_HEIGHT; i++) {
        for (int j = 0; j < MAX_GRID_WIDTH; j++) {
            grid[i][j] = ' ';
        }
    }
    min_x_drawn = MAX_GRID_WIDTH;
    max_x_drawn = -1;
    min_y_drawn = MAX_GRID_HEIGHT;
    max_y_drawn = -1;
}

void markPoint(int x, int y, char c) {
    if (x >= 0 && x < MAX_GRID_WIDTH && y >= 0 && y < MAX_GRID_HEIGHT) {
        grid[y][x] = c; // Remember: grid[row][col] -> grid[y][x]
        if (x < min_x_drawn) min_x_drawn = x;
        if (x > max_x_drawn) max_x_drawn = x;
        if (y < min_y_drawn) min_y_drawn = y;
        if (y > max_y_drawn) max_y_drawn = y;
    }
}

void drawLine(Point p1, Point p2, char c) {
    int dx = abs(p2.x - p1.x);
    int dy = abs(p2.y - p1.y);
    int sx = (p1.x < p2.x) ? 1 : -1;
    int sy = (p1.y < p2.y) ? 1 : -1;
    int err = dx - dy;

    int current_x = p1.x;
    int current_y = p1.y;

    while (1) {
        markPoint(current_x, current_y, c);
        if (current_x == p2.x && current_y == p2.y) break;

        int e2 = 2 * err;
        if (e2 > -dy) {
            err -= dy;
            current_x += sx;
        }
        if (e2 < dx) {
            err += dx;
            current_y += sy;
        }
    }
}

void interpretAndDraw(const char *l_string, const LSystem *lsys) {
    initGrid();

    TurtleState current_turtle = {{MAX_GRID_WIDTH / 2, MAX_GRID_HEIGHT / 2}, -PI / 2.0}; // Start facing up
    TurtleStack stack;
    initStack(&stack);

    double angle_rad = lsys->angle_degrees * PI / 180.0; // Convert angle to radians

    markPoint(current_turtle.pos.x, current_turtle.pos.y, '*'); // Mark starting point

    for (size_t i = 0; i < strlen(l_string); i++) {
        char cmd = l_string[i];
        Point prev_pos = current_turtle.pos;

        switch (cmd) {
            case 'F':
            case 'G':
                current_turtle.pos.x += round(cos(current_turtle.angle_radians));
                current_turtle.pos.y += round(sin(current_turtle.angle_radians));
                drawLine(prev_pos, current_turtle.pos, '*'); // Draw path
                break;
            case '+': // Turn right
                current_turtle.angle_radians += angle_rad;
                break;
            case '-': // Turn left
                current_turtle.angle_radians -= angle_rad;
                break;
            case '[':
                push(&stack, current_turtle);
                break;
            case ']':
                current_turtle = pop(&stack);
                // Mark the point where the turtle reappears, if it's different
                if (current_turtle.pos.x != prev_pos.x || current_turtle.pos.y != prev_pos.y) {
                     markPoint(current_turtle.pos.x, current_turtle.pos.y, '*');
                }
                break;
            default:
                // Ignore other characters (e.g., 'X' in some systems)
                break;
        }
    }
}

void displayGrid() {
    // If nothing was drawn, or the min/max values are invalid
    if (min_x_drawn > max_x_drawn || min_y_drawn > max_y_drawn) {
        printf("No pattern drawn or pattern is outside grid boundaries '%dx%d'.\n", MAX_GRID_WIDTH, MAX_GRID_HEIGHT);
        return;
    }

    // Add a small border for better display
    int effective_min_x = (min_x_drawn > 0) ? min_x_drawn - 1 : 0;
    int effective_max_x = (max_x_drawn < MAX_GRID_WIDTH - 1) ? max_x_drawn + 1 : MAX_GRID_WIDTH - 1;
    int effective_min_y = (min_y_drawn > 0) ? min_y_drawn - 1 : 0;
    int effective_max_y = (max_y_drawn < MAX_GRID_HEIGHT - 1) ? max_y_drawn + 1 : MAX_GRID_HEIGHT - 1;

    printf("\n--- L-System Fractal Pattern ---\n");
    for (int i = effective_min_y; i <= effective_max_y; i++) {
        for (int j = effective_min_x; j <= effective_max_x; j++) {
            printf("%c", grid[i][j]);
        }
        printf("\n");
    }
    printf("------------------------------\n");
}

