#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAXLEN 16384
#define GRIDSIZE 80

// Directions: 0 = right, 1 = up, 2 = left, 3 = down
const int dx[4] = {1, 0, -1, 0};
const int dy[4] = {0, -1, 0, 1};

typedef struct {
    int x, y;      // Position
    int dir;       // Direction (0,1,2,3)
} Turtle;

// L-System string generation: Koch Curve
void lsystem(const char *axiom, const char *predecessor, const char *successor, int iter, char *out) {
    char temp1[MAXLEN], temp2[MAXLEN];
    strcpy(temp1, axiom);

    for (int i = 0; i < iter; ++i) {
        int j = 0;
        int len = strlen(temp1);
        for (int k = 0; k < len && j < MAXLEN - 1; ++k) {
            if (temp1[k] == predecessor[0]) {
                // Replace 'F'
                int ss = strlen(successor);
                if (j + ss < MAXLEN - 1) {
                    strcpy(&temp2[j], successor);
                    j += ss;
                }
            } else {
                temp2[j++] = temp1[k];
            }
        }
        temp2[j] = '\0';
        strcpy(temp1, temp2);
    }
    strcpy(out, temp1);
}

// Draw the L-system string onto grid
void draw(char *commands, char grid[GRIDSIZE][GRIDSIZE], int grid_w, int grid_h) {
    // Start at center
    Turtle t;
    t.x = grid_w / 2;
    t.y = grid_h / 2;
    t.dir = 0;  // Facing right

    int minx = t.x, maxx = t.x, miny = t.y, maxy = t.y;

    int len = strlen(commands);
    for (int i = 0; i < len; ++i) {
        char c = commands[i];
        if (c == 'F') {
            int nx = t.x + dx[t.dir];
            int ny = t.y + dy[t.dir];
            // Draw line:
            if (nx >= 0 && nx < grid_w && ny >= 0 && ny < grid_h)
                grid[ny][nx] = (t.dir % 2 == 0 ? '-' : '|');
            t.x = nx; t.y = ny;
            // Track bounding box
            if (t.x < minx) minx = t.x;
            if (t.x > maxx) maxx = t.x;
            if (t.y < miny) miny = t.y;
            if (t.y > maxy) maxy = t.y;
        }
        else if (c == '+') { t.dir = (t.dir + 1) % 4; }
        else if (c == '-') { t.dir = (t.dir + 3) % 4; }
        // else: ignore
    }

    // Optional: print only the used region
    printf("\nResulting fractal (approximate bounding box):\n");
    for (int y = miny-1; y <= maxy+1 && y < grid_h; ++y) {
        for (int x = minx-1; x <= maxx+1 && x < grid_w; ++x) {
            if (y >= 0 && x >= 0)
                putchar(grid[y][x]);
        }
        putchar('\n');
    }
}

int main() {
    // System: Koch Curve (right angle version for ASCII)
    const char *axiom = "F";
    const char *predecessor = "F";
    const char *successor = "F+F-F-F+F"; // Using only 90° angles

    int iterations;
    printf("Enter number of iterations (e.g., 2 or 3): ");
    scanf("%d", &iterations);

    char lsys[MAXLEN];
    lsystem(axiom, predecessor, successor, iterations, lsys);

    // Prepare grid
    char grid[GRIDSIZE][GRIDSIZE];
    for (int i = 0; i < GRIDSIZE; ++i)
        for (int j = 0; j < GRIDSIZE; ++j)
            grid[i][j] = ' ';

    draw(lsys, grid, GRIDSIZE, GRIDSIZE);

    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAX_ITERATIONS 5    // Max depth of the fractal
#define BUFFER_SIZE 10000   // Buffer size to hold generated string

void applyLSystemRules(char *current, char *next) {
    while (*current) {
        if (*current == 'A') {
            strcat(next, "B-A-B");
        } else if (*current == 'B') {
            strcat(next, "A+B+A");
        } else {
            strncat(next, current, 1);
        }
        current++;
    }
}

int main() {
    char axiom[] = "A";
    char current[BUFFER_SIZE];
    char next[BUFFER_SIZE];

    strcpy(current, axiom);

    for (int i = 0; i < MAX_ITERATIONS; i++) {
        memset(next, 0, BUFFER_SIZE);
        applyLSystemRules(current, next);
        strcpy(current, next);
    }

    printf("Generated L-System: %s\n", current);

    int x = 0, y = 0;
    int stack_x[BUFFER_SIZE], stack_y[BUFFER_SIZE];
    int stack_pointer = 0;
    char direction = 'R'; // R: Right, D: Down, L: Left, U: Up

    printf("\nResulting ASCII Art:\n");

    for (int i = 0; i < strlen(current); ++i) {
        char c = current[i];
        if (c == 'A' || c == 'B') {
            putchar('*'); // Draw a point on the pattern
        } else {
            putchar(' '); // Space between points
        }

        if (c == '+') {
            // Turn right
            direction = (direction == 'R') ? 'D' : ((direction == 'D') ? 'L' : ((direction == 'L') ? 'U' : 'R'));
        } else if (c == '-') {
            // Turn left
            direction = (direction == 'R') ? 'U' : ((direction == 'U') ? 'L' : ((direction == 'L') ? 'D' : 'R'));
        }

        switch (direction) {
            case 'R': x++; break;
            case 'L': x--; break;
            case 'U': y--; break;
            case 'D': y++; break;
        }

        // Newline for every row
        if (direction == 'U' || direction == 'D') {
            putchar('\n');
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXLEN 1024
#define MAXITERATIONS 10

typedef struct {
    char *axiom;
    char *rules[128]; // store rules for letters
    char *output;
} LSystem;

void initializeLSystem(LSystem *lSystem) {
    lSystem->axiom = "F";
    lSystem->rules['F'] = "F+F--F+F"; // Koch curve
    lSystem->output = malloc(MAXLEN);
    strcpy(lSystem->output, lSystem->axiom);
}

void generateLSystem(LSystem *lSystem, int iterations) {
    char newOutput[MAXLEN];
    for (int iter = 0; iter < iterations; iter++) {
        newOutput[0] = '\0'; // reset the new output
        for (int i = 0; i < strlen(lSystem->output); i++) {
            char currentChar = lSystem->output[i];
            if (lSystem->rules[currentChar] != NULL) {
                strcat(newOutput, lSystem->rules[currentChar]);
            } else {
                strncat(newOutput, &currentChar, 1);
            }
        }
        strcpy(lSystem->output, newOutput);
    }
}

void drawASCII(LSystem *lSystem) {
    int length = strlen(lSystem->output);
    printf("Output of L-system:\n");
    for (int i = 0; i < length; i++) {
        char currentChar = lSystem->output[i];
        if (currentChar == 'F') {
            printf("*"); // Drawing command for forward
        } else if (currentChar == '+') {
            printf("/"); // Turning right
        } else if (currentChar == '-') {
            printf("\\"); // Turning left
        } else {
            printf(" "); // For any other character
        }
    }
    printf("\n");
}

int main() {
    LSystem lSystem;
    initializeLSystem(&lSystem);

    int iterations;
    printf("Enter the number of iterations (0-%d): ", MAXITERATIONS);
    scanf("%d", &iterations);
    if (iterations < 0 || iterations > MAXITERATIONS) {
        printf("Invalid input.\n");
        return 1;
    }

    generateLSystem(&lSystem, iterations);
    drawASCII(&lSystem);

    free(lSystem.output); // Remember to free allocated memory
    return 0;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// Structure to store production rules
typedef struct {
    char symbol;
    char* result;
} production_rule;

// Function to apply production rules
void apply_rules(char* str, production_rule* rules, int num_rules) {
    char* new_str = (char*) malloc(strlen(str) * 2 + 1);
    char* ptr = new_str;

    for (char* c = str; *c; c++) {
        int found = 0;
        for (int i = 0; i < num_rules; i++) {
            if (*c == rules[i].symbol) {
                strcpy(ptr, rules[i].result);
                ptr += strlen(rules[i].result);
                found = 1;
                break;
            }
        }
        if (!found) {
            *ptr++ = *c;
        }
    }
    *ptr = '\0';

    strcpy(str, new_str);
    free(new_str);
}

// Function to draw the turtle graphics
void draw_turtle(char* str, int angle) {
    int x = 0, y = 0;
    char dir = 'N'; // N, S, E, W
    for (char* c = str; *c; c++) {
        switch (*c) {
        case 'F':
            switch (dir) {
            case 'N':
                y++;
                break;
            case 'S':
                y--;
                break;
            case 'E':
                x++;
                break;
            case 'W':
                x--;
                break;
            }
            break;
        case '+':
            switch (dir) {
            case 'N':
                dir = 'E';
                break;
            case 'S':
                dir = 'W';
                break;
            case 'E':
                dir = 'S';
                break;
            case 'W':
                dir = 'N';
                break;
            }
            break;
        case '-':
            switch (dir) {
            case 'N':
                dir = 'W';
                break;
            case 'S':
                dir = 'E';
                break;
            case 'E':
                dir = 'N';
                break;
            case 'W':
                dir = 'S';
                break;
            }
            break;
        }
    }
    printf("(%d, %d)\n", x, y);
}

int main() {
    // Define the production rules for the Koch Curve
    production_rule koch_rules[] = {
        {'F', "F+F--F+F"},
    };
    char koch_str[] = "F";
    int num_koch_rules = sizeof(koch_rules) / sizeof(koch_rules[0]);

    // Generate the Koch Curve
    for (int i = 0; i < 4; i++) {
        apply_rules(koch_str, koch_rules, num_koch_rules);
    }
    printf("Koch Curve:\n%s\n", koch_str);

    // Draw the Koch Curve using turtle graphics
    draw_turtle(koch_str, 60);

    // Define the production rules for the Sierpinski Triangle
    production_rule sierpinski_rules[] = {
        {'A', "+B-A-B+"},
        {'B', "-A+B+A-"},
    };
    char sierpinski_str[] = "A";
    int num_sierpinski_rules = sizeof(sierpinski_rules) / sizeof(sierpinski_rules[0]);

    // Generate the Sierpinski Triangle
    for (int i = 0; i < 5; i++) {
        apply_rules(sierpinski_str, sierpinski_rules, num_sierpinski_rules);
    }
    printf("\nSierpinski Triangle:\n%s\n", sierpinski_str);

    // Draw the Sierpinski Triangle using turtle graphics
    draw_turtle(sierpinski_str, 60);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ITERATIONS 10
#define MAX_LENGTH 10000

typedef struct {
    char axiom[100];
    int rules_count;
    char rules[50][50];
} LSystem;

void initialize_lsystem(LSystem *lsystem) {
    // Example: Koch Curve
    strcpy(lsystem->axiom, "F");
    lsystem->rules_count = 1;
    strcpy(lsystem->rules[0], "F=F+F-F-F+F");
}

void generate_lsystem(LSystem *lsystem, char *result, int iterations) {
    char buffer[MAX_LENGTH];
    strcpy(result, lsystem->axiom);

    for (int i = 0; i < iterations; i++) {
        strcpy(buffer, result);
        result[0] = '\0';

        for (int j = 0; buffer[j] != '\0'; j++) {
            int rule_found = 0;
            for (int k = 0; k < lsystem->rules_count; k++) {
                if (buffer[j] == lsystem->rules[k][0]) {
                    strcat(result, lsystem->rules[k] + 2);
                    rule_found = 1;
                    break;
                }
            }
            if (!rule_found) {
                strncat(result, &buffer[j], 1);
            }
        }
    }
}

void draw_lsystem(const char *lsystem, int angle) {
    int x = 0, y = 0;
    char dir = 'N';

    for (int i = 0; lsystem[i] != '\0'; i++) {
        switch (lsystem[i]) {
            case 'F':
                switch (dir) {
                    case 'N': y--; break;
                    case 'S': y++; break;
                    case 'E': x++; break;
                    case 'W': x--; break;
                }
                printf("Move to (%d, %d)\n", x, y);
                break;
            case '+':
                switch (dir) {
                    case 'N': dir = (angle == 60) ? 'E' : 'W'; break;
                    case 'S': dir = (angle == 60) ? 'W' : 'E'; break;
                    case 'E': dir = (angle == 60) ? 'S' : 'N'; break;
                    case 'W': dir = (angle == 60) ? 'N' : 'S'; break;
                }
                break;
            case '-':
                switch (dir) {
                    case 'N': dir = (angle == 60) ? 'W' : 'E'; break;
                    case 'S': dir = (angle == 60) ? 'E' : 'W'; break;
                    case 'E': dir = (angle == 60) ? 'N' : 'S'; break;
                    case 'W': dir = (angle == 60) ? 'S' : 'N'; break;
                }
                break;
        }
    }
}

int main() {
    LSystem lsystem;
    char result[MAX_LENGTH];

    initialize_lsystem(&lsystem);
    int iterations = 4; // Number of iterations
    int angle = 60; // Angle for rotation (60 degrees for Sierpinski Triangle, 90 degrees for Koch Curve)

    generate_lsystem(&lsystem, result, iterations);
    printf("L-system after %d iterations: %s\n", iterations, result);

    draw_lsystem(result, angle);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define PASSWORD_LENGTH 15

// Function to generate a random password
void generatePassword(char* password) {
    // Character sets to choose from
    const char lowercase[] = "abcdefghijklmnopqrstuvwxyz";
    const char uppercase[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    const char numbers[] = "0123456789";
    const char special[] = "!@#$%^&*()_+-=[]{}|;:,.<>?";

    // Seed the random number generator
    srand(time(NULL));

    // Ensure the password contains at least one character from each character set
    password[0] = lowercase[rand() % (sizeof(lowercase) - 1)];
    password[1] = uppercase[rand() % (sizeof(uppercase) - 1)];
    password[2] = numbers[rand() % (sizeof(numbers) - 1)];
    password[3] = special[rand() % (sizeof(special) - 1)];

    // Fill the rest of the password with random characters from all sets
    for (int i = 4; i < PASSWORD_LENGTH; i++) {
        // Choose a random character set
        int charSetChoice = rand() % 4;

        switch (charSetChoice) {
            case 0:
                password[i] = lowercase[rand() % (sizeof(lowercase) - 1)];
                break;
            case 1:
                password[i] = uppercase[rand() % (sizeof(uppercase) - 1)];
                break;
            case 2:
                password[i] = numbers[rand() % (sizeof(numbers) - 1)];
                break;
            case 3:
                password[i] = special[rand() % (sizeof(special) - 1)];
                break;
        }
    }

    // Null-terminate the password string
    password[PASSWORD_LENGTH] = '\0';
}

// Function to shuffle the password characters for more randomness
void shufflePassword(char* password) {
    for (int i = PASSWORD_LENGTH - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        char temp = password[i];
        password[i] = password[j];
        password[j] = temp;
    }
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Create a character array to store the password
    char password[PASSWORD_LENGTH + 1];

    // Generate the password
    generatePassword(password);

    // Shuffle the password for additional randomness
    shufflePassword(password);

    // Print the generated password
    printf("Generated Password: %s\n", password);

    return 0;
}

