    const char lowercase[] = "abcdefghijklmnopqrstuvwxyz";
    const char uppercase[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    const char numbers[] = "0123456789";
    const char special[] = "!@#$%^&*()_+-=[]{}|;:,.<>?";

    // Ensure at least one character from each set
    password[0] = lowercase[rand() % (sizeof(lowercase) - 1)];
    password[1] = uppercase[rand() % (sizeof(uppercase) - 1)];
    password[2] = numbers[rand() % (sizeof(numbers) - 1)];
    password[3] = special[rand() % (sizeof(special) - 1)];

    // Fill the rest of the password with random characters
    for (int i = 4; i < length; i++) {
        // Combine all character sets
        const char allChars[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-=[]{}|;:,.<>?";

        // Select a random character from the combined set
        password[i] = allChars[rand() % (sizeof(allChars) - 1)];
    }

    // Null-terminate the password string
    password[length] = '\0';
}

// Function to shuffle the password to make it more random
void shufflePassword(char* password, int length) {
    for (int i = length - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        char temp = password[i];
        password[i] = password[j];
        password[j] = temp;
    }
}

