#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Enum for different node types
typedef enum {
    NODE_NUMBER,
    NODE_BINARY_OP
} NodeType;

// Enum for binary operators
typedef enum {
    OP_ADD,
    OP_SUB,
    OP_MUL,
    OP_DIV
} Operator;

// AST Node structure
typedef struct ASTNode {
    NodeType type;
    union {
        // For number nodes
        int value;

        // For binary operation nodes
        struct {
            Operator op;
            struct ASTNode* left;
            struct ASTNode* right;
        } binary;
    } data;
} ASTNode;

// Function prototypes
ASTNode* createNumberNode(int value);
ASTNode* createBinaryOpNode(Operator op, ASTNode* left, ASTNode* right);
void printAST(ASTNode* node, int indent);
void freeAST(ASTNode* node);
ASTNode* parseExpression(char** input);
ASTNode* parseTerm(char** input);
ASTNode* parseFactor(char** input);
void skipWhitespace(char** input);

// Create a number node
ASTNode* createNumberNode(int value) {
    ASTNode* node = (ASTNode*)malloc(sizeof(ASTNode));
    node->type = NODE_NUMBER;
    node->data.value = value;
    return node;
}

// Create a binary operation node
ASTNode* createBinaryOpNode(Operator op, ASTNode* left, ASTNode* right) {
    ASTNode* node = (ASTNode*)malloc(sizeof(ASTNode));
    node->type = NODE_BINARY_OP;
    node->data.binary.op = op;
    node->data.binary.left = left;
    node->data.binary.right = right;
    return node;
}

// Print the AST with indentation
void printAST(ASTNode* node, int indent) {
    if (node == NULL) return;

    // Print indentation
    for (int i = 0; i < indent; i++) {
        printf("  ");
    }

    // Print node details
    if (node->type == NODE_NUMBER) {
        printf("Number: %d\n", node->data.value);
    } else if (node->type == NODE_BINARY_OP) {
        const char* opStr;
        switch (node->data.binary.op) {
            case OP_ADD: opStr = "+"; break;
            case OP_SUB: opStr = "-"; break;
            case OP_MUL: opStr = "*"; break;
            case OP_DIV: opStr = "/"; break;
        }
        printf("Binary Op: %s\n", opStr);

        // Recursively print left and right subtrees
        printAST(node->data.binary.left, indent + 1);
        printAST(node->data.binary.right, indent + 1);
    }
}

// Free the memory allocated for the AST
void freeAST(ASTNode* node) {
    if (node == NULL) return;

    if (node->type == NODE_BINARY_OP) {
        freeAST(node->data.binary.left);
        freeAST(node->data.binary.right);
    }

    free(node);
}

// Skip whitespace characters
void skipWhitespace(char** input) {
    while (**input && isspace(**input)) {
        (*input)++;
    }
}

// Parse factor (numbers or parenthesized expressions)
ASTNode* parseFactor(char** input) {
    skipWhitespace(input);

    // Parse number
    if (isdigit(**input)) {
        int value = 0;
        while (**input && isdigit(**input)) {
            value = value * 10 + (**input - '0');
            (*input)++;
        }
        return createNumberNode(value);
    }

    // Parse parenthesized expression
    if (**input == '(') {
        (*input)++;  // Skip opening parenthesis
        ASTNode* node = parseExpression(input);

        skipWhitespace(input);
        if (**input != ')') {
            printf("Error: Missing closing parenthesis\n");
            exit(1);
        }
        (*input)++;  // Skip closing parenthesis

        return node;
    }

    printf("Error: Invalid factor\n");
    exit(1);
}

// Parse term (multiplication and division)
ASTNode* parseTerm(char** input) {
    ASTNode* left = parseFactor(input);

    while (1) {
        skipWhitespace(input);

        if (**input == '*' || **input == '/') {
            Operator op = (**input == '*') ? OP_MUL : OP_DIV;
            (*input)++;  // Skip operator

            ASTNode* right = parseFactor(input);
            left = createBinaryOpNode(op, left, right);
        } else {
            break;
        }
    }

    return left;
}

// Parse expression (addition and subtraction)
ASTNode* parseExpression(char** input) {
    ASTNode* left = parseTerm(input);

    while (1) {
        skipWhitespace(input);

        if (**input == '+' || **input == '-') {
            Operator op = (**input == '+') ? OP_ADD : OP_SUB;
            (*input)++;  // Skip operator

            ASTNode* right = parseTerm(input);
            left = createBinaryOpNode(op, left, right);
        } else {
            break;
        }
    }

    return left;
}

int main() {
    char input[100];

    printf("Enter an arithmetic expression: ");
    fgets(input, sizeof(input), stdin);

    // Remove newline character
    input[strcspn(input, "\n")] = 0;

    char* ptr = input;
    ASTNode* ast = parseExpression(&ptr);

    printf("\nAbstract Syntax Tree:\n");
    printAST(ast, 0);

    // Free memory
    freeAST(ast);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

// AST node types
typedef enum {
    AST_NUMBER,
    AST_VARIABLE,
    AST_ADD,
    AST_SUBTRACT,
    AST_MULTIPLY,
    AST_DIVIDE
} ASTNodeType;

// AST node structure
typedef struct ASTNode {
    ASTNodeType type;
    union {
        int number;         // For AST_NUMBER
        char *variable;     // For AST_VARIABLE
    } value;
    struct ASTNode *left;   // Left child
    struct ASTNode *right;  // Right child
} ASTNode;

// Function prototypes
ASTNode *parse_expression();
ASTNode *parse_term();
ASTNode *parse_factor();
void free_ast(ASTNode *node);
void print_ast(ASTNode *node, int indent);
void expect(char expected);
void skip_whitespace();
char peek_next_char();

// Global variables for parsing
const char *input;
int position = 0;

// Create a new AST node
ASTNode *new_ast_node(ASTNodeType type) {
    ASTNode *node = (ASTNode *)malloc(sizeof(ASTNode));
    node->type = type;
    node->left = NULL;
    node->right = NULL;
    return node;
}

// Parse an arithmetic expression
ASTNode *parse_expression() {
    ASTNode *node = parse_term();

    while (1) {
        skip_whitespace();
        char op = peek_next_char();

        if (op == '+') {
            position++;
            ASTNode *new_node = new_ast_node(AST_ADD);
            new_node->left = node;
            new_node->right = parse_term();
            node = new_node;
        } else if (op == '-') {
            position++;
            ASTNode *new_node = new_ast_node(AST_SUBTRACT);
            new_node->left = node;
            new_node->right = parse_term();
            node = new_node;
        } else {
            break;
        }
    }

    return node;
}

// Parse a term (multiplication/division)
ASTNode *parse_term() {
    ASTNode *node = parse_factor();

    while (1) {
        skip_whitespace();
        char op = peek_next_char();

        if (op == '*') {
            position++;
            ASTNode *new_node = new_ast_node(AST_MULTIPLY);
            new_node->left = node;
            new_node->right = parse_factor();
            node = new_node;
        } else if (op == '/') {
            position++;
            ASTNode *new_node = new_ast_node(AST_DIVIDE);
            new_node->left = node;
            new_node->right = parse_factor();
            node = new_node;
        } else {
            break;
        }
    }

    return node;
}

// Parse a factor (number, variable, or parenthesized expression)
ASTNode *parse_factor() {
    skip_whitespace();
    char c = peek_next_char();

    if (isdigit(c)) {
        // Parse a number
        ASTNode *node = new_ast_node(AST_NUMBER);
        int num = 0;

        while (isdigit(peek_next_char())) {
            num = num * 10 + (input[position] - '0');
            position++;
        }

        node->value.number = num;
        return node;
    } else if (isalpha(c)) {
        // Parse a variable
        ASTNode *node = new_ast_node(AST_VARIABLE);
        int start = position;

        while (isalnum(peek_next_char())) {
            position++;
        }

        int len = position - start;
        node->value.variable = (char *)malloc(len + 1);
        strncpy(node->value.variable, input + start, len);
        node->value.variable[len] = '\0';
        return node;
    } else if (c == '(') {
        // Parse a parenthesized expression
        position++; // Skip '('
        ASTNode *node = parse_expression();
        skip_whitespace();
        expect(')');
        return node;
    } else {
        fprintf(stderr, "Unexpected character: %c\n", c);
        exit(1);
    }
}

// Helper function to check and consume the expected character
void expect(char expected) {
    skip_whitespace();
    if (peek_next_char() != expected) {
        fprintf(stderr, "Expected '%c' but found '%c'\n", expected, peek_next_char());
        exit(1);
    }
    position++;
}

// Skip whitespace characters
void skip_whitespace() {
    while (isspace(peek_next_char())) {
        position++;
    }
}

// Peek at the next character without consuming it
char peek_next_char() {
    return input[position];
}

// Free the memory used by the AST
void free_ast(ASTNode *node) {
    if (node == NULL) return;

    free_ast(node->left);
    free_ast(node->right);

    if (node->type == AST_VARIABLE) {
        free(node->value.variable);
    }

    free(node);
}

// Print the AST with indentation
void print_ast(ASTNode *node, int indent) {
    if (node == NULL) return;

    for (int i = 0; i < indent; i++) printf("  ");

    switch (node->type) {
        case AST_NUMBER:
            printf("NUMBER: %d\n", node->value.number);
            break;
        case AST_VARIABLE:
            printf("VARIABLE: %s\n", node->value.variable);
            break;
        case AST_ADD:
            printf("ADD\n");
            print_ast(node->left, indent + 1);
            print_ast(node->right, indent + 1);
            break;
        case AST_SUBTRACT:
            printf("SUBTRACT\n");
            print_ast(node->left, indent + 1);
            print_ast(node->right, indent + 1);
            break;
        case AST_MULTIPLY:
            printf("MULTIPLY\n");
            print_ast(node->left, indent + 1);
            print_ast(node->right, indent + 1);
            break;
        case AST_DIVIDE:
            printf("DIVIDE\n");
            print_ast(node->left, indent + 1);
            print_ast(node->right, indent + 1);
            break;
    }
}

int main() {
    char buffer[256];

    printf("Enter an arithmetic expression (e.g., 2*(3+x)): ");
    fgets(buffer, sizeof(buffer), stdin);

    // Remove newline if present
    buffer[strcspn(buffer, "\n")] = '\0';

    input = buffer;
    position = 0;

    ASTNode *ast = parse_expression();

    printf("\nAbstract Syntax Tree:\n");
    print_ast(ast, 0);

    free_ast(ast);
    return 0;
}

