#include <stdlib.h>
#include <ctype.h>

// AST node types
typedef enum {
    AST_NUMBER,
    AST_ADD,
    AST_SUB,
    AST_MUL,
    AST_DIV
} ASTNodeType;

// AST node structure
typedef struct ASTNode {
    ASTNodeType type;
    union {
        int value;  // for numbers
        struct {
            struct ASTNode *left, *right;
        } op; // for binary operators
    };
} ASTNode;

// Function prototypes
ASTNode* parse_expr();
ASTNode* parse_term();
ASTNode* parse_factor();
void skip_whitespace();
void print_ast(ASTNode *node, int indent);
void free_ast(ASTNode *node);

// Lexer global state
const char *input;
int pos = 0;

// Utility: skip whitespace
void skip_whitespace() {
    while (isspace(input[pos])) pos++;
}

// Utility: parse integer numbers
int parse_number() {
    skip_whitespace();
    int num = 0;
    int start = pos;
    while (isdigit(input[pos])) {
        num = num * 10 + (input[pos] - '0');
        pos++;
    }
    if (pos == start) {
        printf("Error: Expected a number at pos %d\n", pos);
        exit(1);
    }
    return num;
}

// Parse factor: NUMBER | '(' expr ')'
ASTNode* parse_factor() {
    skip_whitespace();
    if (input[pos] == '(') {
        pos++; // consume '('
        ASTNode* node = parse_expr();
        skip_whitespace();
        if (input[pos] != ')') {
            printf("Error: Expected ) at pos %d\n", pos);
            exit(1);
        }
        pos++; // consume ')'
        return node;
    } else {
        int value = parse_number();
        ASTNode *node = malloc(sizeof(ASTNode));
        node->type = AST_NUMBER;
        node->value = value;
        return node;
    }
}

// Parse term: factor (('*' | '/') factor)*
ASTNode* parse_term() {
    ASTNode* node = parse_factor();
    while (1) {
        skip_whitespace();
        if (input[pos] == '*') {
            pos++;
            ASTNode* right = parse_factor();
            ASTNode* newnode = malloc(sizeof(ASTNode));
            newnode->type = AST_MUL;
            newnode->op.left = node;
            newnode->op.right = right;
            node = newnode;
        } else if (input[pos] == '/') {
            pos++;
            ASTNode* right = parse_factor();
            ASTNode* newnode = malloc(sizeof(ASTNode));
            newnode->type = AST_DIV;
            newnode->op.left = node;
            newnode->op.right = right;
            node = newnode;
        } else {
            break;
        }
    }
    return node;
}

// Parse expr: term (('+' | '-') term)*
ASTNode* parse_expr() {
    ASTNode* node = parse_term();
    while (1) {
        skip_whitespace();
        if (input[pos] == '+') {
            pos++;
            ASTNode* right = parse_term();
            ASTNode* newnode = malloc(sizeof(ASTNode));
            newnode->type = AST_ADD;
            newnode->op.left = node;
            newnode->op.right = right;
            node = newnode;
        } else if (input[pos] == '-') {
            pos++;
            ASTNode* right = parse_term();
            ASTNode* newnode = malloc(sizeof(ASTNode));
            newnode->type = AST_SUB;
            newnode->op.left = node;
            newnode->op.right = right;
            node = newnode;
        } else {
            break;
        }
    }
    return node;
}

// Print AST (preorder, indented)
void print_ast(ASTNode *node, int indent) {
    for(int i=0; i<indent; i++) printf("  ");
    switch(node->type) {
        case AST_NUMBER:
            printf("Number(%d)\n", node->value);
            break;
        case AST_ADD:
            printf("Add\n");
            print_ast(node->op.left, indent+1);
            print_ast(node->op.right, indent+1);
            break;
        case AST_SUB:
            printf("Sub\n");
            print_ast(node->op.left, indent+1);
            print_ast(node->op.right, indent+1);
            break;
        case AST_MUL:
            printf("Mul\n");
            print_ast(node->op.left, indent+1);
            print_ast(node->op.right, indent+1);
            break;
        case AST_DIV:
            printf("Div\n");
            print_ast(node->op.left, indent+1);
            print_ast(node->op.right, indent+1);
            break;
    }
}

// Free the AST
void free_ast(ASTNode *node) {
    if (!node) return;
    if (node->type != AST_NUMBER) {
        free_ast(node->op.left);
        free_ast(node->op.right);
    }
    free(node);
}

int main() {
    char buffer[256];

    printf("Enter an arithmetic expression:\n");
    if (!fgets(buffer, sizeof(buffer), stdin)) return 1;

    input = buffer;
    pos = 0;

    ASTNode* root = parse_expr();

    skip_whitespace();
    if (input[pos] != '\0' && input[pos] != '\n') {
        printf("Error: Unexpected character: '%c'\n", input[pos]);
        free_ast(root);
        return 1;
    }

    printf("\nAbstract Syntax Tree:\n");
    print_ast(root, 0);

    free_ast(root);
    return 0;
}

