// Function to create a new number node
ASTNode *newNumNode(int value) {
    ASTNode *node = (ASTNode *)malloc(sizeof(ASTNode));
    node->type = NODE_NUM;
    node->data.num = value;
    return node;
}

// Function to create a new operator node
ASTNode *newOpNode(char operator, ASTNode *left, ASTNode *right) {
    ASTNode *node = (ASTNode *)malloc(sizeof(ASTNode));
    node->type = NODE_OP;
    node->data.op.op = operator;
    node->data.op.left = left;
    node->data.op.right = right;
    return node;
}

// Function to parse expression (for simplicity, assume expression is fully parenthesized)
ASTNode *parseExpression(const char **str) {
    while (isspace(**str)) (*str)++;

    if (**str == '(') {
        (*str)++; // Skip '('
        ASTNode *left = parseExpression(str);
        while (isspace(**str)) (*str)++;
        char operator = **str;
        (*str)++; // Skip operator
        ASTNode *right = parseExpression(str);
        while (isspace(**str)) (*str)++;
        if (**str == ')') {
            (*str)++; // Skip ')'
        }
        return newOpNode(operator, left, right);
    } else {
        int value = 0;
        while (isdigit(**str)) {
            value = value * 10 + (**str - '0');
            (*str)++;
        }
        return newNumNode(value);
    }
}

