// Enum for operator types
typedef enum {
    OP_ADD,
    OP_SUB,
    OP_MUL,
    OP_DIV,
    OP_NUM
} OpType;

// Structure for AST nodes
typedef struct Node {
    OpType type;
    int value;
    struct Node* left;
    struct Node* right;
} Node;

// Function to create a new node
Node* createNode(OpType type) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory error\n");
        exit(1);
    }
    newNode->type = type;
    newNode->left = NULL;
    newNode->right = NULL;
    return newNode;
}

// Function to create a number node
Node* createNumberNode(int value) {
    Node* newNode = createNode(OP_NUM);
    newNode->value = value;
    return newNode;
}

// Function to create an operator node
Node* createOpNode(OpType op, Node* left, Node* right) {
    Node* newNode = createNode(op);
    if (left) newNode->left = left;
    if (right) newNode->right = right;
    return newNode;
}

// Function to parse an expression and build the AST
Node* parseExpr(char** expr);

// Function to parse a term and build the AST
Node* parseTerm(char** expr);

// Function to parse a factor and build the AST
Node* parseFactor(char** expr);

// Function to skip whitespace
void skipWhitespace(char** expr) {
    while (**expr && isspace(**expr)) (*expr)++;
}

// Main parsing function
Node* parseExpr(char** expr) {
    Node* left = parseTerm(expr);
    skipWhitespace(expr);
    while (**expr && (**expr == '+' || **expr == '-')) {
        char op = **expr;
        (*expr)++;
        skipWhitespace(expr);
        Node* right = parseTerm(expr);
        left = createOpNode((op == '+') ? OP_ADD : OP_SUB, left, right);
        skipWhitespace(expr);
    }
    return left;
}

// Parse a term
Node* parseTerm(char** expr) {
    Node* left = parseFactor(expr);
    skipWhitespace(expr);
    while (**expr && (**expr == '*' || **expr == '/')) {
        char op = **expr;
        (*expr)++;
        skipWhitespace(expr);
        Node* right = parseFactor(expr);
        left = createOpNode((op == '*') ? OP_MUL : OP_DIV, left, right);
        skipWhitespace(expr);
    }
    return left;
}

// Parse a factor (number)
Node* parseFactor(char** expr) {
    if (isdigit(**expr)) {
        int value = 0;
        while (**expr && isdigit(**expr)) {
            value = value * 10 + (**expr - '0');
            (*expr)++;
        }
        return createNumberNode(value);
    }
    fprintf(stderr, "Error: Expected a number\n");
    exit(1);
}

// Function to print the AST
void printAST(Node* node, int indent) {
    if (!node) return;
    for (int i = 0; i < indent; i++) printf("  ");
    switch (node->type) {
        case OP_NUM:
            printf("Number: %d\n", node->value);
            break;
        case OP_ADD:
            printf("Add\n");
            printAST(node->left, indent + 1);
            printAST(node->right, indent + 1);
            break;
        case OP_SUB:
            printf("Subtract\n");
            printAST(node->left, indent + 1);
            printAST(node->right, indent + 1);
            break;
        case OP_MUL:
            printf("Multiply\n");
            printAST(node->left, indent + 1);
            printAST(node->right, indent + 1);
            break;
        case OP_DIV:
            printf("Divide\n");
            printAST(node->left, indent + 1);
            printAST(node->right, indent + 1);
            break;
        default:
            break;
    }
}

