// Monte Carlo integration function
double monte_carlo_integration(double a, double b, int num_samples) {
    // Initialize random seed
    srand(time(NULL));

    // Variables for Monte Carlo integration
    double total_sum = 0.0;
    double area_rectangle = (b - a);
    double max_y = 0.0;
    double min_y = 0.0;

    // Find the maximum and minimum values of the function in the interval
    int i;
    for (i = 0; i < 1000; i++) {
        double x = a + (b - a) * ((double)rand() / RAND_MAX);
        double y = f(x);

        if (y > max_y) max_y = y;
        if (y < min_y) min_y = y;
    }

    // Total rectangle area
    double total_area = area_rectangle * (max_y - min_y);

    // Perform Monte Carlo sampling
    int points_under_curve = 0;
    for (i = 0; i < num_samples; i++) {
        // Generate random x and y points within the rectangle
        double x = a + (b - a) * ((double)rand() / RAND_MAX);
        double y = min_y + (max_y - min_y) * ((double)rand() / RAND_MAX);

        // Check if the point is under the curve
        if (y <= f(x)) {
            points_under_curve++;
        }
    }

    // Calculate the integral estimate
    double integral_estimate = total_area * ((double)points_under_curve / num_samples);

    return integral_estimate;
}

