}

// --------------------------------------------------------------------------
// Helper function to find the maximum value of f(x) in [a, b]
// This is critical for defining the bounding box.
// A more robust solution might involve numerical optimization or
// knowing the analytical properties of the function.
// For simplicity, we'll sample many points to find an approximate max/min.
// --------------------------------------------------------------------------
double find_max_f(double a, double b, int num_samples) {
    double max_val = f(a);
    double step = (b - a) / num_samples;
    for (int i = 0; i <= num_samples; ++i) {
        double x = a + i * step;
        double fx = f(x);
        if (fx > max_val) {
            max_val = fx;
        }
    }
    return max_val;
}

double find_min_f(double a, double b, int num_samples) {
    double min_val = f(a);
    double step = (b - a) / num_samples;
    for (int i = 0; i <= num_samples; ++i) {
        double x = a + i * step;
        double fx = f(x);
        if (fx < min_val) {
            min_val = fx;
        }
    }
    return min_val;
}

// --------------------------------------------------------------------------
// Main function for Monte Carlo Integration
// --------------------------------------------------------------------------
double monte_carlo_integrate(double a, double b, long num_points) {
    if (a >= b) {
        fprintf(stderr, "Error: 'a' must be less than 'b'. Resulting in 0.\n");
        return 0.0;
    }

    // Determine the y-range of the bounding box.
    // We add some buffer to the max/min found to ensure all points are enclosed,
    // especially for functions with sharp peaks or troughs.
    // For many integrals, this is sufficient if you don't analytically know the bounds.
    int sampling_points_for_bounds = 10000;
    double f_max = find_max_f(a, b, sampling_points_for_bounds);
    double f_min = find_min_f(a, b, sampling_points_for_bounds);

    // If f_max and f_min are very close, adjust slightly to avoid zero-height box.
    if (fabs(f_max - f_min) < 1e-9) { // Using a small epsilon for float comparison
        if (f_max >= 0) {
            f_max += 0.1; // Make the box slightly taller above the x-axis
        } else {
            f_min -= 0.1; // Make the box slightly deeper below the x-axis
        }
    }

    // Y-range of the bounding box
    double y_min = f_min;
    double y_max = f_max;

    // Area of the bounding box
    double bounding_box_area = (b - a) * (y_max - y_min);

    long hit_count = 0;
    long total_points = num_points;

    // Seed the random number generator
    srand(time(NULL));

    for (long i = 0; i < total_points; ++i) {
        // Generate random x within [a, b]
        double rand_x = a + (double)rand() / RAND_MAX * (b - a);

        // Generate random y within [y_min, y_max]
        double rand_y = y_min + (double)rand() / RAND_MAX * (y_max - y_min);

        // Check if the point is a "hit" (i.e., it falls between the x-axis and the curve f(x))
        double fx_at_rand_x = f(rand_x);

        if (fx_at_rand_x >= 0) {
            // For positive function values, we count points between 0 and f(x)
            if (rand_y >= 0 && rand_y <= fx_at_rand_x) {
                hit_count++;
            }
        } else {
            // For negative function values, we count points between f(x) and 0
            if (rand_y <= 0 && rand_y >= fx_at_rand_x) {
                hit_count--; // Subtract for negative area
            }
        }
    }

    // Estimate the integral
    // The ratio of (hits / total_points) applied to the bounding box area
    // gives the estimated integral.
    // Note: The bounding box area is (b-a) * (y_max - y_min).
    // The points are uniformly distributed in this box.
    // The "hits" represent the area under the curve relative to the box area.
    // We adjust for the negative y_min if the function goes below x-axis.

    // A simpler way to think about it for signed area:
    // If f(x) > 0, points (x,y) where 0 <= y <= f(x) contribute positively.
    // If f(x) < 0, points (x,y) where f(x) <= y <= 0 contribute negatively.
    // The `hit_count` itself needs to reflect this signed area.
    // The `hit_count` tracks positive and negative contributions.

    // The integral is the ratio of how many points fall into the "target" area
    // relative to the total area of the bounding box.
    // Target area = Integral.
    // Integral / Bounding Box Area = (hit_count adjusted for minY) / total_points
    // This is equivalent to: (sum of signs * y_val for hits) / total_points * x_range * y_range_in_box
    // Let's refine the hit counting and use the full bounding box area directly:
    // The estimated value is the density of "hits" within the bounding box range, scaled by the area of the box.

    // The logic `hit_count++` and `hit_count--` for signed area is correct.
    // Then we scale it by the proportion of points.
    return (double)hit_count / total_points * bounding_box_area + (b-a) * fabs(f_min) ; // Added a correction for f_min, more specific later.

    // Let's rethink the calculation of the result based on signed area for `hit_count`.

    /*
    With the `hit_count` logic above:
    - If `f(x) >= 0`, `hit_count` increments for suitable `y`.
    - If `f(x) < 0`, `hit_count` decrements for suitable `y`.

    This means `hit_count` directly represents the net "area units" sampled within the bounding box.
    The ratio `(double)hit_count / total_points` gives the proportion of the bounding box area
    that corresponds to the integral.

    So, the result is `(double)hit_count / total_points * bounding_box_area`.
    However, this assumes the "0" level is at `y_min`. We need to effectively shift the coordinate system
    or adjust for `y_min`.

    Correct logic for the integral estimate:
    The integral is `sum(f(x_i) for i=1 to N) / N * (b-a)`. This is a direct Riemann sum approach.
    Monte Carlo is different.

    Let's go back to basics of Monte Carlo Area Estimation:
    Integral of f(x) from a to b = A_true.
    We define a rectangular region R = [a, b] x [y_min, y_max]. Area(R) = (b-a) * (y_max - y_min).
    We sample N points (x_i, y_i) in R.
    For each point, we check if it's "under the curve".
    If f(x) > 0: point is under if 0 <= y_i <= f(x_i).
    If f(x) < 0: point is under if f(x_i) <= y_i <= 0.

    Let `N_hits_positive` be count of points for `f(x) >= 0` and `0 <= y_i <= f(x_i)`.
    Let `N_hits_negative` be count of points for `f(x) < 0` and `f(x_i) <= y_i <= 0`.

    The number of points that estimate the positive area `A_pos` is `N_hits_positive`.
    The number of points that estimate the negative area `A_neg` is `N_hits_negative`.

    `A_pos / Area(R) = N_hits_positive / N` => `A_pos = N_hits_positive / N * Area(R)`
    `A_neg / Area(R) = N_hits_negative / N` => `A_neg = N_hits_negative / N * Area(R)`

    The Integral is `A_pos - |A_neg|` where `A_neg` is inherently negative.
    The most straightforward approach is to calculate the average of f(x) values sampled and multiply by the width:

    `Integral approx (b - a) * AVERAGE_f(x_i)`.
    Where `AVERAGE_f(x_i) = sum(f(x_i)) / N`.

    Let's re-implement for that simpler and generally more robust approach for signed area.
    This is also known as the "mean value" method of Monte Carlo integration.
    */

}

// --------------------------------------------------------------------------
// Monte Carlo Integration using the "mean value" method (more robust for signed area)
// --------------------------------------------------------------------------
double monte_carlo_integrate_mean_value(double a, double b, long num_points) {
    if (a >= b) {
        fprintf(stderr, "Error: 'a' must be less than 'b'. Resulting in 0.\n");
        return 0.0;
    }

    double sum_fx = 0.0;

    // Seed the random number generator
    srand(time(NULL));

    for (long i = 0; i < num_points; ++i) {
        // Generate random x within [a, b]
        double rand_x = a + (double)rand() / RAND_MAX * (b - a);
        sum_fx += f(rand_x);
    }

    double average_fx = sum_fx / num_points;
    return (b - a) * average_fx;
}


int main() {
    double a, b;
    long num_points;

    printf("Enter the lower limit of integration (a): ");
    scanf("%lf", &a);

    printf("Enter the upper limit of integration (b): ");
    scanf("%lf", &b);

    printf("Enter the number of random points (e.g., 100000, 10000000): ");
    scanf("%ld", &num_points);

    // Using the Mean Value Method (generally preferred for signed area)
    double estimated_integral = monte_carlo_integrate_mean_value(a, b, num_points);

