#define MAX_EXPRESSION_LENGTH 100
#define MAX_STACK_SIZE 100

// Stack for operators
typedef struct {
    char items[MAX_STACK_SIZE];
    int top;
} CharStack;

// Stack for numeric operands
typedef struct {
    double items[MAX_STACK_SIZE];
    int top;
} DoubleStack;

// Initialize character stack
void initCharStack(CharStack* stack) {
    stack->top = -1;
}

// Push character to stack
void pushChar(CharStack* stack, char c) {
    if (stack->top < MAX_STACK_SIZE - 1) {
        stack->items[++(stack->top)] = c;
    }
}

// Pop character from stack
char popChar(CharStack* stack) {
    if (stack->top >= 0) {
        return stack->items[(stack->top)--];
    }
    return '\0';
}

// Peek top character of stack
char peekChar(CharStack* stack) {
    if (stack->top >= 0) {
        return stack->items[stack->top];
    }
    return '\0';
}

// Initialize double stack
void initDoubleStack(DoubleStack* stack) {
    stack->top = -1;
}

// Push double to stack
void pushDouble(DoubleStack* stack, double value) {
    if (stack->top < MAX_STACK_SIZE - 1) {
        stack->items[++(stack->top)] = value;
    }
}

// Pop double from stack
double popDouble(DoubleStack* stack) {
    if (stack->top >= 0) {
        return stack->items[(stack->top)--];
    }
    return 0.0;
}

// Get operator precedence
int getPrecedence(char op) {
    switch (op) {
        case '+':
        case '-':
            return 1;
        case '*':
        case '/':
            return 2;
        case '^':
            return 3;
        default:
            return 0;
    }
}

// Check if character is an operator
int isOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/' || c == '^';
}

// Convert infix expression to postfix
void infixToPostfix(char* infix, char* postfix) {
    CharStack operatorStack;
    initCharStack(&operatorStack);
    int j = 0;

    for (int i = 0; infix[i] != '\0'; i++) {
        char c = infix[i];

        // Skip whitespace
        if (isspace(c)) continue;

        // If operand, add to postfix
        if (isdigit(c) || c == '.') {
            postfix[j++] = c;
        }
        // If opening parenthesis, push to stack
        else if (c == '(') {
            pushChar(&operatorStack, c);
        }
        // If closing parenthesis, pop operators until opening parenthesis
        else if (c == ')') {
            while (peekChar(&operatorStack) != '(') {
                postfix[j++] = popChar(&operatorStack);
            }
            popChar(&operatorStack); // Remove '('
        }
        // If operator
        else if (isOperator(c)) {
            // Add space to separate numbers
            postfix[j++] = ' ';

            // Pop operators with higher or equal precedence
            while (operatorStack.top >= 0 && 
                   peekChar(&operatorStack) != '(' && 
                   getPrecedence(peekChar(&operatorStack)) >= getPrecedence(c)) {
                postfix[j++] = popChar(&operatorStack);
            }
            pushChar(&operatorStack, c);
        }
    }

    // Pop remaining operators
    while (operatorStack.top >= 0) {
        postfix[j++] = popChar(&operatorStack);
    }

    postfix[j] = '\0';
}

// Evaluate postfix expression
double evaluatePostfix(char* postfix) {
    DoubleStack valueStack;
    initDoubleStack(&valueStack);

    for (int i = 0; postfix[i] != '\0'; i++) {
        char c = postfix[i];

        // Skip whitespace
        if (isspace(c)) continue;

        // If digit, parse number
        if (isdigit(c) || c == '.') {
            double num = strtod(&postfix[i], NULL);
            pushDouble(&valueStack, num);

            // Skip to end of number
            while (isdigit(postfix[i]) || postfix[i] == '.') {
                i++;
            }
            i--; // Counteract the increment in the for loop
        }
        // If operator, perform calculation
        else if (isOperator(c)) {
            double b = popDouble(&valueStack);
            double a = popDouble(&valueStack);

            switch (c) {
                case '+':
                    pushDouble(&valueStack, a + b);
                    break;
                case '-':
                    pushDouble(&valueStack, a - b);
                    break;
                case '*':
                    pushDouble(&valueStack, a * b);
                    break;
                case '/':
                    if (b != 0) {
                        pushDouble(&valueStack, a / b);
                    } else {
                        printf("Error: Division by zero\n");
                        return 0.0;
                    }
                    break;
                case '^':
                    pushDouble(&valueStack, pow(a, b));
                    break;
            }
        }
    }

    return popDouble(&valueStack);
}

int main() {
    char infix[MAX_EXPRESSION_LENGTH];
    char postfix[MAX_EXPRESSION_LENGTH];

    // Input expression
    printf("Enter an arithmetic expression: ");
    fgets(infix, sizeof(infix), stdin);

    // Remove newline character
    infix[strcspn(infix, "\n")] = '\0';

    // Convert to postfix
    infixToPostfix(infix, postfix);

    // Evaluate and print result
    printf("Postfix expression: %s\n", postfix);
    double result = evaluatePostfix(postfix);
    printf("Result: %f\n", result);

    return 0;
}

