// --- Global variables for parsing ---
static const char *expression_ptr; // Points to the current character in the expression string

// --- Function Prototypes ---
double parse_expression();
double parse_term();
double parse_factor();
double parse_number();
void skip_whitespace();
void match(char expected_char);

// --- Main Parsing Logic ---

// Parses an entire expression (e.g., "1 + 2 * 3 - 4 / 2")
// Handles addition and subtraction.
double parse_expression() {
    double value = parse_term(); // Start with a term

    skip_whitespace();
    while (*expression_ptr == '+' || *expression_ptr == '-') {
        char op = *expression_ptr;
        expression_ptr++; // Consume the operator
        skip_whitespace();
        double next_term = parse_term();

        if (op == '+') {
            value += next_term;
        } else { // op == '-'
            value -= next_term;
        }
        skip_whitespace();
    }
    return value;
}

// Parses a term (e.g., "2 * 3" or "4 / 2")
// Handles multiplication and division.
double parse_term() {
    double value = parse_factor(); // Start with a factor

    skip_whitespace();
    while (*expression_ptr == '*' || *expression_ptr == '/') {
        char op = *expression_ptr;
        expression_ptr++; // Consume the operator
        skip_whitespace();
        double next_factor = parse_factor();

        if (op == '*') {
            value *= next_factor;
        } else { // op == '/'
            if (next_factor == 0) {
                fprintf(stderr, "Error: Division by zero\n");
                exit(EXIT_FAILURE);
            }
            value /= next_factor;
        }
        skip_whitespace();
    }
    return value;
}

// Parses a factor (e.g., a number, or an expression in parentheses)
// Handles numbers and parentheses.
double parse_factor() {
    double value;
    skip_whitespace();

    if (*expression_ptr == '(') {
        expression_ptr++; // Consume '('
        value = parse_expression(); // Recursively parse the inner expression
        skip_whitespace();
        match(')'); // Ensure there's a closing parenthesis
    } else if (isdigit(*expression_ptr) || *expression_ptr == '.') {
        value = parse_number(); // Parse a number
    } else {
        fprintf(stderr, "Error: Unexpected character '%c' in expression\n", *expression_ptr);
        exit(EXIT_FAILURE);
    }
    return value;
}

// Parses a number (integer or floating-point)
double parse_number() {
    double result = 0.0;
    int decimal_point_seen = 0;
    double decimal_divisor = 1.0;

    skip_whitespace();

    // Handle leading sign if any (though typically handled by parse_expression for subtraction,
    // this could catch a unary minus if parse_factor was modified to allow it directly).
    // For simplicity, we'll assume numbers are positive or that unary minus is handled by subtraction.
    // If you need unary minus, you'd modify parse_factor to check for it before parse_number.

    while (isdigit(*expression_ptr) || (*expression_ptr == '.' && !decimal_point_seen)) {
        if (*expression_ptr == '.') {
            decimal_point_seen = 1;
            expression_ptr++;
        } else {
            if (!decimal_point_seen) {
                result = result * 10.0 + (*expression_ptr - '0');
            } else {
                decimal_divisor *= 10.0;
                result = result + (*expression_ptr - '0') / decimal_divisor;
            }
            expression_ptr++;
        }
    }
    return result;
}

// --- Helper Functions ---

// Skips any whitespace characters
void skip_whitespace() {
    while (isspace(*expression_ptr)) {
        expression_ptr++;
    }
}

// Consumes the expected character, or reports an error if it's not found
void match(char expected_char) {
    if (*expression_ptr == expected_char) {
        expression_ptr++;
    } else {
        fprintf(stderr, "Error: Expected '%c' but found '%c'\n", expected_char, *expression_ptr);
        exit(EXIT_FAILURE);
    }
}

// --- Main function to test the parser ---
int main() {
    char expression[256];
    double result;

    printf("Enter an arithmetic expression (e.g., 2 + 3 * 4 / 2 - (1 + 1)): \n");
    printf("Type 'exit' to quit.\n");

    while (fgets(expression, sizeof(expression), stdin) != NULL) {
        // Remove trailing newline character if present
        expression[strcspn(expression, "\n")] = '\0';

        if (strcmp(expression, "exit") == 0) {
            break;
        }

        // Initialize the global expression pointer
        expression_ptr = expression;

        // Try to parse and compute
        result = parse_expression();

        // After parsing, the expression_ptr should be at the null terminator,
        // or there are unparsed characters.
        skip_whitespace(); // Consume any trailing whitespace
        if (*expression_ptr != '\0') {
            fprintf(stderr, "Warning: Extra characters found after computation: '%s'\n", expression_ptr);
        } else {
            printf("Result: %lf\n", result);
        }
        printf("\nEnter another expression: \n");
    }

    return 0;
}

