#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX 100

typedef struct {
    int top;
    int items[MAX];
} Stack;

// Function to create a new stack
Stack* createStack() {
    Stack* s = (Stack*)malloc(sizeof(Stack));
    s->top = -1;
    return s;
}

// Function to check if the stack is empty
int isEmpty(Stack* s) {
    return s->top == -1;
}

// Function to push an item onto the stack
void push(Stack* s, int value) {
    if (s->top == MAX - 1) {
        printf("Stack overflow\n");
        return;
    }
    s->items[++(s->top)] = value;
}

// Function to pop an item from the stack
int pop(Stack* s) {
    if (isEmpty(s)) {
        printf("Stack underflow\n");
        return 0;   // error value
    }
    return s->items[(s->top)--];
}

// Function to peek the top item of the stack
int peek(Stack* s) {
    return s->items[s->top];
}

// Function to evaluate a basic arithmetic operation
int applyOperation(int a, int b, char operator) {
    switch (operator) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/': if (b != 0) return a / b; else {
            printf("Division by zero error\n");
            exit(EXIT_FAILURE);
        }
    }
    return 0;
}

// Function to check precedence of operators
int precedence(char operator) {
    switch (operator) {
        case '+':
        case '-': return 1;
        case '*':
        case '/': return 2;
        default: return 0;
    }
}

// Function to convert infix expression to postfix
void infixToPostfix(const char* expression, char* output) {
    Stack* stack = createStack();
    int outputIndex = 0;

    for (int i = 0; expression[i]; i++) {
        char current = expression[i];

        // If the character is a space, skip it
        if (isspace(current)) continue;

        // If the character is a number, add it to output
        if (isdigit(current)) {
            while (isdigit(expression[i])) {
                output[outputIndex++] = expression[i++];
            }
            output[outputIndex++] = ' '; // Add space to separate numbers
            i--; // Adjust for the extra increment
        }
        // If the character is '(', push it to stack
        else if (current == '(') {
            push(stack, current);
        }
        // If the character is ')', pop and output from the stack until '(' is found
        else if (current == ')') {
            while (!isEmpty(stack) && peek(stack) != '(') {
                output[outputIndex++] = pop(stack);
                output[outputIndex++] = ' ';
            }
            pop(stack); // Remove '(' from the stack
        }
        // If an operator is encountered
        else {
            while (!isEmpty(stack) && precedence(peek(stack)) >= precedence(current)) {
                output[outputIndex++] = pop(stack);
                output[outputIndex++] = ' ';
            }
            push(stack, current);
        }
    }

    // Pop all remaining operators from the stack
    while (!isEmpty(stack)) {
        output[outputIndex++] = pop(stack);
        output[outputIndex++] = ' ';
    }
    output[outputIndex] = '\0'; // Null-terminate the output
    free(stack);
}

// Function to evaluate postfix expression
int evaluatePostfix(const char* expression) {
    Stack* stack = createStack();

    for (int i = 0; expression[i]; i++) {
        char current = expression[i];

        // Skip spaces
        if (isspace(current)) continue;

        // If the character is a number, push it to the stack
        if (isdigit(current)) {
            int num = 0;
            while (isdigit(expression[i])) {
                num = num * 10 + (expression[i] - '0');
                i++;
            }
            push(stack, num);
            i--; // Adjust for the extra increment
        }
        // If the character is an operator, pop two elements and apply the operator
        else {
            int b = pop(stack);
            int a = pop(stack);
            int result = applyOperation(a, b, current);
            push(stack, result);
        }
    }

    int finalResult = pop(stack); // The result of the expression
    free(stack);
    return finalResult;
}

