// Define a structure to represent a token
typedef struct Token {
    char type; // '+' for addition, '-' for subtraction, '*' for multiplication, '/' for division, 'n' for number
    int value;
} Token;

// Function to get the next token from the input string
Token getNextToken(char **str) {
    Token token;

    // Skip whitespace
    while (**str && (**str == ' ' || **str == '\t' || **str == '\n'))
        (*str)++;

    if (**str == '\0') {
        token.type = '\0';
        return token;
    }

    if (**str >= '0' && **str <= '9') {
        token.type = 'n';
        token.value = 0;
        while (**str >= '0' && **str <= '9') {
            token.value = token.value * 10 + (**str - '0');
            (*str)++;
        }
    } else if (**str == '+' || **str == '-' || **str == '*' || **str == '/') {
        token.type = **str;
        (*str)++;
    } else {
        printf("Invalid character: %c\n", **str);
        exit(1);
    }

    return token;
}

// Function to evaluate an arithmetic expression
int evaluate(char *str) {
    char *tempStr = str;
    Token token = getNextToken(&tempStr);

    // Base case: if the token is a number, return its value
    if (token.type == 'n')
        return token.value;

    // If the token is not a number, it should be an operator
    int leftValue = evaluate(str);
    tempStr = tempStr + 1; // move past the operator
    token = getNextToken(&tempStr);

    // Recursively evaluate the right operand
    int rightValue = evaluate(tempStr);

    // Apply the operator
    switch (token.type) {
        case '+':
            return leftValue + rightValue;
        case '-':
            return leftValue - rightValue;
        case '*':
            return leftValue * rightValue;
        case '/':
            if (rightValue == 0) {
                printf("Error: division by zero\n");
                exit(1);
            }
            return leftValue / rightValue;
        default:
            printf("Error: unknown operator\n");
            exit(1);
    }
}

int main() {
    char expression[] = "2+3*4";
    int result = evaluate(expression);
    printf("Result: %d\n", result);

    return 0;
}

#include <stdio.h>
