#define MAX_EXPRESSION_LENGTH 100
#define MAX_STACK_SIZE 100

typedef struct {
    int items[MAX_STACK_SIZE];
    int top;
} Stack;

void initStack(Stack *s) {
    s->top = -1;
}

int isStackEmpty(Stack *s) {
    return s->top == -1;
}

int isStackFull(Stack *s) {
    return s->top == MAX_STACK_SIZE - 1;
}

void push(Stack *s, int item) {
    if (isStackFull(s)) {
        printf("Stack overflow\n");
        exit(1);
    }
    s->items[++(s->top)] = item;
}

int pop(Stack *s) {
    if (isStackEmpty(s)) {
        printf("Stack underflow\n");
        exit(1);
    }
    return s->items[(s->top)--];
}

int peek(Stack *s) {
    if (isStackEmpty(s)) {
        return -1;
    }
    return s->items[s->top];
}

int applyOperator(int a, int b, char op) {
    switch (op) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/': return a / b;
        default: printf("Invalid operator\n"); exit(1);
    }
}

int precedence(char op) {
    switch (op) {
        case '+':
        case '-': return 1;
        case '*':
        case '/': return 2;
        default: return 0;
    }
}

int evaluateExpression(char *expression) {
    Stack values;
    Stack operators;
    initStack(&values);
    initStack(&operators);

    for (int i = 0; i < strlen(expression); i++) {
        if (isspace(expression[i])) {
            continue;
        }

        if (isdigit(expression[i])) {
            int value = 0;
            while (isdigit(expression[i])) {
                value = value * 10 + (expression[i] - '0');
                i++;
            }
            i--;
            push(&values, value);
        } else if (expression[i] == '(') {
            push(&operators, expression[i]);
        } else if (expression[i] == ')') {
            while (!isStackEmpty(&operators) && peek(&operators) != '(') {
                int val2 = pop(&values);
                int val1 = pop(&values);
                char op = pop(&operators);
                int result = applyOperator(val1, val2, op);
                push(&values, result);
            }
            pop(&operators); // Pop '('
        } else if (expression[i] == '+' || expression[i] == '-' || expression[i] == '*' || expression[i] == '/') {
            while (!isStackEmpty(&operators) && precedence(peek(&operators)) >= precedence(expression[i])) {
                int val2 = pop(&values);
                int val1 = pop(&values);
                char op = pop(&operators);
                int result = applyOperator(val1, val2, op);
                push(&values, result);
            }
            push(&operators, expression[i]);
        }
    }

    while (!isStackEmpty(&operators)) {
        int val2 = pop(&values);
        int val1 = pop(&values);
        char op = pop(&operators);
        int result = applyOperator(val1, val2, op);
        push(&values, result);
    }

    return pop(&values);
}

int main() {
    char expression[MAX_EXPRESSION_LENGTH];
    printf("Enter a simple arithmetic expression: ");
    fgets(expression, MAX_EXPRESSION_LENGTH, stdin);
    expression[strcspn(expression, "\n")] = 0; // Remove newline character

    int result = evaluateExpression(expression);
    printf("Result: %d\n", result);

    return 0;
}

