// Main parsing and evaluation function
double parseExpression(char** expr) {
    double value = parseTerm(expr);

    // Handle subtraction
    while (**expr == '-') {
        (*expr)++;  // Move past '-'
        double term = parseTerm(expr);
        value -= term;
    }

    return value;
}

// Parse multiplication and terms
double parseTerm(char** expr) {
    double value = parseFactor(expr);

    // Handle multiplication
    while (**expr == '*') {
        (*expr)++;  // Move past '*'
        double factor = parseFactor(expr);
        value *= factor;
    }

    return value;
}

// Parse factors (variables or parenthesized expressions)
double parseFactor(char** expr) {
    skipWhitespace(expr);

    // Handle variables
    if (isalpha(**expr)) {
        char var = **expr;
        (*expr)++;

        // Return corresponding value based on variable
        switch (var) {
            case 'x': return 2.0;  // Example value for x
            case 'y': return 3.0;  // Example value for y
            case 'z': return 4.0;  // Example value for z
            case 'w': return 1.0;  // Example value for w
            default:
                printf("Unknown variable: %c\n", var);
                return 0.0;
        }
    }

    // Handle parenthesized expressions
    if (**expr == '(') {
        (*expr)++;  // Move past '('
        double value = parseExpression(expr);

        if (**expr != ')') {
            printf("Expected closing parenthesis\n");
            return 0.0;
        }

        (*expr)++;  // Move past ')'
        return value;
    }

    printf("Unexpected character: %c\n", **expr);
    return 0.0;
}

// Skip whitespace characters
void skipWhitespace(char** expr) {
    while (isspace(**expr)) {
        (*expr)++;
    }
}

