#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h> // For isdigit(), isalpha()

// --- 1. Define Node Types for the Abstract Syntax Tree (AST) ---

// Enum to represent different types of nodes in our expression tree
typedef enum {
    NODE_TYPE_NUMBER,
    NODE_TYPE_VARIABLE,
    NODE_TYPE_OPERATOR
} NodeType;

// Enum to represent different operators
typedef enum {
    OP_ADD,
    OP_SUBTRACT,
    OP_MULTIPLY,
    OP_DIVIDE // Not in the original expression, but good to include for generality
} OperatorType;

// Structure for a node in the expression tree
typedef struct Node {
    NodeType type;
    union {
        double value;           // For NODE_TYPE_NUMBER
        char varName;           // For NODE_TYPE_VARIABLE (e.g., 'x', 'y')
        OperatorType op;        // For NODE_TYPE_OPERATOR
    } data;
    struct Node *left;      // Left child for operations
    struct Node *right;     // Right child for operations
} Node;

// --- 2. Lexer (Tokenizer) ---
// Breaks the input string into a stream of tokens

typedef enum {
    TOKEN_NUMBER,
    TOKEN_VARIABLE,
    TOKEN_OPERATOR,
    TOKEN_LPAREN,
    TOKEN_RPAREN,
    TOKEN_END
} TokenType;

typedef struct {
    TokenType type;
    union {
        double value;
        char varName;
        char opChar; // Store +, -, *, /
    } data;
} Token;

char *input_ptr; // Global pointer to traverse the input string

// Function to get the next token
Token get_next_token() {
    Token token;

    // Skip whitespace
    while (*input_ptr != '\0' && isspace(*input_ptr)) {
        input_ptr++;
    }

    if (*input_ptr == '\0') {
        token.type = TOKEN_END;
        return token;
    }

    if (isdigit(*input_ptr)) {
        token.type = TOKEN_NUMBER;
        token.data.value = strtod(input_ptr, &input_ptr); // Reads the whole number
    } else if (isalpha(*input_ptr)) {
        token.type = TOKEN_VARIABLE;
        token.data.varName = *input_ptr;
        input_ptr++;
    } else {
        token.type = TOKEN_OPERATOR; // Default to operator for now, check specifics
        token.data.opChar = *input_ptr;
        switch (*input_ptr) {
            case '+':
            case '-':
            case '*':
            case '/':
            case '(':
                token.type = (*input_ptr == '(') ? TOKEN_LPAREN : TOKEN_OPERATOR;
                input_ptr++;
                break;
            case ')':
                token.type = TOKEN_RPAREN;
                input_ptr++;
                break;
            default:
                fprintf(stderr, "Error: Unexpected character '%c'\n", *input_ptr);
                exit(EXIT_FAILURE);
        }
    }
    return token;
}

Token current_token; // Global variable to hold the current token

void consume_token() {
    current_token = get_next_token();
}

// --- 3. Parser (Recursive Descent) ---
// Builds the AST from the token stream

// Function prototypes to handle operator precedence
Node *parse_expression();
Node *parse_term();
Node *parse_factor();

// Helper to create new nodes
Node *create_node(NodeType type) {
    Node *node = (Node *)malloc(sizeof(Node));
    if (!node) {
        perror("Failed to allocate node");
        exit(EXIT_FAILURE);
    }
    node->type = type;
    node->left = NULL;
    node->right = NULL;
    return node;
}

Node *create_number_node(double value) {
    Node *node = create_node(NODE_TYPE_NUMBER);
    node->data.value = value;
    return node;
}

Node *create_variable_node(char varName) {
    Node *node = create_node(NODE_TYPE_VARIABLE);
    node->data.varName = varName;
    return node;
}

Node *create_operator_node(OperatorType op, Node *left, Node *right) {
    Node *node = create_node(NODE_TYPE_OPERATOR);
    node->data.op = op;
    node->left = left;
    node->right = right;
    return node;
}

// factor = number | variable | "(" expression ")"
Node *parse_factor() {
    Node *node = NULL;
    if (current_token.type == TOKEN_NUMBER) {
        node = create_number_node(current_token.data.value);
        consume_token();
    } else if (current_token.type == TOKEN_VARIABLE) {
        node = create_variable_node(current_token.data.varName);
        consume_token();
    } else if (current_token.type == TOKEN_LPAREN) {
        consume_token(); // Consume '('
        node = parse_expression();
        if (current_token.type != TOKEN_RPAREN) {
            fprintf(stderr, "Error: Expected ')' but found token type %d\n", current_token.type);
            exit(EXIT_FAILURE);
        }
        consume_token(); // Consume ')'
    } else {
        fprintf(stderr, "Error: Unexpected token in factor production (type: %d)\n", current_token.type);
        exit(EXIT_FAILURE);
    }
    return node;
}

// term = factor ( ( "*" | "/" ) factor )*
Node *parse_term() {
    Node *node = parse_factor();
    while (current_token.type == TOKEN_OPERATOR &&
           (current_token.data.opChar == '*' || current_token.data.opChar == '/')) {
        char op_char = current_token.data.opChar;
        consume_token(); // Consume operator
        Node *right_node = parse_factor();
        node = create_operator_node((op_char == '*') ? OP_MULTIPLY : OP_DIVIDE, node, right_node);
    }
    return node;
}

// expression = term ( ( "+" | "-" ) term )*
Node *parse_expression() {
    Node *node = parse_term();
    while (current_token.type == TOKEN_OPERATOR &&
           (current_token.data.opChar == '+' || current_token.data.opChar == '-')) {
        char op_char = current_token.data.opChar;
        consume_token(); // Consume operator
        Node *right_node = parse_term();
        node = create_operator_node((op_char == '+') ? OP_ADD : OP_SUBTRACT, node, right_node);
    }
    return node;
}

// --- 4. Evaluation ---
// Traverses the AST to compute the result

typedef struct {
    char varName;
    double value;
} Variable;

// A simple approach: an array of variables. For more complex scenarios, a hash map is better.
Variable variables[4]; // Enough for x, y, z, w
int num_variables = 0;

void set_variable(char name, double value) {
    for (int i = 0; i < num_variables; i++) {
        if (variables[i].varName == name) {
            variables[i].value = value;
            return;
        }
    }
    if (num_variables < 4) {
        variables[num_variables].varName = name;
        variables[num_variables].value = value;
        num_variables++;
    } else {
        fprintf(stderr, "Error: Too many variables, limit is 4.\n");
        exit(EXIT_FAILURE);
    }
}

double get_variable_value(char name) {
    for (int i = 0; i < num_variables; i++) {
        if (variables[i].varName == name) {
            return variables[i].value;
        }
    }
    fprintf(stderr, "Error: Variable '%c' not defined.\n", name);
    exit(EXIT_FAILURE);
    return 0.0; // Should not reach here
}

double evaluate_ast(Node *node) {
    if (!node) {
        return 0.0; // Or handle error
    }

    switch (node->type) {
        case NODE_TYPE_NUMBER:
            return node->data.value;
        case NODE_TYPE_VARIABLE:
            return get_variable_value(node->data.varName);
        case NODE_TYPE_OPERATOR:
            {
                double left_val = evaluate_ast(node->left);
                double right_val = evaluate_ast(node->right);
                switch (node->data.op) {
                    case OP_ADD:
                        return left_val + right_val;
                    case OP_SUBTRACT:
                        return left_val - right_val;
                    case OP_MULTIPLY:
                        return left_val * right_val;
                    case OP_DIVIDE:
                        if (right_val == 0) {
                            fprintf(stderr, "Error: Division by zero!\n");
                            exit(EXIT_FAILURE);
                        }
                        return left_val / right_val;
                    default:
                        fprintf(stderr, "Error: Unknown operator type.\n");
                        exit(EXIT_FAILURE);
                }
            }
        default:
            fprintf(stderr, "Error: Unknown node type.\n");
            exit(EXIT_FAILURE);
    }
}

// --- 5. Memory Management (Freeing the AST) ---

void free_ast(Node *node) {
    if (node == NULL) {
        return;
    }
    free_ast(node->left);
    free_ast(node->right);
    free(node);
}

// --- Main Program ---

int main() {
    char *expression_str = "x*(y+z)-w"; // The target expression

    // Define values for variables
    set_variable('x', 10.0);
    set_variable('y', 5.0);
    set_variable('z', 2.0);
    set_variable('w', 3.0);

    printf("Expression: %s\n", expression_str);
    printf("Variables: x=%.2f, y=%.2f, z=%.2f, w=%.2f\n\n",
           get_variable_value('x'),
           get_variable_value('y'),
           get_variable_value('z'),
           get_variable_value('w'));

    // 1. Initialize input pointer for lexer
    input_ptr = expression_str;

    // 2. Get the first token
    consume_token();

    // 3. Parse the expression into an AST
    Node *ast_root = parse_expression();

    // Check if parsing consumed all expected tokens
    if (current_token.type != TOKEN_END) {
        fprintf(stderr, "Error: Extra tokens found after parsing expression.\n");
        // Optionally print remaining tokens for debugging
    }

    // 4. Evaluate the AST
    double result = evaluate_ast(ast_root);

    printf("Result: %.2f\n", result); // Expected: 10 * (5 + 2) - 3 = 10 * 7 - 3 = 70 - 3 = 67.00

    // 5. Free allocated memory
    free_ast(ast_root);

    return 0;
}

