#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Structure to represent a node in the expression tree
typedef struct Node {
    char* value;
    struct Node* left;
    struct Node* right;
} Node;

// Function to create a new node
Node* createNode(char* value) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    newNode->value = value;
    newNode->left = NULL;
    newNode->right = NULL;
    return newNode;
}

// Function to parse the expression and create the expression tree
Node* parseExpression(char* expression) {
    // Find the operator with the lowest precedence
    int pos = -1;
    char op = '\0';
    for (int i = 0; i < strlen(expression); i++) {
        if (expression[i] == '-' && (pos == -1 || expression[pos] == '*')) {
            pos = i;
            op = '-';
        } else if (expression[i] == '*' && pos == -1) {
            pos = i;
            op = '*';
        }
    }

    // Create the root node
    Node* root;
    if (pos != -1) {
        root = createNode(&op);
        // Recursively parse the left and right subtrees
        char* leftExpr = (char*) malloc(pos * sizeof(char));
        char* rightExpr = (char*) malloc((strlen(expression) - pos - 1) * sizeof(char));
        strncpy(leftExpr, expression, pos);
        strcpy(rightExpr, expression + pos + 1);
        root->left = parseExpression(leftExpr);
        root->right = parseExpression(rightExpr);
        free(leftExpr);
        free(rightExpr);
    } else {
        // If there are no more operators, create a leaf node
        root = createNode(expression);
    }

    return root;
}

// Function to evaluate the expression tree
float evaluateExpression(Node* root, float x, float y, float z, float w) {
    if (root->left == NULL && root->right == NULL) {
        // If it's a leaf node, return the value
        if (strcmp(root->value, "x") == 0) return x;
        if (strcmp(root->value, "y") == 0) return y;
        if (strcmp(root->value, "z") == 0) return z;
        if (strcmp(root->value, "w") == 0) return w;
        return atof(root->value);
    } else {
        // If it's a non-leaf node, recursively evaluate the left and right subtrees
        float leftValue = evaluateExpression(root->left, x, y, z, w);
        float rightValue = evaluateExpression(root->right, x, y, z, w);
        if (strcmp(root->value, "+") == 0) return leftValue + rightValue;
        if (strcmp(root->value, "-") == 0) return leftValue - rightValue;
        if (strcmp(root->value, "*") == 0) return leftValue * rightValue;
    }
}

int main() {
    char* expression = "x*(y+z)-w";
    Node* root = parseExpression(expression);

    float x = 1.0;
    float y = 2.0;
    float z = 3.0;
    float w = 4.0;

    float result = evaluateExpression(root, x, y, z, w);
    printf("The result of the expression is: %f\n", result);

    return 0;
}

