// Function to check if a string represents a valid integer
bool is_valid_integer(const char* str) {
    // Check if string is empty
    if (str == NULL || *str == '\0') {
        return false;
    }

    // Check each character
    while (*str) {
        if (!isdigit(*str)) {
            return false;
        }
        str++;
    }
    return true;
}

// Function to validate an IPv4 address
bool validate_ipv4_address(const char* ip_address) {
    // Check if input is NULL
    if (ip_address == NULL) {
        return false;
    }

    // Create a copy of the input string for tokenization
    char* ip_copy = strdup(ip_address);
    if (ip_copy == NULL) {
        return false;
    }

    // Variables to track tokens and octets
    char* token;
    int octet_count = 0;
    int octet_value;

    // Split the IP address into tokens using dot as delimiter
    token = strtok(ip_copy, ".");

    // Process each octet
    while (token != NULL && octet_count < 4) {
        // Check if token is a valid integer
        if (!is_valid_integer(token)) {
            free(ip_copy);
            return false;
        }

        // Convert token to integer
        octet_value = atoi(token);

        // Check if octet is within valid range (0-255)
        if (octet_value < 0 || octet_value > 255) {
            free(ip_copy);
            return false;
        }

        // Check for leading zeros
        if (strlen(token) > 1 && token[0] == '0') {
            free(ip_copy);
            return false;
        }

        // Move to next token
        token = strtok(NULL, ".");
        octet_count++;
    }

    // Free the copied string
    free(ip_copy);

    // Check if exactly 4 octets were found
    return (octet_count == 4 && token == NULL);
}

// Function to parse and display IP address details
void parse_ip_address(const char* ip_address) {
    // Check if IP address is valid
    if (!validate_ipv4_address(ip_address)) {
        printf("Invalid IPv4 address: %s\n", ip_address);
        return;
    }

    // Create a copy of the input string for parsing
    char* ip_copy = strdup(ip_address);
    char* token;
    int octets[4];
    int i = 0;

    // Split the IP address into tokens
    token = strtok(ip_copy, ".");
    while (token != NULL && i < 4) {
        octets[i++] = atoi(token);
        token = strtok(NULL, ".");
    }

    // Display IP address details
    printf("IPv4 Address: %s\n", ip_address);
    printf("Octets:\n");
    for (int j = 0; j < 4; j++) {
        printf("  Octet %d: %d (Decimal: %d, Binary: ", j + 1, octets[j], octets[j]);

        // Convert decimal to binary
        for (int k = 7; k >= 0; k--) {
            printf("%d", (octets[j] >> k) & 1);
        }
        printf(")\n");
    }

    // Free the copied string
    free(ip_copy);
}

