// Function to validate an IPv4 address
// Returns 1 if valid, 0 if invalid
int validateIPv4Address(const char *ipAddress) {
    if (ipAddress == NULL || *ipAddress == '\0') {
        return 0; // Null or empty string is invalid
    }

    int octetCount = 0;
    int currentOctetValue = 0;
    int i = 0;
    int len = strlen(ipAddress);

    // Flag to track if the previous character was a dot (to catch "1.2..3" or ".1.2.3")
    int prevCharWasDot = 1; 

    while (i < len) {
        char c = ipAddress[i];

        if (c >= '0' && c <= '9') {
            // Check for leading zeros (e.g., "192.168.01.1" -> invalid)
            // Exception: single '0' is valid (e.g., "192.168.0.1")
            if (currentOctetValue == 0 && (c == '0' && i > 0 && ipAddress[i-1] != '.') ) {
                return 0; // Leading zero (e.g., "01")
            }
            if (currentOctetValue > 0 && c == '0' && (i == 0 || (i > 0 && ipAddress[i-1] == '.') ) ) {
                return 0; // Leading zero for non-zero octet (e.g., "01")
             }


            // Parse the digit and update currentOctetValue
            int digit = c - '0';
            currentOctetValue = currentOctetValue * 10 + digit;

            // Check if octet value exceeds 255
            if (currentOctetValue > 255) {
                return 0; // Octet out of range
            }
            prevCharWasDot = 0; // Current character is a digit
        } else if (c == '.') {
            // Check for consecutive dots (e.g., "1.2..3")
            // Or a dot at the beginning/end ("." or "1.2.3.")
            if (prevCharWasDot || octetCount >= 3 || i == 0 || i == len - 1) {
                return 0; // Invalid dot placement
            }

            // Octet is complete, reset for next
            currentOctetValue = 0;
            octetCount++;
            prevCharWasDot = 1; // Current character is a dot
        } else {
            // Invalid character
            return 0;
        }
        i++;
    }

    // After loop, we must have exactly 4 octets
    if (octetCount != 3) { // 3 dots mean 4 octets
        return 0;
    }

    return 1; // All checks passed
}

