        // Each segment must be between 0-255
        if (num < 0 || num > 255) return 0;

        ptr = strtok(NULL, ".");
        dots++;
    }

    // Valid IP must have exactly 4 segments
    if (dots != 4)
        return 0;

    return 1;
}

