// Structure to represent an IPv4 address
typedef struct {
    int octets[4];
} ipv4_address;

// Function to parse and validate an IPv4 address
int parse_ipv4_address(const char* ip, ipv4_address* addr) {
    // Split the IP address into four octets
    char* token;
    char ip_copy[16];
    strcpy(ip_copy, ip);
    token = strtok(ip_copy, ".");

    int octet_count = 0;
    while (token != NULL && octet_count < 4) {
        // Check if the octet is a valid number
        if (!is_digit_string(token)) {
            return 0; // Invalid IP address
        }

        int octet_value = atoi(token);
        if (octet_value < 0 || octet_value > 255) {
            return 0; // Invalid IP address
        }

        addr->octets[octet_count] = octet_value;
        token = strtok(NULL, ".");
        octet_count++;
    }

    // Check if we have exactly four octets
    if (octet_count != 4) {
        return 0; // Invalid IP address
    }

    return 1; // Valid IP address
}

// Helper function to check if a string consists only of digits
int is_digit_string(const char* str) {
    while (*str != '\0') {
        if (*str < '0' || *str > '9') {
            return 0;
        }
        str++;
    }
    return 1;
}

