// Function to check if a string is a valid IPv4 address
int isValidIPv4(const char *ip) {
    int octetCount = 0;
    char buffer[4]; // Buffer to hold each octet
    int bufferIndex = 0;

    for (int i = 0; i < strlen(ip); i++) {
        if (isdigit(ip[i])) {
            // If the buffer is full or the number is too large, it's invalid
            if (bufferIndex == 3 || (bufferIndex > 0 && buffer[0] == '0')) {
                return 0;
            }
            buffer[bufferIndex++] = ip[i];
        } else if (ip[i] == '.') {
            if (bufferIndex == 0 || octetCount == 3) {
                return 0;
            }
            buffer[bufferIndex] = '\0';
            int octet = atoi(buffer);
            if (octet < 0 || octet > 255) {
                return 0;
            }
            bufferIndex = 0;
            octetCount++;
        } else {
            // Any other character makes it invalid
            return 0;
        }
    }

    // Check the last octet
    if (bufferIndex == 0 || octetCount != 3) {
        return 0;
    }
    buffer[bufferIndex] = '\0';
    int octet = atoi(buffer);
    if (octet < 0 || octet > 255) {
        return 0;
    }

    return 1;
}

