// Function to check if an IP address is private
bool is_private_ip(unsigned int ip) {
    // Private IP address ranges:
    // 10.0.0.0 - 10.255.255.255
    // 172.16.0.0 - 172.31.255.255
    // 192.168.0.0 - 192.168.255.255

    // 10.0.0.0/8
    if ((ip >= 0x0A000000) && (ip <= 0x0AFFFFFF)) {
        return true;
    }

    // 172.16.0.0/12
    if ((ip >= 0xAC100000) && (ip <= 0xAC1FFFFF)) {
        return true;
    }

    // 192.168.0.0/16
    if ((ip >= 0xC0A80000) && (ip <= 0xC0A8FFFF)) {
        return true;
    }

    return false;
}

// Function to validate and parse IPv4 address
bool validate_ip(const char* ip_str) {
    if (ip_str == NULL) {
        return false;
    }

    // Count the number of dots
    int dot_count = 0;
    for (int i = 0; ip_str[i] != '\0'; i++) {
        if (ip_str[i] == '.') {
            dot_count++;
        }
    }

    // IPv4 address should have 3 dots
    if (dot_count != 3) {
        return false;
    }

    // Tokenize the IP address
    char* token;
    char ip_copy[16];  // Maximum length of IPv4 address
    strcpy(ip_copy, ip_str);

    // Stores each octet
    int octets[4];
    int octet_index = 0;

    // Parse each octet
    token = strtok(ip_copy, ".");
    while (token != NULL && octet_index < 4) {
        // Check for empty or leading zero octets
        if (strlen(token) == 0 || 
            (strlen(token) > 1 && token[0] == '0')) {
            return false;
        }

        // Convert token to integer
        int octet = atoi(token);

        // Validate octet range (0-255)
        if (octet < 0 || octet > 255) {
            return false;
        }

        octets[octet_index++] = octet;
        token = strtok(NULL, ".");
    }

    // Ensure exactly 4 octets
    if (octet_index != 4) {
        return false;
    }

    // Construct 32-bit IP address
    unsigned int ip = (octets[0] << 24) | 
                      (octets[1] << 16) | 
                      (octets[2] << 8)  | 
                      octets[3];

    // Check if IP is private or public
    bool is_private = is_private_ip(ip);

    printf("IP Address: %s\n", ip_str);
    printf("Type: %s\n", is_private ? "Private" : "Public");

    return true;
}

