// Function to validate an octet (0-255)
int isValidOctet(const char *str) {
    int octet = atoi(str);
    if (octet < 0 || octet > 255) {
        return 0; // Invalid range
    }
    // Check for leading zeros (e.g., "01" is invalid unless it's just "0")
    if (strlen(str) > 1 && str[0] == '0' && octet != 0) {
        return 0;
    }
    // Check if the string actually represents the parsed integer
    char numStr[4]; // Max 3 digits + null terminator
    sprintf(numStr, "%d", octet);
    if (strcmp(str, numStr) != 0) {
        return 0; // e.g., "abc" would atoi to 0, but strcmp would fail
    }
    return 1;
}

// Function to parse and validate an IPv4 address
// Returns 1 if valid, 0 otherwise
int parseAndValidateIPv4(const char *ipAddress, char *type) {
    char ipCopy[16]; // Max "255.255.255.255" + null terminator
    strncpy(ipCopy, ipAddress, sizeof(ipCopy) - 1);
    ipCopy[sizeof(ipCopy) - 1] = '\0'; // Ensure null termination

    char *token;
    int octets[4];
    int count = 0;

    // Tokenize the string by '.'
    token = strtok(ipCopy, ".");

    while (token != NULL) {
        if (count >= 4) {
            return 0; // Too many octets
        }
        if (!isValidOctet(token)) {
            return 0; // Invalid octet
        }
        octets[count] = atoi(token);
        count++;
        token = strtok(NULL, ".");
    }

    if (count != 4) {
        return 0; // Not exactly four octets
    }

    // Determine if public or private
    // Private IP ranges (RFC 1918):
    // Class A: 10.0.0.0 - 10.255.255.255
    // Class B: 172.16.0.0 - 172.31.255.255
    // Class C: 192.168.0.0 - 192.168.255.255

    if (octets[0] == 10) {
        strcpy(type, "Private");
    } else if (octets[0] == 172 && (octets[1] >= 16 && octets[1] <= 31)) {
        strcpy(type, "Private");
    } else if (octets[0] == 192 && octets[1] == 168) {
        strcpy(type, "Private");
    }
    // Loopback address
    else if (octets[0] == 127) {
        strcpy(type, "Private (Loopback)");
    }
    // APIPA (Automatic Private IP Addressing)
    else if (octets[0] == 169 && octets[1] == 254) {
        strcpy(type, "Private (APIPA)");
    }
    // Link-local (RFC 3927) for 169.254.0.0/16 - already covered by APIPA but good to explicitly state
    else if (octets[0] == 169 && octets[1] == 254) {
        strcpy(type, "Private (Link-Local)");
    } else {
        strcpy(type, "Public");
    }

    return 1; // Valid IPv4 address
}

