    strncpy(buf, ip, sizeof(buf)-1);
    buf[sizeof(buf)-1] = '\0'; // Null-terminate for safety
    char *token = strtok(buf, ".");
    int count = 0;
    while (token != NULL) {
        // Check for non-digit input
        for (int i=0; token[i]; ++i) {
            if (!isdigit((unsigned char)token[i]))
                return 0;
        }
        // Convert to integer and range check
        int val = atoi(token);
        if (val < 0 || val > 255)
            return 0;
        octets[count++] = val;
        token = strtok(NULL, ".");
    }
    return (count == 4);
}

