// Function to check if a string is a valid IPv4 address
int is_valid_ipv4(const char *ip) {
    int parts = 0;
    int num = 0;
    for (const char *ptr = ip; *ptr; ++ptr) {
        if (*ptr == '.') {
            if (num < 0 || num > 255) {
                return 0; // Invalid part
            }
            parts++;
            num = 0;
        } else if (*ptr >= '0' && *ptr <= '9') {
            num = num * 10 + (*ptr - '0');
        } else {
            return 0; // Non-numeric character
        }
    }
    if (num < 0 || num > 255) {
        return 0; // Invalid last part
    }
    return parts == 3; // Four parts (three dots)
}

// Function to check if an IPv4 address is private
int is_private_ipv4(uint32_t ip) {
    // Check for private IP ranges
    // 10.0.0.0/8
    if ((ip & 0xFF000000) == 0x0A000000) {
        return 1;
    }
    // 172.16.0.0/12
    if ((ip & 0xFFF00000) == 0xAC100000) {
        return 1;
    }
    // 192.168.0.0/16
    if ((ip & 0xFFC00000) == 0xC0A80000) {
        return 1;
    }
    return 0;
}

