    for (int i = 0; i < 4; ++i) {
        if (tok == NULL) {
            printf("Invalid IPv4 address\n");
            return 1;
        }
        parts[i] = atoi(tok);
        tok = strtok(NULL, ".");
    }
    ip = (parts[0] << 24) | (parts[1] << 16) | (parts[2] << 8) | parts[3];

    printf("IPv4 address: %s\n", ip_str);
    if (is_private_ipv4(ip)) {
        printf("Type: Private\n");
