// Function to validate an IPv4 address
int validateIPv4(const char *ip) {
    struct in_addr addr;
    return inet_pton(AF_INET, ip, &addr) == 1;
}

// Function to determine if an IP address is private
int isPrivateIPv4(const char *ip) {
    struct in_addr addr;
    inet_pton(AF_INET, ip, &addr);
    unsigned int num = ntohl(addr.s_addr);

    // Check if the IP is private
    if ((num >> 24) == 10) { // 10.0.0.0/8
        return 1;
    }
    if ((num >> 20) == 0x12A) { // 172.16.0.0/12
        return 1;
    }
    if ((num >> 16) == 0xA10) { // 192.168.0.0/16
        return 1;
    }
    if ((num >> 16) == 0xC0A8) { // 192.168.0.0/16
        return 1;
    }
    return 0;
}

