// Function to check if a line already exists in the array
int line_exists(char *lines[], int count, const char *new_line) {
    for (int i = 0; i < count; i++) {
        if (strcmp(lines[i], new_line) == 0) {
            return 1;  // Line already exists
        }
    }
    return 0;  // Line does not exist
}

int main() {
    char *input_filename = "input.txt";
    char *output_filename = "output.txt";

    FILE *input_file, *output_file;
    char line[MAX_LINE_LENGTH];
    char *unique_lines[MAX_LINES];
    int line_count = 0;

    // Open input file
    input_file = fopen(input_filename, "r");
    if (input_file == NULL) {
        printf("Error opening input file.\n");
        return 1;
    }

    // Open output file
    output_file = fopen(output_filename, "w");
    if (output_file == NULL) {
        printf("Error opening output file.\n");
        fclose(input_file);
        return 1;
    }

    // Read lines from input file
    while (fgets(line, sizeof(line), input_file) != NULL) {
        // Remove newline character if present
        line[strcspn(line, "\n")] = '\0';

        // Check if the line is already in the unique lines array
        if (!line_exists(unique_lines, line_count, line)) {
            // Allocate memory for the line and add it to unique lines
            unique_lines[line_count] = strdup(line);

            // Write the unique line to the output file
            fprintf(output_file, "%s\n", unique_lines[line_count]);

            line_count++;

            // Check if maximum number of lines is reached
            if (line_count >= MAX_LINES) {
                printf("Maximum number of lines reached.\n");
                break;
            }
        }
    }

    // Free allocated memory
    for (int i = 0; i < line_count; i++) {
        free(unique_lines[i]);
    }

    // Close files
    fclose(input_file);
    fclose(output_file);

    printf("Duplicate lines removed successfully.\n");
    return 0;
}

