// Function to check if a line exists in the array of unique lines
bool is_duplicate(char lines[][MAX_LENGTH], int count, char *line) {
    for (int i = 0; i < count; i++) {
        if (strcmp(lines[i], line) == 0) {
            return true;
        }
    }
    return false;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s input_file output_file\n", argv[0]);
        return 1;
    }

    char unique_lines[MAX_LINES][MAX_LENGTH];
    int line_count = 0;
    char buffer[MAX_LENGTH];

    FILE *input = fopen(argv[1], "r");
    if (input == NULL) {
        perror("Error opening input file");
        return 1;
    }

    // Read input file and store unique lines
    while (fgets(buffer, MAX_LENGTH, input) != NULL && line_count < MAX_LINES) {
        // Remove newline character if present
        buffer[strcspn(buffer, "\n")] = '\0';

        if (!is_duplicate(unique_lines, line_count, buffer)) {
            strcpy(unique_lines[line_count], buffer);
            line_count++;
