#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// --- Constants ---
#define MAX_LINE_LENGTH 1024 // Maximum assumed length of a line
#define INITIAL_HASHTABLE_SIZE 1024 // Initial size of our hash table
#define LOAD_FACTOR_THRESHOLD 0.75 // Resize hash table if load factor exceeds this

// --- Hash Table Structures ---

// A node in our linked list for collision handling (separate chaining)
typedef struct HashNode {
    char *line;             // The actual line content
    struct HashNode *next;  // Pointer to the next node in case of collision
} HashNode;

// Our hash table structure
typedef struct HashTable {
    HashNode **table;       // Array of pointers to HashNodes (the buckets)
    size_t size;            // Current size of the hash table array
    size_t num_elements;    // Number of elements (unique lines) stored
} HashTable;

// --- Hash Function (DJB2) ---
// A widely used and reasonably good string hash function
unsigned long hash_string(const char *str) {
    unsigned long hash = 5381; // Initial prime
    int c;

    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    }
    return hash;
}

// --- Hash Table Operations ---

// Initializes a new hash table
HashTable* create_hash_table(size_t initial_size) {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    if (ht == NULL) {
        perror("Failed to allocate hash table");
        exit(EXIT_FAILURE);
    }
    ht->size = initial_size;
    ht->num_elements = 0;
    ht->table = (HashNode**)calloc(ht->size, sizeof(HashNode*)); // calloc initializes to NULL
    if (ht->table == NULL) {
        perror("Failed to allocate hash table buckets");
        free(ht);
        exit(EXIT_FAILURE);
    }
    return ht;
}

// Resizes the hash table when it gets too full
void resize_hash_table(HashTable *ht) {
    size_t old_size = ht->size;
    HashNode **old_table = ht->table;

    // Double the size
    ht->size *= 2;
    ht->num_elements = 0; // Reset count as we'll re-insert

    ht->table = (HashNode**)calloc(ht->size, sizeof(HashNode*));
    if (ht->table == NULL) {
        perror("Failed to reallocate hash table during resize");
        exit(EXIT_FAILURE);
    }

    // Re-insert all existing elements into the new, larger table
    for (size_t i = 0; i < old_size; i++) {
        HashNode *node = old_table[i];
        while (node != NULL) {
            HashNode *next_node = node->next; // Store next before modifying current node
            // Re-insert into new table (effectively just linking a new node)
            // We can reuse the node, but for simplicity of `insert_hash_table`, we pass a new string.
            // A more optimized approach would be to directly move the node.
            // For now, let's keep it simple and ensure `insert_hash_table` logic holds.
            // We'll manage memory for the 'line' separately.

            // To properly move nodes:
            unsigned long index = hash_string(node->line) % ht->size;
            node->next = ht->table[index]; // Link to head of new bucket
            ht->table[index] = node;       // Set as new head
            ht->num_elements++;             // Increment count for new table

            node = next_node; // Move to next node in the old linked list
        }
    }
    free(old_table); // Free the old table array
    printf("Hash table resized to %zu\n", ht->size); // For debugging/info
}


// Inserts a line into the hash table.
// Returns 1 if the line is new and was inserted, 0 if it was a duplicate.
int insert_hash_table(HashTable *ht, const char *line) {
    // Check load factor and resize if necessary
    if ((double)ht->num_elements / ht->size > LOAD_FACTOR_THRESHOLD) {
        resize_hash_table(ht);
    }

    unsigned long index = hash_string(line) % ht->size;

    HashNode *current = ht->table[index];
    while (current != NULL) {
        if (strcmp(current->line, line) == 0) {
            return 0; // Duplicate found
        }
        current = current->next;
    }

    // Line is new, insert it
    HashNode *new_node = (HashNode*)malloc(sizeof(HashNode));
    if (new_node == NULL) {
        perror("Failed to allocate hash node");
        exit(EXIT_FAILURE);
    }
    new_node->line = strdup(line); // strdup allocates memory and copies the string
    if (new_node->line == NULL) {
        perror("Failed to duplicate line string");
        free(new_node);
        exit(EXIT_FAILURE);
    }
    new_node->next = ht->table[index]; // Link to the current head of the bucket
    ht->table[index] = new_node;       // Set as the new head

    ht->num_elements++;
    return 1; // Successfully inserted
}

// Cleans up (frees memory) for the hash table
void free_hash_table(HashTable *ht) {
    if (ht == NULL) return;

    for (size_t i = 0; i < ht->size; i++) {
        HashNode *current = ht->table[i];
        while (current != NULL) {
            HashNode *temp = current;
            current = current->next;
            free(temp->line); // Free the duplicated line string
            free(temp);       // Free the hash node itself
        }
    }
    free(ht->table); // Free the array of bucket pointers
    free(ht);        // Free the hash table structure
}


// --- Main Program Logic ---

int main(int argc, char *argv[]) {
    if (argc < 2 || argc > 3) {
        fprintf(stderr, "Usage: %s <input_file> [output_file]\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input_filename = argv[1];
    const char *output_filename = (argc == 3) ? argv[2] : "unique_lines.txt"; // Default output

    FILE *input_file = NULL;
    FILE *output_file = NULL;
    char line_buffer[MAX_LINE_LENGTH]; // Buffer to read lines

    HashTable *seen_lines = NULL;

    // --- Open input file ---
    input_file = fopen(input_filename, "r");
    if (input_file == NULL) {
        perror("Error opening input file");
        return EXIT_FAILURE;
    }

    // --- Open output file ---
    output_file = fopen(output_filename, "w");
    if (output_file == NULL) {
        perror("Error opening output file");
        fclose(input_file);
        return EXIT_FAILURE;
    }

    seen_lines = create_hash_table(INITIAL_HASHTABLE_SIZE);

    printf("Processing file '%s'...\n", input_filename);

    // --- Read lines, check for duplicates, and write unique ones ---
    while (fgets(line_buffer, sizeof(line_buffer), input_file) != NULL) {
        // Remove trailing newline character if present
        // (fgets includes it, and we want to compare actual line content)
        size_t len = strlen(line_buffer);
        if (len > 0 && line_buffer[len - 1] == '\n') {
            line_buffer[len - 1] = '\0';
        }
        // If the line consists only of a newline (i.e., it was "\n" and became ""),
        // we might want to treat "" and "\n" as different or the same.
        // For simplicity, now "" and "\n" are different.
        // If you want "" and "\n" to be considered the same, you might need to adjust.
        // For example, if line_buffer was just "\n", after removing newline, it's "".
        // If you want to keep blank lines (empty strings) unique, this is fine.
        // If you want to treat all blank lines (including those that were just '\n')
        // as the same effectively, you might need to check if strlen is 0.

        // Insert into hash table. If true, it's a new unique line.
        if (insert_hash_table(seen_lines, line_buffer)) {
            // Write the line back to the output file, followed by a newline.
            // We removed the newline for comparison, so add it back for output.
            fprintf(output_file, "%s\n", line_buffer);
        }
    }

    printf("Duplicate lines removed. Unique lines written to '%s'.\n", output_filename);

    // --- Cleanup ---
    fclose(input_file);
    fclose(output_file);
    free_hash_table(seen_lines);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE 1024
#define HASH_SIZE 10007   // A prime number for good hash distribution

// Linked list node for hash table chaining
typedef struct Node {
    char *line;
    struct Node *next;
} Node;

// Simple hash function for strings
unsigned int hash(const char *s) {
    unsigned int h = 5381;
    while (*s) {
        h = ((h << 5) + h) + (unsigned char)(*s);
        s++;
    }
    return h % HASH_SIZE;
}

// Check if line exists in hash table; if not, insert and return 0; if exists, return 1
int is_duplicate_and_insert(Node *table[], const char *line) {
    unsigned int h = hash(line);
    Node *curr = table[h];
    while (curr) {
        if (strcmp(curr->line, line) == 0)
            return 1; // Duplicate found
        curr = curr->next;
    }
    // Not found: insert new node
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Out of memory\n");
        exit(1);
    }
    new_node->line = strdup(line);
    new_node->next = table[h];
    table[h] = new_node;
    return 0;
}

// Free hash table
void free_table(Node *table[]) {
    for (int i = 0; i < HASH_SIZE; i++) {
        Node *curr = table[i];
        while (curr) {
            Node *tmp = curr;
            curr = curr->next;
            free(tmp->line);
            free(tmp);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s input.txt output.txt\n", argv[0]);
        return 1;
    }

    FILE *fin = fopen(argv[1], "r");
    if (!fin) {
        perror("Cannot open input file");
        return 1;
    }

    FILE *fout = fopen(argv[2], "w");
    if (!fout) {
        perror("Cannot open output file");
        fclose(fin);
        return 1;
    }

    // Initialize hash table
    Node *hash_table[HASH_SIZE] = {0};

    char buffer[MAX_LINE];
    while (fgets(buffer, sizeof(buffer), fin)) {
        // Remove possible line endings for strict duplicate checking
        size_t len = strlen(buffer);
        if (len > 0 && buffer[len-1] == '\n')
            buffer[len-1] = '\0';

        if (!is_duplicate_and_insert(hash_table, buffer)) {
            fprintf(fout, "%s\n", buffer);
        }
    }

    // Cleanup
    free_table(hash_table);
    fclose(fin);
    fclose(fout);
    return 0;
}

