#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define LINE_SIZE 256
#define TABLE_SIZE 1000

typedef struct Node {
    char line[LINE_SIZE];
    struct Node *next;
} Node;

typedef struct {
    Node *table[TABLE_SIZE];
} HashTable;

// Hash function to determine index for a given line
unsigned long hash(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    }
    return hash % TABLE_SIZE;
}

// Create a new hash table
HashTable *createHashTable() {
    HashTable *hashTable = (HashTable *)malloc(sizeof(HashTable));
    for (int i = 0; i < TABLE_SIZE; i++) {
        hashTable->table[i] = NULL;
    }
    return hashTable;
}

// Check if the line already exists in the hash table
int contains(HashTable *hashTable, const char *line) {
    unsigned long index = hash(line);
    Node *current = hashTable->table[index];
    while (current != NULL) {
        if (strcmp(current->line, line) == 0) {
            return 1; // Found a duplicate
        }
        current = current->next;
    }
    return 0; // Not found
}

// Insert a new line into the hash table
void insert(HashTable *hashTable, const char *line) {
    unsigned long index = hash(line);
    Node *newNode = (Node *)malloc(sizeof(Node));
    strcpy(newNode->line, line);
    newNode->next = hashTable->table[index];
    hashTable->table[index] = newNode;
}

// Function to remove duplicate lines from a file
void removeDuplicateLines(const char *inputFile, const char *outputFile) {
    FILE *inFile = fopen(inputFile, "r");
    if (!inFile) {
        perror("Unable to open input file");
        return;
    }

    HashTable *hashTable = createHashTable();
    char line[LINE_SIZE];

    FILE *outFile = fopen(outputFile, "w");
    if (!outFile) {
        perror("Unable to open output file");
        fclose(inFile);
        return;
    }

    while (fgets(line, sizeof(line), inFile)) {
        // Remove newline character at the end if it exists
        line[strcspn(line, "\n")] = 0;

        if (!contains(hashTable, line)) {
            fprintf(outFile, "%s\n", line);
            insert(hashTable, line);
        }
    }

    fclose(inFile);
    fclose(outFile);

    // Free memory
    for (int i = 0; i < TABLE_SIZE; i++) {
        Node *current = hashTable->table[i];
        while (current != NULL) {
            Node *temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(hashTable);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_file> <output_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    removeDuplicateLines(argv[1], argv[2]);

    return EXIT_SUCCESS;
}

