// Function to scan for Bluetooth Low Energy (BLE) devices using hcitool lescan
void scan_bluetooth_ble_devices_popen() {
    FILE *fp;
    char buffer[256]; // Buffer to hold each line of output
    int scan_duration_seconds = 5; // How long to scan

    printf("Scanning for Bluetooth Low Energy (BLE) devices for %d seconds...\n", scan_duration_seconds);
    printf("This requires root privileges or appropriate BlueZ capabilities.\n");
    printf("Make sure your Bluetooth adapter is enabled.\n\n");

    // Start hcitool lescan in a separate process
    // The -r flag prevents immediate reporting and allows continuous scanning
    // It's tricky to stop it cleanly with popen, so we'll just read for a few seconds.
    // A better approach for continuous scanning would be the D-Bus method or proper BlueZ API.
    char command[128];
    sprintf(command, "sudo hcitool lescan --passive & sleep %d", scan_duration_seconds);
    // Note: The above command will run hcitool lescan in background and then immediately sleep.
    // This is not what we want for reading output over a duration.
    // We need to execute hcitool lescan, read output, and then kill it.
    // For popen, a simpler approach is to use 'hcitool lescan' and let it run for a bit, then close popen.
    // Or, for a controlled duration without external scripts, just a short scan.

    // A more practical approach with popen for a short burst
    // hcitool lescan will typically run for ~10 seconds by default, or until Ctrl+C
    // Let's open it and read for a bit.
    fp = popen("sudo hcitool lescan", "r"); // "r" for read mode
    if (fp == NULL) {
        perror("Failed to run command 'hcitool lescan'. Check permissions.");
        return;
    }

    printf("MAC Address         Device Name\n");
    printf("----------------------------------\n");

    time_t start_time = time(NULL);
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        // hcitool lescan output format: "MAC_ADDR DEVICE_NAME"
        // Example: "C0:E4:33:44:55:66 (unknown)" or "D0:E1:F2:G3:H4:I5 MyDevice"
        char *mac = strtok(buffer, " ");
        char *name = strtok(NULL, "\n"); // Get the rest of the line as name

        if (mac && name) {
            // Remove trailing newline from name if present
            name[strcspn(name, "\n")] = 0;
            printf("%-18s %s\n", mac, name);
        }

        // Limit the reading time
        if (time(NULL) - start_time >= scan_duration_seconds) {
            printf("\nScan duration reached. Stopping...\n");
            break; // Stop reading after scan_duration_seconds
        }
    }

    // Killing the process spawned by popen immediately might be tricky.
    // You might need to use `pkill` or manage process IDs explicitly if `hcitool lescan`
    // doesn't terminate cleanly. For a simple `popen` call, it usually terminates
    // when `pclose` is called or the pipe is closed.
    pclose(fp); // Close the pipe
    printf("\nScan complete.\n");
}

// Function to scan for classic Bluetooth devices using hcitool scan
void scan_bluetooth_classic_devices_popen() {
    FILE *fp;
    char buffer[256];
    int scan_duration_seconds = 5; // hcitool scan usually takes about 10 seconds

    printf("\nScanning for Classic Bluetooth devices for up to %d seconds...\n", scan_duration_seconds);
    printf("This requires root privileges or appropriate BlueZ capabilities.\n");
    printf("Make sure your Bluetooth adapter is enabled.\n\n");

    fp = popen("sudo hcitool scan", "r");
    if (fp == NULL) {
        perror("Failed to run command 'hcitool scan'. Check permissions.");
        return;
    }

    printf("MAC Address         Device Name\n");
    printf("----------------------------------\n");

    // Skip the first line which is "Scanning ..."
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        printf("No output from hcitool scan.\n");
        pclose(fp);
        return;
    }

    time_t start_time = time(NULL);
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        // hcitool scan output format: "\tMAC_ADDR\tDEVICE_NAME"
        // Example: "\tC0:E4:33:44:55:66\tMyBluetoothSpeaker"
        char *mac = NULL;
        char *name = NULL;

        // Find the first tab, then the MAC address
        char *tab1 = strchr(buffer, '\t');
        if (tab1) {
            mac = tab1 + 1; // MAC starts after the first tab
            char *tab2 = strchr(mac, '\t'); // Find the second tab
            if (tab2) {
                *tab2 = '\0'; // Null-terminate MAC address
                name = tab2 + 1; // Name starts after the second tab
                name[strcspn(name, "\n")] = 0; // Remove trailing newline
            }
        }

        if (mac && name) {
            printf("%-18s %s\n", mac, name);
        }

        if (time(NULL) - start_time >= scan_duration_seconds + 3) { // Allow a bit more time for hcitool scan
             printf("\nScan duration reached. Stopping...\n");
             break;
        }
    }

    pclose(fp);
    printf("\nScan complete.\n");
}


