#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Function to generate a random double between 0 and 1
double random_double() {
    return (double)rand() / RAND_MAX;
}

// Function to simulate a Markov chain
void simulate_markov_chain(int states, int steps, double** transition_matrix) {
    // Seed the random number generator
    srand(time(NULL));

    // Initialize the current state (randomly)
    int current_state = rand() % states;

    // Array to store state visitation count
    int* state_visits = calloc(states, sizeof(int));

    // Print initial state
    printf("Markov Chain Simulation:\n");
    printf("Initial State: %d\n", current_state);
    state_visits[current_state]++;

    // Simulate Markov chain for specified steps
    for (int step = 1; step <= steps; step++) {
        // Generate a random number to determine next state
        double random_prob = random_double();
        double cumulative_prob = 0.0;

        // Find the next state based on transition probabilities
        for (int next_state = 0; next_state < states; next_state++) {
            cumulative_prob += transition_matrix[current_state][next_state];

            if (random_prob <= cumulative_prob) {
                current_state = next_state;
                break;
            }
        }

        // Update state visits
        state_visits[current_state]++;

        // Print current state and step
        printf("Step %d: State %d\n", step, current_state);
    }

    // Print state visitation statistics
    printf("\nState Visitation Statistics:\n");
    for (int i = 0; i < states; i++) {
        printf("State %d: %d visits (%.2f%%)\n", 
               i, state_visits[i], 
               (double)state_visits[i] / steps * 100.0);
    }

    // Free allocated memory
    free(state_visits);
}

// Function to create a transition matrix
double** create_transition_matrix(int states) {
    // Allocate memory for transition matrix
    double** matrix = malloc(states * sizeof(double*));
    for (int i = 0; i < states; i++) {
        matrix[i] = malloc(states * sizeof(double));
    }

    // Input transition probabilities
    printf("Enter transition probabilities:\n");
    for (int i = 0; i < states; i++) {
        double row_sum = 0.0;
        printf("For state %d:\n", i);

        for (int j = 0; j < states; j++) {
            printf("Probability to state %d: ", j);
            scanf("%lf", &matrix[i][j]);
            row_sum += matrix[i][j];
        }

        // Validate row probabilities
        if (row_sum != 1.0) {
            printf("Warning: Row probabilities do not sum to 1.0\n");
        }
    }

    return matrix;
}

// Function to free transition matrix memory
void free_transition_matrix(double** matrix, int states) {
    for (int i = 0; i < states; i++) {
        free(matrix[i]);
    }
    free(matrix);
}

int main() {
    int states, steps;

    // Input number of states and steps
    printf("Enter number of states: ");
    scanf("%d", &states);

    printf("Enter number of steps: ");
    scanf("%d", &steps);

    // Create transition matrix
    double** transition_matrix = create_transition_matrix(states);

    // Simulate Markov chain
    simulate_markov_chain(states, steps, transition_matrix);

    // Free allocated memory
    free_transition_matrix(transition_matrix, states);

    return 0;
}

