// Function to simulate the Markov chain
void simulateMarkovChain(int states, int steps, double transitionMatrix[states][states], int initialState) {
    int currentState = initialState;
    printf("Step 0: State %d\n", currentState);

    srand(time(NULL)); // Seed the random number generator

    for (int step = 1; step <= steps; step++) {
        double randomValue = (double)rand() / RAND_MAX;
        double cumulativeProbability = 0.0;

        for (int nextState = 0; nextState < states; nextState++) {
            cumulativeProbability += transitionMatrix[currentState][nextState];
            if (randomValue <= cumulativeProbability) {
                currentState = nextState;
                break;
            }
        }

        printf("Step %d: State %d\n", step, currentState);
    }
}

int main() {
    int states, steps, initialState;

    // Input the number of states
    printf("Enter the number of states: ");
