    printf("Enter the transition matrix (row by row):\n");
    for (int i = 0; i < states; i++) {
        for (int j = 0; j < states; j++) {
            scanf("%lf", &transitionMatrix[i][j]);
        }
    }

    // Simulate the Markov chain
    simulateMarkovChain(states, steps, transitionMatrix, initialState);

    return 0;
}

#include <stdio.h>
