// --- Configuration ---
#define NUM_STATES 3 // Replace with your desired number of states (e.g., 3, 5, 10)
#define NUM_STEPS 20 // Replace with your desired number of steps (e.g., 20, 100, 1000)

// Function to print the current state
void print_state(int current_state) {
    printf("State: %d\n", current_state);
}

// Function to choose the next state based on probabilities
int get_next_state(int current_state, double transition_matrix[NUM_STATES][NUM_STATES]) {
    double rand_val = (double)rand() / RAND_MAX; // Generate a random double between 0.0 and 1.0
    double cumulative_prob = 0.0;

    // Iterate through possible next states from the current state
    for (int next_state = 0; next_state < NUM_STATES; next_state++) {
        cumulative_prob += transition_matrix[current_state][next_state];
        if (rand_val < cumulative_prob) {
            return next_state; // This is the chosen next state
        }
    }
    // This should ideally not be reached if probabilities sum to 1
    return current_state; // Fallback: stay in current state
}

