        printf("Invalid number of states (1-%d)\n", MAX_STATES);
        return 1;
    }

    printf("Enter number of steps: ");
    scanf("%d", &steps);
    if (steps < 1) {
        printf("Number of steps must be positive.\n");
        return 1;
    }

    // Transition matrix input
    double P[MAX_STATES][MAX_STATES];
    printf("Enter the transition matrix (row-wise, use spaces/double, sum of each row should be 1.0):\n");
    for (int i = 0; i < states; ++i) {
        printf("Row %d: ", i);
        double rowsum = 0.0;
        for (int j = 0; j < states; ++j) {
            scanf("%lf", &P[i][j]);
            rowsum += P[i][j];
        }
        // Optionally verify row sum
        if (rowsum < 0.999 || rowsum > 1.001) {
            printf("Warning: Row %d does not sum to 1 (sum=%.3lf)\n", i, rowsum);
        }
    }

    int current;
    printf("Enter initial state (0 to %d): ", states-1);
    scanf("%d", &current);
    if (current < 0 || current >= states) {
        printf("Invalid initial state.\n");
        return 1;
    }

    // Seed random number generator
    srand((unsigned int)time(NULL));

    printf("\nSimulating Markov chain:\nState sequence: %d", current);
    for (int step = 1; step <= steps; ++step) {
        // Weighted random: roll next state based on current's row
        double r = (double) rand() / RAND_MAX;
        double acc = 0.0;
        int next = 0;
        for (int j = 0; j < states; ++j) {
            acc += P[current][j];
            if (r < acc) {
                next = j;
                break;
            }
        }
        current = next;
        printf(" -> %d", current);
    }
    printf("\n");
    return 0;
}

#include <stdio.h>
