#define STATES 3   // Replace with the desired number of states
#define STEPS 10   // Replace with the desired number of steps

// Function to initialize transition matrix with random probabilities
void initializeTransitionMatrix(double matrix[STATES][STATES]) {
    for (int i = 0; i < STATES; i++) {
        double sum = 0.0;
        for (int j = 0; j < STATES; j++) {
            matrix[i][j] = ((double) rand() / (RAND_MAX));
            sum += matrix[i][j];
        }
        // Normalize row to ensure probabilities sum up to 1
        for (int j = 0; j < STATES; j++) {
            matrix[i][j] /= sum;
        }
    }
}

// Function to choose the next state based on the current state
int chooseNextState(int currentState, double matrix[STATES][STATES]) {
    double r = (double) rand() / RAND_MAX;
    double cumulativeProbability = 0.0;
    for (int i = 0; i < STATES; i++) {
        cumulativeProbability += matrix[currentState][i];
        if (r < cumulativeProbability) {
            return i;
        }
    }
    return STATES - 1; // Return the last state as fallback
}

int main() {
    srand(time(NULL)); // Seed random number generator

    double transitionMatrix[STATES][STATES];
    initializeTransitionMatrix(transitionMatrix);

    // Print the transition matrix
    printf("Transition Matrix:\n");
    for (int i = 0; i < STATES; i++) {
        for (int j = 0; j < STATES; j++) {
            printf("%0.2f ", transitionMatrix[i][j]);
        }
        printf("\n");
    }
    printf("\n");

    // Starting from an initial state (e.g., state 0)
    int currentState = 0;
    printf("Markov Chain Simulation:\n");
    printf("Start: State %d\n", currentState);

    for (int step = 0; step < STEPS; step++) {
        currentState = chooseNextState(currentState, transitionMatrix);
        printf("Step %d: Moved to State %d\n", step + 1, currentState);
    }

    return 0;
}

