    for (int i = 0; i < states; i++) {
        for (int j = 0; j < states; j++) {
            if (i == j) {
                transition_matrix[i][j] = 0.3; // Self-transition probability
            } else {
                transition_matrix[i][j] = 0.7 / (states - 1); // Transition to other states
            }
        }
    }
}

// Function to generate an initial state
int generate_initial_state(int states) {
    return rand() % states;
}

// Function to simulate the Markov chain
void simulate_markov_chain(double transition_matrix[][100], int states, int steps) {
