// Enum to represent traffic light states
typedef enum {
    RED,
    YELLOW,
    GREEN
} TrafficLightState;

// Structure to represent traffic light for each direction
typedef struct {
    char* name;
    TrafficLightState state;
    int greenDuration;
    int yellowDuration;
    int redDuration;
} TrafficLight;

// Function prototypes
void initializeTrafficLight(TrafficLight* light, char* name);
void changeState(TrafficLight* light);
void displayTrafficLight(TrafficLight* light);
void simulateIntersection();

// Initialize traffic light with default values
void initializeTrafficLight(TrafficLight* light, char* name) {
    light->name = name;
    light->state = RED;
    light->greenDuration = 30;
    light->yellowDuration = 5;
    light->redDuration = 35;
}

// Change traffic light state
void changeState(TrafficLight* light) {
    switch (light->state) {
        case RED:
            light->state = GREEN;
            break;
        case GREEN:
            light->state = YELLOW;
            break;
        case YELLOW:
            light->state = RED;
            break;
    }
}

// Display traffic light status
void displayTrafficLight(TrafficLight* light) {
    printf("\n--- %s Traffic Light ---\n", light->name);

    switch (light->state) {
        case RED:
            printf("State: RED (Stop)\n");
            break;
        case YELLOW:
            printf("State: YELLOW (Caution)\n");
            break;
        case GREEN:
            printf("State: GREEN (Go)\n");
            break;
    }
}

// Simulate traffic light at intersection
void simulateIntersection() {
    TrafficLight northSouth, eastWest;

    // Initialize traffic lights
    initializeTrafficLight(&northSouth, "North-South");
    initializeTrafficLight(&eastWest, "East-West");

    // Simulation loop
    for (int i = 0; i < 6; i++) {
        // Display current state
        displayTrafficLight(&northSouth);
        displayTrafficLight(&eastWest);

        // Simulate different durations
        if (northSouth.state == GREEN) {
            sleep(northSouth.greenDuration);
        } else if (northSouth.state == YELLOW) {
            sleep(northSouth.yellowDuration);
        } else {
            sleep(northSouth.redDuration);
        }

        // Change states
        changeState(&northSouth);

        if (eastWest.state == RED) {
            eastWest.state = GREEN;
        } else if (eastWest.state == GREEN) {
            eastWest.state = YELLOW;
        } else {
            eastWest.state = RED;
        }

        printf("\n--- Changing Lights ---\n");
        sleep(2);
    }
}

// Main function
int main() {
    printf("Traffic Light Simulation\n");
    printf("=======================\n");

    simulateIntersection();

    return 0;
}

