#include <ncurses.h> // For screen manipulation
#include <unistd.h>  // For usleep (sleep in microseconds)
#include <stdlib.h>  // For exit

// Define the colors we'll use
#define COLOR_RED_ON    1
#define COLOR_YELLOW_ON 2
#define COLOR_GREEN_ON  3
#define COLOR_BLACK_BG  4 // For turning off lights

// Define light states
typedef enum {
    RED,
    RED_YELLOW, // For transition (optional, but realistic)
    GREEN,
    YELLOW
} LightState;

// Function to draw a single traffic light enclosure
void draw_light_enclosure(int start_row, int start_col) {
    mvprintw(start_row,     start_col,     " ----- ");
    mvprintw(start_row + 1, start_col,     "|     |"); // Red
    mvprintw(start_row + 2, start_col,     "|     |"); // Yellow
    mvprintw(start_row + 3, start_col,     "|     |"); // Green
    mvprintw(start_row + 4, start_col,     " ----- ");
    mvprintw(start_row + 5, start_col + 3, "|");
    mvprintw(start_row + 6, start_col + 3, "|");
}

// Function to update the state of a single traffic light
void update_light_display(int start_row, int start_col, LightState state) {
    // Turn off all lights first (by drawing black circles)
    attron(COLOR_PAIR(COLOR_BLACK_BG));
    mvaddch(start_row + 1, start_col + 3, 'O'); // Red position
    mvaddch(start_row + 2, start_col + 3, 'O'); // Yellow position
    mvaddch(start_row + 3, start_col + 3, 'O'); // Green position
    attroff(COLOR_PAIR(COLOR_BLACK_BG));

    // Turn on the appropriate light
    switch (state) {
        case RED:
            attron(COLOR_PAIR(COLOR_RED_ON));
            mvaddch(start_row + 1, start_col + 3, 'O'); // Red
            attroff(COLOR_PAIR(COLOR_RED_ON));
            break;
        case RED_YELLOW:
            attron(COLOR_PAIR(COLOR_RED_ON));
            mvaddch(start_row + 1, start_col + 3, 'O'); // Red
            attroff(COLOR_PAIR(COLOR_RED_ON));
            attron(COLOR_PAIR(COLOR_YELLOW_ON));
            mvaddch(start_row + 2, start_col + 3, 'O'); // Yellow
            attroff(COLOR_PAIR(COLOR_YELLOW_ON));
            break;
        case GREEN:
            attron(COLOR_PAIR(COLOR_GREEN_ON));
            mvaddch(start_row + 3, start_col + 3, 'O'); // Green
            attroff(COLOR_PAIR(COLOR_GREEN_ON));
            break;
        case YELLOW:
            attron(COLOR_PAIR(COLOR_YELLOW_ON));
            mvaddch(start_row + 2, start_col + 3, 'O'); // Yellow
            attroff(COLOR_PAIR(COLOR_YELLOW_ON));
            break;
    }
    refresh(); // Update the screen
}

int main() {
    // Initialize ncurses
    initscr();              // Start curses mode
    noecho();               // Don't echo user input
    cbreak();               // Line buffering disabled, pass on ctrl characters
    clear();                // Clear the screen
    curs_set(0);            // Hide the cursor
    timeout(100);           // Non-blocking getch() with a 100ms timeout

    // Check for color support
    if (has_colors() == FALSE) {
        endwin();
        printf("Your terminal does not support color.\n");
        return 1;
    }

    start_color();          // Start color functionality

    // Define color pairs
    init_pair(COLOR_RED_ON,    COLOR_RED,    COLOR_BLACK);
    init_pair(COLOR_YELLOW_ON, COLOR_YELLOW, COLOR_BLACK);
    init_pair(COLOR_GREEN_ON,  COLOR_GREEN,  COLOR_BLACK);
    init_pair(COLOR_BLACK_BG,  COLOR_WHITE,  COLOR_BLACK); // For turning off lights

    // Light positions for the intersection
    // We'll simulate two traffic lights: one for North-South, one for East-West
    int ns_light_row = 5;
    int ns_light_col = 20;

    int ew_light_row = 5;
    int ew_light_col = 50;

    // Draw the light enclosures once
    mvprintw(2, 30, "TRAFFIC LIGHT SIMULATION");
    mvprintw(ns_light_row - 2, ns_light_col + 1, "N-S Light");
    draw_light_enclosure(ns_light_row, ns_light_col);
    mvprintw(ew_light_row - 2, ew_light_col + 1, "E-W Light");
    draw_light_enclosure(ew_light_row, ew_light_col);

    mvprintw(LINES - 2, 0, "Press 'q' to quit.");
    refresh();

    LightState ns_state = RED;
    LightState ew_state = GREEN; // Assuming E-W starts green

    int ch; // For keyboard input

    while ((ch = getch()) != 'q') {
        // --- N-S Light Logic ---
        switch (ns_state) {
            case RED:
                update_light_display(ns_light_row, ns_light_col, RED);
                // When N-S is RED, E-W should be GREEN or YELLOW
                if (ew_state == GREEN) {
                    usleep(3000000); // Wait 3 seconds with N-S Red, E-W Green
                    if (getch() == 'q') break; // Check for quit during sleep
                    ew_state = YELLOW;
                } else if (ew_state == YELLOW) {
                    update_light_display(ew_light_row, ew_light_col, YELLOW);
                    usleep(1000000); // 1 second for Yellow
                    if (getch() == 'q') break;
                    ew_state = RED;
                    ns_state = RED_YELLOW; // N-S prepares to go Green
                }
                break;
            case RED_YELLOW:
                update_light_display(ns_light_row, ns_light_col, RED_YELLOW);
                usleep(1000000); // 1 second for Red+Yellow
                if (getch() == 'q') break;
                ns_state = GREEN;
                break;
            case GREEN:
                update_light_display(ns_light_row, ns_light_col, GREEN);
                // When N-S is GREEN, E-W should be RED
                usleep(3000000); // Wait 3 seconds with N-S Green
                if (getch() == 'q') break;
                ns_state = YELLOW;
                break;
            case YELLOW:
                update_light_display(ns_light_row, ns_light_col, YELLOW);
                usleep(1000000); // 1 second for Yellow
                if (getch() == 'q') break;
                ns_state = RED; // N-S goes Red
                // E-W can now prepare to go green if it's currently Red
                if (ew_state == RED) {
                     ew_state = RED_YELLOW; // E-W prepares to go Green
                }
                break;
        }

        // --- E-W Light Logic (Simplified, driven by N-S state) ---
        // The E-W light's state changes are mostly triggered by N-S transitions
        // This ensures they are synchronized and don't clash.
        update_light_display(ew_light_row, ew_light_col, ew_state);

        if (ch == 'q') break; // Allow breaking with 'q' press
    }

    // Clean up ncurses
    endwin();
    return 0;
}

