// Enum for traffic light states
typedef enum {
    RED,
    YELLOW,
    GREEN
} TrafficLightState;

// Structure to represent traffic lights for different directions
typedef struct {
    char* direction;
    TrafficLightState state;
    int duration;
} TrafficLight;

// Function prototypes
void initializeTrafficLights(TrafficLight* lights, int size);
void displayTrafficLights(TrafficLight* lights, int size);
void updateTrafficLights(TrafficLight* lights, int size);
void simulateTrafficLight(TrafficLight* lights, int size, int cycles);

int main() {
    // Define traffic lights for four directions
    TrafficLight lights[4] = {
        {"North", RED, 30},    // North-South vertical
        {"South", RED, 30},    // North-South vertical
        {"East", RED, 30},     // East-West horizontal
        {"West", RED, 30}      // East-West horizontal
    };

    int numLights = sizeof(lights) / sizeof(lights[0]);
    int simulationCycles = 5;  // Number of complete light cycles

    // Start traffic light simulation
    simulateTrafficLight(lights, numLights, simulationCycles);

    return 0;
}

// Initialize traffic lights
void initializeTrafficLights(TrafficLight* lights, int size) {
    for (int i = 0; i < size; i++) {
        // Initial state: All lights are red
        lights[i].state = RED;
    }
}

// Display current traffic light states
void displayTrafficLights(TrafficLight* lights, int size) {
    printf("\n--- Traffic Light Status ---\n");
    for (int i = 0; i < size; i++) {
        printf("%s Light: ", lights[i].direction);
        switch (lights[i].state) {
            case RED:
                printf("RED    ");
                break;
            case YELLOW:
                printf("YELLOW ");
                break;
            case GREEN:
                printf("GREEN  ");
                break;
        }
        printf("(Duration: %d seconds)\n", lights[i].duration);
    }
    printf("\n");
}

// Update traffic light states
void updateTrafficLights(TrafficLight* lights, int size) {
    // Simple traffic light cycle logic
    for (int i = 0; i < size; i++) {
        switch (lights[i].state) {
            case RED:
                lights[i].state = GREEN;
                lights[i].duration = 30;
                break;
            case GREEN:
                lights[i].state = YELLOW;
                lights[i].duration = 5;
                break;
            case YELLOW:
                lights[i].state = RED;
                lights[i].duration = 30;
                break;
        }
    }
}

// Simulate traffic light cycles
void simulateTrafficLight(TrafficLight* lights, int size, int cycles) {
    initializeTrafficLights(lights, size);

    for (int cycle = 1; cycle <= cycles; cycle++) {
        printf("--- Cycle %d ---\n", cycle);

        // Display initial light states
        displayTrafficLights(lights, size);

        // Wait for light durations
        for (int i = 0; i < size; i++) {
            sleep(lights[i].duration);
        }

        // Update light states
        updateTrafficLights(lights, size);
    }
}

