// Define traffic light states
typedef enum {
    RED,
    YELLOW,
    GREEN
} LightState;

// Define ANSI color codes (for better visualization)
#define RESET_COLOR    "\x1b[0m"
#define RED_COLOR      "\x1b[31m"  // Red text
#define YELLOW_COLOR   "\x1b[33m"  // Yellow text
#define GREEN_COLOR    "\x1b[32m"  // Green text
#define BG_RED_COLOR   "\x1b[41m"  // Red background
#define BG_YELLOW_COLOR "\x1b[43m" // Yellow background
#define BG_GREEN_COLOR "\x1b[42m"  // Green background
#define BRIGHT_RED_COLOR "\x1b[91m"
#define BRIGHT_YELLOW_COLOR "\x1b[93m"
#define BRIGHT_GREEN_COLOR "\x1b[92m"

// Function to print a single traffic light
void printTrafficLight(LightState state, const char* label) {
    printf("    %s %s Traffic Light %s\t%s\n", RESET_COLOR, label, RESET_COLOR, BG_RED_COLOR);
    printf("    %s+-------+%s\n", RESET_COLOR, RESET_COLOR);
    printf("    %s|       |%s\n", RESET_COLOR, RESET_COLOR);

    printf("    %s|   ", RESET_COLOR);
    if (state == RED) {
        printf("%sO%s   |", BRIGHT_RED_COLOR, RESET_COLOR); // Red light on
    } else {
        printf("O   |"); // Red light off
    }
    printf("%s\n", RESET_COLOR);

    printf("    %s|       |%s\n", RESET_COLOR, RESET_COLOR);

    printf("    %s|   ", RESET_COLOR);
    if (state == YELLOW) {
        printf("%sO%s   |", BRIGHT_YELLOW_COLOR, RESET_COLOR); // Yellow light on
    } else {
        printf("O   |"); // Yellow light off
    }
    printf("%s\n", RESET_COLOR);

    printf("    %s|       |%s\n", RESET_COLOR, RESET_COLOR);

    printf("    %s|   ", RESET_COLOR);
    if (state == GREEN) {
        printf("%sO%s   |", BRIGHT_GREEN_COLOR, RESET_COLOR); // Green light on
    } else {
        printf("O   |"); // Green light off
    }
    printf("%s\n", RESET_COLOR);

    printf("    %s|       |%s\n", RESET_COLOR, RESET_COLOR);
    printf("    %s+-------+%s\n", RESET_COLOR, RESET_COLOR);
}

// Main simulation function
int main() {
    LightState ns_light = RED;   // North-South traffic light (starts Red)
    LightState ew_light = GREEN; // East-West traffic light (starts Green)

    // Duration for each state (in milliseconds)
    const int RED_DURATION_MS = 5000;      // 5 seconds
    const int GREEN_DURATION_MS = 4000;    // 4 seconds
    const int YELLOW_DURATION_MS = 2000;   // 2 seconds
    const int TRANSITION_PAUSE_MS = 500;  // Pause between updates

    printf("Traffic Light Simulation (Press Ctrl+C to exit)\n");
    printf("--------------------------------------------------\n");
    SLEEP_MS(2000); // Give user time to read initial message

    while (true) {
        CLEAR_SCREEN();
        printf("Traffic Light Simulation (Press Ctrl+C to exit)\n");
        printf("--------------------------------------------------\n\n");

        printTrafficLight(ns_light, "North/South");
        printf("\n\n"); // Separator between lights
        printTrafficLight(ew_light, "East/West  "); // Added spaces for alignment

        printf("\n%sCurrent Time: %.1f seconds%s\n", GREEN_COLOR, (double)time(NULL), RESET_COLOR);
        printf("%s--------------------------------------------------%s\n", RESET_COLOR, RESET_COLOR);

        // --- Logic for traffic light transitions ---

        if (ns_light == RED && ew_light == GREEN) {
            printf("NS is RED, EW is GREEN. (%dms)\n", GREEN_DURATION_MS);
            SLEEP_MS(GREEN_DURATION_MS);
            ew_light = YELLOW; // EW turns yellow
            SLEEP_MS(TRANSITION_PAUSE_MS);

        } else if (ns_light == RED && ew_light == YELLOW) {
            printf("NS is RED, EW is YELLOW. (%dms)\n", YELLOW_DURATION_MS);
            SLEEP_MS(YELLOW_DURATION_MS);
            ew_light = RED;   // EW turns red
            ns_light = GREEN; // NS turns green
            SLEEP_MS(TRANSITION_PAUSE_MS);

        } else if (ns_light == GREEN && ew_light == RED) {
            printf("NS is GREEN, EW is RED. (%dms)\n", GREEN_DURATION_MS);
            SLEEP_MS(GREEN_DURATION_MS);
            ns_light = YELLOW; // NS turns yellow
            SLEEP_MS(TRANSITION_PAUSE_MS);

        } else if (ns_light == YELLOW && ew_light == RED) {
            printf("NS is YELLOW, EW is RED. (%dms)\n", YELLOW_DURATION_MS);
            SLEEP_MS(YELLOW_DURATION_MS);
            ns_light = RED;   // NS turns red
            ew_light = GREEN; // EW turns green
            SLEEP_MS(TRANSITION_PAUSE_MS);
        }
    }

    return 0;
}

