// Structure to represent a bank account
typedef struct {
    int account_number;
    char account_holder[50];
    float balance;
} Account;

// Function prototypes
void initialize_accounts(Account accounts[]);
void display_accounts(Account accounts[]);
void deposit(Account accounts[], int account_num, float amount);
void withdraw(Account accounts[], int account_num, float amount);
void transfer(Account accounts[], int from_account, int to_account, float amount);

#define MAX_ACCOUNTS 10

int main() {
    Account accounts[MAX_ACCOUNTS];
    int choice, account_num, from_account, to_account;
    float amount;

    // Initialize accounts
    initialize_accounts(accounts);

    while (1) {
        // Display menu
        printf("\n===== Bank Transaction Simulator =====\n");
        printf("1. Display All Accounts\n");
        printf("2. Deposit\n");
        printf("3. Withdraw\n");
        printf("4. Transfer\n");
        printf("5. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                display_accounts(accounts);
                break;

            case 2:
                printf("Enter account number: ");
                scanf("%d", &account_num);
                printf("Enter deposit amount: ");
                scanf("%f", &amount);
                deposit(accounts, account_num, amount);
                break;

            case 3:
                printf("Enter account number: ");
                scanf("%d", &account_num);
                printf("Enter withdrawal amount: ");
                scanf("%f", &amount);
                withdraw(accounts, account_num, amount);
                break;

            case 4:
                printf("Enter source account number: ");
                scanf("%d", &from_account);
                printf("Enter destination account number: ");
                scanf("%d", &to_account);
                printf("Enter transfer amount: ");
                scanf("%f", &amount);
                transfer(accounts, from_account, to_account, amount);
                break;

            case 5:
                printf("Exiting...\n");
                exit(0);

            default:
                printf("Invalid choice. Please try again.\n");
        }
    }

    return 0;
}

// Initialize accounts with sample data
void initialize_accounts(Account accounts[]) {
    for (int i = 0; i < MAX_ACCOUNTS; i++) {
        accounts[i].account_number = i + 1001;
        sprintf(accounts[i].account_holder, "Account Holder %d", i + 1);
        accounts[i].balance = 1000.0 + (i * 500.0);
    }
}

// Display all account details
void display_accounts(Account accounts[]) {
    printf("\n===== Account Details =====\n");
    printf("%-15s %-20s %-10s\n", "Account Number", "Account Holder", "Balance");
    printf("---------------------------------------------\n");

    for (int i = 0; i < MAX_ACCOUNTS; i++) {
        printf("%-15d %-20s $%.2f\n", 
               accounts[i].account_number, 
               accounts[i].account_holder, 
               accounts[i].balance);
    }
}

// Deposit amount to an account
void deposit(Account accounts[], int account_num, float amount) {
    if (amount <= 0) {
        printf("Invalid deposit amount.\n");
        return;
    }

    for (int i = 0; i < MAX_ACCOUNTS; i++) {
        if (accounts[i].account_number == account_num) {
            accounts[i].balance += amount;
            printf("Deposit of $%.2f successful.\n", amount);
            printf("New balance: $%.2f\n", accounts[i].balance);
            return;
        }
    }

    printf("Account not found.\n");
}

// Withdraw amount from an account
void withdraw(Account accounts[], int account_num, float amount) {
    if (amount <= 0) {
        printf("Invalid withdrawal amount.\n");
        return;
    }

    for (int i = 0; i < MAX_ACCOUNTS; i++) {
        if (accounts[i].account_number == account_num) {
            if (accounts[i].balance >= amount) {
                accounts[i].balance -= amount;
                printf("Withdrawal of $%.2f successful.\n", amount);
                printf("New balance: $%.2f\n", accounts[i].balance);
            } else {
                printf("Insufficient funds.\n");
            }
            return;
        }
    }

    printf("Account not found.\n");
}

// Transfer amount between accounts
void transfer(Account accounts[], int from_account, int to_account, float amount) {
    int from_index = -1, to_index = -1;

    if (amount <= 0) {
        printf("Invalid transfer amount.\n");
        return;
    }

    // Find source and destination accounts
    for (int i = 0; i < MAX_ACCOUNTS; i++) {
        if (accounts[i].account_number == from_account) {
            from_index = i;
        }
        if (accounts[i].account_number == to_account) {
            to_index = i;
        }
    }

    // Check if accounts exist
    if (from_index == -1 || to_index == -1) {
        printf("One or both accounts not found.\n");
        return;
    }

    // Check sufficient balance
    if (accounts[from_index].balance >= amount) {
        accounts[from_index].balance -= amount;
        accounts[to_index].balance += amount;
        printf("Transfer of $%.2f from account %d to account %d successful.\n", 
               amount, from_account, to_account);
        printf("Source account new balance: $%.2f\n", accounts[from_index].balance);
        printf("Destination account new balance: $%.2f\n", accounts[to_index].balance);
    } else {
