#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

#define NUM_ACCOUNTS 10
#define INITIAL_BALANCE 1000
#define NUM_TRANSACTIONS 20

// Global array to hold account balances
double accounts[NUM_ACCOUNTS];
pthread_mutex_t locks[NUM_ACCOUNTS]; // One mutex per account

// Function to initialize accounts
void initialize_accounts() {
    for (int i = 0; i < NUM_ACCOUNTS; i++) {
        accounts[i] = INITIAL_BALANCE;
        pthread_mutex_init(&locks[i], NULL);
    }
}

// Function to perform a transaction
void* perform_transaction(void* arg) {
    int from, to;
    double amount;

    // Seed random number generator for each thread
    unsigned int seed = time(NULL) ^ pthread_self();

    for (int i = 0; i < NUM_TRANSACTIONS; i++) {
        // Randomly select accounts (must be different)
        do {
            from = rand_r(&seed) % NUM_ACCOUNTS;
            to = rand_r(&seed) % NUM_ACCOUNTS;
        } while (from == to);

        // Random amount between 1 and 100
        amount = (rand_r(&seed) % 100) + 1;

        // Lock both accounts (always lock lower numbered account first to prevent deadlock)
        int first = (from < to) ? from : to;
        int second = (from < to) ? to : from;

        pthread_mutex_lock(&locks[first]);
        pthread_mutex_lock(&locks[second]);

        // Check if sufficient funds
        if (accounts[from] >= amount) {
            accounts[from] -= amount;
            accounts[to] += amount;

            printf("Thread %lu: Transferred $%.2f from account %d to account %d\n", 
                  pthread_self(), amount, from, to);
        } else {
            printf("Thread %lu: Insufficient funds in account %d (Balance: $%.2f, Attempted: $%.2f)\n",
                  pthread_self(), from, accounts[from], amount);
        }

        // Unlock accounts
        pthread_mutex_unlock(&locks[second]);
        pthread_mutex_unlock(&locks[first]);

        // Sleep for random time between transactions
        usleep(rand_r(&seed) % 100000); // Up to 100ms
    }

    return NULL;
}

// Function to print account balances
void print_balances() {
    printf("\nFinal Account Balances:\n");
    double total = 0;
    for (int i = 0; i < NUM_ACCOUNTS; i++) {
        printf("Account %d: $%.2f\n", i, accounts[i]);
        total += accounts[i];
    }
    printf("Total balance across all accounts: $%.2f\n", total);
}

int main() {
    pthread_t threads[3]; // Create 3 threads for concurrent transactions

    initialize_accounts();

    // Create threads
    for (int i = 0; i < 3; i++) {
        pthread_create(&threads[i], NULL, perform_transaction, NULL);
    }

    // Wait for all threads to complete
    for (int i = 0; i < 3; i++) {
        pthread_join(threads[i], NULL);
    }

    print_balances();

    // Clean up mutexes
    for (int i = 0; i < NUM_ACCOUNTS; i++) {
        pthread_mutex_destroy(&locks[i]);
    }

    return 0;
}

