// Handles withdrawal transaction
void withdraw(struct BankAccount accounts[], int numAccounts) {
    int accNum;
    double amount;
    int index;

    printf("\n--- Withdraw ---");
    printf("\nEnter account number: ");
    if (scanf("%d", &accNum) != 1) {
        printf("Invalid input. Account number must be a number.\n");
        clearInputBuffer();
        return;
    }
    clearInputBuffer();

    index = findAccountIndex(accounts, numAccounts, accNum);

    if (index == -1) {
        printf("Account number %d not found.\n", accNum);
        return;
    }

    printf("Account found: %s (Current Balance: %.2f)\n", 
           accounts[index].accountHolderName, accounts[index].balance);
    printf("Enter amount to withdraw: ");
    if (scanf("%lf", &amount) != 1) {
        printf("Invalid input. Amount must be a number.\n");
        clearInputBuffer();
        return;
    }
    clearInputBuffer();

    if (amount <= 0) {
        printf("Withdrawal amount must be positive.\n");
    } else if (accounts[index].balance < amount) {
        printf("Insufficient funds! Current balance: %.2f.\n", accounts[index].balance);
    } else {
        accounts[index].balance -= amount;
        printf("Withdrawal successful! New balance for %s (Acc %d): %.2f\n",
               accounts[index].accountHolderName, accounts[index].accountNumber, accounts[index].balance);
    }
}

// Checks and displays account balance
void checkBalance(const struct BankAccount accounts[], int numAccounts) {
