        displayAccount(&accounts[index]);
        printf("-----------------------\n");
    }
}

// Helper function to find the index of an account by its number
// Returns the index if found, -1 otherwise
int findAccountIndex(const struct BankAccount accounts[], int numAccounts, int accNum) {
    for (int i = 0; i < numAccounts; i++) {
        if (accounts[i].accountNumber == accNum) {
            return i;
        }
    }
    return -1;
}

