        printf("Invalid account number.\n");
        return;
    }
    if (accounts[accountNumber - 1].balance < amount) {
        printf("Insufficient funds.\n");
        return;
    }
    accounts[accountNumber - 1].balance -= amount;
    printf("Withdrawn %.2f from account %d. New balance: %.2f\n", amount, accountNumber, accounts[accountNumber - 1].balance);
}

void displayBalance(int accountNumber) {
    if (accountNumber < 1 || accountNumber > NUM_ACCOUNTS) {
        printf("Invalid account number.\n");
        return;
    }
    printf("Account %d: %s, Balance: %.2f\n", accountNumber, accounts[accountNumber - 1].name, accounts[accountNumber - 1].balance);
}

