// Initialize accounts with default values
void initialize_accounts(Account accounts[]) {
    int account_numbers[MAX_ACCOUNTS] = {1001, 1002, 1003, 1004, 1005};
    char *account_holders[MAX_ACCOUNTS] = {"John Doe", "Jane Smith", "Mike Johnson", 
                                           "Sarah Williams", "David Brown"};
    float initial_balances[MAX_ACCOUNTS] = {5000.0, 7500.0, 3000.0, 6200.0, 4800.0};

    for (int i = 0; i < MAX_ACCOUNTS; i++) {
        accounts[i].account_number = account_numbers[i];
        strcpy(accounts[i].account_holder, account_holders[i]);
        accounts[i].balance = initial_balances[i];
    }
}

// Display account information
void display_accounts(Account accounts[]) {
    printf("\n--- Account Information ---\n");
    for (int i = 0; i < MAX_ACCOUNTS; i++) {
        printf("Account #%d\n", i + 1);
        printf("Account Number: %d\n", accounts[i].account_number);
        printf("Account Holder: %s\n", accounts[i].account_holder);
        printf("Balance: $%.2f\n\n", accounts[i].balance);
    }
}

// Deposit money into an account
void deposit(Account accounts[], int account_num, float amount) {
    if (account_num >= 0 && account_num < MAX_ACCOUNTS) {
        if (amount > 0) {
            accounts[account_num].balance += amount;
            printf("Deposit successful. New balance: $%.2f\n", 
                   accounts[account_num].balance);
        } else {
            printf("Invalid deposit amount!\n");
        }
    } else {
        printf("Invalid account number!\n");
    }
}

// Withdraw money from an account
void withdraw(Account accounts[], int account_num, float amount) {
    if (account_num >= 0 && account_num < MAX_ACCOUNTS) {
        if (amount > 0 && amount <= accounts[account_num].balance) {
            accounts[account_num].balance -= amount;
            printf("Withdrawal successful. New balance: $%.2f\n", 
                   accounts[account_num].balance);
        } else {
            printf("Invalid withdrawal amount or insufficient funds!\n");
        }
    } else {
        printf("Invalid account number!\n");
    }
}

// Transfer money between accounts
void transfer(Account accounts[], int from_account, int to_account, float amount) {
    if (from_account >= 0 && from_account < MAX_ACCOUNTS &&
        to_account >= 0 && to_account < MAX_ACCOUNTS) {

        if (from_account != to_account) {
            if (amount > 0 && amount <= accounts[from_account].balance) {
                accounts[from_account].balance -= amount;
                accounts[to_account].balance += amount;

                printf("Transfer successful!\n");
                printf("Source Account New Balance: $%.2f\n", 
                       accounts[from_account].balance);
                printf("Destination Account New Balance: $%.2f\n", 
                       accounts[to_account].balance);
            } else {
                printf("Invalid transfer amount or insufficient funds!\n");
            }
        } else {
            printf("Cannot transfer to the same account!\n");
        }
    } else {
        printf("Invalid account number(s)!\n");
    }
}

