// Deposit money into an account
void deposit(Account accounts[]) {
    int accountNum;
    float amount;

    printf("Enter account number: ");
    scanf("%d", &accountNum);

    int found = 0;
    for(int i = 0; i < NUM_ACCOUNTS; i++) {
        if(accounts[i].accountNumber == accountNum) {
            found = 1;
            printf("Enter amount to deposit: ");
            scanf("%f", &amount);

            if(amount > 0) {
                accounts[i].balance += amount;
                printf("Deposit successful. New balance: %.2f\n", accounts[i].balance);
            } else {
                printf("Invalid amount. Deposit amount must be positive.\n");
            }
            break;
        }
    }

    if(!found) {
        printf("Account not found.\n");
    }
}

// Withdraw money from an account
void withdraw(Account accounts[]) {
    int accountNum;
    float amount;

    printf("Enter account number: ");
    scanf("%d", &accountNum);

    int found = 0;
    for(int i = 0; i < NUM_ACCOUNTS; i++) {
        if(accounts[i].accountNumber == accountNum) {
            found = 1;
            printf("Enter amount to withdraw: ");
            scanf("%f", &amount);

            if(amount <= 0) {
                printf("Invalid amount. Withdrawal amount must be positive.\n");
            } else if(amount > accounts[i].balance) {
                printf("Insufficient balance.\n");
            } else {
                accounts[i].balance -= amount;
                printf("Withdrawal successful. New balance: %.2f\n", accounts[i].balance);
            }
            break;
        }
    }

    if(!found) {
        printf("Account not found.\n");
    }
}

// Transfer money between accounts
void transfer(Account accounts[]) {
    int fromAccount, toAccount;
    float amount;

    printf("Enter source account number: ");
    scanf("%d", &fromAccount);
    printf("Enter destination account number: ");
    scanf("%d", &toAccount);

    if(fromAccount == toAccount) {
        printf("Source and destination accounts cannot be the same.\n");
        return;
    }

    int fromIndex = -1, toIndex = -1;

    // Find both accounts
    for(int i = 0; i < NUM_ACCOUNTS; i++) {
        if(accounts[i].accountNumber == fromAccount) {
            fromIndex = i;
        }
        if(accounts[i].accountNumber == toAccount) {
            toIndex = i;
        }
    }

    if(fromIndex == -1 || toIndex == -1) {
        printf("One or both accounts not found.\n");
        return;
    }

    printf("Enter amount to transfer: ");
    scanf("%f", &amount);

    if(amount <= 0) {
        printf("Invalid amount. Transfer amount must be positive.\n");
    } else if(amount > accounts[fromIndex].balance) {
        printf("Insufficient balance in source account.\n");
    } else {
        accounts[fromIndex].balance -= amount;
        accounts[toIndex].balance += amount;
        printf("Transfer successful.\n");
        printf("Source account new balance: %.2f\n", accounts[fromIndex].balance);
        printf("Destination account new balance: %.2f\n", accounts[toIndex].balance);
    }
}

#include <stdio.h>
#include <stdlib.h> // For exit()
#include <limits.h> // Not strictly needed here, but good for larger integer limits

#define NUM_ACCOUNTS 5
