void list_all_accounts();
int find_account_index(int acc_num); // Helper to get array index from account number

// --- Main Function ---
int main() {
    int choice;

    initialize_accounts();

    do {
        display_menu();
        printf("Enter your choice: ");
        // Check if scanf successfully read an integer
        if (scanf("%d", &choice) != 1) {
            printf("Invalid input. Please enter a number.\n");
            // Clear the input buffer to prevent infinite loop
            while (getchar() != '\n');
            continue; // Skip to the next iteration of the loop
        }

        printf("\n"); // Newline for better formatting

        switch (choice) {
            case 1:
                deposit();
                break;
            case 2:
                withdraw();
                break;
            case 3:
