                break;
            case 6:
                printf("Exiting the banking system. Goodbye!\n");
                break;
            default:
                printf("Invalid choice. Please try again.\n");
        }
        printf("\nPress Enter to continue...");
        // Clear the input buffer and wait for Enter
        while (getchar() != '\n'); // Consume any leftover newline from previous scanf
        getchar(); // Wait for the user to press Enter

    } while (choice != 6);

    return 0;
}

// --- Function Implementations ---

// Initializes the 5 bank accounts with unique numbers and an initial balance
void initialize_accounts() {
    printf("Initializing bank accounts...\n");
    for (int i = 0; i < NUM_ACCOUNTS; i++) {
        accounts[i].account_number = i + 1; // Account numbers 1 to 5
        accounts[i].balance = INITIAL_BALANCE;
        printf("Account %d created with %.2f balance.\n", accounts[i].account_number, accounts[i].balance);
    }
    printf("All accounts initialized.\n\n");
}

// Displays the main menu options to the user
void display_menu() {
    printf("\n--- Bank Transaction System ---\n");
    printf("1. Deposit\n");
    printf("2. Withdraw\n");
    printf("3. Check Balance\n");
    printf("4. Transfer Funds\n");
    printf("5. List All Accounts\n");
    printf("6. Exit\n");
    printf("-------------------------------\n");
}

// Helper function to find the array index for a given account number
// Returns -1 if account not found
int find_account_index(int acc_num) {
    if (acc_num < 1 || acc_num > NUM_ACCOUNTS) {
        return -1; // Account number out of valid range
    }
    // Since account numbers are 1-based and array indices are 0-based
    // account_number - 1 directly gives the index
    return acc_num - 1;
}

// Handles deposit operations
void deposit() {
    int acc_num;
    double amount;
    int index;

    printf("--- Deposit Funds ---\n");
    printf("Enter account number: ");
    if (scanf("%d", &acc_num) != 1) {
        printf("Invalid input for account number.\n");
        while (getchar() != '\n'); // Clear buffer
        return;
    }

    index = find_account_index(acc_num);

    if (index == -1) {
        printf("Error: Account %d not found.\n", acc_num);
        return;
    }

    printf("Enter amount to deposit: ");
    if (scanf("%lf", &amount) != 1) {
        printf("Invalid input for amount.\n");
        while (getchar() != '\n'); // Clear buffer
        return;
    }

    if (amount <= 0) {
        printf("Error: Deposit amount must be positive.\n");
        return;
    }

    accounts[index].balance += amount;
    printf("Successfully deposited %.2f into account %d.\n", amount, acc_num);
    printf("New balance: %.2f\n", accounts[index].balance);
}

// Handles withdrawal operations
void withdraw() {
    int acc_num;
    double amount;
    int index;

    printf("--- Withdraw Funds ---\n");
    printf("Enter account number: ");
    if (scanf("%d", &acc_num) != 1) {
        printf("Invalid input for account number.\n");
        while (getchar() != '\n'); // Clear buffer
        return;
    }

    index = find_account_index(acc_num);

    if (index == -1) {
        printf("Error: Account %d not found.\n", acc_num);
        return;
    }

    printf("Enter amount to withdraw: ");
    if (scanf("%lf", &amount) != 1) {
        printf("Invalid input for amount.\n");
        while (getchar() != '\n'); // Clear buffer
        return;
    }

    if (amount <= 0) {
        printf("Error: Withdrawal amount must be positive.\n");
        return;
    }

    if (accounts[index].balance < amount) {
        printf("Error: Insufficient funds in account %d. Current balance: %.2f\n", acc_num, accounts[index].balance);
    } else {
        accounts[index].balance -= amount;
        printf("Successfully withdrew %.2f from account %d.\n", amount, acc_num);
        printf("New balance: %.2f\n", accounts[index].balance);
    }
}

// Handles checking balance for an account
void check_balance() {
    int acc_num;
    int index;

    printf("--- Check Balance ---\n");
    printf("Enter account number: ");
    if (scanf("%d", &acc_num) != 1) {
        printf("Invalid input for account number.\n");
        while (getchar() != '\n'); // Clear buffer
        return;
    }

    index = find_account_index(acc_num);

    if (index == -1) {
        printf("Error: Account %d not found.\n", acc_num);
    } else {
        printf("Account %d balance: %.2f\n", acc_num, accounts[index].balance);
    }
}

// Handles transferring funds between two accounts
void transfer() {
    int from_acc_num, to_acc_num;
    double amount;
    int from_index, to_index;

    printf("--- Transfer Funds ---\n");

    printf("Enter source account number: ");
    if (scanf("%d", &from_acc_num) != 1) {
        printf("Invalid input for source account number.\n");
        while (getchar() != '\n'); // Clear buffer
        return;
    }

    printf("Enter destination account number: ");
    if (scanf("%d", &to_acc_num) != 1) {
        printf("Invalid input for destination account number.\n");
        while (getchar() != '\n'); // Clear buffer
        return;
    }

    if (from_acc_num == to_acc_num) {
        printf("Error: Cannot transfer to the same account.\n");
        return;
    }

    from_index = find_account_index(from_acc_num);
    to_index = find_account_index(to_acc_num);

    if (from_index == -1) {
        printf("Error: Source account %d not found.\n", from_acc_num);
        return;
    }
    if (to_index == -1) {
        printf("Error: Destination account %d not found.\n", to_acc_num);
        return;
    }

    printf("Enter amount to transfer: ");
    if (scanf("%lf", &amount) != 1) {
        printf("Invalid input for amount.\n");
        while (getchar() != '\n'); // Clear buffer
        return;
    }

    if (amount <= 0) {
        printf("Error: Transfer amount must be positive.\n");
        return;
    }

    if (accounts[from_index].balance < amount) {
        printf("Error: Insufficient funds in source account %d. Current balance: %.2f\n", from_acc_num, accounts[from_index].balance);
    } else {
        accounts[from_index].balance -= amount;
        accounts[to_index].balance += amount;
        printf("Transferred %.2f from account %d to account %d.\n", amount, from_acc_num, to_acc_num);
        printf("Source account %d new balance: %.2f\n", from_acc_num, accounts[from_index].balance);
        printf("Destination account %d new balance: %.2f\n", to_acc_num, accounts[to_index].balance);
    }
}

// Lists the balance of all accounts
void list_all_accounts() {
    printf("--- All Account Balances ---\n");
    for (int i = 0; i < NUM_ACCOUNTS; i++) {
        printf("Account %d: %.2f\n", accounts[i].account_number, accounts[i].balance);
    }
    printf("----------------------------\n");
}

#include <stdio.h>
#include <string.h>

#define NUM_ACCOUNTS 5
#define NAME_LEN 50

typedef struct {
    int account_number;
    char name[NAME_LEN];
    double balance;
} Account;

void display_accounts(Account accs[], int n) {
    printf("\n%-10s %-20s %-10s\n", "Acc No.", "Name", "Balance");
    for (int i = 0; i < n; i++) {
        printf("%-10d %-20s $%-10.2lf\n", accs[i].account_number, accs[i].name, accs[i].balance);
    }
}

int find_account(Account accs[], int n, int acc_no) {
    for (int i = 0; i < n; i++) {
        if (accs[i].account_number == acc_no)
            return i;
    }
    return -1;
}

void deposit(Account accs[], int n) {
    int acc_no;
    double amount;
    printf("Enter account number: ");
    scanf("%d", &acc_no);
    int idx = find_account(accs, n, acc_no);
    if (idx == -1) {
        printf("Account not found!\n");
        return;
    }
    printf("Enter amount to deposit: ");
    scanf("%lf", &amount);
    if (amount <= 0) {
        printf("Invalid amount!\n");
        return;
    }
    accs[idx].balance += amount;
    printf("Deposited successfully. New balance: $%.2lf\n", accs[idx].balance);
}

void withdraw(Account accs[], int n) {
    int acc_no;
    double amount;
    printf("Enter account number: ");
    scanf("%d", &acc_no);
    int idx = find_account(accs, n, acc_no);
    if (idx == -1) {
        printf("Account not found!\n");
        return;
    }
    printf("Enter amount to withdraw: ");
    scanf("%lf", &amount);
    if (amount <= 0) {
        printf("Invalid amount!\n");
        return;
    }
    if (accs[idx].balance < amount) {
        printf("Insufficient balance!\n");
        return;
    }
    accs[idx].balance -= amount;
    printf("Withdrawn successfully. New balance: $%.2lf\n", accs[idx].balance);
}

void transfer(Account accs[], int n) {
    int from_acc, to_acc;
    double amount;
    printf("Enter your account number: ");
    scanf("%d", &from_acc);
    int from_idx = find_account(accs, n, from_acc);
    if (from_idx == -1) {
        printf("Your account not found!\n");
        return;
    }
    printf("Enter receiver's account number: ");
    scanf("%d", &to_acc);
    int to_idx = find_account(accs, n, to_acc);
    if (to_idx == -1) {
        printf("Receiver's account not found!\n");
        return;
    }
    printf("Enter amount to transfer: ");
    scanf("%lf", &amount);
    if (amount <= 0) {
        printf("Invalid amount!\n");
        return;
    }
    if (accs[from_idx].balance < amount) {
        printf("Insufficient balance!\n");
        return;
    }
    accs[from_idx].balance -= amount;
    accs[to_idx].balance += amount;
    printf("Transfer successful.\n");
    printf("Your new balance: $%.2lf\n", accs[from_idx].balance);
    printf("Receiver's new balance: $%.2lf\n", accs[to_idx].balance);
}

