            printf("Deposit successful. New balance: $%.2f\n", accounts[i].balance);
            return;
        }
    }

    printf("Account not found!\n");
}

// Function to withdraw money from an account
void withdraw() {
    int account_num;
    float amount;

    printf("Enter Account Number: ");
    scanf("%d", &account_num);

    for (int i = 0; i < num_accounts; i++) {
        if (accounts[i].account_number == account_num) {
            printf("Enter Withdrawal Amount: ");
            scanf("%f", &amount);

            if (amount > accounts[i].balance) {
                printf("Insufficient funds!\n");
                return;
            }

            accounts[i].balance -= amount;
            printf("Withdrawal successful. New balance: $%.2f\n", accounts[i].balance);
            return;
        }
    }

    printf("Account not found!\n");
}

// Function to transfer money between accounts
void transfer() {
    int from_account, to_account;
    float amount;

    printf("Enter Source Account Number: ");
    scanf("%d", &from_account);

    printf("Enter Destination Account Number: ");
    scanf("%d", &to_account);

    printf("Enter Transfer Amount: ");
    scanf("%f", &amount);

    int from_index = -1, to_index = -1;

    // Find source and destination account indices
    for (int i = 0; i < num_accounts; i++) {
        if (accounts[i].account_number == from_account)
            from_index = i;
        if (accounts[i].account_number == to_account)
            to_index = i;
    }

    // Check for valid accounts and sufficient funds
    if (from_index == -1 || to_index == -1) {
        printf("Invalid account number(s)!\n");
        return;
    }

    if (amount > accounts[from_index].balance) {
        printf("Insufficient funds for transfer!\n");
        return;
    }

    // Perform transfer
    accounts[from_index].balance -= amount;
    accounts[to_index].balance += amount;

    printf("Transfer successful!\n");
    printf("Source Account New Balance: $%.2f\n", accounts[from_index].balance);
    printf("Destination Account New Balance: $%.2f\n", accounts[to_index].balance);
}

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

#define NUM_ACCOUNTS 6
#define NUM_TRANSACTIONS 20

// Account structure
typedef struct {
    int id;
    double balance;
    pthread_mutex_t lock;
} Account;

// Global array of accounts
Account accounts[NUM_ACCOUNTS];

// Initialize accounts
void init_accounts() {
    for (int i = 0; i < NUM_ACCOUNTS; i++) {
        accounts[i].id = i + 1;
        accounts[i].balance = 1000.00; // Start each account with $1000
        pthread_mutex_init(&accounts[i].lock, NULL);
    }
}

// Perform a transaction between two accounts
void* perform_transaction(void* arg) {
    int from, to;
    double amount;

    // Randomly select two different accounts
    from = rand() % NUM_ACCOUNTS;
    do {
        to = rand() % NUM_ACCOUNTS;
    } while (to == from);

    // Random amount between $10 and $200
    amount = 10.0 + (rand() % 190);

    // To avoid deadlock, always lock the account with the smaller ID first
    int first = (from < to) ? from : to;
    int second = (from < to) ? to : from;

    // Lock both accounts
    pthread_mutex_lock(&accounts[first].lock);
    pthread_mutex_lock(&accounts[second].lock);

    // Perform the transaction if sufficient funds
    if (accounts[from].balance >= amount) {
        accounts[from].balance -= amount;
        accounts[to].balance += amount;
        printf("Transferred $%.2f from Account %d to Account %d\n", 
               amount, accounts[from].id, accounts[to].id);
    } else {
        printf("Failed to transfer $%.2f from Account %d (Insufficient funds)\n", 
               amount, accounts[from].id);
    }

    // Unlock both accounts
    pthread_mutex_unlock(&accounts[second].lock);
    pthread_mutex_unlock(&accounts[first].lock);

    return NULL;
}

// Display account balances
void display_balances() {
    printf("\nCurrent Account Balances:\n");
    for (int i = 0; i < NUM_ACCOUNTS; i++) {
        printf("Account %d: $%.2f\n", accounts[i].id, accounts[i].balance);
    }
}

int main() {
    pthread_t threads[NUM_TRANSACTIONS];

    // Seed random number generator
    srand(time(NULL));

    // Initialize accounts
    init_accounts();

    printf("Starting bank transaction simulation with %d accounts...\n", NUM_ACCOUNTS);
    display_balances();

    // Create threads to perform transactions
    for (int i = 0; i < NUM_TRANSACTIONS; i++) {
        pthread_create(&threads[i], NULL, perform_transaction, NULL);
        // Small delay to make output more readable
        usleep(100000);
    }

    // Wait for all threads to complete
    for (int i = 0; i < NUM_TRANSACTIONS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Display final balances
    display_balances();

    // Clean up mutexes
    for (int i = 0; i < NUM_ACCOUNTS; i++) {
        pthread_mutex_destroy(&accounts[i].lock);
    }

    return 0;
}

