    } else {
        printf("Balance for Account %d: $%.2f\n", accountNumber, accountBalances[accountNumber - 1]);
    }
}

// Handles fund transfers between two accounts
void transfer() {
    int fromAccount, toAccount;
    double amount;

    printf("\n--- TRANSFER FUNDS ---\n");
    printf("Enter source account number (1 to %d): ", NUM_ACCOUNTS);
    scanf("%d", &fromAccount);

    if (!isValidAccountNumber(fromAccount)) {
        printf("Invalid source account number.\n");
        return;
    }

    printf("Enter destination account number (1 to %d): ", NUM_ACCOUNTS);
    scanf("%d", &toAccount);

    if (!isValidAccountNumber(toAccount)) {
        printf("Invalid destination account number.\n");
        return;
    }

    if (fromAccount == toAccount) {
        printf("Cannot transfer to the same account.\n");
        return;
    }

    printf("Enter amount to transfer: $");
    scanf("%lf", &amount);

    if (amount <= 0) {
        printf("Transfer amount must be positive.\n");
    } else if (accountBalances[fromAccount - 1] < amount) {
        printf("Insufficient funds in Account %d to transfer. Current balance: $%.2f\n",
               fromAccount, accountBalances[fromAccount - 1]);
    } else {
        accountBalances[fromAccount - 1] -= amount;
        accountBalances[toAccount - 1] += amount;
        printf("Successfully transferred $%.2f from Account %d to Account %d.\n",
               amount, fromAccount, toAccount);
        printf("New balance for Account %d: $%.2f\n", fromAccount, accountBalances[fromAccount - 1]);
        printf("New balance for Account %d: $%.2f\n", toAccount, accountBalances[toAccount - 1]);
    }
}

// Displays the balance of all accounts
void displayAllAccounts() {
    printf("\n--- ALL ACCOUNT BALANCES ---\n");
    for (int i = 0; i < NUM_ACCOUNTS; i++) {
        printf("Account %d: $%.2f\n", i + 1, accountBalances[i]);
    }
}

// Helper function to validate account numbers
int isValidAccountNumber(int accNum) {
    return (accNum >= 1 && accNum <= NUM_ACCOUNTS);
}

