// --- Function Definitions ---

/**
 * @brief Initializes all bank account balances to 0.0.
 */
void initialize_accounts() {
    for (int i = 0; i < NUM_ACCOUNTS; i++) {
        account_balances[i] = 0.0;
    }
}

/**
 * @brief Displays the main menu of banking operations.
 */
void display_menu() {
    printf("--- Bank Operations Menu ---\n");
    printf("1. Deposit\n");
    printf("2. Withdraw\n");
    printf("3. Check Balance\n");
    printf("4. Transfer Funds\n");
    printf("5. View All Accounts\n");
    printf("6. Exit\n");
    printf("----------------------------\n");
}

/**
 * @brief Prompts the user for an account number and validates it.
 * @return The valid account number (0 to NUM_ACCOUNTS-1).
 */
int get_account_number() {
    int account_num;
    while (true) {
        printf("Enter account number (1 to %d): ", NUM_ACCOUNTS);
        if (scanf("%d", &account_num) != 1) {
            printf("Invalid input. Please enter a number.\n");
            while (getchar() != '\n'); // Clear buffer
            continue;
        }
        while (getchar() != '\n'); // Clear buffer

        if (account_num >= 1 && account_num <= NUM_ACCOUNTS) {
            return account_num - 1; // Adjust to 0-indexed array
        } else {
            printf("Account number %d is invalid. Please enter a number between 1 and %d.\n", account_num, NUM_ACCOUNTS);
        }
    }
}

/**
 * @brief Prompts the user for a positive amount and validates it.
 * @return The valid positive amount.
 */
float get_positive_amount() {
    float amount;
    while (true) {
        printf("Enter amount: ");
        if (scanf("%f", &amount) != 1) {
            printf("Invalid input. Please enter a number.\n");
            while (getchar() != '\n'); // Clear buffer
            continue;
        }
        while (getchar() != '\n'); // Clear buffer

        if (amount > 0) {
            return amount;
        } else {
            printf("Amount must be positive. Please try again.\n");
        }
    }
}

/**
 * @brief Handles the deposit operation.
 * Prompts for account number and amount, then adds to the balance.
 */
void deposit() {
    printf("--- Deposit Funds ---\n");
    int acc_idx = get_account_number();
    float amount = get_positive_amount();

    account_balances[acc_idx] += amount;
    printf("Successfully deposited %.2f into account %d.\n", amount, acc_idx + 1);
    printf("New balance for account %d: %.2f\n", acc_idx + 1, account_balances[acc_idx]);
}

/**
 * @brief Handles the withdrawal operation.
 * Prompts for account number and amount, checks for sufficient funds, then withdraws.
 */
void withdraw() {
    printf("--- Withdraw Funds ---\n");
    int acc_idx = get_account_number();
    float amount = get_positive_amount();

    if (account_balances[acc_idx] >= amount) {
        account_balances[acc_idx] -= amount;
        printf("Successfully withdrew %.2f from account %d.\n", amount, acc_idx + 1);
        printf("New balance for account %d: %.2f\n", acc_idx + 1, account_balances[acc_idx]);
    } else {
        printf("Insufficient funds in account %d. Current balance: %.2f\n", acc_idx + 1, account_balances[acc_idx]);
        printf("Withdrawal of %.2f failed.\n", amount);
    }
}

/**
 * @brief Handles checking an account balance.
 * Prompts for account number and displays its current balance.
 */
void check_balance() {
    printf("--- Check Balance ---\n");
    int acc_idx = get_account_number();
    printf("Balance for account %d: %.2f\n", acc_idx + 1, account_balances[acc_idx]);
}

/**
 * @brief Handles transferring funds between two accounts.
 * Prompts for source and destination accounts and amount, validates, then transfers.
 */
void transfer() {
    printf("--- Transfer Funds ---\n");
    printf("From Account:\n");
    int from_acc_idx = get_account_number();

    printf("To Account:\n");
    int to_acc_idx = get_account_number();

    if (from_acc_idx == to_acc_idx) {
        printf("Cannot transfer to the same account. Please choose different accounts.\n");
        return;
    }

    float amount = get_positive_amount();

    if (account_balances[from_acc_idx] >= amount) {
        account_balances[from_acc_idx] -= amount;
        account_balances[to_acc_idx] += amount;
        printf("Successfully transferred %.2f from account %d to account %d.\n", amount, from_acc_idx + 1, to_acc_idx + 1);
        printf("New balance for account %d: %.2f\n", from_acc_idx + 1, account_balances[from_acc_idx]);
        printf("New balance for account %d: %.2f\n", to_acc_idx + 1, account_balances[to_acc_idx]);
    } else {
        printf("Insufficient funds in account %d for transfer. Current balance: %.2f\n", from_acc_idx + 1, account_balances[from_acc_idx]);
        printf("Transfer of %.2f failed.\n", amount);
    }
}

/**
 * @brief Displays the current balance for all accounts.
 */
void view_all_accounts() {
    printf("--- All Account Balances ---\n");
    for (int i = 0; i < NUM_ACCOUNTS; i++) {
        printf("Account %d: %.2f\n", i + 1, account_balances[i]);
    }
    printf("----------------------------\n");
}

