        return;
    }
    int idx_from = findAccount(accounts, from_acc);
    int idx_to = findAccount(accounts, to_acc);
    if (idx_from == -1 || idx_to == -1) {
        printf("Invalid account number(s).\n");
        return;
    }
    printf("Enter amount to transfer: ");
    scanf("%lf", &amount);
    if (amount > 0 && amount <= accounts[idx_from].balance) {
        accounts[idx_from].balance -= amount;
        accounts[idx_to].balance += amount;
        printf("Transfer successful.\n");
        printf("Sender new balance: %.2lf\n", accounts[idx_from].balance);
        printf("Recipient new balance: %.2lf\n", accounts[idx_to].balance);
    } else {
        printf("Insufficient funds or invalid amount.\n");
    }
}

