#define MAX_BLOCKS 10
#define MAX_PROCESSES 10

int memory_blocks[MAX_BLOCKS];
int process_sizes[MAX_PROCESSES];
int allocated[MAX_PROCESSES];

void initialize() {
    for (int i = 0; i < MAX_BLOCKS; i++) {
        memory_blocks[i] = rand() % 100 + 50; // Random block sizes between 50 and 150
    }
    for (int i = 0; i < MAX_PROCESSES; i++) {
        process_sizes[i] = rand() % 100 + 10; // Random process sizes between 10 and 100
        allocated[i] = -1; // -1 means not allocated
    }
}

void display() {
    printf("Memory Blocks:\n");
    for (int i = 0; i < MAX_BLOCKS; i++) {
        printf("Block %d: %d KB\n", i, memory_blocks[i]);
    }
    printf("\nProcess Sizes:\n");
    for (int i = 0; i < MAX_PROCESSES; i++) {
        printf("Process %d: %d KB\n", i, process_sizes[i]);
    }
    printf("\nAllocation:\n");
    for (int i = 0; i < MAX_PROCESSES; i++) {
        if (allocated[i] != -1) {
            printf("Process %d is allocated to Block %d\n", i, allocated[i]);
        } else {
            printf("Process %d is not allocated\n", i);
        }
    }
}

void first_fit() {
    for (int i = 0; i < MAX_PROCESSES; i++) {
        for (int j = 0; j < MAX_BLOCKS; j++) {
            if (memory_blocks[j] >= process_sizes[i]) {
                allocated[i] = j;
                memory_blocks[j] -= process_sizes[i];
                break;
            }
        }
    }
}

void best_fit() {
    for (int i = 0; i < MAX_PROCESSES; i++) {
        int best_index = -1;
        for (int j = 0; j < MAX_BLOCKS; j++) {
            if (memory_blocks[j] >= process_sizes[i]) {
                if (best_index == -1 || memory_blocks[j] < memory_blocks[best_index]) {
                    best_index = j;
                }
            }
        }
        if (best_index != -1) {
            allocated[i] = best_index;
            memory_blocks[best_index] -= process_sizes[i];
        }
    }
}

void worst_fit() {
    for (int i = 0; i < MAX_PROCESSES; i++) {
        int worst_index = -1;
        for (int j = 0; j < MAX_BLOCKS; j++) {
            if (memory_blocks[j] >= process_sizes[i]) {
                if (worst_index == -1 || memory_blocks[j] > memory_blocks[worst_index]) {
                    worst_index = j;
                }
            }
        }
        if (worst_index != -1) {
            allocated[i] = worst_index;
            memory_blocks[worst_index] -= process_sizes[i];
        }
    }
}

