#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <limits.h> // For INT_MAX

// --- Configuration ---
#define TOTAL_MEMORY_SIZE 1024 // Total size of our simulated memory
#define MAX_PROCESSES 100      // Maximum number of processes we can track
#define INITIAL_PROCESS_ID 1   // Starting ID for allocated processes

// --- Data Structures ---

// Represents a memory block
typedef struct MemoryBlock {
    int id;           // Unique ID for the block (or process ID if allocated)
    int size;         // Size of the block
    int start_address; // Starting address of the block in memory
    bool is_free;     // True if the block is free, false if allocated
} MemoryBlock;

// Our simulated memory will be a dynamic array of MemoryBlock structures
MemoryBlock *memory_blocks = NULL;
int num_blocks = 0; // Current number of memory blocks

// --- Global Variables ---
int next_process_id = INITIAL_PROCESS_ID; // To assign unique IDs to new allocations

// --- Function Prototypes ---
void initialize_memory(int total_size);
void print_memory_status();
void allocate_memory(int requested_size, const char *strategy_name, int strategy_type);
void deallocate_memory(int process_id);
void coalesce_memory();

// Allocation Strategies
void first_fit_allocate(int requested_size);
void best_fit_allocate(int requested_size);
void worst_fit_allocate(int requested_size);

// Helper function to split a block
void split_block(int block_index, int requested_size, int process_id);

// --- Main Program ---
int main() {
    printf("--- Memory Allocation Simulator ---\n");
    initialize_memory(TOTAL_MEMORY_SIZE);
    print_memory_status();

    printf("\n--- Allocating (First Fit) ---\n");
    allocate_memory(100, "First Fit", 0); // 0 for First Fit
    allocate_memory(250, "First Fit", 0);
    allocate_memory(50, "First Fit", 0);
    print_memory_status();

    printf("\n--- Deallocating Process ID 2 ---\n");
    deallocate_memory(2);
    print_memory_status();

    printf("\n--- Allocating (Best Fit) ---\n");
    allocate_memory(75, "Best Fit", 1); // 1 for Best Fit
    allocate_memory(300, "Best Fit", 1);
    print_memory_status();

    printf("\n--- Deallocating Process ID 1 ---\n");
    deallocate_memory(1);
    print_memory_status();

    printf("\n--- Deallocating Process ID 3 ---\n");
    deallocate_memory(3);
    print_memory_status();

    printf("\n--- Allocating (Worst Fit) ---\n");
    allocate_memory(400, "Worst Fit", 2); // 2 for Worst Fit
    allocate_memory(10, "Worst Fit", 2);
    print_memory_status();

    printf("\n--- Deallocating Process ID 4 ---\n");
    deallocate_memory(4);
    print_memory_status();

    printf("\n--- Deallocating Process ID 5 ---\n");
    deallocate_memory(5);
    print_memory_status();

    printf("\n--- Deallocating Process ID 6 ---\n");
    deallocate_memory(6);
    print_memory_status();

    // Free dynamically allocated memory for blocks
    if (memory_blocks != NULL) {
        free(memory_blocks);
        memory_blocks = NULL;
    }

    return 0;
}

// --- Function Definitions ---

// Initializes memory as one large free block
void initialize_memory(int total_size) {
    memory_blocks = (MemoryBlock *)malloc(sizeof(MemoryBlock));
    if (memory_blocks == NULL) {
        fprintf(stderr, "Memory allocation failed for initial block!\n");
        exit(EXIT_FAILURE);
    }
    num_blocks = 1;

    memory_blocks[0].id = 0; // ID 0 for the initial large free block
    memory_blocks[0].size = total_size;
    memory_blocks[0].start_address = 0;
    memory_blocks[0].is_free = true;

    printf("Memory initialized with %d bytes.\n", total_size);
}

// Prints the current status of all memory blocks
void print_memory_status() {
    printf("\n--- Current Memory Status (%d blocks) ---\n", num_blocks);
    printf("------------------------------------------------------------------\n");
    printf("| %-5s | %-10s | %-8s | %-8s | %-12s |\n", "Index", "ID/Proc", "Size", "Address", "Status");
    printf("------------------------------------------------------------------\n");
    for (int i = 0; i < num_blocks; i++) {
        printf("| %-5d | %-10d | %-8d | %-8d | %-12s |\n",
               i,
               memory_blocks[i].id,
               memory_blocks[i].size,
               memory_blocks[i].start_address,
               memory_blocks[i].is_free ? "FREE" : "ALLOCATED");
    }
    printf("------------------------------------------------------------------\n");
}

// General allocation function that dispatches to specific strategies
void allocate_memory(int requested_size, const char *strategy_name, int strategy_type) {
    printf("\nAttempting to allocate %d bytes using %s...\n", requested_size, strategy_name);

    if (requested_size <= 0) {
        printf("  Error: Requested size must be positive.\n");
        return;
    }

    switch (strategy_type) {
        case 0: first_fit_allocate(requested_size); break;  // First Fit
        case 1: best_fit_allocate(requested_size); break;   // Best Fit
        case 2: worst_fit_allocate(requested_size); break;  // Worst Fit
        default: printf("  Error: Unknown allocation strategy.\n"); return;
    }
}

// Helper function to split a free block if it's larger than the requested size
void split_block(int block_index, int requested_size, int process_id) {
    MemoryBlock *block = &memory_blocks[block_index];

    // If the block is significantly larger, split it
    // A small remaining block might be less useful, but for this simulation, we always split.
    if (block->size > requested_size) {
        // Create a new free block for the remaining space
        MemoryBlock new_free_block;
        new_free_block.id = 0; // ID 0 for free blocks
        new_free_block.size = block->size - requested_size;
        new_free_block.start_address = block->start_address + requested_size;
        new_free_block.is_free = true;

        // Resize the allocated block
        block->size = requested_size;

        // Shift blocks after this one to make space for the new free block
        num_blocks++;
        memory_blocks = (MemoryBlock *)realloc(memory_blocks, num_blocks * sizeof(MemoryBlock));
        if (memory_blocks == NULL) {
            fprintf(stderr, "Memory re-allocation failed during split!\n");
            exit(EXIT_FAILURE);
        }

        for (int i = num_blocks - 1; i > block_index + 1; i--) {
            memory_blocks[i] = memory_blocks[i - 1];
        }
        memory_blocks[block_index + 1] = new_free_block;
    }
    // Mark the block as allocated and assign process ID
    block->id = process_id;
    block->is_free = false;
    printf("  Allocated %d bytes for Process ID %d at address %d.\n", requested_size, process_id, block->start_address);
}

// --- Allocation Strategies ---

// First Fit: Finds the first free block that is large enough
void first_fit_allocate(int requested_size) {
    for (int i = 0; i < num_blocks; i++) {
        if (memory_blocks[i].is_free && memory_blocks[i].size >= requested_size) {
            split_block(i, requested_size, next_process_id++);
            return;
        }
    }
    printf("  Allocation failed: No suitable free block found for %d bytes (First Fit).\n", requested_size);
}

// Best Fit: Finds the smallest free block that is large enough
void best_fit_allocate(int requested_size) {
    int best_fit_index = -1;
    int min_fragment = INT_MAX; // To find the smallest difference (best fit)

    for (int i = 0; i < num_blocks; i++) {
        if (memory_blocks[i].is_free && memory_blocks[i].size >= requested_size) {
            int current_fragment = memory_blocks[i].size - requested_size;
            if (current_fragment < min_fragment) {
                min_fragment = current_fragment;
                best_fit_index = i;
            }
        }
    }

    if (best_fit_index != -1) {
        split_block(best_fit_index, requested_size, next_process_id++);
    } else {
        printf("  Allocation failed: No suitable free block found for %d bytes (Best Fit).\n", requested_size);
    }
}

// Worst Fit: Finds the largest free block
void worst_fit_allocate(int requested_size) {
    int worst_fit_index = -1;
    int max_size_found = -1;

    for (int i = 0; i < num_blocks; i++) {
        if (memory_blocks[i].is_free && memory_blocks[i].size >= requested_size) {
            if (memory_blocks[i].size > max_size_found) {
                max_size_found = memory_blocks[i].size;
                worst_fit_index = i;
            }
        }
    }

    if (worst_fit_index != -1) {
        split_block(worst_fit_index, requested_size, next_process_id++);
    } else {
        printf("  Allocation failed: No suitable free block found for %d bytes (Worst Fit).\n", requested_size);
    }
}

// Deallocates memory for a given process ID
void deallocate_memory(int process_id) {
    printf("\nAttempting to deallocate memory for Process ID %d...\n", process_id);
    bool found = false;
    for (int i = 0; i < num_blocks; i++) {
        if (!memory_blocks[i].is_free && memory_blocks[i].id == process_id) {
            memory_blocks[i].is_free = true;
            memory_blocks[i].id = 0; // Mark as free with ID 0
            printf("  Deallocated %d bytes for Process ID %d at address %d.\n",
                   memory_blocks[i].size, process_id, memory_blocks[i].start_address);
            found = true;
            break; // Assuming one block per process ID for simplicity
        }
    }

    if (!found) {
        printf("  Deallocation failed: Process ID %d not found or already free.\n", process_id);
    } else {
        coalesce_memory(); // Try to merge adjacent free blocks after deallocation
    }
}

// Merges adjacent free memory blocks
void coalesce_memory() {
    printf("  Coalescing free memory blocks...\n");
    if (num_blocks <= 1) {
        return; // Nothing to coalesce
    }

    int current_write_index = 0; // Where the next block will be placed in the compacted array

    for (int i = 0; i < num_blocks; i++) {
        if (memory_blocks[i].is_free) {
            // Check if the next block is also free and adjacent
            if (i + 1 < num_blocks && memory_blocks[i + 1].is_free) {
                // Merge current and next free block
                memory_blocks[i].size += memory_blocks[i + 1].size;
                // Don't copy the next block, effectively removing it
                // Increment i to skip the merged next block
                i++;
            }
        }
        // Copy the (potentially merged) block to the new compacted position
        memory_blocks[current_write_index++] = memory_blocks[i];
    }

    // Update num_blocks and reallocate memory to free up unused space
    if (current_write_index < num_blocks) {
        // Correct the start_address after merging if there were gaps
        // This is crucial for maintaining a contiguous block list in memory.
        int current_address = 0;
        for (int i = 0; i < current_write_index; i++) {
            memory_blocks[i].start_address = current_address;
            current_address += memory_blocks[i].size;
        }

        num_blocks = current_write_index;
        memory_blocks = (MemoryBlock *)realloc(memory_blocks, num_blocks * sizeof(MemoryBlock));
        if (memory_blocks == NULL && num_blocks > 0) { // Realloc can return NULL if size is 0
            fprintf(stderr, "Memory re-allocation failed during coalesce!\n");
            exit(EXIT_FAILURE);
        } else if (num_blocks == 0) { // All memory is perhaps freed and coaleased into nothing (unlikely for this sim)
             free(memory_blocks);
             memory_blocks = NULL;
        }
        printf("  Memory coalesced. New block count: %d.\n", num_blocks);
    } else {
        printf("  No blocks were coalesced (already optimized).\n");
    }
}

