#include <stdio.h>
#include <stdlib.h>

// Structure to represent a memory block
typedef struct {
    int size;
    int allocated;
} MemoryBlock;

// Function to simulate memory allocation using First Fit strategy
void firstFit(MemoryBlock* blocks, int numBlocks, int requestSize) {
    for (int i = 0; i < numBlocks; i++) {
        if (blocks[i].size >= requestSize &&!blocks[i].allocated) {
            blocks[i].allocated = 1;
            printf("Allocated %d bytes of memory at block %d\n", requestSize, i + 1);
            return;
        }
    }
    printf("Insufficient memory\n");
}

// Function to simulate memory allocation using Best Fit strategy
void bestFit(MemoryBlock* blocks, int numBlocks, int requestSize) {
    int bestIndex = -1;
    int bestSize = -1;
    for (int i = 0; i < numBlocks; i++) {
        if (blocks[i].size >= requestSize &&!blocks[i].allocated) {
            if (bestIndex == -1 || blocks[i].size < bestSize) {
                bestIndex = i;
                bestSize = blocks[i].size;
            }
        }
    }
    if (bestIndex!= -1) {
        blocks[bestIndex].allocated = 1;
        printf("Allocated %d bytes of memory at block %d\n", requestSize, bestIndex + 1);
    } else {
        printf("Insufficient memory\n");
    }
}

// Function to simulate memory allocation using Worst Fit strategy
void worstFit(MemoryBlock* blocks, int numBlocks, int requestSize) {
    int worstIndex = -1;
    int worstSize = -1;
    for (int i = 0; i < numBlocks; i++) {
        if (blocks[i].size >= requestSize &&!blocks[i].allocated) {
            if (worstIndex == -1 || blocks[i].size > worstSize) {
                worstIndex = i;
                worstSize = blocks[i].size;
            }
        }
    }
    if (worstIndex!= -1) {
        blocks[worstIndex].allocated = 1;
        printf("Allocated %d bytes of memory at block %d\n", requestSize, worstIndex + 1);
    } else {
        printf("Insufficient memory\n");
    }
}

int main() {
    int numBlocks;
    printf("Enter the number of memory blocks: ");
    scanf("%d", &numBlocks);

    MemoryBlock* blocks = (MemoryBlock*) malloc(numBlocks * sizeof(MemoryBlock));

    for (int i = 0; i < numBlocks; i++) {
        printf("Enter the size of block %d: ", i + 1);
        scanf("%d", &blocks[i].size);
        blocks[i].allocated = 0;
    }

    int choice;
    printf("Enter the fit strategy (1 - First Fit, 2 - Best Fit, 3 - Worst Fit): ");
    scanf("%d", &choice);

    int requestSize;
    printf("Enter the size of the memory request: ");
    scanf("%d", &requestSize);

    switch (choice) {
        case 1:
            firstFit(blocks, numBlocks, requestSize);
            break;
        case 2:
            bestFit(blocks, numBlocks, requestSize);
            break;
        case 3:
            worstFit(blocks, numBlocks, requestSize);
            break;
        default:
            printf("Invalid choice\n");
    }

    free(blocks);
    return 0;
}

