// Structure to represent a memory block
typedef struct MemoryBlock {
    int start;
    int end;
    int allocated;  // 0 if free, 1 if allocated
} MemoryBlock;

int main() {
    // Initialize memory blocks
    int num_blocks = 5;
    MemoryBlock blocks[] = {
        {0, 200, 0},   // Free
        {201, 500, 1}, // Allocated
        {501, 700, 0}, // Free
        {701, 900, 0}, // Free
        {901, 999, 1}  // Allocated
    };

    // Function to display memory blocks
    void display_blocks(MemoryBlock *blocks, int num_blocks) {
        for (int i = 0; i < num_blocks; i++) {
            printf("Block %d: Start = %d, End = %d, Allocated = %s\n", i, blocks[i].start, blocks[i].end, blocks[i].allocated ? "Yes" : "No");
        }
    }

    // Function to allocate memory using First Fit
    int allocate_memory(MemoryBlock *blocks, int num_blocks, int process_size, int *block_index) {
        for (int i = 0; i < num_blocks; i++) {
            if (!blocks[i].allocated && (blocks[i].end - blocks[i].start + 1) >= process_size) {
                blocks[i].allocated = 1;
                *block_index = i;
                return 1; // Memory allocated successfully
            }
        }
        return 0; // No suitable block found
    }

    // Function to deallocate memory
    void deallocate_memory(MemoryBlock *blocks, int block_index) {
        if (block_index >= 0 && block_index < num_blocks) {
            blocks[block_index].allocated = 0;
        } else {
            printf("Invalid block index for deallocation.\n");
        }
    }

    int choice, process_size, block_index;

    while (1) {
        printf("\nMemory Allocation Simulator\n");
        printf("1. Allocate Memory\n");
        printf("2. Deallocate Memory\n");
        printf("3. Display Memory Blocks\n");
        printf("4. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                printf("Enter the size of the process: ");
                scanf("%d", &process_size);
                if (allocate_memory(blocks, num_blocks, process_size, &block_index)) {
                    printf("Memory allocated in block %d\n", block_index);
                } else {
                    printf("No suitable block found for allocation.\n");
                }
                break;
            case 2:
                printf("Enter the block index to deallocate: ");
                scanf("%d", &block_index);
                deallocate_memory(blocks, block_index);
                printf("Memory deallocated from block %d\n", block_index);
                break;
            case 3:
                display_blocks(blocks, num_blocks);
                break;
            case 4:
                exit(0);
            default:
                printf("Invalid choice. Please try again.\n");
        }
    }

    return 0;
}

