#define MAX_VERTICES 100

// Function prototypes
void dijkstra(int graph[MAX_VERTICES][MAX_VERTICES], int vertices, int start);
int minDistance(int dist[], bool visited[], int vertices);
void printStep(int dist[], bool visited[], int vertices, int current);
void printPath(int parent[], int j);

// Dijkstra's algorithm implementation
void dijkstra(int graph[MAX_VERTICES][MAX_VERTICES], int vertices, int start) {
    int dist[MAX_VERTICES];     // Shortest distance from start to each vertex
    bool visited[MAX_VERTICES]; // Visited vertices
    int parent[MAX_VERTICES];   // Parent vertices to reconstruct path

    // Initialize distances, visited array, and parent array
    for (int i = 0; i < vertices; i++) {
        dist[i] = INT_MAX;
        visited[i] = false;
        parent[i] = -1;
    }

    // Distance from start vertex to itself is 0
    dist[start] = 0;

    // Find shortest path for all vertices
    for (int count = 0; count < vertices - 1; count++) {
        // Pick minimum distance vertex from unvisited vertices
        int u = minDistance(dist, visited, vertices);

        // Mark selected vertex as visited
        visited[u] = true;

        // Print current step
        printf("\nStep %d:\n", count + 1);
        printStep(dist, visited, vertices, u);

        // Update distance values of adjacent vertices
        for (int v = 0; v < vertices; v++) {
            // Update dist[v] if:
            // 1. Vertex is not visited
            // 2. Edge exists
            // 3. Current distance through u is smaller
            if (!visited[v] && 
                graph[u][v] && 
                dist[u] != INT_MAX && 
                dist[u] + graph[u][v] < dist[v]) {

                dist[v] = dist[u] + graph[u][v];
                parent[v] = u;
            }
        }
    }

    // Print final results and paths
    printf("\nFinal Shortest Paths:\n");
    for (int i = 0; i < vertices; i++) {
        if (i != start) {
            printf("From %d to %d: ", start, i);
            if (dist[i] == INT_MAX) {
                printf("No path\n");
            } else {
                printf("Distance = %d, Path = ", dist[i]);
                printPath(parent, i);
                printf("\n");
            }
        }
    }
}

// Find vertex with minimum distance
int minDistance(int dist[], bool visited[], int vertices) {
    int min = INT_MAX, min_index;

    for (int v = 0; v < vertices; v++) {
        if (!visited[v] && dist[v] <= min) {
            min = dist[v];
            min_index = v;
        }
    }

    return min_index;
}

// Print current step details
void printStep(int dist[], bool visited[], int vertices, int current) {
    printf("Current Vertex: %d\n", current);

    printf("Distances:   ");
    for (int i = 0; i < vertices; i++) {
        if (dist[i] == INT_MAX)
            printf("∞ ");
        else
            printf("%d ", dist[i]);
    }
    printf("\n");

    printf("Visited:     ");
    for (int i = 0; i < vertices; i++) {
        printf("%c ", visited[i] ? 'T' : 'F');
    }
    printf("\n");
}

// Reconstruct and print path
void printPath(int parent[], int j) {
    // Base case: if parent is -1, we've reached source
    if (parent[j] == -1)
        return;

    printPath(parent, parent[j]);
    printf("%d ", j);
}

