// Function to find the vertex with minimum distance value
int minDistance(int dist[], bool sptSet[]) {
    int min = INT_MAX, min_index;

    for (int v = 0; v < V; v++) {
        if (!sptSet[v] && dist[v] <= min) {
            min = dist[v];
            min_index = v;
        }
    }

    return min_index;
}

// Function to print the current state of the algorithm
void printCurrentState(int dist[], bool sptSet[], int parent[], int current) {
    printf("\nCurrent vertex being processed: %c\n", 'A' + current);

    printf("Vertex\tDistance from Source\tIncluded in SPT\tPath\n");
    for (int i = 0; i < V; i++) {
        printf("%c\t", 'A' + i);
        if (dist[i] == INT_MAX)
            printf("INF\t\t\t");
        else
            printf("%d\t\t\t", dist[i]);

        printf("%s\t\t", sptSet[i] ? "Yes" : "No");

        // Print path
        if (dist[i] == INT_MAX) {
            printf("No path\n");
        } else {
            // Reconstruct path
            int j = i;
            char path[20];
            int path_index = 0;

            while (j != -1) {
                path[path_index++] = 'A' + j;
                j = parent[j];
            }

            // Print path in reverse
            for (int k = path_index - 1; k >= 0; k--) {
                printf("%c", path[k]);
                if (k != 0) printf("->");
            }
            printf("\n");
        }
    }
    printf("\n");
}

// Function to implement Dijkstra's algorithm with visualization
void dijkstra(int graph[V][V], int src) {
    int dist[V];     // The output array. dist[i] will hold the shortest distance from src to i
    bool sptSet[V];  // sptSet[i] will be true if vertex i is included in shortest path tree
    int parent[V];   // To store the shortest path tree

    // Initialize all distances as INFINITE and sptSet[] as false
    for (int i = 0; i < V; i++) {
        dist[i] = INT_MAX;
        sptSet[i] = false;
        parent[i] = -1;
    }

    // Distance of source vertex from itself is always 0
    dist[src] = 0;

    printf("Starting Dijkstra's algorithm from vertex %c\n", 'A' + src);

    // Find shortest path for all vertices
    for (int count = 0; count < V - 1; count++) {
        // Pick the minimum distance vertex from the set of vertices not yet processed
        int u = minDistance(dist, sptSet);

        // Mark the picked vertex as processed
        sptSet[u] = true;

        // Print current state
        printCurrentState(dist, sptSet, parent, u);

        // Update dist value of the adjacent vertices of the picked vertex
        for (int v = 0; v < V; v++) {
            // Update dist[v] only if:
            // 1. It's not in sptSet
            // 2. There's an edge from u to v
            // 3. Total weight of path from src to v through u is smaller than current value of dist[v]
            if (!sptSet[v] && graph[u][v] && dist[u] != INT_MAX 
                && dist[u] + graph[u][v] < dist[v]) {
                dist[v] = dist[u] + graph[u][v];
                parent[v] = u;

                printf("Updating distance to vertex %c: new distance = %d (via %c)\n", 
                      'A' + v, dist[v], 'A' + u);
            }
        }
    }

    // Print the final result
    printf("\nFinal Shortest Paths from vertex %c:\n", 'A' + src);
    printf("Vertex\tDistance\tPath\n");
    for (int i = 0; i < V; i++) {
        printf("%c\t", 'A' + i);
        if (dist[i] == INT_MAX)
            printf("INF\t\t");
        else
            printf("%d\t\t", dist[i]);

        // Reconstruct path
        int j = i;
        char path[20];
        int path_index = 0;

        while (j != -1) {
            path[path_index++] = 'A' + j;
            j = parent[j];
        }

        // Print path in reverse
        for (int k = path_index - 1; k >= 0; k--) {
            printf("%c", path[k]);
            if (k != 0) printf("->");
        }
        printf("\n");
    }
}

