// Dijkstra's algorithm implementation
void dijkstra(int graph[V][V], int source) {
    int dist[V];    // The output array. dist[i] will hold the shortest distance from source to i
    int visited[V]; // visited[i] will be true if vertex i is included in shortest path tree or shortest distance from source to i is finalized
    int parent[V];  // parent[i] stores the parent of i in the shortest path tree

    // Initialize all distances as INFINITE, visited as false, and parent as -1
    for (int i = 0; i < V; i++) {
        dist[i] = INT_MAX;
        visited[i] = 0;
        parent[i] = -1; // -1 indicates no parent (for source node initially)
    }

    // Distance of source vertex from itself is always 0
    dist[source] = 0;

    // Iterate V-1 times to find shortest path for all vertices
    for (int count = 0; count < V - 1; count++) {
        printGraph(graph, dist, visited, parent, -1, source); // Initial state or after a node is picked
        printf("STEP %d: Finding unvisited node with minimum distance...\n", count + 1);
        SLEEP(2000); // Pause for 2 seconds

        // Pick the minimum distance vertex from the set of vertices not yet processed.
        // u is always equal to source in the first iteration.
        int u = minDistance(dist, visited);

        printGraph(graph, dist, visited, parent, u, source);
        printf("STEP %d: Picked Node %d (distance %d). Marking as visited.\n", count + 1, u, dist[u]);
        SLEEP(2000);

        // Mark the picked vertex as visited
        visited[u] = 1;

        // Update dist value of the adjacent vertices of the picked vertex.
        printf("STEP %d: Updating distances for neighbors of Node %d:\n", count + 1, u);
        SLEEP(1000);

        for (int v = 0; v < V; v++) {
            // Update dist[v] only if it is not visited, and there is an edge from u to v,
            // and total weight of path from source to v through u is smaller than current dist[v]
            if (!visited[v] && graph[u][v] && dist[u] != INT_MAX &&
                dist[u] + graph[u][v] < dist[v]) {

                int old_dist_v = dist[v]; // Store old distance for comparison
                dist[v] = dist[u] + graph[u][v];
                parent[v] = u;

                printGraph(graph, dist, visited, parent, u, source); // Update visualization after change
                printf("STEP %d:   Path from %d to %d through %d (cost %d) is shorter than current %d. New distance for %d: %d\n",
                       count + 1, source, v, u, graph[u][v], (old_dist_v == INT_MAX ? 99999 : old_dist_v), v, dist[v]);
                SLEEP(2000); // Pause to show update
            } else if (graph[u][v] && !visited[v]) {
                printGraph(graph, dist, visited, parent, u, source);
                printf("STEP %d:   Node %d is a neighbor of %d. Current path through %d is NOT shorter (or distance already optimal) for %d.\n",
                       count + 1, v, u, u, v);
                SLEEP(1000);
            }
        }
        printf("\n");
        SLEEP(1000); // Pause after processing all neighbors
    }

    // Final result
    CLEAR_SCREEN;
    printf("Dijkstra's Algorithm Completed!\n");
    printf("----------------------------------\n\n");
    printGraph(graph, dist, visited, parent, -1, source);
    printf("Final Shortest Paths from Node %d:\n", source);
    for (int i = 0; i < V; i++) {
        if (i != source) {
            printf("  To Node %d: Distance = %d, Path: ", i, dist[i]);
            printPath(parent, i);
            printf("\n");
        }
    }
    printf("\nPress Enter to exit.");
    getchar(); // Consume the leftover newline
    getchar(); // Wait for user input
}

