        if (dist[i]==INT_MAX)
            printf("%sINF %s", YELLOW, RESET);
        else
            printf("%3d ", dist[i]);
    printf("\n");
}

// Find the unvisited node with the minimum distance
int min_distance(int dist[], bool visited[]) {
    int min = INT_MAX, min_index = -1;
    for (int v = 0; v < V; v++)
        if (!visited[v] && dist[v] <= min)
            min = dist[v], min_index = v;
    return min_index;
}

void dijkstra(int graph[V][V], int src) {
    int dist[V]; // Shortest-distance array
    bool visited[V]; // Visited status array

    for (int i = 0; i < V; i++)
        dist[i] = INT_MAX, visited[i] = false;

    dist[src] = 0;

    printf(GREEN "=== Dijkstra's Algorithm Step-by-Step Visualization ===\n" RESET);

    for (int count = 0; count < V; count++) {
        printf(GREEN "\nStep %d:\n" RESET, count+1);

        int u = min_distance(dist, visited);
        if (u == -1) {
            printf(RED "--No more reachable nodes--\n" RESET);
            break;
        }

        printf("Selected Node: %s%d%s (Minimum tentative distance: %d)\n", YELLOW, u, RESET, dist[u]);
        visited[u] = true;

        for (int v = 0; v < V; v++) {
            // If next node is connected and not visited, and the new distance is shorter
            if (!visited[v] && graph[u][v] && dist[u] != INT_MAX &&
                dist[u] + graph[u][v] < dist[v]) {
                printf("Updating distance for node %d (old: ", v);
                if (dist[v]==INT_MAX) printf("INF");
                else printf("%d", dist[v]);
                printf(", new: %d)\n", dist[u] + graph[u][v]);
                dist[v] = dist[u] + graph[u][v];
            }
        }
        print_step(dist, visited);
        printf("---------------------------------------------------------\n");
    }

