// Structure to represent a graph
typedef struct {
    int numVertices;
    int** adjMatrix;
} Graph;

// Function to create a graph with the given number of vertices
Graph* createGraph(int numVertices) {
    Graph* graph = (Graph*) malloc(sizeof(Graph));
    graph->numVertices = numVertices;
    graph->adjMatrix = (int**) malloc(numVertices * sizeof(int*));

    for (int i = 0; i < numVertices; i++) {
        graph->adjMatrix[i] = (int*) malloc(numVertices * sizeof(int));
        for (int j = 0; j < numVertices; j++) {
            graph->adjMatrix[i][j] = (i == j) ? 0 : INT_MAX;
        }
    }

    return graph;
}

// Function to add an edge to the graph
void addEdge(Graph* graph, int src, int dest, int weight) {
    graph->adjMatrix[src][dest] = weight;
    graph->adjMatrix[dest][src] = weight;
}

// Function to print the graph
void printGraph(Graph* graph) {
    printf("  ");
    for (int i = 0; i < graph->numVertices; i++) {
        printf("%2d ", i);
    }
    printf("\n");

    for (int i = 0; i < graph->numVertices; i++) {
        printf("%2d ", i);
        for (int j = 0; j < graph->numVertices; j++) {
            if (graph->adjMatrix[i][j] == INT_MAX) {
                printf(" X ");
            } else {
                printf("%2d ", graph->adjMatrix[i][j]);
            }
        }
        printf("\n");
    }
}

// Function to implement Dijkstra's algorithm
void dijkstra(Graph* graph, int src) {
    int* distances = (int*) malloc(graph->numVertices * sizeof(int));
    int* visited = (int*) malloc(graph->numVertices * sizeof(int));
    int* parent = (int*) malloc(graph->numVertices * sizeof(int));

    // Initialize distances and visited arrays
    for (int i = 0; i < graph->numVertices; i++) {
        distances[i] = INT_MAX;
        visited[i] = 0;
    }
    distances[src] = 0;

    printf("Initial distances:\n");
    for (int i = 0; i < graph->numVertices; i++) {
        printf("Vertex %d: %d\n", i, distances[i]);
    }

    // Main loop of Dijkstra's algorithm
    for (int i = 0; i < graph->numVertices - 1; i++) {
        int minDistance = INT_MAX;
        int minIndex = -1;

        // Find the vertex with the minimum distance that has not been visited
        for (int j = 0; j < graph->numVertices; j++) {
            if (!visited[j] && distances[j] < minDistance) {
                minDistance = distances[j];
                minIndex = j;
            }
        }

        // Mark the vertex as visited
        visited[minIndex] = 1;

        // Update the distances of the adjacent vertices
        for (int j = 0; j < graph->numVertices; j++) {
            if (!visited[j] && graph->adjMatrix[minIndex][j] != INT_MAX) {
                int newDistance = distances[minIndex] + graph->adjMatrix[minIndex][j];
                if (newDistance < distances[j]) {
                    distances[j] = newDistance;
                    parent[j] = minIndex;
                }
            }
        }

        printf("\nAfter %d iterations:\n", i + 1);
        printf("Vertex %d marked as visited.\n", minIndex);
        printf("Updated distances:\n");
        for (int j = 0; j < graph->numVertices; j++) {
            printf("Vertex %d: %d\n", j, distances[j]);
        }
    }

    // Print the shortest path from the source to each vertex
    printf("\nShortest paths:\n");
    for (int i = 0; i < graph->numVertices; i++) {
        if (i != src) {
            printf("Path from %d to %d: ", src, i);
            int j = i;
            while (j != src) {
                printf("%d ", j);
                j = parent[j];
            }
            printf("%d, Distance: %d\n", src, distances[i]);
        }
    }
}

