// A utility function to print the constructed distance array
void printSolution(int dist[], int parent[], int src) {
    printf("Vertex\tDistance from Source\tPath\n");
    for (int i = 0; i < V; i++) {
        printf("%d \t %d \t\t", i, dist[i]);
        int p = i;
        while (p != src) {
            printf("<- %d ", parent[p]);
            p = parent[p];
        }
        printf("\n");
    }
}

// Function to print the current state of the algorithm
void printStep(int step, int dist[], int sptSet[]) {
    printf("Step %d:\n", step);
    printf("Vertex\tDistance from Source\tIn SPT Set\n");
    for (int i = 0; i < V; i++) {
        printf("%d \t %d \t\t\t %d\n", i, dist[i], sptSet[i]);
    }
