typedef struct {
    float lower_bound;
    float upper_bound;
    float tax_rate;
} TaxBracket;

// Tax calculation function
float calculateIncomeTax(float total_income, TaxBracket* tax_brackets, int num_brackets) {
    float total_tax = 0.0;

    for (int i = 0; i < num_brackets; i++) {
        if (total_income > tax_brackets[i].lower_bound) {
            float taxable_amount = (total_income > tax_brackets[i].upper_bound) 
                ? (tax_brackets[i].upper_bound - tax_brackets[i].lower_bound)
                : (total_income - tax_brackets[i].lower_bound);

            total_tax += taxable_amount * tax_brackets[i].tax_rate;
        }
    }

    return total_tax;
}

