        // Clear input buffer
        while (getchar() != '\n');

        if (success == 0 || value < 0) {
            printf("Invalid input. Please enter a non-negative number.\n");
        }
    } while (success == 0 || value < 0);
    return value;
}

// Gets a 'Y' or 'N' input from the user
char getYesNoInput(const char *prompt) {
    char input;
    do {
        printf("%s (Y/N): ", prompt);
        scanf(" %c", &input); // Note the space before %c to consume leftover newline
        while (getchar() != '\n'); // Clear input buffer
        input = toupper(input);
        if (input != 'Y' && input != 'N') {
            printf("Invalid input. Please enter Y or N.\n");
        }
    } while (input != 'Y' && input != 'N');
    return input;
}

