// Calculates tax based on progressive ordinary income brackets (FAKE)
double calculateOrdinaryIncomeTax(double taxableOrdinaryIncome) {
    double tax = 0.0;
    double remainingIncome = taxableOrdinaryIncome;

    for (int i = 0; i < NUM_BRACKETS; i++) {
        double bracketUpperLimit;
        if (i < NUM_BRACKETS - 1) {
            bracketUpperLimit = ORDINARY_BRACKET_LIMITS[i];
        } else {
            bracketUpperLimit = -1; // Represents no upper limit for the last bracket
        }

        double incomeInThisBracket;
        if (bracketUpperLimit == -1) { // Last bracket
            incomeInThisBracket = remainingIncome;
        } else {
            incomeInThisBracket = (remainingIncome > (bracketUpperLimit - (i == 0 ? 0 : ORDINARY_BRACKET_LIMITS[i-1])))
                                ? (bracketUpperLimit - (i == 0 ? 0 : ORDINARY_BRACKET_LIMITS[i-1]))
                                : remainingIncome;
        }

        if (remainingIncome <= 0) {
            break; // No more taxable income
        }

        tax += incomeInThisBracket * ORDINARY_RATES[i];
        remainingIncome -= incomeInThisBracket;

        // Correctly handle the base for the next bracket
        if (i < NUM_BRACKETS - 1 && remainingIncome > 0) {
            if (taxableOrdinaryIncome > bracketUpperLimit) {
                // If the total income exceeds this bracket's limit, the amount for the next bracket
                // is calculated from its lower bound. We've just taxed the portion up to this bracket's limit.
                // The remaining income will be taxed at the next rate.
            }
        }
    }
    return tax;
}

