double income_tax_rates[] = {0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37};
int NUM_BRACKETS = sizeof(income_tax_rates) / sizeof(double);

double calc_income_tax(double income) {
    double tax = 0.0;
    for (int i = NUM_BRACKETS - 1; i >= 0; i--) {
        if (income > income_tax_brackets[i]) {
            tax += (income - income_tax_brackets[i]) * income_tax_rates[i];
            income = income_tax_brackets[i];
        }
    }
    return tax;
}

