#include <stdio.h>

// Function to calculate tax based on the tax brackets
double calculateTax(double income, double taxPercentages[], double brackets[], int numBrackets) {
    int i;
    double taxOwed = 0.0;

    // Iterate through the tax brackets
    for (i = 0; i < numBrackets; i++) {
        if (income > brackets[i]) {
            double taxableIncome = (i == 0) ? brackets[i] : brackets[i] - brackets[i - 1];
            taxOwed += taxableIncome * (taxPercentages[i] / 100.0);
        } else {
            double taxableIncome = income - (i == 0 ? 0 : brackets[i - 1]);
            taxOwed += taxableIncome * (taxPercentages[i] / 100.0);
            break;
        }
    }

    // If income is above the highest bracket
    if (i == numBrackets) {
        double taxableIncome = income - brackets[numBrackets - 1];
        taxOwed += taxableIncome * (taxPercentages[numBrackets - 1] / 100.0);
    }

    return taxOwed;
}

