        // fgets is safer than scanf for strings as it handles spaces and prevents buffer overflow
        fgets(portfolio[num_assets].name, MAX_NAME_LEN, stdin);
        // Remove the trailing newline character that fgets often includes
        portfolio[num_assets].name[strcspn(portfolio[num_assets].name, "\n")] = '\0';

        // Get Shares Owned
        printf("Enter Shares Owned by Investor (e.g., 1500): ");
        if (scanf("%d", &portfolio[num_assets].shares_owned) != 1 || portfolio[num_assets].shares_owned < 0) {
            printf("Invalid input for shares owned. Please enter a non-negative integer.\n");
            clear_input_buffer(); // Clear buffer in case of bad input
            continue; // Skip to next iteration of the loop
        }
        clear_input_buffer(); // Clear the input buffer after scanf

        // Get Total Outstanding Shares
        printf("Enter Total Outstanding Shares (e.g., 200000): ");
        if (scanf("%d", &portfolio[num_assets].total_shares) != 1 || portfolio[num_assets].total_shares < 0) {
            printf("Invalid input for total shares. Please enter a non-negative integer.\n");
            clear_input_buffer();
            continue;
        }
        clear_input_buffer(); // Clear the input buffer after scanf

        num_assets++; // Increment the count of assets

        printf("\nAdd another asset? (y/n): ");
        scanf(" %c", &add_more_choice); // Space before %c to consume any leftover whitespace
        clear_input_buffer(); // Clear the input buffer after scanf

    } while (add_more_choice == 'y' || add_more_choice == 'Y');

    // Call the function to print the generated statement
    if (num_assets > 0) {
        print_disclosure_statement(portfolio, num_assets);
    } else {
        printf("\nNo assets entered. Disclosure statement not generated.\n");
    }

    printf("\nProgram finished. Press Enter to exit.\n");
    getchar(); // Wait for user to press Enter before closing console (if running as executable)

    return 0; // Indicate successful execution
}

