/**
 * @brief Prints the investment disclosure statement for a given list of assets.
 *
 * @param assets An array of Asset structures containing the investment data.
 * @param num_assets The number of assets in the array to process.
 */
void print_disclosure_statement(const Asset assets[], int num_assets) {
    printf("\n\n--- GENERATED INVESTMENT DISCLOSURE STATEMENT ---\n");
    printf("-------------------------------------------------\n");
    // Print table header
    printf("%-30s | %-10s | %-10s | %-9s | %-20s\n",
           "Asset Name", "Owned", "Total", "Share %", "Shareholder Status");
    printf("------------------------------------------------------------------------------------\n");

    for (int i = 0; i < num_assets; i++) {
        double percentage = 0.0;
        char status[30]; // Buffer for status string

        // Calculate percentage, avoid division by zero
        if (assets[i].total_shares > 0) {
            percentage = ((double)assets[i].shares_owned / assets[i].total_shares) * 100.0;
        }

        // Determine shareholder status
        if (percentage > MAJORITY_THRESHOLD) {
            strncpy(status, "Majority Shareholder", sizeof(status) - 1);
        } else {
            strncpy(status, "Minority Shareholder", sizeof(status) - 1);
        }
        status[sizeof(status) - 1] = '\0'; // Ensure null-termination

        // Print asset details in a formatted row
        printf("%-30s | %-10d | %-10d | %-8.2f%% | %-20s\n",
               assets[i].name,
               assets[i].shares_owned,
               assets[i].total_shares,
               percentage,
               status);
    }
    printf("------------------------------------------------------------------------------------\n");
    printf("Note: 'Majority Shareholder' implies ownership > %.1f%%.\n", MAJORITY_THRESHOLD);
}

/**
 * @brief Clears the standard input buffer.
 * This is important after using `scanf` to prevent leftover characters (like newline)
 * from interfering with subsequent `fgets` or `scanf` calls.
 */
void clear_input_buffer() {
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
}

