// Function to list tables in a database
int list_tables(const char *database_path) {
    sqlite3 *db;
    char *error_message = 0;
    int rc;

    // Open the database
    rc = sqlite3_open(database_path, &db);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return rc;
    }

