        fprintf(stderr, "SQL error: %s\n", error_message);
        sqlite3_free(error_message);
    }

    // Close the database
    sqlite3_close(db);
    printf("\n");

    return rc;
}

// Recursive function to explore directories and find SQLite databases
void explore_databases(const char *path) {
    DIR *dir;
    struct dirent *entry;
    struct stat file_stat;

    // Open directory
    dir = opendir(path);
    if (dir == NULL) {
        perror("Unable to open directory");
        return;
    }

    // Iterate through directory entries
    while ((entry = readdir(dir)) != NULL) {
        char full_path[PATH_MAX];
        snprintf(full_path, sizeof(full_path), "%s/%s", path, entry->d_name);

        // Skip current and parent directory
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        // Get file stats
        if (stat(full_path, &file_stat) == -1) {
            perror("Error getting file stats");
            continue;
        }

        // If it's a directory, recursively explore
        if (S_ISDIR(file_stat.st_mode)) {
            explore_databases(full_path);
        }
        // If it's a file and ends with .db or .sqlite, try to list tables
        else if (S_ISREG(file_stat.st_mode)) {
            const char *ext = strrchr(full_path, '.');
            if (ext != NULL && 
                (strcmp(ext, ".db") == 0 || strcmp(ext, ".sqlite") == 0)) {
                list_tables(full_path);
            }
        }
    }

    closedir(dir);
}

int main(int argc, char *argv[]) {
    // Check if path is provided
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <directory_path>\n", argv[0]);
        return 1;
    }

    const char *search_path = argv[1];

    // Explore databases recursively
    explore_databases(search_path);

    return 0;
}

