        fprintf(stderr, "SQL error: %s\n", zErrMsg);
        sqlite3_free(zErrMsg);
    }

    // Close the database
    sqlite3_close(db);
    return 0;
}

#include <stdio.h>
#include <sqlite3.h>
#include <stdlib.h>

// Function to list all tables in a given database
void listTablesInDatabase(sqlite3 *db) {
    sqlite3_stmt *stmt;
    const char *sql = "SELECT name FROM sqlite_master WHERE type='table'";

    if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare statement: %s\n", sqlite3_errmsg(db));
        return;
    }

    while (sqlite3_step(stmt) == SQLITE_ROW) {
        const char *tableName = (const char *)sqlite3_column_text(stmt, 0);
        printf("  Table: %s\n", tableName);
    }

    sqlite3_finalize(stmt);
}

// Function to list all attached databases
void listAttachedDatabases(sqlite3 *db) {
    sqlite3_stmt *stmt;
    const char *sql = "PRAGMA database_list";

    if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare statement: %s\n", sqlite3_errmsg(db));
        return;
    }

    while (sqlite3_step(stmt) == SQLITE_ROW) {
        const char *dbName = (const char *)sqlite3_column_text(stmt, 1);
        const char *fileName = (const char *)sqlite3_column_text(stmt, 2);

        if (strcmp(dbName, "main") == 0) {
            printf("Database: %s (main)\n", fileName);
        } else {
            printf("Database: %s (attached as %s)\n", fileName, dbName);
        }

        // Recursively list tables in the attached database
        sqlite3 *attachedDb;
        if (sqlite3_open(fileName, &attachedDb) != SQLITE_OK) {
            fprintf(stderr, "Failed to open attached database %s: %s\n", fileName, sqlite3_errmsg(db));
        } else {
            listTablesInDatabase(attachedDb);
            sqlite3_close(attachedDb);
        }
    }

    sqlite3_finalize(stmt);
}

// Main function
int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <database_file>\n", argv[0]);
        return 1;
    }

    const char *databaseFile = argv[1];
    sqlite3 *db;

    if (sqlite3_open(databaseFile, &db) != SQLITE_OK) {
        fprintf(stderr, "Failed to open database %s: %s\n", databaseFile, sqlite3_errmsg(db));
        return 1;
    }

    printf("Listing databases and tables in %s:\n", databaseFile);
    listAttachedDatabases(db);

    sqlite3_close(db);
    return 0;
}

#include <stdio.h>
