// Base64 decoding function
size_t base64_decode(const char *input, unsigned char *output) {
    const char base64_chars[] = 
        "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    size_t input_len = strlen(input);
    size_t output_len = 0;
    int i, j, k;
    unsigned int temp;
    unsigned char decoded[4];

    for (i = 0; i < input_len; i += 4) {
        temp = 0;
        int padding = 0;

        // Decode 4 base64 characters at a time
        for (j = 0; j < 4; j++) {
            if (i + j >= input_len) {
                padding++;
                continue;
            }

            char *ptr = strchr(base64_chars, input[i + j]);
            if (ptr == NULL) {
                // Invalid character
                return 0;
            }
            temp = (temp << 6) | (ptr - base64_chars);
        }

        // Convert to 3 bytes
        decoded[0] = (temp >> 16) & 0xFF;
        decoded[1] = (temp >> 8) & 0xFF;
        decoded[2] = temp & 0xFF;

        // Copy to output, accounting for padding
        for (k = 0; k < 3 - padding; k++) {
            output[output_len++] = decoded[k];
        }
    }

    return output_len;
}

// HEX decoding function
size_t hex_decode(const char *input, unsigned char *output) {
    size_t input_len = strlen(input);
    size_t output_len = 0;

    for (size_t i = 0; i < input_len; i += 2) {
        char hex_pair[3] = {input[i], input[i+1], '\0'};
        unsigned int decoded;
        sscanf(hex_pair, "%x", &decoded);
        output[output_len++] = (unsigned char)decoded;
    }

    return output_len;
}

// ASCII decoding (essentially a pass-through)
size_t ascii_decode(const char *input, unsigned char *output) {
    size_t input_len = strlen(input);
    for (size_t i = 0; i < input_len; i++) {
        output[i] = (unsigned char)input[i];
    }
    return input_len;
}

// Function to print decoded content
void print_decoded_content(unsigned char *decoded, size_t len) {
    for (size_t i = 0; i < len; i++) {
        printf("%c", decoded[i]);
    }
}

int main(int argc, char *argv[]) {
    // Check command-line arguments
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <filename> <encoding> <content>\n", argv[0]);
        fprintf(stderr, "Encodings: ascii, hex, base64\n");
        return 1;
    }

    // Parse arguments
    const char *filename = argv[1];
    const char *encoding = argv[2];
    const char *content = argv[3];

    // Open file
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Error opening file");
        return 1;
    }

    // Determine file size
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    // Allocate buffer for file contents and decoded content
    unsigned char *file_buffer = malloc(file_size);
    unsigned char *decoded_buffer = malloc(file_size * 2);  // Allocate extra space for decoding

    if (file_buffer == NULL || decoded_buffer == NULL) {
        perror("Memory allocation error");
        fclose(file);
        return 1;
    }

    // Read file contents
    size_t read_bytes = fread(file_buffer, 1, file_size, file);
    fclose(file);

    // Null-terminate the buffer
    file_buffer[read_bytes] = '\0';

    // Decode based on encoding
    size_t decoded_len = 0;
    if (strcmp(encoding, "base64") == 0) {
        decoded_len = base64_decode(content, decoded_buffer);
    } else if (strcmp(encoding, "hex") == 0) {
        decoded_len = hex_decode(content, decoded_buffer);
    } else if (strcmp(encoding, "ascii") == 0) {
        decoded_len = ascii_decode(content, decoded_buffer);
    } else {
        fprintf(stderr, "Unsupported encoding: %s\n", encoding);
        free(file_buffer);
        free(decoded_buffer);
        return 1;
    }

    if (decoded_len == 0) {
        fprintf(stderr, "Decoding failed\n");
        free(file_buffer);
        free(decoded_buffer);
        return 1;
    }

    // Print decoded content
    print_decoded_content(decoded_buffer, decoded_len);

    // Free allocated memory
    free(file_buffer);
    free(decoded_buffer);

    return 0;
}

