// Function to decode Base64
int base64_decode(const char *input, unsigned char **output, size_t *output_len) {
    BIO *bio, *b64;
    int len;

    b64 = BIO_new(BIO_f_base64());
    bio = BIO_new_mem_buf((void *)input, -1);
    bio = BIO_push(b64, bio);

    *output = (unsigned char *)malloc(strlen(input));
    len = BIO_read(bio, *output, strlen(input));
    *output_len = len;

    BIO_free_all(bio);
    return 0;
}

// Function to decode HEX
int hex_decode(const char *input, unsigned char **output, size_t *output_len) {
    size_t len = strlen(input);
    if (len % 2 != 0) {
        fprintf(stderr, "Invalid HEX input length\n");
        return -1;
    }

    *output = (unsigned char *)malloc(len / 2);
    *output_len = len / 2;

    for (size_t i = 0; i < len; i += 2) {
        sscanf(input + i, "%2hhx", &(*output)[i / 2]);
    }

    return 0;
}

// Function to read file contents
char *read_file(const char *file_path, size_t *file_size) {
    FILE *file = fopen(file_path, "rb");
