// --- Base64 Encoding/Decoding Functions (Simplified for this example) ---
// Note: A full Base64 implementation is more complex, handling padding, etc.
// This is a basic version sufficient for demonstrating the concept.

const char *base64_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

// Decodes a single 4-character Base64 block into up to 3 bytes
// Returns the number of bytes decoded (1, 2, or 3)
int base64_decode_block(const char *in, unsigned char *out) {
    if (in == NULL || out == NULL) return 0;

    int val[4];
    for (int i = 0; i < 4; i++) {
        const char *p = strchr(base64_chars, in[i]);
        if (p == NULL) { // Handle padding or invalid chars
            val[i] = 0; // Or -1 to indicate error/padding
        } else {
            val[i] = p - base64_chars;
        }
    }

    // Combine 24 bits into 3 bytes
    out[0] = (val[0] << 2) | ((val[1] & 0x30) >> 4);
    out[1] = ((val[1] & 0xF) << 4) | ((val[2] & 0x3C) >> 2);
    out[2] = ((val[2] & 0x3) << 6) | val[3];

    // Determine actual bytes decoded (handle padding)
    int decoded_bytes = 3;
    if (in[3] == '=') decoded_bytes--;
    if (in[2] == '=') decoded_bytes--;

    return decoded_bytes;
}

// --- Main Decoding Logic ---

void decode_and_print(FILE *fp, const char *encoding) {
    if (fp == NULL) {
        fprintf(stderr, "Error: File pointer is NULL.\n");
        return;
    }

    if (strcmp(encoding, "ASCII") == 0) {
        int c;
        while ((c = fgetc(fp)) != EOF) {
            if (c >= 32 && c <= 126) { // Printable ASCII range
                printf("%c", (char)c);
            } else {
                // For non-printable ASCII, maybe print a dot or hex representation
                // For simplicity, we'll just print if it's printable.
                // If you want to see all bytes, treat a raw byte as ASCII.
                printf("[%02X]", c); // Show non-printable as hex
            }
        }
        printf("\n");
    } else if (strcmp(encoding, "HEX") == 0) {
        unsigned char byte;
        while (fread(&byte, 1, 1, fp) == 1) {
            printf("%02X ", byte); // Print each byte as two hexadecimal characters
        }
        printf("\n");
    } else if (strcmp(encoding, "Base64") == 0) {
        char base64_block[5]; // 4 chars + null terminator
        unsigned char decoded_bytes[3];
        size_t bytes_read;

        while ((bytes_read = fread(base64_block, 1, 4, fp)) > 0) {
            base64_block[bytes_read] = '\0'; // Null-terminate the block

            // If we didn't read 4 bytes, it's the end of the file, handle padding
            // In a real decoder, you'd process remaining bytes carefully.
            // For this simplified version, we just print what we can decode.
            if (bytes_read < 4) {
                // Pad with '=' characters if it's the last block
                for (size_t i = bytes_read; i < 4; i++) {
                    base64_block[i] = '=';
                }
                base64_block[4] = '\0'; // Re-null-terminate
            }

            int num_decoded = base64_decode_block(base64_block, decoded_bytes);
            for (int i = 0; i < num_decoded; i++) {
                printf("%c", (char)decoded_bytes[i]); // Print decoded byte as character
            }
        }
         printf("\n");
    } else {
        fprintf(stderr, "Error: Unknown encoding '%s'. Supported encodings: ASCII, HEX, Base64\n", encoding);
    }
}

