int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <binary_file_path> <encoding>\n", argv[0]);
        fprintf(stderr, "Supported encodings: ASCII, HEX, Base64\n");
        return EXIT_FAILURE;
    }

    const char *file_path = argv[1];
