    FILE *fp = fopen(file_path, "rb"); // Open in binary read mode
    if (fp == NULL) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    decode_and_print(fp, encoding);

    fclose(fp); // Close the file

    return EXIT_SUCCESS;
}

