    putchar('\n');
}

void print_binary_from_hex(const unsigned char *data, size_t length) {
    // Each byte is two characters
    if (length % 2 != 0) {
        fprintf(stderr, "Hex input length should be even.\n");
        return;
    }
    for (size_t i = 0; i < length; i +=2) {
        unsigned int val;
        if (sscanf((const char *)data + i, "%2x", &val) != 1) {
            fprintf(stderr, "Invalid hex digit detected.\n");
            return;
        }
        putchar((unsigned char)val);
    }
    putchar('\n');
}

void print_binary_from_base64(const unsigned char *data, size_t length) {
    unsigned int val = 0, valb = -8;
    unsigned char *outbuf = malloc(length);
    if (!outbuf) {
        fprintf(stderr, "Memory allocation error.\n");
        return;
    }
    int outpos = 0;
    for (size_t i = 0; i < length; ++i) {
        unsigned char c = data[i];
        if (isspace(c)) continue;
        if (c == '=') break;
        unsigned char d = base64_table[c];
        if (d == 0x80) {
            fprintf(stderr, "Invalid base64 character.\n");
            free(outbuf);
            return;
        }
        val = (val << 6) | d;
        valb += 6;
        if (valb >= 0) {
            outbuf[outpos++] = (unsigned char)((val >> valb) & 0xFF);
            valb -= 8;
        }
    }
    fwrite(outbuf, 1, outpos, stdout);
    putchar('\n');
    free(outbuf);
}

