    while ((c = fgetc(file)) != EOF) {
        if (c == '\n' || c == '\r') continue;
        hex[0] = c;
        c = fgetc(file);
        if (c == '\n' || c == '\r') break;
        hex[1] = c;
        hex[2] = '\0';
        printf("%c", (char)strtol(hex, NULL, 16));
    }
}

// Base64 encoding/decoding implementation (simplified for brevity)
// Note: This implementation only decodes and does not handle errors or edge cases.
void base64_decode(char *in, char *out) {
    static const char *base64_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    int val = 0, valb = 0;
    char *p = in;
    while (*p) {
        char c = *p++;
        int idx = strchr(base64_chars, c) - base64_chars;
        val = (val << 6) + idx;
        valb += 6;
        if (valb >= 8) {
            *out++ = (val >> (valb - 8)) & 0xFF;
            valb -= 8;
        }
    }
    *out = '\0';
}

void decode_base64(FILE *file) {
    char buffer[1024];
    char decoded[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        base64_decode(buffer, decoded);
        printf("%s", decoded);
    }
}

