int decode_base64(const char *buffer, size_t length, unsigned char *output) {
    int o_idx = 0;
    while (length > 4) {
        int block[4];
        for (int i = 0; i < 4; i++) {
            if (buffer[o_idx + i] == '=') {
                block[i] = 0;
            } else {
                block[i] = base64_decode_table[(unsigned char)buffer[o_idx + i]];
                if (block[i] == -1) return -1;
            }
        }

        output[o_idx / 4 * 3 + 0] = (block[0] << 2) | (block[1] >> 4);
        output[o_idx / 4 * 3 + 1] = (block[1] << 4) | (block[2] >> 2);
        output[o_idx / 4 * 3 + 2] = (block[2] << 6) | block[3];

        o_idx += 4;
        length -= 4;
    }

    if (length) {
        int block[4];
        for (int i = 0; i < length; i++) {
            if (buffer[o_idx + i] == '=') {
                block[i] = 0;
            } else {
                block[i] = base64_decode_table[(unsigned char)buffer[o_idx + i]];
                if (block[i] == -1) return -1;
            }
        }

        if (length == 2) {
            output[o_idx / 4 * 3 + 0] = (block[0] << 2) | (block[1] >> 4);
        } else if (length == 3) {
            output[o_idx / 4 * 3 + 0] = (block[0] << 2) | (block[1] >> 4);
            output[o_idx / 4 * 3 + 1] = (block[1] << 4) | (block[2] >> 2);
        } else if (length == 4) {
            output[o_idx / 4 * 3 + 0] = (block[0] << 2) | (block[1] >> 4);
            output[o_idx / 4 * 3 + 1] = (block[1] << 4) | (block[2] >> 2);
            output[o_idx / 4 * 3 + 2] = (block[2] << 6) | block[3];
        }
    }

    return 0;
}

void decode_base64_to_console(const char *buffer, size_t length) {
    // Calculate the maximum possible output length
    size_t max_output_length = (length / 4) * 3;
    if (length % 4 > 0) {
        max_output_length += (length % 4) - 1;
    }

    unsigned char *output = malloc(max_output_length);
    if (!output) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    if (decode_base64(buffer, length, output) == 0) {
        for (size_t i = 0; i < max_output_length; i++) {
            printf("%c", output[i]);
        }
        printf("\n");
    } else {
        fprintf(stderr, "Invalid Base64 data\n");
    }

    free(output);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <file> <encoding>\n", argv[0]);
        fprintf(stderr, "Encoding can be 'ascii', 'hex', or 'base64'\n");
        return 1;
    }

    const char *filename = argv[1];
    const char *encoding = argv[2];

    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *buffer = malloc(file_size);
    if (!buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        return 1;
    }

    size_t bytes_read = fread(buffer, 1, file_size, file);
    if (bytes_read != file_size) {
        fprintf(stderr, "Error reading file\n");
        free(buffer);
        fclose(file);
        return 1;
    }

    fclose(file);

    if (strcmp(encoding, "ascii") == 0) {
        decode_ascii(buffer, bytes_read);
    } else if (strcmp(encoding, "hex") == 0) {
        decode_hex(buffer, bytes_read);
    } else if (strcmp(encoding, "base64") == 0) {
        decode_base64_to_console(buffer, bytes_read);
    } else {
        fprintf(stderr, "Unsupported encoding: %s\n", encoding);
        return 1;
    }

    free(buffer);
    return 0;
}

