// Function to check if a file should be deleted
int should_delete_file(const char* filename, const char* extension) {
    // Check if the filename ends with the specified extension
    size_t filename_len = strlen(filename);
    size_t ext_len = strlen(extension);

    if (filename_len < ext_len) {
        return 0;
    }

    return (strcmp(filename + filename_len - ext_len, extension) == 0);
}

// Recursive function to delete files with the specified extension
int delete_files_with_extension(const char* path, const char* extension, const char* self_path) {
    DIR* dir;
    struct dirent* entry;
    char full_path[PATH_MAX];
    struct stat file_stat;
    int deleted_count = 0;

    // Open the directory
    dir = opendir(path);
    if (dir == NULL) {
        fprintf(stderr, "Error opening directory %s: %s\n", path, strerror(errno));
        return -1;
    }

    // Iterate through directory entries
    while ((entry = readdir(dir)) != NULL) {
        // Skip current and parent directory entries
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        // Construct full path
        snprintf(full_path, sizeof(full_path), "%s/%s", path, entry->d_name);

        // Get file status
        if (lstat(full_path, &file_stat) == -1) {
            fprintf(stderr, "Error getting file status for %s: %s\n", full_path, strerror(errno));
            continue;
        }

        // Skip symbolic links
        if (S_ISLNK(file_stat.st_mode)) {
            continue;
        }

        // If it's a directory, recursively process it
        if (S_ISDIR(file_stat.st_mode)) {
            delete_files_with_extension(full_path, extension, self_path);
        }
        // If it's a regular file and matches the extension
        else if (S_ISREG(file_stat.st_mode)) {
            // Check if the file is not the program itself
            if (strcmp(full_path, self_path) != 0 && should_delete_file(entry->d_name, extension)) {
                if (unlink(full_path) == 0) {
                    printf("Deleted: %s\n", full_path);
                    deleted_count++;
                } else {
                    fprintf(stderr, "Error deleting file %s: %s\n", full_path, strerror(errno));
                }
            }
        }
    }

    // Close the directory
    closedir(dir);

    return deleted_count;
}

int main(int argc, char* argv[]) {
    // Check command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <directory_path> <file_extension>\n", argv[0]);
        return 1;
    }

    const char* directory_path = argv[1];
    const char* file_extension = argv[2];

    // Get the full path of the executable
    char self_path[PATH_MAX];
    if (realpath(argv[0], self_path) == NULL) {
        fprintf(stderr, "Error getting full path of executable: %s\n", strerror(errno));
        return 1;
    }

    // Validate input directory
    struct stat dir_stat;
    if (stat(directory_path, &dir_stat) != 0 || !S_ISDIR(dir_stat.st_mode)) {
        fprintf(stderr, "Invalid directory path: %s\n", directory_path);
        return 1;
    }

    // Confirm deletion
    char confirm;
    printf("Are you sure you want to delete all files with extension '%s' in '%s'? (y/N): ", 
           file_extension, directory_path);
    scanf(" %c", &confirm);

    if (confirm != 'y' && confirm != 'Y') {
        printf("Deletion cancelled.\n");
        return 0;
    }

    // Perform deletion
    int deleted = delete_files_with_extension(directory_path, file_extension, self_path);

    if (deleted > 0) {
        printf("Total files deleted: %d\n", deleted);
    } else {
        printf("No files were deleted.\n");
    }

    return 0;
}

