#define MAX_PATH 1024

// Function to check if a file has the given extension
int has_extension(const char *filename, const char *extension) {
    const char *dot = strrchr(filename, '.');
    if (dot && !strcmp(dot, extension)) {
        return 1;
    }
    return 0;
}

// Function to delete files with the given extension recursively
void delete_files(const char *dir_path, const char *extension, const char *self_path) {
    DIR *dir;
    struct dirent *entry;
    struct stat statbuf;
    char path[MAX_PATH];

    if ((dir = opendir(dir_path)) == NULL) {
        perror("opendir");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        snprintf(path, sizeof(path), "%s/%s", dir_path, entry->d_name);

        if (lstat(path, &statbuf) == -1) {
            perror("lstat");
            continue;
        }

        // Skip the program itself
        if (strcmp(path, self_path) == 0) {
            continue;
        }

        if (S_ISDIR(statbuf.st_mode)) {
            // Recursively process directories
            if (strcmp(entry->d_name, ".") != 0 && strcmp(entry->d_name, "..") != 0) {
                delete_files(path, extension, self_path);
            }
        } else if (S_ISREG(statbuf.st_mode)) {
            // Delete files with the given extension
            if (has_extension(entry->d_name, extension)) {
                printf("Deleting: %s\n", path);
                if (unlink(path) == -1) {
                    perror("unlink");
                }
            }
        }
    }

    closedir(dir);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <directory> <extension>\n", argv[0]);
        return 1;
    }

    const char *dir_path = argv[1];
    const char *extension = argv[2];
    const char *self_path = argv[0];

    delete_files(dir_path, extension, self_path);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>   // For directory operations (opendir, readdir, closedir)
#include <sys/stat.h> // For stat, lstat (file status, symlink detection)
#include <unistd.h>   // For unlink (delete file), realpath (get absolute path of executable)
#include <errno.h>    // For error numbers

#define MAX_PATH_LEN 4096 // Maximum path length (e.g., ARG_MAX on Linux)
#define MAX_EXT_LEN 64    // Maximum extension length (e.g., ".txt")

// Global variable to store the absolute path of the executable
char g_executable_path[MAX_PATH_LEN];
size_t g_executable_path_len = 0;

// Function prototypes
void delete_files_recursive(const char *path, const char *extension, int *deleted_count);
int is_regular_file(const char *path);
int is_directory(const char *path);
int is_symlink(const char *path);
int check_extension(const char *filename, const char *extension);
int is_executable_itself(const char *filepath);
void print_usage(const char *program_name);

int main(int argc, char *argv[]) {
    if (argc != 3) {
        print_usage(argv[0]);
        return EXIT_FAILURE;
    }

    const char *folder_path = argv[1];
    const char *extension = argv[2]; // Example: ".txt", ".log", etc.

    // 1. Get the absolute path of the executable
    if (realpath(argv[0], g_executable_path) == NULL) {
        fprintf(stderr, "Error: Could not get absolute path of executable (%s).\n", strerror(errno));
        fprintf(stderr, "       Self-deletion prevention might be impaired.\n");
        // Proceed but warn. This is a critical security measure.
        g_executable_path_len = 0; // Mark as unknown path
    } else {
        g_executable_path_len = strlen(g_executable_path);
        fprintf(stderr, "Info: Executable path identified as: %s\n", g_executable_path);
    }

    // 2. Validate initial folder path
    struct stat st;
    if (lstat(folder_path, &st) == -1) {
        fprintf(stderr, "Error: Folder path '%s' does not exist or is not accessible: %s\n", folder_path, strerror(errno));
        return EXIT_FAILURE;
    }
    if (!S_ISDIR(st.st_mode)) {
        fprintf(stderr, "Error: Path '%s' is not a directory.\n", folder_path);
        return EXIT_FAILURE;
    }

    fprintf(stdout, "Scanning '%s' for files with extension '%s' to delete...\n", folder_path, extension);

    int deleted_total_count = 0;
    delete_files_recursive(folder_path, extension, &deleted_total_count);

    fprintf(stdout, "Process completed. Total files deleted: %d\n", deleted_total_count);

    return EXIT_SUCCESS;
}

// Function to print usage instructions
void print_usage(const char *program_name) {
    fprintf(stderr, "Usage: %s <folder_path> <file_extension>\n", program_name);
    fprintf(stderr, "  <folder_path>: The path to the folder to scan recursively.\n");
    fprintf(stderr, "  <file_extension>: The extension of files to delete (e.g., '.txt', '.log').\n");
    fprintf(stderr, "                    Case-sensitive. Must include the leading dot if desired.\n");
    fprintf(stderr, "\n");
    fprintf(stderr, "WARNING: This program permanently deletes files. Use with extreme caution!\n");
    fprintf(stderr, "         It prevents self-deletion and does not follow symbolic links.\n");
}

// Recursive function to delete files with a given extension
void delete_files_recursive(const char *base_path, const char *extension, int *deleted_count) {
    DIR *dir;
    struct dirent *entry;
    char full_path[MAX_PATH_LEN];

    if (!(dir = opendir(base_path))) {
        fprintf(stderr, "Error: Could not open directory '%s': %s\n", base_path, strerror(errno));
        return;
    }

    errno = 0; // Clear errno for readdir check
    while ((entry = readdir(dir)) != NULL) {
        // Skip "." (current directory) and ".." (parent directory)
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        // Construct full path
        if (snprintf(full_path, sizeof(full_path), "%s/%s", base_path, entry->d_name) >= sizeof(full_path)) {
            fprintf(stderr, "Error: Path length exceeded for '%s/%s'. Skipping.\n", base_path, entry->d_name);
            continue;
        }

        struct stat st;
        // Use lstat to check file type WITHOUT following symbolic links
        if (lstat(full_path, &st) == -1) {
            fprintf(stderr, "Warning: Could not get status for '%s': %s. Skipping.\n", full_path, strerror(errno));
            continue;
        }

        if (S_ISDIR(st.st_mode)) {
            // It's a directory, recurse into it
            delete_files_recursive(full_path, extension, deleted_count);
        } else if (S_ISREG(st.st_mode)) {
            // It's a regular file
            if (check_extension(entry->d_name, extension)) {
                if (!is_executable_itself(full_path)) {
                    fprintf(stdout, "Deleting: %s\n", full_path);
                    if (unlink(full_path) == 0) {
                        (*deleted_count)++;
                        fprintf(stdout, "  SUCCESS: Deleted '%s'\n", full_path);
                    } else {
                        fprintf(stderr, "  FAILED: Could not delete '%s': %s\n", full_path, strerror(errno));
                    }
                } else {
                    fprintf(stdout, "Skipping: %s (This is the executable itself).\n", full_path);
                }
            }
        }
        // If it's a symbolic link (S_ISLNK), we explicitly do nothing as per requirement.
        // Other types (FIFOs, sockets, character/block devices) are also ignored.
    }

    if (errno != 0) {
        fprintf(stderr, "Error: During readdir for directory '%s': %s.\n", base_path, strerror(errno));
    }

    closedir(dir);
}

// Checks if a file's extension matches the given extension string.
// Case-sensitive. 'extension' should include the dot if required (e.g., ".txt").
int check_extension(const char *filename, const char *extension) {
    const char *dot = strrchr(filename, '.');
    if (dot && dot != filename) { // Ensure dot is found and not at the beginning (e.g., ".bashrc")
        return strcmp(dot, extension) == 0;
    }
    return 0; // No extension found or invalid
}

// Checks if the given filepath is the executable itself using its absolute path.
int is_executable_itself(const char *filepath) {
    if (g_executable_path_len == 0) {
        return 0; // Cannot determine executable path, so assume no match
    }

    char absolute_filepath[MAX_PATH_LEN];
    // Get the absolute path of the file being checked
    if (realpath(filepath, absolute_filepath) == NULL) {
        // If realpath fails (e.g., permission denied), assume it's not the executable
        // to avoid accidental deletion, but warn.
        fprintf(stderr, "Warning: Could not get realpath for '%s' (%s). Assuming not executable.\n", filepath, strerror(errno));
        return 0;
    }

    return strcmp(absolute_filepath, g_executable_path) == 0;
}

