// Check if file_name has extension ext (ext includes the leading dot, e.g., ".txt")
bool has_extension(const char *file_name, const char *ext) {
    size_t name_len = strlen(file_name);
    size_t ext_len = strlen(ext);
    if (name_len <= ext_len)
        return false;
    return strcmp(file_name + name_len - ext_len, ext) == 0;
}

// Recursively delete files with the given extension
void delete_files(const char *dir_path, const char *ext, const char *self_path) {
    DIR *dir = opendir(dir_path);
    if (!dir) {
        fprintf(stderr, "Cannot open directory '%s': %s\n", dir_path, strerror(errno));
        return;
    }

    struct dirent *entry;
    char path[PATH_MAX];

    while ((entry = readdir(dir)) != NULL) {
        // Skip "." and ".."
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        snprintf(path, sizeof(path), "%s/%s", dir_path, entry->d_name);

        struct stat st;
        // Use lstat to avoid following symlinks
        if (lstat(path, &st) == -1) {
            fprintf(stderr, "lstat error on '%s': %s\n", path, strerror(errno));
            continue;
        }

        // If entry is a symlink, skip it (do not recurse or delete)
        if (S_ISLNK(st.st_mode))
            continue;

        if (S_ISDIR(st.st_mode)) {
            // Recursive call on subdirectory
            delete_files(path, ext, self_path);
        } else if (S_ISREG(st.st_mode)) {
            // Compare absolute path to self_path to avoid deleting self
            char abs_path[PATH_MAX];
            if (realpath(path, abs_path) == NULL) {
                fprintf(stderr, "realpath error on '%s': %s\n", path, strerror(errno));
                continue;
            }

            if (strcmp(abs_path, self_path) == 0)
                continue; // Never delete self

            if (has_extension(entry->d_name, ext)) {
                if (unlink(abs_path) == 0) {
                    printf("Deleted: %s\n", abs_path);
                } else {
                    fprintf(stderr, "Cannot delete '%s': %s\n", abs_path, strerror(errno));
                }
            }
        }
    }
    closedir(dir);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <directory> <extension>\n", argv[0]);
        fprintf(stderr, "Example: %s /tmp '.txt'\n", argv[0]);
        return EXIT_FAILURE;
    }

    char self_path[PATH_MAX];
    // For Linux: /proc/self/exe gives an absolute path to the running executable
    ssize_t len = readlink("/proc/self/exe", self_path, sizeof(self_path)-1);
    if (len == -1) {
        perror("Could not determine executable path");
        return EXIT_FAILURE;
    }
    self_path[len] = '\0';
    // Optionally, resolve symlinks
    char real_self_path[PATH_MAX];
    if (realpath(self_path, real_self_path) == NULL) {
        perror("realpath for self");
        return EXIT_FAILURE;
    }

    delete_files(argv[1], argv[2], real_self_path);
    return EXIT_SUCCESS;
}

