void delete_files_with_extension(const char *directory, const char *extension, const char *self_path);
int has_extension(const char *filename, const char *extension);
char *get_absolute_self_path();

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <directory> <extension>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *self_path = get_absolute_self_path();
    if (self_path == NULL) {
        perror("Failed to get the absolute path of the executable");
        return EXIT_FAILURE;
    }

    delete_files_with_extension(argv[1], argv[2], self_path);

    free(self_path);
    return EXIT_SUCCESS;
}

void delete_files_with_extension(const char *directory, const char *extension, const char *self_path) {
    struct dirent *entry;
    struct stat entry_stat;

    DIR *dp = opendir(directory);
    if (dp == NULL) {
        perror("opendir");
        return;
    }

    while ((entry = readdir(dp)) != NULL) {
        char path[PATH_MAX];
        snprintf(path, sizeof(path), "%s/%s", directory, entry->d_name);

        // Skip "." and ".."
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        // Get file stats
        if (lstat(path, &entry_stat) == -1) {
            perror("lstat");
            continue;
        }

        // Ensure not to follow symbolic links
        if (S_ISLNK(entry_stat.st_mode)) {
            continue;
        }

        if (S_ISDIR(entry_stat.st_mode)) {
            // Recurse into subdirectory
            delete_files_with_extension(path, extension, self_path);
        } else if (S_ISREG(entry_stat.st_mode)) {
            // Check for file extension match
            if (has_extension(entry->d_name, extension) && strcmp(self_path, path) != 0) {
                printf("Deleting file: %s\n", path);
                if (remove(path) != 0) {
                    perror("remove");
                }
            }
        }
    }

    closedir(dp);
}

int has_extension(const char *filename, const char *extension) {
    const char *dot = strrchr(filename, '.');
    if (!dot || dot == filename) return 0;
    return strcmp(dot + 1, extension) == 0;
}

char *get_absolute_self_path() {
    char *path = malloc(PATH_MAX);
    if (!path) return NULL;

    ssize_t len = readlink("/proc/self/exe", path, PATH_MAX - 1);
    if (len == -1) {
        free(path);
        return NULL;
    }

    path[len] = '\0';
    return path;
}

