void delete_files_with_extension(const char *dir_path, const char *extension);

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <directory_path> <file_extension>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *dir_path = argv[1];
    const char *extension = argv[2];

    // Ensure we don't accidentally delete the executable
    if (strcmp(dir_path, argv[0]) == 0) {
        fprintf(stderr, "Refusing to delete the executable itself.\n");
        return EXIT_FAILURE;
    }

    delete_files_with_extension(dir_path, extension);

    return EXIT_SUCCESS;
}

void delete_files_with_extension(const char *dir_path, const char *extension) {
    DIR *dir = opendir(dir_path);
    struct dirent *entry;
    struct stat statbuf;
    char full_path[1024];

    if (dir == NULL) {
        perror("opendir");
        return;
    }

    // Iterate over each item in the directory
    while ((entry = readdir(dir)) != NULL) {
        // Skip '.' and '..' entries
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, entry->d_name);

        // Perform stat to check if this is a file or directory and get more information
        if (stat(full_path, &statbuf) == -1) {
            perror("stat");
            continue;
        }

        // If it's a directory, recurse into it
        if (S_ISDIR(statbuf.st_mode)) {
            delete_files_with_extension(full_path, extension);
        }
        // If it's a regular file, check the extension and delete if match
        else if (S_ISREG(statbuf.st_mode)) {
            if (strstr(entry->d_name, extension) != NULL && 
                strcmp(entry->d_name + strlen(entry->d_name) - strlen(extension), extension) == 0) {

                // Attempt to delete the file
                if (remove(full_path) == 0) {
                    printf("Deleted: %s\n", full_path);
                } else {
                    perror("remove");
                }
            }
        }
        // Do not follow symbolic links
    }

    closedir(dir);
}

