// Function to check if a path is a symbolic link
int is_symbolic_link(const char *path) {
    struct stat statbuf;
    if (lstat(path, &statbuf)!= 0) {
        perror("lstat");
        return 1; // Error checking if it's a symbolic link
    }
    return S_ISLNK(statbuf.st_mode);
}

// Function to remove files recursively
void remove_files_recursively(const char *dir_path, const char *file_extension) {
    DIR *dir;
    struct dirent *ent;
    struct stat statbuf;
    char filepath[PATH_MAX];

    // Open the directory
    if ((dir = opendir(dir_path)) == NULL) {
        perror("opendir");
        return;
    }

    while ((ent = readdir(dir))!= NULL) {
        // Skip current directory and parent directory
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) {
            continue;
        }

        // Construct full path of the file/directory
        snprintf(filepath, sizeof(filepath), "%s/%s", dir_path, ent->d_name);

        // Check if it's a directory
        if (stat(filepath, &statbuf) == -1) {
            perror("stat");
            continue;
        }

        if (S_ISDIR(statbuf.st_mode)) {
            // If it's a directory, recursively call the function
            remove_files_recursively(filepath, file_extension);
        } else if (S_ISREG(statbuf.st_mode)) {
            // If it's a regular file, check its extension
            size_t ext_len = strlen(file_extension);
            if (strlen(ent->d_name) >= ext_len && strcmp(ent->d_name + strlen(ent->d_name) - ext_len, file_extension) == 0) {
                // Check it's not a symbolic link and not the executable itself
                if (!is_symbolic_link(filepath)) {
                    printf("Removing file: %s\n", filepath);
                    if (remove(filepath)!= 0) {
                        perror("remove");
                    }
                } else {
                    printf("Skipping symbolic link: %s\n", filepath);
                }
            }
        }
    }

    closedir(dir);
}

int main(int argc, char *argv[]) {
    if (argc!= 3) {
        fprintf(stderr, "Usage: %s <directory_path> <file_extension>\n", argv[0]);
        return EXIT_FAILURE;
    }

    // Remove the dot from the file extension if it's provided
    char *file_extension = argv[2];
    if (file_extension[0] == '.') {
        file_extension++;
    }

    printf("Removing files with extension '%s' in '%s'\n", argv[2], argv[1]);
    remove_files_recursively(argv[1], file_extension);

    return EXIT_SUCCESS;
}

