#include <unistd.h>

// Function to check if a file has the specified extension
int has_extension(const char *filename, const char *extension) {
    int filename_len = strlen(filename);
    int ext_len = strlen(extension);
    if (ext_len > filename_len) return 0;
    return !strcmp(filename + filename_len - ext_len, extension);
}

// Function to recursively delete files with the specified extension
void delete_files_with_extension(const char *path, const char *extension, const char *self_path) {
    DIR *dir;
    struct dirent *entry;
    struct stat file_stat;
    char full_path[1024];

    // Open the directory
    dir = opendir(path);
    if (!dir) {
        perror("opendir");
        return;
    }

    // Iterate over all entries in the directory
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue; // Skip "." and ".."
        }

        snprintf(full_path, sizeof(full_path), "%s/%s", path, entry->d_name);

        // Get file status
        if (lstat(full_path, &file_stat) == -1) {
            perror("lstat");
            continue;
        }

        // Check if the entry is a symbolic link
        if (S_ISLNK(file_stat.st_mode)) {
            continue; // Skip symbolic links
        }

        // Check if the entry is a directory
        if (S_ISDIR(file_stat.st_mode)) {
            delete_files_with_extension(full_path, extension, self_path);
            continue;
        }

        // Check if the file has the specified extension and is not the program itself
        if (has_extension(entry->d_name, extension) && strcmp(full_path, self_path) != 0) {
            if (unlink(full_path) == -1) {
                perror("unlink");
            } else {
                printf("Deleted file: %s\n", full_path);
            }
        }
    }

    // Close the directory
    closedir(dir);
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <folder_path> <file_extension> <self_path>\n", argv[0]);
        return 1;
    }

    const char *folder_path = argv[1];
    const char *file_extension = argv[2];
    const char *self_path = argv[3];

    delete_files_with_extension(folder_path, file_extension, self_path);

    return 0;
}

