#define PACKET_SIZE 64
#define MAX_HOSTS 10
#define PING_COUNT 5

// Function to calculate checksum
unsigned short calculate_checksum(unsigned short *buffer, int length) {
    unsigned long sum = 0;
    unsigned short *ptr = buffer;
    int count = length;

    while (count > 1) {
        sum += *ptr++;
        count -= 2;
    }

    if (count > 0)
        sum += *(unsigned char *)ptr;

    while (sum >> 16)
        sum = (sum & 0xFFFF) + (sum >> 16);

    return ~sum;
}

// Function to resolve hostname to IP address
int resolve_hostname(const char *hostname, char *ip_str) {
    struct hostent *host_entry;
    struct in_addr **addr_list;

    host_entry = gethostbyname(hostname);
    if (host_entry == NULL) {
        herror("gethostbyname");
        return -1;
    }

    addr_list = (struct in_addr **)host_entry->h_addr_list;
    strcpy(ip_str, inet_ntoa(*addr_list[0]));
    return 0;
}

// Function to send ping packet and measure round trip time
double ping_host(const char *ip_address) {
    int sockfd;
    struct sockaddr_in dest_addr;
    struct icmphdr *icmp_header;
    struct timeval start, end;
    char packet[PACKET_SIZE];
    int seq_number = 1;
    double total_rtt = 0.0;

    sockfd = socket(AF_INET, SOCK_RAW, IPPROTO_ICMP);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    dest_addr.sin_family = AF_INET;
    dest_addr.sin_addr.s_addr = inet_addr(ip_address);

    for (int i = 0; i < PING_COUNT; i++) {
        // Prepare ICMP packet
        memset(packet, 0, sizeof(packet));
        icmp_header = (struct icmphdr *)packet;
        icmp_header->type = ICMP_ECHO;
        icmp_header->code = 0;
        icmp_header->un.echo.id = getpid();
        icmp_header->un.echo.sequence = seq_number++;
        icmp_header->checksum = 0;
        icmp_header->checksum = calculate_checksum((unsigned short *)packet, sizeof(packet));

        // Send packet
        gettimeofday(&start, NULL);
        if (sendto(sockfd, packet, sizeof(packet), 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr)) < 0) {
            perror("sendto");
            continue;
        }

        // Receive response
        char recv_packet[PACKET_SIZE];
        socklen_t addr_len = sizeof(dest_addr);
        if (recvfrom(sockfd, recv_packet, sizeof(recv_packet), 0, (struct sockaddr *)&dest_addr, &addr_len) < 0) {
            perror("recvfrom");
            continue;
        }

        gettimeofday(&end, NULL);

        // Calculate round trip time
        double rtt = (end.tv_sec - start.tv_sec) * 1000.0 + 
                     (end.tv_usec - start.tv_usec) / 1000.0;
        total_rtt += rtt;

        usleep(500000);  // Wait 500ms between packets
    }

    close(sockfd);
    return total_rtt / PING_COUNT;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <host1> [host2] [host3] ...\n", argv[0]);
        return 1;
    }

    // Check if running with root/sudo privileges
    if (geteuid() != 0) {
        fprintf(stderr, "This program requires root privileges to send ICMP packets.\n");
        return 1;
    }

    // Limit hosts to prevent buffer overflow
    int host_count = (argc - 1 > MAX_HOSTS) ? MAX_HOSTS : argc - 1;

    printf("Pinging %d host(s):\n", host_count);

    for (int i = 1; i <= host_count; i++) {
        char ip_address[INET_ADDRSTRLEN];

        // Resolve hostname to IP if needed
        if (resolve_hostname(argv[i], ip_address) < 0) {
            continue;
        }

        printf("Host: %s (IP: %s) ", argv[i], ip_address);

        double avg_rtt = ping_host(ip_address);
        if (avg_rtt >= 0) {
            printf("Average RTT: %.2f ms\n", avg_rtt);
        } else {
            printf("Ping failed\n");
        }
    }

    return 0;
}

