#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netinet/ip.h>
#include <netinet/ip_icmp.h>
#include <arpa/inet.h>
#include <errno.h>
#include <signal.h>

// --- Constants ---
#define PING_PACKET_SIZE 64
#define PING_TIMEOUT_MS 1000 // Timeout for a single ping in milliseconds
#define PING_COUNT 4         // Number of pings to send per IP
#define MAX_IP_ADDRESSES 10  // Maximum number of IP addresses to process

// --- Global Variables ---
int g_sockfd = -1; // Socket file descriptor
pid_t g_pid;       // Process ID for ICMP ID
int g_sequence = 0; // ICMP sequence number

// --- Structures ---

// ICMP echo request packet structure
typedef struct icmp_echo_packet {
    struct icmphdr hdr;
    char data[PING_PACKET_SIZE - sizeof(struct icmphdr)];
} icmp_echo_packet_t;

// Structure to store ping results for an IP
typedef struct ping_result {
    char ip_address[INET_ADDRSTRLEN];
    double total_rtt_ms;
    int successful_pings;
} ping_result_t;

// --- Function Prototypes ---
unsigned short checksum(short *addr, int len);
void tv_sub(struct timeval *out, struct timeval *in);
int send_ping(int sockfd, struct sockaddr_in *dest_addr, int sequence, const char *data, int data_len);
double receive_ping(int sockfd, int sequence, int timeout_ms);
void cleanup(int signum);
void print_usage(const char *prog_name);

// --- Main Function ---
int main(int argc, char *argv[]) {
    if (argc < 2) {
        print_usage(argv[0]);
        return 1;
    }

    // Register a signal handler for graceful shutdown
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    g_pid = getpid(); // Get process ID for ICMP ID

    // Create a raw socket for ICMP. Requires CAP_NET_RAW or root privileges.
    g_sockfd = socket(AF_INET, SOCK_RAW, IPPROTO_ICMP);
    if (g_sockfd < 0) {
        perror("Error creating socket. Try running with sudo or setuid root (not recommended).");
        return 1;
    }

    // Set a receive timeout for the socket
    struct timeval tv_recv_timeout;
    tv_recv_timeout.tv_sec = 0;
    tv_recv_timeout.tv_usec = PING_TIMEOUT_MS * 1000;
    if (setsockopt(g_sockfd, SOL_SOCKET, SO_RCVTIMEO, (const char*)&tv_recv_timeout, sizeof(tv_recv_timeout)) < 0) {
        perror("Error setting socket receive timeout");
        cleanup(0);
        return 1;
    }

    ping_result_t results[MAX_IP_ADDRESSES];
    int num_ips = 0;

    // Process command line arguments (IP addresses)
    for (int i = 1; i < argc; ++i) {
        if (num_ips >= MAX_IP_ADDRESSES) {
            fprintf(stderr, "Warning: Maximum %d IP addresses supported. Skipping %s\n", MAX_IP_ADDRESSES, argv[i]);
            break;
        }
        strncpy(results[num_ips].ip_address, argv[i], INET_ADDRSTRLEN - 1);
        results[num_ips].ip_address[INET_ADDRSTRLEN - 1] = '\0';
        results[num_ips].total_rtt_ms = 0.0;
        results[num_ips].successful_pings = 0;
        num_ips++;
    }

    printf("Starting ping utility for %d IP addresses...\n", num_ips);

    // Loop through each IP address and send pings
    for (int i = 0; i < num_ips; ++i) {
        printf("\nPinging %s (%d pings)...\n", results[i].ip_address, PING_COUNT);

        struct sockaddr_in dest_addr;
        memset(&dest_addr, 0, sizeof(dest_addr));
        dest_addr.sin_family = AF_INET;
        if (inet_pton(AF_INET, results[i].ip_address, &(dest_addr.sin_addr)) <= 0) {
            fprintf(stderr, "Invalid IP address: %s. Skipping.\n", results[i].ip_address);
            continue;
        }

        for (int p = 0; p < PING_COUNT; ++p) {
            g_sequence++; // Increment global sequence number for each ping
            char data[PING_PACKET_SIZE - sizeof(struct icmphdr)];
            memset(data, 0xA5, sizeof(data)); // Fill with some arbitrary data

            // Send ping
            if (send_ping(g_sockfd, &dest_addr, g_sequence, data, sizeof(data)) < 0) {
                fprintf(stderr, "Error sending ping to %s. Skipping this ping.\n", results[i].ip_address);
                continue;
            }

            // Receive ping response
            double rtt = receive_ping(g_sockfd, g_sequence, PING_TIMEOUT_MS);

            if (rtt >= 0) {
                printf("  %s: Ping %d: %.2f ms\n", results[i].ip_address, p + 1, rtt);
                results[i].total_rtt_ms += rtt;
                results[i].successful_pings++;
            } else {
                printf("  %s: Ping %d: Request timed out\n", results[i].ip_address, p + 1);
            }
            usleep(100 * 1000); // 100ms delay between pings to avoid flooding
        }
    }

    // Report results
    printf("\n--- Ping Report ---\n");
    for (int i = 0; i < num_ips; ++i) {
        if (results[i].successful_pings > 0) {
            double avg_rtt = results[i].total_rtt_ms / results[i].successful_pings;
            printf("IP: %s, Pings Sent: %d, Pings Received: %d, Average RTT: %.2f ms\n",
                   results[i].ip_address, PING_COUNT, results[i].successful_pings, avg_rtt);
        } else {
            printf("IP: %s, Pings Sent: %d, Pings Received: 0, Average RTT: No response\n",
                   results[i].ip_address, PING_COUNT);
        }
    }

    cleanup(0); // Close socket
    return 0;
}

// --- Function Implementations ---

// Calculate the Internet checksum for ICMP packets
unsigned short checksum(short *addr, int len) {
    int sum = 0;
    unsigned short *w = addr;
    int nleft = len;

    while (nleft > 1) {
        sum += *w++;
        nleft -= 2;
    }

    if (nleft == 1) {
        sum += *(unsigned char *)w;
    }

    sum = (sum >> 16) + (sum & 0xFFFF);
    sum += (sum >> 16);
    return (unsigned short)~sum;
}

// Subtract two timeval structs
void tv_sub(struct timeval *out, struct timeval *in) {
    if ((out->tv_usec -= in->tv_usec) < 0) {
        --out->tv_sec;
        out->tv_usec += 1000000;
    }
    out->tv_sec -= in->tv_sec;
}

// Sends an ICMP echo request packet
int send_ping(int sockfd, struct sockaddr_in *dest_addr, int sequence, const char *data, int data_len) {
    icmp_echo_packet_t packet;
    memset(&packet, 0, sizeof(packet));

    packet.hdr.type = ICMP_ECHO;
    packet.hdr.code = 0;
    packet.hdr.un.echo.id = htons(g_pid);
    packet.hdr.un.echo.sequence = htons(sequence);

    // Copy data
    if (data_len > sizeof(packet.data)) {
        data_len = sizeof(packet.data); // Truncate if data is too big
    }
    memcpy(packet.data, data, data_len);

    // Record send time
    struct timeval *tval = (struct timeval *)packet.data;
    gettimeofday(tval, NULL);

    packet.hdr.checksum = 0; // Calculate checksum on zeroed checksum field
    packet.hdr.checksum = checksum((short *)&packet, sizeof(packet.hdr) + data_len);

    return sendto(sockfd, &packet, sizeof(packet.hdr) + data_len, 0,
                  (struct sockaddr *)dest_addr, sizeof(*dest_addr));
}

// Receives an ICMP echo reply packet and calculates RTT
double receive_ping(int sockfd, int expected_sequence, int timeout_ms) {
    char recv_buf[1500]; // Max possible IP packet size
    struct sockaddr_in from_addr;
    socklen_t addr_len = sizeof(from_addr);
    struct timeval tv_recv_start, tv_recv_end, tv_rtt;

    gettimeofday(&tv_recv_start, NULL); // Mark start of receive attempt

    ssize_t bytes_received = recvfrom(sockfd, recv_buf, sizeof(recv_buf), 0,
                                      (struct sockaddr *)&from_addr, &addr_len);

    gettimeofday(&tv_recv_end, NULL); // Mark end of receive attempt

    if (bytes_received < 0) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            // Timeout occurred
            return -1.0;
        }
        perror("recvfrom error");
        return -1.0;
    }

    // Parse IP header
    struct ip *ip_hdr = (struct ip *)recv_buf;
    int ip_hdr_len = ip_hdr->ip_hl << 2; // IP header length in bytes

    // Check if enough bytes for ICMP header
    if (bytes_received < ip_hdr_len + sizeof(struct icmphdr)) {
        fprintf(stderr, "Received packet too small.\n");
        return -1.0;
    }

    // Parse ICMP header
    struct icmphdr *icmp_hdr = (struct icmphdr *)(recv_buf + ip_hdr_len);

    // Check if it's an ICMP Echo Reply and matches our process ID and sequence
    if (icmp_hdr->type == ICMP_ECHOREPLY &&
        ntohs(icmp_hdr->un.echo.id) == g_pid &&
        ntohs(icmp_hdr->un.echo.sequence) == expected_sequence) {

        // Get the timestamp from the ICMP data field
        struct timeval tv_send_time;
        // Ensure the received data contains enough bytes for the timeval structure
        if (bytes_received - ip_hdr_len - sizeof(struct icmphdr) >= sizeof(struct timeval)) {
            memcpy(&tv_send_time, ((char *)icmp_hdr + sizeof(struct icmphdr)), sizeof(struct timeval));
        } else {
            // No timestamp in the reply or not enough data, can't calculate RTT
            fprintf(stderr, "Warning: No timestamp in ICMP reply or malformed. Cannot calculate RTT precisely.\n");
            return 0.0; // Return 0 or some indication of non-calculable RTT
        }

        // Calculate RTT
        tv_rtt = tv_recv_end;
        tv_sub(&tv_rtt, &tv_send_time);
        return (double)(tv_rtt.tv_sec * 1000.0 + tv_rtt.tv_usec / 1000.0);
    }

    // Not the ICMP echo reply we were looking for (e.g., another process's ping, or ICMP error)
    return -1.0;
}

// Cleanup function for graceful shutdown
void cleanup(int signum) {
    if (g_sockfd != -1) {
        close(g_sockfd);
        g_sockfd = -1;
        if (signum == SIGINT || signum == SIGTERM) {
            printf("\nCaught signal %d. Shutting down.\n", signum);
        }
    }
    exit(0);
}

// Prints usage information
void print_usage(const char *prog_name) {
    fprintf(stderr, "Usage: %s <IP_ADDRESS_1> [IP_ADDRESS_2] ... [IP_ADDRESS_N]\n", prog_name);
    fprintf(stderr, "  Example: %s 8.8.8.8 192.168.1.1\n", prog_name);
    fprintf(stderr, "  Note: This program requires root privileges or CAP_NET_RAW capability.\n");
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/socket.h>
#include <netinet/ip_icmp.h>
#include <arpa/inet.h>
#include <errno.h>

#define PACKET_SIZE 64
#define NUM_PINGS 4

unsigned short checksum(void *b, int len) {
    unsigned short *buf = b;
    unsigned int sum = 0;
    for (; len > 1; len -= 2)
        sum += *buf++;
    if (len == 1)
        sum += *(unsigned char*)buf;
    sum = (sum >> 16) + (sum & 0xFFFF);
    sum += (sum >> 16);
    return ~sum;
}

double timeval_diff(struct timeval *start, struct timeval *end) {
    return (double)(end->tv_sec - start->tv_sec) * 1000.0 +
           (double)(end->tv_usec - start->tv_usec) / 1000.0;
}

int ping(const char *ip_addr) {
    int sockfd;
    struct sockaddr_in addr;
    struct icmphdr icmp_hdr;
    char packet[PACKET_SIZE];
    struct timeval start, end;
    socklen_t addr_len = sizeof(addr);

    int successes = 0;
    double total_time = 0.0;

    sockfd = socket(AF_INET, SOCK_RAW, IPPROTO_ICMP);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    if (inet_pton(AF_INET, ip_addr, &addr.sin_addr) <= 0) {
        fprintf(stderr, "inet_pton failed for %s\n", ip_addr);
        close(sockfd);
        return -1;
    }

    for (int i = 0; i < NUM_PINGS; ++i) {
        // Prepare ICMP header
        memset(&icmp_hdr, 0, sizeof(icmp_hdr));
        icmp_hdr.type = ICMP_ECHO;
        icmp_hdr.un.echo.id = getpid() & 0xFFFF;
        icmp_hdr.un.echo.sequence = i;
        icmp_hdr.checksum = 0;

        memset(packet, 0, sizeof(packet));
        memcpy(packet, &icmp_hdr, sizeof(icmp_hdr));

        // calculate checksum
        icmp_hdr.checksum = checksum(packet, sizeof(icmp_hdr));
        memcpy(packet, &icmp_hdr, sizeof(icmp_hdr));

        // Get start time
        gettimeofday(&start, NULL);

        if (sendto(sockfd, packet, sizeof(icmp_hdr), 0, (struct sockaddr *)&addr, sizeof(addr)) <= 0) {
            perror("sendto");
            continue;
        }

        fd_set readfds;
        struct timeval timeout;
        FD_ZERO(&readfds);
        FD_SET(sockfd, &readfds);
        timeout.tv_sec = 1; timeout.tv_usec = 0; // 1 second timeout

        int ready = select(sockfd+1, &readfds, NULL, NULL, &timeout);
        if (ready > 0 && FD_ISSET(sockfd, &readfds)) {
            char recvbuf[PACKET_SIZE + 64];
            struct sockaddr_in r_addr;
            socklen_t len = sizeof(r_addr);
            ssize_t len_recv = recvfrom(sockfd, recvbuf, sizeof(recvbuf), 0, (struct sockaddr *)&r_addr, &len);
            if (len_recv > 0) {
                struct iphdr *ip_hdr = (struct iphdr*)recvbuf;
                struct icmphdr *icmp_resp = (struct icmphdr*)(recvbuf + (ip_hdr->ihl << 2));
                if (icmp_resp->type == ICMP_ECHOREPLY && icmp_resp->un.echo.id == (getpid() & 0xFFFF)) {
                    gettimeofday(&end, NULL);
                    double rtt = timeval_diff(&start, &end);
                    total_time += rtt;
                    successes++;
                }
            }
        }
        usleep(300*1000); // 300 ms between pings
    }

    close(sockfd);

    if (successes == 0) {
        printf("%s: unreachable\n", ip_addr);
        return -1;
    } else {
        printf("%s: avg RTT = %.2f ms (%d/%d received)\n", ip_addr, total_time / successes, successes, NUM_PINGS);
        return 0;
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: sudo %s IP1 [IP2 ...]\n", argv[0]);
        exit(1);
    }
    for (int i = 1; i < argc; ++i)
        ping(argv[i]);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netinet/ip_icmp.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <errno.h>

#define PACKET_SIZE 64
#define PING_LOOP 4

// Checksum function
unsigned short calculate_checksum(void *b, int len) {    
    unsigned short *buf = b;
    unsigned int sum = 0;
    unsigned short result;

    for (sum = 0; len > 1; len -= 2) sum += *buf++;
    if (len == 1) sum += *(unsigned char *)buf;
    sum = (sum >> 16) + (sum & 0xFFFF);
    sum += (sum >> 16);
    result = ~sum;
    return result;
}

// Ping function
void ping(const char *ip_address) {
    int sockfd;
    struct sockaddr_in addr;
    uint8_t packet[PACKET_SIZE];
    struct icmphdr *icmp_hdr = (struct icmphdr *)packet;
    struct timeval start, end;
    double rtt[PING_LOOP];

    // Create a raw socket
    if ((sockfd = socket(AF_INET, SOCK_RAW, IPPROTO_ICMP)) < 0) {
        perror("Socket creation");
        return;
    }

    addr.sin_family = AF_INET;
    inet_pton(AF_INET, ip_address, &(addr.sin_addr));

    for (int i = 0; i < PING_LOOP; i++) {
        memset(packet, 0, PACKET_SIZE);

        icmp_hdr->type = ICMP_ECHO;
        icmp_hdr->code = 0;
        icmp_hdr->un.echo.id = getpid();
        icmp_hdr->un.echo.sequence = i + 1;
        icmp_hdr->checksum = calculate_checksum(packet, PACKET_SIZE);

        // Record time
        gettimeofday(&start, NULL);

        if (sendto(sockfd, packet, PACKET_SIZE, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
            perror("Sendto");
            close(sockfd);
            return;
        }

        if (recv(sockfd, packet, PACKET_SIZE, 0) < 0) {
            perror("Recv");
            close(sockfd);
            return;
        }

        // Record time
        gettimeofday(&end, NULL);

        // Calculate round-trip time
        rtt[i] = (end.tv_sec - start.tv_sec) * 1000.0 + (end.tv_usec - start.tv_usec) / 1000.0;
        printf("Ping to %s, icmp_seq=%d, time=%.3f ms\n", ip_address, i + 1, rtt[i]);

        sleep(1);
    }

    close(sockfd);

    // Calculate average RTT
    double sum = 0;
    for (int i = 0; i < PING_LOOP; i++) sum += rtt[i];
    printf("Average round-trip time to %s: %.3f ms\n", ip_address, sum / PING_LOOP);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <ip-address-1> [<ip-address-2> ...]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    for (int i = 1; i < argc; i++) {
        printf("Pinging %s:\n", argv[i]);
        ping(argv[i]);
        printf("\n");
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netinet/ip_icmp.h>
#include <time.h>
#include <errno.h>

#define PACKET_SIZE 64
#define PING_COUNT 4

// Function to calculate checksum
unsigned short checksum(void *b, int len) {    
    unsigned short *buf = b;
    unsigned int sum = 0;
    unsigned short result;

    for (sum = 0; len > 1; len -= 2) 
        sum += *buf++;

    if (len == 1)
        sum += *(unsigned char *)buf;

    sum = (sum >> 16) + (sum & 0xFFFF); // Fold 32-bit sum to 16 bits
    sum += (sum >> 16); // Fold again
    result = ~sum; // Invert to get checksum

    return result;
}

void ping(const char *ip_address) {
    int sockfd;
    struct sockaddr_in addr;
    struct icmp icmp_packet;
    struct timeval tv_start, tv_end;
    char packet[PACKET_SIZE];
    int i, total_time = 0;

    sockfd = socket(AF_INET, SOCK_RAW, IPPROTO_ICMP);
    if (sockfd < 0) {
        perror("Socket creation failed");
        return;
    }

    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(ip_address);

    // Prepare ICMP packets
    memset(packet, 0, sizeof(packet));
    memset(&icmp_packet, 0, sizeof(icmp_packet));
    icmp_packet.icmp_type = ICMP_ECHO; // Echo request
    icmp_packet.icmp_code = 0;
    icmp_packet.icmp_id = getpid(); // Use the process ID as the ID
    for (i = 0; i < sizeof(icmp_packet.icmp_seq); i++)
        ((char *)&icmp_packet.icmp_seq)[i] = 'A' + (i % 26);
    icmp_packet.icmp_cksum = checksum(&icmp_packet, sizeof(icmp_packet));

    for (i = 0; i < PING_COUNT; i++) {
        gettimeofday(&tv_start, NULL);

        if (sendto(sockfd, &icmp_packet, sizeof(icmp_packet), 0, (struct sockaddr*)&addr, sizeof(addr)) <= 0) {
            perror("Send failed");
            continue;
        }

        // Wait for reply
        char recv_buffer[PACKET_SIZE];
        socklen_t addr_len = sizeof(addr);
        if (recvfrom(sockfd, recv_buffer, sizeof(recv_buffer), 0, (struct sockaddr*)&addr, &addr_len) > 0) {
            gettimeofday(&tv_end, NULL);
            int time_taken = (tv_end.tv_sec - tv_start.tv_sec) * 1000 + (tv_end.tv_usec - tv_start.tv_usec) / 1000;
            total_time += time_taken;
            printf("Reply from %s: seq=%d time=%d ms\n", ip_address, i + 1, time_taken);
        } else {
            perror("Receive failed");
        }
        usleep(1000000); // Sleep for a second between pings
    }

    close(sockfd);
    printf("Average RTT for %s: %d ms\n", ip_address, total_time / PING_COUNT);
}

