    if (argc < 2) {
        fprintf(stderr, "Usage: %s <IP address1> <IP address2> ... <IP addressN>\n", argv[0]);
        return 1;
    }

    for (int i = 1; i < argc; i++) {
        ping(argv[i]);
    }
    return 0;
}

#include <stdio.h>
