// Define the ICMP packet structure
typedef struct {
    unsigned char type;      // Type of ICMP message (8 for echo request)
    unsigned char code;      // Code (0 for echo request)
    unsigned short checksum; // Checksum (0 for now)
    unsigned short id;       // Identifier (our PID)
    unsigned short sequence; // Sequence number
} icmp_packet;

// Function to calculate the checksum
unsigned short calculate_checksum(unsigned short *ptr, int len) {
    unsigned long checksum = 0;
    while (len > 1) {
        checksum += *(unsigned short *)ptr;
        ptr++;
        len -= 2;
    }
    if (len == 1) {
        checksum += *(unsigned char *)ptr;
    }
    checksum = (checksum >> 16) + (checksum & 0xffff);
    checksum += (checksum >> 16);
    return (unsigned short)(~checksum);
}

// Function to send ping packet and get the response
int send_ping_packet(int sockfd, struct sockaddr_in *addr, icmp_packet *packet) {
    // Calculate the checksum
    packet->checksum = calculate_checksum((unsigned short *)packet, sizeof(icmp_packet));

    // Send the ping packet
    sendto(sockfd, packet, sizeof(icmp_packet), 0, (struct sockaddr *)addr, sizeof(struct sockaddr_in));

    // Receive the response
    char buffer[1024];
    int bytes_received = recvfrom(sockfd, buffer, 1024, 0, NULL, NULL);
    if (bytes_received < 0) {
        perror("recvfrom");
        return -1;
    }

    // Calculate the round-trip time
    struct timeval start, end;
    gettimeofday(&start, NULL);
    gettimeofday(&end, NULL);
    int rtt = (end.tv_usec - start.tv_usec) / 1000;

    return rtt;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <ip_address1> <ip_address2> ...\n", argv[0]);
        return 1;
    }

    // Create a raw socket
    int sockfd = socket(AF_INET, SOCK_RAW, IPPROTO_ICMP);
    if (sockfd < 0) {
        perror("socket");
        return 1;
    }

    // Create an ICMP packet
    icmp_packet packet;
    packet.type = 8;  // Echo request
    packet.code = 0;  // Code
    packet.checksum = 0; // Checksum
    packet.id = getpid(); // Identifier (our PID)
    packet.sequence = 0; // Sequence number

    // Send ping packets to each IP address
    for (int i = 1; i < argc; i++) {
        struct sockaddr_in addr;
        addr.sin_family = AF_INET;
        addr.sin_port = htons(0);
        inet_pton(AF_INET, argv[i], &addr.sin_addr);

        int rtt = send_ping_packet(sockfd, &addr, &packet);
        if (rtt < 0) {
            printf("Error sending ping packet to %s\n", argv[i]);
            continue;
        }

        printf("Round-trip time to %s: %d ms\n", argv[i], rtt);
    }

    // Close the socket
    close(sockfd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <pcap.h>
#include <netinet/ip_icmp.h>
#include <sys/time.h>
#include <time.h>

#define ICMP_DATA_SIZE 40
#define ICMP_HDR_SIZE 8
#define TOTAL_PACKET_SIZE 64
#define NUM_PINGS 5

struct timeval start_time, end_time;

void send_ping(pcap_t *handle, const char *dest_ip) {
    struct icmphdr icmp_hdr;
    char packet[TOTAL_PACKET_SIZE];
    struct in_addr dest_addr;
    struct sockaddr_in sin;
    struct pcap_pkthdr header;
    const u_char *pkt_data;

    memset(&icmp_hdr, 0, sizeof(icmp_hdr));
    icmp_hdr.type = ICMP_ECHO;
    icmp_hdr.code = 0;
    icmp_hdr.un.echo.id = htons(getpid());
    icmp_hdr.un.echo.sequence = htons(1);

    // Generate some data
    for (int i = 0; i < ICMP_DATA_SIZE; i++) {
        packet[i] = i;
    }

    // Calculate the checksum
    icmp_hdr.checksum = 0;
    icmp_hdr.checksum = htons(0x1234); // Placeholder, should be calculated

    // Construct the packet
    memcpy(packet, &icmp_hdr, ICMP_HDR_SIZE);

    // Set the destination IP
    inet_pton(AF_INET, dest_ip, &dest_addr);
    sin.sin_family = AF_INET;
    sin.sin_addr = dest_addr;

    // Send the packet
    if (pcap_sendpacket(handle, packet, TOTAL_PACKET_SIZE) != 0) {
        fprintf(stderr, "Error sending packet: %s\n", pcap_geterr(handle));
        return;
    }

    // Capture the response
    if (pcap_next_ex(handle, &header, &pkt_data) < 1) {
        fprintf(stderr, "Error receiving packet: %s\n", pcap_geterr(handle));
        return;
    }

    // Calculate the round-trip time
    gettimeofday(&end_time, NULL);
    long sec = end_time.tv_sec - start_time.tv_sec;
    long usec = end_time.tv_usec - start_time.tv_usec;
    double rtt = (sec * 1000.0 + usec / 1000.0);
    printf("RTT to %s: %.2f ms\n", dest_ip, rtt);
}

double calculate_average_rtt(pcap_t *handle, const char *dest_ip) {
    double total_rtt = 0.0;
    for (int i = 0; i < NUM_PINGS; i++) {
        gettimeofday(&start_time, NULL);
        send_ping(handle, dest_ip);
        total_rtt += (end_time.tv_sec - start_time.tv_sec) * 1000.0 + (end_time.tv_usec - start_time.tv_usec) / 1000.0;
    }
    return total_rtt / NUM_PINGS;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <ip1> <ip2> ... <ipN>\n", argv[0]);
        return 1;
    }

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle = pcap_open_live("eth0", 65536, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Couldn't open device eth0: %s\n", errbuf);
        return 2;
    }

    for (int i = 1; i < argc; i++) {
        double avg_rtt = calculate_average_rtt(handle, argv[i]);
        printf("Average RTT to %s: %.2f ms\n", argv[i], avg_rtt);
    }

    pcap_close(handle);
    return 0;
}

