#define MAX_ANIMAL_NAME_LEN 50 // Maximum length for an animal name + null terminator

// Function to convert a string to lowercase
void toLowerString(char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        str[i] = tolower(str[i]);
    }
}

// Function to clear the input buffer
void clearInputBuffer() {
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
}

int main() {
    int total_legs = 0;
    char animal_name_input[MAX_ANIMAL_NAME_LEN];
    char lower_animal_name[MAX_ANIMAL_NAME_LEN]; // To store the lowercase version for comparison
    int animal_count;

    printf("Welcome to the Farm Leg Calculator!\n");
    printf("Enter animal names and their counts. Valid animals are: cow, chicken, pig, sheep.\n");
    printf("Type 'done' when you are finished.\n\n");

    while (1) { // Loop indefinitely until 'done' is entered
        printf("Enter animal name (or 'done' to finish): ");
        if (scanf("%s", animal_name_input) != 1) {
            printf("Error reading animal name. Exiting.\n");
            clearInputBuffer(); // Clear buffer in case of an odd input error
            break;
        }
        // Consume the rest of the line, especially the newline left by scanf,
        // which might interfere with subsequent inputs if not consumed.
        clearInputBuffer(); 

        // Convert the input animal name to lowercase for case-insensitive comparison
        strncpy(lower_animal_name, animal_name_input, MAX_ANIMAL_NAME_LEN - 1);
        lower_animal_name[MAX_ANIMAL_NAME_LEN - 1] = '\0'; // Ensure null termination
        toLowerString(lower_animal_name);

        // Check if the user wants to quit
        if (strcmp(lower_animal_name, "done") == 0) {
            break; // Exit the loop
        }

        int legs_per_animal = 0;

        // Determine legs based on animal type
        if (strcmp(lower_animal_name, "cow") == 0) {
            legs_per_animal = 4;
        } else if (strcmp(lower_animal_name, "chicken") == 0) {
            legs_per_animal = 2;
        } else if (strcmp(lower_animal_name, "pig") == 0) {
            legs_per_animal = 4;
        } else if (strcmp(lower_animal_name, "sheep") == 0) {
            legs_per_animal = 4;
        } else {
            printf("Unknown animal: '%s'. Please enter one of the valid animal names.\n", animal_name_input);
            continue; // Skip to the next iteration of the loop
        }

        // If animal name is valid, ask for count
        printf("Enter count for %s: ", animal_name_input);
        if (scanf("%d", &animal_count) != 1) {
            printf("Invalid count. Please enter a number.\n");
            clearInputBuffer(); // Clear the buffer to prevent infinite loop on bad input
            continue; // Skip to the next iteration of the loop
        }
        clearInputBuffer(); // Clear the newline after reading the count

        if (animal_count < 0) {
            printf("Count cannot be negative. Skipping this entry.\n");
            continue; // Skip negative counts
        }

        // Calculate and add to total legs
        total_legs += animal_count * legs_per_animal;
        printf("Added %d legs for %d %s(s).\n\n", animal_count * legs_per_animal, animal_count, animal_name_input);
    }

    printf("\n---------------------------------------\n");
    printf("Total number of legs on the farm: %d\n", total_legs);
    printf("Thank you for using the Farm Leg Calculator!\n");

    return 0; // Indicate successful execution
}

