#define MAX_PATH 1024
#define MAX_COMMAND 2048

// Function to check if a file exists
int file_exists(const char* filename) {
    struct stat buffer;
    return (stat(filename, &buffer) == 0);
}

// Function to find the main .tex file in the directory
int find_main_tex_file(char* path, char* main_tex_file) {
    DIR* dir;
    struct dirent* entry;

    dir = opendir(path);
    if (dir == NULL) {
        perror("Unable to open directory");
        return 0;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (strstr(entry->d_name, ".tex") != NULL) {
            snprintf(main_tex_file, MAX_PATH, "%s/%s", path, entry->d_name);
            closedir(dir);
            return 1;
        }
    }

    closedir(dir);
    return 0;
}

// Function to compile LaTeX document
int compile_latex(const char* path, const char* main_tex_file) {
    char command[MAX_COMMAND];

    // Run pdflatex twice for references and citations
    snprintf(command, sizeof(command), 
             "cd %s && pdflatex -interaction=nonstopmode %s", 
             path, main_tex_file);

    int result1 = system(command);
    int result2 = system(command);

    return (result1 == 0 && result2 == 0);
}

// Function to remove unnecessary files
void clean_latex_files(const char* path, const char* main_tex_file) {
    char* files_to_remove[] = {
        "*.aux", "*.log", "*.toc", "*.lot", "*.lof", 
        "*.out", "*.bbl", "*.blg", "*.synctex.gz"
    };

    int num_files = sizeof(files_to_remove) / sizeof(files_to_remove[0]);

    for (int i = 0; i < num_files; i++) {
        char command[MAX_COMMAND];
        snprintf(command, sizeof(command), 
                 "cd %s && rm -f %s", path, files_to_remove[i]);
        system(command);
    }
}

// Function to create zip archive
int create_zip_archive(const char* path, const char* project_name) {
    char command[MAX_COMMAND];

    // Create a zip file with PDF and necessary source files
    snprintf(command, sizeof(command), 
             "cd %s && zip -r %s.zip *.tex *.bib *.pdf Makefile", 
             path, project_name);

    return system(command) == 0;
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <latex_project_directory>\n", argv[0]);
        return 1;
    }

    char* project_path = argv[1];
    char main_tex_file[MAX_PATH];
    char project_name[MAX_PATH];

    // Extract project name from path
    char* last_slash = strrchr(project_path, '/');
    if (last_slash != NULL) {
        strcpy(project_name, last_slash + 1);
    } else {
        strcpy(project_name, project_path);
    }

    // Find main LaTeX file
    if (!find_main_tex_file(project_path, main_tex_file)) {
        fprintf(stderr, "No LaTeX file found in the directory\n");
        return 1;
    }

    // Compile LaTeX document
    printf("Compiling LaTeX document...\n");
    if (!compile_latex(project_path, main_tex_file)) {
        fprintf(stderr, "LaTeX compilation failed\n");
        return 1;
    }

    // Clean up unnecessary files
    printf("Cleaning up intermediate files...\n");
    clean_latex_files(project_path, main_tex_file);

    // Create zip archive
    printf("Creating project archive...\n");
    if (!create_zip_archive(project_path, project_name)) {
        fprintf(stderr, "Failed to create zip archive\n");
        return 1;
    }

    printf("LaTeX project compiled and archived successfully!\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#define MAX_PATH_LENGTH 1024

void compile_latex(const char *folder_path) {
    char command[MAX_PATH_LENGTH];
    snprintf(command, sizeof(command), "pdflatex -output-directory=%s %s/main.tex", folder_path, folder_path);
    printf("Compiling LaTeX project...\n");
    system(command);
}

void remove_unnecessary_files(const char *folder_path) {
    const char *extensions[] = {".aux", ".log", ".out", ".toc", ".lof", ".lot", ".bbl", ".blg", ".nav", ".snm", ".vrb", NULL};
    char file_path[MAX_PATH_LENGTH];
    for (int i = 0; extensions[i] != NULL; i++) {
        snprintf(file_path, sizeof(file_path), "%s/main%s", folder_path, extensions[i]);
        if (access(file_path, F_OK) == 0) {
            printf("Removing file: %s\n", file_path);
            remove(file_path);
        }
    }
}

void zip_folder(const char *folder_path) {
    char command[MAX_PATH_LENGTH];
    snprintf(command, sizeof(command), "zip -r %s.zip %s", folder_path, folder_path);
    printf("Zipping folder...\n");
    system(command);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <folder_path>\n", argv[0]);
        return 1;
    }

    char folder_path[MAX_PATH_LENGTH];
    strncpy(folder_path, argv[1], sizeof(folder_path) - 1);
    folder_path[sizeof(folder_path) - 1] = '\0';

    // Ensure the folder exists
    struct stat st;
    if (stat(folder_path, &st) != 0 || !S_ISDIR(st.st_mode)) {
        fprintf(stderr, "Error: %s is not a valid directory.\n", folder_path);
        return 1;
    }

    // Compile the LaTeX project
    compile_latex(folder_path);

    // Remove unnecessary files
    remove_unnecessary_files(folder_path);

    // Zip the folder
    zip_folder(folder_path);

    printf("LaTeX project compiled and zipped successfully!\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <unistd.h> // For chdir, getcwd
#include <limits.h> // For PATH_MAX
#include <sys/stat.h> // For stat

// Define constants for buffer sizes
#define MAX_PATH_LEN PATH_MAX
#define MAX_FILENAME_LEN NAME_MAX // Max length of filename in directory entry
#define MAX_COMMAND_LEN 1024
#define MAX_TEX_FILES 10 // Max number of .tex files to consider

// --- Utility Functions ---

// Returns a pointer to the start of the extension (after the last dot)
// or NULL if no dot is found. Modifies the input string.
char *get_last_dot_extension(char *filename) {
    if (!filename || *filename == '\0') return NULL;
    char *dot = strrchr(filename, '.');
    if (dot && dot != filename) { // Ensure it's not a hidden file like ".bashrc"
        return dot + 1;
    }
    return NULL;
}

// Custom basename implementation (safer than POSIX basename which can modify input)
// Caller must free the returned string. Handles trailing slashes.
char *get_base_name_from_path(const char *path) {
    if (!path || *path == '\0') return NULL;

    const char *base = path;
    const char *p = path;

    // Handle trailing slashes first
    size_t len = strlen(path);
    while (len > 0 && path[len - 1] == '/') {
        len--;
    }

    if (len == 0) return strdup("."); // Path was "/" or "///"

    // Find the last slash
    const char *last_slash = NULL;
    for (p = path; *p && (p - path) < len; ++p) {
        if (*p == '/') {
            last_slash = p;
        }
    }

    if (last_slash) {
        base = last_slash + 1;
    }

    // Check if the basename is empty (e.g., path was "/a/b/")
    if (*base == '\0' || (base - path) >= len) {
        // This case means the path was like "/foo/bar/" -- basename is "bar"
        // Need to backtrack one more slash to find the actual name.
        if (last_slash && last_slash != path) { // Not the root slash
            const char *prev_slash = NULL;
            for (p = path; p < last_slash; ++p) {
                if (*p == '/') {
                    prev_slash = p;
                }
            }
            if (prev_slash) {
                base = prev_slash + 1;
            } else { // Path was like "/foo"
                 base = path + 1;
            }
        }
        // If still empty or something went wrong, just use "."
        if (*base == '\0' || (base - path) >= len) {
            return strdup(".");
        }
    }


    size_t base_len = len - (base - path);
    char *result = (char *)malloc(base_len + 1);
    if (result) {
        strncpy(result, base, base_len);
        result[base_len] = '\0';
    }
    return result;
}

// --- Core Logic Functions ---

// Locates the main .tex file in the given directory.
// Prioritizes files containing "\documentclass". If multiple, picks the first.
// If none contain "\documentclass", picks the first .tex file found alphabetically.
// Returns 1 on success (main_tex_file populated), 0 on failure.
int find_main_tex_file(const char *dir_path, char *main_tex_file) {
    DIR *d;
    struct dirent *dir;
    FILE *fp;
    char path[MAX_PATH_LEN];
    char line[256];
    char temp_tex_files[MAX_TEX_FILES][MAX_FILENAME_LEN];
    int tex_count = 0;
    int found_documentclass = 0;

    d = opendir(dir_path);
    if (!d) {
        fprintf(stderr, "Error: Could not open directory '%s'\n", dir_path);
        return 0;
    }

    // Step 1: Find all .tex files and store them
    while ((dir = readdir(d)) != NULL) {
        char *ext = get_last_dot_extension(dir->d_name);
        if (ext && strcmp(ext, "tex") == 0) {
            if (tex_count < MAX_TEX_FILES) {
                strncpy(temp_tex_files[tex_count], dir->d_name, MAX_FILENAME_LEN - 1);
                temp_tex_files[tex_count][MAX_FILENAME_LEN - 1] = '\0';
                tex_count++;
            } else {
                fprintf(stderr, "Warning: More than %d .tex files found. Only processing the first %d.\n", MAX_TEX_FILES, MAX_TEX_FILES);
                break;
            }
        }
    }
    closedir(d); // Reopen for second pass if needed, or sort and check

    if (tex_count == 0) {
        fprintf(stderr, "Error: No .tex files found in '%s'\n", dir_path);
        return 0;
    }

    // Step 2: Check each .tex file for \documentclass
    // Sorting first helps ensure consistent behavior if multiple have \documentclass
    // (though not strictly necessary as we take the first one found that matches)
    for (int i = 0; i < tex_count - 1; i++) {
        for (int j = i + 1; j < tex_count; j++) {
            if (strcmp(temp_tex_files[i], temp_tex_files[j]) > 0) {
                char temp[MAX_FILENAME_LEN];
                strncpy(temp, temp_tex_files[i], MAX_FILENAME_LEN);
                strncpy(temp_tex_files[i], temp_tex_files[j], MAX_FILENAME_LEN);
                strncpy(temp_tex_files[j], temp, MAX_FILENAME_LEN);
            }
        }
    }

    for (int i = 0; i < tex_count; i++) {
        snprintf(path, MAX_PATH_LEN, "%s/%s", dir_path, temp_tex_files[i]);
        fp = fopen(path, "r");
        if (fp) {
            while (fgets(line, sizeof(line), fp) != NULL) {
                if (strstr(line, "\\documentclass") != NULL) {
                    strncpy(main_tex_file, temp_tex_files[i], MAX_FILENAME_LEN - 1);
                    main_tex_file[MAX_FILENAME_LEN - 1] = '\0';
                    fclose(fp);
                    return 1; // Found the main .tex file
                }
            }
            fclose(fp);
        } else {
            fprintf(stderr, "Warning: Could not open file '%s' for reading.\n", path);
        }
    }

    // If no file with \documentclass was found, default to the first .tex file alphabetically
    fprintf(stderr, "Warning: No .tex file with \\documentclass found naturally. Using '%s' as main file.\n", temp_tex_files[0]);
    strncpy(main_tex_file, temp_tex_files[0], MAX_FILENAME_LEN - 1);
    main_tex_file[MAX_FILENAME_LEN - 1] = '\0';
    return 1;
}

// Compiles the LaTeX project using pdflatex. Runs multiple times if necessary.
// Returns 0 on success, -1 on failure.
int compile_latex(const char *main_tex_file) {
    char command[MAX_COMMAND_LEN];
    int ret;

    printf("--> Compiling LaTeX project with %s...\n", main_tex_file);

    // Run pdflatex multiple times for TOC, references, bibliography, etc.
    // A typical LaTeX workflow might be: pdflatex -> bibtex -> pdflatex -> pdflatex
    // We'll run pdflatex a few times, which often generates most necessary info.
    // For bibtex, we should explicitly check for .aux and .bib existence.

    // First run to generate .aux and .bbl (if using bibtex)
    snprintf(command, MAX_COMMAND_LEN, "pdflatex -interaction=nonstopmode %s", main_tex_file);
    printf("Running command: %s\n", command);
    ret = system(command);
    if (ret != 0) {
        fprintf(stderr, "Error: pdflatex failed on first pass. Exit code: %d\n", ret);
        return -1;
    }

    // Check if a .aux file exists (to determine if bibtex/biber might be needed)
    char aux_file[MAX_FILENAME_LEN];
    char base_name[MAX_FILENAME_LEN]; // e.g. "document" from "document.tex"
    strncpy(base_name, main_tex_file, MAX_FILENAME_LEN - 1);
    char *dot = strrchr(base_name, '.');
    if (dot) *dot = '\0'; // Null-terminate at the dot

    snprintf(aux_file, MAX_FILENAME_LEN, "%s.aux", base_name);

    struct stat buffer;
    if (stat(aux_file, &buffer) == 0) { // Check if .aux file exists
        // Check if there are .bib files
        DIR *d = opendir("."); // Current directory
        struct dirent *dir;
        int bib_found = 0;
        if (d) {
            while ((dir = readdir(d)) != NULL) {
                char *ext = get_last_dot_extension(dir->d_name);
                if (ext && strcmp(ext, "bib") == 0) {
                    bib_found = 1;
                    break;
                }
            }
            closedir(d);
        }

        if (bib_found) {
            // Run bibtex or biber if necessary (check for biber.log/biber command presence for smarter choice)
            // For simplicity, we'll try bibtex first. A more advanced app might check for biber usage.
            printf("Running bibtex...\n");
            snprintf(command, MAX_COMMAND_LEN, "bibtex %s", base_name);
            printf("Running command: %s\n", command);
            ret = system(command);
            if (ret != 0 && ret != 256) { // bibtex returns 256 for no references, which is not an error
                fprintf(stderr, "Warning: bibtex failed. Exit code: %d\n", ret);
                // Don't return -1 here, pdflatex might still work enough
            }
        }
    }

    // Run pdflatex two more times to resolve references, TOC, etc.
    for (int i = 0; i < 2; ++i) {
        snprintf(command, MAX_COMMAND_LEN, "pdflatex -interaction=nonstopmode %s", main_tex_file);
        printf("Running command: %s (Pass %d/2)\n", command, i + 1);
        ret = system(command);
        if (ret != 0) {
            fprintf(stderr, "Error: pdflatex failed on pass %d. Exit code: %d\n", i + 2, ret);
            return -1;
        }
    }

    char pdf_name[MAX_FILENAME_LEN];
    snprintf(pdf_name, MAX_FILENAME_LEN, "%s.pdf", base_name);
    if (access(pdf_name, F_OK) != 0) {
        fprintf(stderr, "Error: PDF file '%s' was not generated.\n", pdf_name);
        return -1;
    }

    printf("--> LaTeX compilation successful. PDF generated: %s\n", pdf_name);
    return 0;
}

// Removes common intermediate LaTeX files.
void clean_latex_files(const char *project_dir_path, const char *main_pdf_name) {
    printf("--> Cleaning up intermediate files...\n");
    DIR *d;
    struct dirent *dir;
    char file_path[MAX_PATH_LEN];
    char command[MAX_COMMAND_LEN];

    // List of common LaTeX temporary file extensions to remove
    const char *cleanup_extensions[] = {
        "aux", "log", "blg", "bbl", "lof", "lot", "toc", "nav",
        "out", "snm", "fls", "fdb_latexmk", "vrb", "synctex.gz",
        "gz", // specifically for .gz if not taken care of by synctex.gz
        "xdv", "bcf", "run.xml", "spl", "mlf", "mlt", "bak", "idx", "ilg", "ind",
        // Add more exotic ones if needed:
        "dpth", "tps", "thm", "tdo", "mw", "gz(log)"
    };
    int num_cleanup_ext = sizeof(cleanup_extensions) / sizeof(cleanup_extensions[0]);

    d = opendir(project_dir_path);
    if (!d) {
        fprintf(stderr, "Warning: Could not open directory for cleanup '%s'\n", project_dir_path);
        return;
    }

    while ((dir = readdir(d)) != NULL) {
        // Skip . and ..
        if (strcmp(dir->d_name, ".") == 0 || strcmp(dir->d_name, "..") == 0) continue;

        // Do not delete the main PDF file or .tex/.bib files
        if (strcmp(dir->d_name, main_pdf_name) == 0) continue;
        char *ext_upper = strrchr(dir->d_name, '.');
        if (ext_upper) {
            ext_upper++; // Move past the dot
            if(strcmp(ext_upper, "tex") == 0 || strcmp(ext_upper, "pdf") == 0 || strcmp(ext_upper, "bib") == 0 || strcmp(ext_upper, "eps") == 0 || strcmp(ext_upper, "png") == 0 || strcmp(ext_upper, "jpg") == 0 || strcmp(ext_upper, "jpeg") == 0) {
                continue;
            }
        }

        // Check if the file's extension is in our cleanup list
        char *file_ext = get_last_dot_extension(dir->d_name);
        if (file_ext) {
            int should_delete = 0;
            for (int i = 0; i < num_cleanup_ext; ++i) {
                if (strcmp(file_ext, cleanup_extensions[i]) == 0) {
                    should_delete = 1;
                    break;
                }
            }

            if (should_delete) {
                snprintf(command, MAX_COMMAND_LEN, "rm \"%s\"", dir->d_name);
                printf(" - Deleting: %s\n", dir->d_name);
                int ret = system(command);
                if (ret != 0) {
                    fprintf(stderr, "Warning: Failed to delete '%s'. Exit code: %d\n", dir->d_name, ret);
                }
            }
        }
    }
    closedir(d);
    printf("--> Cleanup complete.\n");
}


// Zips the main PDF, .tex files, and .bib files into an archive.
// Returns 0 on success, -1 on failure.
int zip_project(const char *project_dir_path, const char *zip_name, const char *main_pdf_name, const char *main_tex_file) {
    printf("--> Zipping project for publishing...\n");
    char command[MAX_COMMAND_LEN];
    char pdf_base_name[MAX_FILENAME_LEN];
    char tex_base_name[MAX_FILENAME_LEN];

    // Extract base name for main PDF (e.g., "document.pdf")
    strncpy(pdf_base_name, main_pdf_name, MAX_FILENAME_LEN - 1);
    pdf_base_name[MAX_FILENAME_LEN - 1] = '\0';

    // Extract base name for main TEX (e.g., "document.tex")
    strncpy(tex_base_name, main_tex_file, MAX_FILENAME_LEN - 1);
    tex_base_name[MAX_FILENAME_LEN - 1] = '\0';

    // Construct the zip command to include main .pdf, .tex files, and .bib files.
    // Including `*.tex` and `*.bib` will get all of them.
    snprintf(command, MAX_COMMAND_LEN, "zip -r ../\"%s\" \"%s\" *.tex *.bib", zip_name, pdf_base_name);

    printf("Running command: %s\n", command);
    int ret = system(command);
    if (ret != 0) {
        fprintf(stderr, "Error: Zipping failed. Exit code: %d\n", ret);
        return -1;
    }

    printf("--> Project zipped to %s\n", zip_name);
    return 0;
}


int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <path_to_latex_project_folder>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char project_dir_path[MAX_PATH_LEN];
    // Resolve the absolute path to handle relative paths given by user
    if (realpath(argv[1], project_dir_path) == NULL) {
        fprintf(stderr, "Error: Invalid path or directory does not exist: '%s'\n", argv[1]);
        return EXIT_FAILURE;
    }

    char original_cwd[MAX_PATH_LEN];
    if (getcwd(original_cwd, sizeof(original_cwd)) == NULL) {
        perror("Error getting current working directory");
        return EXIT_FAILURE;
    }

    // Change to the project directory
    if (chdir(project_dir_path) != 0) {
        perror("Error changing directory to project folder");
        fprintf(stderr, "Path: '%s'\n", project_dir_path);
        return EXIT_FAILURE;
    }

    char main_tex_file[MAX_FILENAME_LEN];
    if (!find_main_tex_file(".", main_tex_file)) { // Search in current directory (which is project_dir_path)
        chdir(original_cwd); // Change back before exiting
        return EXIT_FAILURE;
    }

    // Attempt to compile LaTeX
    if (compile_latex(main_tex_file) != 0) {
        fprintf(stderr, "LaTeX compilation failed. Exiting.\n");
        chdir(original_cwd); // Change back before exiting
        return EXIT_FAILURE;
    }

    char base_name[MAX_FILENAME_LEN]; // e.g. "document" from "document.tex"
    strncpy(base_name, main_tex_file, MAX_FILENAME_LEN - 1);
    char *dot = strrchr(base_name, '.');
    if (dot) *dot = '\0'; // Null-terminate at the dot

    char main_pdf_name[MAX_FILENAME_LEN];
    snprintf(main_pdf_name, MAX_FILENAME_LEN, "%s.pdf", base_name);

    // Clean up intermediate files
    clean_latex_files(".", main_pdf_name); // Cleanup in current directory

    // Get the base name of the project folder for the zip file name
    char *project_folder_base_name = get_base_name_from_path(project_dir_path);
    if (!project_folder_base_name) {
        fprintf(stderr, "Error: Could not determine project folder base name.\n");
        chdir(original_cwd); // Change back before exiting
        return EXIT_FAILURE;
    }

    char zip_file_name[MAX_FILENAME_LEN];
    snprintf(zip_file_name, MAX_FILENAME_LEN, "%s_compiled.zip", project_folder_base_name);

    // Zip the project
    int zip_result = zip_project(".", zip_file_name, main_pdf_name, main_tex_file); // Zip in current directory

    // Change back to the original directory
    if (chdir(original_cwd) != 0) {
        perror("Error changing back to original directory");
        // Don't exit, we've already done most work, just a cleanup error
    }

    free(project_folder_base_name); // Free the dynamically allocated string

    if (zip_result != 0) {
        fprintf(stderr, "Project zipping failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("\nSuccess! LaTeX project processed and zipped.\n");
    printf("Output ZIP file: %s/%s\n", original_cwd, zip_file_name);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>

#define MAX_PATH 1024

// List of common LaTeX aux files
const char *aux_exts[] = {
    ".aux", ".log", ".out", ".bbl", ".blg", ".toc", ".lof", ".lot",
    ".fls", ".fdb_latexmk", ".synctex.gz", ".nav", ".snm", ".vrb",
    ".ilg", ".ind", ".idx", ".bcf", ".run.xml"
};
const int NUM_AUX_EXTS = sizeof(aux_exts)/sizeof(aux_exts[0]);

int endsWith(const char *str, const char *suffix) {
    if (!str || !suffix) return 0;
    size_t slen = strlen(str);
    size_t suflen = strlen(suffix);
    if (slen < suflen) return 0;
    return strcmp(str + slen - suflen, suffix) == 0;
}

// Finds the first .tex file in folder_path, sets result in texfile_path (MUST fit buffer)
int find_tex_file(const char *folder_path, char *texfile_path) {
    DIR *dir = opendir(folder_path);
    struct dirent *entry;
    if (!dir) return 0;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && endsWith(entry->d_name, ".tex")) {
            snprintf(texfile_path, MAX_PATH, "%s/%s", folder_path, entry->d_name);
            closedir(dir);
            return 1;
        }
    }
    closedir(dir);
    return 0;
}

void remove_aux_files(const char *folder_path) {
    DIR *dir = opendir(folder_path);
    struct dirent *entry;
    if (!dir) return;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) {
            for (int i=0; i<NUM_AUX_EXTS; ++i) {
                if (endsWith(entry->d_name, aux_exts[i])) {
                    char to_remove[MAX_PATH];
                    snprintf(to_remove, MAX_PATH, "%s/%s", folder_path, entry->d_name);
                    if (remove(to_remove) == 0) {
                        printf("Removed: %s\n", to_remove);
                    }
                }
            }
        }
    }
    closedir(dir);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <latex-project-folder>\n", argv[0]);
        return 1;
    }

    char *folder = argv[1];
    struct stat sb;
    if (stat(folder, &sb) != 0 || !S_ISDIR(sb.st_mode)) {
        printf("Given path is not a folder.\n");
        return 2;
    }

    // Find .tex file
    char texfile[MAX_PATH];
    if (!find_tex_file(folder, texfile)) {
        printf("No .tex file found in provided folder.\n");
        return 3;
    }
    printf("Found main tex file: %s\n", texfile);

    // Compile PDF (twice to resolve references)
    char pdflatex_cmd[MAX_PATH * 2];
    snprintf(pdflatex_cmd, sizeof(pdflatex_cmd), "cd \"%s\" && pdflatex -interaction=nonstopmode \"%s\" > /dev/null", folder, texfile + strlen(folder) + 1);
    printf("Compiling PDF...\n");
    if (system(pdflatex_cmd) != 0) {
        printf("First pdflatex pass failed.\n");
        return 4;
    }
    if (system(pdflatex_cmd) != 0) {
        printf("Second pdflatex pass failed.\n");
        return 5;
    }

    // Remove auxiliary files
    printf("Removing auxiliary files...\n");
    remove_aux_files(folder);

    // Create ZIP
    char zip_cmd[MAX_PATH*2];
    snprintf(zip_cmd, sizeof(zip_cmd), "cd \"%s/..\" && zip -r \"%s.zip\" \"%s\" > /dev/null",
        folder, folder, strrchr(folder, '/') ? strrchr(folder, '/')+1 : folder);
    printf("Creating ZIP archive...\n");
    if(system(zip_cmd) != 0) {
        printf("ZIP command failed.\n");
        return 6;
    }

    printf("Project folder compiled, cleaned, and zipped to %s.zip\n", folder);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>

#define BUFFER_SIZE 256

// Helper function to execute a command and handle errors
void execute_command(const char *command) {
    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Error executing command: %s\n", command);
        exit(EXIT_FAILURE);
    }
}

// Function to compile the LaTeX project
void compile_latex(const char *project_dir) {
    char command[BUFFER_SIZE];
    snprintf(command, BUFFER_SIZE, "pdflatex -output-directory=%s %s/main.tex", project_dir, project_dir);
    execute_command(command);
    // Run pdflatex twice to resolve references and citations
    execute_command(command);
}

// Function to remove unnecessary files generated by LaTeX
void clean_directory(const char *project_dir) {
    const char *extensions[] = {".aux", ".log", ".out", ".toc"};
    size_t ext_count = sizeof(extensions) / sizeof(extensions[0]);

    char path[BUFFER_SIZE];
    DIR *dir = opendir(project_dir);
    if (dir == NULL) {
        perror("Unable to open directory");
        exit(EXIT_FAILURE);
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        for (size_t i = 0; i < ext_count; i++) {
            if (strstr(entry->d_name, extensions[i]) != NULL) {
                snprintf(path, BUFFER_SIZE, "%s/%s", project_dir, entry->d_name);
                if (remove(path) != 0) {
                    perror("Error removing file");
                }
            }
        }
    }
    closedir(dir);
}

// Function to zip the LaTeX project
void zip_project(const char *project_dir, const char *output_zip) {
    char command[BUFFER_SIZE];
    snprintf(command, BUFFER_SIZE, "zip -r %s %s", output_zip, project_dir);
    execute_command(command);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <project_directory> <output_zip>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *project_dir = argv[1];
    const char *output_zip = argv[2];

    compile_latex(project_dir);
    clean_directory(project_dir);
    zip_project(project_dir, output_zip);

    printf("LaTeX project compiled and zipped successfully.\n");
    return EXIT_SUCCESS;
}

