#define MAX_FILE_NAME_LENGTH 256
#define MAX_COMMAND_LENGTH 1024

// Function to execute a system command
int executeCommand(const char *command) {
    int result = system(command);
    if (result == -1) {
        perror("Error executing command");
        return -1;
    }
    return result;
}

// Function to remove unnecessary files
int cleanUpFiles(char *folderPath) {
    char command[MAX_COMMAND_LENGTH];
    snprintf(command, sizeof(command), "cd %s && rm -f *.aux *.log *.out *.toc", folderPath);
    return executeCommand(command);
}

// Function to zip the folder
int zipFolder(char *folderPath, char *outputZip) {
    char command[MAX_COMMAND_LENGTH];
    snprintf(command, sizeof(command), "cd %s && zip -r %s .", folderPath, outputZip);
    return executeCommand(command);
}

// Function to find the main LaTeX file (assumes it has a .tex extension)
char* findMainTexFile(char *folderPath) {
    DIR *dir;
    struct dirent *entry;
    char *mainTexFile = NULL;

    dir = opendir(folderPath);
    if (dir == NULL) {
        perror("Error opening directory");
        return NULL;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) { // Regular file
            char *ext = strrchr(entry->d_name, '.');
            if (ext != NULL && strcmp(ext, ".tex") == 0) {
                if (mainTexFile == NULL) {
                    mainTexFile = strdup(entry->d_name); // Assume the first .tex file is the main one
                } else {
                    fprintf(stderr, "Multiple .tex files found. Using the first one: %s\n", mainTexFile);
                }
            }
        }
    }

    closedir(dir);
    return mainTexFile;
}

// Function to compile the LaTeX project
int compileLaTeX(char *folderPath, char *mainTexFile) {
    char command[MAX_COMMAND_LENGTH];
    snprintf(command, sizeof(command), "cd %s && pdflatex %s", folderPath, mainTexFile);
    return executeCommand(command);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <folder_path>\n", argv[0]);
        return 1;
    }

    char *folderPath = argv[1];
    char *mainTexFile = findMainTexFile(folderPath);

    if (mainTexFile == NULL) {
        fprintf(stderr, "No .tex file found in the specified folder.\n");
        return 1;
    }

    // Compile the LaTeX project
    if (compileLaTeX(folderPath, mainTexFile) != 0) {
        fprintf(stderr, "Error compiling LaTeX project.\n");
        free(mainTexFile);
        return 1;
    }

    // Clean up unnecessary files
    if (cleanUpFiles(folderPath) != 0) {
        fprintf(stderr, "Error cleaning up files.\n");
        free(mainTexFile);
        return 1;
    }

    // Zip the folder
    char outputZip[MAX_FILE_NAME_LENGTH];
    snprintf(outputZip, sizeof(outputZip), "%s.zip", folderPath);
    if (zipFolder(folderPath, outputZip) != 0) {
        fprintf(stderr, "Error zipping the folder.\n");
        free(mainTexFile);
        return 1;
    }

    printf("Project compiled, cleaned, and zipped successfully as %s\n", outputZip);
    free(mainTexFile);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/wait.h>

#define MAX_REPOS 100
#define MAX_URL_LENGTH 256
#define MAX_ERROR_LENGTH 512

// Structure to track repository cloning status
typedef struct {
    char url[MAX_URL_LENGTH];
    int success;
    char error_message[MAX_ERROR_LENGTH];
} RepoStatus;

// Function to clone a single repository
int clone_repository(const char* repo_url, const char* output_dir) {
    pid_t pid = fork();

    if (pid == -1) {
        perror("Fork failed");
        return -1;
    }

    if (pid == 0) {
        // Child process
        execlp("git", "git", "clone", repo_url, output_dir, NULL);
        // If execlp fails
        perror("Exec failed");
        exit(1);
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);

        if (WIFEXITED(status)) {
            return WEXITSTATUS(status);
        }

        return -1;
    }
}

// Function to create output directory if it doesn't exist
int create_output_directory(const char* dir_path) {
    struct stat st = {0};

    if (stat(dir_path, &st) == -1) {
        if (mkdir(dir_path, 0755) == -1) {
            perror("Failed to create output directory");
            return -1;
        }
    }

    return 0;
}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <output_directory> <repo_url1> [<repo_url2> ...]\n", argv[0]);
        return 1;
    }

    const char* output_base_dir = argv[1];
    int repo_count = argc - 2;

    // Create base output directory
    if (create_output_directory(output_base_dir) != 0) {
        return 1;
    }

    // Array to track repository statuses
    RepoStatus repo_statuses[MAX_REPOS];

    // Clone repositories
    for (int i = 0; i < repo_count; i++) {
        const char* repo_url = argv[i + 2];

        // Create a unique directory for each repository
        char output_dir[MAX_URL_LENGTH];
        char* repo_name = strrchr(repo_url, '/');
        if (repo_name == NULL) {
            repo_name = (char*)repo_url;
        } else {
            repo_name++; // Skip the '/'
        }

        // Remove .git extension if present
        char* git_ext = strstr(repo_name, ".git");
        if (git_ext) {
            *git_ext = '\0';
        }

        snprintf(output_dir, sizeof(output_dir), "%s/%s", output_base_dir, repo_name);

        // Prepare status tracking
        strncpy(repo_statuses[i].url, repo_url, MAX_URL_LENGTH - 1);

        // Attempt to clone
        int result = clone_repository(repo_url, output_dir);

        if (result == 0) {
            repo_statuses[i].success = 1;
            strcpy(repo_statuses[i].error_message, "");
        } else {
            repo_statuses[i].success = 0;
            snprintf(repo_statuses[i].error_message, MAX_ERROR_LENGTH, "Failed to clone repository");
        }
    }

    // Print summary of cloning results
    printf("\nCloning Summary:\n");
    printf("---------------\n");

    int failed_count = 0;
    for (int i = 0; i < repo_count; i++) {
        if (repo_statuses[i].success) {
            printf("✓ Successfully cloned: %s\n", repo_statuses[i].url);
        } else {
            printf("✗ Failed to clone: %s\n", repo_statuses[i].url);
            failed_count++;
        }
    }

    printf("\nTotal Repositories: %d\n", repo_count);
    printf("Successfully Cloned: %d\n", repo_count - failed_count);
    printf("Failed to Clone: %d\n", failed_count);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <dirent.h>
#include <errno.h>

#define MAX_REPOS 100
#define MAX_URL_LENGTH 256
#define MAX_PATH_LENGTH 1024

typedef struct {
    char url[MAX_URL_LENGTH];
    int success;
} GitRepoResult;

int clone_repository(const char *url, const char *target_dir) {
    pid_t pid = fork();

    if (pid == -1) {
        perror("fork failed");
        return -1;
    }

    if (pid == 0) { // Child process
        // Change to target directory
        if (chdir(target_dir) == -1) {
            perror("chdir failed");
            exit(EXIT_FAILURE);
        }

        // Execute git clone
        execlp("git", "git", "clone", url, NULL);

        // If execlp returns, it failed
        perror("execlp failed");
        exit(EXIT_FAILURE);
    } else { // Parent process
        int status;
        waitpid(pid, &status, 0);

        if (WIFEXITED(status)) {
            return WEXITSTATUS(status) == 0 ? 0 : -1;
        }
        return -1;
    }
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <target_directory> <repo_url1> [repo_url2 ...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *target_dir = argv[1];
    int num_repos = argc - 2;

    if (num_repos > MAX_REPOS) {
        fprintf(stderr, "Error: Maximum number of repositories (%d) exceeded\n", MAX_REPOS);
        return EXIT_FAILURE;
    }

    // Create target directory if it doesn't exist
    DIR *dir = opendir(target_dir);
    if (dir) {
        closedir(dir);
    } else if (mkdir(target_dir, 0755) == -1) {
        perror("Failed to create target directory");
        return EXIT_FAILURE;
    }

    GitRepoResult results[MAX_REPOS];
    int failed_count = 0;

    printf("Starting to clone %d repositories to: %s\n\n", num_repos, target_dir);

    for (int i = 0; i < num_repos; i++) {
        const char *url = argv[i + 2];
        strncpy(results[i].url, url, MAX_URL_LENGTH - 1);
        results[i].url[MAX_URL_LENGTH - 1] = '\0';

        printf("Cloning repository %d/%d: %s\n", i + 1, num_repos, url);

        if (clone_repository(url, target_dir) == 0) {
            results[i].success = 1;
            printf("Successfully cloned: %s\n\n", url);
        } else {
            results[i].success = 0;
            fprintf(stderr, "Failed to clone: %s\n\n", url);
            failed_count++;
        }
    }

    printf("\nCloning process completed.\n");
    printf("Successfully cloned: %d\n", num_repos - failed_count);
    printf("Failed to clone: %d\n", failed_count);

    if (failed_count > 0) {
        printf("\nFailed repositories:\n");
        for (int i = 0; i < num_repos; i++) {
            if (!results[i].success) {
                printf("- %s\n", results[i].url);
            }
        }
    }

    return failed_count == 0 ? EXIT_SUCCESS : EXIT_FAILURE;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h> // For mkdir
#include <sys/types.h> // For mkdir
#include <errno.h>    // For errno
#include <libgen.h>   // For basename (GNU extension, sometimes part of string.h)

#ifdef _WIN32
    #include <direct.h> // For _mkdir on Windows
    #define MKDIR(dir) _mkdir(dir)
#else
    #include <unistd.h> // For rmdir, access
    #define MKDIR(dir) mkdir(dir, 0755) // Permissions for Unix-like systems
#endif

// Threading includes
#ifdef _WIN32
    #include <windows.h>
    #define THREAD_HANDLE HANDLE
    #define THREAD_FUNC_RETURN DWORD WINAPI
    #define THREAD_CREATE(handle, func, arg) (*handle = CreateThread(NULL, 0, func, arg, 0, NULL))
    #define THREAD_JOIN(handle) WaitForSingleObject(handle, INFINITE)
    #define MUTEX_T CRITICAL_SECTION
    #define MUTEX_INIT(mutex) InitializeCriticalSection(mutex)
    #define MUTEX_LOCK(mutex) EnterCriticalSection(mutex)
    #define MUTEX_UNLOCK(mutex) LeaveCriticalSection(mutex)
    #define MUTEX_DESTROY(mutex) DeleteCriticalSection(mutex)
    #define POPEN _popen
    #define PCLOSE _pclose
    #define PATH_SEP '\\'
#else
    #include <pthread.h>
    #define THREAD_HANDLE pthread_t
    #define THREAD_FUNC_RETURN void*
    #define THREAD_CREATE(handle, func, arg) pthread_create(handle, NULL, func, arg)
    #define THREAD_JOIN(handle) pthread_join(handle, NULL)
    #define MUTEX_T pthread_mutex_t
    #define MUTEX_INIT(mutex) pthread_mutex_init(mutex, NULL)
    #define MUTEX_LOCK(mutex) pthread_mutex_lock(mutex)
    #define MUTEX_UNLOCK(mutex) pthread_mutex_unlock(mutex)
    #define MUTEX_DESTROY(mutex) pthread_mutex_destroy(mutex)
    #define POPEN popen
    #define PCLOSE pclose
    #define PATH_SEP '/'
#endif

#define MAX_LINE_LENGTH 1024
#define DEFAULT_THREADS 4

typedef enum {
    STATUS_PENDING,
    STATUS_SUCCESS,
    STATUS_FAILED
} clone_status_t;

typedef struct git_repo {
    char url[MAX_LINE_LENGTH];
    char target_dir[MAX_LINE_LENGTH]; // Full path to where it should be cloned
    clone_status_t status;
    char error_message[MAX_LINE_LENGTH * 2]; // More space for error messages
    struct git_repo *next;
} git_repo_t;

// --- Global Variables (Protected by Mutexes) ---
git_repo_t *repo_list = NULL;
int total_repos = 0;
int cloned_count = 0;
int failed_count = 0;

MUTEX_T list_mutex; // Protects access to repo_list, total_repos, cloned_count, failed_count
MUTEX_T print_mutex; // Protects shared access to stdout/stderr

// --- Function Prototypes ---
void usage(const char *prog_name);
int read_repos_from_file(const char *filename);
char* get_repo_name_from_url(const char *url);
int create_directory_recursive(const char *path);
int rmdir_recursive(const char *path);
THREAD_FUNC_RETURN clone_repository(void *arg);
void free_repo_list();
void print_results();

// --- Main Function ---
int main(int argc, char *argv[]) {
    if (argc < 3) {
        usage(argv[0]);
        return 1;
    }

    const char *repo_list_file = argv[1];
    const char *output_dir = argv[2];
    int num_threads = DEFAULT_THREADS;

    if (argc >= 4) {
        num_threads = atoi(argv[3]);
        if (num_threads <= 0) {
            fprintf(stderr, "Error: Invalid number of threads. Using default %d.\n", DEFAULT_THREADS);
            num_threads = DEFAULT_THREADS;
        }
    }

    fprintf(stdout, "Git Cloner Application\n");
    fprintf(stdout, "----------------------\n");
    fprintf(stdout, "Repository list file: %s\n", repo_list_file);
    fprintf(stdout, "Output directory: %s\n", output_dir);
    fprintf(stdout, "Concurrency: %d threads\n", num_threads);
    fprintf(stdout, "----------------------\n\n");

    // Initialize mutexes
    MUTEX_INIT(&list_mutex);
    MUTEX_INIT(&print_mutex);

    // Create the base output directory if it doesn't exist
    if (create_directory_recursive(output_dir) != 0) {
        fprintf(stderr, "Error: Could not create output directory '%s'. Reason: %s\n", output_dir, strerror(errno));
        free_repo_list();
        MUTEX_DESTROY(&list_mutex);
        MUTEX_DESTROY(&print_mutex);
        return 1;
    }

    // Read repository URLs
    if (read_repos_from_file(repo_list_file) != 0) {
        fprintf(stderr, "Error: Failed to read repository list from '%s'.\n", repo_list_file);
        free_repo_list();
        MUTEX_DESTROY(&list_mutex);
        MUTEX_DESTROY(&print_mutex);
        return 1;
    }

    if (total_repos == 0) {
        fprintf(stdout, "No repositories found in '%s'. Exiting.\n", repo_list_file);
        free_repo_list();
        MUTEX_DESTROY(&list_mutex);
        MUTEX_DESTROY(&print_mutex);
        return 0;
    }

    // Populate target_dir for each repo
    git_repo_t *current = repo_list;
    while (current != NULL) {
        char *repo_name = get_repo_name_from_url(current->url);
        if (repo_name == NULL) {
             snprintf(current->error_message, sizeof(current->error_message), "Could not extract repo name from URL '%s'", current->url);
             current->status = STATUS_FAILED;
             failed_count++;
             current = current->next;
             continue;
        }
        snprintf(current->target_dir, sizeof(current->target_dir), "%s%c%s", output_dir, PATH_SEP, repo_name);
        // Free the dynamically allocated repo_name
        free(repo_name);
        current = current->next;
    }

    // Create threads
    THREAD_HANDLE *threads = (THREAD_HANDLE *)malloc(sizeof(THREAD_HANDLE) * num_threads);
    if (threads == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for threads.\n");
        free_repo_list();
        MUTEX_DESTROY(&list_mutex);
        MUTEX_DESTROY(&print_mutex);
        return 1;
    }

    fprintf(stdout, "Initiating cloning of %d repositories with %d threads...\n\n", total_repos, num_threads);

    for (int i = 0; i < num_threads; ++i) {
        if (THREAD_CREATE(&threads[i], clone_repository, (void *) output_dir) != 0) { // Pass output_dir to threads
            fprintf(stderr, "Error: Could not create thread %d.\n", i);
            // In a real application, you might want to terminate others or retry.
            // For now, continue and let the join process handle it.
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_threads; ++i) {
        THREAD_JOIN(threads[i]);
    }

    free(threads);

    fprintf(stdout, "\n--- Cloning Process Finished ---\n");
    print_results();

    // Cleanup
    free_repo_list();
    MUTEX_DESTROY(&list_mutex);
    MUTEX_DESTROY(&print_mutex);

    return (failed_count > 0) ? 1 : 0; // Return non-zero if any failed
}

// --- Utility Functions ---

void usage(const char *prog_name) {
    fprintf(stderr, "Usage: %s <repository_list_file> <output_directory> [num_threads]\n", prog_name);
    fprintf(stderr, "\nArguments:\n");
    fprintf(stderr, "  <repository_list_file> : A file containing one Git repository URL per line.\n");
    fprintf(stderr, "  <output_directory>     : The base directory where repositories will be cloned.\n");
    fprintf(stderr, "                           Each repository will be cloned into its own subdirectory.\n");
    fprintf(stderr, "  [num_threads]          : Optional. The number of concurrent cloning threads (default: %d).\n", DEFAULT_THREADS);
    fprintf(stderr, "\nExample:\n");
    fprintf(stderr, "  %s repos.txt my_clones 8\n", prog_name);
}

int read_repos_from_file(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open repository list file '%s'. Reason: %s\n", filename, strerror(errno));
        return -1;
    }

    char line[MAX_LINE_LENGTH];
    git_repo_t *tail = NULL;

    while (fgets(line, sizeof(line), fp) != NULL) {
        // Remove trailing newline character
        line[strcspn(line, "\r\n")] = '\0';

        if (strlen(line) == 0) continue; // Skip empty lines

        git_repo_t *new_repo = (git_repo_t *)malloc(sizeof(git_repo_t));
        if (new_repo == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for new repository entry.\n");
            fclose(fp);
            return -1;
        }

        strcpy(new_repo->url, line);
        new_repo->status = STATUS_PENDING;
        new_repo->error_message[0] = '\0'; // Initialize error message
        new_repo->next = NULL;

        MUTEX_LOCK(&list_mutex);
        if (total_repos == 0) {
            repo_list = new_repo;
            tail = new_repo;
        } else {
            tail->next = new_repo;
            tail = new_repo;
        }
        total_repos++;
        MUTEX_UNLOCK(&list_mutex);
    }

    fclose(fp);
    return 0;
}

// Extracts the last component of a URL path (e.g., "repo.git" from "https://github.com/user/repo.git")
// It also removes the ".git" suffix if present.
// Returns a dynamically allocated string, which must be freed by the caller.
char* get_repo_name_from_url(const char *url) {
    // Make a mutable copy of the URL for basename, which might modify its argument
    char *url_copy = strdup(url);
    if (url_copy == NULL) {
        return NULL;
    }

    char *bname = basename(url_copy);
    if (bname == NULL) {
        free(url_copy);
        return NULL;
    }

    char *repo_name = strdup(bname);
    free(url_copy); // Free the copy

    if (repo_name == NULL) {
        return NULL;
    }

    // Remove ".git" suffix if present
    size_t len = strlen(repo_name);
    if (len >= 4 && strcmp(repo_name + len - 4, ".git") == 0) {
        repo_name[len - 4] = '\0';
    }

    return repo_name;
}

// Function to recursively create directories
int create_directory_recursive(const char *path) {
    char *p = NULL;
    char *path_copy = strdup(path); // Duplicate path as strtok modifies the string
    if (path_copy == NULL) {
        return -1;
    }

    size_t len = strlen(path_copy);
    if (len > 0 && (path_copy[len-1] == '/' || path_copy[len-1] == '\\')) {
        path_copy[len-1] = '\0'; // Remove trailing slash
    }

    char *current_path = (char*)malloc(len + 1);
    if (current_path == NULL) {
        free(path_copy);
        return -1;
    }
    current_path[0] = '\0';

    // Handle root directory creation: For absolute paths like /a/b or C:\a\b
    char *segment = strtok(path_copy, "/\\");
    if (path[0] == '/' || path[0] == '\\') { // Unix absolute path
        strcpy(current_path, "/");
        if (MKDIR(current_path) != 0 && errno != EEXIST) {
            MUTEX_LOCK(&print_mutex);
            fprintf(stderr, "Error: Could not create base directory '%s'. Reason: %s\n", current_path, strerror(errno));
            MUTEX_UNLOCK(&print_mutex);
            free(path_copy);
            free(current_path);
            return -1;
        }
    } else if (len > 1 && path[1] == ':') { // Windows drive letter
        strncat(current_path, path, 2);
        strcat(current_path, "\\"); // Append backslash for typical Windows path
        if (MKDIR(current_path) != 0 && errno != EEXIST) {
            MUTEX_LOCK(&print_mutex);
            fprintf(stderr, "Error: Could not create base directory '%s'. Reason: %s\n", current_path, strerror(errno));
            MUTEX_UNLOCK(&print_mutex);
            free(path_copy);
            free(current_path);
            return -1;
        }
        segment = strtok(NULL, "/\\"); // Skip the drive letter part for subsequent tokenization
    }

    // Build path segment by segment and create directories
    while (segment != NULL) {
        if (current_path[0] != '\0') {
            #ifdef _WIN32
                strcat(current_path, "\\");
            #else
                strcat(current_path, "/");
            #endif
        }
        strcat(current_path, segment);

        if (MKDIR(current_path) != 0 && errno != EEXIST) {
            MUTEX_LOCK(&print_mutex);
            fprintf(stderr, "Error: Could not create directory '%s'. Reason: %s\n", current_path, strerror(errno));
            MUTEX_UNLOCK(&print_mutex);
            free(path_copy);
            free(current_path);
            return -1;
        }
        segment = strtok(NULL, "/\\");
    }

    free(path_copy);
    free(current_path);
    return 0;
}


// Function to recursively remove a directory and its contents
// WARNING: Use with caution! This acts like 'rm -rf'
int rmdir_recursive(const char *path) {
#ifdef _WIN32
    char cmd[MAX_LINE_LENGTH + 50];
    snprintf(cmd, sizeof(cmd), "rmdir /S /Q \"%s\"", path);
    if (system(cmd) != 0) {
        MUTEX_LOCK(&print_mutex);
        fprintf(stderr, "Warning: Failed to remove directory '%s'. Command: %s. Please remove manually.\n", path, cmd);
        MUTEX_UNLOCK(&print_mutex);
        return -1;
    }
#else
    char cmd[MAX_LINE_LENGTH + 50];
    snprintf(cmd, sizeof(cmd), "rm -rf \"%s\"", path);
    if (system(cmd) != 0) {
        MUTEX_LOCK(&print_mutex);
        fprintf(stderr, "Warning: Failed to remove directory '%s'. Command: %s. Please remove manually.\n", path, cmd);
        MUTEX_UNLOCK(&print_mutex);
        return -1;
    }
#endif
    return 0;
}


THREAD_FUNC_RETURN clone_repository(void *arg) {
    git_repo_t *repo_to_clone = NULL;
    char *base_output_dir = (char*)arg;
    char command[MAX_LINE_LENGTH * 3]; // Increased size for command string
    FILE *fp_cmd_output = NULL;
    char buffer[MAX_LINE_LENGTH];
    int cmd_status;

    while (1) {
        MUTEX_LOCK(&list_mutex);
        repo_to_clone = NULL;
        git_repo_t *current = repo_list;
        while (current != NULL) {
            if (current->status == STATUS_PENDING) {
                repo_to_clone = current;
                current->status = (clone_status_t)100; // Mark as "in progress" to prevent other threads from taking it
                break;
            }
            current = current->next;
        }
        MUTEX_UNLOCK(&list_mutex);

        if (repo_to_clone == NULL) {
            break; // No more pending repositories
        }

        MUTEX_LOCK(&print_mutex);
        fprintf(stdout, "[INFO] Cloning: %s into %s...\n", repo_to_clone->url, repo_to_clone->target_dir);
        MUTEX_UNLOCK(&print_mutex);

        // Check if output directory already exists (robustness)
        // #ifdef _WIN32
        //     struct _stat st;
        //     if (_stat(repo_to_clone->target_dir, &st) == 0 && (st.st_mode & _S_IFDIR)) {
        // #else
        //     struct stat st;
        //     if (stat(repo_to_clone->target_dir, &st) == 0 && S_ISDIR(st.st_mode)) {
        // #endif
        //     MUTEX_LOCK(&print_mutex);
        //     fprintf(stderr, "[WARN] Target directory '%s' already exists for %s. Skipping clone to avoid conflicts.\n",
        //             repo_to_clone->target_dir, repo_to_clone->url);
        //     MUTEX_UNLOCK(&print_mutex);
        //     MUTEX_LOCK(&list_mutex);
        //     repo_to_clone->status = STATUS_SUCCESS; // Treat as success if it's already there
        //     cloned_count++;
        //     MUTEX_UNLOCK(&list_mutex);
        //     continue;
        // }


        // Construct the git clone command
        // Using --depth 1 for faster clones, and --quiet to suppress output to stdout/stderr.
        // We'll capture stderr ourselves via `popen` if needed.
        snprintf(command, sizeof(command), "git clone --quiet --depth 1 \"%s\" \"%s\" 2>&1",
                 repo_to_clone->url, repo_to_clone->target_dir);


        fp_cmd_output = POPEN(command, "r");
        if (fp_cmd_output == NULL) {
            MUTEX_LOCK(&print_mutex);
            fprintf(stderr, "[ERROR] POPEN failed to execute command for %s. Reason: %s\n",
                    repo_to_clone->url, strerror(errno));
            MUTEX_UNLOCK(&print_mutex);
            MUTEX_LOCK(&list_mutex);
            repo_to_clone->status = STATUS_FAILED;
            snprintf(repo_to_clone->error_message, sizeof(repo_to_clone->error_message),
                     "Failed to execute git command: %s", strerror(errno));
            failed_count++;
            MUTEX_UNLOCK(&list_mutex);
            // Attempt to clean up even if popen failed
            rmdir_recursive(repo_to_clone->target_dir);
            continue;
        }

        // Read command output (primarily error messages)
        repo_to_clone->error_message[0] = '\0';
        size_t total_len = 0;
        while (fgets(buffer, sizeof(buffer), fp_cmd_output) != NULL) {
            size_t current_len = strlen(buffer);
            if (total_len + current_len < sizeof(repo_to_clone->error_message)) {
                strcat(repo_to_clone->error_message, buffer);
                total_len += current_len;
            } else {
                // Truncate message if it's too long
                strcat(repo_to_clone->error_message, "...\n");
                break;
            }
        }

        cmd_status = PCLOSE(fp_cmd_output);

        MUTEX_LOCK(&list_mutex);
        if (cmd_status == 0) { // Success
            repo_to_clone->status = STATUS_SUCCESS;
            cloned_count++;
            MUTEX_LOCK(&print_mutex);
            fprintf(stdout, "[DONE] Cloned: %s\n", repo_to_clone->url);
            MUTEX_UNLOCK(&print_mutex);
        } else { // Failure
            repo_to_clone->status = STATUS_FAILED;
            failed_count++;
            MUTEX_LOCK(&print_mutex);
            fprintf(stderr, "[FAIL] Failed to clone: %s (Exit Status: %d)\n", repo_to_clone->url, cmd_status);
            if (repo_to_clone->error_message[0] != '\0') {
                 fprintf(stderr, "       Reason: %s", repo_to_clone->error_message);
            }
            MUTEX_UNLOCK(&print_mutex);

            // Attempt to clean up partially cloned directory
            rmdir_recursive(repo_to_clone->target_dir);
        }
        MUTEX_UNLOCK(&list_mutex);
    }

    return NULL;
}

void free_repo_list() {
    git_repo_t *current = repo_list;
    git_repo_t *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    repo_list = NULL;
}

