    fprintf(stdout, "Successfully cloned: %d\n", cloned_count);
    fprintf(stdout, "Failed to clone: %d\n\n", failed_count);

    if (failed_count > 0) {
        fprintf(stdout, "--- Failed Repositories ---\n");
        git_repo_t *current = repo_list;
        while (current != NULL) {
            if (current->status == STATUS_FAILED) {
                fprintf(stdout, "URL: %s\n", current->url);
                fprintf(stdout, "  Error: %s%s\n",
