// Function to execute a command and return the result status
int execute_command(const char *command) {
    int status = system(command);
    return WIFEXITED(status) && WEXITSTATUS(status) == 0;
}

// Function to trim newline characters from strings
void trim_newline(char *str) {
    char *p = strchr(str, '\n');
    if (p) {
        *p = '\0';
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_file> <output_directory>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input_file = argv[1];
    const char *output_dir = argv[2];
    char repo_url[512];
    char command[1024];
    FILE *file = fopen(input_file, "r");

    if (!file) {
        perror("Failed to open input file");
        return EXIT_FAILURE;
    }

    // Create the output directory if it doesn't exist
    snprintf(command, sizeof(command), "mkdir -p %s", output_dir);
    if (!execute_command(command)) {
        fprintf(stderr, "Failed to create output directory: %s\n", output_dir);
        fclose(file);
        return EXIT_FAILURE;
    }

    printf("Cloning repositories...\n");

    FILE *failed_file = fopen("failed_repos.txt", "w");
    if (!failed_file) {
        perror("Failed to open 'failed_repos.txt'");
        fclose(file);
        return EXIT_FAILURE;
    }

    while (fgets(repo_url, sizeof(repo_url), file)) {
        trim_newline(repo_url);
        snprintf(command, sizeof(command), "git clone %s %s/%s", repo_url, output_dir, strrchr(repo_url, '/') + 1);
        printf("Cloning %s...\n", repo_url);

        if (!execute_command(command)) {
            fprintf(stderr, "Failed to clone repository: %s\n", repo_url);
            fprintf(failed_file, "%s\n", repo_url);
        }
    }

    fclose(file);
    fclose(failed_file);

    printf("Cloning process completed. Failed repositories are listed in 'failed_repos.txt'.\n");

    return EXIT_SUCCESS;
}

