// Function to handle cloning errors
void handle_clone_error(const git_error *e, char *url) {
    printf("Failed to clone %s: %s\n", url, git_error_last()->message);
}

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("Usage: %s <target_directory> <repository_url1> [repository_url2...]\n", argv[0]);
        return 1;
    }

    char *target_dir = argv[1];
    int num_repos = argc - 2;
    char **repo_urls = &argv[2];

    // Initialize libgit2
    git_libgit2_init();

    // Create target directory if it doesn't exist
    mkdir(target_dir, 0777);

    // Clone each repository
    int failed_clones = 0;
    for (int i = 0; i < num_repos; i++) {
        char *url = repo_urls[i];
        char *repo_name = strrchr(url, '/') + 1;
        char *repo_path = malloc(strlen(target_dir) + strlen(repo_name) + 2);
        sprintf(repo_path, "%s/%s", target_dir, repo_name);

        git_repository *repo = NULL;
        int error = git_clone(&repo, url, repo_path, NULL);
        if (error < 0) {
            handle_clone_error(git_error_last(), url);
            failed_clones++;
        } else {
            git_repository_free(repo);
        }

        free(repo_path);
    }

    // Report failed clones
    if (failed_clones > 0) {
        printf("\nFailed to clone %d repository(ies):\n", failed_clones);
        for (int i = 0; i < num_repos; i++) {
            char *url = repo_urls[i];
            git_repository *repo = NULL;
            if (git_clone(&repo, url, NULL, NULL) < 0) {
                printf("%s\n", url);
            } else {
                git_repository_free(repo);
            }
        }
    } else {
        printf("\nAll repositories cloned successfully!\n");
    }

    // Cleanup
    git_libgit2_shutdown();
    return 0;
}

