#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define MAX_PATH_LENGTH 1024
#define MAX_PATHS 100

// Function to validate a single path
int validate_path(const char* path) {
    // Check if path exists
    if (access(path, F_OK) != 0) {
        fprintf(stderr, "Path does not exist: %s (Error: %s)\n", path, strerror(errno));
        return 0;
    }

    // Check if path is writable
    if (access(path, W_OK) != 0) {
        fprintf(stderr, "Path is not writable: %s (Error: %s)\n", path, strerror(errno));
        return 0;
    }

    return 1;
}

// Function to validate multiple paths from command line arguments
void validate_paths(int argc, char* argv[]) {
    // Array to store invalid paths
    char invalid_paths[MAX_PATHS][MAX_PATH_LENGTH];
    int invalid_count = 0;

    // Skip the first argument (program name)
    for (int i = 1; i < argc; i++) {
        if (!validate_path(argv[i])) {
            // Store the invalid path
            strncpy(invalid_paths[invalid_count], argv[i], MAX_PATH_LENGTH - 1);
            invalid_paths[invalid_count][MAX_PATH_LENGTH - 1] = '\0';
            invalid_count++;
        }
    }

    // Print summary of invalid paths
    if (invalid_count > 0) {
        printf("\nInvalid Paths (%d):\n", invalid_count);
        for (int i = 0; i < invalid_count; i++) {
            printf("%d. %s\n", i + 1, invalid_paths[i]);
        }
        exit(EXIT_FAILURE);
    } else {
        printf("All paths are valid and writable.\n");
        exit(EXIT_SUCCESS);
    }
}

// Function to read paths from a file
void validate_paths_from_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    char path[MAX_PATH_LENGTH];
    char invalid_paths[MAX_PATHS][MAX_PATH_LENGTH];
    int invalid_count = 0;

    // Read paths from file line by line
    while (fgets(path, sizeof(path), file) != NULL) {
        // Remove newline character
        path[strcspn(path, "\n")] = 0;

        if (!validate_path(path)) {
            // Store the invalid path
            strncpy(invalid_paths[invalid_count], path, MAX_PATH_LENGTH - 1);
            invalid_paths[invalid_count][MAX_PATH_LENGTH - 1] = '\0';
            invalid_count++;
        }
    }

    fclose(file);

    // Print summary of invalid paths
    if (invalid_count > 0) {
        printf("\nInvalid Paths (%d):\n", invalid_count);
        for (int i = 0; i < invalid_count; i++) {
            printf("%d. %s\n", i + 1, invalid_paths[i]);
        }
        exit(EXIT_FAILURE);
    } else {
        printf("All paths are valid and writable.\n");
        exit(EXIT_SUCCESS);
    }
}

void print_usage(const char* program_name) {
    printf("Usage:\n");
    printf("1. Validate paths from command line: %s /path1 /path2 /path3\n", program_name);
    printf("2. Validate paths from file: %s -f paths.txt\n", program_name);
}

int main(int argc, char* argv[]) {
    // Check if arguments are provided
    if (argc < 2) {
        print_usage(argv[0]);
        return EXIT_FAILURE;
    }

    // Check if file mode is selected
    if (argc == 3 && strcmp(argv[1], "-f") == 0) {
        validate_paths_from_file(argv[2]);
    } else {
        validate_paths(argc, argv);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <errno.h>

// Function to check if a path is valid, exists and is writable
int is_path_valid(const char *path) {
    struct stat statbuf;

    // Check if path exists
    if (access(path, F_OK) != 0) {
        return 0;
    }

    // Get file status
    if (stat(path, &statbuf) != 0) {
        return 0;
    }

    // Check if it's a directory (we'll treat files differently)
    if (S_ISDIR(statbuf.st_mode)) {
        // Check directory writability
        if (access(path, W_OK) != 0) {
            return 0;
        }
    } else {
        // For files, check if parent directory is writable
        char *parent_dir = strdup(path);
        char *last_slash = strrchr(parent_dir, '/');

        if (last_slash != NULL) {
            *last_slash = '\0'; // Null-terminate at last slash

            // If parent_dir is empty after split, it's root
            if (strlen(parent_dir) == 0) {
                strcpy(parent_dir, "/");
            }

            if (access(parent_dir, W_OK) != 0) {
                free(parent_dir);
                return 0;
            }
        }
        free(parent_dir);
    }

    return 1;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <path1> [path2] ... [pathN]\n", argv[0]);
        return 1;
    }

    int invalid_count = 0;

    for (int i = 1; i < argc; i++) {
        const char *path = argv[i];

        if (!is_path_valid(path)) {
            printf("Invalid path: %s (Reason: ", path);

            // Provide more detailed error information
            if (access(path, F_OK) != 0) {
                printf("Does not exist");
            } else if (access(path, W_OK) != 0) {
                printf("Not writable");
            } else {
                printf("Unknown error");
            }

            printf(")\n");
            invalid_count++;
        }
    }

    if (invalid_count == 0) {
        printf("All paths are valid, exist, and are writable.\n");
    }

    return invalid_count;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>   // For access()
#include <sys/stat.h> // For stat()

// Function to validate a single path
// Returns 0 if valid (exists, readable, writable), 
//         1 if path does not exist
//         2 if path exists but is not readable
//         3 if path exists but is not writable
//         4 if path exists but is not a regular file or directory (e.g., symlink to nowhere, pipe, device)
//         5 for other unknown errors during stat or access checks
int validate_path(const char *path) {
    struct stat sb;

    // Check if path exists
    if (access(path, F_OK) == -1) {
        return 1; // Path does not exist
    }

    // Get file status to check type
    if (stat(path, &sb) == -1) {
        // This should ideally not happen if access(F_OK) passed, but for robustness
        perror("stat error");
        return 5; 
    }

    // Check if it's a regular file or directory
    if (!S_ISREG(sb.st_mode) && !S_ISDIR(sb.st_mode)) {
        return 4; // Not a regular file or directory
    }

    // Check if readable
    if (access(path, R_OK) == -1) {
        return 2; // Path exists but is not readable
    }

    // Check if writable
    // For directories, writable means you can create/delete files in it.
    // For files, writable means you can modify its content.
    if (access(path, W_OK) == -1) {
        return 3; // Path exists but is not writable
    }

    return 0; // Path is valid
}

int main(int argc, char *argv[]) {
    // Check if at least one path is provided
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <path1> [path2] [path3] ...\n", argv[0]);
        return EXIT_FAILURE;
    }

    int problematic_paths_found = 0;

    // Iterate through each provided path
    for (int i = 1; i < argc; i++) {
        const char *current_path = argv[i];
        int validation_result = validate_path(current_path);

        if (validation_result != 0) {
            fprintf(stdout, "Problematic Path: '%s' - ", current_path);
            problematic_paths_found = 1; // Mark that at least one problematic path was found

            switch (validation_result) {
                case 1:
                    fprintf(stdout, "Does not exist.\n");
                    break;
                case 2:
                    fprintf(stdout, "Exists but is not readable by the current user.\n");
                    break;
                case 3:
                    fprintf(stdout, "Exists but is not writable by the current user.\n");
                    break;
                case 4:
                    fprintf(stdout, "Exists but is not a regular file or directory (e.g., symlink, pipe, device).\n");
                    break;
                case 5:
                    fprintf(stdout, "An unexpected error occurred during validation.\n");
                    break;
                default:
                    fprintf(stdout, "Unknown validation error code.\n");
                    break;
            }
        }
    }

    if (!problematic_paths_found) {
        printf("All provided paths are valid (exist, readable, and writable).\n");
        return EXIT_SUCCESS;
    } else {
        printf("Validation complete. See output above for problematic paths.\n");
        return EXIT_FAILURE; // Indicate that some paths were problematic
    }
}

