// Structure to hold path information
typedef struct {
    char* path;
    int isValid;
    int exists;
    int isWritable;
} path_info;

// Function to check if a path is valid, exists, and is writable
void check_path(path_info* info) {
    struct stat sb;

    // Check if path is null
    if (info->path == NULL) {
        info->isValid = 0;
        info->exists = 0;
        info->isWritable = 0;
        return;
    }

    // Check if path exists
    if (stat(info->path, &sb) == -1) {
        info->isValid = 1;
        info->exists = 0;
        info->isWritable = 0;
        return;
    }

    // Check if path is writable
    if (access(info->path, W_OK) == -1) {
        info->isValid = 1;
        info->exists = 1;
        info->isWritable = 0;
        return;
    }

    // If all checks pass, path is valid, exists, and is writable
    info->isValid = 1;
    info->exists = 1;
    info->isWritable = 1;
}

// Function to print path information
void print_path_info(path_info* info) {
    printf("%s:\n", info->path);
    printf("  Is Valid: %s\n", info->isValid ? "Yes" : "No");
    printf("  Exists: %s\n", info->exists ? "Yes" : "No");
    printf("  Is Writable: %s\n", info->isWritable ? "Yes" : "No");
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <path1> <path2> ...\n", argv[0]);
        return 1;
    }

    // Create an array to hold path information
    path_info* paths = malloc((argc - 1) * sizeof(path_info));

    // Initialize path information
    for (int i = 1; i < argc; i++) {
        paths[i - 1].path = argv[i];
        paths[i - 1].isValid = 0;
        paths[i - 1].exists = 0;
        paths[i - 1].isWritable = 0;
    }

    // Check each path
    for (int i = 0; i < argc - 1; i++) {
        check_path(&paths[i]);
    }

    // Print path information
    for (int i = 0; i < argc - 1; i++) {
        print_path_info(&paths[i]);
        if (!paths[i].isValid || !paths[i].exists || !paths[i].isWritable) {
            printf("Error: Path '%s' is not valid, does not exist, or is not writable.\n", paths[i].path);
        }
        printf("\n");
    }

    free(paths);
    return 0;
}

