#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netinet/ip.h>
#include <netinet/ip_icmp.h>
#include <netinet/icmp6.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <errno.h>
#include <sys/time.h>

#define MAX_HOPS 64
#define PACKET_SIZE 64

// Function prototypes
int perform_traceroute(const char *destination, int is_ipv6);
int create_socket(int is_ipv6);
void set_socket_timeout(int sockfd, int seconds);
double calculate_time_diff(struct timeval start, struct timeval end);

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <IP address>\n", argv[0]);
        return 1;
    }

    // Determine IP version
    struct addrinfo hints, *result;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_flags = AI_NUMERICHOST;

    int ret = getaddrinfo(argv[1], NULL, &hints, &result);
    if (ret != 0) {
        fprintf(stderr, "Invalid IP address\n");
        return 1;
    }

    int is_ipv6 = (result->ai_family == AF_INET6);
    freeaddrinfo(result);

    // Perform traceroute
    int hops = perform_traceroute(argv[1], is_ipv6);

    if (hops > 0) {
        printf("Destination %s reached in %d hops\n", argv[1], hops);
    } else {
        printf("Could not reach destination %s\n", argv[1]);
    }

    return 0;
}

int perform_traceroute(const char *destination, int is_ipv6) {
    int sockfd = create_socket(is_ipv6);
    set_socket_timeout(sockfd, 3);  // 3-second timeout

    struct sockaddr_storage dest_addr;
    socklen_t addr_len;

    if (is_ipv6) {
        struct sockaddr_in6 *addr6 = (struct sockaddr_in6 *)&dest_addr;
        addr6->sin6_family = AF_INET6;
        inet_pton(AF_INET6, destination, &addr6->sin6_addr);
        addr_len = sizeof(struct sockaddr_in6);
    } else {
        struct sockaddr_in *addr4 = (struct sockaddr_in *)&dest_addr;
        addr4->sin_family = AF_INET;
        inet_pton(AF_INET, destination, &addr4->sin_addr);
        addr_len = sizeof(struct sockaddr_in);
    }

    char packet[PACKET_SIZE];
    char reply[PACKET_SIZE];
    struct sockaddr_storage from_addr;
    socklen_t from_len = sizeof(from_addr);

    for (int ttl = 1; ttl <= MAX_HOPS; ttl++) {
        // Set TTL
        if (is_ipv6) {
            setsockopt(sockfd, IPPROTO_IPV6, IPV6_UNICAST_HOPS, &ttl, sizeof(ttl));
        } else {
            setsockopt(sockfd, IPPROTO_IP, IP_TTL, &ttl, sizeof(ttl));
        }

        // Prepare packet
        memset(packet, 0, PACKET_SIZE);
        struct timeval start, end;
        gettimeofday(&start, NULL);

        // Send packet
        if (sendto(sockfd, packet, PACKET_SIZE, 0, 
                   (struct sockaddr *)&dest_addr, addr_len) < 0) {
            perror("sendto");
            return -1;
        }

        // Receive reply
        int recv_len = recvfrom(sockfd, reply, PACKET_SIZE, 0, 
                                (struct sockaddr *)&from_addr, &from_len);

        gettimeofday(&end, NULL);

        if (recv_len < 0) {
            if (errno == ETIMEDOUT) {
                printf("%d: *\n", ttl);
                continue;
            }
            perror("recvfrom");
            return -1;
        }

        // Get sender's IP address
        char from_ip[INET6_ADDRSTRLEN];
        if (is_ipv6) {
            struct sockaddr_in6 *from = (struct sockaddr_in6 *)&from_addr;
            inet_ntop(AF_INET6, &from->sin6_addr, from_ip, sizeof(from_ip));
        } else {
            struct sockaddr_in *from = (struct sockaddr_in *)&from_addr;
            inet_ntop(AF_INET, &from->sin_addr, from_ip, sizeof(from_ip));
        }

        double rtt = calculate_time_diff(start, end);
        printf("%d: %s (%.2f ms)\n", ttl, from_ip, rtt);

        // Check if destination is reached
        if (strcmp(from_ip, destination) == 0) {
            close(sockfd);
            return ttl;
        }
    }

    close(sockfd);
    return -1;
}

int create_socket(int is_ipv6) {
    int sockfd;
    if (is_ipv6) {
        sockfd = socket(AF_INET6, SOCK_RAW, IPPROTO_ICMPV6);
    } else {
        sockfd = socket(AF_INET, SOCK_RAW, IPPROTO_ICMP);
    }

    if (sockfd < 0) {
        perror("socket");
        exit(1);
    }

    return sockfd;
}

void set_socket_timeout(int sockfd, int seconds) {
    struct timeval timeout;
    timeout.tv_sec = seconds;
    timeout.tv_usec = 0;

    if (setsockopt(sockfd, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout)) < 0) {
        perror("setsockopt");
        exit(1);
    }
}

double calculate_time_diff(struct timeval start, struct timeval end) {
    return (end.tv_sec - start.tv_sec) * 1000.0 + 
           (end.tv_usec - start.tv_usec) / 1000.0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <arpa/inet.h>

#define MAX_HOPS 30
#define BUFFER_SIZE 1024

int is_valid_ip(const char *ip) {
    struct sockaddr_in sa;
    struct sockaddr_in6 sa6;

    // Check for IPv4
    if (inet_pton(AF_INET, ip, &(sa.sin_addr)) == 1) {
        return 4;
    }

    // Check for IPv6
    if (inet_pton(AF_INET6, ip, &(sa6.sin6_addr)) == 1) {
        return 6;
    }

    return 0;
}

int count_hops(const char *ip_address, int ip_version) {
    char command[BUFFER_SIZE];
    FILE *fp;
    char output[BUFFER_SIZE];
    int hop_count = -1;

    if (ip_version == 4) {
        snprintf(command, sizeof(command), "traceroute -n -m %d %s 2>&1", MAX_HOPS, ip_address);
    } else if (ip_version == 6) {
        snprintf(command, sizeof(command), "traceroute6 -n -m %d %s 2>&1", MAX_HOPS, ip_address);
    } else {
        return -1;
    }

    fp = popen(command, "r");
    if (fp == NULL) {
        perror("Failed to execute traceroute");
        return -1;
    }

    while (fgets(output, sizeof(output), fp) != NULL) {
        // Skip header lines
        if (strstr(output, "traceroute") != NULL) {
            continue;
        }

        // Count valid hop lines
        if (strstr(output, "*") == NULL && strlen(output) > 1) {
            hop_count++;
        }
    }

    pclose(fp);
    return hop_count;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <IP address>\n", argv[0]);
        return 1;
    }

    const char *ip_address = argv[1];
    int ip_version = is_valid_ip(ip_address);

    if (ip_version == 0) {
        fprintf(stderr, "Error: Invalid IP address format\n");
        return 1;
    }

    printf("Checking route to %s (IPv%d)...\n", ip_address, ip_version);

    int hops = count_hops(ip_address, ip_version);

    if (hops < 0) {
        fprintf(stderr, "Failed to determine hop count\n");
        return 1;
    }

    printf("Hop count to %s: %d\n", ip_address, hops);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to get the number of hops using an external traceroute/tracert command
int get_hops_count(const char *ip_address, char *os_type) {
    char command[256];
    FILE *fp;
    char line[512];
    int hops = 0;
    int found_destination = 0; // Flag to track if the destination was reached

    // Determine the correct command based on OS
    if (strcmp(os_type, "windows") == 0) {
        snprintf(command, sizeof(command), "tracert -d %s", ip_address); // -d to avoid DNS resolution
    } else if (strcmp(os_type, "linux") == 0 || strcmp(os_type, "macos") == 0) {
        snprintf(command, sizeof(command), "traceroute -n %s", ip_address); // -n to avoid DNS resolution
    } else {
        fprintf(stderr, "Error: Unsupported OS type. Use 'windows', 'linux', or 'macos'.\n");
        return -1;
    }

    printf("Executing command: %s\n", command);

    // Open the command for reading
    fp = popen(command, "r");
    if (fp == NULL) {
        perror("Failed to run command");
        return -1;
    }

    // Read the output line by line
    while (fgets(line, sizeof(line), fp) != NULL) {
        printf("Output Line: %s", line); // For debugging: print each line

        // --- Parsing logic for traceroute/tracert output ---
        // This parsing is HEAVILY dependent on the specific output format
        // of traceroute on your OS and can break with different versions/locales.

        if (strstr(line, ip_address) != NULL) {
            // If the IP address is found in the line, it likely means we've
            // reached the destination or a later hop.
            // We need to extract the hop number from the beginning of the line.
            int current_hop_num;
            if (sscanf(line, "%d", &current_hop_num) == 1) {
                if (current_hop_num > hops) { // Update if it's a higher hop number
                    hops = current_hop_num;
                    found_destination = 1; // Mark that we've found a line with the target IP
                }
            }
        }
        // More robust parsing would iteratively look for hop numbers, e.g.:
        // For Linux/macOS traceroute: " 1  192.168.1.1  0.500 ms"
        // For Windows tracert:      "  1     1 ms     1 ms     1 ms  192.168.1.1"

        // A simpler (but less accurate) way for Linux/macOS traceroute is to
        // just count lines if the destination IP is present on the last meaningful line:
        // You'd count lines that start with a number and contain RTTs.
        // For demonstration, we'll try to extract the hop number if the IP is found.
    }

    // Close the command
    pclose(fp);

    if (found_destination) {
        return hops;
    } else {
        // If the destination IP was never found in the output, it probably timed out
        // or a firewall blocked the trace.
        fprintf(stderr, "Warning: Could not determine hops. Destination '%s' might be unreachable or traceroute timed out.\n", ip_address);
        return -1; // Indicate failure or inability to determine hops
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IPv4_or_IPv6_address> <os_type>\n", argv[0]);
        fprintf(stderr, "  os_type can be: windows, linux, macos\n");
        return 1;
    }

    const char *ip_address = argv[1];
    const char *os_type = argv[2];

    int hops = get_hops_count(ip_address, (char *)os_type);

    if (hops != -1) {
        printf("\nIt takes approximately %d hops to reach %s.\n", hops, ip_address);
    } else {
        printf("\nCould not determine the number of hops for %s.\n", ip_address);
    }

    return 0;
}

