#define MAX_TTL 30
#define TIMEOUT_SEC 3

unsigned short checksum(void *b, int len)
{
    unsigned short *buf = b;
    unsigned int sum=0;
    unsigned short result;

    for (sum = 0; len > 1; len -= 2)
        sum += *buf++;
    if (len == 1)
        sum += *(unsigned char*)buf;
    sum = (sum >> 16) + (sum & 0xFFFF);
    sum += (sum >> 16);
    result = ~sum;
    return result;
}

int main(int argc, char *argv[])
{
    if(argc != 2) {
        printf("Usage: %s <IPv4-or-IPv6-address>\n", argv[0]);
        return 1;
    }

    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_socktype = SOCK_RAW;
    hints.ai_family = AF_UNSPEC;

    int ret = getaddrinfo(argv[1], NULL, &hints, &res);
    if(ret != 0) {
        fprintf(stderr, "Invalid address: %s\n", gai_strerror(ret));
        return 1;
    }

    int proto, ttl_optname;
    uint8_t icmp_type_reply, icmp_type_time_exceeded;

    if(res->ai_family == AF_INET) {
        proto = IPPROTO_ICMP;
        ttl_optname = IP_TTL;
        icmp_type_reply = 0;     // ICMP_ECHOREPLY
        icmp_type_time_exceeded = 11;
    } else if(res->ai_family == AF_INET6) {
        proto = IPPROTO_ICMPV6;
        ttl_optname = IPV6_UNICAST_HOPS;
        icmp_type_reply = 129;   // ICMP6_ECHO_REPLY
        icmp_type_time_exceeded = 3;
    } else {
        fprintf(stderr, "Unknown address family.\n");
        freeaddrinfo(res);
        return 1;
    }

    int s = socket(res->ai_family, SOCK_RAW, proto);
    if(s < 0) {
        perror("socket");
        freeaddrinfo(res);
        return 1;
    }

    uint16_t sequence = getpid() & 0xffff;
    int hops = -1;

    for(int ttl=1; ttl<=MAX_TTL; ++ttl) {
        // Set TTL/Hop limit
        if(setsockopt(s, (res->ai_family == AF_INET ? IPPROTO_IP : IPPROTO_IPV6), ttl_optname, &ttl, sizeof(ttl)) < 0) {
            perror("setsockopt");
            close(s);
            freeaddrinfo(res);
            return 1;
        }

        char sendbuf[128];
        ssize_t packet_len = 0;
        if(res->ai_family == AF_INET) {
            // ICMPv4 Echo Request
            struct icmphdr *icmph = (struct icmphdr *)sendbuf;
            memset(icmph, 0, sizeof(*icmph));
            icmph->type = ICMP_ECHO;
            icmph->code = 0;
            icmph->un.echo.id = htons(getpid() & 0xffff);
            icmph->un.echo.sequence = htons(sequence);
            icmph->checksum = 0;
            packet_len = sizeof(struct icmphdr);
            icmph->checksum = checksum(icmph, packet_len);
        } else {
            // ICMPv6 Echo Request
            struct icmp6_hdr *icmph = (struct icmp6_hdr *)sendbuf;
            memset(icmph, 0, sizeof(*icmph));
            icmph->icmp6_type = ICMP6_ECHO_REQUEST;
            icmph->icmp6_code = 0;
            icmph->icmp6_id = htons(getpid() & 0xffff);
            icmph->icmp6_seq = htons(sequence);
            packet_len = sizeof(struct icmp6_hdr);
            // no checksum for icmp6 here (kernel will do it)
        }

        ssize_t sent = sendto(s, sendbuf, packet_len, 0, res->ai_addr, res->ai_addrlen);
        if(sent < 0) {
            perror("sendto");
            break;
        }

        // Wait for response
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(s, &fds);
        struct timeval tv = {TIMEOUT_SEC, 0};
        int rv = select(s+1, &fds, NULL, NULL, &tv);
        if(rv == 0) {
            printf("%2d  *\n", ttl);
            continue; // no reply, try next TTL
        } else if(rv < 0) {
            perror("select");
            break;
        }

        char recvbuf[512];
        struct sockaddr_storage from;
        socklen_t fromlen = sizeof(from);

        ssize_t recvd = recvfrom(s, recvbuf, sizeof(recvbuf), 0, (struct sockaddr*)&from, &fromlen);
        if(recvd < 0) {
            perror("recvfrom");
            break;
        }

        int got_reply = 0;

        if(res->ai_family == AF_INET) {
            struct iphdr *iph = (struct iphdr*)recvbuf;
            int iphl = iph->ihl * 4;
            struct icmphdr *icmph = (struct icmphdr*)(recvbuf + iphl);
            if(icmph->type == icmp_type_reply && ntohs(icmph->un.echo.id) == (getpid() & 0xffff)) {
                printf("%2d  reached destination\n", ttl);
                hops = ttl;
                break;
            } else if(icmph->type == icmp_type_time_exceeded) {
                printf("%2d  intermediate hop\n", ttl);
            } else {
                printf("%2d  unexpected reply type %d\n", ttl, icmph->type);
            }
        } else {
            // For IPv6, receiving only ICMPv6 header after IPv6 header
            struct icmp6_hdr *icmph = (struct icmp6_hdr*)recvbuf;
            if(icmph->icmp6_type == icmp_type_reply && ntohs(icmph->icmp6_id) == (getpid() & 0xffff)) {
                printf("%2d  reached destination\n", ttl);
                hops = ttl;
                break;
            } else if(icmph->icmp6_type == icmp_type_time_exceeded) {
                printf("%2d  intermediate hop\n", ttl);
            } else {
                printf("%2d  unexpected reply type %d\n", ttl, icmph->icmp6_type);
            }
        }
    }

    if(hops > 0) {
        printf("Number of hops to %s: %d\n", argv[1], hops);
    } else {
        printf("Could not reach the host within %d hops.\n", MAX_TTL);
    }

    close(s);
    freeaddrinfo(res);
    return 0;
}

