#include <unistd.h>
#include <errno.h>

#define MAX_TTL 30
#define PACKET_SIZE 64

// Function to calculate checksum of the packet.
unsigned short checksum(void *b, int len)
{
    unsigned short *buf = b;
    unsigned int sum = 0;
    unsigned short result;

    for (sum = 0; len > 1; len -= 2)
        sum += *buf++;
    if (len == 1)
        sum += *(unsigned char *)buf;
    sum = (sum >> 16) + (sum & 0xFFFF);
    sum += (sum >> 16);
    result = ~sum;
    return result;
}

// Traceroute function: inputs an IP address as a string
int traceroute(const char *target)
{
    struct sockaddr_storage dest_addr;
    socklen_t addr_len;
    int sockfd, ttl = 1, recv_sock, addr_family, hops = 0;
    char packet[PACKET_SIZE], recv_buffer[PACKET_SIZE];
    struct icmp *icmp_header;
    struct timeval timeout = {5, 0}; // 5 seconds

    // Convert the target address
    memset(&dest_addr, 0, sizeof(dest_addr));
    if (inet_pton(AF_INET, target, &((struct sockaddr_in*)&dest_addr)->sin_addr)) {
        addr_family = AF_INET;
        dest_addr.ss_family = AF_INET;
        addr_len = sizeof(struct sockaddr_in);
    } else if (inet_pton(AF_INET6, target, &((struct sockaddr_in6*)&dest_addr)->sin6_addr)) {
        addr_family = AF_INET6;
        dest_addr.ss_family = AF_INET6;
        addr_len = sizeof(struct sockaddr_in6);
    } else {
        fprintf(stderr, "Invalid IP address.\n");
        return -1;
    }

    // Create sending socket
    sockfd = socket(addr_family, SOCK_RAW, IPPROTO_ICMP);
    if (sockfd < 0) {
        perror("Socket error");
        return -1;
    }

    // Create receiving socket
    recv_sock = socket(addr_family, SOCK_RAW, IPPROTO_ICMP);
    if (recv_sock < 0) {
        perror("Socket error");
        return -1;
    }

    // Set receive timeout
    setsockopt(recv_sock, SOL_SOCKET, SO_RCVTIMEO, (const char*)&timeout, sizeof(timeout));

    while (ttl <= MAX_TTL) {
        // Set TTL option
        setsockopt(sockfd, IPPROTO_IP, IP_TTL, &ttl, sizeof(ttl));

        // Prepare ICMP echo request
        memset(packet, 0, PACKET_SIZE);
        icmp_header = (struct icmp*)packet;
        icmp_header->icmp_type = ICMP_ECHO;
        icmp_header->icmp_code = 0;
        icmp_header->icmp_id = getpid();
        icmp_header->icmp_seq = ttl;
        icmp_header->icmp_cksum = checksum(packet, sizeof(struct icmp));

        if (sendto(sockfd, packet, sizeof(struct icmp), 0, (struct sockaddr*)&dest_addr, addr_len) < 0) {
            perror("sendto");
            break;
        }

        // Receive reply and check
        if (recvfrom(recv_sock, recv_buffer, PACKET_SIZE, 0, NULL, NULL) >= 0) {
            struct iphdr *ip_header = (struct iphdr*)recv_buffer;
            struct icmp *icmp_resp = (struct icmp*)(recv_buffer + (ip_header->ihl * 4));

            // Check if we have reached the destination
            if (icmp_resp->icmp_type == ICMP_ECHOREPLY) {
                printf("Reached destination in %d hops.\n", ttl);
                hops = ttl;
                break;
            }
        } else if (errno == EAGAIN || errno == EWOULDBLOCK) {
            printf("Timeout at %d hops.\n", ttl);
        }

        ttl++;
    }

    close(sockfd);
    close(recv_sock);
    return hops;
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <IP address>\n", argv[0]);
        return 1;
    }

    int hops = traceroute(argv[1]);
    if (hops > 0) {
        printf("Total hops: %d\n", hops);
    } else {
        printf("Could not reach the destination.\n");
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define BUFFER_SIZE 128

void execute_traceroute(const char *address) {
    char command[BUFFER_SIZE];
    FILE *fp;
    int hops = 0;

    // Creating the command to execute based on the operating system
#ifdef _WIN32
    snprintf(command, sizeof(command), "tracert -h 50 %s", address);
#else
    snprintf(command, sizeof(command), "traceroute -m 50 %s", address); // Limit to 50 hops
#endif

    // Open the command for reading.
    fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to run command: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Read the output a line at a time - output it.
    char line[BUFFER_SIZE];
    while (fgets(line, sizeof(line)-1, fp) != NULL) {
        // Check for valid hop lines in the traceroute output
        if (isdigit(line[0])) {
            hops++;
        }
    }

    // Close the process.
    if (pclose(fp) == -1) {
        fprintf(stderr, "Error occurred while closing command stream: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    printf("Number of hops to reach %s: %d\n", address, hops);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <IPv4 or IPv6 Address>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *address = argv[1];
    execute_traceroute(address);

    return EXIT_SUCCESS;
}

