#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netinet/ip.h>
#include <netinet/ip_icmp.h>

#define MAX_HOPS 30
#define TIMEOUT 5

// Function to create an ICMP echo request packet
void create_icmp_packet(char *buffer, int id, int seq) {
    struct icmphdr *icmp = (struct icmphdr *)buffer;
    icmp->type = ICMP_ECHO;
    icmp->code = 0;
    icmp->un.echo.id = id;
    icmp->un.echo.sequence = seq;
    icmp->checksum = 0;
    icmp->checksum = htons(0);
}

// Function to compute the checksum
unsigned short compute_checksum(unsigned short *buffer, int size) {
    unsigned long sum = 0;
    while (size > 1) {
        sum += *buffer++;
        size -= 2;
    }
    if (size == 1) {
        sum += *(unsigned char *)buffer;
    }
    sum = (sum >> 16) + (sum & 0xFFFF);
    sum += (sum >> 16);
    return (unsigned short)(~sum);
}

// Function to perform traceroute
int traceroute(const char *dest_addr) {
    int sock, ttl, i;
    struct sockaddr_in dest, src;
    char buffer[1024];
    struct icmphdr *icmp;
    struct iphdr *iph;
    struct sockaddr_in from;
    socklen_t fromlen;
    fd_set readfds;
    struct timeval timeout;
    int id = getpid();
    int seq = 1;

    // Create a raw socket
    if ((sock = socket(AF_INET, SOCK_RAW, IPPROTO_ICMP)) < 0) {
        perror("socket");
        exit(1);
    }

    // Set destination address
    memset(&dest, 0, sizeof(dest));
    dest.sin_family = AF_INET;
    if (inet_pton(AF_INET, dest_addr, &dest.sin_addr) <= 0) {
        perror("inet_pton");
        exit(1);
    }

    for (ttl = 1; ttl <= MAX_HOPS; ttl++) {
        // Set the TTL value
        if (setsockopt(sock, IPPROTO_IP, IP_TTL, &ttl, sizeof(ttl)) < 0) {
            perror("setsockopt");
            exit(1);
        }

        // Create ICMP echo request packet
        create_icmp_packet(buffer, id, seq);

        // Compute checksum
        icmp = (struct icmphdr *)buffer;
        icmp->checksum = compute_checksum((unsigned short *)buffer, sizeof(buffer));

        // Send the packet
        if (sendto(sock, buffer, sizeof(buffer), 0, (struct sockaddr *)&dest, sizeof(dest)) < 0) {
            perror("sendto");
            exit(1);
        }

        // Prepare to receive the response
        FD_ZERO(&readfds);
        FD_SET(sock, &readfds);
        timeout.tv_sec = TIMEOUT;
        timeout.tv_usec = 0;

        // Wait for a response
        if (select(sock + 1, &readfds, NULL, NULL, &timeout) > 0) {
            fromlen = sizeof(from);
            if (recvfrom(sock, buffer, sizeof(buffer), 0, (struct sockaddr *)&from, &fromlen) < 0) {
                perror("recvfrom");
                exit(1);
            }

            // Parse the received packet
            iph = (struct iphdr *)buffer;
            if (iph->protocol == IPPROTO_ICMP) {
                icmp = (struct icmphdr *)(buffer + iph->ihl * 4);
                if (icmp->type == ICMP_TIME_EXCEEDED) {
                    printf("%2d  %s\n", ttl, inet_ntoa(from.sin_addr));
                } else if (icmp->type == ICMP_ECHOREPLY) {
                    printf("%2d  %s\n", ttl, inet_ntoa(from.sin_addr));
                    break;
                }
            }
        } else {
            printf("%2d  *\n", ttl);
        }

        seq++;
    }

    close(sock);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <destination>\n", argv[0]);
        exit(1);
    }

    traceroute(argv[1]);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
