// Simple modular exponentiation function
unsigned long long mod_pow(unsigned long long base, unsigned long long exponent, unsigned long long modulus) {
    unsigned long long result = 1;
    base = base % modulus;

    while (exponent > 0) {
        if (exponent & 1) {
            result = (result * base) % modulus;
        }

        base = (base * base) % modulus;
        exponent >>= 1;
    }

    return result;
}

// OPRF structure
typedef struct {
    unsigned long long prime;       // Public prime
    unsigned long long generator;   // Public generator
    unsigned long long server_secret; // Server's private key
    unsigned long long server_public; // Server's public key
} OPRF;

// Initialize OPRF
void oprf_init(OPRF* oprf) {
    // Use a predefined prime and generator for simplicity
    oprf->prime = 23;       // A small prime for demonstration
    oprf->generator = 5;    // Generator

    // Generate server's secret key
    srand(time(NULL));
    oprf->server_secret = rand() % (oprf->prime - 2) + 2; // Random number between 2 and prime-1

    // Compute server's public key
    oprf->server_public = mod_pow(oprf->generator, oprf->server_secret, oprf->prime);
}

// Client-side blinding
unsigned long long client_blind(OPRF* oprf, unsigned long long input) {
    // Client generates a random blinding factor
    unsigned long long blind_factor = rand() % (oprf->prime - 2) + 2;

    // Blind the input
    unsigned long long blinded_input = mod_pow(input, blind_factor, oprf->prime);

    return blinded_input;
}

// Server-side evaluation
unsigned long long server_evaluate(OPRF* oprf, unsigned long long blinded_input) {
    // Server evaluates the blinded input with its secret key
    unsigned long long evaluated = mod_pow(blinded_input, oprf->server_secret, oprf->prime);

    return evaluated;
}

// Client-side unblinding
unsigned long long client_unblind(OPRF* oprf, unsigned long long evaluated_input, unsigned long long blind_factor) {
    // Compute modular multiplicative inverse of blind factor
    unsigned long long inverse = 1;
    for (unsigned long long i = 1; i < oprf->prime; i++) {
        if ((blind_factor * i) % oprf->prime == 1) {
            inverse = i;
            break;
        }
    }

    // Unblind the evaluated input
    unsigned long long unblinded = (evaluated_input * inverse) % oprf->prime;

    return unblinded;
}

int main() {
    // Seed random number generator
    srand(time(NULL));

    // Create OPRF instance
    OPRF oprf;
    oprf_init(&oprf);

    // Input to be processed
    unsigned long long input = 7;

    printf("Original Input: %llu\n", input);

    // Client blinds the input
    unsigned long long blinded_input = client_blind(&oprf, input);
    printf("Blinded Input: %llu\n", blinded_input);

    // Server evaluates the blinded input
    unsigned long long evaluated_input = server_evaluate(&oprf, blinded_input);
    printf("Server Evaluated Input: %llu\n", evaluated_input);

    // Client unblinds the evaluated input
    unsigned long long unblinded = client_unblind(&oprf, evaluated_input, input);
    printf("Unblinded Result: %llu\n", unblinded);

    return 0;
}

