#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// --- Utility Functions for Demonstration ---

// A very basic "pseudorandom" number generator for demonstration.
// NOT CRYPTOGRAPHICALLY SECURE.
long long generate_random_prime_ish_ish(long long max_val) {
    long long num;
    do {
        // Use a simple rand() for demonstration.
        // In real crypto, you'd use a cryptographically secure PRNG like /dev/urandom.
        num = (long long)rand() % max_val;
        if (num < 2) num = 2; // Ensure it's at least 2
    } while (num % 2 == 0 && num != 2); // Simple check for non-even numbers, very rudimentary.
    return num;
}

// Simple modular exponentiation (pow(base, exp) % mod).
// Used in real OPRF with elliptic curves for point multiplication.
// Here, it's just a placeholder for the concept.
long long power(long long base, long long exp, long long mod) {
    long long res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp % 2 == 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp /= 2;
    }
    return res;
}

// Simple modular inverse using Fermat's Little Theorem (a^(m-2) % m for prime m).
// Used for unblinding.
// NOT suitable if 'mod' is not prime or 'a' is not coprime to 'mod'.
long long modInverse(long long n, long long mod) {
    return power(n, mod - 2, mod);
}


// --- OPRF Components ---

// Server's secret key and base point
typedef struct {
    long long server_secret_key; // k_s
    long long server_base_point; // G
    long long modulus;           // A large prime for modular arithmetic
} ServerConfig;

// Client's blinded request
typedef struct {
    long long blinded_input; // r * (x + G)
} ClientRequest;

// Server's blinded response
typedef struct {
    long long blinded_output; // k_s * r * (x + G)
} ServerResponse;


// --- SERVER SIDE FUNCTIONS ---

// Initializes server's secret key and base point
void server_init(ServerConfig *config) {
    // For demonstration, use a fixed "large prime" modulus.
    // In real crypto, this would be a field order of an elliptic curve.
    config->modulus = 2147483647; // A Mersenne prime (2^31 - 1)

    // Generate server's secret key (k_s)
    config->server_secret_key = generate_random_prime_ish_ish(config->modulus / 4);
    if (config->server_secret_key == 0) config->server_secret_key = 1; // Ensure not zero

    // Set a base point (G)
    config->server_base_point = generate_random_prime_ish_ish(config->modulus / 4);
    if (config->server_base_point == 0) config->server_base_point = 1; // Ensure not zero

    printf("\nSERVER: Initialized with\n");
    printf("  Secret Key (k_s): %lld\n", config->server_secret_key);
    printf("  Base Point (G):   %lld\n", config->server_base_point);
    printf("  Modulus:          %lld\n", config->modulus);
}

// Server processes client's blinded request
ServerResponse server_process_request(const ServerConfig *config, const ClientRequest *req) {
    ServerResponse res;
    // Compute Y_blinded = k_s * X_blinded (modulo modulus)
    res.blinded_output = (config->server_secret_key * req->blinded_input) % config->modulus;

    printf("\nSERVER: Received blinded input: %lld\n", req->blinded_input);
    printf("SERVER: Computed blinded output: %lld\n", res.blinded_output);
    return res;
}


// --- CLIENT SIDE FUNCTIONS ---

// Client prepares a blinded request
ClientRequest client_prepare_request(long long input_x, const ServerConfig *server_config, long long *blinding_factor_r) {
    ClientRequest req;

    // Generate a random blinding factor (r)
    *blinding_factor_r = generate_random_prime_ish_ish(server_config->modulus / 4);
    if (*blinding_factor_r == 0) *blinding_factor_r = 1; // Ensure not zero

    // Compute X_blinded = r * (x + G) (modulo modulus)
    long long pre_blind_value = (input_x + server_config->server_base_point) % server_config->modulus;
    req.blinded_input = (*blinding_factor_r * pre_blind_value) % server_config->modulus;

    printf("\nCLIENT: Input x: %lld\n", input_x);
    printf("CLIENT: Generated blinding factor r: %lld\n", *blinding_factor_r);
    printf("CLIENT: Computed (x + G): %lld\n", pre_blind_value);
    printf("CLIENT: Computed blinded input (r * (x + G)): %lld\n", req.blinded_input);
    return req;
}

// Client unblinds the server's response to get F(x)
long long client_unblind_response(const ServerResponse *res, long long blinding_factor_r, const ServerConfig *server_config) {
    // Compute F(x) = Y_blinded / r = Y_blinded * r_inverse (modulo modulus)
    long long r_inverse = modInverse(blinding_factor_r, server_config->modulus);
    long long F_x = (res->blinded_output * r_inverse) % server_config->modulus;

    printf("\nCLIENT: Received blinded output: %lld\n", res->blinded_output);
    printf("CLIENT: Original blinding factor r: %lld\n", blinding_factor_r);
    printf("CLIENT: Inverse of r (mod Modulus): %lld\n", r_inverse);
    printf("CLIENT: UNBLINDED OPRF Result F(x): %lld\n", F_x);

    return F_x;
}


// --- MAIN DEMONSTRATION ---

int main() {
