// A simple hash function to create a pseudorandom seed from input
unsigned int simple_hash(const char *input) {
    unsigned int hash = 0;
    while (*input) {
        hash = (hash << 5) + (*input++); // hash = hash * 31 + input_char
    }
    return hash;
}

// A simple PRF that generates pseudorandom output based on a key and input
unsigned int oblivious_prf(const char *key, const char *input) {
    unsigned int seed = simple_hash(key) ^ simple_hash(input); // Mix key and input
    srand(seed); // Seed the random generator
    return rand(); // Generate a pseudorandom number
}

