#define MAX_TOKEN_LENGTH 100
#define MAX_VARIABLES 100

// Token types
typedef enum {
    TOKEN_INTEGER,
    TOKEN_IDENTIFIER,
    TOKEN_PLUS,
    TOKEN_MINUS,
    TOKEN_MULTIPLY,
    TOKEN_DIVIDE,
    TOKEN_ASSIGN,
    TOKEN_EQUALS,
    TOKEN_EOF
} TokenType;

// Token structure
typedef struct {
    TokenType type;
    char value[MAX_TOKEN_LENGTH];
} Token;

// Variable structure
typedef struct {
    char name[MAX_TOKEN_LENGTH];
    int value;
} Variable;

// Global variables
Variable variables[MAX_VARIABLES];
int variable_count = 0;

// Function prototypes
Token getNextToken(const char** input);
int evaluateExpression(const char** input);
void assignVariable(const char* name, int value);
int findVariable(const char* name);

// Tokenizer
Token getNextToken(const char** input) {
    Token token;

    // Skip whitespace
    while (isspace(**input)) {
        (*input)++;
    }

    // End of input
    if (**input == '\0') {
        token.type = TOKEN_EOF;
        return token;
    }

    // Integer
    if (isdigit(**input)) {
        token.type = TOKEN_INTEGER;
        int i = 0;
        while (isdigit(**input)) {
            token.value[i++] = **input;
            (*input)++;
        }
        token.value[i] = '\0';
        return token;
    }

    // Identifier or variable
    if (isalpha(**input)) {
        token.type = TOKEN_IDENTIFIER;
        int i = 0;
        while (isalnum(**input)) {
            token.value[i++] = **input;
            (*input)++;
        }
        token.value[i] = '\0';
        return token;
    }

    // Operators
    switch (**input) {
        case '+':
            token.type = TOKEN_PLUS;
            break;
        case '-':
            token.type = TOKEN_MINUS;
            break;
        case '*':
            token.type = TOKEN_MULTIPLY;
            break;
        case '/':
            token.type = TOKEN_DIVIDE;
            break;
        case '=':
            token.type = TOKEN_ASSIGN;
            break;
        default:
            fprintf(stderr, "Unexpected character: %c\n", **input);
            exit(1);
    }

    token.value[0] = **input;
    token.value[1] = '\0';
    (*input)++;

    return token;
}

// Evaluate arithmetic expression
int evaluateExpression(const char** input) {
    Token token = getNextToken(input);
    int result;

    // Handle integer or variable
    if (token.type == TOKEN_INTEGER) {
        result = atoi(token.value);
    } else if (token.type == TOKEN_IDENTIFIER) {
        int var_index = findVariable(token.value);
        if (var_index == -1) {
            fprintf(stderr, "Undefined variable: %s\n", token.value);
            exit(1);
        }
        result = variables[var_index].value;
    } else {
        fprintf(stderr, "Unexpected token in expression\n");
        exit(1);
    }

    // Handle subsequent arithmetic operations
    while (1) {
        token = getNextToken(input);

        if (token.type == TOKEN_EOF) {
            break;
        }

        int right_operand;
        Token next_token = getNextToken(input);

        if (next_token.type == TOKEN_INTEGER) {
            right_operand = atoi(next_token.value);
        } else if (next_token.type == TOKEN_IDENTIFIER) {
            int var_index = findVariable(next_token.value);
            if (var_index == -1) {
                fprintf(stderr, "Undefined variable: %s\n", next_token.value);
                exit(1);
            }
            right_operand = variables[var_index].value;
        } else {
            fprintf(stderr, "Invalid operand\n");
            exit(1);
        }

        switch (token.type) {
            case TOKEN_PLUS:
                result += right_operand;
                break;
            case TOKEN_MINUS:
                result -= right_operand;
                break;
            case TOKEN_MULTIPLY:
                result *= right_operand;
                break;
            case TOKEN_DIVIDE:
                if (right_operand == 0) {
                    fprintf(stderr, "Division by zero\n");
                    exit(1);
                }
                result /= right_operand;
                break;
            default:
                (*input)--; // Revert token
                return result;
        }
    }

    return result;
}

// Assign variable value
void assignVariable(const char* name, int value) {
    int index = findVariable(name);

    if (index == -1) {
        // Create new variable
        if (variable_count >= MAX_VARIABLES) {
            fprintf(stderr, "Too many variables\n");
            exit(1);
        }

        strcpy(variables[variable_count].name, name);
        variables[variable_count].value = value;
        variable_count++;
    } else {
        // Update existing variable
        variables[index].value = value;
    }
}

// Find variable index
int findVariable(const char* name) {
    for (int i = 0; i < variable_count; i++) {
        if (strcmp(variables[i].name, name) == 0) {
            return i;
        }
    }
    return -1;
}

// Main interpreter
void interpret(const char* input) {
    Token token = getNextToken(&input);

    if (token.type == TOKEN_IDENTIFIER) {
        Token next_token = getNextToken(&input);

        if (next_token.type == TOKEN_ASSIGN) {
            // Variable assignment
            int value = evaluateExpression(&input);
            assignVariable(token.value, value);
            printf("Assigned %s = %d\n", token.value, value);
        } else {
            fprintf(stderr, "Invalid syntax\n");
            exit(1);
        }
    } else {
        // Expression evaluation
        int result = evaluateExpression(&input);
        printf("Result: %d\n", result);
    }
}

int main() {
    char input[256];

    while (1) {
        printf("> ");
        if (fgets(input, sizeof(input), stdin) == NULL) {
            break;
        }

        input[strcspn(input, "\n")] = 0; // Remove newline

        if (strcmp(input, "exit") == 0) {
            break;
        }

        interpret(input);
    }

    return 0;
}

