double eval_expr(char *expr) {
    // Simple recursive descent parser for basic arithmetic expressions
    // Grammar:
    // expr   -> term (( '+' | '-' ) term)*
    // term   -> factor (( '*' | '/' ) factor)*
    // factor -> NUMBER | VARIABLE | '(' expr ')'

    double result = 0;
    char *token;
    char op = '+';

    token = strtok(expr, " ");
    while (token != NULL) {
        if (isdigit(token[0]) || (token[0] == '-' && isdigit(token[1]))) {
            double num = atof(token);
            if (op == '+') result += num;
            else if (op == '-') result -= num;
            else if (op == '*') result *= num;
            else if (op == '/') result /= num;
        } else if (isalpha(token[0])) {
            double var_value = vars[toupper(token[0]) - 'A'];
            if (op == '+') result += var_value;
            else if (op == '-') result -= var_value;
            else if (op == '*') result *= var_value;
            else if (op == '/') result /= var_value;
        } else if (token[0] == '(') {
            // Handle sub-expression
            char sub_expr[MAX_EXPR_LEN];
            strcpy(sub_expr, token + 1);
            double sub_result = eval_expr(sub_expr);
            if (op == '+') result += sub_result;
            else if (op == '-') result -= sub_result;
            else if (op == '*') result *= sub_result;
            else if (op == '/') result /= sub_result;
        } else if (token[0] == ')') {
            // End of sub-expression
            return result;
        } else if (strchr("+-*/", token[0])) {
            op = token[0];
        }

        token = strtok(NULL, " ");
    }

    return result;
}

void handle_assignment(char *line) {
    char var;
    char expr[MAX_EXPR_LEN];

    if (sscanf(line, "%c = %[^\n]", &var, expr) == 2) {
        if (isalpha(var)) {
            double result = eval_expr(expr);
            vars[toupper(var) - 'A'] = result;
            printf("%c = %.2f\n", var, result);
        } else {
            printf("Error: Invalid variable name.\n");
        }
    } else {
        printf("Error: Invalid syntax.\n");
    }
}

