#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

#define MAX_LINE 256

// Variable storage: only 26 variables a..z
int vars[26];

int skip_spaces(const char **p) {
    while (isspace(**p)) (*p)++;
    return 0;
}

// Forward declaration
int eval_expr(const char **p);

// Parse a factor: number or variable
int eval_factor(const char **p) {
    skip_spaces(p);
    int val = 0;
    if (isdigit(**p)) {
        while (isdigit(**p)) {
            val = val * 10 + (**p - '0');
            (*p)++;
        }
        return val;
    } else if (isalpha(**p)) {
        val = vars[(**p) - 'a'];
        (*p)++;
        return val;
    } else {
        printf("Parse error (factor): %c\n", **p);
        exit(1);
    }
}

// Parse term: factors combined by * or /
int eval_term(const char **p) {
    int val = eval_factor(p);
    skip_spaces(p);
    while (**p == '*' || **p == '/') {
        char op = **p;
        (*p)++;
        int rhs = eval_factor(p);
        if (op == '*')
            val *= rhs;
        else
            val /= rhs;
        skip_spaces(p);
    }
    return val;
}

// Parse expr: terms combined by + or -
int eval_expr(const char **p) {
    int val = eval_term(p);
    skip_spaces(p);
    while (**p == '+' || **p == '-') {
        char op = **p;
        (*p)++;
        int rhs = eval_term(p);
        if (op == '+')
            val += rhs;
        else
            val -= rhs;
        skip_spaces(p);
    }
    return val;
}

// Entry for each input line
void exec_line(const char *line) {
    const char *p = line;
    skip_spaces(&p);

    // print statement?
    if (strncmp(p, "print", 5) == 0 && isspace(p[5])) {
        p += 5;
        skip_spaces(&p);
        if (isalpha(*p)) {
            int val = vars[*p - 'a'];
            printf("%d\n", val);
        } else {
            printf("Syntax error in print\n");
            exit(1);
        }
    }
    // assignment
    else if (isalpha(*p)) {
        char var = *p;
        p++;
        skip_spaces(&p);
        if (*p != '=') {
            printf("Parse error: expected =\n");
            exit(1);
        }
        p++;
        int val = eval_expr(&p);
        vars[var - 'a'] = val;
    }
    // ignore empty/whitespace lines
    else if (*p == '\0' || *p == '\n') {
        // do nothing
    } else {
        printf("Unknown statement: %s\n", line);
        exit(1);
    }
}

int main() {
    char line[MAX_LINE];
    printf("Mini Interpreter. Enter lines (Ctrl+D to exit):\n");
    while (fgets(line, sizeof(line), stdin)) {
        // Remove newline
        size_t len = strlen(line);
        if (len && line[len-1]=='\n') line[len-1]='\0';
        exec_line(line);
    }
    return 0;
}

