    return make_token(TOK_INT, value, NULL);
}

Token lex_identifier(Lexer *lexer) {
    char name[MAX_VAR_NAME] = {0};
    int length = 0;
    while (isalpha(lexer->input[lexer->pos])) {
        if (length < MAX_VAR_NAME - 1) {
            name[length++] = lexer->input[lexer->pos];
            lexer->pos++;
        }
    }
    return make_token(TOK_VAR, 0, name);
}

Token get_next_token(Lexer *lexer) {
    while (lexer->input[lexer->pos] != '\0') {
        char current = lexer->input[lexer->pos];

        if (isspace(current)) {
            lexer->pos++;
            continue;
        }
        if (isdigit(current)) {
            return lex_integer(lexer);
        }
        if (isalpha(current)) {
            return lex_identifier(lexer);
        }
        if (current == '+') {
            lexer->pos++;
            return make_token(TOK_PLUS, 0, NULL);
        }
        if (current == '-') {
            lexer->pos++;
            return make_token(TOK_MINUS, 0, NULL);
        }
        if (current == '*') {
            lexer->pos++;
            return make_token(TOK_MULT, 0, NULL);
        }
        if (current == '/') {
            lexer->pos++;
            return make_token(TOK_DIV, 0, NULL);
        }
        if (current == '=') {
            lexer->pos++;
            return make_token(TOK_ASSIGN, 0, NULL);
        }

        error("Unexpected character");
    }
    return make_token(TOK_EOF, 0, NULL);
}

int find_variable(VariableTable *table, const char *name) {
    for (int i = 0; i < table->count; i++) {
        if (strcmp(table->vars[i].name, name) == 0) {
            return i;
        }
    }
    return -1;
}

int expression(Lexer *lexer, VariableTable *table);

int factor(Lexer *lexer, VariableTable *table) {
    if (lexer->currentToken.type == TOK_INT) {
        int value = lexer->currentToken.value;
        lexer->currentToken = get_next_token(lexer);
        return value;
    }
    if (lexer->currentToken.type == TOK_VAR) {
        int index = find_variable(table, lexer->currentToken.name);
        if (index == -1) error("Undefined variable.");
        int value = table->vars[index].value;
        lexer->currentToken = get_next_token(lexer);
        return value;
    }
    error("Expected an integer or a variable");
    return 0; // Unreachable
}

int term(Lexer *lexer, VariableTable *table) {
    int result = factor(lexer, table);
    while (lexer->currentToken.type == TOK_MULT || lexer->currentToken.type == TOK_DIV) {
        if (lexer->currentToken.type == TOK_MULT) {
            lexer->currentToken = get_next_token(lexer);
            result *= factor(lexer, table);
        } else if (lexer->currentToken.type == TOK_DIV) {
            lexer->currentToken = get_next_token(lexer);
            result /= factor(lexer, table);
        }
    }
    return result;
}

int expression(Lexer *lexer, VariableTable *table) {
    int result = term(lexer, table);
    while (lexer->currentToken.type == TOK_PLUS || lexer->currentToken.type == TOK_MINUS) {
        if (lexer->currentToken.type == TOK_PLUS) {
            lexer->currentToken = get_next_token(lexer);
            result += term(lexer, table);
        } else if (lexer->currentToken.type == TOK_MINUS) {
            lexer->currentToken = get_next_token(lexer);
            result -= term(lexer, table);
        }
    }
    return result;
}

void assignment(Lexer *lexer, VariableTable *table) {
    if (lexer->currentToken.type != TOK_VAR) error("Expected a variable name");
    char varName[MAX_VAR_NAME];
    strcpy(varName, lexer->currentToken.name);

    lexer->currentToken = get_next_token(lexer);

    if (lexer->currentToken.type != TOK_ASSIGN) error("Expected '='");
    lexer->currentToken = get_next_token(lexer);

    int value = expression(lexer, table);

    int varIndex = find_variable(table, varName);
    if (varIndex == -1) {
        if (table->count >= MAX_VARS) error("Variable limit reached");
        strcpy(table->vars[table->count].name, varName);
        table->vars[table->count].value = value;
        table->count++;
    } else {
        table->vars[varIndex].value = value;
    }
}

void interpret(const char *input) {
    Lexer lexer = {input, 0, make_token(TOK_EOF, 0, NULL)};
    lexer.currentToken = get_next_token(&lexer);

    VariableTable table = {0};

    while (lexer.currentToken.type != TOK_EOF) {
        assignment(&lexer, &table);
    }

    // For demonstration, print all variables
    for (int i = 0; i < table.count; i++) {
        printf("%s = %d\n", table.vars[i].name, table.vars[i].value);
    }
}

int main() {
    const char *code =
        "x = 3 + 4 * 2\n"
        "y = x * 5 - 2\n"
        "z = x + y / 2\n";

    interpret(code);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_VARS 100
#define MAX_VAR_NAME 32
#define MAX_INPUT 256

typedef struct {
    char name[MAX_VAR_NAME];
    double value;
} Variable;

Variable vars[MAX_VARS];
int var_count = 0;

double eval_expression(const char *expr);
double eval_term(const char **expr);
double eval_factor(const char **expr);
double get_variable_value(const char *name);
void set_variable_value(const char *name, double value);

void error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

void trim_whitespace(const char **expr) {
    while (isspace(**expr)) (*expr)++;
}

void expect_char(const char **expr, char c) {
    trim_whitespace(expr);
    if (**expr == c) {
        (*expr)++;
    } else {
        error("Unexpected character");
    }
}

void expect_end(const char **expr) {
    trim_whitespace(expr);
    if (**expr != '\0') {
        error("Unexpected characters at end");
    }
}

double eval_expression(const char *expr) {
    double result = eval_term(&expr);
    while (*expr) {
        trim_whitespace(&expr);
        if (*expr == '+') {
            expr++;
            result += eval_term(&expr);
        } else if (*expr == '-') {
            expr++;
            result -= eval_term(&expr);
        } else {
            break;
        }
    }
    return result;
}

double eval_term(const char **expr) {
    double result = eval_factor(expr);
    while (**expr) {
        trim_whitespace(expr);
        if (**expr == '*') {
            (*expr)++;
            result *= eval_factor(expr);
        } else if (**expr == '/') {
            (*expr)++;
            double divisor = eval_factor(expr);
            if (divisor == 0) {
                error("Division by zero");
            }
            result /= divisor;
        } else {
            break;
        }
    }
    return result;
}

double eval_factor(const char **expr) {
    trim_whitespace(expr);
    if (isdigit(**expr) || **expr == '-') {
        char *end;
        double value = strtod(*expr, &end);
        if (end == *expr) {
            error("Expected a number");
        }
        *expr = end;
        return value;
    } else if (isalpha(**expr)) {
        char var_name[MAX_VAR_NAME];
        size_t len = 0;
        while (isalnum(**expr) || **expr == '_') {
            if (len < MAX_VAR_NAME - 1) {
                var_name[len++] = *(*expr)++;
            }
        }
        var_name[len] = '\0';
        return get_variable_value(var_name);
    } else {
        error("Unexpected factor");
    }
    return 0.0;
}

double get_variable_value(const char *name) {
    for (int i = 0; i < var_count; i++) {
        if (strcmp(vars[i].name, name) == 0) {
            return vars[i].value;
        }
    }
    error("Variable not found");
    return 0.0; // Just for safety, won't reach here
}

void set_variable_value(const char *name, double value) {
    for (int i = 0; i < var_count; i++) {
        if (strcmp(vars[i].name, name) == 0) {
            vars[i].value = value;
            return;
        }
    }
    if (var_count < MAX_VARS) {
        strcpy(vars[var_count].name, name);
        vars[var_count].value = value;
        var_count++;
    } else {
        error("Too many variables");
    }
}

void parse_assignment(const char *input) {
    char var_name[MAX_VAR_NAME];
    int len = 0;

    while (isalnum(*input) || *input == '_') {
        if (len < MAX_VAR_NAME - 1) {
            var_name[len++] = *input++;
        }
    }
    var_name[len] = '\0';

    trim_whitespace(&input);
    expect_char(&input, '=');
    double value = eval_expression(input);
    set_variable_value(var_name, value);
}

void interpret(const char *input) {
    trim_whitespace(&input);
    if (strchr(input, '=')) {
        parse_assignment(input);
    } else {
        double result = eval_expression(input);
        printf("Result: %lf\n", result);
    }
}

int main() {
    char input[MAX_INPUT];

    printf("Simple Interpreter. Type 'exit' to quit.\n");

    while (1) {
        printf("> ");
        if (!fgets(input, sizeof(input), stdin)) break;

        if (strncmp(input, "exit", 4) == 0) break;

        interpret(input);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Token types
#define TOKEN_EOF 0
#define TOKEN_IDENTIFIER 1
#define TOKEN_KEYWORD 2
#define TOKEN_OPERATOR 3
#define TOKEN_NUMBER 4
#define TOKEN_STRING 5

// Operator types
#define OP_ADD 1
#define OP_SUB 2
#define OP_MUL 3
#define OP_DIV 4
#define OP_ASSIGN 5

// AST node types
#define AST_IDENTIFIER 1
#define AST_NUMBER 2
#define AST_OPERATOR 3
#define AST_ASSIGN 4

// Token structure
typedef struct token {
    int type;
    char* value;
} Token;

// AST node structure
typedef struct ast_node {
    int type;
    char* value;
    struct ast_node* left;
    struct ast_node* right;
} AstNode;

// Lexer structure
typedef struct lexer {
    char* input;
    int pos;
} Lexer;

// Parser structure
typedef struct parser {
    Lexer* lexer;
    Token* current_token;
} Parser;

// Interpreter structure
typedef struct interpreter {
    Parser* parser;
} Interpreter;

// Function to create a new token
Token* new_token(int type, char* value) {
    Token* token = malloc(sizeof(Token));
    token->type = type;
    token->value = strdup(value);
    return token;
}

// Function to create a new AST node
AstNode* new_ast_node(int type, char* value) {
    AstNode* node = malloc(sizeof(AstNode));
    node->type = type;
    node->value = strdup(value);
    node->left = NULL;
    node->right = NULL;
    return node;
}

// Function to initialize the lexer
void init_lexer(Lexer* lexer, char* input) {
    lexer->input = input;
    lexer->pos = 0;
}

// Function to get the next token from the lexer
Token* get_next_token(Lexer* lexer) {
    if (lexer->pos >= strlen(lexer->input)) {
        return new_token(TOKEN_EOF, NULL);
    }

    while (isspace(lexer->input[lexer->pos])) {
        lexer->pos++;
    }

    if (isalpha(lexer->input[lexer->pos])) {
        int start = lexer->pos;
        while (isalnum(lexer->input[lexer->pos])) {
            lexer->pos++;
        }
        char* value = malloc(lexer->pos - start + 1);
        strncpy(value, lexer->input + start, lexer->pos - start);
        value[lexer->pos - start] = '\0';
        return new_token(TOKEN_IDENTIFIER, value);
    }

    if (isdigit(lexer->input[lexer->pos])) {
        int start = lexer->pos;
        while (isdigit(lexer->input[lexer->pos])) {
            lexer->pos++;
        }
        char* value = malloc(lexer->pos - start + 1);
        strncpy(value, lexer->input + start, lexer->pos - start);
        value[lexer->pos - start] = '\0';
        return new_token(TOKEN_NUMBER, value);
    }

    switch (lexer->input[lexer->pos]) {
        case '+':
            lexer->pos++;
            return new_token(TOKEN_OPERATOR, "+");
        case '-':
            lexer->pos++;
            return new_token(TOKEN_OPERATOR, "-");
        case '*':
            lexer->pos++;
            return new_token(TOKEN_OPERATOR, "*");
        case '/':
            lexer->pos++;
            return new_token(TOKEN_OPERATOR, "/");
        case '=':
            lexer->pos++;
            return new_token(TOKEN_OPERATOR, "=");
        default:
            return new_token(TOKEN_EOF, NULL);
    }
}

// Function to parse an expression
AstNode* parse_expression(Parser* parser) {
    Token* token = parser->current_token;
    if (token->type == TOKEN_IDENTIFIER) {
        AstNode* node = new_ast_node(AST_IDENTIFIER, token->value);
        parser->current_token = get_next_token(parser->lexer);
        return node;
    }

    if (token->type == TOKEN_NUMBER) {
        AstNode* node = new_ast_node(AST_NUMBER, token->value);
        parser->current_token = get_next_token(parser->lexer);
        return node;
    }

    if (token->type == TOKEN_OPERATOR && strcmp(token->value, "(") == 0) {
        parser->current_token = get_next_token(parser->lexer);
        AstNode* node = parse_expression(parser);
        token = parser->current_token;
        if (token->type == TOKEN_OPERATOR && strcmp(token->value, ")") == 0) {
            parser->current_token = get_next_token(parser->lexer);
            return node;
        }
    }

    AstNode* left = parse_expression(parser);
    token = parser->current_token;
    if (token->type == TOKEN_OPERATOR) {
        int op;
        if (strcmp(token->value, "+") == 0) {
            op = OP_ADD;
        } else if (strcmp(token->value, "-") == 0) {
            op = OP_SUB;
        } else if (strcmp(token->value, "*") == 0) {
            op = OP_MUL;
        } else if (strcmp(token->value, "/") == 0) {
            op = OP_DIV;
        }

        parser->current_token = get_next_token(parser->lexer);
        AstNode* right = parse_expression(parser);
        AstNode* node = new_ast_node(AST_OPERATOR, token->value);
        node->left = left;
        node->right = right;
        return node;
    }

    return left;
}

// Function to parse an assignment statement
AstNode* parse_assignment(Parser* parser) {
    AstNode* node = parse_expression(parser);
    Token* token = parser->current_token;
    if (token->type == TOKEN_OPERATOR && strcmp(token->value, "=") == 0) {
        parser->current_token = get_next_token(parser->lexer);
        AstNode* right = parse_expression(parser);
        AstNode* assign_node = new_ast_node(AST_ASSIGN, token->value);
        assign_node->left = node;
        assign_node->right = right;
        return assign_node;
    }

    return node;
}

// Function to parse a statement
AstNode* parse_statement(Parser* parser) {
    Token* token = parser->current_token;
    if (token->type == TOKEN_IDENTIFIER) {
        return parse_assignment(parser);
    }

    return parse_expression(parser);
}

// Function to parse the input code
AstNode* parse_code(Parser* parser) {
    AstNode* node = parse_statement(parser);
    return node;
}

// Function to evaluate an AST node
double evaluate(AstNode* node) {
    if (node->type == AST_IDENTIFIER) {
        // todo: implement variable lookup
        printf("Error: variable lookup not implemented\n");
        exit(1);
    }

    if (node->type == AST_NUMBER) {
        return atof(node->value);
    }

    if (node->type == AST_OPERATOR) {
        double left = evaluate(node->left);
        double right = evaluate(node->right);
        int op;
        if (strcmp(node->value, "+") == 0) {
            op = OP_ADD;
        } else if (strcmp(node->value, "-") == 0) {
            op = OP_SUB;
        } else if (strcmp(node->value, "*") == 0) {
            op = OP_MUL;
        } else if (strcmp(node->value, "/") == 0) {
            op = OP_DIV;
        }

        switch (op) {
            case OP_ADD:
                return left + right;
            case OP_SUB:
                return left - right;
            case OP_MUL:
                return left * right;
            case OP_DIV:
                return left / right;
            default:
                printf("Error: unknown operator\n");
                exit(1);
        }
    }

    if (node->type == AST_ASSIGN) {
        // todo: implement variable assignment
        printf("Error: variable assignment not implemented\n");
        exit(1);
    }

    printf("Error: unknown node type\n");
    exit(1);
}

int main() {
    char* input = "x = 5 + 3 * 2";
    Lexer lexer;
    init_lexer(&lexer, input);

    Parser parser;
    parser.lexer = &lexer;
    parser.current_token = get_next_token(&lexer);

    AstNode* ast = parse_code(&parser);
    double result = evaluate(ast);

    printf("Result: %f\n", result);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_VARIABLES 100
#define MAX_NAME_LENGTH 32
#define MAX_LINE_LENGTH 256

typedef struct {
    char name[MAX_NAME_LENGTH];
    int value;
} Variable;

Variable variables[MAX_VARIABLES];
int variable_count = 0;

int get_variable_index(const char *name) {
    for (int i = 0; i < variable_count; i++) {
        if (strcmp(variables[i].name, name) == 0) {
            return i;
        }
    }
    return -1;
}

void set_variable(const char *name, int value) {
    int index = get_variable_index(name);
    if (index == -1) {
        if (variable_count >= MAX_VARIABLES) {
            fprintf(stderr, "Error: Too many variables\n");
            exit(1);
        }
        strcpy(variables[variable_count].name, name);
        variables[variable_count].value = value;
        variable_count++;
    } else {
        variables[index].value = value;
    }
}

int get_variable_value(const char *name) {
    int index = get_variable_index(name);
    if (index == -1) {
        fprintf(stderr, "Error: Undefined variable '%s'\n", name);
        exit(1);
    }
    return variables[index].value;
}
